# -*- coding: utf-8 -*-
# VMAX core application (open source edition).
# The private encrypted "admin vault" and phrase-based unlock were removed.
# Admin-only routes are gated by a simple opt-in switch:
#     VMAX_ADMIN=1  (see README)  — default is LOCKED.
import os as _oss_os

VMAX_ROLE_VERSION = "4.0.0-OSS"


def vmax_admin_unlocked() -> bool:
    """Admin features are off unless the operator sets VMAX_ADMIN=1."""
    return _oss_os.environ.get("VMAX_ADMIN", "0") == "1"


def vmax_admin_require(action: str = "admin"):
    if not vmax_admin_unlocked():
        raise PermissionError(f"admin required for: {action} (set VMAX_ADMIN=1)")
    return True

# ============================================================================
# REAL NEEDLE 3 BOOTSTRAP — AUTO INSTALL + AUTO FETCH
# ----------------------------------------------------------------------------
# On a connected machine this single file installs the official
# `cactus-needle` package when missing, then creates one real Needle 3 agent.
# The official package fetches/caches the native Needle 3 engine and
# `needle3.cact` weights on first use. Later runs use the local cache.
# Inference itself does not require network access.
#
# ความปลอดภัย: pin เวอร์ชันไว้ตายตัว (ไม่ใช้ --upgrade ดึง "ล่าสุด" แบบไม่รู้ตัวอีกต่อไป)
# กัน supply-chain: เวอร์ชันใหม่กว่าที่ pin ไว้จะไม่ถูกติดตั้งอัตโนมัติ ต้องแก้เลขเวอร์ชันเองเท่านั้น
# ถ้าต้องการเข้มกว่านี้ ตั้ง VMAX_NEEDLE3_HASH เป็น sha256 ของไฟล์ wheel/sdist ที่ตรวจสอบมาแล้ว
# (ไปคัดลอกจากหน้า https://pypi.org/project/cactus-needle/<version>/#files) ระบบจะสั่ง
# pip install --require-hashes ให้แทน ถ้าไม่ตั้งค่านี้จะยังติดตั้งแบบ pin เวอร์ชันแต่ไม่ verify hash
#
# VMAX_NEEDLE3_AUTO_INSTALL=0  -> disable automatic pip installation
# VMAX_NEEDLE3_AUTO_FETCH=0    -> disable first-use engine/weight fetch
# HF_HUB_OFFLINE=1             -> force the official package to stay offline
# VMAX_NEEDLE3_VERSION         -> override the pinned version (default below)
# VMAX_NEEDLE3_HASH             -> optional sha256 for --require-hashes verification
# ============================================================================

# --- VMAX UniMate early CLI (no heavy deps) ---
def _vmax_unimate_early_cli():
    """UniMate vault is admin-only in ROLE edition; player path skips."""
    return False

try:
    if _vmax_unimate_early_cli():
        raise SystemExit(0)
except SystemExit:
    raise
except Exception as _um_early_exc:
    if any(a.startswith("--unimate-") for a in __import__("sys").argv):
        print("[VMAX] UniMate early CLI failed:", _um_early_exc)
        raise SystemExit(1)
# --- end UniMate early CLI ---

import os as _vmax_os_bootstrap
import sys as _vmax_sys_bootstrap
import importlib as _vmax_importlib_bootstrap
import subprocess as _vmax_subprocess_bootstrap

VMAX_NEEDLE3_PINNED_VERSION = _vmax_os_bootstrap.environ.get("VMAX_NEEDLE3_VERSION", "2.0.5")

def _vmax_load_real_cactus_needle():
    try:
        return _vmax_importlib_bootstrap.import_module("needle")
    except (ImportError, ModuleNotFoundError):
        if _vmax_os_bootstrap.environ.get("VMAX_NEEDLE3_AUTO_INSTALL", "1") != "1":
            return None
        env = dict(_vmax_os_bootstrap.environ)
        env["PIP_DISABLE_PIP_VERSION_CHECK"] = "1"
        pinned = f"cactus-needle=={VMAX_NEEDLE3_PINNED_VERSION}"
        pip_hash = _vmax_os_bootstrap.environ.get("VMAX_NEEDLE3_HASH", "")
        if pip_hash:
            cmd = [_vmax_sys_bootstrap.executable, "-m", "pip", "install",
                   "--require-hashes", pinned, f"--hash=sha256:{pip_hash}"]
        else:
            # pin เวอร์ชันตายตัว — ไม่มี --upgrade แล้ว กันโดนสลับแพ็กเกจเป็นเวอร์ชันปลอมที่ใหม่กว่า
            cmd = [_vmax_sys_bootstrap.executable, "-m", "pip", "install", pinned]
        try:
            _vmax_subprocess_bootstrap.check_call(cmd, env=env)
        except (_vmax_subprocess_bootstrap.CalledProcessError, OSError) as _needle_install_exc:
            # Runtime audit fix: a missing optional Needle package must not make
            # the whole application crash merely because this machine is offline
            # or PyPI is unreachable.  The file already contains a dependency-
            # light compatibility implementation below, so return None and let
            # that implementation remain available.  Production deployments can
            # still require the official package by checking VMAX_NEEDLE3_real.
            print(f"[VMAX Needle 3] auto-install unavailable; using local compatibility layer: {_needle_install_exc}")
            return None
        return _vmax_importlib_bootstrap.import_module("needle")

_REAL_CACTUS_NEEDLE3 = _vmax_load_real_cactus_needle()


# =====================================================================
# VMAX COMPLETE VIRTUAL COMPUTER / KERNEL / RUNTIME INTEGRATION LAYER
# =====================================================================
# This is an application-level reference implementation of the 12
# subsystems discussed for VMAX.  It is intentionally self-contained
# and uses deterministic in-process simulation rather than pretending
# that Python can execute a bare-metal kernel directly.
#
# 01 Virtual CPU / instruction execution
# 02 Virtual RAM / memory manager
# 03 Interrupt subsystem
# 04 Scheduler / process-thread model
# 05 System-call layer
# 06 Virtual devices / drivers
# 07 Virtual filesystem / storage
# 08 VM <-> Game IPC/API bridge
# 09 Web deployment protocol
# 10 Sandbox / permission model
# 11 Boot/runtime handoff
# 12 Game SDK
# =====================================================================
#
# --- Credits / เจ้าของไฟล์ ---
#   Author (nickname): neko / zumo
#   Pronoun: cos
#   Japanese nickname: ネコ
# (ไม่มีการฝังชื่อจริง วันเกิด หรือเลขบัตรประชาชนไว้ในไฟล์นี้ เพื่อความปลอดภัย
#  ของข้อมูลส่วนบุคคล — ดูระบบ PIN gate ด้านล่างสำหรับการควบคุมการเข้าใช้งาน)
# =====================================================================

import time as _v12_time
import json as _v12_json
import uuid as _v12_uuid
import hashlib as _v12_hashlib
import threading as _v12_threading
from dataclasses import dataclass as _v12_dataclass, field as _v12_field
from pathlib import Path as _v12_Path


@_v12_dataclass
class VMAXVirtualCPU:
    """01. Small deterministic virtual CPU used by the VM layer."""
    registers: dict = _v12_field(default_factory=lambda: {
        "R0": 0, "R1": 0, "R2": 0, "R3": 0, "PC": 0, "FLAGS": 0
    })
    halted: bool = False
    program: list = _v12_field(default_factory=list)

    def load(self, program):
        self.program = list(program)
        self.registers["PC"] = 0
        self.halted = False

    def step(self):
        if self.halted:
            return {"ok": False, "reason": "halted"}
        pc = self.registers["PC"]
        if pc >= len(self.program):
            self.halted = True
            return {"ok": True, "op": "EOF"}
        ins = self.program[pc]
        op = ins.get("op")
        if op == "MOV":
            self.registers[ins["dst"]] = int(ins.get("value", 0))
        elif op == "ADD":
            self.registers[ins["dst"]] += int(ins.get("value", 0))
        elif op == "SUB":
            self.registers[ins["dst"]] -= int(ins.get("value", 0))
        elif op == "JMP":
            self.registers["PC"] = int(ins["target"])
            return {"ok": True, "op": op, "pc": pc}
        elif op == "HALT":
            self.halted = True
        else:
            return {"ok": False, "reason": f"unknown opcode: {op}"}
        self.registers["PC"] += 1
        return {"ok": True, "op": op, "pc": pc}

    def run(self, max_steps=1000):
        out = []
        for _ in range(max_steps):
            r = self.step()
            out.append(r)
            if self.halted:
                break
        return out


class VMAXMemoryManager:
    """02. Virtual RAM with bounds checks and allocation tracking."""

    def __init__(self, size=1024 * 1024):
        self.size = int(size)
        self.memory = bytearray(self.size)
        self.allocations = {}
        self._next = 0

    def alloc(self, size):
        size = int(size)
        if size <= 0 or self._next + size > self.size:
            raise MemoryError("VMAX virtual RAM exhausted")
        addr = self._next
        self._next += size
        self.allocations[addr] = size
        return addr

    def _check(self, addr, size):
        if addr < 0 or size < 0 or addr + size > self.size:
            raise MemoryError("VMAX virtual memory bounds violation")

    def write(self, addr, data):
        data = bytes(data)
        self._check(addr, len(data))
        self.memory[addr:addr + len(data)] = data

    def read(self, addr, size):
        self._check(addr, size)
        return bytes(self.memory[addr:addr + size])

    def stats(self):
        return {"size": self.size, "used": self._next,
                "free": self.size - self._next,
                "allocations": len(self.allocations)}


class VMAXInterruptController:
    """03. Interrupt/exception queue."""

    def __init__(self):
        self.handlers = {}
        self.pending = []
        self.lock = _v12_threading.Lock()

    def register(self, vector, handler):
        self.handlers[int(vector)] = handler

    def raise_interrupt(self, vector, payload=None):
        with self.lock:
            self.pending.append((int(vector), payload))

    def dispatch(self, limit=64):
        dispatched = 0
        while dispatched < limit:
            with self.lock:
                if not self.pending:
                    break
                vector, payload = self.pending.pop(0)
            handler = self.handlers.get(vector)
            if handler:
                handler(payload)
            dispatched += 1
        return dispatched


class VMAXScheduler:
    """04. Cooperative VM task scheduler."""

    def __init__(self):
        self.tasks = {}
        self.ready = []
        self.lock = _v12_threading.Lock()

    def create_task(self, name, target, priority=0):
        tid = _v12_uuid.uuid4().hex[:12]
        task = {"id": tid, "name": name, "target": target,
                "priority": int(priority), "state": "ready"}
        with self.lock:
            self.tasks[tid] = task
            self.ready.append(tid)
            self.ready.sort(key=lambda x: self.tasks[x]["priority"], reverse=True)
        return tid

    def run_once(self):
        ran = 0
        with self.lock:
            ids = list(self.ready)
        for tid in ids:
            task = self.tasks.get(tid)
            if not task or task["state"] != "ready":
                continue
            task["state"] = "running"
            try:
                task["target"]()
                task["state"] = "ready"
            except Exception as exc:
                task["state"] = "failed"
                task["error"] = repr(exc)
            ran += 1
        return ran


class VMAXSyscallLayer:
    """05. Controlled syscall facade between runtime and VM resources."""

    ALLOWED = {"clock", "memory_stats", "device_list", "storage_list"}

    def __init__(self, vm):
        self.vm = vm

    def call(self, name, **kwargs):
        if name not in self.ALLOWED:
            raise PermissionError(f"syscall not allowed: {name}")
        if name == "clock":
            return {"unix": _v12_time.time()}
        if name == "memory_stats":
            return self.vm.memory.stats()
        if name == "device_list":
            return list(self.vm.devices.keys())
        if name == "storage_list":
            return self.vm.storage.list_files()
        raise RuntimeError("unreachable")


class VMAXVirtualDevice:
    def __init__(self, name, kind):
        self.name, self.kind = name, kind
        self.events = []

    def emit(self, event, payload=None):
        self.events.append({"event": event, "payload": payload, "at": _v12_time.time()})


class VMAXDeviceManager:
    """06. Virtual devices and driver registration."""

    def __init__(self):
        self.devices = {}

    def register(self, name, kind):
        self.devices[name] = VMAXVirtualDevice(name, kind)
        return self.devices[name]

    def write(self, name, event, payload=None):
        if name not in self.devices:
            raise KeyError(name)
        self.devices[name].emit(event, payload)


class VMAXVirtualFilesystem:
    """07. Sandboxed in-VM filesystem backed by a Python dictionary."""

    def __init__(self):
        self.files = {}

    def _norm(self, path):
        p = str(path).replace("\\", "/")
        if not p.startswith("/"):
            p = "/" + p
        if ".." in p.split("/"):
            raise PermissionError("path traversal denied")
        return p

    def write(self, path, data):
        self.files[self._norm(path)] = bytes(data)

    def read(self, path):
        return self.files[self._norm(path)]

    def list_files(self):
        return sorted(self.files)

    def delete(self, path):
        self.files.pop(self._norm(path), None)


class VMAXGameIPC:
    """08. Explicit VM/runtime/game message bridge."""

    def __init__(self):
        self.handlers = {}
        self.messages = []

    def on(self, event, handler):
        self.handlers[str(event)] = handler

    def send(self, event, payload=None):
        msg = {"id": _v12_uuid.uuid4().hex, "event": str(event),
               "payload": payload, "at": _v12_time.time()}
        self.messages.append(msg)
        handler = self.handlers.get(str(event))
        if handler:
            msg["result"] = handler(payload)
        return msg


class VMAXWebDeploymentProtocol:
    """09. Manifest/sign/verify stage for a web/backend deployment."""

    def package(self, image_bytes, target="web", game_id=None):
        raw = bytes(image_bytes)
        return {
            "protocol": "VMAX-DEPLOY-V1",
            "target": target,
            "game_id": game_id,
            "size": len(raw),
            "sha256": _v12_hashlib.sha256(raw).hexdigest(),
            "payload_hex": raw.hex(),
            "created": _v12_time.time(),
        }

    def verify(self, bundle):
        raw = bytes.fromhex(bundle["payload_hex"])
        return _v12_hashlib.sha256(raw).hexdigest() == bundle["sha256"]


class VMAXSandbox:
    """10. Capability-based permissions for runtime/game code."""

    def __init__(self):
        self.capabilities = {
            "memory": False,
            "storage": False,
            "network": False,
            "devices": False,
            "kernel": False,
        }

    def grant(self, capability):
        if capability not in self.capabilities:
            raise KeyError(capability)
        self.capabilities[capability] = True

    def require(self, capability):
        if not self.capabilities.get(capability, False):
            raise PermissionError(f"VMAX capability denied: {capability}")


class VMAXBootHandoff:
    """11. Boot -> kernel -> runtime -> game lifecycle."""

    STATES = ("off", "booting", "kernel", "runtime", "game", "halted")

    def __init__(self):
        self.state = "off"
        self.history = []

    def transition(self, state):
        if state not in self.STATES:
            raise ValueError(state)
        self.history.append((self.state, state, _v12_time.time()))
        self.state = state
        return self.state

    def boot(self):
        for state in ("booting", "kernel", "runtime"):
            self.transition(state)
        return self.state

    def start_game(self):
        if self.state != "runtime":
            raise RuntimeError("runtime is not ready")
        return self.transition("game")


class VMAXGameSDK:
    """12. Stable game-facing SDK over the VM/runtime boundary."""

    def __init__(self, vm):
        self.vm = vm

    def connect(self, game_id):
        self.vm.game_id = str(game_id)
        return {"ok": True, "game_id": self.vm.game_id}

    def kernel_call(self, syscall, **kwargs):
        return self.vm.syscalls.call(syscall, **kwargs)

    def send_event(self, event, payload=None):
        return self.vm.ipc.send(event, payload)

    def storage_write(self, path, data):
        self.vm.sandbox.require("storage")
        self.vm.storage.write(path, data)

    def storage_read(self, path):
        self.vm.sandbox.require("storage")
        return self.vm.storage.read(path)

    def device_event(self, device, event, payload=None):
        self.vm.sandbox.require("devices")
        return self.vm.devices.write(device, event, payload)


class VMAXCompleteVirtualComputer:
    """Top-level composition of all 12 systems."""

    def __init__(self, ram_size=1024 * 1024):
        self.name = "VMAX Virtual Computer"
        self.cpu = VMAXVirtualCPU()
        self.memory = VMAXMemoryManager(ram_size)
        self.interrupts = VMAXInterruptController()
        self.scheduler = VMAXScheduler()
        self.devices = VMAXDeviceManager()
        self.storage = VMAXVirtualFilesystem()
        self.ipc = VMAXGameIPC()
        self.deployer = VMAXWebDeploymentProtocol()
        self.sandbox = VMAXSandbox()
        self.handoff = VMAXBootHandoff()
        self.game_id = None
        self.syscalls = VMAXSyscallLayer(self)
        self.sdk = VMAXGameSDK(self)

        # Basic virtual hardware.
        self.devices.register("vga", "display")
        self.devices.register("timer", "clock")
        self.devices.register("net0", "network")

        self.interrupts.register(32, lambda payload: self.devices.write("timer", "tick", payload))

    def boot(self):
        return self.handoff.boot()

    def launch_game(self, game_id):
        if self.handoff.state == "off":
            self.boot()
        if self.handoff.state == "runtime":
            self.handoff.start_game()
        self.sandbox.grant("storage")
        self.sandbox.grant("devices")
        return self.sdk.connect(game_id)

    def status(self):
        return {
            "name": self.name,
            "boot_state": self.handoff.state,
            "game_id": self.game_id,
            "cpu": dict(self.cpu.registers),
            "ram": self.memory.stats(),
            "devices": {k: v.kind for k, v in self.devices.devices.items()},
            "files": self.storage.list_files(),
            "sandbox": dict(self.sandbox.capabilities),
            "kernel_version": globals().get("VMAX_KERNEL_VERSION"),
            "kernel_arch": globals().get("VMAX_KERNEL_ARCH"),
        }


def vmax_create_complete_virtual_computer(ram_size=1024 * 1024):
    """Public factory for the complete 12-system VM."""
    return VMAXCompleteVirtualComputer(ram_size)


