def _vmax_12_systems_cli():
    import sys
    argv = sys.argv[1:]
    if not argv:
        return False

    if argv[0] == "--vmax-vm-demo":
        vm = vmax_create_complete_virtual_computer()
        print("[VMAX] boot:", vm.boot())
        print("[VMAX] launch:", vm.launch_game("vmax"))
        vm.cpu.load([
            {"op": "MOV", "dst": "R0", "value": 10},
            {"op": "ADD", "dst": "R0", "value": 32},
            {"op": "HALT"},
        ])
        vm.cpu.run()
        print(_v12_json.dumps(vm.status(), ensure_ascii=False, indent=2))
        return True

    if argv[0] == "--vmax-vm-status":
        vm = vmax_create_complete_virtual_computer()
        print(_v12_json.dumps(vm.status(), ensure_ascii=False, indent=2))
        return True

    return False

