# ================================================================
# VMAX KERNEL SIMULATOR / GAME-WEB DEPLOYMENT BRIDGE
# ------------------------------------------------
# This layer does NOT execute the bare-metal kernel inside Python.
# Instead it provides a safe application-level virtual computer
# model and a single-file deployment package that can:
#   1) stage kernel/runtime artifacts,
#   2) export a manifest + payload bundle,
#   3) hand the payload to a game/website integration endpoint,
#   4) keep the actual bare-metal image separate until a compatible
#      boot/runtime environment consumes it.
#
# The bridge is deliberately transport-neutral: HTTP upload can be
# added by the host application, while local export works offline.
# ================================================================
import json as _vmax_bridge_json
import hashlib as _vmax_bridge_hashlib
import base64 as _vmax_bridge_base64
import time as _vmax_bridge_time
from pathlib import Path as _vmax_bridge_Path


class VMAXVirtualComputer:
    """A lightweight virtual-computer staging model for VMAX assets."""

    def __init__(self, name="VMAX Virtual Computer"):
        self.name = name
        self.state = "powered_off"
        self.cpu_arch = VMAX_KERNEL_ARCH
        self.memory_mb = 1024
        self.storage = {}
        self.boot_image = None
        self.attached_game = None
        self.attached_web_target = None

    def power_on(self):
        self.state = "running"
        return {"ok": True, "state": self.state, "arch": self.cpu_arch}

    def attach_boot_image(self, image_path):
        p = _vmax_bridge_Path(image_path)
        if not p.is_file():
            raise FileNotFoundError(str(p))
        self.boot_image = str(p.resolve())
        return {"ok": True, "boot_image": self.boot_image}

    def attach_game(self, game_id):
        self.attached_game = str(game_id)
        return {"ok": True, "game": self.attached_game}

    def attach_web_target(self, endpoint):
        self.attached_web_target = str(endpoint)
        return {"ok": True, "endpoint": self.attached_web_target}

    def status(self):
        return {
            "name": self.name,
            "state": self.state,
            "cpu_arch": self.cpu_arch,
            "memory_mb": self.memory_mb,
            "boot_image": self.boot_image,
            "game": self.attached_game,
            "web_target": self.attached_web_target,
        }


class VMAXDeploymentBridge:
    """Packages a VMAX kernel image for game/web transfer."""

    FORMAT = "VMAX-SINGLE-FILE-BUNDLE"
    VERSION = "1.0"

    def __init__(self, root="."):
        self.root = _vmax_bridge_Path(root)

    @staticmethod
    def _sha256(path):
        h = _vmax_bridge_hashlib.sha256()
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(1024 * 1024), b""):
                h.update(chunk)
        return h.hexdigest()

    def package(self, boot_image, output_file="vmax_deployment_bundle.json",
                game_id=None, web_endpoint=None):
        image = _vmax_bridge_Path(boot_image)
        if not image.is_file():
            raise FileNotFoundError(str(image))

        raw = image.read_bytes()
        manifest = {
            "format": self.FORMAT,
            "version": self.VERSION,
            "created_unix": _vmax_bridge_time.time(),
            "kernel": {
                "version": VMAX_KERNEL_VERSION,
                "architecture": VMAX_KERNEL_ARCH,
                "image_name": image.name,
                "image_size": len(raw),
                "sha256": self._sha256(image),
            },
            "deployment": {
                "game_id": game_id,
                "web_endpoint": web_endpoint,
                "transport": "application-defined",
            },
            "payload_b64": _vmax_bridge_base64.b64encode(raw).decode("ascii"),
        }

        out = _vmax_bridge_Path(output_file)
        out.write_text(
            _vmax_bridge_json.dumps(manifest, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return str(out.resolve())

    @staticmethod
    def verify_bundle(bundle_file):
        bundle = _vmax_bridge_json.loads(
            _vmax_bridge_Path(bundle_file).read_text(encoding="utf-8")
        )
        raw = _vmax_bridge_base64.b64decode(bundle["payload_b64"])
        digest = _vmax_bridge_hashlib.sha256(raw).hexdigest()
        expected = bundle["kernel"]["sha256"]
        return {
            "ok": digest == expected,
            "sha256": digest,
            "expected": expected,
            "format": bundle.get("format"),
            "version": bundle.get("version"),
        }


def vmax_stage_kernel_for_game(boot_image, game_id, output_file=None):
    """Create a single-file bundle intended for a game's importer."""
    if output_file is None:
        output_file = f"VMAX_GAME_{game_id}_KERNEL_BUNDLE.json"
    bridge = VMAXDeploymentBridge()
    return bridge.package(boot_image, output_file=output_file,
                          game_id=game_id)


def vmax_stage_kernel_for_web(boot_image, web_endpoint, output_file=None):
    """Create a single-file bundle for a website/backend uploader."""
    if output_file is None:
        output_file = "VMAX_WEB_KERNEL_BUNDLE.json"
    bridge = VMAXDeploymentBridge()
    return bridge.package(boot_image, output_file=output_file,
                          web_endpoint=web_endpoint)


def vmax_verify_deployment_bundle(bundle_file):
    return VMAXDeploymentBridge.verify_bundle(bundle_file)


# Optional CLI bridge:
# python VMAX...py --vmax-package-game <image> <game_id> [output]
# python VMAX...py --vmax-package-web <image> <endpoint> [output]
# python VMAX...py --vmax-verify-bundle <bundle>
def _vmax_bridge_cli():
    import sys
    argv = sys.argv[1:]
    if not argv:
        return False

    if argv[0] == "--vmax-package-game" and len(argv) >= 3:
        image, game_id = argv[1], argv[2]
        output = argv[3] if len(argv) >= 4 else None
        print(vmax_stage_kernel_for_game(image, game_id, output))
        return True

    if argv[0] == "--vmax-package-web" and len(argv) >= 3:
        image, endpoint = argv[1], argv[2]
        output = argv[3] if len(argv) >= 4 else None
        print(vmax_stage_kernel_for_web(image, endpoint, output))
        return True

    if argv[0] == "--vmax-verify-bundle" and len(argv) >= 2:
        print(_vmax_bridge_json.dumps(
            vmax_verify_deployment_bundle(argv[1]),
            ensure_ascii=False, indent=2
        ))
        return True

    return False




# ============================================================================
# VMAX SINGLE-FILE BARE-METAL KERNEL INTEGRATION
# ============================================================================
# This section adds a REAL x86_64 bare-metal kernel source + build pipeline
# to this single Python file. The normal VMAX Python application remains
# intact below it.
#
# IMPORTANT:
#   - The Python application itself is NOT an OS kernel.
#   - The kernel below is freestanding C + x86 assembly and can boot without
#     Windows/Linux once a bootable image has been built.
#   - Build it with:
#       python VMAX_PRODUCTION_SINGLE_FILE_WITH_BARE_METAL_KERNEL.py --vmax-kernel-build
#   - The builder creates a temporary build directory and a raw boot image.
#
# First kernel milestone:
#   BIOS -> boot sector -> 32-bit protected mode -> x86_64 long mode
#   -> identity-mapped first 1 GiB -> freestanding C kernel -> VGA text output
#
# This is intentionally a small, auditable foundation. It does NOT pretend
# to already contain a complete OS (drivers, processes, filesystem, etc.).
# ============================================================================

import sys as _vmax_kernel_sys
import os as _vmax_kernel_os
import shutil as _vmax_kernel_shutil
import subprocess as _vmax_kernel_sp
from pathlib import Path as _vmax_kernel_Path

VMAX_KERNEL_VERSION = "0.1.0-bare-metal-x86_64"
VMAX_KERNEL_ARCH = "x86_64"
VMAX_KERNEL_BUILD_DIRNAME = "vmax_kernel_build"

VMAX_KERNEL_BOOT_ASM = r"""
BITS 16
ORG 0x7C00

start:
    cli
    xor ax, ax
    mov ds, ax
    mov es, ax
    mov ss, ax
    mov sp, 0x7C00
    mov [boot_drive], dl

    ; Enable A20 before any write/copy above the 1 MiB boundary.  The fast
    ; port-0x92 method is supported by the intended PC/QEMU targets and avoids
    ; the old 20-bit address wrap that would alias 0x100000 to low memory.
    in al, 0x92
    or al, 0x02
    and al, 0xFE
    out 0x92, al

    ; Load the raw freestanding kernel one 512-byte sector at a time.
    ; Destination starts at physical 0x10000. Maximum supported payload:
    ; 0x7E00 sectors (~16 MiB), although the normal first build is tiny.
    xor bx, bx
    mov word [load_segment], 0x1000
    mov word [current_lba], 1

.load_next:
    mov ax, [kernel_sectors]
    test ax, ax
    jz .loaded
    dec ax
    mov [kernel_sectors_left], ax

    mov ax, [load_segment]
    mov [dap_segment], ax
    mov word [dap_offset], 0

    ; LBA low 16 bits. The first kernel is deliberately kept small.
    xor eax, eax
    mov ax, [current_lba]
    mov [dap_lba_low], eax
    mov dword [dap_lba_high], 0

    mov si, dap
    mov dl, [boot_drive]
    mov ah, 0x42
    int 0x13
    jc disk_error

    inc word [current_lba]
    add word [load_segment], 0x20

    cmp word [kernel_sectors_left], 0
    jne .load_next

.loaded:
    ; Enter 32-bit protected mode.
    cli
    lgdt [gdt_descriptor]
    mov eax, cr0
    or eax, 1
    mov cr0, eax
    jmp 0x08:protected_mode

disk_error:
    mov si, disk_error_msg
.print:
    lodsb
    test al, al
    jz .halt
    mov ah, 0x0E
    mov bh, 0
    int 0x10
    jmp .print
.halt:
    cli
    hlt
    jmp .halt

BITS 32
protected_mode:
    mov ax, 0x10
    mov ds, ax
    mov es, ax
    mov ss, ax
    mov esp, 0x90000

    ; Copy loaded kernel from 0x10000 -> 0x100000.
    movzx ecx, word [kernel_sectors]
    imul ecx, 128
    mov esi, 0x10000
    mov edi, 0x100000
    cld
    rep movsd

    ; Build identity mapping for the first 1 GiB using 2 MiB pages.
    ; PML4 at 0x9000, PDPT at 0xA000, PD at 0xB000.
    mov edi, 0x9000
    xor eax, eax
    mov ecx, 3072
    rep stosd

    mov dword [0x9000], 0xA003
    mov dword [0xA000], 0xB003

    ; PD entries: 512 x 2 MiB = 1 GiB.
    mov edi, 0xB000
    xor ebx, ebx
    mov ecx, 512
.make_pd:
    mov eax, ebx
    or eax, 0x083
    mov [edi], eax
    mov dword [edi+4], 0
    add ebx, 0x200000
    add edi, 8
    loop .make_pd

    ; Enable PAE.
    mov eax, cr4
    or eax, 1 << 5
    mov cr4, eax

    ; CR3 = PML4.
    mov eax, 0x9000
    mov cr3, eax

    ; Enable long mode through EFER.LME.
    mov ecx, 0xC0000080
    rdmsr
    or eax, 1 << 8
    wrmsr

    ; Enable paging.
    mov eax, cr0
    or eax, 1 << 31
    mov cr0, eax

    lgdt [gdt64_descriptor]
    jmp 0x08:long_mode

BITS 64
long_mode:
    mov ax, 0x10
    mov ds, ax
    mov es, ax
    mov ss, ax
    mov rsp, 0x80000

    ; Call the C kernel at the address recorded by the build step.  This is
    ; patched from the ELF symbol value, so the boot stub never relies on
    ; name mangling or on a function merely happening to be first in .text.
    mov rax, [kernel_entry_ptr]
    test rax, rax
    jz .entry_error
    call rax

.entry_error:
    cli
    hlt
    jmp .entry_error

.hang:
    cli
    hlt
    jmp .hang

boot_drive db 0
load_segment dw 0x1000
current_lba dw 1
; Build-time marker; patched to the real sector count before the image is written.
kernel_sectors dw 0x4B53
kernel_sectors_left dw 0

dap:
    db 0x10
    db 0
    dw 1
dap_offset dw 0
dap_segment dw 0x1000
dap_lba_low dd 1
dap_lba_high dd 0

; Magic marker + 64-bit entry address patched by the Python build step.
; The magic value is intentionally non-zero and unique for safe replacement.
kernel_entry_ptr:
    dq 0x564D4158454E5452

disk_error_msg db "VMAX Kernel: disk read error", 0

align 8
gdt_start:
    dq 0x0000000000000000
    ; 64-bit code: L=1, G=1, present, ring 0, executable/readable.
    dq 0x00AF9A000000FFFF
    ; Data segment: present, ring 0, writable. Long mode ignores the base/limit.
    dq 0x00CF92000000FFFF
gdt_end:

gdt_descriptor:
    dw gdt_end - gdt_start - 1
    dd gdt_start

gdt64_descriptor:
    dw gdt_end - gdt_start - 1
    dq gdt_start

times 510-($-$$) db 0
dw 0xAA55
"""

VMAX_KERNEL_C = r"""
#include <stdint.h>

/* Keep the boot entry as a real, unmangled C symbol and force it into the
 * first text section selected by the linker.  The 64-bit boot stub jumps to
 * the linked address patched into the boot image by the Python build step. */
__attribute__((section(".text.vmax_entry"), used, noinline))
void vmax_kernel_main(void);

static volatile uint16_t* const VGA = (uint16_t*)0xB8000;

static void putc_at(int x, int y, char c, uint8_t attr) {
    VGA[y * 80 + x] = ((uint16_t)attr << 8) | (uint8_t)c;
}

static void print_at(int x, int y, const char* s, uint8_t attr) {
    while (*s && x < 80) {
        putc_at(x++, y, *s++, attr);
    }
}

static void hex64_at(int x, int y, uint64_t v, uint8_t attr) {
    const char* hex = "0123456789ABCDEF";
    for (int i = 0; i < 16; ++i) {
        int shift = 60 - i * 4;
        putc_at(x + i, y, hex[(v >> shift) & 0xF], attr);
    }
}

__attribute__((section(".text.vmax_entry"), used, noinline))
void vmax_kernel_main(void) {
    /* Clear VGA text memory. */
    for (int y = 0; y < 25; ++y) {
        for (int x = 0; x < 80; ++x) {
            putc_at(x, y, ' ', 0x07);
        }
    }

    print_at(0, 0, "VMAX Kernel", 0x0F);
    print_at(0, 1, "Bare-metal x86_64 kernel booted successfully.", 0x0A);
    print_at(0, 3, "Layer:", 0x07);
    print_at(8, 3, "VMAX application kernel / OS foundation", 0x0B);
    print_at(0, 5, "CPU mode:", 0x07);
    print_at(11, 5, "x86_64 long mode", 0x0B);
    print_at(0, 6, "Paging:", 0x07);
    print_at(11, 6, "identity map, first 1 GiB, 2 MiB pages", 0x0B);
    print_at(0, 8, "Kernel entry:", 0x07);
    hex64_at(14, 8, (uint64_t)(uintptr_t)&vmax_kernel_main, 0x0E);

    print_at(0, 10, "Next subsystems:", 0x07);
    print_at(0, 11, "- physical page allocator", 0x07);
    print_at(0, 12, "- interrupt / exception handlers", 0x07);
    print_at(0, 13, "- timer + scheduler", 0x07);
    print_at(0, 14, "- keyboard / storage / network drivers", 0x07);
    print_at(0, 15, "- VMAX syscall ABI", 0x07);

    for (;;) {
        __asm__ volatile ("hlt");
    }
}
"""

VMAX_KERNEL_LINKER_LD = r"""
ENTRY(vmax_kernel_main)

SECTIONS
{
    . = 0x100000;

    /* The C entry is deliberately first and kept alive.  This makes the
       entry address deterministic and prevents an unrelated function from
       being placed at the boot hand-off address. */
    .text : ALIGN(16)
    {
        KEEP(*(.text.vmax_entry))
        *(.text*)
    }

    .rodata : ALIGN(16)
    {
        *(.rodata*)
    }

    .data : ALIGN(16)
    {
        *(.data*)
    }

    .bss : ALIGN(16)
    {
        *(COMMON)
        *(.bss*)
    }

    /DISCARD/ :
    {
        *(.comment*)
        *(.note*)
        *(.eh_frame*)
    }
}
"""

def _vmax_kernel_tool(name):
    return _vmax_kernel_shutil.which(name)

def _vmax_kernel_build():
    root = _vmax_kernel_Path(__file__).resolve().parent
    build = root / VMAX_KERNEL_BUILD_DIRNAME
    build.mkdir(parents=True, exist_ok=True)

    required = ["nasm", "gcc", "ld", "objcopy", "nm"]
    missing = [x for x in required if not _vmax_kernel_tool(x)]
    if missing:
        print("VMAX Kernel build cannot start; missing tools: " + ", ".join(missing))
        print("Required: NASM + GCC/binutils (gcc, ld, objcopy).")
        return 2

    boot_s = build / "vmax_boot.asm"
    kernel_c = build / "vmax_kernel.c"
    linker_ld = build / "vmax_kernel.ld"
    boot_bin = build / "vmax_boot.bin"
    kernel_elf = build / "vmax_kernel.elf"
    kernel_bin = build / "vmax_kernel.raw"
    image = build / "vmax_kernel.img"

    boot_s.write_text(VMAX_KERNEL_BOOT_ASM, encoding="utf-8")
    kernel_c.write_text(VMAX_KERNEL_C, encoding="utf-8")
    linker_ld.write_text(VMAX_KERNEL_LINKER_LD, encoding="utf-8")

    def run(cmd):
        print("+", " ".join(str(x) for x in cmd))
        _vmax_kernel_sp.run(cmd, check=True)

    try:
        run(["nasm", "-f", "bin", str(boot_s), "-o", str(boot_bin)])

        run([
            "gcc", "-m64", "-ffreestanding", "-fno-pic", "-fno-pie",
            "-fno-stack-protector", "-fno-asynchronous-unwind-tables",
            "-fno-unwind-tables", "-mno-red-zone", "-mno-mmx", "-mno-sse",
            "-mno-sse2", "-c", str(kernel_c), "-o", str(build / "vmax_kernel.o")
        ])

        run([
            "ld", "-nostdlib", "-z", "max-page-size=0x1000",
            "-T", str(linker_ld), "-o", str(kernel_elf), str(build / "vmax_kernel.o")
        ])

        nm_out = _vmax_kernel_sp.check_output(["nm", "-n", str(kernel_elf)], text=True)
        entry_addr = None
        for line in nm_out.splitlines():
            parts = line.split()
            if len(parts) >= 3 and parts[2] == "vmax_kernel_main":
                entry_addr = int(parts[0], 16)
                break
        if entry_addr is None:
            raise RuntimeError("Could not locate vmax_kernel_main in linked ELF.")

        run([
            "objcopy", "-O", "binary", "-j", ".text", "-j", ".rodata",
            "-j", ".data", "-j", ".bss", str(kernel_elf), str(kernel_bin)
        ])

        kernel_size = kernel_bin.stat().st_size
        sectors = (kernel_size + 511) // 512
        if sectors == 0:
            raise RuntimeError("Kernel binary is empty.")
        if sectors > 0xFFFF:
            raise RuntimeError("Kernel is too large for this first-stage loader.")

        boot = bytearray(boot_bin.read_bytes())
        if len(boot) != 512:
            raise RuntimeError(f"Boot sector must be exactly 512 bytes, got {len(boot)}.")

        # Patch the kernel sector count using its dedicated non-zero marker,
        # never the first arbitrary zero word in the boot sector.
        sector_marker = (0x4B53).to_bytes(2, "little")
        entry_marker = (0x564D4158454E5452).to_bytes(8, "little")
        entry_marker_pos = boot.find(entry_marker)
        if entry_marker_pos < 0:
            raise RuntimeError("Could not locate kernel entry marker.")
        if entry_marker_pos < 2:
            raise RuntimeError("Kernel entry marker is unexpectedly positioned.")

        # kernel_sectors is deliberately located before kernel_sectors_left and
        # the DAP/entry data. Use the assembled symbol offsets by deriving them
        # from the known boot image layout rather than guessing a zero byte.
        # The field is encoded as a little-endian word immediately after the
        # load/current state words in this boot source.
        kernel_sectors_pos = boot.find(sector_marker)
        if kernel_sectors_pos < 0:
            raise RuntimeError("Could not locate kernel sector marker.")
        boot[kernel_sectors_pos:kernel_sectors_pos+2] = sectors.to_bytes(2, "little")
        boot[entry_marker_pos:entry_marker_pos+8] = entry_addr.to_bytes(8, "little")

        # Final raw disk image: boot sector + padded kernel.
        padded_kernel = kernel_bin.read_bytes() + b"\x00" * (sectors * 512 - kernel_size)
        image.write_bytes(bytes(boot) + padded_kernel)

        print()
        print("VMAX Kernel build complete.")
        print("Architecture :", VMAX_KERNEL_ARCH)
        print("Kernel bytes :", kernel_size)
        print("Kernel sectors:", sectors)
        print("Boot image    :", image)
        print()
        print("Test with QEMU:")
        print(f"  qemu-system-x86_64 -drive format=raw,file={image.name}")
        return 0
    except _vmax_kernel_sp.CalledProcessError as e:
        print("VMAX Kernel build failed with exit code", e.returncode)
        return e.returncode
    except Exception as e:
        print("VMAX Kernel build failed:", e)
        return 1

# Handle the special build command before the original VMAX application
# starts, keeping the whole project in ONE Python source file.
if "--vmax-kernel-build" in _vmax_kernel_sys.argv:
    raise SystemExit(_vmax_kernel_build())

# ============================================================================
# END BARE-METAL KERNEL INTEGRATION
# ============================================================================


