def _vmax_load_bridge_templates_module():
    _mod_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "vmax_bridge_templates.py")
    _expected = _b64.b64decode(_BRIDGE_TEMPLATES_SRC_B64)
    _needs_refresh = True
    try:
        _needs_refresh = (not os.path.isfile(_mod_path) or hashlib.sha256(_v12_Path(_mod_path).read_bytes()).digest() != hashlib.sha256(_expected).digest())
    except Exception:
        _needs_refresh = True
    if _needs_refresh:
        with open(_mod_path, "wb") as _f:
            _f.write(_expected)
        print(f"[VMAX Kernel] สร้าง/ซ่อมไฟล์ {_mod_path} จาก source ที่ฝังในไฟล์หลัก")
    _spec = _ilu.spec_from_file_location("vmax_bridge_templates", _mod_path)
    _mod = _ilu.module_from_spec(_spec)
    _spec.loader.exec_module(_mod)
    return _mod

_bridge_templates_mod = _vmax_load_bridge_templates_module()
BRIDGE_PROTOCOL_DESC = _bridge_templates_mod.BRIDGE_PROTOCOL_DESC
BRIDGE_CLIENT_TEMPLATES = _bridge_templates_mod.BRIDGE_CLIENT_TEMPLATES
CLIENT_INTEGRITY_SCANNER = _bridge_templates_mod.CLIENT_INTEGRITY_SCANNER

