def _vmax_load_anniversary_module():
    _mod_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "vmax_module_anniversary_gift.py")
    _expected = _b64.b64decode(_ANNIVERSARY_MODULE_SRC_B64)
    _needs_refresh = True
    try:
        _needs_refresh = (not os.path.isfile(_mod_path) or hashlib.sha256(_v12_Path(_mod_path).read_bytes()).digest() != hashlib.sha256(_expected).digest())
    except Exception:
        _needs_refresh = True
    if _needs_refresh:
        with open(_mod_path, "wb") as _f:
            _f.write(_expected)
        print(f"[VMAX Kernel] สร้าง/ซ่อมไฟล์ {_mod_path} จาก source ที่ฝังในไฟล์หลัก")
    _spec = _ilu.spec_from_file_location("vmax_module_anniversary_gift", _mod_path)
    _mod = _ilu.module_from_spec(_spec)
    _spec.loader.exec_module(_mod)
    return _mod

_anniversary_mod = _vmax_load_anniversary_module()

def _vmax_attach_anniversary_module():
    """เรียกตอน app/sio/register_user/INVENTORY/VMAX_MODULES/watchdog_register_thread
    ถูกประกาศครบแล้ว (ก่อน sio.run(...) ท้ายไฟล์) — ต่อโมดูลจดหมายอวยพรครบ 4,500 วัน
    เข้ากับไฟล์หลักแบบไม่แก้/ไม่ทับโค้ดเดิมแม้แต่บรรทัดเดียว"""
    _anniversary_mod.attach(globals())

