def _vmax_load_viewpoint_module():
    _mod_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "vmax_module_viewpoint.py")
    _expected = _b64.b64decode(_VIEWPOINT_MODULE_SRC_B64)
    _needs_refresh = True
    try:
        _needs_refresh = (not os.path.isfile(_mod_path) or hashlib.sha256(_v12_Path(_mod_path).read_bytes()).digest() != hashlib.sha256(_expected).digest())
    except Exception:
        _needs_refresh = True
    if _needs_refresh:
        with open(_mod_path, "wb") as _f:
            _f.write(_expected)
        print(f"[VMAX Kernel] สร้าง/ซ่อมไฟล์ {_mod_path} จาก source ที่ฝังในไฟล์หลัก")
    _spec = _ilu.spec_from_file_location("vmax_module_viewpoint", _mod_path)
    _mod = _ilu.module_from_spec(_spec)
    _spec.loader.exec_module(_mod)
    return _mod

_viewpoint_mod = _vmax_load_viewpoint_module()

def _vmax_attach_viewpoint_module():
    """เรียกตอน app/sio/central_store_push/central_store_get/central_store_list/
    central_store_update/VMAX_MODULES ถูกประกาศครบแล้ว (ก่อน sio.run(...) ท้ายไฟล์
    — ต้องเรียกหลังบล็อก CENTRAL_STORE เพราะโมดูลนี้พึ่งฟังก์ชันเหล่านั้น) —
    ต่อโมดูลจุดชมวิวเข้ากับไฟล์หลักแบบไม่แก้/ไม่ทับโค้ดเดิมแม้แต่บรรทัดเดียว"""
    _viewpoint_mod.attach(globals())



