def _vmax_load_armor_wiki_module():
    _mod_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "vmax_module_armor_wiki.py")
    _expected = _b64.b64decode(_ARMOR_WIKI_MODULE_SRC_B64)
    _needs_refresh = True
    try:
        _needs_refresh = (not os.path.isfile(_mod_path) or hashlib.sha256(_v12_Path(_mod_path).read_bytes()).digest() != hashlib.sha256(_expected).digest())
    except Exception:
        _needs_refresh = True
    if _needs_refresh:
        with open(_mod_path, "wb") as _f:
            _f.write(_expected)
        print(f"[VMAX Kernel] สร้าง/ซ่อมไฟล์ {_mod_path} จาก source ที่ฝังในไฟล์หลัก")
    _spec = _ilu.spec_from_file_location("vmax_module_armor_wiki", _mod_path)
    _mod = _ilu.module_from_spec(_spec)
    _spec.loader.exec_module(_mod)
    return _mod

_armor_wiki_mod = _vmax_load_armor_wiki_module()

def _vmax_attach_armor_wiki_module():
    """เรียกก่อน sio.run(...) ท้ายไฟล์ ตอน app/INVENTORY/PLAYERS/sio/require_auth/
    require_staff_rank/VMAX_MODULES ถูกประกาศครบแล้ว"""
    _armor_wiki_mod.attach(globals())

def _vmax_armor_hook(target_sid, dmg, damage_type="ballistic", pen=3):
    """ลดดาเมจตามเกราะที่เป้าหมายสวมอยู่ — คืนดาเมจสุดท้าย (int) ถ้ามีปัญหาใด ๆ คืนค่าเดิม"""
    try:
        return _armor_wiki_mod.mitigate_for_sid(target_sid, dmg, globals(), damage_type, pen)
    except Exception:
        return dmg

# ==========================================
# [ 1a7. Gunsmith (หน้าแต่งปืน) Module — self-extracting single-file link ]
# [NEW] แพทเทิร์นเดียวกับโมดูลด้านบน: ฝัง vmax_module_gunsmith.py เป็น base64 -> เขียนออกเป็นไฟล์จริง
# ข้างสคริปต์ (ซ่อมให้ถ้าเนื้อหาไม่ตรง) -> import -> attach ก่อน sio.run(...) ท้ายไฟล์
#   - ช่องอุปกรณ์เสริมข้างรูปปืน + การ์ด "แต่งรอบที่แล้ว" + พรีเซ็ต 5 ช่อง/ปืน
#   - กดแล้วขึ้นกล่องยืนยัน Yes/No พร้อมแสดงค่าอุปกรณ์ + ภาษี 7% + ยอดรวม (เซิร์ฟเวอร์คิดราคาเอง)
#   - เงินที่ใช้ = P["credits"] (เปลี่ยนที่ CURRENCY_KEY ในโมดูล)
#   - vmax_gunsmith_snapshot(uid) เรียกตอนจบเรดเพื่อจำชุดที่ใส่อยู่เป็น "แต่งรอบที่แล้ว"
# ==========================================
