def _vmax_load_ad_overlay_module():
    import hashlib as _ad_hl
    _mod_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "vmax_module_ad_overlay.py")
    _expected = _b64.b64decode(_AD_OVERLAY_MODULE_SRC_B64)
    _needs_refresh = True
    try:
        with open(_mod_path, "rb") as _rf:
            _needs_refresh = _ad_hl.sha256(_rf.read()).digest() != _ad_hl.sha256(_expected).digest()
    except Exception:
        _needs_refresh = True
    if _needs_refresh:
        with open(_mod_path, "wb") as _f:
            _f.write(_expected)
        print(f"[VMAX Kernel] สร้าง/ซ่อมไฟล์ {_mod_path} จาก source ที่ฝังในไฟล์หลัก")
    _spec = _ilu.spec_from_file_location("vmax_module_ad_overlay", _mod_path)
    _mod = _ilu.module_from_spec(_spec)
    _spec.loader.exec_module(_mod)
    return _mod

try:
    _ad_overlay_mod = _vmax_load_ad_overlay_module()
except Exception as _ad_exc:   # โมดูลโฆษณาพังต้องไม่ล้มทั้งเกม
    _ad_overlay_mod = None
    print(f"[Ad Overlay] ⚠️  โหลดโมดูลไม่สำเร็จ ข้ามไป: {_ad_exc}")

def _vmax_attach_ad_overlay_module():
    """เรียกตอน app/sio/require_auth/require_staff_rank/audit_log/VMAX_MODULES ถูกประกาศครบแล้ว (ก่อน sio.run)"""
    if _ad_overlay_mod is None:
        return
    try:
        _ad_overlay_mod.attach(globals())
    except Exception as _e:
        print(f"[Ad Overlay] ⚠️  ต่อโมดูลไม่สำเร็จ ข้ามไป: {_e}")

# ==========================================
# [ 2A. Security / Login Module ]
# Password auth (PBKDF2) + HMAC-signed session tokens + Refresh Token
# (with rotation) + real TOTP 2FA (pyotp) + Device tracking + Session Manager
# Source: VMAX_System_Design_Summary_v2 + VMAX_Expansion_Plan
# ==========================================
import hashlib, hmac, base64, secrets as _secrets

SESSIONS   = {}   # token -> {uid, device_id, expires}
DEVICES    = {}   # uid  -> [device_id, ...]
REFRESH_TOKENS = {}   # uid -> refresh_token
LOGIN_ATTEMPTS = {}    # uid -> [timestamp, ...] of recent failed logins

MAX_LOGIN_ATTEMPTS   = 5
LOGIN_LOCKOUT_SECONDS = 300
PBKDF2_ITERATIONS     = 200_000

# [BUG-FIX #16] เดิม JWT_SECRET/PASSWORD_PEPPER สุ่มขึ้นมาเงียบๆ ตอน start แล้วแค่
# print warning — ถ้า deploy จริงแล้วไม่มีใครสังเกต log (log ถูกกลืนไปโดย process
# manager/container/reverse proxy อย่างที่มักเกิดขึ้นจริง) แอปจะรันต่อไปได้ปกติทั้งที่
# secret เปลี่ยนใหม่ทุกครั้งที่ restart (session หลุดหมด, vault/password hash ตรวจ
# ไม่ผ่านเงียบๆ) — เพิ่ม VMAX_ENV=production เป็นสวิตช์ชัดเจน: ถ้าตั้งไว้แล้วไม่มี
# secret จริงจาก env จะ "หยุดการ start ทันที" (fail-fast) แทนที่จะรันต่อแบบเสี่ยงๆ
# ส่วนตอน dev/local (ไม่ได้ตั้ง VMAX_ENV เลย) ยังคงพฤติกรรมเดิม — สุ่มมาใช้ชั่วคราว
# ได้ ไม่บล็อกการพัฒนา
VMAX_ENV = os.environ.get("VMAX_ENV", "development").strip().lower()

# --- Session-signing secret -------------------------------------------------
# NEVER hardcode this. Must come from the environment in any real deployment:
#   export VMAX_JWT_SECRET=$(python3 -c "import secrets; print(secrets.token_hex(32))")
JWT_SECRET = os.environ.get("VMAX_JWT_SECRET")
if not JWT_SECRET:
    if VMAX_ENV == "production":
        raise RuntimeError(
            "[VMAX Kernel][FATAL] VMAX_ENV=production but VMAX_JWT_SECRET is not set. "
            "Refusing to start with a randomly-generated session secret in production "
            "(every restart would silently invalidate all sessions). Set it first:\n"
            '  export VMAX_JWT_SECRET=$(python3 -c "import secrets; print(secrets.token_hex(32))")'
        )
    JWT_SECRET = _secrets.token_hex(32)
    print("[VMAX Kernel][WARNING] VMAX_JWT_SECRET is not set — using a random, "
          "ephemeral secret for this run only.")
    print("                       Every session will be invalidated on restart, "
          "and this is NOT safe for production.")
    print("                       Set it explicitly before deploying:")
    print('                         export VMAX_JWT_SECRET=$(python3 -c "import secrets; print(secrets.token_hex(32))")')

# --- Server-side pepper -------------------------------------------------------
# A pepper is a secret mixed into every password/passphrase hash that lives
# ONLY in server config/environment -- never in the database next to the
# salt+hash. This matters against a *database-only* compromise (leaked DB
# dump, SQL injection, backup theft): without the pepper, offline cracking of
# the stolen hashes is impossible even if the attacker has unlimited compute,
# because they're missing an input that never left the server's environment.
# It does NOT help if the attacker also gets server memory/env access (at
# that point they have the pepper too) -- pepper defends one specific,
# common breach shape, not every breach shape.
# NEVER hardcode this. Must come from the environment in any real deployment:
#   export VMAX_PASSWORD_PEPPER=$(python3 -c "import secrets; print(secrets.token_hex(32))")
PASSWORD_PEPPER = os.environ.get("VMAX_PASSWORD_PEPPER")
if not PASSWORD_PEPPER:
    if VMAX_ENV == "production":
        raise RuntimeError(
            "[VMAX Kernel][FATAL] VMAX_ENV=production but VMAX_PASSWORD_PEPPER is not "
            "set. Refusing to start with a randomly-generated pepper in production "
            "(every restart would silently make all stored password/vault hashes "
            "unverifiable). Set it first:\n"
            '  export VMAX_PASSWORD_PEPPER=$(python3 -c "import secrets; print(secrets.token_hex(32))")'
        )
    PASSWORD_PEPPER = _secrets.token_hex(32)
    print("[VMAX Kernel][WARNING] VMAX_PASSWORD_PEPPER is not set — using a random, "
          "ephemeral pepper for this run only.")
    print("                       Every stored password/vault hash becomes unverifiable "
          "after restart with an ephemeral pepper, and this is NOT safe for production.")
    print("                       Set it explicitly before deploying:")
    print('                         export VMAX_PASSWORD_PEPPER=$(python3 -c "import secrets; print(secrets.token_hex(32))")')

def _apply_pepper(secret: str) -> bytes:
    """Mix the server-side pepper into a password/passphrase via HMAC-SHA256
    before it ever reaches the (Argon2id/PBKDF2) KDF. HMAC, not concatenation,
    so the pepper can't be trivially stripped or shifted by a crafted input."""
    return hmac.new(PASSWORD_PEPPER.encode("utf-8"), secret.encode("utf-8"), hashlib.sha256).digest()

# --- Login audit log -----------------------------------------------------------
# In-memory ring buffer of security-relevant events (auth + vault). Not a
# replacement for real centralized logging in production, but gives the
# operator/admin UI something to query without wiring up a log pipeline.
AUDIT_LOG = deque(maxlen=5000)

def audit_log(event: str, uid: str = "", **details):
    """event examples: login_ok, login_fail_password, login_fail_2fa,
    login_locked_out, new_device, 2fa_setup, 2fa_enabled, 2fa_disabled,
    vault_setup, vault_unlock_ok, vault_unlock_fail, vault_passphrase_changed"""
    try:
        ip = request.remote_addr
    except RuntimeError:
        ip = None   # called outside an active Flask request context (e.g. at startup)
    AUDIT_LOG.append({"ts": time.time(), "event": event, "uid": uid, "ip": ip, **details})

# --- Password storage --------------------------------------------------------
# USER_STORE: uid -> {"algo": "argon2id" | "pbkdf2", "peppered": bool, "salt": hex, "hash": hex,
#                      "totp_secret": str|None, "totp_enabled": bool, "totp_pending": str|None}
#
# Upgrade note (Argon2id): PBKDF2-SHA256 is CPU-only, so cracking it can be
# massively parallelized on GPUs/ASICs. Argon2id (PHC-winning, RFC 9106) also
# forces high *memory* usage per guess, which GPUs/ASICs are far worse at
# scaling than raw hash throughput -- that's the actual, measurable hardening
# here (not a marketing claim). Existing PBKDF2 hashes keep verifying (below)
# and are transparently re-hashed to Argon2id the next time that user logs in
# successfully, so no one is locked out and no migration script is needed.
#
# Upgrade note (pepper): "peppered" tracks whether PASSWORD_PEPPER was mixed
# into a given stored hash. Old PBKDF2 hashes were computed before the pepper
# existed, so they MUST keep verifying unpeppered -- re-checking them with the
# pepper applied would just make every existing password wrong. New hashes
# (fresh registrations, and PBKDF2->Argon2id migrations, both go through
# _hash_password_argon2) are always peppered going forward.
USER_STORE = {}

# RFC 9106 "sensitive" tier-ish parameters, tuned for a login endpoint:
#   time_cost (iterations), memory_cost (KiB), parallelism (lanes)
ARGON2_TIME_COST    = 3
ARGON2_MEMORY_COST  = 65536   # 64 MiB per hash -- deliberately memory-hard
ARGON2_PARALLELISM  = 2
ARGON2_HASH_LEN     = 32

def _hash_password_argon2(password: str, salt: bytes | None = None) -> tuple[str, str]:
    salt = salt or os.urandom(16)
    dk = hash_secret_raw(
        secret=_apply_pepper(password), salt=salt,
        time_cost=ARGON2_TIME_COST, memory_cost=ARGON2_MEMORY_COST,
        parallelism=ARGON2_PARALLELISM, hash_len=ARGON2_HASH_LEN,
        type=_Argon2Type.ID,   # Argon2id: hybrid resistance to both side-channel and GPU attacks
    )
    return salt.hex(), dk.hex()

def _verify_password_argon2(password: str, salt_hex: str, hash_hex: str) -> bool:
    salt = bytes.fromhex(salt_hex)
    dk = hash_secret_raw(
        secret=_apply_pepper(password), salt=salt,
        time_cost=ARGON2_TIME_COST, memory_cost=ARGON2_MEMORY_COST,
        parallelism=ARGON2_PARALLELISM, hash_len=ARGON2_HASH_LEN,
        type=_Argon2Type.ID,
    )
    return hmac.compare_digest(dk.hex(), hash_hex)

# --- Legacy PBKDF2 path (kept only so old accounts still verify) -------------
# Deliberately NOT peppered -- see "Upgrade note (pepper)" above.
def _hash_password_pbkdf2(password: str, salt: bytes | None = None) -> tuple[str, str]:
    salt = salt or os.urandom(16)
    dk = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, PBKDF2_ITERATIONS)
    return salt.hex(), dk.hex()

def _verify_password_pbkdf2(password: str, salt_hex: str, hash_hex: str) -> bool:
    salt = bytes.fromhex(salt_hex)
    dk = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, PBKDF2_ITERATIONS)
    return hmac.compare_digest(dk.hex(), hash_hex)

def register_user(uid: str, password: str) -> tuple[bool, str]:
    if uid in USER_STORE:
        return False, "uid already exists"
    if len(password) < 8:
        return False, "password must be at least 8 characters"
    salt, pwhash = _hash_password_argon2(password)
    USER_STORE[uid] = {"algo": "argon2id", "peppered": True, "salt": salt, "hash": pwhash,
                        "totp_secret": None, "totp_enabled": False, "totp_pending": None}
    return True, "registered"

def verify_password_for_uid(uid: str, password: str) -> bool:
    user = USER_STORE.get(uid)
    if not user:
        return False
    algo = user.get("algo", "pbkdf2")   # accounts created before this upgrade have no "algo" key
    if algo == "argon2id":
        return _verify_password_argon2(password, user["salt"], user["hash"])
    # Legacy account: verify with PBKDF2, then transparently upgrade to peppered
    # Argon2id in place so the weaker (and unpeppered) hash is never used again.
    ok = _verify_password_pbkdf2(password, user["salt"], user["hash"])
    if ok:
        new_salt, new_hash = _hash_password_argon2(password)
        user["algo"], user["peppered"], user["salt"], user["hash"] = "argon2id", True, new_salt, new_hash
    return ok

# Seed a default operator account so the existing single-player UI keeps working.
# Set VMAX_ADMIN_PASSWORD to control this explicitly; otherwise a random
# one-time password is generated and printed once at startup.
_default_admin_pw = os.environ.get("VMAX_ADMIN_PASSWORD")
if not _default_admin_pw:
    _default_admin_pw = _secrets.token_urlsafe(12)
    print(f"[VMAX Kernel][WARNING] VMAX_ADMIN_PASSWORD not set — generated a "
          f"one-time password for 'VMAX-OP-01': {_default_admin_pw}")
    print("                       Set VMAX_ADMIN_PASSWORD to control this in production.")
register_user("VMAX-OP-01", _default_admin_pw)
print("[VMAX Kernel][INFO] 2FA is mandatory for every account, including 'VMAX-OP-01' -- "
      "the first login attempt will prompt for 2FA setup before issuing a session.")

# --- Login rate limiting ------------------------------------------------------
# [BUG-FIX #15] Flask รันแบบ threaded ได้ (หลาย request พร้อมกันจริงในหลาย thread)
# เดิม is_login_locked_out / record_failed_login ไม่มี lock คุม LOGIN_ATTEMPTS เลย —
# เกิด TOCTOU (time-of-check-to-time-of-use) race ได้: สอง login request ของ uid
# เดียวกันมาพร้อมกัน ทั้งคู่อ่าน attempts เก่าไปพร้อมกันก่อนที่อีกฝั่งจะ append เสร็จ
# ผลคือนับจำนวนครั้งที่ผิดพลาด (undercounting) ทำให้ brute-force ยิงพร้อมกันหลาย
# thread หลบผ่าน lockout ไปได้บางส่วน ใช้ threading.Lock() ครอบทั้งสามฟังก์ชันกัน
_LOGIN_ATTEMPTS_LOCK = threading.Lock()

def is_login_locked_out(uid: str) -> bool:
    with _LOGIN_ATTEMPTS_LOCK:
        attempts = [t for t in LOGIN_ATTEMPTS.get(uid, []) if time.time() - t < LOGIN_LOCKOUT_SECONDS]
        LOGIN_ATTEMPTS[uid] = attempts
        return len(attempts) >= MAX_LOGIN_ATTEMPTS

def record_failed_login(uid: str):
    with _LOGIN_ATTEMPTS_LOCK:
        LOGIN_ATTEMPTS.setdefault(uid, []).append(time.time())

def clear_failed_logins(uid: str):
    with _LOGIN_ATTEMPTS_LOCK:
        LOGIN_ATTEMPTS.pop(uid, None)

# --- Session tokens (HMAC-signed, server-revocable) ---------------------------
def generate_jwt(uid: str, device_id: str, ttl: int = 3600) -> str:
    """JWT-style token: base64(payload).hmac_sha256(payload, JWT_SECRET)."""
    payload = json.dumps({"uid": uid, "device": device_id,
                          "exp": time.time() + ttl})
    b64 = base64.urlsafe_b64encode(payload.encode()).decode()
    sig = hmac.new(JWT_SECRET.encode(), b64.encode(), hashlib.sha256).hexdigest()
    token = f"{b64}.{sig}"
    SESSIONS[token] = {"uid": uid, "device_id": device_id,
                       "expires": time.time() + ttl}
    return token

def verify_jwt(token: str) -> dict | None:
    try:
        b64, sig = token.rsplit(".", 1)
    except (ValueError, AttributeError):
        return None
    expected_sig = hmac.new(JWT_SECRET.encode(), b64.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(sig, expected_sig):
        return None
    sess = SESSIONS.get(token)
    if not sess:
        return None
    if time.time() > sess["expires"]:
        SESSIONS.pop(token, None)
        return None
    # [BUG-FIX #21] เดิม verify_jwt เช็คแค่ลายเซ็น + วันหมดอายุ ไม่เคยเช็คว่า
    # device_id ที่ฝังอยู่ใน token นี้ยังเป็น device ที่ "รู้จัก/ยังไม่ถูกถอด" สำหรับ
    # uid นี้อยู่ไหม — ผลคือถ้ามีการถอดอุปกรณ์ออก (device revoked/removed จาก DEVICES,
    # เช่นตอนผู้ใช้กด "ออกจากระบบอุปกรณ์นี้ทั้งหมด" หรือ admin สั่งเพิกถอน) token ของ
    # device นั้นที่ยังไม่หมดอายุจะยังใช้งานได้ต่อไปเรื่อยๆ จนกว่าจะหมดอายุเอง — เพิ่ม
    # การเช็ค is_known_device() ตรงนี้ ถ้า device ถูกถอดไปแล้วให้ session ใช้ไม่ได้ทันที
    if not is_known_device(sess["uid"], sess["device_id"]):
        SESSIONS.pop(token, None)
        return None
    return sess

def revoke_token(token: str):
    SESSIONS.pop(token, None)

# [UPGRADE][BUG-FIX #11-13] SESSIONS / VAULT_SESSIONS / LOGIN_ATTEMPTS เดิมลบทิ้ง
# เฉพาะตอนมีคนมาเช็ค token/uid นั้นซ้ำอีกครั้ง (lazy prune แบบ on-access เท่านั้น) —
# token ที่ออกไปแล้วไม่มีใครใช้ต่อเลย (ปิดแท็บ, ไม่ได้ล็อกเอาต์, พยายาม login ผิดครั้ง
# เดียวแล้วเลิก ฯลฯ) จะค้างอยู่ใน dict ตลอดไปไม่มีวันถูกลบ — memory leak แบบค่อยๆ โต
# ไปเรื่อยๆ ตามอายุของ process ที่รันยาวนาน (ยิ่ง VAULT_SESSIONS ยิ่งเสี่ยงเพราะถือ
# Fernet key ของผู้ใช้ค้างในหน่วยความจำด้วย ไม่ใช่แค่ token) — แก้ด้วยการกวาดล้าง
# entries ที่หมดอายุ/ไม่มีการใช้งานแล้วเป็นระยะ เรียกจาก tele_loop (ดูด้านล่าง)
def prune_expired_auth_state():
    """Periodic hard prune for auth state so abandoned sessions cannot grow forever.

    [BUG-FIX #4] ใช้ snapshot ของ dict ก่อนลบ เพื่อไม่ให้ background tele_loop
    ชนกับ request thread แล้วเกิด RuntimeError: dictionary changed size during iteration.
    LOGIN_ATTEMPTS ใช้ lock เดียวกับ rate limiter เพื่อไม่ให้ prune ชนกับ login พร้อมกัน.
    """
    now = time.time()
    for token, sess in list(SESSIONS.items()):
        try:
            if now > sess.get("expires", 0):
                SESSIONS.pop(token, None)
        except AttributeError:
            SESSIONS.pop(token, None)
    for token, sess in list(VAULT_SESSIONS.items()):
        try:
            if sess.get("expires_at", 0) < now:
                VAULT_SESSIONS.pop(token, None)
        except AttributeError:
            VAULT_SESSIONS.pop(token, None)
    with _LOGIN_ATTEMPTS_LOCK:
        for uid, attempts in list(LOGIN_ATTEMPTS.items()):
            fresh = [t for t in attempts if now - t < LOGIN_LOCKOUT_SECONDS]
            if fresh:
                LOGIN_ATTEMPTS[uid] = fresh
            else:
                LOGIN_ATTEMPTS.pop(uid, None)

# --- [P0 FIX #3] require_auth: decorator สำหรับ endpoint ที่ต้อง login ก่อนเรียก ---
# ตรวจ JWT จาก header Authorization: Bearer <token> ด้วย verify_jwt() ที่มีอยู่แล้ว
# (HMAC-signed, server-revocable) ถ้าไม่มี/หมดอายุ/ปลอมแปลง ตอบ 401 ทันที ไม่ปล่อยให้
# โค้ดของ endpoint รันเลย ใช้กับจุดที่มีผลกระทบสูง (เช่น plugin loader ที่เดิมไม่มี
# auth เลย — ดู #6) นำไปแปะเพิ่มกับ endpoint อื่นๆ ที่ยังไม่มี auth ได้ทีละจุดต่อจากนี้
def require_auth(view_func):
    from functools import wraps
    @wraps(view_func)
    def _wrapped(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        sess = verify_jwt(token)
        if not sess:
            return jsonify({"st": "error",
                             "msg": "ต้อง login ก่อน (ส่ง header Authorization: Bearer <token>)"}), 401
        request.vmax_uid = sess["uid"]
        try:
            body_uid = None
            body = request.get_json(silent=True)
            if isinstance(body, dict):
                body_uid = body.get("uid")
            supplied_uid = body_uid or request.args.get("uid") or request.form.get("uid")
            if supplied_uid is not None and str(supplied_uid).strip() and str(supplied_uid).strip() != str(request.vmax_uid).strip():
                audit_log("uid_mismatch_rejected", uid=str(request.vmax_uid), requested_uid=str(supplied_uid),
                          endpoint=request.path, method=request.method)
                return jsonify({"st":"error", "msg":"uid ไม่ตรงกับบัญชีที่ล็อกอิน"}), 403
        except Exception:
            pass
        return view_func(*args, **kwargs)
    return _wrapped

# ==========================================
# [ P0.6 Toggleable Auth Enforcement ]
# ต่อยอดจาก require_auth (P0 #3) และ audit log "uid_resolved_via_fallback" (P0.5) —
# แทนที่จะบังคับ @require_auth ตายตัวกับ endpoint ที่ยังไม่มี auth ทีละจุด (ซึ่งพัง
# ทันทีถ้ามีเกมอื่น/ระบบอื่นที่ตั้งใจเรียก endpoint นั้นแทนผู้เล่นโดยไม่มี JWT จริง)
# ระบบนี้ให้บังคับ auth เป็น "ค่าเริ่มต้น" กับทุก endpoint ที่แปะ
# @require_auth_toggleable แต่แอดมิน (ยศ >= admin ในระบบ STAFF_RANKS เดิม —
# ดู /api/admin/panel) ปิดเฉพาะจุดได้ทีหลังผ่าน API โดยไม่ต้องแก้/deploy โค้ดใหม่
# สถานะเก็บลงไฟล์ json (แพทเทิร์นเดียวกับ _load_registry()/_save_registry() ของ
# Central Fixed-Code Registry ด้านบน) เพื่อให้อยู่รอดข้าม restart
AUTH_ENFORCEMENT_PATH = "auth_enforcement_registry.json"

def _load_auth_enforcement() -> dict:
    if os.path.exists(AUTH_ENFORCEMENT_PATH):
        with open(AUTH_ENFORCEMENT_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    return {}

def _save_auth_enforcement(reg: dict) -> None:
    with open(AUTH_ENFORCEMENT_PATH, "w", encoding="utf-8") as f:
        json.dump(reg, f, ensure_ascii=False, indent=2)

# endpoint_key (ชื่อฟังก์ชัน view — ตรงกับ Flask rule.endpoint โดย default) -> {"enabled": bool, ...}
AUTH_ENFORCEMENT = _load_auth_enforcement()

# endpoint_key -> True เฉพาะจุดที่แปะ @require_auth_toggleable จริง (ใช้กันแอดมิน
# ส่ง endpoint_key มั่วๆ มา toggle endpoint ที่ไม่มีอยู่จริงหรือไม่ได้อยู่ในระบบนี้)
AUTH_TOGGLEABLE_ENDPOINTS: dict = {}

def is_auth_enforced(endpoint_key: str) -> bool:
    """ค่าเริ่มต้นคือ True (บังคับ auth) เสมอถ้ายังไม่เคย toggle — ปลอดภัยไว้ก่อน"""
    entry = AUTH_ENFORCEMENT.get(endpoint_key)
    return True if entry is None else bool(entry.get("enabled", True))

def set_auth_enforcement(endpoint_key: str, enabled: bool, actor_uid: str | None = None) -> None:
    AUTH_ENFORCEMENT[endpoint_key] = {
        "enabled": bool(enabled), "updated_at": time.time(), "updated_by": actor_uid,
    }
    _save_auth_enforcement(AUTH_ENFORCEMENT)
    audit_log("auth_enforcement_toggled", uid=actor_uid or "", endpoint=endpoint_key, enabled=bool(enabled))

def require_auth_toggleable(view_func):
    """เหมือน require_auth ทุกประการตอนเปิดใช้งาน (default) แต่เช็ค AUTH_ENFORCEMENT
    ก่อนทุกครั้ง — ถ้าแอดมินปิดไว้เฉพาะจุดนี้ จะข้ามการบังคับ auth (ปล่อยให้โค้ดเดิม
    รันต่อแบบไม่มี request.vmax_uid ที่มาจาก JWT ตรงๆ — ยังมี fallback +
    audit_log('uid_resolved_via_fallback') ของ _vmax_bind_current_uid ทำงานอยู่เป็น
    เซฟตี้เน็ตเหมือนเดิมสำหรับ endpoint ที่ปิดการบังคับ)"""
    from functools import wraps
    endpoint_key = view_func.__name__
    AUTH_TOGGLEABLE_ENDPOINTS[endpoint_key] = True

    @wraps(view_func)
    def _wrapped(*args, **kwargs):
        if not is_auth_enforced(endpoint_key):
            return view_func(*args, **kwargs)
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        sess = verify_jwt(token)
        if not sess:
            return jsonify({"st": "error",
                             "msg": "ต้อง login ก่อน (ส่ง header Authorization: Bearer <token>)"}), 401
        request.vmax_uid = sess["uid"]
        try:
            body_uid = None
            body = request.get_json(silent=True)
            if isinstance(body, dict):
                body_uid = body.get("uid")
            supplied_uid = body_uid or request.args.get("uid") or request.form.get("uid")
            if supplied_uid is not None and str(supplied_uid).strip() and str(supplied_uid).strip() != str(request.vmax_uid).strip():
                audit_log("uid_mismatch_rejected", uid=str(request.vmax_uid), requested_uid=str(supplied_uid),
                          endpoint=request.path, method=request.method)
                return jsonify({"st":"error", "msg":"uid ไม่ตรงกับบัญชีที่ล็อกอิน"}), 403
        except Exception:
            pass
        return view_func(*args, **kwargs)
    _wrapped._vmax_auth_toggleable = True
    _wrapped._vmax_endpoint_key = endpoint_key
    return _wrapped

# ==========================================================================
# [SEC-AUDIT] ตัวช่วยความปลอดภัยกลาง (เพิ่มจากการไล่ตรวจ route ทั้งไฟล์)
#  - require_staff_rank(): บังคับ "ล็อกอิน + ยศพนักงาน" (ไม่ใช่แค่ล็อกอิน) กับ endpoint ระดับระบบ
#  - _vs_rl_*: จำกัดจำนวนครั้งที่ผิด/ล็อกชั่วคราว (ใช้กับ dev/staff login)
#  - _vs_url_trusted(): จำกัดปลายทางที่เซิร์ฟเวอร์จะส่ง API key ไปให้ (กัน key รั่ว/SSRF)
#  - strict auth mode: VMAX_STRICT_AUTH=1 (หรือ VMAX_ENV=production) ให้ endpoint เขียนข้อมูลที่เดิมเชื่อ uid จาก body
#    ต้องมี JWT จริงเท่านั้น รายชื่อ endpoint ด้านล่างเป็น snapshot จากการ audit ครั้งนี้
# ==========================================================================
import hmac as _vs_hmac
import ipaddress as _vs_ip
import threading as _vs_thr
import re as _vs_re
from urllib.parse import urlparse as _vs_urlparse


def require_staff_rank(rank_name):
    """decorator: ต้องมี Bearer JWT และเป็นพนักงานยศ >= rank_name (ดู STAFF_RANKS)"""
    def deco(view_func):
        from functools import wraps

        @wraps(view_func)
        def _wrapped(*args, **kwargs):
            uid, rank = _staff_from_request()
            if uid is None:
                return jsonify({"st": "error", "msg": "ต้องล็อกอินก่อน (Bearer token)"}), 401
            if rank is None or rank < STAFF_RANKS.get(rank_name, 10 ** 6):
                audit_log("staff_rank_denied", uid=uid, endpoint=request.path, need=rank_name)
                return jsonify({"st": "error", "msg": f"ต้องมียศ {rank_name} ขึ้นไป"}), 403
            request.vmax_uid = uid
            return view_func(*args, **kwargs)
        return _wrapped
    return deco


# ==========================================
# [ P0.7 Module Kill-Switch — เปิด/ปิดทั้งฟีเจอร์ได้จริง ไม่ใช่แค่ข้าม auth ]
# ต่อยอดจาก VMAX_MODULES (รายการฟีเจอร์ทั้งหมดที่มีชื่อ/desc ภาษาไทยอยู่แล้วในไฟล์)
# — endpoint ที่ถูกปิดจะตอบ 503 ทันทีตั้งแต่ before_request ก่อนโค้ดจริงของ view
# function จะรันเลยแม้แต่บรรทัดเดียว (ต่างจาก @require_auth_toggleable ที่แค่ข้าม
# การเช็คตัวตน แต่โค้ดข้างในยังรันอยู่) ควบคุมผ่าน 2 ทาง:
#  1) POST /api/admin/module/toggle {module, enabled} — ต้องเป็น staff ยศ >= admin
#  2) พิมพ์ภาษาไทยผ่าน /api/game-terminal/command เช่น "ปิดระบบ ล็อตเตอรี่เวิร์กช็อป"
#     (ดู _module_gate_parse_thai_command ที่เพิ่มใน api_game_terminal_command)
#
# ข้อจำกัดที่ควรรู้: VMAX_MODULES["routes"] เป็น path string ที่เขียนไว้เป็นเอกสาร
# ไม่ได้ผูกกับ Flask rule จริงแบบอัตโนมัติ บาง entry สะกดไม่ตรงกับ @app.route จริง
# 100% (เช่น <id> vs <title_id>) — ตัว resolve ด้านล่างจะจับคู่เฉพาะ path ที่สะกดตรง
# กับ app.url_map จริงเท่านั้น ที่ไม่ตรงจะถูกข้ามอย่างเงียบๆ (ปลอดภัยไว้ก่อน — "ไม่ปิด
# ถ้าไม่แน่ใจ" ดีกว่าปิดผิดจุด) เช็คได้ก่อนสั่งปิดจริงที่ GET /api/admin/module/list
# ==========================================
MODULE_ENABLEMENT_PATH = "module_enablement_registry.json"

def _load_module_enablement() -> dict:
    if os.path.exists(MODULE_ENABLEMENT_PATH):
        try:
            with open(MODULE_ENABLEMENT_PATH, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return {}
    return {}

def _save_module_enablement(reg: dict) -> None:
    with open(MODULE_ENABLEMENT_PATH, "w", encoding="utf-8") as f:
        json.dump(reg, f, ensure_ascii=False, indent=2)

# Flask endpoint (ชื่อ view function) -> {"enabled": bool, ...}
MODULE_ENDPOINT_ENABLEMENT = _load_module_enablement()

def is_endpoint_module_enabled(endpoint_key: str) -> bool:
    """default เปิดใช้งานเสมอถ้ายังไม่เคยสั่งปิด — ไม่กระทบของเดิมที่มีอยู่แล้วเลย"""
    entry = MODULE_ENDPOINT_ENABLEMENT.get(endpoint_key)
    return True if entry is None else bool(entry.get("enabled", True))

def set_endpoint_module_enabled(endpoint_key: str, enabled: bool, actor_uid: str | None = None) -> None:
    MODULE_ENDPOINT_ENABLEMENT[endpoint_key] = {
        "enabled": bool(enabled), "updated_at": time.time(), "updated_by": actor_uid,
    }
    _save_module_enablement(MODULE_ENDPOINT_ENABLEMENT)
    audit_log("module_endpoint_toggled", uid=actor_uid or "", endpoint=endpoint_key, enabled=bool(enabled))

def _resolve_module_endpoints(module_key: str) -> list:
    """คืนรายชื่อ Flask endpoint (function name) จริงที่ resolve ได้จาก
    VMAX_MODULES[module_key]['routes'] เทียบกับ app.url_map จริง — path ที่สะกดไม่ตรง
    กับ Flask rule จริงจะถูกข้ามอย่างเงียบๆ"""
    mod = VMAX_MODULES.get(module_key)
    if not mod:
        return []
    wanted = {str(w).split("?")[0].rstrip("/") for w in mod.get("routes", [])}
    found = []
    for rule in app.url_map.iter_rules():
        if rule.rule.rstrip("/") in wanted:
            found.append(rule.endpoint)
    return sorted(set(found))

def _find_modules_by_query(query: str) -> list:
    """หา module key จาก VMAX_MODULES โดยเทียบ query (ไทย/อังกฤษก็ได้) กับ
    key/name/desc — ไม่สนตัวพิมพ์เล็กใหญ่ คืนลิสต์ key ที่ match (อาจมากกว่า 1)"""
    q = query.strip().lower().replace("_", " ").replace("-", " ")
    if not q:
        return []
    if query.strip() in VMAX_MODULES:
        return [query.strip()]
    hits = []
    for key, mod in VMAX_MODULES.items():
        haystack = " ".join([key.replace("_", " "), str(mod.get("name", "")),
                             str(mod.get("desc", ""))]).lower()
        if q in haystack:
            hits.append(key)
    return hits

@app.before_request
def _vmax_module_kill_switch():
    """เช็คก่อน before_request อื่นทั้งหมด (ลงทะเบียนก่อน _vmax_bind_current_uid) —
    endpoint ที่ถูกสั่งปิดไว้จะตอบ 503 ทันที ไม่ให้โค้ดจริงรันเลยแม้แต่บรรทัดเดียว"""
    ep = request.endpoint
    if ep and not is_endpoint_module_enabled(ep):
        return jsonify({"st": "error",
                        "msg": f"ฟังก์ชันนี้ถูกปิดใช้งานอยู่ (endpoint: {ep}) — "
                                "เปิดใหม่ได้ผ่านคำสั่ง terminal 'เปิดระบบ ...' หรือ "
                                "POST /api/admin/module/toggle"}), 503

@app.route('/api/admin/module/toggle', methods=['POST'])
@require_staff_rank('admin')
def api_admin_module_toggle():
    """body: {module: "<VMAX_MODULES key หรือคำค้นไทย/อังกฤษ>", enabled: bool}
    ถ้าคำค้น match มากกว่า 1 โมดูล จะไม่เดาปิดให้ทั้งหมด — ต้องระบุให้ชัดเจนกว่านี้
    (กันปิดผิดโมดูลจากการเดา) ดูชื่อ key ที่แน่นอนได้จาก /api/admin/module/list"""
    body = request.json or {}
    query = str(body.get('module', '')).strip()
    enabled = body.get('enabled')
    if not query or enabled is None:
        return jsonify({"st": "error", "msg": "ต้องระบุ module และ enabled (true/false)"}), 400
    hits = _find_modules_by_query(query)
    if len(hits) == 0:
        return jsonify({"st": "error", "msg": f"ไม่พบโมดูลที่ตรงกับ '{query}' — "
                                                "ดูรายชื่อได้ที่ GET /api/admin/module/list"}), 404
    if len(hits) > 1:
        return jsonify({"st": "error", "msg": "เจอมากกว่า 1 โมดูลที่ตรงกับคำค้นนี้ ระบุให้ชัดเจนกว่านี้",
                        "candidates": hits}), 400
    module_key = hits[0]
    endpoints = _resolve_module_endpoints(module_key)
    if not endpoints:
        return jsonify({"st": "error",
                        "msg": f"โมดูล '{module_key}' resolve ไป Flask endpoint จริงไม่ได้เลย "
                                "(อาจเป็นโมดูลเอกสารล้วนๆ หรือ path ในเอกสารสะกดไม่ตรงกับ @app.route จริง) "
                                "— ไม่มีอะไรให้ปิด"}), 400
    for ep in endpoints:
        set_endpoint_module_enabled(ep, bool(enabled), actor_uid=getattr(request, "vmax_uid", None))
    return jsonify({"st": "ok", "module": module_key, "enabled": bool(enabled),
                    "affected_endpoints": endpoints})

@app.route('/api/admin/module/list', methods=['GET'])
@require_staff_rank('admin')
def api_admin_module_list():
    out = []
    for key, mod in VMAX_MODULES.items():
        eps = _resolve_module_endpoints(key)
        out.append({"key": key, "name": mod.get("name") or mod.get("desc", ""),
                    "resolved_endpoints": eps,
                    "enabled": (all(is_endpoint_module_enabled(e) for e in eps) if eps else None)})
    return jsonify({"st": "ok", "count": len(out), "modules": out})

def _module_gate_parse_thai_command(command_text: str):
    """เรียกจาก api_game_terminal_command — parse คำสั่งไทย 'ปิดระบบ <ชื่อ>' /
    'เปิดระบบ <ชื่อ>' / 'รายชื่อระบบ' คืน None ถ้าไม่ใช่คำสั่งกลุ่มนี้ ไม่งั้นคืน
    dict ผลลัพธ์พร้อม 'ok' บอกว่าทำสำเร็จไหม (caller เป็นคนตัดสิน permission เอง
    ก่อนเรียกฟังก์ชันนี้ — ต้องเช็ค _vmax_vm_require('system') ก่อนเสมอ)"""
    text = command_text.strip()
    low = text.lower()
    if low in ("รายชื่อระบบ", "ระบบทั้งหมด", "list modules", "system list"):
        out = []
        for key, mod in VMAX_MODULES.items():
            eps = _resolve_module_endpoints(key)
            out.append({"key": key, "name": mod.get("name") or mod.get("desc", ""),
                        "enabled": (all(is_endpoint_module_enabled(e) for e in eps) if eps else None)})
        return {"ok": True, "kind": "list", "modules": out}
    m = re.match(r"^(เปิด|ปิด)\s*ระบบ\s+(.+)$", text)
    if not m:
        return None
    want_enable = (m.group(1) == "เปิด")
    query = m.group(2).strip()
    hits = _find_modules_by_query(query)
    if len(hits) == 0:
        return {"ok": False, "kind": "toggle", "msg": f"ไม่พบระบบที่ตรงกับ '{query}'"}
    if len(hits) > 1:
        return {"ok": False, "kind": "toggle", "msg": "เจอมากกว่า 1 ระบบที่ตรงกับคำนี้ ระบุให้ชัดเจนกว่านี้",
                "candidates": hits}
    module_key = hits[0]
    endpoints = _resolve_module_endpoints(module_key)
    if not endpoints:
        return {"ok": False, "kind": "toggle",
                "msg": f"ระบบ '{module_key}' ไม่มี endpoint จริงให้ปิด/เปิด (เป็นเอกสารล้วนๆ หรือสะกด path ไม่ตรง)"}
    for ep in endpoints:
        set_endpoint_module_enabled(ep, want_enable, actor_uid=getattr(request, "vmax_uid", None))
    return {"ok": True, "kind": "toggle", "module": module_key, "enabled": want_enable,
            "affected_endpoints": endpoints}


_VS_RL_STATE = {}

_VS_RL_LOCK = _vs_thr.Lock()


def _vs_rl_retry_after(key):
    now = time.time()
    with _VS_RL_LOCK:
        st = _VS_RL_STATE.get(key)
        if st and st.get("locked_until", 0) > now:
            return int(st["locked_until"] - now) + 1
    return 0


def _vs_rl_fail(key, max_fails=8, window=900, lock_sec=900):
    now = time.time()
    with _VS_RL_LOCK:
        if len(_VS_RL_STATE) > 5000:
            for k in [k for k, v in _VS_RL_STATE.items() if v.get("locked_until", 0) < now and not v["fails"]]:
                _VS_RL_STATE.pop(k, None)
        st = _VS_RL_STATE.setdefault(key, {"fails": [], "locked_until": 0})
        st["fails"] = [t for t in st["fails"] if now - t < window] + [now]
        if len(st["fails"]) >= max_fails:
            st["locked_until"], st["fails"] = now + lock_sec, []
        return st["locked_until"] > now


def _vs_rl_reset(key):
    with _VS_RL_LOCK:
        _VS_RL_STATE.pop(key, None)


_VS_NET_NAME_RE = _vs_re.compile(r"^\w[\w .\-*()]{0,63}$")


def _vs_valid_net_name(v):
    return isinstance(v, str) and bool(_VS_NET_NAME_RE.match(v))


def _vs_valid_hotspot_params(ssid, password, iface):
    if not isinstance(ssid, str) or not isinstance(password, str) or not isinstance(iface, str):
        return False
    if not (1 <= len(ssid) <= 32) or ssid.startswith("-") or any(ord(c) < 32 or ord(c) == 127 for c in ssid):
        return False
    if not (8 <= len(password) <= 63) or password.startswith("-") or any(not (32 <= ord(c) <= 126) for c in password):
        return False
    return (not iface) or bool(_vs_re.match(r"^[A-Za-z0-9][A-Za-z0-9_.:\-]{0,31}$", iface))


def _vs_trusted_api_hosts():
    hosts = {"api.openai.com", "api.anthropic.com"}
    for ev in ("OPENAI_BASE_URL", "VMAX_MEDIA_AI_URL", "VMAX_LOCAL_AI_BASE_URL"):
        u = os.environ.get(ev, "").strip()
        if u:
            h = (_vs_urlparse(u).hostname or "").lower()
            if h:
                hosts.add(h)
    for h in os.environ.get("VMAX_TRUSTED_API_HOSTS", "").split(","):
        if h.strip():
            hosts.add(h.strip().lower())
    return hosts


def _vs_url_trusted(url):
    try:
        u = _vs_urlparse(str(url))
        return u.scheme in ("http", "https") and (u.hostname or "").lower() in _vs_trusted_api_hosts()
    except Exception:
        return False


def _vs_strict_auth_enabled():
    """[SEC-AUDIT round 2] เดิมถ้าไม่ได้ตั้ง VMAX_STRICT_AUTH หรือ VMAX_ENV=production
    เลย strict mode จะปิดเงียบๆ โดย default — แปลว่า endpoint ใน _VS_STRICT_AUTH_ENDPOINTS
    (gameplay ~100 จุด: combat/extraction/capture/wildkin/horse/weapon-duel ฯลฯ) ยังเชื่อ
    uid จาก body ตรงๆ ได้อยู่ถ้าลืมตั้ง env ตอน deploy จริง (ปลอมเป็นผู้เล่นคนอื่นได้)
    ตอนนี้ default เปลี่ยนเป็น "เปิด strict mode เสมอ" (ปลอดภัยไว้ก่อน — pattern เดียวกับ
    is_auth_enforced() ด้านบน) นอกจากจะตั้ง VMAX_STRICT_AUTH=0 ชัดเจนเพื่อปิดตอน dev/test
    เท่านั้น VMAX_ENV=production ก็ยังบังคับเปิดเสมอเหมือนเดิม (ตั้งใจกันคนตั้ง STRICT_AUTH=0
    ค้างไว้แล้วลืมปิดตอน deploy จริง)"""
    if os.environ.get("VMAX_ENV", "").strip().lower() == "production":
        return True
    v = os.environ.get("VMAX_STRICT_AUTH", "").strip().lower()
    if v in ("0", "false", "no", "off"):
        return False
    return True


