@app.route('/api/gear/t7/status', methods=['GET'])
@require_auth
def api_gear_t7_status():
    """ดูสถานะปัจจุบันของกล้อง T7 + กระเป๋า (ติดอยู่บนหมวกหรือปืน / ขาจับไหนอยู่ในกระเป๋า)"""
    uid = request.args.get("uid", P.get("uid", "VMAX-OP-01"))
    t7 = EQUIPPED_T7.get(uid)
    backpack = EQUIPPED_BACKPACK.get(uid)
    if not t7:
        return jsonify({"st": "error", "msg": "ไม่พบกล้อง T7"}), 404
    return jsonify({
        "st": "ok", "t7": t7.to_dict(),
        "backpack": backpack.to_dict() if backpack else None,
    })

# ==========================================
# [ 2E1b. Wikipedia Weapon-Attachment Catalog ]
# ดึงข้อมูล "ของแต่งอาวุธ" (สายพาน/ศูนย์เล็ง/ด้ามจับ/ราง ฯลฯ — อุปกรณ์เสริมทั่วไปที่
# วางขายถูกกฎหมายและมีบทความสารานุกรมอยู่แล้ว) จาก Wikipedia API มาเก็บเป็นคลังกลาง
# ใช้เป็น "คำอธิบายไอเทม" (flavor text/tooltip) ในระบบ Modular Gear ด้านบน — นี่คือ
# ข้อมูลสารานุกรมทั่วไปเกี่ยวกับอุปกรณ์ที่มีอยู่จริง ไม่ใช่คู่มือการผลิต/ดัดแปลง/ประกอบ
# อาวุธแต่อย่างใด (ระบบไม่ดึง/ไม่เก็บเนื้อหาประเภทนั้น)
# ==========================================
WEAPON_ATTACHMENT_WIKI_TOPICS = [
    "Optical sight", "Reflex sight", "Red dot sight", "Telescopic sight", "Iron sights",
    "Holographic weapon sight", "Bipod", "Forward grip", "Picatinny rail", "Sling (firearms)",
    "Bayonet", "Rifle scope", "Laser sight", "Weapon-mounted light", "Speed loader",
    "Magazine (firearms)", "Drum magazine", "Buttstock", "Compensator (firearms)",
    "Flash suppressor", "Recoil pad", "Cheek riser", "Sling swivel", "Bipod (weapon)",
    # [NEW] หัวข้อเพิ่มสำหรับของแต่งชุดเต็มในหน้าแต่งปืน (ใช้เป็นคำอธิบายใต้ชื่ออุปกรณ์)
    "Suppressor", "Muzzle brake", "Choke (firearms)", "Handguard", "Pistol grip", "Gun barrel",
    "Night-vision device", "Thermal weapon sight", "Box magazine",
]

WIKI_SEARCH_ENDPOINT = "https://en.wikipedia.org/w/api.php"
WIKI_SUMMARY_ENDPOINT = "https://en.wikipedia.org/api/rest_v1/page/summary/{title}"
_WIKI_UA = {"User-Agent": "VMAX-Kernel-GameServer/1.0 (internal item-flavor-text fetcher)"}

WEAPON_ATTACHMENT_WIKI_CATALOG = {}   # topic -> {title, extract, thumbnail, wiki_url, fetched_at}
_WIKI_CATALOG_LOCK = threading.Lock()


def _wiki_search_best_title(query: str, timeout: int = 8):
    """ใช้ Wikipedia Search API หาไตเติลบทความที่ตรงกับคำค้นมากที่สุด"""
    try:
        r = requests.get(WIKI_SEARCH_ENDPOINT, params={
            "action": "query", "list": "search", "srsearch": query,
            "format": "json", "srlimit": 1,
        }, headers=_WIKI_UA, timeout=timeout)
        r.raise_for_status()
        hits = r.json().get("query", {}).get("search", [])
        return hits[0]["title"] if hits else None
    except Exception as _e:
        print(f"[Wiki] ค้นหาบทความ '{query}' ไม่สำเร็จ: {_e}")
        return None


def _wiki_fetch_summary(title: str, timeout: int = 8):
    """ดึงสรุปบทความ (extract + thumbnail) จาก Wikipedia REST API"""
    try:
        url = WIKI_SUMMARY_ENDPOINT.format(title=urlquote(title.replace(" ", "_")))
        r = requests.get(url, headers=_WIKI_UA, timeout=timeout)
        if r.status_code != 200:
            return None
        j = r.json()
        return {
            "title": j.get("title", title),
            "extract": j.get("extract", ""),
            "thumbnail": (j.get("thumbnail") or {}).get("source"),
            "wiki_url": ((j.get("content_urls") or {}).get("desktop") or {}).get("page"),
        }
    except Exception as _e:
        print(f"[Wiki] ดึงสรุปบทความ '{title}' ไม่สำเร็จ: {_e}")
        return None


def wiki_sync_weapon_attachments_catalog(topics: list = None) -> dict:
    """ไล่ดึงข้อมูล 'ของแต่งอาวุธ' จาก Wikipedia มาเก็บเป็นคลังกลางในเกม (สารานุกรมทั่วไป
    ใช้เป็น flavor text ของไอเทมในระบบ Modular Gear เท่านั้น) เรียกอัตโนมัติตอนสตาร์ท
    เซิร์ฟเวอร์ครั้งเดียว หรือเรียกซ้ำผ่าน POST /api/wiki/weapon-attachments/sync เพื่ออัปเดต"""
    topics = topics or WEAPON_ATTACHMENT_WIKI_TOPICS
    synced, failed = [], []
    for topic in topics:
        best_title = _wiki_search_best_title(topic) or topic
        summary = _wiki_fetch_summary(best_title)
        if summary:
            with _WIKI_CATALOG_LOCK:
                WEAPON_ATTACHMENT_WIKI_CATALOG[topic] = {**summary, "queried_as": topic,
                                                          "fetched_at": time.time()}
            synced.append(topic)
        else:
            failed.append(topic)
        time.sleep(0.2)  # กันยิงคำขอถี่เกินไปจนโดน Wikipedia จำกัด rate
    print(f"[Wiki] ซิงก์คลังของแต่งอาวุธจาก Wikipedia แล้ว: สำเร็จ {len(synced)}/{len(topics)} รายการ")
    return {"synced": synced, "failed": failed}


@app.route('/api/wiki/weapon-attachments', methods=['GET'])
def api_wiki_weapon_attachments_list():
    """ดูคลังข้อมูลของแต่งอาวุธที่ซิงก์จาก Wikipedia ไว้แล้ว (เอาไปใช้เป็นคำอธิบายไอเทมในเกมได้เลย)"""
    with _WIKI_CATALOG_LOCK:
        return jsonify({"st": "ok", "total": len(WEAPON_ATTACHMENT_WIKI_CATALOG),
                        "items": WEAPON_ATTACHMENT_WIKI_CATALOG})


@app.route('/api/wiki/weapon-attachments/sync', methods=['POST'])
@require_auth_toggleable
def api_wiki_weapon_attachments_sync():
    """สั่งซิงก์/รีเฟรชคลังของแต่งอาวุธจาก Wikipedia ใหม่ — body: {"topics": [...]} ถ้าอยากซิงก์
    เฉพาะบางหัวข้อ ไม่ส่ง body มาจะซิงก์ตามลิสต์เริ่มต้นทั้งหมด — ทำงานเป็น background thread
    ไม่บล็อก request, ผลลัพธ์ไปดูได้ที่ GET /api/wiki/weapon-attachments ทีหลัง"""
    data = request.get_json(force=True, silent=True) or {}
    topics = data.get("topics") or None
    threading.Thread(target=wiki_sync_weapon_attachments_catalog, args=(topics,), daemon=True).start()
    return jsonify({"st": "ok", "msg": "เริ่มซิงก์คลังของแต่งอาวุธจาก Wikipedia ใน background แล้ว "
                                       "เช็คผลได้ที่ GET /api/wiki/weapon-attachments"})

# ==========================================
# [ 2E1c. Wikidata Biome / Terrain Catalog ]
# ดึงข้อมูล "ภูมิประเทศ/ไบโอม" (ป่าดงดิบ ทะเลทราย ป่าสน ป่าชายเลน ทุ่งหญ้า ฯลฯ —
# หมวดหมู่ภูมิศาสตร์ทั่วไปที่มีบทความสารานุกรมอยู่แล้ว) จาก Wikidata มาเก็บเป็นคลัง
# กลาง ใช้เป็น "คำอธิบายโซนแผนที่" (flavor text/tooltip ของโซนบนแผนที่โลก) — นี่คือ
# ข้อมูลสารานุกรมทั่วไปเกี่ยวกับประเภทภูมิประเทศที่มีอยู่จริง ไม่ใช่พิกัด/แผนที่จริง
# ของสถานที่ใดสถานที่หนึ่ง แค่คำอธิบาย+รูปประกอบของ "ประเภท" ภูมิประเทศเพื่อโยงกับ
# โซนที่สุ่มสร้างในเกม (จาก [ ระบบมินิแมพ/แผนที่โลก ] และ [ world seed generator ] ด้านบน)
# ==========================================
BIOME_WIKIDATA_TOPICS = [
    "Tropical rainforest", "Jungle", "Desert", "Temperate broadleaf forest",
    "Coniferous forest", "Taiga", "Savanna", "Swamp", "Mangrove", "Grassland",
    "Steppe", "Tundra", "Wetland", "Oasis", "Canyon", "Mountain forest",
]

WIKIDATA_SEARCH_ENDPOINT = "https://www.wikidata.org/w/api.php"
WIKIDATA_ENTITY_ENDPOINT = "https://www.wikidata.org/wiki/Special:EntityData/{qid}.json"

BIOME_WIKIDATA_CATALOG = {}   # topic -> {qid, label, description, extract, thumbnail, wiki_url, fetched_at}
_BIOME_CATALOG_LOCK = threading.Lock()


def _wikidata_search_qid(query: str, timeout: int = 8):
    """ใช้ Wikidata Search API หา QID ของหัวข้อที่ตรงกับคำค้นมากที่สุด"""
    try:
        r = requests.get(WIKIDATA_SEARCH_ENDPOINT, params={
            "action": "wbsearchentities", "search": query, "language": "en",
            "format": "json", "limit": 1, "type": "item",
        }, headers=_WIKI_UA, timeout=timeout)
        r.raise_for_status()
        hits = r.json().get("search", [])
        return hits[0]["id"] if hits else None
    except Exception as _e:
        print(f"[Wikidata] ค้นหา QID สำหรับ '{query}' ไม่สำเร็จ: {_e}")
        return None


def _wikidata_fetch_entity(qid: str, timeout: int = 8):
    """ดึงข้อมูล entity จาก Wikidata (label/description/sitelink ไปหน้า Wikipedia อังกฤษ)"""
    try:
        url = WIKIDATA_ENTITY_ENDPOINT.format(qid=qid)
        r = requests.get(url, headers=_WIKI_UA, timeout=timeout)
        if r.status_code != 200:
            return None
        ent = (r.json().get("entities") or {}).get(qid)
        if not ent:
            return None
        label = ((ent.get("labels") or {}).get("en") or {}).get("value", qid)
        desc = ((ent.get("descriptions") or {}).get("en") or {}).get("value", "")
        enwiki_title = ((ent.get("sitelinks") or {}).get("enwiki") or {}).get("title")
        return {"qid": qid, "label": label, "description": desc, "enwiki_title": enwiki_title}
    except Exception as _e:
        print(f"[Wikidata] ดึงข้อมูล entity '{qid}' ไม่สำเร็จ: {_e}")
        return None


def wikidata_sync_biome_catalog(topics: list = None) -> dict:
    """ไล่ดึงข้อมูล 'ประเภทภูมิประเทศ/ไบโอม' จาก Wikidata (+ สรุปเนื้อหาจาก Wikipedia
    ผ่านฟังก์ชันเดิม _wiki_fetch_summary) มาเก็บเป็นคลังกลางในเกม ใช้เป็น flavor text
    ของโซนแผนที่เท่านั้น เรียกอัตโนมัติตอนสตาร์ทเซิร์ฟเวอร์ครั้งเดียว หรือเรียกซ้ำผ่าน
    POST /api/wikidata/biomes/sync เพื่ออัปเดต"""
    topics = topics or BIOME_WIKIDATA_TOPICS
    synced, failed = [], []
    for topic in topics:
        qid = _wikidata_search_qid(topic)
        entity = _wikidata_fetch_entity(qid) if qid else None
        if not entity:
            failed.append(topic)
            time.sleep(0.2)
            continue
        summary = _wiki_fetch_summary(entity.get("enwiki_title") or topic) or {}
        with _BIOME_CATALOG_LOCK:
            BIOME_WIKIDATA_CATALOG[topic] = {
                "qid": entity["qid"], "label": entity["label"], "description": entity["description"],
                "extract": summary.get("extract", ""), "thumbnail": summary.get("thumbnail"),
                "wiki_url": summary.get("wiki_url"), "queried_as": topic, "fetched_at": time.time(),
            }
        synced.append(topic)
        time.sleep(0.2)  # กันยิงคำขอถี่เกินไปจนโดน Wikidata/Wikipedia จำกัด rate
    print(f"[Wikidata] ซิงก์คลังไบโอม/ภูมิประเทศแล้ว: สำเร็จ {len(synced)}/{len(topics)} รายการ")
    return {"synced": synced, "failed": failed}


@app.route('/api/wikidata/biomes', methods=['GET'])
def api_wikidata_biomes_list():
    """ดูคลังข้อมูลไบโอม/ภูมิประเทศที่ซิงก์จาก Wikidata ไว้แล้ว (เอาไปใช้เป็นคำอธิบายโซนแผนที่ในเกมได้เลย)"""
    with _BIOME_CATALOG_LOCK:
        return jsonify({"st": "ok", "total": len(BIOME_WIKIDATA_CATALOG),
                        "items": BIOME_WIKIDATA_CATALOG})


@app.route('/api/wikidata/biomes/sync', methods=['POST'])
@require_auth_toggleable
def api_wikidata_biomes_sync():
    """สั่งซิงก์/รีเฟรชคลังไบโอม/ภูมิประเทศจาก Wikidata ใหม่ — body: {"topics": [...]} ถ้าอยากซิงก์
    เฉพาะบางหัวข้อ (เช่น "Desert", "Jungle") ไม่ส่ง body มาจะซิงก์ตามลิสต์เริ่มต้นทั้งหมด —
    ทำงานเป็น background thread ไม่บล็อก request, ผลลัพธ์ไปดูได้ที่ GET /api/wikidata/biomes ทีหลัง"""
    data = request.get_json(force=True, silent=True) or {}
    topics = data.get("topics") or None
    threading.Thread(target=wikidata_sync_biome_catalog, args=(topics,), daemon=True).start()
    return jsonify({"st": "ok", "msg": "เริ่มซิงก์คลังไบโอม/ภูมิประเทศจาก Wikidata ใน background แล้ว "
                                       "เช็คผลได้ที่ GET /api/wikidata/biomes"})

# ลงทะเบียนใน VMAX_MODULES
VMAX_MODULES["wikidata_biomes"] = {
    "name": "คลังข้อมูลไบโอม/ภูมิประเทศจาก Wikidata", "level": "basic", "category": "content",
    "desc": "ดึงคำอธิบาย+รูปของประเภทภูมิประเทศ (ป่าดงดิบ ทะเลทราย ป่าสน ป่าชายเลน ทุ่งหญ้า ฯลฯ) "
            "จาก Wikidata/Wikipedia มาใช้เป็น flavor text ของโซนบนแผนที่โลก",
    "routes": ["/api/wikidata/biomes", "/api/wikidata/biomes/sync"],
}


# ==========================================
# [ 2E2. Safe Value Check & Gold Tag Event System ]
# Server-Authoritative + Signed Event Tokens
# - ไม่มีการแคปจอ/OCR
# - ทุก event (ฆ่าศัตรู, แลกป้ายทอง) ต้องมี token ที่เซ็นจากฝั่งเกมเซิร์ฟเวอร์เท่านั้น
# - token ใช้ได้ครั้งเดียว (กัน replay) และหมดอายุตามเวลา (TTL)
# ==========================================
import hmac
import hashlib
import secrets as _secrets
from functools import wraps

# --- ตั้งค่า ---
MAP_ENTRY_VALUE_LIMIT = 500000        # ค่าเข้าแมพสูงสุด
EVENT_TOKEN_TTL_SECONDS = 60          # token มีอายุกี่วินาที (กันเก็บไว้ใช้ทีหลัง)

# Secret key สำหรับเซ็น token — ต้องเก็บเป็นความลับ ไม่ให้ client รู้เด็ดขาด
# (โปรดตั้งผ่าน environment variable จริงในการใช้งานจริง เช่น os.environ["EVENT_SIGNING_SECRET"])
EVENT_SIGNING_SECRET = _secrets.token_bytes(32)

# --- ตู้เซฟส่วนกลาง (Central Stash) ของแมพ ---
# [BUG-FIX #18] CENTRAL_STASH เป็น dict กลางที่หลาย request/thread แก้พร้อมกันได้
# (ผู้เล่นหลายคนยิงป้ายทองเข้าคลัง หรือพยายาม extract พร้อมกัน) เดิมไม่มี lock เลย —
# เกิด race แบบ "double read-modify-write" ได้จริง เช่นสอง extract request ที่
# use_gold_tag_event=true มาพร้อมกัน ทั้งคู่อ่าน stash_tags >= 2 เป็น True ก่อนที่
# อีกฝั่งจะเขียนค่าที่หักแล้วกลับไป ผลคือป้ายทองถูกใช้ซ้ำ (double-spend) จริง ไม่ใช่
# แค่ตัวเลขคลาดเคลื่อนเล็กน้อย — ครอบทุกจุดที่อ่าน+เขียน CENTRAL_STASH ด้วย lock นี้
_CENTRAL_STASH_LOCK = threading.Lock()
CENTRAL_STASH = {"gold_tags": 0}

# ==========================================
# MySQL Connection (ต่อกับฐานข้อมูลจริง)
# ตั้งค่าผ่าน environment variables เท่านั้น — ห้าม hardcode รหัสผ่านในโค้ด
#   export DB_HOST=localhost
#   export DB_PORT=3306
#   export DB_USER=vmax_app
#   export DB_PASSWORD=xxxxx
#   export DB_NAME=vmax_game
# ต้องมีตาราง (ตัวอย่าง schema):
#   CREATE TABLE player_safe_items (
#       uid VARCHAR(64) NOT NULL,
#       item_key VARCHAR(64) NOT NULL,
#       qty INT NOT NULL DEFAULT 0,
#       value_per_unit INT NOT NULL DEFAULT 0,
#       PRIMARY KEY (uid, item_key)
#   );
# ถ้าเชื่อม DB ไม่ได้ (ตั้งค่าไม่ครบ/เซิร์ฟเวอร์ DB ล่ม) ระบบจะ fallback เป็น
# in-memory dict ชั่วคราวโดยอัตโนมัติ พร้อม log แจ้งเตือน — เพื่อไม่ให้ endpoint
# ทั้งหมดล่มไปด้วย แต่ข้อมูลจะไม่ persist ข้าม restart จนกว่าจะแก้การเชื่อมต่อ
# ==========================================
import os as _os
import logging as _logging

_db_logger = _logging.getLogger("vmax.db")

try:
    import pymysql as _pymysql
    import pymysql.cursors as _pymysql_cursors
    _MYSQL_LIB_AVAILABLE = True
except ImportError:
    _MYSQL_LIB_AVAILABLE = False
    _db_logger.warning("ไม่พบไลบรารี pymysql — รัน: pip install pymysql")

_DB_CONFIG = {
    "host": _os.environ.get("DB_HOST"),
    "port": int(_os.environ.get("DB_PORT", "3306")),
    "user": _os.environ.get("DB_USER"),
    "password": _os.environ.get("DB_PASSWORD"),
    "database": _os.environ.get("DB_NAME"),
}

# fallback ในหน่วยความจำ ใช้เฉพาะตอนเชื่อม MySQL ไม่ได้เท่านั้น
_PLAYER_SAFE_DB_FALLBACK = {
    "VMAX-OP-01": {
        "diamond": {"qty": 10, "value_per_unit": 15000},
        "gold_bar": {"qty": 5, "value_per_unit": 10000}
    }
}


def _db_config_is_complete() -> bool:
    return all([_DB_CONFIG["host"], _DB_CONFIG["user"],
                _DB_CONFIG["password"], _DB_CONFIG["database"]])


def _get_db_connection():
    """คืน connection ใหม่ทุกครั้ง (short-lived) ถ้าเชื่อมไม่ได้คืน None แทนการ raise
    เพื่อให้ endpoint fallback ไปใช้ in-memory ต่อได้โดยไม่ล่มทั้งระบบ"""
    if not _MYSQL_LIB_AVAILABLE or not _db_config_is_complete():
        return None
    try:
        return _pymysql.connect(
            host=_DB_CONFIG["host"],
            port=_DB_CONFIG["port"],
            user=_DB_CONFIG["user"],
            password=_DB_CONFIG["password"],
            database=_DB_CONFIG["database"],
            cursorclass=_pymysql_cursors.DictCursor,
            connect_timeout=3,
            autocommit=True,
        )
    except Exception as e:
        _db_logger.error(f"เชื่อมต่อ MySQL ไม่สำเร็จ, ใช้ fallback in-memory แทน: {e}")
        return None


# ==========================================
# Central Server Client (เซิร์ฟเวอร์กลางแยกพอร์ต — ดู central_server.py)
# ลำดับความสำคัญ: Central Server -> MySQL local -> in-memory fallback
# ==========================================
_CENTRAL_SERVER_URL = _os.environ.get("CENTRAL_SERVER_URL")  # เช่น http://127.0.0.1:6100
_CENTRAL_API_KEY = _os.environ.get("CENTRAL_API_KEY")


def _central_get(uid: str, state_key: str):
    """ขอข้อมูลจาก Central Server ก่อนเสมอ คืน None ถ้าเรียกไม่ได้ (ให้ fallback ต่อไป)"""
    if not _CENTRAL_SERVER_URL or not _CENTRAL_API_KEY:
        return None
    try:
        resp = requests.get(
            f"{_CENTRAL_SERVER_URL.rstrip('/')}/api/central/player/{uid}/{state_key}",
            headers={"X-API-Key": _CENTRAL_API_KEY},
            timeout=3,
        )
        if resp.status_code != 200:
            _db_logger.warning(f"Central Server ตอบ {resp.status_code}, ใช้ fallback แทน")
            return None
        body = resp.json()
        if not body.get("found"):
            return None
        return body.get("value")
    except Exception as e:
        _db_logger.warning(f"เรียก Central Server ไม่สำเร็จ, ใช้ fallback แทน: {e}")
        return None


def _central_set(uid: str, state_key: str, value) -> bool:
    """เขียนข้อมูลไป Central Server คืน True ถ้าสำเร็จ"""
    if not _CENTRAL_SERVER_URL or not _CENTRAL_API_KEY:
        return False
    try:
        resp = requests.put(
            f"{_CENTRAL_SERVER_URL.rstrip('/')}/api/central/player/{uid}/{state_key}",
            headers={"X-API-Key": _CENTRAL_API_KEY},
            json={"value": value},
            timeout=3,
        )
        return resp.status_code == 200
    except Exception as e:
        _db_logger.warning(f"เขียนไป Central Server ไม่สำเร็จ: {e}")
        return False


def _player_safe_items_from_db(uid: str):
    """ดึงรายการไอเทมในตู้เซฟของผู้เล่นจาก MySQL ถ้าเชื่อมได้
    คืน None ถ้าเชื่อม DB ไม่ได้ (ให้ผู้เรียกไป fallback เอง)"""
    conn = _get_db_connection()
    if conn is None:
        return None
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT item_key, qty, value_per_unit FROM player_safe_items WHERE uid = %s",
                (uid,)
            )
            rows = cur.fetchall()
        return {r["item_key"]: {"qty": r["qty"], "value_per_unit": r["value_per_unit"]} for r in rows}
    except Exception as e:
        _db_logger.error(f"query player_safe_items ล้มเหลว, ใช้ fallback in-memory แทน: {e}")
        return None
    finally:
        conn.close()


def _get_player_safe_items(uid: str) -> dict:
    """จุดเดียวที่โค้ดส่วนอื่นเรียกใช้
    ลำดับ: Central Server (แยกพอร์ต, เข้ารหัส) -> MySQL local -> in-memory fallback"""
    from_central = _central_get(uid, "safe_items")
    if from_central is not None:
        return from_central

    from_db = _player_safe_items_from_db(uid)
    if from_db is not None:
        return from_db

    return _PLAYER_SAFE_DB_FALLBACK.get(uid, {})


# ==========================================
# [ 2E3. Central Data Server — ในไฟล์เดียวกัน แต่รันคนละพอร์ต ]
# หมายเหตุทางเทคนิคที่ต้องรู้: Flask/Werkzeug 1 instance bind ได้แค่ 1 พอร์ต
# ต่อการเรียก .run() 1 ครั้ง ดังนั้น "ไฟล์เดียวแต่ 2 พอร์ต" ทำได้จริง โดยสร้าง
# Flask app คนละตัว (ในที่นี้คือ CENTRAL_APP แยกจาก app หลัก) แล้วรัน .run()
# ของแต่ละตัวคนละ thread — ไม่ใช่การรวมเป็น process/พอร์ตเดียวกัน (ทำไม่ได้จริง)
# แต่เป็น "รันสอง server พร้อมกันจากไฟล์เดียว" ซึ่งตรงกับสิ่งที่ต้องการ
#
# เก็บข้อมูลลง MySQL จริง + เข้ารหัสก่อนบันทึก (Fernet) + ยืนยันด้วย API key
# ==========================================
CENTRAL_APP = Flask(__name__ + "_central")
# [SECURITY-FIX C1] Central Server รับแค่ JSON เล็กๆ — จำกัดขนาด body กัน DoS/ดิสก์เต็ม
CENTRAL_APP.config["MAX_CONTENT_LENGTH"] = int(_os.environ.get("CENTRAL_MAX_BODY_KB", "1024")) * 1024
_CENTRAL_ID_RE = __import__("re").compile(r"^[A-Za-z0-9_.@:\-]{1,128}$")

_CENTRAL_SERVER_PORT = int(_os.environ.get("CENTRAL_SERVER_PORT", "6100"))
_CENTRAL_SERVER_HOST = _os.environ.get("CENTRAL_SERVER_HOST", "127.0.0.1")

_DB_ENC_KEY = _os.environ.get("CENTRAL_DB_ENCRYPTION_KEY")
_central_fernet = None
try:
    from cryptography.fernet import Fernet as _Fernet, InvalidToken as _InvalidToken
    _CENTRAL_CRYPTO_AVAILABLE = True
except ImportError:
    _CENTRAL_CRYPTO_AVAILABLE = False

# [SECURITY: FORCE ENCRYPTION] เดิมถ้าลืมตั้ง CENTRAL_DB_ENCRYPTION_KEY ระบบจะเก็บ
# ข้อมูลลง DB แบบ plaintext เงียบๆ (แค่ log warning) — เปลี่ยนพฤติกรรมใหม่: ถ้าไม่มี
# key ที่ตั้งเองผ่าน env ให้ "สร้าง key ให้อัตโนมัติ" แล้วเก็บไว้ในไฟล์ local ที่จำกัด
# สิทธิ์การอ่าน (chmod 600) เพื่อให้ข้อมูลถูกเข้ารหัสเสมอ ไม่มีเส้นทางไหนที่เขียน
# ข้อมูลแบบไม่เข้ารหัสลง DB ได้อีก ถ้าไม่มี `cryptography` ติดตั้งอยู่เลย ระบบจะปฏิเสธ
# ไม่ยอมสตาร์ท Central Server แทนที่จะรันแบบไม่เข้ารหัส (fail-closed)
_CENTRAL_KEY_FILE = _os.environ.get(
    "CENTRAL_DB_ENCRYPTION_KEY_FILE",
    _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), ".vmax_central_db.key")
)


def _central_load_or_create_key() -> str:
    if _DB_ENC_KEY:
        return _DB_ENC_KEY
    if _os.path.exists(_CENTRAL_KEY_FILE):
        with open(_CENTRAL_KEY_FILE, "r") as _kf:
            existing = _kf.read().strip()
        if existing:
            return existing
    new_key = _Fernet.generate_key().decode()
    _old_umask = _os.umask(0o177)
    try:
        with open(_CENTRAL_KEY_FILE, "w") as _kf:
            _kf.write(new_key)
    finally:
        _os.umask(_old_umask)
    try:
        _os.chmod(_CENTRAL_KEY_FILE, 0o600)
    except Exception:
        pass
    _db_logger.warning(
        "CENTRAL_DB_ENCRYPTION_KEY ไม่ได้ตั้งไว้ — สร้างคีย์ใหม่อัตโนมัติและบันทึกไว้ที่ "
        f"{_CENTRAL_KEY_FILE} (permission 600) เพื่อให้ข้อมูลยังถูกเข้ารหัสเสมอ "
        "สำหรับ production ให้ตั้ง env CENTRAL_DB_ENCRYPTION_KEY เอง แล้วเก็บ key ไว้ในที่ปลอดภัย "
        "(secrets manager) แทนการพึ่งไฟล์นี้ — และห้ามลบ/สลับไฟล์นี้โดยไม่ backup เพราะข้อมูลเก่าจะถอดรหัสไม่ได้"
    )
    return new_key


if not _CENTRAL_CRYPTO_AVAILABLE:
    raise RuntimeError(
        "VMAX Central Server ต้องการแพ็กเกจ `cryptography` เพื่อเข้ารหัสข้อมูลผู้เล่นเสมอ "
        "(ไม่อนุญาตให้รันแบบไม่เข้ารหัสอีกต่อไป) — ติดตั้งด้วย: pip install cryptography"
    )

_central_fernet = _Fernet(_central_load_or_create_key().encode())


# ============================================================================
# [ AUTO .ENV.EXAMPLE WRITER ]
# เขียนไฟล์ .env.example ให้อัตโนมัติข้างสคริปต์นี้ตอนรันครั้งแรก (ถ้ายังไม่มีไฟล์อยู่)
# รวมทุกตัวแปร environment ที่มีผลต่อความปลอดภัย (JWT secret, DB encryption key,
# API key ต่างๆ ฯลฯ) พร้อมคำอธิบายว่าตัวไหน "ต้องตั้ง" ตัวไหน "แนะนำ" — ทำให้ทั้งโปรเจกต์
# อยู่ในไฟล์ .py ไฟล์เดียว ไม่ต้องแนบ .env.example แยกอีกไฟล์
# ============================================================================
