def _vmax_write_dotenv_example_if_missing():
    try:
        _target = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), ".env.example")
        if not _os.path.exists(_target):
            with open(_target, "w", encoding="utf-8") as _f:
                _f.write(_VMAX_DOTENV_EXAMPLE_CONTENT)
            print(f"[VMAX Kernel] สร้าง .env.example ให้แล้วที่ {_target} — คัดลอกเป็น .env แล้วกรอกค่าจริงก่อน deploy")
    except Exception as _e:
        print(f"[VMAX Kernel][WARNING] เขียน .env.example อัตโนมัติไม่สำเร็จ: {_e}")

_vmax_write_dotenv_example_if_missing()

if not _CENTRAL_API_KEY:
    _db_logger.warning("ยังไม่ได้ตั้งค่า CENTRAL_API_KEY — Central Server จะปฏิเสธทุก request จนกว่าจะตั้งค่า")


def _central_encrypt(value_dict) -> str:
    raw = json.dumps(value_dict, ensure_ascii=False)
    return _central_fernet.encrypt(raw.encode()).decode()


def _central_decrypt(stored: str):
    try:
        raw = _central_fernet.decrypt(stored.encode()).decode()
    except _InvalidToken:
        _db_logger.error("ถอดรหัสข้อมูล Central Server ไม่สำเร็จ — คีย์อาจไม่ตรง")
        return None
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        return None


def _central_require_api_key(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        if not _CENTRAL_API_KEY:
            return jsonify({"st": "error", "msg": "เซิร์ฟเวอร์ยังไม่ได้ตั้งค่า CENTRAL_API_KEY"}), 503
        given = request.headers.get("X-API-Key", "")
        if not hmac.compare_digest(given, _CENTRAL_API_KEY):
            return jsonify({"st": "error", "msg": "API key ไม่ถูกต้อง"}), 401
        return f(*args, **kwargs)
    return wrapper


@CENTRAL_APP.route('/api/central/player/<uid>/<state_key>', methods=['GET'])
@_central_require_api_key
def central_get_player_state(uid, state_key):
    # [SECURITY-FIX C1] whitelist รูปแบบ uid/state_key (ยัง parameterized %s อยู่เหมือนเดิม
    # นี่คือชั้นป้องกันที่สอง — defense in depth กัน SQL injection / ข้อมูลขยะ)
    if not _CENTRAL_ID_RE.match(uid or "") or not _CENTRAL_ID_RE.match(state_key or ""):
        return jsonify({"st": "error", "msg": "uid/state_key ไม่ถูกต้อง"}), 400
    conn = _get_db_connection()
    if conn is None:
        return jsonify({"st": "error", "msg": "เชื่อมต่อฐานข้อมูลกลางไม่ได้"}), 503
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT state_value_encrypted FROM central_player_state WHERE uid=%s AND state_key=%s",
                (uid, state_key)
            )
            row = cur.fetchone()
        if row is None:
            return jsonify({"st": "ok", "found": False, "value": None})
        value = _central_decrypt(row["state_value_encrypted"])
        if value is None:
            return jsonify({"st": "error", "msg": "ข้อมูลเสียหายหรือถอดรหัสไม่ได้"}), 500
        return jsonify({"st": "ok", "found": True, "value": value})
    except Exception as e:
        _db_logger.error(f"Central Server query ล้มเหลว: {e}")
        return jsonify({"st": "error", "msg": "เกิดข้อผิดพลาดฝั่งเซิร์ฟเวอร์"}), 500
    finally:
        conn.close()


@CENTRAL_APP.route('/api/central/player/<uid>/<state_key>', methods=['PUT'])
@_central_require_api_key
def central_set_player_state(uid, state_key):
    if not _CENTRAL_ID_RE.match(uid or "") or not _CENTRAL_ID_RE.match(state_key or ""):
        return jsonify({"st": "error", "msg": "uid/state_key ไม่ถูกต้อง"}), 400
    d = request.get_json(force=True, silent=True)
    if d is None or "value" not in d:
        return jsonify({"st": "error", "msg": "ต้องส่ง JSON body ที่มี field 'value'"}), 400

    conn = _get_db_connection()
    if conn is None:
        return jsonify({"st": "error", "msg": "เชื่อมต่อฐานข้อมูลกลางไม่ได้"}), 503
    try:
        encrypted = _central_encrypt(d["value"])
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO central_player_state (uid, state_key, state_value_encrypted)
                   VALUES (%s, %s, %s)
                   ON DUPLICATE KEY UPDATE state_value_encrypted = VALUES(state_value_encrypted)""",
                (uid, state_key, encrypted)
            )
        return jsonify({"st": "ok", "msg": "บันทึกแล้ว"})
    except Exception as e:
        _db_logger.error(f"Central Server insert/update ล้มเหลว: {e}")
        return jsonify({"st": "error", "msg": "เกิดข้อผิดพลาดฝั่งเซิร์ฟเวอร์"}), 500
    finally:
        conn.close()


@CENTRAL_APP.route('/api/central/health', methods=['GET'])
def central_health():
    db_ok = _get_db_connection() is not None
    return jsonify({"st": "ok", "db_connected": db_ok, "encryption_enabled": True,
                     "encryption_key_source": "env" if _DB_ENC_KEY else "auto_generated_file"})


def _start_central_server():
    """เรียกจาก main thread ก่อน sio.run() หลัก — รัน Central Server ใน background thread
    คนละพอร์ต (default 6100) จากเซิร์ฟเวอร์เกมหลัก (5000)"""
    if not _CENTRAL_API_KEY:
        print("⚠️  ยังไม่ได้ตั้งค่า CENTRAL_API_KEY — Central Server จะปฏิเสธทุก request")
    if not _DB_ENC_KEY:
        print(f"⚠️  ยังไม่ได้ตั้งค่า CENTRAL_DB_ENCRYPTION_KEY — ใช้คีย์ที่สร้างอัตโนมัติจาก {_CENTRAL_KEY_FILE} แทน "
              "(ข้อมูลยังถูกเข้ารหัสเสมอ แต่แนะนำให้ตั้ง env เองก่อนใช้งานจริง)")

    def _run():
        print(f"👉 Central Server กำลังรันที่: http://{_CENTRAL_SERVER_HOST}:{_CENTRAL_SERVER_PORT}")
        CENTRAL_APP.run(host=_CENTRAL_SERVER_HOST, port=_CENTRAL_SERVER_PORT,
                         debug=False, use_reloader=False)

    threading.Thread(target=_run, daemon=True).start()


# --- เก็บ token ที่ถูกใช้ไปแล้ว กัน replay ---
# [BUG-FIX #12] เดิมเป็น set() เปล่าๆ ไม่มีการลบออกเลยตลอดอายุ process — token ทุก
# อันที่เคยถูก verify (ไม่ว่าจะสำเร็จหรือไม่) ค้างอยู่ในหน่วยความจำตลอดไป memory leak
# แบบค่อยๆ โตไปเรื่อยๆ ตามจำนวน event ที่เกิดขึ้นทั้งหมดของ server ที่รันนาน — ในเมื่อ
# ตัว token เองมี TTL (EVENT_TOKEN_TTL_SECONDS) อยู่แล้ว ก็ไม่มีประโยชน์ต้องจำ token
# ที่หมดอายุไปนานแล้ว เปลี่ยนเป็น dict เก็บ token -> เวลาหมดอายุ แล้วกวาดทิ้งเป็นระยะ
# ในรอบเดียวกับ prune_expired_auth_state() (ดู tele_loop ด้านล่าง)
_USED_EVENT_TOKENS = {}   # token -> expires_at (epoch seconds)
# [SECURITY-FIX R1] เดิมเช็ค "token in _USED_EVENT_TOKENS" แล้วค่อยมา mark ทีหลังใน
# _verify_event_token โดยไม่มี lock — request 2 ตัวที่ยิงพร้อมกันด้วย token เดียวกัน
# ผ่านการเช็คทั้งคู่ก่อนที่ใครจะ mark = ปั๊มป้ายทอง/เงินซ้ำได้ (race condition แบบ TOCTOU)
# ตอนนี้ "เช็ค + mark" ทำใน critical section เดียว (atomic)
_USED_EVENT_TOKENS_LOCK = threading.Lock()

def _prune_used_event_tokens():
    """ลบ token ที่หมดอายุไปแล้วออกจาก _USED_EVENT_TOKENS กัน dict โตไม่มีที่สิ้นสุด"""
    now = time.time()
    with _USED_EVENT_TOKENS_LOCK:
        for tok in [t for t, exp in list(_USED_EVENT_TOKENS.items()) if now > exp]:
            _USED_EVENT_TOKENS.pop(tok, None)


# หมายเหตุสำคัญ: _issue_event_token ต้องถูกเรียกจากฝั่งเกมเซิร์ฟเวอร์เท่านั้น
# (โค้ดที่รันในเครื่องเกม ไม่ใช่โค้ดที่ client ควบคุมได้) หลังจากตรวจสอบแล้วว่า
# ผู้เล่นทำ action นั้นสำเร็จจริง เช่น ฆ่าศัตรูครบตามเงื่อนไขในเกมจริง
# ห้าม expose endpoint นี้ให้ client เรียกเองโดยตรงเด็ดขาด มิเช่นนั้นจะเปิดช่องโกงเหมือนเดิม
def _issue_event_token(uid: str, event_type: str, payload: dict) -> str:
    """สร้าง signed token สำหรับ event หนึ่งครั้ง ต้องเรียกจากฝั่งเกมเซิร์ฟเวอร์เท่านั้น

    [P0 FIX #1] เดิม payload ถูกใช้คำนวณ sig ตอน "ออก" token เท่านั้น แต่ตอน "ตรวจ"
    (_verify_event_token) ใช้ค่าคงที่ "[]" เสมอแทนที่จะเป็น payload จริง — เท่ากับ
    payload ไม่เคยถูกยืนยันด้วยลายเซ็นจริงๆ เลย ผลคือ endpoint ที่เรียกใช้ token นี้
    (gold_tag drop_all / lobby_redeem) ต้องเชื่อค่า amount / required_tags ที่ "client"
    ส่งมาในตัว JSON request โดยตรง ไม่ได้ผูกกับ token ที่เซ็นมาเลย — ส่งค่าติดลบหรือ
    ค่าใหญ่ผิดปกติมาก็ปั่นเศรษฐกิจ (เงิน/ป้ายทอง) ได้ทันที ตอนนี้ payload ถูกฝังลงใน
    ตัว token เอง (base64) และเป็นส่วนหนึ่งของข้อมูลที่เซ็นจริง เวลา verify จะคืน
    payload ที่ผ่านการยืนยันแล้วกลับไปให้ endpoint ใช้แทนค่าที่ client ส่งมา"""
    ts = int(time.time())
    nonce = _secrets.token_hex(8)
    payload_json = json.dumps(payload or {}, sort_keys=True, separators=(",", ":"))
    payload_b64 = base64.urlsafe_b64encode(payload_json.encode()).decode()
    raw = f"{uid}|{event_type}|{ts}|{nonce}|{payload_b64}"
    sig = hmac.new(EVENT_SIGNING_SECRET, raw.encode(), hashlib.sha256).hexdigest()
    return f"{uid}.{event_type}.{ts}.{nonce}.{payload_b64}.{sig}"


def _verify_event_token(token: str, uid: str, event_type: str):
    """ตรวจสอบ token: ลายเซ็นถูกต้อง, ยังไม่หมดอายุ, ยังไม่เคยถูกใช้
    คืนค่า (ok: bool, msg: str, payload: dict) — payload คือค่าที่เซ็นรับรองมาจริง
    ตอน _issue_event_token endpoint ที่เรียกใช้ต้องอ่านค่า (เช่น amount/required_tags)
    จาก payload นี้เท่านั้น ห้ามเชื่อค่าที่ client ส่งมาเองในตัว request อีกต่อไป"""
    try:
        # [BUG-FIX] เดิมใช้ .split(".") เฉยๆ ถ้า uid มีจุดอยู่ในตัว (เช่น
        # อีเมล หรือ "player.01") จะได้ส่วนเกินมาแล้ว unpack ไม่ลง 6 ตัวแปร
        # (ValueError ถูกจับไว้อยู่แล้วก็จริง แต่ผลคือ token ที่ถูกต้องของ uid
        # แบบนี้จะถูกปฏิเสธเสมอ) แก้เป็น rsplit(".", 5) เพื่อแยกจากขวาแค่ 5 จุด
        # ส่วนจุดที่เหลือ (ถ้ามี) จะยังอยู่ใน uid ตามเดิม ไม่ถูกตัดขาด
        t_uid, t_event, t_ts, t_nonce, t_payload_b64, t_sig = token.rsplit(".", 5)
    except (ValueError, AttributeError):
        return False, "รูปแบบ token ไม่ถูกต้อง", {}

    if t_uid != uid or t_event != event_type:
        return False, "token ไม่ตรงกับผู้เล่นหรือประเภท event นี้", {}

    if token in _USED_EVENT_TOKENS:
        return False, "token นี้ถูกใช้ไปแล้ว (ห้ามใช้ซ้ำ)", {}

    try:
        ts = int(t_ts)
    except ValueError:
        return False, "token เสียหาย", {}

    if time.time() - ts > EVENT_TOKEN_TTL_SECONDS:
        return False, "token หมดอายุแล้ว", {}

    raw = f"{t_uid}|{t_event}|{t_ts}|{t_nonce}|{t_payload_b64}"
    expected_sig = hmac.new(EVENT_SIGNING_SECRET, raw.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected_sig, t_sig):
        return False, "ลายเซ็น token ไม่ถูกต้อง (อาจถูกปลอมแปลง)", {}

    try:
        payload = json.loads(base64.urlsafe_b64decode(t_payload_b64.encode()).decode())
        if not isinstance(payload, dict):
            payload = {}
    except Exception:
        return False, "payload ใน token เสียหาย", {}

    # เก็บไว้จนกว่าจะหมดอายุจริง (เผื่อเวลา verify ซ้ำใน edge case) แทนที่จะเก็บตลอดไป
    # [SECURITY-FIX R1] เช็คซ้ำ + mark แบบ atomic ใต้ lock (กัน 2 request ใช้ token เดียวกันพร้อมกัน)
    with _USED_EVENT_TOKENS_LOCK:
        if token in _USED_EVENT_TOKENS:
            return False, "token นี้ถูกใช้ไปแล้ว (ห้ามใช้ซ้ำ)", {}
        _USED_EVENT_TOKENS[token] = ts + EVENT_TOKEN_TTL_SECONDS
    return True, "ok", payload


def _calculate_safe_value(uid):
    player_items = _get_player_safe_items(uid)
    total_value = 0
    for item_data in player_items.values():
        total_value += item_data.get("qty", 0) * item_data.get("value_per_unit", 0)
    return total_value


# --- ระบบ 1: เช็คค่าเข้าแมพ จาก Database ฝั่งเซิร์ฟเวอร์โดยตรง ---
@app.route('/api/safe/scan', methods=['POST'])
@require_auth_toggleable
def api_safe_scan():
    d = request.get_json(force=True, silent=True) or {}
    uid = d.get("uid", "VMAX-OP-01")

    total = _calculate_safe_value(uid)
    can_enter = total <= MAP_ENTRY_VALUE_LIMIT

    return jsonify({
        "st": "ok",
        "total_value": total,
        "can_enter_map": can_enter,
        "msg": "ปลอดภัย เข้าแมพได้" if can_enter else "แจ้งเตือน! มูลค่าในตู้เซฟเกินค่าเข้าแมพ"
    })


# --- ระบบ 2: ฆ่าศัตรูครบ -> ป้ายทองเข้าตู้เซฟส่วนกลาง (ต้องมี token จากเกมเซิร์ฟเวอร์) ---
@app.route('/api/event/gold_tag/drop_all', methods=['POST'])
@require_auth_toggleable
def api_gold_tag_drop_all():
    d = request.get_json(force=True, silent=True) or {}
    uid = d.get("uid", "VMAX-OP-01")
    token = d.get("event_token")

    if not token:
        return jsonify({"st": "error", "msg": "ต้องมี event_token ที่ออกจากเกมเซิร์ฟเวอร์"}), 400

    ok, msg, ev_payload = _verify_event_token(token, uid, "kill_all_enemies")
    if not ok:
        return jsonify({"st": "error", "msg": f"token ไม่ผ่านการตรวจสอบ: {msg}"}), 403

    # [P0 FIX #1] amount มาจาก payload ที่เซ็นรับรองไว้ในตัว token เท่านั้น
    # ไม่ใช่ค่า "amount" ที่ client ส่งมาใน request อีกต่อไป
    amt = ev_payload.get("amount", 1)
    if not isinstance(amt, int) or amt <= 0 or amt > 10:
        return jsonify({"st": "error", "msg": "จำนวนป้ายทองไม่ถูกต้อง"}), 400

    with _CENTRAL_STASH_LOCK:
        CENTRAL_STASH["gold_tags"] += amt
        current_stash = CENTRAL_STASH["gold_tags"]
    return jsonify({
        "st": "ok",
        "msg": "ฆ่าศัตรูครบ! ป้ายทองเข้าตู้เซฟส่วนกลางอัตโนมัติ",
        "central_gold_tags": current_stash
    })


# --- ระบบ 3: ออกแมพ -> ทางออกพิเศษ / ทางออกปกติ (ต้องมี token) ---
@app.route('/api/event/gold_tag/extract', methods=['POST'])
@require_auth_toggleable
def api_gold_tag_extract():
    d = request.get_json(force=True, silent=True) or {}
    uid = d.get("uid", "VMAX-OP-01")
    token = d.get("event_token")

    if not token:
        return jsonify({"st": "error", "msg": "ต้องมี event_token ที่ออกจากเกมเซิร์ฟเวอร์"}), 400

    ok, msg, _ev_payload = _verify_event_token(token, uid, "extract_map")
    if not ok:
        return jsonify({"st": "error", "msg": f"token ไม่ผ่านการตรวจสอบ: {msg}"}), 403

    inv = INVENTORY.setdefault(uid, {})

    # [BUG-FIX #18] อ่าน+เช็ค+หัก+เคลียร์ CENTRAL_STASH ต้องเป็น atomic operation
    # เดียวกันทั้งหมด (ไม่ใช่อ่านนอก lock แล้วค่อยเขียนใน if) ไม่งั้นสอง request ที่มา
    # พร้อมกันจะยังแทรกกลางกันได้อยู่ดีแม้จะมี lock แยกจุด — ต้องล็อกครอบทั้งบล็อก
    # ตัดสินใจ+แก้ค่าให้อยู่ใน critical section เดียว
    with _CENTRAL_STASH_LOCK:
        stash_tags = CENTRAL_STASH.get("gold_tags", 0)
        if d.get("use_gold_tag_event"):
            if stash_tags >= 2:
                remaining = stash_tags - 2
                CENTRAL_STASH["gold_tags"] = 0
                event_success = True
                granted_tags = remaining
            else:
                event_success = None   # ไม่พอ — ตอบ error ข้างนอก lock
                granted_tags = 0
        else:
            CENTRAL_STASH["gold_tags"] = 0
            event_success = False
            granted_tags = stash_tags

    if d.get("use_gold_tag_event"):
        if event_success is None:
            return jsonify({"st": "error", "msg": f"ต้องการป้ายทอง 2 อัน (ในตู้ส่วนกลางมีแค่ {stash_tags})"})
        inv["ป้ายทอง"] = inv.get("ป้ายทอง", 0) + granted_tags
        return jsonify({
            "st": "ok",
            "msg": "ปฏิบัติการสำเร็จ! ใช้ป้ายทอง 2 อันเพื่อจบแมพ ที่เหลือเข้าคลังแล้ว",
            "event_success": True,
            "inventory_tags": inv["ป้ายทอง"]
        })
    else:
        inv["ป้ายทอง"] = inv.get("ป้ายทอง", 0) + granted_tags
        return jsonify({
            "st": "ok",
            "msg": "ออกแมพปกติ ป้ายทองโอนเข้าคลังผู้เล่นทั้งหมดแล้ว",
            "inventory_tags": inv["ป้ายทอง"]
        })


# --- ระบบ 4: อีเวนต์ล็อบบี้ -> แลกป้ายทองเป็นเงิน/EXP (ต้องมี token) ---
@app.route('/api/event/gold_tag/lobby_redeem', methods=['POST'])
@require_auth_toggleable
def api_gold_tag_lobby_redeem():
    d = request.get_json(force=True, silent=True) or {}
    uid = d.get("uid", "VMAX-OP-01")
    token = d.get("event_token")

    if not token:
        return jsonify({"st": "error", "msg": "ต้องมี event_token ที่ออกจากเกมเซิร์ฟเวอร์"}), 400

    ok, msg, ev_payload = _verify_event_token(token, uid, "lobby_redeem")
    if not ok:
        return jsonify({"st": "error", "msg": f"token ไม่ผ่านการตรวจสอบ: {msg}"}), 403

    # [P0 FIX #1] required_tags เดิมมาจาก client ตรงๆ (d.get("required_tags", 5))
    # ส่งค่าติดลบมาก็ทำให้ inv["ป้ายทอง"] เพิ่มขึ้นฟรีๆ ได้ (current_tags - required_tags
    # กลายเป็นบวกเมื่อ required_tags ติดลบ) ตอนนี้ต้องมาจาก payload ที่เซ็นรับรองแล้วเท่านั้น
    required_tags = ev_payload.get("required_tags", 5)
    if not isinstance(required_tags, int) or required_tags <= 0:
        return jsonify({"st": "error", "msg": "จำนวนป้ายทองที่ต้องใช้ไม่ถูกต้อง"}), 400

    inv = INVENTORY.setdefault(uid, {})
    current_tags = inv.get("ป้ายทอง", 0)

    if current_tags >= required_tags:
        inv["ป้ายทอง"] = current_tags - required_tags

        reward_credits = required_tags * 2500
        reward_exp = required_tags * 500

        P["credits"] = P.get("credits", 0) + reward_credits
        WALLET["balance"] = P["credits"]
        P["exp"] = P.get("exp", 0) + reward_exp

        while P["exp"] >= 1000:
            P["exp"] -= 1000
            P["level"] = P.get("level", 1) + 1

        return jsonify({
            "st": "ok",
            "msg": f"แลกสำเร็จ! ใช้ป้ายทอง {required_tags} อัน รับเงิน {reward_credits} และอัปยศเป็น Lv.{P['level']}",
            "credits": P["credits"],
            "level": P["level"],
            "exp": P["exp"],
            "remaining_tags": inv["ป้ายทอง"]
        })
    else:
        return jsonify({"st": "error", "msg": f"ป้ายทองไม่พอ (NPC ต้องการ {required_tags} อัน, คุณมี {current_tags} อัน)"})

# ==========================================
# [ 2F0. Cross-Engine Bridge — how two different-language programs
#        actually "know about" each other (there's no magic here: it's a
#        plain REST event queue + shared key/value state, polled over HTTP.
#        This is the real, standard way e.g. a Python/Flask backend and a
#        Unity/C# game talk to each other — NOT automatic language detection,
#        NOT one process controlling the other's source code.) ]
#
#   Python side (this file)         Unity side (VMAXBridge.cs, separate file)
#   ---------------------------     -------------------------------------------
#   POST /api/bridge/push      <--  Unity posts an event when something happens
#                                    in the Unity game (e.g. "boss_defeated")
#   GET  /api/bridge/pull?since=N -->  Unity polls this on a timer to receive
#                                    events that happened on the Python side
#                                    (e.g. "player_leveled_up") and reacts locally
#   GET/POST /api/bridge/state      <--> either side can read/write shared
#                                    values both games care about (e.g. score)
#
#   Both sides stay independent programs the whole time. Nothing here executes
#   the other side's code — they just exchange JSON over HTTP, which is the
#   only thing that lets two different languages/runtimes cooperate safely.
# ==========================================
from collections import deque as _deque

BRIDGE_EVENTS = _deque(maxlen=500)   # [{id, ts, source, type, data}]
BRIDGE_STATE  = {}                   # shared key -> value, either side can touch it
_BRIDGE_NEXT_ID = {"n": 1}

# ตำแหน่งวัตถุจาก "เกม/เอนจินอื่น" ที่เชื่อมเข้ามาผ่าน bridge (เช่น Unity) — คนละ
# ก้อนกับ OBSTACLES/CONSTRUCTION_SITES/PLAYERS ด้านบนโดยตั้งใจ เพราะนั่นคือวัตถุ
# "ของเกมนี้เอง" (Flask/pymunk รู้จักโดยตรง) ส่วนอันนี้คือวัตถุของเกมฝั่งที่เชื่อม
# เข้ามา ซึ่งเซิร์ฟเวอร์นี้ไม่รู้จักโครงสร้างข้างในเลย รู้แค่ตำแหน่ง x,y ที่เขารายงานมา
# โครงสร้าง: source ("unity", "python_client", ฯลฯ) -> obj_id -> {x,y,label,ts}
BRIDGE_MAP_OBJECTS = {}
BRIDGE_MAP_OBJECT_TTL_SEC = 20   # ไม่ได้อัปเดตนานกว่านี้ = ถือว่าเกมนั้นหลุด/ปิดไปแล้ว ไม่โชว์ต่อ

def bridge_update_map_object(source: str, obj_id: str, x: float, y: float, label: str | None = None):
    bucket = BRIDGE_MAP_OBJECTS.setdefault(source, {})
    bucket[obj_id] = {"x": x, "y": y, "label": label or obj_id, "ts": time.time()}

def bridge_get_live_map_objects() -> list:
    """คืนวัตถุจากเกมอื่นๆ ที่ยังไม่หมดอายุ (TTL) พร้อม tag source ไว้ให้ /map แยกสี"""
    now = time.time()
    out = []
    for source, bucket in BRIDGE_MAP_OBJECTS.items():
        for obj_id, o in list(bucket.items()):
            if now - o["ts"] > BRIDGE_MAP_OBJECT_TTL_SEC:
                del bucket[obj_id]
                continue
            out.append({"id": f"bridge:{source}:{obj_id}", "type": "external", "source": source,
                       "x": o["x"], "y": o["y"], "label": f"[{source}] {o['label']}"})
    return out

def bridge_push_event(source: str, ev_type: str, data: dict | None = None) -> dict:
    """source = 'python' or 'unity' (or any engine name) — just a label so the
    other side knows who sent it. Doesn't grant any special access either way."""
    ev = {"id": _BRIDGE_NEXT_ID["n"], "ts": time.time(),
          "source": source, "type": ev_type, "data": data or {}}
    _BRIDGE_NEXT_ID["n"] += 1
    BRIDGE_EVENTS.append(ev)
    return ev

def bridge_pull_events(since_id: int = 0) -> list:
    return [e for e in BRIDGE_EVENTS if e["id"] > since_id]

# ==========================================
# [ 2E3. Fishing System (Python Logic & Flash Client) ]
# ระบบจำลองการตกปลา (จากภาพเกมตกปลา) - แยกส่วน Logic ฝั่ง Python และ UI ฝั่ง Flash
# ==========================================
FISHING_STATE = {} # uid -> {"state": "IDLE"|"WAITING"|"HOOKED", "bite_time": 0}
FISH_DATABASE = [
    {"name": "ปลาเล็ก", "min_weight": 0.5, "max_weight": 2.0, "rarity": 0.6},
    {"name": "ปลากลาง", "min_weight": 2.0, "max_weight": 8.0, "rarity": 0.3},
    {"name": "ปลายักษ์", "min_weight": 15.0, "max_weight": 50.0, "rarity": 0.1}  # ปลายักษ์แบบในภาพ
]

def fishing_cast_line(uid: str) -> bool:
    st = FISHING_STATE.setdefault(uid, {"state": "IDLE", "bite_time": 0})
    if st["state"] == "IDLE":
        st["state"] = "WAITING"
        # สุ่มเวลาที่ปลาจะมากัม (2 ถึง 6 วินาที)
        st["bite_time"] = time.time() + random.uniform(2.0, 6.0)
        return True
    return False

def fishing_update(uid: str):
    """อัปเดตสถานะเกม (เรียกจาก API หรือ tele_loop)"""
    st = FISHING_STATE.get(uid)
    if st and st["state"] == "WAITING" and time.time() >= st["bite_time"]:
        st["state"] = "HOOKED"

def fishing_reel_in(uid: str):
    st = FISHING_STATE.get(uid)
    if st and st["state"] == "HOOKED":
        # สุ่มปลาที่จะได้รับตามระดับความหายาก (Rarity)
        catch_chance = random.random()
        accumulated = 0
        caught_fish = None
        for fish in FISH_DATABASE:
            accumulated += fish["rarity"]
            if catch_chance <= accumulated:
                weight = round(random.uniform(fish["min_weight"], fish["max_weight"]), 2)
                caught_fish = {"name": fish["name"], "weight": weight}
                break

        # เพิ่มปลาเข้าตู้เซฟของผู้เล่น (ใช้ INVENTORY ที่มีอยู่แล้วในไฟล์)
        if caught_fish:
            inv = INVENTORY.setdefault(uid, {})
            inv[caught_fish["name"]] = inv.get(caught_fish["name"], 0) + 1

        st["state"] = "IDLE"
        return caught_fish
    return None

@app.route('/api/fishing/mini/cast', methods=['POST'])
@require_auth_toggleable
def api_fishing_mini_cast():
    uid = getattr(request, 'vmax_uid', None) or resolve_uid()
    if fishing_cast_line(uid):
        return jsonify({"st": "ok", "msg": "เหวี่ยงเบ็ดแล้ว กำลังรอปลา..."})
    return jsonify({"st": "error", "msg": "ไม่สามารถเหวี่ยงเบ็ดได้ในตอนนี้"}), 400

@app.route('/api/fishing/mini/status', methods=['GET'])
@require_auth_toggleable
def api_fishing_mini_status():
    uid = getattr(request, 'vmax_uid', None) or resolve_uid()
    fishing_update(uid)
    st = FISHING_STATE.get(uid, {"state": "IDLE"})
    return jsonify({"st": "ok", "state": st["state"]})

@app.route('/api/fishing/mini/reel', methods=['POST'])
@require_auth_toggleable
def api_fishing_mini_reel():
    uid = getattr(request, 'vmax_uid', None) or resolve_uid()
    fish = fishing_reel_in(uid)
    if fish:
        return jsonify({"st": "ok", "msg": "ตกได้แล้ว!", "fish": fish})
    return jsonify({"st": "error", "msg": "ยังไม่มีปลากัม หรือดึงเร็วเกินไป"}), 400

# --- Flash (ActionScript 3) Client Code ---
# โค้ดนี้เป็น String ที่เซิร์ฟเวอร์สามารถส่งไปให้ฝั่ง Client หรือคุณเอาไปวางใน Adobe Animate ได้เลย
FISHING_FLASH_CLIENT_CODE = r'''
package {
    import flash.display.Sprite;
    import flash.events.MouseEvent;
    import flash.text.TextField;
    import flash.text.TextFormat;
    import flash.utils.Timer;
    import flash.events.TimerEvent;
    import flash.net.URLLoader;
    import flash.net.URLRequest;
    import flash.net.URLRequestMethod;
    import flash.net.URLVariables;

    public class FishingGameFlash extends Sprite {
        private var state:String = "IDLE";
        private var waitTimer:Timer;
        private var statusText:TextField;
        private var actionButton:Sprite;

        // ตั้งค่า URL ของเซิร์ฟเวอร์ VMAX
        private const BASE_URL:String = "http://127.0.0.1:5000";

        public function FishingGameFlash() {
            initUI();
        }

        private function initUI():void {
            // 1. ข้อความแสดงสถานะ
            statusText = new TextField();
            statusText.text = "พร้อมตกปลา! กดปุ่มเพื่อเหวี่ยงเบ็ด";
            statusText.width = 300;
            statusText.height = 30;
            statusText.x = 100;
            statusText.y = 50;
            var format:TextFormat = new TextFormat("Arial", 16, 0xFFFFFF, true);
            statusText.setTextFormat(format);
            addChild(statusText);

            // 2. ปุ่มตกปลา
            actionButton = new Sprite();
            actionButton.graphics.beginFill(0x0099FF);
            actionButton.graphics.drawRect(0, 0, 120, 40);
            actionButton.graphics.endFill();
            actionButton.x = 190;
            actionButton.y = 300;
            actionButton.buttonMode = true;
            addChild(actionButton);

            actionButton.addEventListener(MouseEvent.CLICK, onActionClick);
        }

        private function onActionClick(e:MouseEvent):void {
            if (state == "IDLE") {
                castLine();
            } else if (state == "HOOKED") {
                reelIn();
            }
        }

        private function castLine():void {
            state = "WAITING";
            statusText.text = "กำลังตกปลา... (รอปลากัม)";

            // จำลองการเหวี่ยงเบ็ด (ในเกมจริงควรยิง API ไป server แล้วรอสถานะ HOOKED)
            var delay:Number = (Math.random() * 3000) + 2000;
            waitTimer = new Timer(delay, 1);
            waitTimer.addEventListener(TimerEvent.TIMER_COMPLETE, onFishBite);
            waitTimer.start();
        }

        private function onFishBite(e:TimerEvent):void {
            state = "HOOKED";
            statusText.text = "ปลากัมแล้ว! กดดึงเบ็ดด่วน!";
        }

        private function reelIn():void {
            state = "IDLE";

            // จำลองการสุ่มปลา (ในเกมจริงควรดึงข้อมูลจาก /api/fishing/reel)
            var fishTypes:Array = ["ปลาหมึกยักษ์", "ปลากระพง", "ปลาช่อน", "ปลายักษ์", "รองเท้าแก่ๆ"];
            var caught:String = fishTypes[Math.floor(Math.random() * fishTypes.length)];

            statusText.text = "ตกได้แล้ว: " + caught + "!";
        }
    }
}
'''

# ลงทะเบียนใน VMAX_MODULES
VMAX_MODULES["fishing_system"] = {
    "desc": "ระบบจำลองการตกปลาและ UI (Python Logic + Flash AS3 Client)",
    "routes": ["/api/fishing/mini/cast", "/api/fishing/mini/status", "/api/fishing/mini/reel"],
    "flash_client_code": "FISHING_FLASH_CLIENT_CODE"
}

# ==========================================
# [ 2F. Model System ]
# GLTF/FBX loader | Animation presets | Hitboxes
# Character assembly from imported reference images
# Source: VMAX_System_Design_Page2 + VMAX_Expansion_Plan
# ==========================================
MODEL_REGISTRY = {}   # model_id -> {source, parts, animations, hitboxes}
ANIMATION_PRESETS = ["idle", "walk", "run", "jump", "interact"]

def register_model(source_path: str, parts: list | None = None) -> str:
    """
    Register a GLTF/FBX model.
    'parts'  — auto-segmented body parts (head, torso, arms, legs).
    In production: pipe through a mesh segmentation library.
    """
    mid = uuid.uuid4().hex[:8]
    MODEL_REGISTRY[mid] = {
        "source":     source_path,
        "format":     "gltf" if source_path.endswith(".glb") else "fbx",
        "parts":      parts or ["head", "torso", "left_arm",
                                "right_arm", "left_leg", "right_leg"],
        "animations": {preset: f"{preset}.anim" for preset in ANIMATION_PRESETS},
        "hitboxes":   {},   # part -> {x, y, w, h}
        "published":  False,
    }
    return mid

def set_hitbox(model_id: str, part: str,
               x: float, y: float, w: float, h: float):
    m = MODEL_REGISTRY.get(model_id)
    if m:
        m["hitboxes"][part] = {"x": x, "y": y, "w": w, "h": h}

def publish_model(model_id: str) -> bool:
    m = MODEL_REGISTRY.get(model_id)
    if not m:
        return False
    m["published"] = True
    return True

# ------------------------------------------
# [ 2F1. Animation-from-images extractor ]
# ยังไม่มีของจริงมาก่อน — ก่อนหน้านี้ "animations" ใน register_model() ด้านบนมีแค่
# ชื่อไฟล์ placeholder เช่น "walk.anim" ที่ไม่มีข้อมูลข้างในจริง ส่วนนี้เพิ่มของจริง:
# ป้อนรูปภาพ (เฟรมเรียงลำดับ เช่น รูปที่ตัดมาจากวิดีโอ/สไปรต์ชีต) เข้าไป ระบบจะใช้
# mediapipe Pose (มีอยู่แล้วเป็น dependency ของโปรเจกต์นี้ — ดู [ 3. Vision Tracker ])
# ตรวจจับจุดข้อต่อ (landmark) ในแต่ละรูป แล้วประกอบเป็น keyframe ของอนิเมชันจริง
#
# ข้อจำกัดที่ต้องรู้ตรงๆ: รูปภาพเดียวให้ได้แค่ "ท่าเดียว" (1 keyframe) เท่านั้น — จะ
# ได้อนิเมชันเดิน/วิ่งที่ดูเคลื่อนไหวจริง ต้องป้อนรูปหลายเฟรมเรียงลำดับ (เช่น 8-16
# เฟรมจากคลิปวิดีโอที่ตัดออกมา) ระบบไม่ได้ "แต่งท่า" ขึ้นมาเองจากรูปเดียว มันสกัด
# เฉพาะท่าที่เห็นจริงในรูปแต่ละใบเท่านั้น
# ------------------------------------------
_POSE_DETECTOR = None
# [BUG-FIX #10] เดิม lazy init เช็คแค่ "if _POSE_DETECTOR is None" เฉยๆ — ถ้าสอง
# request/thread มาถึงพร้อมกันตอนยังไม่เคยโหลด ทั้งคู่จะเห็น None พร้อมกันแล้วสร้าง
# mediapipe.Pose() ซ้ำสองอินสแตนซ์ (race condition แบบ TOCTOU) ตัวหนึ่งจะถูกเขียนทับ
# กลายเป็น orphaned object ที่ไม่มีใครเรียก .close() ให้ (เปลือง native memory ของ
# mediapipe ที่ไม่ถูกคืน) ใช้ threading.Lock() คุม double-checked locking กันซ้ำ
_POSE_DETECTOR_LOCK = threading.Lock()

def _load_pose_detector():
    """โหลด mediapipe Pose แบบ lazy (โหลดครั้งแรกตอนใช้จริงเท่านั้น กันแอปช้าตอน start)
    thread-safe: ใช้ double-checked locking กัน race ตอนหลาย thread เรียกพร้อมกันครั้งแรก"""
    global _POSE_DETECTOR
    if _POSE_DETECTOR is None:
        with _POSE_DETECTOR_LOCK:
            if _POSE_DETECTOR is None:   # เช็คซ้ำหลังได้ lock — เผื่อ thread อื่นสร้างเสร็จไปแล้ว
                _POSE_DETECTOR = mediapipe.solutions.pose.Pose(static_image_mode=True,
                                                                model_complexity=1,
                                                                min_detection_confidence=0.5)
    return _POSE_DETECTOR

# แมป landmark index ของ mediapipe (33 จุด) ไปเป็นชื่อ part ที่ MODEL_REGISTRY ใช้
# อยู่แล้ว (head/torso/left_arm/right_arm/left_leg/right_leg) โดยเฉลี่ยจุดที่เกี่ยวข้อง
_MP_PART_LANDMARKS = {
    "head":      [0],              # nose
    "torso":     [11, 12, 23, 24], # shoulders + hips
    "left_arm":  [11, 13, 15],     # shoulder, elbow, wrist (ฝั่งซ้ายของภาพ)
    "right_arm": [12, 14, 16],
    "left_leg":  [23, 25, 27],     # hip, knee, ankle
    "right_leg": [24, 26, 28],
}

def extract_pose_keyframe(image_bytes: bytes) -> dict | None:
    """รับไบต์ของรูปภาพ 1 ใบ คืน keyframe เป็น {part: {x,y,z,visibility}} (พิกัด
    normalize 0-1 ตามที่ mediapipe คืนมา) หรือ None ถ้าตรวจไม่เจอคนในรูป"""
    import numpy as _np   # มากับ opencv-python อยู่แล้ว (dependency ของ cv2) ไม่ต้องเพิ่ม pip pkg ใหม่
    arr = _np.frombuffer(image_bytes, dtype=_np.uint8)
    img = cv2.imdecode(arr, cv2.IMREAD_COLOR)
    if img is None:
        return None
    result = _load_pose_detector().process(cv2.cvtColor(img, cv2.COLOR_BGR2RGB))
    if not result.pose_landmarks:
        return None
    lm = result.pose_landmarks.landmark
    keyframe = {}
    for part, idxs in _MP_PART_LANDMARKS.items():
        pts = [lm[i] for i in idxs]
        keyframe[part] = {
            "x": sum(p.x for p in pts) / len(pts),
            "y": sum(p.y for p in pts) / len(pts),
            "z": sum(p.z for p in pts) / len(pts),
            "visibility": min(p.visibility for p in pts),
        }
    return keyframe

def build_animation_from_images(model_id: str, preset: str, image_files: list) -> dict:
    """image_files: list ของ (filename, bytes) เรียงตามลำดับเฟรม — สกัด pose ทีละ
    ใบแล้วเก็บเป็นอนิเมชันจริงใน MODEL_REGISTRY[model_id]['animations'][preset]
    (แทนที่ placeholder string เดิม เช่น 'walk.anim')"""
    m = MODEL_REGISTRY.get(model_id)
    if not m:
        return {"st": "error", "msg": f"ไม่พบโมเดล {model_id}"}
    keyframes, skipped = [], []
    for i, (fname, data) in enumerate(image_files):
        kf = extract_pose_keyframe(data)
        if kf is None:
            skipped.append(fname)
            continue
        keyframes.append({"frame": i, "t": i / max(1, len(image_files) - 1), "parts": kf})
    if not keyframes:
        return {"st": "error", "msg": "ตรวจไม่พบคนในรูปเลยสักใบ — ลองใช้รูปที่เห็นตัวคนชัดเจนกว่านี้"}
    m["animations"][preset] = {
        "type": "extracted_from_images",
        "source_frame_count": len(image_files),
        "keyframe_count": len(keyframes),
        "keyframes": keyframes,
        "skipped_frames": skipped,
    }
    return {"st": "ok", "preset": preset, "keyframe_count": len(keyframes), "skipped_frames": skipped}

# ==========================================
# [ 2G. Hot Update Server ]
# Deploy new modules/assets while players continue playing.
# Core engine updates that change networking or DB schema
# may still require scheduled maintenance.
# Source: VMAX_System_Design_Summary_v2
# ==========================================
HOT_UPDATES  = {}   # update_id -> {module, asset_url, compatible, status}
UPDATE_QUEUE = []   # pending updates to apply after safe-reload signal

def register_hot_update(module: str, asset_url: str,
                         compatible: bool = True) -> str:
    uid_upd = uuid.uuid4().hex[:8]
    HOT_UPDATES[uid_upd] = {
        "module":     module,
        "asset_url":  asset_url,
        "compatible": compatible,
        "status":     "pending",
        "registered": time.time(),
    }
    if compatible:
        UPDATE_QUEUE.append(uid_upd)
    return uid_upd

def apply_hot_updates():
    """
    Apply queued compatible updates.
    Non-compatible updates are deferred to maintenance window.
    """
    applied = []
    for uid_upd in list(UPDATE_QUEUE):
        upd = HOT_UPDATES[uid_upd]
        # Production: download asset_url, hot-swap module in sys.modules
        upd["status"] = "applied"
        UPDATE_QUEUE.remove(uid_upd)
        applied.append(uid_upd)
    return applied

# ==========================================
# [ 2H. Version Manager ]
# Staged rollout | Rollback
# Source: VMAX_System_Design_Summary_v2
# ==========================================
VERSION_HISTORY = []   # [{version, deployed_at, rollback_to}]
CURRENT_VERSION = {"major": 1, "minor": 0, "patch": 0,
                   "label": "VMAX-1.0.0", "rollout_pct": 100}

def deploy_version(major: int, minor: int, patch: int,
                   rollout_pct: int = 10) -> dict:
    """Staged rollout — start at 10 %, ramp up after monitoring."""
    VERSION_HISTORY.append({**CURRENT_VERSION,
                             "deployed_at": time.time()})
    CURRENT_VERSION.update({
        "major": major, "minor": minor, "patch": patch,
        "label": f"VMAX-{major}.{minor}.{patch}",
        "rollout_pct": rollout_pct,
    })
    return dict(CURRENT_VERSION)

def rollback_version() -> dict | None:
    if not VERSION_HISTORY:
        return None
    prev = VERSION_HISTORY.pop()
    CURRENT_VERSION.update(prev)
    return dict(CURRENT_VERSION)

# ==========================================
# [ 2I. Announcement System ]
# Website news | In-game popup/news feed | Maintenance countdown
# Event notifications | Emergency broadcast | Patch notes
# Source: VMAX_System_Design_Summary_v2
# ==========================================
ANNOUNCEMENTS = []   # [{id, type, title, body, expires, active, game_id}]
_ANN_TYPES = ("website_news", "ingame_popup", "maintenance",
              "event", "emergency", "patch_notes")

def post_announcement(ann_type: str, title: str, body: str,
                      expires_in: int = 3600, game_id: str = "all") -> str:
    """game_id='all' คือประกาศกลางที่โชว์ทุกเกมใน launcher ส่วนถ้าระบุ game_id
    เจาะจง (เช่น 'vmax', 'iron_fist') ก็จะโชว์เฉพาะเกมนั้นเกมเดียว — ทำให้แต่ละ
    เกมมีประกาศ/ข่าวสารเป็นของตัวเองแยกจากกันได้"""
    if ann_type not in _ANN_TYPES:
        raise ValueError(f"Unknown announcement type: {ann_type}")
    aid = uuid.uuid4().hex[:6]
    ANNOUNCEMENTS.append({
        "id":      aid,
        "type":    ann_type,
        "title":   title,
        "body":    body,
        "expires": time.time() + expires_in,
        "active":  True,
        "game_id": game_id,
    })
    sio.emit("announcement", {"id": aid, "type": ann_type,
                               "title": title, "body": body, "game_id": game_id})
    return aid

def expire_announcements():
    """Deactivate expired announcements — call from tele_loop."""
    now = time.time()
    for ann in ANNOUNCEMENTS:
        if ann["active"] and now > ann["expires"]:
            ann["active"] = False

def active_announcements(ann_type: str | None = None, game_id: str | None = None) -> list:
    """game_id=None คืนทุกประกาศ (มุมมอง admin) — ถ้าระบุ game_id จะคืนเฉพาะ
    ประกาศของเกมนั้น บวกกับประกาศกลาง (game_id='all') ที่โชว์ทุกเกมด้วย"""
    return [a for a in ANNOUNCEMENTS
            if a["active"] and (ann_type is None or a["type"] == ann_type)
            and (game_id is None or a.get("game_id", "all") in ("all", game_id))]

# ==========================================
# [ 2I2. Scheduled Server Maintenance Countdown ]
# จำลองระบบแจ้งเตือน "server maintenance" แบบที่เห็นในเกมมือถือทั่วไป:
#   [ระบบ] We will start a server maintenance in 10 minutes, and the
#   maintenance is expected to complete within 2 hours. Please log out
#   at a safe location.
# ข้อความจะถูกยิงซ้ำเป็นช่วงๆ (ทุก MAINT_REPEAT_SEC วิ) ในแต่ละช่วงเตือน
# (เช่น "10 นาที" ซ้ำหลายรอบ แล้วค่อยขยับไป "5 นาที" ซ้ำหลายรอบ) เหมือน log
# แชทระบบจริงที่เห็นซ้ำๆ กันหลายบรรทัด — ตรงกับพฤติกรรมในภาพตัวอย่างที่แนบมา
# เมื่อถึงเวลาเริ่ม จะยิง event บังคับ logout ผู้เล่น แล้วพอครบเวลาซ่อมจะยิง
# ประกาศ "เสร็จสิ้น" ปิดท้าย
# ==========================================
MAINT_WARN_TIERS_MIN = [10, 5]     # นาทีก่อนเริ่ม ที่จะเริ่มเตือน (เรียงจากไกลไปใกล้)
MAINT_REPEAT_SEC      = 60         # ความถี่ที่ข้อความเดิมของ tier นั้นจะถูกส่งซ้ำ

MAINTENANCE = {
    "scheduled":     False,
    "start_at":      None,   # epoch seconds ที่จะเริ่มปิดปรับปรุง
    "duration_min":  None,   # ระยะเวลาที่คาดว่าจะใช้ซ่อม (นาที)
    "in_progress":   False,  # True ตั้งแต่ start_at ผ่านไปแล้ว จนกว่าจะซ่อมเสร็จ
    "current_tier":  None,   # tier (นาที) ล่าสุดที่กำลังเตือนอยู่ ใช้เช็คตอนสลับ tier
    "_last_sent_at": 0.0,    # เวลา (epoch) ที่ส่งข้อความ tier ปัจจุบันครั้งล่าสุด
}

def _maint_msg(tier_min: int, duration_min: int) -> str:
    hours = max(1, round(duration_min / 60))
    return (f"We will start a server maintenance in {tier_min} minutes, "
            f"and the maintenance is expected to complete within {hours} "
            f"hours. Please log out at a safe location.")

def schedule_maintenance(start_in_min: float, duration_min: int) -> dict:
    """ตั้งเวลาปิดปรับปรุงล่วงหน้า start_in_min นาทีจากนี้ ใช้เวลาซ่อม duration_min นาที."""
    MAINTENANCE.update({
        "scheduled":     True,
        "start_at":      time.time() + max(0.0, start_in_min) * 60,
        "duration_min":  int(duration_min),
        "in_progress":   False,
        "current_tier":  None,
        "_last_sent_at": 0.0,
    })
    return dict(MAINTENANCE)

def cancel_maintenance() -> dict:
    MAINTENANCE.update({
        "scheduled": False, "start_at": None, "duration_min": None,
        "in_progress": False, "current_tier": None, "_last_sent_at": 0.0,
    })
    sio.emit("system_chat", {"channel": "ระบบ", "text": "Scheduled server maintenance has been cancelled."})
    return dict(MAINTENANCE)

def _maint_broadcast(text: str):
    """ยิงข้อความออกทั้งช่องแชท 'ระบบ' (system_chat), แบนเนอร์บนหัวจอ (sky-style banner),
    และประกาศกลาง (post_announcement) เพื่อให้เข้ากับ UI ที่มีอยู่แล้วทุกจุด."""
    sio.emit("system_chat", {"channel": "ระบบ", "text": text})
    sio.emit("maintenance_banner", {"text": text})
    post_announcement("maintenance", "🛠️ Server Maintenance", text, expires_in=MAINT_REPEAT_SEC + 5)

def maintenance_tick():
    """เรียกทุก 1 วิจาก tele_loop — ตรวจว่าอยู่ช่วงเตือน / ถึงเวลาเริ่ม / ซ่อมเสร็จหรือยัง."""
    if not MAINTENANCE["scheduled"]:
        return
    now = time.time()

    if not MAINTENANCE["in_progress"]:
        remaining = MAINTENANCE["start_at"] - now

        if remaining <= 0:
            # ถึงเวลาเริ่มปิดปรับปรุงแล้ว
            MAINTENANCE["in_progress"] = True
            _maint_broadcast("Server maintenance has started. You have been logged out safely.")
            sio.emit("force_logout", {"reason": "maintenance"})
            return

        # หา tier ที่ตรงกับเวลาที่เหลือ (ไกลสุดที่ >= remaining)
        tier = next((t for t in MAINT_WARN_TIERS_MIN if remaining <= t * 60), None)
        if tier is None:
            return  # ยังไม่ถึงช่วงเตือนแรก

        first_hit_of_tier = tier != MAINTENANCE["current_tier"]
        due_for_repeat = (now - MAINTENANCE["_last_sent_at"]) >= MAINT_REPEAT_SEC
        if first_hit_of_tier or due_for_repeat:
            _maint_broadcast(_maint_msg(tier, MAINTENANCE["duration_min"]))
            MAINTENANCE["current_tier"]  = tier
            MAINTENANCE["_last_sent_at"] = now
    else:
        end_at = MAINTENANCE["start_at"] + MAINTENANCE["duration_min"] * 60
        if now >= end_at:
            _maint_broadcast("Server maintenance is complete. You may now log back in.")
            cancel_maintenance()

@app.route('/api/system/maintenance/schedule', methods=['POST'])
@require_auth_toggleable
def api_maintenance_schedule():
    body = request.get_json(force=True, silent=True) or {}
    try:
        start_in_min = float(body.get("start_in_min", 10))
        duration_min = int(body.get("duration_min", 120))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "start_in_min/duration_min ต้องเป็นตัวเลข"}), 400
    return jsonify({"ok": True, "maintenance": schedule_maintenance(start_in_min, duration_min)})

@app.route('/api/system/maintenance/cancel', methods=['POST'])
@require_auth_toggleable
def api_maintenance_cancel():
    return jsonify({"ok": True, "maintenance": cancel_maintenance()})

@app.route('/api/system/maintenance/status')
def api_maintenance_status():
    m = dict(MAINTENANCE)
    if m["scheduled"] and not m["in_progress"]:
        m["seconds_until_start"] = max(0, m["start_at"] - time.time())
    return jsonify({"ok": True, "maintenance": m})

# ==========================================
# [ 2J. Plugin / Module Loader ]
# Gameplay features delivered as plugins.
# Terminal creates compatible modules from natural-language
# commands after validation (human approval required).
# Source: VMAX_System_Design_Page2 + VMAX_System_Design_Summary_v2
# ==========================================
LOADED_PLUGINS = {}   # name -> {module_obj, version, loaded_at}

# [P0 FIX #6] plugin ต้องอยู่ใต้โฟลเดอร์นี้เท่านั้น (whitelist) — กัน RCE ผ่าน path ที่
# client ส่งมาเอง (เดิม load_plugin exec ไฟล์ตาม path ตรงๆ ไม่ตรวจอะไรเลย)
PLUGIN_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "plugins")
os.makedirs(PLUGIN_DIR, exist_ok=True)

def load_plugin(name: str, path: str) -> tuple[bool, str]:
    """
    Dynamically load a validated plugin module.
    Only call after human approval (see /api/approve_feature).

    [P0 FIX #6] เดิมฟังก์ชันนี้ exec_module() ไฟล์ตาม `path` ที่ส่งเข้ามาโดยไม่มีการ
    ตรวจสอบใดๆ เลย — endpoint /api/plugins/load (ดู #3) ส่ง path จาก client ตรงๆ เข้ามา
    ที่นี่ เท่ากับใครก็ตามที่ยิง request ได้ สั่งรันไฟล์ .py อะไรก็ได้บนดิสก์ (RCE เต็ม
    รูปแบบ) ตอนนี้บังคับ whitelist: (1) name ต้องเป็นตัวอักษร/ตัวเลข/_/- เท่านั้น
    (2) path ต้อง resolve (realpath) แล้วอยู่ใต้ PLUGIN_DIR เท่านั้น กัน path traversal
    เช่น "../../etc/passwd" (3) ต้องเป็นไฟล์ .py ที่มีอยู่จริงเท่านั้น
    """
    import importlib.util
    if not name or not re.fullmatch(r"[A-Za-z0-9_\-]{1,64}", name):
        return False, "ชื่อ plugin ไม่ถูกต้อง (a-z A-Z 0-9 _ - เท่านั้น ไม่เกิน 64 ตัวอักษร)"
    if not path:
        return False, "ต้องระบุ path"
    try:
        real_dir = os.path.realpath(PLUGIN_DIR)
        candidate = path if os.path.isabs(path) else os.path.join(PLUGIN_DIR, path)
        real_path = os.path.realpath(candidate)
        if os.path.commonpath([real_dir, real_path]) != real_dir:
            return False, f"ปฏิเสธ: path ต้องอยู่ใต้โฟลเดอร์ plugin ที่อนุญาตเท่านั้น ({PLUGIN_DIR})"
        if not real_path.endswith(".py"):
            return False, "ปฏิเสธ: อนุญาตเฉพาะไฟล์ .py เท่านั้น"
        if not os.path.isfile(real_path):
            return False, f"ไม่พบไฟล์: {real_path}"

        # [SECURITY-FIX #8] การอยู่ใต้ PLUGIN_DIR อย่างเดียวไม่พอ เพราะ
        # importlib.exec_module() จะรัน Python ใด ๆ ที่อยู่ในโฟลเดอร์นั้นทันที.
        # อนุญาตเฉพาะไฟล์ที่มี SHA-256 ตรงกับ allowlist ที่ผู้ดูแลตั้งไว้เท่านั้น
        # และบังคับให้ endpoint เรียกโดย admin เท่านั้น. ค่า allowlist รูปแบบ
        # "name=sha256hex,name2=sha256hex" เก็บอยู่นอกไฟล์/นอก request เพื่อกัน
        # client เขียนทั้งไฟล์และเปลี่ยนค่าอนุมัติเอง.
        caller_uid = getattr(request, "vmax_uid", None)
        if _staff_rank_value(caller_uid) < STAFF_RANKS["admin"]:
            return False, "ปฏิเสธ: การโหลด plugin ต้องใช้บัญชี admin"
        allowlist = {}
        for item in os.environ.get("VMAX_PLUGIN_SHA256_ALLOWLIST", "").split(","):
            item = item.strip()
            if "=" in item:
                plugin_key, expected_hash = item.split("=", 1)
                allowlist[plugin_key.strip()] = expected_hash.strip().lower()
        expected_hash = allowlist.get(name)
        if not expected_hash or not re.fullmatch(r"[0-9a-f]{64}", expected_hash):
            return False, "ปฏิเสธ: plugin นี้ไม่มี SHA-256 allowlist ที่เชื่อถือได้"
        digest = hashlib.sha256(_v12_Path(real_path).read_bytes()).hexdigest()
        if not hmac.compare_digest(digest, expected_hash):
            return False, "ปฏิเสธ: SHA-256 ของ plugin ไม่ตรงกับ allowlist"

        spec = importlib.util.spec_from_file_location(name, real_path)
        if spec is None or spec.loader is None:
            return False, "โหลด plugin ไม่สำเร็จ: ไม่พบ Python loader ที่ถูกต้อง"
        mod  = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        LOADED_PLUGINS[name] = {"module": mod, "path": real_path,
                                 "loaded_at": time.time(), "sha256": digest}
        return True, f"Plugin '{name}' loaded from {real_path}"
    except Exception as e:
        return False, str(e)

def unload_plugin(name: str) -> bool:
    return bool(LOADED_PLUGINS.pop(name, None))

# ==========================================
# [ 2J2. Central Fixed-Code Registry ]
# ที่เก็บกลางของโค้ดที่ "ซ่อม/ทำเสร็จแล้ว" (ผ่านการอนุมัติจาก /api/approve_feature
# หรือถูกเพิ่มมือผ่าน /api/registry/store) — เก็บเป็นไฟล์จริงบนดิสก์ + index.json
# แยกตาม name และ version (version ใหม่ทุกครั้งที่ชื่อเดิมถูกบันทึกซ้ำ) ระบบอื่น
# (หรือ bridge client ภาษาไหนก็ได้) ต่อ API เข้ามาเพื่อดึงโค้ดล่าสุดไปใช้ได้เลย —
# แต่ "ใช้อัตโนมัติจริง" ทำได้เฉพาะ target python เท่านั้น (ผ่านกลไก exec เดิมของ
# approve_feature) ภาษาอื่นยังต้องเอาไฟล์ที่ดึงมาไปวางในโปรเจกต์เป้าหมายเอง —
# เหตุผลเดียวกับที่ wiring="manual" อธิบายไว้ด้านบน: ไม่มีทาง auto-wire กลางๆ
# ที่ถูกต้องสำหรับทุก runtime ได้จริง
# ==========================================
os.makedirs("code_registry", exist_ok=True)
REGISTRY_INDEX_PATH = "code_registry/index.json"

def _load_registry() -> dict:
    if os.path.exists(REGISTRY_INDEX_PATH):
        with open(REGISTRY_INDEX_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    return {}

def _save_registry(idx: dict) -> None:
    with open(REGISTRY_INDEX_PATH, "w", encoding="utf-8") as f:
        json.dump(idx, f, ensure_ascii=False, indent=2)

def register_fixed_code(name: str, code: str, target: str = "python",
                        description: str = "", source_fid: str | None = None) -> dict:
    """เก็บโค้ดที่ทำ/ซ่อมเสร็จแล้วหนึ่งชิ้นเข้าที่เก็บกลาง — เวอร์ชันใหม่จะถูกเพิ่ม
    ต่อท้ายถ้าชื่อนี้เคยมีอยู่แล้ว (ของเก่าไม่ถูกทับ) คืนค่า record ที่เพิ่งบันทึก"""
    idx = _load_registry()
    # [BUG-FIX #23] เดิม key ผ่านแค่ .lower().replace(" ", "_") เท่านั้น — ไม่ได้กรอง
    # "/", "\\", ".." หรืออักขระ path พิเศษอื่นๆ เลย ถ้า name มาจาก input ที่ผู้ใช้/
    # ระบบอื่นควบคุมได้ (เช่น "../../../etc/cron.d/evil" หรือ path แบบ absolute)
    # ค่านี้จะไหลตรงเข้า rel_path แล้วถูกเปิดเขียนไฟล์ทันทีที่ open(rel_path, "w", ...)
    # ด้านล่าง — เท่ากับเขียนไฟล์ออกไปนอกโฟลเดอร์ code_registry/ ได้ตามใจ (arbitrary
    # file write / path traversal) ใช้ secure_filename() (มี import อยู่แล้วในไฟล์นี้
    # สำหรับงาน upload อื่น) กรองก่อน แล้วกันเคสที่กรองแล้วว่างเปล่าด้วย uuid สำรอง
    key_raw = (name or "").strip().lower().replace(" ", "_")
    key = secure_filename(key_raw) or uuid.uuid4().hex[:8]
    versions = idx.setdefault(key, [])
    version = len(versions) + 1
    ext = _lang_config(target)["ext"]
    rel_path = f"code_registry/{key}_v{version}.{ext}"
    # กันอีกชั้น: ยืนยันว่า path ที่ประกอบแล้วยังอยู่ใต้ code_registry/ จริง ไม่หลุด
    # ออกไปนอกโฟลเดอร์ไม่ว่าจะด้วยเหตุผลอะไรก็ตาม (defense in depth)
    _registry_root = os.path.abspath("code_registry")
    _resolved_path = os.path.abspath(rel_path)
    if os.path.commonpath([_registry_root, _resolved_path]) != _registry_root:
        raise ValueError(f"ชื่อไม่ถูกต้อง: '{name}' ทำให้ path หลุดออกนอกโฟลเดอร์ code_registry/")
    with open(rel_path, "w", encoding="utf-8") as f:
        f.write(code)
    record = {
        "name": key, "version": version, "target": target,
        "description": description, "path": rel_path,
        "source_fid": source_fid, "stored_at": time.time(),
    }
    versions.append(record)
    _save_registry(idx)
    return record

def get_registry_entry(name: str, version: int | None = None) -> dict | None:
    versions = _load_registry().get(secure_filename((name or "").strip().lower().replace(" ", "_")))
    if not versions:
        return None
    if version is None:
        return versions[-1]              # ล่าสุด
    return next((v for v in versions if v["version"] == version), None)

