LAUNCHER_CATALOG = {}   # game_id -> {name, version, size_mb, installed}
DOWNLOAD_QUEUE   = []   # [{game_id, progress, total}]

# ==========================================
# [ 6j0. Central Anti-Cheat Hub ]
# ไฟล์นี้ทำหน้าที่เป็น central server ที่เกมต่างๆ (ระบุด้วย game_id) ส่งรายงาน
# ความน่าสงสัยเข้ามา — ไม่ใช่แค่ VMAX เกมเดียว เกมอื่นที่จะต่อเข้ามาทีหลังก็ยิง
# 2 endpoint นี้ได้เลย:
#   POST /api/anticheat/report  — ส่งหลักฐานเข้ามาให้ตรวจ
#   GET  /api/anticheat/bans    — poll รายชื่อที่โดนแบนแล้ว เอาไปบังคับใช้เอง
#     ฝั่งเกมนั้นๆ (เช่น เตะคนที่อยู่ใน list นี้ตอน connect)
#
# การ "ตรวจสอบ" มี 2 ชั้น: heuristic (กฎตายตัว เร็ว/ฟรี/debug ได้) ใช้ตัดสิน
# เคสที่ชัดเจน (คะแนนสูง=แบนอัตโนมัติ, ต่ำ=ปล่อยผ่านอัตโนมัติ) ส่วนเคสก้ำกึ่ง
# ตรงกลางถึงส่งให้ Claude ช่วยพิจารณา (ต้องตั้ง env var ANTHROPIC_API_KEY เอง
# ไม่งั้นจะไม่เรียก และปล่อยเป็นสถานะ "needs_human_review" ให้แอดมินตัดสินเอง
# แทนที่จะเดา/แบนมั่ว)
# ==========================================
BANNED_UIDS   = set()   # uid ที่โดนแบนแล้ว ทุกเกมที่ผูกกับ hub นี้ควร enforce
CHEAT_REPORTS = {}      # report_id -> {...}

AUTO_BAN_THRESHOLD   = 0.7   # heuristic score >= นี้ -> แบนอัตโนมัติ ไม่ต้องรอ LLM
AUTO_CLEAR_THRESHOLD = 0.2   # heuristic score <= นี้ -> ปล่อยผ่านอัตโนมัติ
# ระหว่างสองค่านี้ = เคสก้ำกึ่ง ส่งให้ LLM ช่วยพิจารณา (ถ้ามี API key)

def heuristic_cheat_score(evidence: dict) -> float:
    """ให้คะแนนความน่าสงสัย 0-1 จากกฎง่ายๆ ที่ตรวจสอบ/ปรับได้ตรงไปตรงมา
    (นี่คือ rule-based ไม่ใช่ machine learning — บอกตรงๆ เพื่อไม่ให้เข้าใจผิดว่า
    เป็น AI วิเศษที่ตัดสินถูกเสมอ)"""
    ev = evidence or {}
    score = 0.0
    if ev.get("max_speed_observed", 0) > ev.get("allowed_speed", MOVE_SPEED) * 1.5:
        score += 0.4
    if ev.get("shots_per_sec", 0) > ev.get("weapon_max_fire_rate", 10):
        score += 0.4
    if ev.get("hp_gained_without_pickup", False):
        score += 0.3
    if ev.get("hit_rate", 0) > 0.9 and ev.get("shots_fired", 0) > 20:   # แม่นเกินจริง
        score += 0.3
    if ev.get("processes"):          # เจอโปรเซสต้องสงสัยตรงๆ — สัญญาณค่อนข้างหนัก
        score += 0.6
    if ev.get("remote_addrs"):       # connection แปลกเข้าพอร์ตเกม — สัญญาณอ่อนกว่า (false positive ได้)
        score += 0.3
    return min(score, 1.0)

def llm_review_report(report: dict) -> dict:
    """ให้ Claude ช่วยพิจารณาเคสก้ำกึ่ง — ต้องตั้ง ANTHROPIC_API_KEY เป็น env var เอง"""
    api_key = os.environ.get("ANTHROPIC_API_KEY")
    if not api_key:
        return {"decision": "heuristic_only", "note": "ไม่ได้ตั้ง ANTHROPIC_API_KEY ไว้ — ข้ามขั้นตอนนี้"}
    try:
        prompt = (f"พิจารณาหลักฐานการเล่นเกมนี้ว่าเข้าข่ายโกงหรือไม่ ตอบขึ้นต้นด้วยคำว่า "
                 f"'ban' หรือ 'clear' คำเดียวก่อน แล้วตามด้วยเหตุผลสั้นๆ 1 บรรทัด:\n"
                 f"game_id: {report['game_id']}\nreason: {report['reason']}\n"
                 f"evidence: {json.dumps(report['evidence'], ensure_ascii=False)}")
        resp = requests.post(
            "https://api.anthropic.com/v1/messages",
            headers={"x-api-key": api_key, "anthropic-version": "2023-06-01",
                    "content-type": "application/json"},
            json={"model": "claude-sonnet-4-6", "max_tokens": 200,
                 "messages": [{"role": "user", "content": prompt}]},
            timeout=10)
        resp.raise_for_status()
        text = resp.json()["content"][0]["text"].strip()
        decision = "ban" if text.lower().startswith("ban") else "clear"
        return {"decision": decision, "raw": text}
    except Exception as e:
        return {"decision": "error", "note": str(e)}

def submit_cheat_report(uid: str, game_id: str, reason: str, evidence: dict) -> dict:
    rid = uuid.uuid4().hex[:8]
    score = heuristic_cheat_score(evidence)
    report = {"id": rid, "uid": uid, "game_id": game_id, "reason": reason,
              "evidence": evidence, "score": round(score, 2),
              "status": "pending", "created_at": time.time()}
    if score >= AUTO_BAN_THRESHOLD:
        report["status"] = "auto_banned"
        BANNED_UIDS.add(uid)
        generate_ban_evidence_video(uid, report)
    elif score <= AUTO_CLEAR_THRESHOLD:
        report["status"] = "auto_cleared"
    else:
        review = llm_review_report(report)
        report["review"] = review
        if review.get("decision") == "ban":
            report["status"] = "auto_banned"
            BANNED_UIDS.add(uid)
            generate_ban_evidence_video(uid, report)
        elif review.get("decision") == "clear":
            report["status"] = "auto_cleared"
        else:
            report["status"] = "needs_human_review"   # ไม่มี LLM ช่วย และ heuristic ก็ไม่ฟันธง
    CHEAT_REPORTS[rid] = report
    return report


# ==========================================
# [ 6j0. API Service Auto-Setup / Missing API Guard ]
# ตรวจ API ที่ระบบรู้จัก ถ้าขาดจะแสดงหน้าสมัคร/ตั้งค่าและเก็บ key แบบเข้ารหัส
# ==========================================
_SERVICE_CRED_DIR=os.path.join(os.path.dirname(os.path.abspath(__file__)),'.vmax_service_credentials')
_SERVICE_CRED_KEY_PATH=os.path.join(_SERVICE_CRED_DIR,'.fernet.key')
_SERVICE_CRED_DATA_PATH=os.path.join(_SERVICE_CRED_DIR,'credentials.enc')
def _service_cred_fernet():
    os.makedirs(_SERVICE_CRED_DIR,exist_ok=True)
    if not os.path.isfile(_SERVICE_CRED_KEY_PATH):
        with open(_SERVICE_CRED_KEY_PATH,'wb') as _f:_f.write(Fernet.generate_key())
        try:os.chmod(_SERVICE_CRED_KEY_PATH,0o600)
        except OSError:pass
    with open(_SERVICE_CRED_KEY_PATH,'rb') as _f:return Fernet(_f.read())
def _service_credentials_load():
    if not os.path.isfile(_SERVICE_CRED_DATA_PATH):return {}
    try:
        with open(_SERVICE_CRED_DATA_PATH,'rb') as _f:raw=_service_cred_fernet().decrypt(_f.read())
        data=json.loads(raw.decode('utf-8'));return data if isinstance(data,dict) else {}
    except Exception as _e:
        print(f'[API Setup] cannot load encrypted credentials: {_e}');return {}
def _service_credentials_save(data):
    enc=_service_cred_fernet().encrypt(json.dumps(data,ensure_ascii=False).encode('utf-8'));tmp=_SERVICE_CRED_DATA_PATH+'.tmp'
    with open(tmp,'wb') as _f:_f.write(enc)
    os.replace(tmp,_SERVICE_CRED_DATA_PATH)
    try:os.chmod(_SERVICE_CRED_DATA_PATH,0o600)
    except OSError:pass
_SERVICE_CREDENTIALS=_service_credentials_load()
SERVICE_API_REGISTRY={
 'openai':{'name':'OpenAI','env':'OPENAI_API_KEY','signup_url':'https://platform.openai.com/api-keys','note':'ใช้กับ Background Analyst AI และฟังก์ชัน OpenAI'},
 'anthropic':{'name':'Anthropic / Claude','env':'ANTHROPIC_API_KEY','signup_url':'https://console.anthropic.com/settings/keys','note':'ใช้กับ Claude analyst/review'},
 'huggingface':{'name':'Hugging Face','env':'HF_API_TOKEN','signup_url':'https://huggingface.co/settings/tokens','note':'ใช้กับ vision/model ที่ต้องใช้ HF token'},
 'local_ai':{'name':'Local AI (Ollama / LM Studio)','env':'LOCAL_AI_API_KEY','signup_url':None,'optional':True,'note':'ไม่ต้องสมัคร ถ้า local server ไม่ต้องใช้ key'},
 'central':{'name':'VMAX Central API','env':'CENTRAL_API_KEY','signup_url':None,'optional':True,'note':'API ภายในระบบ ไม่ใช่บริการภายนอก'}}
def _service_apply_saved_credentials():
    for _sid,_meta in SERVICE_API_REGISTRY.items():
        _saved=_SERVICE_CREDENTIALS.get(_sid)
        if isinstance(_saved,dict) and _saved.get('value'):os.environ[_meta['env']]=str(_saved['value'])
_service_apply_saved_credentials()
def detect_missing_api_services():
    return [{'id':sid,'name':m['name'],'env':m['env'],'configured':bool(os.environ.get(m['env'],'').strip()),'missing':not bool(os.environ.get(m['env'],'').strip()),'optional':bool(m.get('optional')),'signup_url':m.get('signup_url'),'note':m.get('note','')} for sid,m in SERVICE_API_REGISTRY.items()]
def missing_required_api_services():return [x for x in detect_missing_api_services() if x['missing'] and not x['optional']]
@app.route('/api/service-check')
def api_service_check():
    services=detect_missing_api_services();missing=[x for x in services if x['missing']];req=[x for x in missing if not x['optional']]
    return jsonify({'st':'ok','ready':not req,'missing_count':len(missing),'required_missing_count':len(req),'services':services,'setup_url':'/api-services' if missing else None})
@app.route('/api/service-credential',methods=['POST'])
@require_auth_toggleable
def api_service_credential():
    body=request.get_json(force=True,silent=True) or {};sid=str(body.get('service_id','')).strip().lower();value=str(body.get('api_key','')).strip()
    if sid not in SERVICE_API_REGISTRY:return jsonify({'st':'error','msg':'ไม่รู้จัก service นี้'}),400
    if not value:return jsonify({'st':'error','msg':'ต้องระบุ API key/token'}),400
    meta=SERVICE_API_REGISTRY[sid];_SERVICE_CREDENTIALS[sid]={'value':value,'saved_at':time.time(),'env':meta['env']};_service_credentials_save(_SERVICE_CREDENTIALS);os.environ[meta['env']]=value
    return jsonify({'st':'ok','service_id':sid,'configured':True,'msg':f"บันทึก {meta['name']} แบบเข้ารหัสแล้ว และโหลด API ให้ระบบทันที"})
@app.route('/api-services')
def api_services_page():
    html='''<!doctype html><html lang=\"th\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>VMAX API Service Setup</title><style>body{font-family:system-ui;background:#080b12;color:#eaf2ff;padding:24px}.wrap{max-width:900px;margin:auto}.card{background:#101827;border:1px solid #263650;border-radius:14px;padding:18px;margin:12px 0}.btn{padding:9px 13px;border-radius:9px;border:1px solid #36557f;background:#162a45;color:#fff;cursor:pointer}input{width:100%;box-sizing:border-box;padding:10px;background:#080e18;color:#fff;border:1px solid #344a68;border-radius:8px;margin:8px 0}</style></head><body><div class=\"wrap\"><h1>🔌 VMAX API Service Setup</h1><p>ตรวจ API ที่ระบบรู้จัก และตั้งค่าบริการที่ยังไม่มี credential</p><div id=\"list\">กำลังตรวจ...</div><script>async function load(){const r=await fetch(\'/api/service-check\',{cache:\'no-store\'}),d=await r.json();document.getElementById(\'list\').innerHTML=d.services.map(s=>`<div class=\"card\"><h2>${s.name} — ${s.configured?\'พร้อมใช้\':\'ยังไม่มี\'}</h2><p>${s.note||\'\'}</p>${s.signup_url?`<p><a class=\"btn\" href=\"${s.signup_url}\" target=\"_blank\" rel=\"noopener\">สมัคร/รับ API จากเว็บทางการ</a></p>`:``}${s.configured?\'\':`<input id=\"key_${s.id}\" type=\"password\" placeholder=\"วาง API key / token\"><button class=\"btn\" onclick=\"saveKey(\'${s.id}\')\">บันทึกและเปิดใช้ทันที</button>`}<div id=\"msg_${s.id}\"></div></div>`).join(\'\');}async function saveKey(id){const el=document.getElementById(\'key_\'+id),msg=document.getElementById(\'msg_\'+id);const r=await fetch(\'/api/service-credential\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({service_id:id,api_key:el.value.trim()})}),d=await r.json();msg.textContent=(d.st===\'ok\'?\'✅ \':\'❌ \')+(d.msg||\'\');if(d.st===\'ok\')setTimeout(load,400)}load();</script></div></body></html>'''
    return html

# ==========================================
# [ 6j1. Background Analyst AI ]
# เป็น "AI ตัวที่สอง" ที่รันแยกเป็น background thread อยู่ในเทอร์มินัลเดียวกับ
# เกม/เว็บไซต์นี้ (ไม่ใช่ process แยก) หน้าที่ของมันคือ: ทุกๆ ANALYST_AI_CONFIG
# ["interval_sec"] วินาที มันจะ
#   1) เก็บสรุปสถานะปัจจุบันของเกม/เว็บ (จำนวนผู้เล่น, เครดิต, รายงานโกง,
#      เหตุการณ์ bridge ล่าสุด ฯลฯ) เป็น snapshot
#   2) ยิง API ไปหา "AI อีกตัวหนึ่ง" — ไม่ยึดติดกับผู้ให้บริการเจ้าเดียว เลือกได้
#      3 ทาง (ปรับที่ ANALYST_AI_CONFIG["provider"]):
#        - "claude"  -> Anthropic Messages API (ต้องมี ANTHROPIC_API_KEY)
#        - "openai"  -> OpenAI Chat Completions API (ต้องมี OPENAI_API_KEY)
#        - "local"   -> เซิร์ฟเวอร์โมเดลที่รันในเครื่องเอง ผ่าน endpoint แบบ
#                       OpenAI-compatible (เช่น Ollama/LM Studio/llama.cpp
#                       server) ที่ ANALYST_AI_CONFIG["local_base_url"] —
#                       ไม่ต้องมี API key ก็ได้
#        - "auto"    -> เช็คตามลำดับ: ANTHROPIC_API_KEY -> OPENAI_API_KEY ->
#                       ตกไปที่ local เป็นทางเลือกสุดท้าย
#      ปรับ provider ได้ตอน runtime ผ่าน POST /api/analyst-ai/config โดยไม่ต้อง
#      แก้โค้ด/รีสตาร์ท
#   3) เอาผลลัพธ์ไปโชว์ที่เว็บไซต์ — ผ่าน bridge เดิม (BRIDGE_STATE +
#      BRIDGE_EVENTS ที่ /api/bridge/pull และ /map ก็ดึงไปใช้ได้อยู่แล้ว) และ
#      ผ่าน endpoint เฉพาะของตัวเอง /api/analyst-ai/* สำหรับหน้าเว็บที่อยากดู
#      แบบละเอียดกว่า
#
# หมายเหตุตรงไปตรงมา: ถ้าไม่มี provider ไหนพร้อมใช้เลย (ไม่มี key และเรียก local
# ไม่ติด) มันจะยัง "ทำงาน" อยู่ (เก็บ snapshot ทุกรอบ) แต่ข้าม step เรียก AI ตัว
# ที่สอง แล้วบอกสถานะเป็น "no_provider_available"/"error" ตรงๆ ในผลลัพธ์ ไม่ได้
# แกล้งทำเป็นว่ามี AI มาวิเคราะห์ให้ทั้งที่จริงไม่มี — เช่นเดียวกับที่
# heuristic_cheat_score() ทำไว้ข้างบน
# ==========================================
ANALYST_AI_CONFIG = {
    "enabled": True,
    "interval_sec": 60,          # ทุกกี่วินาทีให้ทำงานหนึ่งรอบ
    "provider": "auto",          # "claude" | "openai" | "local" | "auto"
    "models": {
        "claude": "claude-sonnet-4-6",     # ปรับตามที่บัญชี ANTHROPIC_API_KEY เข้าถึงได้จริง
        "openai": "gpt-4o-mini",           # ปรับตามที่บัญชี OPENAI_API_KEY เข้าถึงได้จริง
        "local":  os.environ.get("LOCAL_AI_MODEL", "llama3"),
    },
    # base URL ของเซิร์ฟเวอร์โมเดล local แบบ OpenAI-compatible เช่น
    # Ollama (http://localhost:11434/v1), LM Studio (http://localhost:1234/v1) ฯลฯ
    "local_base_url": os.environ.get("LOCAL_AI_BASE_URL", "http://localhost:11434/v1"),
}
ANALYST_AI_STATE = {
    "last_run_ts": None,
    "last_snapshot": None,
    "last_summary": None,     # ข้อความสรุปจาก AI ตัวที่สอง (หรือ None ถ้าไม่มี provider พร้อม)
    "last_provider": None,    # provider ที่ถูกใช้จริงในรอบล่าสุด
    "last_status": "not_run_yet",
    "history": deque(maxlen=50),   # เก็บผลลัพธ์ย้อนหลังไว้ดูเทรนด์
}

def collect_analyst_snapshot() -> dict:
    """เก็บสถานะปัจจุบันของเกม/เว็บแบบสั้นๆ ไว้ให้ AI ตัวที่สองอ่าน
    ปรับ/เพิ่มคีย์ตรงนี้ได้ตามข้อมูลที่อยากให้มันช่วยดู"""
    return {
        "ts": time.time(),
        "players_online": len(PLAYERS),
        "player_credits": P.get("credits"),
        "wallet_balance": WALLET.get("balance") if isinstance(WALLET, dict) else None,
        "banned_uid_count": len(BANNED_UIDS),
        "cheat_reports_total": len(CHEAT_REPORTS),
        "cheat_reports_pending": sum(1 for r in CHEAT_REPORTS.values() if r["status"] == "pending"
                                     or r["status"] == "needs_human_review"),
        "bridge_events_total": len(BRIDGE_EVENTS),
        "modules_loaded": len(VMAX_MODULES),
    }

def _analyst_build_prompt(snapshot: dict) -> str:
    """prompt กลาง ใช้ร่วมกันทุก provider เพื่อให้ผลลัพธ์เทียบกันได้ไม่ว่าจะสลับ
    ไปใช้ AI เจ้าไหนก็ตาม"""
    return (
        "นี่คือ snapshot สถานะปัจจุบันของเกม/เว็บไซต์หนึ่ง (รูปแบบ JSON) "
        "ช่วยสรุปสั้นๆ ไม่เกิน 3 บรรทัดเป็นภาษาไทยว่ามีอะไรน่าสนใจ/น่ากังวลไหม "
        "(เช่น รายงานโกงค้างเยอะผิดปกติ, ผู้เล่นหาย, เครดิตผิดปกติ) "
        "ถ้าดูปกติดีก็บอกตรงๆ ว่าปกติ:\n" + json.dumps(snapshot, ensure_ascii=False)
    )

def _analyst_call_claude(prompt: str) -> str:
    api_key = os.environ["ANTHROPIC_API_KEY"]
    resp = requests.post(
        "https://api.anthropic.com/v1/messages",
        headers={"x-api-key": api_key, "anthropic-version": "2023-06-01",
                "content-type": "application/json"},
        json={"model": ANALYST_AI_CONFIG["models"]["claude"], "max_tokens": 300,
             "messages": [{"role": "user", "content": prompt}]},
        timeout=15)
    resp.raise_for_status()
    return resp.json()["content"][0]["text"].strip()

def _analyst_call_openai(prompt: str) -> str:
    api_key = os.environ["OPENAI_API_KEY"]
    resp = requests.post(
        "https://api.openai.com/v1/chat/completions",
        headers={"Authorization": f"Bearer {api_key}", "content-type": "application/json"},
        json={"model": ANALYST_AI_CONFIG["models"]["openai"], "max_tokens": 300,
             "messages": [{"role": "user", "content": prompt}]},
        timeout=15)
    resp.raise_for_status()
    return resp.json()["choices"][0]["message"]["content"].strip()

def _analyst_call_local(prompt: str) -> str:
    """โมเดลที่รันในเครื่องเอง ผ่าน endpoint แบบ OpenAI-compatible (Ollama /
    LM Studio / llama.cpp server ฯลฯ) — ปกติไม่ต้องใช้ API key"""
    base_url = ANALYST_AI_CONFIG["local_base_url"].rstrip("/")
    headers = {"content-type": "application/json"}
    local_key = os.environ.get("LOCAL_AI_API_KEY")
    if local_key:
        headers["Authorization"] = f"Bearer {local_key}"
    resp = requests.post(
        f"{base_url}/chat/completions",
        headers=headers,
        json={"model": ANALYST_AI_CONFIG["models"]["local"], "max_tokens": 300,
             "messages": [{"role": "user", "content": prompt}]},
        timeout=30)
    resp.raise_for_status()
    return resp.json()["choices"][0]["message"]["content"].strip()

ANALYST_AI_PROVIDERS = {
    "claude": {"fn": _analyst_call_claude, "ready": lambda: bool(os.environ.get("ANTHROPIC_API_KEY"))},
    "openai": {"fn": _analyst_call_openai, "ready": lambda: bool(os.environ.get("OPENAI_API_KEY"))},
    # local ถือว่า "ready" เสมอ (ไม่ต้องมี key) — ถ้าเซิร์ฟเวอร์ local จริงๆ ไม่ได้
    # เปิดอยู่ ก็จะไปพังตอนเรียกจริงแล้วรายงานเป็น status="error" แทน ไม่ใช่การเดา
    # ล่วงหน้าว่ามี/ไม่มี
    "local":  {"fn": _analyst_call_local,  "ready": lambda: True},
}

def _analyst_resolve_provider() -> str | None:
    """เลือก provider ที่จะใช้จริงตาม ANALYST_AI_CONFIG['provider']:
    ถ้าระบุเจ้าใดเจ้าหนึ่งตรงๆ ก็ใช้เจ้านั้นเลย (ไม่เช็ค ready ล่วงหน้า ปล่อยให้
    ไปเจอ error ตอนเรียกจริงถ้า key ไม่มี จะได้เห็น note ชัดเจนกว่า "ข้ามเงียบๆ")
    ถ้าเป็น "auto" ค่อยไล่เช็คตามลำดับความสำคัญ: claude -> openai -> local"""
    provider = ANALYST_AI_CONFIG.get("provider", "auto")
    if provider in ANALYST_AI_PROVIDERS:
        return provider
    for name in ("claude", "openai", "local"):
        if ANALYST_AI_PROVIDERS[name]["ready"]():
            return name
    return None

def call_other_ai_for_analysis(snapshot: dict) -> dict:
    """ติดต่อ 'AI อีกตัวหนึ่ง' ผ่าน API จริง — ไม่ยึดติดผู้ให้บริการเจ้าเดียว
    เลือกได้ระหว่าง claude / openai / local (หรือ "auto" ให้เลือกเองตาม key/
    เซิร์ฟเวอร์ที่มีอยู่) ปรับได้ที่ ANALYST_AI_CONFIG["provider"] แบบ runtime
    ผ่าน POST /api/analyst-ai/config โดยไม่ต้องแก้โค้ด"""
    provider = _analyst_resolve_provider()
    if provider is None:
        return {"status": "no_provider_available", "provider": None,
                "note": "ไม่มี provider ไหนพร้อมใช้เลย — ตั้ง ANTHROPIC_API_KEY, "
                        "OPENAI_API_KEY, หรือเปิดเซิร์ฟเวอร์ local ไว้ อย่างน้อยหนึ่งทาง"}
    try:
        prompt = _analyst_build_prompt(snapshot)
        text = ANALYST_AI_PROVIDERS[provider]["fn"](prompt)
        return {"status": "ok", "provider": provider, "summary": text}
    except Exception as e:
        return {"status": "error", "provider": provider, "note": str(e)}

def run_analyst_ai_once() -> dict:
    """ทำงานหนึ่งรอบ: เก็บ snapshot -> เรียก AI ตัวที่สอง -> ส่งผลไปที่เว็บไซต์
    (bridge state/events) -> เก็บลง history แล้วคืนผลลัพธ์ทั้งหมด"""
    snapshot = collect_analyst_snapshot()
    analysis = call_other_ai_for_analysis(snapshot)
    result = {"ts": snapshot["ts"], "snapshot": snapshot, "analysis": analysis}

    ANALYST_AI_STATE["last_run_ts"] = snapshot["ts"]
    ANALYST_AI_STATE["last_snapshot"] = snapshot
    ANALYST_AI_STATE["last_summary"] = analysis.get("summary")
    ANALYST_AI_STATE["last_provider"] = analysis.get("provider")
    ANALYST_AI_STATE["last_status"] = analysis["status"]
    ANALYST_AI_STATE["history"].append(result)

    # ส่งผลไปที่เว็บไซต์ผ่านช่องทาง bridge เดิม ให้หน้าเว็บ/เกมอื่นดึงไปโชว์ได้เลย
    BRIDGE_STATE["background_analyst_ai"] = {
        "status": analysis["status"], "provider": analysis.get("provider"),
        "summary": analysis.get("summary"), "ts": snapshot["ts"],
    }
    bridge_push_event("background_analyst_ai", "analyst_report", result)

    tag = {"ok": "✅", "no_provider_available": "⏭️ ", "error": "❌"}.get(analysis["status"], "•")
    provider_txt = f"[{analysis['provider']}] " if analysis.get("provider") else ""
    print(f"[Analyst AI] {tag} {provider_txt}{analysis['status']} — players={snapshot['players_online']} "
          f"cheat_pending={snapshot['cheat_reports_pending']}"
          + (f" | {analysis['summary'][:80]}" if analysis.get("summary") else ""))
    return result

def background_analyst_loop():
    """รันเป็น daemon thread แยกจาก tele_loop/physics_loop — วนตลอดในเทอร์มินัล
    เดียวกับที่รันเกม/เว็บนี้ ไม่ใช่ process ใหม่ที่แยกออกไป"""
    while True:
        if ANALYST_AI_CONFIG["enabled"]:
            try:
                run_analyst_ai_once()
            except Exception as e:
                ANALYST_AI_STATE["last_status"] = "error"
                print(f"[Analyst AI] ❌ loop error: {e}")
        time.sleep(max(5, ANALYST_AI_CONFIG["interval_sec"]))


@app.route('/api/analyst-ai/status')
def api_analyst_ai_status():
    """สถานะล่าสุด + config ปัจจุบันของ background analyst AI"""
    return jsonify({
        "st": "ok",
        "config": ANALYST_AI_CONFIG,
        "providers_ready": {name: p["ready"]() for name, p in ANALYST_AI_PROVIDERS.items()},
        "last_run_ts": ANALYST_AI_STATE["last_run_ts"],
        "last_status": ANALYST_AI_STATE["last_status"],
        "last_provider": ANALYST_AI_STATE["last_provider"],
        "last_summary": ANALYST_AI_STATE["last_summary"],
        "last_snapshot": ANALYST_AI_STATE["last_snapshot"],
    })

@app.route('/api/analyst-ai/history')
def api_analyst_ai_history():
    """ผลลัพธ์ย้อนหลังสูงสุด 50 รอบล่าสุด เอาไว้ดูเทรนด์"""
    return jsonify({"st": "ok", "history": list(ANALYST_AI_STATE["history"])})

@app.route('/api/analyst-ai/config', methods=['POST'])
@require_auth_toggleable
def api_analyst_ai_config():
    """ปรับ config runtime: {"enabled": true/false, "interval_sec": 60,
    "provider": "claude"|"openai"|"local"|"auto", "models": {"claude": "..."}}"""
    body = request.json or {}
    if "enabled" in body:
        ANALYST_AI_CONFIG["enabled"] = bool(body["enabled"])
    if "interval_sec" in body:
        try:
            ANALYST_AI_CONFIG["interval_sec"] = max(5, int(body["interval_sec"]))
        except (TypeError, ValueError):
            return jsonify({"st": "error", "msg": "interval_sec ต้องเป็นตัวเลข"}), 400
    if "provider" in body:
        provider = body["provider"]
        if provider not in ANALYST_AI_PROVIDERS and provider != "auto":
            return jsonify({"st": "error",
                            "msg": f"provider ต้องเป็นหนึ่งใน: auto, {', '.join(ANALYST_AI_PROVIDERS)}"}), 400
        ANALYST_AI_CONFIG["provider"] = provider
    if "models" in body and isinstance(body["models"], dict):
        ANALYST_AI_CONFIG["models"].update(body["models"])
    if "local_base_url" in body:
        ANALYST_AI_CONFIG["local_base_url"] = body["local_base_url"]
    return jsonify({"st": "ok", "config": ANALYST_AI_CONFIG})

@app.route('/api/analyst-ai/run-now', methods=['POST'])
@require_auth_toggleable
def api_analyst_ai_run_now():
    """สั่งให้ทำงานหนึ่งรอบทันที ไม่ต้องรอรอบถัดไปของ background loop"""
    return jsonify({"st": "ok", "result": run_analyst_ai_once()})


