def game_systems_list(level: str | None = None, category: str | None = None) -> list:
    out = []
    for key, spec in GAME_SYSTEMS_REGISTRY.items():
        if level and spec.get("level") != level:
            continue
        if category and spec.get("category") != category:
            continue
        out.append({"key": key, "name": spec["name"], "level": spec["level"],
                    "category": spec["category"], "desc": spec["desc"]})
    return out

@app.route('/api/game-systems/list')
def api_game_systems_list():
    """?level=basic|intermediate|advanced&category=... -> รายชื่อระบบที่ตรงเงื่อนไข
    (ไม่ระบุ query = คืนทั้งหมด) เอาไว้ให้เกม/เว็บอื่นดูก่อนว่ามีอะไรให้ดึงบ้าง"""
    return jsonify({"st": "ok",
                    "systems": game_systems_list(request.args.get("level"), request.args.get("category")),
                    "total": len(GAME_SYSTEMS_REGISTRY)})

@app.route('/api/game-systems/<key>')
def api_game_systems_get(key):
    """ดึงสเปคเต็มของระบบเดียว — เอาไปใช้ตอนจะลงมือ implement จริง"""
    spec = GAME_SYSTEMS_REGISTRY.get(key)
    if not spec:
        return jsonify({"st": "error", "msg": f"ไม่พบระบบ '{key}' ในคลัง"}), 404
    return jsonify({"st": "ok", "key": key, "spec": spec})

@app.route('/api/game-systems/contribute', methods=['POST'])
@require_auth_toggleable
def api_game_systems_contribute():
    """ให้เกม/เว็บอื่นที่ต่อเข้ามา (ผ่าน bridge เดิม) เพิ่ม/แก้สเปคของตัวเองเข้าคลัง
    กลางนี้ได้ด้วย body: {key, name, level, category, desc, key_fields, notes,
    overwrite: bool}. ค่า level ต้องเป็น basic/intermediate/advanced เท่านั้น
    ป้องกันเผลอทับของเดิมโดยไม่ตั้งใจ (ต้องส่ง overwrite=true ถ้า key ซ้ำ)"""
    body = request.json or {}
    key = (body.get("key") or "").strip()
    if not key:
        return jsonify({"st": "error", "msg": "ต้องระบุ key"}), 400
    if key in GAME_SYSTEMS_REGISTRY and not body.get("overwrite"):
        return jsonify({"st": "error", "msg": f"'{key}' มีอยู่แล้ว — ส่ง overwrite:true ถ้าต้องการทับ"}), 409
    level = body.get("level", "basic")
    if level not in ("basic", "intermediate", "advanced"):
        return jsonify({"st": "error", "msg": "level ต้องเป็น basic, intermediate, หรือ advanced"}), 400
    spec = {
        "name": body.get("name", key), "level": level, "category": body.get("category", "misc"),
        "desc": body.get("desc", ""), "key_fields": body.get("key_fields", []),
        "notes": body.get("notes"),
    }
    GAME_SYSTEMS_REGISTRY[key] = spec
    bridge_push_event(body.get("source", "unknown"), "game_system_contributed", {"key": key, **spec})
    return jsonify({"st": "ok", "key": key, "spec": spec})


