@app.route('/api/exam/identity/submit', methods=['POST'])
@require_auth_toggleable
def api_exam_identity_submit():
    """ยืนยันชื่อ-นามสกุลจริง + เลขบัตรประชาชนก่อนขอใบเซอร์ (แยกจาก login/JWT เดิม
    ซึ่งยืนยันแค่ 'เจ้าของบัญชีเกม' — ไม่รู้ว่าเจ้าของบัญชีชื่อจริงอะไร) body:
    {full_name, id_number}. เลขบัตรจะถูก checksum ตรวจรูปแบบ แล้วเก็บเฉพาะค่าแฮช +
    เลขที่ปิดบังบางส่วนไว้แสดงผลเท่านั้น ไม่เก็บเลขบัตรจริงแบบข้อความล้วน"""
    uid = getattr(request, 'vmax_uid', None) or resolve_uid()
    d = request.get_json(force=True, silent=True) or {}
    ok, msg, code = _identity_submit(uid, d.get("full_name"), d.get("id_number"))
    if not ok:
        return jsonify({"st": "error", "msg": msg}), code
    rec = _IDENTITY_REGISTRY[uid]
    return jsonify({"st": "ok", "msg": msg,
        "full_name": rec["full_name"], "id_masked": rec["id_masked"]})


@app.route('/api/exam/certificate/request', methods=['POST'])
@require_auth_toggleable
def api_exam_request_certificate():
    uid = getattr(request, 'vmax_uid', None) or resolve_uid()
    # ห้ามออกใบเซอร์เด็ดขาดถ้ายังไม่ได้ตั้งค่าบริษัทผู้ออก + คีย์เซ็นลายเซ็นจริง —
    # กันไม่ให้มีใบเซอร์ที่อ้างบริษัทซึ่งไม่มีตัวตนจริงหลุดออกไป
    if not _cert_issuer_ready():
        return jsonify({"st": "error",
            "msg": "ระบบยังไม่พร้อมออกใบเซอร์ เนื่องจากยังไม่ได้ตั้งค่าข้อมูลบริษัทผู้ออกใบเซอร์จริง "
                   "(VMAX_CERT_COMPANY_NAME / VMAX_CERT_COMPANY_TAX / VMAX_CERT_SECRET_KEY) "
                   "กรุณาติดต่อผู้ดูแลระบบ"}), 503
    # [NEW] ต้องยืนยันตัวตน (ชื่อจริง + เลขบัตรผ่าน checksum) ก่อน ไม่งั้นใบเซอร์จะมีแค่
    # uid (บัญชีเกม) ซึ่งเอาไปสมัครงานไม่ได้จริง
    if not _identity_is_verified(uid):
        return jsonify({"st": "error",
            "msg": "กรุณายืนยันตัวตน (ชื่อ-นามสกุลจริง + เลขบัตรประชาชน) ที่ "
                   "/api/exam/identity/submit ก่อนขอใบเซอร์"}), 403
    a = _exam_get_account(uid)
    years = _exam_age_years(uid)
    if years < _CERT_REQUIRED_YEARS:
        return jsonify({"st": "error",
            "msg": f"บัญชีอายุ {years} ปี ต้องครบ {_CERT_REQUIRED_YEARS} ปีถึงจะขอใบเซอร์ได้",
            "remaining_years": _CERT_REQUIRED_YEARS - years}), 403
    if a["has_certificate"]:
        return jsonify({"st": "ok", "msg": "มีใบเซอร์อยู่แล้ว", "path": a["cert_path"],
            "cert_id": a["cert_id"],
            "verify_url": f"/api/exam/verify/{a['cert_id']}"})
    identity = _IDENTITY_REGISTRY[uid]
    path = _exam_generate_certificate(uid, years,
        display_name=identity["full_name"], id_masked=identity["id_masked"])
    a["has_certificate"] = True
    audit_log("exam_certificate_issued", uid=uid, cert_id=a["cert_id"])
    return jsonify({"st": "ok", "msg": "อนุมัติ! สร้างใบเซอร์และบันทึกลงคลังรูปภาพแล้ว",
        "company": _CERT_COMPANY_NAME, "cert_id": a["cert_id"],
        "path": path, "age_years": years,
        "certified_name": identity["full_name"], "id_masked": identity["id_masked"],
        "verify_url": f"/api/exam/verify/{a['cert_id']}",
        "note": "ใบเซอร์นี้ออกโดยบริษัทที่ตั้งค่าไว้ในระบบ ผู้รับสามารถตรวจสอบความถูกต้องได้ที่ verify_url ด้านบน"})

@app.route('/api/exam/verify/<cert_id>')
def api_exam_verify_certificate(cert_id):
    """Endpoint สาธารณะ ไม่ต้องล็อกอิน — ให้บุคคลภายนอก (เช่น ฝ่าย HR ที่รับสมัครงาน)
    ตรวจสอบว่าใบเซอร์เลขนี้ถูกออกจากระบบจริง ยังไม่ถูกเพิกถอน และลายเซ็นตรงกันหรือไม่"""
    rec = _CERT_REGISTRY.get(cert_id)
    if not rec:
        return jsonify({"st": "error", "valid": False,
            "msg": "ไม่พบใบเซอร์เลขนี้ในระบบ — อาจเป็นใบปลอมหรือกรอกเลขผิด"}), 404
    if rec.get("revoked"):
        return jsonify({"st": "ok", "valid": False, "msg": "ใบเซอร์นี้ถูกเพิกถอนแล้ว",
            "cert_id": cert_id})
    expected_sig = _cert_sign(cert_id, rec["uid"], rec["issue_date"])
    if not _hmac_mod.compare_digest(expected_sig, rec["signature"]):
        # ทะเบียนถูกแก้ไข/ปลอมแปลง หรือ VMAX_CERT_SECRET_KEY ถูกเปลี่ยนหลังออกใบเซอร์นี้
        return jsonify({"st": "error", "valid": False,
            "msg": "ลายเซ็นไม่ตรงกับทะเบียน — ไม่สามารถยืนยันความถูกต้องได้"}), 409
    return jsonify({
        "st": "ok", "valid": True, "cert_id": cert_id,
        "uid": rec["uid"],
        "certified_name": rec.get("display_name") or rec["uid"],
        "id_masked": rec.get("id_masked"),
        "issued_by": _CERT_COMPANY_NAME,
        "company_tax_id": _CERT_COMPANY_TAX,
        "issue_date": rec["issue_date"], "years_of_service": rec["years"],
        "role": "Anti-Cheat Officer", "signature": rec["signature"],
    })

@app.route('/api/exam/certificate/revoke', methods=['POST'])
@require_auth_toggleable
def api_exam_revoke_certificate():
    """เฉพาะแอดมิน (STAFF_RANKS >= admin) — ใช้เมื่อพบว่าออกใบเซอร์ผิดพลาด หรือผู้ถือทำผิดร้ายแรงภายหลัง"""
    caller_uid = getattr(request, 'vmax_uid', None) or resolve_uid()
    if _staff_rank_value(caller_uid) < STAFF_RANKS["admin"]:
        return jsonify({"st": "error", "msg": "ต้องเป็นแอดมินเท่านั้น"}), 403
    d = request.get_json(force=True, silent=True) or {}
    cert_id = d.get("cert_id")
    rec = _CERT_REGISTRY.get(cert_id)
    if not rec:
        return jsonify({"st": "error", "msg": "ไม่พบใบเซอร์เลขนี้"}), 404
    rec["revoked"] = True
    # [BUG-FIX] เดิมไม่ได้รีเซ็ตสถานะฝั่งเจ้าของบัญชี (has_certificate/cert_id ยังค้าง
    # อยู่) ทำให้ api_exam_request_certificate เห็นว่า a["has_certificate"] เป็น True
    # อยู่ตลอด แล้วคืนใบเซอร์ใบเดิม (ที่ถูกเพิกถอนไปแล้ว) ซ้ำ ๆ ทุกครั้งที่ขอใหม่ —
    # ผู้ถือจึงไม่มีทางขอใบเซอร์ใหม่ได้เลยหลังโดนเพิกถอน ต้องรีเซ็ตให้ขอใหม่ได้
    owner_acc = _EXAM_ACCOUNTS.get(rec["uid"])
    if owner_acc is not None:
        owner_acc["has_certificate"] = False
        owner_acc["cert_id"] = None
        owner_acc["cert_path"] = None
    audit_log("exam_certificate_revoked", uid=caller_uid, cert_id=cert_id, target_uid=rec["uid"])
    return jsonify({"st": "ok", "msg": f"เพิกถอนใบเซอร์ {cert_id} แล้ว ผู้ถือขอใบเซอร์ใหม่ได้"})

