@app.route('/api/exam/mailbox/claim', methods=['POST'])
@require_auth
def api_exam_claim_mail():
    uid = getattr(request, 'vmax_uid', None) or resolve_uid()
    d = request.get_json(force=True, silent=True) or {}
    idx = d.get("index", 0)
    box = _exam_get_mailbox(uid)
    if 0 <= idx < len(box) and not box[idx]["received"]:
        box[idx]["received"] = True
        item = box[idx]["item"]
        inv = INVENTORY.setdefault(uid, {})
        inv[item] = inv.get(item, 0) + 1
        return jsonify({"st": "ok", "received": item})
    return jsonify({"st": "error", "msg": "รับของไปแล้วหรือไม่พบ"}), 400

# --- ลงทะเบียนใน VMAX_MODULES ---
