# --- ตัวอย่างการตรวจจับจริงในเกมนี้เอง: อัตรายิงเกินจริง (macro/aimbot มักยิงถี่ผิดปกติ) ---
SHOOT_LOG = {}   # sid -> deque[timestamp] ของการยิงล่าสุด (ไว้คำนวณ shots_per_sec)
FIRE_RATE_LIMIT = 8.0   # นัด/วิ — ปรับตามอาวุธจริงในเกม อันนี้ตั้งแบบผ่อนปรนไว้ก่อน

def check_fire_rate_and_report(sid: str, uid: str) -> bool:
    """เรียกจาก player_shoot ทุกครั้ง — คืน False ถ้าอัตรายิงเกินและได้ยื่นรายงานไปแล้ว"""
    log = SHOOT_LOG.setdefault(sid, deque(maxlen=20))
    now = time.time()
    log.append(now)
    recent = [t for t in log if now - t <= 1.0]
    if len(recent) > FIRE_RATE_LIMIT:
        submit_cheat_report(uid, "vmax", "fire_rate_exceeded",
                            {"shots_per_sec": len(recent), "weapon_max_fire_rate": FIRE_RATE_LIMIT})
        return False
    return True

def _default_resource_profiles(size_mb: float, game_id: str = "game") -> dict:
    base = max(float(size_mb), 1.0)
    return {
        "SD": {"size_mb": round(base * 0.68, 1), "label": "Standard / SD", "asset_url": "", "filename": f"{game_id}_SD.pack"},
        "HD": {"size_mb": round(base * 0.90, 1), "label": "High / HD", "asset_url": "", "filename": f"{game_id}_HD.pack"},
        "UHD": {"size_mb": round(base * 1.00, 1), "label": "Ultra / UHD", "asset_url": "", "filename": f"{game_id}_UHD.pack"},
    }

def catalog_register(game_id: str, name: str,
                      version: str, size_mb: float, genre: str = "shooter",
                      resources: dict | None = None):
    LAUNCHER_CATALOG[game_id] = {
        "name": name, "version": version, "size_mb": float(size_mb),
        "installed": False, "installed_quality": None, "genre": genre,
        "resources": resources or _default_resource_profiles(size_mb, game_id),
    }

def launcher_resource_profile(game_id: str, quality: str = "HD") -> dict | None:
    g = LAUNCHER_CATALOG.get(game_id)
    if not g: return None
    return g.get("resources", {}).get(str(quality or "HD").upper())

DOWNLOAD_LOCK       = threading.Lock()   # กัน race ระหว่าง Flask request thread กับ download_loop
DOWNLOAD_SPEED_MBPS = 40.0                # ความเร็วดาวน์โหลดจำลอง (MB/วิ) ปรับได้
DOWNLOAD_STEP_SEC   = 0.5                 # เดินหน้า progress ทุกกี่วิ

def launcher_install(game_id: str, quality: str = "HD") -> tuple[bool, str]:
    g = LAUNCHER_CATALOG.get(game_id)
    if not g: return False, "Game not in catalog"
    q = str(quality or "HD").upper()
    profile = launcher_resource_profile(game_id, q)
    if not profile: return False, f"ไม่พบ resource quality: {q}"
    with DOWNLOAD_LOCK:
        if any(d["game_id"] == game_id and d.get("resource_quality", "HD") == q for d in DOWNLOAD_QUEUE):
            return False, "กำลังดาวน์โหลดแพ็กนี้อยู่แล้ว"
        DOWNLOAD_QUEUE.append({"game_id": game_id, "resource_quality": q, "progress": 0.0,
                               "total": float(profile["size_mb"]), "started_at": time.time(),
                               "asset_url": profile.get("asset_url", "")})
    return True, f"Download queued: {g['name']} {q} v{g['version']}"

def download_progress_step():
    """เดินหน้า progress ของทุกรายการใน DOWNLOAD_QUEUE จริงตามเวลาที่ผ่านไป (จำลองความเร็ว
    คงที่ DOWNLOAD_SPEED_MBPS) พอครบ total ค่อยตั้ง installed=True จริง แล้วเอาออกจากคิว —
    เรียกจาก download_loop เธรดพื้นหลังทุก DOWNLOAD_STEP_SEC วิ"""
    with DOWNLOAD_LOCK:
        done = []
        for d in DOWNLOAD_QUEUE:
            d["progress"] = min(d["total"], d["progress"] + DOWNLOAD_SPEED_MBPS * DOWNLOAD_STEP_SEC)
            if d["progress"] >= d["total"]:
                done.append(d)
        for d in done:
            DOWNLOAD_QUEUE.remove(d)
            g = LAUNCHER_CATALOG.get(d["game_id"])
            if g:
                g["installed"] = True
                g["installed_quality"] = d.get("resource_quality", "HD")

def download_loop():
    """เธรดพื้นหลัง — ทำให้การดาวน์โหลดในคิวเดินหน้าจริงแม้ไม่มี request เข้ามาเลย"""
    while True:
        download_progress_step()
        time.sleep(DOWNLOAD_STEP_SEC)

def launcher_uninstall(game_id: str) -> tuple[bool, str]:
    g = LAUNCHER_CATALOG.get(game_id)
    if not g or not g["installed"]:
        return False, "Game not installed"
    g["installed"] = False
    g["installed_quality"] = None
    return True, f"Uninstalled {g['name']}"

def search_launcher_catalog(query: str, limit: int = 30) -> list:
    """ค้นหาเกมใน LAUNCHER_CATALOG แบบ substring (ไม่สนตัวพิมพ์เล็ก/ใหญ่) จาก name/genre/game_id —
    ใช้เป็น backend ของหน้าต่างร้านค้าลอย (floating storefront widget, ดู [6j2] ด้านล่าง)
    query ว่าง -> คืนทั้งหมด (จำกัดที่ limit) เรียงตามชื่อ"""
    q = (query or "").strip().lower()
    rows = []
    for game_id, g in LAUNCHER_CATALOG.items():
        haystack = f"{game_id} {g.get('name','')} {g.get('genre','')}".lower()
        if not q or q in haystack:
            rows.append({
                "game_id": game_id, "name": g.get("name", game_id),
                "version": g.get("version", ""), "size_mb": g.get("size_mb", 0),
                "genre": g.get("genre", "shooter"), "installed": bool(g.get("installed")),
                "installed_quality": g.get("installed_quality"), "resources": g.get("resources", {}),
            })
    rows.sort(key=lambda r: r["name"].lower())
    return rows[:limit]

