# uid -> {"game_id","genre","opponent_hp","opponent_max_hp","player_hp","active","mode"}
BATTLE_STATE = {}

def battle_start(uid: str, game_id: str) -> dict:
    g = LAUNCHER_CATALOG.get(game_id, {})
    genre = g.get("genre", "shooter")
    profile = _genre_profile(game_id)
    opp_hp = 80 + P["level"] * 10
    BATTLE_STATE[uid] = {
        "game_id": game_id, "genre": genre, "opponent_hp": opp_hp, "opponent_max_hp": opp_hp,
        "player_hp": P["hp"], "active": True, "mode": profile["battle_mode"]["label"], "combo_count": 0,
    }
    return {"st": "ok", **{k: v for k, v in BATTLE_STATE[uid].items() if k != "game_id"}}

def battle_attack(uid: str) -> dict:
    st = BATTLE_STATE.get(uid)
    if not st or not st["active"]:
        return {"st": "error", "msg": "ยังไม่ได้เริ่มการต่อสู้"}
    dmg = random.randint(8, 18)
    st["opponent_hp"] = max(0, st["opponent_hp"] - dmg)
    st["combo_count"] = min(3, st.get("combo_count", 0) + 1)
    result = {"st": "ok", "dealt": dmg, "opponent_hp": st["opponent_hp"],
              "combo_count": st["combo_count"], "finisher_ready": st["combo_count"] >= 3}
    if st["opponent_hp"] <= 0:
        st["active"] = False
        P["credits"] += 100
        WALLET["balance"] = P["credits"]
        result["win"] = True
        result["reward"] = {"credits": 100}
        return result
    counter = random.randint(5, 15)
    st["player_hp"] = max(0, st["player_hp"] - counter)
    P["hp"] = st["player_hp"]
    result["counter_damage"] = counter
    result["player_hp"] = st["player_hp"]
    if st["player_hp"] <= 0:
        st["active"] = False
        result["lose"] = True
    return result

def battle_finisher(uid: str) -> dict:
    """ท่าไม้ตาย 'หนีบปลิดชีพ' (snip_finisher) — เฉพาะเกม genre 'fighting' เท่านั้น
    ต้องสะสมคอมโบให้ครบ (combo_charges_needed) ก่อนถึงจะปล่อยได้ ดาเมจคูณตาม
    damage_multiplier ของท่าใน SCISSOR_COMBAT_ASSET"""
    st = BATTLE_STATE.get(uid)
    if not st or not st["active"]:
        return {"st": "error", "msg": "ยังไม่ได้เริ่มการต่อสู้"}
    if st.get("genre") != "fighting":
        return {"st": "error", "msg": "ท่าไม้ตายนี้ใช้ได้เฉพาะเกมแนวต่อสู้ (อาวุธกรรไกรนักฆ่า) เท่านั้น"}

    finisher = next(c for c in SCISSOR_COMBAT_ASSET["combo_sets"] if c["id"] == "snip_finisher")
    needed = finisher["combo_charges_needed"]
    if st.get("combo_count", 0) < needed:
        return {"st": "error", "msg": f"คอมโบยังไม่เต็ม ({st.get('combo_count', 0)}/{needed}) — โจมตีสะสมก่อนถึงจะปล่อยท่าไม้ตายได้"}

    dmg = int(random.randint(8, 18) * finisher["damage_multiplier"])
    st["opponent_hp"] = max(0, st["opponent_hp"] - dmg)
    st["combo_count"] = 0
    result = {"st": "ok", "dealt": dmg, "opponent_hp": st["opponent_hp"], "move": finisher["name_th"]}
    if st["opponent_hp"] <= 0:
        st["active"] = False
        P["credits"] += 150
        WALLET["balance"] = P["credits"]
        result["win"] = True
        result["reward"] = {"credits": 150}
        return result
    counter = random.randint(5, 15)
    st["player_hp"] = max(0, st["player_hp"] - counter)
    P["hp"] = st["player_hp"]
    result["counter_damage"] = counter
    result["player_hp"] = st["player_hp"]
    if st["player_hp"] <= 0:
        st["active"] = False
        result["lose"] = True
    return result



