# ==========================================
# [ 2. Core Architecture & Game State ]
# ==========================================
class BatteryDigitalTwin:
    def __init__(self):
        self.soc = 100.0
        self.v = 4.2
        self.t = 25.0

    def drain(self, d):
        self.soc = max(0, self.soc - d)
        self.t += d * 0.15

    def tick(self, current):
        self.soc = max(0, min(100, self.soc - (current / 3600 / 2.5) * 100))
        self.v = 3.0 + 1.2 * (self.soc / 100) - current * 0.02
        self.t += (current ** 2 * 0.02 * 0.1) - ((self.t - 25) * 0.02)
        return {"soc_percent": round(self.soc, 1), "voltage_v": round(self.v, 2), "temp_c": round(self.t, 1)}


# app + sio ถูกสร้างไปแล้วที่ [ 1b. ] ด้านบนสุดของไฟล์ — ไม่สร้างซ้ำตรงนี้ เพราะ
# ถ้าสร้าง SocketIO(app) รอบสองจะทำให้ @sio.on(...) ทั้งหมดที่ลงทะเบียนไปก่อนหน้านี้
# (เช่น 'connect'/'disconnect'/'player_input' ในหัวข้อ Multiplayer Sync) หลุดหาย
# เพราะไปผูกกับ instance เก่าที่ไม่มีใครใช้งานต่อแล้ว
BAT = BatteryDigitalTwin()

# --- Community game uploads (นักพัฒนาเกมคนอื่นส่งไฟล์ .exe/.apk ให้คนโหลดเล่น) --
# เก็บไฟล์จริงไว้ใน GAME_UPLOADS_DIR/<game_id>/<ชื่อไฟล์> และเก็บ metadata
# (ชื่อเกม, แพลตฟอร์ม, ขนาดไฟล์, เวลาที่ส่ง ฯลฯ) แยกไว้ใน index.json ตาม pattern
# เดียวกับ _load_pending/_save_pending ที่ใช้กับระบบ "เพิ่มระบบใหม่" ด้านบน
GAME_UPLOADS_DIR = "uploaded_games"
GAME_UPLOADS_INDEX_PATH = os.path.join(GAME_UPLOADS_DIR, "index.json")
ALLOWED_GAME_EXTENSIONS = {"exe", "apk"}  # เพิ่ม "zip" เองได้ถ้าอยากรองรับเกมเว็บ/บิลด์อื่นๆ
# [BUG-FIX #11] เดิม 500 GB ต่อไฟล์ — ตัวเลขนี้สูงจนแทบไม่ทำหน้าที่เป็น cap เลยจริงๆ
# (เกม .exe/.apk จริงแทบไม่มีตัวไหนใหญ่ขนาดนั้น) ผลคือ client ที่ตั้งใจ/พลาด ส่งสตรีม
# ข้อมูลมหาศาลเข้ามาได้เกือบไม่จำกัด กิน disk/bandwidth ของ server จนพังได้ (DoS ทาง
# อ้อม) ลดเหลือค่าที่เกมจริงๆ ควรอยู่ในขอบเขตนี้ (ปรับผ่าน env ได้ถ้าเกมใหญ่กว่านี้จริง)
#   export VMAX_MAX_GAME_UPLOAD_GB=16
MAX_GAME_UPLOAD_BYTES = int(os.environ.get("VMAX_MAX_GAME_UPLOAD_GB", "8")) * 1024 * 1024 * 1024
os.makedirs(GAME_UPLOADS_DIR, exist_ok=True)
# [SECURITY-FIX U1] เดิมตั้ง MAX_CONTENT_LENGTH = ขนาดเกมสูงสุด (GB) ให้ "ทุก route" ทั้งเซิร์ฟเวอร์
# ทำให้ endpoint JSON ธรรมดาทุกตัวรับ body หลาย GB ได้ (DoS ทางดิสก์/RAM/แบนด์วิดท์)
# ตอนนี้ขีดจำกัดทั่วไปเล็กลง (default 512 MB ปรับด้วย VMAX_MAX_BODY_MB) และให้เพดานใหญ่
# เฉพาะ route อัปโหลดเกมเท่านั้น (override รายคำขอผ่าน request_class — ใช้ได้ทุกเวอร์ชัน Flask)
_DEFAULT_MAX_BODY_BYTES = int(os.environ.get("VMAX_MAX_BODY_MB", "512")) * 1024 * 1024
_LARGE_BODY_PATHS = {"/api/games/upload"}
GAME_UPLOAD_MIN_FREE_BYTES = int(os.environ.get("VMAX_MIN_FREE_DISK_GB", "5")) * 1024 * 1024 * 1024
app.config["MAX_CONTENT_LENGTH"] = _DEFAULT_MAX_BODY_BYTES

class _VmaxRequest(app.request_class):
    @property
    def max_content_length(self):
        if self.path in _LARGE_BODY_PATHS:
            return MAX_GAME_UPLOAD_BYTES
        return _DEFAULT_MAX_BODY_BYTES

    @max_content_length.setter
    def max_content_length(self, value):
        pass

app.request_class = _VmaxRequest

# --- Optional S3-compatible storage for game uploads ------------------------
# ตั้ง env var S3_BUCKET ไว้ = อัปโหลดไฟล์เกมขึ้น S3 (หรืออะไรก็ได้ที่พูด S3 API
# เหมือนกัน เช่น Cloudflare R2 / MinIO / DigitalOcean Spaces / Backblaze B2)
# แทนการเก็บลงดิสก์เซิร์ฟเวอร์ตรงๆ — เหมาะกับไฟล์ใหญ่เพราะโหลดผ่าน "presigned URL"
# ที่ชี้ตรงไปที่ S3 เลย ไม่ต้องผ่าน/กินแบนด์วิดท์เซิร์ฟเวอร์ตัวนี้
#   export S3_BUCKET=my-vmax-games
#   export S3_ENDPOINT_URL=https://xxxx.r2.cloudflarestorage.com   # เว้นว่างถ้าใช้ AWS S3 จริง
#   export S3_REGION=auto           # หรือ region จริงถ้าใช้ AWS
#   export AWS_ACCESS_KEY_ID=...    # boto3 อ่าน env var มาตรฐานพวกนี้เอง
#   export AWS_SECRET_ACCESS_KEY=...
# ไม่ตั้ง S3_BUCKET = fallback ไปเก็บลงดิสก์เหมือนเดิมทุกอย่าง ไม่พัง
S3_BUCKET = os.environ.get("S3_BUCKET")
S3_ENDPOINT_URL = os.environ.get("S3_ENDPOINT_URL") or None
S3_REGION = os.environ.get("S3_REGION", "us-east-1")
S3_PRESIGNED_URL_TTL = 3600  # ลิงก์โหลดจาก S3 หมดอายุใน 1 ชม.

# ขี้เกียจไปตั้ง CORS เองในหน้า console ของ S3? ปล่อยให้สคริปต์นี้ตั้งให้อัตโนมัติตอน
# start ได้เลย (ต้องการสิทธิ์ PutBucketCORS บน access key ที่ใช้) — ปิดได้ด้วย
# S3_AUTO_CORS=0 ถ้าอยากตั้งเองหรือ IAM policy ไม่ให้สิทธิ์นี้ไว้
S3_AUTO_CORS = os.environ.get("S3_AUTO_CORS", "1") != "0"
# origin ที่อนุญาตให้ browser อัปโหลดตรงเข้า bucket ได้ — ค่า default "*" คือเปิดให้
# ทุกโดเมนได้ (สะดวกสุดตอนทดสอบ) แต่ถ้าจะเอาขึ้นจริงจัง ควรตั้งเป็นโดเมนเว็บตัวเอง
# เช่น export S3_CORS_ORIGIN=https://your-domain.com เพื่อกันคนอื่นเอา presigned URL
# ไปยิงอัปโหลดแทรกจากเว็บอื่น
S3_CORS_ORIGIN = os.environ.get("S3_CORS_ORIGIN", "*")
# [UPGRADE][SECURITY-FIX #7] เดิม default "*" แค่พิมพ์ warning เฉยๆ แล้วยังตั้ง CORS
# แบบ wildcard บน bucket จริงให้อัตโนมัติต่อไป — ถ้าลืมตั้ง S3_CORS_ORIGIN ก่อน deploy
# จริง (เรื่องที่เกิดขึ้นได้ง่ายมาก) เว็บไซต์ไหนก็เอา presigned URL ที่หลุดออกไปยิง
# อัปโหลด/ปลอมแปลงเข้า bucket แทนผู้ใช้ได้ (CORS wildcard = ทุก origin ผ่านได้หมด)
# ตอนนี้เปลี่ยนเป็น "fail-safe": ถ้ายังเป็น wildcard จะไม่ยอมตั้ง CORS อัตโนมัติให้เอง
# อีกต่อไป (ต้องตั้ง S3_CORS_ORIGIN เป็นโดเมนจริงก่อน ถึงจะเปิด S3_AUTO_CORS ได้จริง)
# เว้นแต่จะยืนยันชัดเจนด้วย S3_ALLOW_WILDCARD_CORS=1 (สำหรับ dev/ทดสอบในเครื่องเท่านั้น)
S3_ALLOW_WILDCARD_CORS = os.environ.get("S3_ALLOW_WILDCARD_CORS", "0") == "1"
if S3_AUTO_CORS and S3_CORS_ORIGIN == "*" and not S3_ALLOW_WILDCARD_CORS:
    print("[VMAX Kernel][WARNING] S3_CORS_ORIGIN ยังเป็น '*' (ทุกโดเมนอัปโหลดตรงเข้า bucket ได้) "
          "— ปิด S3_AUTO_CORS อัตโนมัติไว้ก่อนเพื่อความปลอดภัย (ไม่ตั้ง wildcard CORS บน bucket "
          "ให้เอง) ตั้ง env S3_CORS_ORIGIN=https://your-domain.com ก่อนเอาขึ้นจริง — หรือถ้ากำลัง "
          "ทดสอบในเครื่องและยอมรับความเสี่ยงนี้ ให้ตั้ง S3_ALLOW_WILDCARD_CORS=1 เพิ่มด้วย")
    S3_AUTO_CORS = False
elif S3_AUTO_CORS and S3_CORS_ORIGIN == "*" and S3_ALLOW_WILDCARD_CORS:
    print("[VMAX Kernel][WARNING] S3_CORS_ORIGIN เป็น '*' และ S3_ALLOW_WILDCARD_CORS=1 "
          "(ยืนยันแล้วว่ายอมรับความเสี่ยง) — ตั้ง wildcard CORS บน bucket ต่อไปตามเดิม "
          "ห้ามใช้ค่านี้บน production")

_s3 = None
if S3_BUCKET:
    try:
        import boto3
        _s3 = boto3.client("s3", region_name=S3_REGION, endpoint_url=S3_ENDPOINT_URL)
        print(f"[VMAX Kernel] S3 storage เปิดใช้งานสำหรับเกมที่อัปโหลด — bucket={S3_BUCKET}")
        if S3_AUTO_CORS:
            try:
                _s3.put_bucket_cors(Bucket=S3_BUCKET, CORSConfiguration={
                    "CORSRules": [{
                        "AllowedMethods": ["PUT", "GET"],
                        "AllowedOrigins": [S3_CORS_ORIGIN],
                        "AllowedHeaders": ["*"],
                        "ExposeHeaders": ["ETag"],
                        "MaxAgeSeconds": 3600,
                    }]
                })
                print(f"[VMAX Kernel] ตั้ง CORS บน bucket ให้อัตโนมัติแล้ว (origin={S3_CORS_ORIGIN})")
            except Exception as e:
                print(f"[VMAX Kernel][WARNING] ตั้ง CORS อัตโนมัติไม่สำเร็จ ({e}) — "
                      "อัปโหลดตรงจาก browser ไป S3 (upload_init) อาจใช้ไม่ได้จนกว่าจะตั้ง CORS "
                      "เองในหน้า S3 console (หรือเช็คว่า access key มีสิทธิ์ PutBucketCORS "
                      "ไหม) — ทางเลือกอื่นคือใช้ S3_AUTO_CORS=0 แล้วอัปโหลดผ่าน /api/games/upload "
                      "(relay ผ่านเซิร์ฟเวอร์) แทน ซึ่งไม่ต้องพึ่ง CORS เลย")
    except ImportError:
        print("[VMAX Kernel][WARNING] ตั้ง S3_BUCKET ไว้ แต่ไม่ได้ติดตั้ง boto3 — "
              "รัน: pip install boto3 — ตอนนี้ fallback ไปเก็บไฟล์ลงดิสก์เซิร์ฟเวอร์แทน")

# --- Browser → S3 โดยตรง (presigned upload) ---------------------------------
# แทนที่จะให้ browser ส่งไฟล์มาที่เซิร์ฟเวอร์ตัวนี้ก่อนแล้วค่อย relay ขึ้น S3
# (แบบ /api/games/upload เดิม ซึ่งไฟล์ต้องผ่านเซิร์ฟเวอร์ 2 รอบ — เปลืองทั้ง
# แบนด์วิดท์และหน่วยความจำ) เส้นทางนี้ให้ browser คุยกับ S3 ตรงๆ:
#   1) POST /api/games/upload_init  -> ขอ presigned URL(s) จากเซิร์ฟเวอร์ (ไม่ส่งไฟล์)
#   2) browser PUT ไฟล์ (หรือแต่ละ part ถ้าไฟล์ใหญ่กว่า S3_MULTIPART_THRESHOLD)
#      ตรงไปที่ S3 เอง — เซิร์ฟเวอร์ไม่เห็นไบต์ไฟล์เลย
#   3) POST /api/games/upload_complete -> บอกเซิร์ฟเวอร์ว่าอัปโหลดเสร็จแล้ว
# ⚠️ ต้องเปิด CORS บน S3 bucket เองก่อนถึงจะใช้ได้ (ดูคำอธิบายในคำตอบ)
S3_MULTIPART_THRESHOLD = 5 * 1024 * 1024 * 1024  # เกิน 5GB ต้องใช้ multipart (ข้อจำกัดของ S3 single PUT)
S3_PART_SIZE = 100 * 1024 * 1024                 # 100MB ต่อ part ตอน multipart
PENDING_UPLOADS_PATH = os.path.join(GAME_UPLOADS_DIR, "pending_uploads.json")

def _load_pending_uploads() -> dict:
    if os.path.exists(PENDING_UPLOADS_PATH):
        with open(PENDING_UPLOADS_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    return {}

def _save_pending_uploads(d: dict):
    with open(PENDING_UPLOADS_PATH, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=2)

def _load_games_index() -> dict:
    if os.path.exists(GAME_UPLOADS_INDEX_PATH):
        with open(GAME_UPLOADS_INDEX_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    return {}

def _save_games_index(idx: dict):
    with open(GAME_UPLOADS_INDEX_PATH, "w", encoding="utf-8") as f:
        json.dump(idx, f, ensure_ascii=False, indent=2)

def _game_ext(filename: str) -> str:
    return filename.rsplit(".", 1)[-1].lower() if "." in filename else ""

# --- [P0 FIX #2] Player state: one dict per uid instead of one shared global ---
# เดิม P เป็น dict global ตัวเดียวที่ทุก request/ทุก uid ใช้ร่วมกัน แปลว่า credits/
# exp/hp/level ของ "ผู้เล่นทุกคน" จริงๆ แล้วเป็นก้อนเดียวกันหมด — ผู้เล่น A ยิง
# endpoint ไหนก็ตามด้วย uid ของตัวเอง จะไปแก้ credits ของผู้เล่น B ทันที (และตรงกันข้าม)
# นี่คือช่องโหว่เศรษฐกิจเกมตัวใหญ่ที่สุดในไฟล์นี้ เปลี่ยนเป็น per-uid โดยไม่ต้องแก้
# ทุกจุดที่อ้าง P[...] ทั่วไฟล์ (มีมากกว่า 270 จุด) ด้วยการทำ P เป็น proxy object ที่
# resolve ไปยัง dict ของ uid "ปัจจุบัน" ของ request นั้นๆ (ผูกด้วย contextvar ที่
# before_request ตั้งไว้ทุก request — อ่าน uid จาก JWT session ก่อนถ้ามี ไม่งั้น fallback
# ไปที่ uid ใน body/args/form เพื่อคงพฤติกรรมเดิมของ endpoint ที่ยังไม่บังคับ auth)
# โค้ดเดิมทุกจุดที่เขียน P["credits"], P.get(...), P["level"] += 1 ฯลฯ ยังใช้ได้เหมือน
# เดิมทุกประการ แต่ตอนนี้แต่ละ uid จะมี state แยกจากกันจริงแล้ว
import contextvars as _contextvars
from collections.abc import MutableMapping as _MutableMapping

_DEFAULT_PLAYER_STATE = {"level": 1, "exp": 0, "credits": 500, "score": 0,
                          "weap": "plasma", "hp": 100, "ammo": 12, "reserve_ammo": 36}
PLAYER_STATES = {}   # uid -> player state dict (ของเดิมใช้ PLAYERS ไปแล้วสำหรับ socket/sid)
_current_uid_ctx = _contextvars.ContextVar("vmax_current_uid", default="VMAX-OP-01")

def set_current_uid(uid: str | None) -> None:
    _current_uid_ctx.set(uid or "VMAX-OP-01")

def get_current_uid() -> str:
    return _current_uid_ctx.get()

def _player_state_for(uid: str) -> dict:
    st = PLAYER_STATES.get(uid)
    if st is None:
        st = dict(_DEFAULT_PLAYER_STATE)
        st["uid"] = uid
        PLAYER_STATES[uid] = st
    return st

class _CurrentPlayerProxy(_MutableMapping):
    """ทำงานเหมือน dict P เดิมทุกประการ (P[...], P.get, P.setdefault, P.update, ...)
    แต่ทุกการเข้าถึงจะถูกส่งต่อไปยัง state dict ของ uid ปัจจุบัน (ดู _vmax_bind_current_uid)."""
    def __getitem__(self, k): return _player_state_for(get_current_uid())[k]
    def __setitem__(self, k, v): _player_state_for(get_current_uid())[k] = v
    def __delitem__(self, k): del _player_state_for(get_current_uid())[k]
    def __iter__(self): return iter(_player_state_for(get_current_uid()))
    def __len__(self): return len(_player_state_for(get_current_uid()))
    def __repr__(self): return repr(_player_state_for(get_current_uid()))

P = _CurrentPlayerProxy()

@app.before_request
def _vmax_bind_current_uid():
    """ผูก P ของแต่ละ request เข้ากับ uid ที่ถูกต้อง: เชื่อ JWT session ก่อนเสมอถ้ามี
    (ปลอมแปลงไม่ได้ ผ่าน verify_jwt) ถ้าไม่มี session ค่อย fallback ไปอ่าน uid จาก
    body/args/form ของ request (คง backward-compat ของ endpoint ที่ยังไม่บังคับ auth —
    ดู require_auth / P0 #3 สำหรับจุดที่ถูกบังคับ auth แล้ว).

    [BUG-FIX #GLM-2] เดิม fallback (อ่าน uid จาก body ตรงๆ) เกิดขึ้นแบบเงียบๆ ไม่มี
    audit trail เลย ทำให้ endpoint ไหนก็ตามที่ยังไม่ได้แปะ @require_auth (เช่น
    /api/gacha/pull, /api/sr/deploy ก่อนแก้) ยอมให้ผู้เรียกที่ไม่มี JWT ส่ง
    {"uid": "เหยื่อ"} มาสวมรอยเป็นคนอื่นได้ทันที เพราะ P["uid"] จะ resolve เป็น uid
    ที่ส่งมาโดยไม่มีการตรวจสอบใดๆ — ตอนนี้ใช้ pattern เดียวกับ resolve_uid() ด้านล่าง
    (ที่มี audit_log("uid_resolved_via_fallback", ...) อยู่แล้ว) เพื่อให้ทุกครั้งที่
    fallback เกิดขึ้นจริงถูกบันทึกไว้ตรวจสอบย้อนหลังได้ ว่า endpoint ไหนยังเสี่ยงอยู่
    (ทางแก้ที่ถูกต้องจริงๆ คือทยอยแปะ @require_auth ให้ endpoint ที่กระทบเงิน/ไอเทม/
    ข้อมูลผู้ใช้ทุกจุด — audit log นี้ช่วยให้ไล่หาจุดที่เหลือได้ตรงๆ แทนต้องเดา)."""
    uid = None
    auth_header = request.headers.get('Authorization', '')
    if auth_header.startswith('Bearer '):
        sess = verify_jwt(auth_header[7:])
        if sess:
            uid = sess.get('uid')
    jwt_ok = bool(uid)
    # [SEC-AUDIT round 3] Once a valid JWT exists, a client-supplied uid must never
    # override it on strict-auth gameplay endpoints. Reject mismatches instead of
    # merely auditing them; this closes IDOR/impersonation paths where an attacker
    # has their own valid token but sends another player's uid in JSON/query/form.
    if jwt_ok and request.endpoint in _VS_STRICT_AUTH_ENDPOINTS and request.method in ("POST", "PUT", "PATCH", "DELETE"):
        try:
            body_for_uid_check = request.get_json(silent=True) or {}
        except Exception:
            body_for_uid_check = {}
        client_uid = None
        if isinstance(body_for_uid_check, dict):
            client_uid = body_for_uid_check.get("uid")
        client_uid = client_uid or request.args.get("uid") or request.form.get("uid")
        if client_uid is not None and str(client_uid).strip() and str(client_uid).strip() != str(uid).strip():
            audit_log("uid_mismatch_rejected", uid=str(uid), requested_uid=str(client_uid),
                      endpoint=request.path, method=request.method)
            return jsonify({"st": "error", "msg": "uid ไม่ตรงกับบัญชีที่ล็อกอิน"}), 403
    if not uid:
        body = request.get_json(silent=True) or {}
        if isinstance(body, dict):
            uid = body.get('uid')
        uid = uid or request.args.get('uid') or request.form.get('uid')
        if uid:
            audit_log("uid_resolved_via_fallback", uid=uid,
                       endpoint=request.path, method=request.method)
    # [SEC-AUDIT] strict auth mode: endpoint เขียนข้อมูลที่ไม่มี JWT ถูกปฏิเสธ (เดิมสวมรอยเป็น uid ใครก็ได้ผ่าน body
    # หรือตกไปเป็นผู้เล่นเริ่มต้น VMAX-OP-01) เปิดด้วย VMAX_STRICT_AUTH=1 หรือ VMAX_ENV=production
    if (not jwt_ok and request.method in ("POST", "PUT", "PATCH", "DELETE")
            and request.endpoint in _VS_STRICT_AUTH_ENDPOINTS and _vs_strict_auth_enabled()):
        audit_log("strict_auth_rejected", uid=str(uid or ""), endpoint=request.path, method=request.method)
        return jsonify({"st": "error",
                        "msg": "ต้อง login ก่อน (strict auth mode: ส่ง header Authorization: Bearer <token>)"}), 401
    set_current_uid(uid)

# --- [P0.5 FIX] resolve_uid(): จุดกลางจุดเดียวสำหรับ endpoint ที่ยังอ่าน uid ตรงๆ
# จาก body (แทนที่จะผ่าน P proxy) — แพทเทิร์นเดียวกับ _vmax_bind_current_uid ด้านบน
# (เชื่อ JWT ก่อนเสมอเพราะปลอมแปลงไม่ได้ ถ้าไม่มี/หมดอายุค่อย fallback ไป uid ใน
# body/args/form เพื่อคง backward-compat กับ frontend เดิมที่ยังไม่ส่ง JWT) แต่จุดต่างจาก
# _vmax_bind_current_uid ตรงที่จุดนี้จะ audit_log ทุกครั้งที่เกิด fallback จริง เพื่อให้เห็น
# ชัดเจนว่า endpoint ไหนยัง "เชื่อ uid ที่ client ส่งมาเอง" อยู่ (ยังปลอมแปลงได้) จะได้ทยอย
# บังคับ require_auth() เพิ่มทีละจุดในอนาคตโดยไม่ต้องเดา — ดู log event "uid_resolved_via_fallback"
# ใช้แทน body.get('uid') ตรงๆ ทีละ endpoint (เริ่มจากกลุ่มที่กระทบข้อมูล/เงิน/ไอเทมของผู้ใช้ก่อน)
def resolve_uid(body: dict | None = None, *, required: bool = False) -> str | None:
    """คืน uid ของผู้เรียก โดยเชื่อ JWT session (header Authorization: Bearer <token>) ก่อนเสมอ
    ถ้าไม่มี/หมดอายุ/ปลอมแปลง ค่อย fallback ไปอ่าน uid จาก body ที่ endpoint ส่งเข้ามาให้ (หรือ
    args/form ถ้า body ไม่มี) — ทุกครั้งที่ fallback เกิดขึ้นจริง (เจอ uid จากทางที่ไม่ใช่ JWT)
    จะถูก audit_log ไว้พร้อม endpoint/method เพื่อให้ตรวจสอบย้อนหลังได้ว่าจุดไหนยังเสี่ยง
    ถ้า required=True และหา uid ไม่ได้เลยทั้งสองทาง จะคืน None ให้ caller ตัดสินใจตอบ 400/401 เอง
    (ฟังก์ชันนี้เองไม่ throw/ตอบ response แทน caller)"""
    auth_header = request.headers.get('Authorization', '')
    if auth_header.startswith('Bearer '):
        sess = verify_jwt(auth_header[7:])
        if sess and sess.get('uid'):
            return sess['uid']
    if body is None:
        body = request.get_json(silent=True) or {}
    uid = None
    if isinstance(body, dict):
        uid = body.get('uid')
    uid = uid or request.args.get('uid') or request.form.get('uid')
    if uid:
        audit_log("uid_resolved_via_fallback", uid=uid,
                   endpoint=request.path, method=request.method)
    elif required:
        return None
    return uid

W = {
    "plasma": {"name": "Pulse Rifle", "cost": 0, "dmg": 25, "energy": 2.0, "mag_size": 12},
    "railgun": {"name": "Hyper Railgun", "cost": 300, "dmg": 60, "energy": 5.0, "mag_size": 6},
}
ACTIVE_PROCS = {}

# ==========================================
# [ 2a2. Dive Shot + Leech (rainforest terrain mechanic) ]
# ==========================================
DIVE = {"bonus_until": 0}
LEECHES = {}  # id -> {"dmg_per_tick": int}

def do_dive():
    DIVE["bonus_until"] = time.time() + 0.6  # หน้าต่างเวลาที่นัดถัดไปได้โบนัสดาเมจ
    LEECHES.clear()
    n = random.choices([0, 1, 2, 3], weights=[30, 40, 20, 10])[0]  # ส่วนใหญ่โดน 0-1 ตัว
    for _ in range(n):
        lid = uuid.uuid4().hex[:6]
        LEECHES[lid] = {"dmg_per_tick": 2}
    return list(LEECHES.keys())

def remove_leech(lid):
    return LEECHES.pop(lid, None) is not None

def leech_tick():
    """เรียกทุก 1 วิ จาก tele_loop — ดูดเลือดผู้เล่นตามจำนวนปลิงที่ยังเกาะอยู่"""
    if LEECHES:
        total_dmg = sum(l["dmg_per_tick"] for l in LEECHES.values())
        P["hp"] = max(1, P["hp"] - total_dmg)  # ไม่ให้ตายจากปลิงอย่างเดียว เหลือ hp อย่างน้อย 1

# ==========================================
# [ 2a3. Ammo / Reload (one bullet at a time) ]
# ==========================================
LAST_RELOAD_AT = {"t": 0}
RELOAD_INTERVAL = 0.3  # วินาที ต่อนัดที่ใส่
# [HOLD-RELOAD] กดปุ่มรีโหลดค้าง = รีโหลดช้าลงอย่างตั้งใจ
# ใช้เป็น server-side timing ด้วย เพื่อไม่ให้ client ปรับแอนิเมชันอย่างเดียว
RELOAD_SLOW_INTERVAL = 0.85
RELOAD_NORMAL_LOCK_DURATION = 0.35
RELOAD_SLOW_LOCK_DURATION = 0.90

# --- Anti-Cheat: Reload-Lock (ปิดช่องโหว่ "reload canceling") --------------
# ช่องโหว่เดิม: /api/reload กับ /api/fire เป็นคนละ endpoint ไม่เกี่ยวกันเลย
# ผู้เล่นโกงสามารถเรียก insert bullet แล้วยิงตามทันทีในเฟรมถัดไป โดยไม่ต้องรอ
# "จังหวะปิดรังเพลิง" (chamber the round) เหมือนผู้เล่นปกติที่ต้องรอแอนิเมชัน
# reload ฝั่ง client เล่นจบก่อนถึงจะยิงได้จริง — เท่ากับได้รีโหลดเร็วกว่าที่ตั้งใจ
# ไว้แบบไม่จำกัด (client-side animation timing ไม่มีผลอะไรกับ server เลย)
# ทางแก้: ล็อกฝั่ง server เอง — ทันทีที่ใส่กระสุนสำเร็จ ห้ามยิงจนกว่าจะครบ
# RELOAD_LOCK_DURATION วินาที (จำลองจังหวะปิดรังเพลิง) ไม่ว่า client จะพยายาม
# เรียก /api/fire เร็วแค่ไหนก็ตาม เพราะเช็คจากเวลาจริงบนเซิร์ฟเวอร์เท่านั้น
RELOAD_LOCK_UNTIL = {"t": 0}
RELOAD_LOCK_DURATION = RELOAD_NORMAL_LOCK_DURATION  # ค่า default

def insert_one_bullet(slow=False):
    """ใส่กระสุน 1 นัด; slow=True ใช้เมื่อผู้เล่นกดรีโหลดค้าง"""
    mag = W[P["weap"]]["mag_size"]
    now = time.time()
    interval = RELOAD_SLOW_INTERVAL if slow else RELOAD_INTERVAL
    lock_duration = RELOAD_SLOW_LOCK_DURATION if slow else RELOAD_NORMAL_LOCK_DURATION
    if P["ammo"] >= mag:
        return False, "แม็กเต็มแล้ว"
    if now - LAST_RELOAD_AT["t"] < interval:
        return False, "ใส่เร็วเกินไป รอจังหวะก่อน"
    LAST_RELOAD_AT["t"] = now
    RELOAD_LOCK_UNTIL["t"] = now + lock_duration  # ล็อกการยิงทันที ปิดช่อง reload-cancel
    P["ammo"] += 1
    return True, f"ใส่กระสุนแล้ว {P['ammo']}/{mag}"

# [MAGAZINE-RELOAD] เปลี่ยนแม็กทั้งแม็ก โดยดึงกระสุนจาก reserve_ammo
MAG_RELOAD_NORMAL_DURATION = 1.10
MAG_RELOAD_SLOW_DURATION = 2.40
MAG_RELOAD_NORMAL_LOCK_DURATION = 1.15
MAG_RELOAD_SLOW_LOCK_DURATION = 2.45
LAST_MAG_RELOAD_AT = {"t": 0}

def _ensure_reserve_ammo():
    if P.get("reserve_ammo") is None:
        P["reserve_ammo"] = W[P["weap"]]["mag_size"] * 3
    return int(P.get("reserve_ammo", 0))

def reload_full_magazine(slow=False):
    """เปลี่ยนแม็กทั้งแม็ก; slow=True ใช้เมื่อกดค้าง"""
    mag = W[P["weap"]]["mag_size"]
    reserve = _ensure_reserve_ammo()
    current = int(P.get("ammo", 0))
    if current >= mag:
        return False, "แม็กเต็มแล้ว", current, reserve, 0.0
    if reserve <= 0:
        return False, "กระสุนสำรองหมด", current, reserve, 0.0
    now = time.time()
    duration = MAG_RELOAD_SLOW_DURATION if slow else MAG_RELOAD_NORMAL_DURATION
    if now - LAST_MAG_RELOAD_AT["t"] < duration:
        wait = duration - (now - LAST_MAG_RELOAD_AT["t"])
        return False, f"กำลังเปลี่ยนแม็ก รออีก {wait:.2f} วิ", current, reserve, wait
    take = min(mag - current, reserve)
    P["ammo"] = current + take
    P["reserve_ammo"] = reserve - take
    LAST_MAG_RELOAD_AT["t"] = now
    RELOAD_LOCK_UNTIL["t"] = now + (MAG_RELOAD_SLOW_LOCK_DURATION if slow else MAG_RELOAD_NORMAL_LOCK_DURATION)
    return True, f"เปลี่ยนแม็กแล้ว {P['ammo']}/{mag} | สำรอง {P['reserve_ammo']}", P["ammo"], P["reserve_ammo"], duration

# ==========================================
# [ 2a4. Bullet Wounds (ถูกยิงสวนกลับ -> ต้องคีบออก) ]
# ==========================================
BULLETS = {}  # id -> {"target_start": int, "target_width": int, "dmg_per_tick": int, "start_time": float}
BULLET_EXTRACT_WINDOW = 6  # วินาทีต่อการคีบ 1 นัด ก่อนต้องเริ่มจับจังหวะใหม่

def maybe_take_return_fire():
    """เรียกทุกครั้งที่ผู้เล่นยิง — มีโอกาสโดนยิงสวนกลับ ฝังกระสุนที่ต้องคีบออก"""
    if random.random() < 0.15:
        bid = uuid.uuid4().hex[:6]
        BULLETS[bid] = {
            "target_start": random.randint(15, 75),
            "target_width": 10,
            "dmg_per_tick": 3,
            "start_time": time.time(),
        }
        P["hp"] = max(1, P["hp"] - 8)  # ดาเมจทันทีตอนโดนยิง
        return bid
    return None

def bullet_tick():
    """เรียกทุก 1 วิ — กระสุนที่ยังฝังอยู่ทำเลือดไหลต่อเนื่อง"""
    if BULLETS:
        total_dmg = sum(b["dmg_per_tick"] for b in BULLETS.values())
        P["hp"] = max(1, P["hp"] - total_dmg)

def extract_bullet(bid, value):
    b = BULLETS.get(bid)
    if not b:
        return False, "ไม่พบกระสุนนัดนี้"
    ok = b["target_start"] <= value <= b["target_start"] + b["target_width"]
    if ok:
        BULLETS.pop(bid)
    return ok, ("คีบออกสำเร็จ" if ok else "พลาด ลองใหม่")

# ==========================================
# [ 2a5. Random Starting Disease + Saline Treatment ]
# ==========================================
DISEASES = {
    "none": {"name": "ปกติดี", "desc": "ไม่มีอาการผิดปกติ"},
    "fever": {"name": "ไข้ป่า", "desc": "เลือดไหลช้าๆ ตลอดเวลาจนกว่าจะรักษา", "hp_drain": 1},
    "tremor": {"name": "มือสั่น", "desc": "โอกาสยิงพลาดสูงขึ้น", "hit_penalty": 0.25},
    "fatigue": {"name": "อ่อนเพลีย", "desc": "อาวุธกินพลังงานแบตเพิ่มขึ้น", "energy_mult": 1.6},
}

def roll_disease():
    """เรียกตอนเริ่มเกม — 40% เจ็บป่วยแบบสุ่ม 1 โรค, 60% ปกติดี"""
    if random.random() < 0.4:
        return random.choice(["fever", "tremor", "fatigue"])
    return "none"

P_DISEASE = {"id": roll_disease()}

SALINE = {"active": False, "level": 0, "target_min": 0, "target_max": 0, "confirmed_at": 0}
NEEDLE_MIN_WAIT = 2.0  # ต้องรอใจเย็นๆ อย่างน้อยเท่านี้ก่อนถอดเข็มได้

def start_saline():
    if P_DISEASE["id"] == "none":
        return False, "ตอนนี้ไม่ได้ป่วยอะไร ไม่ต้องรักษา"
    lo = random.randint(40, 60)
    SALINE.update({"active": True, "level": 0, "target_min": lo, "target_max": lo + 20, "confirmed_at": 0})
    return True, "เริ่มรักษาแล้ว ตัวละครขยับ/ยิงไม่ได้จนกว่าจะรักษาเสร็จ"

def add_saline():
    if not SALINE["active"]:
        return False, "ยังไม่ได้เริ่มรักษา"
    SALINE["level"] = min(100, SALINE["level"] + 6)
    return True, SALINE["level"]

def confirm_saline():
    if not SALINE["active"]:
        return False, "ยังไม่ได้เริ่มรักษา"
    ok = SALINE["target_min"] <= SALINE["level"] <= SALINE["target_max"]
    if ok:
        SALINE["confirmed_at"] = time.time()
    return ok, ("พอดีแล้ว เตรียมถอดเข็มได้" if ok else "ยังไม่พอดี เติมหรือรอดูเครื่องวัดอีกที")

def remove_needle():
    if not SALINE["active"] or not SALINE["confirmed_at"]:
        return False, "ต้องเติมน้ำเกลือให้พอดีและกดยืนยันก่อน"
    waited = time.time() - SALINE["confirmed_at"]
    if waited < NEEDLE_MIN_WAIT:
        return False, f"ใจเย็นๆ ก่อน รออีก {NEEDLE_MIN_WAIT - waited:.1f} วิ"
    P_DISEASE["id"] = "none"
    SALINE.update({"active": False, "level": 0, "confirmed_at": 0})
    return True, "ถอดเข็มสำเร็จ รักษาหายแล้ว!"

# ==========================================
# [ 2b. Anti-Cheat: Fire-Rate Anomaly Check ]
# ตรวจที่ฝั่งเซิร์ฟเวอร์เท่านั้น จากเวลาที่ยิงจริงของผู้เล่นคนนี้
# ไม่ต้องอ่านหน้าจอหรือเครื่องของใครทั้งสิ้น
# ==========================================
FIRE_LOG = deque(maxlen=50)          # เก็บ timestamp การยิงล่าสุด
MIN_FIRE_INTERVAL = {"plasma": 0.15, "railgun": 0.35}  # วินาที ต่อนัด ตามอาวุธ
FLAGGED = {"count": 0, "reason": ""}

def check_fire_rate(weap_id):
    """คืนค่า True ถ้าจังหวะยิงปกติ, False ถ้าเร็วผิดปกติ (ต้องสงสัยว่าใช้โปรแกรมช่วยยิงอัตโนมัติ)"""
    now = time.time()
    min_gap = MIN_FIRE_INTERVAL.get(weap_id, 0.15)
    if FIRE_LOG and (now - FIRE_LOG[-1]) < (min_gap * 0.6):  # เร็วกว่าขั้นต่ำเกิน 40%
        FLAGGED["count"] += 1
        FLAGGED["reason"] = f"fire interval {now - FIRE_LOG[-1]:.3f}s < allowed {min_gap:.3f}s"
        return False
    FIRE_LOG.append(now)
    return True

# ==========================================
# [ 2c. Feature Request Queue ]
# พิมพ์บรรยายเป็นภาษาไทย -> AI แปลงเป็นโค้ด -> เก็บไว้ให้ตรวจก่อน -> กดยืนยันค่อย merge
# (ไม่รันโค้ดที่ AI สร้างมาโดยอัตโนมัติ ต้องกดยืนยันจากในนี้เท่านั้น)
# ==========================================
os.makedirs("pending_features", exist_ok=True)
PENDING_INDEX_PATH = "pending_features/index.json"

def _load_pending():
    if os.path.exists(PENDING_INDEX_PATH):
        with open(PENDING_INDEX_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    return {}

def _save_pending(idx):
    with open(PENDING_INDEX_PATH, "w", encoding="utf-8") as f:
        json.dump(idx, f, ensure_ascii=False, indent=2)

# --- Multi-language target config ------------------------------------------
# "wiring" tells the approve step what auto-connect is actually possible:
#   "exec"        -> real: code runs inside THIS running Flask process (Python only)
#   "unity_dropin"-> real: file lands inside your Unity project's Assets folder,
#                    Unity's own editor/compiler picks it up & recompiles automatically
#                    (this is Unity doing the work, not this script — requires the
#                    Unity Editor to be open and UNITY_PROJECT_PATH set)
#   "manual"      -> honest default for anything else: no generic live auto-wiring
#                    exists across arbitrary languages/runtimes, so the file is
#                    saved for you to drop into your own project yourself
KNOWN_LANGUAGES = {
    "python":     {"ext": "py",  "label": "Python (เกมนี้)",
                   "prompt_lang": "Python สำหรับเกม Flask ชื่อ VMAX เขียนเฉพาะฟังก์ชัน/route ที่เกี่ยวข้อง",
                   "wiring": "exec"},
    # "csharp" = auto-detect: อ่าน UNITY_PROJECT_PATH แล้วเดาว่าเป็นโปรเจกต์ Unity
    # หรือ .NET ธรรมดา จากไฟล์/โฟลเดอร์จริงที่พบ (ดู _detect_csharp_project_kind
    # ด้านล่าง) — ก่อนหน้านี้ "csharp" ถูก map ไป wiring="unity_dropin" ตรงๆ เหมือน
    # "unity" ทุกอย่าง เลยพังเวลาโปรเจกต์จริงเป็น .NET ธรรมดา (ไม่มี Assets/
    # ProjectSettings) เพราะมันพยายามเขียนไฟล์ลง Assets/Scripts/Generated ที่ไม่มีอยู่จริง
    "csharp":     {"ext": "cs",  "label": "C# (auto-detect: Unity หรือ .NET ธรรมดา)",
                   "prompt_lang": ("C# — เขียนโค้ดที่ไม่ผูกกับ UnityEngine โดยตรงถ้าเป็นไปได้ "
                                   "(เผื่อโปรเจกต์เป้าหมายเป็น .NET ธรรมดา ไม่ใช่ Unity) "
                                   "แต่ถ้าฟีเจอร์ต้องพึ่ง MonoBehaviour/Unity API จริงๆ ก็เขียนแบบนั้นได้"),
                   "wiring": "csharp_auto"},
    # "unity" = บังคับ Unity ตรงๆ ไม่ต้องเดา ใช้ตอนผู้ใช้มั่นใจอยู่แล้วว่าเป็น Unity
    "unity":      {"ext": "cs",  "label": "C# (Unity เท่านั้น — บังคับ)",
                   "prompt_lang": "C# สำหรับ Unity 6 เขียนเป็น MonoBehaviour หรือคลาสที่เกี่ยวข้องเท่านั้น",
                   "wiring": "unity_dropin"},
    "javascript": {"ext": "js",  "label": "JavaScript",
                   "prompt_lang": "JavaScript สำหรับฟีเจอร์นี้",
                   "wiring": "manual"},
    "cpp":        {"ext": "cpp", "label": "C++",
                   "prompt_lang": "C++ สำหรับฟีเจอร์นี้",
                   "wiring": "manual"},
    "java":       {"ext": "java","label": "Java",
                   "prompt_lang": "Java สำหรับฟีเจอร์นี้",
                   "wiring": "manual"},
}

def _lang_config(target: str) -> dict:
    key = (target or "python").strip().lower()
    if key in KNOWN_LANGUAGES:
        return {"key": key, **KNOWN_LANGUAGES[key]}
    # Unknown/unlisted language name typed by the user — still supported generically,
    # just with no known live auto-wiring mechanism (honest "manual" default).
    return {"key": key, "ext": "txt", "label": key,
            "prompt_lang": f"{key} สำหรับฟีเจอร์นี้", "wiring": "manual"}


def _detect_csharp_project_kind(path: str) -> str:
    """เดาว่า path ที่ตั้งไว้ใน UNITY_PROJECT_PATH เป็นโปรเจกต์ Unity หรือ
    .NET ธรรมดา โดยดูจากไฟล์/โฟลเดอร์ที่มีอยู่จริง ไม่ได้เดาจากชื่อภาษา
    ที่ผู้ใช้เลือกในหน้าเว็บ (นั่นคือจุดที่พังมาก่อนหน้านี้ — "csharp" ถูกสมมติ
    ว่าเป็น Unity เสมอ) คืนค่า "unity" | "dotnet" | "unknown" | "missing"."""
    if not path or not os.path.isdir(path):
        return "missing"
    has_assets = os.path.isdir(os.path.join(path, "Assets"))
    has_project_settings = os.path.isdir(os.path.join(path, "ProjectSettings"))
    if has_assets and has_project_settings:
        return "unity"
    try:
        entries = os.listdir(path)
    except OSError:
        entries = []
    if any(e.lower().endswith((".csproj", ".sln")) for e in entries):
        return "dotnet"
    return "unknown"


def _existing_codebase_symbols() -> dict:
    """อ่านไฟล์ตัวเองด้วย ast (ไม่ใช่ regex) แล้วเก็บว่ามีอะไรอยู่แล้วบ้าง:
    - ชื่อฟังก์ชัน/คลาส/ตัวแปร global ระดับบนสุดทั้งหมด (เช่น WALLET, GENRE_PROFILES,
      LAUNCHER_CATALOG, VMAX_MODULES, P, W, BAT, ...)
    - path ของทุก route ที่ลงทะเบียนไว้แล้ว (จาก app.url_map ตรงๆ ไม่ต้องเดา)
    ใช้แก้ปัญหาที่ AI เขียนโค้ดฟีเจอร์ใหม่แบบไม่รู้จักบริบทของไฟล์นี้เลย เพราะก่อนหน้านี้
    ส่งไปแค่ประโยคบรรยายสั้นๆ อย่างเดียว ไม่มีข้อมูลว่าไฟล์นี้มีอะไรอยู่แล้ว
    """
    names = set()
    try:
        with open(__file__, "r", encoding="utf-8") as f:
            tree = ast.parse(f.read(), filename=__file__)
        for node in tree.body:  # เฉพาะระดับบนสุดของไฟล์ ไม่ลงไปใน function body
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                names.add(node.name)
            elif isinstance(node, ast.Assign):
                for t in node.targets:
                    if isinstance(t, ast.Name):
                        names.add(t.id)
            elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                names.add(node.target.id)
    except Exception as e:
        # อ่านไฟล์ตัวเองไม่ได้ (เช่น รันจาก path แปลกๆ) — ไม่ให้ทั้งฟีเจอร์พังเพราะเรื่องนี้
        print(f"[propose_feature] เก็บ context จากไฟล์ตัวเองไม่ได้: {e}")

    routes = set()
    try:
        routes = {rule.rule for rule in app.url_map.iter_rules()}
    except Exception:
        pass

    return {"names": names, "routes": routes}


def _format_codebase_context_for_prompt(symbols: dict, max_names: int = 120) -> str:
    names = sorted(symbols["names"])
    routes = sorted(symbols["routes"])
    names_shown = names[:max_names]
    more = f" (และอีก {len(names) - max_names} ชื่อ)" if len(names) > max_names else ""
    return (
        "ไฟล์นี้มีตัวแปร/ฟังก์ชัน/คลาสระดับบนสุดที่ชื่อเหล่านี้อยู่แล้ว "
        "ห้ามประกาศชื่อซ้ำ (ถ้าต้องใช้ของเดิม เช่น WALLET, GENRE_PROFILES, LAUNCHER_CATALOG, "
        "VMAX_MODULES ให้เรียกใช้ตรงๆ ไม่ต้องประกาศใหม่):\n"
        + ", ".join(names_shown) + more + "\n\n"
        "route ที่มีอยู่แล้ว (ห้ามใช้ path ซ้ำกับพวกนี้ ถ้าจะเพิ่ม route ใหม่ให้ตั้ง path ที่ไม่ชนกัน):\n"
        + ", ".join(routes)
    )


def _relevant_code_excerpts(thai_description: str, max_chars: int = None) -> tuple:
    """ดึง 'โค้ดจริง' (ไม่ใช่แค่รายชื่อ) จากไฟล์นี้มาใส่ในพรอมต์ — เลือกเฉพาะ
    บล็อกระดับบนสุด (ฟังก์ชัน/คลาส/global dict) ที่น่าจะเกี่ยวข้องกับคำบรรยายก่อน
    แล้วเติมบล็อกอื่นๆ ตามลำดับเดิมของไฟล์จนกว่าจะเต็มงบตัวอักษรที่กำหนด

    งบตัวอักษรมีไว้เพราะโมเดล local (เช่น Ollama 8B ตัวเล็กๆ) มี context window
    จำกัด — ส่งทั้งไฟล์ (7000+ บรรทัด / ~400KB) เข้าไปตรงๆ มีโอกาสสูงที่จะเกิน
    context แล้วโดนตัดท้ายหายไปแบบไม่มีใครรู้ ปรับงบได้ด้วย env var:
        export LOCAL_AI_MAX_CONTEXT_CHARS=60000   (ตัวเลขใหญ่ = ส่งไปเยอะขึ้น
                                                     แต่ต้องมั่นใจว่าโมเดล/เซิร์ฟเวอร์
                                                     ที่ LOCAL_AI_URL ชี้ไปรองรับ
                                                     context ยาวขนาดนั้นจริง)
    ค่านี้ควรปรับคู่กับ LOCAL_AI_NUM_CTX (ดู _local_ai_num_ctx ด้านล่าง) — ถ้าเพิ่ม
    ตัวนี้แต่ไม่เพิ่ม LOCAL_AI_NUM_CTX ด้วย (สำหรับ Ollama) พรอมต์ที่ยาวขึ้นจะโดน
    Ollama ตัดทิ้งอยู่ดี ไม่มีประโยชน์ที่จะเพิ่มแค่ตัวเดียว
    ค่า default (24000 ตัวอักษร ≈ 6000 token) ตั้งให้เหลือที่พอสำหรับ system
    prompt ส่วนอื่น + คำตอบ ภายใต้ default ของ LOCAL_AI_NUM_CTX (8192 token)
    คืนค่า (excerpt_text, total_blocks, blocks_included, total_chars_in_file)
    """
    if max_chars is None:
        max_chars = int(os.environ.get("LOCAL_AI_MAX_CONTEXT_CHARS", "24000"))

    try:
        with open(__file__, "r", encoding="utf-8") as f:
            source = f.read()
        tree = ast.parse(source, filename=__file__)
    except Exception as e:
        return (f"# (อ่านไฟล์ตัวเองเพื่อดึงโค้ดจริงไม่ได้: {e})", 0, 0, 0)

    blocks = []  # [(name, source_text), ...] ตามลำดับในไฟล์
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Assign, ast.AnnAssign)):
            seg = ast.get_source_segment(source, node)
            if not seg:
                continue
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                name = node.name
            elif isinstance(node, ast.Assign) and node.targets and isinstance(node.targets[0], ast.Name):
                name = node.targets[0].id
            elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                name = node.target.id
            else:
                name = "?"
            blocks.append((name, seg))

    # ให้คะแนนแต่ละบล็อก: นับว่ามีคำจากคำบรรยาย (ตัดด้วยช่องว่าง) โผล่ในชื่อ/เนื้อบล็อก
    # กี่คำ — บล็อกที่เกี่ยวข้องกับสิ่งที่ผู้ใช้พิมพ์มากกว่าจะถูกใส่ก่อน
    desc_tokens = [t for t in thai_description.replace(",", " ").split() if len(t) >= 2]

    def score(name, text):
        hay = (name + " " + text).casefold()
        return sum(1 for t in desc_tokens if t.casefold() in hay)

    scored = sorted(range(len(blocks)), key=lambda i: score(*blocks[i]), reverse=True)

    # global state สำคัญที่มักถูกอ้างถึงบ่อย ให้ติดไปด้วยเสมอไม่ว่าคะแนนจะเป็นเท่าไหร่
    always_include = {"WALLET", "GENRE_PROFILES", "LAUNCHER_CATALOG", "VMAX_MODULES"}
    priority_idx = [i for i in scored if blocks[i][0] in always_include]
    rest_idx = [i for i in scored if blocks[i][0] not in always_include]
    order = priority_idx + rest_idx

    included, used_chars, included_count = [], 0, 0
    for i in order:
        name, text = blocks[i]
        if used_chars + len(text) > max_chars and included_count > 0:
            continue  # ข้ามบล็อกนี้ไปก่อน ลองบล็อกถัดไปที่อาจจะสั้นกว่าและยังพอมีที่
        if used_chars + len(text) > max_chars:
            break  # แม้แต่บล็อกแรกก็ยังใหญ่กว่างบทั้งหมด — ตัดตรงนี้เลย
        included.append(f"# --- {name} ---\n{text}")
        used_chars += len(text)
        included_count += 1

    excerpt_text = "\n\n".join(included) if included else "(ไม่มีโค้ดที่ดึงมาได้พอดีกับงบที่ตั้งไว้)"
    return (excerpt_text, len(blocks), included_count, len(source))



    warnings = []
    try:
        tree = ast.parse(code, filename="<generated_feature>")
    except SyntaxError as e:
        return [f"SYNTAX ERROR: โค้ดที่ AI สร้างมาไม่ใช่ Python ที่ถูกต้อง — บรรทัด {e.lineno}: {e.msg}"]

    new_names = set()
    new_routes = set()
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and node in tree.body:
            new_names.add(node.name)
        if isinstance(node, ast.Assign):
            for t in node.targets:
                if isinstance(t, ast.Name):
                    new_names.add(t.id)
        # หา @app.route("...") หรือ @app.route('...') เพื่อเช็ค path ชนกัน
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "route":
            if node.args and isinstance(node.args[0], ast.Constant) and isinstance(node.args[0].value, str):
                new_routes.add(node.args[0].value)

    collided_names = new_names & existing_symbols["names"]
    collided_routes = new_routes & existing_symbols["routes"]
    if collided_names:
        warnings.append("ชื่อชนกับของเดิมในไฟล์: " + ", ".join(sorted(collided_names)))
    if collided_routes:
        warnings.append("route path ชนกับของเดิม: " + ", ".join(sorted(collided_routes)))
    return warnings


def _local_ai_num_ctx() -> int:
    """ขนาด context window (หน่วยเป็น token) ที่จะขอจาก Ollama ต่อ request หนึ่งครั้ง
    ค่า default ของ Ollama เอง (2048) เตี้ยกว่าที่โมเดลส่วนใหญ่รองรับได้จริงมาก —
    ต่อให้เราสร้างพรอมต์ยาวแค่ไหน (เช่นจาก _relevant_code_excerpts) ถ้าไม่ส่ง
    num_ctx ไปด้วย Ollama จะตัดพรอมต์ทิ้งเงียบๆ จนเหลือแค่ 2048 token อยู่ดี
    ปรับได้ด้วย:
        export LOCAL_AI_NUM_CTX=16384
    ต้องดูด้วยว่าโมเดลที่โหลดไว้ใน Ollama รองรับ context ยาวขนาดนั้นจริง (เช่น
    llama3 รุ่นมาตรฐานรองรับถึง 8192, บางรุ่น/บาง fine-tune รองรับยาวกว่านั้น)
    และเครื่องมี VRAM/RAM พอ — ตั้งสูงเกินคุณสมบัติเครื่อง Ollama จะช้าลงมากหรือ error

    หมายเหตุ: ค่านี้มีผลเฉพาะฝั่ง Ollama (/api/chat) เท่านั้น ส่วน endpoint แบบ
    OpenAI-compatible (LM Studio/vLLM/...) ไม่มีฟิลด์มาตรฐานให้ตั้ง context ต่อ
    request แบบนี้ — ต้องไปตั้งตอนโหลดโมเดล/รันเซิร์ฟเวอร์นั้นๆ เอง
    """
    try:
        return int(os.environ.get("LOCAL_AI_NUM_CTX", "8192"))
    except ValueError:
        return 8192


def _token_overlap_score(a: str, b: str, n: int = 3) -> float:
    """วัดความคล้ายของคำบรรยาย 2 อันด้วย character n-gram Jaccard similarity
    (ค่า 0.0-1.0) — ตั้งใจ 'ไม่' ตัดคำด้วยช่องว่าง เพราะภาษาไทยไม่เว้นวรรคระหว่าง
    คำ (ประโยคไทยทั้งประโยคจะกลายเป็น 'คำ' เดียวถ้าตัดด้วยช่องว่าง แล้วจะไม่ตรง
    กันเลยแม้จะบรรยายเรื่องเดียวกัน) ตัด n-gram ระดับตัวอักษรแทนใช้ได้กับทุกภาษา
    โดยไม่ต้องมี tokenizer ภาษาไทยแยกต่างหาก แม่นยำน้อยกว่า embedding/AI จริงๆ
    แต่ไม่ต้องพึ่ง AI ภายนอกเลยเช่นกัน"""
    def ngrams(s):
        s = s.replace(" ", "").replace(",", "")
        return {s[i:i + n] for i in range(max(0, len(s) - n + 1))}
    ga, gb = ngrams(a), ngrams(b)
    if not ga or not gb:
        return 0.0
    inter = len(ga & gb)
    union = len(ga | gb)
    return inter / union if union else 0.0


def _registry_recall(thai_description: str, target_key: str, threshold: float = None):
    """ค้นหาใน code_registry (ที่ approve_feature() บันทึกทุกฟีเจอร์ที่เคยอนุมัติแล้ว
    เข้าไปอยู่แล้วโดยอัตโนมัติ) ว่ามีฟีเจอร์เก่าที่คำบรรยายคล้ายกับอันนี้ไหม —
    นี่คือส่วน "AI ที่งอกตามงานไปเรื่อยๆ": ทุกครั้งที่กดอนุมัติฟีเจอร์ ระบบจะจำไว้
    เอง ไม่ต้องเทรนอะไร ยิ่งอนุมัติเยอะ ยิ่งมีโอกาสตอบจากความจำแทนที่จะต้องยิงไป
    หา local AI ภายนอกทุกครั้ง (เร็วกว่า, ไม่พึ่ง Ollama, การันตีว่า syntax ถูก
    เพราะเป็นโค้ดที่เคยผ่านการตรวจ/อนุมัติมาแล้วจริง)

    ปรับเกณฑ์ความคล้ายที่ยอมรับได้ด้วย env var:
        export GROWN_AI_MATCH_THRESHOLD=0.6   (ตัวเลขสูงขึ้น = เข้มงวดขึ้น ต้องคล้าย
                                                 กันมากถึงจะดึงของเก่ามาใช้ซ้ำ)
    คืนค่า (record, score) ของอันที่คะแนนสูงสุดถ้าผ่านเกณฑ์ ไม่งั้นคืน (None, 0.0)
    """
    if threshold is None:
        threshold = float(os.environ.get("GROWN_AI_MATCH_THRESHOLD", "0.5"))

    idx = _load_registry()
    best_record, best_score = None, 0.0
    for name, versions in idx.items():
        for rec in versions:
            if rec.get("target") != target_key:
                continue
            score = _token_overlap_score(thai_description, rec.get("description", ""))
            if score > best_score:
                best_record, best_score = rec, score

    if best_record and best_score >= threshold:
        return best_record, best_score
    return None, 0.0


def generate_feature_code(thai_description: str, target: str = "python"):
    # คืนค่า (code, context_meta) เสมอ — context_meta เป็น None ถ้าไม่ใช่ target=python
    # (ภาษาอื่นเป็นไฟล์แยก ไม่แชร์ globals กับไฟล์นี้ เลยไม่มีอะไรให้ "ดูในไฟล์" ด้วย)
    lang = _lang_config(target)

    # --- 1) ลองดึงจากความจำที่ "งอก" ขึ้นมาเองก่อน (ฟีเจอร์เก่าที่เคยอนุมัติแล้ว
    #     และคำบรรยายคล้ายกันพอ) ถ้าเจอ ไม่ต้องยิงไปหา AI ภายนอกเลย ---
    recalled_rec, recalled_score = _registry_recall(thai_description, lang["key"])
    if recalled_rec:
        try:
            with open(recalled_rec["path"], "r", encoding="utf-8") as f:
                recalled_code = f.read()
        except OSError as e:
            recalled_rec = None  # ไฟล์อาจถูกลบไปแล้ว — ตกไปเรียก AI ตามปกติแทน
        if recalled_rec:
            note = (f"# ♻️ นำโค้ดจากฟีเจอร์เก่าที่เคยอนุมัติแล้ว '{recalled_rec['name']}' "
                     f"(v{recalled_rec['version']}) มาใช้ซ้ำ — คำบรรยายคล้ายกัน "
                     f"{round(recalled_score * 100)}% ไม่ได้ยิงไปหา AI ภายนอกรอบนี้\n"
                     f"# คำบรรยายเดิม: {recalled_rec.get('description', '')}\n\n")
            return note + recalled_code, {
                "reused_from_registry": True,
                "reused_name": recalled_rec["name"],
                "reused_version": recalled_rec["version"],
                "similarity": round(recalled_score, 3),
            }

    # --- 2) ไม่เจอของเก่าที่คล้ายพอ — เขียนด้วย "AI ของตัวเอง" ตามปกติ (ไม่ยิงไปหา
    #     Anthropic API) ---
    # รองรับ AI ที่รันในเครื่องคุณเอง หรือ AI ตัวไหนก็ได้ที่เปิด HTTP endpoint
    # แบบ Ollama หรือ OpenAI-compatible (LM Studio, vLLM, Jan, LocalAI, text-generation-webui ฯลฯ)
    #   export LOCAL_AI_URL=http://localhost:11434/api/chat            (Ollama)
    #   export LOCAL_AI_URL=http://localhost:1234/v1/chat/completions  (LM Studio / อื่นๆ ที่ compatible)
    #   export LOCAL_AI_MODEL=llama3   (ชื่อโมเดลที่โหลดไว้ในเครื่องคุณ)
    #
    # `target` เลือกภาษา/แพลตฟอร์มปลายทาง — รับได้ทุกภาษาที่พิมพ์เข้ามา ไม่ได้จำกัดแค่ใน
    # KNOWN_LANGUAGES ด้านบน แต่ภาษาที่ไม่รู้จักจะไม่มี auto-wire ให้ (ดูคอมเมนต์ที่ KNOWN_LANGUAGES)
    #
    # คืนค่า (code, context_meta) — context_meta เป็น None สำหรับภาษาที่ไม่ใช่ python
    # (เพราะภาษาอื่นเป็นไฟล์แยก ไม่ได้แชร์ globals กับไฟล์นี้ เลยไม่มีอะไรให้ "ดูในไฟล์" ด้วย)

    context_meta = None
    SYSTEM_PROMPT = (
        f"คุณคือตัวช่วยเขียนโค้ด {lang['prompt_lang']} "
        "ห้ามเขียนคำอธิบายอื่นนอกจากโค้ดและคอมเมนต์ในโค้ด"
    )
    # เฉพาะ target=python เท่านั้นที่โค้ดจะไปรันร่วมกับ global namespace ของไฟล์นี้จริงๆ
    # (ภาษาอื่นเป็นไฟล์แยกต่างหาก ไม่ได้แชร์ globals กัน) จึงต้องบอก AI ว่าไฟล์นี้มี
    # อะไรอยู่แล้วบ้าง ไม่งั้นมันจะเขียนแบบไม่รู้เรื่อง WALLET/GENRE_PROFILES/LAUNCHER_CATALOG
    # ที่มีอยู่แล้ว แล้วชนกันตอนเอาไปรวมจริง — ให้ทั้งรายชื่อ (กว้าง ครบทุกชื่อ) และ
    # โค้ดจริงบางส่วน (แคบกว่า แต่ลึกกว่า) ประกอบกัน
    if lang["key"] == "python":
        ctx = _existing_codebase_symbols()
        excerpt_text, blocks_total, blocks_included, file_chars = _relevant_code_excerpts(thai_description)
        context_meta = {
            "blocks_total": blocks_total,
            "blocks_included": blocks_included,
            "file_chars": file_chars,
            "excerpt_chars": len(excerpt_text),
        }
        SYSTEM_PROMPT += (
            "\n\nนี่คือบริบทของไฟล์เกมที่โค้ดนี้จะถูกเอาไปต่อท้ายเข้าไปจริง (import ไม่ได้ "
            "เพราะเป็น global namespace เดียวกัน) ให้เขียนโค้ดที่เข้ากับของเดิมได้ ไม่ประกาศชื่อซ้ำ "
            "ไม่สร้าง route path ซ้ำ และเรียกใช้ตัวแปร/ฟังก์ชันเดิมที่มีอยู่แล้วแทนการสร้างใหม่:\n\n"
            + _format_codebase_context_for_prompt(ctx)
            + f"\n\nนี่คือโค้ดจริงบางส่วนจากไฟล์นี้ (เลือกมาเฉพาะส่วนที่น่าจะเกี่ยวข้อง "
              f"{blocks_included}/{blocks_total} บล็อก จากทั้งไฟล์ {file_chars:,} ตัวอักษร "
              f"— ถ้าไม่ครบทุกบล็อกเพราะจำกัดขนาดพรอมต์ไว้ที่ "
              f"{os.environ.get('LOCAL_AI_MAX_CONTEXT_CHARS', '24000')} ตัวอักษร):\n\n"
            + excerpt_text
        )

    USER_PROMPT = f"เขียนโค้ดสำหรับฟีเจอร์นี้ในเกม: {thai_description}"

    local_url   = os.environ.get("LOCAL_AI_URL")
    local_model = os.environ.get("LOCAL_AI_MODEL", "llama3")

    if not local_url:
        return (
            "# ยังไม่ได้ตั้งค่า AI ของตัวเอง\n"
            "# ต้องมีโมเดลรันอยู่ในเครื่อง (หรือ LAN) ก่อน แล้วตั้ง env var นี้:\n"
            "#   export LOCAL_AI_URL=http://localhost:11434/api/chat            (ตัวอย่าง: Ollama)\n"
            "#   export LOCAL_AI_URL=http://localhost:1234/v1/chat/completions  (ตัวอย่าง: LM Studio)\n"
            "#   export LOCAL_AI_MODEL=<ชื่อโมเดลที่โหลดไว้>\n"
            "# ระบบนี้จะไม่ยิงไปหา Anthropic API หรือ AI ภายนอกใดๆ ทั้งสิ้น\n",
            context_meta,
        )

    try:
        if "11434" in local_url or "/api/chat" in local_url:
            # Ollama format — ต้องส่ง num_ctx ไปด้วย ไม่งั้น Ollama ใช้ context เตี้ยๆ
            # default ของมันเอง (2048) ต่อให้พรอมต์เราจากด้านบนยาวแค่ไหนก็ตาม
            resp = requests.post(
                local_url,
                json={"model": local_model, "stream": False,
                      "options": {"num_ctx": _local_ai_num_ctx()},
                      "messages": [{"role": "system", "content": SYSTEM_PROMPT},
                                   {"role": "user",   "content": USER_PROMPT}]},
                timeout=120,
            )
            code = resp.json().get("message", {}).get("content", "# Local AI ไม่ส่งผลลัพธ์กลับมา\n")
        else:
            # OpenAI-compatible format (LM Studio, vLLM, Jan, LocalAI ฯลฯ) — ไม่มีฟิลด์
            # มาตรฐานสำหรับตั้ง context ต่อ request แบบ Ollama ต้องตั้งตอนรันเซิร์ฟเวอร์นั้นเอง
            resp = requests.post(
                local_url,
                json={"model": local_model, "max_tokens": 800,
                      "messages": [{"role": "system", "content": SYSTEM_PROMPT},
                                   {"role": "user",   "content": USER_PROMPT}]},
                timeout=120,
            )
            code = resp.json()["choices"][0]["message"]["content"]
        return code, context_meta
    except Exception as e:
        return (f"# Local AI error: {e}\n# ตรวจสอบว่า LOCAL_AI_URL ถูกต้องและ server กำลังรันอยู่\n",
                context_meta)

# ==========================================
# [ 2d. Hacking Minigame (in-game device puzzle) ]
# กลไกในเกมล้วนๆ: อุปกรณ์ในเกม -> เข้าใกล้แล้วเปิดปริศนา 3 หน้าจอ
# สุ่ม/ตรวจทุกอย่างที่ฝั่งเซิร์ฟเวอร์ กัน client โกงค่า
# ==========================================
HACK_SESSION = {}  # session เดียวสำหรับผู้เล่นนี้ ณ ตอนนี้
HACK_TIME_LIMIT = 20  # วินาที
WIRE_COLORS = ["red", "blue", "green", "yellow"]

def new_hack_session():
    seq = list(range(1, 7))
    shuffled_seq = seq[:]
    random.shuffle(shuffled_seq)

    wires = WIRE_COLORS[:]
    shuffled_wires = wires[:]
    random.shuffle(shuffled_wires)

    target_start = random.randint(20, 70)
    target_width = 12

    HACK_SESSION.clear()
    HACK_SESSION.update({
        "start_time": time.time(),
        "panel1": {"shuffled": shuffled_seq, "correct_order": seq, "solved": False},
        "panel2": {"left": wires, "right_shuffled": shuffled_wires, "solved": False},
        "panel3": {"target_start": target_start, "target_end": target_start + target_width, "solved": False},
    })
    return {
        "panel1_numbers": shuffled_seq,
        "panel2_left": wires,
        "panel2_right": shuffled_wires,
        "panel3_target_start": target_start,
        "panel3_target_width": target_width,
        "time_limit": HACK_TIME_LIMIT,
    }

def hack_time_left():
    if "start_time" not in HACK_SESSION:
        return 0
    return max(0, HACK_TIME_LIMIT - (time.time() - HACK_SESSION["start_time"]))

def submit_panel1(order):
    if hack_time_left() <= 0: return False
    ok = order == HACK_SESSION["panel1"]["correct_order"]
    HACK_SESSION["panel1"]["solved"] = ok
    return ok

def submit_panel2(mapping):
    """mapping: ลำดับสีที่ผู้เล่นจับคู่ ต้องตรงกับ left ตามลำดับเดิม"""
    if hack_time_left() <= 0: return False
    ok = mapping == HACK_SESSION["panel2"]["left"]
    HACK_SESSION["panel2"]["solved"] = ok
    return ok

def submit_panel3(stop_value):
    if hack_time_left() <= 0: return False
    p3 = HACK_SESSION["panel3"]
    ok = p3["target_start"] <= stop_value <= p3["target_end"]
    p3["solved"] = ok
    return ok

def hack_all_solved():
    return all(HACK_SESSION.get(f"panel{i}", {}).get("solved") for i in (1, 2, 3))

# ==========================================
# [ 3. Vision Tracker (camera/hand) ]
# กล้อง/มือ - ใช้สำหรับสแกนและระบบ assist ที่ไม่โกง
# ==========================================
VIS_CODE = """
import cv2, mediapipe as mp, requests, time
h = mp.solutions.hands.Hands(max_num_hands=1, min_detection_confidence=0.7)
c = cv2.VideoCapture(0)
while c.isOpened():
    s, i = c.read()
    if not s: break
    i = cv2.flip(i, 1)
    r = h.process(cv2.cvtColor(i, cv2.COLOR_BGR2RGB))
    if r.multi_hand_landmarks:
        lm = r.multi_hand_landmarks[0].landmark
        if lm[8].y < lm[6].y and lm[12].y > lm[10].y:  # ตรวจจับการชี้นิ้ว
            try:
                requests.post('http://localhost:5000/api/vision_trigger', json={'x': lm[8].x, 'y': lm[8].y})
            except Exception:
                pass
            time.sleep(0.2)  # ดีเลย์
    cv2.imshow('VMAX TACTICAL VISION', i)
    if cv2.waitKey(5) == 27: break
c.release(); cv2.destroyAllWindows()
"""

