CALCULATOR_WIDGET_JS = """
// ==========================================
// ---- เครื่องคิดเลขลอย (ใช้ได้ทั้งหน้าเว็บไซต์/ล็อกอิน และในเกม — และดึงไปฝังเกมอื่นได้ด้วย) ----
// ตั้งใจให้ทำงานอิสระจากสถานะล็อกอิน/เกม ไม่ต้องรอ boot()/startGame() —
// เปิดใช้ได้ทันทีตั้งแต่หน้าแรกที่โหลดเว็บ ไม่ต้องออกจากแอปไปคำนวณที่อื่น
// ==========================================
let calcState = { display: '0', prevValue: null, operator: null, waitingForOperand: false };

function toggleCalculator() {
    let panel = document.getElementById('calc_panel');
    if (!panel) return;
    panel.style.display = (panel.style.display === 'none' || !panel.style.display) ? 'block' : 'none';
}

function calcRender() {
    let disp = document.getElementById('calc_display');
    if (disp) disp.innerText = calcState.display;
}

function calcInputDigit(d) {
    if (calcState.waitingForOperand) {
        calcState.display = d;
        calcState.waitingForOperand = false;
    } else {
        calcState.display = (calcState.display === '0') ? d : calcState.display + d;
    }
    calcRender();
}

function calcInputDot() {
    if (calcState.waitingForOperand) {
        calcState.display = '0.';
        calcState.waitingForOperand = false;
    } else if (!calcState.display.includes('.')) {
        calcState.display += '.';
    }
    calcRender();
}

function calcClear() {
    calcState = { display: '0', prevValue: null, operator: null, waitingForOperand: false };
    calcRender();
}

function calcBackspace() {
    if (calcState.waitingForOperand) return;
    calcState.display = calcState.display.length > 1 ? calcState.display.slice(0, -1) : '0';
    calcRender();
}

function calcToggleSign() {
    calcState.display = String(parseFloat(calcState.display) * -1);
    calcRender();
}

function calcPercent() {
    calcState.display = String(parseFloat(calcState.display) / 100);
    calcRender();
}

function _calcCompute(a, b, op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '×': return a * b;
        case '÷': return b === 0 ? NaN : a / b;
        default: return b;
    }
}

function calcInputOperator(nextOp) {
    let inputValue = parseFloat(calcState.display);
    if (calcState.prevValue === null) {
        calcState.prevValue = inputValue;
    } else if (calcState.operator && !calcState.waitingForOperand) {
        calcState.prevValue = _calcCompute(calcState.prevValue, inputValue, calcState.operator);
        calcState.display = String(calcState.prevValue);
    }
    calcState.waitingForOperand = true;
    calcState.operator = nextOp;
    calcRender();
}

function calcEquals() {
    let inputValue = parseFloat(calcState.display);
    if (calcState.operator !== null && calcState.prevValue !== null) {
        calcState.display = String(_calcCompute(calcState.prevValue, inputValue, calcState.operator));
        calcState.prevValue = null;
        calcState.operator = null;
        calcState.waitingForOperand = true;
    }
    calcRender();
}
"""

