@app.route('/api/town/state')
def api_town_state():
    return jsonify({
        "buildings": TOWN_BUILDINGS,
        "quests": TOWN_QUESTS,
        "credits": P.get("credits", 0) # ดึงเงินจากตัวแปรกลางของเกม
    })

@app.route('/api/town/upgrade', methods=['POST'])
@require_auth_toggleable
def api_town_upgrade():
    data = request.get_json(force=True, silent=True) or {}
    building_id = data.get("building_id")
    b = TOWN_BUILDINGS.get(building_id)
    if not b:
        return jsonify({"st": "error", "msg": "ไม่พบอาคารนี้"}), 404
    
    cost = b["upgrade_cost"]
    if P["credits"] < cost:
        return jsonify({"st": "error", "msg": "เครดิตไม่พอ"})
    
    # หักเงินและอัปเกรด
    P["credits"] -= cost
    WALLET["balance"] = P["credits"] # ซิงค์กระเป๋าเงินด้วย
    b["level"] += 1
    b["upgrade_cost"] = int(cost * 1.5)
    
    return jsonify({"st": "ok", "msg": f"อัปเกรด {b['name']} เป็น Lv.{b['level']}", "credits": P["credits"]})


