_OFFICIAL_SITE_JS = r"""
<script>
(function(){
  document.querySelectorAll('.aosite-hero').forEach(function(hero){
    var slides = hero.querySelectorAll('.aosite-hero-slide');
    var dots = hero.querySelectorAll('.aosite-hero-dots span');
    var prevBtn = hero.querySelector('.aosite-hero-arrow.prev');
    var nextBtn = hero.querySelector('.aosite-hero-arrow.next');
    var n = slides.length;
    var i = 0;
    var timer = null;

    function show(idx){
      i = (idx + n) % n;
      slides.forEach(function(s,k){ s.classList.toggle('active', k===i); });
      dots.forEach(function(d,k){ d.classList.toggle('active', k===i); });
    }
    function next(){ show(i+1); }
    function prev(){ show(i-1); }
    function resetTimer(){
      if (timer) clearInterval(timer);
      if (n > 1) timer = setInterval(next, 5000);
    }

    dots.forEach(function(d,idx){ d.addEventListener('click', function(){ show(idx); resetTimer(); }); });
    if (nextBtn) nextBtn.addEventListener('click', function(){ next(); resetTimer(); });
    if (prevBtn) prevBtn.addEventListener('click', function(){ prev(); resetTimer(); });

    // ท่าปัดนิ้ว (touch swipe) — ปัดซ้าย = สไลด์ถัดไป, ปัดขวา = สไลด์ก่อนหน้า
    var touchStartX = null;
    hero.addEventListener('touchstart', function(e){
      touchStartX = e.changedTouches[0].clientX;
    }, {passive: true});
    hero.addEventListener('touchend', function(e){
      if (touchStartX === null) return;
      var dx = e.changedTouches[0].clientX - touchStartX;
      var THRESHOLD = 40;
      if (dx <= -THRESHOLD) { next(); resetTimer(); }
      else if (dx >= THRESHOLD) { prev(); resetTimer(); }
      touchStartX = null;
    }, {passive: true});

    // รองรับลากด้วยเมาส์บนเดสก์ท็อปด้วย (drag ค้างแล้วปล่อย = เหมือนปัด)
    var mouseDownX = null;
    hero.addEventListener('mousedown', function(e){ mouseDownX = e.clientX; });
    hero.addEventListener('mouseup', function(e){
      if (mouseDownX === null) return;
      var dx = e.clientX - mouseDownX;
      var THRESHOLD = 40;
      if (dx <= -THRESHOLD) { next(); resetTimer(); }
      else if (dx >= THRESHOLD) { prev(); resetTimer(); }
      mouseDownX = null;
    });

    resetTimer();
  });
})();
</script>
"""


def _aosite_nav_html(current_slug):
    """สร้างเมนู 'Our Games' ที่ลิงก์ไปเว็บเกมอื่น ๆ ทั้งหมดใน GAME_SITES"""
    items = []
    for slug, data in GAME_SITES.items():
        cls = "current" if slug == current_slug else ""
        items.append(f'<a class="{cls}" href="/site/{slug}">{data["name"]}</a>')
    items.append('<a href="/sites">All Official Sites</a>')
    return "".join(items)


def render_game_site(slug):
    game = GAME_SITES[slug]
    name = game["name"]

    # --- hero carousel slides ---
    hero_slides = []
    hero_dots = []
    for idx, h in enumerate(game.get("hero_images", [])):
        active = "active" if idx == 0 else ""
        hero_slides.append(
            f'<div class="aosite-hero-slide {active}" style="background:{h.get("gradient","#111")};">'
            f'<div class="label">{h.get("label","")}</div></div>'
        )
        hero_dots.append(f'<span class="{active}"></span>')
    hero_arrows = ""
    if len(game.get("hero_images", [])) > 1:
        hero_arrows = (
            '<button class="aosite-hero-arrow prev" aria-label="Previous slide">\u2039</button>'
            '<button class="aosite-hero-arrow next" aria-label="Next slide">\u203a</button>'
        )
    hero_html = (
        '<div class="aosite-hero">' + "".join(hero_slides) + hero_arrows +
        '<div class="aosite-hero-dots">' + "".join(hero_dots) + '</div></div>'
    )

    # --- characters section (one featured card, matches the reference screenshot) ---
    char_html = ""
    if game.get("characters"):
        c = game["characters"][0]
        char_html = f'''
        <div class="aosite-section">
          <h2>Characters</h2><div class="rule"></div>
          <div class="aosite-char">
            <div class="org">{c.get("org","")}</div>
            <div class="role">{c.get("role","")}</div>
            <button class="btn">\u2726 View Details \u2726</button>
          </div>
        </div>'''

    # --- media section ---
    media = game.get("media", [])
    media_hero = media[0] if media else None
    media_rest = media[1:] if media else []
    media_hero_html = ""
    if media_hero:
        media_hero_html = (
            f'<div class="aosite-media-hero" style="background:{media_hero.get("gradient","#111")};">'
            f'<div class="cap">{media_hero.get("title","")}</div></div>'
        )
    media_cards = []
    for m in media_rest:
        badge = f'<div class="aosite-media-badge">{m["badge"]}</div>' if m.get("badge") else ""
        media_cards.append(
            f'<div class="aosite-media-card">'
            f'<div class="aosite-media-thumb" style="background:{m.get("gradient","#111")};">{badge}</div>'
            f'<div class="cap">{m.get("title","")}</div></div>'
        )
    media_html = f'''
    <div class="aosite-section">
      <h2>Media</h2><div class="rule"></div>
      {media_hero_html}
      <div class="aosite-media-grid">{"".join(media_cards)}</div>
    </div>''' if media else ""

    # --- news section ---
    news_cards = []
    for n in game.get("news", []):
        news_cards.append(f'''
        <div class="aosite-news-card">
          <div class="aosite-news-top" style="background:{n.get("gradient","#111")};">
            <span class="aosite-news-badge-a">FEATURED</span>
            <span class="aosite-news-badge-b">{n.get("badge","Notice")}</span>
          </div>
          <div class="aosite-news-body">
            <div class="t">{n.get("title","")}</div>
            <div class="d">{n.get("date","")}</div>
          </div>
        </div>''')
    news_html = f'''
    <div class="aosite-section">
      <h2>News</h2><div class="rule"></div>
      {"".join(news_cards)}
    </div>''' if game.get("news") else ""

    tagline = (
        f'{game.get("tagline_prefix","")} '
        f'<span style="color:#9fd0ff;">{game.get("tagline_highlight","")}</span> '
        f'{game.get("tagline_suffix","")}'
    )

    return f'''<!DOCTYPE html>
<html lang="th">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{name} Official Website</title>
{_OFFICIAL_SITE_CSS}
</head>
<body class="aosite">
  <nav class="aosite-nav">
    <div class="aosite-logo">{game.get("logo_mark", name[:2].upper())}</div>
    <div class="aosite-gamesmenu">
      <button class="aosite-gamesmenu-btn">\u2630 Our Games</button>
      <div class="aosite-gamesmenu-list">{_aosite_nav_html(slug)}</div>
    </div>
  </nav>

  {hero_html}

  <div class="aosite-titleblock">
    <h1>{name}</h1>
    <div class="rule"></div>
    <div style="font-size:18px;color:#c8c4b6;">{tagline}</div>
  </div>

  {char_html}
  {media_html}
  {news_html}

  <div class="aosite-footer">\u00a9 {name} — Official Website</div>
  {_OFFICIAL_SITE_JS}
</body>
</html>'''


