# ==========================================
# [ 6u. Keyboard Widget — ฝั่งเซิร์ฟเวอร์ (ธีม/ขนาด/ภาษา/gif ต่อผู้เล่น + คลังอิโมจิ-
# สติกเกอร์ข้ามเกม) ]
# แนวคิดคลังข้ามเกม: เกม A push อิโมจิ/gif ของตัวเองเข้ามาที่ /api/keyboard/share-asset
# พร้อมระบุ source เป็นชื่อเกม A แล้วเกม B (ที่ฝัง widget เดียวกันนี้ แต่ตั้ง
# VMAX_KEYBOARD_SOURCE เป็นชื่อเกม B) ดึงรายการทั้งหมดจาก /api/keyboard/shared-assets
# มาแสดงในแป้นพิมพ์ของตัวเองได้ทันที — ของที่แชร์ถูกเก็บไว้ที่เซิร์ฟเวอร์กลางนี้
# (ไม่ใช่การโอนไฟล์ข้ามเครื่องของผู้เล่นแต่ละคน) ผู้เล่นที่ต่อกับ launcher เดียวกัน
# ทุกคนจึงเห็นชุดอิโมจิ/gif เดียวกันหมด ไม่ว่าจะมาแชร์จากเกมไหนก็ตาม
# ==========================================
KEYBOARD_ASSET_TTL_SEC = 6 * 3600  # ของที่แชร์ไว้ไม่มีคนอัปเดตซ้ำเกินเวลานี้ถือว่าเก่า/เกมนั้นเลิกใช้แล้ว ไม่โชว์ต่อ

KEYBOARD_CUSTOM_THEMES = {}    # theme_id -> {id, name, colors: {bg, fg, border}}
KEYBOARD_GIF_BACKGROUNDS = {}  # gif_id -> {id, url, label}
KEYBOARD_PLAYER_PREFS = {}    # uid -> {lang, size, theme, gif}
KEYBOARD_SHARED_ASSETS = {}   # "source:value" -> {source, asset_type, value, label, ts}


def _kb_prune_shared_assets():
    now = time.time()
    stale = [k for k, a in list(KEYBOARD_SHARED_ASSETS.items()) if now - a["ts"] > KEYBOARD_ASSET_TTL_SEC]
    for k in stale:
        KEYBOARD_SHARED_ASSETS.pop(k, None)


# --- [SECURITY-FIX K1] helper ตรวจ/ทำความสะอาด input ของแป้นพิมพ์ + ผูก uid กับ JWT ---
import re as _kb_re
_KB_ID_RE = _kb_re.compile(r"^[A-Za-z0-9_\-]{1,40}$")
_KB_SOURCE_RE = _kb_re.compile(r"^[A-Za-z0-9_.\- ]{1,40}$")
_KB_COLOR_RE = _kb_re.compile(r"^(#[0-9a-fA-F]{3,8}|[A-Za-z]{3,20}|rgba?\([0-9., %]{5,40}\))$")
_KB_URL_RE = _kb_re.compile(r"^https://[^\s'\"()<>\\]{4,480}$")
_KB_EMOJI_BAD = _kb_re.compile(r"[<>\"'`\\]")
KEYBOARD_MAX_THEMES = 200
KEYBOARD_MAX_GIFS = 200
KEYBOARD_MAX_PREFS = 100000
KEYBOARD_MAX_SHARED = 500
_KB_LOCK = threading.Lock()


def _kb_safe_url(v):
    v = (v or "").strip() if isinstance(v, str) else ""
    return v if _KB_URL_RE.match(v) else None


def _kb_bounded_put(store: dict, key, value, cap: int):
    """ใส่ค่าใน dict โดยไม่ให้ขนาดเกิน cap (ตัดของเก่าสุดออก กัน memory โตไม่จำกัด)"""
    with _KB_LOCK:
        store.pop(key, None)
        store[key] = value
        while len(store) > cap:
            store.pop(next(iter(store)), None)


def _kb_bound_uid(claimed_uid):
    """คืน (uid, error_response). เชื่อ JWT ก่อนเสมอ ถ้า client ส่ง uid ไม่ตรงกับ token = 403"""
    jwt_uid = None
    try:
        jwt_uid = _current_uid()
    except Exception:
        jwt_uid = None
    claimed = str(claimed_uid or "").strip()
    if jwt_uid:
        if claimed and claimed != str(jwt_uid):
            return None, (jsonify({"st": "error", "msg": "uid ไม่ตรงกับบัญชีที่ล็อกอิน"}), 403)
        return str(jwt_uid), None
    if _vs_strict_auth_enabled():
        return None, (jsonify({"st": "error", "msg": "ต้องล็อกอินก่อน"}), 401)
    if not claimed or len(claimed) > 128:
        return None, (jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400)
    return claimed, None


def _kb_clean_prefs(prefs):
    """whitelist เฉพาะ key/ค่าที่แป้นพิมพ์ใช้จริง — ทิ้งอย่างอื่นทั้งหมด"""
    if not isinstance(prefs, dict):
        return {}
    out = {}
    for k in ("lang", "size", "theme"):
        v = prefs.get(k)
        if isinstance(v, str) and _KB_ID_RE.match(v):
            out[k] = v
    g = prefs.get("gif")
    out["gif"] = _kb_safe_url(g) if g else None
    return out


@app.route('/api/keyboard/themes', methods=['GET', 'POST'])
@require_auth_toggleable
def api_keyboard_themes():
    """GET: คืนรายการธีมกำหนดเอง / POST body: {id, name, colors: {bg, fg, border}}
    [SECURITY-FIX K1] validate id/ชื่อ/สี (กัน CSS/HTML injection) + จำกัดจำนวนธีม
    + ห้ามทับชื่อธีม built-in"""
    if request.method == 'POST':
        body = request.get_json(silent=True) or {}
        tid = (body.get('id') or '').strip() if isinstance(body.get('id'), str) else ''
        name = (body.get('name') or '').strip() if isinstance(body.get('name'), str) else ''
        colors = body.get('colors') if isinstance(body.get('colors'), dict) else {}
        if not _KB_ID_RE.match(tid) or not name or len(name) > 40:
            return jsonify({"st": "error", "msg": "id ต้องเป็น a-z 0-9 _ - (≤40) และต้องมี name (≤40)"}), 400
        if tid in ("neon", "fire", "grape", "mono"):
            return jsonify({"st": "error", "msg": "ห้ามใช้ id เดียวกับธีม built-in"}), 400
        clean_colors = {}
        for ck in ("bg", "fg", "border"):
            cv = colors.get(ck)
            if not isinstance(cv, str) or not _KB_COLOR_RE.match(cv.strip()):
                return jsonify({"st": "error", "msg": f"สี {ck} ไม่ถูกต้อง"}), 400
            clean_colors[ck] = cv.strip()
        name = _kb_re.sub(r"[<>\"'`]", "", name)
        theme = {"id": tid, "name": name, "colors": clean_colors}
        _kb_bounded_put(KEYBOARD_CUSTOM_THEMES, tid, theme, KEYBOARD_MAX_THEMES)
        return jsonify({"st": "ok", "theme": theme})
    return jsonify({"st": "ok", "custom_themes": list(KEYBOARD_CUSTOM_THEMES.values())})


@app.route('/api/keyboard/gifs', methods=['GET', 'POST'])
@require_auth_toggleable
def api_keyboard_gifs():
    """GET: รายการพื้นหลัง gif / POST body: {id, url, label?}
    [SECURITY-FIX K1] url ต้องเป็น https เท่านั้น ห้ามมีอักขระที่หลุดออกจาก url('...') ได้"""
    if request.method == 'POST':
        body = request.get_json(silent=True) or {}
        gid = (body.get('id') or '').strip() if isinstance(body.get('id'), str) else ''
        url = _kb_safe_url(body.get('url'))
        if not _KB_ID_RE.match(gid) or not url:
            return jsonify({"st": "error", "msg": "ต้องระบุ id (a-z 0-9 _ -) และ url แบบ https ที่ถูกต้อง"}), 400
        label = body.get('label', gid)
        label = _kb_re.sub(r"[<>\"'`]", "", label)[:40] if isinstance(label, str) else gid
        gif = {"id": gid, "url": url, "label": label}
        _kb_bounded_put(KEYBOARD_GIF_BACKGROUNDS, gid, gif, KEYBOARD_MAX_GIFS)
        return jsonify({"st": "ok", "gif": gif})
    return jsonify({"st": "ok", "gifs": list(KEYBOARD_GIF_BACKGROUNDS.values())})


@app.route('/api/keyboard/prefs', methods=['GET', 'POST'])
@require_auth_toggleable
def api_keyboard_prefs():
    """GET ?uid=xxx / POST body: {uid, prefs: {lang, size, theme, gif}}
    [SECURITY-FIX K1] uid ผูกกับ JWT (อ่าน/เขียน prefs ของคนอื่นไม่ได้) + whitelist ค่า prefs
    + จำกัดจำนวนรายการ"""
    if request.method == 'POST':
        body = request.get_json(silent=True) or {}
        uid, err = _kb_bound_uid(body.get('uid'))
        if err:
            return err
        prefs = _kb_clean_prefs(body.get('prefs'))
        _kb_bounded_put(KEYBOARD_PLAYER_PREFS, uid, prefs, KEYBOARD_MAX_PREFS)
        return jsonify({"st": "ok", "uid": uid, "prefs": prefs})
    uid, err = _kb_bound_uid(request.args.get('uid', ''))
    if err:
        return err
    return jsonify({"st": "ok", "uid": uid, "prefs": KEYBOARD_PLAYER_PREFS.get(uid)})


@app.route('/api/keyboard/share-asset', methods=['POST'])
@require_auth_toggleable
def api_keyboard_share_asset():
    """body: {source, asset_type ('emoji'|'gif'), value, label?}
    [SECURITY-FIX K1] ตรวจ source/value ตามชนิด (gif ต้อง https url, emoji ห้ามมีอักขระ HTML)
    + จำกัดจำนวนของในคลังกลาง กัน stored XSS / memory โตไม่จำกัด"""
    body = request.get_json(silent=True) or {}
    source = (body.get('source') or '').strip() if isinstance(body.get('source'), str) else ''
    asset_type = body.get('asset_type', 'emoji')
    raw_value = (body.get('value') or '').strip() if isinstance(body.get('value'), str) else ''
    if not source or not raw_value:
        return jsonify({"st": "error", "msg": "ต้องระบุ source และ value"}), 400
    if not _KB_SOURCE_RE.match(source):
        return jsonify({"st": "error", "msg": "source ไม่ถูกต้อง"}), 400
    if asset_type not in ('emoji', 'gif'):
        return jsonify({"st": "error", "msg": "asset_type ต้องเป็น emoji หรือ gif"}), 400
    if asset_type == 'gif':
        value = _kb_safe_url(raw_value)
        if not value:
            return jsonify({"st": "error", "msg": "gif ต้องเป็น url แบบ https ที่ถูกต้อง"}), 400
    else:
        if len(raw_value) > 32 or _KB_EMOJI_BAD.search(raw_value):
            return jsonify({"st": "error", "msg": "ข้อความ/อิโมจิไม่ถูกต้อง (ไม่เกิน 32 ตัวอักษร และห้ามมีอักขระพิเศษของ HTML)"}), 400
        value = raw_value
    label = body.get('label', value)
    label = _kb_re.sub(r"[<>\"'`]", "", label)[:40] if isinstance(label, str) else value[:40]
    key = f"{source}:{value}"
    asset = {"source": source, "asset_type": asset_type, "value": value,
             "label": label, "ts": time.time()}
    _kb_bounded_put(KEYBOARD_SHARED_ASSETS, key, asset, KEYBOARD_MAX_SHARED)
    _kb_prune_shared_assets()
    return jsonify({"st": "ok", "asset": asset})


@app.route('/api/keyboard/shared-assets')
def api_keyboard_shared_assets():
    """คืนของทุกชิ้นที่เกมต่างๆ แชร์ไว้ในคลังกลาง — ?exclude=<source> ใช้กรองไม่เอา
    ของที่เกมตัวเอง (ที่กำลังเรียก) แชร์ไว้เองกลับมาแสดงซ้ำในลิสต์ของตัวเอง เพื่อให้
    หน้าแป้นพิมพ์แสดงเฉพาะ "ของจากเกมอื่น" ตามที่ผู้เล่นต้องการเห็น"""
    _kb_prune_shared_assets()
    exclude = request.args.get('exclude', '')
    assets = [a for a in KEYBOARD_SHARED_ASSETS.values() if a["source"] != exclude]
    assets.sort(key=lambda a: a["ts"], reverse=True)
    return jsonify({"st": "ok", "assets": assets})


