# ==========================================
# [ 6y. Mini-Game Overlay Widget — ฝั่งเซิร์ฟเวอร์ ]
# งานหลัก (Always on Top + Dedicated Pointer Input scoped ในกรอบหน้าต่าง) ทำฝั่ง
# client ล้วนๆ ใน MINIGAME_OVERLAY_WIDGET_JS ด้านบน (ไม่ต้องพึ่งเซิร์ฟเวอร์เลยสำหรับ
# การเล่นเอง) — endpoint นี้มีไว้แค่เก็บ high score ต่อผู้เล่นข้ามเกม/ข้าม session
# เหมือน /api/keyboard/prefs และ /api/power-saver/prefs ด้านบน
# ==========================================
MINIGAME_OVERLAY_SCORES = {}  # uid -> {uid, score, ts}


@app.route('/api/minigame-overlay/score', methods=['GET', 'POST'])
@require_auth_toggleable
def api_minigame_overlay_score():
    """GET ?uid=xxx -> คืน high score ล่าสุดที่บันทึกไว้ของผู้เล่นคนนี้
    POST body: {uid, score} -> บันทึกทับเฉพาะตอนที่ score ใหม่สูงกว่าที่เก็บไว้เดิม"""
    if request.method == 'POST':
        body = request.json or {}
        uid = body.get('uid', '')
        try:
            score = int(body.get('score', 0))
        except (TypeError, ValueError):
            score = 0
        if not uid:
            return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
        prev = MINIGAME_OVERLAY_SCORES.get(uid)
        if not prev or score > prev["score"]:
            MINIGAME_OVERLAY_SCORES[uid] = {"uid": uid, "score": score, "ts": time.time()}
        return jsonify({"st": "ok", "uid": uid, "best": MINIGAME_OVERLAY_SCORES[uid]["score"]})
    uid = request.args.get('uid', '')
    rec = MINIGAME_OVERLAY_SCORES.get(uid)
    return jsonify({"st": "ok", "uid": uid, "best": rec["score"] if rec else 0})


@app.route('/widgets/minigame-overlay')
def widget_minigame_overlay():
    """หน้าต่างมินิเกมลอยบนสุด (Always on Top) แบบ standalone — เหมือน widget อื่นๆ
    ด้านบน: เกมอื่นๆ ที่ต่อกับ launcher เดียวกัน (รันเป็นโปรเซส/เว็บแยกของตัวเอง) ดึง
    endpoint นี้ไปฝังในหน้าเว็บของตัวเองได้เลย ตัวอย่างการฝัง:
        fetch('/widgets/minigame-overlay').then(r => r.text())
            .then(html => document.body.insertAdjacentHTML('beforeend', html));
    คืน HTML ปุ่ม + หน้าต่างมินิเกม (ลาก/รีไซส์ได้) + <script> ที่ผูกฟังก์ชันไว้ในตัว
    เสร็จ พร้อมใช้ทันที ไม่ต้องพึ่ง element หรือ global อื่นใดจากหน้าเดิมเลย — pointer
    event ทั้งหมดของหน้าต่างนี้ถูก stopPropagation() ในตัวอยู่แล้ว จึงไม่ไปชนกับ
    input handler ของเกมหลักที่ฝังมันเข้าไป"""
    return MINIGAME_OVERLAY_WIDGET_HTML + "<script>" + MINIGAME_OVERLAY_WIDGET_JS + "</script>"


