# ==========================================
# [ 2a6c. Vent Breach — เชื่อมคลัง (raid carry) + ระเบิด C4/Frag + น้ำหนักคนบนท่อ ]
#
# 1) คลังไอเทม: ใช้ EXTRACTION_RAIDS[uid]["carry"] (กระเป๋าใน raid ที่มีน้ำหนัก/ความจุ และเป็นก้อน
#    เดียวกับที่ระบบ death-drop explosive / container blast ใช้อยู่แล้ว) ไม่เปิดคลังใหม่ซ้อน
#    - เครื่องมือ crowbar / hammer / bolt_cutter: ต้องมีในกระเป๋า (ไม่หมดเมื่อใช้) — ต้องอยู่ใน raid ที่เล่นอยู่
#    - c4_charge / frag_grenade: หักออกจากกระเป๋า 1 ชิ้นตอนวาง/ขว้าง
#    - โหมด speedrun_infil (ห้ามอาวุธ) ใช้ระเบิดไม่ได้ ผ่าน extraction_speedrun_assert_action เดิม
# 2) ระเบิด: C4 วางที่ตะแกรง/จุดแขวนท่อ (fuse 6 วิ หรือกดจุดชนวนเองก่อนเวลา) / Frag ขว้างไกล 25 ม. (fuse 3 วิ)
#    ตอนระเบิดเรียก _explode_carry_item เดิม -> ดาเมจคน + (ผ่าน hook) ทำลายตะแกรง/สายแขวนในรัศมี
# 3) น้ำหนักคนบนท่อ: ผู้เล่นปีนขึ้นท่อได้ (/api/vent/duct/climb) server คิดมวลเอง = 70 กก. + น้ำหนักของในกระเป๋า
#    แบ่งลงสายแขวน 2 จุดใกล้สุด สายที่รับเกินพิกัด (ลดลงตาม hp ที่โดนยิง/ตัดไว้) จะสะสมความเสียหายจนขาด
#    ท่อร่วง -> คนบนท่อได้ fall damage, คนข้างล่างโดนทับ (ของเดิม)
# ==========================================
VENT_INVENTORY_LOCK = threading.RLock()
VENT_EXPLOSIVES = {}          # bomb_id -> {uid,item_id,x,y,vent_id,detonate_at,...}
VENT_EXPLOSIVE_KINDS = {
    "c4_charge":    {"mode": "plant", "fuse_s": 6.0, "plant_noise_m": 20.0, "max_active_per_uid": 3},
    "frag_grenade": {"mode": "throw", "fuse_s": 3.0, "range_m": 25.0, "plant_noise_m": 30.0, "max_active_per_uid": 3},
}

VENT_RIDER_BASE_KG = 70.0            # มวลตัวผู้เล่น (server กำหนด ไม่รับจาก client)
VENT_RIDER_MAX_PER_DUCT = 3
VENT_CLIMB_REACH_M = 2.0             # ต้องอยู่ใกล้แนวท่อเท่านี้ถึงปีนขึ้นได้
VENT_RIDER_OFF_DUCT_M = 1.6          # เดินห่างจากแนวท่อเกินนี้ = ตกลงจากท่อ/ลงจากท่อเอง (ไม่เจ็บ)
VENT_HANGER_RATED_BY_TYPE = {"rod": 60.0, "strap": 35.0}   # กก. ต่อสายแขวน 1 จุด (hp เต็ม): แท่งเหล็กเกลียว / สายเหล็กรู
VENT_HANGER_MIN_SHARE = 0.35         # สายที่ใกล้สุดรับไม่เกิน 65% ของน้ำหนัก (ท่อแข็งช่วยกระจายแรง)
VENT_OVERLOAD_HP_PER_SEC = 40.0      # เกินพิกัด 100% = เสีย hp สายนี้ 40/วินาที (เกินน้อยค่อย ๆ ล้า เกินมากขาดไว)
VENT_DUCT_FALL_DAMAGE = 35
VENT_TICK_INTERVAL = 0.25
_VENT_TICK_LAST = 0.0
_VENT_CREAK_LAST = {}


# ---------- 1) คลังไอเทม (raid carry) ----------
def _vent_raid_for(uid):
    raids = globals().get("EXTRACTION_RAIDS")
    raid = raids.get(uid) if isinstance(raids, dict) else None
    if raid and raid.get("active"):
        return raid
    return None


def vmax_vent_has_tool(uid, tool_id) -> bool:
    """ผู้เล่นมีเครื่องมือชิ้นนี้ในกระเป๋า raid (หรือลงทะเบียนใน loadout['tools']) หรือไม่ — ไม่หักของ"""
    raid = _vent_raid_for(uid)
    if not raid:
        return False
    if int((raid.get("carry") or {}).get(tool_id, 0)) >= 1:
        return True
    lo = raid.get("loadout")
    tools = lo.get("tools") if isinstance(lo, dict) else None
    return bool(tools) and tool_id in tools


def _vent_take_item(uid, item_id):
    """หักไอเทม 1 ชิ้นออกจากกระเป๋า raid แบบ atomic -> (ok, reason)"""
    with VENT_INVENTORY_LOCK:
        raid = _vent_raid_for(uid)
        if not raid:
            return False, "no_active_raid"
        carry = raid.setdefault("carry", {})
        if int(carry.get(item_id, 0)) < 1:
            return False, "no_item"
        carry[item_id] -= 1
        if carry[item_id] <= 0:
            del carry[item_id]
        return True, "ok"


def _vent_rider_mass(uid) -> float:
    mass = VENT_RIDER_BASE_KG
    raid = _vent_raid_for(uid)
    if raid:
        try:
            mass += float(sum(_item_weight(k, v) for k, v in (raid.get("carry") or {}).items()))
        except Exception:
            pass
    return mass


# ---------- 3) น้ำหนักคนบนท่อ ----------
def _vent_duct_project(v, px, py):
    """จุด (px,py) ฉายลงแนวท่อ -> (t 0..1, ระยะห่างจากแนวท่อ)"""
    ax, ay, bx, by_ = v["x"], v["y"], v["x2"], v["y2"]
    abx, aby = bx - ax, by_ - ay
    den = abx * abx + aby * aby
    t = 0.0 if den <= 1e-12 else max(0.0, min(1.0, ((px - ax) * abx + (py - ay) * aby) / den))
    return t, math.hypot(px - (ax + abx * t), py - (ay + aby * t))


def _vent_hanger_rated(v, h) -> float:
    """พิกัดรับน้ำหนักจริงของสายแขวน = พิกัดตามชนิด x สัดส่วน hp (สายที่โดนยิง/ตัดไว้แล้วอ่อนลง)"""
    base = VENT_HANGER_RATED_BY_TYPE.get(v.get("hanger_type", "rod"), 45.0)
    return base * max(0.2, h["hp"] / max(1.0, h["max_hp"]))


def _vent_duct_loads(v) -> dict:
    """น้ำหนักที่ลงสายแขวนแต่ละจุด (กก.) — คนแต่ละคนแบ่งลงสายที่ใกล้สุดซ้าย/ขวา ตามสัดส่วนระยะ (จำกัด 35-65%)"""
    loads = {h["id"]: 0.0 for h in v["hangers"]}
    riders = v.get("riders") or {}
    intact = [h for h in v["hangers"] if not h["broken"]]
    if not riders or not intact:
        return loads
    length = max(0.1, math.hypot(v["x2"] - v["x"], v["y2"] - v["y"]))
    single = 1.0 - VENT_HANGER_MIN_SHARE
    for r in riders.values():
        t, m = r["t"], r["mass"]
        left = max((h for h in intact if h["t"] <= t), key=lambda h: h["t"], default=None)
        right = min((h for h in intact if h["t"] > t), key=lambda h: h["t"], default=None)
        if left is None and right is None:
            continue
        if left is None or right is None:
            loads[(left or right)["id"]] += m * single      # ปลายท่อ: สายเดียวรับ (ที่เหลือท่อ/ผนังช่วยรับ)
            continue
        span = (right["t"] - left["t"]) * length
        share_left = 0.5 if span <= 1e-6 else (right["t"] - t) * length / span
        share_left = min(single, max(VENT_HANGER_MIN_SHARE, share_left))
        loads[left["id"]] += m * share_left
        loads[right["id"]] += m * (1.0 - share_left)
    return loads


def _vent_drop_riders(v, by_uid):
    """ท่อร่วง: คนที่อยู่บนท่อตกลงมาเจ็บ (fall damage) — ส่วนคนข้างล่างโดนทับใน _vent_crush_below"""
    riders = v.get("riders") or {}
    out = []
    with _PAWNS_LOCK:
        for uid in list(riders):
            for sid, pawn in PLAYER_PAWNS.items():
                if not (sid == uid or PLAYERS.get(sid, {}).get("uid") == uid):
                    continue
                if not pawn.get("alive", True):
                    continue
                pawn["hp"] = max(0, float(pawn.get("hp", 100)) - VENT_DUCT_FALL_DAMAGE)
                pawn["alive"] = pawn["hp"] > 0
                out.append({"uid": uid, "hp": pawn["hp"], "dead": not pawn["alive"]})
                break
    riders.clear()
    return out


def _vent_tick_duct_weight(v, now, dt):
    riders = v.get("riders") or {}
    if not riders or v["status"] == "fallen":
        return
    for uid in list(riders):                       # อัปเดตตำแหน่งจาก pawn ฝั่ง server / ปล่อยคนที่เดินออกจากท่อ
        pawn = _pawn_by_uid(uid)
        if not pawn or not pawn.get("alive", True):
            riders.pop(uid, None)
            continue
        t, d = _vent_duct_project(v, float(pawn["x"]), float(pawn["y"]))
        if d > VENT_RIDER_OFF_DUCT_M:
            riders.pop(uid, None)
            continue
        riders[uid]["t"] = t
    if not riders:
        return
    loads = _vent_duct_loads(v)
    broke, overloaded = [], False
    for h in v["hangers"]:
        load = loads.get(h["id"], 0.0)
        if h["broken"] or load <= 0.0:
            continue
        rated = _vent_hanger_rated(v, h)
        if load > rated:
            overloaded = True
            if _vent_damage_hanger(h, (load / rated - 1.0) * VENT_OVERLOAD_HP_PER_SEC * dt):
                broke.append(h["id"])
    if broke:
        _vent_finish(v, None, {"overload": True, "broken_hangers": broke})
    elif overloaded and now - _VENT_CREAK_LAST.get(v["vent_id"], 0.0) >= 1.5:
        _VENT_CREAK_LAST[v["vent_id"]] = now
        mx = sum(r["mass"] for r in riders.values())
        _vent_noise("", (v["x"] + v["x2"]) / 2.0, (v["y"] + v["y2"]) / 2.0, 35.0, "duct_creak")
        _vent_finish(v, None, {"creaking": True, "load_kg": round(mx, 1)})


# ---------- 2) ระเบิด ----------
def _vent_target_point(v, pawn, hanger_id=""):
    if v["kind"] == "grille":
        return v["x"], v["y"]
    cands = [h for h in v["hangers"] if not h["broken"]] or v["hangers"]
    if hanger_id:
        hh = next((h for h in cands if h["id"] == hanger_id), None)
        if hh:
            return hh["x"], hh["y"]
    px, py = float(pawn["x"]), float(pawn["y"])
    h = min(cands, key=lambda h: math.hypot(h["x"] - px, h["y"] - py))
    return h["x"], h["y"]


def _vent_detonate(b):
    uid, item_id, x, y = b["uid"], b["item_id"], b["x"], b["y"]
    _vent_emit("vent_explosive_detonated", {"bomb_id": b["bomb_id"], "uid": uid, "item_id": item_id,
                                            "x": x, "y": y, "vent_id": b.get("vent_id")})
    boom = globals().get("_explode_carry_item")
    if callable(boom):
        try:
            boom(uid, item_id, 1, x, y, f"vent_{item_id}")   # ดาเมจคน + (ผ่าน hook ใน _explode_carry_item) ตะแกรง/ท่อ
            return
        except Exception:
            pass
    stats = (globals().get("DEATH_DROP_EXPLOSIVE_STATS") or {}).get(item_id, {"damage": 100, "radius": 6.0})
    vmax_vent_apply_explosion(uid, x, y, 1.0, stats["radius"], stats["damage"] / 100.0)


def _vent_process_explosives(now):
    due = []
    with VENT_INVENTORY_LOCK:
        for bid, b in list(VENT_EXPLOSIVES.items()):
            if now >= b["detonate_at"]:
                due.append(VENT_EXPLOSIVES.pop(bid))
    for b in due:
        try:
            _vent_detonate(b)
        except Exception:
            pass


def vmax_vent_tick(dt: float = 0.0):
    """เรียกจาก physics_step (และแบบ lazy จาก endpoint vent) — ประมวลผลชนวนระเบิด + น้ำหนักคนบนท่อ"""
    global _VENT_TICK_LAST
    now = time.time()
    if now - _VENT_TICK_LAST < VENT_TICK_INTERVAL:
        return
    step = min(1.0, now - _VENT_TICK_LAST) if _VENT_TICK_LAST else VENT_TICK_INTERVAL
    _VENT_TICK_LAST = now
    try:
        _vent_process_explosives(now)
    except Exception:
        pass
    with VENT_LOCK:
        for v in list(VENT_REGISTRY.values()):
            if v["kind"] == "duct" and v.get("riders"):
                try:
                    _vent_tick_duct_weight(v, now, step)
                except Exception:
                    pass


# public view: เพิ่มจำนวนคนบนท่อ + % โหลดของสายแขวนแต่ละจุด (>100% = กำลังล้า/เสียงลั่น)
_vmax_vent_public_base = vmax_vent_public


def vmax_vent_public(v: dict) -> dict:
    out = _vmax_vent_public_base(v)
    if v["kind"] == "duct":
        riders = v.get("riders") or {}
        out["rider_count"] = len(riders)
        loads = _vent_duct_loads(v) if riders else {}
        by_id = {h["id"]: h for h in v["hangers"]}
        for ph in out.get("hangers", []):
            h = by_id.get(ph["id"])
            if h is not None:
                ph["load_pct"] = round(100.0 * loads.get(h["id"], 0.0) / _vent_hanger_rated(v, h)) if not h["broken"] else 0
    return out


@app.route('/api/vent/duct/climb', methods=['POST'])
@require_auth_toggleable
def api_vent_duct_climb():
    """ปีนขึ้น/ลงท่อดักท์: body = {vent_id, action: "mount" | "dismount"} — มวลคิดฝั่ง server (70 กก. + ของในกระเป๋า)"""
    body = request.get_json(silent=True) or {}
    uid = _vmax_authenticated_owner_uid(body)
    if not uid:
        return jsonify({"st": "error", "msg": "ต้องมี uid/JWT"}), 401
    vmax_vent_tick()
    vent_id, action = str(body.get("vent_id", "")), str(body.get("action", "mount"))
    pawn = _pawn_by_uid(uid)
    if not pawn or not pawn.get("alive", True):
        return jsonify({"st": "blocked", "reason": "player_not_found"}), 400
    with VENT_LOCK:
        v = VENT_REGISTRY.get(vent_id)
        if not v or v["kind"] != "duct":
            return jsonify({"st": "error", "msg": "ไม่พบท่อดักท์นี้"}), 404
        riders = v.setdefault("riders", {})
        if action == "dismount":
            riders.pop(uid, None)
            return jsonify({"st": "ok", "vent": vmax_vent_public(v)})
        if action != "mount":
            return jsonify({"st": "error", "msg": "action ต้องเป็น mount/dismount"}), 400
        if v["status"] == "fallen":
            return jsonify({"st": "blocked", "reason": "duct_fallen"}), 400
        t, d = _vent_duct_project(v, float(pawn["x"]), float(pawn["y"]))
        if d > VENT_CLIMB_REACH_M:
            return jsonify({"st": "blocked", "reason": "too_far", "reach_m": VENT_CLIMB_REACH_M}), 400
        if uid not in riders and len(riders) >= VENT_RIDER_MAX_PER_DUCT:
            return jsonify({"st": "blocked", "reason": "duct_full", "max_riders": VENT_RIDER_MAX_PER_DUCT}), 400
        mass = _vent_rider_mass(uid)
        riders[uid] = {"t": t, "mass": mass, "since": time.time()}
        _vent_noise(uid, float(pawn["x"]), float(pawn["y"]), 15.0, "duct_climb")
        _vent_emit("vent_update", {"vent": vmax_vent_public(v), "by": uid, "climb": "mount"}, v)
        return jsonify({"st": "ok", "mass_kg": round(mass, 1), "vent": vmax_vent_public(v)})


@app.route('/api/vent/explosive/plant', methods=['POST'])
@require_auth_toggleable
def api_vent_explosive_plant():
    """วาง C4 ที่ตะแกรง/จุดแขวนท่อ (ต้องอยู่ใกล้) หรือขว้าง Frag ไปที่ vent/พิกัด — หักของจากกระเป๋า raid จริง
    body = {item_id: "c4_charge"|"frag_grenade", vent_id?, hanger?, x?, y?}"""
    body = request.get_json(silent=True) or {}
    uid = _vmax_authenticated_owner_uid(body)
    if not uid:
        return jsonify({"st": "error", "msg": "ต้องมี uid/JWT"}), 401
    vmax_vent_tick()
    item_id = str(body.get("item_id", "c4_charge"))
    kind = VENT_EXPLOSIVE_KINDS.get(item_id)
    if not kind:
        return jsonify({"st": "error", "msg": "ชนิดระเบิดไม่รองรับ", "supported": list(VENT_EXPLOSIVE_KINDS)}), 400
    _guard = globals().get("extraction_speedrun_assert_action")
    if callable(_guard):
        _ok, _msg = _guard(uid, "weapon")
        if not _ok:
            return jsonify({"st": "blocked", "reason": "weapons_banned", "msg": _msg}), 403
    pawn = _pawn_by_uid(uid)
    if not pawn or not pawn.get("alive", True):
        return jsonify({"st": "blocked", "reason": "player_not_found"}), 400
    px, py = float(pawn["x"]), float(pawn["y"])
    vent_id = str(body.get("vent_id", ""))
    with VENT_LOCK:
        v = VENT_REGISTRY.get(vent_id) if vent_id else None
        if vent_id and not v:
            return jsonify({"st": "error", "msg": "ไม่พบช่องระบายอากาศนี้"}), 404
        if v is not None:
            if (v["kind"] == "grille" and v["status"] == "open") or (v["kind"] == "duct" and v["status"] == "fallen"):
                return jsonify({"st": "blocked", "reason": "already_destroyed"}), 400
            tx, ty = _vent_target_point(v, pawn, str(body.get("hanger", "")))
        else:
            try:
                tx, ty = float(body["x"]), float(body["y"])
            except (KeyError, TypeError, ValueError):
                return jsonify({"st": "error", "msg": "ต้องระบุ vent_id หรือ x,y"}), 400
            if not (math.isfinite(tx) and math.isfinite(ty)):
                return jsonify({"st": "error", "msg": "x,y ไม่ถูกต้อง"}), 400
    dist = math.hypot(tx - px, ty - py)
    if kind["mode"] == "plant":
        if v is None:
            return jsonify({"st": "blocked", "reason": "c4_needs_vent"}), 400
        if dist > VENT_REACH_M:
            return jsonify({"st": "blocked", "reason": "too_far", "reach_m": VENT_REACH_M}), 400
    elif dist > kind["range_m"]:
        return jsonify({"st": "blocked", "reason": "out_of_range", "range_m": kind["range_m"]}), 400
    with VENT_INVENTORY_LOCK:
        active = sum(1 for b in VENT_EXPLOSIVES.values() if b["uid"] == uid)
        if active >= kind["max_active_per_uid"]:
            return jsonify({"st": "blocked", "reason": "too_many_active", "max": kind["max_active_per_uid"]}), 400
        ok, why = _vent_take_item(uid, item_id)
        if not ok:
            return jsonify({"st": "blocked", "reason": why, "item_id": item_id}), 403
        now = time.time()
        bomb_id = uuid.uuid4().hex[:10]
        VENT_EXPLOSIVES[bomb_id] = {"bomb_id": bomb_id, "uid": uid, "item_id": item_id, "mode": kind["mode"],
                                    "x": tx, "y": ty, "vent_id": vent_id or None,
                                    "planted_at": now, "detonate_at": now + kind["fuse_s"]}
    _vent_noise(uid, px, py, kind["plant_noise_m"], f"{kind['mode']}_{item_id}")
    _vent_emit("vent_explosive_planted", {"bomb_id": bomb_id, "uid": uid, "item_id": item_id,
                                          "x": tx, "y": ty, "vent_id": vent_id or None, "fuse_s": kind["fuse_s"]})
    return jsonify({"st": "ok", "bomb_id": bomb_id, "item_id": item_id, "fuse_s": kind["fuse_s"],
                    "manual_detonate": item_id == "c4_charge"})


