# ---------- server-side soft lock target query ----------
TACTICAL_SOFT_LOCK = {"max_distance_m": 55.0, "fov_deg": 24.0, "turn_strength": 0.16}
TACTICAL_POSITIONS = {}  # uid -> {x,y,z,yaw,pitch,updated_at}
TACTICAL_POS_LOCK = threading.RLock()

@app.route('/api/tactical/position', methods=['POST'])
@require_auth_toggleable
def api_tactical_position():
    body = request.get_json(silent=True) or {}
    uid = _vmax_authenticated_owner_uid(body)
    if not uid: return jsonify({"st":"error","msg":"ต้องมี uid/JWT"}), 401
    try:
        x,y,z,yaw,pitch = [float(body.get(k,0)) for k in ("x","y","z","yaw","pitch")]
    except (TypeError,ValueError):
        return jsonify({"st":"error","msg":"position ไม่ถูกต้อง"}), 400
    with TACTICAL_POS_LOCK:
        TACTICAL_POSITIONS[uid] = {"x":x,"y":y,"z":z,"yaw":yaw,"pitch":pitch,"updated_at":time.time()}
    return jsonify({"st":"ok"})

def _angle_wrap(a):
    return (a + math.pi) % (2*math.pi) - math.pi

@app.route('/api/tactical/targets')
def api_tactical_targets():
    uid = request.args.get("uid", "")
    try:
        yaw = float(request.args.get("yaw", 0)); max_dist = min(float(request.args.get("max_distance", TACTICAL_SOFT_LOCK["max_distance_m"])), TACTICAL_SOFT_LOCK["max_distance_m"])
    except (TypeError,ValueError):
        return jsonify({"st":"error","msg":"yaw/max_distance ไม่ถูกต้อง"}), 400
    with TACTICAL_POS_LOCK:
        me = dict(TACTICAL_POSITIONS.get(uid, {}))
        positions = {u:dict(v) for u,v in TACTICAL_POSITIONS.items() if u != uid and time.time()-v.get("updated_at",0) < 2.0}
    if not me:
        return jsonify({"st":"ok","targets":[]})
    out=[]; half=math.radians(TACTICAL_SOFT_LOCK["fov_deg"])
    for tu,p in positions.items():
        dx, dz = p["x"]-me["x"], p["z"]-me["z"]
        dist=math.hypot(dx,dz)
        if dist > max_dist or dist < 0.01: continue
        ang=math.atan2(dx,-dz)
        delta=abs(_angle_wrap(ang-yaw))
        if delta <= half:
            out.append({"uid":tu,"x":p["x"],"y":p["y"],"z":p["z"],"distance_m":dist,"angle_delta_deg":math.degrees(delta)})
    out.sort(key=lambda x:(x["angle_delta_deg"],x["distance_m"]))
    return jsonify({"st":"ok","targets":out[:4],"soft_lock":TACTICAL_SOFT_LOCK})

@app.route('/api/fire', methods=['POST'])
@require_auth_toggleable
def fire():
    if SALINE["active"]:
        return jsonify({"hit": False, "locked": True, "msg": "กำลังรักษาอยู่ ขยับตัวไม่ได้"})
    if BAT.soc <= 1:
        return jsonify({"hit": False})  # แบตหมด ยิงไม่ได้
    if P["ammo"] <= 0:
        return jsonify({"hit": False, "no_ammo": True})  # กระสุนหมด ต้องรีโหลดก่อน
    now = time.time()
    if now < RELOAD_LOCK_UNTIL["t"]:   # ยังอยู่ในจังหวะปิดรังเพลิง — ปิดช่อง reload-cancel
        wait = RELOAD_LOCK_UNTIL["t"] - now
        return jsonify({"hit": False, "locked": True, "reason": "reload_lock",
                         "msg": f"กำลังใส่กระสุน รออีก {wait:.2f} วิ"})
    if not check_fire_rate(P["weap"]):
        return jsonify({"hit": False, "flagged": True, "reason": FLAGGED["reason"]})
    disease = DISEASES[P_DISEASE["id"]]
    energy_mult = disease.get("energy_mult", 1)
    BAT.drain(W[P["weap"]]["energy"] * energy_mult)
    P["ammo"] -= 1
    hit_chance = 0.7 - disease.get("hit_penalty", 0)
    hit = random.random() < hit_chance
    dive_bonus = time.time() < DIVE["bonus_until"]
    if dive_bonus:
        DIVE["bonus_until"] = 0  # ใช้โบนัสได้แค่นัดเดียวหลังพุ่งหมอบ
    if hit:
        dmg = W[P["weap"]]["dmg"] * (1.5 if dive_bonus else 1)
        P["score"] += dmg
        P["credits"] += 25
        P["exp"] += int(round(15 * _season_event_char_exp_mult()))  # [ 6zz6r5 ] เร่ง EXP ตัวละครระหว่างอีเวนต์ท้ายซีซั่น
        if P["exp"] >= P["level"] * 100:
            P["level"] += 1
            P["exp"] = 0
            bridge_push_event("python", "player_leveled_up", {"uid": P["uid"], "new_level": P["level"]})
    new_bullet = maybe_take_return_fire()
    return jsonify({"hit": hit, "dive_bonus": dive_bonus, "ammo": P["ammo"], "return_fire_bullet": new_bullet})


@app.route('/api/reload', methods=['POST'])
@require_auth_toggleable
def reload_bullet():
    body = request.get_json(silent=True) or {}
