@app.route('/api/propose_feature', methods=['POST'])
@require_auth_toggleable
def propose_feature():
    body = request.json or {}
    desc = body.get('description', '').strip()
    target = body.get('target', 'python').strip().lower()
    if not desc:
        return jsonify({"st": "error", "msg": "กรุณาพิมพ์คำบรรยาย"}), 400
    lang = _lang_config(target)
    code, context_meta = generate_feature_code(desc, target)

    # เช็ค syntax + ชื่อ/route ชนกับของเดิม ก่อนที่ผู้ใช้จะเห็นหน้าจออนุมัติ — ไม่ได้
    # ตัดสิทธิ์ผู้ใช้ในการอนุมัติเอง แค่ให้เห็นความเสี่ยงก่อนกด ถ้า syntax ผิดเลยก็ไม่ต้อง
    # เก็บเป็น pending ให้เสียเวลาตรวจ เพราะรู้แน่ๆ ว่าใช้ไม่ได้
    conflicts = []
    if lang["key"] == "python":
        conflicts = _check_feature_code_conflicts(code, _existing_codebase_symbols())
        if conflicts and conflicts[0].startswith("SYNTAX ERROR"):
            return jsonify({"st": "error", "msg": conflicts[0], "code": code,
                             "context": context_meta}), 422

    fid = uuid.uuid4().hex[:8]
    path = f"pending_features/{fid}.{lang['ext']}"
    with open(path, "w", encoding="utf-8") as f:
        f.write(code)
    idx = _load_pending()
    idx[fid] = {"description": desc, "path": path, "status": "pending",
                "created": time.time(), "target": lang["key"], "wiring": lang["wiring"],
                "conflicts": conflicts, "context": context_meta}
    _save_pending(idx)
    return jsonify({"st": "ok", "id": fid, "code": code, "conflicts": conflicts,
                    "target": lang["key"], "wiring": lang["wiring"], "context": context_meta})


