@app.route('/api/grown_ai/stats')
def api_grown_ai_stats():
    """โชว์ว่าตอนนี้ 'ความจำ' ที่งอกมาจากฟีเจอร์ที่เคยอนุมัติแล้วมีขนาดเท่าไหร่ —
    ยิ่งอนุมัติเยอะ ตัวเลขนี้ยิ่งโต และ generate_feature_code() ยิ่งมีโอกาสตอบจาก
    ตรงนี้แทนที่จะต้องยิงไปหา local AI ภายนอก"""
    idx = _load_registry()
    total_versions = sum(len(v) for v in idx.values())
    by_target = {}
    for versions in idx.values():
        for rec in versions:
            t = rec.get("target", "?")
            by_target[t] = by_target.get(t, 0) + 1
    return jsonify({"st": "ok", "unique_features": len(idx),
                     "total_versions": total_versions, "by_target": by_target})


@app.route('/api/approve_feature/<fid>', methods=['POST'])
@require_auth_toggleable
def approve_feature(fid):
    """[PATCHED] เดิม endpoint นี้ไม่เช็คสิทธิ์อะไรเลย — ใครก็ยิง POST เข้ามาอนุมัติ
    โค้ดที่รออยู่ได้ทันที และถ้า wiring เป็น 'exec' โค้ดนั้นจะถูกเขียนต่อท้าย
    approved_features.py แล้วโดน exec ตอนรีสตาร์ทเซิร์ฟเวอร์ = Remote Code
    Execution เต็มรูปแบบ ตอนนี้บังคับต้องล็อกอิน (Bearer JWT) และมียศ admin
    ขึ้นไปเท่านั้นถึงจะอนุมัติ/merge โค้ดได้"""
    caller_uid, caller_rank = _staff_from_request()
    if caller_uid is None:
        return jsonify({"st": "error", "msg": "ต้องล็อกอินก่อน (Bearer token)"}), 401
    if caller_rank < STAFF_RANKS["admin"]:
        return jsonify({"st": "error", "msg": "ปฏิเสธคำร้อง: สิทธิ์ของคุณไม่พอในการอนุมัติโค้ดเข้าระบบ"}), 403

    idx = _load_pending()
    if fid not in idx:
        return jsonify({"st": "error", "msg": "ไม่พบรายการนี้"}), 404
    entry = idx[fid]
    # ผู้ใช้ต้องกดยืนยันเองเท่านั้นถึงจะ merge — ไม่ merge อัตโนมัติ ไม่ว่าภาษาไหน
    entry["status"] = "approved"
    lang_key = entry.get("target", "python")
    wiring = entry.get("wiring", "manual")

    with open(entry["path"], "r", encoding="utf-8") as src:
        code = src.read()

    # ไม่ว่า wiring จะเป็นแบบไหน (auto-exec / unity dropin / manual) — ของที่ผ่าน
    # การอนุมัติแล้วถือว่า "ซ่อม/ทำเสร็จแล้ว" ทั้งหมด จึงบันทึกเข้าที่เก็บกลางเดียวกัน
    # เสมอ เพื่อให้ระบบอื่นหรือ API ภายนอกดึงไปใช้ได้ทีหลัง โดยไม่ต้องรู้ว่า
    # ตอนอนุมัติมันถูก auto-wire เข้าเกมนี้ไปแล้วหรือยัง
    registry_record = register_fixed_code(
        name=fid, code=code, target=lang_key,
        description=entry.get("description", ""), source_fid=fid)

    if wiring == "exec":
        # [SECURITY-FIX #8] ไม่อนุญาตให้ endpoint HTTP เขียนโค้ดที่ผู้ใช้ส่งมา
        # เข้า approved_features.py เพื่อ exec ใน process หลักอีกต่อไป. การอนุมัติ
        # จะเก็บโค้ดไว้ใน registry เท่านั้น; หากต้องนำไปใช้งาน ให้ deploy/ตรวจสอบ
        # แบบ explicit ภายนอก process นี้. นี่ตัด RCE chain จาก pending code -> exec.
        entry["status"] = "blocked_security"
        _save_pending(idx)
        return jsonify({
            "st": "error",
            "msg": "ปฏิเสธ wiring=exec เพื่อความปลอดภัย: ระบบไม่รันโค้ด Python ที่ส่งผ่าน API โดยตรง; โค้ดถูกเก็บใน registry แล้ว",
            "registry": registry_record,
        }), 403

    if wiring == "unity_dropin":
        unity_path = os.environ.get("UNITY_PROJECT_PATH")
        if not unity_path:
            _save_pending(idx)
            return jsonify({
                "st": "ok",
                "msg": ("บันทึกไฟล์ .cs ไว้แล้ว แต่ยังไม่ auto-wire เข้า Unity — "
                        "ต้องตั้ง env var ก่อน: export UNITY_PROJECT_PATH=/path/to/YourUnityProject "
                        f"แล้วกดอนุมัติใหม่ (ไฟล์ปัจจุบันอยู่ที่ {entry['path']})"),
                "registry": registry_record,
            })
        gen_dir = os.path.join(unity_path, "Assets", "Scripts", "Generated")
        os.makedirs(gen_dir, exist_ok=True)
        out_path = os.path.join(gen_dir, f"Feature_{fid}.cs")
        with open(out_path, "w", encoding="utf-8") as f:
            f.write(code)
        _save_pending(idx)
        return jsonify({
            "st": "ok",
            "msg": (f"เขียนไฟล์ไปที่ {out_path} แล้ว — ถ้า Unity Editor เปิดโปรเจกต์นี้ค้างอยู่ "
                    "Unity จะ detect ไฟล์ใหม่แล้ว compile ให้อัตโนมัติเอง (นี่คือกลไกของ Unity เอง "
                    "ไม่ใช่ของสคริปต์นี้ — ถ้า Editor ปิดอยู่ ก็แค่เปิดโปรเจกต์แล้ว Unity จะ pick up ตอนเปิด)"),
            "registry": registry_record,
        })

    if wiring == "csharp_auto":
        project_path = os.environ.get("UNITY_PROJECT_PATH")
        if not project_path:
            _save_pending(idx)
            return jsonify({
                "st": "ok",
                "msg": ("บันทึกไฟล์ .cs ไว้แล้ว แต่ยังไม่ auto-wire — ต้องตั้ง env var ก่อน: "
                        "export UNITY_PROJECT_PATH=/path/to/YourProject (ใช้ path เดียวกันได้ทั้ง "
                        "โปรเจกต์ Unity และโปรเจกต์ .NET ธรรมดา ระบบจะตรวจเองว่าเป็นแบบไหน) "
                        f"แล้วกดอนุมัติใหม่ (ไฟล์ปัจจุบันอยู่ที่ {entry['path']})"),
                "registry": registry_record,
            })

        kind = _detect_csharp_project_kind(project_path)

        if kind == "missing":
            _save_pending(idx)
            return jsonify({
                "st": "ok",
                "msg": (f"บันทึกไฟล์ .cs ไว้แล้วที่ {entry['path']} แต่ path ที่ตั้งไว้ใน "
                        f"UNITY_PROJECT_PATH ({project_path}) ไม่มีอยู่จริง ตรวจ path แล้วกดอนุมัติใหม่"),
                "registry": registry_record,
            })

        if kind == "unity":
            gen_dir = os.path.join(project_path, "Assets", "Scripts", "Generated")
            os.makedirs(gen_dir, exist_ok=True)
            out_path = os.path.join(gen_dir, f"Feature_{fid}.cs")
            with open(out_path, "w", encoding="utf-8") as f:
                f.write(code)
            _save_pending(idx)
            return jsonify({
                "st": "ok",
                "msg": (f"ตรวจพบว่า path นี้เป็นโปรเจกต์ Unity (เจอ Assets/ + ProjectSettings/) — "
                        f"เขียนไฟล์ไปที่ {out_path} แล้ว ถ้า Unity Editor เปิดโปรเจกต์นี้ค้างอยู่ Unity "
                        "จะ detect ไฟล์ใหม่แล้ว compile ให้อัตโนมัติเอง (ถ้า Editor ปิดอยู่ ก็แค่เปิด "
                        "โปรเจกต์แล้ว Unity จะ pick up ตอนเปิด)"),
                "registry": registry_record,
            })

        if kind == "dotnet":
            gen_dir = os.path.join(project_path, "Generated")
            os.makedirs(gen_dir, exist_ok=True)
            out_path = os.path.join(gen_dir, f"Feature_{fid}.cs")
            with open(out_path, "w", encoding="utf-8") as f:
                f.write(code)
            _save_pending(idx)
            return jsonify({
                "st": "ok",
                "msg": (f"ตรวจพบว่า path นี้เป็นโปรเจกต์ .NET ธรรมดา (เจอ .csproj/.sln แต่ไม่ใช่ Unity) — "
                        f"เขียนไฟล์ไปที่ {out_path} แล้ว ถ้า .csproj เป็นแบบ SDK-style (ค่า default ของ "
                        ".NET รุ่นใหม่ๆ) ไฟล์ .cs ในโฟลเดอร์นี้จะถูกรวมเข้า build อัตโนมัติตอนสั่ง "
                        "'dotnet build'/'dotnet run' ครั้งถัดไป โดยไม่ต้องแก้ .csproj เอง — แต่ถ้าเป็น "
                        ".csproj แบบเก่าที่ list ไฟล์ทีละไฟล์ ต้องเพิ่มบรรทัดอ้างอิงไฟล์นี้เข้าไปเอง"),
                "registry": registry_record,
            })

        # kind == "unknown" — path มีอยู่จริง แต่ไม่เจอทั้งร่องรอย Unity และ .NET
        _save_pending(idx)
        return jsonify({
            "st": "ok",
            "msg": (f"บันทึกไฟล์ .cs ไว้แล้วที่ {entry['path']} แต่ path ใน UNITY_PROJECT_PATH "
                    f"({project_path}) ไม่มีทั้ง Assets/+ProjectSettings/ (Unity) และ .csproj/.sln "
                    "(.NET ธรรมดา) เลย — ตรวจว่า path ตั้งถูกโฟลเดอร์ไหม หรือถ้ามั่นใจว่าเป็น Unity "
                    "จริงๆ ให้เลือกภาษา 'unity' (บังคับ) แทน 'csharp' (auto-detect) ตอนสร้างฟีเจอร์ใหม่"),
            "registry": registry_record,
        })

    # wiring == "manual" — no generic live auto-wire exists across arbitrary
    # languages/runtimes; saving the file honestly is the correct behavior here.
    _save_pending(idx)
    return jsonify({
        "st": "ok",
        "msg": (f"บันทึกโค้ด {lang_key} ไว้ที่ {entry['path']} แล้ว — ภาษานี้ไม่มีกลไก auto-wire "
                "ให้ทำเองครับ (โปรเจกต์/runtime แต่ละอันมีวิธี load โค้ดไม่เหมือนกัน จึงทำ auto-connect "
                "กลางๆ ให้ทุกภาษาแบบเดียวกันไม่ได้จริง) ต้องเอาไฟล์นี้ไปวางในโปรเจกต์เป้าหมายเอง"),
        "registry": registry_record,
    })


def load_approved_features():
    """Compatibility hook for the legacy approved_features.py mechanism.

    [SECURITY-FIX #8] External Python is never executed into the main process.
    Approved code is kept in code_registry and must be deployed explicitly outside
    this runtime after review. The no-op hook keeps legacy callers from breaking.
    """
    print("[VMAX Kernel] approved_features.py auto-exec disabled; no external code was executed.")
    return False

