# [ 6b. Security / Login Routes ]
# ==========================================
@app.route('/api/auth/register', methods=['POST'])
def api_register():
    body = request.json or {}
    uid, pw = body.get('uid', '').strip(), body.get('password', '')
    if not uid:
        return jsonify({"st": "error", "msg": "uid is required"}), 400
    ok, msg = register_user(uid, pw)
    onboarding = None
    if ok:
        audit_log("register", uid=uid)
        # ผู้ช่วยทักผู้ใช้ใหม่ — เลือกภาษา + ถามว่าต้องการความช่วยเหลือเรื่องใด
        try:
            if callable(globals().get("vmax_onboarding_start")):
                onboarding = vmax_onboarding_start(uid, preferred_lang=body.get("lang") or body.get("language"))
        except Exception as _ob_exc:
            print("[ONBOARDING] start error:", repr(_ob_exc))
    return jsonify({
        "st": "ok" if ok else "error",
        "msg": msg,
        "onboarding": onboarding,
        "next_step": ("2FA setup is required before you can log in — "
                      "call /api/auth/2fa/setup then /api/auth/2fa/enable") if ok else None,
    }), (200 if ok else 400)

@app.route('/api/auth/login', methods=['POST'])
def api_login():
    """2FA is MANDATORY for every account (not opt-in): a correct password on
    an account that hasn't finished TOTP setup returns st="2fa_setup_required"
    instead of a session token, so the client can route straight into
    /api/auth/2fa/setup + /api/auth/2fa/enable before any session is issued."""
    body      = request.json or {}
    uid       = body.get('uid', 'VMAX-OP-01')
    password  = body.get('password', '')
    device_id = body.get('device_id', 'default-device')
    code_2fa  = body.get('code_2fa', '')

    # --- Device standards gate (กันอุปกรณ์ไม่เข้าเกณฑ์ / เหลี่ยม) ---
    try:
        if callable(globals().get("vmax_device_gate_required")) and vmax_device_gate_required():
            gt = body.get("device_gate_token") or request.headers.get("X-VMAX-Device-Gate")
            ok_g, gmsg = vmax_device_gate_verify_token(gt, device_id=device_id)
            if not ok_g:
                try:
                    audit_log("login_blocked_device_gate", uid=uid, device_id=device_id, reason=gmsg)
                except Exception:
                    pass
                return jsonify({"st": "error", "msg": "อุปกรณ์ไม่ผ่านเกณฑ์มาตรฐาน: " + str(gmsg),
                                "code": "device_gate_failed"}), 403
            # เก็บโหมดไว้ใส่ใน response ทีหลัง
            try:
                request.vmax_device_mode = "compat" if gmsg == "ok_compat" else "pass"
            except Exception:
                pass
    except NameError:
        pass
    except Exception as _dg_exc:
        print("[DEVICE GATE] login check error:", repr(_dg_exc))

    if is_login_locked_out(uid):
        audit_log("login_locked_out", uid=uid)
        return jsonify({"st": "error", "msg": "Too many failed attempts — try again later"}), 429

    if not verify_password_for_uid(uid, password):
        record_failed_login(uid)
        audit_log("login_fail_password", uid=uid)
        return jsonify({"st": "error", "msg": "Invalid credentials"}), 401

    user = USER_STORE.get(uid, {})
    if not user.get("totp_enabled"):
        audit_log("login_blocked_2fa_setup_required", uid=uid)
        return jsonify({"st": "2fa_setup_required",
                        "msg": "2FA is required on this account — set it up via /api/auth/2fa/setup, "
                               "confirm via /api/auth/2fa/enable, then log in again"}), 403

    if not verify_2fa(uid, code_2fa):
        record_failed_login(uid)
        audit_log("login_fail_2fa", uid=uid)
        return jsonify({"st": "error", "msg": "Invalid 2FA code"}), 401

    clear_failed_logins(uid)
    is_new_device = register_device(uid, device_id)
    if is_new_device:
        audit_log("new_device", uid=uid, device_id=device_id)
    token = generate_jwt(uid, device_id)
    rt    = issue_refresh_token(uid)
    audit_log("login_ok", uid=uid, device_id=device_id)
    device_mode = getattr(request, "vmax_device_mode", None) or "pass"
    try:
        if body.get("device_gate_token"):
            device_mode = vmax_device_gate_token_mode(body.get("device_gate_token")) or device_mode
    except Exception:
        pass
    return jsonify({
        "st": "ok",
        "token": token,
        "refresh_token": rt,
        "new_device": is_new_device,
        "device_mode": device_mode,
        "compat_mode": device_mode == "compat",
        "msg_device": ("เข้าเล่นแบบจำกัด — ใช้อุปกรณ์ที่ไม่ถึงเกณฑ์ / ร่วมระบบเก่าได้"
                      if device_mode == "compat" else None),
    })

@app.route('/api/auth/refresh', methods=['POST'])
def api_refresh():
    body = request.json or {}
    # หมายเหตุ: จุดนี้ปกติจะไม่มี JWT ที่ valid อยู่แล้ว (คือเหตุผลที่ต้องมา refresh) ดังนั้น
    # resolve_uid() แทบทุกครั้งจะ fallback ไป uid ใน body แล้ว log ไว้ — เป็นพฤติกรรมที่คาดหวัง
    # ไม่ใช่ช่องโหว่ เพราะ verify_refresh_token() ด้านล่างตรวจ rt (refresh tokenลับ) แยกอีกชั้น
    uid, rt = resolve_uid(body), body.get('refresh_token')
    if not verify_refresh_token(uid, rt):
        return jsonify({"st": "error", "msg": "Invalid refresh token"}), 401
    device_id  = body.get('device_id', 'default-device')
    token      = generate_jwt(uid, device_id)
    new_rt     = rotate_refresh_token(uid)   # invalidates the old refresh token
    return jsonify({"st": "ok", "token": token, "refresh_token": new_rt})

