@app.route('/api/gacha/pull', methods=['POST'])
@require_auth
def api_gacha_pull():
    # [BUG-FIX #GLM-1] เดิมไม่มี @require_auth เลย — ใช้ P["uid"] ซึ่งพึ่งพา fallback
    # ใน _vmax_bind_current_uid ที่ (ก่อนแก้) อ่าน uid จาก body ตรงๆ แบบไม่ตรวจสอบ —
    # ผู้เรียกที่ไม่มี JWT ส่ง {"uid": "เหยื่อ"} มาสั่งสุ่มกาชาแล้วหักเครดิตของเหยื่อ
    # ได้ทันที ตอนนี้บังคับ auth แล้วใช้ uid จาก JWT session (request.vmax_uid) เท่านั้น
    body = request.json or {}
    count = int(body.get('count', 1))
    uid = request.vmax_uid
    ok, msg, results = gacha_pull(uid, count)
    if not ok:
        return jsonify({"st": "error", "msg": msg}), 400
    return jsonify({
        "st": "ok",
        "results": results,
        "credits": P["credits"],
        "pity": gacha_pity_status(uid),
    })

