@app.route('/api/router/auto_setup_repeater', methods=['POST'])
@require_staff_rank('admin')   # [SEC-AUDIT] เดิมผู้เล่นทั่วไปสั่งให้เซิร์ฟเวอร์เปิดเบราว์เซอร์ไปที่ IP ใดก็ได้ (SSRF)
def api_router_auto_setup_repeater():
    """สั่งสคริปต์ Selenium ไปตั้งค่า Xplor RE1200R4GC ให้เป็นโหมด Repeater
    อัตโนมัติ — ดูข้อจำกัด/สิ่งที่ต้องติดตั้งก่อนใน docstring ของ
    auto_setup_xplor_repeater() ด้านบน"""
    body = request.json or {}
    required = ["router_ip", "router_user", "router_pass", "home_ssid", "home_pass", "new_ssid", "new_pass"]
    missing = [k for k in required if not body.get(k)]
    if missing:
        return jsonify({"st": "error", "msg": f"ขาดข้อมูล: {', '.join(missing)}"}), 400
    try:
        _rip = _vs_ip.ip_address(str(body["router_ip"]).strip())
    except ValueError:
        return jsonify({"st": "error", "msg": "router_ip ต้องเป็น IP address"}), 400
    if (not _rip.is_private or _rip.is_loopback or _rip.is_link_local
            or _rip.is_unspecified or _rip.is_multicast):
        return jsonify({"st": "error", "msg": "router_ip ต้องเป็น IP ในวงแลนส่วนตัวของ router เท่านั้น"}), 400
    body["router_ip"] = str(_rip)
    ok, msg = auto_setup_xplor_repeater(
        body["router_ip"], body["router_user"], body["router_pass"],
        body["home_ssid"], body["home_pass"], body["new_ssid"], body["new_pass"])
    return jsonify({"st": "ok" if ok else "error", "msg": msg})

