@app.route('/api/models/<mid>/animation/extract', methods=['POST'])
@require_auth_toggleable
def api_model_extract_animation(mid):
    """สกัดอนิเมชันจริงจากรูปภาพ — field: 'preset' (ชื่อ เช่น walk/run/idle หรือ
    ชื่อเองก็ได้), field: 'frames' (แนบรูปได้หลายไฟล์ เรียงตามลำดับเฟรม)
    ตัวอย่าง curl:
      curl -F preset=walk -F frames=@f1.jpg -F frames=@f2.jpg -F frames=@f3.jpg \\
           http://127.0.0.1:5000/api/models/<mid>/animation/extract"""
    if mid not in MODEL_REGISTRY:
        return jsonify({"st": "error", "msg": f"ไม่พบโมเดล {mid}"}), 404
    preset = (request.form.get('preset') or '').strip()
    if not preset:
        return jsonify({"st": "error", "msg": "ต้องระบุ preset (ชื่ออนิเมชัน เช่น walk)"}), 400
    files = request.files.getlist('frames')
    if not files:
        return jsonify({"st": "error", "msg": "ต้องแนบรูปอย่างน้อย 1 ไฟล์ (field: frames) "
                                                "— แนบหลายรูปเรียงลำดับเฟรมจะได้อนิเมชันที่เคลื่อนไหวจริง"}), 400
    image_files = [(secure_filename(f.filename or f"frame{i}.jpg"), f.read())
                   for i, f in enumerate(files)]
    result = build_animation_from_images(mid, preset, image_files)
    return jsonify(result), (200 if result.get("st") == "ok" else 400)

@app.route('/api/models/<mid>/animation/<preset>')
def api_model_get_animation(mid, preset):
    m = MODEL_REGISTRY.get(mid)
    if not m:
        return jsonify({"st": "error", "msg": f"ไม่พบโมเดล {mid}"}), 404
    anim = m["animations"].get(preset)
    if anim is None:
        return jsonify({"st": "error", "msg": f"ไม่พบอนิเมชันชื่อ {preset} ในโมเดลนี้"}), 404
    return jsonify({"st": "ok", "preset": preset, "animation": anim})


# ==========================================
# [ 6f2. Cross-Engine Bridge Routes ]
# These are what VMAXBridge.cs (Unity side) actually calls. No auth on
# purpose here since it's meant for localhost/LAN dev use between your own
# two programs — if you expose this beyond your own machine, put it behind
# the same auth/session system the rest of the API already uses.
# ==========================================
@app.route('/api/bridge/push', methods=['POST'])
@require_auth_toggleable
def api_bridge_push():
    body = request.json or {}
    source = body.get('source', 'unknown')
    ev_type = body.get('type', 'event')
    data = body.get('data') or {}
    ev = bridge_push_event(source, ev_type, data)
    # กรณีพิเศษ: ถ้าเป็นการรายงานตำแหน่งวัตถุของเกมฝั่งที่เชื่อมเข้ามา ให้เก็บลง
    # BRIDGE_MAP_OBJECTS ด้วยเลย (นอกเหนือจากที่บันทึกเป็น event ปกติข้างบน) เพื่อ
    # ให้หน้า /map ดึงไปโชว์แยกสีจากวัตถุของเกมนี้เองได้ — data ต้องมี id, x, y
    # (label ไม่บังคับ) เช่น: {"source":"unity","type":"map_object_position",
    #  "data":{"id":"npc_42","x":3.2,"y":-1.1,"label":"NPC ทหาร"}}
    if ev_type == 'map_object_position' and 'id' in data and 'x' in data and 'y' in data:
        try:
            bridge_update_map_object(source, str(data['id']), float(data['x']), float(data['y']),
                                     data.get('label'))
        except (TypeError, ValueError):
            pass
    return jsonify({"st": "ok", "event": ev})

