@app.route('/api/bridge/client/<lang>')
def api_bridge_client(lang):
    key = lang.strip().lower()
    if key in BRIDGE_CLIENT_TEMPLATES:
        tpl = BRIDGE_CLIENT_TEMPLATES[key]
        return jsonify({"st": "ok", "source": "builtin", "lang": key,
                        "ext": tpl["ext"], "label": tpl["label"], "code": tpl["code"]})

    # Not one of the hand-written templates — ask your own local AI to write one,
    # using the same protocol description so it targets the real endpoints.
    # This is the honest way to "support every language": pre-written & reviewed
    # for common ones above, generated fresh (and NOT auto-verified) for anything
    # else — you should read generated code before running it, same as the
    # feature terminal.
    desc = (f"เขียนไคลเอนต์สำหรับภาษา {key} ที่คุยกับ REST bridge นี้:\n{BRIDGE_PROTOCOL_DESC}"
             "ให้ poll /api/bridge/pull ทุก 2 วินาที แล้ว handle event ที่ได้มา "
             "และมีฟังก์ชันสำหรับ POST ไปที่ /api/bridge/push ด้วย")
    code, _bridge_ctx = generate_feature_code(desc, key)
    return jsonify({"st": "ok", "source": "ai_generated", "lang": key,
                    "ext": _lang_config(key)["ext"], "label": key, "code": code,
                    "note": "โค้ดนี้สร้างจาก AI ของคุณเอง ยังไม่ผ่านการตรวจ ต้องอ่าน/ทดสอบเองก่อนใช้จริง"})


