@app.route('/api/shop/topup-callback', methods=['POST'])
def api_shop_topup_callback():
    """เว็บไซต์เรียก endpoint นี้หลังผู้เล่นเติมเงินสำเร็จ -> เครดิตเข้ากระเป๋ากลาง
    [SEC-AUDIT] เดิมไม่มีการยืนยันตัวตนเลย ใครก็ POST amount_credits เท่าไรก็ได้มาเสกเครดิตให้ตัวเอง ตอนนี้ fail-closed:
      - ต้องตั้ง env VMAX_TOPUP_CALLBACK_SECRET (ถ้าไม่ตั้ง endpoint ปิด 503 — แนะนำใช้ Omise webhook แทน)
      - เว็บต้องเซ็น: X-Topup-Timestamp (วินาที, คลาดได้ไม่เกิน 5 นาที) และ
        X-Topup-Signature = HMAC-SHA256(secret, f"{timestamp}.{raw_body}") แบบ hex
      - body: {uid, amount_credits, order_id, game_id?} ต้องมี uid + order_id, จำนวนจำกัด, order_id ซ้ำไม่เครดิตซ้ำ"""
    secret = os.environ.get("VMAX_TOPUP_CALLBACK_SECRET", "").strip()
    if not secret:
        return jsonify({"st": "error", "msg": "topup-callback ปิดอยู่ (ยังไม่ได้ตั้ง VMAX_TOPUP_CALLBACK_SECRET)"}), 503
    raw = request.get_data()
    ts = request.headers.get("X-Topup-Timestamp", "")
    sig = request.headers.get("X-Topup-Signature", "")
    try:
        ts_ok = abs(time.time() - float(ts)) <= 300
    except ValueError:
        ts_ok = False
    expected = _vs_hmac.new(secret.encode("utf-8"), ts.encode("utf-8") + b"." + raw, "sha256").hexdigest()
    if not ts_ok or not _vs_hmac.compare_digest(sig, expected):
        audit_log("topup_callback_bad_signature", uid="", ip=request.remote_addr)
        return jsonify({"st": "error", "msg": "invalid signature"}), 401
    data = request.get_json(silent=True) or {}
    amount = data.get("amount_credits", 0)
    if (isinstance(amount, bool) or not isinstance(amount, (int, float)) or not math.isfinite(amount)
            or amount <= 0 or amount > 1_000_000):
        return jsonify({"st": "error", "msg": "amount_credits ต้องเป็นตัวเลข 0 < x <= 1,000,000"}), 400
    order_id = str(data.get("order_id") or "").strip()[:128]
    uid = str(data.get("uid") or "").strip()[:128]
    if not order_id or not uid:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid และ order_id"}), 400
    if any(h.get("order_id") == order_id and h.get("source") == "website_topup" for h in WALLET["history"]):
        return jsonify({"st": "ok", "msg": "order นี้ประมวลผลแล้ว (idempotent)", "duplicate": True})
    set_current_uid(uid)
    P["credits"] += amount
    WALLET["balance"] = P["credits"]
    WALLET["history"].append({"ts": time.time(), "source": "website_topup", "uid": uid,
                               "game_id": data.get("game_id", CURRENT_GAME_ID),
                               "amount": amount, "order_id": order_id})
    audit_log("topup_callback_ok", uid=uid, order_id=order_id, amount=amount)
    return jsonify({"st": "ok", "new_balance": P["credits"]})

