@app.route('/api/launcher/game/<game_id>/wallet/calendar')
def api_wallet_calendar(game_id):
    """คืนประวัติการซื้อของในร้านค้า/เติมเงินผ่านเว็บไซต์ของเกมนี้ (จากกระเป๋าเงินกลาง
    WALLET) พร้อมวันที่ (YYYY-MM-DD) ให้ฝั่งหน้าเว็บเอาไปทำเครื่องหมายบนปฏิทินเดียวกับ
    ของขวัญล็อกอิน แล้วคลิกดูรายละเอียดรายวันได้"""
    out = []
    for h in WALLET["history"]:
        if h.get("game_id") != game_id:
            continue
        date_str = datetime.utcfromtimestamp(h["ts"]).strftime("%Y-%m-%d")
        entry = {"date": date_str}
        if "item" in h:
            entry.update({"type": "purchase", "label": h["item"], "price": h["price"], "currency": h["currency"]})
        elif h.get("source") == "website_topup":
            entry.update({"type": "topup", "label": f"เติมเครดิตผ่านเว็บไซต์ {h['amount']}", "amount": h["amount"]})
        else:
            entry.update({"type": "other", "label": "รายการอื่นๆ"})
        out.append(entry)
    return jsonify({"st": "ok", "entries": out})

