# --- Community game uploads: dev คนอื่นส่ง .exe/.apk มาให้คนเล่นโหลดไปเล่นเอง -----
def _current_uid() -> str | None:
    """อ่าน uid จาก Bearer token ใน header (ใช้ระบบ JWT เดียวกับ /api/auth/*).
    คืน None ถ้าไม่ได้ล็อกอิน/token หมดอายุ — ใช้เช็คสิทธิ์ก่อนอัปโหลด/ลบเกม"""
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    sess = verify_jwt(token)
    return sess["uid"] if sess else None

@app.route('/api/games/upload', methods=['POST'])
@require_auth_toggleable
def api_games_upload():
    uid = _current_uid()
    if not uid:
        return jsonify({"st": "error", "msg": "ต้องล็อกอินก่อนถึงจะอัปโหลดเกมได้"}), 401

    f = request.files.get('file')
    if not f or not f.filename:
        return jsonify({"st": "error", "msg": "ไม่พบไฟล์ที่ส่งมา"}), 400

    ext = _game_ext(f.filename)
    if ext not in ALLOWED_GAME_EXTENSIONS:
        return jsonify({
            "st": "error",
            "msg": f"รองรับเฉพาะไฟล์ {', '.join('.' + e for e in sorted(ALLOWED_GAME_EXTENSIONS))} เท่านั้น"
        }), 400

    game_name = (request.form.get('name') or f.filename).strip()[:80]
    dev_name = (request.form.get('dev') or 'ไม่ระบุ').strip()[:60]
    description = (request.form.get('description') or '').strip()[:500]

    game_id = uuid.uuid4().hex[:12]
    safe_filename = secure_filename(f.filename) or f"game.{ext}"

    if _s3:
        s3_key = f"{game_id}/{safe_filename}"
        try:
            _s3.upload_fileobj(f.stream, S3_BUCKET, s3_key)
            size_bytes = _s3.head_object(Bucket=S3_BUCKET, Key=s3_key)["ContentLength"]
        except Exception as e:
            return jsonify({"st": "error", "msg": f"อัปโหลดขึ้น S3 ไม่สำเร็จ: {e}"}), 500
        storage, local_ref = "s3", None
    else:
        # [SECURITY-FIX U1] เหลือพื้นที่ดิสก์ไม่พอ = ปฏิเสธก่อนเขียน (กัน disk exhaustion)
        try:
            _free = _vmax_kernel_shutil.disk_usage(GAME_UPLOADS_DIR).free
        except Exception:
            _free = None
        if _free is not None and (_free - int(request.content_length or 0)) < GAME_UPLOAD_MIN_FREE_BYTES:
            return jsonify({"st": "error", "msg": "พื้นที่ดิสก์เซิร์ฟเวอร์ไม่พอสำหรับอัปโหลดตอนนี้"}), 507
        game_dir = os.path.join(GAME_UPLOADS_DIR, game_id)
        os.makedirs(game_dir, exist_ok=True)
        save_path = os.path.join(game_dir, safe_filename)
        f.save(save_path)
        size_bytes = os.path.getsize(save_path)
        if size_bytes <= 0 or size_bytes > MAX_GAME_UPLOAD_BYTES:
            try:
                os.remove(save_path)
            except OSError:
                pass
            return jsonify({"st": "error", "msg": "ขนาดไฟล์ไม่อยู่ในเกณฑ์ที่อนุญาต"}), 400
        storage, s3_key, local_ref = "local", None, save_path

    # Store security gate: scan uploaded game files before they enter the public catalog.
    # Internal server-side only; there is intentionally no public antivirus endpoint.
    scan_result = store_security_scan(local_ref)
    if scan_result.get("status") == "malicious":
        try:
            os.remove(local_ref)
            os.rmdir(os.path.dirname(local_ref))
        except OSError:
            pass
        return jsonify({"st": "error", "msg": "ไฟล์ถูกปฏิเสธจากระบบตรวจสอบความปลอดภัยของ Store",
                        "security_scan": scan_result}), 422
    if scan_result.get("status") == "error" and STORE_SCAN_FAIL_CLOSED:
        try:
            os.remove(local_ref)
            os.rmdir(os.path.dirname(local_ref))
        except OSError:
            pass
        return jsonify({"st": "error", "msg": "ยังไม่สามารถยืนยันความปลอดภัยของไฟล์ได้ — Store ปฏิเสธการเผยแพร่ชั่วคราว",
                        "security_scan": scan_result}), 503

    entry = {
        "id": game_id,
        "name": game_name,
        "dev": dev_name,
        "owner_uid": uid,  # ใช้เช็คสิทธิ์ลบทีหลัง — เฉพาะคนที่อัปโหลด (หรือแอดมิน) ลบได้
        "description": description,
        "filename": safe_filename,
        "platform": "Android (.apk)" if ext == "apk" else "Windows (.exe)",
        "ext": ext,
        "storage": storage,   # "s3" หรือ "local"
        "s3_key": s3_key,
        "size_bytes": size_bytes,
        "uploaded_at": time.time(),
        "security_scan": scan_result,
    }
    idx = _load_games_index()
    idx[game_id] = entry
    _save_games_index(idx)
    return jsonify({"st": "ok", "msg": f"อัปโหลด '{game_name}' สำเร็จ", "game": entry})

# --- Browser → S3 โดยตรง (ไม่ผ่านเซิร์ฟเวอร์นี้เลย) — ดูคำอธิบายเรื่อง CORS ---
# ในคอมเมนต์แถว S3_MULTIPART_THRESHOLD ด้านบน ต้องมี _s3 (ตั้ง S3_BUCKET) ก่อน
# ถึงจะใช้เส้นทางนี้ได้ — ถ้าไม่มี ให้ใช้ /api/games/upload (relay ผ่านเซิร์ฟเวอร์) แทน
@app.route('/api/games/upload_init', methods=['POST'])
@require_auth_toggleable
def api_games_upload_init():
    uid = _current_uid()
    if not uid:
        return jsonify({"st": "error", "msg": "ต้องล็อกอินก่อนถึงจะอัปโหลดเกมได้"}), 401
    if not _s3:
        return jsonify({"st": "error", "msg": "เซิร์ฟเวอร์นี้ไม่ได้ตั้งค่า S3 ไว้ (ไม่มี S3_BUCKET) — "
                                               "ใช้ /api/games/upload แทน"}), 400

    body = request.json or {}
    filename = (body.get('filename') or '').strip()
    file_size = int(body.get('file_size') or 0)
    ext = _game_ext(filename)
    if ext not in ALLOWED_GAME_EXTENSIONS:
        return jsonify({"st": "error",
                        "msg": f"รองรับเฉพาะไฟล์ {', '.join('.' + e for e in sorted(ALLOWED_GAME_EXTENSIONS))} เท่านั้น"}), 400
    if file_size <= 0 or file_size > MAX_GAME_UPLOAD_BYTES:
        return jsonify({"st": "error", "msg": f"ขนาดไฟล์ต้องมากกว่า 0 และไม่เกิน {MAX_GAME_UPLOAD_BYTES} bytes"}), 400

    game_id = uuid.uuid4().hex[:12]
    safe_filename = secure_filename(filename) or f"game.{ext}"
    s3_key = f"{game_id}/{safe_filename}"

    pending = _load_pending_uploads()
    meta = {
        "owner_uid": uid,
        "s3_key": s3_key,
        "filename": safe_filename,
        "ext": ext,
        "name": (body.get('name') or safe_filename).strip()[:80],
        "dev": (body.get('dev') or 'ไม่ระบุ').strip()[:60],
        "description": (body.get('description') or '').strip()[:500],
        "file_size": file_size,
    }

    if file_size <= S3_MULTIPART_THRESHOLD:
        try:
            upload_url = _s3.generate_presigned_url(
                'put_object', Params={'Bucket': S3_BUCKET, 'Key': s3_key}, ExpiresIn=3600)
        except Exception as e:
            return jsonify({"st": "error", "msg": f"ขอ presigned URL ไม่สำเร็จ: {e}"}), 500
        meta["mode"] = "single"
        pending[game_id] = meta
        _save_pending_uploads(pending)
        return jsonify({"st": "ok", "mode": "single", "game_id": game_id, "upload_url": upload_url})

    # ไฟล์ใหญ่กว่า threshold -> multipart upload หลาย part แยก presigned URL ต่อ part
    try:
        mpu = _s3.create_multipart_upload(Bucket=S3_BUCKET, Key=s3_key)
        upload_id = mpu["UploadId"]
        num_parts = math.ceil(file_size / S3_PART_SIZE)
        part_urls = []
        for part_no in range(1, num_parts + 1):
            purl = _s3.generate_presigned_url(
                'upload_part',
                Params={'Bucket': S3_BUCKET, 'Key': s3_key, 'UploadId': upload_id, 'PartNumber': part_no},
                ExpiresIn=4 * 3600)
            part_urls.append(purl)
    except Exception as e:
        return jsonify({"st": "error", "msg": f"เริ่ม multipart upload ไม่สำเร็จ: {e}"}), 500

    meta["mode"] = "multipart"
    meta["upload_id"] = upload_id
    pending[game_id] = meta
    _save_pending_uploads(pending)
    return jsonify({"st": "ok", "mode": "multipart", "game_id": game_id,
                    "part_urls": part_urls, "part_size": S3_PART_SIZE})

@app.route('/api/games/upload_complete', methods=['POST'])
@require_auth_toggleable
def api_games_upload_complete():
    uid = _current_uid()
    if not uid:
        return jsonify({"st": "error", "msg": "ต้องล็อกอินก่อน"}), 401

    body = request.json or {}
    game_id = body.get('game_id')
    pending = _load_pending_uploads()
    meta = pending.get(game_id)
    if not meta:
        return jsonify({"st": "error", "msg": "ไม่พบ upload session นี้ (อาจหมดอายุ หรือ complete ไปแล้ว)"}), 404
    if meta["owner_uid"] != uid:
        return jsonify({"st": "error", "msg": "ไม่ใช่ upload ของบัญชีนี้"}), 403

    if meta["mode"] == "multipart":
        parts = body.get('parts') or []  # [{PartNumber, ETag}, ...] จาก response header ตอน browser PUT แต่ละ part
        if not parts:
            return jsonify({"st": "error", "msg": "ต้องส่ง parts (PartNumber + ETag ของทุก part) มาด้วย"}), 400
        try:
            _s3.complete_multipart_upload(
                Bucket=S3_BUCKET, Key=meta["s3_key"], UploadId=meta["upload_id"],
                MultipartUpload={"Parts": [{"ETag": p["ETag"], "PartNumber": p["PartNumber"]} for p in parts]})
        except Exception as e:
            return jsonify({"st": "error", "msg": f"complete multipart upload ไม่สำเร็จ: {e}"}), 500

    try:
        size_bytes = _s3.head_object(Bucket=S3_BUCKET, Key=meta["s3_key"])["ContentLength"]
    except Exception as e:
        return jsonify({"st": "error", "msg": f"ตรวจไฟล์บน S3 ไม่สำเร็จหลังอัปโหลด: {e}"}), 500

    # Direct-to-S3 uploads still pass through the same internal Store security gate.
    scan_tmp = None
    try:
        with tempfile.NamedTemporaryFile(prefix="vmax_store_scan_", suffix=".bin", delete=False) as tf:
            scan_tmp = tf.name
        _s3.download_file(S3_BUCKET, meta["s3_key"], scan_tmp)
        scan_result = store_security_scan(scan_tmp)
    except Exception as e:
        scan_result = {"status": "error", "engine": "s3-download", "detail": str(e)}
    finally:
        if scan_tmp:
            try:
                os.remove(scan_tmp)
            except OSError:
                pass

    if scan_result.get("status") == "malicious" or (scan_result.get("status") == "error" and STORE_SCAN_FAIL_CLOSED):
        try:
            _s3.delete_object(Bucket=S3_BUCKET, Key=meta["s3_key"])
        except Exception:
            pass
        pending.pop(game_id, None)
        _save_pending_uploads(pending)
        code = 422 if scan_result.get("status") == "malicious" else 503
        msg = ("ไฟล์ถูกปฏิเสธจากระบบตรวจสอบความปลอดภัยของ Store"
               if code == 422 else
               "ยังไม่สามารถยืนยันความปลอดภัยของไฟล์ได้ — Store ปฏิเสธการเผยแพร่ชั่วคราว")
        return jsonify({"st": "error", "msg": msg, "security_scan": scan_result}), code

    entry = {
        "id": game_id,
        "name": meta["name"],
        "dev": meta["dev"],
        "owner_uid": uid,
        "description": meta["description"],
        "filename": meta["filename"],
        "platform": "Android (.apk)" if meta["ext"] == "apk" else "Windows (.exe)",
        "ext": meta["ext"],
        "storage": "s3",
        "s3_key": meta["s3_key"],
        "size_bytes": size_bytes,
        "uploaded_at": time.time(),
        "security_scan": scan_result,
    }
    idx = _load_games_index()
    idx[game_id] = entry
    _save_games_index(idx)
    pending.pop(game_id, None)
    _save_pending_uploads(pending)
    return jsonify({"st": "ok", "msg": f"อัปโหลด '{entry['name']}' สำเร็จ (ตรงจาก browser ไป S3)", "game": entry})

@app.route('/api/games/upload_abort', methods=['POST'])
@require_auth_toggleable
def api_games_upload_abort():
    uid = _current_uid()
    if not uid:
        return jsonify({"st": "error", "msg": "ต้องล็อกอินก่อน"}), 401
    body = request.json or {}
    game_id = body.get('game_id')
    pending = _load_pending_uploads()
    meta = pending.get(game_id)
    if not meta or meta["owner_uid"] != uid:
        return jsonify({"st": "error", "msg": "ไม่พบ upload session นี้"}), 404
    if meta["mode"] == "multipart" and _s3:
        try:
            _s3.abort_multipart_upload(Bucket=S3_BUCKET, Key=meta["s3_key"], UploadId=meta["upload_id"])
        except Exception:
            pass
    pending.pop(game_id, None)
    _save_pending_uploads(pending)
    return jsonify({"st": "ok", "msg": "ยกเลิกอัปโหลดแล้ว"})

@app.route('/api/games/list')
def api_games_list():
    idx = _load_games_index()
    games = sorted(idx.values(), key=lambda g: g.get("uploaded_at", 0), reverse=True)
    return jsonify(games)

@app.route('/games/download/<game_id>')
def games_download(game_id):
    idx = _load_games_index()
    entry = idx.get(game_id)
    if not entry:
        return jsonify({"st": "error", "msg": "ไม่พบเกมนี้"}), 404
    if entry.get("storage") == "s3":
        if not _s3:
            return jsonify({"st": "error", "msg": "ไฟล์นี้อยู่บน S3 แต่เซิร์ฟเวอร์ตอนนี้ไม่ได้ตั้งค่า S3 ไว้"}), 500
        try:
            url = _s3.generate_presigned_url(
                "get_object",
                Params={
                    "Bucket": S3_BUCKET,
                    "Key": entry["s3_key"],
                    "ResponseContentDisposition": f'attachment; filename="{entry["filename"]}"',
                },
                ExpiresIn=S3_PRESIGNED_URL_TTL,
            )
        except Exception as e:
            return jsonify({"st": "error", "msg": f"สร้างลิงก์โหลดจาก S3 ไม่สำเร็จ: {e}"}), 500
        return redirect(url)
    game_dir = os.path.join(GAME_UPLOADS_DIR, game_id)
    return send_from_directory(game_dir, entry["filename"], as_attachment=True)

@app.route('/api/games/delete/<game_id>', methods=['POST'])
@require_auth_toggleable
def api_games_delete(game_id):
    uid = _current_uid()
    if not uid:
        return jsonify({"st": "error", "msg": "ต้องล็อกอินก่อน"}), 401
    idx = _load_games_index()
    entry = idx.get(game_id)
    if not entry:
        return jsonify({"st": "error", "msg": "ไม่พบเกมนี้"}), 404
    if entry.get("owner_uid") != uid:
        return jsonify({"st": "error", "msg": "ลบได้เฉพาะเกมที่ตัวเองอัปโหลดเท่านั้น"}), 403
    idx.pop(game_id, None)
    _save_games_index(idx)
    if entry.get("storage") == "s3" and _s3:
        try:
            _s3.delete_object(Bucket=S3_BUCKET, Key=entry["s3_key"])
        except Exception:
            pass
    else:
        game_dir = os.path.join(GAME_UPLOADS_DIR, game_id)
        try:
            os.remove(os.path.join(game_dir, entry["filename"]))
            os.rmdir(game_dir)
        except OSError:
            pass
    return jsonify({"st": "ok", "msg": f"ลบ '{entry['name']}' แล้ว"})

