# [ 6j3. Central Code Registry Routes ]
# ที่เก็บกลางของโค้ดที่ "ซ่อม/ทำเสร็จแล้ว" — ดู [ 2J2 ] ด้านบนสำหรับกลไกจริง
# ==========================================
@app.route('/api/registry', methods=['GET'])
def api_registry_list():
    """รายชื่อโค้ดทั้งหมดในที่เก็บกลาง พร้อมสรุปจำนวน version ของแต่ละชื่อ"""
    idx = _load_registry()
    return jsonify({name: {"versions": len(v), "latest": v[-1]}
                    for name, v in idx.items()})

@app.route('/api/registry/<name>', methods=['GET'])
def api_registry_get(name):
    """ประวัติทุก version ของโค้ดชื่อนี้ (หรือระบุ ?version=N เพื่อดูตัวเดียว)"""
    version = request.args.get('version', type=int)
    if version is not None:
        rec = get_registry_entry(name, version)
        return (jsonify(rec) if rec else
                jsonify({"st": "error", "msg": "ไม่พบ version นี้"})), (200 if rec else 404)
    versions = _load_registry().get((name or "").strip().lower().replace(" ", "_"))
    if not versions:
        return jsonify({"st": "error", "msg": "ไม่พบชื่อนี้ในที่เก็บกลาง"}), 404
    return jsonify(versions)

@app.route('/api/registry/<name>/code', methods=['GET'])
def api_registry_get_code(name):
    """ดึงโค้ดดิบ (ล่าสุด หรือ ?version=N) ให้ระบบภายนอก/bridge client ต่อ API
    เข้ามาเอาไปใช้ได้เลย — ใช้อัตโนมัติจริงได้เฉพาะ target python เท่านั้น"""
    version = request.args.get('version', type=int)
    rec = get_registry_entry(name, version)
    if not rec:
        return jsonify({"st": "error", "msg": "ไม่พบโค้ดชื่อนี้"}), 404
    with open(rec["path"], "r", encoding="utf-8") as f:
        code = f.read()
    return jsonify({"st": "ok", "name": rec["name"], "version": rec["version"],
                    "target": rec["target"], "description": rec["description"],
                    "code": code})

@app.route('/api/registry/store', methods=['POST'])
@require_auth_toggleable
def api_registry_store():
    """เพิ่มโค้ดที่ซ่อม/ทำเสร็จแล้วเข้าที่เก็บกลางตรงๆ โดยไม่ต้องผ่านขั้นตอน
    propose/approve (เช่น โค้ดที่แก้เสร็จนอกระบบนี้อยู่แล้ว)"""
    body = request.json or {}
    name = (body.get('name') or '').strip()
    code = body.get('code') or ''
    if not name or not code:
        return jsonify({"st": "error", "msg": "ต้องระบุ name และ code"}), 400
    record = register_fixed_code(name=name, code=code,
                                 target=body.get('target', 'python'),
                                 description=body.get('description', ''))
    return jsonify({"st": "ok", "registry": record})


