# ==========================================
# [ 2h. WiFi Hotspot — ส่วนตัว (มีรหัสผ่าน) แต่ออกอินเทอร์เน็ตได้จริง ]
# แก้ตามที่คุยกันรอบล่าสุด: ไม่ใช่ "ปิดไม่ให้ออกเน็ต" แบบก่อนหน้านี้แล้ว —
# ตอนนี้แชร์อินเทอร์เน็ตจริงจากเครื่องโฮสต์ให้อุปกรณ์ที่ต่อเข้ามา "ส่วนตัว"
# หมายถึง: มีรหัสผ่าน WPA2 ต้องรู้รหัสถึงต่อได้ (ไม่ใช่ open network ที่ใครก็ต่อได้)
# "ไม่ใช่สาธารณะ" ไม่ได้แปลว่า "ตัดไม่ให้ออกเน็ต" — สองเรื่องนี้คนละเรื่องกัน:
#   - private/public  = ใครต่อได้บ้าง (ตรงนี้คุมด้วยรหัสผ่านอยู่แล้ว)
#   - internet access = ต่อแล้วออกเน็ตได้ไหม (ตรงนี้คือสิ่งที่เพิ่มให้รอบนี้)
#
# ข้อจำกัดที่ต้องรู้ตรงๆ (ไม่ใช่ทุก OS ทำได้เท่ากัน):
#   - Linux   : ทำได้ตรงไปตรงมา — nmcli โหมด "shared" จัดการ NAT+DHCP ให้เองหมด
#   - Windows : ทำได้ แต่ Windows ไม่มีคำสั่ง netsh ตัวเดียวเปิด ICS (Internet
#               Connection Sharing) ตรงๆ ต้องสั่งผ่าน COM object (HNetCfg.HNetShare)
#               ด้วย PowerShell ซึ่ง "อาจไม่เสถียรเท่ากันทุกเครื่อง/ทุก Windows build"
#               ถ้าสคริปต์หาอะแดปเตอร์ไม่เจอ ให้ทำ manual แทน (มีบอกไว้ใน error message)
#   - macOS   : ไม่มีทาง script ที่เสถียรข้าม version ได้ — ต้องเปิดเองผ่าน
#               System Settings > General > Sharing > Internet Sharing
#   - Android : มือถือไม่ให้สคริปต์ธรรมดาสั่งเปิด hotspot ได้ (ต้องเป็นแอปเนทีฟ
#               ที่ขอสิทธิ์ LocalOnlyHotspot API) ทำจากไฟล์ Python นี้ตรงๆ ไม่ได้
# ==========================================
HOTSPOT_STATE = {"active": False, "ssid": None, "os": platform.system(),
                 "started_at": None, "internet_shared": False}

def _windows_enable_ics(internet_iface: str, hotspot_iface: str) -> tuple[bool, str]:
    """เปิด Internet Connection Sharing ผ่าน COM object — วิธีมาตรฐานที่ใช้กันจริง
    เพราะ netsh เองไม่มีคำสั่งเปิด ICS ตรงๆ ตั้งแต่ Windows 8 เป็นต้นมา"""
    ps_script = f'''
$ErrorActionPreference = "Stop"
$netShare = New-Object -ComObject HNetCfg.HNetShare
$found_public = $false; $found_private = $false
foreach ($conn in $netShare.EnumEveryConnection) {{
    $props = $netShare.NetConnectionProps.Invoke($conn)
    if ($props.Name -eq $env:VMAX_ICS_PUBLIC) {{
        $netShare.INetSharingConfigurationForINetConnection.Invoke($conn).EnableSharing(0)
        $found_public = $true
    }}
    if ($props.Name -eq $env:VMAX_ICS_PRIVATE) {{
        $netShare.INetSharingConfigurationForINetConnection.Invoke($conn).EnableSharing(1)
        $found_private = $true
    }}
}}
if (-not $found_public) {{ Write-Error "ไม่พบอะแดปเตอร์อินเทอร์เน็ตชื่อ '$env:VMAX_ICS_PUBLIC'" }}
if (-not $found_private) {{ Write-Error "ไม่พบอะแดปเตอร์ hostednetwork ชื่อ '$env:VMAX_ICS_PRIVATE'" }}
'''
    if not (_vs_valid_net_name(internet_iface) and _vs_valid_net_name(hotspot_iface)):
        return False, "ชื่ออะแดปเตอร์มีอักขระที่ไม่อนุญาต (ใช้ได้เฉพาะตัวอักษร/ตัวเลข เว้นวรรค . - * ( ))"
    try:
        # [SEC-AUDIT] ส่งชื่ออะแดปเตอร์ผ่าน env var ไม่ฝังในสคริปต์ PowerShell (เดิมแทรกสตริงตรงๆ = command injection)
        sp.run(["powershell", "-NoProfile", "-Command", ps_script],
               check=True, capture_output=True, text=True,
               env={**os.environ, "VMAX_ICS_PUBLIC": internet_iface, "VMAX_ICS_PRIVATE": hotspot_iface})
        return True, "เปิด ICS สำเร็จ"
    except sp.CalledProcessError as e:
        return False, (f"เปิด ICS อัตโนมัติไม่สำเร็จ ({(e.stderr or '').strip()}) — "
                        "ทำเองแทนได้: Control Panel > Network Connections > คลิกขวาที่การ์ดเน็ตที่ต่อ"
                        "อินเทอร์เน็ตจริง > Properties > แท็บ Sharing > ติ๊ก 'Allow other network "
                        "users to connect...' แล้วเลือกการ์ด 'Local Area Connection* (Microsoft "
                        "Hosted Network Virtual Adapter)' ในช่อง Home networking connection")


def start_lan_hotspot(ssid: str, password: str, iface: str = "",
                      internet_iface: str = "", hotspot_iface: str = "") -> tuple[bool, str]:
    if len(password) < 8:
        return False, "รหัสผ่านต้องยาวอย่างน้อย 8 ตัวอักษร (ข้อจำกัดของ WiFi WPA2)"
    if not _vs_valid_hotspot_params(ssid, password, iface):
        return False, "ssid/รหัสผ่าน/ชื่ออินเตอร์เฟซไม่ถูกต้อง (ssid 1-32 ตัว, รหัส 8-63 ตัว ASCII, ห้ามขึ้นต้นด้วย -)"
    system = platform.system()
    ics_msg = ""
    try:
        if system == "Windows":
            sp.run(["netsh", "wlan", "set", "hostednetwork", "mode=allow",
                    f"ssid={ssid}", f"key={password}"], check=True, capture_output=True, text=True)
            sp.run(["netsh", "wlan", "start", "hostednetwork"], check=True, capture_output=True, text=True)
            if internet_iface:
                hn_iface = hotspot_iface or "Local Area Connection* 1"
                ok, ics_msg = _windows_enable_ics(internet_iface, hn_iface)
            else:
                ics_msg = ("ยังไม่ได้แชร์เน็ต — ต้องระบุชื่ออะแดปเตอร์อินเทอร์เน็ตจริง (เช่น 'Wi-Fi' "
                          "หรือ 'Ethernet') มาด้วยถึงจะเปิด ICS ให้อัตโนมัติ")
        elif system == "Linux":
            iface = iface or "wlan0"
            sp.run(["nmcli", "connection", "delete", "vmax-hotspot"],
                   capture_output=True, text=True)  # ลบของเก่าถ้ามีค้าง ไม่ต้องเช็ค error
            sp.run(["nmcli", "connection", "add", "type", "wifi", "ifname", iface,
                    "con-name", "vmax-hotspot", "autoconnect", "no", "ssid", ssid],
                   check=True, capture_output=True, text=True)
            sp.run(["nmcli", "connection", "modify", "vmax-hotspot",
                    "802-11-wireless.mode", "ap", "802-11-wireless.band", "bg",
                    "wifi-sec.key-mgmt", "wpa-psk", "wifi-sec.psk", password,
                    # ipv4.method "shared" = nmcli จัดการ NAT + DHCP ให้เองอัตโนมัติ
                    # (ต่างจากก่อนหน้านี้ที่ตั้งเป็น "manual" เพื่อตัดเน็ต — รอบนี้ตั้งใจให้ออกเน็ตได้)
                    "ipv4.method", "shared"],
                   check=True, capture_output=True, text=True)
            sp.run(["nmcli", "connection", "up", "vmax-hotspot"],
                   check=True, capture_output=True, text=True)
            ics_msg = "แชร์อินเทอร์เน็ตอัตโนมัติผ่าน nmcli (NAT+DHCP จัดการให้เองแล้ว)"
        else:
            return False, (f"OS นี้ ({system}) ไม่รองรับการเปิด hotspot ผ่านสคริปต์ — "
                            "ดูคอมเมนต์ด้านบน def นี้สำหรับเหตุผลและทางเลือกของ macOS/Android")
    except sp.CalledProcessError as e:
        err = (e.stderr or str(e)).strip()
        return False, f"เปิด hotspot ไม่สำเร็จ: {err}"

    HOTSPOT_STATE.update({"active": True, "ssid": ssid, "started_at": time.time(),
                          "internet_shared": system == "Linux" or bool(internet_iface)})
    return True, f"เปิด hotspot ส่วนตัว '{ssid}' แล้ว (มีรหัสผ่าน ไม่ใช่ public) — {ics_msg}"

def stop_lan_hotspot() -> tuple[bool, str]:
    system = platform.system()
    try:
        if system == "Windows":
            sp.run(["netsh", "wlan", "stop", "hostednetwork"], check=True, capture_output=True, text=True)
        elif system == "Linux":
            sp.run(["nmcli", "connection", "down", "vmax-hotspot"], check=True, capture_output=True, text=True)
        else:
            return False, f"OS นี้ ({system}) ไม่รองรับการปิด hotspot ผ่านสคริปต์"
    except sp.CalledProcessError as e:
        err = (e.stderr or str(e)).strip()
        return False, f"ปิด hotspot ไม่สำเร็จ: {err}"

    HOTSPOT_STATE.update({"active": False, "ssid": None, "started_at": None, "internet_shared": False})

    return True, "ปิด hotspot แล้ว"

# ==========================================
# [ 2h2. Xplor RE1200R4GC-2T2R-V3 — Auto Repeater Setup ]
# สคริปต์ Selenium เปิดเบราว์เซอร์จำลองไปตั้งค่าโหมด Repeater ให้เองอัตโนมัติ
# ตามขั้นตอนจริงของหน้าเว็บ router (192.168.2.1) ที่คุยกันไว้ก่อนหน้า
#
# ข้อจำกัดที่ต้องรู้ตรงๆ ก่อนใช้:
#   1. ต้องติดตั้งเพิ่มเอง 2 อย่างในเครื่องที่จะรันเกมนี้ (ยังไม่ได้ติดตั้งให้อัตโนมัติ
#      เพราะเป็น dependency หนักและต้องมี Chrome ติดตั้งอยู่ในเครื่องด้วย):
#         pip install selenium webdriver-manager
#   2. selector (id/class/xpath ของปุ่มแต่ละปุ่ม) ด้านล่างนี้เป็นการเดาที่สมเหตุสมผล
#      จากคำอธิบายขั้นตอนที่หาข้อมูลมาได้ (Log in > Setup Wizard > Repeater >
#      กรอก SSID/รหัส > NEXT > เลือก WiFi บ้าน > กรอกรหัส > CONNECT) — ผมไม่มีทาง
#      เห็น HTML จริงของหน้าเว็บ router รุ่นนี้ ดังนั้น selector อาจไม่ตรงเป๊ะ
#      ทุกจุด ถ้าขั้นไหน fail ฟังก์ชันจะบันทึก screenshot ของขั้นตอนนั้นไว้ที่
#      /tmp/xplor_setup_fail_<step>.png ให้ส่งกลับมาดู จะได้แก้ selector ให้ตรงจุด
#   3. ต้องรู้รหัส login เข้าหน้า router เอง (ถ้าลืม ให้กดปุ่ม Reset ค้าง ~10 วิ
#      ที่ตัวเครื่องก่อน จะกลับไปเป็นรหัสเริ่มต้นตามสติ๊กเกอร์ใต้เครื่อง)
# ==========================================
def auto_setup_xplor_repeater(router_ip: str, router_user: str, router_pass: str,
                              home_ssid: str, home_pass: str,
                              new_ssid: str, new_pass: str) -> tuple[bool, str]:
    try:
        from selenium import webdriver
        from selenium.webdriver.common.by import By
        from selenium.webdriver.support.ui import WebDriverWait
        from selenium.webdriver.support import expected_conditions as EC
        from webdriver_manager.chrome import ChromeDriverManager
        from selenium.webdriver.chrome.service import Service
    except ImportError:
        return False, ("ยังไม่ได้ติดตั้ง selenium/webdriver-manager — รันคำสั่งนี้ก่อน:\n"
                       "pip install selenium webdriver-manager")

    def _fail_shot(driver, step: str, err: Exception) -> str:
        path = f"/tmp/xplor_setup_fail_{step}.png"
        try:
            driver.save_screenshot(path)
        except Exception:
            path = "(ถ่าย screenshot ไม่สำเร็จด้วย)"
        return f"ขั้นตอน '{step}' ล้มเหลว: {err} — screenshot: {path}"

    driver = webdriver.Chrome(service=Service(ChromeDriverManager().install()))
    wait = WebDriverWait(driver, 15)
    try:
        # ขั้น 1: เข้าหน้า login
        try:
            driver.get(f"http://{router_ip}/")
            user_field = wait.until(EC.presence_of_element_located((By.NAME, "username")))
            pass_field = driver.find_element(By.NAME, "password")
            user_field.send_keys(router_user)
            pass_field.send_keys(router_pass)
            driver.find_element(By.XPATH, "//button[contains(.,'Login') or contains(.,'LOGIN')]").click()
        except Exception as e:
            return False, _fail_shot(driver, "login", e)

        # ขั้น 2: กด SETUP WIZARD
        try:
            wizard_btn = wait.until(EC.element_to_be_clickable(
                (By.XPATH, "//*[contains(text(),'SETUP WIZARD') or contains(text(),'Setup Wizard')]")))
            wizard_btn.click()
        except Exception as e:
            return False, _fail_shot(driver, "setup_wizard", e)

        # ขั้น 3: เลือก Repeater แล้ว NEXT
        try:
            repeater_opt = wait.until(EC.element_to_be_clickable(
                (By.XPATH, "//*[contains(text(),'Repeater')]")))
            repeater_opt.click()
            driver.find_element(By.XPATH, "//button[contains(.,'NEXT') or contains(.,'Next')]").click()
        except Exception as e:
            return False, _fail_shot(driver, "select_repeater", e)

        # ขั้น 4: ตั้งชื่อ WiFi ใหม่ + รหัส แล้ว NEXT
        try:
            ssid_field = wait.until(EC.presence_of_element_located((By.NAME, "ssid")))
            ssid_field.clear(); ssid_field.send_keys(new_ssid)
            key_field = driver.find_element(By.NAME, "key")
            key_field.clear(); key_field.send_keys(new_pass)
            driver.find_element(By.XPATH, "//button[contains(.,'NEXT') or contains(.,'Next')]").click()
            time.sleep(20)  # เครื่อง reboot รอบแรก ให้เวลามันบูตกลับมา
        except Exception as e:
            return False, _fail_shot(driver, "set_new_ssid", e)

        # ขั้น 5: สแกนหา + เลือก WiFi บ้าน
        try:
            home_ap = wait.until(EC.element_to_be_clickable(
                (By.XPATH, f"//*[contains(text(),'{home_ssid}')]")))
            home_ap.click()
            driver.find_element(By.XPATH, "//button[contains(.,'SELECT') or contains(.,'Select')]").click()
        except Exception as e:
            return False, _fail_shot(driver, "select_home_wifi", e)

        # ขั้น 6: กรอกรหัส WiFi บ้าน แล้ว CONNECT
        try:
            home_pass_field = wait.until(EC.presence_of_element_located((By.NAME, "key")))
            home_pass_field.clear(); home_pass_field.send_keys(home_pass)
            driver.find_element(By.XPATH, "//button[contains(.,'CONNECT') or contains(.,'Connect')]").click()
        except Exception as e:
            return False, _fail_shot(driver, "connect_home_wifi", e)

        return True, f"ตั้งค่า Repeater เสร็จแล้ว — ปล่อย WiFi ชื่อ '{new_ssid}' เชื่อมกับบ้านผ่าน '{home_ssid}'"
    finally:
        driver.quit()

def tele_loop():
    _prune_tick_n = 0
    while True:
        # --- existing ticks ---
        sio.emit('bat', BAT.tick(random.uniform(-1.5, -0.2)))
        leech_tick()
        bullet_tick()
        fever_dmg = DISEASES[P_DISEASE["id"]].get("hp_drain", 0)
        if fever_dmg:
            P["hp"] = max(1, P["hp"] - fever_dmg)
        sio.emit('hp', {"hp": P["hp"], "leeches": list(LEECHES.keys()),
                        "bullets": list(BULLETS.keys())})

        # --- new system ticks ---
        airdrop_tick()                          # [ 2E ] land pending airdrops
        expire_announcements()                  # [ 2I ] deactivate expired announcements
        maintenance_tick()                      # [ 2I2 ] scheduled maintenance countdown warnings
        for aid in list(AI_AGENTS):             # [ 2C ] tick all AI agents
            ai_tick_agent(aid)
        camera_tick()                           # [ 2C2 ] check camera network sightings
        tick_construction()                     # [ 2b9b2 ] advance build/repair hologram progress
        market_tick()                           # [ 2D3 ] advance ธุรกิจ/ตลาดสินค้าโภคภัณฑ์ (นับถอยหลังวัน)
        npc_travel_tick()                       # [ 6zz2 ] หมุน NPC ไปเกมถัดไปที่เชื่อมต่ออยู่ (ถ้าเปิด auto_travel)
        golden_treasure_tick_all()              # [ 2E0z ] เดินผู้ตรวจตาม/จัดการแก๊ส/เช็คจบอีเวนต์สมบัติทองของแดง
        tdm4v4_tick_all()                       # [ NEW ] เช็คแมตช์ TDM 4v4 Polygon: Gan ที่หมดเวลาแล้วปิดอัตโนมัติ
        try:
            four_vs_four_tick_all()             # [EVENT] ปิดรอบ 4v4 เมื่อหมดเวลา
        except NameError:
            pass

        # [BUG-FIX #11-13] กวาดล้าง session/lockout ที่หมดอายุทุก ~60 วิ (ไม่ทุก
        # tick เพราะ loop วนที่ 1Hz — ทำทุกวิเปลือง CPU เกินจำเป็นสำหรับงานที่ไม่
        # เร่งด่วนขนาดนั้น)
        _prune_tick_n += 1
        if _prune_tick_n % 60 == 0:
            try:
                prune_expired_auth_state()
            except Exception as _prune_e:
                print(f"[VMAX Kernel][WARNING] prune_expired_auth_state ล้มเหลว: {_prune_e}")
            try:
                _prune_used_event_tokens()   # [BUG-FIX #12]
            except Exception as _prune_e2:
                print(f"[VMAX Kernel][WARNING] _prune_used_event_tokens ล้มเหลว: {_prune_e2}")

        # keep wallet in sync with player credits
        WALLET["balance"] = P["credits"]

        time.sleep(1)




