def market_generate_dynamic_headline(commodity_key: str) -> dict:
    """ประกอบข่าว 1 ชิ้นแบบสดๆ จาก phrase-bank สำหรับสินค้าที่ระบุ:
    สุ่ม[สาเหตุ] (ทั่วไป + เฉพาะทางของสินค้านั้นถ้ามี) + สุ่ม[ทิศทางราคา] + สุ่ม[ตัวเชื่อม]
    แล้วคำนวณ effect (ขนาดสุ่มตาม volatility ของสินค้า x ทิศทางที่สุ่มได้)"""
    spec = COMMODITIES[commodity_key]
    pool = MARKET_NEWS_GENERIC_CAUSES + MARKET_NEWS_EXTRA_CAUSES.get(commodity_key, [])
    cause = random.choice(pool)
    direction = random.choice(("up", "down"))
    connector = random.choice(MARKET_NEWS_UP_CONNECTORS if direction == "up" else MARKET_NEWS_DOWN_CONNECTORS)
    headline = f"{cause} {connector.format(name=spec['name_th'])}"
    magnitude = round(random.uniform(spec["volatility"] * 0.6, spec["volatility"] * 1.8), 3)
    effect = magnitude if direction == "up" else -magnitude
    return {"commodity": commodity_key, "headline": headline, "effect": effect}

