MARKET_HISTORY = {k: deque([v["base_price"]], maxlen=MARKET_HISTORY_MAX) for k, v in COMMODITIES.items()}
MARKET_NEWS = deque(maxlen=MARKET_NEWS_MAX)          # ช่อง "市場ニュース" — มีผลต่อราคาจริง
MARKET_OBSERVATIONS = deque(maxlen=MARKET_NEWS_MAX)  # ช่อง "市場情報" — ข้อสังเกตประกอบ ไม่ผูกราคาตรงๆ

WAREHOUSE = {"capacity": 100, "stock": {k: 0 for k in COMMODITIES}}
WAREHOUSE_UPGRADE_COST = 500   # เครดิตต่อการอัปเกรดความจุ +50
WAREHOUSE_UPGRADE_AMOUNT = 50

# บอทคู่แข่งจำลอง (ให้บรรยากาศตารางอันดับแบบในภาพตัวอย่าง: Neko / ゆあてゃ / ほなみ)
# มูลค่าสุทธิของบอทแกว่งขึ้นลงแบบสุ่มเบาๆ ทุกวัน ไม่ผูกกับเศรษฐกิจจริงของผู้เล่น
MARKET_BOTS = {
    "bot_neko":   {"display_name": "Neko",    "net_worth": 33900, "avatar": "🐱"},
    "bot_yua":    {"display_name": "ゆあてゃ", "net_worth": 29500, "avatar": "🌸"},
    "bot_honami": {"display_name": "ほなみ",   "net_worth": 27200, "avatar": "🌙"},
}


def market_price(commodity_key: str) -> int:
    return MARKET_STATE["prices"].get(commodity_key, 0)


def market_warehouse_used() -> int:
    return sum(WAREHOUSE["stock"].values())


def market_warehouse_value() -> int:
    """มูลค่าสต๊อกในคลังผู้เล่น ณ ราคาตลาดปัจจุบัน — ใช้คำนวณมูลค่าสุทธิรวมในตารางอันดับ"""
    return sum(qty * market_price(k) for k, qty in WAREHOUSE["stock"].items())


def market_generate_news_event():
    """สุ่มเลือกสินค้า 1 ชนิดจากทุกสินค้าในตลาด (รวมทองคำ/แก๊สหุงต้ม) แล้วประกอบข่าว
    แบบไดนามิกจาก phrase-bank (market_generate_dynamic_headline) ที่ขยับราคาจริง +
    ข้อสังเกต 1 ชิ้นที่ไม่ผูกราคาตรงๆ แล้วเก็บเข้าฟีดทั้งสองช่อง — เรียกทุกครั้งที่ขึ้นวันใหม่
    (market_advance_day)"""
    commodity_key = random.choice(list(COMMODITIES.keys()))
    tmpl = market_generate_dynamic_headline(commodity_key)
    entry = {"day": MARKET_STATE["day"], "commodity": tmpl["commodity"],
             "headline": tmpl["headline"], "effect": tmpl["effect"], "ts": time.time()}
    MARKET_NEWS.appendleft(entry)
    MARKET_OBSERVATIONS.appendleft({"day": MARKET_STATE["day"],
                                    "headline": random.choice(MARKET_OBSERVATION_TEMPLATES),
                                    "ts": time.time()})
    return entry


def market_apply_price_walk(news_entry):
    """เดินราคาแบบสุ่มเบาๆ ทุกวัน (random walk ตาม volatility ของสินค้าแต่ละตัว)
    บวกผลจากข่าวของวันนี้ (ถ้ามี) เข้ากับสินค้าที่ข่าวนั้นระบุ — ราคาถูกกันไม่ให้ต่ำกว่า 1"""
    for key, spec in COMMODITIES.items():
        price = MARKET_STATE["prices"][key]
        drift = random.uniform(-spec["volatility"], spec["volatility"])
        if news_entry and news_entry["commodity"] == key:
            drift += news_entry["effect"]
        price = max(1, round(price * (1 + drift)))
        MARKET_STATE["prices"][key] = price
        MARKET_HISTORY[key].append(price)


def market_jiggle_bots():
    """ขยับมูลค่าสุทธิของบอทคู่แข่งจำลองแบบสุ่มเบาๆ ทุกวัน ให้ตารางอันดับดูมีชีวิตชีวา"""
    for bot in MARKET_BOTS.values():
        bot["net_worth"] = max(0, round(bot["net_worth"] * (1 + random.uniform(-0.03, 0.05))))


def market_leaderboard(limit=10):
    """รวมบอทคู่แข่งจำลอง + ผู้เล่นจริง (เงินสด + มูลค่าสต๊อกในคลัง ณ ราคาปัจจุบัน)
    เรียงจากมูลค่าสุทธิมากไปน้อย แล้วติดอันดับ"""
    rows = [{"uid": bid, "display_name": b["display_name"], "avatar": b["avatar"],
             "net_worth": b["net_worth"], "is_player": False} for bid, b in MARKET_BOTS.items()]
    rows.append({"uid": P["uid"], "display_name": P["uid"], "avatar": "🧑‍💼",
                 "net_worth": P["credits"] + market_warehouse_value(), "is_player": True})
    rows.sort(key=lambda r: r["net_worth"], reverse=True)
    for i, r in enumerate(rows[:limit], start=1):
        r["rank"] = i
    return rows[:limit]


def market_advance_day():
    """ขึ้นวันใหม่: สุ่มข่าว -> เดินราคา -> ขยับบอท -> รีเซ็ตตัวนับวินาที
    ถ้าครบ MARKET_TOTAL_DAYS แล้ว วนกลับไปวันที่ 1 ของซีซันถัดไป (ราคาไม่รีเซ็ต
    กลับไปที่ base_price — เดินราคาต่อเนื่องข้ามซีซัน เหมือนตลาดจริงที่ไม่หยุดนิ่ง)"""
    news_entry = market_generate_news_event()
    market_apply_price_walk(news_entry)
    market_jiggle_bots()
    if MARKET_STATE["day"] >= MARKET_TOTAL_DAYS:
        MARKET_STATE["day"] = 1
        MARKET_STATE["season"] += 1
    else:
        MARKET_STATE["day"] += 1
    MARKET_STATE["seconds_left"] = MARKET_DAY_DURATION_SEC


def market_tick():
    """เรียกทุก 1 วิ จาก tele_loop — นับถอยหลังวินาทีของวันปัจจุบัน พอครบก็ขึ้นวันใหม่"""
    MARKET_STATE["seconds_left"] -= 1
    if MARKET_STATE["seconds_left"] <= 0:
        market_advance_day()


def market_buy(commodity_key, qty):
    if commodity_key not in COMMODITIES:
        return False, "ไม่พบสินค้านี้ในตลาด"
    if qty <= 0:
        return False, "จำนวนต้องมากกว่า 0"
    if market_warehouse_used() + qty > WAREHOUSE["capacity"]:
        return False, "คลังสินค้าไม่พอ — ลองอัปเกรดความจุหรือขายของเก่าออกก่อน"
    cost = market_price(commodity_key) * qty
    if P["credits"] < cost:
        return False, "เครดิตไม่พอซื้อ"
    P["credits"] -= cost
    WALLET["balance"] = P["credits"]
    WAREHOUSE["stock"][commodity_key] += qty
    return True, f"ซื้อ {COMMODITIES[commodity_key]['name_th']} จำนวน {qty} หน่วย ด้วยราคา {cost} เครดิต"


def market_sell(commodity_key, qty):
    if commodity_key not in COMMODITIES:
        return False, "ไม่พบสินค้านี้ในตลาด"
    if qty <= 0:
        return False, "จำนวนต้องมากกว่า 0"
    have = WAREHOUSE["stock"].get(commodity_key, 0)
    if have < qty:
        return False, "มีสินค้านี้ในคลังไม่พอที่จะขาย"
    revenue = market_price(commodity_key) * qty
    WAREHOUSE["stock"][commodity_key] -= qty
    P["credits"] += revenue
    WALLET["balance"] = P["credits"]
    # [Credit Support Fund] ถ้าผู้เล่นมีหนี้ค้างจากการยืมเครดิตมาเล่น หักส่วนหนึ่งของรายได้ขายของ
    # ครั้งนี้ไปโปะหนี้อัตโนมัติ (ดูฟังก์ชัน credit_fund_auto_deduct ในหมวด Credit Support Fund)
    _cf_deducted = credit_fund_auto_deduct(P["uid"], revenue, "market_sell")
    if _cf_deducted:
        return True, (f"ขาย {COMMODITIES[commodity_key]['name_th']} จำนวน {qty} หน่วย ได้ {revenue} เครดิต "
                       f"(หัก {_cf_deducted} เครดิตไปชำระหนี้ Credit Support Fund อัตโนมัติ)")
    return True, f"ขาย {COMMODITIES[commodity_key]['name_th']} จำนวน {qty} หน่วย ได้ {revenue} เครดิต"


def market_upgrade_warehouse():
    if P["credits"] < WAREHOUSE_UPGRADE_COST:
        return False, f"ต้องใช้ {WAREHOUSE_UPGRADE_COST} เครดิตในการอัปเกรดคลัง"
    P["credits"] -= WAREHOUSE_UPGRADE_COST
    WALLET["balance"] = P["credits"]
    WAREHOUSE["capacity"] += WAREHOUSE_UPGRADE_AMOUNT
    return True, f"อัปเกรดคลังสำเร็จ! ความจุใหม่: {WAREHOUSE['capacity']} หน่วย"


def market_full_state():
    return {
        "season": MARKET_STATE["season"], "day": MARKET_STATE["day"], "total_days": MARKET_TOTAL_DAYS,
        "seconds_left": MARKET_STATE["seconds_left"],
        "commodities": {k: {**v, "price": MARKET_STATE["prices"][k],
                            "history": list(MARKET_HISTORY[k])} for k, v in COMMODITIES.items()},
        "warehouse": {"capacity": WAREHOUSE["capacity"], "used": market_warehouse_used(),
                     "stock": WAREHOUSE["stock"], "upgrade_cost": WAREHOUSE_UPGRADE_COST,
                     "upgrade_amount": WAREHOUSE_UPGRADE_AMOUNT},
        "news": list(MARKET_NEWS), "observations": list(MARKET_OBSERVATIONS),
        "leaderboard": market_leaderboard(),
        "player_credits": P["credits"],
    }


# ปลูกข่าว/ราคาชุดแรกไว้ตั้งแต่ตอนเริ่มเซิร์ฟเวอร์ ไม่ต้องรอวันแรกผ่านไปก่อนถึงจะมีข่าวให้เห็น
market_generate_news_event()


@app.route('/api/market/state')
def api_market_state():
    return jsonify({"st": "ok", **market_full_state()})


@app.route('/api/market/buy', methods=['POST'])
@require_auth
def api_market_buy():
    body = request.json or {}
    ok, msg = market_buy(body.get("commodity", ""), int(body.get("qty", 0)))
    status = 200 if ok else 400
    return jsonify({"st": "ok" if ok else "error", "msg": msg, **market_full_state()}), status


@app.route('/api/market/sell', methods=['POST'])
@require_auth
def api_market_sell():
    body = request.json or {}
    ok, msg = market_sell(body.get("commodity", ""), int(body.get("qty", 0)))
    status = 200 if ok else 400
    return jsonify({"st": "ok" if ok else "error", "msg": msg, **market_full_state()}), status


@app.route('/api/market/upgrade-warehouse', methods=['POST'])
@require_auth
def api_market_upgrade_warehouse():
    ok, msg = market_upgrade_warehouse()
    status = 200 if ok else 400
    return jsonify({"st": "ok" if ok else "error", "msg": msg, **market_full_state()}), status


