# ==========================================
# [ 6l. Manga Platform: อัปโหลด/อ่าน, บัญชีครีเอเตอร์, ลิขสิทธิ์, ระบบขาย (ยังไม่รวมภาษี) ]
# ต่อจากที่คุยค้างไว้ (เว็บมังงะ + ลิขสิทธิ์ + ดึงข้อมูล VAT ล่าสุดมาช่วยประเมิน)
# หมายเหตุสำคัญ: เซิร์ฟเวอร์นี้รันแบบไม่มีอินเทอร์เน็ตขาออก จึงดึง VAT "สด" จาก
# เว็บไซต์รัฐบาลจริงให้ตอนรันโค้ดนี้ไม่ได้ — ผมใส่ตารางอัตรา VAT ไว้เป็นค่าอ้างอิง
# (ณ ความรู้ล่าสุดที่ผมมี ไม่ใช่ real-time) พร้อมฟังก์ชัน refresh_vat_rates_from_url()
# ที่คุณเรียกเองได้ตอน deploy จริง (มีอินเทอร์เน็ต) เพื่อดึงเรตล่าสุดจาก API ทางการ
# เช่น VATComply / EU VIES / หรือ Stripe Tax — ตัวเลขภาษีที่ได้ยัง "ควรให้นักบัญชี/
# ทนายตรวจสอบก่อนใช้จริง" เสมอ ผมไม่ใช่ที่ปรึกษาภาษี
# ==========================================

MANGA_DIR = "uploaded_manga"
MANGA_INDEX_PATH = os.path.join(MANGA_DIR, "index.json")
ALLOWED_PAGE_EXTENSIONS = {"jpg", "jpeg", "png", "webp"}
ALLOWED_LICENSE_EXTENSIONS = {"pdf", "png", "jpg", "jpeg"}
MAX_PAGE_UPLOAD_BYTES = 25 * 1024 * 1024  # 25MB ต่อหน้า
os.makedirs(MANGA_DIR, exist_ok=True)

PLATFORM_FEE_PERCENT = 20.0   # ส่วนแบ่งแพลตฟอร์ม — ปรับได้ตามโมเดลธุรกิจจริง

CREATORS = {}      # creator_id -> {name, joined_at, balance, payout_history:[]}
MANGA_TITLES = {}  # title_id  -> {creator_id, title, description, price_excl_vat,
                    #              chapters:{chapter_id:{pages:[...], uploaded_at}},
                    #              license:{status, doc_path, note}, status, created_at}
MANGA_SALES = []   # {sale_id, title_id, chapter_id, uid, gross, platform_fee, creator_net, ts}


def _manga_load_index():
    if os.path.exists(MANGA_INDEX_PATH):
        with open(MANGA_INDEX_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    return {"creators": {}, "titles": {}, "sales": []}


def _manga_save_index():
    with open(MANGA_INDEX_PATH, "w", encoding="utf-8") as f:
        json.dump({"creators": CREATORS, "titles": MANGA_TITLES, "sales": MANGA_SALES},
                  f, ensure_ascii=False, indent=2)


def _manga_load_on_boot():
    data = _manga_load_index()
    CREATORS.update(data.get("creators", {}))
    MANGA_TITLES.update(data.get("titles", {}))
    MANGA_SALES.extend(data.get("sales", []))


_manga_load_on_boot()


# --- ครีเอเตอร์ ---------------------------------------------------------------
@app.route('/api/creators/register', methods=['POST'])
@require_auth_toggleable
def api_creator_register():
    body = request.json or {}
    name = (body.get('name') or '').strip()
    if not name:
        return jsonify({"st": "error", "msg": "ต้องระบุชื่อครีเอเตอร์"}), 400
    creator_id = str(uuid.uuid4())[:8]
    CREATORS[creator_id] = {"name": name, "joined_at": time.time(),
                            "balance": 0.0, "payout_history": []}
    _manga_save_index()
    return jsonify({"st": "ok", "creator_id": creator_id, "creator": CREATORS[creator_id]})


@app.route('/api/creators/<creator_id>/ledger', methods=['GET'])
def api_creator_ledger(creator_id):
    """สรุปยอดขาย/ส่วนแบ่งของครีเอเตอร์คนนี้ — ยังไม่รวมภาษี ให้นักบัญชีคำนวณต่อ"""
    creator = CREATORS.get(creator_id)
    if not creator:
        return jsonify({"st": "error", "msg": "ไม่พบครีเอเตอร์นี้"}), 404
    sales = [s for s in MANGA_SALES if s["creator_id"] == creator_id]
    gross = sum(s["gross"] for s in sales)
    net = sum(s["creator_net"] for s in sales)
    return jsonify({"st": "ok", "creator": creator, "sales_count": len(sales),
                    "gross_excl_vat": round(gross, 2), "creator_net_excl_vat": round(net, 2),
                    "platform_fee_percent": PLATFORM_FEE_PERCENT, "sales": sales})


# --- อัปโหลด/จัดการเรื่อง ------------------------------------------------------
@app.route('/api/manga/create', methods=['POST'])
@require_auth_toggleable
def api_manga_create():
    body = request.json or {}
    creator_id = body.get('creator_id', '')
    title = (body.get('title') or '').strip()
    if creator_id not in CREATORS:
        return jsonify({"st": "error", "msg": "ไม่พบครีเอเตอร์นี้ — สมัครก่อนที่ /api/creators/register"}), 400
    if not title:
        return jsonify({"st": "error", "msg": "ต้องระบุชื่อเรื่อง"}), 400
    title_id = str(uuid.uuid4())[:8]
    MANGA_TITLES[title_id] = {
        "creator_id": creator_id, "title": title,
        "description": body.get('description', ''),
        "price_excl_vat": float(body.get('price_excl_vat', 0)),
        "chapters": {},
        "license": {"status": "missing", "doc_path": None, "note": ""},
        "status": "draft",  # draft -> published (ต้องมี license ก่อนถึงจะ publish ได้)
        "created_at": time.time(),
    }
    os.makedirs(os.path.join(MANGA_DIR, title_id), exist_ok=True)
    _manga_save_index()
    return jsonify({"st": "ok", "title_id": title_id, "title": MANGA_TITLES[title_id]})


@app.route('/api/manga/<title_id>/chapters', methods=['POST'])
@require_auth_toggleable
def api_manga_upload_chapter(title_id):
    """อัปโหลดหน้ามังงะของ 1 ตอน — ส่งเป็น multipart หลายไฟล์ (field name: pages)"""
    t = MANGA_TITLES.get(title_id)
    if not t:
        return jsonify({"st": "error", "msg": "ไม่พบเรื่องนี้"}), 404
    files = request.files.getlist('pages')
    if not files:
        return jsonify({"st": "error", "msg": "ต้องแนบไฟล์หน้ามังงะอย่างน้อย 1 หน้า (field: pages)"}), 400
    chapter_id = str(uuid.uuid4())[:8]
    chapter_dir = os.path.join(MANGA_DIR, title_id, chapter_id)
    os.makedirs(chapter_dir, exist_ok=True)
    saved_pages = []
    for i, f in enumerate(files):
        ext = (f.filename.rsplit('.', 1)[-1] if '.' in f.filename else '').lower()
        if ext not in ALLOWED_PAGE_EXTENSIONS:
            continue
        fname = secure_filename(f"page_{i:03d}.{ext}")
        f.save(os.path.join(chapter_dir, fname))
        saved_pages.append(fname)
    if not saved_pages:
        return jsonify({"st": "error", "msg": "ไม่มีไฟล์ที่นามสกุลถูกต้อง (jpg/jpeg/png/webp)"}), 400
    t["chapters"][chapter_id] = {"pages": saved_pages, "uploaded_at": time.time()}
    _manga_save_index()
    return jsonify({"st": "ok", "chapter_id": chapter_id, "pages": saved_pages})


@app.route('/api/manga/<title_id>/chapters/<chapter_id>/pages/<path:filename>', methods=['GET'])
def api_manga_get_page(title_id, chapter_id, filename):
    chapter_dir = os.path.join(MANGA_DIR, title_id, chapter_id)
    return send_from_directory(chapter_dir, secure_filename(filename))


@app.route('/api/manga', methods=['GET'])
def api_manga_list():
    out = {}
    for tid, t in MANGA_TITLES.items():
        base = t.get("price_excl_vat")
        row = {"title": t["title"], "creator_id": t["creator_id"],
               "status": t["status"], "license_status": t["license"]["status"],
               "chapters": list(t["chapters"].keys()),
               "price_excl_vat": base}
        try:
            if callable(globals().get("vmax_festival_price_apply")):
                priced = vmax_festival_price_apply(base, "manga")
                row["price_excl_vat_base"] = priced.get("base")
                row["price_excl_vat"] = priced.get("final")
                row["festival_discount"] = priced.get("discounted")
                row["price_mult"] = priced.get("mult")
        except Exception:
            pass
        out[tid] = row
    return jsonify(out)


@app.route('/api/manga/<title_id>', methods=['GET'])
def api_manga_detail(title_id):
    t = MANGA_TITLES.get(title_id)
    if not t:
        return jsonify({"st": "error", "msg": "ไม่พบเรื่องนี้"}), 404
    payload = dict(t)
    try:
        if callable(globals().get("vmax_festival_price_apply")):
            priced = vmax_festival_price_apply(t.get("price_excl_vat"), "manga")
            payload = dict(t)
            payload["price_excl_vat_base"] = priced.get("base")
            payload["price_excl_vat"] = priced.get("final")
            payload["festival_discount"] = priced.get("discounted")
            payload["price_mult"] = priced.get("mult")
    except Exception:
        pass
    return jsonify({"st": "ok", "title": payload})


# --- ลิขสิทธิ์/สัญญา -----------------------------------------------------------
@app.route('/api/manga/<title_id>/license', methods=['POST'])
@require_auth_toggleable
def api_manga_upload_license(title_id):
    """อัปโหลดเอกสารลิขสิทธิ์/สัญญาของเรื่องนี้ (field: doc) — ต้องมีสถานะ
    'confirmed' ก่อนถึงจะ publish/เปิดขายได้ ระบบนี้แค่ 'เก็บ' เอกสารไว้ ไม่ได้
    ตรวจสอบความถูกต้องทางกฎหมายให้ — ควรให้ทนาย/ฝ่ายกฎหมายตรวจก่อนกด confirm"""
    t = MANGA_TITLES.get(title_id)
    if not t:
        return jsonify({"st": "error", "msg": "ไม่พบเรื่องนี้"}), 404
    f = request.files.get('doc')
    if not f or not f.filename:
        return jsonify({"st": "error", "msg": "ต้องแนบไฟล์เอกสาร (field: doc)"}), 400
    ext = (f.filename.rsplit('.', 1)[-1] if '.' in f.filename else '').lower()
    if ext not in ALLOWED_LICENSE_EXTENSIONS:
        return jsonify({"st": "error", "msg": "รองรับเฉพาะ pdf/png/jpg/jpeg"}), 400
    license_dir = os.path.join(MANGA_DIR, title_id, "license")
    os.makedirs(license_dir, exist_ok=True)
    fname = secure_filename(f"license.{ext}")
    path = os.path.join(license_dir, fname)
    f.save(path)
    t["license"] = {"status": "pending_review", "doc_path": path,
                    "note": request.form.get('note', '')}
    _manga_save_index()
    return jsonify({"st": "ok", "license": t["license"]})


@app.route('/api/manga/<title_id>/license/confirm', methods=['POST'])
@require_auth_toggleable
def api_manga_confirm_license(title_id):
    """ยืนยันว่าตรวจเอกสารลิขสิทธิ์แล้วโอเค — ทำเองหลังตรวจนอกระบบ (คนจริง/ทนาย)"""
    t = MANGA_TITLES.get(title_id)
    if not t:
        return jsonify({"st": "error", "msg": "ไม่พบเรื่องนี้"}), 404
    if t["license"]["status"] == "missing":
        return jsonify({"st": "error", "msg": "ยังไม่ได้อัปโหลดเอกสารลิขสิทธิ์"}), 400
    t["license"]["status"] = "confirmed"
    _manga_save_index()
    return jsonify({"st": "ok", "license": t["license"]})


@app.route('/api/manga/<title_id>/publish', methods=['POST'])
@require_auth_toggleable
def api_manga_publish(title_id):
    t = MANGA_TITLES.get(title_id)
    if not t:
        return jsonify({"st": "error", "msg": "ไม่พบเรื่องนี้"}), 404
    if t["license"]["status"] != "confirmed":
        return jsonify({"st": "error", "msg": "ต้องยืนยันลิขสิทธิ์ก่อน (/license/confirm) ถึงจะ publish ได้"}), 400
    if not t["chapters"]:
        return jsonify({"st": "error", "msg": "ต้องมีอย่างน้อย 1 ตอนก่อน publish"}), 400
    t["status"] = "published"
    _manga_save_index()
    return jsonify({"st": "ok", "title": t})


# --- ระบบขาย (ยังไม่รวมภาษี) --------------------------------------------------
@app.route('/api/manga/<title_id>/purchase', methods=['POST'])
@require_auth
def api_manga_purchase(title_id):
    """ซื้อเรื่องนี้ (ราคาที่ตั้งไว้ 'ไม่รวม VAT') — หักส่วนแพลตฟอร์ม แล้วโอนส่วน
    ที่เหลือเข้า balance ครีเอเตอร์ทันที เหมือน pattern WALLET ที่ใช้อยู่แล้วในระบบนี้"""
    t = MANGA_TITLES.get(title_id)
    if not t:
        return jsonify({"st": "error", "msg": "ไม่พบเรื่องนี้"}), 404
    if t["status"] != "published":
        return jsonify({"st": "error", "msg": "เรื่องนี้ยังไม่เปิดขาย"}), 400
    body = request.json or {}
    uid = body.get('uid', 'anon')
    base_gross = round(float(t["price_excl_vat"]), 2)
    festival_meta = {}
    try:
        if callable(globals().get("vmax_festival_price_apply")):
            festival_meta = vmax_festival_price_apply(base_gross, "manga")
            gross = round(float(festival_meta.get("final", base_gross)), 2)
        else:
            gross = base_gross
    except Exception:
        gross = base_gross
    platform_fee = round(gross * PLATFORM_FEE_PERCENT / 100.0, 2)
    creator_net = round(gross - platform_fee, 2)
    creator = CREATORS.get(t["creator_id"])
    if creator:
        creator["balance"] = round(creator.get("balance", 0.0) + creator_net, 2)
    sale = {"sale_id": str(uuid.uuid4())[:8], "title_id": title_id,
            "creator_id": t["creator_id"], "uid": uid, "gross": gross,
            "gross_base": base_gross,
            "festival_discount": bool(festival_meta.get("discounted")),
            "price_mult": festival_meta.get("mult", 1.0),
            "platform_fee": platform_fee, "creator_net": creator_net, "ts": time.time()}
    MANGA_SALES.append(sale)
    _manga_save_index()
    return jsonify({"st": "ok", "sale": sale,
                    "note": "ราคานี้ยังไม่รวม VAT — ดูตัวประมาณที่รวม VAT ได้ที่ /api/manga/<title_id>/estimate-price-with-vat?country=XX"})


@app.route('/api/manga/sales', methods=['GET'])
def api_manga_sales_list():
    return jsonify({"st": "ok", "count": len(MANGA_SALES), "sales": MANGA_SALES})


# --- ตาราง VAT อ้างอิง (ไม่ real-time) + จุดต่อยอดดึงข้อมูลสดภายหลัง -----------
# ค่าพวกนี้คือ "อัตรา VAT/GST มาตรฐาน" ณ ความรู้ล่าสุดของผม ใช้เป็นค่าประมาณคร่าวๆ
# เท่านั้น หลายประเทศมีอัตราลดสำหรับสินค้าดิจิทัล/หนังสือ/มังงะโดยเฉพาะ ซึ่งต่างจาก
# อัตรามาตรฐานนี้ — ก่อนคิดราคาขายจริงควรเช็คกับนักบัญชี/ผู้เชี่ยวชาญภาษีของแต่ละ
# ประเทศที่จะขาย หรือใช้บริการที่คำนวณให้อัตโนมัติเช่น Stripe Tax
VAT_RATES_TABLE = {
    "TH": {"rate_percent": 7.0,  "label": "Thailand VAT"},
    "SG": {"rate_percent": 9.0,  "label": "Singapore GST"},
    "JP": {"rate_percent": 10.0, "label": "Japan Consumption Tax"},
    "KR": {"rate_percent": 10.0, "label": "South Korea VAT"},
    "GB": {"rate_percent": 20.0, "label": "UK VAT"},
    "DE": {"rate_percent": 19.0, "label": "Germany VAT"},
    "FR": {"rate_percent": 20.0, "label": "France VAT"},
    "AU": {"rate_percent": 10.0, "label": "Australia GST"},
    "US": {"rate_percent": 0.0,  "label": "US — ไม่มี VAT ระดับประเทศ (sales tax ต่างกันตามรัฐ)"},
}
VAT_RATES_UPDATED_AT = None  # ตั้งเป็น timestamp เมื่อ refresh_vat_rates_from_url() ทำงานสำเร็จ


def refresh_vat_rates_from_url(source_url):
    """เรียกฟังก์ชันนี้เองตอน deploy จริง (เซิร์ฟเวอร์ต้องมีอินเทอร์เน็ตขาออก) เพื่อ
    ดึงอัตรา VAT ล่าสุดจาก API ทางการ เช่น https://api.vatcomply.com/rates — ไม่เรียก
    อัตโนมัติตอนบูตเพราะสภาพแวดล้อมรันโค้ดนี้ตอนพัฒนาไม่มีอินเทอร์เน็ตขาออก"""
    global VAT_RATES_UPDATED_AT
    resp = requests.get(source_url, timeout=10)
    resp.raise_for_status()
    data = resp.json()
    rates = data.get("rates", {})
    for country_code, rate in rates.items():
        VAT_RATES_TABLE[country_code] = {"rate_percent": round(float(rate) * 100, 2)
                                         if rate < 1 else round(float(rate), 2),
                                         "label": f"{country_code} (จาก {source_url})"}
    VAT_RATES_UPDATED_AT = time.time()
    return VAT_RATES_TABLE


@app.route('/api/tax/vat-rates', methods=['GET'])
def api_vat_rates_list():
    # [SEC-AUDIT round 2] เดิม note บอกแค่ "ไม่ใช่คำแนะนำภาษี" เฉยๆ ยังไม่ชัดพอว่า
    # เอาไปออกเอกสาร/ยื่นสรรพากรจริงไม่ได้เด็ดขาดจนกว่าจะต่อ e-Tax Invoice Provider
    # จริง (มีแค่ VAT_RATES_TABLE เป็นสถิติอ้างอิงในระบบ ไม่ได้ดึง live data จาก
    # สรรพากรภายนอกเลยตั้งแต่เริ่มรัน นอกจากมีคนเรียก refresh เอง)
    return jsonify({"st": "ok", "updated_at": VAT_RATES_UPDATED_AT,
                    "is_live_data": VAT_RATES_UPDATED_AT is not None,
                    "usable_for_official_tax_filing": False,
                    "note": ("ค่าอ้างอิงคร่าวๆ ไม่ใช่คำแนะนำภาษี — ห้ามนำไปออกเอกสารภาษีหรือยื่นสรรพากรจริง "
                              "จนกว่าจะเชื่อมต่อกับ e-Tax Invoice Provider จริง (เช่น Stripe Tax หรือผู้ให้บริการที่สรรพากรรับรอง) "
                              "ตรวจกับนักบัญชี/ทนายก่อนใช้งานจริงเสมอ"),
                    "rates": VAT_RATES_TABLE})


@app.route('/api/tax/vat-rates/refresh', methods=['POST'])
@require_auth_toggleable
def api_vat_rates_refresh():
    """เรียก endpoint นี้เองตอน deploy จริง (ที่มีอินเทอร์เน็ต) พร้อม
    body: {"source_url": "https://api.vatcomply.com/rates"} เพื่อดึงเรตสดมาแทนตารางอ้างอิง"""
    body = request.json or {}
    source_url = body.get('source_url')
    if not source_url:
        return jsonify({"st": "error", "msg": "ต้องระบุ source_url ของ API อัตรา VAT"}), 400
    try:
        rates = refresh_vat_rates_from_url(source_url)
        return jsonify({"st": "ok", "updated_at": VAT_RATES_UPDATED_AT, "rates": rates})
    except Exception as e:
        return jsonify({"st": "error", "msg": f"ดึงข้อมูลไม่สำเร็จ: {e}"}), 502


@app.route('/api/manga/<title_id>/estimate-price-with-vat', methods=['GET'])
def api_manga_estimate_price_with_vat(title_id):
    """ราคาประมาณรวม VAT ตามประเทศที่ระบุ — เป็นตัวเลข 'ประมาณการ' เท่านั้น
    ไม่ใช่การคำนวณภาษีที่ใช้ยื่นจริงได้ ให้ระบบคิดราคาสุดท้ายจริงผ่านผู้ให้บริการที่
    เชี่ยวชาญเรื่องนี้โดยเฉพาะ (เช่น Stripe Tax) หรือให้นักบัญชี/ทนายตรวจสอบก่อน"""
    t = MANGA_TITLES.get(title_id)
    if not t:
        return jsonify({"st": "error", "msg": "ไม่พบเรื่องนี้"}), 404
    country = (request.args.get('country') or '').upper()
    vat = VAT_RATES_TABLE.get(country)
    if not vat:
        return jsonify({"st": "error", "msg": f"ไม่มีข้อมูล VAT สำหรับ '{country}' ในตารางอ้างอิง"}), 404
    base_raw = round(float(t["price_excl_vat"]), 2)
    base = base_raw
    fest = {}
    try:
        if callable(globals().get("vmax_festival_price_apply")):
            fest = vmax_festival_price_apply(base_raw, "manga")
            base = round(float(fest.get("final", base_raw)), 2)
    except Exception:
        pass
    vat_amount = round(base * vat["rate_percent"] / 100.0, 2)
    return jsonify({"st": "ok", "country": country, "vat_rate_percent": vat["rate_percent"],
                    "price_excl_vat_base": base_raw,
                    "price_excl_vat": base,
                    "festival_discount": bool(fest.get("discounted")),
                    "price_mult": fest.get("mult", 1.0),
                    "vat_amount_estimate": vat_amount,
                    "price_incl_vat_estimate": round(base + vat_amount, 2),
                    "is_live_vat_data": VAT_RATES_UPDATED_AT is not None,
                    "usable_for_official_tax_filing": False,
                    "note": ("ตัวเลขประมาณการเท่านั้น ไม่ใช่คำแนะนำภาษี — ห้ามนำไปออกเอกสารภาษีหรือยื่นสรรพากรจริง "
                              "จนกว่าจะเชื่อมต่อกับ e-Tax Invoice Provider จริง")})


