# ==========================================
# [ 6m. Gallery / Community: โพสต์งานวาด, ไลก์, คอมเมนต์, follow ครีเอเตอร์ ]
# แยกจากมังงะ (ที่มีลำดับตอน+license+ขายเป็นชิ้น) — ตรงนี้คือโพสต์งานวาดเดี่ยวๆ
# ใช้ CREATORS ชุดเดียวกับส่วนมังงะด้านบน [ 6l ] เพื่อให้ครีเอเตอร์คนเดียวกันมีทั้ง
# ผลงานมังงะและงานวาดเดี่ยวอยู่ในบัญชีเดียว ไม่ต้องสมัครซ้ำ
# ==========================================

GALLERY_DIR = "uploaded_gallery"
GALLERY_INDEX_PATH = os.path.join(GALLERY_DIR, "index.json")
os.makedirs(GALLERY_DIR, exist_ok=True)

GALLERY_POSTS = {}   # post_id -> {creator_id, caption, image_filename, tags:[], posted_at,
                     #             likes:set(uid), comments:[{comment_id, uid, text, ts}]}
FOLLOWS = {}         # creator_id -> set(uid ที่ follow อยู่)


def _gallery_load_index():
    if os.path.exists(GALLERY_INDEX_PATH):
        with open(GALLERY_INDEX_PATH, "r", encoding="utf-8") as f:
            raw = json.load(f)
            for pid, p in raw.get("posts", {}).items():
                p["likes"] = set(p.get("likes", []))
            return raw.get("posts", {}), {cid: set(uids) for cid, uids in raw.get("follows", {}).items()}
    return {}, {}


def _gallery_save_index():
    posts_out = {}
    for pid, p in GALLERY_POSTS.items():
        p2 = dict(p)
        p2["likes"] = list(p["likes"])
        posts_out[pid] = p2
    with open(GALLERY_INDEX_PATH, "w", encoding="utf-8") as f:
        json.dump({"posts": posts_out,
                  "follows": {cid: list(uids) for cid, uids in FOLLOWS.items()}},
                  f, ensure_ascii=False, indent=2)


_loaded_posts, _loaded_follows = _gallery_load_index()
GALLERY_POSTS.update(_loaded_posts)
FOLLOWS.update(_loaded_follows)


# --- โพสต์งานวาด ---------------------------------------------------------------
@app.route('/api/gallery/posts', methods=['POST'])
@require_auth_toggleable
def api_gallery_create_post():
    """ลงผลงานวาด 1 ภาพต่อโพสต์ — ส่ง multipart field: image, กับ form field:
    creator_id, caption (ไม่บังคับ), tags (คั่นด้วยจุลภาค ไม่บังคับ)"""
    creator_id = request.form.get('creator_id', '')
    if creator_id not in CREATORS:
        return jsonify({"st": "error", "msg": "ไม่พบครีเอเตอร์นี้ — สมัครก่อนที่ /api/creators/register"}), 400
    f = request.files.get('image')
    if not f or not f.filename:
        return jsonify({"st": "error", "msg": "ต้องแนบไฟล์ภาพ (field: image)"}), 400
    ext = (f.filename.rsplit('.', 1)[-1] if '.' in f.filename else '').lower()
    if ext not in ALLOWED_PAGE_EXTENSIONS:
        return jsonify({"st": "error", "msg": "รองรับเฉพาะ jpg/jpeg/png/webp"}), 400
    post_id = str(uuid.uuid4())[:8]
    post_dir = os.path.join(GALLERY_DIR, post_id)
    os.makedirs(post_dir, exist_ok=True)
    fname = secure_filename(f"art.{ext}")
    f.save(os.path.join(post_dir, fname))
    tags = [t.strip() for t in (request.form.get('tags', '') or '').split(',') if t.strip()]
    GALLERY_POSTS[post_id] = {
        "creator_id": creator_id, "caption": request.form.get('caption', ''),
        "image_filename": fname, "tags": tags, "posted_at": time.time(),
        "likes": set(), "comments": [],
    }
    _gallery_save_index()
    return jsonify({"st": "ok", "post_id": post_id})


@app.route('/api/gallery/posts/<post_id>/image', methods=['GET'])
def api_gallery_get_image(post_id):
    p = GALLERY_POSTS.get(post_id)
    if not p:
        return jsonify({"st": "error", "msg": "ไม่พบโพสต์นี้"}), 404
    return send_from_directory(os.path.join(GALLERY_DIR, post_id), p["image_filename"])


@app.route('/api/gallery/feed', methods=['GET'])
def api_gallery_feed():
    """feed ไล่เวลา ล่าสุดก่อน — filter ได้ด้วย ?tag=xxx หรือ ?creator_id=xxx"""
    tag = request.args.get('tag')
    creator_id = request.args.get('creator_id')
    limit = int(request.args.get('limit', 30))
    items = list(GALLERY_POSTS.items())
    if tag:
        items = [(pid, p) for pid, p in items if tag in p["tags"]]
    if creator_id:
        items = [(pid, p) for pid, p in items if p["creator_id"] == creator_id]
    items.sort(key=lambda kv: kv[1]["posted_at"], reverse=True)
    out = [{"post_id": pid, "creator_id": p["creator_id"], "creator_name": CREATORS.get(p["creator_id"], {}).get("name", "?"),
            "caption": p["caption"], "tags": p["tags"], "posted_at": p["posted_at"],
            "like_count": len(p["likes"]), "comment_count": len(p["comments"])}
           for pid, p in items[:limit]]
    return jsonify({"st": "ok", "count": len(out), "posts": out})


@app.route('/api/gallery/posts/<post_id>', methods=['GET'])
def api_gallery_post_detail(post_id):
    p = GALLERY_POSTS.get(post_id)
    if not p:
        return jsonify({"st": "error", "msg": "ไม่พบโพสต์นี้"}), 404
    out = dict(p)
    out["like_count"] = len(p["likes"])
    del out["likes"]
    return jsonify({"st": "ok", "post_id": post_id, "post": out})


# --- ไลก์ ------------------------------------------------------------------
@app.route('/api/gallery/posts/<post_id>/like', methods=['POST'])
@require_auth_toggleable
def api_gallery_like(post_id):
    p = GALLERY_POSTS.get(post_id)
    if not p:
        return jsonify({"st": "error", "msg": "ไม่พบโพสต์นี้"}), 404
    uid = (request.json or {}).get('uid', 'anon')
    p["likes"].add(uid)
    _gallery_save_index()
    return jsonify({"st": "ok", "like_count": len(p["likes"])})


@app.route('/api/gallery/posts/<post_id>/unlike', methods=['POST'])
@require_auth_toggleable
def api_gallery_unlike(post_id):
    p = GALLERY_POSTS.get(post_id)
    if not p:
        return jsonify({"st": "error", "msg": "ไม่พบโพสต์นี้"}), 404
    uid = (request.json or {}).get('uid', 'anon')
    p["likes"].discard(uid)
    _gallery_save_index()
    return jsonify({"st": "ok", "like_count": len(p["likes"])})


# --- คอมเมนต์ ---------------------------------------------------------------
@app.route('/api/gallery/posts/<post_id>/comments', methods=['POST'])
@require_auth_toggleable
def api_gallery_comment(post_id):
    p = GALLERY_POSTS.get(post_id)
    if not p:
        return jsonify({"st": "error", "msg": "ไม่พบโพสต์นี้"}), 404
    body = request.json or {}
    text = (body.get('text') or '').strip()
    if not text:
        return jsonify({"st": "error", "msg": "ต้องระบุข้อความคอมเมนต์"}), 400
    comment = {"comment_id": str(uuid.uuid4())[:8], "uid": body.get('uid', 'anon'),
              "text": text, "ts": time.time()}
    p["comments"].append(comment)
    _gallery_save_index()
    return jsonify({"st": "ok", "comment": comment})


@app.route('/api/gallery/posts/<post_id>/comments', methods=['GET'])
def api_gallery_comments_list(post_id):
    p = GALLERY_POSTS.get(post_id)
    if not p:
        return jsonify({"st": "error", "msg": "ไม่พบโพสต์นี้"}), 404
    return jsonify({"st": "ok", "comments": p["comments"]})


@app.route('/api/gallery/posts/<post_id>/comments/<comment_id>', methods=['DELETE'])
@require_auth_toggleable
def api_gallery_comment_delete(post_id, comment_id):
    p = GALLERY_POSTS.get(post_id)
    if not p:
        return jsonify({"st": "error", "msg": "ไม่พบโพสต์นี้"}), 404
    before = len(p["comments"])
    p["comments"] = [c for c in p["comments"] if c["comment_id"] != comment_id]
    if len(p["comments"]) == before:
        return jsonify({"st": "error", "msg": "ไม่พบคอมเมนต์นี้"}), 404
    _gallery_save_index()
    return jsonify({"st": "ok"})


# --- Follow ครีเอเตอร์ --------------------------------------------------------
@app.route('/api/creators/<creator_id>/follow', methods=['POST'])
@require_auth_toggleable
def api_creator_follow(creator_id):
    if creator_id not in CREATORS:
        return jsonify({"st": "error", "msg": "ไม่พบครีเอเตอร์นี้"}), 404
    uid = (request.json or {}).get('uid', 'anon')
    FOLLOWS.setdefault(creator_id, set()).add(uid)
    _following_hook("follow", uid, creator_id)  # [ 6m1 ]
    _gallery_save_index()
    return jsonify({"st": "ok", "follower_count": len(FOLLOWS[creator_id])})


@app.route('/api/creators/<creator_id>/unfollow', methods=['POST'])
@require_auth_toggleable
def api_creator_unfollow(creator_id):
    if creator_id not in CREATORS:
        return jsonify({"st": "error", "msg": "ไม่พบครีเอเตอร์นี้"}), 404
    uid = (request.json or {}).get('uid', 'anon')
    _following_hook("unfollow", uid, creator_id)  # [ 6m1 ] บันทึกประวัติก่อนลบ
    FOLLOWS.get(creator_id, set()).discard(uid)
    _gallery_save_index()
    return jsonify({"st": "ok", "follower_count": len(FOLLOWS.get(creator_id, set()))})


@app.route('/api/creators/<creator_id>/followers', methods=['GET'])
def api_creator_followers(creator_id):
    if creator_id not in CREATORS:
        return jsonify({"st": "error", "msg": "ไม่พบครีเอเตอร์นี้"}), 404
    return jsonify({"st": "ok", "follower_count": len(FOLLOWS.get(creator_id, set()))})


@app.route('/api/gallery/following-feed', methods=['GET'])
def api_gallery_following_feed():
    """feed เฉพาะครีเอเตอร์ที่ uid นี้ follow อยู่ — ?uid=xxx"""
    uid = request.args.get('uid', '')
    followed_creator_ids = {cid for cid, uids in FOLLOWS.items() if uid in uids}
    items = [(pid, p) for pid, p in GALLERY_POSTS.items() if p["creator_id"] in followed_creator_ids]
    items.sort(key=lambda kv: kv[1]["posted_at"], reverse=True)
    out = [{"post_id": pid, "creator_id": p["creator_id"],
            "creator_name": CREATORS.get(p["creator_id"], {}).get("name", "?"),
            "caption": p["caption"], "posted_at": p["posted_at"],
            "like_count": len(p["likes"]), "comment_count": len(p["comments"])}
           for pid, p in items]
    return jsonify({"st": "ok", "count": len(out), "posts": out})


