FOLLOW_INTERACTION_TYPES = ("view", "profile", "share")  # like/comment ดึงจาก gallery เอง กันนับซ้ำ
FOLLOW_MAX_EVENTS_PER_CALL = 200
FOLLOW_MAX_EVENT_COUNT = 20
FOLLOW_ACTIVITY_SCORE_CAP = 1000.0
FOLLOW_MAX_LISTS_PER_UID = 50
FOLLOW_FLUSH_DELAY_S = 5.0
FOLLOW_TOP_N_DEFAULT = 100
FOLLOW_DORMANT_DAYS_DEFAULT = 30.0
FOLLOW_ACTIVE_DAYS_DEFAULT = 7.0
FOLLOW_MUTE_MAX_DAYS = 3650
