FOLLOW_UNDO_MAX_BATCHES = 10
FOLLOW_FEED_HALF_LIFE_DAYS = 3.0
FOLLOW_FEED_MAX_AGE_DAYS = 90
FOLLOW_FEED_LIMIT_MAX = 100

FOLLOW_META = {}        # uid -> {creator_id -> {tags:[str], note:str, starred:bool, followed_at:float|None}}
FOLLOW_UNFOLLOWED = {}  # uid -> {creator_id -> {name, tags, note, starred, followed_at, unfollowed_at}}
