# --- ประวัติเลิกติดตาม + กู้คืน ----------------------------------------------------
@app.route('/api/following/unfollowed', methods=['GET'])
@require_auth_toggleable
def api_following_unfollowed():
    """คนที่เคยเลิกติดตาม (ล่าสุดก่อน) ค้นหาด้วย q/tag เหมือน /list — ?since_days=7 จำกัดช่วงเวลา"""
    uid = _ft_uid()
    if not uid:
        return _ft_err("ต้องระบุ uid")
    f = _ft_filters(request.args)
    stats = _ft_creator_stats()
    try:
        since = time.time() - float(request.args["since_days"]) * 86400 if request.args.get("since_days") else 0
    except ValueError:
        since = 0
    items = []
    for cid, e in FOLLOW_UNFOLLOWED.get(uid, {}).items():
        if e.get("unfollowed_at", 0) < since:
            continue
        name = CREATORS.get(cid, {}).get("name") or e.get("name") or "?"
        if _ft_match(f, name, e, stats.get(cid, {}).get("auto_tags", [])):
            it = _ft_item(cid, e, stats)
            it["still_exists"] = cid in CREATORS
            items.append(it)
    _ft_sort(items, request.args.get("sort", "unfollowed"))
    return jsonify({"st": "ok", **_ft_page(items)})


@app.route('/api/following/restore', methods=['POST'])
@require_auth_toggleable
def api_following_restore():
    """body: {uid, creator_id | creator_ids:[...]} — ติดตามกลับ พร้อมแท็ก/โน้ต/ดาวเดิม"""
    uid, body = _ft_uid(), _ft_body()
    if not uid:
        return _ft_err("ต้องระบุ uid")
    ids = body.get("creator_ids") or ([body["creator_id"]] if body.get("creator_id") else [])
    restored, failed = [], []
    with _FOLLOWING_LOCK:
        for cid in ids if isinstance(ids, list) else []:
            if not isinstance(cid, str) or cid not in CREATORS:
                failed.append({"creator_id": cid, "msg": "ครีเอเตอร์นี้ไม่มีอยู่ในระบบแล้ว"})
                continue
            FOLLOWS.setdefault(cid, set()).add(uid)
            _following_hook("follow", uid, cid, save=False)
            restored.append(cid)
        if restored:
            _following_save()
    if restored:
        _gallery_save_index()
    return jsonify({"st": "ok", "restored": restored, "failed": failed})


