# --- [ใหม่] Interaction -> affinity score ----------------------------------------
@app.route('/api/following/interaction', methods=['POST'])
@require_auth_toggleable
def api_following_interaction():
    """body: {uid, events:[{creator_id, type:"view"|"profile"|"share", count?:1..20}, ...]} (สูงสุด 200/ครั้ง)
    หรือส่ง event เดียวแบบ {uid, creator_id, type} — ให้แอปรวม event เป็น batch แล้วส่งทุกไม่กี่วินาที
    ไลก์/คอมเมนต์ไม่ต้องส่ง (ดึงจาก gallery เอง) ส่งเฉพาะคนที่ติดตามอยู่ ที่เหลือถูกข้าม"""
    uid, body = _ft_uid(), _ft_body()
    if not uid:
        return _ft_err("ต้องระบุ uid")
    events = body.get("events")
    if events is None:
        events = [body]
    if not isinstance(events, list):
        return _ft_err("events ต้องเป็น list")
    if len(events) > FOLLOW_MAX_EVENTS_PER_CALL:
        return _ft_err("ส่งได้ครั้งละไม่เกิน %d events" % FOLLOW_MAX_EVENTS_PER_CALL)
    followed = set(_ft_followed_ids(uid))
    now = time.time()
    applied = ignored = 0
    with _FOLLOWING_LOCK:
        act = FOLLOW_ACTIVITY.setdefault(uid, {})
        for ev in events:
            if not isinstance(ev, dict):
                ignored += 1
                continue
            cid, typ = ev.get("creator_id"), str(ev.get("type", "view")).strip().lower()
            if typ not in FOLLOW_INTERACTION_TYPES or not isinstance(cid, str) or cid not in followed:
                ignored += 1
                continue
            try:
                n = int(ev.get("count", 1))
            except (TypeError, ValueError):
                n = 1
            n = max(1, min(FOLLOW_MAX_EVENT_COUNT, n))
            a_ = act.get(cid) or {"score": 0.0, "ts": now}
            a_["score"] = min(FOLLOW_ACTIVITY_SCORE_CAP,
                              _ft_decay(a_.get("score", 0.0), a_.get("ts"), now) + FOLLOW_EVENT_WEIGHTS[typ] * n)
            a_["ts"] = now
            act[cid] = a_
            applied += 1
        if applied:
            _following_save_soon()
    return jsonify({"st": "ok", "applied": applied, "ignored": ignored})


# --- [ใหม่] Mute / พักคน (ไม่เลิกติดตาม) -------------------------------------------
@app.route('/api/following/mute', methods=['POST'])
@require_auth_toggleable
def api_following_mute():
    """body: {uid, creator_id | creator_ids | filter | list, mute:true|false (default true), days?:N}
    days = พักชั่วคราวแล้วเปิดเสียงให้เองเมื่อครบ (ไม่ใส่ = ไม่มีกำหนด) — คนที่ปิดเสียงยังอยู่ในรายชื่อ
    แต่ไม่โผล่ในฟีดจัดอันดับ"""
    uid, body = _ft_uid(), _ft_body()
    if not uid:
        return _ft_err("ต้องระบุ uid")
    targets, info, err = _ft_targets(uid, body)
    if err:
        return err
    if info["by"] == "ids" and not targets:
        return _ft_err("ไม่พบครีเอเตอร์ที่ติดตามอยู่ตามที่ระบุ", 404)
    mute = body.get("mute", True) is not False
    until = None
    if mute and body.get("days") not in (None, ""):
        d = _ft_num(body.get("days"), None)
        if not d:
            return _ft_err("days ต้องเป็นตัวเลขมากกว่า 0")
        until = time.time() + min(d, FOLLOW_MUTE_MAX_DAYS) * 86400
    with _FOLLOWING_LOCK:
        meta = FOLLOW_META.setdefault(uid, {})
        for cid in targets:
            e = meta.setdefault(cid, _ft_new_entry())
            if mute:
                e["muted"], e["muted_until"] = True, until
            else:
                e.pop("muted", None)
                e.pop("muted_until", None)
        _following_save()
    return jsonify({"st": "ok", "updated": len(targets), "muted": mute, "muted_until": until})


