@app.route('/api/following/lists/save', methods=['POST'])
@require_auth_toggleable
def api_following_lists_save():
    """body: {uid, name, filter:{...เหมือน /list...}} — ชื่อซ้ำ = เขียนทับ
    ลิสต์เก็บ "ตัวกรอง" ไม่ใช่รายชื่อตายตัว คนที่เข้าเงื่อนไขภายหลังจะเข้าลิสต์เองอัตโนมัติ"""
    uid, body = _ft_uid(), _ft_body()
    name = _ft_norm_tag(body.get("name"))
    if not uid or not name:
        return _ft_err("ต้องระบุ uid และ name")
    if not isinstance(body.get("filter"), dict):
        return _ft_err("ต้องส่ง filter เป็น object")
    f = _ft_filters(body["filter"])
    if _ft_filter_is_empty(f):
        return _ft_err("ตัวกรองว่าง — ต้องระบุเงื่อนไขอย่างน้อยหนึ่งอย่าง")
    saved = {k: f[k] for k in _FT_SAVED_KEYS}
    now = time.time()
    with _FOLLOWING_LOCK:
        lists = FOLLOW_LISTS.setdefault(uid, {})
        old_name, old = _ft_find_list(uid, name)
        if old is None and len(lists) >= FOLLOW_MAX_LISTS_PER_UID:
            return _ft_err("สร้างลิสต์ได้สูงสุด %d ลิสต์ — ลบอันที่ไม่ใช้ก่อน" % FOLLOW_MAX_LISTS_PER_UID)
        if old is not None:
            lists.pop(old_name, None)
        lists[name] = {"filter": saved, "created_at": (old or {}).get("created_at", now), "updated_at": now}
        _following_save()
    return jsonify({"st": "ok", "name": name, "filter": saved})


