# ==========================================
# [ 6m2. Photo Library -> Auto Map Generation ]
# ยังไม่มีของนี้มาก่อนเลย (คนละอันกับ gallery ด้านบนที่เอาไว้โพสต์โชว์งานวาด) —
# เพิ่มใหม่: ผู้เล่นถ่ายรูป/อัปโหลดรูปเก็บไว้ในคลัง (PHOTO_LIBRARY) แล้วกด
# "สร้างแผนที่จากรูปนี้" ระบบจะวิเคราะห์รูปอัตโนมัติแล้ววาง obstacle ลงในโลก
# ฟิสิกส์จริงให้เลย (ใช้ physics_add_obstacle() ตัวเดียวกับระบบก่อสร้าง [ 6f1 ])
#
# ข้อจำกัดที่ต้องพูดตรงๆ: นี่คือ "การตรวจจับขอบ/รูปทรงสี่เหลี่ยมในภาพ" (OpenCV
# Canny edge + findContours) แล้วแปลงตำแหน่งพิกเซล -> พิกัดโลกแบบเชิงเส้นตรงๆ
# ไม่ใช่การสร้างแบบจำลอง 3 มิติจากภาพจริง (photogrammetry) และไม่รู้ว่าสิ่งที่
# ตรวจเจอคือ "กำแพง" จริงหรือแค่กรอบรูป/เงา/ขอบโต๊ะ — เหมาะเป็นจุดเริ่มต้นคร่าวๆ
# ให้ผู้เล่นมาปรับตำแหน่ง/ลบของที่ไม่ต้องการต่อเอง ไม่ใช่ผลลัพธ์ที่แม่นยำพร้อมใช้
# ==========================================

PHOTO_LIBRARY_DIR = "uploaded_photo_library"
PHOTO_LIBRARY_INDEX_PATH = os.path.join(PHOTO_LIBRARY_DIR, "index.json")
os.makedirs(PHOTO_LIBRARY_DIR, exist_ok=True)

PHOTO_LIBRARY = {}   # photo_id -> {uploader, filename, uploaded_at, analyzed, generated_obstacle_ids}


def _photo_library_load_index():
    if os.path.exists(PHOTO_LIBRARY_INDEX_PATH):
        with open(PHOTO_LIBRARY_INDEX_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    return {}


def _photo_library_save_index():
    with open(PHOTO_LIBRARY_INDEX_PATH, "w", encoding="utf-8") as f:
        json.dump(PHOTO_LIBRARY, f, ensure_ascii=False, indent=2)


PHOTO_LIBRARY.update(_photo_library_load_index())


def analyze_photo_to_obstacle_rects(image_bytes: bytes, world_range: float = None,
                                    min_area_frac: float = 0.002, max_objects: int = 40) -> list:
    """หาสี่เหลี่ยม/ขอบเด่นๆ ในรูป แล้วแปลงพิกัดพิกเซล -> พิกัดโลก (กึ่งกลางรูป = (0,0),
    สเกลเต็มความกว้าง/สูงของรูปให้พอดีกับ world_range*2) คืน list ของ {x,y,w,h} หน่วยเมตร"""
    import numpy as _np
    world_range = world_range or CONST_MAP_RANGE_PY
    arr = _np.frombuffer(image_bytes, dtype=_np.uint8)
    img = cv2.imdecode(arr, cv2.IMREAD_COLOR)
    if img is None:
        return []
    h_px, w_px = img.shape[:2]
    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    blurred = cv2.GaussianBlur(gray, (5, 5), 0)
    edges = cv2.Canny(blurred, 50, 150)
    edges = cv2.dilate(edges, None, iterations=2)   # เชื่อมขอบที่ขาดๆ ให้ปิดเป็นรูปทรงมากขึ้น
    contours, _ = cv2.findContours(edges, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

    img_area = w_px * h_px
    scale = (world_range * 2) / max(w_px, h_px)   # เมตรต่อพิกเซล
    rects = []
    for c in contours:
        x, y, bw, bh = cv2.boundingRect(c)
        if (bw * bh) / img_area < min_area_frac:
            continue   # เล็กเกินไป (แทบทุกภาพมี noise เต็มไปหมด กรองทิ้ง)
        # จุดกึ่งกลาง bounding box พิกเซล -> โลก (กลับแกน y เพราะพิกเซลนับจากบนลงล่าง)
        cx_px, cy_px = x + bw / 2, y + bh / 2
        wx = (cx_px - w_px / 2) * scale
        wy = (h_px / 2 - cy_px) * scale
        rects.append({"x": round(wx, 2), "y": round(wy, 2),
                     "w": round(max(bw * scale, 0.3), 2), "h": round(max(bh * scale, 0.3), 2)})
    # เอาอันใหญ่สุดก่อน (มักเป็นโครงสร้างจริงมากกว่า noise เล็กๆ) จำกัดจำนวนกันวางรกเกิน
    rects.sort(key=lambda r: r["w"] * r["h"], reverse=True)
    return rects[:max_objects]


def _ai_vision_analyze_photo(image_bytes: bytes, media_type: str, world_range: float = None,
                             max_objects: int = 40) -> list | None:
    """ให้ AI vision (ใช้ AI_SERVER_LLM_API_URL/_KEY ชุดเดียวกับระบบ RAG ที่ [ ai_server_rag ]
    ด้านล่างของไฟล์) ช่วยดูรูปแล้วบอกตำแหน่งกำแพง/สิ่งกีดขวางที่เห็นจริงในภาพ — ดีกว่า
    การตรวจจับขอบแบบ OpenCV ล้วนๆ ตรงที่เข้าใจ "ความหมาย" ของสิ่งที่เห็น (แยกกำแพง
    ออกจากเงา/กรอบรูปได้) แต่ก็ยังเป็นการ "เดาจากภาพ 2 มิติ" อยู่ดี ไม่ใช่การวัดระยะจริง
    — คืน None ถ้ายังไม่ได้ตั้งค่า AI_SERVER_LLM_API_URL/_KEY หรือเรียก/parse ไม่สำเร็จ
    (ให้ caller fallback ไปใช้ analyze_photo_to_obstacle_rects แบบ edge-detection แทน)"""
    if not (AI_SERVER_LLM_API_URL and AI_SERVER_LLM_API_KEY):
        return None
    world_range = world_range or CONST_MAP_RANGE_PY
    b64 = base64.b64encode(image_bytes).decode("ascii")
    prompt = (
        "ดูภาพนี้แล้วระบุ \"สิ่งกีดขวาง/กำแพง/โครงสร้างทางกายภาพ\" ที่เห็นจริงในภาพ "
        "(ไม่เอาเงา ไม่เอากรอบรูป ไม่เอาพื้นหลังลอยๆ) ตอบเป็น JSON array ล้วนๆ เท่านั้น "
        "ห้ามมีข้อความอื่นก่อน/หลัง แต่ละอ็อบเจกต์มีฟิลด์: label (ชื่อสั้นๆ), "
        "x_frac, y_frac (จุดกึ่งกลางของวัตถุ เทียบเป็นสัดส่วน 0-1 ของภาพ นับจากซ้ายบน), "
        "w_frac, h_frac (ขนาดกว้าง/สูง เทียบเป็นสัดส่วนของภาพ) "
        f"ระบุได้ไม่เกิน {max_objects} ชิ้น เรียงจากชิ้นใหญ่/สำคัญที่สุดก่อน"
    )
    headers = {"x-api-key": AI_SERVER_LLM_API_KEY, "anthropic-version": "2023-06-01",
              "content-type": "application/json"}
    payload = {"model": "claude-sonnet-4-6", "max_tokens": 1500,
              "messages": [{"role": "user", "content": [
                  {"type": "image", "source": {"type": "base64", "media_type": media_type, "data": b64}},
                  {"type": "text", "text": prompt},
              ]}]}
    try:
        resp = requests.post(AI_SERVER_LLM_API_URL, json=payload, headers=headers, timeout=45)
        resp.raise_for_status()
        data = resp.json()
        text = "".join(b.get("text", "") for b in data.get("content", []) if b.get("type") == "text").strip()
        if text.startswith("```"):
            text = text.strip("`")
            text = text.split("\n", 1)[-1] if "\n" in text else text
        items = json.loads(text)
    except Exception as e:
        print(f"[photo-library] AI vision analyze ล้มเหลว, fallback ไป edge-detection: {e}")
        return None

    rects = []
    for it in items[:max_objects]:
        try:
            xf, yf = float(it["x_frac"]), float(it["y_frac"])
            wf, hf = float(it["w_frac"]), float(it["h_frac"])
        except (KeyError, TypeError, ValueError):
            continue
        wx = (xf - 0.5) * world_range * 2
        wy = (0.5 - yf) * world_range * 2   # กลับแกน y เพราะพิกเซล/สัดส่วนภาพนับจากบนลงล่าง
        rects.append({"x": round(wx, 2), "y": round(wy, 2),
                     "w": round(max(wf * world_range * 2, 0.3), 2),
                     "h": round(max(hf * world_range * 2, 0.3), 2),
                     "label": str(it.get("label", "object"))[:40]})
    return rects or None


@app.route('/api/photo-library/upload', methods=['POST'])
@require_auth_toggleable
def api_photo_library_upload():
    """เก็บรูปเข้าคลัง — field: image (ไฟล์), uploader (ไม่บังคับ) ยังไม่วิเคราะห์
    ตอนนี้ ต้องกด /generate-map ทีหลังถึงจะแปลงเป็น obstacle ในเกม"""
    f = request.files.get('image')
    if not f or not f.filename:
        return jsonify({"st": "error", "msg": "ต้องแนบไฟล์ภาพ (field: image)"}), 400
    ext = (f.filename.rsplit('.', 1)[-1] if '.' in f.filename else '').lower()
    if ext not in ALLOWED_PAGE_EXTENSIONS:
        return jsonify({"st": "error", "msg": "รองรับเฉพาะ jpg/jpeg/png/webp"}), 400
    photo_id = uuid.uuid4().hex[:8]
    photo_dir = os.path.join(PHOTO_LIBRARY_DIR, photo_id)
    os.makedirs(photo_dir, exist_ok=True)
    fname = secure_filename(f"photo.{ext}")
    f.save(os.path.join(photo_dir, fname))
    PHOTO_LIBRARY[photo_id] = {"uploader": request.form.get('uploader', ''), "filename": fname,
                               "uploaded_at": time.time(), "analyzed": False,
                               "generated_obstacle_ids": []}
    _photo_library_save_index()
    return jsonify({"st": "ok", "photo_id": photo_id})


@app.route('/api/photo-library', methods=['GET'])
def api_photo_library_list():
    return jsonify({"st": "ok", "photos": PHOTO_LIBRARY})


@app.route('/api/photo-library/<photo_id>/image', methods=['GET'])
def api_photo_library_get_image(photo_id):
    p = PHOTO_LIBRARY.get(photo_id)
    if not p:
        return jsonify({"st": "error", "msg": "ไม่พบรูปนี้ในคลัง"}), 404
    return send_from_directory(os.path.join(PHOTO_LIBRARY_DIR, photo_id), p["filename"])


@app.route('/api/photo-library/<photo_id>/generate-map', methods=['POST'])
@require_auth_toggleable
def api_photo_library_generate_map(photo_id):
    """วิเคราะห์รูปที่อยู่ในคลังแล้ววาง obstacle ลงในโลกฟิสิกส์จริงให้อัตโนมัติ —
    ลอง AI vision ก่อน (ถ้าตั้งค่า AI_SERVER_LLM_API_URL/_KEY ไว้แล้ว แม่นยำกว่าเพราะ
    เข้าใจความหมายของภาพ) ถ้าไม่ได้ตั้งค่าไว้หรือเรียกไม่สำเร็จ จะ fallback ไปใช้การ
    ตรวจจับขอบแบบ OpenCV แทน (หยาบกว่า) — ไม่ว่าจะวิธีไหนก็ยังเป็นการประมาณจากภาพ
    2 มิติ ไม่ใช่การวัดระยะจริง แนะนำเข้าไปดู/ปรับที่หน้า /map หลังสร้างเสร็จทุกครั้ง"""
    p = PHOTO_LIBRARY.get(photo_id)
    if not p:
        return jsonify({"st": "error", "msg": "ไม่พบรูปนี้ในคลัง"}), 404
    photo_path = os.path.join(PHOTO_LIBRARY_DIR, photo_id, p["filename"])
    with open(photo_path, "rb") as f:
        image_bytes = f.read()
    ext = p["filename"].rsplit(".", 1)[-1].lower()
    media_type = {"jpg": "image/jpeg", "jpeg": "image/jpeg",
                 "png": "image/png", "webp": "image/webp"}.get(ext, "image/jpeg")

    method = "ai_vision"
    rects = _ai_vision_analyze_photo(image_bytes, media_type)
    if not rects:
        method = "edge_detection_fallback"
        rects = analyze_photo_to_obstacle_rects(image_bytes)
    if not rects:
        return jsonify({"st": "error", "msg": "วิเคราะห์รูปนี้แล้วไม่เจอรูปทรง/ขอบที่ชัดเจนพอจะสร้างเป็นแผนที่ได้"}), 400

    created_ids = [physics_add_obstacle(r["x"], r["y"], r["w"], r["h"]) for r in rects]
    p["analyzed"] = True
    p["generated_obstacle_ids"] = created_ids
    p["last_method"] = method
    _photo_library_save_index()
    note = ("วิเคราะห์ด้วย AI vision (เข้าใจความหมายของสิ่งที่เห็นในภาพ ไม่ใช่แค่ตรวจขอบ) "
           if method == "ai_vision" else
           "ยังไม่ได้ตั้งค่า AI_SERVER_LLM_API_URL/_KEY (หรือเรียกไม่สำเร็จ) เลย fallback ไปใช้ "
           "การตรวจจับขอบแบบ OpenCV แทน (หยาบกว่า) ")
    return jsonify({"st": "ok", "photo_id": photo_id, "method": method,
                    "obstacle_count": len(created_ids), "obstacle_ids": created_ids,
                    "note": note + "— ยังเป็นการประมาณจากภาพ 2 มิติอยู่ดี ไม่ใช่การวัดระยะจริง "
                                    "แนะนำเข้าไปดู/ปรับที่หน้า /map ต่อ"})


VMAX_MODULES["photo_library_auto_map"] = {
    "desc": "อัปโหลดรูปเก็บคลัง แล้ววิเคราะห์อัตโนมัติเพื่อวาง obstacle ลงแผนที่เกมให้ — ใช้ AI vision "
            "ก่อน (ถ้าตั้งค่า AI_SERVER_LLM_API_URL/_KEY) แม่นยำกว่าเพราะเข้าใจความหมายของภาพ ถ้าไม่ได้ตั้งค่า "
            "จะ fallback ไปใช้ OpenCV edge/contour detection แทน (หยาบกว่า) — ทั้งสองวิธียังเป็นค่าประมาณ "
            "จากภาพ 2 มิติ ต้องมาปรับเองต่อที่ /map",
    "routes": ["/api/photo-library/upload", "/api/photo-library", "/api/photo-library/<id>/image",
              "/api/photo-library/<id>/generate-map"],
}


# ==========================================
# [ 6m3. Earth Engine Satellite Import -> Auto Map Generation ]
# จุดเชื่อมระหว่างสองไฟล์ที่รวมกันมา: ปลั๊กอิน "qgis-earthengine-plugin" เป็นปลั๊กอิน
# ของโปรแกรม QGIS (desktop GIS) รันอยู่ *ภายใน* QGIS เท่านั้น ใช้ qgis.core/qgis.PyQt
# — เอาโค้ดของมันมารันในเซิร์ฟเวอร์ Flask ตรงๆ ไม่ได้ (คนละ runtime กันโดยสิ้นเชิง)
# ดังนั้นจุดที่เชื่อมกันได้จริงคือ "แหล่งข้อมูล Google Earth Engine" ตัวเดียวกับที่
# ปลั๊กอิน QGIS เรียกใช้อยู่ข้างใน (ผ่านไลบรารี earthengine-api ของ Google) เอามาป้อน
# ให้ระบบ Photo Library -> Auto Map Generation ที่ [ 6m2 ] ด้านบนแทนการอัปโหลดรูปเอง —
# ใส่พิกัด lat/lon มา ระบบจะไปดึงภาพถ่ายดาวเทียม Sentinel-2 จริงของจุดนั้นจาก Earth
# Engine มาเก็บเข้าคลังเดียวกัน แล้วส่งต่อเข้า pipeline วิเคราะห์/วาง obstacle เดิมได้เลย
#
# ข้อจำกัดที่ต้องพูดตรงๆ:
#  - ต้องมีบัญชี Google Earth Engine ที่ลงทะเบียนแล้ว (https://signup.earthengine.google.com)
#    และตั้งค่า credential ก่อนใช้งานจริง ไม่งั้น endpoint นี้จะตอบ error กลับมา (ไม่ใช่ crash
#    ทั้งแอป — ตัวแอปยังบูตและใช้งานส่วนอื่นได้ปกติแม้ยังไม่ได้ตั้งค่า Earth Engine)
#  - ตั้งค่าได้ 3 ทาง (เรียงตามลำดับที่ระบบจะลองใช้): (1) ผ่านหน้าเว็บ /admin/earthengine-settings
#    ที่ฝังมาในไฟล์นี้เลย — วาง service account email + เนื้อหาไฟล์ key .json ผ่านฟอร์มได้เลย
#    ไม่ต้องยุ่งกับ env var ของเซิร์ฟเวอร์ (2) env EE_SERVICE_ACCOUNT + EE_SERVICE_ACCOUNT_KEY_FILE
#    (3) เคยรัน `earthengine authenticate` ไว้ล่วงหน้าในเครื่องนี้แล้ว (โหมด user credential)
#  - ตั้ง env หรือกรอกในฟอร์ม EE_PROJECT เป็น Google Cloud project ที่เปิดใช้ Earth Engine API ไว้ด้วย
#  - ผลลัพธ์เป็นภาพเรนเดอร์ true-color (RGB) ที่เมฆบังน้อยสุดในรอบ 90 วันล่าสุดของจุดนั้น
#    ไม่ใช่ข้อมูลเรียลไทม์ และการแปลงพิกเซล -> obstacle ยังเป็นการประมาณแบบเดิมที่ [ 6m2 ]
#
# โค้ดสองส่วนถัดไป (radians/hillshade/hillshadeRGB และ EE_PALETTES) คัดลอกมาจริงจาก
# ee_plugin/contrib/utils.py และ ee_plugin/contrib/palettes.py ในปลั๊กอิน QGIS ที่แนบมา —
# เป็นสองไฟล์เดียวในปลั๊กอินทั้งหมดที่ "ไม่ import qgis/PyQt เลย" (เช็คแล้วด้วย grep) จึงยกมา
# ใช้ตรงๆ ได้จริง ไม่ต้องเขียนใหม่ (ต้นฉบับ MIT License โดย Gennadii Donchyts และผู้ร่วมพัฒนา)
# ==========================================

# --- คัดลอกจาก ee_plugin/contrib/utils.py (MIT License) ---
def ee_radians(img):
    """แปลงภาพจากหน่วยองศาเป็นเรเดียน"""
    return img.toFloat().multiply(math.pi).divide(180)


def ee_hillshade(az, ze, slope, aspect):
    """คำนวณ hillshade (แสงเงาภูมิประเทศ) จากมุมและความชัน — ใช้ภายใน ee_hillshade_rgb"""
    import ee
    azimuth = ee_radians(ee.Image.constant(az))
    zenith = ee_radians(ee.Image.constant(90).subtract(ee.Image.constant(ze)))
    return (azimuth.subtract(aspect).cos().multiply(slope.sin()).multiply(zenith.sin())
           .add(zenith.cos().multiply(slope.cos())))


def ee_hillshade_rgb(image, elevation, weight=1, height_multiplier=5, azimuth=0,
                     zenith=45, contrast=0, brightness=0, saturation=1):
    """ผสมภาพ RGB เข้ากับ hillshade ของภูมิประเทศ (ใช้ elevation เช่น SRTM) ให้เห็นความสูง-ต่ำ
    ของพื้นที่ชัดขึ้นก่อนส่งเข้า pipeline วาง obstacle — มีประโยชน์กับพื้นที่ภูเขา/หุบเขา
    ที่ภาพสีเฉยๆ มองไม่ออกว่าเป็นเนินหรือที่ราบ"""
    import ee
    hsv = image.visualize().unitScale(0, 255).rgbToHsv()
    z = elevation.multiply(ee.Image.constant(height_multiplier))
    terrain = ee.Algorithms.Terrain(z)
    slope = ee_radians(terrain.select(["slope"])).resample("bicubic")
    aspect = ee_radians(terrain.select(["aspect"])).resample("bicubic")
    hs = ee_hillshade(azimuth, zenith, slope, aspect).resample("bicubic")
    intensity = hs.multiply(ee.Image.constant(weight)).add(
        hsv.select("value").multiply(ee.Image.constant(1).subtract(weight)))
    sat = hsv.select("saturation").multiply(saturation)
    hue = hsv.select("hue")
    return (ee.Image.cat(hue, sat, intensity).hsvToRgb()
           .multiply(ee.Image.constant(1).float().add(contrast))
           .add(ee.Image.constant(brightness).float()))


# --- คัดลอกมาจริงจาก ee_plugin/contrib/palettes.py (MIT License) — ใช้เลือกจานสีตอน
# render ภาพจาก Earth Engine เช่น NDVI/elevation ให้ตีความง่ายขึ้นกว่าสีจริง (true color) ---
EE_PALETTES = {
    "elevation": ["0000ff", "00ffff", "ffff00", "ff0000", "ffffff"],
    "ndvi": ["ffffff", "ce7e45", "df923d", "f1b555", "fcd163", "99b718", "74a901",
            "66a000", "529400", "3e8601", "207401", "056201", "004c00", "023b01",
            "012e01", "011d01", "011301"],
    "water": ["ffffff", "d4f0ff", "a2d4f7", "5aa8d8", "1f5f99", "0a2f52"],
}

EE_INITIALIZED = False
EE_INIT_ERROR = ""

# ที่เก็บ credential ที่กรอกผ่านหน้าเว็บ /admin/earthengine-settings (ทางเลือกแทน env var) —
# เข้ารหัสด้วย Fernet (ไลบรารีเดียวกับที่ระบบ Vault ของแอปนี้ใช้อยู่แล้วที่ [ 6v/vault ])
# ก่อนเขียนลงดิสก์ กุญแจเข้ารหัสถูกสุ่มสร้างครั้งแรกแล้วเก็บแยกไฟล์ในเครื่องนี้เท่านั้น —
# นี่ป้องกันการเห็น key แบบ plaintext เผลอๆ ในไฟล์ แต่ไม่ได้แทนที่การดูแลเซิร์ฟเวอร์ให้
# ปลอดภัย (จำกัดสิทธิ์เข้าถึงเครื่อง/ดิสก์นี้เองด้วย)
EE_CRED_DIR = "vmax_data"
EE_CRED_ENC_PATH = os.path.join(EE_CRED_DIR, "earthengine_credential.enc")
EE_CRED_FERNET_KEY_PATH = os.path.join(EE_CRED_DIR, "earthengine_credential.fernetkey")
os.makedirs(EE_CRED_DIR, exist_ok=True)


def _ee_cred_fernet():
    if not os.path.exists(EE_CRED_FERNET_KEY_PATH):
        with open(EE_CRED_FERNET_KEY_PATH, "wb") as f:
            f.write(Fernet.generate_key())
    with open(EE_CRED_FERNET_KEY_PATH, "rb") as f:
        return Fernet(f.read())


def _ee_cred_save(service_account_email: str, key_json_text: str, project: str):
    payload = json.dumps({"service_account_email": service_account_email,
                          "key_json_text": key_json_text, "project": project}).encode("utf-8")
    enc = _ee_cred_fernet().encrypt(payload)
    with open(EE_CRED_ENC_PATH, "wb") as f:
        f.write(enc)
    global EE_INITIALIZED
    EE_INITIALIZED = False   # บังคับให้ initialize ใหม่ด้วย credential ล่าสุดตอนถูกเรียกใช้ครั้งถัดไป


def _ee_cred_load():
    if not os.path.exists(EE_CRED_ENC_PATH):
        return None
    try:
        with open(EE_CRED_ENC_PATH, "rb") as f:
            enc = f.read()
        payload = _ee_cred_fernet().decrypt(enc)
        return json.loads(payload.decode("utf-8"))
    except (InvalidToken, Exception):
        return None


def _ee_ensure_initialized():
    """เชื่อมต่อ Google Earth Engine แบบ lazy (เชื่อมจริงตอนถูกเรียกใช้งานครั้งแรกเท่านั้น
    ไม่กระทบการบูตแอปหลักแม้ยังไม่ได้ตั้งค่า/ยังไม่ได้ติดตั้ง earthengine-api) ลองอ่าน
    credential ที่กรอกผ่านหน้าเว็บ /admin/earthengine-settings ก่อน ถ้าไม่มีค่อย fallback
    ไป env var แบบเดิม คืน (True, "") ถ้าเชื่อมต่อสำเร็จ, (False, เหตุผล) ถ้าไม่สำเร็จ"""
    global EE_INITIALIZED, EE_INIT_ERROR
    if EE_INITIALIZED:
        return True, ""
    try:
        import ee
    except ImportError:
        EE_INIT_ERROR = "ยังไม่ได้ติดตั้ง earthengine-api — รัน: pip install earthengine-api"
        return False, EE_INIT_ERROR
    try:
        stored = _ee_cred_load()
        if stored and stored.get("service_account_email") and stored.get("key_json_text"):
            key_file_path = os.path.join(EE_CRED_DIR, "_earthengine_key_runtime.json")
            with open(key_file_path, "w", encoding="utf-8") as f:
                f.write(stored["key_json_text"])
            creds = ee.ServiceAccountCredentials(stored["service_account_email"], key_file_path)
            ee.Initialize(creds, project=stored.get("project") or None)
        else:
            service_account = os.environ.get("EE_SERVICE_ACCOUNT", "")
            key_file = os.environ.get("EE_SERVICE_ACCOUNT_KEY_FILE", "")
            project = os.environ.get("EE_PROJECT", "") or None
            if service_account and key_file and os.path.exists(key_file):
                creds = ee.ServiceAccountCredentials(service_account, key_file)
                ee.Initialize(creds, project=project)
            else:
                ee.Initialize(project=project)   # ใช้ credential ที่เคย `earthengine authenticate` ไว้แล้ว
        EE_INITIALIZED = True
        return True, ""
    except Exception as e:
        EE_INIT_ERROR = (f"เชื่อมต่อ Google Earth Engine ไม่สำเร็จ: {e} — กรอก credential ที่หน้า "
                        "/admin/earthengine-settings หรือตั้งค่า EE_SERVICE_ACCOUNT + "
                        "EE_SERVICE_ACCOUNT_KEY_FILE หรือรัน `earthengine authenticate` ก่อน")
        return False, EE_INIT_ERROR


