# ==========================================
# [ 6p. Admin Panel ตามยศ (แทน terminal เปิดโล่ง) ]
# แทนที่จะเปิด terminal ให้รันคำสั่งอะไรก็ได้ (เสี่ยงถูกยึดเซิร์ฟเวอร์ทั้งเครื่องถ้า
# หลุด auth) ระบบนี้ทำงานคล้าย terminal (พิมพ์ชื่อ action + พารามิเตอร์) แต่จำกัดให้
# เลือกได้เฉพาะ action ที่ลงทะเบียนไว้ล่วงหน้าเท่านั้น และเช็คยศก่อนทุกครั้ง
# ==========================================

STAFF_RANKS = {"owner": 100, "admin": 80, "developer": 70, "moderator": 50, "support": 20}
STAFF_MEMBERS = {}   # staff_uid -> {"name": str, "rank": "owner"|"admin"|"developer"|"moderator"|"support"}
# [ADD] ยศ "developer" — ใช้ endpoint เดิม /api/staff/register (ด้านล่าง [6p]) ตั้งได้เลย
# (ต้องเป็น owner ถึงจะตั้งคนอื่นได้ เหมือนยศอื่น ๆ) ผลคือ uid นั้นจะได้ชื่อสีแดงในแชท +
# badge "🛠️ Developer" อัตโนมัติทุกที่ที่ส่งข้อความ ดู get_chat_identity() ที่ [6zz5f0b]


def _staff_rank_value(staff_uid):
    m = STAFF_MEMBERS.get(staff_uid)
    if not m:
        return -1
    return STAFF_RANKS.get(m["rank"], -1)


# --- [PATCHED] ดึงตัวตนพนักงานจาก Bearer JWT เท่านั้น (ใช้ระบบล็อกอินเดียวกับ
# ผู้เล่นทั่วไป: verify_jwt/SESSIONS ที่มีอยู่แล้วในไฟล์นี้) ------------------------
# เดิม /api/admin/run, /api/admin/panel, /api/approve_feature/<fid> อ่านค่า
# staff_uid ตรง ๆ จาก body/query ที่ client พิมพ์เอง ทำให้ใครก็ปลอม staff_uid ของ
# owner/admin คนอื่นมาสวมสิทธิ์ได้ทันที (privilege escalation) — ฟังก์ชันนี้บังคับ
# ให้ uid ต้องมาจาก token ที่เซิร์ฟเวอร์เซ็นให้ตอนล็อกอินจริงเท่านั้น แก้ไม่ได้จากฝั่ง client
def _staff_from_request():
    """คืน (uid, rank_value) ของผู้ที่ล็อกอินอยู่ตอนนี้ (จาก Authorization: Bearer <jwt>)
    คืน (None, None) ถ้าไม่มี/หมดอายุ token; rank_value เป็น -1 ถ้า uid นี้ยังไม่ใช่พนักงาน"""
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    sess = verify_jwt(token)
    if not sess:
        return None, None
    uid = sess["uid"]
    return uid, _staff_rank_value(uid)


# --- ชุด action ที่อนุญาต (whitelist เท่านั้น ห้ามมี eval/exec/รันคำสั่งอิสระ) ----
def _action_toggle_electronics_market(params):
    global ELECTRONICS_MARKET_OPEN
    ELECTRONICS_MARKET_OPEN = bool(params.get("open", not ELECTRONICS_MARKET_OPEN))
    return {"open": ELECTRONICS_MARKET_OPEN}


def _action_confirm_manga_license(params):
    title_id = params.get("title_id")
    t = MANGA_TITLES.get(title_id)
    if not t:
        return {"error": "ไม่พบเรื่องนี้"}
    if t["license"]["status"] == "missing":
        return {"error": "ยังไม่ได้อัปโหลดเอกสารลิขสิทธิ์"}
    t["license"]["status"] = "confirmed"
    _manga_save_index()
    return {"license": t["license"]}


def _action_view_sales_summary(params):
    return {"manga_sales_count": len(MANGA_SALES),
            "manga_gross": round(sum(s["gross"] for s in MANGA_SALES), 2),
            "electronics_listings": len(ELECTRONICS_LISTINGS),
            "electronics_invoices": len(ELECTRONICS_INVOICES)}


def _action_refresh_vat_rates(params):
    source_url = params.get("source_url")
    if not source_url:
        return {"error": "ต้องระบุ source_url"}
    try:
        return {"rates": refresh_vat_rates_from_url(source_url)}
    except Exception as e:
        return {"error": str(e)}


def _action_delete_gallery_comment(params):
    post_id = params.get("post_id")
    comment_id = params.get("comment_id")
    p = GALLERY_POSTS.get(post_id)
    if not p:
        return {"error": "ไม่พบโพสต์นี้"}
    before = len(p["comments"])
    p["comments"] = [c for c in p["comments"] if c["comment_id"] != comment_id]
    if len(p["comments"]) == before:
        return {"error": "ไม่พบคอมเมนต์นี้"}
    _gallery_save_index()
    return {"deleted": comment_id}


# ชื่อ action -> (ยศขั้นต่ำที่ใช้ได้, ฟังก์ชัน, คำอธิบาย)
ADMIN_ACTIONS = {
    "toggle_electronics_market": (STAFF_RANKS["admin"], _action_toggle_electronics_market,
                                  "เปิด/ปิดโซนขายอุปกรณ์อิเล็กทรอนิกส์"),
    "confirm_manga_license": (STAFF_RANKS["moderator"], _action_confirm_manga_license,
                              "ยืนยันลิขสิทธิ์มังงะเรื่องหนึ่ง (params: title_id)"),
    "view_sales_summary": (STAFF_RANKS["support"], _action_view_sales_summary,
                           "ดูสรุปยอดขายรวมทั้งระบบ"),
    "refresh_vat_rates": (STAFF_RANKS["admin"], _action_refresh_vat_rates,
                          "ดึงอัตรา VAT ล่าสุด (params: source_url)"),
    "delete_gallery_comment": (STAFF_RANKS["moderator"], _action_delete_gallery_comment,
                               "ลบคอมเมนต์ในแกลเลอรี (params: post_id, comment_id)"),
}


@app.route('/api/staff/register', methods=['POST'])
def api_staff_register():
    """[PATCHED] เพิ่มพนักงาน/ทีมงานพร้อมยศ — เดิม endpoint นี้เปิดโล่งให้ใครก็ได้
    ยิง POST เข้ามาสร้างตัวเองเป็น 'owner' ฟรี ๆ (self-service privilege escalation)
    ตอนนี้บังคับ:
      - ถ้ายังไม่มีพนักงานเลยในระบบ (bootstrap ครั้งแรก) ต้องแนบ
        X-Staff-Bootstrap-Key ให้ตรงกับ env var VMAX_STAFF_BOOTSTRAP_KEY เท่านั้น
      - ถ้ามีพนักงานอยู่แล้ว ผู้เรียกต้องล็อกอิน (Bearer JWT) และมียศ owner เท่านั้น
    body: {target_uid, name, rank} — target_uid คือ uid บัญชีผู้เล่นจริงที่จะตั้งเป็นพนักงาน
    (STAFF_MEMBERS ผูกกับ uid บัญชีจริงโดยตรง ไม่ใช่รหัสสุ่มลอย ๆ แบบเดิมอีกต่อไป)"""
    body = request.json or {}
    target_uid = (body.get('target_uid') or '').strip()
    name = (body.get('name') or '').strip()
    rank = body.get('rank', 'support')
    if rank not in STAFF_RANKS:
        return jsonify({"st": "error", "msg": f"ยศต้องเป็นหนึ่งใน {list(STAFF_RANKS.keys())}"}), 400
    if not target_uid:
        return jsonify({"st": "error", "msg": "ต้องระบุ target_uid (uid บัญชีผู้เล่นที่จะตั้งเป็นพนักงาน)"}), 400

    if not STAFF_MEMBERS:
        bootstrap_key = request.headers.get('X-Staff-Bootstrap-Key', '')
        expected = os.environ.get('VMAX_STAFF_BOOTSTRAP_KEY', '')
        if not expected or not hmac.compare_digest(bootstrap_key, expected):
            return jsonify({"st": "error",
                             "msg": "ยังไม่มีพนักงานในระบบ ต้อง bootstrap owner คนแรกด้วย "
                                    "X-Staff-Bootstrap-Key ที่ตรงกับ env var VMAX_STAFF_BOOTSTRAP_KEY เท่านั้น"}), 403
    else:
        caller_uid, caller_rank = _staff_from_request()
        if caller_uid is None:
            return jsonify({"st": "error", "msg": "ต้องล็อกอินก่อน (Bearer token)"}), 401
        if caller_rank < STAFF_RANKS["owner"]:
            return jsonify({"st": "error", "msg": "ต้องเป็น owner เท่านั้นถึงจะเพิ่มพนักงานได้"}), 403

    STAFF_MEMBERS[target_uid] = {"name": name, "rank": rank}
    return jsonify({"st": "ok", "staff_uid": target_uid, "staff": STAFF_MEMBERS[target_uid]})


@app.route('/api/admin/panel', methods=['GET'])
def api_admin_panel():
    """[PATCHED] แสดงรายการ action ที่ผู้ล็อกอินอยู่ตอนนี้มีสิทธิ์ใช้ — ดึง uid จาก
    Bearer JWT เท่านั้น (เดิมรับ staff_uid ลอย ๆ จาก query string ทำให้ดูสิทธิ์ของ
    คนอื่นหรือปลอมตัวได้)"""
    uid, my_rank = _staff_from_request()
    if uid is None:
        return jsonify({"st": "error", "msg": "ต้องล็อกอินก่อน (Bearer token)"}), 401
    if my_rank < 0:
        return jsonify({"st": "error", "msg": "ไม่พบพนักงานนี้"}), 403
    available = {name: desc for name, (min_rank, _, desc) in ADMIN_ACTIONS.items()
                if my_rank >= min_rank}
    return jsonify({"st": "ok", "your_rank": STAFF_MEMBERS[uid]["rank"], "actions": available})


@app.route('/api/admin/run', methods=['POST'])
def api_admin_run():
    """[PATCHED] รัน action ที่อยู่ใน whitelist เท่านั้น — ดึงตัวตนพนักงานจาก Bearer
    JWT เสมอ (เดิมอ่าน staff_uid จาก body ตรง ๆ ทำให้ใครก็ปลอม staff_uid ของ
    owner/admin คนอื่นมาสวมสิทธิ์รันคำสั่งระดับแอดมินได้ — privilege escalation)
    body: {action, params}"""
    uid, my_rank = _staff_from_request()
    if uid is None:
        return jsonify({"st": "error", "msg": "ต้องล็อกอินก่อน (Bearer token)"}), 401
    if my_rank < 0:
        return jsonify({"st": "error", "msg": "ไม่พบพนักงานนี้"}), 403
    body = request.json or {}
    action_name = body.get('action', '')
    params = body.get('params', {}) or {}
    action = ADMIN_ACTIONS.get(action_name)
    if not action:
        return jsonify({"st": "error", "msg": f"ไม่มี action '{action_name}' — ดูรายการที่ /api/admin/panel"}), 404
    min_rank, func, _ = action
    if my_rank < min_rank:
        return jsonify({"st": "error", "msg": "ยศไม่พอสำหรับ action นี้"}), 403
    result = func(params)
    return jsonify({"st": "ok", "action": action_name, "result": result})


@app.route('/api/admin/auth-enforcement/list', methods=['GET'])
def api_admin_auth_enforcement_list():
    """[P0.6] รายชื่อ endpoint ทั้งหมดที่อยู่ในระบบ toggleable auth (แปะ
    @require_auth_toggleable) พร้อมสถานะเปิด/ปิดปัจจุบัน และ path/methods จริงของ
    แต่ละ endpoint (ดึงจาก app.url_map — Flask ใช้ชื่อฟังก์ชัน view เป็น
    rule.endpoint โดย default จึงจับคู่กับ AUTH_TOGGLEABLE_ENDPOINTS ได้ตรงๆ)
    ต้องล็อกอินเป็นพนักงาน (ยศ >= support) เท่านั้นถึงจะดูได้"""
    uid, my_rank = _staff_from_request()
    if uid is None:
        return jsonify({"st": "error", "msg": "ต้องล็อกอินก่อน (Bearer token)"}), 401
    if my_rank < STAFF_RANKS["support"]:
        return jsonify({"st": "error", "msg": "ต้องเป็นพนักงานเท่านั้นถึงจะดูได้"}), 403

    path_map: dict = {}
    for rule in app.url_map.iter_rules():
        if rule.endpoint in AUTH_TOGGLEABLE_ENDPOINTS:
            info = path_map.setdefault(rule.endpoint, {"paths": [], "methods": set()})
            info["paths"].append(str(rule))
            info["methods"] |= (rule.methods - {"HEAD", "OPTIONS"})

    out = []
    for key in sorted(AUTH_TOGGLEABLE_ENDPOINTS):
        info = path_map.get(key, {"paths": [], "methods": set()})
        out.append({
            "endpoint": key,
            "enabled": is_auth_enforced(key),
            "paths": info["paths"],
            "methods": sorted(info["methods"]),
        })
    return jsonify({"st": "ok", "count": len(out), "endpoints": out})


@app.route('/api/admin/auth-enforcement/toggle', methods=['POST'])
def api_admin_auth_enforcement_toggle():
    """[P0.6] เปิด/ปิดการบังคับ auth เฉพาะจุดของ endpoint หนึ่งตัวที่แปะ
    @require_auth_toggleable ไว้ — เปลี่ยนผลทันทีโดยไม่ต้อง restart/deploy (เขียนลง
    AUTH_ENFORCEMENT_PATH ทันที) ต้องเป็นแอดมิน (ยศ >= admin) เท่านั้น และทุกครั้งที่
    toggle จะถูก audit_log('auth_enforcement_toggled', ...) ไว้เพื่อตรวจสอบย้อนหลังได้
    body: {endpoint: <ชื่อ endpoint จาก /api/admin/auth-enforcement/list>, enabled: true/false}"""
    uid, my_rank = _staff_from_request()
    if uid is None:
        return jsonify({"st": "error", "msg": "ต้องล็อกอินก่อน (Bearer token)"}), 401
    if my_rank < STAFF_RANKS["admin"]:
        return jsonify({"st": "error", "msg": "ต้องเป็น admin ขึ้นไปเท่านั้นถึงจะ toggle ได้"}), 403

    body = request.json or {}
    endpoint_key = (body.get('endpoint') or '').strip()
    enabled = body.get('enabled')
    if endpoint_key not in AUTH_TOGGLEABLE_ENDPOINTS:
        return jsonify({"st": "error",
                         "msg": f"ไม่พบ '{endpoint_key}' ในระบบ toggleable auth — "
                                f"ดูรายชื่อที่ /api/admin/auth-enforcement/list"}), 404
    if not isinstance(enabled, bool):
        return jsonify({"st": "error", "msg": "ต้องระบุ enabled เป็น true/false"}), 400

    set_auth_enforcement(endpoint_key, enabled, actor_uid=uid)
    return jsonify({"st": "ok", "endpoint": endpoint_key, "enabled": enabled})


VMAX_MODULES["admin_panel"] = {
    "desc": "แผงแอดมินตามยศ (owner/admin/moderator/support) — รันได้เฉพาะ action ที่ลงทะเบียนไว้ล่วงหน้า ไม่ใช่ terminal เปิดโล่ง",
    "routes": ["/api/staff/register", "/api/admin/panel", "/api/admin/run",
               "/api/admin/auth-enforcement/list", "/api/admin/auth-enforcement/toggle"],
}


# ==========================================
# [ 6q0. โมเดล AI วาดรูปจากลายเส้น — สถาปัตยกรรมที่เขียนเอง (pix2pix-style) ]
# เดิมอยู่ไฟล์แยก train_sketch_model.py — ย้ายมารวมในไฟล์นี้ตามที่ขอ
# ใช้งาน 2 แบบจากไฟล์เดียวกันนี้:
#   1) รันเว็บปกติ:        python App123.py
#   2) สั่งเทรนโมเดล:      python App123.py --train-sketch --dataset ./dataset --epochs 200
# การ import torch/torchvision ทำแบบ "เผื่อไว้" (try/except) เพื่อไม่ให้เว็บทั้งเว็บ
# พังถ้าเครื่องที่รันเว็บยังไม่ได้ลง torch — ฟีเจอร์นี้ใช้ไม่ได้แค่ส่วนเดียวเฉยๆ
# ==========================================

try:
    import torch as _sk_torch
    import torch.nn as _sk_nn
    from torch.utils.data import Dataset as _SkDataset, DataLoader as _SkDataLoader
    from torchvision import transforms as _sk_transforms
    from PIL import Image as _SkImage
    _TORCH_AVAILABLE = True
except ImportError:
    _TORCH_AVAILABLE = False

SKETCH_MODEL_IMG_SIZE = 128


if _TORCH_AVAILABLE:

    class SketchDataset(_SkDataset):
        """โหลดคู่ภาพ (ลายเส้น, ภาพเสร็จ) จาก dataset/sketches/ และ dataset/targets/
        — ชื่อไฟล์ต้องตรงกันทีละคู่"""

        def __init__(self, root_dir, img_size=SKETCH_MODEL_IMG_SIZE):
            self.sketch_dir = os.path.join(root_dir, "sketches")
            self.target_dir = os.path.join(root_dir, "targets")
            self.filenames = sorted(os.listdir(self.sketch_dir))
            self.sketch_tf = _sk_transforms.Compose([
                _sk_transforms.Resize((img_size, img_size)),
                _sk_transforms.Grayscale(num_output_channels=1),
                _sk_transforms.ToTensor(),
            ])
            self.target_tf = _sk_transforms.Compose([
                _sk_transforms.Resize((img_size, img_size)),
                _sk_transforms.ToTensor(),
            ])

        def __len__(self):
            return len(self.filenames)

        def __getitem__(self, idx):
            fname = self.filenames[idx]
            sketch = _SkImage.open(os.path.join(self.sketch_dir, fname)).convert("L")
            target = _SkImage.open(os.path.join(self.target_dir, fname)).convert("RGB")
            return self.sketch_tf(sketch), self.target_tf(target)


    def _sk_down_block(in_ch, out_ch, normalize=True):
        layers = [_sk_nn.Conv2d(in_ch, out_ch, 4, stride=2, padding=1)]
        if normalize:
            layers.append(_sk_nn.BatchNorm2d(out_ch))
        layers.append(_sk_nn.LeakyReLU(0.2, inplace=True))
        return _sk_nn.Sequential(*layers)


    def _sk_up_block(in_ch, out_ch, dropout=False):
        layers = [_sk_nn.ConvTranspose2d(in_ch, out_ch, 4, stride=2, padding=1),
                 _sk_nn.BatchNorm2d(out_ch), _sk_nn.ReLU(inplace=True)]
        if dropout:
            layers.append(_sk_nn.Dropout(0.5))
        return _sk_nn.Sequential(*layers)


    class Generator(_sk_nn.Module):
        """รับภาพลายเส้น 1 ช่อง (grayscale) -> ภาพสี 3 ช่อง (RGB) ขนาด 128x128
        เขียนเองแบบ U-Net encoder-decoder + skip connections (สไตล์ pix2pix)"""

        def __init__(self):
            super().__init__()
            self.d1 = _sk_down_block(1, 64, normalize=False)   # 128 -> 64
            self.d2 = _sk_down_block(64, 128)                  # 64  -> 32
            self.d3 = _sk_down_block(128, 256)                 # 32  -> 16
            self.d4 = _sk_down_block(256, 512)                 # 16  -> 8
            self.d5 = _sk_down_block(512, 512)                 # 8   -> 4

            self.u1 = _sk_up_block(512, 512, dropout=True)     # 4   -> 8
            self.u2 = _sk_up_block(1024, 256)                  # 8   -> 16
            self.u3 = _sk_up_block(512, 128)                   # 16  -> 32
            self.u4 = _sk_up_block(256, 64)                    # 32  -> 64
            self.final = _sk_nn.ConvTranspose2d(128, 3, 4, stride=2, padding=1)  # 64 -> 128

        def forward(self, x):
            d1 = self.d1(x)
            d2 = self.d2(d1)
            d3 = self.d3(d2)
            d4 = self.d4(d3)
            d5 = self.d5(d4)

            u1 = self.u1(d5)
            u2 = self.u2(_sk_torch.cat([u1, d4], dim=1))
            u3 = self.u3(_sk_torch.cat([u2, d3], dim=1))
            u4 = self.u4(_sk_torch.cat([u3, d2], dim=1))
            out = self.final(_sk_torch.cat([u4, d1], dim=1))
            return _sk_torch.sigmoid(out)


    class Discriminator(_sk_nn.Module):
        """PatchGAN — ตัดสินทีละ patch ว่าคู่ภาพนี้ 'จริง' หรือ 'ปลอม'"""

        def __init__(self):
            super().__init__()
            self.model = _sk_nn.Sequential(
                _sk_nn.Conv2d(1 + 3, 64, 4, stride=2, padding=1), _sk_nn.LeakyReLU(0.2, inplace=True),
                _sk_nn.Conv2d(64, 128, 4, stride=2, padding=1), _sk_nn.BatchNorm2d(128), _sk_nn.LeakyReLU(0.2, inplace=True),
                _sk_nn.Conv2d(128, 256, 4, stride=2, padding=1), _sk_nn.BatchNorm2d(256), _sk_nn.LeakyReLU(0.2, inplace=True),
                _sk_nn.Conv2d(256, 1, 4, stride=1, padding=1),
            )

        def forward(self, sketch, image):
            x = _sk_torch.cat([sketch, image], dim=1)
            return self.model(x)


    def train_sketch_model(dataset_dir, epochs=200, batch_size=8, lr=2e-4, out_path="sketch_generator.pt",
                            resume_from=None):
        """เทรน Generator+Discriminator ด้วยชุดภาพของคุณเอง — รันบนเครื่องที่มี GPU
        ผ่าน: python App123.py --train-sketch --dataset ./dataset --epochs 200

        resume_from: [UPGRADE] path ไฟล์ weight (.pt) ของ Generator เดิม ถ้าใส่มาจะโหลด
        มาเป็นจุดเริ่มต้นแล้วเทรนต่อ (fine-tune) แทนที่จะเริ่มจากน้ำหนักสุ่มใหม่ — ใช้โดย
        pipeline self-learn ที่ [6q0c] เพื่อให้เทรนต่อยอดจากรอบก่อนหน้าได้เรื่อยๆ ไม่ต้อง
        เริ่มนับหนึ่งใหม่ทุกครั้งที่มีข้อมูลเพิ่ม

        คำเตือนคุณภาพ: ถ้ามีภาพตัวอย่างน้อย (หลักสิบ-ร้อยคู่) ผลลัพธ์จะยังเบลอ/ไม่
        คมชัดเท่าโมเดลเชิงพาณิชย์ที่เทรนจากภาพนับล้าน — โมเดลนี้เหมาะเป็นจุดเริ่มต้น
        เรียนรู้หลักการมากกว่าใช้งานจริงระดับโปรทันที"""
        device = "cuda" if _sk_torch.cuda.is_available() else "cpu"
        if device == "cpu":
            print("⚠️  ไม่พบ GPU — จะเทรนบน CPU ซึ่งช้ามาก แนะนำให้หาเครื่องที่มี GPU ก่อน")

        ds = SketchDataset(dataset_dir)
        if len(ds) == 0:
            raise RuntimeError(f"ไม่พบข้อมูลใน {dataset_dir} — เตรียมโฟลเดอร์ sketches/ กับ targets/ ก่อน")
        print(f"พบข้อมูลทั้งหมด {len(ds)} คู่ภาพ")
        loader = _SkDataLoader(ds, batch_size=batch_size, shuffle=True)

        gen = Generator().to(device)
        disc = Discriminator().to(device)

        if resume_from and os.path.isfile(resume_from):
            try:
                gen.load_state_dict(_sk_torch.load(resume_from, map_location=device))
                print(f"↪️  โหลดน้ำหนักเดิมจาก {resume_from} มาเป็นจุดเริ่มต้น (fine-tune ต่อ ไม่เริ่มจากศูนย์)")
            except Exception as e:
                print(f"⚠️  โหลด resume_from={resume_from} ไม่สำเร็จ ({e}) — เริ่มเทรนจากน้ำหนักสุ่มใหม่แทน")

        opt_g = _sk_torch.optim.Adam(gen.parameters(), lr=lr, betas=(0.5, 0.999))
        opt_d = _sk_torch.optim.Adam(disc.parameters(), lr=lr, betas=(0.5, 0.999))
        bce = _sk_nn.BCEWithLogitsLoss()
        l1 = _sk_nn.L1Loss()
        L1_WEIGHT = 100  # ให้ภาพที่วาดออกมาใกล้เคียงภาพเป้าหมายจริง ไม่ใช่แค่ดูสมจริงเฉยๆ

        for epoch in range(1, epochs + 1):
            for sketches, targets in loader:
                sketches, targets = sketches.to(device), targets.to(device)

                fake = gen(sketches)
                pred_real = disc(sketches, targets)
                pred_fake = disc(sketches, fake.detach())
                loss_d = 0.5 * (bce(pred_real, _sk_torch.ones_like(pred_real)) +
                                bce(pred_fake, _sk_torch.zeros_like(pred_fake)))
                opt_d.zero_grad(); loss_d.backward(); opt_d.step()

                pred_fake_for_g = disc(sketches, fake)
                loss_g_adv = bce(pred_fake_for_g, _sk_torch.ones_like(pred_fake_for_g))
                loss_g_l1 = l1(fake, targets) * L1_WEIGHT
                loss_g = loss_g_adv + loss_g_l1
                opt_g.zero_grad(); loss_g.backward(); opt_g.step()

            if epoch % 10 == 0 or epoch == 1:
                print(f"epoch {epoch}/{epochs} — loss_g: {loss_g.item():.3f}  loss_d: {loss_d.item():.3f}")

        _sk_torch.save(gen.state_dict(), out_path)
        print(f"✅ เทรนเสร็จ บันทึกโมเดลไว้ที่ {out_path}")
        print(f"   เอา path นี้ไปตั้งเป็น env var AI_DRAW_MODEL_PATH ก่อนรันเว็บรอบถัดไป")


