def _hf_text_to_image(prompt: str):
    """text-to-image ธรรมดาผ่าน HF Inference API (คนละ endpoint กับ _hf_anime_colorize ที่เป็น
    image-to-image/ControlNet) — คืน (bytes, error) เหมือนแพทเทิร์นเดิมของกลุ่ม ai_draw"""
    if not HF_API_TOKEN:
        return None, "ไม่ได้ตั้ง HF_API_TOKEN"
    try:
        url = f"https://api-inference.huggingface.co/models/{HF_BLUEPRINT_MODEL_ID}"
        headers = {"Authorization": f"Bearer {HF_API_TOKEN}"}
        resp = requests.post(url, headers=headers, json={"inputs": prompt}, timeout=HF_API_TIMEOUT_SEC)
        if resp.status_code == 503:
            try:
                wait_s = resp.json().get("estimated_time", 20)
            except Exception:
                wait_s = 20
            return None, f"โมเดลกำลังโหลดอยู่บนเซิร์ฟเวอร์ HF (cold start) ลองใหม่อีกครั้งใน ~{int(wait_s)} วิ"
        if resp.status_code != 200:
            return None, f"HF API ตอบกลับ status {resp.status_code}: {resp.text[:200]}"
        content_type = resp.headers.get("content-type", "")
        if "image" not in content_type:
            return None, f"HF API ไม่ได้ส่งรูปกลับมา (content-type={content_type}): {resp.text[:200]}"
        return resp.content, None
    except requests.exceptions.Timeout:
        return None, f"เรียก HF API หมดเวลา (>{HF_API_TIMEOUT_SEC}s)"
    except Exception as e:
        return None, f"เรียก HF API ไม่สำเร็จ: {e}"


def _hf_blueprint_from_sketch(sketch_bytes: bytes):
    """เหมือน _hf_anime_colorize เป๊ะ แต่ใช้ prompt แนวบลูปรินต์-โฮโลแกรมแทนแนวอนิเมะ —
    เผื่อผู้เล่นเลือกวาดสเก็ตช์คร่าวๆ ของตึก/ผังแมพเองแทนการพิมพ์บรรยาย"""
    if not HF_API_TOKEN:
        return None, "ไม่ได้ตั้ง HF_API_TOKEN"
    try:
        url = f"https://api-inference.huggingface.co/models/{HF_BLUEPRINT_SKETCH_MODEL_ID}"
        headers = {"Authorization": f"Bearer {HF_API_TOKEN}", "Content-Type": "application/octet-stream"}
        resp = requests.post(url, headers=headers, params={"prompt": HF_BLUEPRINT_STYLE_PROMPT},
                             data=sketch_bytes, timeout=HF_API_TIMEOUT_SEC)
        if resp.status_code == 503:
            try:
                wait_s = resp.json().get("estimated_time", 20)
            except Exception:
                wait_s = 20
            return None, f"โมเดลกำลังโหลดอยู่บนเซิร์ฟเวอร์ HF (cold start) ลองใหม่อีกครั้งใน ~{int(wait_s)} วิ"
        if resp.status_code != 200:
            return None, f"HF API ตอบกลับ status {resp.status_code}: {resp.text[:200]}"
        content_type = resp.headers.get("content-type", "")
        if "image" not in content_type:
            return None, f"HF API ไม่ได้ส่งรูปกลับมา (content-type={content_type}): {resp.text[:200]}"
        return resp.content, None
    except requests.exceptions.Timeout:
        return None, f"เรียก HF API หมดเวลา (>{HF_API_TIMEOUT_SEC}s)"
    except Exception as e:
        return None, f"เรียก HF API ไม่สำเร็จ: {e}"


def _hf_image_caption(image_bytes: bytes):
    """image captioning ผ่าน HF Inference API — ส่งภาพดิบเป็น bytes ตรงๆ (แพทเทิร์นเดียวกับ
    image classification ของ HF) คืน (caption_str, error)"""
    if not HF_API_TOKEN:
        return None, "ไม่ได้ตั้ง HF_API_TOKEN"
    try:
        url = f"https://api-inference.huggingface.co/models/{HF_CAPTION_MODEL_ID}"
        headers = {"Authorization": f"Bearer {HF_API_TOKEN}", "Content-Type": "application/octet-stream"}
        resp = requests.post(url, headers=headers, data=image_bytes, timeout=HF_API_TIMEOUT_SEC)
        if resp.status_code == 503:
            try:
                wait_s = resp.json().get("estimated_time", 20)
            except Exception:
                wait_s = 20
            return None, f"โมเดลกำลังโหลดอยู่บนเซิร์ฟเวอร์ HF (cold start) ลองใหม่อีกครั้งใน ~{int(wait_s)} วิ"
        if resp.status_code != 200:
            return None, f"HF API ตอบกลับ status {resp.status_code}: {resp.text[:200]}"
        data = resp.json()
        caption = data[0].get("generated_text", "") if isinstance(data, list) and data else ""
        if not caption:
            return None, f"HF API ไม่ได้ส่งคำบรรยายภาพกลับมา: {resp.text[:200]}"
        return caption, None
    except requests.exceptions.Timeout:
        return None, f"เรียก HF API หมดเวลา (>{HF_API_TIMEOUT_SEC}s)"
    except Exception as e:
        return None, f"เรียก HF API ไม่สำเร็จ: {e}"


def _hf_image_vqa(image_bytes: bytes, question: str):
    """visual question answering ผ่าน HF Inference API — ต้องส่งเป็น JSON {inputs:{image,question}}
    (คนละรูปแบบ payload กับ captioning/ControlNet ด้านบน เพราะเป็นคนละ task ของ HF) คืน (answer_str, error)"""
    if not HF_API_TOKEN:
        return None, "ไม่ได้ตั้ง HF_API_TOKEN"
    try:
        url = f"https://api-inference.huggingface.co/models/{HF_VQA_MODEL_ID}"
        headers = {"Authorization": f"Bearer {HF_API_TOKEN}", "Content-Type": "application/json"}
        img_b64 = base64.b64encode(image_bytes).decode("ascii")
        resp = requests.post(url, headers=headers,
                             json={"inputs": {"image": img_b64, "question": question}},
                             timeout=HF_API_TIMEOUT_SEC)
        if resp.status_code == 503:
            try:
                wait_s = resp.json().get("estimated_time", 20)
            except Exception:
                wait_s = 20
            return None, f"โมเดลกำลังโหลดอยู่บนเซิร์ฟเวอร์ HF (cold start) ลองใหม่อีกครั้งใน ~{int(wait_s)} วิ"
        if resp.status_code != 200:
            return None, f"HF API ตอบกลับ status {resp.status_code}: {resp.text[:200]}"
        data = resp.json()
        answer = data[0].get("answer", "") if isinstance(data, list) and data else ""
        if not answer:
            return None, f"HF API ไม่ได้ส่งคำตอบกลับมา: {resp.text[:200]}"
        return answer, None
    except requests.exceptions.Timeout:
        return None, f"เรียก HF API หมดเวลา (>{HF_API_TIMEOUT_SEC}s)"
    except Exception as e:
        return None, f"เรียก HF API ไม่สำเร็จ: {e}"
