    out_dir = "uploaded_ai_draw"
    os.makedirs(out_dir, exist_ok=True)
    out_name = f"{design_id}_blueprint.png"
    with open(os.path.join(out_dir, out_name), "wb") as fp:
        fp.write(out_bytes)
    MAP_DESIGNS[design_id]["result_file"] = out_name
    MAP_DESIGNS[design_id]["status"] = "done"
    return jsonify({"st": "ok", "design_id": design_id, "design": MAP_DESIGNS[design_id]})


