# ------------------------------------------------------------------
# [UPGRADE] Auto image-to-structure heuristic converter — ตามที่ขอ:
# "ถ้าให้ต้องการให้มันเป็นแบบว่าเอาไปแปลงเป็นโครงสร้างตึกเราต้องเพิ่มอะไรเพิ่มเติมไหม"
# วิเคราะห์ภาพบลูปรินต์ที่สร้างเสร็จแล้วด้วย cv2 (ไม่เรียก AI เพิ่ม ไม่มีค่าใช้จ่าย/เวลารอเพิ่ม)
# เพื่อประมาณ "ขนาดโครงสร้าง (w,h)" และ "ความซับซ้อน (จำนวนชั้น/ห้องโดยประมาณ)" จากรูปทรง/
# สัดส่วนภาพเอง แทนที่ผู้เล่นต้องเดาตัวเลข w,h เองทุกครั้งตอนปักเป็นไซต์ก่อสร้างจริง — ค่าที่ได้
# เป็นแค่ "ค่าเริ่มต้นที่สมเหตุสมผลกว่าเดิม" ไม่ใช่การวิเคราะห์สถาปัตยกรรมที่แม่นยำจริง (ปรับเองได้เสมอ)
# ------------------------------------------------------------------
def image_to_structure_heuristic(image_path):
    """วิเคราะห์ภาพบลูปรินต์/สเก็ตช์ด้วย cv2 ล้วนๆ (ไม่ใช้ AI เพิ่ม) เพื่อประมาณค่าเริ่มต้นของ
    โครงสร้าง — คืน dict {suggested_w, suggested_h, estimated_floors, estimated_rooms,
    structure_type, confidence, note}"""
    import cv2
    import numpy as np

    img = cv2.imread(image_path)
    if img is None:
        raise RuntimeError(f"อ่านไฟล์ภาพไม่ได้: {image_path}")
    h_px, w_px = img.shape[:2]

    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    edges = cv2.Canny(gray, 50, 150)
    edges = cv2.dilate(edges, np.ones((3, 3), np.uint8), iterations=1)

    contours, _ = cv2.findContours(edges, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    if not contours:
        return {
            "suggested_w": 4.0, "suggested_h": 4.0, "estimated_floors": 1, "estimated_rooms": 1,
            "structure_type": "simple", "confidence": "low",
            "note": "หาโครงร่างในภาพไม่เจอ (ภาพอาจเรียบ/คอนทราสต์ต่ำ) ใช้ค่าเริ่มต้นทั่วไปแทน",
        }

    # กรอบที่ครอบทุก contour รวมกัน = ขอบเขตโครงสร้างหลักในภาพ
    all_pts = np.vstack([c.reshape(-1, 2) for c in contours])
    _, _, bw, bh = cv2.boundingRect(all_pts)
    aspect = bh / max(bw, 1)

    # แปลงสัดส่วนภาพ -> ขนาดโครงสร้างในหน่วยแมพ (ฐาน 4x4 หน่วย ปรับตามสัดส่วนจริงของภาพ)
    BASE_UNIT = 4.0
    if aspect >= 1.3:
        suggested_w, suggested_h, structure_type = round(BASE_UNIT / aspect, 2), BASE_UNIT, "tower"          # สูงกว่ากว้าง
    elif aspect <= 0.75:
        suggested_w, suggested_h, structure_type = BASE_UNIT, round(BASE_UNIT * aspect, 2), "wide_complex"   # กว้างกว่าสูง
    else:
        suggested_w, suggested_h, structure_type = BASE_UNIT, BASE_UNIT, "block"                              # ใกล้เคียงสี่เหลี่ยมจัตุรัส
    suggested_w, suggested_h = max(suggested_w, 1.5), max(suggested_h, 1.5)  # กันขนาดเล็กเกินจริง

    # นับ region ปิดภายในโครงร่าง (ใช้แทน "จำนวนห้อง" คร่าวๆ) — วิธีเดียวกับ auto_colorize_image ที่ [6q1]
    fillable = cv2.bitwise_not(edges)
    num_labels, labels, stats, _ = cv2.connectedComponentsWithStats(fillable, connectivity=4)
    min_region_px = max(20, (h_px * w_px) // 3000)
    room_like_regions = sum(1 for i in range(1, num_labels) if stats[i, cv2.CC_STAT_AREA] >= min_region_px)
    room_like_regions = max(1, room_like_regions - 1)  # หัก region พื้นหลังใหญ่สุดออก 1 อัน

    estimated_floors = max(1, min(20, round(aspect * 2)))  # ทรงยิ่งสูง ยิ่งสมมติว่าหลายชั้นขึ้น (คร่าวๆ)
    estimated_rooms = max(1, min(50, room_like_regions))

    return {
        "suggested_w": suggested_w, "suggested_h": suggested_h,
        "estimated_floors": estimated_floors, "estimated_rooms": estimated_rooms,
        "structure_type": structure_type, "confidence": "heuristic",
        "note": "ประมาณจากสัดส่วน/จำนวน region ปิดในภาพเท่านั้น ไม่ใช่การวิเคราะห์สถาปัตยกรรมจริง "
                "— ปรับตัวเลขเองได้เสมอตอนเรียก place_as_construction",
    }


@app.route('/api/mapdesign/<design_id>/analyze_structure', methods=['POST'])
@require_auth_toggleable
def api_mapdesign_analyze_structure(design_id):
    """วิเคราะห์ภาพบลูปรินต์ที่สร้างเสร็จแล้ว (โหมดไหนก็ได้) ด้วย heuristic ด้านบน แล้วเก็บผลไว้ใน
    design — place_as_construction ด้านล่างจะดึงค่านี้ไปใช้เป็น w,h เริ่มต้นอัตโนมัติถ้าไม่ได้ระบุมาเอง"""
    d = MAP_DESIGNS.get(design_id)
    if not d or d["status"] != "done" or not d.get("result_file"):
        return jsonify({"st": "error", "msg": "ดีไซน์นี้ยังไม่เสร็จหรือไม่พบ"}), 400
    img_path = os.path.join("uploaded_ai_draw", d["result_file"])
    try:
        analysis = image_to_structure_heuristic(img_path)
    except Exception as e:
        return jsonify({"st": "error", "msg": f"วิเคราะห์โครงสร้างไม่สำเร็จ: {e}"}), 500
    d["structure_analysis"] = analysis
    return jsonify({"st": "ok", "design_id": design_id, "structure_analysis": analysis})


@app.route('/api/mapdesign/<design_id>/analyze_structure_ai', methods=['POST'])
@require_auth_toggleable
def api_mapdesign_analyze_structure_ai(design_id):
    """[UPGRADE] ระดับ 'สถาปัตยกรรมจริงๆ' ที่ถามมา — ต่างจาก analyze_structure ด้านบน (heuristic
    ดูแค่รูปทรง/สัดส่วนภาพด้วย cv2) ตัวนี้ให้โมเดล vision-language จริงๆ 'มอง' ภาพแล้วอธิบายเป็น
    ภาษาคน ผ่าน HF Inference API (ต้องตั้ง HF_API_TOKEN + มีอินเทอร์เน็ต เหมือนกลุ่ม ai_draw ทุกครั้ง)
    — ได้คำบรรยายภาพ + ตอบคำถามเฉพาะทาง (จำนวนชั้น/ประเภทอาคาร/จำนวนห้อง) แล้วรวมกับผลจาก
    analyze_structure (cv2 heuristic) เป็นรายงานเดียว — ยิ่งครบยิ่งดี แต่ไม่การันตีความแม่นยำ
    (ดูคำเตือนเรื่องขอบเขตที่ [ 6q1b upgrade ] ด้านบน: โมเดล general-purpose ไม่ได้เทรนเฉพาะทาง
    ด้านแปลนอาคาร มีโอกาส hallucinate ได้เหมือน AI ทั่วไป)"""
    d = MAP_DESIGNS.get(design_id)
    if not d or d["status"] != "done" or not d.get("result_file"):
        return jsonify({"st": "error", "msg": "ดีไซน์นี้ยังไม่เสร็จหรือไม่พบ"}), 400
    if not HF_API_TOKEN:
        return jsonify({"st": "error",
                        "msg": "ฟีเจอร์นี้ต้องตั้ง HF_API_TOKEN ก่อน (สมัครฟรีที่ huggingface.co -> "
                                "Settings -> Access Tokens) แล้วตั้ง env var HF_API_TOKEN ก่อนรันเว็บ"}), 503

    img_path = os.path.join("uploaded_ai_draw", d["result_file"])
    try:
        with open(img_path, "rb") as fp:
            img_bytes = fp.read()
    except OSError as e:
        return jsonify({"st": "error", "msg": f"อ่านไฟล์ภาพไม่ได้: {e}"}), 500

    caption, cap_err = _hf_image_caption(img_bytes)
    vqa_answers, vqa_errors = {}, {}
    for key, question in STRUCTURE_VQA_QUESTIONS.items():
        answer, err = _hf_image_vqa(img_bytes, question)
        if answer:
            vqa_answers[key] = answer
        else:
            vqa_errors[key] = err

    if caption is None and not vqa_answers:
        return jsonify({"st": "error",
                        "msg": f"เรียกโมเดล vision-language ไม่สำเร็จเลยสักตัว — caption: {cap_err}; "
                                f"vqa: {vqa_errors}"}), 502

    # ลองดึงตัวเลขจำนวนชั้นจากคำตอบ VQA มาเสริม (ถ้าตีความได้) — ไม่มีก็ปล่อยว่าง ไม่เดาสุ่ม
    ai_floors_guess = None
    if vqa_answers.get("floors"):
        _m = re.search(r"\d+", vqa_answers["floors"])
        if _m:
            ai_floors_guess = int(_m.group())

    result = {
        "caption": caption, "caption_error": cap_err,
        "vqa_answers": vqa_answers, "vqa_errors": vqa_errors,
        "ai_floors_guess": ai_floors_guess,
        "geometry_heuristic": d.get("structure_analysis"),  # แนบผลจาก analyze_structure เดิมมาด้วยถ้ามี
        "warning": "ผลลัพธ์จากโมเดล vision-language ทั่วไป ไม่ได้เทรนเฉพาะทางด้านสถาปัตยกรรม/แปลนอาคาร "
                   "— ใช้เป็นข้อมูลเสริมประกอบการตัดสินใจ ไม่ใช่แหล่งความจริงเดียวหรือการวิเคราะห์เชิงวิศวกรรม",
    }
    d["structure_analysis_ai"] = result
    return jsonify({"st": "ok", "design_id": design_id, "structure_analysis_ai": result})


@app.route('/api/mapdesign/<design_id>/place_as_construction', methods=['POST'])
@require_auth_toggleable
def api_mapdesign_place_as_construction(design_id):
    """body: {x,y,w?,h?,duration,material?} -> เอาดีไซน์ที่สร้างเสร็จแล้วไป 'ปัก' เป็นไซต์ก่อสร้างจริง
    ในแมพ (ผ่าน start_construction() เดิมที่ [2b9b2]) พิกัด x,y ต้องให้ผู้เล่น/แอดมินกำหนดเอง (AI ไม่รู้
    ตำแหน่งจริงในแมพ) — ส่วน w,h ถ้าไม่ระบุมา จะใช้ค่าที่ได้จาก analyze_structure ด้านบน (ถ้าเคย
    เรียกไว้ก่อน) เป็นค่าเริ่มต้นแทนค่า 4.0/4.0 ตายตัวแบบเดิม — ถ้าเคยเรียก analyze_structure_ai
    ไว้ด้วยและตีความจำนวนชั้นจากคำตอบ AI ได้ (ai_floors_guess) จะแนบมาบอกใน response เผื่ออยาก
    เอาไปคูณความสูงเอง (ไม่ได้เอาไปคูณอัตโนมัติ เพราะเป็นแค่การเดาจาก VQA ไม่ใช่ค่าที่มั่นใจได้)
    [UPGRADE] material: เลือกวัสดุจาก MATERIAL_CATALOG ด้านล่าง (ไม่ระบุ = concrete) — ใช้คำนวณ
    'ค่ารับน้ำหนักโดยประมาณ (ค่าเกม)' เก็บไว้ใน STRUCTURE_HOLOGRAM_DATA ให้ /hologram/<cid> เอาไปโชว์"""
    d = MAP_DESIGNS.get(design_id)
    if not d or d["status"] != "done":
        return jsonify({"st": "error", "msg": "ดีไซน์นี้ยังไม่เสร็จหรือไม่พบ"}), 400
    body = request.json or {}
    analysis = d.get("structure_analysis") or {}
    default_w = analysis.get("suggested_w", 4.0)
    default_h = analysis.get("suggested_h", 4.0)
    used_w = float(body.get("w", default_w))
    used_h = float(body.get("h", default_h))
    cid = start_construction(
        x=float(body.get("x", 0)), y=float(body.get("y", 0)),
        w=used_w, h=used_h,
        label=f"{d['name']} (ออกแบบโดยผู้เล่น)",
        duration=float(body.get("duration", 10.0)),
    )
    ai_analysis = d.get("structure_analysis_ai") or {}

    # [UPGRADE] บันทึกข้อมูลโฮโลแกรม (วัสดุ + ค่ารับน้ำหนักเกม + ขนาด/ชั้น) ผูกกับ cid นี้ไว้เลย
    material_id = body.get("material", DEFAULT_STRUCTURE_MATERIAL)
    mat = _material_info(material_id)
    area_sqm = round(used_w * used_h, 2)
    STRUCTURE_HOLOGRAM_DATA[cid] = {
        "design_id": design_id, "material_id": material_id, "material_name": mat["name"],
        "floors": analysis.get("estimated_floors", 1), "width_units": used_w, "height_units": used_h,
        "area_sqm": area_sqm, "load_capacity_total_kg": round(mat["load_capacity_kg_per_sqm"] * area_sqm),
    }
    return jsonify({"st": "ok", "cid": cid, "site": CONSTRUCTION_SITES[cid],
                    "used_structure_analysis": bool(analysis),
                    "ai_floors_guess": ai_analysis.get("ai_floors_guess"),
                    "hologram_url": f"/hologram/{cid}"})


# ------------------------------------------------------------------
# [UPGRADE] Structure Hologram Scanner — ตามที่ขอ: "ขึ้นเป็นโฮโลแกรม บอกวัสดุ/รับน้ำหนักได้เท่าไหร่
# สแกนด้านในว่ามีคนอยู่/เคลื่อนไหวไหม สแกนห้องเป็นสีเขียวๆ ความสูงกี่ชั้น กว้างเท่าไหร่ พื้นที่ตารางเมตร"
#
# พูดตรงๆ ก่อน 2 เรื่อง:
#   1) "วัสดุ/รับน้ำหนักได้เท่าไหร่" — ไม่มีทางที่ AI จะดูภาพแล้วบอกวัสดุจริง/ค่าน้ำหนักรับจริงทาง
#      วิศวกรรมได้แม่นยำ (เป็นไปไม่ได้ทั้งทางเทคนิคและอันตรายถ้าเอาไปอ้างอิงงานจริง) ระบบนี้เลยทำเป็น
#      "ค่าเกม" ล้วนๆ — ผู้เล่น/แอดมิน "เลือก" วัสดุเองตอน place_as_construction (พารามิเตอร์ material)
#      จากแคตตาล็อก MATERIAL_CATALOG ด้านล่าง แล้วระบบคูณค่าเกมให้ ไม่ใช่การวิเคราะห์จากภาพจริง —
#      ห้ามเอาไปอ้างอิงงานก่อสร้าง/วิศวกรรมจริงเด็ดขาด
#   2) "สแกนหาคน/ความเคลื่อนไหว" — อันนี้ทำได้จริงและมีความหมายจริง เพราะดึงจากตำแหน่งผู้เล่นจริง
#      ในเกม (PLAYERS ที่ระบบ multiplayer sync ด้านบนเก็บไว้อยู่แล้ว) ไม่ใช่เซนเซอร์จริง — เช็คว่าใคร
#      อยู่ในกรอบพิกัดของตึกหลังนี้ แล้วเทียบตำแหน่งกับครั้งก่อนหน้าเพื่อบอกว่าเคลื่อนไหวหรือนิ่ง
# ------------------------------------------------------------------
MATERIAL_CATALOG = {  # ค่าเกมเพื่อความสมดุลเท่านั้น ไม่ใช่ค่าจริงทางวิศวกรรม
    "wood":                {"name": "ไม้",              "load_capacity_kg_per_sqm": 150},
    "brick":               {"name": "อิฐ/ปูนก่อ",        "load_capacity_kg_per_sqm": 400},
    "concrete":            {"name": "คอนกรีต",           "load_capacity_kg_per_sqm": 800},
    "reinforced_concrete": {"name": "คอนกรีตเสริมเหล็ก",  "load_capacity_kg_per_sqm": 1500},
    "steel":               {"name": "โครงเหล็ก",         "load_capacity_kg_per_sqm": 2000},
}
DEFAULT_STRUCTURE_MATERIAL = "concrete"

STRUCTURE_HOLOGRAM_DATA = {}  # cid -> {design_id, material_id, material_name, floors, width_units, height_units, area_sqm, load_capacity_total_kg}
_LIFESCAN_LAST_POS = {}       # cid -> {sid: (x, y, ts)} — เก็บตำแหน่งรอบสแกนก่อนหน้าไว้เทียบว่าใครเคลื่อนไหว


def _material_info(material_id):
    return MATERIAL_CATALOG.get(material_id, MATERIAL_CATALOG[DEFAULT_STRUCTURE_MATERIAL])


def structure_lifescan(cid):
    """เช็คว่าใครอยู่ในกรอบพิกัดของตึกนี้บ้าง (จากตำแหน่งผู้เล่นจริงใน PLAYERS) แล้วบอกว่านิ่งหรือ
    เคลื่อนไหว (เทียบกับตำแหน่งครั้งก่อนหน้าที่เคยสแกนตึกหลังนี้) — ต้องเรียกอย่างน้อย 2 ครั้งขึ้นไป
    ถึงจะบอกสถานะเคลื่อนไหวได้ ครั้งแรกจะได้แค่ moving=None (แปลว่า 'ตรวจพบ' ยังไม่รู้ว่าเคลื่อนไหวไหม)"""
    site = CONSTRUCTION_SITES.get(cid)
    if not site:
        return None
    x0, y0, w, h = site["x"], site["y"], site["w"], site["h"]
    now = time.time()
    prev = _LIFESCAN_LAST_POS.get(cid, {})
    curr, detected = {}, []
    for sid, pdata in list(PLAYERS.items()):
        px, py = pdata["x"], pdata["y"]
        if x0 <= px <= x0 + w and y0 <= py <= y0 + h:
            curr[sid] = (px, py, now)
            moving = None
            if sid in prev:
                pxp, pyp, _tsp = prev[sid]
                moving = _dist(px, py, pxp, pyp) > 0.15  # เกิน 15 ซม.ระหว่างรอบสแกน = นับว่าเคลื่อนไหว
            detected.append({"sid": sid, "x": round(px, 2), "y": round(py, 2), "moving": moving})
    _LIFESCAN_LAST_POS[cid] = curr
    return detected


@app.route('/api/mapdesign/structure/<cid>/hologram', methods=['GET'])
def api_mapdesign_structure_hologram(cid):
    """ข้อมูลโฮโลแกรมของตึกที่ปักไว้แล้ว: วัสดุ+ค่ารับน้ำหนัก(ค่าเกม), ขนาด/จำนวนชั้น, และผลสแกน
    หาสิ่งมีชีวิตในตึก ณ ขณะนี้ (จากตำแหน่งผู้เล่นจริงในเกม) — ให้ /hologram/<cid> ดึงไปแสดงผล"""
    site = CONSTRUCTION_SITES.get(cid)
    if not site:
        return jsonify({"st": "error", "msg": "ไม่พบไซต์นี้"}), 404
    return jsonify({
        "st": "ok", "cid": cid, "site": site,
        "hologram": STRUCTURE_HOLOGRAM_DATA.get(cid, {}),
        "life_scan": structure_lifescan(cid),
        "life_scan_note": "ดึงจากตำแหน่งผู้เล่นจริงในเกม ไม่ใช่เซนเซอร์จริง — 'moving' เป็น null ถ้า "
                          "เป็นการสแกนครั้งแรกของตึกนี้ (ยังไม่มีตำแหน่งก่อนหน้าให้เทียบ)",
        "material_warning": "ค่ารับน้ำหนักเป็น 'ค่าเกมเพื่อความสมดุล' ตามวัสดุที่เลือกไว้ตอนปักตึก "
                            "ไม่ใช่การวิเคราะห์จากภาพหรือค่าจริงทางวิศวกรรม ห้ามใช้อ้างอิงงานก่อสร้างจริง",
    })


HOLOGRAM_PAGE_HTML = """
<!DOCTYPE html><html lang="th"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Structure Hologram Scan</title>
<style>
  body{margin:0;background:#000;color:#7CFC00;font-family:monospace;padding:16px}
  h1{color:#00e5ff;font-size:15px;text-shadow:0 0 8px #00e5ff;margin:14px 0 6px}
  .frame{border:1px solid #00e5ff;box-shadow:0 0 12px #00e5ff inset;border-radius:8px;padding:12px}
  .stat{display:flex;justify-content:space-between;padding:4px 0;border-bottom:1px dashed #113;font-size:13px}
  .warn{color:#ffcc00;font-size:11px;margin-top:8px;line-height:1.5}
  .radar{position:relative;background:#001;border:1px solid #0f0;height:220px;border-radius:6px;overflow:hidden;margin-top:6px}
  .dot{position:absolute;width:10px;height:10px;border-radius:50%;background:#39ff14;box-shadow:0 0 8px #39ff14;
       transform:translate(-50%,-50%)}
  .dot.moving{background:#ffff33;box-shadow:0 0 10px #ffff33;animation:pulse 1s infinite}
  @keyframes pulse{0%{transform:translate(-50%,-50%) scale(1)}50%{transform:translate(-50%,-50%) scale(1.6)}100%{transform:translate(-50%,-50%) scale(1)}}
</style></head><body>
<h1>🔷 STRUCTURE HOLOGRAM SCAN — <span id="cid"></span></h1>
<div id="app">กำลังสแกน...</div>
<script>
const CID = location.pathname.split('/').pop();
document.getElementById('cid').innerText = CID;
async function jf(url){ const r = await fetch(url); return r.json(); }
async function render(){
  const d = await jf(`/api/mapdesign/structure/${CID}/hologram`);
  const app = document.getElementById('app');
  if (d.st !== 'ok'){ app.innerHTML = `<p>${d.msg}</p>`; return; }
  const h = d.hologram || {}, s = d.site || {};
  app.innerHTML = `
    <div class="frame">
      <div class="stat"><span>วัสดุ</span><span>${h.material_name || '-'}</span></div>
      <div class="stat"><span>รับน้ำหนักโดยประมาณ (ค่าเกม)</span><span>${h.load_capacity_total_kg ?? '-'} kg</span></div>
      <div class="stat"><span>จำนวนชั้น (ประมาณ)</span><span>${h.floors ?? '-'}</span></div>
      <div class="stat"><span>ขนาด (กว้าง×สูง)</span><span>${h.width_units ?? '-'} × ${h.height_units ?? '-'} หน่วย</span></div>
      <div class="stat"><span>พื้นที่</span><span>${h.area_sqm ?? '-'} ตร.ม.</span></div>
      <div class="warn">⚠️ ${d.material_warning}</div>
    </div>
    <h1>🟢 LIFE SCAN</h1>
    <div class="radar" id="radar"></div>
    <div class="warn">${d.life_scan_note}</div>
  `;
  const radar = document.getElementById('radar');
  (d.life_scan || []).forEach(p => {
    const dot = document.createElement('div');
    dot.className = 'dot' + (p.moving === true ? ' moving' : '');
    const pctX = s.w ? ((p.x - s.x) / s.w) * 100 : 50;
    const pctY = s.h ? ((p.y - s.y) / s.h) * 100 : 50;
    dot.style.left = Math.max(2, Math.min(98, pctX)) + '%';
    dot.style.top = Math.max(2, Math.min(98, pctY)) + '%';
    dot.title = `${p.sid} — ${p.moving === true ? 'เคลื่อนไหว' : p.moving === false ? 'นิ่ง' : 'ตรวจพบ'}`;
    radar.appendChild(dot);
  });
  if (!(d.life_scan || []).length) radar.innerHTML = '<div style="padding:10px;color:#555">ไม่พบสิ่งมีชีวิตในตึกขณะนี้</div>';
}
render(); setInterval(render, 2000);
</script>
</body></html>
"""


