# ==========================================
# [ 6r. AI Chat sub-menu (คุยกับ AI — แยกจาก game logic) ]
# ใช้ local AI ตัวเดียวกับที่ generate_feature_code() เรียกอยู่แล้ว (Ollama /
# OpenAI-compatible ผ่าน LOCAL_AI_URL / LOCAL_AI_MODEL) ไม่ยิงไปหา Anthropic
# API หรือ AI ภายนอกใดๆ ประวัติแชทเก็บลง sqlite3 คนละไฟล์กับ DB เกม แยก
# session ด้วย session_id ที่ฝั่ง client ส่งมา
# ==========================================

AI_CHAT_DB_PATH = os.environ.get("AI_CHAT_DB_PATH", "ai_chat.db")


def _ai_chat_db():
    conn = sqlite3.connect(AI_CHAT_DB_PATH)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS ai_chat_messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            session_id TEXT NOT NULL,
            role TEXT NOT NULL,
            content TEXT NOT NULL,
            created_at TEXT NOT NULL
        )
    """)
    return conn


def _ai_chat_history(session_id, limit=20):
    conn = _ai_chat_db()
    try:
        rows = conn.execute(
            "SELECT role, content, created_at FROM ai_chat_messages "
            "WHERE session_id = ? ORDER BY id DESC LIMIT ?",
            (session_id, limit),
        ).fetchall()
    finally:
        conn.close()
    rows.reverse()
    return [{"role": r[0], "content": r[1], "created_at": r[2]} for r in rows]


def _ai_chat_save(session_id, role, content):
    conn = _ai_chat_db()
    try:
        conn.execute(
            "INSERT INTO ai_chat_messages (session_id, role, content, created_at) VALUES (?, ?, ?, ?)",
            (session_id, role, content, datetime.utcnow().isoformat()),
        )
        conn.commit()
    finally:
        conn.close()


def _ai_chat_call_local_ai(session_id, user_message):
    """เรียก local AI ตัวเดียวกับ generate_feature_code() พร้อมแนบประวัติแชท
    ล่าสุดของ session นี้ไปด้วย เพื่อให้ AI จำบริบทการสนทนาได้"""
    local_url   = os.environ.get("LOCAL_AI_URL")
    local_model = os.environ.get("LOCAL_AI_MODEL", "llama3")

    if not local_url:
        return ("ยังไม่ได้ตั้งค่า AI ของตัวเอง — ต้องมีโมเดลรันอยู่ในเครื่อง (หรือ LAN) ก่อน "
                "แล้วตั้ง env var LOCAL_AI_URL (เช่น http://localhost:11434/api/chat สำหรับ Ollama, "
                "หรือ http://localhost:1234/v1/chat/completions สำหรับ LM Studio) และ LOCAL_AI_MODEL "
                "ก่อนใช้แชทนี้ ระบบนี้จะไม่ยิงไปหา Anthropic API หรือ AI ภายนอกใดๆ ทั้งสิ้น")

    history = _ai_chat_history(session_id, limit=20)
    messages = [{"role": "system",
                 "content": "คุณคือผู้ช่วย AI แชทของเกม VMAX พูดคุยเป็นกันเอง ตอบสั้นกระชับ"}]
    for h in history:
        messages.append({"role": h["role"], "content": h["content"]})
    messages.append({"role": "user", "content": user_message})

    try:
        if "11434" in local_url or "/api/chat" in local_url:
            resp = requests.post(local_url,
                                  json={"model": local_model, "stream": False,
                                        "options": {"num_ctx": _local_ai_num_ctx()},
                                        "messages": messages},
                                  timeout=120)
            return resp.json().get("message", {}).get("content", "(local AI ไม่ส่งผลลัพธ์กลับมา)")
        else:
            resp = requests.post(local_url,
                                  json={"model": local_model, "max_tokens": 500, "messages": messages},
                                  timeout=120)
            return resp.json()["choices"][0]["message"]["content"]
    except Exception as e:
        return f"(local AI error: {e})"


@app.route('/api/ai-chat/send', methods=['POST'])
@require_auth_toggleable
def api_ai_chat_send():
    """ส่งข้อความแชทไปหา local AI — ต้องมี session_id เพื่อแยกประวัติของแต่ละคน
    body: {session_id, message, uid?} -> {st, reply}
    AI ไม่ฟรี: หักเครดิต AI (หรือสิทธิ์จากแพ็กสมาชิก) ก่อนตอบ — ราคาลดได้ตามเทศกาล"""
    data = request.get_json(silent=True) or {}
    session_id = (data.get("session_id") or "").strip()
    user_message = (data.get("message") or "").strip()
    if not session_id:
        return jsonify({"st": "error", "msg": "ต้องระบุ session_id"}), 400
    if not user_message:
        return jsonify({"st": "error", "msg": "ต้องระบุ message"}), 400

    # --- AI paid gate (ไม่ฟรี) ---
    uid = data.get("uid") or getattr(request, "vmax_uid", None) or data.get("user_id") or "anon"
    try:
        if callable(globals().get("vmax_ai_usage_charge")):
            charged = vmax_ai_usage_charge(uid, units=1, feature="ai_chat")
            if not charged.get("ok"):
                return jsonify({
                    "st": "error",
                    "code": "ai_payment_required",
                    "msg": charged.get("msg") or "AI ไม่ฟรี — ต้องมีเครดิตหรือแพ็กสมาชิก",
                    "pricing": charged.get("pricing"),
                    "balance": charged.get("balance"),
                }), 402
    except NameError:
        pass
    except Exception as _ai_pay_exc:
        print("[AI PAID] charge error:", repr(_ai_pay_exc))

    _ai_chat_save(session_id, "user", user_message)
    reply = _ai_chat_call_local_ai(session_id, user_message)
    _ai_chat_save(session_id, "assistant", reply)

    out = {"st": "ok", "reply": reply}
    try:
        if "charged" in dir() and isinstance(charged, dict):
            out["ai_charge"] = {
                "spent": charged.get("spent"),
                "balance": charged.get("balance"),
                "festival_discount": charged.get("festival_discount"),
                "price_mult": charged.get("price_mult"),
            }
    except Exception:
        pass
    return jsonify(out)


@app.route('/api/ai-chat/history', methods=['GET'])
def api_ai_chat_history():
    """?session_id=...&limit=50 -> {st, messages:[{role, content, created_at}]}"""
    session_id = (request.args.get("session_id") or "").strip()
    if not session_id:
        return jsonify({"st": "error", "msg": "ต้องระบุ session_id"}), 400
    limit = request.args.get("limit", default=50, type=int)
    return jsonify({"st": "ok", "messages": _ai_chat_history(session_id, limit=limit)})


@app.route('/api/ai-chat/clear', methods=['POST'])
@require_auth_toggleable
def api_ai_chat_clear():
    """body: {session_id} -> ล้างประวัติแชทของ session นั้น"""
    data = request.get_json(silent=True) or {}
    session_id = (data.get("session_id") or "").strip()
    if not session_id:
        return jsonify({"st": "error", "msg": "ต้องระบุ session_id"}), 400
    conn = _ai_chat_db()
    try:
        conn.execute("DELETE FROM ai_chat_messages WHERE session_id = ?", (session_id,))
        conn.commit()
    finally:
        conn.close()
    return jsonify({"st": "ok"})


# ---- Hologram ตัวการ์ตูน AI Chat: อนิเมชัน + เสียงพากย์/ภาษา ----
# ต่อยอดจากงานที่ 1 (ANIMATION_PRESETS ที่ [ 2F. GLTF/FBX loader ] ใช้อยู่แล้ว) กับ
# งานที่ 2 (เลือก voice line ที่มีอยู่แล้วในเกม ไม่ใช่ TTS สังเคราะห์ใหม่) — ทั้งสอง
# งานนี้เป็นแค่ "ตัวปืน" คุมโฮโลแกรมของ AI chat widget เอง ไม่เกี่ยวกับ MODEL_REGISTRY
# ของโมเดล 3D จริงในเกม (แยกกันโดยตั้งใจ เผื่อทีมอยากผูกเข้าด้วยกันทีหลังค่อยทำ)

# voice line/ไฟล์เสียงที่ "มีอยู่แล้วในเกม" — รายชื่อ mock ไว้ก่อน ทีมสามารถแก้ path
# ให้ชี้ไปที่ไฟล์เสียงจริง (เช่นใน static/voices/) ได้ตามระบบเสียงที่มีอยู่แล้ว
