@app.route('/api/ai-chat/set-animation', methods=['POST'])
@require_auth_toggleable
def api_ai_chat_set_animation():
    """body: {session_id, preset} -> ตั้งอนิเมชันของตัวการ์ตูนโฮโลแกรม AI chat
    ใช้ ANIMATION_PRESETS ชุดเดียวกับที่โมเดล 3D อื่นๆ ในเกมใช้อยู่แล้ว ([ 2F ])"""
    data = request.get_json(silent=True) or {}
    session_id = (data.get("session_id") or "").strip()
    preset = (data.get("preset") or "").strip()
    if not session_id:
        return jsonify({"st": "error", "msg": "ต้องระบุ session_id"}), 400
    if preset not in ANIMATION_PRESETS:
        return jsonify({"st": "error",
                         "msg": f"preset ต้องเป็นหนึ่งใน {ANIMATION_PRESETS}"}), 400
    AI_CHAT_HOLO_STATE.setdefault(session_id, {})["animation"] = preset
    return jsonify({"st": "ok", "animation": preset})


@app.route('/api/ai-chat/set-voice', methods=['POST'])
@require_auth_toggleable
def api_ai_chat_set_voice():
    """body: {session_id, voice_id} -> ตั้งเสียงพากย์/ภาษาของตัวการ์ตูนโฮโลแกรม AI chat
    เลือกจาก voice line ที่มีอยู่แล้วในเกม (AI_CHAT_VOICE_LINES) เท่านั้น"""
    data = request.get_json(silent=True) or {}
    session_id = (data.get("session_id") or "").strip()
    voice_id = (data.get("voice_id") or "").strip()
    if not session_id:
        return jsonify({"st": "error", "msg": "ต้องระบุ session_id"}), 400
    voice = _ai_chat_voice_by_id(voice_id)
    if not voice:
        return jsonify({"st": "error", "msg": f"ไม่พบ voice_id '{voice_id}' ในรายชื่อเสียงที่มี"}), 404
    AI_CHAT_HOLO_STATE.setdefault(session_id, {})["voice_id"] = voice_id
    return jsonify({"st": "ok", "voice": voice})


