# ==========================================
# [ 6s. Centralized AI Server (RAG — Retrieval-Augmented Generation) ]
# เซิร์ฟเวอร์กลางให้ระบบอื่นๆ ในนี้ (NPC, chatbot, help desk ฯลฯ) ยิงคำถามเข้ามา
# แล้วได้คำตอบที่อ้างอิงจาก "คลังความรู้" ที่คุณป้อนไว้เอง แทนที่โมเดลจะตอบจาก
# ความจำล้วนๆ (ลดโอกาสตอบมั่ว/หลอน เพราะมีเอกสารอ้างอิงให้ยึด)
#
# การค้นคืนเอกสาร (retrieval) ใช้ TF-IDF + cosine similarity ที่เขียนเองล้วนๆ
# ไม่พึ่ง library ภายนอก ไม่ต้องมีเน็ต ทำงานได้ทันทีในนี้
#
# ส่วนการ "สร้างคำตอบ" (generation) ต้องต่อ LLM API จริง — เซิร์ฟเวอร์นี้ไม่มีเน็ต
# ขาออกตอนพัฒนา ต่อให้ไม่ได้ตอนนี้ ต้องตั้ง AI_SERVER_LLM_API_URL / _KEY เองตอน
# deploy จริง (เช่น ต่อ Anthropic API หรือ LLM ของคุณเอง) — ถ้ายังไม่ตั้งค่า ระบบจะ
# ส่งกลับแค่ "เอกสารที่เกี่ยวข้องที่สุด" ให้อ่านเอง โดยไม่ปั้นคำตอบให้
# ==========================================

import re as _rag_re
from collections import Counter as _RagCounter

KNOWLEDGE_DOCS = {}   # doc_id -> {title, source, text, uploaded_at}
KNOWLEDGE_CHUNKS = [] # [{chunk_id, doc_id, text, term_freq: Counter}]
_RAG_IDF_CACHE = {}   # term -> idf value, rebuild เมื่อมีเอกสารใหม่

AI_SERVER_LLM_API_URL = os.environ.get("AI_SERVER_LLM_API_URL", "")
AI_SERVER_LLM_API_KEY = os.environ.get("AI_SERVER_LLM_API_KEY", "")

CHUNK_SIZE_CHARS = 500  # ตัดเอกสารเป็นชิ้นละ ~500 ตัวอักษร ให้ retrieval แม่นขึ้น


def _rag_tokenize(text, ngram_sizes=(2, 3)):
    """ตัดคำ — ใช้ character n-gram แทนการตัดด้วย regex \\w+ ตรงๆ เพราะภาษาไทย
    ไม่มีช่องว่างคั่นระหว่างคำ (ลองแล้วพบว่า \\w+ ตัดคำไทยผิดเพี้ยนจนค้นหาไม่เจอ
    อะไรเลย) n-gram ตัวอักษรทำให้จับความคล้ายของข้อความไทยได้แม่นกว่าโดยไม่ต้องพึ่ง
    library ตัดคำไทยภายนอก ส่วนคำอังกฤษ/ตัวเลขเก็บทั้งคำตามปกติ"""
    text = _rag_re.sub(r"\s+", " ", text.lower()).strip()
    tokens = []
    for word in text.split(" "):
        if not word:
            continue
        if _rag_re.fullmatch(r"[a-z0-9_]+", word):
            tokens.append(word)
        else:
            for size in ngram_sizes:
                for i in range(len(word) - size + 1):
                    tokens.append(word[i:i + size])
            if len(word) < min(ngram_sizes):
                tokens.append(word)
    return tokens


def _rag_chunk_text(text, size=CHUNK_SIZE_CHARS):
    text = text.strip()
    return [text[i:i + size] for i in range(0, len(text), size)] or [text]


def _rag_rebuild_idf():
    """คำนวณ IDF ใหม่ทั้งคลัง — เรียกทุกครั้งที่มีการเพิ่ม/ลบเอกสาร"""
    global _RAG_IDF_CACHE
    n_docs = len(KNOWLEDGE_CHUNKS)
    if n_docs == 0:
        _RAG_IDF_CACHE = {}
        return
    doc_freq = _RagCounter()
    for chunk in KNOWLEDGE_CHUNKS:
        for term in set(chunk["term_freq"].keys()):
            doc_freq[term] += 1
    _RAG_IDF_CACHE = {term: math.log((n_docs + 1) / (df + 1)) + 1 for term, df in doc_freq.items()}


def _rag_vector(term_freq):
    """คืนเวกเตอร์ TF-IDF เป็น dict {term: weight}"""
    return {term: freq * _RAG_IDF_CACHE.get(term, 1.0) for term, freq in term_freq.items()}


def _rag_cosine_sim(vec_a, vec_b):
    common = set(vec_a) & set(vec_b)
    dot = sum(vec_a[t] * vec_b[t] for t in common)
    norm_a = math.sqrt(sum(v * v for v in vec_a.values())) or 1e-9
    norm_b = math.sqrt(sum(v * v for v in vec_b.values())) or 1e-9
    return dot / (norm_a * norm_b)


@app.route('/api/ai-server/knowledge', methods=['POST'])
@require_auth_toggleable
def api_ai_server_add_knowledge():
    """เพิ่มเอกสารเข้าคลังความรู้ — body: {title, text, source (ไม่บังคับ)}"""
    body = request.json or {}
    title = (body.get('title') or '').strip()
    text = (body.get('text') or '').strip()
    if not title or not text:
        return jsonify({"st": "error", "msg": "ต้องระบุ title และ text"}), 400
    doc_id = str(uuid.uuid4())[:8]
    KNOWLEDGE_DOCS[doc_id] = {"title": title, "source": body.get('source', ''),
                              "text": text, "uploaded_at": time.time()}
    for i, chunk_text in enumerate(_rag_chunk_text(text)):
        KNOWLEDGE_CHUNKS.append({
            "chunk_id": f"{doc_id}-{i}", "doc_id": doc_id, "title": title,
            "text": chunk_text, "term_freq": _RagCounter(_rag_tokenize(chunk_text)),
        })
    _rag_rebuild_idf()
    return jsonify({"st": "ok", "doc_id": doc_id,
                    "chunk_count": sum(1 for c in KNOWLEDGE_CHUNKS if c["doc_id"] == doc_id)})


@app.route('/api/ai-server/knowledge/<doc_id>', methods=['DELETE'])
@require_auth_toggleable
def api_ai_server_delete_knowledge(doc_id):
    global KNOWLEDGE_CHUNKS
    if doc_id not in KNOWLEDGE_DOCS:
        return jsonify({"st": "error", "msg": "ไม่พบเอกสารนี้"}), 404
    del KNOWLEDGE_DOCS[doc_id]
    KNOWLEDGE_CHUNKS = [c for c in KNOWLEDGE_CHUNKS if c["doc_id"] != doc_id]
    _rag_rebuild_idf()
    return jsonify({"st": "ok"})


@app.route('/api/ai-server/knowledge', methods=['GET'])
def api_ai_server_list_knowledge():
    return jsonify({"st": "ok", "count": len(KNOWLEDGE_DOCS),
                    "docs": {did: {"title": d["title"], "source": d["source"],
                                   "char_count": len(d["text"])}
                             for did, d in KNOWLEDGE_DOCS.items()}})


def _rag_retrieve(question, top_k=4):
    """คืน chunk ที่เกี่ยวข้องที่สุด top_k อันดับ เรียงจากคะแนนสูงไปต่ำ"""
    if not KNOWLEDGE_CHUNKS:
        return []
    q_vec = _rag_vector(_RagCounter(_rag_tokenize(question)))
    scored = []
    for chunk in KNOWLEDGE_CHUNKS:
        c_vec = _rag_vector(chunk["term_freq"])
        score = _rag_cosine_sim(q_vec, c_vec)
        if score > 0:
            scored.append((score, chunk))
    scored.sort(key=lambda x: x[0], reverse=True)
    return scored[:top_k]


def _rag_call_llm(question, context_text):
    """ยิงคำถาม+context ไปที่ LLM API จริง — ต้องตั้งค่า AI_SERVER_LLM_API_URL/_KEY
    ก่อน รูปแบบ payload ด้านล่างอิงตาม Anthropic Messages API เป็นตัวอย่าง ถ้าต่อ
    LLM เจ้าอื่นต้องปรับ payload/headers ให้ตรงกับ API docs ของเจ้านั้นเอง"""
    if not (AI_SERVER_LLM_API_URL and AI_SERVER_LLM_API_KEY):
        return {"ok": False, "error": "ยังไม่ได้ตั้งค่า AI_SERVER_LLM_API_URL / AI_SERVER_LLM_API_KEY"}
    prompt = (f"ใช้ข้อมูลอ้างอิงต่อไปนี้ตอบคำถาม ถ้าข้อมูลไม่พอให้บอกตรงๆ ว่าไม่รู้ "
             f"ห้ามเดา:\n\n--- ข้อมูลอ้างอิง ---\n{context_text}\n\n--- คำถาม ---\n{question}")
    headers = {"x-api-key": AI_SERVER_LLM_API_KEY, "anthropic-version": "2023-06-01",
              "content-type": "application/json"}
    payload = {"model": "claude-sonnet-4-6", "max_tokens": 1000,
              "messages": [{"role": "user", "content": prompt}]}
    try:
        resp = requests.post(AI_SERVER_LLM_API_URL, json=payload, headers=headers, timeout=30)
        resp.raise_for_status()
        data = resp.json()
        answer = "".join(b.get("text", "") for b in data.get("content", []) if b.get("type") == "text")
        return {"ok": True, "answer": answer}
    except Exception as e:
        return {"ok": False, "error": str(e)}


@app.route('/api/ai-server/query', methods=['POST'])
@require_auth_toggleable
def api_ai_server_query():
    """ยิงคำถามเข้าเซิร์ฟเวอร์กลาง — body: {question, top_k (ไม่บังคับ)}
    ค้นเอกสารที่เกี่ยวข้องก่อนเสมอ (ทำงานได้แม้ไม่ได้ต่อ LLM) แล้วถ้าตั้งค่า LLM
    ไว้แล้วจะปั้นคำตอบให้ด้วย ไม่งั้นส่งแค่เอกสารที่เกี่ยวข้องกลับไปให้อ่านเอง"""
    body = request.json or {}
    question = (body.get('question') or '').strip()
    if not question:
        return jsonify({"st": "error", "msg": "ต้องระบุ question"}), 400
    top_k = int(body.get('top_k', 4))
    retrieved = _rag_retrieve(question, top_k=top_k)
    sources = [{"chunk_id": c["chunk_id"], "doc_title": c["title"],
               "score": round(score, 4), "excerpt": c["text"][:200]}
              for score, c in retrieved]
    if not retrieved:
        return jsonify({"st": "ok", "answer": None, "sources": [],
                        "note": "ไม่พบเอกสารในคลังที่เกี่ยวข้องกับคำถามนี้เลย — เพิ่มเอกสารที่ /api/ai-server/knowledge ก่อน"})
    context_text = "\n\n".join(f"[{c['title']}] {c['text']}" for _, c in retrieved)
    llm_result = _rag_call_llm(question, context_text)
    if llm_result["ok"]:
        return jsonify({"st": "ok", "answer": llm_result["answer"], "sources": sources})
    return jsonify({"st": "ok", "answer": None, "sources": sources,
                    "note": f"ยังไม่ได้ต่อ LLM ให้ปั้นคำตอบอัตโนมัติ ({llm_result['error']}) "
                            "— นี่คือเอกสารที่เกี่ยวข้องที่สุดที่หาเจอ อ่านเองได้เลย"})


VMAX_MODULES["ai_server_rag"] = {
    "desc": "Centralized AI Server แบบ RAG — ค้นเอกสาร (TF-IDF เขียนเอง ไม่ต้องมีเน็ต) "
            "แล้วต่อ LLM จริงให้ปั้นคำตอบ (ต้องตั้ง AI_SERVER_LLM_API_URL/_KEY เอง)",
    "routes": ["/api/ai-server/knowledge", "/api/ai-server/knowledge/<id>", "/api/ai-server/query"],
}


# ==========================================
# [ 6t. Game Turbo — ฝั่งเซิร์ฟเวอร์ (รับคำสั่งจาก launcher) ]
# ส่วนที่ตรวจจับ "ปัดหน้าจอ 2 ครั้ง" แล้วเปิดเมนูลอย เป็นโค้ดฝั่ง launcher (client)
# ล้วนๆ ต้องเขียนแยกในตัว launcher เอง — ไม่ใช่ Python/Flask ทำให้ไม่ได้ในไฟล์นี้
#
# ส่วนที่ทำได้ในนี้คือ "ปลายทาง" ที่ launcher ยิงคำสั่งมาหาเมื่อผู้เล่นกดใช้เมนู
# turbo เช่น เคลียร์แคชฝั่งเซิร์ฟเวอร์ของผู้เล่นคนนั้น, สลับโหมด turbo ต่อ session
#
# ข้อจำกัดที่ต้องรู้: เซิร์ฟเวอร์ "เคลียร์แคชบนตัวเครื่องผู้เล่น" ให้ไม่ได้จริงๆ (นั่น
# เป็นพื้นที่เก็บข้อมูลในมือถือ/เครื่องผู้เล่น เซิร์ฟเวอร์เข้าไปแตะไม่ได้และไม่ควร
# ทำได้ด้วยเหตุผลความปลอดภัย) endpoint นี้เคลียร์ได้แค่ "แคชฝั่งเซิร์ฟเวอร์" ที่
# เก็บไว้แทนผู้เล่นคนนั้น (เช่น session state, ข้อมูลชั่วคราวที่ค้างจากรอบก่อน)
# ==========================================

GAME_TURBO_SESSIONS = {}  # uid -> {"turbo_enabled": bool, "last_clear_cache_at": ts}
GAME_TURBO_MAX_SESSIONS = 50000   # [SECURITY-FIX T1] กัน dict โตไม่จำกัดจากการยิง uid สุ่มรัวๆ


def _turbo_session(uid):
    """ดึง/สร้าง session ของ uid โดยจำกัดจำนวนรวม (ตัดของเก่าสุดออกเมื่อเต็ม)"""
    sess = GAME_TURBO_SESSIONS.get(uid)
    if sess is None:
        while len(GAME_TURBO_SESSIONS) >= GAME_TURBO_MAX_SESSIONS:
            GAME_TURBO_SESSIONS.pop(next(iter(GAME_TURBO_SESSIONS)), None)
        sess = GAME_TURBO_SESSIONS.setdefault(uid, {"turbo_enabled": False, "last_clear_cache_at": None})
    return sess


@app.route('/api/game-turbo/toggle', methods=['POST'])
@require_auth_toggleable
def api_game_turbo_toggle():
    """สลับโหมด turbo ต่อผู้เล่น — body: {uid, enabled}
    เก็บไว้เป็น flag ต่อ session ให้ระบบอื่น (เช่น physics_sync_loop) เช็คได้ว่า
    ผู้เล่นคนนี้เปิด turbo อยู่ไหม (เช่น จะได้ลดความถี่ broadcast บางอย่างให้เบาลง)"""
    body = request.get_json(silent=True) or {}
    # [SECURITY-FIX T1] uid ผูกกับ JWT — สลับ turbo ของคนอื่นไม่ได้
    uid, err = _kb_bound_uid(body.get('uid', ''))
    if err:
        return err
    enabled = bool(body.get('enabled', True))
    sess = _turbo_session(uid)
    sess["turbo_enabled"] = enabled
    return jsonify({"st": "ok", "uid": uid, "turbo_enabled": enabled})


@app.route('/api/game-turbo/clear-cache', methods=['POST'])
@require_auth_toggleable
def api_game_turbo_clear_cache():
    """เคลียร์แคชฝั่งเซิร์ฟเวอร์ของผู้เล่นคนนี้ — body: {uid}
    เคลียร์ได้เฉพาะข้อมูลชั่วคราวที่เซิร์ฟเวอร์เก็บแทนผู้เล่น ไม่ใช่แคชบนเครื่อง
    ผู้เล่นเอง (อันนั้นต้องเคลียร์ในโค้ดฝั่ง launcher เอง)"""
    body = request.get_json(silent=True) or {}
    # [SECURITY-FIX T1] uid ผูกกับ JWT — เคลียร์แคชของคนอื่นไม่ได้
    uid, err = _kb_bound_uid(body.get('uid', ''))
    if err:
        return err
    sess = _turbo_session(uid)
    sess["last_clear_cache_at"] = time.time()
    return jsonify({"st": "ok", "uid": uid, "cleared_at": sess["last_clear_cache_at"],
                    "note": "เคลียร์แคชฝั่งเซิร์ฟเวอร์ของ uid นี้แล้ว (แคชบนเครื่องผู้เล่นต้องเคลียร์ในตัว launcher เอง)"})


@app.route('/api/game-turbo/status', methods=['GET'])
def api_game_turbo_status():
    """สถานะให้เมนู turbo ฝั่ง launcher โชว์ผล — ?uid=xxx"""
    uid, err = _kb_bound_uid(request.args.get('uid', ''))
    if err:
        return err
    sess = GAME_TURBO_SESSIONS.get(uid, {"turbo_enabled": False, "last_clear_cache_at": None})
    return jsonify({"st": "ok", "uid": uid, "turbo_enabled": sess["turbo_enabled"],
                    "last_clear_cache_at": sess["last_clear_cache_at"],
                    "active_turbo_sessions": sum(1 for s in GAME_TURBO_SESSIONS.values() if s["turbo_enabled"])})


VMAX_MODULES["game_turbo_server_side"] = {
    "desc": "ปลายทางฝั่งเซิร์ฟเวอร์รับคำสั่งจากเมนู Game Turbo ใน launcher (เคลียร์แคชฝั่งเซิร์ฟเวอร์, สลับโหมด turbo ต่อ session) "
            "— การตรวจจับปัดหน้าจอ 2 ครั้ง + เมนูลอย ต้องเขียนแยกในโค้ดฝั่ง launcher เอง ไม่ได้อยู่ในไฟล์นี้",
    "routes": ["/api/game-turbo/toggle", "/api/game-turbo/clear-cache", "/api/game-turbo/status"],
}


# ==========================================
# [ 6u. Idle Screen Personalization: อัปโหลดรูป/อีโมจิส่วนตัว ]
# ต่อจากที่ค้างไว้ — ให้ผู้เล่นอัปโหลดรูป/GIF หรือเลือกอีโมจิเป็นภาพหน้าจอ idle
# ของตัวเอง (แสดงตอนเกม/แอปเข้าโหมด idle เช่นจาก power_saver_widget ด้านบน)
#
# เรื่องลิขสิทธิ์: ระบบนี้ "ไม่มีทางตรวจสอบอัตโนมัติ" ได้ว่ารูปที่อัปโหลดมาเป็น
# ของผู้เล่นเองจริงหรือไปเอารูปคนอื่น/มีลิขสิทธิ์มา — ต่างจาก manga_platform ที่มี
# ขั้นตอนให้คนจริง/ทนายตรวจเอกสารก่อน confirm ตรงนี้เป็นการใช้งานส่วนตัวเบาๆ เลย
# ใช้วิธีเดียวกับที่หลายแพลตฟอร์มทำ (เช่นตอนตั้งรูปโปรไฟล์): ให้ผู้เล่น "รับรองด้วย
# ตัวเอง" (self-certify) ว่ามีสิทธิ์ใช้รูปนี้ ผ่าน flag copyright_ack=true ที่ต้องส่ง
# มาด้วยทุกครั้ง — ถ้าไม่ส่งมาหรือส่งเป็น false ระบบจะปฏิเสธการอัปโหลดทันที และ
# ทุก asset ที่บันทึกไว้จะมี note เตือนติดไปด้วยเสมอว่านี่คือคำรับรองของผู้ใช้เอง
# ไม่ใช่การตรวจสอบจริงจากระบบ — ถ้าพบว่าเป็นรูปละเมิดลิขสิทธิ์ทีหลัง ให้ลบผ่าน
# DELETE /api/idle-screen/<asset_id> (แอดมิน/เจ้าของบัญชีเรียกเองได้)
# ==========================================

IDLE_SCREEN_DIR = "uploaded_idle_screens"
IDLE_SCREEN_INDEX_PATH = os.path.join(IDLE_SCREEN_DIR, "index.json")
ALLOWED_IDLE_ASSET_EXTENSIONS = {"jpg", "jpeg", "png", "webp", "gif"}
IDLE_SCREEN_COPYRIGHT_NOTE = (
    "รูป/GIF นี้เป็นการรับรองด้วยตนเองของผู้ใช้ (self-certified) ว่ามีสิทธิ์ใช้งาน "
    "ระบบไม่ได้ตรวจสอบลิขสิทธิ์จริงให้ — หากพบว่าละเมิดลิขสิทธิ์ ให้ลบออกที่ "
    "DELETE /api/idle-screen/<asset_id>"
)

os.makedirs(IDLE_SCREEN_DIR, exist_ok=True)

IDLE_SCREEN_ASSETS = {}   # asset_id -> {uid, kind, filename, sha256, copyright_ack, uploaded_at}
IDLE_SCREEN_ACTIVE = {}   # uid -> asset_id (or None -> ใช้ค่าเริ่มต้นของระบบ)


def _idle_screen_load_index():
    if os.path.exists(IDLE_SCREEN_INDEX_PATH):
        with open(IDLE_SCREEN_INDEX_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    return {"assets": {}, "active": {}}


def _idle_screen_save_index():
    with open(IDLE_SCREEN_INDEX_PATH, "w", encoding="utf-8") as f:
        json.dump({"assets": IDLE_SCREEN_ASSETS, "active": IDLE_SCREEN_ACTIVE}, f, ensure_ascii=False, indent=2)


def _idle_screen_load_on_boot():
    data = _idle_screen_load_index()
    IDLE_SCREEN_ASSETS.update(data.get("assets", {}))
    IDLE_SCREEN_ACTIVE.update(data.get("active", {}))


_idle_screen_load_on_boot()


@app.route('/api/idle-screen/upload', methods=['POST'])
@require_auth_toggleable
def api_idle_screen_upload():
    """อัปโหลดรูป/GIF ส่วนตัวไว้ใช้เป็นหน้าจอ idle — multipart: field 'image',
    form fields: uid (required), copyright_ack ('true'/'1', required), label (ไม่บังคับ)
    ถ้าอัปโหลดไฟล์เดิมซ้ำ (hash ตรงกัน) ของ uid เดียวกัน จะคืน asset เดิมแทนที่จะสร้างซ้ำ"""
    uid = (request.form.get('uid') or '').strip()
    if not uid:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
    copyright_ack = (request.form.get('copyright_ack') or '').strip().lower() in ('true', '1', 'yes')
    if not copyright_ack:
        return jsonify({"st": "error",
                        "msg": "ต้องยืนยัน copyright_ack=true ว่าคุณมีสิทธิ์ใช้รูปนี้ "
                               "ก่อนอัปโหลด (ระบบไม่ได้ตรวจสอบลิขสิทธิ์จริงให้)"}), 400
    f = request.files.get('image')
    if not f or not f.filename:
        return jsonify({"st": "error", "msg": "ต้องแนบไฟล์รูป/GIF (field: image)"}), 400
    ext = (f.filename.rsplit('.', 1)[-1] if '.' in f.filename else '').lower()
    if ext not in ALLOWED_IDLE_ASSET_EXTENSIONS:
        return jsonify({"st": "error", "msg": f"รองรับเฉพาะ {', '.join(sorted(ALLOWED_IDLE_ASSET_EXTENSIONS))}"}), 400

    raw = f.read()
    sha256 = hashlib.sha256(raw).hexdigest()

    # เช็คซ้ำ: uid เดียวกัน + hash เดียวกัน -> คืน asset เดิม ไม่บันทึกซ้ำ
    for aid, a in IDLE_SCREEN_ASSETS.items():
        if a["uid"] == uid and a["sha256"] == sha256:
            return jsonify({"st": "ok", "asset_id": aid, "asset": a, "duplicate": True,
                            "copyright_note": IDLE_SCREEN_COPYRIGHT_NOTE})

    asset_id = str(uuid.uuid4())[:8]
    uid_dir = os.path.join(IDLE_SCREEN_DIR, secure_filename(uid))
    os.makedirs(uid_dir, exist_ok=True)
    fname = secure_filename(f"{asset_id}.{ext}")
    with open(os.path.join(uid_dir, fname), "wb") as out:
        out.write(raw)

    IDLE_SCREEN_ASSETS[asset_id] = {
        "uid": uid, "kind": "gif" if ext == "gif" else "image",
        "filename": fname, "sha256": sha256, "label": request.form.get('label', ''),
        "copyright_ack": True, "uploaded_at": time.time(),
    }
    _idle_screen_save_index()
    return jsonify({"st": "ok", "asset_id": asset_id, "asset": IDLE_SCREEN_ASSETS[asset_id],
                    "copyright_note": IDLE_SCREEN_COPYRIGHT_NOTE})


@app.route('/api/idle-screen/emoji', methods=['POST'])
@require_auth
def api_idle_screen_set_emoji():
    """ตั้งอีโมจิ (ตัวอักษร unicode ธรรมดา ไม่ใช่ไฟล์รูป) เป็นหน้าจอ idle —
    body: {uid, emoji, label?} — ไม่ต้องมี copyright_ack เพราะเป็นอีโมจิมาตรฐาน
    ไม่ใช่ไฟล์รูปที่อัปโหลดเอง"""
    body = request.json or {}
    uid = (resolve_uid(body) or '').strip()
    emoji = (body.get('emoji') or '').strip()
    if not uid or not emoji:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid และ emoji"}), 400
    if len(emoji) > 8:
        return jsonify({"st": "error", "msg": "emoji ควรเป็นอักขระเดียว/กลุ่มสั้นๆ ไม่ใช่ข้อความยาว"}), 400
    asset_id = str(uuid.uuid4())[:8]
    IDLE_SCREEN_ASSETS[asset_id] = {
        "uid": uid, "kind": "emoji", "value": emoji, "label": body.get('label', ''),
        "copyright_ack": True, "uploaded_at": time.time(),
    }
    IDLE_SCREEN_ACTIVE[uid] = asset_id
    _idle_screen_save_index()
    return jsonify({"st": "ok", "asset_id": asset_id, "asset": IDLE_SCREEN_ASSETS[asset_id]})


@app.route('/api/idle-screen/list', methods=['GET'])
def api_idle_screen_list():
    """?uid=xxx -> asset ทั้งหมดของผู้เล่นคนนี้ (รูป/GIF/อีโมจิ)"""
    uid = request.args.get('uid', '')
    assets = {aid: a for aid, a in IDLE_SCREEN_ASSETS.items() if a["uid"] == uid}
    return jsonify({"st": "ok", "uid": uid, "assets": assets,
                    "active_asset_id": IDLE_SCREEN_ACTIVE.get(uid)})


@app.route('/api/idle-screen/file/<asset_id>', methods=['GET'])
def api_idle_screen_get_file(asset_id):
    """คืนไฟล์รูป/GIF จริงของ asset นี้ (ใช้ตอน render หน้าจอ idle) — อีโมจิไม่มีไฟล์
    ให้ดึงค่า 'value' จาก /api/idle-screen/list แทน"""
    a = IDLE_SCREEN_ASSETS.get(asset_id)
    if not a or a["kind"] not in ("image", "gif"):
        return jsonify({"st": "error", "msg": "ไม่พบไฟล์รูปสำหรับ asset นี้"}), 404
    uid_dir = os.path.join(IDLE_SCREEN_DIR, secure_filename(a["uid"]))
    return send_from_directory(uid_dir, a["filename"])


@app.route('/api/idle-screen/set-active', methods=['POST'])
@require_auth
def api_idle_screen_set_active():
    """ตั้ง asset ที่จะใช้แสดงตอนเข้าโหมด idle จริง — body: {uid, asset_id}"""
    body = request.json or {}
    uid = (resolve_uid(body) or '').strip()
    asset_id = body.get('asset_id', '')
    if not uid or asset_id not in IDLE_SCREEN_ASSETS or IDLE_SCREEN_ASSETS[asset_id]["uid"] != uid:
        return jsonify({"st": "error", "msg": "uid/asset_id ไม่ถูกต้อง หรือ asset ไม่ใช่ของ uid นี้"}), 400
    IDLE_SCREEN_ACTIVE[uid] = asset_id
    _idle_screen_save_index()
    return jsonify({"st": "ok", "uid": uid, "active_asset_id": asset_id})


@app.route('/api/idle-screen/active', methods=['GET'])
def api_idle_screen_get_active():
    """?uid=xxx -> asset ที่กำลังตั้งเป็นหน้าจอ idle อยู่ตอนนี้ (ให้ตัว renderer ฝั่ง
    client ดึงไปโชว์ตอน power saver / idle mode ทำงาน) คืน None ถ้ายังไม่ได้ตั้งไว้"""
    uid = request.args.get('uid', '')
    asset_id = IDLE_SCREEN_ACTIVE.get(uid)
    asset = IDLE_SCREEN_ASSETS.get(asset_id) if asset_id else None
    return jsonify({"st": "ok", "uid": uid, "active_asset_id": asset_id, "asset": asset})


@app.route('/api/idle-screen/<asset_id>', methods=['DELETE'])
@require_auth_toggleable
def api_idle_screen_delete(asset_id):
    """ลบ asset (เช่นตอนพบว่าละเมิดลิขสิทธิ์ทีหลัง หรือผู้เล่นลบเอง)"""
    a = IDLE_SCREEN_ASSETS.pop(asset_id, None)
    if not a:
        return jsonify({"st": "error", "msg": "ไม่พบ asset นี้"}), 404
    if a["kind"] in ("image", "gif"):
        path = os.path.join(IDLE_SCREEN_DIR, secure_filename(a["uid"]), a["filename"])
        if os.path.exists(path):
            os.remove(path)
    for uid, active_id in list(IDLE_SCREEN_ACTIVE.items()):
        if active_id == asset_id:
            del IDLE_SCREEN_ACTIVE[uid]
    _idle_screen_save_index()
    return jsonify({"st": "ok", "deleted": asset_id})


