# ==========================================
# [ 6v2. World Clock — เวลาประเทศคู่ขนาน ]
# โชว์เวลาหลายประเทศเทียบกันแบบ "คู่ขนาน" ในหน้าเดียว — ผู้เล่นเลือกได้ว่าอยากเทียบ
# กับประเทศไหนบ้าง (เช่น ไทย vs ญี่ปุ่น vs สหรัฐฯ) แล้วบันทึกไว้ข้ามเกม/ข้าม session
# เหมือน widget อื่นๆ ด้านบน — เวลาจริงคำนวณฝั่ง client (Intl.DateTimeFormat) เพื่อให้
# นาฬิกาเดินสดๆ โดยไม่ต้อง poll เซิร์ฟเวอร์ทุกวินาที เซิร์ฟเวอร์มีหน้าที่แค่เก็บว่า
# ผู้เล่นเลือกโซนไหนไว้บ้าง
# ==========================================
from zoneinfo import ZoneInfo

WORLD_CLOCK_ZONES = {
    "thailand":  {"label": "ไทย (กรุงเทพฯ)", "tz": "Asia/Bangkok"},
    "japan":     {"label": "ญี่ปุ่น (โตเกียว)", "tz": "Asia/Tokyo"},
    "korea":     {"label": "เกาหลีใต้ (โซล)", "tz": "Asia/Seoul"},
    "china":     {"label": "จีน (เซี่ยงไฮ้)", "tz": "Asia/Shanghai"},
    "india":     {"label": "อินเดีย (นิวเดลี)", "tz": "Asia/Kolkata"},
    "uae":       {"label": "สหรัฐอาหรับเอมิเรตส์ (ดูไบ)", "tz": "Asia/Dubai"},
    "uk":        {"label": "อังกฤษ (ลอนดอน)", "tz": "Europe/London"},
    "germany":   {"label": "เยอรมนี (เบอร์ลิน)", "tz": "Europe/Berlin"},
    "usa_east":  {"label": "สหรัฐฯ ฝั่งตะวันออก (นิวยอร์ก)", "tz": "America/New_York"},
    "usa_west":  {"label": "สหรัฐฯ ฝั่งตะวันตก (ลอสแอนเจลิส)", "tz": "America/Los_Angeles"},
    "australia": {"label": "ออสเตรเลีย (ซิดนีย์)", "tz": "Australia/Sydney"},
}

WORLD_CLOCK_PAIRS = {}  # uid -> list ของ zone key ที่เลือกโชว์คู่ขนาน (เช่น ["thailand","japan"])


@app.route('/api/world-clock/zones', methods=['GET'])
def api_world_clock_zones():
    """คืนรายชื่อโซนเวลาทั้งหมดที่เลือกได้ พร้อมเวลาปัจจุบัน ณ ตอนเรียก (ฝั่ง client
    ควรเอา tz ไปคำนวณเดินนาฬิกาต่อเองด้วย Intl.DateTimeFormat ไม่ต้อง poll ทุกวินาที)"""
    out = {}
    for key, z in WORLD_CLOCK_ZONES.items():
        local = datetime.now(ZoneInfo(z["tz"]))
        out[key] = {"label": z["label"], "tz": z["tz"], "now": local.strftime("%Y-%m-%d %H:%M:%S")}
    return jsonify({"st": "ok", "zones": out})


@app.route('/api/world-clock/pairs', methods=['GET', 'POST'])
@require_auth_toggleable
def api_world_clock_pairs():
    """GET ?uid=xxx -> คืนรายการโซนที่ผู้เล่นตั้งไว้ให้โชว์คู่ขนาน
    POST body: {uid, zones: ["thailand","japan",...]} -> บันทึกทับของเดิม (สูงสุด 6 โซน)"""
    if request.method == 'POST':
        body = request.json or {}
        uid = body.get('uid', '')
        if not uid:
            return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
        zones = [z for z in body.get('zones', []) if z in WORLD_CLOCK_ZONES][:6]
        WORLD_CLOCK_PAIRS[uid] = zones
        return jsonify({"st": "ok", "uid": uid, "zones": zones})
    uid = request.args.get('uid', '')
    return jsonify({"st": "ok", "uid": uid, "zones": WORLD_CLOCK_PAIRS.get(uid, ["thailand", "japan"])})


