# ==========================================
# [ 6v3. Battery-Critical Simulator Screen — โปรแกรมจำลอง "หน้าจอปลอม" ตอนแบตใกล้หมด ]
# ต่างจาก power_saver_widget (6v) ตรงที่ตัวนั้นตัดสินใจจาก "ไม่มีการแตะจอนาน" ส่วนอันนี้
# ตัดสินใจจาก "ค่าแบตจริงของเกม (BAT.soc) ต่ำกว่าเกณฑ์" — พอเข้าเกณฑ์ จะสลับจากหน้าเกม
# จริงไปเป็น "หน้าจอจำลอง" เบาๆ ที่โชว์แค่เวลา+เปอร์เซ็นต์แบต พื้นหลังดำ ใช้พลังงานน้อย
# ที่สุด (ไม่มี asset หนักๆ ของเกมโหลดอยู่เลยตอนอยู่ในโหมดนี้)
# ==========================================
BATTERY_SIM_PLAYER_PREFS = {}  # uid -> {enabled, threshold_percent}
BATTERY_SIM_DEFAULT_THRESHOLD = 15.0


@app.route('/api/battery-simulator/prefs', methods=['GET', 'POST'])
@require_auth_toggleable
def api_battery_simulator_prefs():
    """GET ?uid=xxx -> ค่า threshold ที่ตั้งไว้ (default 15%)
    POST body: {uid, prefs: {enabled, threshold_percent}}"""
    if request.method == 'POST':
        body = request.json or {}
        uid = body.get('uid', '')
        if not uid:
            return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
        BATTERY_SIM_PLAYER_PREFS[uid] = body.get('prefs') or {}
        return jsonify({"st": "ok", "uid": uid, "prefs": BATTERY_SIM_PLAYER_PREFS[uid]})
    uid = request.args.get('uid', '')
    prefs = BATTERY_SIM_PLAYER_PREFS.get(uid, {"enabled": True, "threshold_percent": BATTERY_SIM_DEFAULT_THRESHOLD})
    return jsonify({"st": "ok", "uid": uid, "prefs": prefs})


@app.route('/api/battery-simulator/status', methods=['GET'])
def api_battery_simulator_status():
    """?uid=xxx -> {active, soc, threshold} — client (widget) poll เบาๆ ทุก 5-10 วิ
    ก็พอ เพื่อรู้ว่าตอนนี้ควรสลับไปหน้าจอจำลองหรือยัง"""
    uid = request.args.get('uid', '')
    prefs = BATTERY_SIM_PLAYER_PREFS.get(uid, {"enabled": True, "threshold_percent": BATTERY_SIM_DEFAULT_THRESHOLD})
    threshold = prefs.get("threshold_percent", BATTERY_SIM_DEFAULT_THRESHOLD)
    active = bool(prefs.get("enabled", True)) and BAT.soc <= threshold
    return jsonify({"st": "ok", "active": active, "soc": round(BAT.soc, 1), "threshold": threshold})


