# ==========================================
# [ 6v4. Device Simulator — โปรแกรมจำลองอุปกรณ์/หน้าจอมือถือปลอมในเกม ]
# ต่างจาก 6v3 (ซึ่งเป็นแค่จอดำโชว์เวลา+แบต) อันนี้คือ "โปรแกรมจำลอง" เต็มรูปแบบ —
# จำลองหน้าจอโฮมของมือถือปลอมๆ ไว้ในเกม (ไอคอนแอป, แถบแจ้งเตือน) ให้เกมต่างๆ เอาไปใช้
# เป็นฉาก/ปริศนา/อีสเตอร์เอ้กในเกมได้ (เช่น ผู้เล่นต้อง "ปลดล็อกมือถือ" ในเกมเพื่อหา
# เบาะแส) ตั้งค่าไอคอน/วอลเปเปอร์/การแจ้งเตือนได้ต่อ uid ผ่าน config ด้านล่าง
# ==========================================
DEVICE_SIM_CONFIG = {}  # uid -> {wallpaper, apps: [...], notifications: [...]}
DEVICE_SIM_DEFAULT_APPS = ["โทรศัพท์", "ข้อความ", "กล้อง", "แกลเลอรี", "ตั้งค่า"]


@app.route('/api/device-simulator/config', methods=['GET', 'POST'])
@require_auth_toggleable
def api_device_simulator_config():
    """GET ?uid=xxx -> config หน้าจอจำลองของ uid นี้ (ไอคอนแอป/วอลเปเปอร์/แจ้งเตือน)
    POST body: {uid, config: {wallpaper?, apps?: [...], notifications?: [...]}}"""
    if request.method == 'POST':
        body = request.json or {}
        uid = body.get('uid', '')
        if not uid:
            return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
        DEVICE_SIM_CONFIG[uid] = body.get('config') or {}
        return jsonify({"st": "ok", "uid": uid, "config": DEVICE_SIM_CONFIG[uid]})
    uid = request.args.get('uid', '')
    cfg = DEVICE_SIM_CONFIG.get(uid, {"wallpaper": "#1c1c2e", "apps": DEVICE_SIM_DEFAULT_APPS, "notifications": []})
    return jsonify({"st": "ok", "uid": uid, "config": cfg})


@app.route('/api/device-simulator/notify', methods=['POST'])
@require_auth_toggleable
def api_device_simulator_push_notify():
    """ดันแจ้งเตือนปลอมเข้าไปในจอจำลอง (เช่นตอนเกมอยากให้ปริศนาโผล่มาเป็นข้อความ)
    body: {uid, title, body}"""
    body = request.json or {}
    uid = body.get('uid', '')
    if not uid:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
    cfg = DEVICE_SIM_CONFIG.setdefault(uid, {"wallpaper": "#1c1c2e", "apps": DEVICE_SIM_DEFAULT_APPS, "notifications": []})
    cfg.setdefault("notifications", []).append({
        "title": body.get("title", ""), "body": body.get("body", ""), "at": time.time(),
    })
    cfg["notifications"] = cfg["notifications"][-20:]  # เก็บล่าสุด 20 อันพอ
    return jsonify({"st": "ok", "uid": uid, "notifications": cfg["notifications"]})


DEVICE_SIM_WIDGET_HTML = """
<div id="vmax-device-sim" style="display:none;position:fixed;inset:0;z-index:99998;
  background:#1c1c2e;color:#fff;font-family:sans-serif;flex-direction:column;">
  <div style="padding:8px 16px;font-size:12px;opacity:.6;display:flex;justify-content:space-between;">
    <span id="vmax-dsim-clock"></span><span>🔋 <span id="vmax-dsim-batt"></span>%</span>
  </div>
  <div id="vmax-dsim-notifs" style="padding:0 12px;"></div>
  <div id="vmax-dsim-apps" style="flex:1;display:grid;grid-template-columns:repeat(4,1fr);
    gap:16px;padding:24px;align-content:start;"></div>
</div>
"""

DEVICE_SIM_WIDGET_JS = """
(function(){
  var uid = (window.VMAX_DEVICE_SIM_CONFIG && window.VMAX_DEVICE_SIM_CONFIG.uid) || 'guest';
  var pollMs = (window.VMAX_DEVICE_SIM_CONFIG && window.VMAX_DEVICE_SIM_CONFIG.pollMs) || 5000;
  var box = document.getElementById('vmax-device-sim');
  function esc(t){
    return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function isOpen(){ return box.style.display !== 'none'; }
  function refresh(){
    fetch('/api/device-simulator/config?uid=' + encodeURIComponent(uid))
      .then(function(r){return r.json();}).then(function(d){
        var cfg = d.config || {};
        box.style.background = cfg.wallpaper || '#1c1c2e';
        document.getElementById('vmax-dsim-apps').innerHTML = (cfg.apps || []).map(function(a){
          return '<div style="text-align:center;font-size:12px;"><div style="width:48px;height:48px;' +
            'background:rgba(255,255,255,.15);border-radius:12px;margin:0 auto 4px;"></div>' + esc(a) + '</div>';
        }).join('');
        document.getElementById('vmax-dsim-notifs').innerHTML = (cfg.notifications || []).slice(-3).map(function(n){
          return '<div style="background:rgba(255,255,255,.1);border-radius:8px;padding:8px 12px;' +
            'margin-bottom:6px;"><b>' + esc(n.title) + '</b><div style="font-size:12px;opacity:.8">' +
            esc(n.body) + '</div></div>';
        }).join('');
      }).catch(function(){});
    fetch('/api/battery-simulator/status?uid=' + encodeURIComponent(uid))
      .then(function(r){return r.json();}).then(function(d){
        document.getElementById('vmax-dsim-batt').innerText = (d.soc != null ? d.soc : '--');
      }).catch(function(){});
  }
  function poll(){ if (isOpen()) refresh(); }
  function tickClock(){
    document.getElementById('vmax-dsim-clock').innerText =
      new Date().toLocaleTimeString('th-TH', {hour12: false, hour: '2-digit', minute: '2-digit'});
  }
  window.vmaxOpenDeviceSimulator = function(){ box.style.display = 'flex'; refresh(); };
  window.vmaxCloseDeviceSimulator = function(){ box.style.display = 'none'; };
  box.addEventListener('dblclick', function(){ box.style.display = 'none'; });
  poll(); tickClock();
  setInterval(poll, pollMs);
  setInterval(tickClock, 1000);
})();
"""


