DUAL_MUSIC_WIDGET_JS = """
(function(){
  var uid = (window.VMAX_DUAL_MUSIC_CONFIG && window.VMAX_DUAL_MUSIC_CONFIG.uid) || 'guest';
  var audioA = document.getElementById('vmax-dm-audio-a');
  var audioB = document.getElementById('vmax-dm-audio-b');
  var selA = document.getElementById('vmax-dm-a');
  var selB = document.getElementById('vmax-dm-b');
  var volA = document.getElementById('vmax-dm-a-vol');
  var volB = document.getElementById('vmax-dm-b-vol');
  var toggleBtn = document.getElementById('vmax-dm-toggle');
  var tracks = {};
  var playing = false;

  function saveState(){
    fetch('/api/music/state', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({
      uid: uid,
      deck_a: {track: selA.value, volume: parseFloat(volA.value)},
      deck_b: {track: selB.value, volume: parseFloat(volB.value)},
      playing: playing,
    })});
  }

  fetch('/api/music/library').then(function(r){return r.json();}).then(function(d){
    tracks = d.tracks;
    var opts = Object.keys(tracks).map(function(k){
      return '<option value="' + k + '">' + tracks[k].title + '</option>';
    }).join('');
    selA.innerHTML = opts; selB.innerHTML = opts;
    return fetch('/api/music/state?uid=' + encodeURIComponent(uid));
  }).then(function(r){return r.json();}).then(function(d){
    var st = d.state;
    if (st.deck_a && st.deck_a.track){ selA.value = st.deck_a.track; volA.value = st.deck_a.volume; }
    if (st.deck_b && st.deck_b.track){ selB.value = st.deck_b.track; volB.value = st.deck_b.volume; }
    applyTrack(audioA, selA.value); applyTrack(audioB, selB.value);
    audioA.volume = parseFloat(volA.value); audioB.volume = parseFloat(volB.value);
    if (st.playing){ playBoth(); }
  });

  function applyTrack(el, key){ if (key && tracks[key]) el.src = tracks[key].url; }

  function playBoth(){
    audioA.play().catch(function(){}); audioB.play().catch(function(){});
    playing = true; toggleBtn.innerText = '⏸';
  }
  function pauseBoth(){
    audioA.pause(); audioB.pause();
    playing = false; toggleBtn.innerText = '▶';
  }

  toggleBtn.addEventListener('click', function(){
    if (playing) pauseBoth(); else playBoth();
    saveState();
  });
  selA.addEventListener('change', function(){ applyTrack(audioA, selA.value); if (playing) audioA.play(); saveState(); });
  selB.addEventListener('change', function(){ applyTrack(audioB, selB.value); if (playing) audioB.play(); saveState(); });
  volA.addEventListener('input', function(){ audioA.volume = parseFloat(volA.value); saveState(); });
  volB.addEventListener('input', function(){ audioB.volume = parseFloat(volB.value); saveState(); });
})();
"""


