# ==========================================
# [ 6v5b. Music Share — แชร์เพลงที่ชอบให้เพื่อนฟัง ]
# ผู้เล่นเลือกเพลงจาก MUSIC_LIBRARY (6v5 ด้านบน) แล้วส่งให้เพื่อนคนใดคนหนึ่ง (ต้องเป็นเพื่อนกันแล้ว
# ผ่าน FRIENDS_LIST/are_friends [6zz5f] เหมือนกฎ DM ของแชท กันสแปมเพลงใส่คนแปลกหน้า) ฝั่งรับจะได้
# ทั้ง (1) push แจ้งเตือนเรียลไทม์ผ่าน Socket.IO event 'music_share_received' พร้อมปุ่ม "เปิดฟัง" ที่
# ตั้งเพลงเข้า Dual Music Player (6v5) ให้เลย และ (2) รายการที่เก็บไว้ใน inbox กันพลาดตอนออฟไลน์
# ดึงย้อนหลังได้ทาง REST — พร้อมข้อความแจ้งเตือนสีแดงแบบ "ระบบ" โผล่ในแชท DM ของผู้รับด้วย
# (ใช้ send_system_chat_message() จาก [6zz5f0b] ด้านล่างในไฟล์ — อ้างอิงไปข้างหน้าได้เพราะ Python
# ค้นชื่อฟังก์ชันตอนเรียกจริง ไม่ใช่ตอน import จึงไม่มีปัญหาแม้นิยามอยู่คนละจุดในไฟล์)
# ==========================================
MUSIC_SHARE_INBOX = {}  # to_uid -> [ {id, from_uid, from_name, track_key, title, url, message, ts, opened} ]
_music_share_seq = 0


def share_music_track(from_uid: str, from_name: str, to_uid: str, track_key: str,
                       message: str = "") -> dict:
    """แชร์เพลง track_key (ต้องมีอยู่จริงใน MUSIC_LIBRARY) จาก from_uid ไปให้ to_uid — ต้องเป็น
    เพื่อนกันก่อน (are_friends [6zz5f]) ไม่งั้น raise ValueError คืน dict ของ share ที่สร้างขึ้น"""
    global _music_share_seq
    track = MUSIC_LIBRARY.get(track_key)
    if not track:
        raise ValueError(f"ไม่พบเพลง '{track_key}' ใน MUSIC_LIBRARY")
    if not are_friends(from_uid, to_uid):
        raise ValueError("แชร์เพลงได้เฉพาะเพื่อนกันเท่านั้น")
    _music_share_seq += 1
    share = {
        "id": f"msh_{_music_share_seq}_{int(time.time())}",
        "from_uid": from_uid, "from_name": from_name or from_uid,
        "to_uid": to_uid, "track_key": track_key, "title": track["title"],
        "url": track["url"], "message": (message or "")[:200],
        "ts": time.time(), "opened": False,
    }
    MUSIC_SHARE_INBOX.setdefault(to_uid, []).append(share)
    return share


def _notify_music_share(share: dict):
    """ยิง Socket.IO แบบเรียลไทม์ + โพสต์ข้อความสีแดง 'ระบบ' เข้า DM ของผู้รับ — ใช้ร่วมกันทั้งทาง
    REST (api_music_share) และ Socket.IO (on_music_share_send) ด้านล่าง กันโค้ดซ้ำ"""
    sio.emit('music_share_received', share, room=share["to_uid"])
    note = f"🎵 {share['from_name']} แชร์เพลง \"{share['title']}\" ให้คุณ"
    if share["message"]:
        note += f" — “{share['message']}”"
    send_system_chat_message(note, to_uid=share["to_uid"], game_id="music_share")


@app.route('/api/music/share', methods=['POST'])
@require_auth_toggleable
def api_music_share():
    """body: {from_uid, from_name, to_uid, track_key, message?} -> แชร์เพลงให้เพื่อน + แจ้งเตือน
    เรียลไทม์ (ดู _notify_music_share ด้านบน) คืน {"st":"ok","share":{...}}"""
    body = request.json or {}
    from_uid = body.get("from_uid", "")
    to_uid = body.get("to_uid", "")
    track_key = body.get("track_key", "")
    if not from_uid or not to_uid or not track_key:
        return jsonify({"st": "error", "msg": "ต้องระบุ from_uid, to_uid, track_key"}), 400
    try:
        share = share_music_track(from_uid, body.get("from_name", from_uid), to_uid,
                                   track_key, body.get("message", ""))
    except ValueError as e:
        return jsonify({"st": "error", "msg": str(e)}), 400
    _notify_music_share(share)
    return jsonify({"st": "ok", "share": share})


@app.route('/api/music/share/inbox', methods=['GET'])
def api_music_share_inbox():
    """GET ?uid=xxx -> รายการเพลงที่เพื่อนแชร์มาให้ทั้งหมด (ล่าสุดอยู่ท้ายลิสต์)"""
    uid = request.args.get('uid', '')
    return jsonify({"st": "ok", "uid": uid, "shares": MUSIC_SHARE_INBOX.get(uid, [])})


@app.route('/api/music/share/open', methods=['POST'])
@require_auth_toggleable
def api_music_share_open():
    """body: {uid, share_id} -> ผู้รับกด "เปิดฟัง" แล้ว mark ว่าเปิดแล้ว (เลิกโชว์ badge แจ้งเตือน)
    คืน track เดิมกลับไปให้ client เอาไปตั้งเข้า deck ของ Dual Music Player (6v5) ต่อเอง"""
    body = request.json or {}
    uid, share_id = body.get("uid", ""), body.get("share_id", "")
    for share in MUSIC_SHARE_INBOX.get(uid, []):
        if share["id"] == share_id:
            share["opened"] = True
            return jsonify({"st": "ok", "share": share})
    return jsonify({"st": "error", "msg": "ไม่พบรายการแชร์นี้"}), 404


@sio.on('music_share_send')
def on_music_share_send(data):
    """ทางเลือก Socket.IO ให้ผลลัพธ์เดียวกับ /api/music/share (ใช้ตอนต่อ Socket.IO อยู่แล้วไม่อยาก
    ยิง REST แยก) data: {from_uid, from_name, to_uid, track_key, message?}"""
    data = data or {}
    from_uid, to_uid, track_key = data.get("from_uid", ""), data.get("to_uid", ""), data.get("track_key", "")
    if not from_uid or not to_uid or not track_key:
        return
    try:
        share = share_music_track(from_uid, data.get("from_name", from_uid), to_uid,
                                   track_key, data.get("message", ""))
    except ValueError:
        return
    _notify_music_share(share)


MUSIC_SHARE_WIDGET_JS = """
(function(){
  var uid = (window.VMAX_DUAL_MUSIC_CONFIG && window.VMAX_DUAL_MUSIC_CONFIG.uid) || 'guest';
  var box = document.getElementById('vmax-dual-music');
  if (!box) return;

  var shareRow = document.createElement('div');
  shareRow.style.cssText = 'margin-top:8px;padding-top:8px;border-top:1px solid #ffffff22;';
  shareRow.innerHTML =
    '<input id="vmax-ms-to" placeholder="uid เพื่อน" style="width:78px;font-size:11px;">' +
    '<button id="vmax-ms-send" style="font-size:11px;">🎵 แชร์เพลงนี้</button>' +
    '<div id="vmax-ms-toast" style="margin-top:6px;"></div>';
  box.appendChild(shareRow);

  var toUidInput = document.getElementById('vmax-ms-to');
  var sendBtn = document.getElementById('vmax-ms-send');
  var toast = document.getElementById('vmax-ms-toast');
  var selA = document.getElementById('vmax-dm-a');

  sendBtn.addEventListener('click', function(){
    var toUid = toUidInput.value.trim();
    var trackKey = selA && selA.value;
    if (!toUid || !trackKey) return;
    fetch('/api/music/share', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({
      from_uid: uid, from_name: uid, to_uid: toUid, track_key: trackKey,
    })}).then(function(r){return r.json();}).then(function(d){
      toast.textContent = (d.st === 'ok') ? '✅ แชร์แล้ว' : ('❌ ' + (d.msg || 'แชร์ไม่สำเร็จ'));
      setTimeout(function(){ toast.textContent = ''; }, 3000);
    });
  });

  function showIncoming(share){
    var line = document.createElement('div');
    line.style.cssText = 'background:#2a2a35;border-radius:8px;padding:6px 8px;margin-top:4px;';
    line.innerHTML = '🎵 <b>' + share.from_name + '</b> แชร์: ' + share.title +
      ' <button style="font-size:11px;">เปิดฟัง</button>';
    line.querySelector('button').addEventListener('click', function(){
      fetch('/api/music/share/open', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({
        uid: uid, share_id: share.id,
      })});
      fetch('/api/music/state', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({
        uid: uid, deck_a: {track: share.track_key, volume: 0.8}, playing: true,
      })}).then(function(){ location.reload(); });
    });
    toast.appendChild(line);
  }

  try {
    var sock = io();
    sock.on('music_share_received', showIncoming);
  } catch (e) {}

  fetch('/api/music/share/inbox?uid=' + encodeURIComponent(uid)).then(function(r){return r.json();})
    .then(function(d){ (d.shares || []).filter(function(s){ return !s.opened; }).forEach(showIncoming); });
})();
"""


