# ==========================================
# [ 6v6. Character Assistant Power Mode — โหมดประหยัดพลังงานแบบมีตัวการ์ตูนผู้ช่วย ]
# โหมดประหยัดพลังงานอีกแบบ เลือกใช้คู่กับ power_saver_widget (6v) หรือ
# battery_critical_simulator (6v3) ก็ได้ — แทนที่จะจอดำ/หรี่จอเฉยๆ ตัวนี้โชว์ "ตัวการ์ตูน
# มาสคอต" ลอยอยู่มุมจอตอนเข้าโหมดประหยัดพลังงาน กดที่ตัวการ์ตูนแล้วจะเด้งกล่องถามว่า
# "มีอะไรให้ช่วยไหม" พร้อมปุ่มลัด + ช่องพิมพ์คำถามที่ต่อเข้ากับ AI chat (6r) ตัวเดียวกับ
# ที่ใช้ในเกม เพื่อให้ตอบคำถามได้จริง ไม่ใช่แค่ mock ข้อความลอยๆ
# ==========================================
CHARACTER_ASSISTANT_PREFS = {}  # uid -> {mascot_key, enabled}
CHARACTER_ASSISTANT_MASCOTS = {
    "robot": {"label": "หุ่นยนต์ผู้ช่วย", "emoji": "🤖"},
    "cat":   {"label": "แมวผู้ช่วย", "emoji": "🐱"},
    "ghost": {"label": "ผีน้อยผู้ช่วย", "emoji": "👻"},
    "star":  {"label": "ดาวผู้ช่วย", "emoji": "⭐"},
}
CHARACTER_ASSISTANT_QUICK_ACTIONS = [
    {"key": "why_dark", "label": "ทำไมจอมืด/หรี่ลง?"},
    {"key": "exit_power_mode", "label": "ออกจากโหมดประหยัดพลังงาน"},
    {"key": "adjust_settings", "label": "ปรับตั้งค่าโหมดประหยัดพลังงาน"},
]


@app.route('/api/character-assistant/prefs', methods=['GET', 'POST'])
@require_auth_toggleable
def api_character_assistant_prefs():
    """GET ?uid=xxx -> มาสคอตที่เลือกไว้ (default: robot) พร้อมรายชื่อมาสคอต+ปุ่มลัดทั้งหมด
    POST body: {uid, mascot_key, enabled}"""
    if request.method == 'POST':
        body = request.json or {}
        uid = body.get('uid', '')
        if not uid:
            return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
        mascot_key = body.get('mascot_key', 'robot')
        if mascot_key not in CHARACTER_ASSISTANT_MASCOTS:
            return jsonify({"st": "error", "msg": "ไม่พบมาสคอตนี้"}), 400
        CHARACTER_ASSISTANT_PREFS[uid] = {"mascot_key": mascot_key, "enabled": body.get('enabled', True)}
        return jsonify({"st": "ok", "uid": uid, "prefs": CHARACTER_ASSISTANT_PREFS[uid]})
    uid = request.args.get('uid', '')
    prefs = CHARACTER_ASSISTANT_PREFS.get(uid, {"mascot_key": "robot", "enabled": True})
    return jsonify({"st": "ok", "uid": uid, "prefs": prefs, "mascots": CHARACTER_ASSISTANT_MASCOTS,
                    "quick_actions": CHARACTER_ASSISTANT_QUICK_ACTIONS})


CHARACTER_ASSISTANT_WIDGET_HTML = """
<div id="vmax-char-assist-bubble" style="display:none;position:fixed;bottom:20px;right:20px;
  z-index:99997;width:56px;height:56px;border-radius:50%;background:#2b2b3a;
  align-items:center;justify-content:center;font-size:28px;cursor:pointer;
  box-shadow:0 2px 10px rgba(0,0,0,.4);">🤖</div>
<div id="vmax-char-assist-panel" style="display:none;position:fixed;bottom:88px;right:20px;
  z-index:99997;width:260px;background:rgba(25,25,35,.97);border-radius:14px;padding:14px;
  color:#fff;font-family:sans-serif;font-size:13px;">
  <div style="margin-bottom:8px;">มีอะไรให้ช่วยไหม?</div>
  <div id="vmax-ca-quick"></div>
  <div style="display:flex;gap:6px;margin-top:8px;">
    <input id="vmax-ca-input" placeholder="พิมพ์คำถาม..." style="flex:1;border-radius:8px;border:none;
      padding:6px 8px;background:#111;color:#fff;">
    <button id="vmax-ca-send" style="background:#4a4af0;border:none;border-radius:8px;color:#fff;
      padding:6px 10px;cursor:pointer;">ส่ง</button>
  </div>
  <div id="vmax-ca-reply" style="margin-top:8px;opacity:.85;max-height:120px;overflow:auto;"></div>
</div>
"""

CHARACTER_ASSISTANT_WIDGET_JS = """
(function(){
  var uid = (window.VMAX_CHAR_ASSIST_CONFIG && window.VMAX_CHAR_ASSIST_CONFIG.uid) || 'guest';
  var bubble = document.getElementById('vmax-char-assist-bubble');
  var panel = document.getElementById('vmax-char-assist-panel');
  var quickBox = document.getElementById('vmax-ca-quick');
  var input = document.getElementById('vmax-ca-input');
  var sendBtn = document.getElementById('vmax-ca-send');
  var replyBox = document.getElementById('vmax-ca-reply');
  var sessionId = 'char-assist-' + uid;

  fetch('/api/character-assistant/prefs?uid=' + encodeURIComponent(uid))
    .then(function(r){return r.json();}).then(function(d){
      if (!d.prefs.enabled) return;
      bubble.innerText = d.mascots[d.prefs.mascot_key].emoji;
      quickBox.innerHTML = d.quick_actions.map(function(a){
        return '<button class="vmax-ca-qa" data-label="' + a.label +
          '" style="display:block;width:100%;text-align:left;background:#333;border:none;' +
          'color:#fff;border-radius:8px;padding:6px 8px;margin-bottom:4px;cursor:pointer;">' +
          a.label + '</button>';
      }).join('');
      Array.prototype.forEach.call(quickBox.querySelectorAll('.vmax-ca-qa'), function(btn){
        btn.addEventListener('click', function(){ ask(btn.getAttribute('data-label')); });
      });
    });

  function showIfPowerModeActive(){
    // ผูกกับสถานะ battery-critical-simulator (6v3) เป็นค่าเริ่มต้น — เกมที่ฝัง widget
    // นี้แล้วใช้ power mode ตัวอื่น (เช่น power_saver_widget แบบ idle timeout) ปรับ
    // endpoint ที่เช็คตรงนี้ให้ตรงกับของตัวเองได้
    fetch('/api/battery-simulator/status?uid=' + encodeURIComponent(uid))
      .then(function(r){return r.json();}).then(function(d){
        bubble.style.display = d.active ? 'flex' : 'none';
        if (!d.active) panel.style.display = 'none';
      });
  }
  showIfPowerModeActive();
  setInterval(showIfPowerModeActive, 8000);

  bubble.addEventListener('click', function(){
    panel.style.display = (panel.style.display === 'none' || !panel.style.display) ? 'block' : 'none';
  });

  function ask(message){
    replyBox.innerText = '...';
    fetch('/api/ai-chat/send', {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({session_id: sessionId, message: message})})
      .then(function(r){return r.json();}).then(function(d){
        replyBox.innerText = d.st === 'ok' ? d.reply : ('❌ ' + d.msg);
      });
  }
  sendBtn.addEventListener('click', function(){
    if (input.value.trim()){ ask(input.value.trim()); input.value = ''; }
  });
  input.addEventListener('keydown', function(e){
    if (e.key === 'Enter') sendBtn.click();
  });
})();
"""


@app.route('/widgets/character-assistant')
def widget_character_assistant():
    """ตัวการ์ตูนผู้ช่วยลอยมุมจอ โผล่ขึ้นมาตอนเข้าโหมดประหยัดพลังงาน (เช็คสถานะจาก
    battery-critical-simulator เป็นค่าเริ่มต้น — ปรับ showIfPowerModeActive() ในโค้ด
    ให้ผูกกับ power mode ของเกมตัวเองได้ถ้าใช้ตัวอื่น) กดแล้วเด้งกล่อง 'มีอะไรให้ช่วย
    ไหม' พร้อมปุ่มลัด + พิมพ์ถามได้จริงผ่าน AI chat (6r) ฝังแบบเดียวกับ widget อื่นๆ:
        window.VMAX_CHAR_ASSIST_CONFIG = { uid: 'xxx' };
        fetch('/widgets/character-assistant').then(r => r.text())
            .then(html => document.body.insertAdjacentHTML('beforeend', html));"""
    return CHARACTER_ASSISTANT_WIDGET_HTML + "<script>" + CHARACTER_ASSISTANT_WIDGET_JS + "</script>"


