# ============================================================================
# [ 6j5. GAME STARTUP HOLOGRAM + IMMEDIATE DOWNLOAD POPUP ]
# ----------------------------------------------------------------------------
# จุดแทรกตั้งใจวาง "ถัดจาก Resource-quality launcher" และก่อน route/module
# ชุดถัดไป เพื่อใช้ LAUNCHER_CATALOG / DOWNLOAD_QUEUE / launcher_install()
# ของเดิมโดยตรง ไม่สร้างระบบดาวน์โหลดชุดใหม่และไม่แตะ UI_TEMPLATE หลัก.
# เปิดเกมผ่าน /game-launch/<game_id> จะเห็นหน้า boot แบบวงแหวนข้อมูลตามภาพ
# แล้วเปิด download popup อัตโนมัติ; ถ้ายังไม่ติดตั้งจะ queue แพ็ก HD ให้ทันที.
# เมื่อดาวน์โหลดเสร็จ ปุ่ม ENTER GAME จะพาไป entry route ของเกมเดิม.
# ============================================================================
VMAX_GAME_STARTUP_DEFAULT_QUALITY = "HD"
VMAX_GAME_STARTUP_ENTRY_ROUTES = {
    "vmax": "/",
}
VMAX_GAME_STARTUP_ENTRY_ROUTES.setdefault(NEKO_MOONLIT_GAME_ID, NEKO_MOONLIT_ENTRY_ROUTE)


def _vmax_startup_download_state(game_id: str, quality: str = "HD") -> dict:
    """คืนสถานะติดตั้ง/ดาวน์โหลดจากระบบ launcher เดิมแบบ read-only."""
    gid = str(game_id or "").strip()
    q = str(quality or VMAX_GAME_STARTUP_DEFAULT_QUALITY).upper()
    g = LAUNCHER_CATALOG.get(gid)
    if not g:
        return {"ok": False, "reason": "Game not in catalog", "game_id": gid, "quality": q}
    with DOWNLOAD_LOCK:
        active = next((dict(d) for d in DOWNLOAD_QUEUE
                       if d.get("game_id") == gid and d.get("resource_quality", "HD") == q), None)
    return {
        "ok": True,
        "game_id": gid,
        "quality": q,
        "installed": bool(g.get("installed")),
        "installed_quality": g.get("installed_quality"),
        "download": active,
        "game": {
            "name": g.get("name", gid),
            "version": g.get("version", ""),
            "genre": g.get("genre", "game"),
            "resources": g.get("resources", {}),
        },
    }


def _vmax_startup_entry_for(game_id: str) -> str:
    gid = str(game_id or "").strip()
    if gid in VMAX_GAME_STARTUP_ENTRY_ROUTES:
        return VMAX_GAME_STARTUP_ENTRY_ROUTES[gid]
    if gid in GAME_SITES:
        return f"/site/{gid}"
    launch_info = globals().get("LAUNCHER_GAME_LAUNCH_INFO", {}).get(gid, {})
    return str(launch_info.get("entry_route") or "/")


@app.route('/api/launcher/startup/<game_id>')
def api_launcher_startup(game_id):
    """ข้อมูล boot screen + auto-queue แพ็กที่เลือกครั้งแรก."""
    quality = str(request.args.get("quality", VMAX_GAME_STARTUP_DEFAULT_QUALITY)).upper()
    if quality not in ("SD", "HD", "UHD"):
        return jsonify({"ok": False, "reason": "invalid quality"}), 400
    state = _vmax_startup_download_state(game_id, quality)
    if not state.get("ok"):
        return jsonify(state), 404

    auto_download = request.args.get("auto_download", "1") != "0"
    if auto_download and not state["installed"] and not state["download"]:
        ok, msg = launcher_install(game_id, quality)
        state["auto_queued"] = bool(ok)
        state["queue_message"] = msg
        state = _vmax_startup_download_state(game_id, quality)
    else:
        state["auto_queued"] = False

    state["entry_route"] = _vmax_startup_entry_for(game_id)
    return jsonify(state)


@app.route('/game-launch/<game_id>')
def vmax_game_launch_startup(game_id):
    """Game entry gate: boot animation -> immediate download popup -> enter game."""
    if game_id not in LAUNCHER_CATALOG:
        return jsonify({"ok": False, "reason": "Game not in catalog"}), 404
    return VMAX_GAME_STARTUP_HOLOGRAM_HTML.replace(
        "__VMAX_GAME_ID__", str(game_id).replace("'", "")
    )


