# ==========================================
# [ 6z. Secure Personal/Work Document Vault (encrypted, separate mini-site at /vault) ]
# หน้าเว็บแยกต่างหากสำหรับเก็บ "เอกสารสำคัญ" (เอกสารงาน/เอกสารส่วนตัว ฯลฯ) — รันอยู่ใน
# process/พอร์ตเดียวกับเกมหลัก แต่มี URL, หน้า UI, และ routes เป็นของตัวเองแยกขาด ไม่ปนกับ
# ระบบอื่นในไฟล์นี้เลย (ไม่แตะ P["credits"]/WALLET หรือระบบ auth เดิม — ใช้ passphrase ของ
# ตัวเองต่างหาก)
#
# หลักการเข้ารหัส (ออกแบบให้ "แน่นหนา" แบบ zero-knowledge ต่อ passphrase):
#   - ผู้ใช้ตั้ง "รหัสผ่านนิรภัย" (vault passphrase) แยกจากรหัสผ่านบัญชีเกม
#   - เซิร์ฟเวอร์ไม่เก็บ passphrase และไม่เก็บกุญแจถอดรหัสไว้ถาวรที่ไหนเลย
#   - กุญแจเข้ารหัสจริง (Fernet = AES128-CBC + HMAC-SHA256 ต่อไฟล์) ถูกคำนวณขึ้นใหม่ทุกครั้ง
#     ตอนปลดล็อก ด้วย PBKDF2-HMAC-SHA256 390,000 รอบ จาก passphrase + salt สุ่ม 16 ไบต์ที่
#     สร้างครั้งเดียวตอน setup แล้วเก็บไว้แค่ใน RAM ของเซิร์ฟเวอร์ผ่าน session token ชั่วคราว
#     (หมดอายุอัตโนมัติถ้าไม่ได้ใช้งาน 15 นาที) ไม่เขียนกุญแจลงดิสก์เด็ดขาด
#   - ไฟล์ทุกไฟล์ที่อัปโหลด "และ" ชื่อไฟล์เดิม ถูกเข้ารหัสก่อนเขียนลงดิสก์เสมอ — ชื่อไฟล์บนดิสก์
#     เป็น UUID สุ่ม ไม่มีทางรู้ได้จากการมองไฟล์ในดิสก์ว่าเป็นเอกสารอะไร
#   - ตรวจ passphrase ตอนปลดล็อกด้วย "verifier" ที่เข้ารหัสไว้ (ไม่ใช่การเทียบ passphrase ตรงๆ)
#   - มีฟังก์ชันเปลี่ยน passphrase ที่ re-encrypt เอกสารทั้งหมดด้วยกุญแจ+salt ใหม่ทุกครั้ง
#   - ข้อควรรู้: ถ้าลืม passphrase = กู้เอกสารคืนไม่ได้ ตั้งใจให้เป็นแบบนี้เพื่อความปลอดภัยจริง
#     (เซิร์ฟเวอร์เองก็ไม่มีทาง backdoor เข้าไปถอดรหัสให้ได้)
# ==========================================
VAULT_DIR = "secure_vault_storage"
os.makedirs(VAULT_DIR, exist_ok=True)
VAULT_USERS_FILE = os.path.join(VAULT_DIR, "_vault_users.json")
VAULT_PBKDF2_ITERATIONS = 390_000
VAULT_SESSION_TTL_SEC = 15 * 60          # ล็อกอัตโนมัติหลังไม่ได้ใช้งาน 15 นาที
VAULT_VERIFY_TOKEN = b"vmax-vault-verify-v1"

VAULT_LOCK = threading.Lock()            # กันไฟล์ users/index ชนกันตอนเขียนพร้อมกัน
VAULT_SESSIONS = {}                      # token -> {"uid", "key" (Fernet key bytes), "expires_at"}


def _vault_load_users() -> dict:
    if not os.path.exists(VAULT_USERS_FILE):
        return {}
    try:
        with open(VAULT_USERS_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def _vault_save_users(data: dict):
    with open(VAULT_USERS_FILE, "w", encoding="utf-8") as f:
        json.dump(data, f)


def _vault_user_dir(uid: str) -> str:
    d = os.path.join(VAULT_DIR, secure_filename(uid) or "anon")
    os.makedirs(d, exist_ok=True)
    return d


def _vault_index_path(uid: str) -> str:
    return os.path.join(_vault_user_dir(uid), "_index.json")


def _vault_load_index(uid: str) -> list:
    p = _vault_index_path(uid)
    if not os.path.exists(p):
        return []
    try:
        with open(p, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return []


def _vault_save_index(uid: str, items: list):
    with open(_vault_index_path(uid), "w", encoding="utf-8") as f:
        json.dump(items, f)


# Vault KDF versions. "pbkdf2" is the original scheme (kept forever, since
# re-keying old vault ciphertext without a full re-encrypt pass would corrupt
# it). "argon2id" is used for every *new* vault setup from here on -- same
# memory-hardness rationale as the login hasher above.
VAULT_ARGON2_TIME_COST   = 3
VAULT_ARGON2_MEMORY_COST = 131072   # 128 MiB -- vault unlock is rarer than login, can afford it
VAULT_ARGON2_PARALLELISM = 2

def _vault_derive_key(passphrase: str, salt: bytes, kdf_algo: str = "pbkdf2") -> bytes:
    """-> คีย์ดิบ 32 ไบต์ เข้ารหัส base64 ตามที่ Fernet ต้องการ
    kdf_algo="pbkdf2"   : PBKDF2-HMAC-SHA256, 390,000 รอบ (ของเดิม, ใช้กับ vault เก่า, ไม่ผสม pepper
                          เพราะ vault เก่า derive ไว้ก่อน pepper จะมีอยู่ -- ผสมตอนนี้จะปลดล็อกไม่ได้)
    kdf_algo="argon2id" : Argon2id memory-hard KDF ผสม server-side pepper (ของใหม่, ใช้กับ vault
                          ที่ setup ใหม่หรืออัปเกรดผ่านการเปลี่ยน passphrase)"""
    if kdf_algo == "argon2id":
        raw = hash_secret_raw(
            secret=_apply_pepper(passphrase), salt=salt,
            time_cost=VAULT_ARGON2_TIME_COST, memory_cost=VAULT_ARGON2_MEMORY_COST,
            parallelism=VAULT_ARGON2_PARALLELISM, hash_len=32, type=_Argon2Type.ID,
        )
    else:
        kdf = PBKDF2HMAC(algorithm=hashes.SHA256(), length=32, salt=salt, iterations=VAULT_PBKDF2_ITERATIONS)
        raw = kdf.derive(passphrase.encode("utf-8"))
    return base64.urlsafe_b64encode(raw)


def _vault_new_session(uid: str, key: bytes) -> str:
    token = uuid.uuid4().hex
    VAULT_SESSIONS[token] = {"uid": uid, "key": key, "expires_at": time.time() + VAULT_SESSION_TTL_SEC}
    return token


def _vault_resolve_session(token: str):
    """คืน (uid, Fernet) ถ้า token ยังไม่หมดอายุ — sliding expiry (ต่ออายุอัตโนมัติเมื่อใช้งาน)
    ถ้าหมดอายุ/ไม่พบ -> ลบทิ้งแล้วคืน (None, None)"""
    sess = VAULT_SESSIONS.get(token)
    if not sess or sess["expires_at"] < time.time():
        VAULT_SESSIONS.pop(token, None)
        return None, None
    sess["expires_at"] = time.time() + VAULT_SESSION_TTL_SEC
    return sess["uid"], Fernet(sess["key"])


@app.route('/api/vault/setup', methods=['POST'])
@require_auth
def api_vault_setup():
    """ตั้งค่า vault ครั้งแรกของ uid นี้: สุ่ม salt ใหม่ + เก็บ 'verifier' ที่เข้ารหัสไว้ (ไม่ใช่
    passphrase ตรงๆ) ไว้ตรวจตอน unlock — ไม่มีการเก็บ passphrase หรือกุญแจถอดรหัสไว้ถาวรเลย"""
    body = request.json or {}
    uid = (resolve_uid(body) or '').strip()
    passphrase = body.get('passphrase') or ''
    if not uid or not passphrase:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid และ passphrase"}), 400
    if len(passphrase) < 8:
        return jsonify({"st": "error", "msg": "passphrase ควรยาวอย่างน้อย 8 ตัวอักษรเพื่อความปลอดภัย"}), 400
    with VAULT_LOCK:
        users = _vault_load_users()
        if uid in users:
            return jsonify({"st": "error", "msg": "uid นี้ตั้งค่า vault ไปแล้ว ใช้ /api/vault/unlock แทน"}), 400
        salt = os.urandom(16)
        key = _vault_derive_key(passphrase, salt, kdf_algo="argon2id")
        verifier = Fernet(key).encrypt(VAULT_VERIFY_TOKEN).decode()
        users[uid] = {"salt": salt.hex(), "verifier": verifier, "created_at": time.time(),
                      "kdf_algo": "argon2id"}
        _vault_save_users(users)
    audit_log("vault_setup", uid=uid)
    return jsonify({"st": "ok", "msg": "ตั้งค่า vault สำเร็จ — ปลดล็อกด้วย /api/vault/unlock ได้เลย"})


@app.route('/api/vault/unlock', methods=['POST'])
@require_auth
def api_vault_unlock():
    """ตรวจ passphrase ผ่าน verifier ที่เข้ารหัสไว้ แล้วสร้าง session token ชั่วคราว — กุญแจถอดรหัส
    จริงอยู่ใน RAM ของเซิร์ฟเวอร์เท่านั้น หมดอายุอัตโนมัติถ้าไม่ได้ใช้งาน"""
    body = request.json or {}
    uid = (resolve_uid(body) or '').strip()
    passphrase = body.get('passphrase') or ''
    users = _vault_load_users()
    user = users.get(uid)
    if not user:
        audit_log("vault_unlock_fail_unknown_uid", uid=uid)
        return jsonify({"st": "error", "msg": "ยังไม่เคยตั้งค่า vault ของ uid นี้"}), 404
    kdf_algo = user.get("kdf_algo", "pbkdf2")   # vaults set up before this upgrade have no key -> old scheme
    key = _vault_derive_key(passphrase, bytes.fromhex(user["salt"]), kdf_algo=kdf_algo)
    try:
        if Fernet(key).decrypt(user["verifier"].encode()) != VAULT_VERIFY_TOKEN:
            raise InvalidToken()
    except InvalidToken:
        audit_log("vault_unlock_fail_passphrase", uid=uid)
        return jsonify({"st": "error", "msg": "passphrase ไม่ถูกต้อง"}), 401
    token = _vault_new_session(uid, key)
    audit_log("vault_unlock_ok", uid=uid)
    return jsonify({"st": "ok", "token": token, "expires_in_sec": VAULT_SESSION_TTL_SEC})


@app.route('/api/vault/lock', methods=['POST'])
@require_auth
def api_vault_lock():
    """ล็อกทันที (ลบ session/กุญแจออกจาก RAM) ไม่ต้องรอหมดอายุเอง"""
    token = (request.json or {}).get('token', '')
    VAULT_SESSIONS.pop(token, None)
    return jsonify({"st": "ok", "msg": "ล็อก vault แล้ว"})


@app.route('/api/vault/upload', methods=['POST'])
@require_auth
def api_vault_upload():
    """อัปโหลดเอกสาร — เข้ารหัสทั้งเนื้อไฟล์และชื่อไฟล์เดิมด้วยกุญแจของ session นี้ก่อนเขียนลงดิสก์
    form-data: token, file"""
    token = request.form.get('token', '')
    uid, fernet = _vault_resolve_session(token)
    if not fernet:
        return jsonify({"st": "error", "msg": "session หมดอายุหรือไม่ถูกต้อง — ปลดล็อกใหม่ก่อน"}), 401
    f = request.files.get('file')
    if not f or not f.filename:
        return jsonify({"st": "error", "msg": "ไม่พบไฟล์ที่อัปโหลด"}), 400
    raw = f.read()
    doc_id = uuid.uuid4().hex
    enc_bytes = fernet.encrypt(raw)
    with open(os.path.join(_vault_user_dir(uid), doc_id + ".enc"), "wb") as out:
        out.write(enc_bytes)
    enc_name = fernet.encrypt(f.filename.encode("utf-8")).decode()
    with VAULT_LOCK:
        items = _vault_load_index(uid)
        items.append({"id": doc_id, "enc_name": enc_name, "size": len(raw), "uploaded_at": time.time()})
        _vault_save_index(uid, items)
    return jsonify({"st": "ok", "id": doc_id, "size": len(raw)})


@app.route('/api/vault/list')
def api_vault_list():
    """รายการเอกสาร — ต้องมี session ที่ปลดล็อกแล้วเท่านั้นถึงจะถอดรหัส 'ชื่อไฟล์' มาโชว์ได้
    (ชื่อไฟล์ก็ถือเป็นข้อมูลอ่อนไหว จึงเข้ารหัสไว้เหมือนเนื้อไฟล์)"""
    # [SEC-AUDIT] รับ token ทาง header ได้ (X-VMAX-Vault-Token) — query string ไปติดใน log/history แนะนำใช้ header
    token = request.headers.get('X-VMAX-Vault-Token') or request.args.get('token', '')
    uid, fernet = _vault_resolve_session(token)
    if not fernet:
        return jsonify({"st": "error", "msg": "session หมดอายุหรือไม่ถูกต้อง — ปลดล็อกใหม่ก่อน"}), 401
    out = []
    for item in _vault_load_index(uid):
        try:
            name = fernet.decrypt(item["enc_name"].encode()).decode("utf-8")
        except InvalidToken:
            name = "(ถอดรหัสชื่อไฟล์ไม่ได้)"
        out.append({"id": item["id"], "name": name, "size": item["size"], "uploaded_at": item["uploaded_at"]})
    out.sort(key=lambda x: x["uploaded_at"], reverse=True)
    return jsonify({"st": "ok", "documents": out})


@app.route('/api/vault/download/<doc_id>')
def api_vault_download(doc_id):
    """ถอดรหัสเอกสารกลับเป็นไฟล์จริง เฉพาะตอนดาวน์โหลดเท่านั้น — ไม่มีเวอร์ชันถอดรหัสค้างบนดิสก์"""
    # [SEC-AUDIT] รับ token ทาง header ได้ (X-VMAX-Vault-Token) — query string ไปติดใน log/history แนะนำใช้ header
    token = request.headers.get('X-VMAX-Vault-Token') or request.args.get('token', '')
    uid, fernet = _vault_resolve_session(token)
    if not fernet:
        return jsonify({"st": "error", "msg": "session หมดอายุหรือไม่ถูกต้อง — ปลดล็อกใหม่ก่อน"}), 401
    items = _vault_load_index(uid)
    meta = next((i for i in items if i["id"] == doc_id), None)
    if not meta:
        return jsonify({"st": "error", "msg": "ไม่พบเอกสารนี้"}), 404
    enc_path = os.path.join(_vault_user_dir(uid), doc_id + ".enc")
    if not os.path.exists(enc_path):
        return jsonify({"st": "error", "msg": "ไฟล์เข้ารหัสหายจากดิสก์"}), 404
    with open(enc_path, "rb") as fin:
        enc_bytes = fin.read()
    try:
        raw = fernet.decrypt(enc_bytes)
        name = fernet.decrypt(meta["enc_name"].encode()).decode("utf-8")
    except InvalidToken:
        return jsonify({"st": "error", "msg": "ถอดรหัสไม่สำเร็จ — กุญแจไม่ตรงกับไฟล์นี้"}), 500
    from flask import Response
    resp = Response(raw, mimetype="application/octet-stream")
    resp.headers["Content-Disposition"] = f"attachment; filename*=UTF-8''{urlquote(name)}"
    return resp


@app.route('/api/vault/delete', methods=['POST'])
@require_auth
def api_vault_delete():
    """ลบเอกสาร (ทั้งไฟล์เข้ารหัสบนดิสก์และ index) — ต้องมี session ปลดล็อกแล้วเท่านั้น"""
    body = request.json or {}
    token = body.get('token', '')
    doc_id = body.get('id', '')
    uid, fernet = _vault_resolve_session(token)
    if not fernet:
        return jsonify({"st": "error", "msg": "session หมดอายุหรือไม่ถูกต้อง — ปลดล็อกใหม่ก่อน"}), 401
    with VAULT_LOCK:
        items = _vault_load_index(uid)
        remaining = [i for i in items if i["id"] != doc_id]
        if len(remaining) == len(items):
            return jsonify({"st": "error", "msg": "ไม่พบเอกสารนี้"}), 404
        _vault_save_index(uid, remaining)
    enc_path = os.path.join(_vault_user_dir(uid), doc_id + ".enc")
    if os.path.exists(enc_path):
        os.remove(enc_path)
    return jsonify({"st": "ok", "msg": "ลบเอกสารแล้ว"})


@app.route('/api/vault/change-passphrase', methods=['POST'])
@require_auth
def api_vault_change_passphrase():
    """เปลี่ยน passphrase: ต้องปลดล็อกด้วยของเก่าให้ผ่านก่อน แล้ว re-encrypt เอกสารทั้งหมดในคลัง
    ด้วยกุญแจ+salt ใหม่ทั้งชุด (ไม่ใช่แค่เปลี่ยน verifier) กันกรณี passphrase เก่าหลุดแล้วยังถอด
    ไฟล์เก่าได้"""
    body = request.json or {}
    uid = (resolve_uid(body) or '').strip()
    old_passphrase = body.get('old_passphrase') or ''
    new_passphrase = body.get('new_passphrase') or ''
    if len(new_passphrase) < 8:
        return jsonify({"st": "error", "msg": "passphrase ใหม่ควรยาวอย่างน้อย 8 ตัวอักษร"}), 400
    with VAULT_LOCK:
        users = _vault_load_users()
        user = users.get(uid)
        if not user:
            return jsonify({"st": "error", "msg": "ยังไม่เคยตั้งค่า vault ของ uid นี้"}), 404
        old_kdf_algo = user.get("kdf_algo", "pbkdf2")
        old_key = _vault_derive_key(old_passphrase, bytes.fromhex(user["salt"]), kdf_algo=old_kdf_algo)
        old_fernet = Fernet(old_key)
        try:
            if old_fernet.decrypt(user["verifier"].encode()) != VAULT_VERIFY_TOKEN:
                raise InvalidToken()
        except InvalidToken:
            audit_log("vault_passphrase_change_fail", uid=uid)
            return jsonify({"st": "error", "msg": "passphrase เดิมไม่ถูกต้อง"}), 401

        # เอกสารถูก re-encrypt ทั้งชุดอยู่แล้วในขั้นตอนนี้ -> ถือโอกาสอัปเกรด KDF เป็น Argon2id
        # ไปด้วยเลยสำหรับ vault ที่ยังเป็น PBKDF2 เดิมอยู่ (ไม่มีต้นทุนเพิ่มจากการอัปเกรดนี้)
        new_salt = os.urandom(16)
        new_key = _vault_derive_key(new_passphrase, new_salt, kdf_algo="argon2id")
        new_fernet = Fernet(new_key)

        items = _vault_load_index(uid)
        udir = _vault_user_dir(uid)
        for item in items:
            enc_path = os.path.join(udir, item["id"] + ".enc")
            if os.path.exists(enc_path):
                with open(enc_path, "rb") as fh:
                    raw = old_fernet.decrypt(fh.read())
                with open(enc_path, "wb") as fh:
                    fh.write(new_fernet.encrypt(raw))
            old_name = old_fernet.decrypt(item["enc_name"].encode())
            item["enc_name"] = new_fernet.encrypt(old_name).decode()
        _vault_save_index(uid, items)

        users[uid] = {"salt": new_salt.hex(), "verifier": new_fernet.encrypt(VAULT_VERIFY_TOKEN).decode(),
                      "created_at": user.get("created_at", time.time()), "kdf_algo": "argon2id"}
        _vault_save_users(users)

    # กุญแจเก่าใช้ไม่ได้อีกต่อไปแล้ว -> เคลียร์ session ค้างของ uid นี้ทั้งหมดทิ้ง
    for tok in [t for t, s in VAULT_SESSIONS.items() if s["uid"] == uid]:
        VAULT_SESSIONS.pop(tok, None)
    audit_log("vault_passphrase_changed", uid=uid)
    return jsonify({"st": "ok", "msg": "เปลี่ยน passphrase และเข้ารหัสเอกสารทั้งหมดใหม่สำเร็จ"})


VAULT_PAGE_HTML = """<!DOCTYPE html>
<html lang="th"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>🔐 Secure Vault — เอกสารสำคัญ</title>
<style>
  body{background:#0f0f16;color:#eee;font-family:sans-serif;max-width:560px;margin:0 auto;padding:20px;}
  h1{font-size:20px;} .card{background:#1b1b26;border-radius:14px;padding:16px;margin-bottom:14px;}
  input{width:100%;box-sizing:border-box;padding:9px;border-radius:8px;border:none;background:#111;color:#fff;margin-bottom:8px;}
  button{background:#4a4af0;border:none;border-radius:8px;color:#fff;padding:9px 14px;cursor:pointer;margin-right:6px;}
  button.danger{background:#c0392b;} button.ghost{background:#333;}
  .doc-row{display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid #2a2a38;}
  .muted{opacity:.6;font-size:12px;} #status{font-size:13px;margin-top:6px;min-height:16px;}
  .locked-badge{color:#e67e22;} .unlocked-badge{color:#2ecc71;}
</style></head>
<body>
<h1>🔐 Secure Vault — เอกสารสำคัญ (งาน/ส่วนตัว)</h1>
<div class="card" id="auth-card">
  <div><span id="lock-state" class="locked-badge">🔒 ล็อกอยู่</span></div>
  <input id="uid" placeholder="uid ของคุณ">
  <input id="pass" type="password" placeholder="vault passphrase (อย่างน้อย 8 ตัวอักษร)">
  <button onclick="vaultSetup()" class="ghost">ตั้งค่าครั้งแรก</button>
  <button onclick="vaultUnlock()">ปลดล็อก</button>
  <button onclick="vaultLock()" class="ghost">ล็อกทันที</button>
  <div id="status"></div>
</div>
<div class="card" id="doc-card" style="display:none;">
  <input type="file" id="fileInput">
  <button onclick="vaultUpload()">อัปโหลด (เข้ารหัสอัตโนมัติ)</button>
  <div id="doc-list" style="margin-top:12px;"></div>
</div>
<script>
let VAULT_TOKEN = null;   // เก็บใน JS memory เท่านั้น — รีเฟรชหน้าแล้วต้องปลดล็อกใหม่เสมอ
function setStatus(msg){ document.getElementById('status').innerText = msg; }
function fmtSize(n){ return n < 1024 ? n+' B' : n < 1048576 ? (n/1024).toFixed(1)+' KB' : (n/1048576).toFixed(1)+' MB'; }

async function vaultSetup(){
  const uid = document.getElementById('uid').value.trim();
  const pass = document.getElementById('pass').value;
  const r = await fetch('/api/vault/setup', {method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({uid, passphrase: pass})});
  const d = await r.json();
  setStatus(d.msg);
}
async function vaultUnlock(){
  const uid = document.getElementById('uid').value.trim();
  const pass = document.getElementById('pass').value;
  const r = await fetch('/api/vault/unlock', {method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({uid, passphrase: pass})});
  const d = await r.json();
  if (d.st === 'ok'){
    VAULT_TOKEN = d.token;
    document.getElementById('lock-state').innerText = '🔓 ปลดล็อกแล้ว';
    document.getElementById('lock-state').className = 'unlocked-badge';
    document.getElementById('doc-card').style.display = 'block';
    setStatus('ปลดล็อกสำเร็จ — session จะหมดอายุถ้าไม่ได้ใช้งาน 15 นาที');
    loadDocs();
  } else {
    setStatus('❌ ' + d.msg);
  }
}
async function vaultLock(){
  if (VAULT_TOKEN) await fetch('/api/vault/lock', {method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({token: VAULT_TOKEN})});
  VAULT_TOKEN = null;
  document.getElementById('lock-state').innerText = '🔒 ล็อกอยู่';
  document.getElementById('lock-state').className = 'locked-badge';
  document.getElementById('doc-card').style.display = 'none';
  setStatus('ล็อกแล้ว');
}
async function loadDocs(){
  if (!VAULT_TOKEN) return;
  const r = await fetch('/api/vault/list?token=' + encodeURIComponent(VAULT_TOKEN));
  const d = await r.json();
  if (d.st !== 'ok'){ setStatus('❌ ' + d.msg); return; }
  const box = document.getElementById('doc-list');
  box.innerHTML = d.documents.length ? '' : '<div class="muted">ยังไม่มีเอกสาร</div>';
  d.documents.forEach(doc => {
    const row = document.createElement('div');
    row.className = 'doc-row';
    row.innerHTML = `<div>📄 ${doc.name}<div class="muted">${fmtSize(doc.size)}</div></div>
      <div><button onclick="vaultDownload('${doc.id}')">ดาวน์โหลด</button>
      <button class="danger" onclick="vaultDelete('${doc.id}')">ลบ</button></div>`;
    box.appendChild(row);
  });
}
async function vaultUpload(){
  const fi = document.getElementById('fileInput');
  if (!fi.files.length || !VAULT_TOKEN) return;
  const fd = new FormData();
  fd.append('token', VAULT_TOKEN);
  fd.append('file', fi.files[0]);
  const r = await fetch('/api/vault/upload', {method:'POST', body: fd});
  const d = await r.json();
  setStatus(d.st === 'ok' ? 'อัปโหลด+เข้ารหัสสำเร็จ' : '❌ ' + d.msg);
  if (d.st === 'ok'){ fi.value=''; loadDocs(); }
}
function vaultDownload(id){
  if (!VAULT_TOKEN) return;
  window.open('/api/vault/download/' + id + '?token=' + encodeURIComponent(VAULT_TOKEN), '_blank');
}
async function vaultDelete(id){
  if (!VAULT_TOKEN || !confirm('ลบเอกสารนี้ถาวร?')) return;
  const r = await fetch('/api/vault/delete', {method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({token: VAULT_TOKEN, id})});
  const d = await r.json();
  setStatus(d.st === 'ok' ? 'ลบแล้ว' : '❌ ' + d.msg);
  loadDocs();
}
</script>
</body></html>"""


