# ==========================================
# [ 6z2. Studio Lite — เว็บย่อยแนว OBS ที่ /studio (จัด scene, webcam/screen, บันทึกคลิป) ]
# ทำงานทั้งหมดในเบราว์เซอร์ผ่าน getUserMedia/getDisplayMedia/Canvas/MediaRecorder — ไม่มี
# process แยกแบบ OBS จริง (เป็นไปไม่ได้ในเว็บแอป) แต่ได้ concept เดียวกัน: มีหลาย "scene"
# แต่ละ scene ใส่ "source" ได้หลายชิ้น (webcam/หน้าจอ/ข้อความ/สีพื้น) วางตำแหน่ง+ขนาดเอง
# สลับ scene ที่ใช้งานอยู่ได้ real-time แล้วอัด canvas ที่ผสมภาพแล้วเป็นวิดีโอ .webm ส่งขึ้น
# เซิร์ฟเวอร์เก็บไว้ (คล้ายการ "Start Recording" ของ OBS)
# เก็บ layout scene (JSON) + รายการคลิปที่บันทึกไว้ ต่อ uid ใน STUDIO_DIR
# ==========================================
STUDIO_DIR = "studio_lite_data"
os.makedirs(STUDIO_DIR, exist_ok=True)


def _studio_user_dir(uid: str) -> str:
    d = os.path.join(STUDIO_DIR, secure_filename(uid) or "anon")
    os.makedirs(d, exist_ok=True)
    return d


def _studio_scenes_path(uid: str) -> str:
    return os.path.join(_studio_user_dir(uid), "_scenes.json")


def _studio_recordings_path(uid: str) -> str:
    return os.path.join(_studio_user_dir(uid), "_recordings.json")


def _studio_load_json(path: str, default):
    if not os.path.exists(path):
        return default
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return default


def _studio_save_json(path: str, data):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f)


@app.route('/api/studio/scenes', methods=['GET', 'POST'])
@require_auth
def api_studio_scenes():
    """GET ?uid=xxx -> layout scene ล่าสุดที่เซฟไว้ (ว่างถ้ายังไม่เคยเซฟ)
    POST body: {uid, scenes:[{name, sources:[{type,x,y,w,h,z,text?,color?}]}], active_scene}"""
    if request.method == 'POST':
        body = request.json or {}
        uid = (resolve_uid(body) or '').strip()
        if not uid:
            return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
        data = {"scenes": body.get('scenes', []), "active_scene": body.get('active_scene', 0)}
        _studio_save_json(_studio_scenes_path(uid), data)
        return jsonify({"st": "ok"})
    uid = (resolve_uid() or '').strip()
    data = _studio_load_json(_studio_scenes_path(uid), {"scenes": [], "active_scene": 0})
    return jsonify({"st": "ok", **data})


@app.route('/api/studio/recordings/upload', methods=['POST'])
@require_auth_toggleable
def api_studio_recordings_upload():
    """อัปโหลดคลิปที่อัดจาก canvas (MediaRecorder -> .webm) form-data: uid, label, file"""
    uid = (request.form.get('uid') or '').strip()
    label = request.form.get('label') or 'คลิปไม่มีชื่อ'
    f = request.files.get('file')
    if not uid or not f:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid และไฟล์คลิป"}), 400
    rec_id = uuid.uuid4().hex
    raw = f.read()
    fname = f"rec_{rec_id}.webm"
    with open(os.path.join(_studio_user_dir(uid), fname), "wb") as out:
        out.write(raw)
    items = _studio_load_json(_studio_recordings_path(uid), [])
    items.append({"id": rec_id, "label": label, "filename": fname,
                  "size": len(raw), "created_at": time.time()})
    _studio_save_json(_studio_recordings_path(uid), items)
    return jsonify({"st": "ok", "id": rec_id})


@app.route('/api/studio/recordings')
def api_studio_recordings_list():
    uid = request.args.get('uid', '')
    items = _studio_load_json(_studio_recordings_path(uid), [])
    items.sort(key=lambda x: x["created_at"], reverse=True)
    return jsonify({"st": "ok", "recordings": items})


@app.route('/api/studio/recordings/<uid>/<rec_id>')
def api_studio_recordings_get(uid, rec_id):
    items = _studio_load_json(_studio_recordings_path(uid), [])
    meta = next((i for i in items if i["id"] == rec_id), None)
    if not meta:
        return jsonify({"st": "error", "msg": "ไม่พบคลิปนี้"}), 404
    return send_from_directory(_studio_user_dir(uid), meta["filename"], as_attachment=True,
                              download_name=secure_filename(meta["label"]) + ".webm")


@app.route('/api/studio/recordings/delete', methods=['POST'])
@require_auth
def api_studio_recordings_delete():
    body = request.json or {}
    uid = (resolve_uid(body) or '').strip()
    rec_id = body.get('id', '')
    items = _studio_load_json(_studio_recordings_path(uid), [])
    remaining = [i for i in items if i["id"] != rec_id]
    if len(remaining) == len(items):
        return jsonify({"st": "error", "msg": "ไม่พบคลิปนี้"}), 404
    meta = next(i for i in items if i["id"] == rec_id)
    fpath = os.path.join(_studio_user_dir(uid), meta["filename"])
    if os.path.exists(fpath):
        os.remove(fpath)
    _studio_save_json(_studio_recordings_path(uid), remaining)
    return jsonify({"st": "ok"})


STUDIO_PAGE_HTML = """<!DOCTYPE html>
<html lang="th"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>🎬 Studio Lite</title>
<style>
  body{background:#0f0f16;color:#eee;font-family:sans-serif;max-width:900px;margin:0 auto;padding:16px;}
  h1{font-size:20px;} .row{display:flex;gap:14px;flex-wrap:wrap;}
  .card{background:#1b1b26;border-radius:14px;padding:14px;margin-bottom:14px;}
  canvas{background:#000;border-radius:10px;width:100%;max-width:480px;aspect-ratio:16/9;}
  input,select{padding:6px;border-radius:6px;border:none;background:#111;color:#fff;margin:2px 0;}
  button{background:#4a4af0;border:none;border-radius:8px;color:#fff;padding:7px 12px;cursor:pointer;margin:2px 2px 2px 0;}
  button.danger{background:#c0392b;} button.ghost{background:#333;}
  .src-row{background:#111120;border-radius:8px;padding:8px;margin-bottom:6px;font-size:12px;}
  .src-row label{display:inline-block;width:64px;}
  .muted{opacity:.6;font-size:12px;}
  #rec-dot{display:none;color:#ff4757;font-weight:bold;}
</style></head>
<body>
<h1>🎬 Studio Lite — จัดฉาก อัดเวบแคม/หน้าจอ แบบ OBS</h1>
<input id="uid" placeholder="uid ของคุณ" style="width:220px;">
<div class="row">
  <div class="card" style="flex:1;min-width:300px;">
    <canvas id="stage" width="1280" height="720"></canvas>
    <div style="margin-top:8px;">
      <button onclick="startWebcam()">เปิดเวบแคม</button>
      <button onclick="startScreen()">แชร์หน้าจอ</button>
      <button onclick="togglePreview()" id="prevBtn">▶️ เริ่มพรีวิว</button>
      <button onclick="toggleRecording()" id="recBtn">⏺ เริ่มอัด</button>
      <span id="rec-dot">● REC</span>
    </div>
  </div>
  <div class="card" style="flex:1;min-width:280px;">
    <div>
      Scene: <select id="sceneSelect" onchange="switchScene(this.value)"></select>
      <button class="ghost" onclick="addScene()">+ Scene</button>
      <button class="danger" onclick="removeScene()">ลบ Scene</button>
    </div>
    <div style="margin-top:8px;">
      เพิ่ม source:
      <select id="srcType"><option value="webcam">เวบแคม</option><option value="screen">หน้าจอ</option>
        <option value="text">ข้อความ</option><option value="color">พื้นสี</option></select>
      <button onclick="addSource()">เพิ่ม</button>
    </div>
    <div id="src-list" style="margin-top:8px;"></div>
    <button onclick="saveLayout()">💾 บันทึก Layout</button>
    <div class="muted" id="studio-status"></div>
  </div>
</div>
<div class="card">
  <b>คลิปที่บันทึกไว้</b>
  <div id="rec-list" style="margin-top:8px;"></div>
</div>
<video id="webcamVideo" autoplay muted playsinline style="display:none;"></video>
<video id="screenVideo" autoplay muted playsinline style="display:none;"></video>
<script>
let scenes = [];
let activeScene = 0;
let webcamStream=null, screenStream=null, previewing=false, recorder=null, chunks=[], recording=false;
const canvas = document.getElementById('stage'), ctx = canvas.getContext('2d');
const webcamVideo = document.getElementById('webcamVideo'), screenVideo = document.getElementById('screenVideo');
function uid(){ return document.getElementById('uid').value.trim() || 'guest'; }
function setStatus(m){ document.getElementById('studio-status').innerText = m; }

async function startWebcam(){
  try{ webcamStream = await navigator.mediaDevices.getUserMedia({video:true,audio:true});
    webcamVideo.srcObject = webcamStream; setStatus('เปิดเวบแคมแล้ว'); }
  catch(e){ setStatus('❌ เปิดเวบแคมไม่ได้: '+e.message); }
}
async function startScreen(){
  try{ screenStream = await navigator.mediaDevices.getDisplayMedia({video:true});
    screenVideo.srcObject = screenStream; setStatus('แชร์หน้าจอแล้ว'); }
  catch(e){ setStatus('❌ แชร์หน้าจอไม่ได้: '+e.message); }
}
function togglePreview(){
  previewing = !previewing;
  document.getElementById('prevBtn').innerText = previewing ? '⏸ หยุดพรีวิว' : '▶️ เริ่มพรีวิว';
  if (previewing) requestAnimationFrame(renderLoop);
}
function renderLoop(){
  if (!previewing) return;
  ctx.fillStyle = '#000'; ctx.fillRect(0,0,canvas.width,canvas.height);
  const scene = scenes[activeScene];
  if (scene) (scene.sources||[]).slice().sort((a,b)=>a.z-b.z).forEach(s=>{
    const x=s.x/100*canvas.width, y=s.y/100*canvas.height, w=s.w/100*canvas.width, h=s.h/100*canvas.height;
    if (s.type==='webcam' && webcamStream) ctx.drawImage(webcamVideo, x, y, w, h);
    else if (s.type==='screen' && screenStream) ctx.drawImage(screenVideo, x, y, w, h);
    else if (s.type==='color'){ ctx.fillStyle = s.color||'#4a4af0'; ctx.fillRect(x,y,w,h); }
    else if (s.type==='text'){ ctx.fillStyle='#fff'; ctx.font=Math.max(12,h*0.6)+'px sans-serif';
      ctx.fillText(s.text||'', x, y+h*0.6); }
  });
  requestAnimationFrame(renderLoop);
}
function addScene(){ scenes.push({name:'Scene '+(scenes.length+1), sources:[]}); activeScene=scenes.length-1; refreshSceneSelect(); renderSourceList(); }
function removeScene(){ if (scenes.length<=1) return; scenes.splice(activeScene,1); activeScene=0; refreshSceneSelect(); renderSourceList(); }
function switchScene(i){ activeScene = parseInt(i); renderSourceList(); }
function refreshSceneSelect(){
  const sel = document.getElementById('sceneSelect');
  sel.innerHTML = scenes.map((s,i)=>`<option value="${i}" ${i===activeScene?'selected':''}>${s.name}</option>`).join('');
}
function addSource(){
  const type = document.getElementById('srcType').value;
  const scene = scenes[activeScene]; if (!scene) return;
  scene.sources.push({type, x:10, y:10, w:40, h:40, z:scene.sources.length,
    text: type==='text' ? 'ข้อความ' : undefined, color: type==='color' ? '#4a4af0' : undefined});
  renderSourceList();
}
function renderSourceList(){
  const box = document.getElementById('src-list'); box.innerHTML='';
  const scene = scenes[activeScene]; if (!scene) return;
  scene.sources.forEach((s,i)=>{
    const row = document.createElement('div'); row.className='src-row';
    row.innerHTML = `<b>${s.type}</b> #${i}
      <label>x%</label><input type="number" value="${s.x}" style="width:50px" onchange="scenes[${activeScene}].sources[${i}].x=+this.value">
      <label>y%</label><input type="number" value="${s.y}" style="width:50px" onchange="scenes[${activeScene}].sources[${i}].y=+this.value"><br>
      <label>w%</label><input type="number" value="${s.w}" style="width:50px" onchange="scenes[${activeScene}].sources[${i}].w=+this.value">
      <label>h%</label><input type="number" value="${s.h}" style="width:50px" onchange="scenes[${activeScene}].sources[${i}].h=+this.value">
      <label>z</label><input type="number" value="${s.z}" style="width:40px" onchange="scenes[${activeScene}].sources[${i}].z=+this.value">
      ${s.type==='text' ? `<br><label>ข้อความ</label><input value="${s.text||''}" onchange="scenes[${activeScene}].sources[${i}].text=this.value">`:''}
      ${s.type==='color' ? `<br><label>สี</label><input type="color" value="${s.color||'#4a4af0'}" onchange="scenes[${activeScene}].sources[${i}].color=this.value">`:''}
      <button class="danger" onclick="scenes[${activeScene}].sources.splice(${i},1);renderSourceList();">ลบ</button>`;
    box.appendChild(row);
  });
}
async function saveLayout(){
  await fetch('/api/studio/scenes', {method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({uid: uid(), scenes, active_scene: activeScene})});
  setStatus('บันทึก layout แล้ว');
}
async function loadLayout(){
  const r = await fetch('/api/studio/scenes?uid='+encodeURIComponent(uid()));
  const d = await r.json();
  scenes = (d.scenes && d.scenes.length) ? d.scenes : [{name:'Scene 1', sources:[]}];
  activeScene = d.active_scene || 0;
  refreshSceneSelect(); renderSourceList();
}
function toggleRecording(){
  if (!recording){
    const stream = canvas.captureStream(30);
    chunks = [];
    recorder = new MediaRecorder(stream, {mimeType:'video/webm'});
    recorder.ondataavailable = e => { if (e.data.size) chunks.push(e.data); };
    recorder.onstop = async () => {
      const blob = new Blob(chunks, {type:'video/webm'});
      const fd = new FormData();
      fd.append('uid', uid()); fd.append('label', 'clip_'+new Date().toISOString());
      fd.append('file', blob, 'clip.webm');
      await fetch('/api/studio/recordings/upload', {method:'POST', body: fd});
      loadRecordings();
    };
    recorder.start(); recording = true;
    document.getElementById('recBtn').innerText = '⏹ หยุดอัด';
    document.getElementById('rec-dot').style.display = 'inline';
  } else {
    recorder.stop(); recording = false;
    document.getElementById('recBtn').innerText = '⏺ เริ่มอัด';
    document.getElementById('rec-dot').style.display = 'none';
  }
}
async function loadRecordings(){
  const r = await fetch('/api/studio/recordings?uid='+encodeURIComponent(uid()));
  const d = await r.json();
  const box = document.getElementById('rec-list'); box.innerHTML='';
  (d.recordings||[]).forEach(rec=>{
    const row = document.createElement('div'); row.className='src-row';
    row.innerHTML = `📹 ${rec.label} <span class="muted">${(rec.size/1048576).toFixed(1)} MB</span>
      <button onclick="window.open('/api/studio/recordings/${uid()}/${rec.id}','_blank')">ดาวน์โหลด</button>
      <button class="danger" onclick="deleteRecording('${rec.id}')">ลบ</button>`;
    box.appendChild(row);
  });
}
async function deleteRecording(id){
  await fetch('/api/studio/recordings/delete', {method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({uid: uid(), id})});
  loadRecordings();
}
loadLayout(); loadRecordings();
</script>
</body></html>"""


