# ==========================================
# [ 6z3. Emoji Lab — เว็บย่อยที่ /emoji-lab (ผสม 2 อิโมจิเป็นสติกเกอร์ใหม่ แนว Emoji Kitchen) ]
# วาดอิโมจิ 2 ตัวลง canvas (ใช้ฟอนต์อิโมจิสีของเครื่อง/เบราว์เซอร์เอง ไม่ต้องมีไฟล์รูปอิโมจิ
# แยก) แล้วผสมด้วยสไตล์ต่างๆ (ซ้อนมุม/เบลนด์โปร่งแสง/แบ่งครึ่ง/ตราประทับหมุนเอียง) ได้ผลลัพธ์
# เป็นสติกเกอร์ผสมใหม่ที่ดาวน์โหลดเป็น PNG ได้ หรือเซฟเก็บไว้ในแกลเลอรีส่วนตัวบนเซิร์ฟเวอร์
# ==========================================
EMOJI_LAB_DIR = "emoji_lab_creations"
os.makedirs(EMOJI_LAB_DIR, exist_ok=True)


def _emoji_lab_user_dir(uid: str) -> str:
    d = os.path.join(EMOJI_LAB_DIR, secure_filename(uid) or "anon")
    os.makedirs(d, exist_ok=True)
    return d


def _emoji_lab_index_path(uid: str) -> str:
    return os.path.join(_emoji_lab_user_dir(uid), "_gallery.json")


@app.route('/api/emoji-lab/save', methods=['POST'])
@require_auth
def api_emoji_lab_save():
    """เซฟผลงานที่ผสมแล้ว — body: {uid, label, image_base64 (data URL PNG จาก canvas.toDataURL())}"""
    body = request.json or {}
    uid = (resolve_uid(body) or '').strip()
    label = body.get('label') or 'emoji mashup'
    data_url = body.get('image_base64') or ''
    if not uid or not data_url.startswith('data:image'):
        return jsonify({"st": "error", "msg": "ต้องระบุ uid และรูปที่ถูกต้อง"}), 400
    try:
        b64data = data_url.split(',', 1)[1]
        raw = base64.b64decode(b64data)
    except Exception:
        return jsonify({"st": "error", "msg": "ถอดรหัสรูปไม่สำเร็จ"}), 400
    creation_id = uuid.uuid4().hex
    with open(os.path.join(_emoji_lab_user_dir(uid), creation_id + ".png"), "wb") as out:
        out.write(raw)
    items = _studio_load_json(_emoji_lab_index_path(uid), [])
    items.append({"id": creation_id, "label": label, "created_at": time.time()})
    _studio_save_json(_emoji_lab_index_path(uid), items)
    return jsonify({"st": "ok", "id": creation_id})


@app.route('/api/emoji-lab/gallery')
def api_emoji_lab_gallery():
    uid = request.args.get('uid', '')
    items = _studio_load_json(_emoji_lab_index_path(uid), [])
    items.sort(key=lambda x: x["created_at"], reverse=True)
    return jsonify({"st": "ok", "creations": items})


@app.route('/api/emoji-lab/image/<uid>/<creation_id>')
def api_emoji_lab_image(uid, creation_id):
    return send_from_directory(_emoji_lab_user_dir(uid), secure_filename(creation_id) + ".png")


@app.route('/api/emoji-lab/delete', methods=['POST'])
@require_auth
def api_emoji_lab_delete():
    body = request.json or {}
    uid = (resolve_uid(body) or '').strip()
    creation_id = body.get('id', '')
    items = _studio_load_json(_emoji_lab_index_path(uid), [])
    remaining = [i for i in items if i["id"] != creation_id]
    if len(remaining) == len(items):
        return jsonify({"st": "error", "msg": "ไม่พบผลงานนี้"}), 404
    _studio_save_json(_emoji_lab_index_path(uid), remaining)
    fpath = os.path.join(_emoji_lab_user_dir(uid), creation_id + ".png")
    if os.path.exists(fpath):
        os.remove(fpath)
    return jsonify({"st": "ok"})


EMOJI_LAB_PAGE_HTML = """<!DOCTYPE html>
<html lang="th"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>😆 Emoji Lab</title>
<style>
  body{background:#0f0f16;color:#eee;font-family:sans-serif;max-width:520px;margin:0 auto;padding:16px;text-align:center;}
  h1{font-size:20px;} .card{background:#1b1b26;border-radius:14px;padding:16px;margin-bottom:14px;}
  input,select{padding:8px;border-radius:8px;border:none;background:#111;color:#fff;margin:4px;font-size:18px;width:70px;text-align:center;}
  button{background:#4a4af0;border:none;border-radius:8px;color:#fff;padding:9px 14px;cursor:pointer;margin:4px;}
  button.ghost{background:#333;} button.danger{background:#c0392b;}
  canvas{background:#fff;border-radius:12px;width:100%;max-width:320px;aspect-ratio:1/1;}
  .gal-item{display:inline-block;margin:6px;text-align:center;}
  .gal-item img{width:80px;height:80px;border-radius:10px;background:#fff;}
</style></head>
<body>
<h1>😆 Emoji Lab — ผสมอิโมจิเป็นสติกเกอร์ใหม่</h1>
<input id="uid" placeholder="uid" style="width:120px;">
<div class="card">
  <input id="emojiA" value="😺" maxlength="4">➕<input id="emojiB" value="🔥" maxlength="4">
  <br>สไตล์:
  <select id="style">
    <option value="overlap">ตราติดมุม</option>
    <option value="blend">เบลนด์โปร่งแสง</option>
    <option value="split">แบ่งครึ่ง</option>
    <option value="stamp">ตราประทับเอียง</option>
  </select>
  <br>
  <button onclick="mashup()">🧪 ผสม!</button>
  <button class="ghost" onclick="randomize()">🎲 สุ่มให้เลย</button>
  <br><canvas id="lab" width="512" height="512"></canvas><br>
  <button onclick="downloadPng()">⬇️ ดาวน์โหลด PNG</button>
  <button class="ghost" onclick="saveToGallery()">💾 เซฟลงแกลเลอรี</button>
  <div class="muted" id="lab-status"></div>
</div>
<div class="card"><b>แกลเลอรีของฉัน</b><div id="gallery"></div></div>
<script>
const EMOJI_POOL = ['😺','🔥','🐶','🌈','👻','🍕','🚀','💀','🦄','😂','🧊','🌸','🍔','🎃','⚡','🐸','🥶','😎','🍩','🌙'];
const canvas = document.getElementById('lab'), ctx = canvas.getContext('2d');
function uid(){ return document.getElementById('uid').value.trim() || 'guest'; }
function setStatus(m){ document.getElementById('lab-status').innerText = m; }

function mashup(){
  const a = document.getElementById('emojiA').value || '😺';
  const b = document.getElementById('emojiB').value || '🔥';
  const style = document.getElementById('style').value;
  ctx.clearRect(0,0,512,512);
  ctx.textAlign='center'; ctx.textBaseline='middle';
  if (style === 'overlap'){
    ctx.font='360px sans-serif'; ctx.fillText(a, 256, 270);
    ctx.font='220px sans-serif'; ctx.fillText(b, 380, 400);
  } else if (style === 'blend'){
    ctx.globalAlpha = 0.75; ctx.font='380px sans-serif'; ctx.fillText(a, 256, 256);
    ctx.globalAlpha = 0.75; ctx.font='380px sans-serif'; ctx.fillText(b, 256, 256);
    ctx.globalAlpha = 1;
  } else if (style === 'split'){
    ctx.save(); ctx.beginPath(); ctx.rect(0,0,256,512); ctx.clip();
    ctx.font='380px sans-serif'; ctx.fillText(a, 256, 256); ctx.restore();
    ctx.save(); ctx.beginPath(); ctx.rect(256,0,256,512); ctx.clip();
    ctx.font='380px sans-serif'; ctx.fillText(b, 256, 256); ctx.restore();
  } else if (style === 'stamp'){
    ctx.font='360px sans-serif'; ctx.fillText(a, 256, 256);
    ctx.save(); ctx.translate(256,256); ctx.rotate(-0.35); ctx.font='230px sans-serif';
    ctx.globalAlpha=0.9; ctx.fillText(b, 0, 0); ctx.restore();
  }
  setStatus('ผสมแล้ว: ' + a + ' + ' + b + ' (' + style + ')');
}
function randomize(){
  document.getElementById('emojiA').value = EMOJI_POOL[Math.floor(Math.random()*EMOJI_POOL.length)];
  document.getElementById('emojiB').value = EMOJI_POOL[Math.floor(Math.random()*EMOJI_POOL.length)];
  const styles = ['overlap','blend','split','stamp'];
  document.getElementById('style').value = styles[Math.floor(Math.random()*styles.length)];
  mashup();
}
function downloadPng(){
  const a = document.createElement('a');
  a.download = 'emoji-mashup.png'; a.href = canvas.toDataURL('image/png'); a.click();
}
async function saveToGallery(){
  const r = await fetch('/api/emoji-lab/save', {method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({uid: uid(), label: document.getElementById('emojiA').value+document.getElementById('emojiB').value,
      image_base64: canvas.toDataURL('image/png')})});
  const d = await r.json();
  setStatus(d.st === 'ok' ? 'เซฟลงแกลเลอรีแล้ว' : '❌ ' + d.msg);
  loadGallery();
}
async function loadGallery(){
  const r = await fetch('/api/emoji-lab/gallery?uid='+encodeURIComponent(uid()));
  const d = await r.json();
  const box = document.getElementById('gallery'); box.innerHTML='';
  (d.creations||[]).forEach(c=>{
    const div = document.createElement('div'); div.className='gal-item';
    div.innerHTML = `<img src="/api/emoji-lab/image/${uid()}/${c.id}"><br>
      <button class="danger" onclick="delCreation('${c.id}')" style="padding:2px 6px;font-size:11px;">ลบ</button>`;
    box.appendChild(div);
  });
}
async function delCreation(id){
  await fetch('/api/emoji-lab/delete', {method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({uid: uid(), id})});
  loadGallery();
}
mashup(); loadGallery();
</script>
</body></html>"""


