# ==========================================
# [ 6zz. NPC: รับฟีดแบ็ก + ประกาศแพตช์โน้ต + ชุมชนในเกม (in-game browser) ]
# NPC ตัวนี้ทำ 2 หน้าที่หลักในตัวเดียว:
#   1) รับฟีดแบ็กจากผู้เล่น (คุยกับ NPC ตรงๆ หรือกดเมนูสำเร็จรูป) — เก็บลง
#      NPC_FEEDBACK_QUEUE แล้วแอดมิน/ผู้เล่นกด "ส่งเข้าคิวพัฒนา" ต่อได้ ซึ่งใช้
#      pipeline เดิมทั้งหมดของ [ 2c. Feature Request Queue ] (generate_feature_code +
#      _load_pending/_save_pending + /api/approve_feature เดิม) ไม่สร้างคิวใหม่ซ้ำ
#   2) ประกาศแพตช์โน้ต — ผูกกับระบบ [ 2I. Announcement System ] เดิม
#      (post_announcement/ANNOUNCEMENTS) กรองมาเฉพาะ type=patch_notes/event ของเกมนี้
#
# ส่วน "ชุมชน" ตามที่ขอ: กดแล้ว *ไม่* เด้ง/redirect ออกไปเว็บไซต์ภายนอก แต่เปิด
# หน้า /community (เสิร์ฟจากแอปนี้เอง) ขึ้นมาเป็น <iframe> ลอยทับอยู่ในหน้าเกม —
# เหมือน "เปิดเบราว์เซอร์ในเกม" แต่ทุกอย่างยังอยู่ใน origin เดียวกัน ไม่ออกจากแอป
# หน้า /community รวมฟีด gallery_community + manga_platform + แพตช์โน้ต + บอร์ด
# ฟีดแบ็กของผู้เล่นคนอื่นเข้าไว้ในที่เดียว (ดึงจาก endpoint เดิมที่มีอยู่แล้ว)
# ==========================================

NPC_FEEDBACK_QUEUE = {}   # feedback_id -> {id,uid,text,category,status,created_at,linked_pending}
NPC_DIALOGUE_LOG = {}     # uid -> deque[{role: 'player'|'npc', text, ts}]

NPC_ID = "reporter_01"
NPC_NAME = "จ่าแจ้ง"   # ชื่อ NPC ประจำคีออสก์ฟีดแบ็ก/ประกาศแพตช์โน้ต
NPC_QUICK_MENU = [
    {"id": "submit_feedback", "label": "📝 ส่งฟีดแบ็ก"},
    {"id": "view_patchnotes", "label": "📜 ดูแพตช์โน้ตล่าสุด"},
    {"id": "open_community", "label": "🌐 เปิดชุมชน"},
]
NPC_FEEDBACK_CATEGORIES = ("general", "bug", "balance", "idea", "other")


def npc_log_message(uid: str, role: str, text: str):
    log = NPC_DIALOGUE_LOG.setdefault(uid, deque(maxlen=100))
    log.append({"role": role, "text": text, "ts": time.time()})


def npc_submit_feedback(uid: str, text: str, category: str = "general") -> tuple:
    """บันทึกฟีดแบ็กที่ผู้เล่นพิมพ์คุยกับ NPC — ยังไม่เข้าคิวพัฒนาอัตโนมัติ ต้องกด
    'ส่งเข้าคิวพัฒนา' อีกทีผ่าน npc_forward_feedback_to_feature_queue() ก่อน (กันสแปม/
    ข้อความไม่เกี่ยวเข้าไปปนกับของจริงในคิว [ 2c ])"""
    if category not in NPC_FEEDBACK_CATEGORIES:
        category = "general"
    fid = uuid.uuid4().hex[:8]
    NPC_FEEDBACK_QUEUE[fid] = {
        "id": fid, "uid": uid, "text": text, "category": category,
        "status": "received", "created_at": time.time(), "linked_pending": None,
    }
    npc_log_message(uid, "player", text)
    reply = f"ขอบคุณสำหรับฟีดแบ็กครับ! บันทึกไว้แล้ว (รหัส {fid}) — ทีมงานจะทยอยตรวจดูนะครับ 🙏"
    npc_log_message(uid, "npc", reply)
    bridge_push_event("npc_feedback", "feedback_received", {"id": fid, "uid": uid, "category": category})
    return fid, reply


def npc_forward_feedback_to_feature_queue(fid: str, target: str = "python") -> tuple:
    """เอาฟีดแบ็กที่รับไว้ ไปเข้าคิว 'เพิ่มระบบใหม่' เดิม ([ 2c ]) ให้ AI ร่างโค้ดให้ —
    ใช้ generate_feature_code() + _load_pending/_save_pending ตัวเดียวกับที่หน้าเว็บ
    'เพิ่มระบบใหม่' ใช้อยู่แล้ว โค้ดที่ได้ยังต้องผ่านการตรวจ/กดอนุมัติที่
    /api/approve_feature เหมือนเดิมทุกประการ — ไม่มีการรันอัตโนมัติจากตรงนี้"""
    fb = NPC_FEEDBACK_QUEUE.get(fid)
    if not fb:
        return False, "ไม่พบฟีดแบ็กรหัสนี้"
    if fb["linked_pending"]:
        return False, f"ฟีดแบ็กนี้ถูกส่งเข้าคิวพัฒนาไปแล้ว (pending id: {fb['linked_pending']})"
    code, context_meta = generate_feature_code(fb["text"], target=target)
    idx = _load_pending()
    pid = uuid.uuid4().hex[:8]
    idx[pid] = {
        "id": pid, "description": fb["text"], "target": target, "code": code,
        "created_at": time.time(), "status": "pending_review",
        "context_meta": context_meta, "source_feedback_id": fid, "source": "npc_feedback",
    }
    _save_pending(idx)
    fb["linked_pending"] = pid
    fb["status"] = "forwarded_to_dev_queue"
    return True, pid


def npc_get_patch_notes(limit: int = 10) -> list:
    """ดึงประกาศประเภทแพตช์โน้ต/อีเวนต์ของเกมนี้ (CURRENT_GAME_ID) จากระบบ
    Announcement เดิม [ 2I ] เรียงใหม่สุดก่อน — ไม่สร้าง store แยกต่างหาก"""
    items = [a for a in ANNOUNCEMENTS
             if a["type"] in ("patch_notes", "event")
             and a.get("game_id", "all") in ("all", CURRENT_GAME_ID)]
    items.sort(key=lambda a: a["expires"], reverse=True)
    return items[:limit]


def npc_announce_patch_notes(title: str, body: str, expires_in: int = 14 * 86400) -> str:
    """ทางลัดให้ NPC 'ประกาศแพตช์โน้ต' — ห่อ post_announcement() เดิมไว้ ตั้ง
    type='patch_notes' และผูก game_id ปัจจุบันให้อัตโนมัติเสมอ"""
    return post_announcement("patch_notes", title, body, expires_in=expires_in, game_id=CURRENT_GAME_ID)


@app.route('/api/npc/<npc_id>/info')
def api_npc_info(npc_id):
    """ข้อมูล NPC + เมนูด่วน — npc_id รับไว้เผื่ออนาคตมี NPC หลายตัว ตอนนี้มีตัวเดียว
    (NPC_ID) จึงคืนข้อมูลตัวเดียวกันไม่ว่า npc_id จะเป็นอะไร"""
    return jsonify({"st": "ok", "id": NPC_ID, "name": NPC_NAME, "quick_menu": NPC_QUICK_MENU,
                    "categories": NPC_FEEDBACK_CATEGORIES})


@app.route('/api/npc/dialogue', methods=['POST'])
@require_auth_toggleable
def api_npc_dialogue():
    """จุดเดียวที่คุยกับ NPC — ผู้เล่นพิมพ์อิสระ (text) หรือกดเมนูด่วน (action) ก็ได้
    body: {uid, text?, action?, category?}
    [P0.5 FIX] ยังคุยกับ NPC แบบ guest (ไม่ login) ได้ตามปกติ เพราะตอนนี้ไม่มี action ไหน
    แจกของ/เงิน/exp จริง แต่แยก is_guest ไว้ล่วงหน้า — ถ้าในอนาคตมี action ที่แจกรางวัล
    ให้เรียก npc_guard_reward_action(uid, is_guest) ก่อนแจกทุกครั้ง (ดู helper ด้านล่าง)
    เพื่อกัน guest ปลอม uid มารับรางวัลซ้ำไม่จำกัดโดยไม่ต้อง login"""
    body = request.json or {}
    _resolved = resolve_uid(body)
    is_guest = _resolved is None
    uid = (_resolved or "").strip() or "guest"
    action = body.get("action")
    text = (body.get("text") or "").strip()

    if action == "view_patchnotes":
        notes = npc_get_patch_notes()
        reply = "แพตช์โน้ตล่าสุดของเกมนี้ครับ 👇" if notes else "ตอนนี้ยังไม่มีแพตช์โน้ตประกาศไว้เลยครับ"
        npc_log_message(uid, "npc", reply)
        return jsonify({"st": "ok", "npc_reply": reply, "patch_notes": notes, "quick_menu": NPC_QUICK_MENU})

    if action == "open_community":
        reply = "เปิดหน้าชุมชนให้เลยครับ 🌐 (เปิดอยู่ในเกมนี้เลย ไม่เด้งออกไปเว็บนอก)"
        npc_log_message(uid, "npc", reply)
        return jsonify({"st": "ok", "npc_reply": reply, "community_url": "/community",
                        "quick_menu": NPC_QUICK_MENU})

    if action == "submit_feedback" or (text and not action):
        if not text:
            return jsonify({"st": "error", "msg": "พิมพ์ข้อความฟีดแบ็กมาด้วยครับ"}), 400
        fid, reply = npc_submit_feedback(uid, text, body.get("category", "general"))
        return jsonify({"st": "ok", "npc_reply": reply, "feedback_id": fid, "quick_menu": NPC_QUICK_MENU})

    reply = f"สวัสดีครับ ผม{NPC_NAME} — เลือกจากเมนูด้านล่าง หรือพิมพ์ฟีดแบ็กมาคุยกับผมได้เลยครับ"
    npc_log_message(uid, "npc", reply)
    return jsonify({"st": "ok", "npc_reply": reply, "quick_menu": NPC_QUICK_MENU})


# --- [P0.5 FIX] npc_guard_reward_action(): guard สำหรับอนาคต ---
# ตอนนี้ (ตรวจแล้ว) ไม่มี action ไหนใน api_npc_dialogue ที่แจกเงิน/ไอเทม/exp จริง จึงยัง
# ปล่อยให้ guest คุยได้เต็มที่โดยไม่ต้อง login — แต่ถ้าในอนาคตมีการเพิ่ม action ที่แจก
# รางวัลผ่าน NPC (เช่น เควสต์ประจำวัน, ของขวัญกิจกรรม) ให้เรียก guard นี้ก่อนแจกของทุกครั้ง
# เพื่อกัน guest (ไม่มี JWT, ปลอม uid ใน body ได้ไม่จำกัด) มารับรางวัลซ้ำๆ ไม่จบไม่สิ้น
# ใช้แบบนี้ในตัว action นั้นๆ:
#   deny = npc_guard_reward_action(is_guest)
#   if deny: return deny
def npc_guard_reward_action(is_guest: bool):
    """เรียกก่อนแจกรางวัลใดๆ ผ่าน NPC dialogue — ถ้าเป็น guest (ไม่มี JWT valid) คืน
    tuple (jsonify(...), 401) ให้ caller return ตรงๆ ได้เลย ถ้าไม่ใช่ guest คืน None
    (แปลว่าแจกรางวัลต่อได้ตามปกติ)"""
    if is_guest:
        return jsonify({"st": "error",
                         "msg": "ต้อง login ก่อนถึงจะรับรางวัลนี้ได้ครับ (คุยเล่นแบบไม่ login ได้ปกติ "
                                "แต่รับของ/เงิน/exp ต้อง login เพื่อกันการปลอมตัวรับซ้ำ)"}), 401
    return None




@app.route('/api/npc/dialogue/history')
def api_npc_dialogue_history():
    uid = (request.args.get("uid") or "guest").strip() or "guest"
    return jsonify({"st": "ok", "log": list(NPC_DIALOGUE_LOG.get(uid, []))})


@app.route('/api/npc/feedback/list')
def api_npc_feedback_list():
    """?uid=... กรองเฉพาะของคนนั้น ไม่ระบุ = คืนทั้งหมด (มุมมองแอดมิน)"""
    uid = request.args.get("uid")
    items = list(NPC_FEEDBACK_QUEUE.values())
    if uid:
        items = [f for f in items if f["uid"] == uid]
    items.sort(key=lambda f: f["created_at"], reverse=True)
    return jsonify({"st": "ok", "count": len(items), "feedback": items})


@app.route('/api/npc/feedback/<fid>/forward', methods=['POST'])
@require_auth_toggleable
def api_npc_feedback_forward(fid):
    """ส่งฟีดแบ็กที่เลือกเข้าคิวพัฒนาเดิม ([ 2c ]) — body: {target: 'python'|...}
    โค้ดที่ได้ยังต้องผ่าน /api/approve_feature ตามปกติ ไม่ auto-merge จากตรงนี้"""
    body = request.json or {}
    ok, result = npc_forward_feedback_to_feature_queue(fid, target=body.get("target", "python"))
    if not ok:
        return jsonify({"st": "error", "msg": result}), 404
    return jsonify({"st": "ok", "pending_id": result})


@app.route('/api/npc/patchnotes/announce', methods=['POST'])
@require_auth_toggleable
def api_npc_patchnotes_announce():
    """ให้ NPC ประกาศแพตช์โน้ตใหม่ — body: {title, body, expires_in?} (สำหรับแอดมิน/
    ทีมพัฒนา ไม่ใช่ endpoint ที่ผู้เล่นทั่วไปเรียก)"""
    body = request.json or {}
    title, note_body = (body.get("title") or "").strip(), (body.get("body") or "").strip()
    if not title or not note_body:
        return jsonify({"st": "error", "msg": "ต้องระบุ title และ body"}), 400
    aid = npc_announce_patch_notes(title, note_body, expires_in=int(body.get("expires_in", 14 * 86400)))
    return jsonify({"st": "ok", "announcement_id": aid})


