# ==========================================
# [ 6v7. On-Hit Audio/HUD Spatial Shift — เพลงสลับข้างหู + HUD ขยับจอ ตอนยิงโดน/ฆ่าศัตรู ]
# กติกา:
#   - Toggle เปิด/ปิด แยกกันได้ 2 อัน: audio panning กับ HUD shift (อยู่ในเมนู
#     ตั้งค่าเสียง/ตั้งค่าหน้าจอฝั่ง client — ฝั่ง server เก็บ pref ไว้ต่อ uid ที่นี่)
#   - Trigger: ฝั่งเกม/ไคลเอนต์เรียก POST /api/onhit-shift/trigger ทุกครั้งที่กระสุน
#     โดนศัตรู (on-hit) หรือฆ่าสำเร็จ (on-kill) พร้อม target_id ของศัตรูตัวนั้น
#   - Server คำนวณค่า pan (-1.0 ซ้ายสุด ถึง +1.0 ขวาสุด) แบบ deterministic ต่อ
#     target_id (ศัตรูตัวเดิมได้ตำแหน่งเดิมเสมอ กันเพลงกระโดดมั่วไปมาแบบสุ่มล้วน)
#     แล้วส่งกลับให้ client ไปสั่ง Web Audio API (StereoPannerNode) กับ HUD widget
#     เอง — ฝั่ง widget ที่แนบมาให้ (widget_onhit_shift) จัดการ "หยุดนิ่ง 1 วินาที
#     ก่อนเริ่มสลับ" ให้อัตโนมัติ เพื่อกันเวียนหัว (ปรับได้ที่ ONHIT_SHIFT_HOLD_MS)
# ==========================================
ONHIT_SHIFT_PREFS = {}  # uid -> {"audio_enabled": bool, "hud_enabled": bool}
ONHIT_SHIFT_HOLD_MS = 1000  # หยุดนิ่ง 1 วิ ก่อนเริ่มสลับตำแหน่ง (กันเวียนหัว)


def _onhit_shift_pan_for_target(target_id):
    """คำนวณค่า pan (-1..1) แบบ deterministic จาก target_id เดิมได้ค่าเดิมเสมอ
    ใช้ hash แทนสุ่มล้วน เพื่อไม่ให้เพลงกระโดดไปมาแบบคาดเดาไม่ได้เกินไป"""
    h = int(hashlib.md5(str(target_id).encode("utf-8")).hexdigest()[:8], 16)
    # กระจายค่าให้เอนไปทางซ้าย/ขวาชัดเจน (หลีกเลี่ยงค่ากลางๆ ที่แทบไม่รู้สึก)
    # เช่นตัวอย่างในสเปค: ศัตรูตัวที่ 1 -> ซ้าย 70%, ศัตรูตัวที่ 2 -> ขวา 100%
    bucket = h % 4
    pan_choices = [-1.0, -0.7, 0.7, 1.0]
    pan = pan_choices[bucket]
    side = "left" if pan < 0 else "right"
    return pan, side, int(abs(pan) * 100)


@app.route('/api/onhit-shift/prefs', methods=['GET', 'POST'])
@require_auth_toggleable
def api_onhit_shift_prefs():
    """GET ?uid=xxx -> ค่า toggle ปัจจุบัน (default ปิดทั้งคู่ ผู้เล่นต้องเปิดเองจากเมนู
    ตั้งค่าเสียง/ตั้งค่าหน้าจอ)
    POST body: {uid, audio_enabled?, hud_enabled?}"""
    if request.method == 'POST':
        body = request.json or {}
        uid = body.get('uid', '')
        if not uid:
            return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
        prefs = ONHIT_SHIFT_PREFS.setdefault(uid, {"audio_enabled": False, "hud_enabled": False})
        if 'audio_enabled' in body:
            prefs['audio_enabled'] = bool(body['audio_enabled'])
        if 'hud_enabled' in body:
            prefs['hud_enabled'] = bool(body['hud_enabled'])
        return jsonify({"st": "ok", "uid": uid, "prefs": prefs})
    uid = request.args.get('uid', '')
    prefs = ONHIT_SHIFT_PREFS.get(uid, {"audio_enabled": False, "hud_enabled": False})
    return jsonify({"st": "ok", "uid": uid, "prefs": prefs, "hold_ms": ONHIT_SHIFT_HOLD_MS})


@app.route('/api/onhit-shift/trigger', methods=['POST'])
@require_auth_toggleable
def api_onhit_shift_trigger():
    """เรียกทุกครั้งที่ on-hit หรือ on-kill
    body: {uid, target_id, event_type: "hit"|"kill"}
    คืนค่า pan (-1..1) + hold_ms ให้ client ไปเล่นเอฟเฟกต์ (server ไม่ได้สั่งเล่นเสียงเอง
    เพราะ audio playback ต้องรันฝั่ง client เท่านั้น)"""
    body = request.json or {}
    uid = body.get('uid', '')
    target_id = body.get('target_id', '')
    event_type = body.get('event_type', 'hit')
    if not uid or not target_id:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid และ target_id"}), 400
    prefs = ONHIT_SHIFT_PREFS.get(uid, {"audio_enabled": False, "hud_enabled": False})
    if not (prefs.get('audio_enabled') or prefs.get('hud_enabled')):
        return jsonify({"st": "ok", "applied": False, "msg": "ผู้เล่นปิดระบบนี้ไว้"})
    pan, side, percent = _onhit_shift_pan_for_target(target_id)
    payload = {
        "st": "ok", "applied": True, "event_type": event_type, "target_id": target_id,
        "pan": pan, "side": side, "percent": percent, "hold_ms": ONHIT_SHIFT_HOLD_MS,
        "audio_enabled": prefs.get('audio_enabled', False),
        "hud_enabled": prefs.get('hud_enabled', False),
    }
    # ส่งผ่าน socket ด้วย เผื่อหน้าอื่น (เช่น mini-player ที่ลอยอยู่นอกหน้าเกมหลัก) อยาก
    # ฟังอีเวนต์นี้แบบ real-time โดยไม่ต้อง poll เอง
    try:
        sio.emit('onhit_shift', payload, room=uid)
    except Exception:
        pass
    return jsonify(payload)


ONHIT_SHIFT_WIDGET_HTML = """
<div id="vmax-onhit-hud" style="display:none;position:fixed;top:16px;left:50%;
  transform:translateX(-50%);transition:left 0.35s ease, top 0.35s ease;z-index:9996;
  background:rgba(20,20,25,.85);color:#fff;font-family:sans-serif;font-size:12px;
  border-radius:10px;padding:6px 12px;pointer-events:none;">
  🎧 <span id="vmax-onhit-hud-label"></span>
</div>
"""

ONHIT_SHIFT_WIDGET_JS = """
(function(){
  var uid = (window.VMAX_ONHIT_SHIFT_CONFIG && window.VMAX_ONHIT_SHIFT_CONFIG.uid) || 'guest';
  var holdMs = 1000;
  var hud = document.getElementById('vmax-onhit-hud');
  var hudLabel = document.getElementById('vmax-onhit-hud-label');
  var audioCtx = null;
  var pannerA = null, pannerB = null;
  var pending = false;

  function ensureAudioGraph(){
    // เกาะไปกับ <audio> ของ dual_music_player (6v5) ถ้ามีอยู่ในหน้านี้ — ถ้าไม่มีก็แค่
    // ข้ามส่วน audio ไป (HUD shift ยังทำงานได้อิสระ)
    if (audioCtx) return true;
    var elA = document.getElementById('vmax-dm-audio-a');
    var elB = document.getElementById('vmax-dm-audio-b');
    if (!elA && !elB) return false;
    try {
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      if (elA) {
        var srcA = audioCtx.createMediaElementSource(elA);
        pannerA = audioCtx.createStereoPanner();
        srcA.connect(pannerA).connect(audioCtx.destination);
      }
      if (elB) {
        var srcB = audioCtx.createMediaElementSource(elB);
        pannerB = audioCtx.createStereoPanner();
        srcB.connect(pannerB).connect(audioCtx.destination);
      }
    } catch (e) {
      console.warn('[onhit-shift] เชื่อม audio graph ไม่สำเร็จ:', e);
      return false;
    }
    return true;
  }

  function applyPan(pan){
    if (!ensureAudioGraph()) return;
    if (pannerA) pannerA.pan.setValueAtTime(pan, audioCtx.currentTime);
    if (pannerB) pannerB.pan.setValueAtTime(pan, audioCtx.currentTime);
  }

  function applyHudShift(side, percent){
    if (side === 'left') {
      hud.style.left = (50 - percent * 0.4) + '%';
    } else {
      hud.style.left = (50 + percent * 0.4) + '%';
    }
    hud.style.top = (12 + Math.random() * 40) + 'px';
  }

  // API หลัก: ฝั่งเกมเรียกตรงนี้ทุกครั้งที่ on-hit/on-kill
  // eventType: 'hit' | 'kill', targetId: id ของศัตรูที่โดน/ถูกฆ่า
  window.vmaxOnHitShiftTrigger = function(targetId, eventType){
    eventType = eventType || 'hit';
    fetch('/api/onhit-shift/trigger', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({uid: uid, target_id: targetId, event_type: eventType})
    }).then(function(r){ return r.json(); }).then(function(d){
      if (!d.applied) return;
      holdMs = d.hold_ms || 1000;
      // ขอมีหยุดนิ่ง 1 วินาทีก่อนเริ่มสลับ กันเวียนหัว — ไม่ทำต่อเนื่องกันรัวๆ
      if (pending) return;
      pending = true;
      setTimeout(function(){
        if (d.audio_enabled) applyPan(d.pan);
        if (d.hud_enabled) {
          hud.style.display = 'block';
          hudLabel.innerText = (eventType === 'kill' ? 'Kill' : 'Hit') + ' → ' +
            (d.side === 'left' ? '⬅ ซ้าย' : 'ขวา ➡') + ' ' + d.percent + '%';
          applyHudShift(d.side, d.percent);
        }
        pending = false;
      }, holdMs);
    }).catch(function(e){ console.warn('[onhit-shift] trigger ล้มเหลว:', e); });
  };

  // helper เผื่ออยากผูกกับ toggle ในเมนูตั้งค่าเสียง/ตั้งค่าหน้าจอโดยตรง
  window.vmaxOnHitShiftSetPrefs = function(audioEnabled, hudEnabled){
    return fetch('/api/onhit-shift/prefs', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({uid: uid, audio_enabled: audioEnabled, hud_enabled: hudEnabled})
    }).then(function(r){ return r.json(); });
  };

  fetch('/api/onhit-shift/prefs?uid=' + encodeURIComponent(uid))
    .then(function(r){ return r.json(); }).then(function(d){ holdMs = d.hold_ms || 1000; });
})();
"""


@app.route('/widgets/onhit-audio-hud-shift')
def widget_onhit_shift():
    """widget ระบบ 'เพลงสลับข้างหู + HUD ขยับจอ' ตอนยิงโดน/ฆ่าศัตรู — ฝังแบบเดียวกับ
    widget อื่นๆ:
        window.VMAX_ONHIT_SHIFT_CONFIG = { uid: 'xxx' };
        fetch('/widgets/onhit-audio-hud-shift').then(r => r.text())
            .then(html => document.body.insertAdjacentHTML('beforeend', html));
    แล้วให้ฝั่งเกมเรียก window.vmaxOnHitShiftTrigger(targetId, 'hit'|'kill') ทุกครั้งที่
    กระสุนโดนศัตรูหรือฆ่าสำเร็จ ระบบจะเช็ค toggle (ตั้งค่าเสียง/ตั้งค่าหน้าจอ) เองว่า
    ผู้เล่นเปิดไว้หรือเปล่าก่อนสั่งสลับ พร้อมหยุดนิ่ง 1 วิ ก่อนเริ่ม กันเวียนหัว
    ต้องมี dual_music_player (6v5) widget อยู่ในหน้าเดียวกันด้วยถ้าอยากได้ audio
    panning จริง (ถ้าไม่มี จะทำงานแค่ฝั่ง HUD shift อย่างเดียว)"""
    return ONHIT_SHIFT_WIDGET_HTML + "<script>" + ONHIT_SHIFT_WIDGET_JS + "</script>"


