# ==========================================
# [ 6zz3. Warp Points (จุดรับส่ง) — เทเลพอร์ตพร้อมเอฟเฟกต์เส้นแสงพุ่ง (dash trail)
#          + ประตูข้ามเกม (ต่อยอดจาก npc_cross_game_travel เดิมที่ [ 6zz2 ]) ]
# กติกา:
#   - ผู้เล่น/แอดมิน "ปัก" จุดรับส่งได้ตรงไหนก็ได้ในโลก (ผ่าน API หรือคลิกบนหน้า
#     /map) แต่ละจุดมีชื่อ+ตำแหน่ง+สีเส้นแสง
#   - เทเลพอร์ต: server เป็นคนย้ายพิกัด pawn จริง (authoritative เหมือนระบบ
#     player_input เดิมที่ [ 2b9d ] — ไม่ใช่ client ส่งพิกัดเองตรงๆ กันโกง)
#     แล้วส่ง event 'warp_teleport' บอกจุดเริ่ม/จุดจบ+สี ให้ client เล่นแอนิเมชัน
#     เส้นแสงพุ่งจากจุดเดิมไปจุดใหม่เอง (แบบในคลิปตัวอย่าง Immersive Combat)
#   - ประตูข้ามเกม: ถ้าจุดรับส่งตั้ง target_game_id ไว้ (เกมใน LAUNCHER_CATALOG
#     ของฮับนี้เอง หรือ source ภายนอกที่เชื่อมผ่าน Cross-Engine Bridge อยู่ตอนนี้
#     — เกณฑ์เดียวกับที่ _npc_connected_game_ids ใช้) การเทเลพอร์ตจะ "ย้ายผู้เล่น
#     ข้ามเกม" ด้วย โดยอัปเดต PLAYER_GAME_LOCATION แล้วยิง bridge event
#     'player_arrived' ไปเกมปลายทาง — เป็นกลไกเดียวกับที่ NPC เดินทางข้ามเกมอยู่
#     แล้ว เพียงแค่ใช้กับผู้เล่นจริงแทน NPC
# ==========================================
WARP_POINTS = {}   # warp_id -> {id, name, x, y, icon, trail_color, effect, target_game_id, created_at}
WARP_TRAIL_DEFAULT_COLOR = "#39cfff"
WARP_TRAIL_DURATION_MS = 900     # นานเท่าเอฟเฟกต์ ก่อนตัวละครโผล่ที่ปลายทางจริง
PLAYER_GAME_LOCATION = {}  # uid -> game_id ที่ผู้เล่นคนนั้น "อยู่" ตอนนี้ (default CURRENT_GAME_ID)

# แต่ละจุดรับส่งเลือก "ธีมเอฟเฟกต์" ตอนเทเลพอร์ตได้ไม่เหมือนกัน — ไม่ใช่แค่เส้น
# แสงพุ่งอย่างเดียว บางจุดจะเป็นมังกรพุ่งข้ามจอ บางจุดเป็นสายฟ้า/วงแหวนพอร์ทัล
# ฯลฯ ถ้าไม่ระบุตอนสร้างจุด จะสุ่มเลือกให้เอง (เพื่อให้แต่ละจุดดูมีเอกลักษณ์ต่าง
# กันโดยอัตโนมัติ ไม่ต้องมานั่งเลือกเองทุกจุด) ฝั่ง client (widget warp-effects
# ด้านล่าง) เป็นคนตีความ key เหล่านี้แล้ววาดแอนิเมชันจริงตามธีม
WARP_EFFECTS = {
    "light_trail": {"label": "เส้นแสงพุ่ง",     "emoji": "💫"},
    "dragon":      {"label": "มังกรพุ่งข้าม",    "emoji": "🐉"},
    "phoenix":     {"label": "หงส์ไฟทะยาน",     "emoji": "🔥"},
    "lightning":   {"label": "สายฟ้าฟาด",       "emoji": "⚡"},
    "portal_ring": {"label": "วงแหวนพอร์ทัล",    "emoji": "🌀"},
    "star_burst":  {"label": "ระเบิดดวงดาว",     "emoji": "✨"},
    "wind_slash":  {"label": "ตัดสายลม",        "emoji": "🌪️"},
}


def _sid_for_uid(uid: str):
    """หา sid (socket session) ปัจจุบันของ uid นี้ จาก PLAYERS ที่ connect อยู่ —
    คืน None ถ้าผู้เล่นคนนี้ไม่ได้เชื่อมต่ออยู่ตอนนี้"""
    for sid, p in PLAYERS.items():
        if p.get("uid") == uid:
            return sid
    return None


@app.route('/api/warp/effects')
def api_warp_effects():
    """รายชื่อธีมเอฟเฟกต์ที่เลือกได้ตอนสร้างจุดรับส่ง (ให้ UI ทำเป็น dropdown/
    ตัวเลือกได้เลย)"""
    return jsonify({"st": "ok", "effects": WARP_EFFECTS})


@app.route('/api/warp/points', methods=['GET', 'POST'])
@require_auth_toggleable
def api_warp_points():
    """GET -> รายชื่อจุดรับส่งทั้งหมด
    POST body: {name, x, y, icon?, trail_color?, effect?, target_game_id?} -> สร้างจุดใหม่
    effect ต้องเป็นหนึ่งใน WARP_EFFECTS (ดู /api/warp/effects) — ไม่ระบุ = สุ่มให้
    เอง เพื่อให้แต่ละจุดมีเอกลักษณ์ไม่ซ้ำกัน ใส่ target_game_id ด้วยถ้าอยากให้จุดนี้
    เป็น 'ประตูข้ามเกม' ไปเกมอื่นในฮับ/ที่เชื่อม bridge อยู่"""
    if request.method == 'POST':
        body = request.json or {}
        name = (body.get('name') or '').strip()
        if not name:
            return jsonify({"st": "error", "msg": "ต้องระบุชื่อจุดรับส่ง"}), 400
        effect = (body.get('effect') or '').strip()
        if effect and effect not in WARP_EFFECTS:
            return jsonify({"st": "error",
                            "msg": f"ไม่รู้จักเอฟเฟกต์ '{effect}' — ดูรายชื่อที่ใช้ได้ที่ /api/warp/effects"}), 400
        if not effect:
            effect = random.choice(list(WARP_EFFECTS.keys()))
        wid = uuid.uuid4().hex[:8]
        WARP_POINTS[wid] = {
            "id": wid, "name": name,
            "x": float(body.get('x', 0)), "y": float(body.get('y', 0)),
            "icon": body.get('icon', WARP_EFFECTS[effect]["emoji"]),
            "trail_color": body.get('trail_color', WARP_TRAIL_DEFAULT_COLOR),
            "effect": effect,
            "target_game_id": (body.get('target_game_id') or '').strip() or None,
            "created_at": time.time(),
        }
        return jsonify({"st": "ok", "warp": WARP_POINTS[wid]})
    return jsonify({"st": "ok", "points": list(WARP_POINTS.values())})


@app.route('/api/warp/points/<wid>', methods=['DELETE'])
@require_auth_toggleable
def api_warp_delete(wid):
    if wid not in WARP_POINTS:
        return jsonify({"st": "error", "msg": "ไม่พบจุดรับส่งนี้"}), 404
    WARP_POINTS.pop(wid)
    return jsonify({"st": "ok"})


@app.route('/api/warp/teleport', methods=['POST'])
@require_auth_toggleable
def api_warp_teleport():
    """body: {uid, warp_id}
    ย้ายตำแหน่งผู้เล่นจริง (authoritative) ไปจุดรับส่งที่ระบุ พร้อมส่ง
    'warp_teleport' ให้ client เล่นเอฟเฟกต์เส้นแสงพุ่ง — ถ้าจุดนั้นมี
    target_game_id จะพาผู้เล่นข้ามเกมไปด้วย (ดู docstring ของหัวข้อด้านบน)"""
    body = request.json or {}
    uid = body.get('uid', '')
    warp_id = body.get('warp_id', '')
    if not uid or not warp_id:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid และ warp_id"}), 400
    warp = WARP_POINTS.get(warp_id)
    if not warp:
        return jsonify({"st": "error", "msg": "ไม่พบจุดรับส่งนี้"}), 404
    sid = _sid_for_uid(uid)
    if not sid or sid not in PLAYER_PAWNS:
        return jsonify({"st": "error", "msg": "ไม่พบผู้เล่นที่กำลังเชื่อมต่ออยู่ตอนนี้"}), 404

    pawn = PLAYER_PAWNS[sid]
    from_x, from_y = pawn["x"], pawn["y"]
    pawn["x"], pawn["y"] = warp["x"], warp["y"]
    if sid in PLAYERS:
        PLAYERS[sid]["x"], PLAYERS[sid]["y"] = warp["x"], warp["y"]

    trail_payload = {
        "warp_id": warp_id, "warp_name": warp["name"],
        "from": {"x": from_x, "y": from_y}, "to": {"x": warp["x"], "y": warp["y"]},
        "trail_color": warp["trail_color"], "duration_ms": WARP_TRAIL_DURATION_MS,
        "effect": warp.get("effect", "light_trail"),
        "effect_emoji": WARP_EFFECTS.get(warp.get("effect", "light_trail"), {}).get("emoji", "💫"),
    }
    sio.emit('warp_teleport', trail_payload, room=uid)
    result = {"st": "ok", "teleported_to": {"x": warp["x"], "y": warp["y"]}, "trail": trail_payload}

    target_game_id = warp.get("target_game_id")
    if target_game_id:
        prev_game = PLAYER_GAME_LOCATION.get(uid, CURRENT_GAME_ID)
        PLAYER_GAME_LOCATION[uid] = target_game_id
        bridge_push_event(target_game_id, "player_arrived",
                          {"uid": uid, "from_game_id": prev_game, "warp_name": warp["name"]})
        sio.emit('player_cross_game_travel', {"uid": uid, "game_id": target_game_id}, room=sid)
        result["cross_game"] = {"from_game_id": prev_game, "to_game_id": target_game_id}
        lore_name = CHARACTER_LORE.get("name") or "นักเดินทาง"
        result["narrator"] = f"{lore_name} พาไปโผล่อีกฟากของประตู — เกม '{target_game_id}' รออยู่แล้ว"
    return jsonify(result)


VMAX_MODULES["warp_points_cross_game"] = {
    "desc": "จุดรับส่ง (warp points) ปักตำแหน่งเองได้ เทเลพอร์ตแบบ authoritative พร้อมส่ง event "
            "ให้ client เล่นเอฟเฟกต์ที่ 'ไม่เหมือนกันในแต่ละจุด' — เลือกธีมได้จาก WARP_EFFECTS "
            "(เส้นแสงพุ่ง/มังกร/หงส์ไฟ/สายฟ้า/วงแหวนพอร์ทัล/ระเบิดดาว/ตัดสายลม) หรือปล่อยให้สุ่มเอง "
            "ก็ได้ ดูตัวอย่างจริงที่ widget warp-effects (6zz3b) — ตั้ง target_game_id ให้จุดไหนก็ได้ "
            "เพื่อทำเป็น 'ประตูข้ามเกม' ไปเกมอื่นในฮับ/ที่เชื่อม bridge อยู่ ต่อยอดจาก "
            "npc_cross_game_travel (6zz2) มาใช้กับผู้เล่นจริง แสดงบน /map ได้เลย (แก้ api_map_export "
            "แล้ว) พร้อมคลิกบนแผนที่เพื่อปัก/ใช้จุดรับส่งได้ตรงๆ",
    "routes": ["/api/warp/points", "/api/warp/points/<wid>", "/api/warp/teleport", "/api/warp/effects"],
}


# ==========================================
# [ 6zz4. Traveler Character Lore — เนื้อเรื่อง/ประวัติตัวละครผู้เดินทางข้ามเกม ]
# ผูกกับระบบ warp/cross-game ด้านบน: ตัวละครนี้คือคนที่ "เดินทาง" ผ่านจุดรับส่ง
# ข้ามเกมต่างๆ ไปเรื่อยๆ (คล้ายแนวคิดเดียวกับ NPC เดินทางข้ามเกมที่ [ 6zz2 ] แต่
# อันนี้เป็นตัวละครหลัก/เนื้อเรื่องของผู้เล่น ไม่ใช่ NPC ฟีดแบ็ก) เก็บเป็น global
# lore ก้อนเดียว แก้ไข/ตั้งชื่อเองได้ผ่าน API ไม่ hardcode ชื่อไว้ตายตัว
# ==========================================
CHARACTER_LORE = {
    "name": "",   # ยังไม่ตั้งชื่อ — ตั้งได้ผ่าน POST /api/character/lore {"name": "..."}
    "bio": (
        "His journey started at Maekhajon Chiang Mai back in 2017, followed by a move to "
        "Rampingwittaya in 2023. Life threw tough challenges his way—both in his studies and "
        "his health—forcing him to step away from formal schooling. But don't let his chronic "
        "illness fool you; he is a tech enthusiast with a deep interest in programming and a "
        "jack-of-all-trades who can master just about anything he sets his mind to."
    ),
    "timeline": [
        {"year": 2017, "event": "เริ่มต้นเส้นทางที่ Maekhajon เชียงใหม่"},
        {"year": 2023, "event": "ย้ายไปเรียนต่อที่ Rampingwittaya"},
    ],
    "traits": ["tech enthusiast", "programming", "jack-of-all-trades"],
    "updated_at": time.time(),
}


@app.route('/api/character/lore', methods=['GET', 'POST'])
@require_auth_toggleable
def api_character_lore():
    """GET -> เนื้อเรื่อง/ประวัติตัวละครปัจจุบันทั้งหมด
    POST body: {name?, bio?, timeline?, traits?} -> แก้ไขเฉพาะฟิลด์ที่ส่งมา
    (timeline เป็น list ของ {year, event}, traits เป็น list ของ string)"""
    if request.method == 'POST':
        body = request.json or {}
        for key in ("name", "bio", "timeline", "traits"):
            if key in body:
                CHARACTER_LORE[key] = body[key]
        CHARACTER_LORE["updated_at"] = time.time()
        return jsonify({"st": "ok", "lore": CHARACTER_LORE})
    return jsonify({"st": "ok", "lore": CHARACTER_LORE})


