MOTION_SETTINGS_WIDGET_JS = """
// ==========================================
// ---- Weapon Sway + Motion/Gyro Aiming (client-side, ใช้ได้อิสระทุกเกม) ----
// อ่านค่าตั้งต้นจาก window.VMAX_MOTION_CONFIG ถ้ามี ผูกกับ uid ใน localStorage
// (key 'vmax_uid') เพื่อจำการตั้งค่าไว้ข้ามเกม เหมือน widget อื่นๆ
// ==========================================
let mtnCfg = Object.assign({
    swayEnabled: true,
    swayIntensity: 50,     // 0-100%
    swayType: 'breathing', // 'breathing' | 'movement'
    gyroEnabled: false,
    gyroSensitivity: 50    // 0-100%
}, window.VMAX_MOTION_CONFIG || {});

// เกมตัวเองอ่านค่าเหล่านี้ทุกเฟรมแล้วบวกเข้ากับ view model / กล้องของตัวเอง
window.VMAX_SWAY_OFFSET = { x: 0, y: 0 };
window.VMAX_GYRO_DELTA  = { dx: 0, dy: 0 };
window.VMAX_MOTION_MOVING = false; // เกมตั้งค่านี้เป็น true ตอนผู้เล่นกดปุ่มเดิน เพื่อให้ sway แบบ Movement ทำงานถูกจังหวะ

function _mtnUid() { return localStorage.getItem('vmax_uid'); }

// ---------- Weapon Sway ----------
let _mtnSwayStartTime = Date.now();

function _mtnSwayLoop() {
    if (mtnCfg.swayEnabled) {
        const t = (Date.now() - _mtnSwayStartTime) / 1000;
        const amp = (mtnCfg.swayIntensity / 100) * 6; // px สูงสุดโดยประมาณที่ความแรง 100%
        if (mtnCfg.swayType === 'movement' && window.VMAX_MOTION_MOVING) {
            // จังหวะเดิน: ความถี่สูงกว่า breathing ชัดเจน
            window.VMAX_SWAY_OFFSET.x = Math.sin(t * 6.0) * amp;
            window.VMAX_SWAY_OFFSET.y = Math.abs(Math.sin(t * 12.0)) * amp * 0.6;
        } else {
            // จังหวะหายใจ (ค่าเริ่มต้น หรือ ตอนยืนนิ่งแม้เลือก Movement ไว้)
            window.VMAX_SWAY_OFFSET.x = Math.sin(t * 1.2) * amp;
            window.VMAX_SWAY_OFFSET.y = Math.sin(t * 0.8) * amp * 0.5;
        }
    } else {
        window.VMAX_SWAY_OFFSET.x = 0;
        window.VMAX_SWAY_OFFSET.y = 0;
    }
    requestAnimationFrame(_mtnSwayLoop);
}
requestAnimationFrame(_mtnSwayLoop);

function mtnSetSwayEnabled(v) {
    mtnCfg.swayEnabled = v;
    mtnSavePrefs();
}
function mtnSetSwayIntensity(v) {
    mtnCfg.swayIntensity = parseInt(v, 10);
    const el = document.getElementById('mtn_sway_intensity_val');
    if (el) el.textContent = mtnCfg.swayIntensity + '%';
    mtnSavePrefs();
}
function mtnSetSwayType(v) {
    mtnCfg.swayType = v;
    mtnSavePrefs();
}

// ---------- Motion / Gyro Aiming ----------
// อ่านค่า orientation จาก sensor ของอุปกรณ์ผู้เล่นเอง (เบราว์เซอร์ตัวเอง) เท่านั้น —
// ไม่ใช่การอ่านหรือแทรกแซง input/process ของเกมหรืออุปกรณ์อื่นใด
let _mtnGyroBaseline = null;
let _mtnGyroActive = false;

function _mtnHandleOrientation(e) {
    if (!mtnCfg.gyroEnabled) return;
    const gamma = e.gamma || 0; // ซ้าย-ขวา (-90..90)
    const beta  = e.beta  || 0; // หน้า-หลัง (-180..180)
    if (_mtnGyroBaseline === null) {
        _mtnGyroBaseline = { gamma, beta }; // จุดเริ่มต้น = ท่าที่ผู้เล่นถือตอนเปิดโหมดนี้
        return;
    }
    const sens = (mtnCfg.gyroSensitivity / 100) * 4; // ตัวคูณความไว
    window.VMAX_GYRO_DELTA.dx = (gamma - _mtnGyroBaseline.gamma) * sens;
    window.VMAX_GYRO_DELTA.dy = (beta  - _mtnGyroBaseline.beta)  * sens;
}

function mtnRequestGyroPermission() {
    const statusLine = document.getElementById('mtn_gyro_status_line');
    const finish = (ok, msg) => { if (statusLine) statusLine.textContent = 'สถานะ: ' + (ok ? '🟢 ' : '🔴 ') + msg; };

    if (typeof DeviceOrientationEvent !== 'undefined' &&
        typeof DeviceOrientationEvent.requestPermission === 'function') {
        // iOS 13+ ต้องขอ permission จาก user gesture โดยตรง (ปุ่มนี้)
        DeviceOrientationEvent.requestPermission().then(state => {
            if (state === 'granted') {
                _mtnGyroBaseline = null;
                window.addEventListener('deviceorientation', _mtnHandleOrientation);
                _mtnGyroActive = true;
                finish(true, 'ใช้งานไจโรสโคปแล้ว');
            } else {
                finish(false, 'ผู้เล่นไม่อนุญาตสิทธิ์เซนเซอร์');
            }
        }).catch(() => finish(false, 'ขอสิทธิ์ไม่สำเร็จ'));
    } else if (typeof DeviceOrientationEvent !== 'undefined') {
        // เบราว์เซอร์/แพลตฟอร์มอื่นที่ไม่ต้องขอ permission แยก
        _mtnGyroBaseline = null;
        window.addEventListener('deviceorientation', _mtnHandleOrientation);
        _mtnGyroActive = true;
        finish(true, 'ใช้งานไจโรสโคปแล้ว');
    } else {
        finish(false, 'อุปกรณ์นี้ไม่รองรับไจโรสโคป');
    }
}

function mtnSetGyroEnabled(v) {
    mtnCfg.gyroEnabled = v;
    if (v && !_mtnGyroActive) mtnRequestGyroPermission();
    if (!v) { window.VMAX_GYRO_DELTA.dx = 0; window.VMAX_GYRO_DELTA.dy = 0; }
    mtnSavePrefs();
}
function mtnSetGyroSensitivity(v) {
    mtnCfg.gyroSensitivity = parseInt(v, 10);
    const el = document.getElementById('mtn_gyro_sens_val');
    if (el) el.textContent = mtnCfg.gyroSensitivity + '%';
    mtnSavePrefs();
}

// ---------- Panel + persistence ----------
function toggleMotionSettingsPanel() {
    const panel = document.getElementById('mtn_panel');
    if (!panel) return;
    panel.style.display = (panel.style.display === 'none' || !panel.style.display) ? 'block' : 'none';
    if (panel.style.display === 'block') mtnLoadPrefs();
}

function mtnApplyToUI() {
    const swayChk = document.getElementById('mtn_sway_enabled');
    const swayInt = document.getElementById('mtn_sway_intensity');
    const swayIntVal = document.getElementById('mtn_sway_intensity_val');
    const swayType = document.getElementById('mtn_sway_type');
    const gyroChk = document.getElementById('mtn_gyro_enabled');
    const gyroSens = document.getElementById('mtn_gyro_sensitivity');
    const gyroSensVal = document.getElementById('mtn_gyro_sens_val');
    if (swayChk) swayChk.checked = mtnCfg.swayEnabled;
    if (swayInt) swayInt.value = mtnCfg.swayIntensity;
    if (swayIntVal) swayIntVal.textContent = mtnCfg.swayIntensity + '%';
    if (swayType) swayType.value = mtnCfg.swayType;
    if (gyroChk) gyroChk.checked = mtnCfg.gyroEnabled;
    if (gyroSens) gyroSens.value = mtnCfg.gyroSensitivity;
    if (gyroSensVal) gyroSensVal.textContent = mtnCfg.gyroSensitivity + '%';
}

async function mtnSavePrefs() {
    mtnApplyToUI();
    const uid = _mtnUid();
    if (!uid) return; // ไม่มี uid ก็ยังใช้ได้ปกติ แค่ไม่จำข้าม session
    try {
        await fetch('/api/motion-settings/prefs', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ uid, prefs: mtnCfg })
        });
    } catch (e) { console.warn('[motion-settings] บันทึกค่าไม่สำเร็จ:', e); }
}

async function mtnLoadPrefs() {
    const uid = _mtnUid();
    if (!uid) { mtnApplyToUI(); return; }
    try {
        const r = await fetch('/api/motion-settings/prefs?uid=' + encodeURIComponent(uid));
        const data = await r.json();
        if (data && data.prefs) {
            mtnCfg = Object.assign(mtnCfg, data.prefs);
        }
    } catch (e) { console.warn('[motion-settings] โหลดค่าไม่สำเร็จ:', e); }
    mtnApplyToUI();
}

mtnLoadPrefs();
"""


# ==========================================
# [ 6z-b. Motion Settings Widget — ฝั่งเซิร์ฟเวอร์ ]
# เก็บแค่ preference ต่อผู้เล่น (sway/gyro on-off, intensity, type) ข้ามเกม/session —
# งานหลัก (คำนวณ sway offset, อ่าน deviceorientation) ทำฝั่ง client ล้วนๆ ด้านบน
# เหมือน POWER_SAVER_PLAYER_PREFS / KEYBOARD prefs
# ==========================================
MOTION_SETTINGS_PLAYER_PREFS = {}  # uid -> {swayEnabled, swayIntensity, swayType, gyroEnabled, gyroSensitivity}


@app.route('/api/motion-settings/prefs', methods=['GET', 'POST'])
@require_auth_toggleable
def api_motion_settings_prefs():
    """GET ?uid=xxx -> คืนค่า preference (weapon sway + gyro aim) ที่ผู้เล่นตั้งไว้ล่าสุด
    POST body: {uid, prefs: {swayEnabled, swayIntensity, swayType, gyroEnabled, gyroSensitivity}} -> บันทึกทับของเดิม"""
    if request.method == 'POST':
        body = request.json or {}
        uid = body.get('uid', '')
        if not uid:
            return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
        prefs = body.get('prefs') or {}
        MOTION_SETTINGS_PLAYER_PREFS[uid] = prefs
        return jsonify({"st": "ok", "uid": uid, "prefs": prefs})
    uid = request.args.get('uid', '')
    return jsonify({"st": "ok", "uid": uid, "prefs": MOTION_SETTINGS_PLAYER_PREFS.get(uid)})


@app.route('/widgets/motion-settings')
def widget_motion_settings():
    """widget ตั้งค่า Weapon Sway + Motion/Gyro Aiming — ฝังแบบเดียวกับ widget อื่นๆ:
        window.VMAX_MOTION_CONFIG = { swayIntensity: 40, gyroEnabled: true };
        fetch('/widgets/motion-settings').then(r => r.text())
            .then(html => document.body.insertAdjacentHTML('beforeend', html));
    เกมอ่าน window.VMAX_SWAY_OFFSET / window.VMAX_GYRO_DELTA ทุกเฟรมแล้วบวกเข้ากับ
    view model / กล้องของตัวเอง (ดู VMAX_MOTION_MOVING สำหรับสลับจังหวะ sway ตอนเดิน)"""
    return MOTION_SETTINGS_WIDGET_HTML + "<script>" + MOTION_SETTINGS_WIDGET_JS + "</script>"


VMAX_MODULES["motion_settings_widget"] = {
    "desc": "แผงตั้งค่า Weapon Sway (ส่ายตามหายใจ/เดิน ปรับความแรง 0-100%) และ Motion/Gyro Aiming "
            "(เล็งด้วยการเอียงเครื่องผ่านไจโรสโคปของอุปกรณ์ผู้เล่นเอง) พร้อมจำค่าไว้ข้ามเกม/session",
    "routes": ["/widgets/motion-settings", "/api/motion-settings/prefs"],
}


# ==========================================
# [ 6z-c. Background Thread Watchdog ]
# เฝ้าดู background thread หลักทั้งหมด (tele_loop, physics_loop, physics_sync_loop,
# background_analyst_loop, banquet_minigame_loop) — ถ้า thread ไหนตายกลางทาง (crash
# จาก exception ที่ loop เดิมไม่ได้ดักไว้) watchdog จะ log ไว้ + spawn thread ใหม่แทนที่
# ให้อัตโนมัติทันที ไม่ต้อง restart ทั้งแอป เช็คทุก WATCHDOG_INTERVAL_SEC วินาที
# ดูสถานะสดได้ที่ GET /api/watchdog/status (alive/ตาย, restart กี่ครั้ง, เวลาล่าสุด)
# ==========================================
WATCHDOG_INTERVAL_SEC = 5
WATCHDOG_REGISTRY = {}   # name -> {"target", "args", "thread", "restarts", "last_start_ts", "last_alive_ts"}

def watchdog_register_thread(name, target, args=()):
    """สร้าง + สตาร์ท daemon thread ตัวหนึ่ง แล้วขึ้นทะเบียนไว้ให้ watchdog_loop คอยเฝ้า
    (ใช้แทน threading.Thread(...).start() ตรงๆ สำหรับ loop หลักที่อยากให้มี watchdog คุ้มครอง)"""
    th = threading.Thread(target=target, args=args, daemon=True)
    th.start()
    entry = WATCHDOG_REGISTRY.get(name, {"restarts": 0})
    entry.update({
        "target": target, "args": args, "thread": th,
        "last_start_ts": time.time(), "last_alive_ts": time.time(),
    })
    WATCHDOG_REGISTRY[name] = entry
    return th

def watchdog_loop():
    """รันเป็น daemon thread แยกต่างหาก คอยวนเช็คทุก WATCHDOG_INTERVAL_SEC วิ ว่า
    thread ที่ขึ้นทะเบียนไว้ (ผ่าน watchdog_register_thread) ยัง is_alive() อยู่ไหม
    ถ้าตัวไหนตายไปแล้ว — log ไว้ + spawn thread ใหม่มาแทนที่ทันที นับจำนวน restart ไว้ด้วย"""
    while True:
        time.sleep(WATCHDOG_INTERVAL_SEC)
        for name, entry in list(WATCHDOG_REGISTRY.items()):
            th = entry.get("thread")
            if th is not None and th.is_alive():
                entry["last_alive_ts"] = time.time()
                continue
            entry["restarts"] = entry.get("restarts", 0) + 1
            print(f"[Watchdog] ⚠️  thread '{name}' ตายไปแล้ว (restart ครั้งที่ {entry['restarts']}) "
                  f"— กำลังสตาร์ทใหม่ให้อัตโนมัติ...")
            new_th = threading.Thread(target=entry["target"], args=entry.get("args", ()), daemon=True)
            new_th.start()
            entry["thread"] = new_th
            entry["last_start_ts"] = time.time()
            entry["last_alive_ts"] = time.time()

@app.route('/api/watchdog/status')
def api_watchdog_status():
    """สถานะ background thread หลักทั้งหมดที่ watchdog กำลังเฝ้าอยู่ — ใช้ตรวจว่าตัวไหน
    ยัง alive อยู่ตอนนี้ไหม และเคยตาย/ถูกรีสตาร์ทไปแล้วกี่ครั้ง"""
    out = {}
    for name, entry in WATCHDOG_REGISTRY.items():
        th = entry.get("thread")
        out[name] = {
            "alive": bool(th and th.is_alive()),
            "restarts": entry.get("restarts", 0),
            "last_start_ts": entry.get("last_start_ts"),
            "last_alive_ts": entry.get("last_alive_ts"),
        }
    return jsonify({"st": "ok", "interval_sec": WATCHDOG_INTERVAL_SEC, "threads": out})

VMAX_MODULES["thread_watchdog"] = {
    "desc": "เฝ้า background thread หลัก (tele/physics/physics_sync/analyst_ai/banquet) "
            "ถ้าตัวไหนตายกลางทางจะ spawn ใหม่ให้อัตโนมัติ พร้อมนับจำนวนครั้งที่ตาย/รีสตาร์ท",
    "routes": ["/api/watchdog/status"],
}


# ==========================================
# [ 6zz5. Survival Base-Building Suite — สมาร์ทคอร์/คราฟต์/ซ่อม/หลอม/สโตร์/
#   เพื่อน-ของขวัญ/กระดานผู้นำโซนสงคราม/ชุดเสบียง/เมคา/แผนที่ฐานที่มั่น/กราฟิก ]
# เพิ่มระบบเกมทั้งชุดตามภาพหน้าจอเกมแนว extraction-survival ที่แนบมา (ธีม
# สมาร์ทคอร์ + ก่อสร้าง + คราฟต์ + โซนสงคราม) โดยยึดรูปแบบเดียวกับโมดูลอื่นในไฟล์
# นี้ทั้งหมด: เก็บ state ต่อผู้เล่นด้วย dict ธรรมดา (ไม่ใช่ DB จริง), เปิด
# endpoint ผ่าน @app.route คืนค่าเป็น jsonify, แล้วขึ้นทะเบียนแต่ละระบบย่อยไว้ใน
# VMAX_MODULES ให้ค้นเจอจาก /api ทั่วไปเหมือนโมดูลอื่นๆ
# ==========================================

# ---------- [ 6zz5a. สมาร์ทคอร์ (Smart Core) — เลเวลฐาน/อัปเกรดสิ่งก่อสร้าง ] ----
# ตรงกับภาพ "สมาร์ทคอร์" (ข้อมูลสมาร์ทคอร์ / อัปเกรดสิ่งก่อสร้าง / ซ่อมแซมสิ่งก่อสร้าง)
# เลเวลฐานขยับตาม "คะแนนสำรวจ" ที่สะสมได้ (สำรวจแผนที่/ทำภารกิจ) ไม่ใช่ exp ปกติ
# และมีขีดจำกัดจำนวนสิ่งก่อสร้างที่วางได้ต่อหมวด (ฐาน/สิ่งก่อสร้าง/สิ่งอำนวยความสะดวก)
SMART_CORE_UPGRADE_MATERIALS = ("stone", "iron", "metal")  # หิน / ไอรอน / โลหะ — ลำดับความสำคัญ: ฐาน > กำแพง > ประตู > พื้น > อื่นๆ
SMART_CORE_STRUCTURE_PRIORITY = ["base", "wall", "door", "floor", "other"]

SMART_CORE_LEVEL_REQ = {lvl: lvl * 1200 for lvl in range(1, 21)}  # คะแนนสำรวจที่ต้องใช้ต่อเลเวล (1200 * เลเวล)
SMART_CORE_LEVEL_LIMITS = {  # ขีดจำกัดจำนวนสิ่งก่อสร้างที่วางพร้อมกันได้ ตามเลเวลสมาร์ทคอร์
    lvl: {"base": 10 + lvl * 3, "structure": 200 + lvl * 60, "furniture": 5 + lvl * 4}
    for lvl in range(1, 21)
}
SMART_CORE_STATE = {}  # uid -> {"level", "survey_points", "material": "stone"|"iron"|"metal"}

def smartcore_get(uid: str) -> dict:
    return SMART_CORE_STATE.setdefault(uid, {"level": 1, "survey_points": 0, "material": "stone"})

def smartcore_progress(uid: str) -> dict:
    st = smartcore_get(uid)
    lvl = st["level"]
    need = SMART_CORE_LEVEL_REQ.get(lvl, lvl * 1200)
    limits = SMART_CORE_LEVEL_LIMITS.get(lvl, SMART_CORE_LEVEL_LIMITS[20])
    return {"uid": uid, "level": lvl, "survey_points": st["survey_points"], "survey_points_needed": need,
            "survey_points_to_next": max(0, need - st["survey_points"]), "limits": limits,
            "upgrade_material": st["material"]}

@app.route('/api/smartcore/state')
def api_smartcore_state():
    """?uid=xxx -> เลเวลสมาร์ทคอร์ปัจจุบัน, คะแนนสำรวจ, ขีดจำกัดสิ่งก่อสร้างแต่ละหมวด"""
    return jsonify({"st": "ok", **smartcore_progress(request.args.get("uid", ""))})

@app.route('/api/smartcore/add_survey', methods=['POST'])
@require_auth
def api_smartcore_add_survey():
    """body: {points} -> บวกคะแนนสำรวจ (ได้จากภารกิจข่าวกรอง/สำรวจแผนที่) เข้าสมาร์ทคอร์
    [BUG-FIX #20] เดิมรับ points จาก client มาบวกตรงๆ ไม่มีขีดจำกัด — ส่ง points:
    999999999 มาเองได้เลย = อัปเลเวลสมาร์ทคอร์ข้ามขั้นฟรี แก้โดยจำกัดค่าให้อยู่ในช่วง
    ที่สมเหตุสมผลต่อการเรียกหนึ่งครั้ง (เท่ากับรางวัลภารกิจข่าวกรองมาตรฐาน) และห้ามติดลบ
    [BUG-FIX #21] เดิมรับ uid จาก body ตรงๆ (สวมรอยเป็นใครก็ได้) — เพิ่ม @require_auth
    แล้วใช้ uid จาก JWT session แทน ไม่เชื่อ uid ที่ client ส่งมาอีกต่อไป"""
    body = request.json or {}
    uid = request.vmax_uid
    try:
        points = int(body.get("points", 0))
    except (TypeError, ValueError):
        return jsonify({"st": "error", "msg": "points ต้องเป็นตัวเลข"}), 400
    points = max(0, min(points, INTEL_MISSION_REWARD_SURVEY_POINTS))
    st = smartcore_get(uid)
    st["survey_points"] += points
    return jsonify({"st": "ok", **smartcore_progress(uid)})

@app.route('/api/smartcore/upgrade', methods=['POST'])
@require_auth_toggleable
def api_smartcore_upgrade():
    """body: {uid} -> อัปเกรดเลเวลสมาร์ทคอร์ ถ้าคะแนนสำรวจครบตามที่กำหนด (คะแนนที่เกินจะพกไปเลเวลถัดไป)"""
    body = request.json or {}
    uid = body.get("uid", "")
    st = smartcore_get(uid)
    need = SMART_CORE_LEVEL_REQ.get(st["level"], st["level"] * 1200)
    if st["survey_points"] < need:
        return jsonify({"st": "error", "msg": f"คะแนนสำรวจไม่พอ ({st['survey_points']}/{need})"}), 400
    st["survey_points"] -= need
    st["level"] += 1
    return jsonify({"st": "ok", "msg": f"อัปเกรดสมาร์ทคอร์เป็นเลเวล {st['level']} สำเร็จ", **smartcore_progress(uid)})

@app.route('/api/smartcore/set_upgrade_material', methods=['POST'])
@require_auth_toggleable
def api_smartcore_set_material():
    """body: {uid, material: stone|iron|metal} -> เลือกวัสดุที่จะใช้อัปเกรด/สร้างสิ่งก่อสร้างรอบถัดไป
    (แผงซ้ายในภาพ 'อัปเกรดสิ่งก่อสร้าง' ให้เลือกได้สามแบบ: หิน / ไอรอน / โลหะ)"""
    body = request.json or {}
    uid = body.get("uid", "")
    material = body.get("material", "stone")
    if material not in SMART_CORE_UPGRADE_MATERIALS:
        return jsonify({"st": "error", "msg": f"material ต้องเป็นหนึ่งใน {SMART_CORE_UPGRADE_MATERIALS}"}), 400
    smartcore_get(uid)["material"] = material
    return jsonify({"st": "ok", **smartcore_progress(uid)})

VMAX_MODULES["smart_core"] = {
    "desc": "ระบบเลเวลฐาน 'สมาร์ทคอร์' — อัปเกรดด้วยคะแนนสำรวจ, เลือกวัสดุอัปเกรดสิ่งก่อสร้าง "
            "(หิน/ไอรอน/โลหะ ตามลำดับความสำคัญ ฐาน>กำแพง>ประตู>พื้น>อื่นๆ), ขีดจำกัดจำนวนสิ่งก่อสร้างต่อเลเวล",
    "routes": ["/api/smartcore/state", "/api/smartcore/add_survey", "/api/smartcore/upgrade",
               "/api/smartcore/set_upgrade_material"],
}


# ---------- [ 6zz5b. กล่องเก็บของ (Storage Box) + กระเป๋าเป้ (Backpack) ] --------
# ตรงกับภาพ "กล่องเก็บของ" — สองช่องแยกกัน: กระเป๋าเป้ (พกติดตัว, หายได้ตอนตาย/
# ถอนกำลังไม่ทัน) กับ กล่องเก็บของ (ของฝากไว้ที่ฐาน ปลอดภัยกว่า) ทั้งคู่มี slot จำกัด
STORAGE_SLOTS_DEFAULT = 40
PLAYER_STORAGE = {}  # uid -> {"backpack": {slot_idx(str): {"item","qty"}}, "storage_box": {...}, "backpack_slots", "storage_slots"}

def storage_get(uid: str) -> dict:
    return PLAYER_STORAGE.setdefault(uid, {
        "backpack": {}, "storage_box": {},
        "backpack_slots": STORAGE_SLOTS_DEFAULT, "storage_slots": STORAGE_SLOTS_DEFAULT,
    })

def _storage_container(state: dict, which: str) -> dict:
    return state["backpack"] if which == "backpack" else state["storage_box"]

@app.route('/api/storage/state')
def api_storage_state():
    """?uid=xxx -> เนื้อหากระเป๋าเป้ + กล่องเก็บของทั้งหมด พร้อมจำนวน slot ที่ใช้ไป/ทั้งหมด"""
    uid = request.args.get("uid", "")
    st = storage_get(uid)
    return jsonify({"st": "ok", "uid": uid,
                    "backpack": {"used": len(st["backpack"]), "slots": st["backpack_slots"], "items": st["backpack"]},
                    "storage_box": {"used": len(st["storage_box"]), "slots": st["storage_slots"], "items": st["storage_box"]}})

@app.route('/api/storage/add', methods=['POST'])
@require_auth_toggleable
def api_storage_add():
    """body: {uid, which: backpack|storage_box, item, qty} -> เพิ่มไอเทม (สแตกกับของเดิมชนิดเดียวกันถ้ามีที่ว่าง)"""
    body = request.json or {}
    uid, which, item, qty = body.get("uid", ""), body.get("which", "backpack"), body.get("item", ""), int(body.get("qty", 1))
    if not uid or not item:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid และ item"}), 400
    st = storage_get(uid)
    box = _storage_container(st, which)
    max_slots = st["backpack_slots"] if which == "backpack" else st["storage_slots"]
    for slot in box.values():
        if slot["item"] == item:
            slot["qty"] += qty
            return jsonify({"st": "ok", "which": which, "items": box})
    if len(box) >= max_slots:
        return jsonify({"st": "error", "msg": f"{which} เต็ม ({len(box)}/{max_slots})"}), 400
    box[str(len(box))] = {"item": item, "qty": qty}
    return jsonify({"st": "ok", "which": which, "items": box})

@app.route('/api/storage/transfer', methods=['POST'])
@require_auth
def api_storage_transfer():
    """body: {from_slot, direction: to_box|to_backpack, qty(optional=all)} -> ย้ายของระหว่างกระเป๋าเป้<->กล่องเก็บของ
    (คลิกลูกศรกลางจอในภาพ 'กล่องเก็บของ' ที่ย้ายของสองฝั่ง)
    [BUG-FIX #17] เดิมไม่เช็คว่า qty ที่ขอย้ายเกินจำนวนที่มีในช่องนั้นจริงไหม — ส่ง qty
    มากกว่าที่มี (หรือติดลบ) มาได้ ทำให้ปลายทางได้ของครบตามที่ขอ แต่ต้นทางแค่ค่า qty
    ติดลบแล้วโดนลบช่องทิ้งไปเฉยๆ (ไม่ error) = ได้ไอเทมฟรีไม่จำกัด (item duplication)
    แก้โดยบังคับ qty ต้องเป็นจำนวนเต็มบวก และห้ามเกินจำนวนที่มีอยู่จริงในช่องต้นทาง
    [BUG-FIX #21] เดิมรับ uid จาก body ตรงๆ (ใครก็สวมรอยเป็น uid ไหนก็ได้ ย้ายของ
    เข้า/ออกกระเป๋าคนอื่นได้ทั้งที่แก้ #17 ไปแล้ว) แก้โดยเพิ่ม @require_auth แล้วใช้
    uid จาก JWT session (request.vmax_uid) เท่านั้น ไม่เชื่อ uid ที่ client ส่งมาอีกต่อไป"""
    body = request.json or {}
    uid, from_slot, direction = request.vmax_uid, str(body.get("from_slot", "")), body.get("direction", "to_box")
    st = storage_get(uid)
    src_key, dst_key = ("backpack", "storage_box") if direction == "to_box" else ("storage_box", "backpack")
    src, dst = st[src_key], st[dst_key]
    if from_slot not in src:
        return jsonify({"st": "error", "msg": "ไม่พบไอเทมในช่องนี้"}), 404
    entry = src[from_slot]
    try:
        qty = int(body.get("qty") or entry["qty"])
    except (TypeError, ValueError):
        return jsonify({"st": "error", "msg": "qty ต้องเป็นตัวเลข"}), 400
    if qty <= 0:
        return jsonify({"st": "error", "msg": "qty ต้องมากกว่า 0"}), 400
    if qty > entry["qty"]:
        return jsonify({"st": "error", "msg": f"มีของแค่ {entry['qty']} ชิ้น ย้ายเกินจำนวนที่มีไม่ได้"}), 400
    dst_max = st["storage_slots"] if dst_key == "storage_box" else st["backpack_slots"]
    moved = False
    for slot in dst.values():
        if slot["item"] == entry["item"]:
            slot["qty"] += qty
            moved = True
            break
    if not moved:
        if len(dst) >= dst_max:
            return jsonify({"st": "error", "msg": f"{dst_key} เต็ม"}), 400
        dst[str(len(dst))] = {"item": entry["item"], "qty": qty}
    entry["qty"] -= qty
    if entry["qty"] <= 0:
        del src[from_slot]
    return jsonify({"st": "ok", "backpack": st["backpack"], "storage_box": st["storage_box"]})

@app.route('/api/storage/collect_all', methods=['POST'])
@require_auth_toggleable
def api_storage_collect_all():
    """body: {uid} -> 'จัดเก็บทั้งหมด' ย้ายทุกอย่างจากกล่องเก็บของเข้ากระเป๋าเป้เท่าที่พื้นที่พอ"""
    body = request.json or {}
    uid = body.get("uid", "")
    st = storage_get(uid)
    moved_any = True
    while moved_any and st["storage_box"]:
        moved_any = False
        for slot_id in list(st["storage_box"].keys()):
            if len(st["backpack"]) >= st["backpack_slots"]:
                break
            entry = st["storage_box"].pop(slot_id)
            placed = False
            for slot in st["backpack"].values():
                if slot["item"] == entry["item"]:
                    slot["qty"] += entry["qty"]
                    placed = True
                    break
            if not placed:
                st["backpack"][str(len(st["backpack"]))] = entry
            moved_any = True
    return jsonify({"st": "ok", "backpack": st["backpack"], "storage_box": st["storage_box"]})

VMAX_MODULES["storage_box"] = {
    "desc": "กล่องเก็บของ + กระเป๋าเป้ แยก slot กันคนละที่ (กล่องเก็บของฝากไว้ที่ฐานปลอดภัยกว่า, "
            "กระเป๋าเป้พกติดตัวเสี่ยงหายตอนถอนกำลังไม่ทัน) ย้ายของสองทาง + จัดเก็บทั้งหมดในคลิกเดียว",
    "routes": ["/api/storage/state", "/api/storage/add", "/api/storage/transfer", "/api/storage/collect_all"],
}


# ---------- [ 6zz5c. ทำอาหาร (Campfire Cooking) ] --------------------------------
COOKING_RECIPES = {
    "grilled_meat": {"name": "เนื้อย่าง", "ingredients": {"raw_meat": 1}, "time_sec": 30, "restores": {"hunger": 40}},
    "boiled_water": {"name": "น้ำต้มสุก", "ingredients": {"dirty_water": 1}, "time_sec": 15, "restores": {"thirst": 30}},
    "roasted_boar": {"name": "หมูป่าย่าง", "ingredients": {"boar_meat": 2}, "time_sec": 45, "restores": {"hunger": 70}},
    # อาหารมื้อใหญ่สำหรับระบบ Food/Water/Waste ใหม่ — ผลผลิตจะเข้ากระเป๋าเดิม
    "energy_meal": {"name": "อาหารพลังงานสูง", "ingredients": {"grilled_meat": 1, "ration_bar": 1}, "time_sec": 60, "restores": {"hunger": 76, "stamina": 34, "waste": 34}},
    "premium_meal": {"name": "อาหารปรุงสุกพิเศษ", "ingredients": {"roasted_boar": 1, "grilled_meat": 1}, "time_sec": 75, "restores": {"hunger": 86, "stamina": 42, "waste": 40}},
    # [NEW] เหล็กร้อน — เอา iron_ingot (ได้จากเตาหลอม, ดู SMELTER_RECIPES) มาเผาที่กองไฟจนแดง
    # แทนไอเดีย "ใช้ดินปืนจี้แผล" ที่ไม่ตรงกับความเป็นจริง (ดินปืนติดไฟแบบระเบิดฉับพลันที่ ~2,000+°C
    # ทำลายเนื้อเยื่อรอบข้างมากกว่าจะห้ามเลือด) ของจริงคือ cauterization ใช้โลหะเผาไฟจนร้อน (~500-700°C)
    # กดลงบนแผลเพื่อให้เลือดแข็งตัวปิดปากแผล — เจ็บมากและได้แผลไฟไหม้เพิ่ม แต่ห้ามเลือดได้จริง
    "hot_iron": {
        "name": "เหล็กร้อน (จี้ปิดแผล)",
        "ingredients": {"iron_ingot": 1},
        "time_sec": 20,
        "restores": {"hp": 15, "bleed_stop": 1},
        "side_effect": {"pain": 25, "burn_dmg": 5},
    },
}
CAMPFIRE_QUEUE = {}  # uid -> [{"recipe","qty","started_at","ready_at"}]

@app.route('/api/campfire/recipes')
def api_campfire_recipes():
    """รายชื่อสูตรทำอาหารที่กองไฟทำได้ทั้งหมด"""
    return jsonify({"st": "ok", "recipes": COOKING_RECIPES})

@app.route('/api/campfire/cook', methods=['POST'])
@require_auth_toggleable
def api_campfire_cook():
    """body: {uid, recipe, qty} -> ใส่วัตถุดิบเข้ากองไฟ (หัก inventory จาก storage backpack) แล้วเข้าคิวทำอาหาร"""
    body = request.json or {}
    uid, recipe_id, qty = body.get("uid", ""), body.get("recipe", ""), int(body.get("qty", 1))
    recipe = COOKING_RECIPES.get(recipe_id)
    if not recipe:
        return jsonify({"st": "error", "msg": f"ไม่พบสูตร '{recipe_id}'"}), 404
    now = time.time()
    entry = {"recipe": recipe_id, "qty": qty, "started_at": now, "ready_at": now + recipe["time_sec"] * qty}
    CAMPFIRE_QUEUE.setdefault(uid, []).append(entry)
    return jsonify({"st": "ok", "queued": entry})

@app.route('/api/campfire/collect', methods=['POST'])
@require_auth_toggleable
def api_campfire_collect():
    """body: {uid} -> เก็บอาหารที่ทำเสร็จแล้ว (ready_at ผ่านไปแล้ว) เข้ากระเป๋าเป้"""
    body = request.json or {}
    uid = body.get("uid", "")
    now = time.time()
    q = CAMPFIRE_QUEUE.get(uid, [])
    done, still_cooking = [], []
    for entry in q:
        (done if entry["ready_at"] <= now else still_cooking).append(entry)
    CAMPFIRE_QUEUE[uid] = still_cooking
    st = storage_get(uid)
    collected = []
    for entry in done:
        recipe = COOKING_RECIPES[entry["recipe"]]
        for slot in st["backpack"].values():
            if slot["item"] == entry["recipe"]:
                slot["qty"] += entry["qty"]
                break
        else:
            if len(st["backpack"]) < st["backpack_slots"]:
                st["backpack"][str(len(st["backpack"]))] = {"item": entry["recipe"], "qty": entry["qty"]}
        collected.append({"item": entry["recipe"], "name": recipe["name"], "qty": entry["qty"]})
    return jsonify({"st": "ok", "collected": collected, "still_cooking": still_cooking})

@app.route('/api/campfire/cauterize', methods=['POST'])
@require_auth_toggleable
def api_campfire_cauterize():
    """body: {uid} -> ใช้ 'เหล็กร้อน' (hot_iron) 1 ชิ้นจากกระเป๋าเป้เพื่อจี้ปิดแผล
    ต้องมี hot_iron อยู่แล้ว (เผาที่กองไฟผ่าน /api/campfire/cook ก่อน) ใช้แล้วหักออกจากกระเป๋า 1 ชิ้น
    คืนค่า effect ให้ client ไปปรับ hp/pain/bleed ของผู้เล่นเอง (โมดูลนี้เก็บแค่ inventory ไม่ได้
    ผูกกับระบบ HP ผู้เล่นโดยตรง) — เหมือนของจริง: ห้ามเลือดได้ แต่เจ็บและได้แผลไหม้เพิ่ม"""
    body = request.json or {}
    uid = body.get("uid", "")
    st = storage_get(uid)
    for slot_id, slot in list(st["backpack"].items()):
        if slot["item"] == "hot_iron" and slot["qty"] > 0:
            slot["qty"] -= 1
            if slot["qty"] <= 0:
                del st["backpack"][slot_id]
            recipe = COOKING_RECIPES["hot_iron"]
            return jsonify({"st": "ok", "used": "hot_iron",
                             "restores": recipe["restores"], "side_effect": recipe["side_effect"],
                             "backpack": st["backpack"]})
    return jsonify({"st": "error", "msg": "ไม่มี 'เหล็กร้อน' ในกระเป๋าเป้ — ต้องเผา iron_ingot ที่กองไฟก่อน"}), 400

VMAX_MODULES["campfire_cooking"] = {
    "desc": "ระบบทำอาหารที่กองไฟ (Campfire) — ใส่วัตถุดิบ, เข้าคิวตามเวลา, เก็บผลลัพธ์เข้ากระเป๋าเป้เมื่อสุกแล้ว "
            "รวมถึงเผา iron_ingot เป็น 'เหล็กร้อน' เพื่อใช้จี้ปิดแผล (ห้ามเลือดจริง แต่เจ็บ+แผลไหม้ ตามหลักการจริง "
            "ต่างจากดินปืนที่ใช้จี้แผลไม่ได้)",
    "routes": ["/api/campfire/recipes", "/api/campfire/cook", "/api/campfire/collect", "/api/campfire/cauterize"],
}


