CRAFT_QUEUE = {}  # uid -> [{"table","item","qty","ready_at"}]

def _craft(uid: str, table: dict, item_id: str, qty: int, table_name: str):
    # [BUG-FIX #18] เดิมไม่เช็คว่า qty เป็นบวกหรือเปล่า — ส่ง qty ติดลบมาได้ ทำให้
    # เช็ค "วัตถุดิบพอไหม" (have < need*qty) ผ่านเสมอ (ติดลบเทียบกับจำนวนที่มียังไงก็
    # น้อยกว่าไม่ได้) แล้วตอนหักวัตถุดิบ slot["qty"] -= need*qty กลายเป็นบวกเพิ่มแทน
    # (ลบด้วยจำนวนติดลบ = บวก) = คราฟต์ด้วย qty ติดลบแล้วได้วัตถุดิบเพิ่มฟรี (duplication)
    if not isinstance(qty, int) or qty <= 0:
        return None, "qty ต้องเป็นจำนวนเต็มบวก"
    for tier_recipes in table.values():
        if item_id in tier_recipes:
            recipe = tier_recipes[item_id]
            break
    else:
        return None, f"ไม่พบสูตร '{item_id}' ใน{table_name}"
    st = storage_get(uid)
    have = {slot["item"]: slot["qty"] for slot in st["backpack"].values()}
    for mat, need in recipe["ingredients"].items():
        if have.get(mat, 0) < need * qty:
            return None, f"วัตถุดิบไม่พอ: {mat} ต้องการ {need * qty} มีอยู่ {have.get(mat, 0)}"
    for slot in list(st["backpack"].values()):
        need = recipe["ingredients"].get(slot["item"])
        if need:
            slot["qty"] -= need * qty
    st["backpack"] = {k: v for k, v in st["backpack"].items() if v["qty"] > 0}
    entry = {"table": table_name, "item": item_id, "qty": qty, "ready_at": time.time() + 5 * qty}
    CRAFT_QUEUE.setdefault(uid, []).append(entry)
    return entry, None

@app.route('/api/crafting_table/recipes')
def api_crafting_table_recipes():
    """?smartcore_level=N -> สูตรทั้งหมดที่ปลดล็อกแล้วตามเลเวลสมาร์ทคอร์ (โต๊ะคราฟต์: สเบียง/ระเบิด/สิ่งอำนวยความสะดวก)"""
    lvl = int(request.args.get("smartcore_level", 99))
    out = {}
    for tier, recipes in CRAFTING_TABLE_RECIPES.items():
        if tier <= lvl:
            out.update(recipes)
    return jsonify({"st": "ok", "recipes": out})

