@app.route('/api/craft_queue/collect', methods=['POST'])
@require_auth
def api_craft_queue_collect():
    """เก็บของที่คราฟต์เสร็จแล้ว (ทั้งจากโต๊ะคราฟต์และโต๊ะอุปกรณ์) เข้ากระเป๋าเป้
    [BUG-FIX #21] เดิมรับ uid จาก body ตรงๆ — ใช้ @require_auth + uid จาก JWT session แทน"""
    uid = request.vmax_uid
    now = time.time()
    q = CRAFT_QUEUE.get(uid, [])
    done, still = [], []
    for entry in q:
        (done if entry["ready_at"] <= now else still).append(entry)
    CRAFT_QUEUE[uid] = still
    st = storage_get(uid)
    for entry in done:
        for slot in st["backpack"].values():
            if slot["item"] == entry["item"]:
                slot["qty"] += entry["qty"]
                break
        else:
            if len(st["backpack"]) < st["backpack_slots"]:
                st["backpack"][str(len(st["backpack"]))] = {"item": entry["item"], "qty": entry["qty"]}
    return jsonify({"st": "ok", "collected": done, "still_crafting": still})

# --- เตาหลอมขนาดเล็ก (Smelter) — แร่ -> แท่งโลหะ ---------------------------------
SMELTER_RECIPES = {"iron_ore": "iron_ingot", "gold_ore": "gold_ingot", "sulfur_ore": "sulfur"}
SMELTER_STATE = {}  # uid -> {"active": bool, "queue": {ore: qty}, "started_at"}
SMELTER_SEC_PER_UNIT = 3

@app.route('/api/smelter/state')
def api_smelter_state():
    """?uid=xxx -> สถานะเตาหลอม (กำลังทำงานไหม, คิววัตถุดิบที่ใส่ไว้)"""
    uid = request.args.get("uid", "")
    return jsonify({"st": "ok", **SMELTER_STATE.setdefault(uid, {"active": False, "queue": {}, "started_at": None})})

@app.route('/api/smelter/add_ore', methods=['POST'])
@require_auth_toggleable
def api_smelter_add_ore():
    """body: {uid, ore, qty} -> ใส่แร่เข้าเตาหลอม (หักจากกระเป๋าเป้)"""
    body = request.json or {}
    uid, ore, qty = body.get("uid", ""), body.get("ore", ""), int(body.get("qty", 1))
    if ore not in SMELTER_RECIPES:
        return jsonify({"st": "error", "msg": f"เตาหลอมไม่รู้จักแร่ '{ore}'"}), 400
    st = storage_get(uid)
    for slot in st["backpack"].values():
        if slot["item"] == ore and slot["qty"] >= qty:
            slot["qty"] -= qty
            break
    else:
        return jsonify({"st": "error", "msg": f"มีแร่ {ore} ไม่พอ"}), 400
    smelter = SMELTER_STATE.setdefault(uid, {"active": False, "queue": {}, "started_at": None})
    smelter["queue"][ore] = smelter["queue"].get(ore, 0) + qty
    if not smelter["active"]:
        smelter["active"] = True
        smelter["started_at"] = time.time()
    return jsonify({"st": "ok", **smelter})

@app.route('/api/smelter/collect', methods=['POST'])
@require_auth_toggleable
def api_smelter_collect():
    """body: {uid} -> เก็บผลผลิตหลอมเสร็จ (คำนวณจากเวลาที่ผ่านไป * SMELTER_SEC_PER_UNIT ต่อหน่วย) เข้ากระเป๋าเป้"""
    body = request.json or {}
    uid = body.get("uid", "")
    smelter = SMELTER_STATE.setdefault(uid, {"active": False, "queue": {}, "started_at": None})
    if not smelter["active"] or not smelter["queue"]:
        return jsonify({"st": "ok", "collected": {}})
    elapsed = time.time() - smelter["started_at"]
    st = storage_get(uid)
    collected = {}
    for ore, qty in list(smelter["queue"].items()):
        can_smelt = min(qty, int(elapsed // SMELTER_SEC_PER_UNIT))
        if can_smelt <= 0:
            continue
        ingot = SMELTER_RECIPES[ore]
        for slot in st["backpack"].values():
            if slot["item"] == ingot:
                slot["qty"] += can_smelt
                break
        else:
            if len(st["backpack"]) < st["backpack_slots"]:
                st["backpack"][str(len(st["backpack"]))] = {"item": ingot, "qty": can_smelt}
        collected[ingot] = collected.get(ingot, 0) + can_smelt
        smelter["queue"][ore] -= can_smelt
        if smelter["queue"][ore] <= 0:
            del smelter["queue"][ore]
    if not smelter["queue"]:
        smelter["active"] = False
        smelter["started_at"] = None
    return jsonify({"st": "ok", "collected": collected, "queue": smelter["queue"]})

# --- โต๊ะซ่อมแซม (Repair Table) --------------------------------------------------
REPAIRABLE_ITEM_DURABILITY = {}  # (uid, item_uid) -> {"item","durability","max_durability"}

@app.route('/api/repair_table/repair', methods=['POST'])
@require_auth_toggleable
def api_repair_table_repair():
    """body: {uid, item_uid, item, repair_cost:{material:qty}} -> ซ่อมไอเทมชิ้นเดียวให้เต็มความทนทาน
    (หักวัตถุดิบซ่อมจากกระเป๋าเป้ตาม repair_cost ที่ส่งมา — คิดสัดส่วนตามความเสียหายจริงในไคลเอนต์เกม)"""
    body = request.json or {}
    uid, item_uid, item = body.get("uid", ""), body.get("item_uid", ""), body.get("item", "")
    repair_cost = body.get("repair_cost", {})
    st = storage_get(uid)
    have = {slot["item"]: slot["qty"] for slot in st["backpack"].values()}
    for mat, need in repair_cost.items():
        if have.get(mat, 0) < need:
            return jsonify({"st": "error", "msg": f"วัตถุดิบซ่อมไม่พอ: {mat} ต้องการ {need}"}), 400
    for slot in list(st["backpack"].values()):
        need = repair_cost.get(slot["item"])
        if need:
            slot["qty"] -= need
    st["backpack"] = {k: v for k, v in st["backpack"].items() if v["qty"] > 0}
    REPAIRABLE_ITEM_DURABILITY[(uid, item_uid)] = {"item": item, "durability": 100, "max_durability": 100}
    return jsonify({"st": "ok", "msg": f"ซ่อม {item} เสร็จแล้ว", "durability": 100})

VMAX_MODULES["crafting_repair_smelter"] = {
    "desc": "ชุดโต๊ะงานฝีมือที่ฐาน: โต๊ะคราฟต์ (สเบียง/ระเบิด/สิ่งอำนวยความสะดวก, 3 เลเวลตามสมาร์ทคอร์), "
            "โต๊ะอุปกรณ์ (อาวุธ/เกราะ), เตาหลอมขนาดเล็ก (แร่->แท่งโลหะ ตามเวลา), โต๊ะซ่อมแซม (ซ่อมความทนทานไอเทม)",
    "routes": ["/api/crafting_table/recipes", "/api/equipment_table/recipes", "/api/crafting_table/craft",
               "/api/equipment_table/craft", "/api/craft_queue/collect", "/api/smelter/state",
               "/api/smelter/add_ore", "/api/smelter/collect", "/api/repair_table/repair"],
}


# ---------- [ 6zz5e. กระดานผู้นำโซนสงคราม (War Zone Leaderboard) + รางวัลอันดับ ] --
WARZONE_LEADERBOARD = []  # [{"uid","name","tier","score"}] เรียงจากคะแนนสูงสุด
WARZONE_RESET_INTERVAL_SEC = 7 * 86400  # รีเซ็ตฤดูกาลโซนสงครามทุก 7 วัน (ตามที่ขอ)
WARZONE_SEASON_END_TS = time.time() + WARZONE_RESET_INTERVAL_SEC
WARZONE_SEASON_HISTORY = []  # เก็บผลอันดับ+รางวัลของฤดูกาลก่อนหน้าไว้ดูย้อนหลัง (ล่าสุดอยู่ท้ายลิสต์)
WARZONE_RANK_REWARDS = [  # (อันดับต่ำสุด, อันดับสูงสุด, รางวัล)
    (1, 4, {"tickets": 5000000, "war_crates": 10}),
    (5, 8, {"tickets": 4000000, "war_crates": 8}),
    (9, 12, {"tickets": 3000000, "war_crates": 6}),
    (13, 20, {"tickets": 2000000, "war_crates": 5}),
]
WARZONE_SCORE_PER_RANK_STEP = 225000  # คะแนนขั้นต่ำเพื่อเลื่อนอันดับขึ้นหนึ่งขั้น (ตามภาพ)

def warzone_reward_for_rank(rank: int) -> dict:
    for lo, hi, reward in WARZONE_RANK_REWARDS:
        if lo <= rank <= hi:
            return reward
    return {}

def _warzone_maybe_reset_season():
    """เรียกทุกครั้งที่มีคนเปิดดูกระดานผู้นำ — ถ้าเวลาสิ้นสุดฤดูกาล (7 วัน) ผ่านไปแล้ว จะแจกรางวัลจริง
    ให้ทุกคนตามช่วงอันดับ เป็นเงิน 'gold' ในสกุลเงินเดิม (PLAYER_CURRENCY จาก [6zz6k]) ที่เอาไปซื้อของใน
    ร้านค้าในเกมได้จริง แล้วเก็บผลฤดูกาลนี้ไว้ดูย้อนหลัง (WARZONE_SEASON_HISTORY) ก่อนรีเซ็ตกระดาน+
    เริ่มฤดูกาลใหม่ทันที (อีก 7 วันถัดไป)"""
    global WARZONE_SEASON_END_TS
    # [ 2E0z hook ] เช็คทุกครั้งที่มีคนเข้าดูกระดาน ว่าเข้าช่วง "กลางๆ ค่อนไปทางท้ายซีซั่น"
    # ของโหมด warzone หรือยัง — ถ้าใช่และยังไม่เคยเริ่มในซีซั่นนี้ ให้สุ่มปล่อยอีเวนต์สมบัติ
    # ทองของแดงออกมา (นี่คือตัวอย่างจริงของการผูกโมดูล golden_treasure_gas_event เข้ากับ
    # โหมดหนึ่ง — โหมดอื่น (xroom/worldmap/ฯลฯ) ก็เรียกแพทเทิร์นเดียวกันนี้ตรง season tick
    # ของตัวเองได้เลย)
    if golden_treasure_should_trigger("warzone", WARZONE_SEASON_END_TS, WARZONE_RESET_INTERVAL_SEC):
        golden_treasure_start_event("warzone", map_w=1000.0, map_h=1000.0)
    if time.time() < WARZONE_SEASON_END_TS:
        return
    golden_treasure_reset_season_flag("warzone")   # [ 2E0z hook ] ซีซั่นใหม่ -> ให้อีเวนต์นี้มีสิทธิสุ่มเริ่มได้อีก
    ranked = sorted(WARZONE_LEADERBOARD, key=lambda p: -p.get("score", 0))
    payouts = []
    for i, p in enumerate(ranked):
        reward = warzone_reward_for_rank(i + 1)
        if not reward:
            continue
        gold_reward = reward.get("tickets", 0) // 1000  # แปลงตั๋วเป็นทองที่ใช้ซื้อของในร้านได้จริง
        cur = _currency_get(p["uid"])
        cur["gold"] += gold_reward
        payouts.append({"uid": p["uid"], "rank": i + 1, "gold": gold_reward, **reward})
        sio.emit('warzone_season_reward', {"rank": i + 1, "gold": gold_reward, **reward}, room=p["uid"])
    WARZONE_SEASON_HISTORY.append({"ended_at": time.time(), "payouts": payouts})
    del WARZONE_SEASON_HISTORY[:-10]  # เก็บย้อนหลังแค่ 10 ฤดูกาลพอ
    WARZONE_LEADERBOARD.clear()
    WARZONE_SEASON_END_TS = time.time() + WARZONE_RESET_INTERVAL_SEC

@app.route('/api/warzone/leaderboard')
def api_warzone_leaderboard():
    """?limit=N -> กระดานผู้นำโซนสงคราม เรียงคะแนนมากไปน้อย พร้อมเวลาที่เหลือของฤดูกาลและรางวัลต่อช่วงอันดับ
    (เรียก _warzone_maybe_reset_season() ทุกครั้งที่เข้าดู — ถ้าครบ 7 วันแล้วจะแจกรางวัล+รีเซ็ตให้อัตโนมัติ)"""
    _warzone_maybe_reset_season()
    limit = int(request.args.get("limit", 50))

    ranked = sorted(WARZONE_LEADERBOARD, key=lambda p: -p.get("score", 0))
    rows = [{"rank": i + 1, **p, "reward": warzone_reward_for_rank(i + 1)} for i, p in enumerate(ranked[:limit])]
    remain = max(0, WARZONE_SEASON_END_TS - time.time())
    return jsonify({"st": "ok", "leaderboard": rows, "season_seconds_remaining": int(remain),
                    "score_per_rank_step": WARZONE_SCORE_PER_RANK_STEP, "reward_tiers": WARZONE_RANK_REWARDS})

@app.route('/api/warzone/submit_score', methods=['POST'])
@require_auth_toggleable
def api_warzone_submit_score():
    """body: {uid, name, tier, score} -> ส่ง/อัปเดตคะแนนโซนสงครามของผู้เล่น (อัปเดตทับถ้ามีอยู่แล้ว)"""
    body = request.json or {}
    uid = body.get("uid", "")
    if not uid:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
    for p in WARZONE_LEADERBOARD:
        if p["uid"] == uid:
            p.update({"name": body.get("name", p["name"]), "tier": body.get("tier", p["tier"]),
                      "score": int(body.get("score", p["score"]))})
            break
    else:
        WARZONE_LEADERBOARD.append({"uid": uid, "name": body.get("name", uid), "tier": body.get("tier", ""),
                                    "score": int(body.get("score", 0))})
    return jsonify({"st": "ok"})

@app.route('/api/warzone/season_history')
def api_warzone_season_history():
    """ผลอันดับ+รางวัลของฤดูกาลก่อนหน้าที่รีเซ็ตไปแล้ว (เก็บย้อนหลังไว้ 10 ฤดูกาลล่าสุด)"""
    return jsonify({"st": "ok", "history": WARZONE_SEASON_HISTORY})

VMAX_MODULES["warzone_leaderboard"] = {
    "desc": "กระดานผู้นำโซนสงคราม (อันดับต่อสู้/ผู้นำพิชิตโซน) พร้อมนับเวลาถอยหลังจบฤดูกาลและตารางรางวัลตามช่วงอันดับ "
            "(ตั๋วฟ้า + คลังนิรภัยสงคราม ตามอันดับ 1-4/5-8/9-12/13-20) รีเซ็ตฤดูกาลอัตโนมัติทุก 7 วัน "
            "แจกรางวัลจริงเป็นทอง (ใช้ซื้อของในร้านค้าได้) ให้ผู้ติดอันดับ แล้วเก็บผลฤดูกาลก่อนไว้ดูย้อนหลัง",
    "routes": ["/api/warzone/leaderboard", "/api/warzone/submit_score", "/api/warzone/season_history"],
}


# ---------- [ 6zz5f. เพื่อน (Friends) + ของขวัญ (Gift) ] --------------------------
FRIENDS_LIST = {}   # uid -> [{"uid","name","status":"online"|"offline","smartcore_level"}]
FRIEND_REQUESTS = {}  # uid -> [from_uid, ...] คำขอเป็นเพื่อนที่รอตอบรับ
GIFT_LOG = {}  # uid(ผู้รับ) -> [{"from","item","qty","ts"}]
GIFT_COOLDOWN_SEC = 12 * 3600
GIFT_SENT_LOG = {}  # (from_uid, to_uid) -> last_sent_ts

@app.route('/api/friends/list')
def api_friends_list():
    """?uid=xxx -> รายชื่อเพื่อนทั้งหมด พร้อมสถานะออนไลน์/เลเวลสมาร์ทคอร์ (ตามหน้าจอ 'เพื่อน')"""
    uid = request.args.get("uid", "")
    return jsonify({"st": "ok", "friends": FRIENDS_LIST.get(uid, [])})

@app.route('/api/friends/request', methods=['POST'])
@require_auth_toggleable
def api_friends_request():
    """body: {from_uid, to_uid} -> ส่งคำขอเป็นเพื่อน (ปุ่ม 'คำขอเป็นเพื่อน' มุมล่างขวา)"""
    body = request.json or {}
    from_uid, to_uid = body.get("from_uid", ""), body.get("to_uid", "")
    if not from_uid or not to_uid or from_uid == to_uid:
        return jsonify({"st": "error", "msg": "from_uid/to_uid ไม่ถูกต้อง"}), 400
    FRIEND_REQUESTS.setdefault(to_uid, [])
    if from_uid not in FRIEND_REQUESTS[to_uid]:
        FRIEND_REQUESTS[to_uid].append(from_uid)
    return jsonify({"st": "ok", "msg": "ส่งคำขอเป็นเพื่อนแล้ว"})

@app.route('/api/friends/accept', methods=['POST'])
@require_auth_toggleable
def api_friends_accept():
    """body: {uid, from_uid, from_name} -> ตอบรับคำขอเป็นเพื่อน -> เพิ่มเข้ารายชื่อเพื่อนทั้งสองฝั่ง"""
    body = request.json or {}
    uid, from_uid = body.get("uid", ""), body.get("from_uid", "")
    reqs = FRIEND_REQUESTS.get(uid, [])
    if from_uid not in reqs:
        return jsonify({"st": "error", "msg": "ไม่พบคำขอนี้"}), 404
    reqs.remove(from_uid)
    FRIENDS_LIST.setdefault(uid, []).append({"uid": from_uid, "name": body.get("from_name", from_uid),
                                             "status": "online", "smartcore_level": 1})
    FRIENDS_LIST.setdefault(from_uid, []).append({"uid": uid, "name": body.get("uid_name", uid),
                                                  "status": "online", "smartcore_level": 1})
    return jsonify({"st": "ok", "msg": "เป็นเพื่อนกันแล้ว"})

@app.route('/api/friends/remove', methods=['POST'])
@require_auth_toggleable
def api_friends_remove():
    """body: {uid, friend_uid} -> ลบเพื่อนออกจากรายชื่อ (ปุ่มถังขยะสีแดงในภาพ)"""
    body = request.json or {}
    uid, friend_uid = body.get("uid", ""), body.get("friend_uid", "")
    FRIENDS_LIST[uid] = [f for f in FRIENDS_LIST.get(uid, []) if f["uid"] != friend_uid]
    return jsonify({"st": "ok", "friends": FRIENDS_LIST.get(uid, [])})

@app.route('/api/friends/gift', methods=['POST'])
@require_auth_toggleable
def api_friends_gift():
    """body: {from_uid, to_uid, item, qty} -> ส่งของขวัญให้เพื่อน (จำกัดคนละครั้งทุก GIFT_COOLDOWN_SEC วิ ต่อคู่เพื่อน)"""
    body = request.json or {}
    from_uid, to_uid = body.get("from_uid", ""), body.get("to_uid", "")
    key = (from_uid, to_uid)
    last = GIFT_SENT_LOG.get(key, 0)
    if time.time() - last < GIFT_COOLDOWN_SEC:
        wait = int(GIFT_COOLDOWN_SEC - (time.time() - last))
        return jsonify({"st": "error", "msg": f"ให้ของขวัญคนนี้ไปแล้ว รออีก {wait} วิ"}), 429
    GIFT_SENT_LOG[key] = time.time()
    entry = {"from": from_uid, "item": body.get("item", "gift_box"), "qty": int(body.get("qty", 1)), "ts": time.time()}
    GIFT_LOG.setdefault(to_uid, []).append(entry)
    return jsonify({"st": "ok", "msg": "ส่งของขวัญแล้ว", "gift": entry})

@app.route('/api/friends/gift/inbox')
def api_friends_gift_inbox():
    """?uid=xxx -> ของขวัญที่ยังไม่ได้รับจากเพื่อนทั้งหมด"""
    return jsonify({"st": "ok", "gifts": GIFT_LOG.get(request.args.get("uid", ""), [])})

VMAX_MODULES["friends_gift"] = {
    "desc": "ระบบเพื่อน (ส่งคำขอ/ตอบรับ/ลบ, ดูสถานะออนไลน์+เลเวลสมาร์ทคอร์) และระบบของขวัญระหว่างเพื่อน "
            "(มีคูลดาวน์ต่อคู่เพื่อนกันสแปม)",
    "routes": ["/api/friends/list", "/api/friends/request", "/api/friends/accept", "/api/friends/remove",
               "/api/friends/gift", "/api/friends/gift/inbox"],
}


# ---------- [ 6zz5f2. Global Chat Moderation — Toxic-Language Filter ] ------------
# [UPGRADE] ตามที่ขอ — จุดกลางจุดเดียวที่ "ทุกเกม" ในไฟล์นี้ (ทั้งที่มีอยู่แล้วและที่จะเพิ่ม
# ทีหลัง ระบุด้วย game_id เหมือน Central Anti-Cheat Hub [6j0] ด้านบน) เรียกผ่านมาได้ทั้งทาง
# Socket.IO (แชทเรียลไทม์ในเกม) และ REST (ระบบที่ไม่ได้ต่อ socket) กติกาตามที่ขอ:
#   - พิมพ์คำหยาบได้ปกติ "ก็ต่อเมื่อเป็นเพื่อนกัน" (เช็คจาก FRIENDS_LIST [6zz5f] ด้านบน) —
#     แชทส่วนตัว (to_uid) เช็คคู่นั้นคู่เดียว, แชทกลุ่ม/ห้อง (room_id) ต้องเป็นเพื่อนกัน "ทุกคน"
#     ในห้องถึงจะปล่อยผ่าน ไม่งั้นถือว่ายังไม่ใช่ friends-context
#   - ไม่ใช่บริบทเพื่อน -> เซ็นเซอร์คำหยาบเป็น *** แล้วค่อยส่งต่อ (ไม่ปิดกั้นการแชททั้งข้อความ)
#     พร้อมสะสม toxic_score ให้ผู้เล่นคนนั้น
#   - สะสมครบ TOXIC_BRAND_THRESHOLD ครั้ง -> "ตราหน้า" (brand) ว่า toxic และยื่นรายงานเข้า
#     Central Anti-Cheat Hub [6j0] อัตโนมัติ (ผ่าน submit_cheat_report เดิม) ให้แอดมินตรวจต่อ —
#     ไม่ใช่แบนอัตโนมัติทันที เพราะ heuristic คำหยาบอย่างเดียวความแม่นยำไม่พอจะแบนถาวรเอง
#   - รายชื่อคำหยาบด้านล่างเป็นชุดตัวอย่างเล็กๆ พอให้เห็นโครง ของจริงแนะนำโหลดชุดคำที่ครบกว่านี้
#     จากไฟล์ภายนอกผ่าน VMAX_PROFANITY_WORDLIST_PATH (บรรทัดละ 1 คำ) แทนการแก้โค้ด
# ==========================================
TOXIC_BRAND_THRESHOLD = 5     # จำนวนข้อความหยาบที่ถูกเซ็นเซอร์ก่อนจะถูกตราหน้าว่า toxic
_DEFAULT_PROFANITY_WORDLIST = [
    # อังกฤษ (ตัวอย่างสั้นๆ)
    "fuck", "shit", "bitch", "asshole", "cunt",
    # ไทย (ตัวอย่างสั้นๆ)
    "เหี้ย", "สัส", "ควย", "เชี่ย", "ไอสัตว์", "แม่ง", "ระยำ",
]

def _load_profanity_wordlist():
    path = os.environ.get("VMAX_PROFANITY_WORDLIST_PATH", "")
    if path and os.path.isfile(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                words = [w.strip().lower() for w in f if w.strip()]
            if words:
                return words
        except OSError:
            pass
    return list(_DEFAULT_PROFANITY_WORDLIST)

PROFANITY_WORDLIST = _load_profanity_wordlist()
TOXIC_PLAYER_STATE = {}   # uid -> {"toxic_score","flagged_count","branded_toxic","last_flag_ts"}


def _find_profanity(text: str):
    """คืนรายการคำหยาบที่เจอในข้อความ (lowercase match แบบ substring ง่ายๆ — ตัว filter จริง
    จะซับซ้อนกว่านี้ เช่น กันการสะกดเลี่ยง/เว้นวรรคแทรก แต่โครงหลักพอใช้งานจริงได้)"""
    low = (text or "").lower()
    return [w for w in PROFANITY_WORDLIST if w in low]


def _censor_profanity(text: str, matched_words) -> str:
    censored = text
    for w in matched_words:
        censored = re.sub(re.escape(w), "*" * len(w), censored, flags=re.IGNORECASE)
    return censored


def are_friends(uid_a: str, uid_b: str) -> bool:
    """เช็คว่า uid_a/uid_b เป็นเพื่อนกันไหม จาก FRIENDS_LIST [6zz5f] — ใช้ร่วมกันทุกเกม"""
    if uid_a == uid_b:
        return True
    return any(f.get("uid") == uid_b for f in FRIENDS_LIST.get(uid_a, []))


# ---------- [ 6zz5f0b. Developer/System Chat Identity — ชื่อสีแดงในแชท ] --------------------
# Developer (ยศ "developer" ใน STAFF_MEMBERS เพิ่มไว้แล้วที่ [6p]) และข้อความที่เซิร์ฟเวอร์ส่งเอง
# ในนาม "ระบบ" (system) ใช้สีเดียวกัน (แดง) เพื่อให้ผู้เล่นแยกออกทันทีว่าข้อความนี้มาจากทีมงานจริง
# หรือจากเซิร์ฟเวอร์เอง ไม่ใช่ผู้เล่นทั่วไป — ยศพนักงานตรวจจาก STAFF_MEMBERS ซึ่งผูกกับ uid บัญชี
# จริงเท่านั้น (ตั้งได้ผ่าน /api/staff/register ที่ต้อง auth ยศ owner เท่านั้น [6p]) ไม่ใช่ค่าที่
# client ส่งมาเอง ผู้เล่นทั่วไปจึงปลอมชื่อตัวเองเป็น developer/system ไม่ได้
CHAT_SYSTEM_COLOR = "#FF3B30"   # แดง — ใช้ร่วมกันทั้ง badge developer และข้อความจากระบบ
SYSTEM_CHAT_UID = "system"      # uid พิเศษ ใช้ตอนเซิร์ฟเวอร์ส่งข้อความแชทเองในนาม "ระบบ"


def get_chat_identity(uid: str) -> dict:
    """คืน {"role", "name_color", "badge"} ให้ client เอาไปแสดงชื่อผู้ส่งในแชท
    - uid == SYSTEM_CHAT_UID -> role "system" สีแดง
    - uid อยู่ใน STAFF_MEMBERS ยศ "developer" -> role "developer" สีแดงเดียวกัน
    - ผู้เล่นทั่วไป -> role "player", name_color None (client ใช้สีปกติของตัวเอง)"""
    if uid == SYSTEM_CHAT_UID:
        return {"role": "system", "name_color": CHAT_SYSTEM_COLOR, "badge": "⚙️ System"}
    member = STAFF_MEMBERS.get(uid)
    if member and member.get("rank") == "developer":
        return {"role": "developer", "name_color": CHAT_SYSTEM_COLOR, "badge": "🛠️ Developer"}
    return {"role": "player", "name_color": None, "badge": None}


def send_system_chat_message(text: str, to_uid: str = None, room_id: str = None,
                              game_id: str = "system") -> dict:
    """ให้เซิร์ฟเวอร์ส่งข้อความแชทเองในนาม "ระบบ" (เช่น แจ้งเตือนแชร์เพลง [6v5b] หรือประกาศสั้น ๆ
    ในห้องแชท) ใช้สีเดียวกับ developer (CHAT_SYSTEM_COLOR) ผ่าน get_chat_identity() ด้านบน — ไม่ผ่าน
    moderate_chat_message() เพราะข้อความมาจากเซิร์ฟเวอร์เอง ไม่ใช่ผู้เล่นพิมพ์ จึงไม่ต้องกรองคำหยาบ"""
    identity = get_chat_identity(SYSTEM_CHAT_UID)
    payload = {"game_id": game_id, "from_uid": SYSTEM_CHAT_UID, "from_name": "ระบบ (System)",
               "text": text, "was_censored": False, "ts": time.time(), **identity}
    if to_uid:
        sio.emit('game_chat_message', payload, room=to_uid)
    elif room_id:
        sio.emit('game_chat_message', payload, room=_chat_room_name(room_id))
    return payload


def moderate_chat_message(from_uid: str, text: str, to_uid: str = None,
                           room_members=None, game_id: str = "unknown") -> dict:
    """จุดกลางที่ "ทุกเกม" เรียกก่อนส่งข้อความแชทออกจริง คืน dict:
      {"text": ข้อความที่จะส่งจริง (เซ็นเซอร์แล้วถ้าจำเป็น), "was_censored": bool,
       "toxic_branded": bool, "newly_branded": bool}
    กติกา: คำหยาบพิมพ์ได้ปกติถ้าเป็นบริบท "เพื่อนกัน" (DM กับเพื่อน หรือห้องที่ทุกคนเป็นเพื่อนกัน
    หมด) นอกนั้นเซ็นเซอร์ + สะสมคะแนน toxic ให้ผู้ส่ง ครบเกณฑ์แล้วยื่นรายงานเข้า Anti-Cheat Hub"""
    matched = _find_profanity(text)
    if not matched:
        state = TOXIC_PLAYER_STATE.get(from_uid, {})
        return {"text": text, "was_censored": False,
                "toxic_branded": state.get("branded_toxic", False), "newly_branded": False}

    friends_context = False
    if to_uid:
        friends_context = are_friends(from_uid, to_uid)
    elif room_members:
        others = [m for m in room_members if m != from_uid]
        friends_context = bool(others) and all(are_friends(from_uid, m) for m in others)

    if friends_context:
        state = TOXIC_PLAYER_STATE.get(from_uid, {})
        return {"text": text, "was_censored": False,
                "toxic_branded": state.get("branded_toxic", False), "newly_branded": False}

    # ไม่ใช่บริบทเพื่อน -> เซ็นเซอร์ + สะสมคะแนน toxic
    censored_text = _censor_profanity(text, matched)
    state = TOXIC_PLAYER_STATE.setdefault(from_uid, {"toxic_score": 0, "flagged_count": 0,
                                                      "branded_toxic": False, "last_flag_ts": 0})
    state["toxic_score"] += len(matched)
    state["flagged_count"] += 1
    state["last_flag_ts"] = time.time()

    newly_branded = False
    if not state["branded_toxic"] and state["flagged_count"] >= TOXIC_BRAND_THRESHOLD:
        state["branded_toxic"] = True
        newly_branded = True
        submit_cheat_report(from_uid, game_id, "toxic_language_repeated",
                            {"flagged_count": state["flagged_count"], "toxic_score": state["toxic_score"]})

    return {"text": censored_text, "was_censored": True,
            "toxic_branded": state["branded_toxic"], "newly_branded": newly_branded}


@app.route('/api/chat/send', methods=['POST'])
@require_auth_toggleable
def api_chat_send():
    """ทางเลือก REST สำหรับเกม/ระบบที่ไม่ได้ต่อ Socket.IO — body: {game_id, from_uid, from_name,
    text, to_uid?, room_members?} -> ผ่าน moderate_chat_message ก่อนคืนข้อความที่จะแสดงจริง"""
    body = request.json or {}
    from_uid, text = body.get("from_uid", ""), body.get("text", "")
    if not from_uid or not text:
        return jsonify({"st": "error", "msg": "ต้องระบุ from_uid และ text"}), 400
    result = moderate_chat_message(from_uid, text, to_uid=body.get("to_uid"),
                                   room_members=body.get("room_members"),
                                   game_id=body.get("game_id", "unknown"))
    identity = get_chat_identity(from_uid)  # role/name_color/badge — แดงถ้าเป็น developer
    return jsonify({"st": "ok", **result, **identity})


@app.route('/api/moderation/toxic/status/<uid>')
def api_moderation_toxic_status(uid):
    state = TOXIC_PLAYER_STATE.get(uid, {"toxic_score": 0, "flagged_count": 0,
                                          "branded_toxic": False, "last_flag_ts": 0})
    return jsonify({"st": "ok", "uid": uid, **state})


@app.route('/api/moderation/toxic/list')
def api_moderation_toxic_list():
    """แอดมินดูรายชื่อผู้เล่นที่ถูกตราหน้าว่า toxic แล้ว (ทุกเกม)"""
    branded = {uid: s for uid, s in TOXIC_PLAYER_STATE.items() if s.get("branded_toxic")}
    return jsonify({"st": "ok", "branded_toxic_uids": branded})


@sio.on('game_chat_send')
def on_game_chat_send(data):
    """Socket.IO event กลางที่ "ทุกเกม" ยิงเข้ามาส่งข้อความแชทได้ — data: {game_id, from_uid,
    from_name, text, to_uid? (แชทส่วนตัว), room_id? (แชทกลุ่ม/ห้อง), room_members? (รายชื่อ uid
    ในห้อง ใช้เช็คบริบทเพื่อน)} ผู้เล่นทุกคนต้อง join_room(uid) ไว้แล้วตอน connect (มีอยู่แล้วที่
    [ event: connect ] ด้านบนสุดของไฟล์) ถึงจะรับ DM ตรงนี้ได้"""
    data = data or {}
    from_uid, text = data.get("from_uid", ""), data.get("text", "")
    if not from_uid or not text:
        return
    result = moderate_chat_message(from_uid, text, to_uid=data.get("to_uid"),
                                   room_members=data.get("room_members"),
                                   game_id=data.get("game_id", "unknown"))
    identity = get_chat_identity(from_uid)  # role/name_color/badge — แดงถ้าเป็น developer
    payload = {"game_id": data.get("game_id", "unknown"), "from_uid": from_uid,
              "from_name": data.get("from_name", from_uid), "text": result["text"],
              "was_censored": result["was_censored"], "ts": time.time(), **identity}
    room_id = data.get("room_id")
    to_uid = data.get("to_uid")
    if to_uid:
        sio.emit('game_chat_message', payload, room=to_uid)
        sio.emit('game_chat_message', payload, room=from_uid)
    elif room_id:
        sio.emit('game_chat_message', payload, room=_chat_room_name(room_id))
    if result.get("newly_branded"):
        sio.emit('toxic_branded', {"uid": from_uid}, room=from_uid)


def _chat_room_name(room_id) -> str:
    return f"chat_room_{room_id}"


@sio.on('game_chat_join')
def on_game_chat_join(data):
    """data: {room_id} -> เข้าห้องแชทกลุ่มของเกมไหนก็ได้ (ใช้ร่วมกันทุกเกม เหมือนแพทเทิร์น
    voice room ที่ [voice_join] ด้านบน)"""
    room_id = (data or {}).get("room_id")
    if room_id:
        join_room(_chat_room_name(room_id))


@sio.on('game_chat_leave')
def on_game_chat_leave(data):
    room_id = (data or {}).get("room_id")
    if room_id:
        leave_room(_chat_room_name(room_id))


