# ---------- [ 6zz5f5. Lobby Mic — เสียงพากย์ CG ของตัวเอง ] ----------------------
# [UPGRADE] ตามที่ขอ — หน้าล็อบบี้ก่อนเริ่มเกมมีปุ่มไมค์ให้อัดเสียงตัวเอง แล้วเลือกใช้แทน
# เสียงพากย์ default ตอนเข้าฉาก CG ได้ (เผื่อเบื่อเสียงพากย์เดิมๆ) เป็นแค่ "อัดเสียงตัวเอง ->
# เก็บไฟล์ -> เล่นแทนแทร็กเดิมตอนถึงฉากนั้น" ธรรมดา ไม่มีการแปลง/โคลนเสียงเป็นเสียงคนอื่นหรือ
# ตัวละครใดๆ ทั้งสิ้น (voice cloning ไปเป็นเสียงคนอื่นเป็นเรื่องละเอียดอ่อนเรื่องยินยอม เลยไม่ทำ
# ส่วนนั้นให้) — เก็บไฟล์เสียงจริงไว้ที่ LOBBY_VOICE_DIR/<uid>/<slot_id>.<ext> ตาม pattern
# เดียวกับ GAME_UPLOADS_DIR ด้านบน ส่วน metadata เก็บแยกไว้ในตัวแปร LOBBY_VOICE_RECORDINGS
# ==========================================
LOBBY_VOICE_DIR = "lobby_voice_recordings"
os.makedirs(LOBBY_VOICE_DIR, exist_ok=True)
MAX_VOICE_CLIP_BYTES = 5 * 1024 * 1024          # 5MB ต่อคลิป กันอัดยาวเกินไป/สแปมพื้นที่ดิสก์
MAX_VOICE_CLIP_SECONDS = 15                     # แนะนำ client ฝั่งหน้าไมค์ตัดอัตโนมัติที่ ~15 วิ
                                                 # (server เช็คได้แค่จาก duration_sec ที่ client
                                                 # ส่งมาบอกเอง เพราะไม่มีไลบรารีแกะความยาวไฟล์เสียง
                                                 # อยู่ในนี้ — ถ้าอยากเช็คแม่นๆ ฝั่ง server แนะนำต่อ
                                                 # ffprobe/pydub เพิ่มเอง)
NARRATION_SLOT_IDS_DEFAULT = ["intro_cg", "loading_screen", "victory_cg", "defeat_cg"]
ALLOWED_VOICE_EXTENSIONS = {"webm", "ogg", "mp3", "wav", "m4a"}

LOBBY_VOICE_RECORDINGS = {}   # uid -> {slot_id: {"file_path","ext","label","duration_sec",
                               #                    "enabled","recorded_ts"}}


@app.route('/api/lobby/voice/record', methods=['POST'])
@require_auth_toggleable
def api_lobby_voice_record():
    """multipart/form-data: uid, slot_id, label?, duration_sec?, audio=<ไฟล์เสียงจากไมค์>
    บันทึกคลิปเสียงของ uid ไว้แทนเสียงพากย์ default ที่ slot นั้น (เช่น 'intro_cg') —
    slot_id ใช้ชื่ออะไรก็ได้ ไม่จำกัดแค่ NARRATION_SLOT_IDS_DEFAULT (เผื่ออยากเพิ่ม CG จุดใหม่)"""
    uid = request.form.get("uid", "")
    slot_id = request.form.get("slot_id", "")
    if not uid or not slot_id:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid และ slot_id"}), 400
    f = request.files.get("audio")
    if not f or not f.filename:
        return jsonify({"st": "error", "msg": "ไม่พบไฟล์เสียง (field ชื่อ 'audio')"}), 400
    ext = f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else ""
    if ext not in ALLOWED_VOICE_EXTENSIONS:
        return jsonify({"st": "error", "msg": f"นามสกุลไฟล์ต้องเป็นหนึ่งใน {sorted(ALLOWED_VOICE_EXTENSIONS)}"}), 400
    raw = f.read()
    if len(raw) > MAX_VOICE_CLIP_BYTES:
        return jsonify({"st": "error", "msg": f"ไฟล์ใหญ่เกิน {MAX_VOICE_CLIP_BYTES // (1024*1024)}MB"}), 400

    uid_dir = os.path.join(LOBBY_VOICE_DIR, uid)
    os.makedirs(uid_dir, exist_ok=True)
    file_path = os.path.join(uid_dir, f"{slot_id}.{ext}")
    with open(file_path, "wb") as out:
        out.write(raw)

    duration_sec = request.form.get("duration_sec", type=float)
    LOBBY_VOICE_RECORDINGS.setdefault(uid, {})[slot_id] = {
        "file_path": file_path, "ext": ext,
        "label": request.form.get("label", slot_id),
        "duration_sec": duration_sec, "enabled": True, "recorded_ts": time.time(),
    }
    return jsonify({"st": "ok", "slot_id": slot_id, "recording": LOBBY_VOICE_RECORDINGS[uid][slot_id]})


@app.route('/api/lobby/voice/list')
def api_lobby_voice_list():
    """?uid=xxx -> คลิปเสียงที่อัดไว้ทั้งหมดของ uid นี้ (ทุก slot) + รายชื่อ slot มาตรฐาน
    ที่ยังไม่ได้อัด (default_slots_available) ให้ UI โชว์ปุ่มไมค์ว่างๆ ให้อัดเพิ่มได้"""
    uid = request.args.get("uid", "")
    recorded = LOBBY_VOICE_RECORDINGS.get(uid, {})
    return jsonify({"st": "ok", "uid": uid, "recordings": recorded,
                    "default_slots_available": [s for s in NARRATION_SLOT_IDS_DEFAULT if s not in recorded]})


@app.route('/api/lobby/voice/set_active', methods=['POST'])
@require_auth_toggleable
def api_lobby_voice_set_active():
    """body: {uid, slot_id, enabled: bool} -> เปิด/ปิดใช้เสียงพากย์ของตัวเองสำหรับ slot นั้น
    (ปิดแล้วกลับไปใช้เสียงพากย์ default ตามเดิม โดยไม่ต้องลบคลิปที่อัดไว้)"""
    body = request.json or {}
    uid, slot_id, enabled = body.get("uid", ""), body.get("slot_id", ""), bool(body.get("enabled", True))
    rec = LOBBY_VOICE_RECORDINGS.get(uid, {}).get(slot_id)
    if not rec:
        return jsonify({"st": "error", "msg": "ยังไม่มีคลิปเสียงของ slot นี้"}), 404
    rec["enabled"] = enabled
    return jsonify({"st": "ok", "recording": rec})


@app.route('/api/lobby/voice/<slot_id>', methods=['DELETE'])
@require_auth_toggleable
def api_lobby_voice_delete(slot_id):
    """?uid=xxx -> ลบคลิปเสียงของ slot นี้ทิ้ง กลับไปใช้เสียงพากย์ default ทันที"""
    uid = request.args.get("uid", "")
    rec = LOBBY_VOICE_RECORDINGS.get(uid, {}).pop(slot_id, None)
    if rec and os.path.isfile(rec["file_path"]):
        try:
            os.remove(rec["file_path"])
        except OSError:
            pass
    return jsonify({"st": "ok"})


@app.route('/api/lobby/voice/active_narration')
def api_lobby_voice_active_narration():
    """?uid=xxx&slot_id=intro_cg -> เกมเรียกตรงนี้ตอนจะเล่นฉาก CG แต่ละจุด เพื่อรู้ว่าจะเล่น
    ไฟล์เสียงพากย์ของผู้เล่นเอง (ถ้าอัดไว้แล้วและเปิดใช้งานอยู่) หรือใช้เสียงพากย์ default ตามเดิม"""
    uid, slot_id = request.args.get("uid", ""), request.args.get("slot_id", "")
    rec = LOBBY_VOICE_RECORDINGS.get(uid, {}).get(slot_id)
    if rec and rec.get("enabled"):
        return jsonify({"st": "ok", "source": "custom", "file_path": rec["file_path"],
                        "duration_sec": rec.get("duration_sec")})
    return jsonify({"st": "ok", "source": "default"})


VMAX_MODULES["lobby_voice_narration"] = {
    "desc": "ปุ่มไมค์หน้าล็อบบี้ก่อนเริ่มเกม อัดเสียงตัวเองแทนเสียงพากย์ default ตอนเข้าฉาก CG ได้ "
            "(เช่น intro/loading/victory/defeat) เปิด-ปิดใช้งานเป็นจุดๆ ได้โดยไม่ต้องลบคลิป — "
            "อัดแค่เสียงตัวเองล้วนๆ ไม่มีการแปลง/โคลนเป็นเสียงคนอื่น",
    "routes": ["/api/lobby/voice/record", "/api/lobby/voice/list", "/api/lobby/voice/set_active",
              "/api/lobby/voice/<slot_id> [DELETE]", "/api/lobby/voice/active_narration"],
}


# ---------- [ 6zz5g. ตั้งชุดเสบียง (Resupply Loadout Presets) ] -------------------
# ตรงกับภาพ "ตั้งชุดเสบียงใหม่" — พรีเซ็ตไอเทม/อาวุธ/เกราะที่จะถูกเรียกเสบียงลงมาให้
# ตอนเข้าโซนสงคราม จำกัดจำนวนครั้งเรียกใช้ต่อรอบ (เหมือน "เรียกเสบียงโซนสงครามได้อีก x/y")
RESUPPLY_LOADOUT_SLOTS_MAX = 6
RESUPPLY_LOADOUTS = {}  # uid -> {slot_idx(str): {"name","items":[{"item","qty"}]}}
RESUPPLY_CALLS_MAX_PER_MATCH = 3
RESUPPLY_CALLS_USED = {}  # uid -> int

@app.route('/api/resupply/loadouts')
def api_resupply_loadouts():
    """?uid=xxx -> ชุดเสบียงที่ตั้งไว้ทั้งหมด (สูงสุด RESUPPLY_LOADOUT_SLOTS_MAX ชุด)"""
    uid = request.args.get("uid", "")
    return jsonify({"st": "ok", "loadouts": RESUPPLY_LOADOUTS.get(uid, {}), "max_slots": RESUPPLY_LOADOUT_SLOTS_MAX})

@app.route('/api/resupply/save_loadout', methods=['POST'])
@require_auth_toggleable
def api_resupply_save_loadout():
    """body: {uid, slot, name, items:[{item,qty}]} -> บันทึกชุดเสบียงลงช่องที่เลือก (กด 'เสร็จสิ้น'/'บันทึก' ในภาพ)"""
    body = request.json or {}
    uid, slot = body.get("uid", ""), str(body.get("slot", "0"))
    if int(slot) >= RESUPPLY_LOADOUT_SLOTS_MAX:
        return jsonify({"st": "error", "msg": f"มีได้สูงสุด {RESUPPLY_LOADOUT_SLOTS_MAX} ชุด"}), 400
    RESUPPLY_LOADOUTS.setdefault(uid, {})[slot] = {"name": body.get("name", f"ชุดเสบียง {int(slot)+1}"),
                                                   "items": body.get("items", [])}
    return jsonify({"st": "ok", "loadout": RESUPPLY_LOADOUTS[uid][slot]})

@app.route('/api/resupply/call', methods=['POST'])
@require_auth_toggleable
def api_resupply_call():
    """body: {uid, slot} -> เรียกชุดเสบียงลงมาจริงระหว่างแมตช์ (จำกัด RESUPPLY_CALLS_MAX_PER_MATCH ครั้งต่อรอบ,
    เติมของจากชุดพรีเซ็ตเข้ากระเป๋าเป้ทันที)"""
    body = request.json or {}
    uid, slot = body.get("uid", ""), str(body.get("slot", "0"))
    used = RESUPPLY_CALLS_USED.get(uid, 0)
    if used >= RESUPPLY_CALLS_MAX_PER_MATCH:
        return jsonify({"st": "error", "msg": "เรียกเสบียงครบจำนวนครั้งของรอบนี้แล้ว"}), 429
    loadout = RESUPPLY_LOADOUTS.get(uid, {}).get(slot)
    if not loadout:
        return jsonify({"st": "error", "msg": "ไม่พบชุดเสบียงในช่องนี้"}), 404
    st = storage_get(uid)
    for it in loadout["items"]:
        for s in st["backpack"].values():
            if s["item"] == it["item"]:
                s["qty"] += it["qty"]
                break
        else:
            if len(st["backpack"]) < st["backpack_slots"]:
                st["backpack"][str(len(st["backpack"]))] = {"item": it["item"], "qty": it["qty"]}
    RESUPPLY_CALLS_USED[uid] = used + 1
    return jsonify({"st": "ok", "calls_left": RESUPPLY_CALLS_MAX_PER_MATCH - RESUPPLY_CALLS_USED[uid],
                    "backpack": st["backpack"]})

@app.route('/api/resupply/reset_calls', methods=['POST'])
@require_auth_toggleable
def api_resupply_reset_calls():
    """body: {uid} -> รีเซ็ตจำนวนครั้งเรียกเสบียง (เรียกตอนเริ่มแมตช์ใหม่)"""
    body = request.json or {}
    RESUPPLY_CALLS_USED[body.get("uid", "")] = 0
    return jsonify({"st": "ok"})

