# [ 6zz6k. หน้าจอหลัก (Main Dashboard) ] --------
# โปรไฟล์ตัวละคร + แถบสกุลเงิน/สเตมิน่า + เมนูด่วน + ทางเข้าโหมดต่อสู้ ตามภาพหน้า Dashboard
# ==========================================
CHARACTER_PROFILE_DEFAULT = {
    "name": "Neko", "combat_power": 793000, "title": "ผู้เดินทางแห่งรุ่งอรุณ", "frame": "frame_gold_01",
}
PLAYER_CURRENCY = {}  # uid -> {diamond, gold, scrap, stamina, stamina_max}

def _currency_get(uid):
    # "scrap" (สแครป) เพิ่มเข้ามาใน [6zz6w-x] เป็นสกุลเงินรองคู่กับ gold — ได้จากการทุบถังบนแผนที่/
    # ขายปลา ใช้จ่ายค่าเช่าโรงแรม/ซื้อกุญแจ NPC/สินบนกล้องวงจรปิด/ซื้อขายในแผงขายของผู้เล่นได้เหมือน gold
    # "vial" (หลอดตัวอย่าง) เพิ่มเข้ามาใน [VMAX EVENTS — FIELD VIAL DRIVE] เป็นสกุลเงินเฉพาะกิจของ
    # อีเวนต์เก็บตัวอย่างภาคสนาม ได้จากจุดเก็บตัวอย่างในแมพเท่านั้น ใช้แลกของสุ่มกับนายหน้าของอีเวนต์นั้น
    return PLAYER_CURRENCY.setdefault(
        uid, {"diamond": 0, "gold": 0, "scrap": 0, "vial": 0, "stamina": 120, "stamina_max": 120})


def _currency_pay(uid: str, pay_with: str, amount: int):
    """หักเงินสกุล pay_with (ต้องเป็น 'gold', 'scrap' หรือ 'vial') จำนวน amount จากผู้เล่น uid ถ้าไม่พอคืน False
    (ใช้ร่วมกันทั่วทั้งระบบใหม่ [6zz6w-x]: โรงแรม/กุญแจ NPC/กล้องวงจรปิด/แผงขายของ เพื่อไม่ให้ตรรกะจ่ายเงิน
    กระจัดกระจายซ้ำซ้อนหลายจุด — "vial" เพิ่มเข้ามาใน [VMAX EVENTS — FIELD VIAL DRIVE])"""
    if pay_with not in ("gold", "scrap", "vial"):
        return False
    cur = _currency_get(uid)
    if cur[pay_with] < amount:
        return False
    cur[pay_with] -= amount
    return True

# ==========================================
# [ BANKNOTE EXCHANGE — แลกเงินเติม (credits) เป็นธนบัตรในเกม ]
# เงินเติมจากเว็บ/topup เข้า P["credits"] / WALLET แล้วผู้เล่นนำ credits
# มาแลกเป็น "ธนบัตร" (แบงค์ในเกม) เก็บเป็นใบตามราคาหน้าบัตร
# ไม่ใช่บัตรรูปลักษณ์ป้อม — เป็นเงินสดในเกมรูปแบบธนบัตร
# ==========================================
BANKNOTE_DATA_DIR = os.environ.get("BANKNOTE_DATA_DIR", "banknote_data")
os.makedirs(BANKNOTE_DATA_DIR, exist_ok=True)
_BANKNOTE_LOCK = threading.Lock()
_BANKNOTE_CACHE = {}  # uid -> state

BANKNOTE_PACKS = {
    "pack_note_100":  {"name_th": "ธนบัตร 100", "face_value": 100, "qty": 1,
        "credit_cost": int(os.environ.get("BANKNOTE_COST_100", "10")), "currency_from": "credits"},
    "pack_note_500":  {"name_th": "ธนบัตร 500", "face_value": 500, "qty": 1,
        "credit_cost": int(os.environ.get("BANKNOTE_COST_500", "45")), "currency_from": "credits"},
    "pack_note_1000": {"name_th": "ธนบัตร 1,000", "face_value": 1000, "qty": 1,
        "credit_cost": int(os.environ.get("BANKNOTE_COST_1000", "85")), "currency_from": "credits"},
    "pack_note_5000": {"name_th": "ธนบัตร 5,000", "face_value": 5000, "qty": 1,
        "credit_cost": int(os.environ.get("BANKNOTE_COST_5000", "400")), "currency_from": "credits"},
    "pack_note_10000": {"name_th": "ธนบัตร 10,000", "face_value": 10000, "qty": 1,
        "credit_cost": int(os.environ.get("BANKNOTE_COST_10000", "750")), "currency_from": "credits"},
    "pack_bundle_small": {"name_th": "ชุดธนบัตรเล็ก (100×5)", "face_value": 100, "qty": 5,
        "credit_cost": int(os.environ.get("BANKNOTE_COST_BUNDLE_S", "45")), "currency_from": "credits"},
    "pack_bundle_mid": {"name_th": "ชุดธนบัตรกลาง (1000×3)", "face_value": 1000, "qty": 3,
        "credit_cost": int(os.environ.get("BANKNOTE_COST_BUNDLE_M", "240")), "currency_from": "credits"},
}

BANKNOTE_DAILY_FACE_LIMIT = int(os.environ.get("BANKNOTE_DAILY_FACE_LIMIT", "50000"))
BANKNOTE_WEEKLY_FACE_LIMIT = int(os.environ.get("BANKNOTE_WEEKLY_FACE_LIMIT", "200000"))

def _banknote_today():
    import datetime as _dt
    return _dt.datetime.fromtimestamp(time.time()).strftime("%Y-%m-%d")

def _banknote_week():
    import datetime as _dt
    iso = _dt.datetime.fromtimestamp(time.time()).isocalendar()
    return "%s-W%02d" % (iso[0], iso[1])

def _banknote_path(uid):
    safe = "".join(c if c.isalnum() or c in "-_" else "_" for c in str(uid))[:96]
    return os.path.join(BANKNOTE_DATA_DIR, "notes_%s.json" % safe)

def _banknote_default():
    return {"notes": {}, "daily_face": {}, "weekly_face": {}, "ledger": [], "updated_at": time.time()}

def _banknote_load(uid):
    with _BANKNOTE_LOCK:
        if uid in _BANKNOTE_CACHE:
            return _BANKNOTE_CACHE[uid]
        st = _banknote_default()
        path = _banknote_path(uid)
        if os.path.isfile(path):
            try:
                with open(path, "r", encoding="utf-8") as f:
                    raw = json.load(f)
                if isinstance(raw, dict):
                    st["notes"] = {str(k): int(v) for k, v in (raw.get("notes") or {}).items()}
                    st["daily_face"] = dict(raw.get("daily_face") or {})
                    st["weekly_face"] = dict(raw.get("weekly_face") or {})
                    st["ledger"] = list(raw.get("ledger") or [])[-200:]
                    st["updated_at"] = float(raw.get("updated_at") or time.time())
            except Exception:
                pass
        _BANKNOTE_CACHE[uid] = st
        return st

def _banknote_save(uid, st=None):
    with _BANKNOTE_LOCK:
        st = st or _BANKNOTE_CACHE.get(uid) or _banknote_default()
        st["updated_at"] = time.time()
        st["ledger"] = list(st.get("ledger") or [])[-200:]
        _BANKNOTE_CACHE[uid] = st
        path = _banknote_path(uid)
        tmp = path + ".tmp"
        try:
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(st, f, ensure_ascii=False, indent=0)
            os.replace(tmp, path)
        except Exception as exc:
            try:
                if os.path.isfile(tmp):
                    os.remove(tmp)
            except Exception:
                pass
            print("[BANKNOTE] save failed uid=%s: %s" % (uid, exc))

def _banknote_total_face(st):
    total = 0
    for face, qty in (st.get("notes") or {}).items():
        try:
            total += int(face) * int(qty)
        except (TypeError, ValueError):
            pass
    return total

def _banknote_limits(uid):
    st = _banknote_load(uid)
    today, week = _banknote_today(), _banknote_week()
    d_used = int(st["daily_face"].get(today, 0))
    w_used = int(st["weekly_face"].get(week, 0))
    return {
        "daily_face_limit": BANKNOTE_DAILY_FACE_LIMIT,
        "daily_face_used": d_used,
        "daily_face_remaining": max(0, BANKNOTE_DAILY_FACE_LIMIT - d_used),
        "weekly_face_limit": BANKNOTE_WEEKLY_FACE_LIMIT,
        "weekly_face_used": w_used,
        "weekly_face_remaining": max(0, BANKNOTE_WEEKLY_FACE_LIMIT - w_used),
        "today": today, "week": week,
    }

def _banknote_get_credits(uid):
    try:
        if "P" in globals() and isinstance(P, dict) and str(P.get("uid", "")) == str(uid):
            return int(P.get("credits", 0) or 0)
    except Exception:
        pass
    try:
        if "set_current_uid" in globals():
            set_current_uid(uid)
            if isinstance(P, dict):
                return int(P.get("credits", 0) or 0)
    except Exception:
        pass
    return 0

def _banknote_debit_credits(uid, amount):
    amount = int(amount)
    if amount <= 0:
        return False, "จำนวนไม่ถูกต้อง"
    try:
        if "set_current_uid" in globals():
            set_current_uid(uid)
        if not isinstance(P, dict):
            return False, "ไม่พบข้อมูลผู้เล่น"
        if int(P.get("credits", 0) or 0) < amount:
            return False, "เครดิตเงินเติมไม่พอ"
        P["credits"] = int(P["credits"]) - amount
        if "WALLET" in globals() and isinstance(WALLET, dict):
            WALLET["balance"] = P["credits"]
            WALLET.setdefault("history", []).append({
                "ts": time.time(), "source": "banknote_exchange", "uid": uid,
                "amount": -amount, "note": "แลกเป็นธนบัตรในเกม",
            })
        return True, P["credits"]
    except Exception as e:
        return False, str(e)

def banknote_exchange(uid, pack_id, qty=1):
    pack = BANKNOTE_PACKS.get(pack_id)
    if not pack:
        return {"st": "error", "msg": "ไม่มีแพ็กธนบัตรนี้"}
    qty = max(1, min(50, int(qty or 1)))
    cost = int(pack["credit_cost"]) * qty
    face = int(pack["face_value"])
    note_qty = int(pack["qty"]) * qty
    face_total = face * note_qty
    lim = _banknote_limits(uid)
    if face_total > lim["daily_face_remaining"]:
        return {"st": "error", "msg": "เกินลิมิตมูลค่าธนบัตรรายวัน (เหลือ %s)" % lim["daily_face_remaining"], "limits": lim}
    if face_total > lim["weekly_face_remaining"]:
        return {"st": "error", "msg": "เกินลิมิตมูลค่าธนบัตรรายสัปดาห์ (เหลือ %s)" % lim["weekly_face_remaining"], "limits": lim}
    ok, bal_or_msg = _banknote_debit_credits(uid, cost)
    if not ok:
        return {"st": "error", "msg": bal_or_msg, "limits": lim}
    with _BANKNOTE_LOCK:
        st = _banknote_load(uid)
        key = str(face)
        st["notes"][key] = int(st["notes"].get(key, 0)) + note_qty
        today, week = lim["today"], lim["week"]
        st["daily_face"][today] = int(st["daily_face"].get(today, 0)) + face_total
        st["weekly_face"][week] = int(st["weekly_face"].get(week, 0)) + face_total
        st.setdefault("ledger", []).append({
            "ts": time.time(), "type": "exchange", "pack_id": pack_id,
            "face_value": face, "note_qty": note_qty, "credit_cost": cost,
            "credits_left": bal_or_msg,
        })
        _banknote_save(uid, st)
    return {
        "st": "ok",
        "msg": "แลก %s ×%s สำเร็จ" % (pack["name_th"], qty),
        "pack_id": pack_id,
        "notes_gained": {str(face): note_qty},
        "notes": dict(st["notes"]),
        "total_face_value": _banknote_total_face(st),
        "credits_left": bal_or_msg,
        "limits": _banknote_limits(uid),
    }

@app.route('/api/banknote/catalog')
def api_banknote_catalog():
    uid = str(request.args.get("uid") or (P.get("uid") if isinstance(P, dict) else "") or "guest")
    st = _banknote_load(uid)
    return jsonify({
        "st": "ok", "packs": BANKNOTE_PACKS, "notes": st["notes"],
        "total_face_value": _banknote_total_face(st),
        "credits": _banknote_get_credits(uid), "limits": _banknote_limits(uid),
    })

@app.route('/api/banknote/status')
@require_auth
def api_banknote_status():
    uid = P["uid"] if isinstance(P, dict) else str(request.args.get("uid") or "")
    st = _banknote_load(uid)
    return jsonify({
        "st": "ok", "notes": st["notes"],
        "total_face_value": _banknote_total_face(st),
        "credits": _banknote_get_credits(uid), "limits": _banknote_limits(uid),
        "ledger_tail": (st.get("ledger") or [])[-20:],
    })

@app.route('/api/banknote/exchange', methods=['POST'])
@require_auth
def api_banknote_exchange():
    """POST {pack_id, qty?} — ใช้เงินเติม (credits) แลกธนบัตรในเกม"""
    uid = P["uid"]
    body = request.get_json(silent=True) or {}
    result = banknote_exchange(uid, str(body.get("pack_id") or ""), body.get("qty", 1))
    code = 200 if result.get("st") == "ok" else 400
    if "ลิมิต" in str(result.get("msg", "")):
        code = 429
    return jsonify(result), code

