# ==========================================
# [ 6zz6l. ผู้ช่วยอัจฉริยะอัตโนมัติ (Academy Assistant) ] --------
# จัดการงานประจำวันอัตโนมัติ (การ์เดน/ล่ารางวัล/นีเบลุนเกน/สมาคม/ร้านค้า/อื่นๆ) + ตัวเร่งความเร็ว Matrix Acceleration
# ==========================================
ASSISTANT_TASK_CATALOG = {
    "garden_duty": {"name_th": "งานการ์เดน", "name_jp": "ガーデン業務"},
    "world_hunt": {"name_th": "เควสต์ล่ารางวัล", "name_jp": "ワールドハント"},
    "nibelungen": {"name_th": "นีเบลุนเกน", "name_jp": "ニーベルンゲン"},
    "circle_duty": {"name_th": "งานสมาคม", "name_jp": "サークル業務"},
    "shop_purchase": {"name_th": "ซื้อของในร้านค้า", "name_jp": "ショップ購入"},
    "other_duty": {"name_th": "งานอื่นๆ", "name_jp": "他の業務"},
}
ASSISTANT_ASSIGNMENTS = {}  # uid -> {task_id: [character_ids]}
ASSISTANT_SPEED = {}  # uid -> multiplier (1-10)

@app.route('/api/assistant/tasks')
def api_assistant_tasks():
    """?uid=xxx -> รายการงานอัตโนมัติทั้งหมด พร้อมตัวละครที่มอบหมายไว้ในแต่ละงาน"""
    uid = request.args.get("uid", "")
    assigned = ASSISTANT_ASSIGNMENTS.setdefault(uid, {})
    tasks = {tid: {**info, "assigned": assigned.get(tid, [])} for tid, info in ASSISTANT_TASK_CATALOG.items()}
    return jsonify({"st": "ok", "tasks": tasks, "speed": ASSISTANT_SPEED.get(uid, 1)})

@app.route('/api/assistant/assign', methods=['POST'])
@require_auth_toggleable
def api_assistant_assign():
    """body: {uid, task_id, character_ids:[...]} -> จัดตัวละครลงทีมสำหรับงานอัตโนมัติที่ระบุ"""
    body = request.json or {}
    uid, task_id = body.get("uid", ""), body.get("task_id", "")
    character_ids = body.get("character_ids", [])
    if task_id not in ASSISTANT_TASK_CATALOG:
        return jsonify({"st": "error", "msg": "ไม่มีงานนี้ในระบบผู้ช่วย"}), 400
    ASSISTANT_ASSIGNMENTS.setdefault(uid, {})[task_id] = character_ids
    return jsonify({"st": "ok", "task_id": task_id, "assigned": character_ids})

@app.route('/api/assistant/speed', methods=['POST'])
@require_auth_toggleable
def api_assistant_speed():
    """body: {uid, multiplier} -> ปรับระดับ Matrix Acceleration (ความเร็วดำเนินงานอัตโนมัติ, 1-10 เท่า)"""
    body = request.json or {}
    uid = body.get("uid", "")
    multiplier = max(1, min(10, int(body.get("multiplier", 1))))
    ASSISTANT_SPEED[uid] = multiplier
    return jsonify({"st": "ok", "speed": multiplier})

@app.route('/api/assistant/quick_execute', methods=['POST'])
@require_auth_toggleable
def api_assistant_quick_execute():
    """body: {uid} -> ดำเนินการงานที่มอบหมายไว้ทั้งหมดในครั้งเดียว (クイック実行) คืนสรุปรางวัลต่อ task"""
    body = request.json or {}
    uid = body.get("uid", "")
    assigned = ASSISTANT_ASSIGNMENTS.get(uid, {})
    speed = ASSISTANT_SPEED.get(uid, 1)
    results = {}
    for task_id, chars in assigned.items():
        if not chars:
            continue
        base = len(chars) * 10
        results[task_id] = {"gold_earned": base * speed, "characters_used": chars}
    return jsonify({"st": "ok", "executed": results, "speed_used": speed})

VMAX_MODULES["academy_assistant"] = {
    "desc": "ผู้ช่วยอัจฉริยะอัตโนมัติ: มอบหมายตัวละครทำงานประจำวัน (การ์เดน/ล่ารางวัล/นีเบลุนเกน/สมาคม/ร้านค้า) พร้อมปรับความเร็ว Matrix Acceleration และกดดำเนินการด่วนทั้งหมด",
    "routes": ["/api/assistant/tasks", "/api/assistant/assign", "/api/assistant/speed", "/api/assistant/quick_execute"],
}


# ==========================================
# [ 6zz6m. แผนพัฒนาพลังงานธาตุ (Element Plan) ] --------
# ธาตุหลัก 5 + แกนกลาง, ผลิตทรัพยากรแบบ Idle รายชั่วโมง, เลเวลรวมและโบนัส Elemental Resonance
# ==========================================
ELEMENT_TYPES = ["water", "wind", "fire", "earth", "spirit", "core"]
ELEMENT_PLAN_STATE = {}  # uid -> {"levels": {elem: int}, "last_claim_ts": float}
ELEMENT_IDLE_RATE_PER_HOUR = 50  # ต่อเลเวลรวม 1 หน่วย

def _element_state_get(uid):
    return ELEMENT_PLAN_STATE.setdefault(uid, {"levels": {e: 0 for e in ELEMENT_TYPES}, "last_claim_ts": time.time()})

def _element_total_level(state):
    return sum(state["levels"].values())

def _element_resonance_bonus(total_level):
    # ทุกๆ 100 เลเวลรวม เพิ่มพลังกดดันธาตุ +5%
    return (total_level // 100) * 5

@app.route('/api/element/state')
def api_element_state():
    """?uid=xxx -> เลเวลของแต่ละธาตุ, เลเวลรวม, โบนัส Elemental Resonance, และทรัพยากรสะสมที่ยังไม่เคลม"""
    uid = request.args.get("uid", "")
    state = _element_state_get(uid)
    total = _element_total_level(state)
    pending_hours = (time.time() - state["last_claim_ts"]) / 3600.0
    pending = int(pending_hours * ELEMENT_IDLE_RATE_PER_HOUR * max(1, total) / 100)
    return jsonify({"st": "ok", "levels": state["levels"], "total_level": total,
                    "resonance_bonus_pct": _element_resonance_bonus(total), "pending_reward": pending})

@app.route('/api/element/claim_idle', methods=['POST'])
@require_auth_toggleable
def api_element_claim_idle():
    """body: {uid} -> รับทรัพยากรสะสมต่อชั่วโมงจากระบบผลิตแบบ Idle (放置報酬受取)"""
    body = request.json or {}
    uid = body.get("uid", "")
    state = _element_state_get(uid)
    total = _element_total_level(state)
    pending_hours = (time.time() - state["last_claim_ts"]) / 3600.0
    reward = int(pending_hours * ELEMENT_IDLE_RATE_PER_HOUR * max(1, total) / 100)
    state["last_claim_ts"] = time.time()
    cur = _currency_get(uid)
    cur["gold"] += reward
    return jsonify({"st": "ok", "claimed": reward, "gold_total": cur["gold"]})

@app.route('/api/element/levelup', methods=['POST'])
@require_auth_toggleable
def api_element_levelup():
    """body: {uid, element} -> เพิ่มเลเวลธาตุที่ระบุ (water/wind/fire/earth/spirit/core) อีก 1 ระดับ"""
    body = request.json or {}
    uid, elem = body.get("uid", ""), body.get("element", "")
    if elem not in ELEMENT_TYPES:
        return jsonify({"st": "error", "msg": "ไม่มีธาตุนี้ในระบบ"}), 400
    state = _element_state_get(uid)
    state["levels"][elem] += 1
    total = _element_total_level(state)
    return jsonify({"st": "ok", "element": elem, "new_level": state["levels"][elem], "total_level": total,
                    "resonance_bonus_pct": _element_resonance_bonus(total)})

VMAX_MODULES["element_plan"] = {
    "desc": "แผนพัฒนาพลังงานธาตุ 5 ธาตุ + แกนกลาง, ผลิตทรัพยากร Idle รายชั่วโมง, เลเวลรวมและโบนัส Elemental Resonance",
    "routes": ["/api/element/state", "/api/element/claim_idle", "/api/element/levelup"],
}


# ==========================================
# [ 6zz6n. คลังไอเทมและการสังเคราะห์ (My Bag) ] --------
# หมวดหมู่ไอเทม (ทั่วไป/คอร์/ดราก้อนไกลฟ์/ฟิโลโซเฟอร์สโตน/สปิริต) + สังเคราะห์ชิ้นส่วนเป็นไอเทมเต็มชิ้น
# ==========================================
BAG_CATEGORIES = ["item", "core", "dragon_glyph", "philosopher_stone", "spirit"]
BAG_INVENTORY = {}  # uid -> {category: {item_id: qty}}
# [UPGRADE - dupe glitch guard] BAG_INVENTORY โดนแตะจากหลายจุดที่ไม่เกี่ยวกันเลย (สังเคราะห์ไอเทม,
# คีย์การ์ด pickup/swipe, เก็บทรัพยากรบนแผนที่, โรงกลั่นน้ำมัน) ทุกจุดเป็นแบบ "เช็คก่อน-ค่อยหัก/เพิ่ม
# ทีหลัง" ไม่ atomic ถ้ายิง 2 คำขอชนกัน (กดรัว ๆ, network retry, สคริปต์โกงยิงขนาน) จะเกิดช่องโหว่แบบ
# ในคลิปที่คนใช้บัค "ใช้ไอเทม" กับ "ทิ้ง/เก็บไอเทมใหม่" สวนทางกันจนได้ของซ้ำ (dupe) — ใช้ lock
# เดียวกันตัวนี้ครอบทุกฟังก์ชันที่อ่าน+เขียน BAG_INVENTORY ของ uid เดียวกัน กันไว้ทั้งระบบ ไม่ใช่แค่
# จุดคีย์การ์ดจุดเดียว ถ้าเพิ่มฟีเจอร์ใหม่ที่แตะกระเป๋านี้ (เช่น "ทิ้งไอเทม", เทรด) ต้องล็อกด้วยตัวนี้เสมอ
BAG_LOCK = threading.Lock()
BAG_SYNTHESIS_RECIPES = {
    "sr_dragon_glyph": {"category": "dragon_glyph", "fragment_id": "dragon_glyph_fragment", "fragments_needed": 100},
}

def _bag_get(uid):
    return BAG_INVENTORY.setdefault(uid, {c: {} for c in BAG_CATEGORIES})

@app.route('/api/bag/inventory')
def api_bag_inventory():
    """?uid=xxx&category=xxx(optional) -> รายการไอเทมในคลัง แยกตามหมวดหมู่"""
    uid = request.args.get("uid", "")
    category = request.args.get("category")
    inv = _bag_get(uid)
    if category:
        if category not in BAG_CATEGORIES:
            return jsonify({"st": "error", "msg": "ไม่มีหมวดหมู่นี้"}), 400
        return jsonify({"st": "ok", "category": category, "items": inv[category]})
    return jsonify({"st": "ok", "categories": BAG_CATEGORIES, "inventory": inv})

@app.route('/api/bag/synthesize', methods=['POST'])
@require_auth_toggleable
def api_bag_synthesize():
    """body: {uid, recipe_id} -> รวมชิ้นส่วนย่อย (เช่น ชิ้นส่วน SR Dragon Glyph) ให้เป็นไอเทมเต็มชิ้นตามสูตร (合成)"""
    body = request.json or {}
    uid, recipe_id = body.get("uid", ""), body.get("recipe_id", "")
    recipe = BAG_SYNTHESIS_RECIPES.get(recipe_id)
    if not recipe:
        return jsonify({"st": "error", "msg": "ไม่มีสูตรสังเคราะห์นี้"}), 400
    with BAG_LOCK:  # [UPGRADE] กันสังเคราะห์ซ้ำจาก 2 คำขอพร้อมกันด้วยชิ้นส่วนกองเดียวกัน
        inv = _bag_get(uid)
        cat_items = inv[recipe["category"]]
        have = cat_items.get(recipe["fragment_id"], 0)
        if have < recipe["fragments_needed"]:
            return jsonify({"st": "error", "msg": "ชิ้นส่วนไม่พอสำหรับสังเคราะห์"}), 400
        cat_items[recipe["fragment_id"]] = have - recipe["fragments_needed"]
        cat_items[recipe_id] = cat_items.get(recipe_id, 0) + 1
        fragments_left = cat_items[recipe["fragment_id"]]
    return jsonify({"st": "ok", "crafted": recipe_id, "fragments_left": fragments_left})

VMAX_MODULES["item_bag"] = {
    "desc": "คลังไอเทม (ทั่วไป/คอร์/ดราก้อนไกลฟ์/ฟิโลโซเฟอร์สโตน/สปิริต) และระบบสังเคราะห์รวมชิ้นส่วนเป็นไอเทมเต็มชิ้น",
    "routes": ["/api/bag/inventory", "/api/bag/synthesize"],
}


