# ==========================================
# [ 6zz6p. Battle Pass ประจำอีเวนต์ ] --------
# แท็บ Present/Plan, เลเวลพาสและ EXP, ภารกิจประจำสัปดาห์, ตารางรางวัลฟรี/พรีเมียม
# ==========================================
BATTLE_PASS_EXP_PER_LEVEL = 40
BP_COINS_PER_MISSION = 10          # เหรียญพาส (bp_coin) ต่อภารกิจประจำสัปดาห์ที่ทำเสร็จ
BP_COINS_PER_CLAIM_FREE = 15       # ต่อการเคลมเลเวล (แถวฟรี)
BP_COINS_PER_CLAIM_PREMIUM = 25    # เพิ่มอีกถ้าเป็นพรีเมียม
BATTLE_PASS_WEEKLY_MISSIONS = {
    "login_once": {"name_th": "ล็อกอินเกม 1 ครั้ง", "points": 20, "target": 1},
    "use_stamina_1000": {"name_th": "ใช้สเตมิน่าสะสมครบ 1,000", "points": 10, "target": 1000},
    "garden_friend_points_10000": {"name_th": "ใช้แต้มเพื่อนในร้านการ์เดนสะสมครบ 10,000", "points": 10, "target": 10000},
    "gacha_partner_20": {"name_th": "สุ่มพรรคพวกสะสมครบ 20 ครั้ง", "points": 10, "target": 20},
}
BATTLE_PASS_REWARD_TABLE = {
    lvl: {"free": f"reward_free_lv{lvl}", "premium": f"reward_premium_lv{lvl}", "premium_bonus_pct": 3800 if lvl % 2 else 3000}
    for lvl in range(1, 41)
}
BATTLE_PASS_STATE = {}  # uid -> {level, exp, premium_owned, weekly_progress:{mission_id:int}, claimed_levels:[]}

def _battlepass_get(uid):
    return BATTLE_PASS_STATE.setdefault(uid, {
        "level": 1, "exp": 0, "premium_owned": False, "coins": 0, "knives_bought": [],
        "weekly_progress": {m: 0 for m in BATTLE_PASS_WEEKLY_MISSIONS}, "claimed_levels": [],
    })

@app.route('/api/battlepass/state')
def api_battlepass_state():
    """?uid=xxx -> เลเวล/EXP ปัจจุบันของพาส, ความคืบหน้าภารกิจประจำสัปดาห์, และสถานะพรีเมียม"""
    uid = request.args.get("uid", "")
    st = _battlepass_get(uid)
    missions = {m: {**info, "progress": st["weekly_progress"][m]} for m, info in BATTLE_PASS_WEEKLY_MISSIONS.items()}
    return jsonify({"st": "ok", "level": st["level"], "exp": st["exp"], "exp_needed": BATTLE_PASS_EXP_PER_LEVEL,
                    "premium_owned": st["premium_owned"], "coins": _bp_econ().coins(uid), "weekly_missions": missions})

@app.route('/api/battlepass/mission_progress', methods=['POST'])
@require_auth_toggleable
def api_battlepass_mission_progress():
    """body: {uid, mission_id, amount} -> เพิ่มความคืบหน้าภารกิจประจำสัปดาห์ และเติม EXP พาสถ้าภารกิจสำเร็จพอดี"""
    body = request.json or {}
    uid, mission_id = body.get("uid", ""), body.get("mission_id", "")
    amount = int(body.get("amount", 0))
    mission = BATTLE_PASS_WEEKLY_MISSIONS.get(mission_id)
    if not mission:
        return jsonify({"st": "error", "msg": "ไม่มีภารกิจนี้"}), 400
    st = _battlepass_get(uid)
    prev = st["weekly_progress"][mission_id]
    st["weekly_progress"][mission_id] = min(mission["target"], prev + amount)
    completed_now = prev < mission["target"] <= st["weekly_progress"][mission_id]
    if completed_now:
        _bp_econ().credit(uid, BP_COINS_PER_MISSION, "mission", mission_id)
        st["exp"] += int(round(mission["points"] * _season_event_battlepass_exp_mult()))  # [ 6zz6r5 ] เร่ง EXP battle pass ระหว่างอีเวนต์ท้ายซีซั่น
        while st["exp"] >= BATTLE_PASS_EXP_PER_LEVEL and st["level"] < max(BATTLE_PASS_REWARD_TABLE):
            st["exp"] -= BATTLE_PASS_EXP_PER_LEVEL
            st["level"] += 1
    return jsonify({"st": "ok", "mission_id": mission_id, "progress": st["weekly_progress"][mission_id],
                    "completed_now": completed_now, "level": st["level"], "exp": st["exp"]})

@app.route('/api/battlepass/claim_reward', methods=['POST'])
@require_auth_toggleable
def api_battlepass_claim_reward():
    """body: {uid, level} -> เคลมรางวัลของเลเวลนั้น (แถวฟรีเสมอ, แถวพรีเมียมถ้าเป็นสมาชิกพรีเมียม)"""
    body = request.json or {}
    uid, level = body.get("uid", ""), int(body.get("level", 0))
    st = _battlepass_get(uid)
    if level > st["level"]:
        return jsonify({"st": "error", "msg": "ยังไม่ถึงเลเวลนี้"}), 400
    if level in st["claimed_levels"]:
        return jsonify({"st": "error", "msg": "เคลมเลเวลนี้ไปแล้ว"}), 400
    row = BATTLE_PASS_REWARD_TABLE.get(level)
    if not row:
        return jsonify({"st": "error", "msg": "ไม่มีรางวัลของเลเวลนี้"}), 400
    st["claimed_levels"].append(level)
    rewards = {"free": row["free"]}
    gained_coins = BP_COINS_PER_CLAIM_FREE + (BP_COINS_PER_CLAIM_PREMIUM if st["premium_owned"] else 0)
    _bp_econ().credit(uid, gained_coins, "claim_level", str(level))
    rewards["bp_coins"] = gained_coins
    if st["premium_owned"]:
        rewards["premium"] = row["premium"]
        rewards["premium_bonus_pct"] = row["premium_bonus_pct"]
    return jsonify({"st": "ok", "level": level, "rewards": rewards})

VMAX_MODULES["battle_pass"] = {
    "desc": "Battle Pass ประจำอีเวนต์: เลเวล/EXP, ภารกิจประจำสัปดาห์, ตารางรางวัลฟรี/พรีเมียม",
    "routes": ["/api/battlepass/state", "/api/battlepass/mission_progress", "/api/battlepass/claim_reward",
               "/api/battlepass/knife/shop", "/api/battlepass/knife/buy", "/api/battlepass/knife/retire", "/api/battlepass/season/end",
               "/api/battlepass/coin_shop", "/api/battlepass/coin_shop/buy", "/api/battlepass/mystery_box/open", "/api/battlepass/plating/use", "/api/battlepass/med/use"],
}


# ==========================================
# [ 6zz6q. ระบบสุ่มไดนามิกประจำอีเวนต์ (Dynamic Loot System) — แบรนด์ดั้งเดิมของเราเอง ] --------
# ทางเข้ามินิเกมกิจกรรม + ตู้สุ่มไอเทมลิมิเต็ดพร้อมระบบการันตี (pity counter)
# ชื่อ/ไอเทมทั้งหมดเป็นของโปรเจกต์นี้เอง ไม่ได้อ้างอิงชื่อตัวละครหรือคอลแลปจากเกม/อนิเมะเรื่องใดเรื่องหนึ่งโดยเฉพาะ
# ==========================================
DYNAMIC_EVENT_MINIGAMES = [
    {"id": "hide_and_seek", "name_th": "ซ่อนหาแสนสนุก"},
    {"id": "kingdom_adventure", "name_th": "การผจญภัยอาณาจักรใหญ่"},
    {"id": "starlight_realm", "name_th": "ดินแดนแสงดาวและเทพนิยาย"},
    {"id": "daily_login_bonus", "name_th": "โบนัสล็อกอินประจำวัน (รับตัวละครพิเศษ)"},
    {"id": "blessing_days", "name_th": "วันแห่งพร"},
    {"id": "sweets_collection", "name_th": "คอลเลกชันของหวาน"},
]
DYNAMIC_LOOT_PITY_THRESHOLD = 100  # การันตีไอเทมระดับสูงสุดภายในจำนวนครั้งนี้
DYNAMIC_LOOT_STATE = {}  # uid -> {"pulls_since_top": int, "total_pulls": int}

def _dynamic_loot_get(uid):
    return DYNAMIC_LOOT_STATE.setdefault(uid, {"pulls_since_top": 0, "total_pulls": 0})

@app.route('/api/dynamicloot/minigames')
def api_dynamicloot_minigames():
    """รายชื่อโหมดมินิเกมกิจกรรมทั้งหมดที่เปิดให้เล่น"""
    return jsonify({"st": "ok", "minigames": DYNAMIC_EVENT_MINIGAMES})

@app.route('/api/dynamicloot/state')
def api_dynamicloot_state():
    """?uid=xxx -> สถานะตู้สุ่มไดนามิกลิมิเต็ด (จำนวนครั้งสะสมตั้งแต่ได้ไอเทมระดับสูงสุดล่าสุด และเหลืออีกกี่ครั้งถึงการันตี)"""
    uid = request.args.get("uid", "")
    st = _dynamic_loot_get(uid)
    return jsonify({"st": "ok", "pulls_since_top": st["pulls_since_top"], "total_pulls": st["total_pulls"],
                    "pulls_until_guarantee": DYNAMIC_LOOT_PITY_THRESHOLD - st["pulls_since_top"]})

@app.route('/api/dynamicloot/pull', methods=['POST'])
@require_auth_toggleable
def api_dynamicloot_pull():
    """body: {uid, pulls=1} -> สุ่มไอเทมจากตู้ไดนามิกลิมิเต็ด รับประกันไอเทมระดับสูงสุดเมื่อครบจำนวนครั้งการันตี (pity counter)"""
    body = request.json or {}
    uid, pulls = body.get("uid", ""), max(1, int(body.get("pulls", 1)))
    st = _dynamic_loot_get(uid)
    results = []
    for _ in range(pulls):
        st["total_pulls"] += 1
        st["pulls_since_top"] += 1
        # [ 6zz6r5 ] อีเวนต์ท้ายซีซั่น: อัตราดรอปไอเทมระดับสูงสุดต่อครั้งขยับจาก 2% ปกติ ไปที่
        # item_drop_rate ของอีเวนต์ (ปกติ 50%) ระหว่างอีเวนต์ทำงาน — pity counter ยังทำงานตามเดิม
        top_tier_chance = _season_event_item_drop_rate() if _season_event_active() else 0.02
        got_top = st["pulls_since_top"] >= DYNAMIC_LOOT_PITY_THRESHOLD or random.random() < top_tier_chance
        if got_top:
            st["pulls_since_top"] = 0
            results.append({"rarity": "top_tier", "item": "signature_character_shard"})
        else:
            results.append({"rarity": random.choice(["common", "rare"]), "item": "generic_fragment"})
    return jsonify({"st": "ok", "results": results, "pulls_since_top": st["pulls_since_top"]})

VMAX_MODULES["dynamic_loot_system"] = {
    "desc": "ระบบสุ่มไดนามิกประจำอีเวนต์ (แบรนด์ดั้งเดิมของเราเอง): ทางเข้ามินิเกมกิจกรรมต่างๆ และตู้สุ่มไอเทมลิมิเต็ดพร้อมระบบการันตี (pity counter)",
    "routes": ["/api/dynamicloot/minigames", "/api/dynamicloot/state", "/api/dynamicloot/pull"],
}


# ==========================================
# [ 6zz6q2. อีเวนต์มินิเกม "ภารกิจเดินทางบนยานอวกาศ" (Starship Corridor Run) — เกมการ์ดเดินทางทีละชั้น ]
# Spec (จากผู้ใช้): เกมเล็กๆ บนยาน ให้ผู้เล่น "เลือกเส้นทาง" เดินทางไปเรื่อยๆ ทีละชั้น ระหว่างทางจะเจอยามศัตรู
#   ต่อสู้แบบการ์ด: ใช้การ์ดแต่ละใบต้องจ่าย "พลังงาน" (เช่นใช้โล่ 1 ครั้ง = กินพลังงาน 1)
#   พลังงานฟื้นเต็มทุกเทิร์น และมีการ์ด "ก๊าซ" ที่ใช้แล้วฟื้นพลังงานเพิ่มโดยไม่เสียพลังงาน (ราคา 0)
# กติกา:
#   - ยาน 6 ชั้น: ชั้น 1-5 เลือก 1 จาก 2-3 เส้นทาง (ยามธรรมดา / ยามหัวหน้าหน่วย / ห้องพัก / คลังเสบียง /
#     เก็บซาก) ชั้น 6 คือกัปตันยาน (บอส)
#   - เทิร์นผู้เล่น: พลังงานเต็ม 3, จั่วการ์ด 5 ใบ, ใช้การ์ดได้ตามพลังงานที่มี แล้วกดจบเทิร์น
#   - ศัตรูโชว์ "เจตนา" ล่วงหน้า (โจมตี X / ตั้งโล่ X) ผู้เล่นวางแผนรับมือได้ ; โล่รีเซ็ตทุกเทิร์นของเจ้าของ
#   - ชนะการต่อสู้ -> เลือกการ์ดใหม่เข้ากอง 1 ใบ (หรือข้าม) ; แพ้ = จบรัน
#   - จบรัน: จ่าย "scrap" (สกุลเงินเดิมของเกม) ตามระยะทางที่ไปถึง + ชนะบอสได้โบนัส
# ==========================================
STARSHIP_EVENT = {
    "id": "starship_corridor_run",
    "name_th": "ภารกิจเดินทางบนยานอวกาศ",
    "desc_th": "เกมการ์ดเดินทางบนยาน เลือกเส้นทางทีละชั้น เจอยามศัตรู ใช้การ์ดโล่/โจมตีโดยกินพลังงาน "
               "และใช้ถังก๊าซ (ราคา 0) ฟื้นพลังงาน ผ่านครบ 6 ชั้นชนะกัปตันยานรับสแครปโบนัส",
}
# ขึ้นทะเบียนในแท็บ/ปฏิทินอีเวนต์เดิม (ถาวร ไม่มีวันหมดอายุ) + โผล่ในทางเข้ามินิเกมกิจกรรมเดิม
if not any(e.get("id") == STARSHIP_EVENT["id"] for e in EVENT_CATALOG):
    EVENT_CATALOG.append({"id": STARSHIP_EVENT["id"], "name_th": STARSHIP_EVENT["name_th"], "type": "permanent"})
