# ==========================================
# [ 6zz6r0. ตัวเชื่อมต่อ Wallet ของเว็บไซต์คุณเอง (Site Wallet Client) ] --------
# นี่คือ "สายเชื่อม" ไปหา wallet ที่มีอยู่แล้วบนเว็บไซต์ของคุณ — ไม่ใช่ payment gateway ใหม่
# และไม่มีการเก็บ/เดารหัสบัตร หรือคีย์ใดๆ ไว้ในซอร์สนี้
#
# ต้องตั้งค่า 2 ตัวแปรแวดล้อมก่อนใช้งานจริง (ตัวอย่างการรัน):
#   export SITE_WALLET_API_BASE="https://your-site.example.com/api/wallet"
#   export SITE_WALLET_API_KEY="<server-side secret ของเว็บคุณ ห้ามฝังในโค้ด>"
#
# โค้ดนี้ "คาดหวัง" ว่าเว็บไซต์คุณมี endpoint หน้าตาประมาณนี้ (ปรับ path/response ให้ตรงจริงได้เลย
# ที่ฟังก์ชัน _wallet_call ด้านล่าง — เป็นจุดเดียวที่ต้องแก้ให้ตรงกับ API จริงของ wallet คุณ):
#   GET  {BASE}/balance?uid=<uid>                       -> {"balance": <number>, "currency": "THB"}
#   POST {BASE}/charge   {uid, amount, currency, ref}   -> {"status": "pending"/"ok", "charge_id": "..."}
#   POST {BASE}/confirm  {charge_id}                    -> {"status": "ok"/"failed"}
# ==========================================
SITE_WALLET_API_BASE = os.environ.get("SITE_WALLET_API_BASE", "").rstrip("/")
SITE_WALLET_API_KEY = os.environ.get("SITE_WALLET_API_KEY", "")
# ต้องตั้งค่านี้เป็น "1" เองด้วยมือ หลังจากตรวจสอบผลลัพธ์จาก /api/wallet/autodiscover แล้วว่าถูกต้องจริง
# — ระบบจะไม่มีวันยิง charge/confirm เงินจริงด้วย endpoint ที่เดา/ค้นหามาเองโดยอัตโนมัติ จนกว่าจะเปิดตัวนี้
SITE_WALLET_ALLOW_AUTO_CHARGE = os.environ.get("SITE_WALLET_ALLOW_AUTO_CHARGE", "") == "1"
# รองรับ 2 พอร์ต: เกมหลักพอร์ตหนึ่ง + เว็บเซอร์วิส (wallet) อีกพอร์ต
# ตัวอย่าง:
#   # เทอร์มินัล 1 — รัน wallet service (พอร์ต 5001)
#   python this.py --wallet-service-port 5001
#   # เทอร์มินัล 2 — รันเกมหลัก ชี้ไปที่ service
#   export SITE_WALLET_API_BASE="http://127.0.0.1:5001/api/wallet"
#   export SITE_WALLET_API_KEY="dev-secret"
#   export SITE_WALLET_ALLOW_AUTO_CHARGE=1
#   python this.py
# หรือชี้ไปที่เว็บไซต์จริงของคุณบนพอร์ตอื่น/โดเมนอื่นก็ได้เหมือนกัน
# path ชัดเจน (ข้าม autodiscover) ถ้าตั้งไว้จะใช้ก่อน
SITE_WALLET_BALANCE_PATH = os.environ.get("SITE_WALLET_BALANCE_PATH", "/balance")
SITE_WALLET_CHARGE_PATH = os.environ.get("SITE_WALLET_CHARGE_PATH", "/charge")
SITE_WALLET_CONFIRM_PATH = os.environ.get("SITE_WALLET_CONFIRM_PATH", "/confirm")
# Fortress สามารถชี้ wallet คนละ base กับ event shop ได้ (ว่าง = ใช้ SITE_WALLET_API_BASE)
FORTRESS_WALLET_API_BASE = os.environ.get("FORTRESS_WALLET_API_BASE", "").rstrip("/")

# path ของไฟล์สเปกมาตรฐานที่มักเจอได้ทั่วไปบนเว็บที่มี REST API (อ่านอย่างเดียว ไม่มีการยิง POST ใดๆ ในขั้นตอนนี้)
WALLET_SPEC_CANDIDATE_PATHS = [
    "/openapi.json", "/swagger.json", "/v1/openapi.json",
    "/../openapi.json", "/../swagger.json", "/../docs/openapi.json",
]
WALLET_ROUTE_KEYWORDS = {"balance": ["balance", "wallet_balance", "get_balance"],
                          "charge": ["charge", "topup", "deduct", "pay"],
                          "confirm": ["confirm", "verify", "capture"]}
_WALLET_DISCOVERY_CACHE = None  # cache ผลการค้นหาสเปก ต่อการรันโปรเซสนี้ครั้งเดียว

def _wallet_autodiscover(force=False):
    """ค้นหาสเปก API ของ wallet อัตโนมัติแบบอ่านอย่างเดียว (ไม่ยิง POST ที่มีผลข้างเคียงใดๆ)
    โดยลองโหลดไฟล์สเปกมาตรฐาน (OpenAPI/Swagger) จาก path ที่มักพบทั่วไปใต้ SITE_WALLET_API_BASE
    แล้วแกะหา endpoint ที่ชื่อคล้ายกับ balance/charge/confirm ออกมาโดยอัตโนมัติ
    คืนค่า mapping ที่เจอ + endpoint เริ่มต้นเผื่อหาไม่เจอ — ไม่ได้แปลว่าเชื่อมสำเร็จ ต้องตรวจสอบผลก่อนเปิดใช้จริง"""
    global _WALLET_DISCOVERY_CACHE
    if _WALLET_DISCOVERY_CACHE is not None and not force:
        return _WALLET_DISCOVERY_CACHE
    found = {}
    if SITE_WALLET_API_BASE:
        for suffix in WALLET_SPEC_CANDIDATE_PATHS:
            try:
                resp = requests.get(f"{SITE_WALLET_API_BASE}{suffix}", timeout=5)
                if resp.status_code != 200:
                    continue
                spec = resp.json()
                paths = spec.get("paths", {})
                for path, methods in paths.items():
                    low = path.lower()
                    for kind, keywords in WALLET_ROUTE_KEYWORDS.items():
                        if kind in found:
                            continue
                        if any(kw in low for kw in keywords):
                            method = "GET" if "get" in methods else next(iter(methods), "POST").upper()
                            found[kind] = {"path": path, "method": method, "source_spec": f"{SITE_WALLET_API_BASE}{suffix}"}
            except (requests.RequestException, ValueError):
                continue
            if len(found) == len(WALLET_ROUTE_KEYWORDS):
                break
    # ใช้ path ตั้งต้น /balance, /charge, /confirm เป็น fallback สำหรับส่วนที่หาไม่เจอ
    defaults = {"balance": {"path": "/balance", "method": "GET"},
                "charge": {"path": "/charge", "method": "POST"},
                "confirm": {"path": "/confirm", "method": "POST"}}
    result = {kind: found.get(kind, defaults[kind]) for kind in defaults}
    result["_discovered_from_spec"] = list(found.keys())
    _WALLET_DISCOVERY_CACHE = result
    return result

@app.route('/api/wallet/autodiscover')
def api_wallet_autodiscover():
    """ลอง (ใหม่) ค้นหาสเปก wallet API อัตโนมัติ แล้วแสดงผลว่าเจอ endpoint ไหนจากสเปกจริงบ้าง กับตัวไหนที่ใช้ค่า
    ตั้งต้นแทนเพราะหาไม่เจอ — ใช้ตรวจสอบก่อนเปิด SITE_WALLET_ALLOW_AUTO_CHARGE เสมอ อย่าเปิดโดยไม่ดูผลนี้ก่อน"""
    result = _wallet_autodiscover(force=request.args.get("refresh") == "1")
    return jsonify({"st": "ok", "discovered": result,
                    "auto_charge_enabled": SITE_WALLET_ALLOW_AUTO_CHARGE,
                    "note": "ตรวจดู path/method ที่เจอให้ตรงกับ wallet จริงของคุณก่อน แล้วค่อยตั้ง "
                            "SITE_WALLET_ALLOW_AUTO_CHARGE=1 เพื่ออนุญาตให้ charge/confirm ใช้ endpoint ที่ค้นเจอนี้"})

def _wallet_call(method, path, **kwargs):
    """เรียก wallet API จริงของเว็บไซต์คุณ ต้องตั้ง SITE_WALLET_API_BASE ไว้ก่อน มิฉะนั้นคืน error"""
    if not SITE_WALLET_API_BASE:
        return {"st": "error", "msg": "ยังไม่ได้ตั้งค่า SITE_WALLET_API_BASE (ต้องชี้ไปที่ wallet API จริงบนเว็บไซต์คุณก่อน)"}
    headers = {"Authorization": f"Bearer {SITE_WALLET_API_KEY}"} if SITE_WALLET_API_KEY else {}
    try:
        resp = requests.request(method, f"{SITE_WALLET_API_BASE}{path}", headers=headers, timeout=10, **kwargs)
        resp.raise_for_status()
        return {"st": "ok", **resp.json()}
    except requests.RequestException as e:
        return {"st": "error", "msg": f"เรียก wallet API ไม่สำเร็จ: {e}"}

def _wallet_call_auto(kind, base_override=None, **kwargs):
    """เรียก endpoint wallet ตามชนิด ('balance'/'charge'/'confirm')
    ลำดับ path: explicit env path → autodiscover → default
    base_override: ใช้ base อื่น (เช่น FORTRESS_WALLET_API_BASE) แทน SITE_WALLET_API_BASE
    balance เรียกได้เสมอ; charge/confirm ต้องเปิด SITE_WALLET_ALLOW_AUTO_CHARGE"""
    if kind != "balance" and not SITE_WALLET_ALLOW_AUTO_CHARGE:
        return {"st": "error", "msg": "ยังไม่เปิด SITE_WALLET_ALLOW_AUTO_CHARGE=1 — ตั้งค่าหลังตรวจสอบ /api/wallet/autodiscover"}
    explicit = {
        "balance": ("GET", SITE_WALLET_BALANCE_PATH),
        "charge": ("POST", SITE_WALLET_CHARGE_PATH),
        "confirm": ("POST", SITE_WALLET_CONFIRM_PATH),
    }.get(kind)
    if explicit and explicit[1]:
        method, path = explicit
    else:
        routes = _wallet_autodiscover()
        route = routes.get(kind) or {"method": "POST" if kind != "balance" else "GET",
                                     "path": f"/{kind}"}
        method, path = route["method"], route["path"]
    # temporary base swap for fortress / multi-service
    global SITE_WALLET_API_BASE
    prev = SITE_WALLET_API_BASE
    try:
        if base_override:
            SITE_WALLET_API_BASE = base_override.rstrip("/")
        return _wallet_call(method, path, **kwargs)
    finally:
        SITE_WALLET_API_BASE = prev

@app.route('/api/wallet/balance')
@require_auth
def api_wallet_balance():
    """?uid=xxx -> ยอดเงินคงเหลือจริงจาก wallet บนเว็บไซต์คุณ (ใช้ endpoint ที่ autodiscover เจอ หรือ /balance เป็นค่าตั้งต้น)"""
    uid = P["uid"]
    result = _wallet_call_auto("balance", params={"uid": uid})
    return jsonify(result)

VMAX_MODULES["site_wallet_client"] = {
    "desc": "ตัวเชื่อมต่อไปยัง wallet จริงบนเว็บไซต์ของคุณเอง พร้อมระบบค้นหาสเปก endpoint อัตโนมัติแบบอ่านอย่างเดียว "
            "(/api/wallet/autodiscover) — endpoint ที่ตัดเงินจริง (charge/confirm) จะไม่ถูกใช้อัตโนมัติจนกว่าจะตั้ง "
            "SITE_WALLET_ALLOW_AUTO_CHARGE=1 ด้วยมือหลังตรวจสอบผลค้นหาแล้ว",
    "routes": ["/api/wallet/balance", "/api/wallet/autodiscover"],
}


# ==========================================
# [ 6zz6r. ร้านค้าอีเวนต์ (Event Shop) ] --------
# กล่องสุ่มใช้เพชร (จำกัดจำนวนครั้ง) + แพ็กเกจพรีเมียม (จำกัดจำนวนครั้ง, ตัดเงินจริงผ่าน wallet ของเว็บไซต์คุณ) + แพ็กฟรีประจำวัน
# ==========================================
EVENT_SHOP_CATALOG = {
    "diamond_box": {"name_th": "กล่องเพชร", "cost_type": "diamond", "cost": 250, "limit": 40},
    "basic_pack": {"name_th": "แพ็กพื้นฐาน", "cost_type": "real_money", "price": 720, "currency": "THB", "limit": 2},
    "special_pack": {"name_th": "แพ็กพิเศษ", "cost_type": "real_money", "price": 2100, "currency": "THB", "limit": 3},
    "advanced_pack": {"name_th": "แพ็กระดับสูง", "cost_type": "real_money", "price": 4000, "currency": "THB", "limit": 3},
    "supreme_pack": {"name_th": "แพ็กสูงสุด", "cost_type": "real_money", "price": 7100, "currency": "THB", "limit": 3},
    "free_pack": {"name_th": "แพ็กฟรีประจำวัน", "cost_type": "free", "limit": 1},
}
EVENT_SHOP_PURCHASES = {}  # uid -> {pack_id: {"bought": int, "reset_date": "YYYY-MM-DD"}}
EVENT_SHOP_PENDING_CHARGES = {}  # charge_id -> {uid, pack_id}

def _eventshop_get(uid, pack_id):
    today = datetime.now().strftime("%Y-%m-%d")
    st = EVENT_SHOP_PURCHASES.setdefault(uid, {})
    rec = st.setdefault(pack_id, {"bought": 0, "reset_date": today})
    if rec["reset_date"] != today and pack_id == "free_pack":
        rec["bought"], rec["reset_date"] = 0, today  # แพ็กฟรีรีเซ็ตรายวัน ส่วนแพ็กจำกัดอื่นๆ นับสะสมตลอดอีเวนต์
    return rec

@app.route('/api/eventshop/catalog')
def api_eventshop_catalog():
    """?uid=xxx -> รายการแพ็กเกจร้านค้าอีเวนต์ทั้งหมด พร้อมจำนวนที่ซื้อไปแล้วเทียบกับโควตา"""
    uid = request.args.get("uid", "")
    out = {}
    for pid, info in EVENT_SHOP_CATALOG.items():
        rec = _eventshop_get(uid, pid)
        out[pid] = {**info, "bought": rec["bought"], "sold_out": rec["bought"] >= info["limit"]}
    return jsonify({"st": "ok", "catalog": out})

@app.route('/api/eventshop/purchase', methods=['POST'])
@require_auth
def api_eventshop_purchase():
    """body: {uid, pack_id} -> ซื้อแพ็กเกจ. กล่องเพชร/แพ็กฟรีปลดล็อกทันที; แพ็กราคาจริงจะสั่ง 'charge' ไปที่ wallet
    จริงบนเว็บไซต์คุณผ่าน /api/wallet (ต้องตั้งค่า SITE_WALLET_API_BASE ไว้ก่อน) แล้วรอผู้ใช้กดยืนยันที่
    /api/eventshop/confirm_payment ถึงจะปลดล็อกไอเทมจริง — ไอเทมจะไม่ถูกปลดล็อกจนกว่า wallet จะยืนยันว่าตัดเงินสำเร็จ"""
    body = request.json or {}
    uid, pack_id = body.get("uid", ""), body.get("pack_id", "")
    info = EVENT_SHOP_CATALOG.get(pack_id)
    if not info:
        return jsonify({"st": "error", "msg": "ไม่มีแพ็กเกจนี้"}), 400
    rec = _eventshop_get(uid, pack_id)
    if rec["bought"] >= info["limit"]:
        return jsonify({"st": "error", "msg": "ซื้อครบจำนวนจำกัดของแพ็กเกจนี้แล้ว"}), 400
    if info["cost_type"] == "real_money":
        charge = _wallet_call_auto("charge", json={
            "uid": uid, "amount": info["price"], "currency": info["currency"], "ref": f"eventshop:{pack_id}",
        })
        if charge.get("st") != "ok":
            return jsonify(charge), 502
        charge_id = charge.get("charge_id")
        if not charge_id:
            return jsonify({"st": "error", "msg": "wallet API ไม่ได้ส่ง charge_id กลับมา"}), 502
        EVENT_SHOP_PENDING_CHARGES[charge_id] = {"uid": uid, "pack_id": pack_id}
        return jsonify({"st": "payment_pending", "charge_id": charge_id, "pack_id": pack_id,
                        "msg": "สร้างรายการตัดเงินที่ wallet แล้ว ให้ผู้ใช้ยืนยันในเว็บไซต์ แล้วเรียก /api/eventshop/confirm_payment"})
    if info["cost_type"] == "diamond":
        cur = _currency_get(uid)
        if cur["diamond"] < info["cost"]:
            return jsonify({"st": "error", "msg": "เพชรไม่พอ"}), 400
        cur["diamond"] -= info["cost"]
    rec["bought"] += 1
    return jsonify({"st": "ok", "pack_id": pack_id, "bought": rec["bought"], "limit": info["limit"]})

@app.route('/api/eventshop/confirm_payment', methods=['POST'])
@require_auth
def api_eventshop_confirm_payment():
    """body: {charge_id} -> ตรวจสอบสถานะการตัดเงินจริงกับ wallet ('/confirm'); ปลดล็อกแพ็กเกจก็ต่อเมื่อ wallet ยืนยันสำเร็จเท่านั้น"""
    body = request.json or {}
    charge_id = body.get("charge_id", "")
    pending = EVENT_SHOP_PENDING_CHARGES.get(charge_id)
    if not pending:
        return jsonify({"st": "error", "msg": "ไม่พบรายการตัดเงินนี้ (charge_id ไม่ถูกต้องหรือถูกยืนยันไปแล้ว)"}), 400
    confirm = _wallet_call_auto("confirm", json={"charge_id": charge_id})
    if confirm.get("st") != "ok" or confirm.get("status") != "ok":
        return jsonify({"st": "error", "msg": "wallet ยังไม่ยืนยันการตัดเงินสำเร็จ", "wallet_response": confirm}), 402
    uid, pack_id = pending["uid"], pending["pack_id"]
    rec = _eventshop_get(uid, pack_id)
    rec["bought"] += 1
    del EVENT_SHOP_PENDING_CHARGES[charge_id]
    return jsonify({"st": "ok", "pack_id": pack_id, "bought": rec["bought"]})

VMAX_MODULES["event_shop"] = {
    "desc": "ร้านค้าอีเวนต์: กล่องเพชรจำกัดครั้ง, แพ็กฟรีประจำวัน, และแพ็กราคาจริงที่ตัดเงินผ่าน wallet จริงของเว็บไซต์คุณ (charge -> confirm) ก่อนปลดล็อก",
    "routes": ["/api/eventshop/catalog", "/api/eventshop/purchase", "/api/eventshop/confirm_payment"],
}


# ==========================================
# [ 6zz6r5. อีเวนต์ท้ายซีซั่น (Season Finale Boost Event) ] --------
# ตามที่ขอ — อีเวนต์ชั่วคราวลงท้ายซีซั่น เร่ง 3 อย่างพร้อมกันทั่วทั้งเคอร์เนล (ทุกแมพ/ทุกโหมด เพราะระบบ
# สุ่ม/ดรอป/EXP ในไฟล์นี้ใช้ฟังก์ชันกลางร่วมกันหมด ไม่ได้แยกตามแมพ):
#   1) อัตราดรอปไอเทม (ของหายาก/ระดับสูงสุด) -> ขยับไปที่ item_drop_rate (ปกติ 50%) ใน 3 ระบบสุ่ม/ดรอป
#      ที่มีอยู่แล้ว: กาชา [2D2], ตู้สุ่มไดนามิกประจำอีเวนต์ [6zz6q], และของดรอปจากบอสโซนสงคราม [6zz6v-1]
#      (คูณจำนวนไอเทมต่อครั้งแทน เพราะของบอสไม่ได้เป็น "อัตราสุ่ม" แต่เป็นของการันตีที่สุ่มแค่ปริมาณ)
#   2) อัตราฟาร์ม EXP ตัวละคร -> คูณ char_exp_mult เข้ากับ EXP ที่ได้จากการยิงโดนใน /api/fire [ตรงกลางไฟล์]
#   3) อัตราฟาร์ม EXP ของ Battle Pass -> คูณ battlepass_exp_mult เข้ากับแต้มภารกิจใน [6zz6p]
# เปิด/ปิดผ่าน API ตั้งเวลาสิ้นสุดอัตโนมัติได้ (duration_hours) หรือปิดเองก็ได้ — endpoint activate/
# deactivate ควรจำกัดสิทธิ์ไว้ที่แอดมิน/GM เท่านั้นในระบบ auth จริงของคุณ (ที่นี่ใช้ require_auth_toggleable
# เดียวกับ endpoint อื่นๆ ในไฟล์ ไม่ได้แยกสิทธิ์แอดมินต่างหาก)
# ==========================================
SEASON_FINALE_EVENT = {
    "active": False,
    "name_th": "อีเวนต์ท้ายซีซั่น: ระเบิดฟาร์มส่งท้าย",
    "item_drop_rate": 0.50,       # อัตราดรอปไอเทม (ของหายาก/ท็อปเทียร์) ระหว่างอีเวนต์ — ใช้ร่วมกับกาชา + ตู้สุ่มไดนามิก
    "char_exp_mult": 2.0,         # ตัวคูณ EXP ตัวละคร ระหว่างอีเวนต์
    "battlepass_exp_mult": 2.0,   # ตัวคูณ EXP Battle Pass ระหว่างอีเวนต์
    "loot_qty_mult": 1.5,         # ตัวคูณจำนวนไอเทมที่ดรอปจากบอส/ลูทที่เป็นของการันตี (คนละแบบกับ "อัตรา")
    "started_at": None,
    "ends_at": None,              # None = ไม่มีกำหนดสิ้นสุดอัตโนมัติ ต้องปิดเองผ่าน /deactivate
}


def _season_event_active() -> bool:
    """เช็คว่าอีเวนต์ท้ายซีซั่นกำลังทำงานอยู่ไหม (auto ปิดเองถ้าเลยเวลา ends_at ที่ตั้งไว้ตอน activate)"""
    ev = SEASON_FINALE_EVENT
    if ev["active"] and ev["ends_at"] and time.time() >= ev["ends_at"]:
        ev["active"] = False
        sio.emit('season_finale_event_ended', {"name_th": ev["name_th"]})
    return ev["active"]


def _season_event_char_exp_mult() -> float:
    return SEASON_FINALE_EVENT["char_exp_mult"] if _season_event_active() else 1.0


def _season_event_battlepass_exp_mult() -> float:
    return SEASON_FINALE_EVENT["battlepass_exp_mult"] if _season_event_active() else 1.0


def _season_event_loot_qty_mult() -> float:
    return SEASON_FINALE_EVENT["loot_qty_mult"] if _season_event_active() else 1.0


def _season_event_item_drop_rate() -> float:
    """อัตราดรอปไอเทม (0.0-1.0) ที่ใช้แทนอัตราปกติของกาชา/ตู้สุ่มไดนามิก ระหว่างอีเวนต์ทำงานเท่านั้น"""
    return SEASON_FINALE_EVENT["item_drop_rate"]


@app.route('/api/seasonevent/status')
def api_seasonevent_status():
    """สถานะอีเวนต์ท้ายซีซั่นตอนนี้ (เปิดอยู่ไหม / ตัวคูณต่างๆ / เวลาเริ่ม-สิ้นสุดถ้ามี)"""
    _season_event_active()  # trigger auto-expire check ก่อนตอบ
    return jsonify({"st": "ok", **SEASON_FINALE_EVENT})


@app.route('/api/seasonevent/activate', methods=['POST'])
@require_auth_toggleable
def api_seasonevent_activate():
    """body: {duration_hours, item_drop_rate, char_exp_mult, battlepass_exp_mult, loot_qty_mult} (ทุกตัวเลือกได้)
    -> เปิดอีเวนต์ท้ายซีซั่น ไม่ใส่ duration_hours = ไม่มีกำหนดสิ้นสุดอัตโนมัติ (ปิดเองทีหลังผ่าน /deactivate)"""
    body = request.json or {}
    ev = SEASON_FINALE_EVENT
    for key in ("item_drop_rate", "char_exp_mult", "battlepass_exp_mult", "loot_qty_mult"):
        if key in body:
            ev[key] = float(body[key])
    duration_hours = body.get("duration_hours")
    ev["active"] = True
    ev["started_at"] = time.time()
    ev["ends_at"] = (time.time() + float(duration_hours) * 3600) if duration_hours else None
    sio.emit('season_finale_event_started', dict(ev))
    return jsonify({"st": "ok", **ev})


@app.route('/api/seasonevent/deactivate', methods=['POST'])
@require_auth_toggleable
def api_seasonevent_deactivate():
    """ปิดอีเวนต์ท้ายซีซั่นทันที (กลับไปใช้อัตราดรอป/EXP ปกติของแต่ละระบบ)"""
    ev = SEASON_FINALE_EVENT
    ev["active"] = False
    ev["ends_at"] = None
    sio.emit('season_finale_event_ended', {"name_th": ev["name_th"]})
    return jsonify({"st": "ok", **ev})


