@app.route('/api/fishing/pro/buy', methods=['POST'])
@require_auth
def api_fishing_pro_buy():
    uid = getattr(request, "vmax_uid", None) or resolve_uid()
    data = request.get_json(force=True, silent=True) or {}
    item_type = str(data.get("type", ""))
    item_id = str(data.get("item_id", ""))
    try:
        qty = max(1, min(100, int(data.get("qty", 1))))
    except (TypeError, ValueError):
        return jsonify({"st": "error", "msg": "qty ต้องเป็นตัวเลข"}), 400

    pools = {
        "rod": FISHING_PRO_RODS,
        "reel": FISHING_PRO_REELS,
        "bait": FISHING_PRO_BAITS,
    }
    pool = pools.get(item_type)
    item = pool.get(item_id) if pool else None
    if not item:
        return jsonify({"st": "error", "msg": "ไม่พบไอเทมตกปลานี้"}), 404

    st = _fishing_pro_get(uid)
    if item_type in ("rod", "reel") and item_id in (
        st["owned_rods"] if item_type == "rod" else st["owned_reels"]
    ):
        return jsonify({"st": "error", "msg": "มีอุปกรณ์นี้อยู่แล้ว"}), 409

    total = int(item["price"]) * qty
    if not _currency_pay(uid, item["currency"], total):
        return jsonify({"st": "error", "msg": f"เงิน {item['currency']} ไม่พอ",
                        "required": total}), 400

    if item_type == "rod":
        st["owned_rods"].append(item_id)
        st["rod"] = item_id
    elif item_type == "reel":
        st["owned_reels"].append(item_id)
        st["reel"] = item_id
    else:
        st["owned_baits"][item_id] = st["owned_baits"].get(item_id, 0) + qty
        st["bait"] = item_id
        st["bait_qty"] = st["owned_baits"][item_id]
    return jsonify({"st": "ok", "msg": f"ซื้อ {item['name']} สำเร็จ",
                    "state": _fishing_pro_public_state(st)})


@app.route('/api/fishing/pro/equip', methods=['POST'])
@require_auth_toggleable
def api_fishing_pro_equip():
    uid = getattr(request, "vmax_uid", None) or resolve_uid()
    data = request.get_json(force=True, silent=True) or {}
    item_type = str(data.get("type", ""))
    item_id = str(data.get("item_id", ""))
    st = _fishing_pro_get(uid)

    if item_type == "rod":
        if item_id not in st["owned_rods"] or item_id not in FISHING_PRO_RODS:
            return jsonify({"st": "error", "msg": "ยังไม่มีคันเบ็ดนี้"}), 400
        st["rod"] = item_id
    elif item_type == "reel":
        if item_id not in st["owned_reels"] or item_id not in FISHING_PRO_REELS:
            return jsonify({"st": "error", "msg": "ยังไม่มีรอกนี้"}), 400
        st["reel"] = item_id
    elif item_type == "bait":
        if item_id not in FISHING_PRO_BAITS or st["owned_baits"].get(item_id, 0) <= 0:
            return jsonify({"st": "error", "msg": "ยังไม่มีเหยื่อนี้"}), 400
        st["bait"] = item_id
        st["bait_qty"] = st["owned_baits"].get(item_id, 0)
    else:
        return jsonify({"st": "error", "msg": "type ต้องเป็น rod, reel หรือ bait"}), 400

    return jsonify({"st": "ok", "state": _fishing_pro_public_state(st)})


@app.route('/api/fishing/pro/cast', methods=['POST'])
@require_auth_toggleable
def api_fishing_pro_cast():
    uid = getattr(request, "vmax_uid", None) or resolve_uid()
    data = request.get_json(force=True, silent=True) or {}
    spot_id = str(data.get("spot_id", "pier"))
    if spot_id not in FISHING_PRO_SPOTS:
        return jsonify({"st": "error", "msg": "ไม่พบจุดตกปลานี้"}), 404

    st = _fishing_pro_update(uid)
    if st["state"] != "IDLE":
        return jsonify({"st": "error", "msg": "กำลังตกปลาอยู่แล้ว", "state": st["state"]}), 409

    now = time.time()
    if now - st["last_cast_at"] < FISHING_PRO_CAST_COOLDOWN:
        left = round(FISHING_PRO_CAST_COOLDOWN - (now - st["last_cast_at"]), 2)
        return jsonify({"st": "error", "msg": "ต้องรอจังหวะก่อนเหวี่ยงอีกครั้ง", "cooldown_left": left}), 429

    bait_id = st["bait"]
    bait_qty = st["owned_baits"].get(bait_id, 0)
    if bait_qty <= 0:
        return jsonify({"st": "error", "msg": "เหยื่อหมด กรุณาซื้อเพิ่ม"}), 400

    st["owned_baits"][bait_id] = bait_qty - 1
    st["bait_qty"] = bait_qty - 1
    st["last_cast_at"] = now
    st["state"] = "WAITING"
    st["bite_at"] = now + random.uniform(FISHING_PRO_BITE_MIN, FISHING_PRO_BITE_MAX)
    st["reel_deadline"] = 0.0
    st["hooked_fish"] = _fishing_pro_pick_fish(st, spot_id)
    st["last_result"] = None
    return jsonify({"st": "ok", "msg": "เหวี่ยงเบ็ดแล้ว รอปลากัด...", "state": "WAITING"})


@app.route('/api/fishing/pro/reel', methods=['POST'])
@require_auth_toggleable
def api_fishing_pro_reel():
    uid = getattr(request, "vmax_uid", None) or resolve_uid()
    st = _fishing_pro_update(uid)
    if st["state"] != "HOOKED" or not st.get("hooked_fish"):
        return jsonify({"st": "error", "msg": "ยังไม่มีปลากัด หรือปลาหลุดไปแล้ว"}), 400

    fish = st["hooked_fish"]
    rod = FISHING_PRO_RODS[st["rod"]]
    reel = FISHING_PRO_REELS[st["reel"]]
    bait = FISHING_PRO_BAITS[st["bait"]]
    combined_power = rod["power"] + reel["power"]
    control = rod["control"] + reel["control"]
    difficulty = min(95.0, 18.0 + fish["kg"] * 1.45 + fish["weight"] * 0.12)
    # Better gear makes heavy fish much more consistent; still keeps a chance to lose.
    catch_chance = max(0.05, min(0.98, (combined_power / 170.0) + (control / 220.0) - difficulty / 180.0))
    catch_chance += bait["bite_bonus"] * 0.25
    success = random.random() < catch_chance

    st["state"] = "IDLE"
    st["reel_deadline"] = 0.0
    st["hooked_fish"] = None

    if not success:
        st["last_result"] = {
            "ok": False, "reason": "line_broke",
            "msg": f"ปลา {fish['name']} หนัก {fish['kg']} kg หลุดเบ็ด",
        }
        return jsonify({"st": "ok", "caught": False, "result": st["last_result"],
                        "state": _fishing_pro_public_state(st)})

    # Scale price by actual weight relative to the species range.
    ratio = (fish["kg"] - fish["min_kg"]) / max(0.01, fish["max_kg"] - fish["min_kg"])
    gold_value = int(round(fish["gold"] * (0.75 + 0.75 * ratio)))
    scrap_value = int(round(fish["scrap"] * (0.75 + 0.75 * ratio)))
    score = float(gold_value)
    catch = {
        "id": uuid.uuid4().hex[:10],
        "fish_id": fish["id"],
        "name": fish["name"],
        "rarity": fish["rarity"],
        "kg": fish["kg"],
        "gold": gold_value,
        "scrap": scrap_value,
        "caught_at": time.time(),
    }
    st["catches"].append(catch)
    st["catches"] = st["catches"][-100:]
    st["total_value"] += gold_value
    st["performance_score"] += score
    st["competition_cash"] += gold_value
    st["last_result"] = {"ok": True, "msg": f"จับ {fish['name']} ได้!", "catch": catch}
    return jsonify({"st": "ok", "caught": True, "fish": catch,
                    "catch_chance": round(catch_chance, 3),
                    "result": st["last_result"],
                    "state": _fishing_pro_public_state(st)})


@app.route('/api/fishing/pro/sell', methods=['POST'])
@require_auth_toggleable
def api_fishing_pro_sell():
    uid = getattr(request, "vmax_uid", None) or resolve_uid()
    data = request.get_json(force=True, silent=True) or {}
    pay_currency = str(data.get("pay_currency", "gold"))
    if pay_currency not in ("gold", "scrap"):
        return jsonify({"st": "error", "msg": "pay_currency ต้องเป็น gold หรือ scrap"}), 400

    st = _fishing_pro_get(uid)
    if not st["catches"]:
        return jsonify({"st": "error", "msg": "ยังไม่มีปลาที่จับได้ให้ขาย"}), 400

    # Selling is based on the actual fish records; no client-supplied price is trusted.
    total = sum(int(c[pay_currency]) for c in st["catches"])
    count = len(st["catches"])
    cur = _currency_get(uid)
    cur[pay_currency] += total
    st["catches"].clear()
    st["total_value"] = 0
    return jsonify({"st": "ok", "sold_count": count, "earned": total,
                    "currency": pay_currency, "currency_total": cur[pay_currency],
                    "performance_score": round(st["performance_score"], 2)})


