@app.route('/api/sabotage/instance/create', methods=['POST'])
@require_auth_toggleable
def api_sabotage_instance_create():
    """body: {owner_uid | owner_uids, participant_uids:[...] | participants:{uid:team_id}, doors?,
    power_zones?, fuse_boxes?, nodes?, edges?, door_cooldown_sec?, position_stale_sec?, ttl_sec?} ->
    โหมดเกมไหนก็เรียกได้ (ยิงปืน/บุกบ้าน/ฆาตกร ฯลฯ) owner_uids ส่งเป็น uid เดี่ยวหรือ list ก็ได้ (list =
    หลายคน/ทั้งทีมคุมแท็บเล็ตร่วมกัน) participants ส่งเป็น list เฉยๆ หรือ dict {uid:team_id} ถ้าอยากแท็ก
    ทีมไว้ ฟิลด์ที่มี ? ไม่ส่งมาจะได้ชุดค่าเริ่มต้นของโหมดฆาตกรไปก่อน คืน instance_id ให้เก็บอ้างอิงเองใน
    แมตช์ของโหมดนั้น (ปกติโหมดเกมไม่ต้องยิง HTTP มาที่ route นี้เอง เรียก sabotage_create_instance(...)
    ตรง ๆ ในโค้ด python ได้เลยถ้าอยู่ใน process เดียวกัน — route นี้เปิดไว้ให้ระบบภายนอก/เอนจินอื่นเรียกได้
    ด้วย)"""
    body = request.json or {}
    owner_uids = body.get("owner_uids") if body.get("owner_uids") is not None else body.get("owner_uid")
    participants = body.get("participants") if body.get("participants") is not None else body.get("participant_uids")
    if not _sabotage_normalize_uid_list(owner_uids):
        return jsonify({"st": "error", "msg": "ต้องระบุ owner_uid หรือ owner_uids อย่างน้อย 1 คน"}), 400
    instance_id = sabotage_create_instance(
        owner_uids, participants,
        doors=body.get("doors"), power_zones=body.get("power_zones"),
        fuse_boxes=body.get("fuse_boxes"), nodes=body.get("nodes"), edges=body.get("edges"),
        door_cooldown_sec=body.get("door_cooldown_sec"), position_stale_sec=body.get("position_stale_sec"),
        ttl_sec=body.get("ttl_sec"))
    return jsonify({"st": "ok", "instance_id": instance_id, "instance": SABOTAGE_INSTANCES[instance_id]})


@app.route('/api/sabotage/instance/end', methods=['POST'])
@require_auth_toggleable
def api_sabotage_instance_end():
    """body: {instance_id, owner_uid} -> ใครก็ตามที่อยู่ใน owner_uids ของอินสแตนซ์นี้ปิดทิ้งได้ (ปกติ
    โหมดเกมเรียก sabotage_end_instance(...) ตรง ๆ ตอนแมตช์จบอยู่แล้ว route นี้ไว้ให้ระบบภายนอกเรียกได้
    เหมือนกัน ลืมเรียกก็ไม่เป็นไร — TTL background loop เก็บกวาดให้เองถ้าอินสแตนซ์เงียบเกิน ttl_sec)"""
    body = request.json or {}
    instance_id, owner_uid = body.get("instance_id", ""), body.get("owner_uid", "")
    inst = SABOTAGE_INSTANCES.get(instance_id)
    if not inst:
        return jsonify({"st": "error", "msg": "ไม่พบอินสแตนซ์นี้"}), 404
    if owner_uid not in inst["owner_uids"]:
        return jsonify({"st": "error", "msg": "เฉพาะเจ้าของอินสแตนซ์เท่านั้นที่ปิดได้"}), 403
    sabotage_end_instance(instance_id)
    return jsonify({"st": "ok"})


@app.route('/api/sabotage/participant/status', methods=['POST'])
@require_auth_toggleable
def api_sabotage_participant_status():
    """body: {instance_id, uid, status} -> [แก้ปัญหา alive/dead] โหมดเกมเรียก route นี้ (หรือ
    sabotage_set_participant_status(...) ตรง ๆ ถ้าอยู่ process เดียวกัน) ตอนผู้เข้าร่วมตาย/ถูกกำจัด/
    ออกจากเกม (status=\"inactive\") หรือกลับมาใหม่ (status=\"active\") — เอนจินกลางไม่รู้กติกาของแต่ละ
    โหมดเอง จึงต้องให้โหมดเกมแจ้งสถานะเข้ามาเอง ผู้เข้าร่วมที่ inactive จะไม่โผล่เป็นจุดแดงและกู้ไฟไม่ได้"""
    body = request.json or {}
    instance_id, uid = body.get("instance_id", ""), body.get("uid", "")
    status = body.get("status", "")
    if status not in ("active", "inactive"):
        return jsonify({"st": "error", "msg": "status ต้องเป็น active หรือ inactive เท่านั้น"}), 400
    if not sabotage_set_participant_status(instance_id, uid, status):
        return jsonify({"st": "error", "msg": "ไม่พบอินสแตนซ์นี้ หรือไม่พบผู้เข้าร่วมคนนี้ในอินสแตนซ์"}), 404
    return jsonify({"st": "ok", "instance_id": instance_id, "uid": uid, "status": status})


@app.route('/api/sabotage/door/toggle', methods=['POST'])
@require_auth_toggleable
def api_sabotage_door_toggle():
    """body: {instance_id, owner_uid, door_id} -> ใครก็ตามที่อยู่ใน owner_uids ของอินสแตนซ์นี้ สั่งปิด/
    เปิดประตูกลจากระยะไกลได้ (หลายคน/ทั้งทีมคุมร่วมกันได้ถ้าตอนสร้างอินสแตนซ์ส่ง owner_uids เป็น list)
    สลับสถานะทุกครั้งที่กด (เปิด->ปิด, ปิด->เปิด) ปิดแล้วล็อกอยู่นาน door_cooldown_sec ของอินสแตนซ์นี้ก่อน
    เปิดเองอัตโนมัติถ้าไม่มีใครมากดเปิดจากแท็บเล็ตก่อน ปิดไม่ได้ถ้าไฟในโซนนั้นดับอยู่ (ประตูกลใช้ไฟ ไฟดับ
    = สั่งอะไรก็ไม่ทำงาน)"""
    body = request.json or {}
    instance_id = body.get("instance_id", "")
    owner_uid, door_id = body.get("owner_uid", ""), body.get("door_id", "")
    inst = SABOTAGE_INSTANCES.get(instance_id)
    if not inst:
        return jsonify({"st": "error", "msg": "ไม่พบอินสแตนซ์นี้"}), 404
    if owner_uid not in inst["owner_uids"]:
        return jsonify({"st": "error", "msg": "เฉพาะเจ้าของแท็บเล็ตเท่านั้นที่สั่งประตูได้"}), 403
    cfg = inst["config"]
    if door_id not in cfg["doors"]:
        return jsonify({"st": "error", "msg": "ไม่มีประตูนี้"}), 404
    zone_id = cfg["doors"][door_id]["zone"]
    if not inst["power_zones"][zone_id]["powered"]:
        return jsonify({"st": "error", "msg": "ไฟโซนนี้ดับอยู่ สั่งประตูจากแท็บเล็ตไม่ได้จนกว่าไฟจะกลับมา"}), 400
    current = _sabotage_door_effective_state(inst, door_id)
    door = inst["doors"][door_id]
    if current == "open":
        door["state"], door["closed_at"] = "closed", time.time()
        new_state = "closed"
    else:
        door["state"], door["closed_at"] = "open", None
        new_state = "open"
    _sabotage_touch(inst)
    payload = {"instance_id": instance_id, "door_id": door_id, "state": new_state}
    for u in inst["owner_uids"]:
        sio.emit('sabotage_door_toggled', payload, room=u)
    for u in inst["participants"]:
        sio.emit('sabotage_door_toggled', payload, room=u)
    return jsonify({"st": "ok", "door_id": door_id, "state": new_state,
                    "blocked_edges": list(_sabotage_blocked_edges(inst))})


@app.route('/api/sabotage/blackout', methods=['POST'])
@require_auth_toggleable
def api_sabotage_blackout():
    """body: {instance_id, owner_uid, zone_id} -> ฝั่งเจ้าของ (คนใดคนหนึ่งใน owner_uids) กดตัดไฟทั้งโซน
    ระหว่างไฟดับ ประตูกลทุกบานในโซนนั้นใช้งานไม่ได้ (เปิดค้าง ผ่านได้ปกติ) เป็นภารกิจย่อยบังคับให้ผู้เข้า
    ร่วมต้องไปกู้ไฟที่ตู้ไฟของโซนนั้นเอง (/api/sabotage/fusebox/repair) ถึงจะกลับมาใช้ระบบไฟ/ประตูอัตโนมัติ
    ได้"""
    body = request.json or {}
    instance_id = body.get("instance_id", "")
    owner_uid, zone_id = body.get("owner_uid", ""), body.get("zone_id", "")
    inst = SABOTAGE_INSTANCES.get(instance_id)
    if not inst:
        return jsonify({"st": "error", "msg": "ไม่พบอินสแตนซ์นี้"}), 404
    if owner_uid not in inst["owner_uids"]:
        return jsonify({"st": "error", "msg": "เฉพาะเจ้าของแท็บเล็ตเท่านั้นที่ตัดไฟได้"}), 403
    if zone_id not in inst["config"]["power_zones"]:
        return jsonify({"st": "error", "msg": "ไม่มีโซนไฟนี้"}), 404
    zone = inst["power_zones"][zone_id]
    if not zone["powered"]:
        return jsonify({"st": "error", "msg": "โซนนี้ไฟดับอยู่แล้ว"}), 400
    zone["powered"] = False
    zone["outage_at"] = time.time()
    _sabotage_touch(inst)
    payload = {"instance_id": instance_id, "zone_id": zone_id, "powered": False}
    for u in inst["owner_uids"]:
        sio.emit('sabotage_blackout', payload, room=u)
    for u in inst["participants"]:
        sio.emit('sabotage_blackout', payload, room=u)
    return jsonify({"st": "ok", "zone_id": zone_id, "powered": False,
                    "blocked_edges": list(_sabotage_blocked_edges(inst))})


@app.route('/api/sabotage/fusebox/repair', methods=['POST'])
@require_auth_toggleable
def api_sabotage_fusebox_repair():
    """body: {instance_id, uid, fusebox_id} -> เฉพาะผู้เข้าร่วมของอินสแตนซ์นี้ที่สถานะยัง \"active\"
    เท่านั้นที่กู้ไฟได้ (คนที่โหมดเกมแจ้งว่า inactive ไปแล้ว เช่นตายไปแล้ว กู้ไม่ได้ — ฝั่งเจ้าของแท็บเล็ตก็
    กู้ไฟไม่ได้เหมือนกัน เป็นฝั่งตรงข้ามกันเสมอ) กู้สำเร็จ ไฟทั้งโซนกลับมาทันที ประตูในโซนนั้นกลับมาใช้งาน/
    ล็อกอัตโนมัติได้ตามปกติ"""
    body = request.json or {}
    instance_id = body.get("instance_id", "")
    uid, fusebox_id = body.get("uid", ""), body.get("fusebox_id", "")
    inst = SABOTAGE_INSTANCES.get(instance_id)
    if not inst:
        return jsonify({"st": "error", "msg": "ไม่พบอินสแตนซ์นี้"}), 404
    participant = inst["participants"].get(uid)
    if not participant or participant["status"] != "active":
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในอินสแตนซ์นี้ในฐานะผู้เข้าร่วมที่ยัง active"}), 403
    fusebox = inst["config"]["fuse_boxes"].get(fusebox_id)
    if not fusebox:
        return jsonify({"st": "error", "msg": "ไม่มีตู้ไฟนี้"}), 404
    zone_id = fusebox["zone"]
    zone = inst["power_zones"][zone_id]
    if zone["powered"]:
        return jsonify({"st": "error", "msg": "โซนนี้ไฟไม่ได้ดับอยู่ ไม่ต้องกู้"}), 400
    zone["powered"] = True
    zone["outage_at"] = None
    _sabotage_touch(inst)
    payload = {"instance_id": instance_id, "zone_id": zone_id, "powered": True, "repaired_by": uid}
    for u in inst["owner_uids"]:
        sio.emit('sabotage_power_restored', payload, room=u)
    for u in inst["participants"]:
        sio.emit('sabotage_power_restored', payload, room=u)
    return jsonify({"st": "ok", "zone_id": zone_id, "powered": True})


@app.route('/api/sabotage/position', methods=['POST'])
@require_auth_toggleable
def api_sabotage_position():
    """body: {instance_id, uid, x, y} -> ผู้เข้าร่วมยิงตำแหน่งตัวเองเป็นระยะระหว่างเกม ให้กลายเป็น
    "จุดแดง" บนแท็บเล็ตของฝั่งเจ้าของ ตำแหน่งที่ไม่อัปเดตนานเกิน position_stale_sec ของอินสแตนซ์นี้ จะไม่
    โผล่ในผลลัพธ์ของ /sabotage/tablet อีก (นับเป็นสัญญาณขาด) — ยอมรับตำแหน่งจากผู้เข้าร่วมทุกคนไม่ว่าจะ
    active/inactive ก็ตาม (เผื่อโหมดเกมอยากโชว์ตำแหน่งคนตายไว้สั้นๆ ก่อนหาย) แต่ /sabotage/tablet จะกรอง
    เฉพาะคน active เท่านั้นออกมาเป็นจุดแดง"""
    body = request.json or {}
    instance_id, uid = body.get("instance_id", ""), body.get("uid", "")
    inst = SABOTAGE_INSTANCES.get(instance_id)
    if not inst:
        return jsonify({"st": "error", "msg": "ไม่พบอินสแตนซ์นี้"}), 404
    if uid not in inst["participants"]:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในอินสแตนซ์นี้ในฐานะผู้เข้าร่วม"}), 403
    x, y = float(body.get("x", 0)), float(body.get("y", 0))
    inst["positions"][uid] = {"x": x, "y": y, "ts": time.time()}
    _sabotage_touch(inst)
    return jsonify({"st": "ok"})


@app.route('/api/sabotage/tablet')
def api_sabotage_tablet():
    """?instance_id=xxx&owner_uid=xxx -> ข้อมูลทั้งหมดที่ขึ้นจอแท็บเล็ตตอนเปิดใช้งาน (สไตล์เมนูตัดไฟของ
    Super Sus): กริดปุ่มประตูทุกบาน (พร้อมสถานะปัจจุบัน+เวลาที่เหลือก่อนเปิดเอง), กริดปุ่มโซนไฟ (powered
    หรือไฟดับ), และจุดแดง = ตำแหน่งผู้เข้าร่วมที่สถานะยัง \"active\" (ดู sabotage_set_participant_status)
    และเพิ่งอัปเดตตำแหน่งมาไม่เกิน position_stale_sec วินาที เฉพาะคนใน owner_uids ของอินสแตนซ์นี้เท่านั้น
    ที่เปิดดูได้"""
    instance_id = request.args.get("instance_id", "")
    owner_uid = request.args.get("owner_uid", "")
    inst = SABOTAGE_INSTANCES.get(instance_id)
    if not inst:
        return jsonify({"st": "error", "msg": "ไม่พบอินสแตนซ์นี้"}), 404
    if owner_uid not in inst["owner_uids"]:
        return jsonify({"st": "error", "msg": "เฉพาะเจ้าของแท็บเล็ตเท่านั้นที่เปิดดูได้"}), 403
    cfg = inst["config"]
    now = time.time()
    doors_out = {}
    for did, dinfo in cfg["doors"].items():
        state = _sabotage_door_effective_state(inst, did)
        door = inst["doors"][did]
        reopens_in = None
        if state == "closed" and door["closed_at"] is not None:
            reopens_in = max(0, int(cfg["door_cooldown_sec"] - (now - door["closed_at"])))
        doors_out[did] = {"name": dinfo.get("name", did), "x": dinfo["x"], "y": dinfo["y"], "zone": dinfo["zone"],
                           "state": state, "reopens_in_sec": reopens_in}
    zones_out = {zid: {"name": zinfo.get("name", zid), "powered": inst["power_zones"][zid]["powered"]}
                 for zid, zinfo in cfg["power_zones"].items()}
    red_dots = []
    for uid, pos in inst["positions"].items():
        participant = inst["participants"].get(uid)
        if not participant or participant["status"] != "active":
            continue
        if (now - pos["ts"]) > cfg["position_stale_sec"]:
            continue
        red_dots.append({"uid": uid, "x": pos["x"], "y": pos["y"], "team": participant["team"]})
    return jsonify({"st": "ok", "instance_id": instance_id, "doors": doors_out, "power_zones": zones_out,
                    "red_dots": red_dots, "fuse_boxes": cfg["fuse_boxes"]})


@app.route('/api/sabotage/path')
def api_sabotage_path():
    """?instance_id=xxx&from_node=xxx&to_node=xxx -> คำนวณเส้นทางสั้นสุดระหว่าง 2 โหนดบนกราฟแผนที่จำลอง
    ของอินสแตนซ์นี้ โดยเลี่ยงประตูที่ปิด/ล็อกอยู่จริงตอนนี้ ให้ client/เอนจินเอาไปใช้เทียบกับ NavMesh ฝั่ง
    ตัวเอง หรือ debug ดูว่าเส้นทางไหน "ถูกตัดขาด" อยู่ — คืน path=None ถ้าไม่มีทางไปถึง"""
    instance_id = request.args.get("instance_id", "")
    from_node, to_node = request.args.get("from_node", ""), request.args.get("to_node", "")
    inst = SABOTAGE_INSTANCES.get(instance_id)
    if not inst:
        return jsonify({"st": "error", "msg": "ไม่พบอินสแตนซ์นี้"}), 404
    if from_node not in inst["config"]["nodes"] or to_node not in inst["config"]["nodes"]:
        return jsonify({"st": "error", "msg": "ไม่มีโหนดนี้บนแผนที่"}), 404
    path = _sabotage_bfs_path(inst, from_node, to_node)
    return jsonify({"st": "ok", "path": path, "reachable": path is not None,
                    "blocked_edges": list(_sabotage_blocked_edges(inst))})


VMAX_MODULES["map_sabotage_engine"] = {
    "desc": "[UPGRADE - Generalized v2] เอนจินกลาง engine-agnostic สำหรับระบบก่อวินาศกรรมแผนที่ระยะไกล "
            "— โหมดเกมไหนก็ขอ \"อินสแตนซ์\" ของตัวเองได้ผ่าน sabotage_create_instance(...) (หรือ "
            "/api/sabotage/instance/create จากภายนอก) พร้อม config ประตู/โซนไฟ/ตู้ไฟ/กราฟโหนดของตัวเอง "
            "killer-mode auto-provision อินสแตนซ์ให้อัตโนมัติตอน /api/killer-mode/match/start แล้ว (เก็บ "
            "instance_id ไว้ใน match dict) รองรับ 3 จุดที่เคยเป็นข้อจำกัด: (1) คุมพร้อมกันหลายคน/ทั้งทีม "
            "ได้ — owner_uids ส่งเป็น list ตอนสร้างอินสแตนซ์ ใครอยู่ในลิสต์สั่งประตู/ไฟได้หมด (2) รู้จัก "
            "alive/dead ผ่าน sabotage_set_participant_status(instance_id, uid, \"active\"/\"inactive\") "
            "(หรือ /api/sabotage/participant/status) โหมดเกมเรียกเองตอนตัวละครตาย/ออกจากเกม คน inactive "
            "จะไม่โผล่จุดแดง/กู้ไฟไม่ได้อีก (3) cleanup อัตโนมัติ — ทุกอินสแตนซ์มี ttl_sec (default "
            "SABOTAGE_INSTANCE_DEFAULT_TTL_SEC) เธรดพื้นหลัง _sabotage_instance_expire_loop เก็บกวาด "
            "อินสแตนซ์ที่เงียบเกิน ttl_sec ทิ้งอัตโนมัติ เผื่อโหมดเกมลืมเรียก sabotage_end_instance(...) "
            "เอง (แนะนำให้เรียกเองตอนจบแมตช์ตามปกติอยู่ดี TTL เป็นแค่ตาข่ายกันหลุดชั้นสอง) — สั่งปิด/เปิด "
            "ประตูกลจากระยะไกล (/sabotage/door/toggle) ปิดแล้วล็อกจนครบ door_cooldown_sec ถึงเปิดเอง, "
            "สั่งตัดไฟทั้งโซน (/sabotage/blackout) ทำให้ประตูในโซนนั้นใช้งานไม่ได้จนกว่าผู้เข้าร่วม active "
            "จะไปกู้ไฟที่ตู้ไฟของโซนนั้น (/sabotage/fusebox/repair) เส้นทางที่ถูกประตูปิดตัดขาดคำนวณผ่าน "
            "กราฟโหนด/เอดจ์จำลอง (/sabotage/path, BFS เลี่ยงประตูปิด) ให้ client เอาไปสร้าง NavMesh "
            "Obstacle เอง ตำแหน่งฝั่งตรงข้าม (/sabotage/position) โผล่เป็นจุดแดงบนแท็บเล็ตของฝั่งเจ้าของ "
            "(/sabotage/tablet) สไตล์เมนูตัดไฟของ Super Sus",
    "routes": ["/api/sabotage/instance/create", "/api/sabotage/instance/end",
               "/api/sabotage/participant/status", "/api/sabotage/door/toggle", "/api/sabotage/blackout",
               "/api/sabotage/fusebox/repair", "/api/sabotage/position",
               "/api/sabotage/tablet", "/api/sabotage/path"],
}


# ==========================================
# [ 6z. Visual Novel Engine: ฉากนิ่งเส้นขาว-ดำ + กล่องข้อความเดินบทสนทนา ]
# แรงบันดาลใจจากเกม visual-novel สไตล์ line-art ที่เห็นสตรีมเมอร์เล่น (ฉากห้อง
# วาดเส้นขาว-ดำ มีกล่องข้อความด้านบน + ปุ่ม ▶ กดเดินบทสนทนาไปทีละบรรทัด)
#
# ภาพเป็น "ภาพนิ่ง" ทั้งหมด — สิ่งเดียวที่ขยับคือข้อความ ตรงตามที่เกมต้นแบบเป็น
# ฉากเก็บเป็น SVG เส้นขาว-ดำ (มีฉากตัวอย่าง VN_DEFAULT_SCENE_SVG ให้พร้อมใช้
# สไตล์เดียวกับในภาพอ้างอิง: ห้อง มีโต๊ะทำงาน คอมพิวเตอร์ ชั้นหนังสือ ประตู
# ลูกฟุตบอล ถุงขยะ กองหนังสือ) และรองรับอัปโหลดฉากของตัวเองเพิ่มได้ทุกเมื่อ
# ผ่าน /api/vn/scenes (multipart, field: image) — ไม่ได้ผูกติดกับ SVG อย่างเดียว
# รองรับ jpg/png/webp ด้วย (ALLOWED_PAGE_EXTENSIONS ที่มีอยู่แล้วในไฟล์)
#
# มีทั้ง REST API (สำหรับเอาไปต่อกับ UI ของตัวเอง) และหน้าเว็บเล่นได้จริงทันที
# ที่ /visual-novel (เข้ากับระบบ "Official Game Websites" เดิมของไฟล์นี้ — ใช้
# งานได้แบบสแตนด์อโลนในตัวเอง ไม่ต้องพึ่งเกมอื่นในไฟล์)
# ==========================================

VN_DIR = "uploaded_vn_scenes"
VN_INDEX_PATH = os.path.join(VN_DIR, "index.json")
os.makedirs(VN_DIR, exist_ok=True)

# scene_id -> {name, kind: "svg"|"image", filename, uploaded_at}
VN_SCENES = {}
# script_id -> {title, scene_id, speaker_name, lines: [str, ...], created_at}
VN_SCRIPTS = {}


def _vn_load_index():
    if os.path.exists(VN_INDEX_PATH):
        with open(VN_INDEX_PATH, "r", encoding="utf-8") as f:
            raw = json.load(f)
            return raw.get("scenes", {}), raw.get("scripts", {})
    return {}, {}


def _vn_save_index():
    with open(VN_INDEX_PATH, "w", encoding="utf-8") as f:
        json.dump({"scenes": VN_SCENES, "scripts": VN_SCRIPTS}, f, ensure_ascii=False, indent=2)


