def _vn_seed_defaults():
    if "room_lineart_01" not in VN_SCENES:
        fname = "room_lineart_01.svg"
        with open(os.path.join(VN_DIR, fname), "w", encoding="utf-8") as f:
            f.write(VN_DEFAULT_SCENE_SVG)
        VN_SCENES["room_lineart_01"] = {
            "name": "ห้องนอนรก (เส้นขาว-ดำ)", "kind": "svg",
            "filename": fname, "uploaded_at": time.time(),
        }
    if "sample_morning_talk" not in VN_SCRIPTS:
        VN_SCRIPTS["sample_morning_talk"] = {
            "title": "บทพูดคนเดียวยามเช้า", "scene_id": "room_lineart_01",
            "speaker_name": "",
            "lines": [
                "...ห้องรกอีกแล้วสินะ",
                "ขยะก็ยังไม่ได้เอาไปทิ้ง หนังสือก็กองอยู่แบบนั้น",
                "แต่ก็นะ... วันนี้ก็ต้องเริ่มต้นใหม่อยู่ดี",
                "ไปกันเถอะ",
            ],
            "created_at": time.time(),
        }
    _vn_save_index()


_loaded_vn_scenes, _loaded_vn_scripts = _vn_load_index()
VN_SCENES.update(_loaded_vn_scenes)
VN_SCRIPTS.update(_loaded_vn_scripts)
_vn_seed_defaults()


# --- ฉาก (scenes) ------------------------------------------------------------
@app.route('/api/vn/scenes', methods=['GET'])
def api_vn_scenes_list():
    out = [{"scene_id": sid, "name": s["name"], "kind": s["kind"]} for sid, s in VN_SCENES.items()]
    return jsonify({"st": "ok", "count": len(out), "scenes": out})


@app.route('/api/vn/scenes', methods=['POST'])
@require_auth_toggleable
def api_vn_scenes_upload():
    """อัปโหลดฉากของตัวเอง — multipart field: image (jpg/jpeg/png/webp/svg),
    form field: name (ไม่บังคับ) — ใช้ภาพอะไรก็ได้ ไม่จำเป็นต้องเป็นเส้นขาว-ดำ"""
    f = request.files.get('image')
    if not f or not f.filename:
        return jsonify({"st": "error", "msg": "ต้องแนบไฟล์ภาพ (field: image)"}), 400
    ext = (f.filename.rsplit('.', 1)[-1] if '.' in f.filename else '').lower()
    allowed = ALLOWED_PAGE_EXTENSIONS | {"svg"}
    if ext not in allowed:
        return jsonify({"st": "error", "msg": f"รองรับเฉพาะ {', '.join(sorted(allowed))}"}), 400
    scene_id = str(uuid.uuid4())[:8]
    fname = secure_filename(f"scene_{scene_id}.{ext}")
    f.save(os.path.join(VN_DIR, fname))
    VN_SCENES[scene_id] = {
        "name": request.form.get('name', fname), "kind": "svg" if ext == "svg" else "image",
        "filename": fname, "uploaded_at": time.time(),
    }
    _vn_save_index()
    return jsonify({"st": "ok", "scene_id": scene_id})


@app.route('/api/vn/scenes/<scene_id>/image', methods=['GET'])
def api_vn_scene_image(scene_id):
    s = VN_SCENES.get(scene_id)
    if not s:
        return jsonify({"st": "error", "msg": "ไม่พบฉากนี้"}), 404
    return send_from_directory(VN_DIR, s["filename"])


# --- สคริปต์บทสนทนา (scripts) -------------------------------------------------
@app.route('/api/vn/scripts', methods=['GET'])
def api_vn_scripts_list():
    out = [{"script_id": kid, "title": s["title"], "scene_id": s["scene_id"], "line_count": len(s["lines"])}
           for kid, s in VN_SCRIPTS.items()]
    return jsonify({"st": "ok", "count": len(out), "scripts": out})


@app.route('/api/vn/scripts', methods=['POST'])
@require_auth_toggleable
def api_vn_scripts_create():
    """body: {title, scene_id, speaker_name?, lines: [str, ...]} -> สร้างบทสนทนาใหม่ผูกกับฉากที่มีอยู่"""
    body = request.json or {}
    title = (body.get('title') or '').strip()
    scene_id = body.get('scene_id', '')
    lines = body.get('lines') or []
    if not title:
        return jsonify({"st": "error", "msg": "ต้องระบุ title"}), 400
    if scene_id not in VN_SCENES:
        return jsonify({"st": "error", "msg": f"ไม่พบฉาก '{scene_id}' — ดูรายชื่อได้ที่ /api/vn/scenes"}), 400
    if not isinstance(lines, list) or not lines:
        return jsonify({"st": "error", "msg": "ต้องระบุ lines เป็น array ของข้อความอย่างน้อย 1 บรรทัด"}), 400
    script_id = str(uuid.uuid4())[:8]
    VN_SCRIPTS[script_id] = {
        "title": title, "scene_id": scene_id,
        "speaker_name": body.get('speaker_name', ''),
        "lines": [str(l) for l in lines], "created_at": time.time(),
    }
    _vn_save_index()
    return jsonify({"st": "ok", "script_id": script_id})


@app.route('/api/vn/scripts/<script_id>', methods=['GET'])
def api_vn_script_detail(script_id):
    s = VN_SCRIPTS.get(script_id)
    if not s:
        return jsonify({"st": "error", "msg": "ไม่พบบทสนทนานี้"}), 404
    return jsonify({"st": "ok", "script_id": script_id, "script": s})


@app.route('/api/vn/scripts/<script_id>/line/<int:idx>', methods=['GET'])
def api_vn_script_line(script_id, idx):
    """ดึงบรรทัดที่ idx (เริ่มที่ 0) ของบทนี้ พร้อม has_next — ไว้ให้ UI ของตัวเอง
    (นอกเหนือจากหน้า /visual-novel ที่มีให้แล้ว) เดินบทสนทนาทีละบรรทัดได้เอง"""
    s = VN_SCRIPTS.get(script_id)
    if not s:
        return jsonify({"st": "error", "msg": "ไม่พบบทสนทนานี้"}), 404
    lines = s["lines"]
    if idx < 0 or idx >= len(lines):
        return jsonify({"st": "error", "msg": f"idx ต้องอยู่ระหว่าง 0-{len(lines)-1}"}), 400
    return jsonify({
        "st": "ok", "script_id": script_id, "idx": idx, "text": lines[idx],
        "speaker_name": s.get("speaker_name", ""), "scene_id": s["scene_id"],
        "has_next": idx + 1 < len(lines), "total_lines": len(lines),
    })


