# ==========================================
# [ 6z2. Killer/Survivor Mode: หน้าจอเล่นจริงแบบ FPS 3D ]
# ต่อยอดจาก killer_survivor_mode เดิม (API ล้วน ๆ ด้านบน) ให้มีหน้าจอเล่นได้จริง
# แทนที่จะเป็นแค่ JSON — ฉาก 3D อย่างง่ายด้วย Three.js (กล่อง/ระนาบพื้นฐาน ไม่ใช่
# กราฟิกสมจริง แต่มองรอบตัวได้ 360° เดินสำรวจแผนที่จริงได้) มุมมองบุคคลที่หนึ่ง
# ถือปืน (ทำจากรูปทรงเรขาคณิตง่าย ๆ ใน Three.js) — ตำแหน่งจุดหาของ/จุดหนีออกบน
# ฉาก 3D คำนวณจากพิกัด x,y จริงใน KILLER_MODE_MAP_SPOTS (ด้านบน) ตรง ๆ ไม่ใช่
# ค่าคงที่แยกต่างหาก เพื่อให้สิ่งที่เห็นบนจอตรงกับสิ่งที่ API คำนวณเป๊ะ
#
# รองรับทั้งคอมพิวเตอร์ (WASD เดิน + เมาส์ mouse-look + คลิกซ้ายยิง/เก็บของ) และ
# มือถือ (joystick เดินซ้ายล่าง + ลากขวาเพื่อหมุนกล้อง + ปุ่มยิง/เก็บของ)
# ==========================================

# [6z5c] Bamboo Chop + Double-Jump Climb System — 3D (Three.js killer-mode scene)
BAMBOO_CHOP_CLIMB_3D_ENABLED = True
BAMBOO_CHOP_CLIMB_3D_JS = r"""<script>
(function(){
if(window.__VMAX_BAMBOO_3D__) return; window.__VMAX_BAMBOO_3D__=true;
if(typeof THREE==='undefined' || typeof vmaxAnimate!=='function' || typeof vmaxInitScene!=='function'){ return; }

const BAMBOO3D_TREES=[
  {id:'b1', x:18, z:-15, hp:100, maxHp:100, cut:false, cutAt:0, pole:null, stump:null},
  {id:'b2', x:23, z:-9,  hp:100, maxHp:100, cut:false, cutAt:0, pole:null, stump:null},
  {id:'b3', x:14, z:-21, hp:100, maxHp:100, cut:false, cutAt:0, pole:null, stump:null}
];
const CHOP_DAMAGE=25, CHOP_RANGE=5, GRAB_RANGE=5.5, RESPAWN_MS=40000;
const CLIMB_MAX_H=4.6, CLIMB_SPEED=2.2, GRAVITY=14, JUMP_VY=6.5, DOUBLE_TAP_MS=420, EYE_H=1.7;

let bambooJumping=false, bambooVY=0, bambooYOffset=0;
let isClimbing3D=false, climbH=0;
let lastSpaceAt=-9999, lastFrameAt=performance.now(), lastChopAt=0;

function forwardVec(){
  const v=new THREE.Vector3(0,0,-1);
  v.applyAxisAngle(new THREE.Vector3(0,1,0), lookYaw);
  return v;
}

function findTree(maxDist, requireFacing){
  const p=playerRig.position, f=forwardVec();
  let best=null, bestD=Infinity;
  BAMBOO3D_TREES.forEach(t=>{
    if(t.cut) return;
    const dx=t.x-p.x, dz=t.z-p.z, d=Math.hypot(dx,dz);
    if(d>maxDist) return;
    if(requireFacing){
      const mag=d||1, dot=(dx/mag)*f.x+(dz/mag)*f.z;
      if(dot<0.35) return;
    }
    if(d<bestD){ bestD=d; best=t; }
  });
  return best;
}

function makeBambooGroup(){
  const g=new THREE.Group();
  const segH=1.1, segs=4;
  for(let i=0;i<segs;i++){
    const mat=new THREE.MeshStandardMaterial({color: i%2===0?0x6fae3e:0x8fce53});
    const seg=new THREE.Mesh(new THREE.CylinderGeometry(0.32,0.36,segH,8), mat);
    seg.position.y=0.2+i*segH+segH/2;
    g.add(seg);
    if(i<segs-1){
      const ring=new THREE.Mesh(new THREE.CylinderGeometry(0.4,0.4,0.08,8), new THREE.MeshStandardMaterial({color:0x3f5c22}));
      ring.position.y=0.2+(i+1)*segH;
      g.add(ring);
    }
  }
  const leaf=new THREE.Mesh(new THREE.ConeGeometry(0.9,1.4,6), new THREE.MeshStandardMaterial({color:0xbfe98a}));
  leaf.position.y=0.2+segs*segH+0.6;
  g.add(leaf);
  return g;
}
function makeStump(){
  return new THREE.Mesh(new THREE.CylinderGeometry(0.38,0.42,0.4,8), new THREE.MeshStandardMaterial({color:0x7a5c3a}));
}

function createBambooMeshes(){
  BAMBOO3D_TREES.forEach(t=>{
    const pole=makeBambooGroup();
    pole.position.set(t.x,0,t.z);
    scene.add(pole);
    const stump=makeStump();
    stump.position.set(t.x,0.2,t.z);
    stump.visible=false;
    scene.add(stump);
    t.pole=pole; t.stump=stump;
  });
}

function chop3D(){
  if(isClimbing3D) return;
  const now=performance.now();
  if(now-lastChopAt<300) return;
  const target=findTree(CHOP_RANGE,true);
  if(!target){ if(typeof vmaxShowMsg==='function') vmaxShowMsg('ไม่มีต้นไผ่ให้ฟันตรงนี้'); return; }
  lastChopAt=now;
  target.hp-=CHOP_DAMAGE;
  if(target.hp<=0){
    target.hp=0; target.cut=true; target.cutAt=now;
    if(target.pole) target.pole.visible=false;
    if(target.stump) target.stump.visible=true;
    if(typeof vmaxShowMsg==='function') vmaxShowMsg('🎍 ตัดต้นไผ่สำเร็จ!');
  } else {
    if(typeof vmaxShowMsg==='function') vmaxShowMsg('🪓 ฟันต้นไผ่! ('+target.hp+'/'+target.maxHp+')');
  }
}

function startClimb3D(){
  const target=findTree(GRAB_RANGE,true);
  if(!target) return false;
  isClimbing3D=true; climbH=0.3;
  bambooJumping=false; bambooVY=0; bambooYOffset=0;
  const p=playerRig.position;
  const dx=target.x-p.x, dz=target.z-p.z, d=Math.hypot(dx,dz)||1;
  p.x=target.x-(dx/d)*1.1; p.z=target.z-(dz/d)*1.1;
  if(typeof vmaxShowMsg==='function') vmaxShowMsg('🎍 กระโดด 2 จังหวะ เกาะไม้ไผ่แล้ว! เดินหน้า/ถอยหลังปีนขึ้น-ลง กดกระโดดอีกครั้งเพื่อกระโดดออก');
  return true;
}
function releaseClimb3D(hop){
  isClimbing3D=false;
  if(hop){
    bambooJumping=true; bambooVY=JUMP_VY*0.75;
    const f=forwardVec();
    playerRig.position.x-=f.x*1.5; playerRig.position.z-=f.z*1.5;
  }
  climbH=0;
}

function handleSpacePress(){
  const now=performance.now();
  const isDouble=(now-lastSpaceAt)<DOUBLE_TAP_MS;
  lastSpaceAt=now;
  if(isClimbing3D){ releaseClimb3D(true); return; }
  if(isDouble){ if(startClimb3D()) return; }
  if(!bambooJumping){ bambooJumping=true; bambooVY=JUMP_VY; }
}

document.addEventListener('keydown', e=>{
  if(e.code==='Space'){ e.preventDefault(); handleSpacePress(); }
  if(e.code==='KeyF'){ chop3D(); }
});

function addMobileButtons(){
  const wrap=document.getElementById('vmax-mobile-controls');
  if(!wrap || document.getElementById('vmax-btn-jump3d')) return;
  const jumpBtn=document.createElement('div');
  jumpBtn.className='vmax-action-btn'; jumpBtn.id='vmax-btn-jump3d';
  jumpBtn.style.right='192px'; jumpBtn.textContent='⬆️';
  jumpBtn.addEventListener('touchstart', e=>{ e.preventDefault(); handleSpacePress(); });
  wrap.appendChild(jumpBtn);
  const chopBtn=document.createElement('div');
  chopBtn.className='vmax-action-btn'; chopBtn.id='vmax-btn-chop3d';
  chopBtn.style.right='32px'; chopBtn.style.bottom='34px'; chopBtn.textContent='🪓';
  chopBtn.addEventListener('touchstart', e=>{ e.preventDefault(); chop3D(); });
  wrap.appendChild(chopBtn);
}
addMobileButtons();

const _origInitScene3D=vmaxInitScene;
vmaxInitScene=function(){
  _origInitScene3D();
  try{ createBambooMeshes(); }catch(e){ console.error(e); }
};

const _origAnimate3D=vmaxAnimate;
vmaxAnimate=function(){
  const now=performance.now();
  const dt=Math.min(0.05,(now-lastFrameAt)/1000);
  lastFrameAt=now;

  BAMBOO3D_TREES.forEach(t=>{
    if(t.cut && now-t.cutAt>RESPAWN_MS){
      t.cut=false; t.hp=t.maxHp;
      if(t.pole) t.pole.visible=true;
      if(t.stump) t.stump.visible=false;
    }
  });

  if(isClimbing3D){
    const savedFwd=moveState.fwd, savedStrafe=moveState.strafe;
    moveState.fwd=0; moveState.strafe=0;
    _origAnimate3D();
    moveState.fwd=savedFwd; moveState.strafe=savedStrafe;
    climbH+=savedFwd*CLIMB_SPEED*dt;
    climbH=Math.max(0,Math.min(CLIMB_MAX_H,climbH));
    if(climbH<=0 && savedFwd<0){ releaseClimb3D(false); }
    playerRig.position.y=EYE_H+climbH;
  } else {
    _origAnimate3D();
    if(bambooJumping){
      bambooYOffset+=bambooVY*dt;
      bambooVY-=GRAVITY*dt;
      if(bambooYOffset<=0){ bambooYOffset=0; bambooJumping=false; }
    }
    playerRig.position.y=EYE_H+bambooYOffset;
  }
};
})();
</script>"""
VMAX_MODULES['bamboo_chop_climb_3d']={'name':'ระบบฟันต้นไผ่ + ปีนไม้ไผ่ (double-jump) — 3D','level':'intermediate','category':'core','desc':'เวอร์ชัน 3D (Three.js) ของระบบฟันไผ่/ปีนไผ่ ต่อกับฉาก killer-mode: กด F ฟัน, กด Space 2 จังหวะขณะหันหน้าเข้าไม้ไผ่เพื่อปีน','routes':['/killer-mode/play']}


