# [ 6z6. Mahjong Scoreboard module (merged from mahjong_game.py) ]
# เดิมเป็นเซิร์ฟเวอร์ Flask แยกต่างหาก รันที่พอร์ต 5050 ของตัวเอง — ฝังเข้ามาเป็นโมดูล
# ในนี้แทน โดยใช้ app/sio ตัวเดียวกับ VMAX Kernel (ประกาศไว้ที่ [1b] ด้านบนสุด) ไม่ได้
# สร้าง Flask() ใหม่ซ้อน และไม่มีการ app.run()/sio.run() ซ้ำ (ตัวเดียวพอที่ท้ายไฟล์)
# เพื่อไม่ให้ชนกับ route เดิมของ VMAX Kernel ('/', '/api/state' ฯลฯ) ทุก route ของ
# มาห์จองถูกย้ายไปอยู่ใต้ prefix /mahjong และ /api/mahjong/* ทั้งหมด (เช็คแล้วว่าไม่ชน
# กับ route อื่นในไฟล์นี้)
#
# เจตนาของโมดูลนี้เหมือนไฟล์เดิมทุกประการ: "แต้ม" ทุกตัวในนี้คือคะแนนเกม (game score)
# ล้วนๆ ไม่มีการแปลงเป็นเงินจริง ไม่มีระบบฝาก/ถอน/payment ใดๆ
# ==========================================

from dataclasses import dataclass as _mj_dataclass, field as _mj_field
from typing import Dict as _MjDict, List as _MjList
from flask import render_template_string as _mj_render_template_string

MAHJONG_RIICHI_STICK_VALUE = 1000  # แต้มต่อไม้ริจิ 1 ไม้ (ค่ามาตรฐาน, เป็นแต้มเกมล้วนๆ)


@_mj_dataclass
class MahjongPlayer:
    player_id: str
    name: str
    score: int = 25000
    is_riichi: bool = False


@_mj_dataclass
class MahjongRoundResult:
    kind: str
    details: _MjDict = _mj_field(default_factory=dict)


class RiichiMahjongScoreBoard:
    def __init__(self, players: _MjList[MahjongPlayer], starting_score: int = 25000):
        self.players: _MjDict[str, MahjongPlayer] = {p.player_id: p for p in players}
        for p in self.players.values():
            p.score = starting_score

        self.riichi_pot = 0
        self.riichi_owners: _MjDict[str, int] = {}
        self.honba = 0

    def declare_riichi(self, player_id: str) -> None:
        p = self.players[player_id]
        if p.is_riichi:
            raise ValueError(f"{p.name} ริจิไปแล้ว วางซ้ำไม่ได้")
        if p.score < MAHJONG_RIICHI_STICK_VALUE:
            raise ValueError(f"{p.name} แต้มไม่พอวางริจิ (ต้องมีอย่างน้อย {MAHJONG_RIICHI_STICK_VALUE})")

        p.score -= MAHJONG_RIICHI_STICK_VALUE
        p.is_riichi = True
        self.riichi_pot += MAHJONG_RIICHI_STICK_VALUE
        self.riichi_owners[player_id] = self.riichi_owners.get(player_id, 0) + 1

    def settle_win(self, winner_id: str, points_from_others: int) -> MahjongRoundResult:
        winner = self.players[winner_id]
        winner.score += points_from_others
        won_pot = self.riichi_pot

        winner.score += won_pot
        self.riichi_pot = 0
        self.riichi_owners.clear()

        for p in self.players.values():
            p.is_riichi = False

        result = MahjongRoundResult(kind="win", details={
            "winner": winner_id,
            "riichi_pot_won": won_pot,
            "honba": self.honba,
        })
        self.honba += 1
        return result

    def settle_exhaustive_draw(self, tenpai_player_ids: _MjList[str]) -> MahjongRoundResult:
        """流局 — ไม่มีคนชนะ ไม้ริจิไม่หาย ยกยอดกองไปรอบถัดไปอัตโนมัติ"""
        all_ids = list(self.players.keys())
        noten_ids = [pid for pid in all_ids if pid not in tenpai_player_ids]

        if tenpai_player_ids and noten_ids:
            n_tenpai, n_noten = len(tenpai_player_ids), len(noten_ids)
            payout_table = {
                (1, 3): (3000, 1000), (3, 1): (1000, 3000),
                (2, 2): (1500, 1500),
                (1, 2): (1500, 750), (2, 1): (750, 1500),
            }
            pay_each_tenpai, pay_each_noten = payout_table.get(
                (n_tenpai, n_noten), (0, 0)
            )
            for pid in tenpai_player_ids:
                self.players[pid].score += pay_each_tenpai
            for pid in noten_ids:
                self.players[pid].score -= pay_each_noten

        for p in self.players.values():
            p.is_riichi = False

        result = MahjongRoundResult(kind="exhaustive_draw", details={
            "tenpai": tenpai_player_ids,
            "noten": noten_ids,
            "riichi_pot_carried_over": self.riichi_pot,
            "honba": self.honba,
        })
        self.honba += 1
        return result

    def refund_unclaimed_riichi_pot_at_session_end(self) -> MahjongRoundResult:
        """จบ session ทั้งหมด ไม่มีรอบถัดไปให้ยกยอด — คืนแต้มไม้ริจิให้เจ้าของ"""
        refunds: _MjDict[str, int] = {}
        for pid, stick_count in self.riichi_owners.items():
            amount = stick_count * MAHJONG_RIICHI_STICK_VALUE
            self.players[pid].score += amount
            refunds[pid] = amount

        leftover = self.riichi_pot - sum(refunds.values())
        if leftover != 0:
            raise RuntimeError(
                f"ไม้ริจิในกอง ({self.riichi_pot}) กับผลรวมที่คืนได้ ({sum(refunds.values())}) "
                f"ไม่ตรงกัน ต่างกัน {leftover} แต้ม"
            )

        self.riichi_pot = 0
        self.riichi_owners.clear()
        return MahjongRoundResult(kind="session_end_refund", details={"refunds": refunds})

    def get_state(self) -> _MjDict:
        return {
            "players": {
                pid: {"name": p.name, "score": p.score, "is_riichi": p.is_riichi}
                for pid, p in self.players.items()
            },
            "riichi_pot": self.riichi_pot,
            "honba": self.honba,
        }


MAHJONG_DEFAULT_PLAYERS = [
    MahjongPlayer("p1", "ผู้เล่น 1"),
    MahjongPlayer("p2", "ผู้เล่น 2"),
    MahjongPlayer("p3", "ผู้เล่น 3"),
]
mahjong_board = RiichiMahjongScoreBoard(MAHJONG_DEFAULT_PLAYERS, starting_score=25000)

