@app.route("/mahjong")
def mahjong_index():
    return _mj_render_template_string(MAHJONG_PAGE)


@app.route("/api/mahjong/state")
def api_mahjong_state():
    return jsonify(mahjong_board.get_state())


@app.route("/api/mahjong/riichi", methods=["POST"])
@require_auth_toggleable
def api_mahjong_riichi():
    body = request.get_json(force=True, silent=True) or {}
    player_id = body.get("player_id")
    try:
        mahjong_board.declare_riichi(player_id)
        return jsonify({"st": "ok", "state": mahjong_board.get_state()})
    except (ValueError, KeyError) as e:
        return jsonify({"st": "error", "msg": str(e)}), 400


@app.route("/api/mahjong/round/win", methods=["POST"])
@require_auth_toggleable
def api_mahjong_round_win():
    body = request.get_json(force=True, silent=True) or {}
    winner_id = body.get("winner_id")
    points = int(body.get("points_from_others", 0))
    try:
        result = mahjong_board.settle_win(winner_id, points)
        return jsonify({"st": "ok", "result": result.details, "state": mahjong_board.get_state()})
    except KeyError as e:
        return jsonify({"st": "error", "msg": f"ไม่รู้จักผู้เล่น: {e}"}), 400


@app.route("/api/mahjong/round/draw", methods=["POST"])
@require_auth_toggleable
def api_mahjong_round_draw():
    body = request.get_json(force=True, silent=True) or {}
    tenpai_ids = body.get("tenpai_player_ids", [])
    result = mahjong_board.settle_exhaustive_draw(tenpai_ids)
    return jsonify({"st": "ok", "result": result.details, "state": mahjong_board.get_state()})


@app.route("/api/mahjong/session/end", methods=["POST"])
@require_auth_toggleable
def api_mahjong_session_end():
    """จบ session ทั้งหมด — คืนไม้ริจิที่ยังค้างอยู่ในกองกลับให้เจ้าของ"""
    try:
        result = mahjong_board.refund_unclaimed_riichi_pot_at_session_end()
        return jsonify({"st": "ok", "result": result.details, "state": mahjong_board.get_state()})
    except RuntimeError as e:
        return jsonify({"st": "error", "msg": str(e)}), 500


