        {"id": "w_score500",    "label": "ทำคะแนนสะสม 500 แต้ม",       "target": 500,"reward_credits": 300, "reward_shards": 18},
        {"id": "w_login5",      "label": "เข้าเกม 5 วันในสัปดาห์นี้",   "target": 5,  "reward_credits": 200, "reward_shards": 12},
