def _tower_floor_config(floor: int) -> dict:
    """คืนค่า config ของชั้นที่ระบุ — authored ถ้ามี ไม่งั้น generate อัตโนมัติ (ไม่มีวันจบ)."""
    if 1 <= floor <= len(TOWER_FLOORS_AUTHORED):
        cfg = dict(TOWER_FLOORS_AUTHORED[floor - 1])
    else:
        zone = TOWER_ZONE_NAMES[(floor - 1) % len(TOWER_ZONE_NAMES)]
        wing = 1 + (floor - 1) // len(TOWER_ZONE_NAMES)
        is_boss = (floor % 10 == 0)
        cfg = {
            "floor": floor,
            "zone": f"{zone} (ปีก {wing})",
            "enemy_count": 1 if is_boss else min(6, 3 + floor // 15),
            "boss": is_boss,
        }
        if is_boss:
            cfg["boss_name"] = f"เจ้าของโรงแรมชั้น {floor} (ร่างที่ {wing})"
    return cfg


def _tower_enemy_stat_base(floor: int, tier: str) -> dict:
    tier_meta = TOWER_TIER_META.get(tier, TOWER_TIER_META["normal"])
    growth = 1.0 + (floor - 1) * 0.12
    hp = int(60 * growth * tier_meta["hp_mult"])
    atk = int(9 * growth * tier_meta["atk_mult"])
    return {"hp": hp, "atk": atk}


def tower_build_encounter(floor: int, tier: str) -> dict:
    """สร้างศัตรูของชั้นนี้ใหม่ทั้งหมด (เรียกตอนเริ่ม battle)."""
    cfg = _tower_floor_config(floor)
    base = _tower_enemy_stat_base(floor, tier)
    enemies = []
    if cfg["boss"]:
        enemies.append({
            "id": "enemy_0",
            "name": cfg.get("boss_name", "บอสประจำชั้น"),
            "element": random.choice(ELEMENTS),
            "hp": base["hp"] * 8,
            "hp_max": base["hp"] * 8,
            "atk": int(base["atk"] * 2.2),
            "is_boss": True,
            "stacks": {e: 0 for e in ELEMENTS},
        })
    else:
        for i in range(cfg["enemy_count"]):
            enemies.append({
                "id": f"enemy_{i}",
                "name": random.choice(TOWER_ENEMY_NAME_POOL),
                "element": random.choice(ELEMENTS),
                "hp": base["hp"],
                "hp_max": base["hp"],
                "atk": base["atk"],
                "is_boss": False,
                "stacks": {e: 0 for e in ELEMENTS},
            })
    return {"floor": floor, "tier": tier, "zone": cfg["zone"], "enemies": enemies}


