# uid -> {char_id: {"level": int, "exp": int, "stars": int, "unlocked_skills": [ids]}}
TOWER_PLAYER_CHARS = {}
# uid -> {char_id: int}  เศษวัสดุปลดล็อคดาว (ได้จากรางวัลด่าน/ความสำเร็จ)
TOWER_CHAR_FRAGMENTS = {}


def _tower_player_chars(uid: str) -> dict:
    store = TOWER_PLAYER_CHARS.setdefault(uid, {})
    for char_id in TOWER_ROSTER:
        store.setdefault(char_id, {"level": 1, "exp": 0, "stars": 1, "unlocked_skills": ["basic"]})
    return store


def _tower_fragments(uid: str) -> dict:
    return TOWER_CHAR_FRAGMENTS.setdefault(uid, {cid: 0 for cid in TOWER_ROSTER})


def tower_char_fragments_add(uid: str, char_id: str, amount: int):
    frags = _tower_fragments(uid)
    frags[char_id] = frags.get(char_id, 0) + amount


def _tower_sync_skills(char_id: str, char_state: dict):
    """ปลดล็อคสกิลในแถบ (ladder) ที่ครบเงื่อนไขเลเวล+ดาวแล้วโดยอัตโนมัติ."""
    roster = TOWER_ROSTER[char_id]
    unlocked = set(char_state["unlocked_skills"])
    for node in roster["skill_track"]:
        if char_state["level"] >= node["unlock_level"] and char_state["stars"] >= node["unlock_star"]:
            unlocked.add(node["id"])
    char_state["unlocked_skills"] = [n["id"] for n in roster["skill_track"] if n["id"] in unlocked]


def tower_char_stats(uid: str, char_id: str) -> dict:
    roster = TOWER_ROSTER[char_id]
    state = _tower_player_chars(uid)[char_id]
    lvl, stars = state["level"], state["stars"]
    hp = int(roster["base_hp"] * (1 + 0.10 * (lvl - 1)) * (1 + 0.15 * (stars - 1)))
    atk = int(roster["base_atk"] * (1 + 0.08 * (lvl - 1)) * (1 + 0.15 * (stars - 1)))
    return {"hp": hp, "hp_max": hp, "atk": atk, "level": lvl, "stars": stars,
            "level_cap": TOWER_LEVEL_CAP_BY_STAR.get(stars, 90),
            "unlocked_skills": state["unlocked_skills"]}


def tower_char_level_up(uid: str, char_id: str, times: int = 1) -> tuple[bool, str, dict]:
    if char_id not in TOWER_ROSTER:
        return False, "ไม่พบตัวละครนี้", {}
    state = _tower_player_chars(uid)[char_id]
    cap = TOWER_LEVEL_CAP_BY_STAR.get(state["stars"], 90)
    if state["level"] >= cap:
        return False, f"เลเวลถึงเพดานของ {state['stars']} ดาวแล้ว (เพดาน {cap}) — ปลดล็อคดาวเพิ่มก่อน", tower_char_stats(uid, char_id)
    total_cost = 0
    leveled = 0
    for _ in range(max(1, times)):
        if state["level"] >= cap:
            break
        total_cost += 40 + state["level"] * 15
        if P["credits"] < total_cost:
            total_cost -= 40 + state["level"] * 15
            break
        state["level"] += 1
        leveled += 1
    if leveled == 0:
        return False, "เครดิตไม่พอสำหรับอัพเลเวล", tower_char_stats(uid, char_id)
    P["credits"] -= total_cost
    _tower_sync_skills(char_id, state)
    return True, f"อัพเลเวล {roster_name(char_id)} ขึ้น {leveled} เลเวล (ใช้ {total_cost} เครดิต)", tower_char_stats(uid, char_id)


# --- [ใช้ gold_coin (ไอเทมในกระเป๋าเป้) อัพเกรดตัวละคร/ปลดสกิล — เสริมจากเครดิต/เศษดาวเดิม ไม่แทนที่] ---
TOWER_GOLD_ITEM = "gold_coin"
TOWER_GOLD_LEVEL_COST_BASE = 10        # gold_coin ต่อเลเวล = BASE + level * PER_LEVEL
TOWER_GOLD_LEVEL_COST_PER_LEVEL = 3
TOWER_GOLD_SKILL_COST_PER_MISSING_STAR = 120   # ปลดสกิลที่เลเวลถึงแล้วแต่ดาวยังไม่ถึง: จ่ายต่อดาวที่ขาด


def _tower_gold_have(uid: str) -> int:
    st = storage_get(uid)
    return sum(slot["qty"] for slot in st["backpack"].values() if slot["item"] == TOWER_GOLD_ITEM)


def _tower_gold_spend(uid: str, amount: int) -> bool:
    if amount <= 0:
        return True
    if _tower_gold_have(uid) < amount:
        return False
    st = storage_get(uid)
    remaining = amount
    for slot in list(st["backpack"].values()):
        if remaining <= 0:
            break
        if slot["item"] == TOWER_GOLD_ITEM:
            take = min(slot["qty"], remaining)
            slot["qty"] -= take
            remaining -= take
    st["backpack"] = {k: v for k, v in st["backpack"].items() if v["qty"] > 0}
    return True


def tower_char_level_up_gold(uid: str, char_id: str, times: int = 1) -> tuple[bool, str, dict]:
    """อัพเลเวลด้วย gold_coin จากกระเป๋าเป้ (เพดานเลเวลตามดาวเหมือนเดิม)"""
    if char_id not in TOWER_ROSTER:
        return False, "ไม่พบตัวละครนี้", {}
    state = _tower_player_chars(uid)[char_id]
    cap = TOWER_LEVEL_CAP_BY_STAR.get(state["stars"], 90)
    if state["level"] >= cap:
        return False, f"เลเวลถึงเพดานของ {state['stars']} ดาวแล้ว (เพดาน {cap}) — ปลดล็อคดาวเพิ่มก่อน", tower_char_stats(uid, char_id)
    have = _tower_gold_have(uid)
    total, leveled, lvl = 0, 0, state["level"]
    for _ in range(max(1, min(int(times), 100))):
        if lvl >= cap:
            break
        c = TOWER_GOLD_LEVEL_COST_BASE + lvl * TOWER_GOLD_LEVEL_COST_PER_LEVEL
        if have < total + c:
            break
        total += c
        lvl += 1
        leveled += 1
    if leveled == 0:
        need = TOWER_GOLD_LEVEL_COST_BASE + state["level"] * TOWER_GOLD_LEVEL_COST_PER_LEVEL
        return False, f"{TOWER_GOLD_ITEM} ไม่พอ (ต้องการ {need} มี {have})", tower_char_stats(uid, char_id)
    _tower_gold_spend(uid, total)
    state["level"] = lvl
    _tower_sync_skills(char_id, state)
    return True, f"อัพเลเวล {roster_name(char_id)} ขึ้น {leveled} เลเวล (ใช้ {total} {TOWER_GOLD_ITEM})", tower_char_stats(uid, char_id)


def tower_char_skill_unlock_gold(uid: str, char_id: str, skill_id: str) -> tuple[bool, str, dict]:
    """ปลดสกิลด้วย gold_coin: ต้องเลเวลถึงเงื่อนไขแล้ว ส่วนดาวที่ยังขาด จ่ายเป็น gold_coin ต่อดาวที่ขาดแทนการรอเศษปลดดาว"""
    if char_id not in TOWER_ROSTER:
        return False, "ไม่พบตัวละครนี้", {}
    state = _tower_player_chars(uid)[char_id]
    node = next((n for n in TOWER_ROSTER[char_id]["skill_track"] if n["id"] == skill_id), None)
    if not node:
        return False, "ไม่พบสกิลนี้", tower_char_stats(uid, char_id)
    if skill_id in state["unlocked_skills"]:
        return False, "สกิลนี้ปลดล็อคแล้ว", tower_char_stats(uid, char_id)
    if state["level"] < node["unlock_level"]:
        return False, f"เลเวลยังไม่ถึง (ต้องการ Lv.{node['unlock_level']}) — ใช้ gold_coin ข้ามเลเวลไม่ได้", tower_char_stats(uid, char_id)
    missing = max(0, node["unlock_star"] - state["stars"])
    cost = missing * TOWER_GOLD_SKILL_COST_PER_MISSING_STAR
    if cost > 0 and not _tower_gold_spend(uid, cost):
        return False, f"{TOWER_GOLD_ITEM} ไม่พอ (ต้องการ {cost} มี {_tower_gold_have(uid)})", tower_char_stats(uid, char_id)
    state["unlocked_skills"].append(skill_id)
    _tower_sync_skills(char_id, state)
    return True, f"ปลดสกิล {node['name']} ของ {roster_name(char_id)} สำเร็จ (ใช้ {cost} {TOWER_GOLD_ITEM})", tower_char_stats(uid, char_id)


TOWER_GOLD_STAR_COST_PER_FRAGMENT = 8   # อัพดาวด้วย gold_coin: ราคา = เศษที่ขาด x ค่านี้ (ใช้เศษที่มีก่อน ส่วนที่ขาดจ่ายเป็นเหรียญ)


def tower_char_star_up_gold(uid: str, char_id: str) -> tuple[bool, str, dict]:
    """อัพดาวโดยใช้เศษที่มีอยู่ก่อน แล้วจ่ายส่วนที่ขาดด้วย gold_coin จากกระเป๋าเป้"""
    if char_id not in TOWER_ROSTER:
        return False, "ไม่พบตัวละครนี้", {}
    state = _tower_player_chars(uid)[char_id]
    if state["stars"] >= TOWER_STAR_MAX:
        return False, f"{roster_name(char_id)} ถึง {TOWER_STAR_MAX} ดาวสูงสุดแล้ว", tower_char_stats(uid, char_id)
    cost = TOWER_STAR_UP_FRAGMENT_COST[state["stars"] - 1]
    frags = _tower_fragments(uid)
    have_f = frags.get(char_id, 0)
    missing = max(0, cost - have_f)
    gold_cost = missing * TOWER_GOLD_STAR_COST_PER_FRAGMENT
    if gold_cost > 0 and _tower_gold_have(uid) < gold_cost:
        return False, f"{TOWER_GOLD_ITEM} ไม่พอ (ต้องการ {gold_cost} สำหรับเศษที่ขาด {missing} ชิ้น มี {_tower_gold_have(uid)})", tower_char_stats(uid, char_id)
    _tower_gold_spend(uid, gold_cost)
    frags[char_id] = have_f - (cost - missing)
    state["stars"] += 1
    _tower_sync_skills(char_id, state)
    return True, f"ปลดล็อค {roster_name(char_id)} เป็น {state['stars']} ดาวสำเร็จ (ใช้เศษ {cost - missing} + {gold_cost} {TOWER_GOLD_ITEM})", tower_char_stats(uid, char_id)


def roster_name(char_id: str) -> str:
    return TOWER_ROSTER.get(char_id, {}).get("name", char_id)


def tower_char_star_up(uid: str, char_id: str) -> tuple[bool, str, dict]:
    if char_id not in TOWER_ROSTER:
        return False, "ไม่พบตัวละครนี้", {}
    state = _tower_player_chars(uid)[char_id]
    if state["stars"] >= TOWER_STAR_MAX:
        return False, f"{roster_name(char_id)} ถึง {TOWER_STAR_MAX} ดาวสูงสุดแล้ว", tower_char_stats(uid, char_id)
    cost = TOWER_STAR_UP_FRAGMENT_COST[state["stars"] - 1]
    frags = _tower_fragments(uid)
    if frags.get(char_id, 0) < cost:
        return False, f"เศษวัสดุไม่พอ (ต้องการ {cost}, มี {frags.get(char_id, 0)})", tower_char_stats(uid, char_id)
    frags[char_id] -= cost
    state["stars"] += 1
    _tower_sync_skills(char_id, state)
    return True, f"ปลดล็อค {roster_name(char_id)} เป็น {state['stars']} ดาวสำเร็จ!", tower_char_stats(uid, char_id)


# ==========================================
# [ 6z3. Battle Loop — turn-based, elemental stacking on enemy heads ]
# ==========================================
# uid -> {"floor":int, "tier":str, "zone":str, "enemies":[...], "team":[char_id,...],
#         "team_hp":{char_id:int}, "log":[...], "won":bool|None}
TOWER_BATTLES = {}

TOWER_TEAM_SIZE = 3


def tower_progress(uid: str) -> dict:
    return TOWER_PROGRESS.setdefault(uid, {t: {"highest_cleared": 0, "claimed_first_clear": []} for t in TOWER_TIERS})


TOWER_PROGRESS = {}


def tower_tier_unlocked(uid: str, tier: str) -> bool:
    if tier == "normal":
        return True
    idx = TOWER_TIERS.index(tier)
    prev_tier = TOWER_TIERS[idx - 1]
    need = TOWER_TIER_META[tier]["unlock_floor"]
    return tower_progress(uid)[prev_tier]["highest_cleared"] >= need


def tower_battle_start(uid: str, floor: int, tier: str, team: list) -> tuple[bool, str, dict]:
    if tier not in TOWER_TIERS:
        return False, "ระดับความยากไม่ถูกต้อง", {}
    if not tower_tier_unlocked(uid, tier):
        prev = TOWER_TIERS[TOWER_TIERS.index(tier) - 1]
        return False, f"ยังไม่ปลดล็อค — ต้องผ่านชั้น {TOWER_TIER_META[tier]['unlock_floor']} ของ {TOWER_TIER_META[prev]['name_th']} ก่อน", {}
    highest = tower_progress(uid)[tier]["highest_cleared"]
    if floor > highest + 1:
        return False, f"ต้องผ่านชั้น {floor - 1} ก่อนถึงจะเข้าชั้นนี้ได้", {}
    if not team:
        return False, "กรุณาเลือกตัวละครลงทีมอย่างน้อย 1 ตัว", {}
    team = [c for c in team if c in TOWER_ROSTER][:TOWER_TEAM_SIZE]
    if not team:
        return False, "ทีมที่เลือกไม่ถูกต้อง", {}
    encounter = tower_build_encounter(floor, tier)
    team_hp = {cid: tower_char_stats(uid, cid)["hp_max"] for cid in team}
    battle = {
        "floor": floor, "tier": tier, "zone": encounter["zone"],
        "enemies": encounter["enemies"], "team": team, "team_hp": team_hp,
        "log": [f"เข้าสู่ชั้น {floor} — {encounter['zone']} ({TOWER_TIER_META[tier]['name_th']})"],
        "won": None,
    }
    TOWER_BATTLES[uid] = battle
    return True, "เริ่มการต่อสู้", battle


def _tower_enemy_alive(battle: dict) -> list:
    return [e for e in battle["enemies"] if e["hp"] > 0]


def tower_battle_attack(uid: str, char_id: str, skill_id: str, target_id: str) -> tuple[bool, str, dict]:
    battle = TOWER_BATTLES.get(uid)
    if not battle or battle["won"] is not None:
        return False, "ไม่มีการต่อสู้ที่กำลังดำเนินอยู่", {}
    if char_id not in battle["team"] or battle["team_hp"].get(char_id, 0) <= 0:
        return False, "ตัวละครนี้ไม่อยู่ในทีมหรือหมดสภาพแล้ว", battle
    stats = tower_char_stats(uid, char_id)
    if skill_id not in stats["unlocked_skills"]:
        return False, "ยังไม่ปลดล็อคสกิลนี้", battle
    skill = next((s for s in TOWER_ROSTER[char_id]["skill_track"] if s["id"] == skill_id), None)
    if not skill or skill["power_mult"] <= 0:
        return False, "สกิลนี้ใช้โจมตีไม่ได้ (พาสซีฟ)", battle
    target = next((e for e in battle["enemies"] if e["id"] == target_id and e["hp"] > 0), None)
    if not target:
        return False, "เป้าหมายไม่ถูกต้องหรือตายแล้ว", battle

    char_elem = TOWER_ROSTER[char_id]["element"]
    dmg = int(stats["atk"] * skill["power_mult"])

    # โบนัสธาตุแพ้ทาง + สะสม stack ธาตุบนหัวศัตรู
    is_advantage = TOWER_ELEMENT_COUNTER.get(char_elem) == target["element"]
    if is_advantage:
        dmg = int(dmg * 1.5)
        target["stacks"][char_elem] = target["stacks"].get(char_elem, 0) + 1
        if target["stacks"][char_elem] >= TOWER_ELEMENT_STACK_MAX:
            dmg = int(dmg * TOWER_ELEMENT_BURST_MULT)
            target["stacks"][char_elem] = 0
            battle["log"].append(f"💥 {ELEMENT_META[char_elem]['emoji']} ธาตุสะสมครบ {TOWER_ELEMENT_STACK_MAX} stack บน {target['name']} — ระเบิดดาเมจ!")

    # ดาเมจเพิ่มจาก stack ธาตุอื่นๆที่ค้างอยู่บนหัวศัตรู (ความเปราะบางสะสม)
    total_stacks = sum(target["stacks"].values())
    if total_stacks:
        dmg = int(dmg * (1 + TOWER_ELEMENT_STACK_DMG_PCT * total_stacks))

    target["hp"] = max(0, target["hp"] - dmg)
    battle["log"].append(f"{roster_name(char_id)} ใช้ {skill['name']} ใส่ {target['name']} — {dmg} ดาเมจ "
                          f"({'ธาตุได้เปรียบ! ' if is_advantage else ''}stack รวม {sum(target['stacks'].values())})")

    if target["hp"] <= 0:
        battle["log"].append(f"☠️ {target['name']} ถูกกำจัด!")

    alive_enemies = _tower_enemy_alive(battle)
    if not alive_enemies:
        battle["won"] = True
        battle["log"].append("🎉 ชนะการต่อสู้!")
        _tower_apply_victory(uid, battle)
        return True, "ชนะ!", battle

    # ศัตรูที่เหลือโจมตีกลับ (สุ่มเป้าหมายในทีมที่ยังไม่ตาย)
    alive_team = [c for c in battle["team"] if battle["team_hp"].get(c, 0) > 0]
    for enemy in alive_enemies:
        if not alive_team:
            break
        victim = random.choice(alive_team)
        e_dmg = enemy["atk"]
        battle["team_hp"][victim] = max(0, battle["team_hp"][victim] - e_dmg)
        battle["log"].append(f"{enemy['name']} โจมตี {roster_name(victim)} — {e_dmg} ดาเมจ")
        if battle["team_hp"][victim] <= 0:
            battle["log"].append(f"💀 {roster_name(victim)} หมดสภาพ!")
            alive_team = [c for c in alive_team if c != victim]

    if not any(battle["team_hp"].get(c, 0) > 0 for c in battle["team"]):
        battle["won"] = False
        battle["log"].append("💀 ทีมพ่ายแพ้...")

    return True, "โจมตีสำเร็จ", battle


def _tower_floor_reward(floor: int, tier: str, first_clear: bool) -> dict:
    tier_meta = TOWER_TIER_META[tier]
    base_credits = int((30 + floor * 6) * tier_meta["atk_mult"])
    base_frag = 1 + floor // 5
    reward = {"credits": base_credits, "fragments": base_frag if floor % 5 == 0 else 0}
    if first_clear:
        reward["credits"] = int(reward["credits"] * 2)
        reward["fragments"] += 2
        reward["bonus"] = "first_clear"
    return reward


def _tower_apply_victory(uid: str, battle: dict):
    floor, tier = battle["floor"], battle["tier"]
    progress = tower_progress(uid)[tier]
    first_clear = floor > progress["highest_cleared"]
    if first_clear:
        progress["highest_cleared"] = floor
    reward = _tower_floor_reward(floor, tier, first_clear)
    P["credits"] += reward["credits"]
    if reward["fragments"]:
        for cid in battle["team"]:
            tower_char_fragments_add(uid, cid, reward["fragments"])
    battle["reward"] = reward


def tower_battle_flee(uid: str) -> tuple[bool, str, dict]:
    battle = TOWER_BATTLES.get(uid)
    if not battle or battle["won"] is not None:
        return False, "ไม่มีการต่อสู้ที่กำลังดำเนินอยู่", {}
    battle["won"] = False
    battle["log"].append("ล่าถอยจากการต่อสู้")
    return True, "ล่าถอยแล้ว", battle


