    {"id": "clear_floor_5",    "name": "แขกขาประจำ",      "desc": "ผ่านชั้น 5 (โหมดมาตรฐาน)",
     "type": "floor", "tier": "normal", "target": 5,  "reward": {"credits": 200, "fragments": 5}},
