# [ 6z5. Flask Routes — Hotel Tower Challenge ]
# ==========================================
@app.route("/api/tower/floors")
def api_tower_floors():
    tier = request.args.get("tier", "normal")
    highest = tower_progress(P["uid"])[tier]["highest_cleared"] if tier in TOWER_TIERS else 0
    preview = [_tower_floor_config(f) for f in range(1, highest + 7)]
    return jsonify({"st": "ok", "tier": tier, "unlocked": tower_tier_unlocked(P["uid"], tier),
                     "highest_cleared": highest, "floors": preview})


@app.route("/api/tower/tiers")
def api_tower_tiers():
    uid = P["uid"]
    out = []
    for t in TOWER_TIERS:
        out.append({"id": t, **TOWER_TIER_META[t], "unlocked": tower_tier_unlocked(uid, t),
                     "highest_cleared": tower_progress(uid)[t]["highest_cleared"]})
    return jsonify({"st": "ok", "tiers": out})


@app.route("/api/tower/roster")
def api_tower_roster():
    uid = P["uid"]
    out = []
    for cid, roster in TOWER_ROSTER.items():
        stats = tower_char_stats(uid, cid)
        out.append({"id": cid, "name": roster["name"], "element": roster["element"],
                     "rarity": roster["rarity"], "role": roster["role"],
                     "skill_track": roster["skill_track"], **stats,
                     "fragments": _tower_fragments(uid).get(cid, 0)})
    return jsonify({"st": "ok", "roster": out})


@app.route("/api/tower/character/levelup", methods=["POST"])
@require_auth_toggleable
def api_tower_char_levelup():
    body = request.get_json(force=True, silent=True) or {}
    char_id = body.get("char_id", "")
    times = int(body.get("times", 1))
    ok, msg, stats = tower_char_level_up(P["uid"], char_id, times)
    return jsonify({"st": "ok" if ok else "error", "msg": msg, "character": stats,
                     "credits": P["credits"]}), (200 if ok else 400)


@app.route("/api/tower/character/levelup_gold", methods=["POST"])
@require_auth_toggleable
def api_tower_char_levelup_gold():
    """body: {char_id, times} -> อัพเลเวลด้วย gold_coin จากกระเป๋าเป้"""
    body = request.get_json(force=True, silent=True) or {}
    ok, msg, stats = tower_char_level_up_gold(P["uid"], body.get("char_id", ""), int(body.get("times", 1)))
    return jsonify({"st": "ok" if ok else "error", "msg": msg, "character": stats,
                     "gold_coin": _tower_gold_have(P["uid"])}), (200 if ok else 400)


@app.route("/api/tower/character/skill_unlock_gold", methods=["POST"])
@require_auth_toggleable
def api_tower_char_skill_unlock_gold():
    """body: {char_id, skill_id} -> ปลดสกิลด้วย gold_coin (เลเวลต้องถึงก่อน)"""
    body = request.get_json(force=True, silent=True) or {}
    ok, msg, stats = tower_char_skill_unlock_gold(P["uid"], body.get("char_id", ""), body.get("skill_id", ""))
    return jsonify({"st": "ok" if ok else "error", "msg": msg, "character": stats,
                     "gold_coin": _tower_gold_have(P["uid"])}), (200 if ok else 400)


@app.route("/api/tower/character/starup_gold", methods=["POST"])
@require_auth_toggleable
def api_tower_char_starup_gold():
    """body: {char_id} -> อัพดาวด้วยเศษที่มี + gold_coin ชดเชยส่วนที่ขาด"""
    body = request.get_json(force=True, silent=True) or {}
    ok, msg, stats = tower_char_star_up_gold(P["uid"], body.get("char_id", ""))
