# ==========================================
# [ 6z. Lucky Bird Nest — shooting mini-game with gacha-style rarity/pity ]
# สเปค (ต่อจาก session ก่อนหน้าที่ทำค้างไว้): มินิเกมแนว "ยิงเก็บของ" — จ่ายเครดิต
# เริ่มรอบ, มีนกบินผ่านจอเป็นชุด (spawn ฝั่ง server พร้อม id + เวลาหมดอายุ), ยิงโดน
# นกตัวไหน = 1 การสุ่มรางวัลจาก "รังนกนำโชค" ทันที — ใช้ระบบ rarity 6 ระดับ + soft/hard
# pity แบบเดียวกับ gacha_pull() ด้านบน (คนละ state/คนละพูลไอเทม แยกจากกาชาหลัก
# เพื่อไม่ให้ pity counter ปนกัน) ยิงพลาด/นกบินหลุดจอ = เสียโอกาสนั้นไปเฉยๆ ไม่ได้คืนเครดิต
# ==========================================
BIRDNEST_COST_PER_ROUND = 80      # credits ต่อรอบ
BIRDNEST_BIRDS_PER_ROUND = 6      # จำนวนนกต่อรอบ
BIRDNEST_BIRD_LIFETIME_SEC = 2.6  # เวลาที่นกแต่ละตัวอยู่บนจอก่อนบินหลุด (server-authoritative)
BIRDNEST_ROUND_SPAWN_GAP_SEC = 0.55  # ระยะห่างเวลาระหว่างนกแต่ละตัวปรากฏ

BIRDNEST_RARITIES = ["common", "uncommon", "rare", "epic", "legendary", "mythic"]

BIRDNEST_BASE_RATES = {
    "common":    0.5000,
    "uncommon":  0.2700,
    "rare":      0.1300,
    "epic":      0.0600,
    "legendary": 0.0300,
    "mythic":    0.0100,
}

BIRDNEST_BANNER = {
    "id": "lucky_bird_nest",
    "name": "🐦 รังนกนำโชค",
    "featured": {"mythic": "ไข่ฟีนิกซ์เพลิงทอง", "legendary": "ขนนกอินทรีสายฟ้า"},
    "pool": {
        "common":    ["ขนนกกระจอกสีเทา", "รังฟางเก่า", "เศษเปลือกไข่"],
        "uncommon":  ["ขนนกพิราบมุก", "รังกิ่งไม้ถัก", "ไข่นกฟ้าจาง"],
        "rare":      ["ขนนกยูงคราม", "รังเงินระยิบ", "ไข่มรกตลาย"],
        "epic":      ["ขนนกหงส์ขาว", "รังทองคำเปลว", "ไข่อำพันเรืองแสง"],
        "legendary": ["ขนนกอินทรีสายฟ้า", "รังคริสตัลสายรุ้ง"],
        "mythic":    ["ไข่ฟีนิกซ์เพลิงทอง", "รังดาวตกนิรันดร์"],
    },
}

BIRDNEST_PITY_SOFT_START = 40
BIRDNEST_PITY_HARD_MYTHIC = 60

# uid -> {"pity": int, "guaranteed_featured": bool, "total_shots": int, "hits": int, "history": [...]}
BIRDNEST_PLAYER_STATE = {}
# uid -> {item_name: qty}
BIRDNEST_INVENTORY = {}
# uid -> {"round_id", "birds": {bird_id: {"spawn_at","expires_at","resolved"}}, "started_at", "cost_paid"}
BIRDNEST_ACTIVE_ROUND = {}


def _birdnest_state(uid: str) -> dict:
    return BIRDNEST_PLAYER_STATE.setdefault(
        uid, {"pity": 0, "guaranteed_featured": False, "total_shots": 0, "hits": 0, "history": []})


def _birdnest_effective_rates(pity: int) -> dict:
    """Soft pity เหมือน gacha หลัก แต่ ramp เร็วกว่า (ช่วงยิงสั้นกว่าดึงกาชา) —
    ดึงโอกาสส่วนเกินออกจาก common เพื่อให้ tier อื่นสัดส่วนคงเดิม"""
    rates = dict(BIRDNEST_BASE_RATES)
    if pity >= BIRDNEST_PITY_SOFT_START:
        progress = min(1.0, (pity - BIRDNEST_PITY_SOFT_START) /
                       max(1, BIRDNEST_PITY_HARD_MYTHIC - BIRDNEST_PITY_SOFT_START))
        boost = 0.30 * progress
        boost = min(boost, rates["common"])
        rates["mythic"] += boost
        rates["common"] -= boost
    return rates


def _birdnest_roll_rarity(rates: dict) -> str:
    roll = random.random()
    cum = 0.0
    for rarity in BIRDNEST_RARITIES:
        cum += rates[rarity]
        if roll <= cum:
            return rarity
    return BIRDNEST_RARITIES[-1]


def _birdnest_pick_item(rarity: str, state: dict) -> str:
    featured = BIRDNEST_BANNER["featured"].get(rarity)
    pool = BIRDNEST_BANNER["pool"][rarity]
    if not featured:
        return random.choice(pool)
    if state["guaranteed_featured"]:
        state["guaranteed_featured"] = False
        return featured
    if random.random() < 0.5:
        return featured
    else:
        state["guaranteed_featured"] = True
        others = [i for i in pool if i != featured] or [featured]
        return random.choice(others)


def birdnest_pity_status(uid: str) -> dict:
    state = _birdnest_state(uid)
    return {
        "pity": state["pity"],
        "hard_pity_at": BIRDNEST_PITY_HARD_MYTHIC,
        "soft_pity_starts_at": BIRDNEST_PITY_SOFT_START,
        "guaranteed_featured_next": state["guaranteed_featured"],
        "total_shots": state["total_shots"],
        "hits": state["hits"],
    }


def birdnest_start_round(uid: str) -> tuple[bool, str, dict]:
    """จ่ายเครดิต, สุ่มตำแหน่ง/เวลา spawn ของนกทั้งชุดล่วงหน้าฝั่ง server แล้วส่งกลับให้
    client เอาไปวาดแอนิเมชัน — server เป็นคนตัดสิน hit/expire จริงตอน /shoot"""
    if uid in BIRDNEST_ACTIVE_ROUND:
        return False, "รอบก่อนหน้ายังไม่จบ", {}
    if P["credits"] < BIRDNEST_COST_PER_ROUND:
        return False, "เครดิตไม่พอ", {}

    P["credits"] -= BIRDNEST_COST_PER_ROUND
    now = time.time()
    round_id = uuid.uuid4().hex[:12]
    birds = {}
    bird_specs = []
    for i in range(BIRDNEST_BIRDS_PER_ROUND):
        bird_id = f"{round_id}-{i}"
        spawn_at = now + i * BIRDNEST_ROUND_SPAWN_GAP_SEC
        expires_at = spawn_at + BIRDNEST_BIRD_LIFETIME_SEC
        # เส้นทางบิน: สุ่มจุดเริ่ม/จุดจบแนวนอน + ความสูงเป็น % ของ canvas ให้ client คำนวณตำแหน่งเอง
        path = {"y_pct": round(random.uniform(0.12, 0.75), 3),
                "x_from_pct": 0.0 if i % 2 == 0 else 1.0,
                "x_to_pct": 1.0 if i % 2 == 0 else 0.0}
        birds[bird_id] = {"spawn_at": spawn_at, "expires_at": expires_at, "resolved": False}
        bird_specs.append({"id": bird_id, "spawn_at": spawn_at, "expires_at": expires_at, **path})

    BIRDNEST_ACTIVE_ROUND[uid] = {"round_id": round_id, "birds": birds, "started_at": now}
    return True, "ok", {"round_id": round_id, "birds": bird_specs,
                         "lifetime_sec": BIRDNEST_BIRD_LIFETIME_SEC, "credits": P["credits"]}


def birdnest_shoot(uid: str, bird_id: str) -> tuple[bool, str, dict]:
    """ยิงนกตัวหนึ่งในรอบปัจจุบัน — ถ้ายิงทันเวลา (ก่อน expires_at) นับเป็น hit และสุ่ม
    รางวัล 1 ครั้งจากระบบ pity ทันที ถ้าสายไปแล้ว/ยิงซ้ำตัวเดิม/ไม่มีรอบ active คืนพลาด"""
    round_ = BIRDNEST_ACTIVE_ROUND.get(uid)
    if not round_:
        return False, "ไม่มีรอบที่กำลังเล่นอยู่", {}
    bird = round_["birds"].get(bird_id)
    if not bird:
        return False, "ไม่พบนกตัวนี้ในรอบนี้", {}
    if bird["resolved"]:
        return False, "นกตัวนี้ถูกยิง/หมดเวลาไปแล้ว", {}

    now = time.time()
    bird["resolved"] = True
    state = _birdnest_state(uid)
    state["total_shots"] += 1

    if now > bird["expires_at"]:
        round_done = all(b["resolved"] for b in round_["birds"].values())
        if round_done:
            del BIRDNEST_ACTIVE_ROUND[uid]
        return True, "พลาด — นกบินหลุดจอไปแล้ว", {"hit": False, "round_done": round_done}

    # hit — สุ่มรางวัล 1 ครั้งด้วยระบบ pity เดียวกับกาชาหลัก
    state["pity"] += 1
    state["hits"] += 1
    rates = _birdnest_effective_rates(state["pity"])
    rarity = _birdnest_roll_rarity(rates)
    if state["pity"] >= BIRDNEST_PITY_HARD_MYTHIC:
        rarity = "mythic"
    if rarity == "mythic":
        state["pity"] = 0

    item = _birdnest_pick_item(rarity, state)
    inv = BIRDNEST_INVENTORY.setdefault(uid, {})
    inv[item] = inv.get(item, 0) + 1
    state["history"].append({"rarity": rarity, "item": item})
    state["history"] = state["history"][-100:]

    round_done = all(b["resolved"] for b in round_["birds"].values())
    if round_done:
        del BIRDNEST_ACTIVE_ROUND[uid]

    return True, "ยิงโดน! 🎯", {"hit": True, "rarity": rarity, "item": item, "round_done": round_done,
                                 "pity": birdnest_pity_status(uid)}


