@app.route('/api/birdnest/shoot', methods=['POST'])
@require_auth_toggleable
def api_birdnest_shoot():
    body = request.get_json(force=True, silent=True) or {}
    bird_id = body.get("bird_id", "")
    ok, msg, result = birdnest_shoot(P["uid"], bird_id)
    return jsonify({"ok": ok, "msg": msg, "result": result})


