# ==========================================
# [ 6z8. Silver Palace module (การ์ดดวลแต้มในวังเงิน) ]
# มินิเกมการ์ดต้นฉบับ (mechanics คิดเองทั้งหมด ไม่ได้ก็อปโค้ด/asset จากเกมเชิงพาณิชย์ใดๆ —
# เทียบเจตนากับ mahjong_scoreboard/lucky_bird_nest ด้านบน: self-contained, แต้ม/ไอเทมในเกม
# ล้วนๆ ไม่ใช่เงินจริง): ผู้เล่นดวลแต้มไพ่มาตรฐาน 52 ใบกับคู่ปรับ AI หลายรอบต่อเซสชัน
# ทิ้งไพ่ได้จำกัดครั้งก่อนล็อกมือ ชนะเซสชันได้ Wax Seal + สุ่ม "confidant" การ์ดสะสม
# ด้วยระบบ rarity แบบเดียวกับโมดูลอื่นในไฟล์นี้ (common..mythic)
# ==========================================

SILVERPALACE_COST_PER_SESSION = 60      # เครดิตต่อเซสชัน
SILVERPALACE_ROUNDS_PER_SESSION = 6     # จำนวนรอบต่อเซสชัน (ตัดสินผู้ชนะจากยอดชนะรอบสะสม)
SILVERPALACE_HAND_SIZE = 5              # จำนวนไพ่ในมือต่อรอบ
SILVERPALACE_DISCARDS_PER_ROUND = 2     # จำนวนครั้งที่ทิ้ง/จั่วใหม่ได้ต่อรอบ

SILVERPALACE_SUITS = ["♠", "♥", "♦", "♣"]
SILVERPALACE_RANK_LABEL = {11: "J", 12: "Q", 13: "K", 14: "A"}

SILVERPALACE_RARITIES = ["common", "uncommon", "rare", "epic", "legendary", "mythic"]
SILVERPALACE_RARITY_RATES = {
    "common": 0.45, "uncommon": 0.27, "rare": 0.15, "epic": 0.08, "legendary": 0.04, "mythic": 0.01,
}
SILVERPALACE_CONFIDANT_POOL = {
    "common":    ["สุภาพบุรุษพนักงานเสิร์ฟ", "นักเรียนฝึกหัดมารยาท", "คนเฝ้าประตูวัง"],
    "uncommon":  ["นักดนตรีประจำห้องโถง", "บรรณารักษ์ปริศนา", "พ่อค้าไพ่เร่ร่อน"],
    "rare":      ["นักสืบสวมหน้ากาก", "ขุนนางหนุ่มไฟแรง", "นักมายากลกลางคืน"],
    "epic":      ["เคาน์เตสแห่งสวนกุหลาบ", "นายพลเกษียณจอมเจ้าเล่ห์", "นักบวชผู้พลิกโชค"],
    "legendary": ["เจ้าหญิงผู้ปฏิเสธมงกุฎ", "นักฆ่าผู้ผันตัวเป็นบัตเลอร์"],
    "mythic":    ["เจ้าแห่งวังเงินตัวจริง"],
}

# uid -> {"wax_seals": int, "wins": int, "losses": int}
SILVERPALACE_PLAYER_STATE = {}
# uid -> {item_name: qty}
SILVERPALACE_CONFIDANTS = {}
# uid -> active session dict (see silverpalace_start_session)
SILVERPALACE_ACTIVE_SESSION = {}


def _silverpalace_state(uid: str) -> dict:
    return SILVERPALACE_PLAYER_STATE.setdefault(uid, {"wax_seals": 0, "wins": 0, "losses": 0})


def _silverpalace_new_deck() -> list:
    deck = []
    for suit in SILVERPALACE_SUITS:
        for rank in range(2, 15):
            deck.append({"id": uuid.uuid4().hex[:8], "rank": rank, "suit": suit,
                         "label": f"{SILVERPALACE_RANK_LABEL.get(rank, str(rank))}{suit}"})
    random.shuffle(deck)
    return deck


def _silverpalace_draw(session: dict, n: int) -> list:
    drawn = []
    for _ in range(n):
        if not session["deck"]:
            session["deck"] = _silverpalace_new_deck()  # หมดสำรับ — สับสำรับใหม่ (ไม่ใช้ discard pile คืน กันนับไพ่)
        drawn.append(session["deck"].pop())
    return drawn


def _silverpalace_deal_round(session: dict):
    session["hand"] = _silverpalace_draw(session, SILVERPALACE_HAND_SIZE)
    session["opponent_hand"] = _silverpalace_draw(session, SILVERPALACE_HAND_SIZE)
    session["discards_left"] = SILVERPALACE_DISCARDS_PER_ROUND
    session["locked"] = False


def _silverpalace_opponent_ai_adjust(session: dict):
    """คู่ปรับ AI สลับไพ่แต้มต่ำ (<=6) ทิ้งบางส่วนก่อนล็อกมือ ให้พอมีความท้าทาย ไม่ใช่สุ่มนิ่งๆ"""
    hand = session["opponent_hand"]
    low_cards = [c for c in hand if c["rank"] <= 6]
    swap_n = min(len(low_cards), random.randint(0, 2))
    for c in random.sample(low_cards, swap_n) if swap_n else []:
        hand.remove(c)
        hand.extend(_silverpalace_draw(session, 1))


def _silverpalace_public_hand(hand: list) -> list:
    return [{"id": c["id"], "rank": c["rank"], "suit": c["suit"], "label": c["label"]} for c in hand]


def silverpalace_status(uid: str) -> dict:
    st = _silverpalace_state(uid)
    session = SILVERPALACE_ACTIVE_SESSION.get(uid)
    return {
        "credits": P["credits"], "wax_seals": st["wax_seals"], "wins": st["wins"], "losses": st["losses"],
        "session_active": session is not None,
        "round": session["round"] if session else 0,
        "rounds_total": SILVERPALACE_ROUNDS_PER_SESSION,
        "player_score": session["player_score"] if session else 0,
        "opponent_score": session["opponent_score"] if session else 0,
    }


def silverpalace_start_session(uid: str) -> tuple[bool, str, dict]:
    if uid in SILVERPALACE_ACTIVE_SESSION:
        return False, "เซสชันก่อนหน้ายังไม่จบ", {}
    if P["credits"] < SILVERPALACE_COST_PER_SESSION:
        return False, "เครดิตไม่พอ", {}

    P["credits"] -= SILVERPALACE_COST_PER_SESSION
    session = {"deck": _silverpalace_new_deck(), "round": 1, "player_score": 0, "opponent_score": 0,
               "hand": [], "opponent_hand": [], "discards_left": SILVERPALACE_DISCARDS_PER_ROUND, "locked": False}
    _silverpalace_deal_round(session)
    SILVERPALACE_ACTIVE_SESSION[uid] = session
    return True, "ok", {"round": session["round"], "rounds_total": SILVERPALACE_ROUNDS_PER_SESSION,
                         "hand": _silverpalace_public_hand(session["hand"]),
                         "discards_left": session["discards_left"], "credits": P["credits"]}


def silverpalace_discard(uid: str, card_id: str) -> tuple[bool, str, dict]:
    session = SILVERPALACE_ACTIVE_SESSION.get(uid)
    if not session:
        return False, "ไม่มีเซสชันที่กำลังเล่นอยู่", {}
    if session["locked"]:
        return False, "มือนี้ล็อกไปแล้ว", {}
    if session["discards_left"] <= 0:
        return False, "ทิ้งไพ่ครบโควตารอบนี้แล้ว", {}
    card = next((c for c in session["hand"] if c["id"] == card_id), None)
    if not card:
        return False, "ไม่พบไพ่ใบนี้ในมือ", {}

    session["hand"].remove(card)
    session["hand"].extend(_silverpalace_draw(session, 1))
    session["discards_left"] -= 1
    return True, "ok", {"hand": _silverpalace_public_hand(session["hand"]),
                         "discards_left": session["discards_left"]}


def silverpalace_play_round(uid: str) -> tuple[bool, str, dict]:
    session = SILVERPALACE_ACTIVE_SESSION.get(uid)
    if not session:
        return False, "ไม่มีเซสชันที่กำลังเล่นอยู่", {}
    if session["locked"]:
        return False, "มือนี้ล็อกไปแล้ว", {}

    session["locked"] = True
    _silverpalace_opponent_ai_adjust(session)

    player_total = sum(c["rank"] for c in session["hand"])
    opponent_total = sum(c["rank"] for c in session["opponent_hand"])
    if player_total > opponent_total:
        round_result = "win"
        session["player_score"] += 1
    elif player_total < opponent_total:
        round_result = "lose"
        session["opponent_score"] += 1
    else:
        round_result = "tie"

    result = {
        "round": session["round"], "rounds_total": SILVERPALACE_ROUNDS_PER_SESSION,
        "player_hand": _silverpalace_public_hand(session["hand"]),
        "opponent_hand": _silverpalace_public_hand(session["opponent_hand"]),
        "player_total": player_total, "opponent_total": opponent_total,
        "round_result": round_result,
        "player_score": session["player_score"], "opponent_score": session["opponent_score"],
        "session_done": False,
    }

    if session["round"] >= SILVERPALACE_ROUNDS_PER_SESSION:
        result["session_done"] = True
        st = _silverpalace_state(uid)
        if session["player_score"] > session["opponent_score"]:
            session_won = True
            st["wins"] += 1
            wax_gain = 25
        elif session["player_score"] < session["opponent_score"]:
            session_won = False
            st["losses"] += 1
            wax_gain = 8
        else:
            session_won = None
            wax_gain = 15
        st["wax_seals"] += wax_gain
        result["session_won"] = session_won
        result["wax_seals_gained"] = wax_gain
        result["wax_seals_total"] = st["wax_seals"]

        # ชนะเซสชันเท่านั้นถึงจะได้สุ่ม confidant 1 ครั้ง (แพ้/เสมอได้แค่ wax seal ปลอบใจ)
        if session_won:
            roll = random.random()
            cum = 0.0
            rarity = SILVERPALACE_RARITIES[-1]
            for r in SILVERPALACE_RARITIES:
                cum += SILVERPALACE_RARITY_RATES[r]
                if roll <= cum:
                    rarity = r
                    break
            item = random.choice(SILVERPALACE_CONFIDANT_POOL[rarity])
            inv = SILVERPALACE_CONFIDANTS.setdefault(uid, {})
            inv[item] = inv.get(item, 0) + 1
            result["confidant_won"] = {"rarity": rarity, "item": item}

        del SILVERPALACE_ACTIVE_SESSION[uid]
    else:
        session["round"] += 1
        _silverpalace_deal_round(session)
        result["next_hand"] = _silverpalace_public_hand(session["hand"])
        result["next_discards_left"] = session["discards_left"]

    return True, "ok", result


