# ==========================================
# [ 6zz4. Social Feed Hub — หน้าโพสต์โปรโมทสไตล์ฟีดโซเชียล (อ้างอิงสกรีนที่ส่งมา) ]
# ใช้ได้กับ "เกมแนวกลยุทธ์/แอคชัน" ทุกเกมในระบบนี้ (game_id ไหนก็ได้ ทั้งที่อยู่ใน
# LAUNCHER_CATALOG อยู่แล้วอย่าง vmax/iron_fist และโมดูลอื่นๆ ในไฟล์นี้) —
# ยกเว้นเกมไพ่ (mahjong_scoreboard, silver_palace) เพราะดีไซน์หน้านี้ (แบนเนอร์
# โปรโมทสไตล์อีเวนต์/LIVE/แอคชัน) ออกแบบมาสำหรับเกมแนวยิง/ต่อสู้/กลยุทธ์ ไม่ใช่
# เกมไพ่ — กันไว้ตั้งแต่ระดับ backend เลย ไม่ใช่แค่ซ่อนปุ่มฝั่ง UI
#
# โครงหน้าจอ (ตามสกรีนตัวอย่าง):
#   แถบบน (LIVE / เพื่อน / กำลังติดตาม / สำหรับคุณ / ค้นหา) -> ป้ายแบนเนอร์อีเวนต์
#   ในกรอบโปสเตอร์ พร้อมชิประยะเวลา -> คอลัมน์ไอคอนฝั่งขวา (ถูกใจ/คอมเมนต์/
#   บุ๊กมาร์ก/แชร์ พร้อมตัวเลข) -> จุดไล่ภาพ (ถ้ามีหลายแบนเนอร์) -> แคปชันผู้โพสต์
#   พร้อมเครื่องหมายยืนยัน -> แถบเมนูล่าง (หน้าหลัก/ร้านค้า/สร้างโพสต์/กล่องข้อความ/
#   โปรไฟล์)
# ==========================================

FEED_DB_PATH = os.environ.get("FEED_DB_PATH", "social_feed.db")

# เกมไพ่ที่ไม่รองรับดีไซน์หน้านี้ — เพิ่ม game_id เกมไพ่ตัวใหม่ในอนาคตต่อท้าย set นี้ได้เลย
CARD_GAME_MODULE_IDS = {"mahjong_scoreboard", "silver_palace"}

# --- [4 จุดแก้] สถานะการตรวจสอบโพสต์ + threshold ตัดสินว่าต้องเข้าคิวรอแอดมิน ---------------
FEED_STATUS_APPROVED = "approved"          # ผ่านอัตโนมัติ โชว์ในฟีดสาธารณะได้เลย (ค่าเริ่มต้น)
FEED_STATUS_PENDING = "pending_review"     # confidence สูงมาก -> รอแอดมินอนุมัติก่อน ยังไม่โชว์
FEED_STATUS_REJECTED = "rejected"          # แอดมินปฏิเสธแล้ว ไม่โชว์ถาวร
# confidence (0..1) จากตัวเช็คลิขสิทธิ์ที่สูงเกินนี้ -> โพสต์เข้าคิว pending_review อัตโนมัติ
FEED_REVIEW_CONFIDENCE_THRESHOLD = float(os.environ.get("FEED_REVIEW_CONFIDENCE_THRESHOLD", "0.85"))


def _feed_db():
    conn = sqlite3.connect(FEED_DB_PATH)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS feed_posts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            game_id TEXT NOT NULL,
            author TEXT NOT NULL,
            verified INTEGER NOT NULL DEFAULT 1,
            pinned INTEGER NOT NULL DEFAULT 0,
            live INTEGER NOT NULL DEFAULT 0,
            caption TEXT NOT NULL DEFAULT '',
            event_start TEXT NOT NULL DEFAULT '',
            event_end TEXT NOT NULL DEFAULT '',
            tags_json TEXT NOT NULL DEFAULT '[]',
            banners_json TEXT NOT NULL DEFAULT '[]',
            likes INTEGER NOT NULL DEFAULT 0,
            comments_count INTEGER NOT NULL DEFAULT 0,
            shares INTEGER NOT NULL DEFAULT 0,
            bookmarks INTEGER NOT NULL DEFAULT 0,
            review_status TEXT NOT NULL DEFAULT 'approved',
            review_meta_json TEXT NOT NULL DEFAULT '{}',
            created_at TEXT NOT NULL
        )
    """)
    # [4 จุดแก้ #1] migration สำหรับ DB เก่าที่สร้างตาราง feed_posts ไปแล้วก่อนมีสองคอลัมน์นี้ —
    # CREATE TABLE IF NOT EXISTS ด้านบนจะไม่เพิ่มคอลัมน์ให้ตารางที่มีอยู่แล้ว ต้อง ALTER TABLE
    # เสริมเอง ถ้าคอลัมน์มีอยู่แล้ว (DB ใหม่ที่เพิ่งสร้างตามสคีมาด้านบน) SQLite จะโยน
    # OperationalError "duplicate column name" ซึ่ง ignore ได้เลย ไม่ใช่ error จริง
    for _col_def in ("review_status TEXT NOT NULL DEFAULT 'approved'",
                     "review_meta_json TEXT NOT NULL DEFAULT '{}'"):
        try:
            conn.execute(f"ALTER TABLE feed_posts ADD COLUMN {_col_def}")
        except sqlite3.OperationalError:
            pass  # คอลัมน์นี้มีอยู่แล้ว
    conn.execute("""
        CREATE TABLE IF NOT EXISTS feed_comments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            post_id INTEGER NOT NULL,
            author TEXT NOT NULL,
            text TEXT NOT NULL,
            created_at TEXT NOT NULL
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS feed_likes (
            post_id INTEGER NOT NULL,
            uid TEXT NOT NULL,
            PRIMARY KEY (post_id, uid)
        )
    """)
    return conn


def feed_check_game_allowed(game_id: str) -> tuple[bool, str]:
    """เช็คว่า game_id นี้ใช้ระบบฟีดโปรโมทนี้ได้ไหม — บล็อกเกมไพ่ตั้งแต่ backend
    (ไม่ใช่แค่ซ่อนปุ่มฝั่งหน้าเว็บ) ส่วนเกมอื่นๆ (ทั้งที่ลงทะเบียนใน LAUNCHER_CATALOG
    แล้วหรือ game_id ใหม่ของโมดูลกลยุทธ์/แอคชันอื่นในไฟล์นี้) ผ่านหมด"""
    if game_id in CARD_GAME_MODULE_IDS:
        return False, ("ระบบฟีดโปรโมทสไตล์นี้ (แบนเนอร์อีเวนต์/LIVE) ออกแบบมาสำหรับเกมแนวยิง/"
                       "ต่อสู้/กลยุทธ์เท่านั้น — ไม่รองรับเกมไพ่ (game_id นี้ถูกจัดเป็นเกมไพ่)")
    genre = LAUNCHER_CATALOG.get(game_id, {}).get("genre", "")
    if genre in ("card", "card_game", "mahjong"):
        return False, "ระบบฟีดโปรโมทนี้ไม่รองรับเกมแนวไพ่ (genre ของเกมนี้ถูกจัดเป็นเกมไพ่)"
    return True, ""


def feed_create_post(game_id, author, caption, banner_paths, event_start="", event_end="",
                     live=False, pinned=False, tags=None, verified=True,
                     status=FEED_STATUS_APPROVED, review_meta=None):
    """[4 จุดแก้ #2] เพิ่มพารามิเตอร์ status/review_meta — ผู้เรียก (api_feed_create_post) เป็นคน
    ตัดสินใจสถานะเริ่มต้นจาก confidence ของผลเช็คลิขสิทธิ์แบนเนอร์ แล้วส่งเข้ามาที่นี่ ฟังก์ชันนี้
    แค่บันทึกตามที่บอก ไม่ได้ตัดสินใจเอง (ค่าเริ่มต้นยังคงเป็น approved เหมือนพฤติกรรมเดิมถ้าไม่
    ส่ง status มา — ไม่กระทบผู้เรียกเดิมที่ยังไม่รู้จักพารามิเตอร์นี้)"""
    ok, msg = feed_check_game_allowed(game_id)
    if not ok:
        raise ValueError(msg)
    if status not in (FEED_STATUS_APPROVED, FEED_STATUS_PENDING, FEED_STATUS_REJECTED):
        raise ValueError(f"status ไม่ถูกต้อง: {status}")
    conn = _feed_db()
    try:
        cur = conn.execute(
            "INSERT INTO feed_posts (game_id, author, verified, pinned, live, caption, event_start, "
            "event_end, tags_json, banners_json, review_status, review_meta_json, created_at) "
            "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (game_id, author, int(verified), int(pinned), int(live), caption, event_start, event_end,
             json.dumps(tags or []), json.dumps(banner_paths), status, json.dumps(review_meta or {}),
             datetime.utcnow().isoformat()),
        )
        conn.commit()
        return cur.lastrowid
    finally:
        conn.close()


def _feed_row_to_dict(row):
    """[4 จุดแก้ #3] เพิ่ม review_status/review_meta ในผลลัพธ์ที่ส่งกลับให้ครบ — ผู้โพสต์เห็นสถานะ
    โพสต์ตัวเอง (เช่น "รอแอดมินตรวจสอบ") และหน้าแอดมินเห็น review_meta (confidence, เหตุผลอัตโนมัติ,
    บันทึกการอนุมัติ/ปฏิเสธ) โดยไม่ต้องยิง query เพิ่ม"""
    return {
        "id": row[0], "game_id": row[1], "author": row[2], "verified": bool(row[3]),
        "pinned": bool(row[4]), "live": bool(row[5]), "caption": row[6],
        "event_start": row[7], "event_end": row[8], "tags": json.loads(row[9] or "[]"),
        "banners": json.loads(row[10] or "[]"), "likes": row[11], "comments_count": row[12],
        "shares": row[13], "bookmarks": row[14],
        "review_status": row[15], "review_meta": json.loads(row[16] or "{}"),
        "created_at": row[17],
    }


_FEED_SELECT_COLS = (
    "id, game_id, author, verified, pinned, live, caption, event_start, event_end, "
    "tags_json, banners_json, likes, comments_count, shares, bookmarks, review_status, "
    "review_meta_json, created_at"
)


def feed_list(game_id, limit=20, include_pending=False):
    """[4 จุดแก้ #3] ค่าเริ่มต้น (include_pending=False) กรองโพสต์สถานะ pending_review และ
    rejected ออกจากฟีดสาธารณะ — โชว์เฉพาะ review_status='approved' หน้าแอดมิน (คิวรอตรวจ) เรียก
    ด้วย include_pending=True เพื่อเห็นทุกสถานะรวม pending_review/rejected ด้วย"""
    ok, msg = feed_check_game_allowed(game_id)
    if not ok:
        return ok, msg, []
    conn = _feed_db()
    try:
        query = f"SELECT {_FEED_SELECT_COLS} FROM feed_posts WHERE game_id=?"
        params = [game_id]
        if not include_pending:
            query += " AND review_status=?"
            params.append(FEED_STATUS_APPROVED)
        query += " ORDER BY pinned DESC, id DESC LIMIT ?"
        params.append(limit)
        rows = conn.execute(query, params).fetchall()
        return True, "", [_feed_row_to_dict(r) for r in rows]
    finally:
        conn.close()


def feed_get_post(post_id):
    """คืนโพสต์ตาม id ไม่กรองตาม review_status (ใช้โดย like/comment/share/bookmark และหน้า
    แอดมินที่ต้องเห็นโพสต์ pending_review/rejected ได้ด้วย ไม่ใช่แค่ approved)"""
    conn = _feed_db()
    try:
        row = conn.execute(
            f"SELECT {_FEED_SELECT_COLS} FROM feed_posts WHERE id=?", (post_id,)
        ).fetchone()
        return _feed_row_to_dict(row) if row else None
    finally:
        conn.close()


def feed_set_review_status(post_id, status, staff_uid="", note=""):
    """[4 จุดแก้ #4] แอดมิน/โมเดอเรเตอร์อนุมัติหรือปฏิเสธโพสต์ที่ค้างอยู่ — จำกัดให้ตั้งได้แค่
    approved/rejected เท่านั้น (ตั้งกลับเป็น pending_review เองไม่ได้ เพราะสถานะนั้นมาจากการเช็ค
    ลิขสิทธิ์อัตโนมัติตอนสร้างโพสต์เท่านั้น ไม่ใช่การตัดสินใจของคน) บันทึกผู้ตัดสิน/หมายเหตุ/เวลา
    ไว้ใน review_meta_json เป็น audit trail"""
    if status not in (FEED_STATUS_APPROVED, FEED_STATUS_REJECTED):
        raise ValueError("status ต้องเป็น 'approved' หรือ 'rejected' เท่านั้น")
    conn = _feed_db()
    try:
        row = conn.execute("SELECT review_meta_json FROM feed_posts WHERE id=?", (post_id,)).fetchone()
        if not row:
            return False
        meta = json.loads(row[0] or "{}")
        meta["admin_decision"] = status
        meta["admin_staff_uid"] = staff_uid
        meta["admin_note"] = note
        meta["admin_decided_at"] = datetime.utcnow().isoformat()
        conn.execute("UPDATE feed_posts SET review_status=?, review_meta_json=? WHERE id=?",
                     (status, json.dumps(meta), post_id))
        conn.commit()
        return True
    finally:
        conn.close()


def feed_toggle_like(post_id, uid):
    """กดถูกใจ/เอาถูกใจออก แบบ toggle ต่อผู้เล่นหนึ่งคน (กันกดรัวเพิ่มยอดปลอม)"""
    conn = _feed_db()
    try:
        existing = conn.execute("SELECT 1 FROM feed_likes WHERE post_id=? AND uid=?", (post_id, uid)).fetchone()
        if existing:
            conn.execute("DELETE FROM feed_likes WHERE post_id=? AND uid=?", (post_id, uid))
            conn.execute("UPDATE feed_posts SET likes = MAX(0, likes - 1) WHERE id=?", (post_id,))
            liked_now = False
        else:
            conn.execute("INSERT INTO feed_likes (post_id, uid) VALUES (?, ?)", (post_id, uid))
            conn.execute("UPDATE feed_posts SET likes = likes + 1 WHERE id=?", (post_id,))
            liked_now = True
        conn.commit()
        likes = conn.execute("SELECT likes FROM feed_posts WHERE id=?", (post_id,)).fetchone()
        return liked_now, (likes[0] if likes else 0)
    finally:
        conn.close()


def feed_bookmark(post_id):
    conn = _feed_db()
    try:
        conn.execute("UPDATE feed_posts SET bookmarks = bookmarks + 1 WHERE id=?", (post_id,))
        conn.commit()
        row = conn.execute("SELECT bookmarks FROM feed_posts WHERE id=?", (post_id,)).fetchone()
        return row[0] if row else 0
    finally:
        conn.close()


def feed_share(post_id):
    conn = _feed_db()
    try:
        conn.execute("UPDATE feed_posts SET shares = shares + 1 WHERE id=?", (post_id,))
        conn.commit()
        row = conn.execute("SELECT shares FROM feed_posts WHERE id=?", (post_id,)).fetchone()
        return row[0] if row else 0
    finally:
        conn.close()


def feed_add_comment(post_id, author, text):
    conn = _feed_db()
    try:
        conn.execute("INSERT INTO feed_comments (post_id, author, text, created_at) VALUES (?,?,?,?)",
                     (post_id, author, text, datetime.utcnow().isoformat()))
        conn.execute("UPDATE feed_posts SET comments_count = comments_count + 1 WHERE id=?", (post_id,))
        conn.commit()
        row = conn.execute("SELECT comments_count FROM feed_posts WHERE id=?", (post_id,)).fetchone()
        return row[0] if row else 0
    finally:
        conn.close()


def feed_list_comments(post_id, limit=50):
    conn = _feed_db()
    try:
        rows = conn.execute(
            "SELECT author, text, created_at FROM feed_comments WHERE post_id=? ORDER BY id ASC LIMIT ?",
            (post_id, limit),
        ).fetchall()
        return [{"author": r[0], "text": r[1], "created_at": r[2]} for r in rows]
    finally:
        conn.close()


FEED_BANNER_DIR = os.environ.get("FEED_BANNER_DIR", "feed_banners")
os.makedirs(FEED_BANNER_DIR, exist_ok=True)


def _feed_banner_max_confidence(banner_copyright_warnings):
    """[4 จุดแก้ #4] หา confidence สูงสุดจากผลเช็คลิขสิทธิ์ของทุกแบนเนอร์ในโพสต์เดียว —
    นับเฉพาะ roboflow (key 'confidence') และ google_vision match_type='web_entity' ที่มี
    'score' เท่านั้น (Google 'best_guess' ไม่มีตัวเลข confidence ตรงๆ ให้เทียบ threshold จึงไม่
    นับด่านนี้ ตามที่คุยกัน) คืน 0.0 ถ้าไม่มีตัวเลขให้เทียบเลย (fail-open เหมือนจุดอื่นในระบบนี้)"""
    best = 0.0
    for cw in banner_copyright_warnings:
        for m in cw.get("possible_matches", []):
            if m.get("source") == "roboflow" and "confidence" in m:
                best = max(best, m["confidence"])
            elif (m.get("source") == "google_vision" and m.get("match_type") == "web_entity"
                  and "score" in m):
                best = max(best, m["score"])
    return best


@app.route('/api/feed/<game_id>/post', methods=['POST'])
@require_auth_toggleable
def api_feed_create_post(game_id):
    """สร้างโพสต์โปรโมทใหม่สำหรับ game_id นี้ (multipart form):
    - banners: แนบรูปแบนเนอร์ได้หลายไฟล์ (field ซ้ำชื่อ banners)
    - caption, event_start, event_end, live(1/0), pinned(1/0), tags(คั่นด้วยจุลภาค)
    ถูกบล็อกถ้า game_id เป็นเกมไพ่ (ดู CARD_GAME_MODULE_IDS ด้านบน)
    [6q0a5] ทุกรูปแบนเนอร์ที่แนบมาจะถูกเช็คกับตัวเตือนลิขสิทธิ์ชุดเดียวกับ ai_draw (Roboflow +
    Google Vision + ฐานข้อมูลสะสม [6q0a2-a4]) ก่อนบันทึกโพสต์ — ไม่บล็อกการโพสต์ (fail-open
    เหมือนกัน) แค่แนบผล copyright_warnings กลับไปใน response ให้ผู้โพสต์/แอดมินเห็น"""
    ok, msg = feed_check_game_allowed(game_id)
    if not ok:
        return jsonify({"st": "error", "msg": msg}), 403

    files = request.files.getlist('banners')
    banner_paths = []
    banner_copyright_warnings = []
    for f in files:
        if not f or not f.filename:
            continue
        raw = f.read()
        f.stream.seek(0)
        fname = f"{uuid.uuid4().hex[:10]}_{secure_filename(f.filename)}"
        path = os.path.join(FEED_BANNER_DIR, fname)
        f.save(path)
        banner_paths.append(path)
        try:
            cw = _run_copyright_warning_check(raw, request.form.get('author', P["uid"]),
                                              f"feed/{game_id}/post", f.filename)
            if cw:
                cw["banner_filename"] = fname
                banner_copyright_warnings.append(cw)
        except Exception as _cw_e:
            print(f"[copyright-warning] เช็คแบนเนอร์ feed ไม่สำเร็จ (ไม่กระทบผลลัพธ์หลัก): {_cw_e}")

    body = request.form
    tags = [t.strip() for t in body.get('tags', '').split(',') if t.strip()]

    # [4 จุดแก้ #4] ตัดสินสถานะโพสต์จาก confidence สูงสุดที่เจอในแบนเนอร์ทั้งหมด — เกิน
    # FEED_REVIEW_CONFIDENCE_THRESHOLD (ค่าเริ่มต้น 85%) -> เข้าคิว pending_review ยังไม่โชว์ใน
    # ฟีดสาธารณะจนกว่าแอดมินจะอนุมัติ ต่ำกว่านั้น -> ผ่านอัตโนมัติเหมือนพฤติกรรมเดิม (ไม่บล็อกการ
    # โพสต์เอง แค่ยังไม่โชว์สาธารณะระหว่างรอตรวจ — คนละเรื่องกับการบล็อกทันที)
    max_conf = _feed_banner_max_confidence(banner_copyright_warnings)
    status = FEED_STATUS_PENDING if max_conf >= FEED_REVIEW_CONFIDENCE_THRESHOLD else FEED_STATUS_APPROVED
    review_meta = {"max_confidence": max_conf, "threshold": FEED_REVIEW_CONFIDENCE_THRESHOLD}
    if status == FEED_STATUS_PENDING:
        review_meta["auto_reason"] = (f"confidence สูงสุด {max_conf*100:.0f}% >= threshold "
                                      f"{FEED_REVIEW_CONFIDENCE_THRESHOLD*100:.0f}%")

    post_id = feed_create_post(
        game_id, author=body.get('author', P["uid"]), caption=body.get('caption', ''),
        banner_paths=banner_paths, event_start=body.get('event_start', ''),
        event_end=body.get('event_end', ''), live=body.get('live', '0') == '1',
        pinned=body.get('pinned', '0') == '1', tags=tags,
        status=status, review_meta=review_meta,
    )
    resp_payload = {"st": "ok", "post_id": post_id, "review_status": status}
    if banner_copyright_warnings:
        resp_payload["copyright_warnings"] = banner_copyright_warnings
    if status == FEED_STATUS_PENDING:
        resp_payload["msg"] = ("โพสต์ถูกสร้างแล้ว แต่ยังไม่แสดงในฟีดสาธารณะ — ตรวจพบว่าอาจตรงกับ"
                               "ตัวละครลิขสิทธิ์ด้วย confidence สูงมาก ต้องรอแอดมินตรวจสอบก่อน")
    return jsonify(resp_payload)


@app.route('/api/feed/<game_id>/list', methods=['GET'])
def api_feed_list(game_id):
    """query: limit (สูงสุด 100), staff_uid (ใส่เพื่อขอเห็นคิว pending_review/rejected ด้วย —
    ต้องมียศ >= moderator เท่านั้น ไม่งั้นจะเห็นแค่ approved เหมือนผู้ใช้ทั่วไป ไม่ error แค่เงียบๆ
    fallback กลับไปฟีดสาธารณะปกติ)"""
    limit = min(int(request.args.get('limit', 20)), 100)
    staff_uid = request.args.get('staff_uid', '')
    include_pending = _staff_rank_value(staff_uid) >= STAFF_RANKS["moderator"]
    ok, msg, items = feed_list(game_id, limit=limit, include_pending=include_pending)
    if not ok:
        return jsonify({"st": "error", "msg": msg}), 403
    return jsonify({"st": "ok", "items": items})


@app.route('/api/feed/<int:post_id>/review', methods=['POST'])
@require_auth_toggleable
def api_feed_review_post(post_id):
    """[4 จุดแก้ #4] Endpoint สำหรับแอดมิน/โมเดอเรเตอร์อนุมัติหรือปฏิเสธโพสต์ที่ค้างอยู่ในคิว
    pending_review — body: {staff_uid, decision: 'approved'|'rejected', note}
    ต้องมียศ >= moderator เท่านั้น (ใช้ระบบยศเดียวกับ /api/admin/panel ด้านบนของไฟล์)"""
    body = request.get_json(force=True, silent=True) or {}
    staff_uid = body.get('staff_uid', '')
    if _staff_rank_value(staff_uid) < STAFF_RANKS["moderator"]:
        return jsonify({"st": "error", "msg": "ต้องมียศ moderator ขึ้นไปเท่านั้นถึงจะตรวจโพสต์ได้"}), 403
    decision = body.get('decision', '')
    if decision not in (FEED_STATUS_APPROVED, FEED_STATUS_REJECTED):
        return jsonify({"st": "error", "msg": "decision ต้องเป็น 'approved' หรือ 'rejected' เท่านั้น"}), 400
    if not feed_get_post(post_id):
        return jsonify({"st": "error", "msg": "ไม่พบโพสต์นี้"}), 404
    ok = feed_set_review_status(post_id, decision, staff_uid=staff_uid, note=body.get('note', ''))
    if not ok:
        return jsonify({"st": "error", "msg": "ไม่พบโพสต์นี้"}), 404
    return jsonify({"st": "ok", "post": feed_get_post(post_id)})


@app.route('/api/feed/banner/<int:post_id>/<int:idx>', methods=['GET'])
def api_feed_get_banner(post_id, idx):
    post = feed_get_post(post_id)
    if not post or idx < 0 or idx >= len(post["banners"]):
        return jsonify({"st": "error", "msg": "ไม่พบแบนเนอร์นี้"}), 404
    path = post["banners"][idx]
    if not os.path.isfile(path):
        return jsonify({"st": "error", "msg": "ไฟล์แบนเนอร์หายไป"}), 404
    folder, fname = os.path.split(path)
    return send_from_directory(folder, fname)


