# room_id -> ห้องแข่งขันทั้งหมด (ในหน่วยความจำ — ห้องหายเมื่อ server รีสตาร์ท ตาม
# แนวทางเดียวกับ WARZONE_DYNAMIC_BOSS_STATE / KILLER_MODE_MATCHES ที่มีอยู่แล้วในไฟล์นี้)
XROOM_ROOMS = {}
XROOM_SID_ROOM = {}   # sid -> room_id ปัจจุบันที่ connection นี้อยู่


def _xroom_now_local():
    """เวลาของอีเวนต์ ใช้เวลาไทยเป็นหลัก เพื่อไม่ขึ้นกับ timezone ของเครื่องเซิร์ฟเวอร์"""
    if ZoneInfo is not None:
        return datetime.now(ZoneInfo(XROOM_EVENT_TZ))
    return datetime.now()


def _xroom_event_schedule_state(now=None):
    now = _xroom_now_local() if now is None else now
    start = now.replace(hour=XROOM_EVENT_OPEN_HOUR, minute=XROOM_EVENT_OPEN_MINUTE,
                        second=0, microsecond=0)
    close = now.replace(hour=XROOM_EVENT_CLOSE_HOUR, minute=XROOM_EVENT_CLOSE_MINUTE,
                        second=59, microsecond=999999)
    # 19:00-23:59 inclusive
    is_open = start <= now <= close
    return {
        "open": is_open,
        "timezone": XROOM_EVENT_TZ,
        "open_at": start.isoformat(),
        "close_at": close.isoformat(),
        "rounds": XROOM_ROUNDS_REQUIRED_DEFAULT,
        "round_time_sec": XROOM_ROUND_TIME_LIMIT_SEC,
    }


def _xroom_event_is_open():
    return bool(_xroom_event_schedule_state().get("open"))


def _xroom_grant_starter_items(room):
    """แจกเงินแข่งขัน + keycard 3 ใบตอนทีมเข้าแข่งขันครั้งแรกเท่านั้น"""
    for tno, team in room.get("teams", {}).items():
        if room.setdefault("starter_items_granted", {}).get(tno):
            continue
        uid = team.get("uid")
        if not uid:
            continue

        room.setdefault("competition_cash", {})[tno] = (
            room.setdefault("competition_cash", {}).get(tno, 0)
            + XROOM_STARTING_COMPETITION_CASH
        )

        # ใช้กระเป๋าเดิมของเกม ไม่สร้าง inventory ใหม่
        try:
            with BAG_LOCK:
                bag = _keycard_bag(uid)
                for card_type, qty in XROOM_STARTER_KEYCARDS.items():
                    item_id = f"keycard_{card_type}"
                    bag[item_id] = bag.get(item_id, 0) + int(qty)
        except Exception as e:
            # ถ้ากระเป๋าระบบเดิมยังไม่พร้อม อย่าให้ทั้งแมตช์ล้ม
            print(f"[xroom] starter keycard grant warning uid={uid}: {e}")

        room["starter_items_granted"][tno] = True
        sio.emit("xroom_starter_items_granted", {
            "room_id": room["room_id"],
            "team_no": tno,
            "competition_cash": XROOM_STARTING_COMPETITION_CASH,
            "keycards": dict(XROOM_STARTER_KEYCARDS),
        }, room=_xroom_room_name(room["room_id"]))


def _xroom_room_name(room_id: str) -> str:
    return f"xroom:{room_id}"


def _xroom_new_room_state(room_id: str, host_uid: str, rounds_required: int = None):
    return {
        "room_id": room_id,
        "host_uid": host_uid,
        "phase": "map_vote",   # map_vote -> char_ban -> playing -> round_end -> (loop กลับ char_ban จนครบรอบ) -> finished
        "teams": {},           # team_no(1-7) -> {"uid", "name", "score", "banned_chars":[]}
        "team_of_uid": {},     # uid -> team_no
        "rounds_required": rounds_required or XROOM_ROUNDS_REQUIRED_DEFAULT,
        "rounds_played": 0,
        "map_votes": {},       # uid -> map_id
        "map_bans": set(),     # map_id ที่ถูกแบนออกจากตัวเลือก
        "map_vote_deadline": time.time() + XROOM_MAP_VOTE_TIME_SEC,
        "chosen_map_id": None,
        "ban_phase_deadline": None,
        "bead_holder_team": None,   # team_no ที่กำลังถือก้อนแมนโดบิกอยู่ตอนนี้ (None = ยังไม่มีใครเก็บ)
        "bead_picked_up": False,
        "bead_position": None,       # จุดเกิด Mando ของรอบนี้บน map เดิม
        "bead_spawn_at": None,
        "bead_spawned": False,
        "round_map_history": [],     # map ที่ใช้จริงตามลำดับ 10 รอบ
        "competition_cash": {},      # เงินแข่งขันแยกจาก wallet หลัก
        "performance_score": {},
        "performance_cash_earned": {},
        "performance_cash_settled": False,
        "starter_items_granted": {}, # กันแจกเงิน/คีย์การ์ดซ้ำเมื่อ reconnect
        "round_deadline": None,
        "round_winner_team": None,  # team_no ที่ exfil สำเร็จรอบล่าสุด (None ถ้ายังไม่มี/หมดเวลา)
        "created_ts": time.time(),
        "claimed_reward": False,
        # [UPGRADE] airdrop + ตำแหน่งทีมสำหรับหน้าจอ lobby แผนที่ใหญ่ — ค่าเริ่มต้นว่างไว้
        # ก่อน จะถูกตั้งค่าจริงตอน _xroom_start_round() ทุกครั้งที่เข้ารอบใหม่
        "airdrop_will_spawn": False,
        "airdrop_spawn_ts": None,
        "airdrop_spawned": False,
        "airdrop_items": {},
        "team_positions": {},
        # [UPGRADE] โหมด C4 — ภารกิจย่อยคู่ขนานกับก้อนแมนโดบิกในรอบเดียวกัน (ไม่ใช่รอบแยก)
        # ทุกทีมวางได้/กู้ได้เหมือนกันหมด (ไม่มีฝั่งตายตัว) จุดวาง A/B สุ่มตำแหน่งใหม่ทุก
        # รอบ ตามที่ตกลง — ค่าเริ่มต้นว่างไว้ก่อน ตั้งค่าจริงตอน _xroom_start_round()
        "c4_sites": {},            # "A"/"B" -> {"x":.., "y":..} สุ่มใหม่ทุกรอบ
        "c4_planted": False,
        "c4_planted_site": None,   # "A" หรือ "B" ที่ถูกใช้วางจริง
        "c4_planted_by_team": None,
        "c4_planted_ts": None,
        "c4_defused": False,
        "c4_defused_by_team": None,
        # [NEW] Extraction-shooter HUD / blue missions / 5-minute special extraction.
        # ระบบนี้ใช้ map เดิมของ xroom ไม่สร้าง map ใหม่
        "mission_sites": {},              # mission_id -> {"x","y","label"}
        "mission_done_by_team": {},       # team_no -> [mission_id]
        "special_extraction": {},         # team_no -> {site_id, unlocked, active, expires_at, used}
        "special_extraction_sites": {},   # site_id -> {"x","y","label"}
        "combat_loot": {},                # loot_id -> item ที่เกิดหลัง combat
        "beacon_brick_count": {},         # team_no -> จำนวน Beacon Brick ที่ถืออยู่
        "decoding_light": {},             # UI-only bridge: ระบบถอดรหัสเดิมของเกมเติมค่าได้เอง
        "drop_skin": {},                  # team_no -> sword/dragon skin id
        "drop_sequence": {},              # team_no -> current cinematic state
    }


def _xroom_public_state(room):
    """ตัดฟิลด์ที่ไม่ต้องส่งให้ client (เช่น set ที่ jsonify ไม่ได้) แปลงให้พร้อมส่งออก"""
    teams_out = {}
    for tno, t in room["teams"].items():
        teams_out[str(tno)] = {"uid": t["uid"], "name": t["name"], "score": t["score"],
                               "banned_chars": t["banned_chars"]}
    now = time.time()
    chosen_map = next((m for m in XROOM_MAP_POOL if m["id"] == room["chosen_map_id"]), None)
    return {
        "room_id": room["room_id"], "phase": room["phase"],
        "teams": teams_out,
        "rounds_required": room["rounds_required"], "rounds_played": room["rounds_played"],
        "map_pool": [m for m in XROOM_MAP_POOL if m["id"] not in room["map_bans"]],
        "map_votes_count": {mid: sum(1 for v in room["map_votes"].values() if v == mid)
                            for mid in {v for v in room["map_votes"].values()}},
        "map_vote_seconds_left": max(0, int(room["map_vote_deadline"] - now)) if room["phase"] == "map_vote" else None,
        "chosen_map_id": room["chosen_map_id"],
        "chosen_map_dims": {"width": chosen_map["width"], "height": chosen_map["height"]} if chosen_map else None,
        "ban_phase_seconds_left": max(0, int(room["ban_phase_deadline"] - now)) \
            if room["phase"] == "char_ban" and room["ban_phase_deadline"] else None,
        "bead_holder_team": room["bead_holder_team"],
        "bead_picked_up": room["bead_picked_up"],
        "bead_position": room.get("bead_position"),
        "bead_spawned": bool(room.get("bead_spawned", False)),
        "bead_spawn_seconds_left": (max(0, int(room["bead_spawn_at"] - now)) if room.get("phase") == "playing" and room.get("bead_spawn_at") and not room.get("bead_spawned") else None),
        "round_map_history": list(room.get("round_map_history", [])),
        "competition_cash": {str(k): v for k, v in room.get("competition_cash", {}).items()},
        "performance_score": {str(k): v for k, v in room.get("performance_score", {}).items()},
        "performance_cash_earned": {str(k): v for k, v in room.get("performance_cash_earned", {}).items()},
        "event_schedule": _xroom_event_schedule_state(),
        "round_seconds_left": max(0, int(room["round_deadline"] - now)) \
            if room["phase"] == "playing" and room["round_deadline"] else None,
        "round_winner_team": room["round_winner_team"],
        "reward_claimable": room["rounds_played"] >= room["rounds_required"] and not room["claimed_reward"],
        "claimed_reward": room["claimed_reward"],
        # [UPGRADE] airdrop — client ใช้ประกอบหน้าจอ lobby แผนที่ใหญ่ + แจ้งเตือนบนจอเกม
        "airdrop_pending": room["airdrop_will_spawn"] and not room["airdrop_spawned"]
            and room["phase"] == "playing",
        "airdrop_items": {iid: {"item": v["item"], "x": v["x"], "y": v["y"],
                                "holder_team": v["holder_team"], "picked_up": v["picked_up"]}
                          for iid, v in room["airdrop_items"].items()},
        # [UPGRADE] ตำแหน่งทุกทีมตอนนี้ — ใช้วาดจุด/เส้นทางบนหน้าจอ lobby แผนที่ใหญ่
        "team_positions": {str(tno): p for tno, p in room["team_positions"].items()},
        # [UPGRADE] โหมด C4 — จุด A/B ของรอบนี้ + สถานะวาง/กู้ล่าสุด
        "c4_sites": room["c4_sites"],
        "c4_planted": room["c4_planted"],
        "c4_planted_site": room["c4_planted_site"],
        "c4_planted_by_team": room["c4_planted_by_team"],
        "c4_defused": room["c4_defused"],
        "c4_defused_by_team": room["c4_defused_by_team"],
        # [NEW] Extraction-shooter HUD data
        "mission_sites": room["mission_sites"],
        "mission_done_by_team": {str(k): v for k, v in room["mission_done_by_team"].items()},
        "special_extraction_sites": room["special_extraction_sites"],
        "special_extraction": {str(k): v for k, v in room["special_extraction"].items()},
        "combat_loot": room["combat_loot"],
        "beacon_brick_count": {str(k): v for k, v in room["beacon_brick_count"].items()},
        "decoding_light": {str(k): v for k, v in room["decoding_light"].items()},
        "drop_skin": {str(k): v for k, v in room.get("drop_skin", {}).items()},
        "drop_sequence": {str(k): v for k, v in room.get("drop_sequence", {}).items()},
    }


def _xroom_broadcast_state(room_id):
    room = XROOM_ROOMS.get(room_id)
    if room:
        sio.emit('xroom_room_state', _xroom_public_state(room), room=_xroom_room_name(room_id))


@app.route('/api/xroom/create', methods=['POST'])
@require_auth_toggleable
def api_xroom_create():
    """สร้างห้องแข่งขันใหม่ — ผู้สร้างเป็น host โดยอัตโนมัติ (team 1)"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    if not uid:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
    if not _xroom_event_is_open():
        return jsonify({
            "st": "error",
            "msg": "การแข่งขันเปิดเฉพาะเวลา 19:00-23:59 น. (เวลาไทย)",
            "event_schedule": _xroom_event_schedule_state(),
        }), 403
    room_id = uuid.uuid4().hex[:8]
    rounds_required = data.get("rounds_required")
    room = _xroom_new_room_state(room_id, uid, rounds_required)
    room["teams"][1] = {"uid": uid, "name": data.get("team_name", "Team 1"), "score": 0, "banned_chars": []}
    room["team_of_uid"][uid] = 1
    XROOM_ROOMS[room_id] = room
    return jsonify({"st": "ok", "room_id": room_id, "state": _xroom_public_state(room)})


@app.route('/api/xroom/join', methods=['POST'])
@require_auth_toggleable
def api_xroom_join():
    """เข้าห้องที่มีอยู่แล้ว — ได้ team slot ถัดไปที่ว่าง (สูงสุด 7 ทีม) เข้าห้องได้เฉพาะ
    ตอน phase == map_vote เท่านั้น (กันคนกระโดดเข้ามากลางเกม)"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room_id = data.get("room_id")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if not _xroom_event_is_open():
        return jsonify({
            "st": "error",
            "msg": "การแข่งขันปิดแล้ว (เปิด 19:00-23:59 น. เวลาไทย)",
            "event_schedule": _xroom_event_schedule_state(),
        }), 403
    if uid in room["team_of_uid"]:
        return jsonify({"st": "ok", "state": _xroom_public_state(room)})  # เข้าซ้ำ ไม่ error
    if room["phase"] != "map_vote":
        return jsonify({"st": "error", "msg": "ห้องนี้เริ่มแข่งไปแล้ว เข้าร่วมไม่ได้"}), 409
    if len(room["teams"]) >= XROOM_MAX_TEAMS:
        return jsonify({"st": "error", "msg": f"ห้องเต็มแล้ว (สูงสุด {XROOM_MAX_TEAMS} ทีม)"}), 409
    team_no = next(n for n in range(1, XROOM_MAX_TEAMS + 1) if n not in room["teams"])
    room["teams"][team_no] = {"uid": uid, "name": data.get("team_name", f"Team {team_no}"),
                              "score": 0, "banned_chars": []}
    room["team_of_uid"][uid] = team_no
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok", "team_no": team_no, "state": _xroom_public_state(room)})


@sio.on('xroom_watch')
def _on_xroom_watch(data):
    """client เรียกหลัง join/create สำเร็จ เพื่อ subscribe realtime update ของห้องนี้
    (ก้อนโดนเก็บ/แย่ง, โหวต map, แบนตัวละคร ฯลฯ) — ตามแนวทาง join_room เดียวกับห้องเสียง [6zz6u]"""
    data = data or {}
    sid = request.sid
    room_id = str(data.get("room_id", ""))
    if not room_id or room_id not in XROOM_ROOMS:
        return
    prev = XROOM_SID_ROOM.get(sid)
    if prev and prev != room_id:
        leave_room(_xroom_room_name(prev))
    join_room(_xroom_room_name(room_id))
    XROOM_SID_ROOM[sid] = room_id
    sio.emit('xroom_room_state', _xroom_public_state(XROOM_ROOMS[room_id]), room=sid)


def _xroom_cleanup_sid(sid: str):
    """เรียกตอน disconnect — แค่เอาออกจาก socket room เฉยๆ ไม่ลบทีมออกจากห้องแข่งขัน
    (คนอาจหลุดเน็ตแล้วกลับมาต่อใหม่ได้ ทีม/คะแนนยังอยู่)"""
    room_id = XROOM_SID_ROOM.pop(sid, None)
    if room_id:
        leave_room(_xroom_room_name(room_id))


# ---- Map vote/ban phase ----

@app.route('/api/xroom/<room_id>/map_vote', methods=['POST'])
@require_auth_toggleable
def api_xroom_map_vote(room_id):
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    map_id = data.get("map_id")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "map_vote":
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในช่วงโหวต map"}), 409
    if uid not in room["team_of_uid"]:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    valid_ids = {m["id"] for m in XROOM_MAP_POOL} - room["map_bans"]
    if map_id not in valid_ids:
        return jsonify({"st": "error", "msg": "map นี้ถูกแบนไปแล้ว หรือไม่มีในระบบ"}), 400
    room["map_votes"][uid] = map_id
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok"})


@app.route('/api/xroom/<room_id>/map_ban', methods=['POST'])
@require_auth_toggleable
def api_xroom_map_ban(room_id):
    """เฉพาะ host เท่านั้นที่แบน map ได้ (กันแต่ละทีมแย่งกันแบนจนไม่เหลือตัวเลือก) —
    ถ้าอยากให้โหวตแบนร่วมกันแทน ปรับ logic ตรงนี้เป็นนับเสียงได้ทีหลัง"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    map_id = data.get("map_id")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if uid != room["host_uid"]:
        return jsonify({"st": "error", "msg": "เฉพาะ host เท่านั้นที่แบน map ได้"}), 403
    if room["phase"] != "map_vote":
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในช่วงเลือก map"}), 409
    remaining = {m["id"] for m in XROOM_MAP_POOL} - room["map_bans"]
    if len(remaining) <= 1:
        return jsonify({"st": "error", "msg": "เหลือ map สุดท้ายแล้ว แบนเพิ่มไม่ได้"}), 400
    room["map_bans"].add(map_id)
    room["map_votes"] = {u: m for u, m in room["map_votes"].items() if m != map_id}
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok"})


def _xroom_resolve_map_vote(room):
    """ปิดโหวต -> เลือก map จากเสียงมากสุด ถ้าไม่มีใครโหวตเลยหรือหมดเวลา -> สุ่มจากที่เหลือ"""
    remaining = [m["id"] for m in XROOM_MAP_POOL if m["id"] not in room["map_bans"]]
    counts = {}
    for mid in room["map_votes"].values():
        counts[mid] = counts.get(mid, 0) + 1
    if counts:
        top = max(counts.values())
        winners = [mid for mid, c in counts.items() if c == top]
        room["chosen_map_id"] = random.choice(winners)
    else:
        room["chosen_map_id"] = random.choice(remaining)


@app.route('/api/xroom/<room_id>/map_vote/finish', methods=['POST'])
@require_auth_toggleable
def api_xroom_map_vote_finish(room_id):
    """host กดปิดโหวตก่อนเวลา หรือเรียกจาก client ตอนหมดเวลานับถอยหลัง — สรุปผล map
    แล้วเข้าสู่ช่วงแบนตัวละคร"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "map_vote":
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในช่วงโหวต map"}), 409
    if uid != room["host_uid"] and time.time() < room["map_vote_deadline"]:
        return jsonify({"st": "error", "msg": "ยังไม่หมดเวลาโหวต เฉพาะ host กดปิดก่อนเวลาได้"}), 403
    _xroom_resolve_map_vote(room)
    room["phase"] = "char_ban"
    room["ban_phase_deadline"] = time.time() + XROOM_BAN_PHASE_TIME_SEC
    sio.emit('xroom_map_chosen', {"room_id": room_id, "map_id": room["chosen_map_id"]},
             room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok", "chosen_map_id": room["chosen_map_id"]})


# ---- Character ban phase ----

@app.route('/api/xroom/<room_id>/char_pool')
def api_xroom_char_pool(room_id):
    """รายชื่อตัวละครทั้งหมด + สถานะแบน ปัจจุบัน ใช้เรนเดอร์หน้าจอ ban เหมือนสไตล์ MOBA
    (แถบฝั่งเรา/ฝั่งตรงข้าม + grid ตัวละคร + ช่องแบนด้านบน)"""
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    all_banned = {c for t in room["teams"].values() for c in t["banned_chars"]}
    pool = [{**c, "banned": c["id"] in all_banned} for c in XROOM_CHARACTER_POOL]
    return jsonify({"st": "ok", "characters": pool,
                    "max_bans_per_side": XROOM_MAX_BANS_PER_SIDE})


@app.route('/api/xroom/<room_id>/char_ban', methods=['POST'])
@require_auth_toggleable
def api_xroom_char_ban(room_id):
    """ทีมของ uid แบนตัวละคร 1 ตัว (สูงสุด 3 ตัวต่อฝั่งตามที่ตกลงไว้) — แบนแล้วตัวละคร
    นั้นใช้ไม่ได้ทั้งห้อง (ทุกทีม) ไม่ใช่แค่ทีมที่แบนเลี่ยงเอง"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    char_id = data.get("char_id")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "char_ban":
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในช่วงแบนตัวละคร"}), 409
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    team = room["teams"][team_no]
    if len(team["banned_chars"]) >= XROOM_MAX_BANS_PER_SIDE:
        return jsonify({"st": "error", "msg": f"ทีมนี้แบนครบ {XROOM_MAX_BANS_PER_SIDE} ตัวแล้ว"}), 400
    if char_id not in {c["id"] for c in XROOM_CHARACTER_POOL}:
        return jsonify({"st": "error", "msg": "ไม่รู้จักตัวละครนี้"}), 400
    already_banned = {c for t in room["teams"].values() for c in t["banned_chars"]}
    if char_id in already_banned:
        return jsonify({"st": "error", "msg": "ตัวละครนี้ถูกแบนไปแล้วโดยทีมอื่น"}), 409
    team["banned_chars"].append(char_id)
    # [UI] ยิง event แยกสำหรับอนิเมชันตัวเลือก -> ขึ้นช่องแบนด้านบน ตามที่อธิบายไว้
    # (client ใช้ event นี้เล่นอนิเมชันตัวละครหมุน/เฟดแล้วเลื่อนขึ้นแถบบน)
    sio.emit('xroom_char_banned', {"room_id": room_id, "team_no": team_no, "char_id": char_id,
                                        "banned_by_side": "home" if team_no == 1 else "away"},
             room=_xroom_room_name(room_id))
    all_teams_done = all(len(t["banned_chars"]) >= XROOM_MAX_BANS_PER_SIDE
                         for t in room["teams"].values())
    if all_teams_done or time.time() >= (room["ban_phase_deadline"] or 0):
        _xroom_start_round(room)
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok", "state": _xroom_public_state(room)})



# =========================================================
# [6zz7b] Extraction Shooter HUD + Blue Missions + 5-Minute
# Special Extraction + Post-Combat Loot
# =========================================================
XROOM_BLUE_MISSION_COUNT = 3
XROOM_SPECIAL_EXTRACTION_DURATION_SEC = 5 * 60
XROOM_COMBAT_LOOT_TTL_SEC = 15 * 60
XROOM_SPECIAL_EXTRACTION_RADIUS = 35.0

def _xroom_add_performance(room, team_no, activity, units=1):
    weight = int(XROOM_PERFORMANCE_WEIGHTS.get(activity, 0))
    try: units = max(0, int(units))
    except (TypeError, ValueError): units = 0
    gain = weight * units
    room.setdefault("performance_score", {}).setdefault(team_no, 0)
    room["performance_score"][team_no] += gain
    return gain

def _xroom_settle_performance_cash(room):
    if room.get("performance_cash_settled"): return {}
    scores = {int(k): max(0, int(v)) for k,v in room.get("performance_score",{}).items()}
    total = sum(scores.values()); payouts = {int(t):0 for t in room.get("teams",{})}
    if total and XROOM_PERFORMANCE_CASH_POOL > 0:
        pool = XROOM_PERFORMANCE_CASH_POOL
        raw = {t: pool*score/total for t,score in scores.items()}
        payouts = {int(t): int(raw.get(int(t),0)) for t in room.get("teams",{})}
        remainder = pool - sum(payouts.values())
        order = sorted(payouts, key=lambda t: raw.get(t,0)-payouts[t], reverse=True)
        for t in order[:remainder]: payouts[t] += 1
        for t,amount in payouts.items(): room.setdefault("competition_cash",{})[t] = room.setdefault("competition_cash",{}).get(t,0)+amount
    room["performance_cash_earned"] = payouts; room["performance_cash_settled"] = True
    sio.emit("xroom_performance_cash_settled", {"room_id":room["room_id"],"pool":XROOM_PERFORMANCE_CASH_POOL,"scores":{str(k):v for k,v in scores.items()},"payouts":{str(k):v for k,v in payouts.items()}}, room=_xroom_room_name(room["room_id"]))
    return payouts

def _xroom_spawn_mando(room):
    if room.get("bead_spawned") or room.get("phase") != "playing": return False
    chosen = next((m for m in XROOM_MAP_POOL if m["id"] == room.get("chosen_map_id")), None)
    mw = chosen["width"] if chosen else 1000; mh = chosen["height"] if chosen else 1000
    _bx, _by = _vmax_map_point(room.get("chosen_map_id"), random.uniform(mw*.15,mw*.85), random.uniform(mh*.15,mh*.85))
    room["bead_position"] = {"x":round(_bx,2),"y":round(_by,2),"label":XROOM_OBJECTIVE_NAME,"color":"yellow"}
    room["bead_spawned"] = True
    sio.emit("xroom_mando_spawned", {"room_id":room["room_id"],"round_no":room["rounds_played"]+1,"item":{"id":"mando","name":XROOM_OBJECTIVE_NAME},"x":room["bead_position"]["x"],"y":room["bead_position"]["y"],"seconds_from_round_start":XROOM_MANDO_SPAWN_AFTER_SEC}, room=_xroom_room_name(room["room_id"]))
    _xroom_broadcast_state(room["room_id"]); return True


def _xroom_init_extraction_layer(room, width, height):
    """สุ่มจุดภารกิจสีฟ้า + จุดทางออกพิเศษ โดยใช้พิกัด map เดิมของ xroom"""
    mission_sites = {}
    for i in range(XROOM_BLUE_MISSION_COUNT):
        mission_sites[f"mission_{i+1}"] = {
            "x": round(random.uniform(width * 0.12, width * 0.88), 2),
            "y": round(random.uniform(height * 0.12, height * 0.88), 2),
            "label": f"Mission {i+1}",
            "color": "blue",
        }
    special_sites = {
        "special_exit_1": {
            "x": round(width * 0.10, 2),
            "y": round(height * 0.50, 2),
            "label": "Special Extraction",
            "color": "blue",
        },
        "special_exit_2": {
            "x": round(width * 0.90, 2),
            "y": round(height * 0.50, 2),
            "label": "Special Extraction",
            "color": "blue",
        },
    }
    _cm_id = room.get("chosen_map_id")
    for _ms in mission_sites.values():   # แมพ layout: ดึงจุดภารกิจเข้าพื้นที่เดินได้
        _ms["x"], _ms["y"] = [round(v, 2) for v in _vmax_map_point(_cm_id, _ms["x"], _ms["y"])]
    _ex_pts = _vmax_map_exit_points(_cm_id, 2)
    for _k, _se in special_sites.items():
        if _ex_pts:
            _src = _ex_pts[0 if _k.endswith("1") else 1]
            _se["x"], _se["y"] = round(float(_src["x"]), 2), round(float(_src["y"]), 2)
        else:
            _se["x"], _se["y"] = [round(v, 2) for v in _vmax_map_point(_cm_id, _se["x"], _se["y"])]
    room["mission_sites"] = mission_sites
    room["mission_done_by_team"] = {int(t): [] for t in room["teams"]}
    room["special_extraction_sites"] = special_sites
    room["special_extraction"] = {}
    room["beacon_brick_count"] = {int(t): 0 for t in room["teams"]}
    room["decoding_light"] = {int(t): 0 for t in room["teams"]}
    for tno in room["teams"]:
        site_id = random.choice(list(special_sites.keys()))
        room["special_extraction"][int(tno)] = {
            "site_id": site_id,
            "unlocked": False,
            "active": False,
            "expires_at": None,
            "used": False,
        }

def _xroom_expire_special_extractions(room, now=None):
    now = time.time() if now is None else now
    changed = False
    for st in room.get("special_extraction", {}).values():
        if st.get("active") and st.get("expires_at") and now >= st["expires_at"]:
            st["active"] = False
            st["expires_at"] = None
            changed = True
    return changed

def _xroom_team_missions_complete(room, team_no):
    done = set(room.get("mission_done_by_team", {}).get(team_no, []))
    return len(done) >= len(room.get("mission_sites", {})) and bool(room.get("mission_sites"))

def _xroom_grant_beacon_brick(room, team_no, qty=1):
    room.setdefault("beacon_brick_count", {}).setdefault(team_no, 0)
    room["beacon_brick_count"][team_no] += max(0, int(qty))

def _xroom_set_decoding_light(room, team_no, value):
    """Bridge เฉย ๆ ไปยังระบบ Decoding เดิม — ไม่สร้าง decoder ใหม่"""
    try:
        value = max(0, int(value))
    except (TypeError, ValueError):
        value = 0
    room.setdefault("decoding_light", {})[team_no] = value

@app.route('/api/xroom/<room_id>/extraction/hud')
def api_xroom_extraction_hud(room_id):
    """สถานะสำหรับ HUD: แถบเหลือง, จุดภารกิจฟ้า, airdrop ส้ม และ special extraction 5 นาที"""
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    _xroom_expire_special_extractions(room)
    return jsonify({"st": "ok", "state": _xroom_public_state(room)})

@app.route('/api/xroom/<room_id>/mission/complete', methods=['POST'])
@require_auth_toggleable
def api_xroom_mission_complete(room_id):
    """ทำภารกิจจุดสีฟ้า 1 จุด — ครบ 3 จุดแล้วปลดล็อกทางออกพิเศษของทีม"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    mission_id = data.get("mission_id")
    room = XROOM_ROOMS.get(room_id)
    if not room or room.get("phase") != "playing":
        return jsonify({"st": "error", "msg": "ไม่พบห้อง หรือยังไม่อยู่ในช่วงแข่งขัน"}), 409
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    if mission_id not in room.get("mission_sites", {}):
        return jsonify({"st": "error", "msg": "ไม่พบภารกิจนี้"}), 404
    done = room["mission_done_by_team"].setdefault(team_no, [])
    if mission_id in done:
        return jsonify({"st": "error", "msg": "ภารกิจนี้ทำไปแล้ว"}), 409
    done.append(mission_id)
    performance_gain = _xroom_add_performance(room, team_no, "blue_mission")
    unlocked = False
    if _xroom_team_missions_complete(room, team_no):
        ex = room["special_extraction"][team_no]
        if not ex["unlocked"]:
            ex["unlocked"] = True
            unlocked = True
    payload = {
        "room_id": room_id, "team_no": team_no, "mission_id": mission_id,
        "completed": len(done), "required": len(room["mission_sites"]), "performance_gain": performance_gain,
        "special_extraction_unlocked": room["special_extraction"][team_no]["unlocked"],
    }
    sio.emit("xroom_blue_mission_completed", payload, room=_xroom_room_name(room_id))
    if unlocked:
        sio.emit("xroom_special_extraction_unlocked", {
            "room_id": room_id, "team_no": team_no,
            "site_id": room["special_extraction"][team_no]["site_id"],
            "duration_sec": XROOM_SPECIAL_EXTRACTION_DURATION_SEC,
        }, room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok", "state": _xroom_public_state(room)})

@app.route('/api/xroom/<room_id>/extraction/special/start', methods=['POST'])
@require_auth_toggleable
def api_xroom_special_extraction_start(room_id):
    """เริ่มหน้าต่างทางออกพิเศษ 5 นาที หลังทำภารกิจสีฟ้าครบ"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = XROOM_ROOMS.get(room_id)
    if not room or room.get("phase") != "playing":
        return jsonify({"st": "error", "msg": "ไม่พบห้อง หรือรอบจบแล้ว"}), 409
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    ex = room["special_extraction"].get(team_no)
    if not ex or not ex["unlocked"]:
        return jsonify({"st": "error", "msg": "ต้องทำภารกิจสีฟ้าให้ครบก่อน"}), 400
    if ex["used"]:
        return jsonify({"st": "error", "msg": "ทางออกพิเศษถูกใช้ไปแล้ว"}), 409
    now = time.time()
    _xroom_expire_special_extractions(room, now)
    if ex["active"]:
        return jsonify({"st": "ok", "expires_at": ex["expires_at"],
                        "seconds_left": max(0, int(ex["expires_at"] - now))})
    ex["active"] = True
    ex["expires_at"] = now + XROOM_SPECIAL_EXTRACTION_DURATION_SEC
    payload = {
        "room_id": room_id, "team_no": team_no, "site_id": ex["site_id"],
        "expires_at": ex["expires_at"], "duration_sec": XROOM_SPECIAL_EXTRACTION_DURATION_SEC,
    }
    sio.emit("xroom_special_extraction_started", payload, room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok", **payload})

@app.route('/api/xroom/<room_id>/extraction/special/finish', methods=['POST'])
@require_auth_toggleable
def api_xroom_special_extraction_finish(room_id):
    """กดออกที่จุดสีฟ้าเมื่อหน้าต่าง 5 นาทีเปิดอยู่ — รักษาของที่ถืออยู่และจบการถอนกำลังของทีม"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = XROOM_ROOMS.get(room_id)
    if not room or room.get("phase") != "playing":
        return jsonify({"st": "error", "msg": "ไม่พบห้อง หรือรอบจบแล้ว"}), 409
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    ex = room["special_extraction"].get(team_no)
    if not ex or not ex.get("active"):
        return jsonify({"st": "error", "msg": "ทางออกพิเศษยังไม่เปิด หรือหมดเวลาแล้ว"}), 409
    ex["active"] = False
    ex["used"] = True
    ex["expires_at"] = None
    performance_gain = _xroom_add_performance(room, team_no, "special_extraction")
    # คะแนนรอบยังใช้กติกา bead exfil เดิม; special extraction เป็นทางออกเสริม
    payload = {"room_id": room_id, "team_no": team_no, "site_id": ex["site_id"]}
    sio.emit("xroom_special_extraction_finished", payload, room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st":"ok","extracted":True,"performance_gain":performance_gain,"state":_xroom_public_state(room)})

@app.route('/api/xroom/<room_id>/combat/drop', methods=['POST'])
@require_auth_toggleable
def api_xroom_combat_drop(room_id):
    """จุดเชื่อมจาก combat engine: หลังยิงกันจบ ให้เรียก endpoint นี้เพื่อทำ item marker โผล่ใน map เดิม"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    item = data.get("item") or {"id": "beacon_brick", "name": "Beacon Brick", "value": 0}
    x, y = float(data.get("x", 0)), float(data.get("y", 0))
    room = XROOM_ROOMS.get(room_id)
    if not room or room.get("phase") != "playing":
        return jsonify({"st": "error", "msg": "ไม่พบห้อง หรือรอบจบแล้ว"}), 409
    if uid not in room["team_of_uid"]:
        return jsonify({"st": "error", "msg": "ผู้เรียกไม่ได้อยู่ในห้อง"}), 403
    loot_id = f"combatloot_{uuid.uuid4().hex[:8]}"
    room["combat_loot"][loot_id] = {
        "id": loot_id, "item": item, "x": x, "y": y,
        "claimed": False, "created_at": time.time(), "color": "yellow",
    }
    sio.emit("xroom_combat_loot_spawned", {
        "room_id": room_id, "loot_id": loot_id, "item": item, "x": x, "y": y,
    }, room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok", "loot_id": loot_id, "loot": room["combat_loot"][loot_id]})

@app.route('/api/xroom/<room_id>/combat/loot/claim', methods=['POST'])
@require_auth_toggleable
def api_xroom_combat_loot_claim(room_id):
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    loot_id = data.get("loot_id")
    room = XROOM_ROOMS.get(room_id)
    if not room or room.get("phase") != "playing":
        return jsonify({"st": "error", "msg": "ไม่พบห้อง หรือรอบจบแล้ว"}), 409
    if uid not in room["team_of_uid"]:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    loot = room["combat_loot"].get(loot_id)
    if not loot or loot.get("claimed"):
        return jsonify({"st": "error", "msg": "item นี้ถูกเก็บไปแล้วหรือหมดอายุ"}), 404
    if time.time() - loot["created_at"] >= XROOM_COMBAT_LOOT_TTL_SEC:
        room["combat_loot"].pop(loot_id, None)
        return jsonify({"st": "error", "msg": "item หมดอายุแล้ว"}), 409
    loot["claimed"] = True
    item = loot["item"]
    team_no = room["team_of_uid"][uid]
    performance_gain = _xroom_add_performance(room, team_no, "combat_loot")
    if item.get("id") == "beacon_brick" or item.get("name") == "Beacon Brick":
        _xroom_grant_beacon_brick(room, team_no, int(item.get("qty", 1)))
    # ไม่แตะระบบ Decoding — ส่งข้อมูลให้ระบบเดิมเท่านั้น
    sio.emit("xroom_combat_loot_claimed", {
        "room_id": room_id, "loot_id": loot_id, "team_no": team_no,
        "item": item, "performance_gain": performance_gain,
        "decode_bridge": {"item_id": item.get("id"), "name": item.get("name")},
    }, room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok", "item": item, "decode_bridge": {"item_id": item.get("id"), "name": item.get("name")}})

def _xroom_start_round(room):
    """เริ่มรอบใหม่ — 18 นาทีต่อรอบ, 10 รอบต่อทัวร์นาเมนต์ และเปลี่ยน map ทุกครั้ง"""
    if not _xroom_event_is_open():
        room["phase"] = "finished"
        sio.emit("xroom_tournament_closed", {
            "room_id": room["room_id"],
            "reason": "event_closed",
            "event_schedule": _xroom_event_schedule_state(),
        }, room=_xroom_room_name(room["room_id"]))
        _xroom_broadcast_state(room["room_id"])
        return

    # รอบแรกใช้ map จาก vote เดิม; รอบต่อไปเปลี่ยน map อัตโนมัติจาก pool เดิม
    previous_map = room.get("chosen_map_id")
    if room.get("rounds_played", 0) > 0:
        candidates = [m["id"] for m in XROOM_MAP_POOL if m["id"] != previous_map]
        room["chosen_map_id"] = random.choice(candidates or [m["id"] for m in XROOM_MAP_POOL])

    room["round_map_history"].append(room.get("chosen_map_id"))
    if previous_map and previous_map != room.get("chosen_map_id"):
        map_info = next((m for m in XROOM_MAP_POOL if m["id"] == room["chosen_map_id"]), None)
        sio.emit("xroom_map_changed", {
            "room_id": room["room_id"],
            "round_no": room["rounds_played"] + 1,
            "previous_map_id": previous_map,
            "map_id": room["chosen_map_id"],
            "map_name": map_info["name"] if map_info else room["chosen_map_id"],
        }, room=_xroom_room_name(room["room_id"]))
    room["phase"] = "playing"
    room["bead_holder_team"] = None
    room["bead_picked_up"] = False
    room["bead_spawned"] = False
    room["bead_position"] = None
    room["round_winner_team"] = None
    round_started_at = time.time()
    room["round_started_at"] = round_started_at
    room["round_deadline"] = round_started_at + XROOM_ROUND_TIME_LIMIT_SEC
    room["bead_spawn_at"] = round_started_at + XROOM_MANDO_SPAWN_AFTER_SEC
    room["performance_score"] = {int(t):0 for t in room["teams"]}
    room["performance_cash_earned"] = {int(t):0 for t in room["teams"]}
    room["performance_cash_settled"] = False

    # Mando ยังไม่แสดงตอนเริ่มรอบ — จะโผล่เมื่อครบ 8 นาที

    # แจกเงินแข่งขัน + keycard 3 ใบเมื่อเข้าแข่งขันครั้งแรก
    _xroom_grant_starter_items(room)
    # [UPGRADE] airdrop — สุ่มว่ารอบนี้ "มีหรือไม่มี" (ตามที่ตกลง) แล้วถ้ามี ให้สุ่มเวลา
    # ลงกลางๆ รอบ (ไม่ใช่ทันทีตอนเริ่ม) — เช็คจริงใน _xroom_tick_loop ด้านล่าง
    room["airdrop_will_spawn"] = random.random() < XROOM_AIRDROP_CHANCE
    if room["airdrop_will_spawn"]:
        # สุ่มเวลาให้ตกช่วงกลางๆ ของเวลารอบ (25%-70% ของเวลาที่ผ่านไป) ไม่ใช่หัว/ท้ายรอบ
        lo = room["round_deadline"] - XROOM_ROUND_TIME_LIMIT_SEC * 0.70
        hi = room["round_deadline"] - XROOM_ROUND_TIME_LIMIT_SEC * 0.25
        room["airdrop_spawn_ts"] = random.uniform(lo, hi)
    else:
        room["airdrop_spawn_ts"] = None
    room["airdrop_spawned"] = False
    room["airdrop_items"] = {}       # item_id -> {"item": {...}, "holder_team": None, "picked_up": False, "x","y"}
    room["team_positions"] = {tno: {"x": 0.0, "y": 0.0, "alive": True, "ts": time.time()}
                              for tno in room["teams"]}
    room["combat_loot"] = {}
    room.setdefault("drop_skin", {})
    room["drop_sequence"] = {int(t): {"state": "aircraft", "skin": room["drop_skin"].get(int(t), "sword"), "started_at": time.time()} for t in room["teams"]}
    # [UPGRADE] โหมด C4 — สุ่มจุด A/B ใหม่ทุกรอบ (ตามพิกัดจริงของ map ที่เลือกไว้ แนวทาง
    # เดียวกับ airdrop ด้านบน) แล้วรีเซ็ตสถานะวาง/กู้ระเบิดของรอบก่อนหน้าทิ้งทั้งหมด
    _chosen_map = next((m for m in XROOM_MAP_POOL if m["id"] == room["chosen_map_id"]), None)
    _mw = _chosen_map["width"] if _chosen_map else 1000
    _mh = _chosen_map["height"] if _chosen_map else 1000
    _xroom_init_extraction_layer(room, _mw, _mh)
    room["c4_sites"] = {
        "A": _vmax_map_xy_dict(room["chosen_map_id"], random.uniform(0, _mw), random.uniform(0, _mh)),
        "B": _vmax_map_xy_dict(room["chosen_map_id"], random.uniform(0, _mw), random.uniform(0, _mh)),
    }
    room["c4_planted"] = False
    room["c4_planted_site"] = None
    room["c4_planted_by_team"] = None
    room["c4_planted_ts"] = None
    room["c4_defused"] = False
    room["c4_defused_by_team"] = None
    sio.emit('xroom_round_started', {
        "room_id": room["room_id"],
        "map_id": room["chosen_map_id"],
        "round_no": room["rounds_played"] + 1,
        "round_time_sec": XROOM_ROUND_TIME_LIMIT_SEC,
        "mando_spawn_after_sec": XROOM_MANDO_SPAWN_AFTER_SEC,
    }, room=_xroom_room_name(room["room_id"]))
    sio.emit('xroom_drop_sequence_started', {
        "room_id": room["room_id"],
        "round_no": room["rounds_played"] + 1,
        "skins": {str(k): v for k, v in room.get("drop_skin", {}).items()},
        "sequence": "aircraft_approach>sword_descent>landing>jump>sword_vanish",
    }, room=_xroom_room_name(room["room_id"]))
    _xroom_broadcast_state(room["room_id"])


# ---- Bead pickup / steal / exfil ----

@app.route('/api/xroom/<room_id>/pickup', methods=['POST'])
@require_auth_toggleable
def api_xroom_pickup(room_id):
    """ทีมของ uid เก็บก้อนแมนโดบิกได้ — แค่ "ถือครอง" เท่านั้น ยังไม่ได้แต้ม (ต้อง exfil
    สำเร็จก่อน) ถ้ามีคนถืออยู่แล้ว ต้องใช้ /steal แทน"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "playing":
        return jsonify({"st": "error", "msg": "ยังไม่ถึงช่วงแข่งขัน"}), 409
    if not room.get("bead_spawned"):
        return jsonify({"st":"error","msg":"Mando ยังไม่โผล่ — รอให้ครบ 8 นาทีของรอบ"}), 409
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    if room["bead_picked_up"]:
        return jsonify({"st": "error", "msg": "ก้อนถูกเก็บไปแล้ว ใช้ /steal ถ้าจะแย่งแทน"}), 409
    room["bead_holder_team"] = team_no
    room["bead_picked_up"] = True
    performance_gain = _xroom_add_performance(room, team_no, "mando_pickup")
    sio.emit('xroom_bead_picked_up', {"room_id": room_id, "team_no": team_no, "performance_gain": performance_gain},
             room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok"})


@app.route('/api/xroom/<room_id>/steal', methods=['POST'])
@require_auth_toggleable
def api_xroom_steal(room_id):
    """ทีมของ uid แย่งก้อนจากทีมที่ถืออยู่ตอนนี้ — ทีมที่โดนแย่ง "ไม่ได้แต้ม" (ตามกติกาที่
    ตกลงไว้) เจ้าของก้อนเปลี่ยนเป็นทีมที่แย่งได้ทันที ถ้าทีมนี้ exfil สำเร็จภายหลัง ทีมนี้
    จะได้แต้มแทน"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "playing":
        return jsonify({"st": "error", "msg": "ยังไม่ถึงช่วงแข่งขัน"}), 409
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    if not room["bead_picked_up"] or room["bead_holder_team"] is None:
        return jsonify({"st": "error", "msg": "ยังไม่มีใครถือก้อนอยู่ ใช้ /pickup แทน"}), 409
    if room["bead_holder_team"] == team_no:
        return jsonify({"st": "error", "msg": "ทีมตัวเองถือก้อนอยู่แล้ว แย่งตัวเองไม่ได้"}), 400
    prev_holder = room["bead_holder_team"]
    room["bead_holder_team"] = team_no
    performance_gain = _xroom_add_performance(room, team_no, "mando_steal")
    sio.emit('xroom_bead_stolen', {"room_id": room_id, "from_team": prev_holder, "to_team": team_no, "performance_gain": performance_gain},
             room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok"})


@app.route('/api/xroom/<room_id>/exfil', methods=['POST'])
@require_auth_toggleable
def api_xroom_exfil(room_id):
    """ทีมที่ถือก้อนอยู่ ณ ตอนนี้ ออกจาก map สำเร็จ -> ได้ 1 แต้มทันที จบรอบนี้ เข้ารอบถัดไป
    (ถ้ายังไม่ครบ rounds_required) หรือเปิดให้เคลมของรางวัลได้ (ถ้าครบแล้ว)"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "playing":
        return jsonify({"st": "error", "msg": "ยังไม่ถึงช่วงแข่งขัน"}), 409
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    if not room["bead_picked_up"] or room["bead_holder_team"] != team_no:
        return jsonify({"st": "error", "msg": "ทีมนี้ไม่ได้ถือก้อนอยู่ ออกไม่ได้"}), 409
    performance_gain = _xroom_add_performance(room, team_no, "mando_exfil")
    _xroom_end_round(room, winner_team=team_no)
    return jsonify({"st":"ok","performance_gain":performance_gain,"state":_xroom_public_state(room)})


def _territory_apply_raid_reward(session: dict):
    """เรียกอัตโนมัติจาก _xroom_end_round ตอน exfil สำเร็จ ถ้าห้องนั้นถูกสร้างผ่าน
    /api/territory/raid/start — ให้คะแนนฝ่าย (ตาม score_rank_pct ของประเภทพื้นที่) และสุ่มโอกาส
    ได้ป้ายด็อกแท็ก (โอกาสสูงขึ้นถ้าเจอฝ่ายศัตรู/บอสระหว่างปฏิบัติการ)"""
    uid = session["uid"]
    pstate = _territory_player(uid)
    score_gain = max(1, round(10 * session["score_rank_pct"] / 100))
    pstate["reputation_score"] += score_gain

    dogtag_chance = 0.6 if session["threat_encountered"] else 0.25
    dogtags_gained = 0
    if random.random() < dogtag_chance:
        bstate = _bounty_player(uid)
        bstate["dogtags_held"] += 1
        dogtags_gained = 1

    session["completed"] = True
    session["completed_at"] = time.time()
    session["reputation_gained"] = score_gain
    session["dogtags_gained"] = dogtags_gained


def _xroom_end_round(room, winner_team):
    """ปิดรอบปัจจุบัน — ถ้ามีผู้ชนะ (exfil สำเร็จ) ให้ +1 แต้ม ถ้า winner_team เป็น None
    (หมดเวลารอบ ไม่มีใคร exfil ได้) ไม่มีใครได้แต้มในรอบนี้"""
    room_id = room["room_id"]
    if winner_team is not None:
        room["teams"][winner_team]["score"] += 1
        # ผูกกับระบบยึดพื้นที่ — ถ้าห้องนี้ถูกสร้างผ่าน /api/territory/raid/start ให้รางวัลย้อนกลับ
        raid_session = TERRITORY_RAID_SESSIONS.get(room_id)
        if raid_session and not raid_session["completed"]:
            _territory_apply_raid_reward(raid_session)
    performance_payouts = _xroom_settle_performance_cash(room)
    room["round_winner_team"] = winner_team
    room["rounds_played"] += 1
    room["phase"] = "round_end"
    sio.emit('xroom_round_ended', {"room_id": room_id, "winner_team": winner_team,
                                        "rounds_played": room["rounds_played"],
                                        "rounds_required": room["rounds_required"],
                                        "performance_score": {str(k): v for k,v in room.get("performance_score",{}).items()},
                                        "performance_cash_earned": {str(k): v for k,v in performance_payouts.items()}},
             room=_xroom_room_name(room_id))
    if room["rounds_played"] >= room["rounds_required"]:
        room["phase"] = "finished"
        sio.emit('xroom_tournament_finished', {"room_id": room_id,
                                                     "final_scores": {str(t): v["score"]
                                                                      for t, v in room["teams"].items()}},
                 room=_xroom_room_name(room_id))
    else:
        # เข้ารอบถัดไป -> กลับไปแบนตัวละครใหม่รอบใหม่ (คงตัวที่แบนไปแล้วสะสมไว้ ตามการ
        # ออกแบบทั่วไปของโหมด draft — ถ้าอยากให้แบนใหม่ได้ทุกรอบ ล้าง banned_chars ตรงนี้แทน)
        room["phase"] = "char_ban"
        room["ban_phase_deadline"] = time.time() + XROOM_BAN_PHASE_TIME_SEC
    _xroom_broadcast_state(room_id)


@app.route('/api/xroom/<room_id>/round/force_timeout', methods=['POST'])
@require_auth_toggleable
def api_xroom_round_force_timeout(room_id):
    """เรียกจาก client (หรืองาน cron/loop ฝั่ง server) ตอนตรวจว่า round_deadline ผ่านไปแล้ว
    แต่ยังไม่มีใคร exfil สำเร็จ — จบรอบแบบไม่มีใครได้แต้ม"""
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "playing":
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในช่วงแข่งขัน"}), 409
    if room["round_deadline"] and time.time() < room["round_deadline"]:
        return jsonify({"st": "error", "msg": "ยังไม่หมดเวลารอบนี้"}), 400
    _xroom_end_round(room, winner_team=None)
    return jsonify({"st": "ok", "state": _xroom_public_state(room)})


# ---- Airdrop สนับสนุน (สุ่มมี/ไม่มีต่อรอบ, ลงกลางๆ รอบ, แยกจากก้อนแมนโดบิกหลัก) ----

def _xroom_spawn_airdrop(room):
    """สุ่มตำแหน่งของตกลง map (สมมติพิกัด 0..width / 0..height ของ map ที่เลือกไว้) พร้อม
    ของสนับสนุน 3-5 ชิ้นจาก XROOM_AIRDROP_CATALOG (มูลค่าตายตัวตาม catalog) แล้วแจ้งเตือน
    ทุกคนในห้อง (event ขึ้นแจ้งเตือนด้านบนจอ + เวลาการแข่งขัน ตามที่อธิบายไว้)"""
    chosen_map = next((m for m in XROOM_MAP_POOL if m["id"] == room["chosen_map_id"]), None)
    w = chosen_map["width"] if chosen_map else 1000
    h = chosen_map["height"] if chosen_map else 1000
    drop_x, drop_y = _vmax_map_point(room["chosen_map_id"], random.uniform(0, w), random.uniform(0, h))
    n_items = min(XROOM_AIRDROP_ITEMS_PER_DROP, len(XROOM_AIRDROP_CATALOG))
    picked_items = random.sample(XROOM_AIRDROP_CATALOG, n_items)
    for item in picked_items:
        item_id = uuid.uuid4().hex[:8]
        # กระจายของแต่ละชิ้นรอบจุดตกจริงเล็กน้อย (รัศมี ~15 หน่วย) ไม่ทับซ้อนจุดเดียวกันเป๊ะ
        ix = min(max(0, drop_x + random.uniform(-15, 15)), w)
        iy = min(max(0, drop_y + random.uniform(-15, 15)), h)
        ix, iy = _vmax_map_point(room["chosen_map_id"], ix, iy)   # แมพ layout: ของแต่ละชิ้นต้องยืนเก็บได้จริง
        room["airdrop_items"][item_id] = {"item": item, "x": ix, "y": iy,
                                          "holder_team": None, "picked_up": False}
    room["airdrop_spawned"] = True
    sio.emit('xroom_airdrop_incoming', {"room_id": room["room_id"], "x": drop_x, "y": drop_y,
                                        "items": [it["name"] for it in picked_items],
                                        "round_seconds_left": max(0, int(room["round_deadline"] - time.time()))
                                            if room["round_deadline"] else None},
             room=_xroom_room_name(room["room_id"]))
    _xroom_broadcast_state(room["room_id"])


@app.route('/api/xroom/<room_id>/airdrop/pickup', methods=['POST'])
@require_auth_toggleable
def api_xroom_airdrop_pickup(room_id):
    """เก็บของชิ้นหนึ่งจาก airdrop — แยกกันคนละ object กับก้อนแมนโดบิกหลักโดยสิ้นเชิง
    (เก็บพร้อมกันได้ ไม่ต้องสละก้อนหลักก่อน) แต่ละชิ้นถือได้ทีละ 1 ทีมเหมือนกัน"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    item_id = data.get("item_id")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "playing":
        return jsonify({"st": "error", "msg": "ยังไม่ถึงช่วงแข่งขัน"}), 409
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    drop = room["airdrop_items"].get(item_id)
    if not drop:
        return jsonify({"st": "error", "msg": "ไม่พบของชิ้นนี้ (อาจถูกเก็บ/exfil ไปแล้ว)"}), 404
    if drop["picked_up"]:
        return jsonify({"st": "error", "msg": "ของชิ้นนี้ถูกเก็บไปแล้ว ใช้ /airdrop/steal ถ้าจะแย่งแทน"}), 409
    drop["holder_team"] = team_no
    drop["picked_up"] = True
    performance_gain = _xroom_add_performance(room, team_no, "airdrop_pickup")
    sio.emit('xroom_airdrop_picked_up', {"room_id": room_id, "item_id": item_id, "team_no": team_no,
                                         "item_name": drop["item"]["name"], "performance_gain": performance_gain},
             room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok"})


@app.route('/api/xroom/<room_id>/airdrop/steal', methods=['POST'])
@require_auth_toggleable
def api_xroom_airdrop_steal(room_id):
    """แย่งของ airdrop ชิ้นหนึ่งจากทีมที่ถืออยู่ — เจ้าของเปลี่ยนทันที เหมือนกติกาก้อนหลัก
    (ทีมเดิมไม่ได้เครดิตของชิ้นนี้ ถ้าทีมที่แย่งไป exfil สำเร็จ ทีมนั้นได้เครดิตแทน)"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    item_id = data.get("item_id")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "playing":
        return jsonify({"st": "error", "msg": "ยังไม่ถึงช่วงแข่งขัน"}), 409
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    drop = room["airdrop_items"].get(item_id)
    if not drop or not drop["picked_up"]:
        return jsonify({"st": "error", "msg": "ยังไม่มีใครถือของชิ้นนี้อยู่ ใช้ /airdrop/pickup แทน"}), 409
    if drop["holder_team"] == team_no:
        return jsonify({"st": "error", "msg": "ทีมตัวเองถืออยู่แล้ว แย่งตัวเองไม่ได้"}), 400
    prev_holder = drop["holder_team"]
    drop["holder_team"] = team_no
    sio.emit('xroom_airdrop_stolen', {"room_id": room_id, "item_id": item_id,
                                      "from_team": prev_holder, "to_team": team_no},
             room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok"})


@app.route('/api/xroom/<room_id>/airdrop/exfil', methods=['POST'])
@require_auth_toggleable
def api_xroom_airdrop_exfil(room_id):
    """ทีมที่ถือของ airdrop ชิ้นนี้อยู่ ออกจาก map สำเร็จ -> ได้เครดิตตามมูลค่าของชิ้นนั้น
    ทันที (จ่ายเข้า P['credits'] แบบเดียวกับระบบเควส/รางวัลอื่นในไฟล์นี้) — ไม่กระทบคะแนน
    แต้มหลัก (score) ของก้อนแมนโดบิก เป็นคนละระบบกัน ไม่ต้องจบรอบตอนนี้"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    item_id = data.get("item_id")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "playing":
        return jsonify({"st": "error", "msg": "ยังไม่ถึงช่วงแข่งขัน"}), 409
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    drop = room["airdrop_items"].get(item_id)
    if not drop or not drop["picked_up"] or drop["holder_team"] != team_no:
        return jsonify({"st": "error", "msg": "ทีมนี้ไม่ได้ถือของชิ้นนี้อยู่ ออกไม่ได้"}), 409
    value = drop["item"]["value"]
    performance_gain = _xroom_add_performance(room, team_no, "airdrop_exfil")
    P["credits"] += value
    del room["airdrop_items"][item_id]
    sio.emit('xroom_airdrop_exfiltrated', {"room_id": room_id, "item_id": item_id, "team_no": team_no,
                                           "item_name": drop["item"]["name"], "value": value,
                                           "performance_gain": performance_gain},
             room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok", "reward_credits": value, "performance_gain": performance_gain})


# ---- ตำแหน่งทีม (สำหรับหน้าจอ lobby แผนที่ใหญ่ / spectator) ----

@app.route('/api/xroom/<room_id>/position', methods=['POST'])
@require_auth_toggleable
def api_xroom_position(room_id):
    """client ของแต่ละทีมยิงตำแหน่งตัวเองมาเป็นระยะระหว่างแข่ง (x, y ตามพิกัด map ที่เลือก
    0..width / 0..height) — ใช้วาดจุด/เส้นทางบนหน้าจอ lobby แผนที่ใหญ่ที่คนดู (ทีมอื่น/ผู้ชม)
    เปิดค้างไว้ระหว่างรอการแข่งขัน (ไม่ใช่ HUD ในเกมจริง ตามที่ตกลง)"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    x, y = float(data.get("x", 0)), float(data.get("y", 0))
    alive = bool(data.get("alive", True))
    room["team_positions"][team_no] = {"x": x, "y": y, "alive": alive, "ts": time.time()}
    sio.emit('xroom_team_moved', {"room_id": room_id, "team_no": team_no, "x": x, "y": y, "alive": alive},
             room=_xroom_room_name(room_id))
    return jsonify({"st": "ok"})


# ---- โหมด C4 (ภารกิจย่อยคู่ขนานกับก้อนแมนโดบิกหลัก ในรอบเดียวกัน) ----
# กติกาตามที่ตกลง: ใช้ระบบ 7 ทีมเดิม, จุดวาง A/B สุ่มใหม่ทุกรอบ (ดู _xroom_start_round),
# ทุกทีมวางได้ทุกทีมกู้ได้ (ไม่มีฝั่งตายตัวแบบ attack/defend) วางสำเร็จได้ 1 แต้มทันที
# กู้ (defuse) สำเร็จได้อีก 1 แต้ม (ทีมที่กู้ไม่จำเป็นต้องเป็นทีมที่วาง) — เป็นคนละคะแนน
# กับก้อนแมนโดบิกหลักโดยสิ้นเชิง ไม่กระทบ/ไม่จบรอบ วางกู้ได้แค่ครั้งเดียวต่อรอบ

@app.route('/api/xroom/<room_id>/c4/plant', methods=['POST'])
@require_auth_toggleable
def api_xroom_c4_plant(room_id):
    """ทีมของ uid วางระเบิด C4 ที่จุด A หรือ B (สุ่มไว้แล้วตอนเริ่มรอบ) — วางสำเร็จได้ 1
    แต้มทันที (ตามที่ตกลง: "วางก็ได้แต้มนะ") วางได้แค่ครั้งเดียวต่อรอบ ไม่ต้องรอ exfil"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    site = str(data.get("site", "")).upper()
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "playing":
        return jsonify({"st": "error", "msg": "ยังไม่ถึงช่วงแข่งขัน"}), 409
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    if room["c4_planted"]:
        return jsonify({"st": "error", "msg": "มีคนวาง C4 ไปแล้วในรอบนี้"}), 409
    if site not in room["c4_sites"]:
        return jsonify({"st": "error", "msg": "จุดวางต้องเป็น A หรือ B เท่านั้น"}), 400
    room["c4_planted"] = True
    room["c4_planted_site"] = site
    room["c4_planted_by_team"] = team_no
    room["c4_planted_ts"] = time.time()
    performance_gain = _xroom_add_performance(room, team_no, "c4_plant")
    room["teams"][team_no]["score"] += 1
    sio.emit('xroom_c4_planted', {"room_id": room_id, "team_no": team_no, "site": site,
                                  "pos": room["c4_sites"][site]},
             room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok", "state": _xroom_public_state(room)})


@app.route('/api/xroom/<room_id>/c4/defuse', methods=['POST'])
@require_auth_toggleable
def api_xroom_c4_defuse(room_id):
    """ทีมของ uid กู้ระเบิด C4 ที่วางอยู่ — ทีมไหนก็กู้ได้หมด รวมถึงทีมที่วางเอง
    (ตามที่ตกลง: "ทุกทีมเลยวางก็ได้แต้มนะ") กู้สำเร็จได้อีก 1 แต้ม กู้ได้แค่ครั้งเดียวต่อรอบ"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "playing":
        return jsonify({"st": "error", "msg": "ยังไม่ถึงช่วงแข่งขัน"}), 409
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    if not room["c4_planted"]:
        return jsonify({"st": "error", "msg": "ยังไม่มีใครวาง C4 ในรอบนี้"}), 409
    if room["c4_defused"]:
        return jsonify({"st": "error", "msg": "มีคนกู้ C4 ไปแล้วในรอบนี้"}), 409
    room["c4_defused"] = True
    room["c4_defused_by_team"] = team_no
    performance_gain = _xroom_add_performance(room, team_no, "c4_defuse")
    room["teams"][team_no]["score"] += 1
    sio.emit('xroom_c4_defused', {"room_id": room_id, "team_no": team_no,
                                  "planted_by_team": room["c4_planted_by_team"],
                                  "site": room["c4_planted_site"]},
             room=_xroom_room_name(room_id))
    _xroom_broadcast_state(room_id)
    return jsonify({"st": "ok", "state": _xroom_public_state(room)})


def _xroom_tick_loop():
    """เธรดพื้นหลังตรวจทุกห้องที่กำลัง 'playing' อยู่ — เช็คว่าถึงเวลาที่สุ่มไว้ให้ airdrop
    ตกหรือยัง (ตามที่ตกลงว่าให้ตกกลางๆ รอบ ไม่ใช่ทันทีตอนเริ่ม) ทำงานคู่กับ watchdog เดิม
    ของไฟล์นี้ (ดู [7. Init] ท้ายไฟล์ที่ลงทะเบียนเธรดนี้ไว้)"""
    while True:
        try:
            now = time.time()
            event_open = _xroom_event_is_open()
            for room in list(XROOM_ROOMS.values()):
                if not event_open and room["phase"] != "finished":
                    # ปิดอีเวนต์ 23:59 — ไม่ให้เริ่มรอบใหม่/เล่นต่อหลังเวลาปิด
                    if room["phase"] == "playing":
                        _xroom_end_round(room, winner_team=None)
                    room["phase"] = "finished"
                    sio.emit("xroom_tournament_closed", {
                        "room_id": room["room_id"],
                        "reason": "event_closed",
                        "event_schedule": _xroom_event_schedule_state(),
                    }, room=_xroom_room_name(room["room_id"]))
                    _xroom_broadcast_state(room["room_id"])
                    continue
                if room["phase"] != "playing":
                    continue
                _xroom_expire_special_extractions(room, now)

                if room.get("bead_spawn_at") and not room.get("bead_spawned") and now >= room["bead_spawn_at"]:
                    _xroom_spawn_mando(room)

                # หมด 18 นาที = จบรอบอัตโนมัติ ถ้ายังไม่มีใคร exfil
                if room.get("round_deadline") and now >= room["round_deadline"]:
                    _xroom_end_round(room, winner_team=None)
                    continue
                for lid, loot in list(room.get("combat_loot", {}).items()):
                    if now - loot.get("created_at", now) >= XROOM_COMBAT_LOOT_TTL_SEC:
                        room["combat_loot"].pop(lid, None)
                if room["airdrop_will_spawn"] and not room["airdrop_spawned"] \
                        and room["airdrop_spawn_ts"] and now >= room["airdrop_spawn_ts"]:
                    _xroom_spawn_airdrop(room)
        except Exception as e:
            print(f"[xroom] tick loop error (ไม่กระทบห้องอื่น รอบหน้าทำงานต่อ): {e}")
        time.sleep(1)


# ---- Reward claim (ต้องเล่นครบจำนวนรอบก่อน) ----

@app.route('/api/xroom/<room_id>/reward/claim', methods=['POST'])
@require_auth_toggleable
def api_xroom_reward_claim(room_id):
    """เคลมของรางวัลได้เมื่อเล่นครบ rounds_required แล้วเท่านั้น — จ่ายรางวัลตามอันดับ
    คะแนนของทีมตัวเองในห้องนี้ (ทีมคะแนนสูงสุดได้เยอะสุด) ใช้ P['credits'] + _shards_add
    แบบเดียวกับระบบเควส [8c] เพื่อให้ของรางวัลไปโผล่ในกระเป๋าเดียวกับที่อื่นในเกม"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    team_no = room["team_of_uid"].get(uid)
    if team_no is None:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    if room["rounds_played"] < room["rounds_required"]:
        return jsonify({"st": "error",
                        "msg": f"ต้องเล่นให้ครบ {room['rounds_required']} รอบก่อน "
                                f"(เล่นไปแล้ว {room['rounds_played']} รอบ)"}), 409
    if room["claimed_reward"]:
        return jsonify({"st": "error", "msg": "ห้องนี้เคลมของรางวัลไปแล้ว"}), 409
    ranking = sorted(room["teams"].items(), key=lambda kv: kv[1]["score"], reverse=True)
    rank_index = next(i for i, (tno, _) in enumerate(ranking) if tno == team_no)
    reward_table = [500, 350, 250, 180, 130, 90, 60]  # อันดับ 1-7 ในห้อง (เยอะสุด -> น้อยสุด)
    credits_reward = reward_table[min(rank_index, len(reward_table) - 1)]
    shards_reward = max(1, (XROOM_MAX_TEAMS - rank_index))
    room["claimed_reward"] = True
    P["credits"] += credits_reward
    _shards_add(uid, shards_reward)
    return jsonify({"st": "ok", "rank_in_room": rank_index + 1, "reward_credits": credits_reward,
                    "reward_shards": shards_reward,
                    "msg": f"อันดับ {rank_index + 1} ในห้อง — รับ {credits_reward} เครดิต, "
                            f"{shards_reward} Elemental Shard"})


@app.route('/api/xroom/schedule')
def api_xroom_schedule():
    return jsonify({"st": "ok", "schedule": _xroom_event_schedule_state()})


@app.route('/api/xroom/<room_id>/state')
def api_xroom_state(room_id):
    room = XROOM_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    return jsonify({"st": "ok", "state": _xroom_public_state(room)})


