# ==========================================
# [ 6zzz. Esports Hub — ห้องแข่งขันสำหรับเกมอื่นๆ ในไฟล์นี้ ]
# [UPGRADE] วิเคราะห์ก่อนทำ (ตามที่ขอ): xroom_tournament ด้านบนใช้ได้เพราะโหมดแย่งก้อน/C4
# เป็นเกม "หลายทีมแข่งพร้อมกันแบบ realtime บนแมพเดียวกัน" (มีตำแหน่ง x/y ที่ต้อง sync สด)
# แต่เกมอื่นในไฟล์นี้ (มาห์จอง, ตกปลา, killer/survivor, banquet) ไม่ใช่แบบนั้น — แต่ละคน
# เล่น "เซสชันของตัวเอง" แยกกัน ไม่มีแมพ/ตำแหน่งร่วมให้ sync สด ดังนั้นรูปแบบห้องแข่งขันที่
# เข้ากับเกมกลุ่มนี้จริงๆ คือ "ห้องแข่งแบบ derby/leaderboard": ตั้งเวลาแข่งไว้ช่วงหนึ่ง (เช่น
# 15-30 นาที) ทุกคนไปเล่นเกมของตัวเอง (โต๊ะมาห์จองของตัวเอง/บ่อตกปลาของตัวเอง/แมตช์
# killer-survivor ของตัวเอง) แล้วส่ง "คะแนนที่ทำได้" เข้ามาเทียบกันในห้องเดียวกัน ณ ตอนจบ
# เวลา ใครคะแนนสูงสุดชนะ — ใช้แพทเทิร์นเดียวกับ xroom (room/phase/host/reward table) แต่
# ตัดส่วน realtime position ออก เพราะเกมกลุ่มนี้ไม่ต้องการ
#
# นิยาม "คะแนน" ของแต่ละเกม (ให้ client เป็นคนคำนวณแล้วส่งเข้ามา เหมือนแพทเทิร์น
# /api/xroom/<room_id>/position ที่เชื่อค่าจาก client อยู่แล้วในไฟล์นี้ — ไม่ใช่ authoritative
# ทุกจุด แต่ยิงเข้า Central Anti-Cheat Hub ที่มีอยู่แล้ว [6j0] ถ้าคะแนนดูสูงผิดปกติเทียบค่าเฉลี่ย
# ห้อง กันสเปคคนโกงชัดๆ แบบเดียวกับที่ fire-rate check ทำอยู่แล้ว):
#   - mahjong          -> แต้มรวมสุดท้ายจากโต๊ะ (อ่านจาก /api/mahjong/state ตอนกด
#                          /api/mahjong/session/end แล้วส่งเลขนั้นเข้ามา)
#   - fishing_derby    -> มูลค่าปลาที่ขาย (บวกสะสม) ผ่าน /api/fishing/sell ภายในช่วงเวลาแข่ง
#   - killer_survivor  -> คะแนนสะสมจากหลายแมตช์ในช่วงเวลาแข่ง (escape สำเร็จ +1,
#                          กำจัดผู้รอดชีวิตได้ (ฝั่งฆาตกร) +1 ต่อคน)
#   - banquet_rush     -> ทิปรวม/คอมโบสูงสุดที่ทำได้จาก banquet minigame ภายในช่วงเวลาแข่ง
# เพิ่มเกมใหม่ในอนาคตแค่เพิ่ม entry ใน ESPORTS_GAME_TYPES ด้านล่าง ไม่ต้องแก้ logic ห้อง
# ==========================================

ESPORTS_GAME_TYPES = {
    "mahjong": {
        "name": "Mahjong Table Rush",
        "score_desc": "แต้มรวมสุดท้ายจากโต๊ะมาห์จอง (ส่งค่าตอนกด /api/mahjong/session/end)",
        "default_duration_sec": 1800,
    },
    "fishing_derby": {
        "name": "Fishing Derby",
        "score_desc": "มูลค่าปลาที่ขายได้สะสมระหว่างแข่ง (ผ่าน /api/fishing/sell)",
        "default_duration_sec": 900,
    },
    "killer_survivor": {
        "name": "Killer/Survivor Ladder",
        "score_desc": "คะแนนสะสมจากหลายแมตช์ (escape สำเร็จ / กำจัดผู้รอดชีวิตได้) ระหว่างแข่ง",
        "default_duration_sec": 1800,
    },
    "banquet_rush": {
        "name": "Banquet Rush",
        "score_desc": "ทิปรวม/คอมโบสูงสุดจาก banquet minigame ระหว่างแข่ง",
        "default_duration_sec": 600,
    },
}
ESPORTS_MAX_PLAYERS_DEFAULT = 32
ESPORTS_REWARD_TABLE = [500, 350, 250, 180, 130, 90, 60, 40]  # อันดับ 1-8, ต่ำกว่านั้นได้เท่าอันดับ 8
ESPORTS_SUSPICIOUS_SCORE_MULTIPLIER = 5  # ส่งเข้า anti-cheat hub ถ้าคะแนนสูงกว่าค่าเฉลี่ยห้อง x เท่านี้ (อย่างน้อย 3 คนส่งแล้ว)

ESPORTS_ROOMS = {}     # room_id -> state
ESPORTS_SID_ROOM = {}  # sid -> room_id (สำหรับ socket subscribe แบบเดียวกับ xroom_watch)


def _esports_room_name(room_id: str) -> str:
    return f"esports:{room_id}"


def _esports_new_room(room_id, host_uid, game_type, name, duration_sec, max_players):
    return {
        "room_id": room_id,
        "host_uid": host_uid,
        "game_type": game_type,
        "name": name or ESPORTS_GAME_TYPES[game_type]["name"],
        "phase": "lobby",   # lobby -> playing -> finished
        "max_players": max_players,
        "players": {},      # uid -> {"name","score","submitted_at"}
        "duration_sec": duration_sec,
        "start_ts": None,
        "deadline": None,
        "created_ts": time.time(),
        "reward_claimed": {},   # uid -> True
    }


def _esports_public_state(room):
    ranking = sorted(room["players"].items(), key=lambda kv: kv[1]["score"], reverse=True)
    now = time.time()
    return {
        "room_id": room["room_id"], "host_uid": room["host_uid"], "game_type": room["game_type"],
        "name": room["name"], "phase": room["phase"], "max_players": room["max_players"],
        "players": room["players"],
        "leaderboard": [{"uid": uid, "score": p["score"]} for uid, p in ranking],
        "duration_sec": room["duration_sec"],
        "seconds_left": max(0, int(room["deadline"] - now)) if room["phase"] == "playing" and room["deadline"] else None,
    }


def _esports_broadcast_state(room_id):
    room = ESPORTS_ROOMS.get(room_id)
    if room:
        sio.emit('esports_room_state', _esports_public_state(room), room=_esports_room_name(room_id))


@app.route('/api/esports/game_types')
def api_esports_game_types():
    """รายชื่อเกมที่เปิดห้องแข่งขันแบบ derby/leaderboard ได้ตอนนี้ พร้อมคำอธิบายว่าคะแนนคิดจากอะไร"""
    return jsonify({"st": "ok", "game_types": ESPORTS_GAME_TYPES})


@app.route('/api/esports/create', methods=['POST'])
@require_auth_toggleable
def api_esports_create():
    """body: {uid, game_type, name?, duration_sec?, max_players?} -> สร้างห้องแข่งขันใหม่
    ผู้สร้างเป็น host โดยอัตโนมัติ และถือเป็นผู้เล่นคนแรกในห้องด้วย"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    game_type = data.get("game_type")
    if not uid:
        return jsonify({"st": "error", "msg": "ต้องระบุ uid"}), 400
    if game_type not in ESPORTS_GAME_TYPES:
        return jsonify({"st": "error", "msg": f"game_type ต้องเป็นหนึ่งใน {list(ESPORTS_GAME_TYPES)}"}), 400
    duration_sec = int(data.get("duration_sec") or ESPORTS_GAME_TYPES[game_type]["default_duration_sec"])
    max_players = int(data.get("max_players") or ESPORTS_MAX_PLAYERS_DEFAULT)
    room_id = uuid.uuid4().hex[:8]
    room = _esports_new_room(room_id, uid, game_type, data.get("name"), duration_sec, max_players)
    room["players"][uid] = {"name": data.get("player_name", uid), "score": 0, "submitted_at": None}
    ESPORTS_ROOMS[room_id] = room
    return jsonify({"st": "ok", "room_id": room_id, "state": _esports_public_state(room)})


@app.route('/api/esports/<room_id>/join', methods=['POST'])
@require_auth_toggleable
def api_esports_join(room_id):
    """body: {uid, player_name?} -> เข้าห้องที่มีอยู่แล้ว เข้าได้เฉพาะตอน phase == lobby เท่านั้น"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = ESPORTS_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if uid in room["players"]:
        return jsonify({"st": "ok", "state": _esports_public_state(room)})  # เข้าซ้ำ ไม่ error
    if room["phase"] != "lobby":
        return jsonify({"st": "error", "msg": "ห้องนี้เริ่มแข่งไปแล้ว เข้าร่วมไม่ได้"}), 409
    if len(room["players"]) >= room["max_players"]:
        return jsonify({"st": "error", "msg": f"ห้องเต็มแล้ว (สูงสุด {room['max_players']} คน)"}), 409
    room["players"][uid] = {"name": data.get("player_name", uid), "score": 0, "submitted_at": None}
    _esports_broadcast_state(room_id)
    return jsonify({"st": "ok", "state": _esports_public_state(room)})


@sio.on('esports_watch')
def _on_esports_watch(data):
    """client เรียกหลัง create/join สำเร็จ เพื่อ subscribe realtime update ของห้องนี้ —
    แนวทางเดียวกับ xroom_watch"""
    data = data or {}
    sid = request.sid
    room_id = str(data.get("room_id", ""))
    if not room_id or room_id not in ESPORTS_ROOMS:
        return
    prev = ESPORTS_SID_ROOM.get(sid)
    if prev and prev != room_id:
        leave_room(_esports_room_name(prev))
    join_room(_esports_room_name(room_id))
    ESPORTS_SID_ROOM[sid] = room_id
    sio.emit('esports_room_state', _esports_public_state(ESPORTS_ROOMS[room_id]), room=sid)


def _esports_cleanup_sid(sid: str):
    room_id = ESPORTS_SID_ROOM.pop(sid, None)
    if room_id:
        leave_room(_esports_room_name(room_id))


@app.route('/api/esports/<room_id>/start', methods=['POST'])
@require_auth_toggleable
def api_esports_start(room_id):
    """เฉพาะ host เท่านั้นที่เริ่มห้องได้ — ตั้งเวลานับถอยหลัง duration_sec ของห้องนี้ แล้ว
    ทุกคนแยกไปเล่นเกมของตัวเองได้เลย ส่งคะแนนกลับมาผ่าน /submit_score ระหว่างที่ยังไม่หมดเวลา"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = ESPORTS_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if uid != room["host_uid"]:
        return jsonify({"st": "error", "msg": "เฉพาะ host เท่านั้นที่เริ่มห้องได้"}), 403
    if room["phase"] != "lobby":
        return jsonify({"st": "error", "msg": "ห้องนี้เริ่มไปแล้ว หรือจบไปแล้ว"}), 409
    if len(room["players"]) < 1:
        return jsonify({"st": "error", "msg": "ต้องมีผู้เล่นอย่างน้อย 1 คน"}), 400
    room["phase"] = "playing"
    room["start_ts"] = time.time()
    room["deadline"] = room["start_ts"] + room["duration_sec"]
    sio.emit('esports_started', {"room_id": room_id, "game_type": room["game_type"],
                                 "duration_sec": room["duration_sec"]},
             room=_esports_room_name(room_id))
    _esports_broadcast_state(room_id)
    return jsonify({"st": "ok", "state": _esports_public_state(room)})


@app.route('/api/esports/<room_id>/submit_score', methods=['POST'])
@require_auth_toggleable
def api_esports_submit_score(room_id):
    """body: {uid, score} -> ส่งคะแนนที่ทำได้เข้ามาเทียบในห้อง (เก็บเฉพาะคะแนน "สูงสุด" ที่เคย
    ส่งมา ไม่ใช่บวกทับ — กันส่งซ้ำหลายรอบแล้วคะแนนพุ่งเกินจริง) เรียกได้เรื่อยๆ ระหว่างที่ยังไม่
    หมดเวลาห้อง [UPGRADE] ถ้าคะแนนที่ส่งมาสูงผิดปกติเทียบค่าเฉลี่ยห้อง (มีคนส่งแล้ว >= 3 คน) จะ
    ยื่นรายงานเข้า Central Anti-Cheat Hub ที่มีอยู่แล้ว [6j0] ให้แอดมินตรวจ (ไม่ได้บล็อกคะแนนอัตโนมัติ
    เพราะเกมกลุ่มนี้ไม่มีทางตรวจสอบฝั่ง server ได้ 100% อยู่แล้ว แค่ยื่นให้ทบทวน)"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = ESPORTS_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "playing":
        return jsonify({"st": "error", "msg": "ห้องนี้ไม่ได้อยู่ในช่วงแข่งขัน"}), 409
    if uid not in room["players"]:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    try:
        score = float(data.get("score", 0))
    except (TypeError, ValueError):
        return jsonify({"st": "error", "msg": "score ต้องเป็นตัวเลข"}), 400
    if score < 0:
        return jsonify({"st": "error", "msg": "score ต้องไม่ติดลบ"}), 400
    others = [p["score"] for other_uid, p in room["players"].items()
              if other_uid != uid and p["submitted_at"] is not None]
    if len(others) >= 3:
        avg = sum(others) / len(others)
        if avg > 0 and score > avg * ESPORTS_SUSPICIOUS_SCORE_MULTIPLIER:
            submit_cheat_report(uid, f"esports:{room['game_type']}", "esports_score_anomaly",
                                {"room_id": room_id, "score": score, "room_avg": avg})
    room["players"][uid]["score"] = max(room["players"][uid]["score"], score)
    room["players"][uid]["submitted_at"] = time.time()
    sio.emit('esports_score_submitted', {"room_id": room_id, "uid": uid,
                                         "score": room["players"][uid]["score"]},
             room=_esports_room_name(room_id))
    _esports_broadcast_state(room_id)
    return jsonify({"st": "ok", "state": _esports_public_state(room)})


def _esports_finish_room(room):
    """ปิดห้อง — ล็อกอันดับสุดท้ายไว้ ให้เคลมของรางวัลได้ต่อจากนี้"""
    room["phase"] = "finished"
    sio.emit('esports_finished', {"room_id": room["room_id"],
                                  "leaderboard": _esports_public_state(room)["leaderboard"]},
             room=_esports_room_name(room["room_id"]))
    _esports_broadcast_state(room["room_id"])


@app.route('/api/esports/<room_id>/finish', methods=['POST'])
@require_auth_toggleable
def api_esports_finish(room_id):
    """host กดปิดห้องก่อนเวลาได้ (เช่น ทุกคนส่งคะแนนครบแล้ว) — ถ้ายังไม่หมดเวลาและไม่ใช่
    host เรียก จะโดนปฏิเสธ (รอ _esports_tick_loop ปิดอัตโนมัติตอนหมดเวลาแทน)"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = ESPORTS_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if room["phase"] != "playing":
        return jsonify({"st": "error", "msg": "ห้องนี้ไม่ได้อยู่ในช่วงแข่งขัน"}), 409
    if uid != room["host_uid"] and time.time() < (room["deadline"] or 0):
        return jsonify({"st": "error", "msg": "ยังไม่หมดเวลา เฉพาะ host กดปิดก่อนเวลาได้"}), 403
    _esports_finish_room(room)
    return jsonify({"st": "ok", "state": _esports_public_state(room)})


@app.route('/api/esports/<room_id>/reward/claim', methods=['POST'])
@require_auth_toggleable
def api_esports_reward_claim(room_id):
    """เคลมของรางวัลได้เมื่อห้อง finished แล้วเท่านั้น จ่ายตามอันดับใน leaderboard ของห้องนี้
    (แพทเทิร์นเดียวกับ /api/xroom/<room_id>/reward/claim) เคลมได้คนละครั้งเดียวต่อห้อง"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid")
    room = ESPORTS_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    if uid not in room["players"]:
        return jsonify({"st": "error", "msg": "ไม่ได้อยู่ในห้องนี้"}), 403
    if room["phase"] != "finished":
        return jsonify({"st": "error", "msg": "ห้องนี้ยังไม่จบการแข่งขัน"}), 409
    if room["reward_claimed"].get(uid):
        return jsonify({"st": "error", "msg": "เคลมของรางวัลไปแล้ว"}), 409
    ranking = sorted(room["players"].items(), key=lambda kv: kv[1]["score"], reverse=True)
    rank_index = next(i for i, (u, _) in enumerate(ranking) if u == uid)
    credits_reward = ESPORTS_REWARD_TABLE[min(rank_index, len(ESPORTS_REWARD_TABLE) - 1)]
    shards_reward = max(1, (len(ESPORTS_REWARD_TABLE) - rank_index))
    room["reward_claimed"][uid] = True
    P["credits"] += credits_reward
    _shards_add(uid, shards_reward)
    return jsonify({"st": "ok", "rank_in_room": rank_index + 1, "reward_credits": credits_reward,
                    "reward_shards": shards_reward,
                    "msg": f"อันดับ {rank_index + 1} ในห้อง — รับ {credits_reward} เครดิต, "
                            f"{shards_reward} Elemental Shard"})


@app.route('/api/esports/<room_id>/state')
def api_esports_state(room_id):
    room = ESPORTS_ROOMS.get(room_id)
    if not room:
        return jsonify({"st": "error", "msg": "ไม่พบห้องนี้"}), 404
    return jsonify({"st": "ok", "state": _esports_public_state(room)})


def _esports_tick_loop():
    """เธรดพื้นหลังตรวจทุกห้องที่กำลัง 'playing' อยู่ — ปิดห้องอัตโนมัติทันทีที่หมดเวลา
    (ทำงานคู่กับ watchdog เดิมของไฟล์นี้ แนวทางเดียวกับ _xroom_tick_loop ด้านบน)"""
    while True:
        try:
            now = time.time()
            for room in list(ESPORTS_ROOMS.values()):
                if room["phase"] == "playing" and room["deadline"] and now >= room["deadline"]:
                    _esports_finish_room(room)
        except Exception as e:
            print(f"[esports] tick loop error (ไม่กระทบห้องอื่น รอบหน้าทำงานต่อ): {e}")
        time.sleep(1)


