def api_phone_repair_use_tool(ticket_id):
    """body: {uid, tool_id} -> ลองใช้เครื่องมือกับบอร์ด — ถ้าเป็นเครื่องมือที่ยังไม่เคยใช้และตรง
    กับอาการ current_draw จะขยับเข้าใกล้ 0 (ซ่อมคืบหน้า) ถ้าใช้ผิด (ไม่ตรงอาการ) current_draw
    จะแกว่งขึ้น (เสียหายเพิ่ม) และนับเป็นการใช้ผิด 1 ครั้ง"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid", P["uid"])
    tool_id = data.get("tool_id")
    session = PHONE_REPAIR_SESSIONS.get(uid)
    if not session or session["ticket_id"] != ticket_id:
        return jsonify({"st": "error", "msg": "ไม่พบตั๋วซ่อมนี้ (อาจหมดอายุหรือส่งผลไปแล้ว)"}), 404
    if tool_id not in PHONE_REPAIR_TOOLS:
        return jsonify({"st": "error", "msg": "ไม่มีเครื่องมือนี้ในโต๊ะซ่อม"}), 400
    fault = PHONE_REPAIR_FAULTS[session["fault_id"]]
    if tool_id in session["tools_used"]:
        return jsonify({"st": "ok", "current_draw": round(session["current_draw"], 2),
                        "msg": "ใช้เครื่องมือนี้ไปแล้ว ลองอันอื่นดู"})
    session["tools_used"].add(tool_id)
    if tool_id in fault["correct_tools"]:
        progress_step = fault["symptom_current_draw"] / max(1, len(fault["correct_tools"]))
        session["current_draw"] = max(0.0, session["current_draw"] - progress_step)
        correct = True
    else:
        session["current_draw"] += 0.35
        session["wrong_tool_count"] += 1
        correct = False
    return jsonify({"st": "ok", "correct": correct, "current_draw": round(session["current_draw"], 2),
                    "wrong_tool_count": session["wrong_tool_count"]})


@app.route('/api/event/phone-repair/ticket/<ticket_id>/hint', methods=['POST'])
@require_auth_toggleable
def api_phone_repair_hint(ticket_id):
    """ให้ AI TERMINAL เฉลยเครื่องมือที่ยังไม่ได้ใช้ 1 ชิ้น — ฟรีครั้งแรกของตั๋ว จากนั้นหักแต้ม
    PHONE_REPAIR_HINT_COST ต่อครั้ง (ถ้าแต้มไม่พอและใช้ฟรีไปแล้ว ขอเพิ่มไม่ได้)"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid", P["uid"])
    session = PHONE_REPAIR_SESSIONS.get(uid)
    if not session or session["ticket_id"] != ticket_id:
        return jsonify({"st": "error", "msg": "ไม่พบตั๋วซ่อมนี้"}), 404
    fault = PHONE_REPAIR_FAULTS[session["fault_id"]]
    remaining = list(fault["correct_tools"] - session["tools_used"])
    if not remaining:
        return jsonify({"st": "error", "msg": "ใช้เครื่องมือที่ถูกต้องครบแล้ว กด submit ได้เลย"}), 409
    if session["hint_used"]:
        if _phone_repair_points(uid) < PHONE_REPAIR_HINT_COST:
            return jsonify({"st": "error", "msg": f"แต้มอีเว้นท์ไม่พอ (ต้องการ {PHONE_REPAIR_HINT_COST})"}), 402
        PHONE_REPAIR_EVENT_POINTS[uid] = _phone_repair_points(uid) - PHONE_REPAIR_HINT_COST
    else:
        session["hint_used"] = True   # ครั้งแรกฟรี
    hint_tool = random.choice(remaining)
    return jsonify({"st": "ok", "hint_tool": hint_tool, "hint_tool_name": PHONE_REPAIR_TOOLS[hint_tool]["name"],
                    "event_points": _phone_repair_points(uid)})


@app.route('/api/event/phone-repair/ticket/<ticket_id>/submit', methods=['POST'])
@require_auth_toggleable
def api_phone_repair_submit(ticket_id):
    """body: {uid} -> ปิดตั๋ว ตัดสินผล: ผ่านถ้าใช้เครื่องมือที่ถูกต้องครบชุด และใช้เครื่องมือผิด
    ไม่เกิน PHONE_REPAIR_WRONG_TOOL_TOLERANCE ครั้ง — ผ่านได้แต้มอีเว้นท์ตาม reward_points ของ
    อาการนั้น ไม่ผ่านไม่ได้แต้ม (แต่ไม่เสียอะไรเพิ่ม) ปิดตั๋วไปแล้วเปิดใหม่ได้ทันที"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid", P["uid"])
    session = PHONE_REPAIR_SESSIONS.get(uid)
    if not session or session["ticket_id"] != ticket_id:
        return jsonify({"st": "error", "msg": "ไม่พบตั๋วซ่อมนี้"}), 404
    fault = PHONE_REPAIR_FAULTS[session["fault_id"]]
    used_all_correct = fault["correct_tools"].issubset(session["tools_used"])
    within_tolerance = session["wrong_tool_count"] <= PHONE_REPAIR_WRONG_TOOL_TOLERANCE
    success = used_all_correct and within_tolerance
    reward_points = fault["reward_points"] if success else 0
    if success:
        PHONE_REPAIR_EVENT_POINTS[uid] = _phone_repair_points(uid) + reward_points
    del PHONE_REPAIR_SESSIONS[uid]
    return jsonify({"st": "ok", "success": success, "reward_points": reward_points,
                    "event_points": _phone_repair_points(uid),
                    "msg": "ซ่อมสำเร็จ! อุปกรณ์กลับมาใช้งานได้ปกติ" if success else
                           "ซ่อมไม่ผ่าน — ใช้เครื่องมือไม่ครบ หรือใช้ผิดเกินกำหนด ลองตั๋วใหม่ดู"})


@app.route('/api/event/phone-repair/redeem', methods=['POST'])
@require_auth_toggleable
def api_phone_repair_redeem():
    """body: {uid, prize_id} -> แลกของรางวัลด้วยแต้มอีเว้นท์ที่สะสมไว้"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid", P["uid"])
    prize = next((p for p in PHONE_REPAIR_PRIZES if p["id"] == data.get("prize_id")), None)
    if not prize:
        return jsonify({"st": "error", "msg": "ไม่พบของรางวัลนี้"}), 404
    if _phone_repair_points(uid) < prize["cost_points"]:
        return jsonify({"st": "error", "msg": f"แต้มอีเว้นท์ไม่พอ (ต้องการ {prize['cost_points']})"}), 402
    PHONE_REPAIR_EVENT_POINTS[uid] = _phone_repair_points(uid) - prize["cost_points"]
    reward = prize["reward"]
    if "credits" in reward:
        P["credits"] += reward["credits"]
    if "shards" in reward:
        _shards_add(uid, reward["shards"])
    if "inventory_item" in reward:
        inv = INVENTORY.setdefault(uid, {})
        inv[reward["inventory_item"]] = inv.get(reward["inventory_item"], 0) + 1
    return jsonify({"st": "ok", "event_points": _phone_repair_points(uid), "received": reward})


