# ==========================================
# [ 6zzzzz. Web Shop — สั่งซื้อหน้าเว็บ + แยกเส้นทางจัดส่ง (Extraction / Instant Mailbox) ]
# [UPGRADE] วิเคราะห์ตามที่ขอ: เว็บไซต์ตัดเงินเองนอกเกม ระบบนี้แค่รับ "คำสั่งซื้อที่จ่ายแล้ว"
# เข้ามาผูกกับ uid ในเกม จากนั้นเลือกเส้นทางส่งของ 2 แบบ:
#   A) Extraction — ของไปสปอว์นในแผนที่ (เลือกจาก XROOM_MAP_POOL เดิมที่มีอยู่แล้ว เพื่อให้ใช้
#      แผนที่จริงที่มีอยู่ในเกม ไม่ต้องสร้างแผนที่ใหม่) ผู้เล่นต้องเข้าไปเก็บ (pickup) แล้ว "หนีออก
#      จากแผนที่" (extract) ให้สำเร็จของถึงเข้าคลังหลักจริง — มีเวลาจำกัดให้ไปเก็บ (TTL) ถ้าไม่ทัน
#      ของหมดอายุ (ต้องให้เว็บไซต์ทำเรื่องคืนของ/ออกให้ใหม่เอง ระบบนี้แค่แจ้งสถานะ)
#   B) Instant Mailbox — ของเข้ากล่องจดหมายทันที ปลอดภัย 100% ผู้เล่นเปิดเกมมากด "รับของ" เข้า
#      คลังได้เลย ไม่มีขั้นตอนเสี่ยงอะไร
# ไม่ว่าจะเลือกแบบไหน สถานะออเดอร์จะอัปเดตทุกครั้งที่มีการเปลี่ยนแปลง (spawn/pickup/extract/
# claim) และยิง socket event ออกไปให้ฝั่งเว็บไซต์/เกม sync กันแบบสด (เว็บไซต์ที่ไม่ได้ต่อ socket
# ไว้ก็ยัง poll get-status เอาได้ตามปกติ)
# ⚠️ Production จริงต้องตรวจลายเซ็น/secret จากเว็บก่อนเชื่อ order/create เหมือนกับ
# /api/shop/topup-callback ด้านบน ไม่งั้นใครก็ยิง API มาแกล้งสร้างออเดอร์ปลอมได้
# ==========================================

WEBSHOP_ITEMS = {
    "item_railgun_skin_eclipse": {"name": "Hyper Railgun Skin: Eclipse",  "delivery_methods": ["extraction", "mailbox"]},
    "item_contraband_case":      {"name": "Contraband Supply Case",       "delivery_methods": ["extraction"]},  # หายาก ต้องเสี่ยงไปเก็บเองเท่านั้น
    "item_outfit_voidwalker":    {"name": "Void Walker Outfit",           "delivery_methods": ["extraction", "mailbox"]},
    "item_battle_pass_token":    {"name": "Battle Pass Token",            "delivery_methods": ["mailbox"]},     # ของดิจิทัลล้วน ปลอดภัยอย่างเดียวพอ
}

WEBSHOP_EXTRACTION_DROP_TTL_SEC = 30 * 60   # ของที่สปอว์นในแผนที่ ต้องไปเก็บให้ทันภายในกี่วิ ก่อนหมดอายุ

WEBSHOP_ORDERS = {}             # order_id -> {uid, item_id, delivery_method, status, drop_id, mail_id, created_ts}
WEBSHOP_EXTRACTION_DROPS = {}   # drop_id -> {order_id, uid, map_id, x, y, status, expires_ts}
WEBSHOP_MAILBOX = {}            # uid -> [{mail_id, order_id, item_id, claimed}]


def _webshop_room_name(uid: str) -> str:
    return f"webshop:{uid}"


def _webshop_set_status(order, status):
    order["status"] = status
    sio.emit('webshop_order_status', {"order_id": order["order_id"], "status": status,
                                      "item_id": order["item_id"]},
             room=_webshop_room_name(order["uid"]))


@app.route('/api/webshop/items')
def api_webshop_items():
    """แคตตาล็อกไอเทมที่ซื้อได้บนเว็บไซต์ พร้อมบอกว่าไอเทมไหนเลือกวิธีส่งแบบไหนได้บ้าง"""
    return jsonify({"st": "ok", "items": WEBSHOP_ITEMS})


@app.route('/api/webshop/order/create', methods=['POST'])
@require_auth
def api_webshop_order_create():
    """เว็บไซต์เรียก endpoint นี้ "หลังตัดเงินสำเร็จแล้วเท่านั้น" (แนวทางเดียวกับ
    /api/shop/topup-callback ด้านบน) body: {uid, item_id, order_id, delivery_method}
    - delivery_method == "mailbox"    -> ส่งเข้ากล่องจดหมายทันที (WEBSHOP_MAILBOX)
    - delivery_method == "extraction" -> สุ่มแผนที่+จุดสปอว์นจาก XROOM_MAP_POOL ผู้เล่นต้อง
      pickup แล้ว extract เองถึงจะได้ของจริง"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid", P["uid"])
    item_id = data.get("item_id")
    order_id = data.get("order_id") or uuid.uuid4().hex[:10]
    delivery_method = data.get("delivery_method")
    item = WEBSHOP_ITEMS.get(item_id)
    if not item:
        return jsonify({"st": "error", "msg": "ไม่พบไอเทมนี้ในแคตตาล็อก"}), 404
    if order_id in WEBSHOP_ORDERS:
        return jsonify({"st": "error", "msg": "order_id นี้ถูกใช้ไปแล้ว (กันสร้างของซ้ำ)"}), 409
    if delivery_method not in item["delivery_methods"]:
        return jsonify({"st": "error", "msg": f"ไอเทมนี้เลือกวิธีส่งแบบ '{delivery_method}' ไม่ได้ "
                                              f"(ส่งได้แค่: {item['delivery_methods']})"}), 400

    order = {"order_id": order_id, "uid": uid, "item_id": item_id, "delivery_method": delivery_method,
              "status": "pending", "drop_id": None, "mail_id": None, "created_ts": time.time()}
    WEBSHOP_ORDERS[order_id] = order

    if delivery_method == "mailbox":
        mail_id = uuid.uuid4().hex[:8]
        WEBSHOP_MAILBOX.setdefault(uid, []).append(
            {"mail_id": mail_id, "order_id": order_id, "item_id": item_id, "claimed": False})
        order["mail_id"] = mail_id
        _webshop_set_status(order, "delivered_to_mailbox")
        return jsonify({"st": "ok", "order_id": order_id, "delivery_method": "mailbox", "mail_id": mail_id,
                        "msg": "ส่งเข้ากล่องจดหมายแล้ว เปิดเกมแล้วกดรับของได้เลย"})

    # delivery_method == "extraction"
    chosen_map = random.choice(XROOM_MAP_POOL)
    drop_id = uuid.uuid4().hex[:8]
    WEBSHOP_EXTRACTION_DROPS[drop_id] = {
        "drop_id": drop_id, "order_id": order_id, "uid": uid, "map_id": chosen_map["id"],
        **_vmax_map_xy_dict(chosen_map["id"], random.uniform(0, chosen_map["width"]), random.uniform(0, chosen_map["height"])),
        "status": "spawned", "expires_ts": time.time() + WEBSHOP_EXTRACTION_DROP_TTL_SEC,
    }
    order["drop_id"] = drop_id
    _webshop_set_status(order, "spawned_in_map")
    return jsonify({"st": "ok", "order_id": order_id, "delivery_method": "extraction", "drop_id": drop_id,
                    "map_id": chosen_map["id"], "map_name": chosen_map["name"],
                    "expires_in_sec": WEBSHOP_EXTRACTION_DROP_TTL_SEC,
                    "msg": f"ของไปสปอว์นที่แผนที่ {chosen_map['name']} แล้ว ไปเก็บแล้วหนีออกจากแผนที่ให้ทัน"})


@app.route('/api/webshop/order/<order_id>/status')
def api_webshop_order_status(order_id):
    """ให้เว็บไซต์ poll เช็คสถานะออเดอร์ได้ตลอด (เผื่อไม่ได้ต่อ socket ไว้) —
    เพื่อ sync ข้อมูลหลังบ้านระหว่างเว็บไซต์กับเซิร์ฟเวอร์เกมตามที่ตกลง"""
    order = WEBSHOP_ORDERS.get(order_id)
    if not order:
        return jsonify({"st": "error", "msg": "ไม่พบออเดอร์นี้"}), 404
    return jsonify({"st": "ok", "order": order})


@sio.on('webshop_watch')
def _on_webshop_watch(data):
    """client subscribe ห้องแจ้งเตือนออเดอร์ของ uid ตัวเอง เพื่อรับ webshop_order_status สด
    แนวทางเดียวกับ xroom_watch/esports_watch"""
    data = data or {}
    uid = data.get("uid")
    if not uid:
        return
    join_room(_webshop_room_name(uid))


@app.route('/api/webshop/delivery/<drop_id>/pickup', methods=['POST'])
@require_auth
def api_webshop_delivery_pickup(drop_id):
    """body: {uid} -> เก็บของที่สปอว์นในแผนที่เข้ากระเป๋า (ยังไม่เข้าคลังหลัก ต้อง extract ก่อน
    เหมือนกลไก pickup/exfil ของโหมดแมนโดบิกด้านบน)"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid", P["uid"])
    drop = WEBSHOP_EXTRACTION_DROPS.get(drop_id)
    if not drop:
        return jsonify({"st": "error", "msg": "ไม่พบของที่สปอว์นนี้"}), 404
    if drop["uid"] != uid:
        return jsonify({"st": "error", "msg": "ของชิ้นนี้ไม่ใช่ของคำสั่งซื้อของ uid นี้"}), 403
    if time.time() >= drop["expires_ts"] and drop["status"] == "spawned":
        drop["status"] = "expired"
    if drop["status"] == "expired":
        order = WEBSHOP_ORDERS.get(drop["order_id"])
        if order:
            _webshop_set_status(order, "expired_unclaimed")
        return jsonify({"st": "error", "msg": "ของหมดอายุแล้ว (ไปเก็บไม่ทันเวลา) ติดต่อฝั่งเว็บไซต์เพื่อออกของใหม่"}), 410
    if drop["status"] != "spawned":
        return jsonify({"st": "error", "msg": f"เก็บไม่ได้ สถานะปัจจุบันคือ {drop['status']}"}), 409
    drop["status"] = "carrying"
    order = WEBSHOP_ORDERS.get(drop["order_id"])
    if order:
        _webshop_set_status(order, "picked_up_carrying")
    return jsonify({"st": "ok", "status": drop["status"], "msg": "เก็บของแล้ว รีบหนีออกจากแผนที่ให้สำเร็จ"})


@app.route('/api/webshop/delivery/<drop_id>/extract', methods=['POST'])
@require_auth
def api_webshop_delivery_extract(drop_id):
    """body: {uid} -> หนีออกจากแผนที่สำเร็จพร้อมของ -> ของเข้าคลังหลักจริง (INVENTORY) ปิดออเดอร์"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid", P["uid"])
    drop = WEBSHOP_EXTRACTION_DROPS.get(drop_id)
    if not drop:
        return jsonify({"st": "error", "msg": "ไม่พบของที่สปอว์นนี้"}), 404
    if drop["uid"] != uid:
        return jsonify({"st": "error", "msg": "ของชิ้นนี้ไม่ใช่ของคำสั่งซื้อของ uid นี้"}), 403
    if drop["status"] != "carrying":
        return jsonify({"st": "error", "msg": "ต้องเก็บของ (pickup) ก่อนถึงจะ extract ได้"}), 409
    drop["status"] = "extracted"
    order = WEBSHOP_ORDERS.get(drop["order_id"])
    item = WEBSHOP_ITEMS.get(order["item_id"]) if order else None
    if item:
        inv = INVENTORY.setdefault(uid, {})
        inv[item["name"]] = inv.get(item["name"], 0) + 1
    if order:
        _webshop_set_status(order, "delivered")
    return jsonify({"st": "ok", "status": "extracted",
                    "msg": "หนีออกจากแผนที่สำเร็จ! ของเข้าคลังหลักแล้ว"})


@app.route('/api/webshop/mailbox')
def api_webshop_mailbox():
    """body(query): uid -> รายการของในกล่องจดหมายที่ยังไม่ได้กด 'รับของ'"""
    uid = request.args.get("uid", P["uid"])
    mail = WEBSHOP_MAILBOX.get(uid, [])
    return jsonify({"st": "ok", "mail": [m for m in mail if not m["claimed"]]})


@app.route('/api/webshop/mailbox/claim', methods=['POST'])
@require_auth
def api_webshop_mailbox_claim():
    """body: {uid, mail_id} -> กดรับของจากกล่องจดหมายเข้าคลังหลัก (INVENTORY)"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid", P["uid"])
    mail_id = data.get("mail_id")
    mail = WEBSHOP_MAILBOX.get(uid, [])
    entry = next((m for m in mail if m["mail_id"] == mail_id), None)
    if not entry:
        return jsonify({"st": "error", "msg": "ไม่พบของชิ้นนี้ในกล่องจดหมาย"}), 404
    if entry["claimed"]:
        return jsonify({"st": "error", "msg": "รับของชิ้นนี้ไปแล้ว"}), 409
    item = WEBSHOP_ITEMS.get(entry["item_id"])
    if item:
        inv = INVENTORY.setdefault(uid, {})
        inv[item["name"]] = inv.get(item["name"], 0) + 1
    entry["claimed"] = True
    order = WEBSHOP_ORDERS.get(entry["order_id"])
    if order:
        _webshop_set_status(order, "claimed")
    return jsonify({"st": "ok", "received": item["name"] if item else entry["item_id"]})


def _webshop_tick_loop():
    """เธรดพื้นหลังเช็คของที่สปอว์นในแผนที่แบบ extraction ที่ยังไม่มีคนไปเก็บทันเวลา — หมดอายุ
    อัตโนมัติแล้วแจ้งสถานะไปที่ออเดอร์ (ฝั่งเว็บไซต์ต้องจัดการออกของใหม่/คืนเงินเอง)"""
    while True:
        try:
            now = time.time()
            for drop in list(WEBSHOP_EXTRACTION_DROPS.values()):
                if drop["status"] == "spawned" and now >= drop["expires_ts"]:
                    drop["status"] = "expired"
                    order = WEBSHOP_ORDERS.get(drop["order_id"])
                    if order and order["status"] != "expired_unclaimed":
                        _webshop_set_status(order, "expired_unclaimed")
        except Exception as e:
            print(f"[webshop] tick loop error (ไม่กระทบออเดอร์อื่น รอบหน้าทำงานต่อ): {e}")
        time.sleep(5)


