HORROR_DUSK_HOUR = 17     # 5 โมงเย็น — ประตูบ้านชาวเมืองเริ่มถูกล็อก บรรยากาศเปลี่ยน
HORROR_CURFEW_HOUR = 23   # 5 ทุ่ม — ล็อกดาวน์เต็มรูปแบบ ออกจากบ้านได้ = แหกกฎทันที
