HORROR_MAX_FEAR = 100
HORROR_FEAR_PER_ENCOUNTER = {"yokai": 35, "mystery_clue": 15}  # ปมปริศนา/ศาลเจ้าแอ่งเลือด ฯลฯ
HORROR_STAMINA_DRAIN_PER_TICK = 4   # ต่อการเดินสำรวจ 1 ครั้ง (/explore-step)
HORROR_FEAR_FAINT_THRESHOLD = 100   # fear เต็มหลอด = สลบ/จบรอบสำรวจคืนนั้นทันที (โดนลากกลับบ้าน)

FARM_VILLAGE_PLAYERS = {}
# uid -> {
#   "plots": {plot_id: {"type","state","crop_id","planted_at","watered_today"}},
#   "processors": {processor_id: {"active": bool, "started_at", "crop_id"}},
#   "livestock": {slot_id: {"kind","fed_at","last_collected_at"}},
#   "inventory": {item_id: qty}, "credits": int,
#   "mine_depth": int (ชั้นปัจจุบันที่ลงลึกสุด),
#   "peaceful_mode": bool,
#   "rule_violations": {rule_id: count},
#   "in_midnight_mode": bool, "stamina": int, "fear": int,
# }


def _farm_player(uid):
    if uid not in FARM_VILLAGE_PLAYERS:
        FARM_VILLAGE_PLAYERS[uid] = {
            "plots": {}, "processors": {}, "livestock": {}, "inventory": {}, "credits": 500,
            "mine_depth": 0, "peaceful_mode": False, "rule_violations": {r: 0 for r in HORROR_RULES},
            "in_midnight_mode": False, "stamina": HORROR_MAX_STAMINA, "fear": 0,
        }
    return FARM_VILLAGE_PLAYERS[uid]


def _farm_give_item(state, item_id, qty):
    state["inventory"][item_id] = state["inventory"].get(item_id, 0) + qty


def _farm_take_item(state, item_id, qty):
    if state["inventory"].get(item_id, 0) < qty:
        return False
    state["inventory"][item_id] -= qty
    if state["inventory"][item_id] <= 0:
        state["inventory"].pop(item_id, None)
    return True


def _horror_is_curfew_now(hour=None):
    """คืน True ถ้าตอนนี้เลยเวลาเคอร์ฟิวเต็มรูปแบบแล้ว (ตั้งแต่ HORROR_CURFEW_HOUR ถึงเช้า) — ไม่ส่ง hour
    เองจะใช้เวลาจริงของเซิร์ฟเวอร์"""
    h = hour if hour is not None else time.localtime().tm_hour
    return h >= HORROR_CURFEW_HOUR or h < 5


def _horror_is_dusk_now(hour=None):
    """คืน True ถ้าเลยเวลาพลบค่ำแล้ว (ประตูชาวบ้านเริ่มล็อก บรรยากาศเปลี่ยน) แต่ยังไม่ถึงเคอร์ฟิวเต็ม"""
    h = hour if hour is not None else time.localtime().tm_hour
    return HORROR_DUSK_HOUR <= h < HORROR_CURFEW_HOUR


