@app.route('/api/kagatsu/camera')
def api_kagatsu_camera():
    """ค่ากล้องเริ่มต้นของเกม — client ตั้งกล้องเป็น top-down (มองจากด้านบนตรงๆ) ตาม FARM_VILLAGE_CAMERA
    นี้ได้เลย ตอนเข้าโหมดสำรวจยามวิกาลให้สลับไปใช้ midnight_fov_deg แทน default_fov_deg"""
    return jsonify({"st": "ok", "camera": FARM_VILLAGE_CAMERA})


@app.route('/api/kagatsu/farm/crops')
def api_kagatsu_farm_crops():
    return jsonify({"st": "ok", "plot_types": FARM_PLOT_TYPES, "crops": FARM_CROPS})


@app.route('/api/kagatsu/farm/plots')
def api_kagatsu_farm_plots():
    uid = request.args.get("uid", P["uid"])
    state = _farm_player(uid)
    now = time.time()
    plots_out = {}
    for pid, plot in state["plots"].items():
        p = dict(plot)
        if p["state"] == "planted":
            crop = FARM_CROPS[p["crop_id"]]
            if now - p["planted_at"] >= crop["grow_sec"]:
                p["state"] = "grown"
        plots_out[pid] = p
    return jsonify({"st": "ok", "plots": plots_out})


@app.route('/api/kagatsu/farm/plot/till', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_farm_till():
    """body: {uid, plot_id, plot_type} -> พรวนดิน/ขุดคันนาเปิดแปลงใหม่ (plot_type: soil หรือ paddy)"""
    data = request.get_json(force=True, silent=True) or {}
    uid, plot_id = data.get("uid", P["uid"]), data.get("plot_id", "")
    plot_type = data.get("plot_type", "soil")
    if plot_type not in FARM_PLOT_TYPES:
        return jsonify({"st": "error", "msg": "ประเภทแปลงไม่ถูกต้อง"}), 400
    if not plot_id:
        return jsonify({"st": "error", "msg": "ต้องระบุ plot_id"}), 400
    state = _farm_player(uid)
    state["plots"][plot_id] = {"type": plot_type, "state": "tilled", "crop_id": None,
                                "planted_at": None, "watered_today": False}
    return jsonify({"st": "ok", "plot": state["plots"][plot_id]})


@app.route('/api/kagatsu/farm/plot/plant', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_farm_plant():
    """body: {uid, plot_id, crop_id} -> ปลูกเมล็ดลงแปลงที่พรวนดินไว้แล้ว (หักค่าเมล็ดจาก credits)"""
    data = request.get_json(force=True, silent=True) or {}
    uid, plot_id, crop_id = data.get("uid", P["uid"]), data.get("plot_id", ""), data.get("crop_id", "")
    state = _farm_player(uid)
    plot = state["plots"].get(plot_id)
    crop = FARM_CROPS.get(crop_id)
    if not plot or plot["state"] != "tilled":
        return jsonify({"st": "error", "msg": "แปลงนี้ยังไม่ได้พรวนดิน หรือมีของปลูกอยู่แล้ว"}), 400
    if not crop:
        return jsonify({"st": "error", "msg": "ไม่มีพืชชนิดนี้"}), 404
    if crop["plot_type"] != plot["type"]:
        return jsonify({"st": "error", "msg": f"พืชนี้ต้องปลูกบน {FARM_PLOT_TYPES[crop['plot_type']]} เท่านั้น"}), 400
    if state["credits"] < crop["seed_cost"]:
        return jsonify({"st": "error", "msg": "เครดิตไม่พอซื้อเมล็ด"}), 402
    state["credits"] -= crop["seed_cost"]
    plot.update({"state": "planted", "crop_id": crop_id, "planted_at": time.time(), "watered_today": False})
    return jsonify({"st": "ok", "plot": plot, "credits": state["credits"]})


@app.route('/api/kagatsu/farm/plot/water', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_farm_water():
    """body: {uid, plot_id} -> รดน้ำแปลง (ปัจจุบันเป็น flag สถานะให้ client โชว์เอฟเฟกต์ — ไม่ผูกกับ
    ความเร็วโต เผื่ออนาคตอยากผูก growth speed กับการรดน้ำก็แก้ตรงนี้จุดเดียว)"""
    data = request.get_json(force=True, silent=True) or {}
    uid, plot_id = data.get("uid", P["uid"]), data.get("plot_id", "")
    state = _farm_player(uid)
    plot = state["plots"].get(plot_id)
    if not plot:
        return jsonify({"st": "error", "msg": "ไม่พบแปลงนี้"}), 404
    plot["watered_today"] = True
    return jsonify({"st": "ok", "plot": plot})


@app.route('/api/kagatsu/farm/plot/harvest', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_farm_harvest():
    """body: {uid, plot_id} -> เก็บเกี่ยวแปลงที่โตเต็มที่แล้ว ได้ผลผลิตเข้า inventory แปลงกลับไปว่างเปล่า
    (ต้องพรวนดินใหม่ก่อนปลูกรอบถัดไป)"""
    data = request.get_json(force=True, silent=True) or {}
    uid, plot_id = data.get("uid", P["uid"]), data.get("plot_id", "")
    state = _farm_player(uid)
    plot = state["plots"].get(plot_id)
    if not plot or plot["state"] != "planted":
        return jsonify({"st": "error", "msg": "แปลงนี้ยังไม่มีของที่กำลังปลูก"}), 400
    crop = FARM_CROPS[plot["crop_id"]]
    if time.time() - plot["planted_at"] < crop["grow_sec"]:
        return jsonify({"st": "error", "msg": "พืชยังโตไม่เต็มที่"}), 400
    _farm_give_item(state, plot["crop_id"], 1)
    plot.update({"state": "empty", "crop_id": None, "planted_at": None, "watered_today": False})
    return jsonify({"st": "ok", "harvested": plot["crop_id"] or crop["name"], "inventory": state["inventory"]})


@app.route('/api/kagatsu/farm/sell', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_farm_sell():
    """body: {uid, item_id, qty} -> ขายพืชผล/ของแปรรูป/ผลิตภัณฑ์ปศุสัตว์/หนังสัตว์ที่ตั้งราคาขายไว้"""
    data = request.get_json(force=True, silent=True) or {}
    uid, item_id, qty = data.get("uid", P["uid"]), data.get("item_id", ""), int(data.get("qty", 1))
    state = _farm_player(uid)
    price = None
    if item_id in FARM_CROPS:
        price = FARM_CROPS[item_id]["sell_price"]
    else:
        for proc in FARM_PROCESSORS.values():
            if proc["output_item"] == item_id:
                price = proc["output_sell_price"]
        for lv in FARM_LIVESTOCK_TYPES.values():
            if lv["product_item"] == item_id:
                price = lv["sell_price"]
        for an in FARM_HUNTING_ANIMALS.values():
            if an["pelt_item"] == item_id:
                price = an["sell_price"]
    if price is None:
        return jsonify({"st": "error", "msg": "ของชิ้นนี้ขายไม่ได้"}), 400
    if not _farm_take_item(state, item_id, qty):
        return jsonify({"st": "error", "msg": "ของในกระเป๋าไม่พอ"}), 400
    state["credits"] += price * qty
    return jsonify({"st": "ok", "credits": state["credits"], "inventory": state["inventory"]})


# ==================== Routes: Cozy — แปรรูป/หมักดอง ====================

@app.route('/api/kagatsu/process/start', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_process_start():
    """body: {uid, processor_id, slot_id} -> ใส่วัตถุดิบลงถังหมัก/กลั่น เริ่มนับเวลาแปรรูป"""
    data = request.get_json(force=True, silent=True) or {}
    uid, processor_id = data.get("uid", P["uid"]), data.get("processor_id", "")
    slot_id = data.get("slot_id", processor_id)
    proc = FARM_PROCESSORS.get(processor_id)
    if not proc:
        return jsonify({"st": "error", "msg": "ไม่มีถังแปรรูปนี้"}), 404
    state = _farm_player(uid)
    if slot_id in state["processors"] and state["processors"][slot_id]["active"]:
        return jsonify({"st": "error", "msg": "ถังนี้กำลังแปรรูปอยู่ รอให้เสร็จก่อน"}), 409
    if not _farm_take_item(state, proc["input_crop"], 1):
        return jsonify({"st": "error", "msg": f"ต้องมี {FARM_CROPS[proc['input_crop']]['name']} อย่างน้อย 1"}), 400
    state["processors"][slot_id] = {"processor_id": processor_id, "active": True, "started_at": time.time()}
    return jsonify({"st": "ok", "slot": state["processors"][slot_id]})


@app.route('/api/kagatsu/process/collect', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_process_collect():
    """body: {uid, slot_id} -> เก็บผลลัพธ์การแปรรูปที่เสร็จแล้ว (ผักดอง/เหล้าพื้นบ้าน) เข้า inventory"""
    data = request.get_json(force=True, silent=True) or {}
    uid, slot_id = data.get("uid", P["uid"]), data.get("slot_id", "")
    state = _farm_player(uid)
    slot = state["processors"].get(slot_id)
    if not slot or not slot["active"]:
        return jsonify({"st": "error", "msg": "ไม่มีของกำลังแปรรูปอยู่ในถังนี้"}), 400
    proc = FARM_PROCESSORS[slot["processor_id"]]
    if time.time() - slot["started_at"] < proc["process_sec"]:
        return jsonify({"st": "error", "msg": "ยังแปรรูปไม่เสร็จ"}), 400
    _farm_give_item(state, proc["output_item"], 1)
    slot["active"] = False
    return jsonify({"st": "ok", "collected": proc["output_item"], "inventory": state["inventory"]})


# ==================== Routes: Cozy — ปศุสัตว์ ====================

@app.route('/api/kagatsu/livestock/add', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_livestock_add():
    """body: {uid, slot_id, kind} -> เพิ่มสัตว์เลี้ยงตัวใหม่ลงคอกเปล่า (kind: chicken/cow/sheep)"""
    data = request.get_json(force=True, silent=True) or {}
    uid, slot_id, kind = data.get("uid", P["uid"]), data.get("slot_id", ""), data.get("kind", "")
    if kind not in FARM_LIVESTOCK_TYPES:
        return jsonify({"st": "error", "msg": "ไม่มีสัตว์เลี้ยงชนิดนี้"}), 404
    state = _farm_player(uid)
    if slot_id in state["livestock"]:
        return jsonify({"st": "error", "msg": "คอกนี้มีสัตว์อยู่แล้ว"}), 409
    state["livestock"][slot_id] = {"kind": kind, "fed_at": None, "last_collected_at": time.time()}
    return jsonify({"st": "ok", "slot": state["livestock"][slot_id]})


@app.route('/api/kagatsu/livestock/feed', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_livestock_feed():
    """body: {uid, slot_id} -> ให้อาหารสัตว์เลี้ยง (จำเป็นสำหรับวัว/แกะ ก่อนจะเก็บผลผลิตรอบถัดไปได้)"""
    data = request.get_json(force=True, silent=True) or {}
    uid, slot_id = data.get("uid", P["uid"]), data.get("slot_id", "")
    state = _farm_player(uid)
    slot = state["livestock"].get(slot_id)
    if not slot:
        return jsonify({"st": "error", "msg": "ไม่พบคอกนี้"}), 404
    slot["fed_at"] = time.time()
    return jsonify({"st": "ok", "slot": slot})


@app.route('/api/kagatsu/livestock/collect', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_livestock_collect():
    """body: {uid, slot_id} -> เก็บผลผลิต (ไข่/นม/ขนแกะ) ถ้าครบรอบเวลา collect_sec แล้ว และให้อาหารแล้ว
    (ถ้าสัตว์ชนิดนั้น needs_feed=True)"""
    data = request.get_json(force=True, silent=True) or {}
    uid, slot_id = data.get("uid", P["uid"]), data.get("slot_id", "")
    state = _farm_player(uid)
    slot = state["livestock"].get(slot_id)
    if not slot:
        return jsonify({"st": "error", "msg": "ไม่พบคอกนี้"}), 404
    lv = FARM_LIVESTOCK_TYPES[slot["kind"]]
    if time.time() - slot["last_collected_at"] < lv["collect_sec"]:
        return jsonify({"st": "error", "msg": "ยังไม่ถึงรอบเก็บผลผลิต"}), 400
    if lv["needs_feed"] and (slot["fed_at"] is None or slot["fed_at"] < slot["last_collected_at"]):
        return jsonify({"st": "error", "msg": f"ต้องให้อาหาร{lv['name']}ก่อนถึงจะเก็บผลผลิตได้"}), 400
    _farm_give_item(state, lv["product_item"], 1)
    slot["last_collected_at"] = time.time()
    return jsonify({"st": "ok", "collected": lv["product_item"], "inventory": state["inventory"]})


# ==================== Routes: Cozy — เหมือง/ล่าสัตว์/คราฟต์/เทศกาล ====================

@app.route('/api/kagatsu/mine/descend', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_mine_descend():
    """body: {uid} -> ลงเหมืองอีก 1 ชั้น (สูงสุด 40 ชั้น) สุ่มเจอศัตรู (ค้างคาว/แมงมุม ตามช่วงชั้น) และ
    แร่ที่ขุดได้ตามความลึก client เอาผล enemy/ore ไปแสดงผลต่อสู้/ขุดของฝั่งตัวเอง"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid", P["uid"])
    state = _farm_player(uid)
    if state["mine_depth"] >= FARM_MINE_MAX_DEPTH:
        return jsonify({"st": "error", "msg": f"ลงได้สูงสุดแค่ชั้น {FARM_MINE_MAX_DEPTH} แล้ว"}), 400
    state["mine_depth"] += 1
    floor = state["mine_depth"]
    possible_enemies = [eid for eid, e in FARM_MINE_ENEMIES.items() if e["min_floor"] <= floor <= e["max_floor"]]
    enemy = None
    if possible_enemies and random.random() < 0.35:
        enemy = random.choice(possible_enemies)
    ore_item, ore_name = next((oi, on) for upto, oi, on in FARM_MINE_ORES_BY_DEPTH if floor <= upto)
    _farm_give_item(state, ore_item, 1)
    return jsonify({"st": "ok", "floor": floor, "encountered_enemy": enemy,
                    "enemy_name": FARM_MINE_ENEMIES[enemy]["name"] if enemy else None,
                    "found_ore": ore_item, "ore_name": ore_name, "inventory": state["inventory"]})


@app.route('/api/kagatsu/mine/leave', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_mine_leave():
    """body: {uid} -> ออกจากเหมืองกลับผิวดิน (รีเซ็ต mine_depth กลับ 0 — รอบถัดไปเริ่มลงจากชั้น 1 ใหม่)"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid", P["uid"])
    state = _farm_player(uid)
    state["mine_depth"] = 0
    return jsonify({"st": "ok"})


@app.route('/api/kagatsu/hunt', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_hunt():
    """body: {uid, method, animal_id} -> ล่าสัตว์ด้วยธนู (สำเร็จสูง, ทันที) หรือกับดัก (สำเร็จต่ำกว่าต่อ
    ครั้ง แต่ไม่ต้องเฝ้า) ได้หนังสัตว์เข้า inventory ถ้าสำเร็จ"""
    data = request.get_json(force=True, silent=True) or {}
    uid, method, animal_id = data.get("uid", P["uid"]), data.get("method", ""), data.get("animal_id", "")
    if method not in FARM_HUNTING_METHODS:
        return jsonify({"st": "error", "msg": "วิธีล่าสัตว์ไม่ถูกต้อง"}), 400
    animal = FARM_HUNTING_ANIMALS.get(animal_id)
    if not animal:
        return jsonify({"st": "error", "msg": "ไม่มีสัตว์ชนิดนี้"}), 404
    success_chance = 0.65 if method == "bow" else 0.40
    success = random.random() < success_chance
    state = _farm_player(uid)
    if success:
        _farm_give_item(state, animal["pelt_item"], 1)
    return jsonify({"st": "ok", "success": success, "pelt": animal["pelt_item"] if success else None,
                    "inventory": state["inventory"]})


@app.route('/api/kagatsu/craft', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_craft():
    """body: {uid, craft_id} -> คราฟต์รั้ว/ทางเดิน/เฟอร์นิเจอร์/อัปเกรดเครื่องมือ ตามวัตถุดิบที่กำหนด"""
    data = request.get_json(force=True, silent=True) or {}
    uid, craft_id = data.get("uid", P["uid"]), data.get("craft_id", "")
    recipe = FARM_CRAFT_RECIPES.get(craft_id)
    if not recipe:
        return jsonify({"st": "error", "msg": "ไม่มีสูตรคราฟต์นี้"}), 404
    state = _farm_player(uid)
    for item, qty in recipe["materials"].items():
        if state["inventory"].get(item, 0) < qty:
            return jsonify({"st": "error", "msg": f"วัตถุดิบไม่พอ: ต้องการ {item} x{qty}"}), 400
    for item, qty in recipe["materials"].items():
        _farm_take_item(state, item, qty)
    _farm_give_item(state, recipe["output_item"], recipe["output_qty"])
    return jsonify({"st": "ok", "crafted": recipe["output_item"], "qty": recipe["output_qty"],
                    "inventory": state["inventory"]})


@app.route('/api/kagatsu/festival/list')
def api_kagatsu_festival_list():
    return jsonify({"st": "ok", "festivals": FARM_FESTIVALS})


@app.route('/api/kagatsu/festival/join', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_festival_join():
    """body: {uid, festival_id} -> เข้าร่วมกิจกรรมเทศกาล (ฮานามิ/เทศกาลฤดูร้อน) กับชาวบ้าน — ปัจจุบันคืน
    สถานะ joined ให้ client เล่นฉาก/ให้รางวัลความสัมพันธ์ต่อเอง"""
    data = request.get_json(force=True, silent=True) or {}
    festival_id = data.get("festival_id", "")
    if festival_id not in FARM_FESTIVALS:
        return jsonify({"st": "error", "msg": "ไม่มีเทศกาลนี้"}), 404
    return jsonify({"st": "ok", "joined": festival_id, "festival": FARM_FESTIVALS[festival_id]})


# ==================== Routes: Horror — เคอร์ฟิว/กฎ/สำรวจยามวิกาล ====================

@app.route('/api/kagatsu/horror/status')
def api_kagatsu_horror_status():
    """สถานะเวลา/เคอร์ฟิวปัจจุบันของหมู่บ้าน + สถานะผู้เล่นเอง (peaceful mode, fear/stamina, จำนวนที่
    เคยแหกกฎแต่ละข้อ) — client เรียก poll ได้เรื่อยๆ เพื่อโชว์ UI เตือนก่อนถึงเคอร์ฟิว"""
    uid = request.args.get("uid", P["uid"])
    state = _farm_player(uid)
    return jsonify({"st": "ok", "is_dusk": _horror_is_dusk_now(), "is_curfew": _horror_is_curfew_now(),
                    "dusk_hour": HORROR_DUSK_HOUR, "curfew_hour": HORROR_CURFEW_HOUR,
                    "rules": HORROR_RULES, "peaceful_mode": state["peaceful_mode"],
                    "rule_violations": state["rule_violations"], "in_midnight_mode": state["in_midnight_mode"],
                    "stamina": state["stamina"], "fear": state["fear"]})


@app.route('/api/kagatsu/horror/peaceful-mode', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_horror_peaceful_mode():
    """body: {uid, enabled} -> เปิด/ปิด Peaceful Mode เปิดไว้แล้วฝ่าฝืนกฎ (/horror/break-rule,
    /horror/midnight/start) จะถูกบล็อกไปเลย เอาไว้ให้คนที่ไม่อยากเจอสยองขวัญเล่นเป็นเกมทำฟาร์มใสๆ ได้
    เต็มเกม"""
    data = request.get_json(force=True, silent=True) or {}
    uid, enabled = data.get("uid", P["uid"]), bool(data.get("enabled", True))
    state = _farm_player(uid)
    state["peaceful_mode"] = enabled
    return jsonify({"st": "ok", "peaceful_mode": state["peaceful_mode"]})


@app.route('/api/kagatsu/horror/break-rule', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_horror_break_rule():
    """body: {uid, rule_id} -> บันทึกว่าผู้เล่นแหกกฎข้อไหน (เช่น เผลอคุยกับคนแปลกหน้า, ออกนอกหมู่บ้าน)
    ถูกบล็อกถ้าเปิด Peaceful Mode อยู่"""
    data = request.get_json(force=True, silent=True) or {}
    uid, rule_id = data.get("uid", P["uid"]), data.get("rule_id", "")
    if rule_id not in HORROR_RULES:
        return jsonify({"st": "error", "msg": "ไม่มีกฎข้อนี้"}), 404
    state = _farm_player(uid)
    if state["peaceful_mode"]:
        return jsonify({"st": "error", "msg": "เปิด Peaceful Mode อยู่ แหกกฎไม่ได้"}), 403
    state["rule_violations"][rule_id] += 1
    return jsonify({"st": "ok", "rule_violations": state["rule_violations"]})


@app.route('/api/kagatsu/horror/midnight/start', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_horror_midnight_start():
    """body: {uid} -> แอบย่องออกจากบ้านตอนเที่ยงคืน เข้าสู่โหมดสำรวจยามวิกาล (Survival Horror) เต็มรูปแบบ
    รีเซ็ต stamina เต็ม/fear เป็น 0 ต้องไม่ได้เปิด Peaceful Mode และต้องถึงเวลาเคอร์ฟิวจริง (>= 23:00)
    เท่านั้น"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid", P["uid"])
    state = _farm_player(uid)
    if state["peaceful_mode"]:
        return jsonify({"st": "error", "msg": "เปิด Peaceful Mode อยู่ ออกไปสำรวจยามวิกาลไม่ได้"}), 403
    if not _horror_is_curfew_now():
        return jsonify({"st": "error", "msg": "ยังไม่ถึงเวลาเคอร์ฟิว (ต้องเป็นช่วงดึกหลัง 5 ทุ่ม)"}), 400
    state["rule_violations"]["no_leave_house_at_night"] += 1
    state["in_midnight_mode"] = True
    state["stamina"] = HORROR_MAX_STAMINA
    state["fear"] = 0
    return jsonify({"st": "ok", "in_midnight_mode": True, "stamina": state["stamina"], "fear": state["fear"],
                    "camera_fov_deg": FARM_VILLAGE_CAMERA["midnight_fov_deg"]})


@app.route('/api/kagatsu/horror/midnight/explore-step', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_horror_midnight_explore_step():
    """body: {uid, encounter?} -> เดินสำรวจ 1 ก้าวในความมืด หัก stamina ทุกครั้ง ถ้ามี encounter
    ("yokai" หรือ "mystery_clue") จะเพิ่ม fear ตามนั้นด้วย fear เต็มหลอด = สลบ จบรอบสำรวจคืนนี้ทันที
    (ถูกลากกลับบ้าน) stamina หมด = หมดแรงเดินต่อไม่ไหว ต้องรีบกลับบ้านผ่าน /horror/midnight/end"""
    data = request.get_json(force=True, silent=True) or {}
    uid, encounter = data.get("uid", P["uid"]), data.get("encounter")
    state = _farm_player(uid)
    if not state["in_midnight_mode"]:
        return jsonify({"st": "error", "msg": "ยังไม่ได้อยู่ในโหมดสำรวจยามวิกาล"}), 400
    state["stamina"] = max(0, state["stamina"] - HORROR_STAMINA_DRAIN_PER_TICK)
    if encounter in HORROR_FEAR_PER_ENCOUNTER:
        state["fear"] = min(HORROR_MAX_FEAR, state["fear"] + HORROR_FEAR_PER_ENCOUNTER[encounter])
    fainted = state["fear"] >= HORROR_FEAR_FAINT_THRESHOLD
    if fainted:
        state["in_midnight_mode"] = False
    return jsonify({"st": "ok", "stamina": state["stamina"], "fear": state["fear"], "fainted": fainted,
                    "exhausted": state["stamina"] <= 0})


@app.route('/api/kagatsu/horror/midnight/end', methods=['POST'])
@require_auth_toggleable
def api_kagatsu_horror_midnight_end():
    """body: {uid} -> รีบกลับเข้าบ้านให้ทันก่อนสว่าง จบโหมดสำรวจยามวิกาลโดยสมัครใจ (ไม่ต้องรอสลบ)"""
    data = request.get_json(force=True, silent=True) or {}
    uid = data.get("uid", P["uid"])
    state = _farm_player(uid)
    state["in_midnight_mode"] = False
    return jsonify({"st": "ok"})


