AICHAT_HOLOGRAM_WIDGET_JS = """
function toggleAIHoloChat() {
    let panel = document.getElementById('aiholo_panel');
    if (!panel) return;
    const opening = (panel.style.display === 'none' || !panel.style.display);
    panel.style.display = opening ? 'block' : 'none';
    if (opening) aiholoLoadHistory();
}

function aiholoSid() {
    let sid = localStorage.getItem('vmax_ai_chat_sid');
    if (!sid) {
        sid = 'web-holo-' + Math.random().toString(36).slice(2) + Date.now();
        localStorage.setItem('vmax_ai_chat_sid', sid);
    }
    return sid;
}

function aiholoRenderLine(role, content) {
    let log = document.getElementById('aiholo_log');
    if (!log) return;
    let who = role === 'user' ? '🧑 คุณ' : '🤖 AI';
    log.innerHTML += `<div><b>${who}:</b> ${content.replace(/</g, '&lt;')}</div>`;
    log.scrollTop = log.scrollHeight;
}

async function aiholoLoadHistory() {
    try {
        let r = await fetch('/api/ai-chat/history?session_id=' + encodeURIComponent(aiholoSid()) + '&limit=20');
        let d = await r.json();
        let log = document.getElementById('aiholo_log');
        if (log) log.innerHTML = '';
        if (d.st === 'ok') { d.messages.forEach(m => aiholoRenderLine(m.role, m.content)); }
    } catch (e) { console.warn('Holo AI: load history failed', e); }
}

async function aiholoSend() {
    let box = document.getElementById('aiholo_msg');
    let msg = box.value.trim();
    if (!msg) return;
    box.value = '';
    aiholoRenderLine('user', msg);
    
    try {
        let r = await fetch('/api/ai-chat/send', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ session_id: aiholoSid(), message: msg })
        });
        let d = await r.json();
        aiholoRenderLine('assistant', d.st === 'ok' ? d.reply : ('❌ ' + d.msg));
    } catch (e) {
        aiholoRenderLine('assistant', '❌ เชื่อมต่อไม่ได้');
    }
}

function aiholoSetAnim(preset) {
    let fig = document.getElementById('aiholo_figure');
    if (!fig) return;
    fig.classList.remove('aiholo-anim-idle', 'aiholo-anim-walk', 'aiholo-anim-run', 'aiholo-anim-jump', 'aiholo-anim-interact');
    fig.classList.add('aiholo-anim-' + preset);
    let emojis = { idle: '🧍', walk: '🚶', run: '🏃', jump: '🤸', interact: '🙋' };
    fig.textContent = emojis[preset] || '🧍';
}

// ตั้งค่าเริ่มต้นตอนโหลด
aiholoSetAnim('idle');
"""

