# ==========================================
# [ 2F2. Motion Mirror System — จับท่าทางร่างกายผู้เล่นผ่านกล้อง → ตัวละครเกมทำตาม ]
# ระบบ "เปิดเกมกาชาแล้วทำท่า → ตัวละครทำตาม" — ใช้กล้องจับ movement ร่างกายผู้เล่น
# (mediapipe Pose ซึ่งมีอยู่แล้วในไฟล์นี้ ตรวจจับ 33 จุด landmark) แล้วจำแนกเป็น "ท่าทาง"
# (pose class) เช่น T-pose / ยกมือข้างเดียว / ยกมือทั้งสองข้าง / โบกมือ / นั่งยอง /
# เอียงซ้าย-ขวา / กอดอก แล้ว map เข้ากับ ANIMATION_PRESETS (idle/walk/run/jump/interact)
# ที่มีอยู่แล้ว — ตัวละครในเกมจะเล่น animation นั้น
# ทำงาน real-time ผ่าน polling ที่ /api/motion-mirror/frame + ทางเลือก SocketIO event
# `motion_mirror_pose` สำหรับซิงก์ข้ามแท็บของผู้เล่นคนเดียวกัน
# ==========================================
MOTION_MIRROR_ENABLED = True
MOTION_MIRROR_SESSIONS = {}           # uid -> {started_at, last_frame_at, last_pose, last_action, frame_count}
MOTION_MIRROR_TARGET_FPS = 12         # rate limit: ประมวลผลไม่เกิน 12 fps (ลดโหลด server)
_MOTION_MIRROR_MIN_INTERVAL = 1.0 / MOTION_MIRROR_TARGET_FPS

# แมป "ท่าทางที่จำแนกได้" -> "animation ที่ตัวละครจะเล่น" (ผูกกับ ANIMATION_PRESETS เดิม)
POSE_ACTION_MAP = {
    "tpose":          {"anim": "idle",     "label": "ท่ายืนกางแขน (T-pose)",   "emoji": "🧍"},
    "hand_left_up":  {"anim": "interact", "label": "ยกมือซ้ายขึ้น",            "emoji": "🙋"},
    "hand_right_up": {"anim": "interact", "label": "ยกมือขวาขึ้น",            "emoji": "🙋‍♂️"},
    "both_hands_up": {"anim": "jump",     "label": "ยกมือทั้งสองข้าง",          "emoji": "🙌"},
    "wave":           {"anim": "interact", "label": "โบกมือ",                 "emoji": "👋"},
    "squat":          {"anim": "idle",     "label": "นั่งยองๆ",                "emoji": "🦵"},
    "lean_left":      {"anim": "walk",     "label": "เอียงซ้าย",               "emoji": "⬅️"},
    "lean_right":     {"anim": "walk",     "label": "เอียงขวา",               "emoji": "➡️"},
    "cross_arms":     {"anim": "idle",     "label": "กอดอก",                  "emoji": "🙅"},
    "unknown":        {"anim": "idle",     "label": "ไม่รู้จักท่านี้",            "emoji": "❓"},
}

def _classify_pose_from_landmarks(landmarks) -> str:
    """รับ landmark list ของ mediapipe Pose (33 จุด) แล้วจำแนกเป็นชื่อท่าทาง
    ด้วยกฎง่ายๆ (heuristic ไม่ใช่ ML) — เปรียบเทียบตำแหน่ง y ของข้อมือ vs ไหล่ vs
    สะโพก และ x ของข้อมือซ้าย-ขวา เพื่อบอกว่ายกมือข้างไหน กี่ข้าง กอดอก นั่งยอง ฯลฯ
    คืนค่าชื่อ pose ที่อยู่ใน POSE_ACTION_MAP"""
    if not landmarks or len(landmarks) < 17:
        return "unknown"

    # จุดสำคัญตาม mediapipe Pose landmark index
    nose          = landmarks[0]
    left_shoulder = landmarks[11]; right_shoulder = landmarks[12]
    left_wrist    = landmarks[15]; right_wrist   = landmarks[16]
    left_hip      = landmarks[23]; right_hip     = landmarks[24]
    left_knee     = landmarks[25]; right_knee    = landmarks[26]

    # T-pose: ข้อมือทั้งสองระดับไหล่ และกางออกจากลำตัว
    lws = abs(left_wrist.y  - left_shoulder.y)  < 0.08
    rws = abs(right_wrist.y - right_shoulder.y) < 0.08
    lwo = left_wrist.x  < left_shoulder.x  - 0.15
    rwo = right_wrist.x > right_shoulder.x + 0.15
    if lws and rws and lwo and rwo:
        return "tpose"

    # ยกมือทั้งสองข้าง
    if left_wrist.y < left_shoulder.y - 0.05 and right_wrist.y < right_shoulder.y - 0.05:
        return "both_hands_up"

    # โบกมือ: มือซ้ายสูงเหนือหัว + ข้อมือขวาต่ำกว่าไหล่
    if left_wrist.y < nose.y - 0.05 and right_wrist.y > right_shoulder.y + 0.05:
        return "wave"

    # ยกมือซ้ายข้างเดียว
    if left_wrist.y < left_shoulder.y - 0.05 and right_wrist.y > right_shoulder.y - 0.02:
        return "hand_left_up"

    # ยกมือขวาข้างเดียว
    if right_wrist.y < right_shoulder.y - 0.05 and left_wrist.y > left_shoulder.y - 0.02:
        return "hand_right_up"

    # กอดอก: ข้อมือซ้ายอยู่ขวากว่ากึ่งกลางลำตัว ข้อมือขวาอยู่ซ้ายกว่า และใกล้ระดับไหล่
    mid_x = (left_shoulder.x + right_shoulder.x) / 2
    if (left_wrist.x > mid_x and right_wrist.x < mid_x and
        abs(left_wrist.y  - left_shoulder.y)  < 0.18 and
        abs(right_wrist.y - right_shoulder.y) < 0.18):
        return "cross_arms"

    # นั่งยอง: เข่าทั้งสองอยู่ใกล้ระดับสะโพก (y ใกล้กัน — หมายเหตุ mediapipe y มาก = ต่ำกว่าในภาพ)
    if abs(left_knee.y - left_hip.y)  < 0.10 and abs(right_knee.y - right_hip.y) < 0.10:
        return "squat"

    # เอียงซ้าย: ไหล่ซ้ายต่ำกว่าขวาอย่างชัดเจน
    if left_shoulder.y > right_shoulder.y + 0.08:
        return "lean_left"
    if right_shoulder.y > left_shoulder.y + 0.08:
        return "lean_right"

    return "unknown"


def motion_mirror_start_session(uid: str) -> dict:
    if not MOTION_MIRROR_ENABLED:
        return {"st": "error", "msg": "ระบบ Motion Mirror ถูกปิดไว้"}
    MOTION_MIRROR_SESSIONS[uid] = {
        "started_at":     time.time(),
        "last_frame_at":   0.0,
        "last_pose":      "unknown",
        "last_action":    POSE_ACTION_MAP["unknown"],
        "frame_count":    0,
    }
    return {"st": "ok", "msg": "เริ่ม session แล้ว ส่งภาพที่ /api/motion-mirror/frame"}


def motion_mirror_stop_session(uid: str) -> dict:
    MOTION_MIRROR_SESSIONS.pop(uid, None)
    return {"st": "ok", "msg": "หยุด session แล้ว"}


def motion_mirror_process_frame(uid: str, image_bytes: bytes) -> dict:
    """รับภาพจากกล้องผู้เล่น → ตรวจจับท่าทาง → คืน pose + action ที่ตัวละครจะเล่น
    มี rate limit ป้องกัน client ส่งภาพมาถี่เกินไป (ใช้ MOTION_MIRROR_TARGET_FPS)
    ใช้โค้ด _load_pose_detector() และ extract_pose_keyframe() ที่มีอยู่แล้ว
    ในส่วน [ 2F1 ] ด้านบน — ไม่ต้องสร้าง mediapipe instance ใหม่"""
    session = MOTION_MIRROR_SESSIONS.get(uid)
    if not session:
        return {"st": "error", "msg": "ยังไม่ได้เริ่ม session — โปรดเรียก /api/motion-mirror/start ก่อน"}

    now = time.time()
    if now - session["last_frame_at"] < _MOTION_MIRROR_MIN_INTERVAL:
        # ส่งเร็วเกินไป — คืนท่าล่าสุดที่เคยตรวจได้ ไม่ประมวลผลใหม่ (ลดโหลด server)
        return {"st": "ok", "throttled": True, "pose": session["last_pose"], "action": session["last_action"]}

    # ใช้โค้ดเดิมจาก [ 2F1 ]: สกัด keyframe + landmark
    keyframe = extract_pose_keyframe(image_bytes)
    if keyframe is None:
        return {"st": "ok", "detected": False, "msg": "ไม่พบคนในภาพ ลองขยับเข้ามาในกรอบกล้อง"}

    # ดึง landmark ดิบ (33 จุด) อีกครั้งเพื่อ classify ท่าทาง — keyframe ด้านบนเก็บแค่ part เฉลี่ย
    import numpy as _np_mm
    arr = _np_mm.frombuffer(image_bytes, dtype=_np_mm.uint8)
    img = cv2.imdecode(arr, cv2.IMREAD_COLOR)
    result = _load_pose_detector().process(cv2.cvtColor(img, cv2.COLOR_BGR2RGB))
    if not result.pose_landmarks:
        return {"st": "ok", "detected": False}

    landmarks = result.pose_landmarks.landmark
    pose_class = _classify_pose_from_landmarks(landmarks)
    action = POSE_ACTION_MAP.get(pose_class, POSE_ACTION_MAP["unknown"])

    session["last_frame_at"] = now
    session["last_pose"]    = pose_class
    session["last_action"]  = action
    session["frame_count"] += 1

    # broadcast ผ่าน socketio ให้แท็บอื่นของผู้เล่นคนเดียวกันเห็นท่าเดียวกัน
    try:
        sio.emit("motion_mirror_pose", {
            "uid":   uid,
            "pose":  pose_class,
            "action": action,
            "frame": session["frame_count"],
        }, room=uid)
    except Exception:
        pass

    return {
        "st":        "ok",
        "detected":  True,
        "pose":      pose_class,
        "action":    action,
        "keyframe":  keyframe,
        "frame":     session["frame_count"],
    }


def motion_mirror_status(uid: str) -> dict:
    s = MOTION_MIRROR_SESSIONS.get(uid)
    if not s:
        return {"st": "ok", "active": False}
    return {
        "st": "ok", "active": True,
        "started_at":   s["started_at"],
        "frame_count":  s["frame_count"],
        "last_pose":    s["last_pose"],
        "last_action":  s["last_action"],
    }


