# ==========================================
# [ Motion Mirror Controller JS ]
# ==========================================
MOTION_MIRROR_WIDGET_JS = r"""
// ==========================================
// ---- กระจกเลียนแบบท่าทาง (Motion Mirror) ----
// เปิดกล้อง → ส่งภาพไป server ตรวจจับท่า → ตัวละครเกมทำตาม
// ==========================================
let mmStream = null;
let mmSessionActive = false;
let mmSendLoop = null;
const MM_SEND_INTERVAL_MS = 90;  // ส่งภาพไป server ทุก ~90ms (~11 fps)

function _mmUid() { return localStorage.getItem('vmax_uid'); }

async function _mmFetch(url, opts = {}) {
    opts = Object.assign({}, opts);
    opts.headers = Object.assign({}, opts.headers || {});
    const token = localStorage.getItem('vmax_token');
    if (token) opts.headers['Authorization'] = 'Bearer ' + token;
    return fetch(url, opts);
}

function mmToggleWidget() {
    let panel = document.getElementById('mm_panel');
    if (!panel) return;
    panel.style.display = (panel.style.display === 'none' || !panel.style.display) ? 'block' : 'none';
}

function mmSetMsg(text) {
    let el = document.getElementById('mm_msg');
    if (el) el.innerText = text || '';
}

async function mmToggleCamera() {
    if (mmStream) { mmStopCamera(); } else { await mmStartCamera(); }
}

async function mmStartCamera() {
    if (!_mmUid()) { mmSetMsg('ต้องล็อกอินก่อน'); return; }
    try {
        mmStream = await navigator.mediaDevices.getUserMedia({ video: { width: 320, height: 240 }, audio: false });
        const video = document.getElementById('mm_video');
        video.srcObject = mmStream;
        await video.play();

        const r = await _mmFetch('/api/motion-mirror/start', { method: 'POST' });
        const d = await r.json();
        if (d.st !== 'ok') { mmSetMsg(d.msg); mmStopCamera(); return; }
        mmSessionActive = true;

        document.getElementById('mm_btn').innerText = '⏹ หยุดกล้อง';
        mmSetMsg('กล้องเปิดแล้ว ลองทำท่าดูสิ! 🤸');

        mmSendLoop = setInterval(mmSendFrame, MM_SEND_INTERVAL_MS);
        mmDrawCharacter();
    } catch (e) {
        mmSetMsg('เปิดกล้องไม่ได้: ' + e.message);
    }
}

function mmStopCamera() {
    if (mmSendLoop) { clearInterval(mmSendLoop); mmSendLoop = null; }
    if (mmStream) { mmStream.getTracks().forEach(t => t.stop()); mmStream = null; }
    mmSessionActive = false;
    document.getElementById('mm_btn').innerText = '📷 เปิดกล้อง';
    mmSetMsg('กล้องปิดแล้ว');
    if (_mmUid()) _mmFetch('/api/motion-mirror/stop', { method: 'POST' }).catch(()=>{});
}

async function mmSendFrame() {
    if (!mmStream || !mmSessionActive) return;
    const video = document.getElementById('mm_video');
    if (!video.videoWidth) return;

    // ย่อขนาดภาพเพื่อลด bandwidth (160x120 jpeg quality 0.6 ~ 5-10KB ต่อเฟรม)
    const canvas = document.createElement('canvas');
    canvas.width = 160; canvas.height = 120;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0, 160, 120);
    const b64 = canvas.toDataURL('image/jpeg', 0.6);

    try {
        const r = await _mmFetch('/api/motion-mirror/frame', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ image: b64 })
        });
        const d = await r.json();
        if (d.st === 'ok' && d.detected) {
            document.getElementById('mm_pose_label').innerText = 'ท่า: ' + (d.action?.label || d.pose);
            document.getElementById('mm_action_label').innerText = (d.action?.emoji || '') + ' → animation: ' + (d.action?.anim || 'idle');
            window._mmLastFrame = d;
        }
    } catch (e) { /* เงียบ */ }
}

// --- วาดตัวละครเกมง่ายๆ ที่จะทำท่าตามที่ server ส่งกลับมา ---
let mmCharFrame = 0;
function mmDrawCharacter() {
    if (!mmSessionActive) return;
    const canvas = document.getElementById('mm_char_canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const w = canvas.width, h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    ctx.fillStyle = '#0a141a';
    ctx.fillRect(0, 0, w, h);

    const frame = window._mmLastFrame;
    const pose = frame?.pose || 'unknown';
    mmCharFrame++;
    const t = mmCharFrame / 30;

    const cx = w / 2, cy = h / 2 + 10;

    // ศีรษะ
    ctx.fillStyle = '#0fc';
    ctx.beginPath();
    ctx.arc(cx, cy - 30, 10, 0, Math.PI * 2);
    ctx.fill();

    // ลำตัว
    ctx.strokeStyle = '#0fc';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(cx, cy - 20);
    ctx.lineTo(cx, cy + 10);
    ctx.stroke();

    let lArmAngle = -0.5, rArmAngle = 0.5;
    let lLegAngle = -0.3, rLegAngle = 0.3;
    let bodyDy = 0;

    switch (pose) {
        case 'tpose':          lArmAngle = -Math.PI/2; rArmAngle = Math.PI/2; break;
        case 'hand_left_up':   lArmAngle = -Math.PI*0.85; rArmAngle = 0.4; break;
        case 'hand_right_up':  lArmAngle = -0.4; rArmAngle = Math.PI*0.85; break;
        case 'both_hands_up':  lArmAngle = -Math.PI*0.85; rArmAngle = Math.PI*0.85; break;
        case 'wave':           lArmAngle = -Math.PI*0.9 + Math.sin(t*8)*0.3; rArmAngle = 0.4; break;
        case 'squat':          lLegAngle = -0.7; rLegAngle = 0.7; bodyDy = 8; break;
        case 'lean_left':      ctx.save(); ctx.translate(cx, cy); ctx.rotate(-0.2); ctx.translate(-cx, -cy); break;
        case 'lean_right':     ctx.save(); ctx.translate(cx, cy); ctx.rotate(0.2); ctx.translate(-cx, -cy); break;
        case 'cross_arms':     lArmAngle = -0.3; rArmAngle = 0.3; break;
    }

    const armLen = 22, legLen = 20;
    const bodyY = cy + bodyDy;

    // แขนซ้าย
    ctx.beginPath();
    ctx.moveTo(cx, bodyY - 15);
    ctx.lineTo(cx + Math.cos(lArmAngle + Math.PI) * armLen, bodyY - 15 + Math.sin(lArmAngle + Math.PI) * armLen);
    ctx.stroke();
    // แขนขวา
    ctx.beginPath();
    ctx.moveTo(cx, bodyY - 15);
    ctx.lineTo(cx + Math.cos(rArmAngle) * armLen, bodyY - 15 + Math.sin(rArmAngle) * armLen);
    ctx.stroke();
    // ขาซ้าย
    ctx.beginPath();
    ctx.moveTo(cx, bodyY + 10);
    ctx.lineTo(cx + Math.cos(lLegAngle + Math.PI) * legLen, bodyY + 10 + Math.sin(lLegAngle + Math.PI) * legLen);
    ctx.stroke();
    // ขาขวา
    ctx.beginPath();
    ctx.moveTo(cx, bodyY + 10);
    ctx.lineTo(cx + Math.cos(rLegAngle) * legLen, bodyY + 10 + Math.sin(rLegAngle) * legLen);
    ctx.stroke();

    if (pose === 'lean_left' || pose === 'lean_right') ctx.restore();

    ctx.fillStyle = '#fff';
    ctx.font = '10px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(pose, w/2, h - 5);

    requestAnimationFrame(mmDrawCharacter);
}
"""

# --- Flask routes สำหรับ Motion Mirror ---
@app.route('/api/motion-mirror/start', methods=['POST'])
@require_auth_toggleable
def api_motion_mirror_start():
    uid = getattr(request, 'vmax_uid', None) or resolve_uid()
    return jsonify(motion_mirror_start_session(uid))

@app.route('/api/motion-mirror/stop', methods=['POST'])
@require_auth_toggleable
def api_motion_mirror_stop():
    uid = getattr(request, 'vmax_uid', None) or resolve_uid()
    return jsonify(motion_mirror_stop_session(uid))

@app.route('/api/motion-mirror/status')
@require_auth_toggleable
def api_motion_mirror_status_route():
    uid = getattr(request, 'vmax_uid', None) or resolve_uid()
    return jsonify(motion_mirror_status(uid))

@app.route('/api/motion-mirror/frame', methods=['POST'])
@require_auth_toggleable
def api_motion_mirror_frame():
    """body: {"image": "<base64 jpeg/png จากกล้อง>"} → ตรวจท่าทาง → คืน pose + action
    ที่ตัวละครในเกมจะเล่นทันที ใช้สำหรับ 'เปิดกล้องแล้วทำท่า → ตัวละครทำตาม'"""
    uid = getattr(request, 'vmax_uid', None) or resolve_uid()
    body = request.get_json(force=True, silent=True) or {}
    img_b64 = body.get("image", "")
    # ตัด data URL prefix ถ้ามี (เช่น "data:image/jpeg;base64,....")
    if "," in img_b64 and img_b64.startswith("data:"):
        img_b64 = img_b64.split(",", 1)[1]
    try:
        img_bytes = base64.b64decode(img_b64)
    except Exception:
        return jsonify({"st": "error", "msg": "image ต้องเป็น base64 string ที่ถูกต้อง"}), 400
    return jsonify(motion_mirror_process_frame(uid, img_bytes))

@app.route('/widgets/motion-mirror')
def widget_motion_mirror():
    return MOTION_MIRROR_WIDGET_HTML + "<script>" + MOTION_MIRROR_WIDGET_JS + "</script>"

