SURVIVAL_GAME_HTML = r'''
<!DOCTYPE html>
<html lang="th">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>Blood Frost Survival</title>
    <style>
        * { box-sizing: border-box; }
        body { margin: 0; background: #050000; color: #b00; font-family: monospace; overflow: hidden; touch-action: none; user-select: none; }
        #game-container { position: relative; width: 100vw; height: 100vh; display: flex; justify-content: center; align-items: center; }
        canvas { background: #1a0505; border: 2px solid #500; image-rendering: pixelated; }
        
        #hud { position: absolute; top: 10px; left: 10px; background: rgba(20,0,0,0.8); padding: 10px; border-radius: 5px; width: 180px; border: 1px solid #700; display: none; z-index: 5; }
        .stat-bar { margin-bottom: 4px; }
        .stat-label { font-size: 11px; display: flex; justify-content: space-between; color: #a00; }
        .bar-bg { width: 100%; height: 6px; background: #300; border-radius: 3px; }
        .bar-fill { height: 100%; border-radius: 3px; transition: width 0.3s; }

        #inventory { position: absolute; bottom: 100px; right: 10px; background: rgba(20,0,0,0.9); padding: 10px; border-radius: 5px; display: none; border: 1px solid #700; z-index: 5; }
        .slot-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 5px; }
        .slot { width: 50px; height: 50px; background: #100; border: 1px solid #500; display: flex; justify-content: center; align-items: center; font-size: 9px; text-align: center; cursor: pointer; color: #b00; }
        .equip-slot { border-color: #700; }
        
        #wheel { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); display: none; pointer-events: auto; z-index: 6; }
        .wheel-btn { display: block; background: rgba(40,0,0,0.9); border: 1px solid #800; color: #f00; padding: 8px; margin: 3px 0; width: 180px; text-align: center; cursor: pointer; font-size: 12px; }
        .wheel-btn:disabled { border-color: #333; color: #333; cursor: not-allowed; }

        #blood-overlay { position: absolute; top:0; left:0; width:100%; height:100%; pointer-events: none; box-shadow: inset 0 0 100px #8b0000; opacity: 0; transition: opacity 1s; z-index: 10; }
        #basement-hud { position:absolute; top:10px; right:10px; min-width:205px; background:rgba(5,8,14,.9); color:#dce7ff; border:1px solid #40516f; border-radius:10px; padding:9px; z-index:7; display:none; font-size:12px; }
        #condition-hud { position:absolute; left:10px; top:270px; max-width:260px; background:rgba(15,0,0,.82); color:#ffd8d8; border:1px solid #713838; border-radius:8px; padding:7px 9px; z-index:7; display:none; font-size:11px; }
        #interaction-hud { position:absolute; left:50%; bottom:88px; transform:translateX(-50%); background:rgba(5,8,14,.95); color:#fff; border:1px solid #7083a6; border-radius:12px; padding:9px 13px; z-index:8; display:none; text-align:center; }
        #interaction-hud button { margin-left:8px; border:0; border-radius:8px; padding:7px 11px; font-weight:800; cursor:pointer; }
        
        #main-menu, #death-screen, #dream-ui { position:absolute; top:0; left:0; width:100%; height:100%; display:none; flex-direction:column; justify-content:center; align-items:center; z-index: 20; text-align:center; }
        #main-menu { background:#000; display:flex; z-index: 50; }
        #main-menu h1 { color:#f00; font-size:40px; margin-bottom:40px; text-shadow:0 0 10px #800; }
        .menu-btn { width:220px; padding:15px; margin:10px; background:#200; color:#f00; border:1px solid #800; font-size:18px; cursor:pointer; font-family:monospace; }
        .menu-btn:hover { background:#400; }
        
        #death-screen { background:rgba(0,0,0,0.95); color:#f00; }
        #death-screen h1 { font-size: 40px; margin: 0; text-shadow: 0 0 10px #f00; }
        
        #dream-ui { background:rgba(0,0,0,0.9); color:#a00; }
        #dream-ui h1 { font-size:30px; text-shadow:0 0 10px #f00; }
        .dream-num-btn { width:60px; height:60px; background:#300; color:#fff; border:1px solid #f00; font-size:24px; cursor:pointer; margin: 0 10px; }

        #mobile-controls { position: absolute; bottom: 0; left: 0; width: 100%; height: 200px; pointer-events: none; display: none; z-index: 5; }
        #joystick-zone { position: absolute; bottom: 0; left: 0; width: 50%; height: 100%; pointer-events: auto; }
        #joystick-base, #joystick-stick { position: absolute; border-radius: 50%; display: none; pointer-events: none; }
        #joystick-base { width: 100px; height: 100px; background: rgba(50,0,0,0.5); border: 2px solid #800; }
        #joystick-stick { width: 50px; height: 50px; background: rgba(150,0,0,0.8); border: 1px solid #f00; }
        
        #action-buttons { position: absolute; bottom: 20px; right: 20px; display: flex; flex-direction: column; gap: 10px; pointer-events: auto; }
        .act-btn { width: 60px; height: 60px; background: rgba(40,0,0,0.7); border: 2px solid #800; color: #f00; border-radius: 50%; font-size: 12px; display: flex; justify-content: center; align-items: center; cursor: pointer; }
        .act-btn:active { background: rgba(150,0,0,0.9); }
        #btn-save { display:none; background: rgba(0,40,0,0.7); border-color:#080; color:#0f0; }
        #btn-sleep { display:none; background: rgba(0,0,40,0.7); border-color:#00f; color:#00f; }
    </style>
</head>
<body>
<div id="game-container">
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <div id="main-menu">
        <h1>🩸 BLOOD FROST 🩸</h1>
        <button class="menu-btn" onclick="startGame('classic')">Classic (No Save)</button>
        <button class="menu-btn" onclick="startGame('saves')">With Saves (Easy)</button>
    </div>
    <div id="blood-overlay"></div>
    <div id="basement-hud">
        <div>📅 วันที่ <b id="day-val">1</b>/12</div>
        <div>🛗 ชั้นใต้ดิน <b id="floor-val">บนดิน</b></div>
        <div>🚪 ประตูชั้นถัดไป: <span id="floor-lock-val">-</span></div>
        <div>🚁 รับตัววันที่ 12: <span id="rescue-val">รอ</span></div>
    </div>
    <div id="condition-hud"><b>🩺 อาการ</b><div id="condition-list">ปกติ</div></div>
    <div id="interaction-hud"><span id="interaction-text"></span><button id="interaction-btn">ทำ</button></div>
    <div id="dream-ui">
        <h1>NIGHTMARE</h1>
        <p style="font-size:14px;color:#fff;">ฝันร้ายกำลังจะมากัดกิน! เดาตัวเลข 1-3 ให้ถูก</p>
        <div id="dream-timer" style="font-size:40px;color:#f00;margin:20px;">3</div>
        <div>
            <button class="dream-num-btn" onclick="resolveDream(1)">1</button>
            <button class="dream-num-btn" onclick="resolveDream(2)">2</button>
            <button class="dream-num-btn" onclick="resolveDream(3)">3</button>
        </div>
    </div>
    <div id="death-screen">
        <h1>💀 YOU DIED 💀</h1>
        <p id="death-reason" style="color:#aaa; font-size:16px; margin-top:10px;"></p>
        <button onclick="location.reload()" style="margin-top:20px; padding:10px 20px; background:#500; color:#fff; border:1px solid #f00; cursor:pointer;">RESPAWN</button>
    </div>
    <div id="hud">
        <div class="stat-bar"><div class="stat-label"><span>❤️ HP</span><span id="hp-val">100</span></div><div class="bar-bg"><div id="hp-bar" class="bar-fill" style="width: 100%; background: #e74c3c;"></div></div></div>
        <div class="stat-bar"><div class="stat-label"><span>🌡️ Temp</span><span id="temp-val">37.0</span></div><div class="bar-bg"><div id="temp-bar" class="bar-fill" style="width: 70%; background: #f1c40f;"></div></div></div>
        <div class="stat-bar"><div class="stat-label"><span>🧠 Sanity</span><span id="san-val">100</span></div><div class="bar-bg"><div id="san-bar" class="bar-fill" style="width: 100%; background: #9b59b6;"></div></div></div>
        <div class="stat-bar"><div class="stat-label"><span>💧 Water</span><span id="thirst-val">100</span></div><div class="bar-bg"><div id="thirst-bar" class="bar-fill" style="width: 100%; background: #3498db;"></div></div></div>
        <div class="stat-bar"><div class="stat-label"><span>🍖 Hunger</span><span id="hunger-val">100</span></div><div class="bar-bg"><div id="hunger-bar" class="bar-fill" style="width: 100%; background: #e67e22;"></div></div></div>
        <div class="stat-bar"><div class="stat-label"><span>⚡ Stamina</span><span id="stam-val">100</span></div><div class="bar-bg"><div id="stam-bar" class="bar-fill" style="width: 100%; background: #2ecc71;"></div></div></div>
        <div class="stat-bar"><div class="stat-label"><span>🚽 Waste</span><span id="waste-val">0</span></div><div class="bar-bg"><div id="waste-bar" class="bar-fill" style="width: 0%; background: #8e6b3e;"></div></div></div>
        <div class="stat-bar"><div class="stat-label"><span>🩸 Pain</span><span id="pain-val">0</span></div><div class="bar-bg"><div id="pain-bar" class="bar-fill" style="width: 0%; background: #8b0000;"></div></div></div>
        <div class="stat-bar"><div class="stat-label"><span>🦠 Infection</span><span id="inf-val">0</span></div><div class="bar-bg"><div id="inf-bar" class="bar-fill" style="width: 0%; background: #2ecc71;"></div></div></div>
    </div>
    <div id="inventory">
        <div style="display: flex; gap: 5px; margin-bottom: 5px;">
            <div class="slot equip-slot" id="equip-mask">Mask: OFF</div>
            <div class="slot equip-slot" id="equip-flash">Light: OFF</div>
        </div>
        <div class="slot-grid" id="inv-slots"></div>
    </div>
    <div id="wheel"><div id="wheel-options"></div></div>
    <div id="mobile-controls">
        <div id="joystick-zone"></div>
        <div id="joystick-base"></div>
        <div id="joystick-stick"></div>
        <div id="action-buttons">
            <div class="act-btn" id="btn-save">SAVE</div>
            <div class="act-btn" id="btn-sleep">SLEEP</div>
            <div class="act-btn" id="btn-inv">INV</div>
            <div class="act-btn" id="btn-interact">Q</div>
            <div class="act-btn" id="btn-jump">JUMP</div>
            <div class="act-btn" id="btn-attack">ฟัน</div>
        </div>
    </div>
</div>
'''
SURVIVAL_GAME_HTML += r'''
<script>
let gameMode = 'classic';
const Game = {
    state: 'MENU',
    bloodParticles: [],
    dreamState: { active: false, targetNum: 0, timeLeft: 0 },
    player: {
        x: 400, y: 300, radius: 15, color: 'darkred',
        vx: 0, vy: 0, speed: 3,
        isJumping: false, z: 0, vz: 0,
        isSlipping: false, slipTime: 0,
        stats: { hp: 100, temp: 37, sanity: 100, thirst: 100, hunger: 100, pain: 0, infection: 0, stamina: 100, waste: 0 },
        conditions: { food_poisoning: false, diarrhea: false, vomiting: false, fever: false, headache: false },
        conditionTick: 0,
        inventory: [null, null],
        maxSlots: 2,
        equipped: { mask: false, flashlight: false, flashlightBattery: 100 }
    },
    world: {
        iceZone: { x: 500, y: 100, w: 300, h: 400 },
        cleanWaterZone: { x: 100, y: 100, w: 100, h: 100 },
        dirtyWaterZone: { x: 250, y: 100, w: 100, h: 100 },
        tentZone: { x: 100, y: 400, w: 150, h: 150 },
        helicopterActive: false,
        bedZone: { x: 55, y: 360, w: 120, h: 100 },
        bathroomZone: { x: 205, y: 400, w: 90, h: 95 },
        lowerDoorZone: { x: 350, y: 65, w: 110, h: 80 },
        basementExitZone: { x: 680, y: 420, w: 90, h: 100 }
    },
    expedition: {
        day: 1,
        rescueDay: 12,
        basementActive: false,
        floor: 40,
        totalFloors: 40,
        doorSawed: false,
        floorKey: false,
        specialKeys: [],
        rescued: false,
        lastSleepDay: 1
    },
    itemsOnGround: [
        {id: 'empty_bottle', x: 200, y: 200}, {id: 'chocolate', x: 300, y: 200},
        {id: 'beer', x: 250, y: 250}, {id: 'battery', x: 600, y: 300},
        {id: 'flare_wet', x: 650, y: 350}, {id: 'backpack', x: 150, y: 450},
        {id: 'painkiller', x: 400, y: 300}, {id: 'antibiotic', x: 450, y: 250},
        {id: 'snack', x: 280, y: 300}, {id: 'biscuit', x: 315, y: 300},
        {id: 'ration_bar', x: 350, y: 300}, {id: 'canned_food', x: 390, y: 300},
        {id: 'grilled_meat', x: 430, y: 300}, {id: 'premium_meal', x: 470, y: 300},
        {id: 'bandage', x: 350, y: 350}, {id: 'mask', x: 550, y: 200},
        {id: 'saw', x: 320, y: 520}, {id: 'flare_gun', x: 430, y: 520},
        {id: 'spoiled_food', x: 720, y: 220}
    ]
};

const ItemDB = {
    empty_bottle: { name: 'ขวดว่าง', type: 'tool' },
    water_bottle: { name: 'น้ำดื่ม', type: 'consumable', effect: { thirst: +30, temp: -0.5 }, transformsTo: 'empty_bottle' },
    dirty_water: { name: 'น้ำสกปรก', type: 'consumable', effect: { thirst: +20, hp: -5, infection: +30 }, transformsTo: 'empty_bottle' },
    painkiller: { name: 'ยาแก้ปวด', type: 'consumable', effect: { pain: -60, hp: +5 } },
    antibiotic: { name: 'ยาปฏิชีวนะ', type: 'consumable', effect: { infection: -80, hp: +10 } },
    bandage: { name: 'ผ้าพันแผล', type: 'consumable', effect: { hp: +20, pain: -10 } },
    chocolate: { name: 'ช็อกโกแลต', type: 'consumable', effect: { temp: -1.0, sanity: -5, stamina: +10 } },
    beer: { name: 'เบียร์', type: 'consumable', effect: { temp: -2.0, sanity: -15, thirst: +10, pain: -20 }, transformsTo: 'empty_bottle' },
    battery: { name: 'ถ่านไฟฉาย', type: 'tool' },
    flare_wet: { name: 'พลุเปียก', type: 'tool' },
    flare_dry: { name: 'พลุแห้ง', type: 'tool' },
    backpack: { name: 'กระเป๋า', type: 'upgrade' },
    mask: { name: 'หน้ากาก', type: 'wearable' },
    flashlight: { name: 'ไฟฉาย', type: 'wearable' },
    saw: { name: 'เลื่อย', type: 'tool' },
    flare_gun: { name: 'ปืนแฟลร์', type: 'tool' },
    floor_key: { name: 'กุญแจปลดล็อกชั้น', type: 'key' },
    security_card: { name: 'คีย์การ์ดความปลอดภัย', type: 'key' },
    snack: { name: 'ขนม', type: 'consumable', food: { hunger: 16, stamina: 7, thirst: -1, waste: 4 } },
    biscuit: { name: 'บิสกิต', type: 'consumable', food: { hunger: 24, stamina: 5, thirst: -2, waste: 6 } },
    ration_bar: { name: 'แท่งอาหารสนาม', type: 'consumable', food: { hunger: 32, stamina: 12, thirst: -3, waste: 8 } },
    canned_food: { name: 'อาหารกระป๋อง', type: 'consumable', food: { hunger: 42, stamina: 10, thirst: -5, waste: 12 } },
    grilled_meat: { name: 'เนื้อย่าง', type: 'consumable', food: { hunger: 52, stamina: 18, thirst: -6, waste: 20 } },
    roasted_boar: { name: 'หมูป่าย่าง', type: 'consumable', food: { hunger: 68, stamina: 26, thirst: -9, waste: 28 } },
    energy_meal: { name: 'อาหารพลังงานสูง', type: 'consumable', food: { hunger: 76, stamina: 34, thirst: -12, waste: 34 } },
    premium_meal: { name: 'อาหารปรุงสุกพิเศษ', type: 'consumable', food: { hunger: 86, stamina: 42, thirst: -15, waste: 40 } },
    spoiled_food: { name: 'อาหารเสีย', type: 'consumable', effect: { thirst: -5, stamina: -5 }, food: { hunger: 10, stamina: -5, thirst: -5, waste: 30 } }
};

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const keys = {};

function resizeCanvas() {
    let scale = Math.min(window.innerWidth / 800, window.innerHeight / 600);
    canvas.style.width = (800 * scale) + 'px';
    canvas.style.height = (600 * scale) + 'px';
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

function showNotif(msg) {
    let n = document.getElementById('notif');
    if(!n) {
        n = document.createElement('div');
        n.id = 'notif';
        n.style.cssText = 'position:absolute;bottom:200px;left:50%;transform:translateX(-50%);background:#fff;color:#000;padding:5px 10px;border-radius:5px;z-index:30;';
        document.getElementById('game-container').appendChild(n);
    }
    n.innerText = msg; n.style.display = 'block';
    clearTimeout(n.timer);
    n.timer = setTimeout(() => { n.style.display = 'none'; }, 2000);
}

function normalizeSaveData(data) {
    if(!data) return;
    if(data.player) Game.player = Object.assign(Game.player, data.player);
    Game.player.stats = Object.assign({hp:100,temp:37,sanity:100,thirst:100,hunger:100,pain:0,infection:0,stamina:100,waste:0}, Game.player.stats || {});
    Game.player.conditions = Object.assign({food_poisoning:false,diarrhea:false,vomiting:false,fever:false,headache:false}, Game.player.conditions || {});
    Game.player.conditionTick = Number(Game.player.conditionTick || 0);
    Game.player.stats.hunger = Number(Game.player.stats.hunger ?? 100);
    Game.player.stats.waste = Number(Game.player.stats.waste ?? 0);
    Game.player.bathroomBusy = false;
    Game.player.bathroomVulnerable = false;
    if(!Game.expedition) Game.expedition = {};
    Game.expedition = Object.assign({day:1,rescueDay:12,basementActive:false,floor:40,totalFloors:40,doorSawed:false,floorKey:false,specialKeys:[],rescued:false,lastSleepDay:1}, data.expedition || {});
    Game.itemsOnGround = Array.isArray(data.items) ? data.items : Game.itemsOnGround;
}

function startGame(mode) {
    gameMode = mode;
    document.getElementById('main-menu').style.display = 'none';
    document.getElementById('hud').style.display = 'block';
    document.getElementById('mobile-controls').style.display = 'block';
    document.getElementById('basement-hud').style.display = 'block';
    document.getElementById('condition-hud').style.display = 'block';
    if(mode === 'saves') {
        const saved = localStorage.getItem('bfs_save');
        if(saved) {
            try { normalizeSaveData(JSON.parse(saved)); showNotif("โหลดเซฟที่เตียงล่าสุดแล้ว"); }
            catch(e) { showNotif("เซฟเสียหาย เริ่มเกมใหม่"); }
        }
    }
    Game.state = 'PLAYING';
    updateUI();
}

function saveGame() {
    if(gameMode !== 'saves') return;
    if(!isNearBed() || Game.expedition.basementActive) {
        showNotif("ต้องกลับมาที่เตียงเพื่อบันทึกเกม");
        return;
    }
    localStorage.setItem('bfs_save', JSON.stringify({ player: Game.player, items: Game.itemsOnGround, expedition: Game.expedition }));
    showNotif("💾 เซฟที่เตียงสำเร็จ!");
}
'''
SURVIVAL_GAME_HTML += r'''
document.addEventListener('keydown', (e) => {
    keys[e.key.toLowerCase()] = true;
    if (e.key === 'Tab') { e.preventDefault(); toggleInventory(); }
    if (e.key.toLowerCase() === 'q') { toggleWheel(); }
    if (e.key.toLowerCase() === 'f' && gameMode === 'saves') { saveGame(); }
    if (e.key === ' ' && !Game.player.isJumping && !Game.player.isSlipping) {
        Game.player.isJumping = true; Game.player.vz = 10;
    }
});
document.addEventListener('keyup', (e) => { keys[e.key.toLowerCase()] = false; });

let joy = {active: false, sx:0, sy:0, dx:0, dy:0};
const joyZone = document.getElementById('joystick-zone');

joyZone.addEventListener('touchstart', e => {
    let t = e.touches[0];
    joy.active = true; joy.sx = t.clientX; joy.sy = t.clientY;
    document.getElementById('joystick-base').style.left = (t.clientX - 50) + 'px';
    document.getElementById('joystick-base').style.top = (t.clientY - 50) + 'px';
    document.getElementById('joystick-base').style.display = 'block';
    document.getElementById('joystick-stick').style.left = (t.clientX - 25) + 'px';
    document.getElementById('joystick-stick').style.top = (t.clientY - 25) + 'px';
    document.getElementById('joystick-stick').style.display = 'block';
});
joyZone.addEventListener('touchmove', e => {
    let t = e.touches[0];
    joy.dx = t.clientX - joy.sx; joy.dy = t.clientY - joy.sy;
    document.getElementById('joystick-stick').style.left = (t.clientX - 25) + 'px';
    document.getElementById('joystick-stick').style.top = (t.clientY - 25) + 'px';
});
joyZone.addEventListener('touchend', e => {
    joy.active = false; joy.dx = 0; joy.dy = 0;
    document.getElementById('joystick-base').style.display = 'none';
    document.getElementById('joystick-stick').style.display = 'none';
});

document.getElementById('btn-inv').addEventListener('touchstart', e => { e.preventDefault(); toggleInventory(); });
document.getElementById('btn-interact').addEventListener('touchstart', e => { e.preventDefault(); toggleWheel(); });
document.getElementById('btn-save').addEventListener('touchstart', e => { e.preventDefault(); saveGame(); });
document.getElementById('btn-sleep').addEventListener('touchstart', e => { e.preventDefault(); startSleeping(); });
document.getElementById('btn-jump').addEventListener('touchstart', e => { 
    e.preventDefault(); 
    if (!Game.player.isJumping && !Game.player.isSlipping) {
        Game.player.isJumping = true; Game.player.vz = 10;
    }
});

function startSleeping() {
    if(Game.player.stats.stamina > 20) return;
    Game.state = 'SLEEPING';
    Game.dreamState.active = true;
    Game.dreamState.targetNum = Math.floor(Math.random() * 3) + 1;
    Game.dreamState.timeLeft = 3.0;
    document.getElementById('dream-ui').style.display = 'flex';
}

function resolveDream(guess) {
    if(!Game.dreamState.active) return;
    Game.dreamState.active = false;
    document.getElementById('dream-ui').style.display = 'none';
    Game.state = 'PLAYING';
    advanceSurvivalDay();
    if (guess === Game.dreamState.targetNum) {
        Game.player.stats.stamina = 50; 
        Game.player.stats.sanity = Math.min(100, Game.player.stats.sanity + 10);
        showNotif("ตื่นจากฝันร้าย! ได้แรงครึ่งนึง");
    } else {
        Game.player.stats.stamina = 0; 
        Game.player.stats.sanity = Math.max(0, Game.player.stats.sanity - 20);
        showNotif("ฝันร้ายกลืนกิน! แรงหายหมด");
    }
}

function fatalDeath(reason) {
    if(Game.state === 'DEAD') return;
    Game.state = 'DEAD';
    for(let i=0; i<150; i++) {
        Game.bloodParticles.push({
            x: Game.player.x, y: Game.player.y, 
            vx: (Math.random()-0.5)*20, vy: (Math.random()-0.5)*20, 
            life: 100, color: `rgba(139,0,0,1)`
        });
    }
    document.getElementById('death-reason').innerText = reason;
    document.getElementById('death-screen').style.display = 'flex';
}

let lastTime = performance.now();
function update(now) {
    const dt = (now - lastTime) / 1000;
    lastTime = now;
    if (Game.state === 'PLAYING') {
        const p = Game.player;
        let moveX = 0, moveY = 0;
        if (keys['w']) moveY -= 1; if (keys['s']) moveY += 1;
        if (keys['a']) moveX -= 1; if (keys['d']) moveX += 1;
        if (joy.active) {
            moveX = 0; moveY = 0;
            if (joy.dy < -20) moveY = -1; if (joy.dy > 20) moveY = 1;
            if (joy.dx < -20) moveX = -1; if (joy.dx > 20) moveX = 1;
        }
        tickBathroom(dt);
        if (p.bathroomBusy) {
            moveX = 0; moveY = 0;
        }
        if (!p.isSlipping && !p.bathroomBusy) {
            p.x += moveX * p.speed; p.y += moveY * p.speed;
        } else if (!p.bathroomBusy) {
            p.x += p.vx; p.y += p.vy;
            p.slipTime--;
            if(p.slipTime <= 0) p.isSlipping = false;
        }
        p.x = Math.max(0, Math.min(canvas.width, p.x));
        p.y = Math.max(0, Math.min(canvas.height, p.y));

        if (p.isJumping) {
            p.z += p.vz; p.vz -= 0.5;
            if (p.z <= 0) {
                p.z = 0; p.isJumping = false;
                const inIce = p.x > 500 && p.x < 800 && p.y > 100 && p.y < 500;
                if (inIce) fatalDeath("หัวฟาดพื้นน้ำแข็ง! กะโหลกแตก (Fatal Impact)");
            }
        } else {
            const inIce = p.x > 500 && p.x < 800 && p.y > 100 && p.y < 500;
            if (inIce && (moveX !== 0 || moveY !== 0)) {
                if(Math.random() < 0.05 && !p.isSlipping) {
                    p.isSlipping = true; p.slipTime = 30;
                    p.vx = (Math.random()-0.5) * 10; p.vy = (Math.random()-0.5) * 10;
                }
            }
        }

        Game.itemsOnGround.forEach((item, idx) => {
            const itemBelongsHere = Game.expedition.basementActive ? item.floor === Game.expedition.floor : !item.floor;
            if (!itemBelongsHere) return;
            if (Math.abs(p.x - item.x) < 20 && Math.abs(p.y - item.y) < 20) {
                if(addItemToInv(item.id)) {
                    if(item.id==='floor_key') Game.expedition.floorKey=true;
                    Game.itemsOnGround.splice(idx, 1);
                    if(item.id==='floor_key') showNotif('🔑 ได้ไอเทมปลดล็อกประตูชั้นถัดไป');
                }
            }
        });

        // ระบบรับตัวจะเริ่มตามวันเท่านั้น ไม่สุ่มแทรกระหว่างการเล่น
        if(Game.expedition.day>=Game.expedition.rescueDay) Game.world.helicopterActive=true;
        conditionTick(dt);

        p.stats.thirst -= 0.05;
        p.stats.hunger = Math.max(0, (p.stats.hunger ?? 100) - 0.018);
        p.stats.waste = Math.max(0, (p.stats.waste ?? 0) - 0.004);
        p.stats.temp -= 0.01;
        let staminaDrain = 0.02;
        if(p.stats.hunger <= 25) staminaDrain *= 1.45;
        if(p.stats.waste >= 75) staminaDrain *= 1.18;
        p.stats.stamina -= staminaDrain;
        document.getElementById('btn-sleep').style.display = (p.stats.stamina <= 20 && isNearBed() && !Game.expedition.basementActive) ? 'flex' : 'none';

        if(p.stats.temp < 34) p.stats.hp -= 0.1;
        if(p.stats.pain > 50) p.stats.hp -= 0.05;
        if(p.stats.infection > 50) p.stats.hp -= 0.1;
        if(p.stats.thirst <= 0) { p.stats.thirst = 0; p.stats.hp -= 0.1; }
        if(p.stats.hunger <= 0) { p.stats.hunger = 0; p.stats.hp -= 0.08; }
        if(p.stats.stamina <= 0) { p.stats.stamina = 0; p.stats.sanity -= 0.05; }
        if(p.stats.hp <= 0) fatalDeath("เสียเลือดจนหมดสติ ตายอย่างทรมาน");
        
        if(p.equipped.flashlight) {
            p.equipped.flashlightBattery -= 0.05;
            if(p.equipped.flashlightBattery <= 0) p.equipped.flashlight = false;
        }

        const san = p.stats.sanity;
        const bloodOverlay = document.getElementById('blood-overlay');
        if (san < 50) bloodOverlay.style.opacity = (50 - san) / 100;
        if (p.stats.hp < 30) bloodOverlay.style.opacity = Math.max(bloodOverlay.style.opacity, (30 - p.stats.hp) / 50);
    } 
    else if (Game.state === 'SLEEPING') {
        Game.dreamState.timeLeft -= dt;
        document.getElementById('dream-timer').innerText = Math.ceil(Game.dreamState.timeLeft);
        if (Game.dreamState.timeLeft <= 0) resolveDream(0);
    }
    updateUI();
}
'''
SURVIVAL_GAME_HTML += r'''
function isNearRect(p, r, pad=0) {
    return p.x >= r.x-pad && p.x <= r.x+r.w+pad && p.y >= r.y-pad && p.y <= r.y+r.h+pad;
}
function isNearBed() { return isNearRect(Game.player, Game.world.bedZone, 28); }
function isNearLowerDoor() { return isNearRect(Game.player, Game.world.lowerDoorZone, 28); }
function isNearBasementExit() { return isNearRect(Game.player, Game.world.basementExitZone, 30); }
function hasItem(id) { return Game.player.inventory.includes(id); }
function consumeItem(id) {
    const i=Game.player.inventory.indexOf(id);
    if(i<0) return false;
    Game.player.inventory[i]=null;
    return true;
}
function advanceSurvivalDay() {
    if(Game.expedition.day >= Game.expedition.rescueDay) return;
    Game.expedition.day += 1;
    Game.expedition.lastSleepDay = Game.expedition.day;
    Game.player.stats.thirst = Math.max(0, Game.player.stats.thirst - 8);
    Game.player.stats.stamina = Math.min(100, Game.player.stats.stamina + 35);
    if(Game.expedition.day >= Game.expedition.rescueDay) {
        Game.world.helicopterActive = true;
        showNotif("🚁 วันที่ 12 — ทีมรับตัวมาถึงแล้ว! ใช้ปืนแฟลร์ส่งสัญญาณ");
    } else {
        showNotif("📅 ขึ้นวันที่ " + Game.expedition.day);
    }
}
function spawnBasementKey() {
    Game.expedition.floorKey = false;
    // key is placed on the current floor; only one key is needed to open the next door
    const existing = Game.itemsOnGround.findIndex(x => x.id === 'floor_key');
    if(existing >= 0) Game.itemsOnGround.splice(existing,1);
    const x = 120 + Math.random()*560, y = 150 + Math.random()*300;
    Game.itemsOnGround.push({id:'floor_key', x, y, floor:Game.expedition.floor});
}
function cutBasementDoor() {
    if(Game.expedition.basementActive) return;
    if(!isNearLowerDoor()) { showNotif("ต้องเข้าใกล้ประตูชั้นล่างก่อน"); return; }
    if(!hasItem('saw')) { showNotif("🪚 ต้องมีเลื่อยก่อน"); return; }
    if(gameMode==='saves' && !localStorage.getItem('bfs_save')) { showNotif("💾 ก่อนลงไปข้างล่าง ให้เซฟที่เตียงก่อน"); return; }
    consumeItem('saw');
    Game.expedition.doorSawed = true;
    Game.expedition.basementActive = true;
    Game.expedition.floor = 40;
    Game.expedition.floorKey = false;
    spawnBasementKey();
    Game.player.x = 400; Game.player.y = 300;
    showNotif("🪚 เลื่อยประตูสำเร็จ — ลงสู่ชั้น 40");
}
function descendNextFloor() {
    if(!Game.expedition.basementActive) return;
    if(Game.expedition.floor <= 0) { exitFloorZero(); return; }
    if(!Game.expedition.floorKey && !hasItem('floor_key')) {
        showNotif("🔐 ประตูล็อก — ต้องหาของปลดล็อกชั้นนี้ก่อน");
        return;
    }
    consumeItem('floor_key');
    Game.expedition.floorKey = false;
    Game.expedition.floor -= 1;
    if(Game.expedition.floor > 0) spawnBasementKey();
    else showNotif("🟢 ถึงชั้น 0 แล้ว — ไปที่ทางออกเพื่อจบภารกิจ");
    Game.player.x=400; Game.player.y=300;
}
function exitFloorZero() {
    if(Game.expedition.floor !== 0 || !Game.expedition.basementActive) return;
    if(!isNearBasementExit()) { showNotif("ไปที่ประตูทางออกของชั้น 0"); return; }
    Game.expedition.basementActive=false;
    Game.expedition.rescued=true;
    showNotif("🏁 ออกจากชั้น 0 สำเร็จ! ภารกิจ 40 ชั้นจบแล้ว");
    Game.state='WIN';
    setTimeout(()=>alert('🏁 ESCAPE COMPLETE\nออกจากชั้น 0 สำเร็จ'),100);
}
function signalRescue() {
    if(Game.expedition.day < Game.expedition.rescueDay) { showNotif("🚁 ทีมรับตัวยังไม่มา — รอถึงวันที่ 12"); return; }
    if(!Game.world.helicopterActive) { showNotif("🚁 เฮลิคอปเตอร์ยังไม่อยู่ในพื้นที่"); return; }
    if(!hasItem('flare_gun') || !hasItem('flare_dry')) { showNotif("ต้องมีปืนแฟลร์ + พลุแห้ง"); return; }
    consumeItem('flare_dry');
    Game.world.helicopterActive=false;
    Game.expedition.rescued=true;
    Game.state='WIN';
    showNotif("🚁 ยิงแฟลร์แล้ว! ทีมรับตัวกำลังลงจอด");
    setTimeout(()=>alert('🚁 RESCUE COMPLETE\nคุณได้รับการช่วยเหลือในวันที่ 12'),500);
}
function getConditionLabels() {
    const p=Game.player, out=[];
    if(p.stats.infection>0) out.push('🦠 ติดเชื้อ '+Math.round(p.stats.infection)+'%');
    if((p.stats.hunger||0) <= 25) out.push('🍖 หิวมาก — พลังงานลดลง');
    if((p.stats.waste||0) >= 75) out.push('🚽 ปวดท้อง/ต้องหาห้องน้ำ');
    if(p.bathroomVulnerable) out.push('⚠️ ตัวละครอยู่นิ่ง — เสี่ยงถูกพบ');
    if(p.conditions.food_poisoning) out.push('🤢 อาหารเป็นพิษ');
    if(p.conditions.diarrhea) out.push('💩 ท้องเสีย');
    if(p.conditions.vomiting) out.push('🤮 อาเจียน');
    if(p.conditions.fever) out.push('🌡️ มีไข้');
    if(p.conditions.headache) out.push('🤕 ปวดหัว');
    return out.length?out:['✅ ปกติ'];
}
function conditionTick(dt) {
    const p=Game.player, c=p.conditions||{};
    p.conditionTick=(p.conditionTick||0)+dt;
    if(p.stats.temp>=38) c.fever=true;
    else if(p.stats.temp<37.4) c.fever=false;
    if(p.stats.infection>=35) c.headache=true;
    if(p.stats.infection<15) c.headache=false;
    if(p.conditionTick<2) return;
    p.conditionTick=0;
    if(c.food_poisoning) { p.stats.thirst=Math.max(0,p.stats.thirst-1.2); p.stats.stamina=Math.max(0,p.stats.stamina-0.8); if(Math.random()<0.08)c.vomiting=true; if(Math.random()<0.15)c.diarrhea=true; }
    if(c.diarrhea) p.stats.thirst=Math.max(0,p.stats.thirst-0.7);
    if(c.vomiting) { p.stats.hp=Math.max(0,p.stats.hp-0.8); p.stats.thirst=Math.max(0,p.stats.thirst-2); c.vomiting=false; }
    if(c.fever) p.stats.hp=Math.max(0,p.stats.hp-0.35);
    if(c.headache) p.stats.sanity=Math.max(0,p.stats.sanity-0.25);
    if(p.stats.infection>50) p.stats.hp=Math.max(0,p.stats.hp-0.25);
}
function isNearBathroom() { return isNearRect(Game.player, Game.world.bathroomZone, 28); }
function startBathroomUse() {
    const p=Game.player;
    if(!isNearBathroom()) { showNotif('ต้องอยู่ใกล้ห้องน้ำก่อน'); return; }
    if((p.stats.waste||0) < 75) { showNotif('ตอนนี้ยังไม่จำเป็นต้องเข้าห้องน้ำ'); return; }
    if(p.bathroomBusy) return;
    p.bathroomBusy=true;
    p.bathroomTimer=4.0;
    p.bathroomVulnerable=true;
    p.lastNoise=18;
    p.lastNoiseKind='bathroom';
    p.trace={kind:'bathroom_trace',x:p.x,y:p.y,strength:24,expiresAt:performance.now()/1000+45};
    showNotif('🚽 กำลังเข้าห้องน้ำ — ตัวละครอยู่นิ่งและเสี่ยงถูกพบ');
}
function tickBathroom(dt) {
    const p=Game.player;
    if(!p.bathroomBusy) return;
    p.bathroomTimer=Math.max(0,p.bathroomTimer-dt);
    p.bathroomVulnerable=true;
    if(p.bathroomTimer<=0) {
        p.bathroomBusy=false;
        p.bathroomVulnerable=false;
        p.stats.waste=0;
        p.lastNoise=0;
        showNotif('🚽 เข้าห้องน้ำเสร็จแล้ว — ภาระขับถ่ายถูกล้าง');
    }
}

function updateInteractionHUD() {
    const hud=document.getElementById('interaction-hud'), text=document.getElementById('interaction-text'), btn=document.getElementById('interaction-btn');
    if(!hud) return;
    let action=null,label='';
    if(Game.expedition.basementActive) {
        if(Game.expedition.floor>0 && isNearLowerDoor()) { action=descendNextFloor; label='🔐 ประตูชั้น '+Game.expedition.floor+' → '+(Game.expedition.floor-1); }
        else if(Game.expedition.floor===0 && isNearBasementExit()) { action=exitFloorZero; label='🚪 ออกจากชั้น 0'; }
    } else if(isNearBathroom() && (Game.player.stats.waste||0) >= 75) { action=startBathroomUse; label='🚽 เข้าห้องน้ำ ('+Math.round(Game.player.stats.waste||0)+'%)'; }
    else if(isNearLowerDoor() && !Game.expedition.doorSawed) { action=cutBasementDoor; label='🪚 เลื่อยประตูลงชั้น 40'; }
    else if(isNearBed()) { action=saveGame; label='💾 เซฟที่เตียง'; }
    if(action) { hud.style.display='block'; text.textContent=label; btn.onclick=action; }
    else hud.style.display='none';
    const saveBtn=document.getElementById('btn-save');
    if(saveBtn) saveBtn.style.display=(gameMode==='saves' && isNearBed() && !Game.expedition.basementActive)?'flex':'none';
}

function addItemToInv(item) {
    for(let i=0; i<Game.player.maxSlots; i++) {
        if (Game.player.inventory[i] === null) {
            Game.player.inventory[i] = item;
            updateUI();
            return true;
        }
    }
    showNotif("กระเป๋าเต็ม!");
    return false;
}

function removeItemFromInv(index) {
    const item = Game.player.inventory[index];
    Game.player.inventory[index] = null;
    updateUI();
    return item;
}

function toggleInventory() {
    const inv = document.getElementById('inventory');
    inv.style.display = inv.style.display === 'block' ? 'none' : 'block';
    updateUI();
}

function toggleWheel() {
    const wheel = document.getElementById('wheel');
    wheel.style.display = wheel.style.display === 'block' ? 'none' : 'block';
    if (wheel.style.display === 'block') renderWheel();
}

function renderWheel() {
    const opts = document.getElementById('wheel-options');
    opts.innerHTML = '';
    const p = Game.player;
    const w = Game.world;
    const isInCleanWater = p.x > w.cleanWaterZone.x && p.x < w.cleanWaterZone.x+w.cleanWaterZone.w && p.y > w.cleanWaterZone.y && p.y < w.cleanWaterZone.y+w.cleanWaterZone.h;
    const isInDirtyWater = p.x > w.dirtyWaterZone.x && p.x < w.dirtyWaterZone.x+w.dirtyWaterZone.w && p.y > w.dirtyWaterZone.y && p.y < w.dirtyWaterZone.y+w.dirtyWaterZone.h;
    const isInTent = p.x > w.tentZone.x && p.x < w.tentZone.x+w.tentZone.w && p.y > w.tentZone.y && p.y < w.tentZone.y+w.tentZone.h;
    const hasEmptyBottle = p.inventory.includes('empty_bottle');
    const hasDirtyWater = p.inventory.includes('dirty_water');
    const hasWetFlare = p.inventory.includes('flare_wet');
    const hasBattery = p.inventory.includes('battery');

    addWheelBtn('เติมน้ำสะอาด', isInCleanWater && hasEmptyBottle, () => {
        const idx = p.inventory.indexOf('empty_bottle');
        p.inventory[idx] = 'water_bottle'; updateUI(); toggleWheel();
    });
    addWheelBtn('ตักน้ำสกปรก', isInDirtyWater && hasEmptyBottle, () => {
        const idx = p.inventory.indexOf('empty_bottle');
        p.inventory[idx] = 'dirty_water'; updateUI(); toggleWheel();
    });
    addWheelBtn('ต้มน้ำฆ่าเชื้อ', isInTent && hasDirtyWater, () => {
        const idx = p.inventory.indexOf('dirty_water');
        p.inventory[idx] = 'water_bottle'; updateUI(); toggleWheel();
    });
    addWheelBtn('อบพลุให้แห้ง', isInTent && hasWetFlare, () => {
        const idx = p.inventory.indexOf('flare_wet');
        p.inventory[idx] = 'flare_dry'; updateUI(); toggleWheel();
    });
    addWheelBtn('เปลี่ยนถ่านไฟฉาย', p.equipped.flashlight && hasBattery && p.equipped.flashlightBattery <= 0, () => {
        const idx = p.inventory.indexOf('battery');
        removeItemFromInv(idx);
        p.equipped.flashlightBattery = 100; updateUI(); toggleWheel();
    });
    addWheelBtn('🪚 เลื่อยประตูลงชั้น 40', !Game.expedition.basementActive && isNearLowerDoor() && hasItem('saw'), cutBasementDoor);
    addWheelBtn('🔐 เปิดประตูชั้นถัดไป', Game.expedition.basementActive && Game.expedition.floor > 0 && (Game.expedition.floorKey || hasItem('floor_key')), descendNextFloor);
    addWheelBtn('🚪 ออกจากชั้น 0', Game.expedition.basementActive && Game.expedition.floor === 0 && isNearBasementExit(), exitFloorZero);
    addWheelBtn('💾 เซฟที่เตียง', gameMode === 'saves' && isNearBed() && !Game.expedition.basementActive, saveGame);
    addWheelBtn('🚁 ยิงแฟลร์ขอความช่วยเหลือ', p.inventory.includes('flare_gun') && p.inventory.includes('flare_dry') && w.helicopterActive, signalRescue);
    addWheelBtn('ยิงพลุขอความช่วยเหลือ', p.inventory.includes('flare_dry') && w.helicopterActive, () => {
        Game.state = 'WIN';
        alert("ยิงพลุถูกต้อง! คุณรอดชีวิตแล้ว");
        location.reload();
    });
    addWheelBtn(p.equipped.mask ? 'ถอดหน้ากาก' : 'ใส่หน้ากาก', p.inventory.includes('mask') || p.equipped.mask, () => {
        if(p.equipped.mask) {
            addItemToInv('mask'); p.equipped.mask = false;
        } else {
            const idx = p.inventory.indexOf('mask'); removeItemFromInv(idx); p.equipped.mask = true;
        }
        updateUI(); toggleWheel();
    });
}

function addWheelBtn(label, enabled, action) {
    const btn = document.createElement('button');
    btn.className = 'wheel-btn';
    btn.innerText = label + (!enabled ? ' (Locked)' : '');
    btn.disabled = !enabled;
    btn.onclick = action;
    document.getElementById('wheel-options').appendChild(btn);
}

function applyFoodEffect(itemId, item, p) {
    if (!item || !item.food || !p || !p.stats) return;
    const f = item.food;
    p.stats.hunger = Math.max(0, Math.min(100, (p.stats.hunger ?? 100) + (f.hunger || 0)));
    p.stats.thirst = Math.max(0, Math.min(100, p.stats.thirst + (f.thirst || 0)));
    p.stats.stamina = Math.max(0, Math.min(100, p.stats.stamina + (f.stamina || 0)));
    p.stats.waste = Math.max(0, Math.min(100, (p.stats.waste ?? 0) + (f.waste || 0)));
    if (itemId === 'spoiled_food') {
        p.conditions.food_poisoning = true;
        p.conditions.diarrhea = true;
        p.stats.waste = Math.min(100, p.stats.waste + 15);
    }
    if (p.stats.waste >= 75) showNotif('🚽 ภาระขับถ่ายสูง — ควรหาห้องน้ำ');
    if (item.food.quality === 'premium' || item.food.hunger >= 70) {
        showNotif('🍱 อาหารคุณภาพสูงฟื้นหิว/พลังงานมาก แต่เพิ่มภาระขับถ่ายเร็ว');
    }
}

function useItem(index) {
    const itemId = Game.player.inventory[index];
    const item = ItemDB[itemId];
    if (!item) return;
    if (item.type === 'consumable') {
        Object.keys(item.effect || {}).forEach(stat => {
            Game.player.stats[stat] = Math.max(0, Game.player.stats[stat] + item.effect[stat]);
        });
        applyFoodEffect(itemId, item, Game.player);
        if(itemId === 'spoiled_food') { Game.player.conditions.food_poisoning=true; Game.player.conditions.diarrhea=true; showNotif('🤢 อาหารเป็นพิษ!'); }
        if(itemId === 'dirty_water') { Game.player.stats.infection=Math.min(100,Game.player.stats.infection+15); if(Math.random()<0.35) Game.player.conditions.food_poisoning=true; }
        if (item.transformsTo) Game.player.inventory[index] = item.transformsTo;
        else removeItemFromInv(index);
        updateUI();
    } else if (item.type === 'wearable') {
        if(itemId === 'mask') { Game.player.equipped.mask = true; removeItemFromInv(index); }
        if(itemId === 'flashlight') { Game.player.equipped.flashlight = true; removeItemFromInv(index); }
        updateUI();
    } else if (item.type === 'upgrade') {
        if(itemId === 'backpack') { Game.player.maxSlots = 4; Game.player.inventory.push(null, null); removeItemFromInv(index); updateUI(); }
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if(Game.expedition.basementActive) {
        ctx.fillStyle='#10141d'; ctx.fillRect(0,0,800,600);
        ctx.fillStyle='#202a38'; ctx.fillRect(50,50,700,500);
        ctx.fillStyle='#4b5568'; ctx.fillRect(350,65,110,80);
        ctx.fillStyle='#dbe5f4'; ctx.font='14px monospace';
        ctx.fillText('BASEMENT FLOOR '+Game.expedition.floor, 60, 85);
        ctx.fillText(Game.expedition.floor===0?'EXIT':'LOCKED DOOR', 360, 108);
        ctx.fillStyle='#334155'; ctx.fillRect(680,420,90,100);
        ctx.fillStyle='#fff'; ctx.fillText('EXIT',700,470);
    } else {
        ctx.fillStyle = '#003366'; ctx.fillRect(100, 100, 100, 100);
        ctx.fillStyle = '#332200'; ctx.fillRect(250, 100, 100, 100);
        ctx.fillStyle = '#222200'; ctx.fillRect(100, 400, 150, 150);
        ctx.fillStyle='#5b3b2a'; ctx.fillRect(Game.world.bathroomZone.x,Game.world.bathroomZone.y,Game.world.bathroomZone.w,Game.world.bathroomZone.h);
        ctx.fillStyle='#fff'; ctx.fillText('BATHROOM', Game.world.bathroomZone.x+8, Game.world.bathroomZone.y+45);
        ctx.fillStyle = '#e0e0e0'; ctx.fillRect(500, 100, 300, 400);
        ctx.fillStyle = '#fff'; ctx.font = '12px monospace';
        ctx.fillText("Clean H2O", 110, 130); ctx.fillText("Dirty H2O", 260, 130);
        ctx.fillText("Tent", 140, 430); ctx.fillText("ICE ZONE (FATAL FALL)", 550, 130);
        ctx.fillStyle='#5b4636'; ctx.fillRect(Game.world.bedZone.x,Game.world.bedZone.y,Game.world.bedZone.w,Game.world.bedZone.h);
        ctx.fillStyle='#fff'; ctx.fillText('BED / SAVE', Game.world.bedZone.x+15, Game.world.bedZone.y+28);
        ctx.fillStyle='#3d2d25'; ctx.fillRect(Game.world.lowerDoorZone.x,Game.world.lowerDoorZone.y,Game.world.lowerDoorZone.w,Game.world.lowerDoorZone.h);
        ctx.fillStyle='#fff'; ctx.fillText(Game.expedition.doorSawed?'OPEN':'SAW DOOR', Game.world.lowerDoorZone.x+12, Game.world.lowerDoorZone.y+42);
    }

    Game.itemsOnGround.forEach(item => {
        if(item.floor && (!Game.expedition.basementActive || item.floor !== Game.expedition.floor)) return;
        ctx.fillStyle = item.id==='floor_key' ? '#ffd166' : '#888';
        ctx.fillRect(item.x - 5, item.y - 5, 10, 10);
        ctx.fillStyle = '#fff'; ctx.font = '9px monospace';
        ctx.fillText(ItemDB[item.id].name, item.x - 10, item.y + 15);
    });

    const p = Game.player;
    ctx.fillStyle = p.color;
    ctx.beginPath(); ctx.arc(p.x, p.y - p.z, p.radius, 0, Math.PI * 2); ctx.fill();
    if(p.isJumping) {
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.beginPath(); ctx.ellipse(p.x, p.y, p.radius, p.radius/2, 0, 0, Math.PI * 2); ctx.fill();
    }
    Game.bloodParticles.forEach(b => {
        b.x += b.vx; b.y += b.vy; b.vy += 0.5; b.life--;
        ctx.fillStyle = `rgba(139, 0, 0, ${b.life/100})`;
        ctx.fillRect(b.x, b.y, 5, 5);
    });
    Game.bloodParticles = Game.bloodParticles.filter(b => b.life > 0);
}

function updateUI() {
    const p = Game.player;
    const s = p.stats;
    if(document.getElementById('hp-val')) {
        document.getElementById('hp-val').innerText = Math.round(s.hp);
        document.getElementById('hp-bar').style.width = s.hp + '%';
        document.getElementById('temp-val').innerText = s.temp.toFixed(1);
        document.getElementById('temp-bar').style.width = ((s.temp-30)/10)*100 + '%';
        document.getElementById('san-val').innerText = Math.round(s.sanity);
        document.getElementById('san-bar').style.width = s.sanity + '%';
        document.getElementById('thirst-val').innerText = Math.round(s.thirst);
        document.getElementById('thirst-bar').style.width = s.thirst + '%';
        document.getElementById('hunger-val').innerText = Math.round(s.hunger ?? 100);
        document.getElementById('hunger-bar').style.width = (s.hunger ?? 100) + '%';
        document.getElementById('stam-val').innerText = Math.round(s.stamina);
        document.getElementById('stam-bar').style.width = s.stamina + '%';
        document.getElementById('waste-val').innerText = Math.round(s.waste ?? 0);
        document.getElementById('waste-bar').style.width = (s.waste ?? 0) + '%';
        document.getElementById('pain-val').innerText = Math.round(s.pain);
        document.getElementById('pain-bar').style.width = s.pain + '%';
        document.getElementById('inf-val').innerText = Math.round(s.infection);
        document.getElementById('inf-bar').style.width = s.infection + '%';
        document.getElementById('equip-mask').innerText = "Mask: " + (p.equipped.mask ? 'ON' : 'OFF');
        document.getElementById('equip-flash').innerText = "Light: " + (p.equipped.flashlight ? Math.round(p.equipped.flashlightBattery)+'%' : 'OFF');
    }
    const dayEl=document.getElementById('day-val'), floorEl=document.getElementById('floor-val'), lockEl=document.getElementById('floor-lock-val'), rescueEl=document.getElementById('rescue-val');
    if(dayEl) dayEl.textContent=Game.expedition.day;
    if(floorEl) floorEl.textContent=Game.expedition.basementActive?String(Game.expedition.floor):'บนดิน';
    if(lockEl) lockEl.textContent=Game.expedition.basementActive?(Game.expedition.floor===0?'ทางออก':(Game.expedition.floorKey||hasItem('floor_key')?'กุญแจพร้อม':'ต้องหาไอเทม')):'-';
    if(rescueEl) rescueEl.textContent=Game.expedition.day>=Game.expedition.rescueDay?'พร้อมรับตัว':'วันที่ 12';
    const ch=document.getElementById('condition-list'); if(ch) ch.innerHTML=getConditionLabels().map(x=>'<div>'+x+'</div>').join('');
    updateInteractionHUD();
    const invSlots = document.getElementById('inv-slots');
    if(invSlots) {
        invSlots.innerHTML = '';
        for(let i=0; i<p.maxSlots; i++) {
            const div = document.createElement('div');
            div.className = 'slot';
            if(p.inventory[i]) {
                div.innerText = ItemDB[p.inventory[i]].name;
                div.onclick = () => useItem(i);
            } else { div.innerText = 'EMPTY'; }
            invSlots.appendChild(div);
        }
    }
}

function gameLoop(now) {
    update(now); render();
    requestAnimationFrame(gameLoop);
}

updateUI();
requestAnimationFrame(gameLoop);
</script>
</body>
</html>
'''



# [6z5c] TACTICAL CHESS-GRID MAP / WORLD-ALIGNED MAP SYSTEM
# Square-cell tactical map: visual style follows the grid example shown to the user.
# Every square is tied directly to the playable world's X/Y coordinates.
TACTICAL_GRID_MAP_ENABLED = True
TACTICAL_GRID_CELL = 50
TACTICAL_GRID_COLS = 16
TACTICAL_GRID_ROWS = 12
TACTICAL_GRID_MAP_JS = r"""<script>
(function(){
if(window.__VMAX_TACTICAL_GRID_MAP__) return;
window.__VMAX_TACTICAL_GRID_MAP__=true;
const CELL=50,COLS=16,ROWS=12,WORLD_W=800,WORLD_H=600;

function worldFeatures(){
  const W=(window.Game&&Game.world)||{};
  const z=(name, fallback, kind, icon)=>({
    name, kind, icon,
    ...(W[name]||fallback)
  });
  return [
    z('cleanWaterZone',{x:100,y:100,w:100,h:100},'water','💧'),
    z('dirtyWaterZone',{x:250,y:100,w:100,h:100},'water','☣'),
    z('iceZone',{x:500,y:100,w:300,h:400},'hazard','❄'),
    z('tentZone',{x:100,y:400,w:150,h:150},'house','⌂'),
    z('bedZone',{x:55,y:360,w:120,h:100},'house','⌂'),
    z('lowerDoorZone',{x:350,y:65,w:110,h:80},'door','▣'),
    z('basementExitZone',{x:680,y:420,w:90,h:100},'exit','⇩')
  ];
}
function ensureMap(){
 let p=document.getElementById('vmax-tactical-map');
 if(p)return p;
 p=document.createElement('div');p.id='vmax-tactical-map';
 p.style.cssText='position:absolute;inset:0;background:rgba(3,7,12,.97);z-index:45;display:none;align-items:center;justify-content:center;';
 p.innerHTML='<div style="position:relative;width:min(94vw,960px);aspect-ratio:4/3;background:#18241e;border:2px solid #7b8d80;box-shadow:0 0 35px #000;overflow:hidden;border-radius:4px"><canvas id="vmax-tactical-canvas" width="800" height="600" style="width:100%;height:100%;image-rendering:auto"></canvas><div style="position:absolute;left:10px;top:8px;color:#eef5ef;font:700 14px monospace;background:#071008dd;padding:6px 9px;border:1px solid #637565;border-radius:4px">TACTICAL MAP · WORLD GRID</div><div style="position:absolute;right:10px;top:8px;color:#d8e1da;font:11px monospace;background:#071008dd;padding:6px 9px;border:1px solid #637565;border-radius:4px">N : ปิดแผนที่</div></div>';
 document.getElementById('game-container').appendChild(p);return p;
}
function drawIcon(c,icon,x,y){
 c.save();c.textAlign='center';c.textBaseline='middle';c.font='22px sans-serif';c.fillStyle='#f4f7ef';c.shadowColor='#000';c.shadowBlur=4;c.fillText(icon,x,y);c.restore();
}
function drawTacticalMap(){
 const p=ensureMap(),c=document.getElementById('vmax-tactical-canvas'),g=c.getContext('2d');
 g.clearRect(0,0,WORLD_W,WORLD_H);
 // Base terrain.
 g.fillStyle='#26362b';g.fillRect(0,0,WORLD_W,WORLD_H);
 // Subtle chessboard-like alternating cells, while preserving the real world scale.
 for(let row=0;row<ROWS;row++)for(let col=0;col<COLS;col++){
   g.fillStyle=((row+col)&1)?'rgba(255,255,255,.025)':'rgba(0,0,0,.035)';
   g.fillRect(col*CELL,row*CELL,CELL,CELL);
 }
 // Real-world features use Game.world when available.
 worldFeatures().forEach(b=>{
   if(!b||typeof b.x!=='number')return;
   const col=b.kind==='house'?'#806a52':b.kind==='door'?'#9d8445':b.kind==='exit'?'#477f58':b.kind==='water'?'#3d7d9e':'#687987';
   g.fillStyle=col;g.globalAlpha=.88;g.fillRect(b.x,b.y,b.w,b.h);g.globalAlpha=1;
   g.strokeStyle='#d6e2d9';g.lineWidth=1.5;g.strokeRect(b.x+.75,b.y+.75,b.w-1.5,b.h-1.5);
   const cx=b.x+b.w/2,cy=b.y+b.h/2;
   drawIcon(g,b.icon,cx,cy);
 });
 // Exact world-position loot.
 if(window.Game&&Array.isArray(Game.itemsOnGround)){
   Game.itemsOnGround.forEach(it=>{
     if(it.floor&&(!Game.expedition.basementActive||it.floor!==Game.expedition.floor))return;
     g.save();g.fillStyle=it.id==='floor_key'?'#ffd166':'#f1f1e8';g.strokeStyle='#111';g.lineWidth=2;
     g.beginPath();g.arc(it.x,it.y,6,0,Math.PI*2);g.fill();g.stroke();g.restore();
   });
 }
 // World grid and cell labels: A1, B1 ... P12.
 g.lineWidth=1;
 for(let row=0;row<ROWS;row++)for(let col=0;col<COLS;col++){
   const x=col*CELL,y=row*CELL,label=String.fromCharCode(65+col)+(row+1);
   g.strokeStyle='rgba(224,238,226,.48)';g.strokeRect(x+.5,y+.5,CELL-1,CELL-1);
   g.fillStyle='rgba(238,246,239,.82)';g.font='bold 10px monospace';g.textAlign='left';g.textBaseline='top';g.fillText(label,x+4,y+4);
 }
 // Player marker is exact playable-world X/Y.
 if(window.Game&&Game.player){
   const q=Game.player;
   g.save();g.translate(q.x,q.y);
   g.fillStyle='#ff4655';g.strokeStyle='#fff';g.lineWidth=2;
   g.beginPath();g.arc(0,0,8,0,Math.PI*2);g.fill();g.stroke();
   g.fillStyle='#fff';g.font='bold 11px monospace';g.textAlign='left';g.textBaseline='bottom';g.fillText('YOU',12,-9);
   g.restore();
 }
 // Legend.
 g.fillStyle='rgba(5,10,7,.82)';g.fillRect(8,548,300,43);
 g.strokeStyle='#607364';g.strokeRect(8.5,548.5,299,42);
 g.fillStyle='#edf5ee';g.font='11px monospace';g.textAlign='left';g.textBaseline='top';
 g.fillText('■ บ้าน/สิ่งปลูกสร้าง   ● Loot   ● YOU',16,556);
 g.fillText('1 ช่อง = 50×50 world units · 16×12',16,573);
}
function toggleTacticalMap(force){const p=ensureMap();const on=force===undefined?p.style.display==='none':!!force;p.style.display=on?'flex':'none';if(on)drawTacticalMap();}
window.VMAXTacticalMap={toggle:toggleTacticalMap,refresh:drawTacticalMap,cellSize:CELL,cols:COLS,rows:ROWS};
document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='n'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();toggleTacticalMap();}});
setInterval(()=>{let p=document.getElementById('vmax-tactical-map');if(p&&p.style.display!=='none')drawTacticalMap();},250);
})();
</script>"""
if 'SURVIVAL_GAME_HTML' in globals() and TACTICAL_GRID_MAP_JS not in SURVIVAL_GAME_HTML:
    SURVIVAL_GAME_HTML=SURVIVAL_GAME_HTML.replace('</body>',TACTICAL_GRID_MAP_JS+'</body>')
