# [6z5] Repair / Craft / Water Filter / Respirator Mask
SURVIVAL_REPAIR_MASK_ENABLED=True
SURVIVAL_REPAIR_MASK_JS=r"""<script>
(function(){if(window.__VMAX_REPAIR_MASK__)return;window.__VMAX_REPAIR_MASK__=true;
const S=window.VMAX_SURVIVAL_EQUIPMENT={workbench:{near:false},waterFilter:{durability:100,filter:100},mask:{equipped:false,durability:100,filter:100,cough:0},inventory:{scrap:3,cloth:2,charcoal:1,filter_cartridge:0,clean_water:0,medicine:1},equipment:{purifier:{durability:55,max:100}}};
function msg(t){if(typeof window.showNotif==='function')window.showNotif(t);else console.log('[SURVIVAL]',t)}
function pay(c){for(const k in c)S.inventory[k]=(S.inventory[k]||0)-c[k]}function can(c){return Object.keys(c).every(k=>(S.inventory[k]||0)>=c[k])}
window.VMAXRepairSystem={setWorkbench(n){S.workbench.near=!!n;render()},repairPurifier(){if(!S.workbench.near)return msg('🔧 ต้องอยู่ที่โต๊ะซ่อมก่อน');if(S.equipment.purifier.durability>=100)return msg('เครื่องกรองน้ำยังสมบูรณ์');if((S.inventory.scrap||0)<1)return msg('❌ เศษอะไหล่ไม่พอ');S.inventory.scrap--;S.equipment.purifier.durability=Math.min(100,S.equipment.purifier.durability+25);msg('🔧 ซ่อมเครื่องกรองน้ำแล้ว');render()},replaceFilter(){if(!S.workbench.near)return msg('🔧 ต้องอยู่ที่โต๊ะซ่อมก่อน');if((S.inventory.filter_cartridge||0)<1)return msg('❌ ไม่มีไส้กรองสำรอง');S.inventory.filter_cartridge--;S.waterFilter.filter=100;msg('💧 เปลี่ยนไส้กรองน้ำแล้ว');render()},repairMask(){if(!S.workbench.near)return msg('🔧 ต้องอยู่ที่โต๊ะซ่อมก่อน');if(S.mask.durability>=100)return msg('หน้ากากยังสมบูรณ์');if((S.inventory.scrap||0)<1||(S.inventory.cloth||0)<1)return msg('❌ ต้องใช้เศษอะไหล่ + ผ้า');S.inventory.scrap--;S.inventory.cloth--;S.mask.durability=Math.min(100,S.mask.durability+35);msg('😷 ซ่อมหน้ากากแล้ว');render()},craftFilter(){const c={scrap:2,charcoal:1,cloth:1};if(!can(c))return msg('❌ วัสดุทำไส้กรองไม่พอ');pay(c);S.inventory.filter_cartridge++;msg('🧰 ทำไส้กรองสำรองสำเร็จ');render()},purifyWater(){if(!S.workbench.near)return msg('💧 ต้องอยู่ใกล้เครื่องกรองน้ำก่อน');if(S.equipment.purifier.durability<=0)return msg('🔧 เครื่องกรองน้ำเสีย ต้องซ่อมก่อน');if(S.waterFilter.filter<=0)return msg('🧪 ไส้กรองหมด ต้องเปลี่ยนก่อน');S.waterFilter.filter=Math.max(0,S.waterFilter.filter-10);S.equipment.purifier.durability=Math.max(0,S.equipment.purifier.durability-2);S.inventory.clean_water++;msg('💧 กรองน้ำสะอาด +1');render()},equipMask(){S.mask.equipped=true;msg('😷 สวมหน้ากากแล้ว');render()},removeMask(){S.mask.equipped=false;msg('😮‍💨 ถอดหน้ากากแล้ว');render()}};
function hazard(){const p=window.Game&&Game.player,f=window.Game&&Game.expedition&&Number(Game.expedition.floor||0);if(f>0&&!S.mask.equipped){if(p&&p.stats){p.stats.stamina=Math.max(0,(p.stats.stamina||100)-.12);p.stats.hp=Math.max(0,(p.stats.hp||100)-.03);p.conditions=p.conditions||{};p.conditions.coughing=true}if(Math.random()<.04)msg('😷 แอ๊ะ ๆ! อากาศข้างล่างทำให้หายใจลำบาก — ใส่หน้ากาก!')}if(f>0&&S.mask.equipped){S.mask.filter=Math.max(0,S.mask.filter-.02);S.mask.durability=Math.max(0,S.mask.durability-.005);if(S.mask.filter<=0&&Math.random()<.08)msg('😷 แอ๊ะ ๆ! ไส้กรองหน้ากากหมดแล้ว')}}
function render(){let h=document.getElementById('vmax-equip-hud');if(!h){h=document.createElement('div');h.id='vmax-equip-hud';h.style.cssText='position:absolute;right:10px;bottom:10px;z-index:20;background:rgba(4,8,12,.94);color:#eee;border:1px solid #56677d;border-radius:10px;padding:10px;font:12px Arial;min-width:240px';document.body.appendChild(h)}const w=S.workbench.near;h.innerHTML='<b>🔧 อุปกรณ์เอาตัวรอด</b><br>😷 หน้ากาก '+Math.round(S.mask.durability)+'% | ไส้กรอง '+Math.round(S.mask.filter)+'% '+(S.mask.equipped?'[สวม]':'[ถอด]')+'<br>💧 เครื่องกรอง '+Math.round(S.equipment.purifier.durability)+'% | ไส้กรอง '+Math.round(S.waterFilter.filter)+'%<br>🔩 Scrap '+S.inventory.scrap+' | 🧵 Cloth '+S.inventory.cloth+' | 🧪 Cartridge '+S.inventory.filter_cartridge+(w?'<hr><button onclick="VMAXRepairSystem.repairMask()">ซ่อมหน้ากาก</button> <button onclick="VMAXRepairSystem.replaceFilter()">เปลี่ยนไส้กรอง</button><br><button onclick="VMAXRepairSystem.repairPurifier()">ซ่อมเครื่องกรอง</button> <button onclick="VMAXRepairSystem.craftFilter()">ทำไส้กรอง</button><br><button onclick="VMAXRepairSystem.purifyWater()">กรองน้ำ</button>':'')} }
window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='m')S.mask.equipped=!S.mask.equipped,msg(S.mask.equipped?'😷 สวมหน้ากาก':'😮‍💨 ถอดหน้ากาก'),render();if(e.key.toLowerCase()==='c'&&S.workbench.near)VMAXRepairSystem.craftFilter()});setInterval(hazard,1000);setInterval(render,1500);render();})();
</script>"""
SURVIVAL_EQUIPMENT_STATE={"mask":{"equipped":False,"durability":100,"filter":100},"water_filter":{"durability":55,"filter":100},"inventory":{"scrap":3,"cloth":2,"charcoal":1,"filter_cartridge":0,"clean_water":0}}
@app.route('/api/survival/equipment',methods=['GET'])
def survival_equipment_state(): return jsonify(SURVIVAL_EQUIPMENT_STATE)
