# [6z5b] Bamboo Chop + Double-Jump Climb System
BAMBOO_CHOP_CLIMB_ENABLED = True
BAMBOO_CHOP_CLIMB_JS = r"""<script>
(function(){
if(window.__VMAX_BAMBOO_CHOP_CLIMB__) return; window.__VMAX_BAMBOO_CHOP_CLIMB__=true;
if(typeof Game==='undefined' || typeof update!=='function' || typeof render!=='function'){ return; }

const BAMBOO_TREES=[
  {id:'bm1', x:430, y:430, hp:100, maxHp:100, cut:false, cutAt:0},
  {id:'bm2', x:468, y:472, hp:100, maxHp:100, cut:false, cutAt:0},
  {id:'bm3', x:402, y:500, hp:100, maxHp:100, cut:false, cutAt:0},
  {id:'bm4', x:445, y:545, hp:100, maxHp:100, cut:false, cutAt:0}
];
const BAMBOO_CHOP_DAMAGE=25, BAMBOO_CHOP_RANGE=42, BAMBOO_GRAB_RANGE=50;
const BAMBOO_RESPAWN_MS=40000, BAMBOO_CLIMB_MAX_Z=150, BAMBOO_CLIMB_SPEED=70;
const DOUBLE_JUMP_WINDOW_MS=420;

let lastJumpTapAt=-9999, chopCooldownAt=0, facing={x:0,y:1}, prevPos=null;
let particles=[], lastTickAt=performance.now();

function updateFacing(){
  const p=Game.player;
  if(!prevPos){ prevPos={x:p.x,y:p.y}; return; }
  const dx=p.x-prevPos.x, dy=p.y-prevPos.y, mag=Math.hypot(dx,dy);
  if(mag>0.4){ facing.x=dx/mag; facing.y=dy/mag; }
  prevPos.x=p.x; prevPos.y=p.y;
}

function findNearestBamboo(maxDist, requireFacing){
  const p=Game.player; let best=null, bestD=Infinity;
  BAMBOO_TREES.forEach(t=>{
    if(t.cut) return;
    const dx=t.x-p.x, dy=t.y-p.y, d=Math.hypot(dx,dy);
    if(d>maxDist) return;
    if(requireFacing){
      const mag=d||1, dot=(dx/mag)*facing.x+(dy/mag)*facing.y;
      if(dot<0.35) return;
    }
    if(d<bestD){ bestD=d; best=t; }
  });
  return best;
}

function spawnChips(t){
  for(let i=0;i<10;i++) particles.push({x:t.x,y:t.y-20,vx:(Math.random()-0.5)*6,vy:-Math.random()*4-1,life:28});
}

function bambooChop(){
  const p=Game.player;
  if(p.isClimbingBamboo) return;
  const now=performance.now();
  if(now-chopCooldownAt<300) return;
  const target=findNearestBamboo(BAMBOO_CHOP_RANGE,true);
  if(!target){ if(typeof showNotif==='function') showNotif('ไม่มีต้นไผ่ให้ฟันตรงนี้'); return; }
  chopCooldownAt=now;
  target.hp-=BAMBOO_CHOP_DAMAGE;
  spawnChips(target);
  if(target.hp<=0){
    target.hp=0; target.cut=true; target.cutAt=now;
    if(Game.itemsOnGround) Game.itemsOnGround.push({id:'bamboo_pole', x:target.x, y:target.y});
    if(typeof ItemDB!=='undefined' && !ItemDB.bamboo_pole) ItemDB.bamboo_pole={name:'ไม้ไผ่', type:'tool'};
    if(typeof showNotif==='function') showNotif('🎍 ตัดต้นไผ่สำเร็จ! ได้ไม้ไผ่');
  } else {
    if(typeof showNotif==='function') showNotif('🪓 ฟันต้นไผ่! ('+target.hp+'/'+target.maxHp+')');
  }
}

function tryClimb(){
  const p=Game.player;
  if(p.isClimbingBamboo) return false;
  const target=findNearestBamboo(BAMBOO_GRAB_RANGE,true);
  if(!target) return false;
  p.isClimbingBamboo=true; p.climbTreeId=target.id;
  p.isJumping=false; p.vz=0; p.isSlipping=false;
  p.climbAnchorX=p.x; p.climbAnchorY=p.y;
  p.x=target.x; p.y=target.y+6;
  p._bambooToppedNotified=false;
  if(typeof showNotif==='function') showNotif('🎍 กระโดด 2 จังหวะ เกาะไม้ไผ่แล้ว! กด W/S ปีนขึ้น-ลง กดกระโดดอีกครั้งเพื่อกระโดดออก');
  return true;
}

function releaseClimb(hop){
  const p=Game.player;
  p.isClimbingBamboo=false;
  if(hop){
    p.isJumping=true; p.vz=9;
    p.x=(p.climbAnchorX!==undefined?p.climbAnchorX:p.x)-facing.x*10;
    p.y=(p.climbAnchorY!==undefined?p.climbAnchorY:p.y)-facing.y*10;
  } else { p.z=0; }
}

function handleJumpPress(){
  const p=Game.player;
  const now=performance.now();
  const isDouble=(now-lastJumpTapAt)<DOUBLE_JUMP_WINDOW_MS;
  lastJumpTapAt=now;
  if(p.isClimbingBamboo){ releaseClimb(true); return; }
  if(isDouble){ tryClimb(); }
}

document.addEventListener('keydown', e=>{
  if(e.key===' ') handleJumpPress();
  if(e.key.toLowerCase()==='j') bambooChop();
});

function bindButtons(){
  const jumpBtn=document.getElementById('btn-jump');
  if(jumpBtn) jumpBtn.addEventListener('touchstart', e=>{ e.preventDefault(); handleJumpPress(); });
  const atkBtn=document.getElementById('btn-attack');
  if(atkBtn) atkBtn.addEventListener('touchstart', e=>{ e.preventDefault(); bambooChop(); });
}
bindButtons();

function bambooTick(now){
  updateFacing();
  BAMBOO_TREES.forEach(t=>{
    if(t.cut && now-t.cutAt>BAMBOO_RESPAWN_MS){ t.cut=false; t.hp=t.maxHp; }
  });
  const p=Game.player;
  if(p.isClimbingBamboo){
    const dt=Math.min(0.05,(now-lastTickAt)/1000);
    let up=0;
    if(typeof keys!=='undefined'){ if(keys['w']) up=1; if(keys['s']) up=-1; }
    if(typeof joy!=='undefined' && joy.active){ if(joy.dy<-20) up=1; if(joy.dy>20) up=-1; }
    p.z=(p.z||0)+up*BAMBOO_CLIMB_SPEED*dt;
    if(p.z>=BAMBOO_CLIMB_MAX_Z){
      p.z=BAMBOO_CLIMB_MAX_Z;
      if(!p._bambooToppedNotified){ p._bambooToppedNotified=true; if(typeof showNotif==='function') showNotif('🎍 ถึงยอดไม้ไผ่แล้ว! กดกระโดดเพื่อกระโดดลง'); }
    } else p._bambooToppedNotified=false;
    if(p.z<=0){ p.z=0; releaseClimb(false); }
  }
  particles.forEach(b=>{ b.x+=b.vx; b.y+=b.vy; b.vy+=0.35; b.life--; });
  particles=particles.filter(b=>b.life>0);
  lastTickAt=now;
}

function hintEl(){
  let h=document.getElementById('bamboo-hint');
  if(!h){
    h=document.createElement('div'); h.id='bamboo-hint';
    h.style.cssText='position:absolute;bottom:170px;left:50%;transform:translateX(-50%);background:rgba(10,20,10,.85);color:#eaffdf;padding:6px 12px;border-radius:8px;font:12px monospace;z-index:25;pointer-events:none;text-align:center;max-width:80vw';
    (document.getElementById('game-container')||document.body).appendChild(h);
  }
  return h;
}

function bambooDraw(){
  BAMBOO_TREES.forEach(t=>{
    if(t.cut){ ctx.fillStyle='#7a5c3a'; ctx.fillRect(t.x-6,t.y-6,12,10); return; }
    const segH=14, segs=5;
    for(let i=0;i<segs;i++){
      ctx.fillStyle= i%2===0 ? '#6fae3e':'#8fce53';
      ctx.fillRect(t.x-6, t.y-14-i*segH, 12, segH-2);
    }
    ctx.fillStyle='#bfe98a';
    ctx.beginPath(); ctx.moveTo(t.x, t.y-14-segs*segH);
    ctx.lineTo(t.x-16, t.y-14-segs*segH-14);
    ctx.lineTo(t.x+2, t.y-14-segs*segH-4);
    ctx.fill();
    if(t.hp<t.maxHp){
      ctx.fillStyle='#222'; ctx.fillRect(t.x-16,t.y-14-segs*segH-22,32,5);
      ctx.fillStyle='#4caf50'; ctx.fillRect(t.x-16,t.y-14-segs*segH-22,32*(t.hp/t.maxHp),5);
    }
  });
  particles.forEach(b=>{ ctx.fillStyle='rgba(143,206,106,'+Math.max(0,b.life/28)+')'; ctx.fillRect(b.x,b.y,4,4); });
  const p=Game.player;
  const near=findNearestBamboo(BAMBOO_GRAB_RANGE,false);
  let hint='';
  if(p.isClimbingBamboo) hint='🎍 กำลังปีนไม้ไผ่ — กด W/S ปีนขึ้น-ลง, กดกระโดดเพื่อกระโดดออก';
  else if(near) hint='🪓 กด J หรือปุ่ม "ฟัน" เพื่อฟันไผ่ | หันหน้าเข้าไม้ไผ่แล้วกระโดด 2 จังหวะเพื่อปีน';
  const el=hintEl(); el.textContent=hint; el.style.display=hint?'block':'none';
}

const _origBambooUpdate=update, _origBambooRender=render;
update=function(now){ _origBambooUpdate(now); try{ bambooTick(now); }catch(e){ console.error(e); } };
render=function(){ _origBambooRender(); try{ bambooDraw(); }catch(e){ console.error(e); } };
})();
</script>"""
if "SURVIVAL_GAME_HTML" in globals() and BAMBOO_CHOP_CLIMB_JS not in SURVIVAL_GAME_HTML:
    SURVIVAL_GAME_HTML=SURVIVAL_GAME_HTML.replace("</body>",BAMBOO_CHOP_CLIMB_JS+"</body>")
VMAX_MODULES['bamboo_chop_climb']={'name':'ระบบฟันต้นไผ่ + ปีนไม้ไผ่ (double-jump)','level':'intermediate','category':'core','desc':'ฟันต้นไผ่ในโลกเปิดให้ถูกตัด (มี HP/ล้มแล้วงอกใหม่) และกระโดดซ้ำ 2 จังหวะขณะหันหน้าเข้าไม้ไผ่เพื่อเกาะปีนขึ้น-ลง','routes':[]}


