# ==========================================
# [ 6zz7b. SLAP CLASH ARENA — ORIGINAL ARCADE MINI-GAME ]
# Inspired by the broad idea of a colorful timing/versus arcade event shown in the
# reference image, but uses original names, characters, UI, rules and assets.
# Reuses VMAX's existing UID, launcher catalog, currency and character progression.
# No real-money mechanic is used by this mini-game.
# ==========================================
SLAP_ARENA_EVENT = {
    "id": "slap_clash_arena_2026",
    "name": "SLAP CLASH ARENA",
    "subtitle": "จังหวะปะทะ — กดให้ตรงเวลา แล้วทำคอมโบ",
    "season": "01 SEP - 05 OCT 2026",
    "rounds": 7,
    "reward_per_win": 120,
}
SLAP_ARENA_MATCHES = {}
SLAP_ARENA_LEADERBOARD = {}
SLAP_ARENA_LOCK = threading.RLock()

def _slap_new_round(match):
    # Create a server-side timing target for the next round.
    match["round"] += 1
    match["target_ms"] = random.randint(520, 1180)
    match["window_ms"] = 115
    match["round_started_at"] = time.time()
    match["status"] = "active"
    return match

def slap_arena_start(uid):
    uid = str(uid or "guest")[:128]
    with SLAP_ARENA_LOCK:
        match = {
            "uid": uid, "match_id": uuid.uuid4().hex[:10], "round": 0,
            "max_rounds": SLAP_ARENA_EVENT["rounds"], "player_hp": 100,
            "opponent_hp": 100, "score": 0, "combo": 0, "best_combo": 0,
            "perfects": 0, "misses": 0, "wins": 0, "status": "active",
            "last_action_at": 0.0, "reward": 0,
        }
        _slap_new_round(match)
        SLAP_ARENA_MATCHES[uid] = match
        return dict(match)

def slap_arena_state(uid):
    uid = str(uid or "guest")[:128]
    with SLAP_ARENA_LOCK:
        match = SLAP_ARENA_MATCHES.get(uid)
        if not match:
            return {"status": "idle", "event": SLAP_ARENA_EVENT,
                    "best_score": SLAP_ARENA_LEADERBOARD.get(uid, 0)}
        out = dict(match)
        out["event"] = SLAP_ARENA_EVENT
        out["best_score"] = SLAP_ARENA_LEADERBOARD.get(uid, 0)
        out.pop("uid", None)
        return out

def slap_arena_action(uid, reaction_ms):
    uid = str(uid or "guest")[:128]
    try:
        reaction_ms = float(reaction_ms)
    except (TypeError, ValueError):
        return False, "ค่า reaction ไม่ถูกต้อง", slap_arena_state(uid)
    if not math.isfinite(reaction_ms):
        return False, "ค่า reaction ไม่ถูกต้อง", slap_arena_state(uid)
    reaction_ms = max(0.0, min(2500.0, reaction_ms))
    with SLAP_ARENA_LOCK:
        m = SLAP_ARENA_MATCHES.get(uid)
        if not m or m.get("status") != "active":
            return False, "ยังไม่มีแมตช์ที่กำลังเล่น", slap_arena_state(uid)
        if time.time() - float(m.get("last_action_at", 0.0)) < 0.08:
            return False, "กดเร็วเกินไป", slap_arena_state(uid)
        m["last_action_at"] = time.time()
        target = float(m["target_ms"])
        delta = abs(reaction_ms - target)
        window = float(m["window_ms"])
        if delta <= 35:
            grade, points, damage = "PERFECT", 300, 20
            m["perfects"] += 1; m["combo"] += 1
        elif delta <= window:
            grade, points, damage = "GREAT", 180, 13; m["combo"] += 1
        elif delta <= window * 2.0:
            grade, points, damage = "GOOD", 90, 7; m["combo"] = max(0, m["combo"] - 1)
        else:
            grade, points, damage = "MISS", 0, 0; m["misses"] += 1; m["combo"] = 0
        combo_bonus = min(500, max(0, m["combo"] - 1) * 25)
        m["best_combo"] = max(m["best_combo"], m["combo"])
        m["score"] += points + combo_bonus
        m["opponent_hp"] = max(0, m["opponent_hp"] - damage)
        counter = {"PERFECT": 3, "GREAT": 6, "GOOD": 9}.get(grade, random.randint(10, 16))
        m["player_hp"] = max(0, m["player_hp"] - counter)
        finished = m["opponent_hp"] <= 0 or m["player_hp"] <= 0 or m["round"] >= m["max_rounds"]
        if finished:
            m["wins"] = 1 if (m["opponent_hp"] <= 0 or (m["player_hp"] > 0 and m["score"] >= 900)) else 0
            m["reward"] = SLAP_ARENA_EVENT["reward_per_win"] if m["wins"] else 20
            m["status"] = "finished"
            SLAP_ARENA_LEADERBOARD[uid] = max(SLAP_ARENA_LEADERBOARD.get(uid, 0), int(m["score"]))
            try:
                cur = _currency_get(uid)
                cur["gold"] = int(cur.get("gold", 0)) + int(m["reward"])
            except Exception:
                pass
            msg = f"{grade} — จบแมตช์! ได้ Gold +{m['reward']}"
        else:
            _slap_new_round(m)
            msg = f"{grade} +{points} | คอมโบ x{m['combo']}"
        out = slap_arena_state(uid)
        out.update({"grade": grade, "delta_ms": round(delta, 1), "message": msg})
        return True, msg, out

@app.route('/api/slap-arena/start', methods=['POST'])
def api_slap_arena_start():
    data = request.get_json(silent=True) or {}
    uid = str(data.get("uid") or getattr(request, "vmax_uid", None) or P.get("uid") or "guest")
    return jsonify({"st": "ok", "state": slap_arena_start(uid)})

@app.route('/api/slap-arena/state', methods=['GET', 'POST'])
def api_slap_arena_state():
    data = request.get_json(silent=True) or {}
    uid = str(data.get("uid") or request.args.get("uid") or getattr(request, "vmax_uid", None) or P.get("uid") or "guest")
    return jsonify({"st": "ok", "state": slap_arena_state(uid)})

@app.route('/api/slap-arena/action', methods=['POST'])
def api_slap_arena_action():
    data = request.get_json(silent=True) or {}
    uid = str(data.get("uid") or getattr(request, "vmax_uid", None) or P.get("uid") or "guest")
    ok, msg, state = slap_arena_action(uid, data.get("reaction_ms"))
    return jsonify({"st": "ok" if ok else "error", "msg": msg, "state": state}), (200 if ok else 400)

@app.route('/api/slap-arena/leaderboard', methods=['GET'])
def api_slap_arena_leaderboard():
    rows = sorted(({"uid": uid, "score": int(score)} for uid, score in SLAP_ARENA_LEADERBOARD.items()), key=lambda x: x["score"], reverse=True)[:20]
    return jsonify({"st": "ok", "event": SLAP_ARENA_EVENT, "leaderboard": rows})

