def _fort_next_monday_ts(now=None):
    """คืน unix timestamp ของวันจันทร์ถัดไป 00:00 (local server time)."""
    import datetime as _dt
    now = _dt.datetime.fromtimestamp(now or time.time())
    days_ahead = (7 - now.weekday()) % 7
    if days_ahead == 0:
        days_ahead = 7
    nxt = (now + _dt.timedelta(days=days_ahead)).replace(hour=0, minute=0, second=0, microsecond=0)
    return nxt.timestamp()


def _fort_today_key(now=None):
    import datetime as _dt
    return _dt.datetime.fromtimestamp(now or time.time()).strftime("%Y-%m-%d")


def _fort_week_key(now=None):
    """ISO year-week key e.g. 2026-W40 — ใช้เทียบ weekly quota."""
    import datetime as _dt
    d = _dt.datetime.fromtimestamp(now or time.time())
    iso = d.isocalendar()
    return f"{iso[0]}-W{iso[1]:02d}"


def _fort_uid_path(uid):
    safe = "".join(c if c.isalnum() or c in "-_" else "_" for c in str(uid))[:96]
    return os.path.join(FORTRESS_DATA_DIR, f"cards_{safe}.json")


def _fort_default_state():
    return {
        "coins": 0,
        "owned": {},          # card_id -> qty (ปกติ 1)
        "equipped": None,
        "daily_exchanges": {},  # date_str -> count
        "weekly_grants": {},    # week_key -> count
        "ledger": [],           # recent events (cap 200)
        "updated_at": time.time(),
    }


def _fort_load_state(uid):
    """โหลดสถานะบัตรจากไฟล์ (หรือ cache) — thread-safe ด้วย _FORT_LOCK."""
    with _FORT_LOCK:
        if uid in _FORT_CARD_CACHE:
            return _FORT_CARD_CACHE[uid]
        path = _fort_uid_path(uid)
        st = _fort_default_state()
        if os.path.isfile(path):
            try:
                with open(path, "r", encoding="utf-8") as f:
                    raw = json.load(f)
                if isinstance(raw, dict):
                    st["coins"] = int(raw.get("coins", 0) or 0)
                    st["owned"] = dict(raw.get("owned") or {})
                    st["equipped"] = raw.get("equipped")
                    st["daily_exchanges"] = dict(raw.get("daily_exchanges") or {})
                    st["weekly_grants"] = dict(raw.get("weekly_grants") or {})
                    st["ledger"] = list(raw.get("ledger") or [])[-200:]
                    st["updated_at"] = float(raw.get("updated_at") or time.time())
            except Exception:
                pass
        _FORT_CARD_CACHE[uid] = st
        return st


def _fort_save_state(uid, st=None):
    with _FORT_LOCK:
        st = st or _FORT_CARD_CACHE.get(uid) or _fort_default_state()
        st["updated_at"] = time.time()
        st["ledger"] = list(st.get("ledger") or [])[-200:]
        _FORT_CARD_CACHE[uid] = st
        path = _fort_uid_path(uid)
        tmp = path + ".tmp"
        try:
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(st, f, ensure_ascii=False, indent=0)
            os.replace(tmp, path)
        except Exception as exc:
            try:
                if os.path.isfile(tmp):
                    os.remove(tmp)
            except Exception:
                pass
            print(f"[FORTRESS] save state failed uid={uid}: {exc}")


def _fort_wallet(uid):
    """เข้ากันได้กับโค้ดเดิม — คืน dict ที่มี key 'coins' (อ้างอิง state จริง)."""
    st = _fort_load_state(uid)
    return st  # มี .coins อยู่แล้ว


def _fort_cards(uid):
    """เข้ากันได้กับโค้ดเดิม — คืน dict ที่มี owned / equipped."""
    return _fort_load_state(uid)


def _fort_limits_status(uid, now=None):
    st = _fort_load_state(uid)
    today = _fort_today_key(now)
    week = _fort_week_key(now)
    daily_used = int(st["daily_exchanges"].get(today, 0))
    weekly_used = int(st["weekly_grants"].get(week, 0))
    return {
        "daily_limit": FORTRESS_CARD_DAILY_EXCHANGE_LIMIT,
        "daily_used": daily_used,
        "daily_remaining": max(0, FORTRESS_CARD_DAILY_EXCHANGE_LIMIT - daily_used),
        "weekly_quota": FORTRESS_CARD_WEEKLY_QUOTA,
        "weekly_used": weekly_used,
        "weekly_remaining": max(0, FORTRESS_CARD_WEEKLY_QUOTA - weekly_used),
        "next_monday_ts": _fort_next_monday_ts(now),
        "today": today,
        "week": week,
    }


def _fort_ledger_append(st, event_type, **extra):
    entry = {"ts": time.time(), "type": event_type}
    entry.update(extra)
    st.setdefault("ledger", []).append(entry)
    if len(st["ledger"]) > 200:
        st["ledger"] = st["ledger"][-200:]


def _fort_new_session(uid, role):
    now = time.time()
    turrets = []
    for lane in range(FORTRESS_LANES):
        for row in range(FORTRESS_ROWS):
            ttype = FORTRESS_ROW_TYPES[row % len(FORTRESS_ROW_TYPES)]
            hp = FORTRESS_TURRET_TYPES[ttype]["hp"]
            turrets.append({"lane": lane, "row": row, "type": ttype, "hp": hp, "max_hp": hp, "shield": 0, "broken": False})
    return {"uid": uid, "role": role, "status": "active", "started": now, "ends": now + FORTRESS_DURATION_SEC,
            "last_tick": now, "turrets": turrets, "breaches": 0, "log": [], "cd": {}, "gust_until": 0.0,
            "rewarded": False, "reward": None, "score": 0}


def _fort_turret(sess, lane, row):
    for t in sess["turrets"]:
        if t["lane"] == lane and t["row"] == row:
            return t
    return None


def _fort_targetable(sess, t):
    """ป้อมแถวหลังยิงได้ก็ต่อเมื่อแถวหน้าในเลนเดียวกันแตกแล้ว (กติกาแบบ MOBA)"""
    if t["broken"]:
        return False
    for r in range(t["row"]):
        front = _fort_turret(sess, t["lane"], r)
        if front and not front["broken"]:
            return False
    return True


def _fort_log(sess, msg):
    sess["log"].append({"t": round(time.time() - sess["started"], 1), "msg": msg})
    del sess["log"][:-12]


def _fort_damage(sess, t, dmg, source_type):
    if t["broken"] or dmg <= 0:
        return 0
    if FORTRESS_TURRET_TYPES[t["type"]]["weak_to"] == source_type:
        dmg = int(dmg * 1.25)
    if t["shield"] > 0:
        absorbed = min(t["shield"], dmg)
        t["shield"] -= absorbed
        dmg -= absorbed
    t["hp"] = max(0, t["hp"] - dmg)
    if t["hp"] <= 0 and not t["broken"]:
        t["broken"] = True
        sess["breaches"] += 1
        _fort_log(sess, "💥 %s เลน %d แถว %d แตก!" % (FORTRESS_TURRET_TYPES[t["type"]]["name_th"], t["lane"] + 1, t["row"] + 1))
    return dmg


def _fort_finish(sess):
    if sess["status"] != "active":
        return
    if sess["breaches"] >= FORTRESS_MAX_BREACH:
        sess["status"] = "attackers_win"
    elif time.time() >= sess["ends"]:
        sess["status"] = "defenders_win"
    else:
        return
    won = (sess["status"] == "defenders_win") == (sess["role"] == "defender")
    intact = sum(1 for t in sess["turrets"] if not t["broken"])
    gold = 60
    if won and sess["role"] == "defender":
        gold += 300 + 40 * intact
    elif won and sess["role"] == "attacker":
        gold += 200
    if sess["role"] == "attacker":
        gold += 40 * sess["breaches"]
    if not sess["rewarded"]:
        sess["rewarded"] = True
        _currency_get(sess["uid"])["gold"] += int(gold)
        sess["reward"] = {"gold": int(gold), "won": bool(won)}


def _fort_tick(sess):
    """จำลองฝ่ายที่ผู้เล่นไม่ได้คุม (AI) แบบ lazy ตามเวลาที่ผ่านไป — เรียกทุกครั้งที่ดึง state/สั่งการ"""
    now = time.time()
    if sess["status"] != "active":
        return
    steps = int(min(now - sess["last_tick"], 30))
    for i in range(steps):
        t_now = sess["last_tick"] + i + 1
        elapsed = t_now - sess["started"]
        if sess["role"] == "defender":
            if t_now < sess["gust_until"]:
                continue                                   # ลมกระโชกชะลอ AI ฝ่ายบุก
            pressure = 1.0 + elapsed / 60.0               # ยิ่งนานยิ่งโหมหนัก
            live = [t for t in sess["turrets"] if _fort_targetable(sess, t)]
            for t in random.sample(live, k=min(len(live), 2)):
                _fort_damage(sess, t, int(random.randint(45, 75) * pressure), random.choice(list(FORTRESS_ATTACK_ELEMENTS)))
        else:
            if int(elapsed) % 2 == 0:                     # AI ฝ่ายป้องกันซ่อม/ตั้งโล่เป็นระยะ
                hurt = [t for t in sess["turrets"] if not t["broken"] and t["hp"] < t["max_hp"]]
                if hurt:
                    t = min(hurt, key=lambda x: x["hp"] / x["max_hp"])
                    t["hp"] = min(t["max_hp"], t["hp"] + 90)
        _fort_finish(sess)
        if sess["status"] != "active":
            break
    sess["last_tick"] = now
    _fort_finish(sess)


def _fort_cd_ok(sess, action):
    now = time.time()
    if now < sess["cd"].get(action, 0):
        return False
    sess["cd"][action] = now + FORTRESS_COOLDOWNS[action]
    return True


def _fort_public(sess):
    now = time.time()
    return {"role": sess["role"], "status": sess["status"], "time_left": max(0, round(sess["ends"] - now, 1)),
            "breaches": sess["breaches"], "max_breach": FORTRESS_MAX_BREACH, "log": sess["log"], "reward": sess["reward"],
            "turrets": [{**t, "targetable": _fort_targetable(sess, t), "icon": FORTRESS_TURRET_TYPES[t["type"]]["icon"],
                         "name_th": FORTRESS_TURRET_TYPES[t["type"]]["name_th"]} for t in sess["turrets"]],
            "cooldowns": {k: max(0, round(v - now, 1)) for k, v in sess["cd"].items()}}


def _fort_uid():
    return str(getattr(request, "vmax_uid", "") or request.args.get("uid") or "guest")


@app.route('/api/fortress/state')
def api_fortress_state():
    uid = str(request.args.get("uid") or "guest")
    cur = _currency_get(uid)
    out = {"st": "ok", "gold": cur["gold"], "coins": _fort_wallet(uid)["coins"], "session": None,
           "turret_types": FORTRESS_TURRET_TYPES, "duration": FORTRESS_DURATION_SEC}
    with _FORT_LOCK:
        sess = FORTRESS_SESSIONS.get(uid)
        if sess:
            _fort_tick(sess)
            out["session"] = _fort_public(sess)
            out["gold"] = _currency_get(uid)["gold"]
    return jsonify(out)


@app.route('/api/fortress/start', methods=['POST'])
@require_auth
def api_fortress_start():
    uid = _fort_uid()
    role = str((request.get_json(silent=True) or {}).get("role", "defender"))
    if role not in ("attacker", "defender"):
        return jsonify({"st": "error", "msg": "role ต้องเป็น attacker หรือ defender"}), 400
    with _FORT_LOCK:
        old = FORTRESS_SESSIONS.get(uid)
        if old and old["status"] == "active":
            return jsonify({"st": "error", "msg": "มีรอบที่กำลังเล่นอยู่แล้ว"}), 400
        FORTRESS_SESSIONS[uid] = _fort_new_session(uid, role)
        return jsonify({"st": "ok", "session": _fort_public(FORTRESS_SESSIONS[uid])})


@app.route('/api/fortress/attack', methods=['POST'])
@require_auth
def api_fortress_attack():
    uid, body = _fort_uid(), request.get_json(silent=True) or {}
    with _FORT_LOCK:
        sess = FORTRESS_SESSIONS.get(uid)
        if not sess or sess["role"] != "attacker":
            return jsonify({"st": "error", "msg": "ต้องเริ่มรอบในฐานะฝ่ายบุกก่อน"}), 400
        _fort_tick(sess)
        if sess["status"] != "active":
            return jsonify({"st": "error", "msg": "รอบนี้จบแล้ว", "session": _fort_public(sess)}), 400
        t = _fort_turret(sess, int(body.get("lane", -1)), int(body.get("row", -1)))
        element = str(body.get("element", "stone"))
        if not t or element not in FORTRESS_ATTACK_ELEMENTS:
            return jsonify({"st": "error", "msg": "เป้าหมาย/ธาตุไม่ถูกต้อง"}), 400
        if not _fort_targetable(sess, t):
            return jsonify({"st": "error", "msg": "ยิงไม่ได้ — ต้องทำลายป้อมแถวหน้าในเลนนี้ก่อน"}), 400
        if not _fort_cd_ok(sess, "attack"):
            return jsonify({"st": "error", "msg": "คูลดาวน์"}), 429
        dealt = _fort_damage(sess, t, FORTRESS_ATTACK_ELEMENTS[element], element)   # ดาเมจคิดฝั่งเซิร์ฟเวอร์เท่านั้น
        sess["score"] += dealt
        _fort_finish(sess)
        return jsonify({"st": "ok", "dealt": dealt, "session": _fort_public(sess)})


@app.route('/api/fortress/defend', methods=['POST'])
@require_auth
def api_fortress_defend():
    uid, body = _fort_uid(), request.get_json(silent=True) or {}
    action = str(body.get("action", "repair"))
    with _FORT_LOCK:
        sess = FORTRESS_SESSIONS.get(uid)
        if not sess or sess["role"] != "defender":
            return jsonify({"st": "error", "msg": "ต้องเริ่มรอบในฐานะฝ่ายป้องกันก่อน"}), 400
        _fort_tick(sess)
        if sess["status"] != "active":
            return jsonify({"st": "error", "msg": "รอบนี้จบแล้ว", "session": _fort_public(sess)}), 400
        if action not in ("repair", "shield", "gust"):
            return jsonify({"st": "error", "msg": "action ไม่ถูกต้อง"}), 400
        t = None
        if action != "gust":
            t = _fort_turret(sess, int(body.get("lane", -1)), int(body.get("row", -1)))
            if not t or t["broken"]:
                return jsonify({"st": "error", "msg": "ป้อมนี้แตกแล้ว/ไม่พบป้อม (ซ่อมป้อมที่แตกไม่ได้)"}), 400
        if not _fort_cd_ok(sess, action):
            return jsonify({"st": "error", "msg": "คูลดาวน์"}), 429
        if action == "repair":
            t["hp"] = min(t["max_hp"], t["hp"] + 160)
        elif action == "shield":
            t["shield"] = min(600, t["shield"] + 300)
        else:
            sess["gust_until"] = time.time() + 5.0
            _fort_log(sess, "🌪️ ลมกระโชกชะลอฝ่ายบุก 5 วินาที")
        return jsonify({"st": "ok", "session": _fort_public(sess)})


# ---------- แลกเงินในเกมจากเกมยิงเก็บของหนี -> บัตรรูปลักษณ์ ----------
@app.route('/api/fortress/cards/catalog')
def api_fortress_cards_catalog():
    uid = str(request.args.get("uid") or "guest")
    c = _fort_cards(uid)
    lim = _fort_limits_status(uid)
    return jsonify({"st": "ok", "catalog": FORTRESS_APPEARANCE_CARDS, "owned": c["owned"], "equipped": c["equipped"],
                    "gold": _currency_get(uid)["gold"], "coins": c["coins"],
                    "limits": lim,
                    "stash": dict(EXTRACTION_STASH.get(uid, {}))})


@app.route('/api/fortress/cards/sell-loot', methods=['POST'])
@require_auth
def api_fortress_sell_loot():
    """ขายของที่เก็บได้จากโหมดยิงเก็บของหนี (EXTRACTION_STASH) เป็นเงินในเกม (gold) ตามราคา value ใน EXTRACTION_ITEM_DB"""
    uid, body = _fort_uid(), request.get_json(silent=True) or {}
    stash = EXTRACTION_STASH[uid]
    wanted = body.get("item_ids") or list(stash.keys())
    total, sold = 0, {}
    for item_id in wanted:
        qty, value = int(stash.get(item_id, 0)), int(EXTRACTION_ITEM_DB.get(item_id, {}).get("value", 0))
        if qty > 0 and value > 0:
            total += qty * value
            sold[item_id] = qty
            del stash[item_id]
    _currency_get(uid)["gold"] += total
    return jsonify({"st": "ok", "sold": sold, "gold_gained": total, "gold": _currency_get(uid)["gold"]})


@app.route('/api/fortress/cards/exchange', methods=['POST'])
@require_auth
def api_fortress_cards_exchange():
    """แลกบัตรรูปลักษณ์ป้อม ด้วย gold (เงินในเกมจาก loot) และ/หรือ coins (เหรียญอีเวนต์)
    มี daily exchange limit + weekly quota กันปั๊ม และบันทึก ledger ลงไฟล์"""
    uid, body = _fort_uid(), request.get_json(silent=True) or {}
    card_id = str(body.get("card_id", ""))
    card = FORTRESS_APPEARANCE_CARDS.get(card_id)
    if not card:
        return jsonify({"st": "error", "msg": "ไม่มีบัตรนี้"}), 400
    with _FORT_LOCK:
        cur = _currency_get(uid)
        st = _fort_load_state(uid)
        lim = _fort_limits_status(uid)
        if card_id in st["owned"]:
            return jsonify({"st": "error", "msg": "มีบัตรนี้แล้ว", "limits": lim}), 400
        if lim["daily_remaining"] <= 0:
            return jsonify({"st": "error", "msg": f"ครบลิมิตแลกรายวันแล้ว ({lim['daily_limit']} ครั้ง/วัน)", "limits": lim}), 429
        if lim["weekly_remaining"] <= 0:
            return jsonify({"st": "error", "msg": f"ครบโควตาสัปดาห์แล้ว ({lim['weekly_quota']} บัตร/สัปดาห์) รีเซ็ตวันจันทร์", "limits": lim}), 429
        if cur["gold"] < card["gold"] or st["coins"] < card["coins"]:
            return jsonify({"st": "error", "msg": "เงินในเกมหรือเหรียญไม่พอ", "limits": lim}), 400
        # debit + grant
        cur["gold"] -= card["gold"]
        st["coins"] -= card["coins"]
        st["owned"][card_id] = st["owned"].get(card_id, 0) + 1
        today, week = lim["today"], lim["week"]
        st["daily_exchanges"][today] = int(st["daily_exchanges"].get(today, 0)) + 1
        st["weekly_grants"][week] = int(st["weekly_grants"].get(week, 0)) + 1
        _fort_ledger_append(st, "exchange", card_id=card_id, gold=card["gold"], coins=card["coins"],
                            rarity=card.get("rarity"), source="in_game")
        _fort_save_state(uid, st)
        lim2 = _fort_limits_status(uid)
    return jsonify({
        "st": "ok", "card_id": card_id, "gold": cur["gold"], "coins": st["coins"],
        "owned": st["owned"], "limits": lim2,
    })


@app.route('/api/fortress/cards/equip', methods=['POST'])
@require_auth
def api_fortress_cards_equip():
    uid, body = _fort_uid(), request.get_json(silent=True) or {}
    card_id = str(body.get("card_id", ""))
    st = _fort_load_state(uid)
    if card_id not in st["owned"]:
        return jsonify({"st": "error", "msg": "ยังไม่มีบัตรนี้"}), 400
    st["equipped"] = card_id
    _fort_ledger_append(st, "equip", card_id=card_id)
    _fort_save_state(uid, st)
    return jsonify({"st": "ok", "equipped": card_id})


@app.route('/api/fortress/cards/status')
@require_auth
def api_fortress_cards_status():
    """สถานะบัตร + ลิมิต daily/weekly ที่เหลือ (สำหรับหน้ากิจกรรม)"""
    uid = _fort_uid()
    st = _fort_load_state(uid)
    lim = _fort_limits_status(uid)
    return jsonify({
        "st": "ok",
        "coins": st["coins"],
        "owned": st["owned"],
        "equipped": st["equipped"],
        "gold": _currency_get(uid).get("gold", 0),
        "limits": lim,
        "ledger_tail": (st.get("ledger") or [])[-20:],
    })


# ---------- ชำระเงิน: ตัดเงินจริงผ่าน wallet ของเว็บไซต์คุณ (charge -> confirm) เท่านั้น ----------
@app.route('/api/fortress/pay/packs')
def api_fortress_pay_packs():
    return jsonify({"st": "ok", "currency": FORTRESS_PAY_CURRENCY, "packs": FORTRESS_COIN_PACKS})


@app.route('/api/fortress/pay/start', methods=['POST'])
@require_auth
def api_fortress_pay_start():
    uid, body = _fort_uid(), request.get_json(silent=True) or {}
    pack_id, qty = str(body.get("pack_id", "")), max(1, min(10, int(body.get("qty", 1) or 1)))
    pack = FORTRESS_COIN_PACKS.get(pack_id)
    if not pack:
        return jsonify({"st": "error", "msg": "ไม่มีแพ็กนี้"}), 400
    _fw_base = FORTRESS_WALLET_API_BASE or None
    charge = _wallet_call_auto("charge", base_override=_fw_base, json={"uid": uid, "amount": pack["price"] * qty, "currency": FORTRESS_PAY_CURRENCY,
                                               "ref": "fortress:%s:x%d" % (pack_id, qty)})
    if charge.get("st") != "ok":
        return jsonify(charge), 502
    charge_id = charge.get("charge_id")
    if not charge_id:
        return jsonify({"st": "error", "msg": "wallet API ไม่ได้ส่ง charge_id กลับมา"}), 502
    FORTRESS_PENDING_PAY[charge_id] = {"uid": uid, "pack_id": pack_id, "qty": qty, "coins": pack["coins"] * qty}
    # แสดงบัตรบนป๊อปอัปได้เฉพาะเมื่อ wallet ส่งข้อมูลแบบ "ปกปิดแล้ว" กลับมาเท่านั้น (brand + 4 ตัวท้าย) — ระบบนี้ไม่เก็บเลขบัตร
    card = {"brand": charge.get("card_brand"), "last4": charge.get("card_last4")} if charge.get("card_last4") else None
    return jsonify({"st": "payment_pending", "charge_id": charge_id, "amount": pack["price"] * qty,
                    "currency": FORTRESS_PAY_CURRENCY, "card": card})


@app.route('/api/fortress/pay/confirm', methods=['POST'])
@require_auth
def api_fortress_pay_confirm():
    """ยืนยันการเติมเหรียญอีเวนต์ — idempotent (charge_id ใช้ได้ครั้งเดียว) + บันทึกลงไฟล์"""
    uid, body = _fort_uid(), request.get_json(silent=True) or {}
    charge_id = str(body.get("charge_id", ""))
    with _FORT_LOCK:
        pending = FORTRESS_PENDING_PAY.get(charge_id)
        if not pending or pending["uid"] != uid:
            # อาจยืนยันไปแล้ว — ตรวจจาก ledger ว่าเคย grant แล้วหรือยัง
            st = _fort_load_state(uid)
            for e in reversed(st.get("ledger") or []):
                if e.get("type") == "coin_topup" and e.get("charge_id") == charge_id:
                    return jsonify({"st": "ok", "msg": "order นี้ประมวลผลแล้ว (idempotent)", "duplicate": True,
                                    "coins": st["coins"], "coins_added": 0})
            return jsonify({"st": "error", "msg": "ไม่พบรายการชำระเงินนี้ (หรือถูกยืนยันไปแล้ว)"}), 400
    confirm = _wallet_call_auto("confirm", base_override=(FORTRESS_WALLET_API_BASE or None), json={"charge_id": charge_id})
    if confirm.get("st") != "ok" or confirm.get("status") not in ("ok", "success", "paid"):
        return jsonify({"st": "pending", "msg": "wallet ยังไม่ยืนยันการตัดเงิน", "wallet_response": confirm}), 202
    with _FORT_LOCK:
        pending = FORTRESS_PENDING_PAY.pop(charge_id, None)
        if not pending:
            st = _fort_load_state(uid)
            return jsonify({"st": "ok", "msg": "order นี้ประมวลผลแล้ว (idempotent)", "duplicate": True, "coins": st["coins"]})
        st = _fort_load_state(uid)
        st["coins"] += int(pending["coins"])
        _fort_ledger_append(st, "coin_topup", charge_id=charge_id, coins=pending["coins"],
                            pack_id=pending.get("pack_id"), qty=pending.get("qty"), source="vmax_pay")
        _fort_save_state(uid, st)
    return jsonify({"st": "ok", "coins_added": pending["coins"], "coins": st["coins"]})


