# [ 6AI. VMAX AI SUPPORT MESH — Website / User App / Engine + AI-to-AI Council ]
# ==========================================
# AI Support กลางสำหรับ Web / User App / Game Engine
# มี shared persistent memory, feedback learning และ AI-to-AI consultation
# หมายเหตุ: learning ที่นี่คือการสะสม/ประเมินความรู้และ feedback ไม่ใช่การฝึก model weights อัตโนมัติ
# ==========================================
AI_MESH_DB_PATH = os.environ.get("VMAX_AI_MESH_DB_PATH", os.path.join(os.path.dirname(os.path.abspath(__file__)), "vmax_ai_mesh.sqlite3"))
AI_MESH_LOCK = threading.RLock()
AI_MESH_NODES = {}
AI_MESH_LAST_EVENTS = deque(maxlen=500)
AI_MESH_CONFIG = {
    "enabled": True, "max_memory": 12, "max_consult_agents": 6,
    "memory_min_confidence": 0.55, "default_provider": os.environ.get("VMAX_AI_PROVIDER", "auto"),
    "default_model": os.environ.get("VMAX_AI_MODEL", ""),
    "openai_base_url": os.environ.get("OPENAI_BASE_URL", "https://api.openai.com/v1"),
    "anthropic_model": os.environ.get("ANTHROPIC_MODEL", "claude-sonnet-4-6"),
    "local_base_url": os.environ.get("VMAX_LOCAL_AI_BASE_URL", "http://127.0.0.1:11434/v1"),
    "local_model": os.environ.get("VMAX_LOCAL_AI_MODEL", "llama3.2"),
}

def _ai_mesh_db():
    os.makedirs(os.path.dirname(os.path.abspath(AI_MESH_DB_PATH)), exist_ok=True)
    con = sqlite3.connect(AI_MESH_DB_PATH, timeout=20, check_same_thread=False)
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA journal_mode=WAL")
    con.execute("CREATE TABLE IF NOT EXISTS ai_mesh_memory (id INTEGER PRIMARY KEY AUTOINCREMENT, scope TEXT NOT NULL DEFAULT 'global', topic TEXT NOT NULL DEFAULT '', content TEXT NOT NULL, source_node TEXT NOT NULL DEFAULT '', source_kind TEXT NOT NULL DEFAULT '', confidence REAL NOT NULL DEFAULT 0.6, verified INTEGER NOT NULL DEFAULT 0, usefulness REAL NOT NULL DEFAULT 0, created_at REAL NOT NULL, updated_at REAL NOT NULL)")
    con.execute("CREATE TABLE IF NOT EXISTS ai_mesh_events (id INTEGER PRIMARY KEY AUTOINCREMENT, event_type TEXT NOT NULL, node_id TEXT NOT NULL DEFAULT '', payload TEXT NOT NULL DEFAULT '{}', created_at REAL NOT NULL)")
    con.execute("CREATE TABLE IF NOT EXISTS ai_mesh_feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, memory_id INTEGER, node_id TEXT NOT NULL DEFAULT '', rating REAL NOT NULL, note TEXT NOT NULL DEFAULT '', created_at REAL NOT NULL)")
    con.commit()
    return con

def _ai_mesh_event(event_type, node_id="", payload=None):
    now = time.time(); payload = payload if isinstance(payload, dict) else {}
    with AI_MESH_LOCK:
        AI_MESH_LAST_EVENTS.append({"type": event_type, "node_id": node_id, "payload": payload, "ts": now})
        try:
            con = _ai_mesh_db(); con.execute("INSERT INTO ai_mesh_events(event_type,node_id,payload,created_at) VALUES(?,?,?,?)", (event_type, node_id, json.dumps(payload, ensure_ascii=False), now)); con.commit(); con.close()
        except Exception as e: print(f"[AI Mesh] event persist warning: {e}")

def _ai_mesh_init():
    try: _ai_mesh_db().close()
    except Exception as e: print(f"[AI Mesh] database init warning: {e}")

def _ai_mesh_register(node_id, kind, name, capabilities=None, metadata=None):
    node_id = secure_filename(str(node_id or "").strip())[:80] or ("node_" + uuid.uuid4().hex[:10])
    now = time.time()
    node = {"node_id": node_id, "kind": str(kind or "unknown").strip().lower()[:40], "name": str(name or node_id).strip()[:120], "capabilities": list(capabilities or []), "metadata": metadata or {}, "registered_at": AI_MESH_NODES.get(node_id, {}).get("registered_at", now), "last_seen": now}
    with AI_MESH_LOCK: AI_MESH_NODES[node_id] = node
    _ai_mesh_event("node_register", node_id, {"kind": node["kind"], "name": node["name"]})
    return node

def _ai_mesh_touch(node_id):
    if node_id in AI_MESH_NODES: AI_MESH_NODES[node_id]["last_seen"] = time.time()

def _ai_mesh_tokenize(text):
    return re.findall(r"[A-Za-z0-9_\-]{2,}|[ก-๙]{2,}", str(text).lower())

def _ai_mesh_memory_search(query, scope="global", limit=8):
    terms = set(_ai_mesh_tokenize(query))
    with AI_MESH_LOCK:
        con = _ai_mesh_db(); rows = con.execute("SELECT * FROM ai_mesh_memory WHERE scope IN (?, 'global') ORDER BY updated_at DESC LIMIT 500", (scope or "global",)).fetchall(); con.close()
    scored=[]
    for r in rows:
        rt=set(_ai_mesh_tokenize(r["topic"]+" "+r["content"])); overlap=len(terms&rt)/max(1,len(terms)) if terms else 0
        score=overlap*0.7+float(r["confidence"])*0.2+min(1.0,float(r["usefulness"])/10.0)*0.1
        if overlap>0 or not terms: scored.append((score,dict(r)))
    scored.sort(key=lambda x:x[0], reverse=True)
    return [{**row,"score":round(score,4)} for score,row in scored[:max(1,min(int(limit),50))]]

def _ai_mesh_add_memory(content, topic="", source_node="", source_kind="", scope="global", confidence=0.65, verified=False):
    content=str(content or "").strip()
    if not content: raise ValueError("memory content is required")
    confidence=max(0.0,min(1.0,float(confidence))); now=time.time()
    with AI_MESH_LOCK:
        con=_ai_mesh_db(); cur=con.execute("INSERT INTO ai_mesh_memory(scope,topic,content,source_node,source_kind,confidence,verified,usefulness,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)", (str(scope or "global")[:80],str(topic or "")[:200],content[:12000],str(source_node or "")[:80],str(source_kind or "")[:40],confidence,1 if verified else 0,0.0,now,now)); mid=cur.lastrowid; con.commit(); con.close()
    _ai_mesh_event("memory_added",source_node,{"memory_id":mid,"topic":topic}); return mid

def _ai_mesh_feedback(memory_id,node_id,rating,note=""):
    rating=max(-1.0,min(1.0,float(rating))); now=time.time()
    with AI_MESH_LOCK:
        con=_ai_mesh_db(); con.execute("INSERT INTO ai_mesh_feedback(memory_id,node_id,rating,note,created_at) VALUES(?,?,?,?,?)",(int(memory_id),str(node_id or "")[:80],rating,str(note or "")[:2000],now)); con.execute("UPDATE ai_mesh_memory SET usefulness=usefulness+?, confidence=CASE WHEN ? > 0 THEN MIN(1.0,confidence+0.03) ELSE MAX(0.0,confidence-0.03) END, updated_at=? WHERE id=?",(rating,rating,now,int(memory_id))); con.commit(); con.close()
    _ai_mesh_event("memory_feedback",node_id,{"memory_id":memory_id,"rating":rating})

def _ai_mesh_provider_ready(provider):
    if provider=="openai": return bool(os.environ.get("OPENAI_API_KEY","" ).strip())
    if provider=="anthropic": return bool(os.environ.get("ANTHROPIC_API_KEY","" ).strip())
    if provider=="local": return bool(AI_MESH_CONFIG.get("local_base_url"))
    return False

def _ai_mesh_resolve_provider(requested=None):
    p=str(requested or AI_MESH_CONFIG.get("default_provider","auto")).lower()
    if p in ("openai","anthropic","local"): return p
    for candidate in ("openai","anthropic","local"):
        if _ai_mesh_provider_ready(candidate): return candidate
    return None

def _ai_mesh_call_llm(system_prompt,user_prompt,provider=None,model=None,timeout=45):
    provider=_ai_mesh_resolve_provider(provider)
    if not provider: return {"ok":False,"provider":None,"error":"no_ai_provider_available"}
    try:
        if provider=="openai":
            base=os.environ.get("OPENAI_BASE_URL",AI_MESH_CONFIG["openai_base_url"]).rstrip("/"); model=model or AI_MESH_CONFIG.get("default_model") or os.environ.get("OPENAI_MODEL","gpt-4o-mini")
            resp=requests.post(base+"/chat/completions",headers={"Authorization":"Bearer "+os.environ["OPENAI_API_KEY"],"Content-Type":"application/json"},json={"model":model,"temperature":0.2,"messages":[{"role":"system","content":system_prompt},{"role":"user","content":user_prompt}]},timeout=timeout); resp.raise_for_status(); data=resp.json(); return {"ok":True,"provider":provider,"model":model,"text":data.get("choices",[{}])[0].get("message",{}).get("content","").strip()}
        if provider=="anthropic":
            model=model or AI_MESH_CONFIG["anthropic_model"]; resp=requests.post("https://api.anthropic.com/v1/messages",headers={"x-api-key":os.environ["ANTHROPIC_API_KEY"],"anthropic-version":"2023-06-01","Content-Type":"application/json"},json={"model":model,"max_tokens":1200,"system":system_prompt,"messages":[{"role":"user","content":user_prompt}]},timeout=timeout); resp.raise_for_status(); data=resp.json(); text="".join(x.get("text","") for x in data.get("content",[]) if x.get("type")=="text").strip(); return {"ok":True,"provider":provider,"model":model,"text":text}
        base=AI_MESH_CONFIG["local_base_url"].rstrip("/"); model=model or AI_MESH_CONFIG["local_model"]; headers={"Content-Type":"application/json"}
        if os.environ.get("LOCAL_AI_API_KEY"): headers["Authorization"]="Bearer "+os.environ["LOCAL_AI_API_KEY"]
        resp=requests.post(base+"/chat/completions",headers=headers,json={"model":model,"temperature":0.2,"messages":[{"role":"system","content":system_prompt},{"role":"user","content":user_prompt}]},timeout=timeout); resp.raise_for_status(); data=resp.json(); return {"ok":True,"provider":provider,"model":model,"text":data.get("choices",[{}])[0].get("message",{}).get("content","").strip()}
    except Exception as e: return {"ok":False,"provider":provider,"error":str(e)}

def _ai_mesh_context(question,scope="global"):
    mem=_ai_mesh_memory_search(question,scope,AI_MESH_CONFIG["max_memory"]); memory_text="\n".join(f"[memory#{m['id']} confidence={m['confidence']:.2f} verified={bool(m['verified'])}] {m['content']}" for m in mem) or "(ไม่มี shared memory ที่เกี่ยวข้อง)"
    nodes=list(AI_MESH_NODES.values()); node_text="\n".join(f"- {n['node_id']} ({n['kind']}): {n['name']}" for n in nodes[-30:]) or "(ไม่มี node ออนไลน์)"; return memory_text,node_text

def _ai_mesh_ask(question,node_id="",scope="global",provider=None,model=None,context=None):
    question=str(question or "").strip()
    if not question:return {"ok":False,"error":"question_required"}
    if node_id:_ai_mesh_touch(node_id)
    memories,nodes=_ai_mesh_context(question,scope); extra=json.dumps(context or {},ensure_ascii=False)
    system=("คุณคือ VMAX AI Support Mesh สำหรับเกม เว็บไซต์ และแอป. ใช้ shared memory เป็นหลัก; ถ้าข้อมูลไม่พอให้บอกว่าไม่ทราบ; ห้ามสร้างสิทธิ์/เหตุการณ์ขึ้นเอง; ห้ามเปิดเผย secret/API key; การกระทำสำคัญต้องให้ human/admin ยืนยัน.\n\nSHARED MEMORY:\n"+memories+"\n\nONLINE AI NODES:\n"+nodes)
    result=_ai_mesh_call_llm(system,"คำถาม:\n"+question+"\n\nruntime context:\n"+extra,provider,model); result.update({"question":question,"node_id":node_id,"memory_count":memories.count("[memory#")}); _ai_mesh_event("ai_ask",node_id,{"provider":result.get("provider"),"ok":result.get("ok")}); return result

def _ai_mesh_consult(question,node_id="",requested_nodes=None,scope="global",provider=None,model=None):
    question=str(question or "").strip()
    if not question:return {"ok":False,"error":"question_required"}
    requested_nodes=requested_nodes if isinstance(requested_nodes,list) else []
    with AI_MESH_LOCK: candidates=[n for n in AI_MESH_NODES.values() if not requested_nodes or n["node_id"] in requested_nodes]
    candidates=candidates[:AI_MESH_CONFIG["max_consult_agents"]] or [{"node_id":"central_coordinator","kind":"engine","name":"Central Coordinator"}]
    memory_text,_=_ai_mesh_context(question,scope); opinions=[]
    for n in candidates:
        r=_ai_mesh_call_llm("คุณเป็นสมาชิกสภา AI ของ VMAX. ให้ความเห็นเชิงเทคนิค/ปฏิบัติการ ระบุ assumptions และความเสี่ยงสั้น ๆ และอย่าอ้างว่าทำสิ่งที่ไม่ได้ทำจริง.\n\nShared memory:\n"+memory_text,question,provider,model)
        opinions.append({"node_id":n["node_id"],"kind":n.get("kind"),"name":n.get("name"),"ok":r.get("ok"),"provider":r.get("provider"),"text":r.get("text",""),"error":r.get("error")})
    joined="\n\n".join(f"[{o['node_id']}] {o['text']}" for o in opinions if o.get("text"))
    c=_ai_mesh_call_llm("คุณคือ Central AI Coordinator. สังเคราะห์ความเห็นจาก AI หลายตัวเป็นคำตอบเดียวที่ตรวจสอบได้; ถ้าขัดกันให้บอกความขัดแย้ง; ห้ามอ้างว่าตรวจระบบจริงถ้ายังไม่ได้ตรวจ.","คำถาม:\n"+question+"\n\nความเห็นจาก AI อื่น:\n"+(joined or "ไม่มีความเห็นที่ใช้งานได้"),provider,model)
    result={"ok":c.get("ok",False),"question":question,"opinions":opinions,"consensus":c.get("text",""),"provider":c.get("provider"),"model":c.get("model"),"error":c.get("error")}; _ai_mesh_event("ai_consult",node_id,{"agents":len(opinions),"ok":result["ok"]}); return result

