@app.route('/api/ai-mesh/config',methods=['GET','POST'])
def api_ai_mesh_config():
    rejected=[]
    if request.method=='POST':
        # [SEC-AUDIT] เดิมใครก็ POST เปลี่ยน openai_base_url/local_base_url ได้ แล้วสั่ง /api/ai-mesh/ask ให้เซิร์ฟเวอร์ส่ง
        # OPENAI_API_KEY ไปที่เซิร์ฟเวอร์ของผู้โจมตี ตอนนี้ต้องเป็น admin และแก้ URL ผ่าน HTTP ไม่ได้ (ตั้งผ่าน env เท่านั้น)
        _u,_r=_staff_from_request()
        if _u is None: return jsonify({"st":"error","msg":"ต้องล็อกอินก่อน (Bearer token)"}),401
        if _r is None or _r<STAFF_RANKS["admin"]: return jsonify({"st":"error","msg":"ต้องเป็น admin ขึ้นไป"}),403
        b=request.get_json(force=True,silent=True) or {}
        for k in AI_MESH_CONFIG:
            if k not in b: continue
            cur=AI_MESH_CONFIG[k]; new=b[k]
            both_num=isinstance(cur,(int,float)) and isinstance(new,(int,float)) and not isinstance(cur,bool) and not isinstance(new,bool)
            if k in ("openai_base_url","local_base_url") or not (type(new) is type(cur) or both_num): rejected.append(k); continue
            AI_MESH_CONFIG[k]=new
    safe=dict(AI_MESH_CONFIG); safe["providers_ready"]={p:_ai_mesh_provider_ready(p) for p in ("openai","anthropic","local")}; return jsonify({"st":"ok","config":safe,"rejected":rejected})

@app.route('/api/ai-mesh/sdk',methods=['GET'])
def api_ai_mesh_sdk():
    base=request.url_root.rstrip('/')
    js='''class VMAXAIMesh { constructor(baseUrl,nodeId){this.baseUrl=(baseUrl||"'''+base+''' ").trim().replace(/\\/$/,"");this.nodeId=nodeId||("client_"+Math.random().toString(16).slice(2));} async post(p,b){let r=await fetch(this.baseUrl+p,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(b)});return r.json();} register(kind,name,capabilities=[]){return this.post("/api/ai-mesh/register",{node_id:this.nodeId,kind,name,capabilities});} heartbeat(meta={}){return this.post("/api/ai-mesh/heartbeat",{node_id:this.nodeId,...meta});} ask(question,context={}){return this.post("/api/ai-mesh/ask",{node_id:this.nodeId,question,context});} consult(question,nodes=[]){return this.post("/api/ai-mesh/consult",{node_id:this.nodeId,question,nodes});} learn(content,topic="",verified=false){return this.post("/api/ai-mesh/memory",{node_id:this.nodeId,content,topic,verified,source_kind:"client"});} }'''
    py='''import requests,uuid\nclass VMAXAIMesh:\n def __init__(self,base_url="'''+base+'''",node_id=None): self.base_url=base_url.rstrip("/"); self.node_id=node_id or "client_"+uuid.uuid4().hex[:10]\n def post(self,path,payload): r=requests.post(self.base_url+path,json=payload,timeout=45); r.raise_for_status(); return r.json()\n def register(self,kind,name,capabilities=None): return self.post("/api/ai-mesh/register",{"node_id":self.node_id,"kind":kind,"name":name,"capabilities":capabilities or []})\n def heartbeat(self,**meta): return self.post("/api/ai-mesh/heartbeat",{"node_id":self.node_id,**meta})\n def ask(self,question,context=None): return self.post("/api/ai-mesh/ask",{"node_id":self.node_id,"question":question,"context":context or {}})\n def consult(self,question,nodes=None): return self.post("/api/ai-mesh/consult",{"node_id":self.node_id,"question":question,"nodes":nodes or []})\n def learn(self,content,topic="",verified=False): return self.post("/api/ai-mesh/memory",{"node_id":self.node_id,"content":content,"topic":topic,"verified":verified,"source_kind":"client"})\n'''
    return jsonify({"st":"ok","base_url":base,"javascript":js,"python":py,"node_kinds":["website_support","user_app","engine","admin","worker","external_ai"],"protocol":["register","heartbeat","ask","consult","memory","feedback"]})

AI_MESH_SUPPORT_PAGE='''<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VMAX AI Support Mesh</title><style>body{font-family:system-ui;background:#0b1020;color:#eef;padding:24px;max-width:1100px;margin:auto}.row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card{background:#111a2d;border:1px solid #293b5a;border-radius:14px;padding:16px;margin:12px 0}textarea{width:100%;box-sizing:border-box;background:#0a1222;color:#fff;border:1px solid #334766;border-radius:10px;padding:10px}button{padding:10px 16px;border-radius:10px;border:1px solid #45658d;background:#18304e;color:#fff}.out{white-space:pre-wrap;background:#080d18;border-radius:10px;padding:12px;min-height:70px}@media(max-width:700px){.row{grid-template-columns:1fr}}</style></head><body><h1>🤖 VMAX AI Support Mesh</h1><p>Website / User App / Engine ใช้ AI กลาง, shared memory และ AI council ร่วมกัน</p><div class="row"><div class="card"><h3>Support AI</h3><textarea id="q" rows="5" placeholder="ถามระบบ..."></textarea><br><br><button onclick="ask()">ถาม AI</button><div id="a" class="out"></div></div><div class="card"><h3>AI Council</h3><textarea id="cq" rows="5" placeholder="เรื่องที่อยากให้ AI หลายตัวปรึกษากัน..."></textarea><br><br><button onclick="consult()">ให้ AI ปรึกษากัน</button><div id="ca" class="out"></div></div></div><div class="card"><h3>AI Nodes</h3><div id="nodes">loading...</div></div><script>async function post(u,b){let r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});return r.json()}async function ask(){let d=await post('/api/ai-mesh/ask',{node_id:'web_support',question:document.getElementById('q').value});document.getElementById('a').textContent=d.text||d.error||'ไม่มีคำตอบ'}async function consult(){let d=await post('/api/ai-mesh/consult',{node_id:'web_support',question:document.getElementById('cq').value});document.getElementById('ca').textContent=d.consensus||d.error||'ไม่มี consensus'}async function load(){let d=await fetch('/api/ai-mesh/nodes').then(r=>r.json());document.getElementById('nodes').innerHTML=d.nodes.map(n=>'• '+n.node_id+' — '+n.kind+' — '+n.name+' — '+(n.online?'online':'offline')).join('<br>')||'ยังไม่มี node'}load();setInterval(load,5000)</script></body></html>'''
