CREATOR_DB_PATH = os.environ.get("VMAX_CREATOR_DB_PATH", os.path.join(os.path.dirname(os.path.abspath(__file__)), "vmax_ai_creator.sqlite3"))
CREATOR_LOCK = threading.RLock(); CREATOR_JOBS = {}; CREATOR_QUEUE = deque(); CREATOR_WORKER_STARTED = False
CREATOR_MODELS_DEFAULT = [
 {"id":"image-default","name":"Image AI (default)","kind":"image","provider":"auto","model":os.environ.get("VMAX_IMAGE_AI_MODEL",""),"enabled":True},
 {"id":"video-default","name":"Video AI (default)","kind":"video","provider":"auto","model":os.environ.get("VMAX_VIDEO_AI_MODEL",""),"enabled":True},
 {"id":"animation-default","name":"Animation AI (default)","kind":"animation","provider":"auto","model":os.environ.get("VMAX_ANIMATION_AI_MODEL",""),"enabled":True},
]
def _creator_db():
 db=sqlite3.connect(CREATOR_DB_PATH,timeout=30,check_same_thread=False); db.row_factory=sqlite3.Row
 db.execute("PRAGMA journal_mode=WAL")
 db.execute("CREATE TABLE IF NOT EXISTS creator_models (id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,provider TEXT NOT NULL,model TEXT DEFAULT '',endpoint TEXT DEFAULT '',enabled INTEGER DEFAULT 1,meta_json TEXT DEFAULT '{}',created_at REAL,updated_at REAL)")
 db.execute("CREATE TABLE IF NOT EXISTS creator_preferences (key TEXT PRIMARY KEY,value TEXT,updated_at REAL)")
 db.execute("CREATE TABLE IF NOT EXISTS creator_jobs (id TEXT PRIMARY KEY,kind TEXT,model_id TEXT,prompt TEXT,status TEXT,result_json TEXT DEFAULT '{}',error TEXT DEFAULT '',created_at REAL,updated_at REAL)"); db.commit(); return db
def _creator_init():
 db=_creator_db(); now=time.time()
 for m in CREATOR_MODELS_DEFAULT: db.execute("INSERT OR IGNORE INTO creator_models(id,name,kind,provider,model,enabled,meta_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)",(m["id"],m["name"],m["kind"],m["provider"],m["model"],1,"{}",now,now))
 db.commit(); db.close()
def _creator_models():
 db=_creator_db(); rows=db.execute("SELECT * FROM creator_models WHERE enabled=1 ORDER BY kind,name").fetchall(); db.close(); out=[]
 for r in rows:
  x=dict(r); x["enabled"]=bool(x["enabled"])
  try:x["meta"]=json.loads(x.pop("meta_json") or "{}")
  except Exception:x["meta"]={}
  out.append(x)
 return out
def _creator_pref_get(key,default=None):
 db=_creator_db(); r=db.execute("SELECT value FROM creator_preferences WHERE key=?",(key,)).fetchone(); db.close()
 if not r:return default
 try:return json.loads(r[0])
 except Exception:return r[0]
def _creator_pref_set(key,value):
 db=_creator_db(); now=time.time(); db.execute("INSERT INTO creator_preferences(key,value,updated_at) VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(key,json.dumps(value,ensure_ascii=False),now)); db.commit(); db.close()
def _creator_find_model(model_id,kind=None):
 for m in _creator_models():
  if m["id"]==model_id and (kind is None or m["kind"]==kind): return m
 return None
def _creator_http_json(endpoint,payload,provider="custom",timeout=180):
 # [SEC-AUDIT] ส่ง API key ไปเฉพาะโฮสต์ที่ไว้ใจ (openai/anthropic + โฮสต์จาก env + VMAX_TRUSTED_API_HOSTS) กัน key รั่ว/SSRF
 if not _vs_url_trusted(endpoint): raise RuntimeError("endpoint นี้ไม่อยู่ใน trusted hosts (เพิ่มชื่อโฮสต์ใน env VMAX_TRUSTED_API_HOSTS)")
 headers={"Content-Type":"application/json"}
 key=(os.environ.get("OPENAI_API_KEY") if provider=="openai" else os.environ.get("VMAX_MEDIA_AI_API_KEY") or os.environ.get("OPENAI_API_KEY"))
 if provider in ("openai","openai-compatible","custom") and key: headers["Authorization"]="Bearer "+key
 if provider=="anthropic" and os.environ.get("ANTHROPIC_API_KEY"):
  headers["x-api-key"]=os.environ["ANTHROPIC_API_KEY"]; headers["anthropic-version"]="2023-06-01"
 r=requests.post(endpoint,headers=headers,json=payload,timeout=timeout); r.raise_for_status(); return r.json()
def _creator_generate(job):
 model=_creator_find_model(job["model_id"],job["kind"])
 if not model: raise RuntimeError("ไม่พบ model ที่เลือก หรือ model ถูกปิดใช้งาน")
 endpoint=model.get("endpoint") or os.environ.get("VMAX_MEDIA_AI_URL","")
 if not endpoint: raise RuntimeError("ยังไม่ได้ตั้ง media AI endpoint สำหรับ model นี้ — ตั้ง endpoint ใน model catalog หรือ VMAX_MEDIA_AI_URL")
 payload={"model":model.get("model") or model["id"],"prompt":job["prompt"],"kind":job["kind"],"input":job.get("input") or {},"options":job.get("options") or {}}
 return _creator_http_json(endpoint,payload,provider=model.get("provider") or "custom",timeout=int((job.get("options") or {}).get("timeout",180)))
def _creator_worker_loop():
 while True:
  with CREATOR_LOCK: job_id=CREATOR_QUEUE.popleft() if CREATOR_QUEUE else None
  if not job_id: time.sleep(.25); continue
  with CREATOR_LOCK: job=CREATOR_JOBS.get(job_id)
  if not job: continue
  job["status"]="running"; job["updated_at"]=time.time()
  try: job["result"]=_creator_generate(job); job["status"]="completed"; job["error"]=""
  except Exception as e: job["status"]="error"; job["error"]=str(e)
  job["updated_at"]=time.time(); db=_creator_db(); db.execute("UPDATE creator_jobs SET status=?,result_json=?,error=?,updated_at=? WHERE id=?",(job["status"],json.dumps(job.get("result",{}),ensure_ascii=False),job.get("error",""),job["updated_at"],job_id)); db.commit(); db.close()
def _creator_start_worker():
 global CREATOR_WORKER_STARTED
 if CREATOR_WORKER_STARTED:return
 CREATOR_WORKER_STARTED=True; threading.Thread(target=_creator_worker_loop,daemon=True,name="vmax-creator-worker").start()
def _creator_submit(kind,body):
 model_id=str(body.get("model_id","")).strip(); prompt=str(body.get("prompt","")).strip(); model=_creator_find_model(model_id,kind)
 if not model: raise ValueError("ต้องเลือก model ที่ตรงกับประเภทงานก่อน")
 if not prompt: raise ValueError("ต้องใส่ prompt")
 jid="cr_"+uuid.uuid4().hex; now=time.time(); job={"id":jid,"kind":kind,"model_id":model_id,"prompt":prompt,"input":body.get("input") or {},"options":body.get("options") or {},"status":"queued","result":{},"error":"","created_at":now,"updated_at":now}
 with CREATOR_LOCK: CREATOR_JOBS[jid]=job; CREATOR_QUEUE.append(jid)
 db=_creator_db(); db.execute("INSERT INTO creator_jobs(id,kind,model_id,prompt,status,result_json,error,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)",(jid,kind,model_id,prompt,"queued","{}","",now,now)); db.commit(); db.close(); return job
@app.route('/api/creator/models',methods=['GET','POST'])
def api_creator_models():
 if request.method=='GET': return jsonify({"st":"ok","models":_creator_models(),"selected":_creator_pref_get("selected_models",{})})
 _u,_r=_staff_from_request()
 if _u is None or _r is None or _r<STAFF_RANKS["admin"]: return jsonify({"st":"error","msg":"ต้องเป็น admin ขึ้นไป (Bearer token)"}),403
 b=request.get_json(force=True,silent=True) or {}; mid=str(b.get("id","")).strip() or ("model_"+uuid.uuid4().hex[:12]); kind=str(b.get("kind","image")).lower().strip()
 if kind not in ("image","video","animation"): return jsonify({"st":"error","msg":"kind ต้องเป็น image/video/animation"}),400
 db=_creator_db(); now=time.time(); db.execute("INSERT INTO creator_models(id,name,kind,provider,model,endpoint,enabled,meta_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,kind=excluded.kind,provider=excluded.provider,model=excluded.model,endpoint=excluded.endpoint,enabled=excluded.enabled,meta_json=excluded.meta_json,updated_at=excluded.updated_at",(mid,str(b.get("name",mid)),kind,str(b.get("provider","custom")),str(b.get("model","")),str(b.get("endpoint","")),1,json.dumps(b.get("meta") or {},ensure_ascii=False),now,now)); db.commit(); db.close(); return jsonify({"st":"ok","model_id":mid,"models":_creator_models()})
@app.route('/api/creator/models/<model_id>',methods=['DELETE'])
def api_creator_model_delete(model_id):
 _u,_r=_staff_from_request()
 if _u is None or _r is None or _r<STAFF_RANKS["admin"]: return jsonify({"st":"error","msg":"ต้องเป็น admin ขึ้นไป (Bearer token)"}),403
 db=_creator_db(); db.execute("UPDATE creator_models SET enabled=0,updated_at=? WHERE id=?",(time.time(),model_id)); db.commit(); db.close(); return jsonify({"st":"ok"})
@app.route('/api/creator/select',methods=['POST'])
def api_creator_select():
 _u,_r=_staff_from_request()
 if _u is None or _r is None or _r<STAFF_RANKS["admin"]: return jsonify({"st":"error","msg":"ต้องเป็น admin ขึ้นไป (Bearer token)"}),403
 b=request.get_json(force=True,silent=True) or {}; clean={}
 for kind in ("image","video","animation"):
  mid=str((b.get("selected") or {}).get(kind,"")).strip()
  if mid and _creator_find_model(mid,kind): clean[kind]=mid
 _creator_pref_set("selected_models",clean); return jsonify({"st":"ok","selected":clean})
@app.route('/api/creator/generate/<kind>',methods=['POST'])
@require_auth
def api_creator_generate(kind):
 try:
  job=_creator_submit(kind,request.get_json(force=True,silent=True) or {}); _creator_start_worker(); return jsonify({"st":"ok","job":job}),202
 except Exception as e:return jsonify({"st":"error","msg":str(e)}),400
@app.route('/api/creator/jobs/<job_id>')
def api_creator_job(job_id):
 with CREATOR_LOCK: job=CREATOR_JOBS.get(job_id)
 if job:return jsonify({"st":"ok","job":job})
 db=_creator_db(); r=db.execute("SELECT * FROM creator_jobs WHERE id=?",(job_id,)).fetchone(); db.close()
 if not r:return jsonify({"st":"error","msg":"ไม่พบงาน"}),404
 x=dict(r)
 try:x["result"]=json.loads(x.pop("result_json") or "{}")
 except Exception:x["result"]={}
 return jsonify({"st":"ok","job":x})
CREATOR_STUDIO_HTML=r'''<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VMAX Creator Studio</title><style>body{margin:0;background:#080b12;color:#edf4ff;font-family:system-ui,sans-serif}.bar{position:sticky;top:0;z-index:50;background:#0d1420;border-bottom:1px solid #263650;padding:12px 16px;display:flex;gap:8px;align-items:center}.bar b{margin-right:auto}.tab,.btn{border:1px solid #36557f;background:#162a45;color:#fff;padding:9px 12px;border-radius:9px;cursor:pointer}.tabs{display:flex;gap:6px}.wrap{max-width:1180px;margin:auto;padding:16px}.panel{background:#101827;border:1px solid #263650;border-radius:14px;padding:16px;margin-bottom:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:800px){.grid{grid-template-columns:1fr}}label{display:block;font-size:13px;color:#a9bad3;margin:7px 0 4px}select,input,textarea{width:100%;box-sizing:border-box;background:#080e18;color:#fff;border:1px solid #344a68;border-radius:9px;padding:10px}textarea{min-height:120px}.modelbox{display:flex;gap:8px}.modelbox select{flex:1}.muted{color:#93a5bd;font-size:13px}.result{max-height:260px;overflow:auto;background:#080e18;padding:10px;border-radius:9px;white-space:pre-wrap}.hidden{display:none}.floating{position:fixed;z-index:100;right:18px;bottom:18px;width:min(560px,calc(100vw - 36px));box-shadow:0 20px 70px #0008}.section-title{display:flex;align-items:center;gap:8px}.section-title h2{margin:0}.pill{font-size:12px;padding:4px 8px;border:1px solid #36557f;border-radius:999px}.spacer{margin-left:auto}</style></head><body><div class="bar"><b>🎬 VMAX Creator Studio</b><div class="tabs" id="tabs"></div><button class="btn" onclick="toggleStudio()">พับ/เปิด</button><button class="btn" onclick="openModelManager()">⚙ Models</button></div><main class="wrap" id="studio"></main><div id="floatingRoot"></div><script>
const K='vmax_creator_ui_v1';let state=JSON.parse(localStorage.getItem(K)||'null')||{closed:[],floating:{},collapsed:{}};let models=[],selected={};const kinds=[['image','🖼️ Image'],['video','🎥 Video'],['animation','✨ Animation']];function save(){localStorage.setItem(K,JSON.stringify(state))}function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}async function load(){let d=await (await fetch('/api/creator/models',{cache:'no-store'})).json();models=d.models||[];selected=d.selected||{};renderTabs();renderStudio()}function renderTabs(){tabs.innerHTML=kinds.filter(k=>!state.closed.includes(k[0])).map(k=>`<button class="tab" draggable="true" ondragstart="dragTab(event,'${k[0]}')" onclick="showKind('${k[0]}')">${k[1]}</button>`).join('')+'<button class="tab" onclick="reopenTab()">＋</button>'}function dragTab(e,k){e.dataTransfer.setData('text/plain',k)}function showKind(k){document.getElementById('panel_'+k)?.scrollIntoView({behavior:'smooth'})}function collapse(k){state.collapsed[k]=!state.collapsed[k];document.getElementById('body_'+k)?.classList.toggle('hidden',state.collapsed[k]);save()}function floatTab(k){let src=document.getElementById('panel_'+k);if(!src)return;let c=src.cloneNode(true);c.id='float_'+k;c.classList.add('floating');c.querySelector('.close').onclick=()=>{c.remove();state.floating[k]=false;save()};floatingRoot.appendChild(c);src.classList.add('hidden');state.floating[k]=true;save()}function toggleFloat(k){if(state.floating[k]){document.getElementById('float_'+k)?.remove();state.floating[k]=false;document.getElementById('panel_'+k)?.classList.remove('hidden')}else floatTab(k);save()}function closeTab(k){state.closed=[...new Set([...state.closed,k])];document.getElementById('panel_'+k)?.remove();document.getElementById('float_'+k)?.remove();state.floating[k]=false;save();renderTabs()}function reopenTab(){let k=state.closed.pop();if(k){save();renderTabs();renderStudio()}}function modelSelect(k){let a=models.filter(m=>m.kind===k),cur=selected[k]||'';return `<div class="modelbox"><select id="model_${k}">${a.map(m=>`<option value="${esc(m.id)}" ${m.id===cur?'selected':''}>${esc(m.name)} — ${esc(m.model||m.provider)}</option>`).join('')}</select><button class="btn" onclick="saveModel('${k}')">เลือก</button></div>`}function panel(k,title,icon){if(state.closed.includes(k))return '';return `<section class="panel" id="panel_${k}"><div class="section-title"><span>${icon}</span><h2>${title}</h2><span class="pill">${k}</span><span class="spacer"></span><button class="btn" onclick="toggleFloat('${k}')">↗ Tab</button><button class="btn" onclick="collapse('${k}')">พับ</button><button class="btn close" onclick="closeTab('${k}')">×</button></div><div id="body_${k}" class="${state.collapsed[k]?'hidden':''}"><label>Model (ต้องเลือกก่อนสร้าง)</label>${modelSelect(k)}<label>Prompt</label><textarea id="prompt_${k}" placeholder="บอกสิ่งที่ต้องการสร้าง..."></textarea><div class="grid"><div><label>Options JSON</label><input id="opt_${k}" value="{}"></div><div><label>Input JSON / reference</label><input id="in_${k}" value="{}"></div></div><p><button class="btn" onclick="generate('${k}')">🚀 สร้าง</button></p><div id="status_${k}" class="muted"></div><div id="result_${k}" class="result hidden"></div></div></section>`}function renderStudio(){studio.innerHTML=kinds.map(k=>panel(k[0],k[1].split(' ')[1],k[1].split(' ')[0])).join('')}async function saveModel(k){let id=document.getElementById('model_'+k)?.value;if(!id)return;selected[k]=id;await fetch('/api/creator/select',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({selected})});alert('บันทึก model แล้ว')}async function generate(k){let id=document.getElementById('model_'+k).value,p=document.getElementById('prompt_'+k).value.trim();if(!id)return alert('เลือก model ก่อน');if(!p)return alert('ใส่ prompt ก่อน');let j=s=>{try{return JSON.parse(document.getElementById(s).value||'{}')}catch(e){throw Error('JSON ไม่ถูกต้อง')}};let r=await fetch('/api/creator/generate/'+k,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model_id:id,prompt:p,input:j('in_'+k),options:j('opt_'+k)})}),d=await r.json();if(d.st!=='ok')return status(k,'❌ '+d.msg);status(k,'⏳ '+d.job.id+' กำลังทำงาน...');poll(k,d.job.id)}function status(k,t){document.getElementById('status_'+k).textContent=t}async function poll(k,id){let d=await (await fetch('/api/creator/jobs/'+id)).json(),j=d.job;if(j.status==='queued'||j.status==='running')return setTimeout(()=>poll(k,id),1200);status(k,(j.status==='completed'?'✅ เสร็จแล้ว':'❌ ล้มเหลว')+' '+(j.error||''));let o=document.getElementById('result_'+k);o.classList.remove('hidden');o.textContent=JSON.stringify(j.result||{},null,2)}function toggleStudio(){studio.classList.toggle('hidden')}function openModelManager(){let x=prompt('เพิ่ม/อัปเดต model เป็น JSON เช่น {"id":"my-video","name":"My Video","kind":"video","provider":"custom","model":"model-name","endpoint":"http://127.0.0.1:9000/generate"}');if(!x)return;let b;try{b=JSON.parse(x)}catch(e){return alert('JSON ไม่ถูกต้อง')};fetch('/api/creator/models',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}).then(load)}load();</script></body></html>'''
_creator_init(); _creator_start_worker()

