# =====================================================================
# [ AUTH GATE ] ต้องกรอกรหัสผ่าน (PIN) ให้ถูกก่อนถึงจะรันเกมได้
# เก็บเป็น SHA-256 hash เท่านั้น ไม่มีการเก็บรหัสผ่านจริงไว้ในไฟล์นี้
# เปลี่ยนรหัสผ่านได้เองโดยรันคำสั่งนี้แล้วเอา hash ที่ได้มาแทนค่า _OWNER_PIN_HASH:
#   python3 -c "import hashlib,getpass; print(hashlib.sha256(getpass.getpass().encode()).hexdigest())"
# =====================================================================
import hashlib as _v_auth_hashlib
try:
    import getpass as _v_auth_getpass
except ImportError:
    _v_auth_getpass = None

_OWNER_PIN_HASH = "eb8512dc4756a61db8e6c3002a4b7b8a9243b112b8395902bc73f7283d448617"
_OWNER_PIN_MAX_TRIES = 3


def _vmax_verify_owner_pin(pin) -> bool:
    """[SEC-AUDIT] ตรวจ PIN เจ้าของ: ถ้าตั้ง env VMAX_OWNER_PIN_HASH (รูปแบบ scrypt$n$r$p$salt$hash — สร้างด้วย
    `python <ไฟล์> --make-pin-hash`) จะใช้ค่านั้นเท่านั้น ไม่งั้น fallback เป็น SHA-256 เดิมในซอร์สโค้ด (ไม่มี salt
    และเร็วมาก ใครได้ไฟล์นี้ไปเดา PIN สั้นๆ แบบออฟไลน์ได้ในไม่กี่วินาที จึงควรตั้ง env)"""
    import hmac as _pin_hmac
    pin = str(pin or "")
    env_hash = os.environ.get("VMAX_OWNER_PIN_HASH", "").strip()
    if env_hash:
        try:
            scheme, n, r, p, salt_hex, hash_hex = env_hash.split("$")
            if scheme != "scrypt":
                return False
            want = bytes.fromhex(hash_hex)
            got = _v_auth_hashlib.scrypt(pin.encode("utf-8"), salt=bytes.fromhex(salt_hex), n=int(n), r=int(r), p=int(p),
                                         dklen=len(want), maxmem=256 * 1024 * 1024)
            return _pin_hmac.compare_digest(got, want)
        except Exception:
            return False
    return _pin_hmac.compare_digest(_v_auth_hashlib.sha256(pin.encode("utf-8")).hexdigest(), _OWNER_PIN_HASH)


def _vmax_make_pin_hash(pin: str) -> str:
    salt = os.urandom(16)
    n, r, p = 2 ** 15, 8, 1
    dk = _v_auth_hashlib.scrypt(pin.encode("utf-8"), salt=salt, n=n, r=r, p=p, dklen=32, maxmem=256 * 1024 * 1024)
    return f"scrypt${n}${r}${p}${salt.hex()}${dk.hex()}"


if "--make-pin-hash" in sys.argv:
    import getpass as _pin_getpass
    _a = _pin_getpass.getpass("PIN ใหม่: ")
    if len(_a) < 6 or _a != _pin_getpass.getpass("ยืนยัน PIN: "):
        print("PIN ต้องยาวอย่างน้อย 6 ตัวและตรงกันทั้งสองครั้ง")
        sys.exit(1)
    print("ตั้งค่านี้เป็น env ก่อนรันเซิร์ฟเวอร์ (อย่าเก็บลงในไฟล์ที่แชร์):")
    print("  export VMAX_OWNER_PIN_HASH='" + _vmax_make_pin_hash(_a) + "'")
    sys.exit(0)


def _vmax_owner_auth_gate() -> bool:
    """ขอรหัสผ่านเจ้าของไฟล์ก่อนอนุญาตให้รันเกม คืนค่า True ถ้าผ่าน"""
    print("🔒 VMAX — กรุณากรอกรหัสผ่านเจ้าของไฟล์เพื่อเริ่มใช้งาน")
    for attempt in range(1, _OWNER_PIN_MAX_TRIES + 1):
        try:
            if _v_auth_getpass is not None:
                pin = _v_auth_getpass.getpass("PIN: ")
            else:
                pin = input("PIN: ")
        except (EOFError, KeyboardInterrupt):
            print("\n❌ ยกเลิกการเข้าสู่ระบบ")
            return False
        if _vmax_verify_owner_pin(pin):
            print("✅ ยืนยันตัวตนสำเร็จ กำลังเริ่มเกม...")
            return True
        remaining = _OWNER_PIN_MAX_TRIES - attempt
        if remaining > 0:
            print(f"❌ รหัสผ่านไม่ถูกต้อง (เหลืออีก {remaining} ครั้ง)")
    print("❌ กรอกรหัสผ่านผิดครบจำนวนครั้งที่กำหนด ปิดโปรแกรม")
    return False


# ==========================================
# [ 2K9. VMAX Play Hub — แท็บ "คุณ" แบบ Google Play (แต้มสะสม / ลีกความท้าทาย / สถิติเล่นต่อเนื่อง / สถิติแข่งขัน) ]
# ต่อเข้ากับ Launcher (LAUNCHER_CATALOG) ที่ใช้โหลดเกม: เกมที่ยังไม่ได้ติดตั้งจะกด "โหลดก่อนเข้าลีก"
# ได้ในหน้าเดียว (เรียก launcher_install เดิม) / พอลงเสร็จก็กด "ไปที่ลีก" ได้เลย
# - แต้ม Play Points + รางวัลรายสัปดาห์ตามระดับ (บรอนซ์/เงิน/ทอง/แพลทินัม) รับได้ครั้งเดียวต่อสัปดาห์
# - ลีก (ความท้าทาย): นับถอยหลังเริ่มลีก (วัน:ชม.:นาที:วินาที) / จำนวนผู้เข้าร่วม / กด "เข้าร่วมลีก"
# - ทำสถิติเล่นต่อเนื่อง: streak วันเล่นติดต่อกัน + นาทีเล่นสะสมต่อเกม
# - สถิติการแข่งขัน: อันดับ/คะแนนในลีกของแต่ละเกม
# ไม่แก้โค้ดเดิม — ต่อผ่าน _vmax_attach_playhub_module() ก่อน sio.run(...) ใน _vmax_main()
# แสดงผลหลักอยู่ที่แท็บ "คุณ" ในหน้า /store (render_store_page, [6j3]) — /widgets/playhub เป็นหน้าเดี่ยวสำรองไว้ฝังที่อื่น
# Endpoint: /widgets/playhub  /api/playhub/{overview,weekly/claim,league/list,league/join,league/create,league/leaderboard,session,redeem}
# ==========================================
import datetime as _ph_dt
PLAYHUB_TIERS = [   # (ชื่อระดับ, แต้มสะสมขั้นต่ำ, แต้มรางวัลรายสัปดาห์สูงสุด)
    ("bronze", 0, 10000), ("silver", 50000, 25000), ("gold", 200000, 60000), ("platinum", 1000000, 150000),
]
PLAYHUB_POINTS_PER_CREDIT = 10      # แลกแต้ม -> เครดิตในเกม: 10 แต้ม = 1 เครดิต (ปรับได้)
PLAYHUB_POINTS_PER_MINUTE = 5       # เล่นจริงได้แต้มต่อนาที
PLAYHUB_MAX_SESSION_MIN   = 240     # กันส่งนาทีเกินจริงต่อครั้ง
PLAYHUB_STATE  = {}                 # uid -> {points, lifetime_points, last_weekly, streak, last_play_day, games:{gid:{minutes,sessions,best_score}}, joined:[league_id]}
PLAYHUB_LEAGUES = {}                # league_id -> {id,game_id,title,prize_points,starts_at,ends_at,members:{uid:score}}
PLAYHUB_LOCK = threading.Lock()

def _playhub_state(uid: str) -> dict:
    return PLAYHUB_STATE.setdefault(uid, {"points": 0, "lifetime_points": 0, "last_weekly": "", "streak": 0,
                                          "last_play_day": "", "games": {}, "joined": []})

def _playhub_tier(lifetime: int) -> dict:
    cur = PLAYHUB_TIERS[0]
    for t in PLAYHUB_TIERS:
        if lifetime >= t[1]: cur = t
    nxt = next((t for t in PLAYHUB_TIERS if t[1] > lifetime), None)
    return {"tier": cur[0], "weekly_max": cur[2], "next_tier": nxt[0] if nxt else None,
            "next_at": nxt[1] if nxt else None}

def _playhub_week_key(ts: float | None = None) -> str:
    y, w, _ = _ph_dt.datetime.fromtimestamp(ts or time.time()).isocalendar()
    return f"{y}-W{w:02d}"

def _playhub_day_key(ts: float | None = None) -> str:
    return _ph_dt.datetime.fromtimestamp(ts or time.time()).strftime("%Y-%m-%d")

def _playhub_add_points(uid: str, pts: int):
    st = _playhub_state(uid)
    st["points"] += int(pts)
    st["lifetime_points"] += max(0, int(pts))

def _playhub_league_create(game_id: str, title: str, prize_points: int, starts_in_sec: int, duration_sec: int = 86400 * 3) -> dict:
    lid = "lg_" + uuid.uuid4().hex[:8]
    now = time.time()
    lg = {"id": lid, "game_id": game_id, "title": title, "prize_points": int(prize_points),
          "starts_at": now + max(0, int(starts_in_sec)), "ends_at": now + max(0, int(starts_in_sec)) + int(duration_sec),
          "members": {}}
    PLAYHUB_LEAGUES[lid] = lg
    return lg

def _playhub_seed():
    """สร้างลีกตัวอย่างจากเกมใน LAUNCHER_CATALOG (ครั้งแรกที่มีคนเปิดหน้า) — ลีกจริงสร้างเพิ่มได้ที่ /api/playhub/league/create"""
    if PLAYHUB_LEAGUES: return
    for gid, g in list(LAUNCHER_CATALOG.items())[:3]:
        _playhub_league_create(gid, f"ลีก {g.get('name', gid)}", 50000, 16 * 3600 - 69)

def _playhub_league_view(lg: dict, uid: str) -> dict:
    now = time.time()
    left = max(0, int(lg["starts_at"] - now))
    d, rem = divmod(left, 86400); h, rem = divmod(rem, 3600); m, s = divmod(rem, 60)
    status = "upcoming" if now < lg["starts_at"] else ("live" if now < lg["ends_at"] else "ended")
    g = LAUNCHER_CATALOG.get(lg["game_id"], {})
    return {"id": lg["id"], "game_id": lg["game_id"], "game_name": g.get("name", lg["game_id"]),
            "installed": bool(g.get("installed")), "title": lg["title"], "prize_points": lg["prize_points"],
            "participants": len(lg["members"]), "joined": uid in lg["members"], "status": status,
            "starts_in_sec": left, "countdown": {"d": d, "h": h, "m": m, "s": s},
            "starts_at": lg["starts_at"], "ends_at": lg["ends_at"]}

def _playhub_rank(lg: dict, uid: str):
    ranked = sorted(lg["members"].items(), key=lambda kv: -kv[1])
    for i, (u, sc) in enumerate(ranked, 1):
        if u == uid: return i, sc
    return None, 0

def _vmax_attach_playhub_module():
    """เรียกก่อน sio.run(...) ใน _vmax_main() ตอน app/require_auth_toggleable/LAUNCHER_CATALOG/WALLET/P/VMAX_MODULES ถูกประกาศครบแล้ว"""
    g = globals()
    if g.get("_PLAYHUB_ATTACHED"): return
    g["_PLAYHUB_ATTACHED"] = True

    def _uid():
        u = str(getattr(request, "vmax_uid", "") or "")
        if not u:
            body = request.get_json(silent=True) or {}
            u = str(body.get("uid") or request.args.get("uid") or "")
        if not u:
            try: u = str(P["uid"])
            except Exception: u = "guest"
        return u

    @app.route("/api/playhub/overview")
    def api_playhub_overview():
        uid = _uid()
        with PLAYHUB_LOCK:
            _playhub_seed()
            st = _playhub_state(uid)
            tier = _playhub_tier(st["lifetime_points"])
            claimed = st["last_weekly"] == _playhub_week_key()
            # streak หลุดถ้าไม่ได้เล่นเมื่อวาน/วันนี้
            today, yday = _playhub_day_key(), _playhub_day_key(time.time() - 86400)
            streak = st["streak"] if st["last_play_day"] in (today, yday) else 0
            games = [{"game_id": gid, "name": LAUNCHER_CATALOG.get(gid, {}).get("name", gid),
                      "minutes": v["minutes"], "sessions": v["sessions"], "best_score": v["best_score"],
                      "installed": bool(LAUNCHER_CATALOG.get(gid, {}).get("installed"))}
                     for gid, v in st["games"].items()]
            games.sort(key=lambda x: -x["minutes"])
            comp = []
            for lg in PLAYHUB_LEAGUES.values():
                if uid in lg["members"]:
                    rank, score = _playhub_rank(lg, uid)
                    comp.append({"league_id": lg["id"], "title": lg["title"], "game_id": lg["game_id"],
                                 "rank": rank, "score": score, "members": len(lg["members"])})
            leagues = [_playhub_league_view(lg, uid) for lg in PLAYHUB_LEAGUES.values()]
        return jsonify({"st": "ok", "uid": uid, "points": st["points"], "lifetime_points": st["lifetime_points"],
                        "tier": tier, "weekly": {"claimed": claimed, "week": _playhub_week_key(),
                                                  "amount": tier["weekly_max"]},
                        "streak_days": streak, "play_stats": games, "competition_stats": comp, "leagues": leagues,
                        "points_per_credit": PLAYHUB_POINTS_PER_CREDIT})

    @app.route("/api/playhub/weekly/claim", methods=["POST"])
    @require_auth_toggleable
    def api_playhub_weekly_claim():
        uid = _uid()
        with PLAYHUB_LOCK:
            st = _playhub_state(uid)
            wk = _playhub_week_key()
            if st["last_weekly"] == wk:
                return jsonify({"st": "error", "msg": "รับรางวัลสัปดาห์นี้ไปแล้ว"}), 409
            tier = _playhub_tier(st["lifetime_points"])
            st["last_weekly"] = wk
            _playhub_add_points(uid, tier["weekly_max"])
            pts = st["points"]
        return jsonify({"st": "ok", "tier": tier["tier"], "gained": tier["weekly_max"], "points": pts})

    @app.route("/api/playhub/league/list")
    def api_playhub_league_list():
        uid = _uid()
        with PLAYHUB_LOCK:
            _playhub_seed()
            return jsonify({"st": "ok", "leagues": [_playhub_league_view(lg, uid) for lg in PLAYHUB_LEAGUES.values()]})

    @app.route("/api/playhub/league/join", methods=["POST"])
    @require_auth_toggleable
    def api_playhub_league_join():
        uid = _uid()
        body = request.get_json(silent=True) or {}
        with PLAYHUB_LOCK:
            lg = PLAYHUB_LEAGUES.get(str(body.get("league_id", "")))
            if not lg: return jsonify({"st": "error", "msg": "ไม่พบลีกนี้"}), 404
            if time.time() >= lg["ends_at"]: return jsonify({"st": "error", "msg": "ลีกนี้จบแล้ว"}), 400
            lg["members"].setdefault(uid, 0)
            st = _playhub_state(uid)
            if lg["id"] not in st["joined"]: st["joined"].append(lg["id"])
            view = _playhub_league_view(lg, uid)
        return jsonify({"st": "ok", "league": view})

    @app.route("/api/playhub/league/create", methods=["POST"])
    @require_staff_rank("admin")
    def api_playhub_league_create():
        """body: {game_id, title, prize_points, starts_in_sec, duration_sec?} (เฉพาะแอดมิน)"""
        b = request.get_json(silent=True) or {}
        gid = str(b.get("game_id", ""))
        if gid not in LAUNCHER_CATALOG: return jsonify({"st": "error", "msg": "game_id ไม่อยู่ใน LAUNCHER_CATALOG"}), 400
        with PLAYHUB_LOCK:
            lg = _playhub_league_create(gid, str(b.get("title") or f"ลีก {gid}")[:80], int(b.get("prize_points", 50000)),
                                         int(b.get("starts_in_sec", 3600)), int(b.get("duration_sec", 86400 * 3)))
        return jsonify({"st": "ok", "league": _playhub_league_view(lg, _uid())})

    @app.route("/api/playhub/league/leaderboard")
    def api_playhub_leaderboard():
        lg = PLAYHUB_LEAGUES.get(str(request.args.get("league_id", "")))
        if not lg: return jsonify({"st": "error", "msg": "ไม่พบลีกนี้"}), 404
        top = sorted(lg["members"].items(), key=lambda kv: -kv[1])[:int(request.args.get("limit", 20))]
        return jsonify({"st": "ok", "league_id": lg["id"], "board": [{"rank": i, "uid": u, "score": s} for i, (u, s) in enumerate(top, 1)]})

    @app.route("/api/playhub/session", methods=["POST"])
    @require_auth_toggleable
    def api_playhub_session():
        """เกมรายงานรอบเล่นจบ: body {game_id, minutes, score?} -> ได้แต้ม + อัปเดต streak + คะแนนลีกที่กำลังแข่ง"""
        uid = _uid()
        b = request.get_json(silent=True) or {}
        gid = str(b.get("game_id", ""))
        gcat = LAUNCHER_CATALOG.get(gid)
        if not gcat: return jsonify({"st": "error", "msg": "ไม่พบเกมนี้ใน catalog"}), 404
        if not gcat.get("installed"): return jsonify({"st": "error", "msg": "ยังไม่ได้ติดตั้งเกมนี้"}), 400
        try:
            minutes = max(0, min(PLAYHUB_MAX_SESSION_MIN, int(b.get("minutes", 0))))
            score = max(0, int(b.get("score", 0)))
        except (TypeError, ValueError):
            return jsonify({"st": "error", "msg": "minutes/score ต้องเป็นตัวเลข"}), 400
        now = time.time()
        with PLAYHUB_LOCK:
            st = _playhub_state(uid)
            today, yday = _playhub_day_key(now), _playhub_day_key(now - 86400)
            if st["last_play_day"] != today:
                st["streak"] = st["streak"] + 1 if st["last_play_day"] == yday else 1
                st["last_play_day"] = today
            gs = st["games"].setdefault(gid, {"minutes": 0, "sessions": 0, "best_score": 0})
            gs["minutes"] += minutes; gs["sessions"] += 1; gs["best_score"] = max(gs["best_score"], score)
            gained = minutes * PLAYHUB_POINTS_PER_MINUTE
            _playhub_add_points(uid, gained)
            for lid in st["joined"]:
                lg = PLAYHUB_LEAGUES.get(lid)
                if lg and lg["game_id"] == gid and lg["starts_at"] <= now < lg["ends_at"]:
                    lg["members"][uid] = max(lg["members"].get(uid, 0), score)
            res = {"st": "ok", "gained_points": gained, "points": st["points"], "streak_days": st["streak"]}
        return jsonify(res)

    @app.route("/api/playhub/redeem", methods=["POST"])
    @require_auth_toggleable
    def api_playhub_redeem():
        """body: {points} -> แลกแต้มเป็นเครดิตในเกม (PLAYHUB_POINTS_PER_CREDIT แต้ม = 1 เครดิต)"""
        uid = _uid()
        b = request.get_json(silent=True) or {}
        try: pts = int(b.get("points", 0))
        except (TypeError, ValueError): pts = 0
        credits, pts = divmod(pts, PLAYHUB_POINTS_PER_CREDIT)[0], (pts // PLAYHUB_POINTS_PER_CREDIT) * PLAYHUB_POINTS_PER_CREDIT
        if credits <= 0: return jsonify({"st": "error", "msg": f"ขั้นต่ำ {PLAYHUB_POINTS_PER_CREDIT} แต้ม"}), 400
        with PLAYHUB_LOCK:
            st = _playhub_state(uid)
            if st["points"] < pts: return jsonify({"st": "error", "msg": "แต้มไม่พอ", "have": st["points"]}), 400
            st["points"] -= pts
        wallet_credit(credits, f"playhub_redeem:{pts}")
        try: P["credits"] = WALLET["balance"]
        except Exception: pass
        return jsonify({"st": "ok", "redeemed_points": pts, "credits_added": credits, "points": st["points"]})

    @app.route("/widgets/playhub")
    def widget_playhub():
        return _PLAYHUB_WIDGET_HTML

    if isinstance(g.get("VMAX_MODULES"), dict):
        g["VMAX_MODULES"]["playhub"] = {
            "desc": "Play Hub แบบแท็บ 'คุณ' ของ Google Play: แต้มสะสม+รางวัลรายสัปดาห์ตามระดับ, ลีกความท้าทายพร้อมนับถอยหลัง, สถิติเล่นต่อเนื่อง, สถิติแข่งขัน — ต่อกับ Launcher โหลดเกมได้ในหน้าเดียว",
            "routes": ["/widgets/playhub", "/api/playhub/overview", "/api/playhub/weekly/claim", "/api/playhub/league/list",
                       "/api/playhub/league/join", "/api/playhub/league/create", "/api/playhub/league/leaderboard",
                       "/api/playhub/session", "/api/playhub/redeem"],
        }
    print("[PlayHub] ต่อโมดูล Play Hub เสร็จ — /widgets/playhub /api/playhub/*")

