        _pl.add_argument("--dataset", required=True, help=f"path ไปที่โฟลเดอร์ภาพตัวละคร (อย่างน้อย {LORA_MIN_TRAINING_IMAGES} ภาพ แนะนำ 10-30 ภาพคนละมุม/ท่า)")
        _pl.add_argument("--epochs", type=int, default=100)
        _args_lora = _pl.parse_args()
        train_character_lora(_args_lora.character_name, _args_lora.dataset, epochs=_args_lora.epochs)
