# ==========================================
# VMAX SURVIVAL — ONE-TIME WEAPONS + FOOD/FLOWERS
# Uses the existing inventory / interaction / mobile-control layer.
# ==========================================
SURVIVAL_EXTRA_ITEMS = {
    "nail_gun": {"name": "ปืนตะปู", "type": "weapon", "ammo_item": "nail",
                 "damage": 22, "range": 520, "stack": 1},
    "nail": {"name": "ตะปู", "type": "ammo", "stack": 30},
    "pen": {"name": "ปากกา", "type": "one_time_weapon", "damage": 45,
            "break_after_use": True, "stack": 1},
    "snack": {"name": "ขนม", "type": "food", "hunger": 16, "stamina": 7, "stack": 5},
    "flower": {"name": "ดอกไม้", "type": "material", "stack": 10},
}

def survival_extra_item_catalog():
    return {k: dict(v) for k, v in SURVIVAL_EXTRA_ITEMS.items()}

def survival_add_item(inventory, item_id, amount=1):
    if amount <= 0 or item_id not in SURVIVAL_EXTRA_ITEMS or not isinstance(inventory, dict):
        return False
    inventory[item_id] = int(inventory.get(item_id, 0)) + int(amount)
    return True

def survival_use_pen(inventory, monster):
    if not isinstance(inventory, dict) or inventory.get("pen", 0) <= 0:
        return {"ok": False, "reason": "ไม่มีปากกา"}
    if not isinstance(monster, dict) or monster.get("hp", 0) <= 0:
        return {"ok": False, "reason": "ไม่พบ Monster"}
    damage = SURVIVAL_EXTRA_ITEMS["pen"]["damage"]
    monster["hp"] = max(0, float(monster.get("hp", 0)) - damage)
    inventory["pen"] -= 1
    if inventory["pen"] <= 0:
        inventory.pop("pen", None)
    return {"ok": True, "damage": damage, "monster_defeated": monster["hp"] <= 0,
            "broken": True, "message": "🖊️ ปากกาแทง Monster แล้วแตก ใช้ได้ครั้งเดียว"}

def survival_fire_nail_gun(inventory, monster):
    if not isinstance(inventory, dict) or inventory.get("nail_gun", 0) <= 0:
        return {"ok": False, "reason": "ไม่มีปืนตะปู"}
    if inventory.get("nail", 0) <= 0:
        return {"ok": False, "reason": "ไม่มีตะปู"}
    if not isinstance(monster, dict) or monster.get("hp", 0) <= 0:
        return {"ok": False, "reason": "ไม่พบ Monster"}
    inventory["nail"] -= 1
    damage = SURVIVAL_EXTRA_ITEMS["nail_gun"]["damage"]
    monster["hp"] = max(0, float(monster.get("hp", 0)) - damage)
    return {"ok": True, "damage": damage, "ammo_left": inventory.get("nail", 0),
            "monster_defeated": monster["hp"] <= 0}

def survival_consume_snack(inventory, player_stats):
    if not isinstance(inventory, dict) or inventory.get("snack", 0) <= 0:
        return {"ok": False, "reason": "ไม่มีขนม"}
    inventory["snack"] -= 1
    if inventory["snack"] <= 0:
        inventory.pop("snack", None)
    if isinstance(player_stats, dict):
        player_stats["hunger"] = min(100, float(player_stats.get("hunger", 0)) + 16)
        player_stats["stamina"] = min(100, float(player_stats.get("stamina", 0)) + 7)
    return {"ok": True, "message": "🍪 กินขนมแล้ว"}

def survival_roll_floor_items(rng=None):
    import random
    r = rng or random
    item, lo, hi = r.choice([
        ("nail", 1, 4), ("snack", 1, 2), ("flower", 1, 3),
        ("pen", 1, 1), ("nail_gun", 1, 1)
    ])
    return item, r.randint(lo, hi)


