# VMAX SURVIVAL — STEALTH / NOISE / CHOCOLATE
# Reuses existing movement, interaction, inventory and monster systems.
# ==========================================
SURVIVAL_STEALTH = {
    "walk_speed_multiplier": 1.0,
    "quiet_walk_speed_multiplier": 0.58,
    "quiet_noise_multiplier": 0.32,
    "normal_noise_multiplier": 1.0,
    "heavy_impact_noise_multiplier": 1.8,
    "rear_stealth_angle_deg": 75,
    "rear_stealth_distance": 115,
    "chocolate_sleep_delay": 180.0,  # seconds
}


# ===== CONNECTED EXTRACTION SHOOTER SYSTEM =====
try:
    SURVIVAL_EQUIPMENT_STATE.setdefault("glasses", {
        "equipped": False,
        "durability": 100,
        "flash_resistance": 0.70,
        "stun_resistance": 0.50
    })
except Exception:
    pass

def survival_has_flash_glasses(player=None):
    try:
        return SURVIVAL_EQUIPMENT_STATE["glasses"]["equipped"]
    except Exception:
        return False

def survival_apply_flash_effect(player, flash_duration, stun_duration):
    if survival_has_flash_glasses(player):
        flash_duration *= 0.30
        stun_duration *= 0.50
    return flash_duration, stun_duration

def survival_apply_stun(player, force_value=25):
    if not isinstance(player, dict):
        return False
    player.setdefault("balance", 100.0)
    player.setdefault("stunned", False)
    player.setdefault("recovery_meter", 0.0)
    player["balance"] -= float(force_value)
    if player["balance"] <= 0:
        player["stunned"] = True
        player["recovery_meter"] = 0.0
    return player["stunned"]

def survival_recovery_input(player, key_name="W"):
    if not isinstance(player, dict):
        return False
    if not player.get("stunned"):
        return False
    player["recovery_meter"] = player.get("recovery_meter", 0.0) + 5.0
    if player["recovery_meter"] >= 100.0:
        player["stunned"] = False
        player["balance"] = 50.0
        return True
    return False


def survival_set_quiet_walk(player, enabled=True):
    if not isinstance(player, dict):
        return False
    player["quiet_walk"] = bool(enabled)
    player["move_speed_multiplier"] = (
        SURVIVAL_STEALTH["quiet_walk_speed_multiplier"] if enabled else
        SURVIVAL_STEALTH["walk_speed_multiplier"]
    )
    return True

def survival_make_noise(player, amount, kind="movement"):
    """Record noise so monsters can react to loud actions."""
    if not isinstance(player, dict):
        return 0.0
    multiplier = SURVIVAL_STEALTH["normal_noise_multiplier"]
    if player.get("quiet_walk") and kind == "movement":
        multiplier = SURVIVAL_STEALTH["quiet_noise_multiplier"]
    if kind in ("heavy_impact", "slam", "fall"):
        multiplier = SURVIVAL_STEALTH["heavy_impact_noise_multiplier"]
    noise = max(0.0, float(amount) * multiplier)
    player["last_noise"] = noise
    player["last_noise_kind"] = kind
    return noise

def survival_can_stealth_kill(player, monster):
    """True when the player is close enough and behind a monster."""
    if not isinstance(player, dict) or not isinstance(monster, dict):
        return False
    if monster.get("hp", 0) <= 0:
        return False
    dx = float(player.get("x", 0)) - float(monster.get("x", 0))
    dy = float(player.get("y", 0)) - float(monster.get("y", 0))
    dist = (dx * dx + dy * dy) ** 0.5
    if dist > SURVIVAL_STEALTH["rear_stealth_distance"]:
        return False

    # Monster facing is stored in radians; fallback to 0 if unavailable.
    import math
    facing = float(monster.get("facing", 0.0))
    angle_to_player = math.atan2(dy, dx)
    delta = abs((angle_to_player - facing + math.pi) % (2 * math.pi) - math.pi)
    return delta >= math.radians(180 - SURVIVAL_STEALTH["rear_stealth_angle_deg"])

def survival_backstab(player, monster, damage=999):
    if not survival_can_stealth_kill(player, monster):
        return {"ok": False, "reason": "ต้องย่องไปด้านหลัง Monster ก่อน"}
    monster["hp"] = max(0, float(monster.get("hp", 0)) - float(damage))
    return {
        "ok": True,
        "damage": float(damage),
        "silent": True,
        "monster_defeated": monster["hp"] <= 0,
        "message": "🗡️ ลอบโจมตีจากด้านหลังสำเร็จ"
    }

def survival_consume_chocolate(inventory, player):
    """Chocolate delays sleepiness/fatigue; it does not replace food/water."""
    if not isinstance(inventory, dict) or inventory.get("chocolate", 0) <= 0:
        return {"ok": False, "reason": "ไม่มีช็อกโกแลต"}
    inventory["chocolate"] -= 1
    if inventory["chocolate"] <= 0:
        inventory.pop("chocolate", None)
    if isinstance(player, dict):
        player["sleepiness_delay"] = max(
            float(player.get("sleepiness_delay", 0)),
            SURVIVAL_STEALTH["chocolate_sleep_delay"]
        )
        player["chocolate_active"] = True
    return {
        "ok": True,
        "sleepiness_delay": SURVIVAL_STEALTH["chocolate_sleep_delay"],
        "message": "🍫 กินช็อกโกแลตแล้ว ง่วงช้าลง"
    }



