# ==========================================
# VMAX SURVIVAL — 40 FLOOR STREAMING WORLD
# ==========================================

# ==========================================
# VMAX SURVIVAL — 40 FLOOR STREAMING WORLD
# Reuses the existing map/world layer; this adds streaming/LOD policy only.
# ==========================================
SURVIVAL_WORLD_STREAMING = {
    "enabled": True,
    "view_distance": 2600.0,
    "near_distance": 900.0,
    "far_distance": 1800.0,
    "unload_distance": 3200.0,
    "max_loaded_buildings": 28,
    "max_loaded_floors": 6,
    "lod_levels": {
        "near": 0,
        "mid": 1,
        "far": 2,
    },
}

def survival_streaming_lod(distance):
    """Select LOD for distant buildings without changing the existing map format."""
    d = max(0.0, float(distance))
    if d <= SURVIVAL_WORLD_STREAMING["near_distance"]:
        return SURVIVAL_WORLD_STREAMING["lod_levels"]["near"]
    if d <= SURVIVAL_WORLD_STREAMING["far_distance"]:
        return SURVIVAL_WORLD_STREAMING["lod_levels"]["mid"]
    if d <= SURVIVAL_WORLD_STREAMING["view_distance"]:
        return SURVIVAL_WORLD_STREAMING["lod_levels"]["far"]
    return None

def survival_stream_buildings(buildings, player_x, player_y):
    """
    Return a streaming plan for the existing map.
    Near buildings keep full detail; distant buildings keep lightweight shells/LOD.
    """
    if not isinstance(buildings, (list, tuple)):
        return {"near": [], "mid": [], "far": [], "unloaded": []}

    plan = {"near": [], "mid": [], "far": [], "unloaded": []}
    px, py = float(player_x), float(player_y)

    for b in buildings:
        if not isinstance(b, dict):
            continue
        bx, by = float(b.get("x", 0)), float(b.get("y", 0))
        distance = ((bx - px) ** 2 + (by - py) ** 2) ** 0.5
        lod = survival_streaming_lod(distance)
        item_id = b.get("id", b.get("building_id", len(plan["near"])))
        if lod is None:
            plan["unloaded"].append(item_id)
        elif lod == 0:
            plan["near"].append(item_id)
        elif lod == 1:
            plan["mid"].append(item_id)
        else:
            plan["far"].append(item_id)

    # Keep the policy bounded so a large 40-floor scene doesn't try to fully render everything.
    plan["near"] = plan["near"][:SURVIVAL_WORLD_STREAMING["max_loaded_buildings"]]
    plan["mid"] = plan["mid"][:SURVIVAL_WORLD_STREAMING["max_loaded_buildings"]]
    plan["far"] = plan["far"][:SURVIVAL_WORLD_STREAMING["max_loaded_buildings"]]
    return plan

def survival_stream_floor(floor, player_floor):
    """Floor-level streaming policy for the 40-floor survival building."""
    try:
        f, pf = int(floor), int(player_floor)
    except (TypeError, ValueError):
        return "unloaded"
    delta = abs(f - pf)
    if delta == 0:
        return "full"
    if delta <= 2:
        return "detail"
    if delta <= SURVIVAL_WORLD_STREAMING["max_loaded_floors"]:
        return "shell"
    return "unloaded"


# --- 40-floor streaming API ---

# --- 40-floor streaming API ---
if "app" in globals():
    @app.route("/api/survival/world-streaming", methods=["POST"])
    def survival_world_streaming_api():
        payload = request.get_json(silent=True) or {}
        return survival_stream_buildings(
            payload.get("buildings", []),
            payload.get("player_x", 0),
            payload.get("player_y", 0),
        )


# ==========================================
# VMAX SURVIVAL — CAMP SLEEP / 07:00
# ==========================================

# ==========================================
# VMAX SURVIVAL — CAMP SLEEP / 07:00
# Camp is on floor 40. Sleeping is available only at the camp bed.
# Sleeping does not spawn monsters at the camp.
# ==========================================
SURVIVAL_CAMP_FLOOR = 40
SURVIVAL_SLEEP_WAKE_HOUR = 7
SURVIVAL_SLEEP_WAKE_MINUTE = 0

def survival_sleep_at_camp(game_state):
    """
    Sleep at the floor-40 camp bed and advance to 07:00 next day.
    Uses the existing save/time/day systems when available.
    """
    if not isinstance(game_state, dict):
        return {"ok": False, "reason": "invalid_game_state"}

    floor = int(game_state.get("floor", SURVIVAL_CAMP_FLOOR))
    if floor != SURVIVAL_CAMP_FLOOR:
        return {"ok": False, "reason": "ต้องนอนที่แคมป์ชั้น 40"}

    # Advance to next day and set the exact wake time.
    game_state["day"] = int(game_state.get("day", 1)) + 1
    game_state["hour"] = SURVIVAL_SLEEP_WAKE_HOUR
    game_state["minute"] = SURVIVAL_SLEEP_WAKE_MINUTE
    game_state["second"] = 0

    # Explicitly mark the camp as a safe zone during sleep.
    game_state["sleeping"] = False
    game_state["camp_safe"] = True
    game_state["monster_spawn_suppressed"] = True

    # Restore basic rest values when those fields exist.
    if "stamina" in game_state:
        game_state["stamina"] = 100
    if "sleepiness" in game_state:
        game_state["sleepiness"] = 0

    # Ask the existing save layer to persist the new state when exposed.
    saver = game_state.get("_save_callback")
    if callable(saver):
        saver(game_state)

    return {
        "ok": True,
        "floor": SURVIVAL_CAMP_FLOOR,
        "day": game_state["day"],
        "wake_time": "07:00",
        "camp_safe": True,
        "monster_spawn_suppressed": True,
        "message": "🛏️ นอนที่แคมป์ชั้น 40 — ตื่นเวลา 07:00 น."
    }

def survival_is_camp_safe_zone(floor):
    return int(floor) == SURVIVAL_CAMP_FLOOR


# --- Camp sleep API ---

# --- Camp sleep API ---
if "app" in globals():
    @app.route("/api/survival/camp/sleep", methods=["POST"])
    def survival_camp_sleep_api():
        payload = request.get_json(silent=True) or {}
        return survival_sleep_at_camp(payload)



