# VMAX EVENTS — FIELD VIAL DRIVE
# อีเวนต์เก็บ "หลอดตัวอย่างบริสุทธิ์" จากจุดเก็บตัวอย่างที่กระจายอยู่ตามโซนต่างๆ ในแมพ
# (ตามที่ขอ — อ้างอิงไอเดียจากสกรีนที่ส่งมา: ยิงเก็บของในแมพ -> ได้สกุลเงินอีเวนต์ -> เอาไปกด
# แลกของสุ่มกับนายหน้า (5 หลอด = สุ่ม 1 ครั้ง, 50 หลอด = สุ่ม 10 ครั้ง) -> มีลุ้นของหายาก ("ของแดง")
# -> ของส่งเข้ากล่องจดหมายก่อนเสมอ ต้องกดรับเข้าคลังเอง)
# ชื่อ/ไอเทม/นายหน้าทั้งหมดด้านล่างเป็นของโปรเจกต์นี้เอง ไม่ได้อ้างอิงชื่อตัวละครหรือแบรนด์จากเกมใดเกมหนึ่ง
# โดยเฉพาะ — ต่อยอดจากระบบที่มีอยู่แล้วในไฟล์นี้แทนที่จะสร้างซ้ำซ้อน:
#   • จุดเก็บตัวอย่าง 3 จุด ผูกกับโซนจริงใน XROOM_MAP_POOL (extraction maps เดิม) แทนการคิดชื่อโซนใหม่
#   • สกุลเงิน "vial" เพิ่มเป็นฟิลด์ใหม่ใน PLAYER_CURRENCY / _currency_get / _currency_pay เดิม
#     (แนวเดียวกับตอนเพิ่ม "scrap" เข้าไปทีหลังใน [6zz6w-x])
#   • ของรางวัลส่งเข้ากล่องจดหมายเฉพาะของอีเวนต์นี้ (VIALRUN_MAILBOX) ก่อน แล้วค่อยกดรับเข้า
#     INVENTORY หลัก — แนวเดียวกับ WEBSHOP_MAILBOX ที่มีอยู่แล้ว
#   • ขึ้นทะเบียนอีเวนต์ใน EVENT_CATALOG เดิม ให้โผล่ในแท็บ/ปฏิทินอีเวนต์อัตโนมัติ (ไม่ต้องเปิดหน้าใหม่)
#   • ใช้ safety-net "การันตีของแดงอย่างน้อย 1 ชิ้นต่อการแลกแบบ 10 ครั้ง" แนวเดียวกับ x10 safety
#     net ของระบบกาชาเดิมที่ [2D2]
# ==========================================

VIALRUN_EVENT = {
    "id": "field_vial_drive",
    "name_th": "ล่าหลอดตัวอย่างภาคสนาม",
    "desc_th": "เก็บหลอดตัวอย่างบริสุทธิ์จากจุดเก็บตัวอย่าง 3 จุดทั่วแมพ แล้วเอาไปแลกของสุ่มกับนายหน้าประจำเซฟเฮาส์ "
               "มีลุ้นของระดับ \"แดง\" หายากพิเศษ — ของทั้งหมดส่งเข้ากล่องจดหมายให้กดรับเอง",
    "game_id": "attackion_root",
    "start": "2026-08-27",
    "end": "2026-09-10",
}

# ให้อีเวนต์นี้โผล่ในแท็บ/ปฏิทินอีเวนต์เดิมโดยอัตโนมัติ (รูปแบบ dict ต้องตรงกับ EVENT_CATALOG เดิมทุกฟิลด์)
EVENT_CATALOG.append({
    "id": VIALRUN_EVENT["id"], "name_th": VIALRUN_EVENT["name_th"],
    "type": "limited", "start": VIALRUN_EVENT["start"], "end": VIALRUN_EVENT["end"],
})

# จุดเก็บตัวอย่าง — ผูกกับโซนจริงที่มีอยู่แล้วใน XROOM_MAP_POOL แทนการสร้างชื่อโซนใหม่ซ้ำซ้อน
VIALRUN_COLLECTION_POINTS = [
    {"point_id": "brakkesh_depot", "zone_id": "brakkesh", "zone_name": "Brakkesh Town",  "yield_min": 2, "yield_max": 5},
    {"point_id": "grove_outpost",  "zone_id": "grove",    "zone_name": "The Grove",       "yield_min": 2, "yield_max": 5},
    {"point_id": "helipad_cache",  "zone_id": "helipad",  "zone_name": "Doctor Helipad",  "yield_min": 3, "yield_max": 6},
]
VIALRUN_COLLECT_COOLDOWN_SEC = 20 * 60  # คูลดาวน์ต่อจุด/ต่อผู้เล่น (มิเรอร์แนว "PLEASE WAIT" ของสถานีในสกรีนอ้างอิง)

# อัตราการแลก — ตรงตามสกรีนอ้างอิง: 5 หลอด = สุ่ม 1 ครั้ง, 50 หลอด = สุ่ม 10 ครั้ง
VIALRUN_EXCHANGE_RATES = {
    "single": {"cost": 5,  "pulls": 1},
    "bulk":   {"cost": 50, "pulls": 10},
}

# อัตราดรอปของแต่ละระดับ (รวมกันต้องเท่ากับ 1.0) — "red" คือ "ของแดง" ที่ผู้เล่นลุ้นถึง
VIALRUN_RATES = {
    "standard": 0.72,
    "enhanced": 0.20,
    "red":      0.08,
}

# คลังไอเทมต่อระดับ — ของทั้งหมดเป็นคอสเมติก/ของสะสมสำหรับเกม attackion_root ชื่อคิดขึ้นเองทั้งหมด
VIALRUN_BANNER = {
    "standard": ["Field Ration Pack", "Scrap Bandage Kit", "Signal Flare x3", "Basic Repair Kit"],
    "enhanced": ["Reinforced Chest Rig", "Thermal Optic: Mk1", "Stabilizer Grip Charm"],
    "red":      ["Broker's Sidearm Skin: Crimson Vial", "Contaminated Zone Outfit: Hazmat Prime"],
}

VIALRUN_COOLDOWNS = {}   # uid -> {point_id: last_claimed_ts}
VIALRUN_MAILBOX = {}     # uid -> [{mail_id, tier, item, red_tier, claimed, received_at}]


def _vialrun_cooldowns(uid: str) -> dict:
    return VIALRUN_COOLDOWNS.setdefault(uid, {})


def vialrun_status(uid: str) -> dict:
    """ยอดหลอดคงเหลือ + สถานะคูลดาวน์ของจุดเก็บตัวอย่างทั้ง 3 จุด"""
    cur = _currency_get(uid)
    cds = _vialrun_cooldowns(uid)
    now = time.time()
    points = []
    for pt in VIALRUN_COLLECTION_POINTS:
        remain = max(0, int(VIALRUN_COLLECT_COOLDOWN_SEC - (now - cds.get(pt["point_id"], 0))))
        points.append({**pt, "ready": remain == 0, "cooldown_remaining_sec": remain})
    return {"st": "ok", "event": VIALRUN_EVENT, "vial_balance": cur["vial"], "points": points}


def vialrun_collect(uid: str, point_id: str) -> dict:
    """เก็บหลอดตัวอย่างจากจุดที่ระบุ ถ้ายังติดคูลดาวน์อยู่จะไม่ได้ของ"""
    pt = next((p for p in VIALRUN_COLLECTION_POINTS if p["point_id"] == point_id), None)
    if not pt:
        return {"st": "error", "msg": "ไม่พบจุดเก็บตัวอย่างนี้"}
    cds = _vialrun_cooldowns(uid)
    now = time.time()
    remain = VIALRUN_COLLECT_COOLDOWN_SEC - (now - cds.get(point_id, 0))
    if remain > 0:
        return {"st": "error", "msg": f"จุดนี้ยังไม่พร้อม รออีก {int(remain)} วินาที",
                "cooldown_remaining_sec": int(remain)}
    gained = random.randint(pt["yield_min"], pt["yield_max"])
    cur = _currency_get(uid)
    cur["vial"] += gained
    cds[point_id] = now
    return {"st": "ok", "point_id": point_id, "zone_name": pt["zone_name"], "gained": gained,
            "vial_balance": cur["vial"], "msg": f"เก็บได้ {gained} หลอดจาก {pt['zone_name']}"}


def _vialrun_roll_one() -> str:
    roll = random.random()
    cum = 0.0
    for tier in ("standard", "enhanced", "red"):
        cum += VIALRUN_RATES[tier]
        if roll <= cum:
            return tier
    return "red"


def _vialrun_mail_add(uid: str, tier: str, item: str) -> str:
    mail_id = uuid.uuid4().hex[:8]
    VIALRUN_MAILBOX.setdefault(uid, []).append({
        "mail_id": mail_id, "tier": tier, "item": item, "red_tier": tier == "red",
        "claimed": False, "received_at": time.time(),
    })
    return mail_id


def vialrun_exchange(uid: str, mode: str) -> dict:
    """mode 'single' = 5 หลอด สุ่ม 1 ครั้ง, mode 'bulk' = 50 หลอด สุ่ม 10 ครั้ง (การันตีของแดงอย่างน้อย
    1 ชิ้นต่อการแลกแบบ bulk เหมือน safety net ของระบบกาชาเดิมที่ [2D2]) ของทุกชิ้นที่ได้ส่งเข้ากล่อง
    จดหมายก่อนเสมอ (ไม่เข้า INVENTORY ทันที) ต้องกด /api/vialrun/mailbox/claim อีกทีถึงจะเข้าคลังจริง"""
    plan = VIALRUN_EXCHANGE_RATES.get(mode)
    if not plan:
        return {"st": "error", "msg": "mode ต้องเป็น 'single' หรือ 'bulk'"}
    if not _currency_pay(uid, "vial", plan["cost"]):
        return {"st": "error", "msg": f"หลอดไม่พอ (ต้องใช้ {plan['cost']} หลอด)"}

    results = []
    saw_red = False
    for _ in range(plan["pulls"]):
        tier = _vialrun_roll_one()
        item = random.choice(VIALRUN_BANNER[tier])
        if tier == "red":
            saw_red = True
        results.append({"tier": tier, "item": item})

    if plan["pulls"] >= 10 and not saw_red:
        idx = random.randrange(len(results))
        results[idx] = {"tier": "red", "item": random.choice(VIALRUN_BANNER["red"])}

    for r in results:
        r["mail_id"] = _vialrun_mail_add(uid, r["tier"], r["item"])

    audit_log("vialrun_exchange", uid=uid, mode=mode, cost=plan["cost"], pulls=plan["pulls"],
              red_count=sum(1 for r in results if r["tier"] == "red"))

    cur = _currency_get(uid)
    return {"st": "ok", "spent": plan["cost"], "vial_balance": cur["vial"], "results": results,
            "msg": "แลกสำเร็จ ของทั้งหมดส่งเข้ากล่องจดหมายแล้ว กดรับเข้าคลังได้เลย"}


