EXTRACTION_CONTAINERS = {}


def _item_weight(item_id, qty=1):
    return EXTRACTION_ITEM_DB.get(item_id, {}).get("weight", 1.0) * qty


def _roll_loot(table_name="warehouse", rolls=3):
    table = EXTRACTION_LOOT_TABLES.get(table_name, EXTRACTION_LOOT_TABLES["warehouse"])
    ids = [x[0] for x in table]
    weights = [x[1] for x in table]
    result = []
    for _ in range(max(1, int(rolls))):
        result.append(random.choices(ids, weights=weights, k=1)[0])
    return result



# ==========================================================================
# [ WEEKLY MISSION ] SPEED-RUN INFILTRATION (แทรกซึม / ห้ามอาวุธ / ห้ามยา)
# --------------------------------------------------------------------------
# ภารกิจรายสัปดาห์ของเกมยิงเก็บของหนี:
#   - เข้าแมพโหมดแทรกซึม (mode=speedrun_infil)
#   - ห้ามพกอาวุธทุกกระบอก
#   - ห้ามใช้ยา / consumable แม้แต่ชนิดเดียว
#   - หนีออก (extract) โดยให้เวลาในแมพเหลืออย่างน้อย 10 นาที
# ชื่อเรียกในระบบ: speed-run / แทรกซึมรายสัปดาห์ (เหมาะสมกับคำว่า speed run
# ในแง่ "เคลียร์เร็วภายใต้ข้อจำกัด" ไม่ใช่แค่วิ่งเร็วอย่างเดียว)
# ==========================================================================
EXTRACTION_DEFAULT_DURATION_SEC = int(os.environ.get("EXTRACTION_DEFAULT_DURATION_SEC", str(20 * 60)))
SPEEDRUN_INFIL_DURATION_SEC = int(os.environ.get("SPEEDRUN_INFIL_DURATION_SEC", str(20 * 60)))  # แมพ 20 นาที
SPEEDRUN_INFIL_REQUIRED_REMAINING_SEC = int(os.environ.get("SPEEDRUN_INFIL_REQUIRED_REMAINING_SEC", str(10 * 60)))  # ต้องเหลือ >= 10 นาที
SPEEDRUN_WEEKLY_REWARD = {
    "gold": int(os.environ.get("SPEEDRUN_REWARD_GOLD", "8000")),
    "credits": int(os.environ.get("SPEEDRUN_REWARD_CREDITS", "200")),
    "scrap": int(os.environ.get("SPEEDRUN_REWARD_SCRAP", "40")),
}
SPEEDRUN_WEEKLY_STATE = {}  # uid -> {"week": "2026-W40", "completed": bool, "completed_at": ts, "best_remaining": sec}
SPEEDRUN_DATA_DIR = os.environ.get("SPEEDRUN_DATA_DIR", "speedrun_data")
os.makedirs(SPEEDRUN_DATA_DIR, exist_ok=True)
_SPEEDRUN_LOCK = threading.Lock()

# รายการ item ที่ถือว่าเป็นยา / consumable ในโหมดนี้
SPEEDRUN_BANNED_MED_IDS = set(os.environ.get(
    "SPEEDRUN_BANNED_MED_IDS",
    "med_kit,bandage,painkiller,stim,adrenaline,syringe,first_aid,heal_spray,hot_iron"
).split(","))
# รายการที่ถือว่าเป็นอาวุธ (prefix / id)
SPEEDRUN_WEAPON_PREFIXES = ("gun_", "rifle_", "pistol_", "smg_", "shotgun_", "sniper_", "melee_", "weapon_")


def _speedrun_week_key(now=None):
    import datetime as _dt
    d = _dt.datetime.fromtimestamp(now or time.time())
    iso = d.isocalendar()
    return "%s-W%02d" % (iso[0], iso[1])


def _speedrun_path(uid):
    safe = "".join(c if c.isalnum() or c in "-_" else "_" for c in str(uid))[:96]
    return os.path.join(SPEEDRUN_DATA_DIR, "sr_%s.json" % safe)


def _speedrun_load(uid):
    with _SPEEDRUN_LOCK:
        if uid in SPEEDRUN_WEEKLY_STATE:
            st = SPEEDRUN_WEEKLY_STATE[uid]
        else:
            st = {"week": "", "completed": False, "completed_at": None, "best_remaining": 0, "history": []}
            path = _speedrun_path(uid)
            if os.path.isfile(path):
                try:
                    with open(path, "r", encoding="utf-8") as f:
                        raw = json.load(f)
                    if isinstance(raw, dict):
                        st.update(raw)
                except Exception:
                    pass
            SPEEDRUN_WEEKLY_STATE[uid] = st
        week = _speedrun_week_key()
        if st.get("week") != week:
            st["week"] = week
            st["completed"] = False
            st["completed_at"] = None
            # เก็บ best_remaining ข้ามสัปดาห์ได้ ไม่รีเซ็ต
        return st


def _speedrun_save(uid, st=None):
    with _SPEEDRUN_LOCK:
        st = st or SPEEDRUN_WEEKLY_STATE.get(uid) or _speedrun_load(uid)
        SPEEDRUN_WEEKLY_STATE[uid] = st
        path = _speedrun_path(uid)
        tmp = path + ".tmp"
        try:
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(st, f, ensure_ascii=False, indent=0)
            os.replace(tmp, path)
        except Exception as exc:
            try:
                if os.path.isfile(tmp):
                    os.remove(tmp)
            except Exception:
                pass
            print("[SPEEDRUN] save failed uid=%s: %s" % (uid, exc))


def _speedrun_weekly_status(uid):
    st = _speedrun_load(uid)
    week = _speedrun_week_key()
    return {
        "week": week,
        "completed_this_week": bool(st.get("completed") and st.get("week") == week),
        "completed_at": st.get("completed_at"),
        "best_remaining_sec": st.get("best_remaining", 0),
        "reward": SPEEDRUN_WEEKLY_REWARD,
        "rules": {
            "map": "infil_speedrun",
            "no_weapons": True,
            "no_meds": True,
            "map_duration_sec": SPEEDRUN_INFIL_DURATION_SEC,
            "must_extract_with_remaining_sec": SPEEDRUN_INFIL_REQUIRED_REMAINING_SEC,
            "label_th": "ภารกิจแทรกซึมรายสัปดาห์ (speed-run): ห้ามอาวุธ ห้ามยา หนีให้เวลาเหลืออย่างน้อย 10 นาที",
        },
    }


def _speedrun_weekly_complete(uid, remaining_sec):
    st = _speedrun_load(uid)
    week = _speedrun_week_key()
    if st.get("completed") and st.get("week") == week:
        return {"st": "ok", "duplicate": True, "msg": "เคลียร์สัปดาห์นี้ไปแล้ว", "status": _speedrun_weekly_status(uid)}
    st["week"] = week
    st["completed"] = True
    st["completed_at"] = time.time()
    st["best_remaining"] = max(float(st.get("best_remaining") or 0), float(remaining_sec))
    st.setdefault("history", []).append({"week": week, "remaining_sec": remaining_sec, "ts": time.time()})
    st["history"] = st["history"][-30:]
    # รางวัล
    reward_given = {}
    try:
        cur = _currency_get(uid)
        g = int(SPEEDRUN_WEEKLY_REWARD.get("gold", 0))
        s = int(SPEEDRUN_WEEKLY_REWARD.get("scrap", 0))
        if g:
            cur["gold"] = int(cur.get("gold", 0)) + g
            reward_given["gold"] = g
        if s:
            cur["scrap"] = int(cur.get("scrap", 0)) + s
            reward_given["scrap"] = s
    except Exception:
        pass
    try:
        c = int(SPEEDRUN_WEEKLY_REWARD.get("credits", 0))
        if c and "set_current_uid" in globals():
            set_current_uid(uid)
            if isinstance(P, dict):
                P["credits"] = int(P.get("credits", 0) or 0) + c
                if "WALLET" in globals() and isinstance(WALLET, dict):
                    WALLET["balance"] = P["credits"]
                reward_given["credits"] = c
    except Exception:
        pass
    _speedrun_save(uid, st)
    return {
        "st": "ok", "duplicate": False, "msg": "เคลียร์ภารกิจ speed-run รายสัปดาห์",
        "reward": reward_given, "status": _speedrun_weekly_status(uid),
    }


def extraction_speedrun_note_violation(uid, vtype, detail=""):
    """บันทึกการละเมิดกฎ (อาวุธ/ยา) ระหว่าง raid speedrun — เรียกจาก shoot/use-med hooks"""
    raid = EXTRACTION_RAIDS.get(uid)
    if not raid or not raid.get("active") or raid.get("mode") != "speedrun_infil":
        return False
    raid.setdefault("violations", []).append({"type": vtype, "detail": detail, "ts": time.time()})
    if vtype == "weapon":
        raid["weapons_used"] = int(raid.get("weapons_used", 0)) + 1
    if vtype == "med":
        raid["meds_used"] = int(raid.get("meds_used", 0)) + 1
    return True


def extraction_speedrun_assert_action(uid, action):
    """กันการใช้ยา/อาวุธระหว่าง speedrun — คืน (ok, msg)"""
    raid = EXTRACTION_RAIDS.get(uid)
    if not raid or not raid.get("active") or raid.get("mode") != "speedrun_infil":
        return True, ""
    if action == "weapon" and raid.get("ban_weapons"):
        extraction_speedrun_note_violation(uid, "weapon", "attempt_use")
        return False, "โหมดแทรกซึม: ห้ามใช้/พกอาวุธทุกชนิด"
    if action == "med" and raid.get("ban_meds"):
        extraction_speedrun_note_violation(uid, "med", "attempt_use")
        return False, "โหมดแทรกซึม: ห้ามใช้ยาหรือ consumable ทุกชนิด"
    return True, ""


@app.route('/api/extraction/weekly/speedrun/status')
def api_extraction_speedrun_status():
    uid = str(request.args.get("uid") or (P.get("uid") if isinstance(P, dict) else "") or "guest")
    return jsonify({"st": "ok", **_speedrun_weekly_status(uid)})


@app.route('/api/extraction/weekly/speedrun/start', methods=['POST'])
def api_extraction_speedrun_start():
    """เริ่มภารกิจแทรกซึมรายสัปดาห์ (speed-run) — บังคับ mode=speedrun_infil, โหลดเอาต์ว่าง"""
    data = request.get_json(silent=True) or {}
    uid = str(data.get("uid") or (P.get("uid") if isinstance(P, dict) else "") or "guest")
    ok, msg, raid = extraction_raid_start(uid, map_name="infil_speedrun", capacity=8, mode="speedrun_infil", loadout={"weapons": [], "meds": []})
    return jsonify({"st": "ok" if ok else "error", "msg": msg, "raid": extraction_raid_state(uid), "weekly": _speedrun_weekly_status(uid)})


def extraction_raid_start(uid, map_name="warehouse", capacity=12, mode="normal", loadout=None):
    """เริ่ม raid. mode='speedrun_infil' = ภารกิจแทรกซึมรายสัปดาห์ (ห้ามอาวุธ/ยา, ต้องหนีให้เวลาเหลือ >= 10 นาที)"""
    old = EXTRACTION_RAIDS.get(uid)
    if old and old.get("active"):
        return False, "มี raid ที่กำลังเล่นอยู่แล้ว", old
    mode = str(mode or "normal")
    loadout = loadout if isinstance(loadout, dict) else {}
    if mode == "speedrun_infil":
        # ตรวจภารกิจรายสัปดาห์ยังไม่เคลียร์ / ยังไม่เกินโควตา
        _sr = _speedrun_weekly_status(uid)
        if _sr.get("completed_this_week"):
            return False, "ภารกิจ speed-run รายสัปดาห์นี้เคลียร์แล้ว รอรีเซ็ตวันจันทร์", old
        # ห้ามพกอาวุธทุกชนิดในโหลดเอาต์ตอนเข้า
        weapons = list(loadout.get("weapons") or loadout.get("weapon_ids") or [])
        if weapons:
            return False, "โหมดแทรกซึม: ห้ามพกอาวุธทุกกระบอกตอนเข้าแมพ", old
        meds = list(loadout.get("meds") or loadout.get("consumables") or [])
        if meds:
            return False, "โหมดแทรกซึม: ห้ามนำยา/consumable เข้าแมพ", old
        map_name = "infil_speedrun"
        capacity = min(int(capacity), 8)
    raid_id = uuid.uuid4().hex[:10]
    containers = {}
    n_boxes = 6 if mode == "speedrun_infil" else 10
    for i in range(n_boxes):
        cid = f"{raid_id}-c{i+1}"
        containers[cid] = {
            "id": cid, "kind": random.choice(["crate", "locker", "case"]),
            "opened": False, "looted": False,
            "loot": _roll_loot(map_name if map_name != "infil_speedrun" else "warehouse", random.choice([1, 2, 3])),
            **_vmax_raid_container_xy(map_name if map_name != "infil_speedrun" else "warehouse"),
        }
    EXTRACTION_CONTAINERS[raid_id] = containers
    duration = SPEEDRUN_INFIL_DURATION_SEC if mode == "speedrun_infil" else EXTRACTION_DEFAULT_DURATION_SEC
    raid = {
        "raid_id": raid_id, "uid": uid, "map": map_name,
        "active": True, "extracted": False, "capacity": int(capacity),
        "carry": {}, "entered_at": time.time(), "extraction_progress": 0.0,
        "mode": mode,
        "duration_sec": duration,
        "ends_at": time.time() + duration,
        "ban_weapons": mode == "speedrun_infil",
        "ban_meds": mode == "speedrun_infil",
        "required_remaining_sec": SPEEDRUN_INFIL_REQUIRED_REMAINING_SEC if mode == "speedrun_infil" else 0,
        "loadout": {"weapons": [], "meds": []} if mode == "speedrun_infil" else dict(loadout),
        "meds_used": 0,
        "weapons_used": 0,
        "violations": [],
    }
    EXTRACTION_RAIDS[uid] = raid
    _supply_pass_hook(uid, "raid_enter")
    msg = "เริ่ม raid แล้ว"
    if mode == "speedrun_infil":
        msg = "เริ่มภารกิจแทรกซึม (speed-run): ห้ามอาวุธ/ยา — หนีออกให้เวลาในแมพเหลืออย่างน้อย 10 นาที"
    return True, msg, raid


def extraction_raid_state(uid):
    raid = EXTRACTION_RAIDS.get(uid)
    if not raid:
        return {"active": False, "carry": {}, "capacity": 12}
    used = sum(_item_weight(k, v) for k, v in raid["carry"].items())
    return {**raid, "carry_weight": round(used, 2), "containers": list(EXTRACTION_CONTAINERS.get(raid["raid_id"], {}).values())}


def extraction_open_container(uid, container_id):
    raid = EXTRACTION_RAIDS.get(uid)
    if not raid or not raid.get("active"):
        return False, "ไม่มี raid ที่กำลังเล่น", None
    c = EXTRACTION_CONTAINERS.get(raid["raid_id"], {}).get(container_id)
    if not c:
        return False, "ไม่พบกล่อง", None
    if c["opened"]:
        return True, "กล่องนี้เปิดแล้ว", c
    c["opened"] = True
    _supply_pass_hook(uid, "container_open")
    return True, "เปิดกล่องสำเร็จ", c


def extraction_pickup(uid, container_id, item_index=0):
    raid = EXTRACTION_RAIDS.get(uid)
    if not raid or not raid.get("active"):
        return False, "ไม่มี raid ที่กำลังเล่น", None
    c = EXTRACTION_CONTAINERS.get(raid["raid_id"], {}).get(container_id)
    if not c or not c.get("opened"):
        return False, "ต้องเปิดกล่องก่อน", None
    if c.get("looted"):
        return False, "กล่องนี้เก็บของไปแล้ว", None
    loot = c.get("loot", [])
    if not loot:
        c["looted"] = True
        return False, "กล่องว่าง", None
    try:
        item_id = loot[int(item_index)]
    except (ValueError, IndexError):
        return False, "ไม่พบไอเทมในช่องนั้น", None
    new_weight = sum(_item_weight(k, v) for k, v in raid["carry"].items()) + _item_weight(item_id)
    if new_weight > raid["capacity"]:
        return False, "กระเป๋าเต็ม", None
    raid["carry"][item_id] = raid["carry"].get(item_id, 0) + 1
    loot.pop(int(item_index))
    if not loot:
        c["looted"] = True
    _supply_pass_hook(uid, "loot_pickup")
    return True, "เก็บของแล้ว", {"item": item_id, "carry": raid["carry"]}


def extraction_craft(uid, recipe_id, craft_qty=1):
    recipe = EXTRACTION_CRAFT_RECIPES.get(recipe_id)
    if not recipe:
        return False, "ไม่พบสูตรคราฟต์", None
    try:
        craft_qty = max(1, min(99, int(craft_qty)))
    except (TypeError, ValueError):
        craft_qty = 1
    stash = EXTRACTION_STASH[uid]
    for item_id, qty in recipe["materials"].items():
        need = qty * craft_qty
        if stash.get(item_id, 0) < need:
            return False, f"วัสดุไม่พอ: {EXTRACTION_ITEM_DB.get(item_id, {}).get('name', item_id)} (ต้องใช้ {need})", None
    for item_id, qty in recipe["materials"].items():
        stash[item_id] -= qty * craft_qty
    out_item = recipe["output"]
    made = recipe["qty"] * craft_qty
    stash[out_item] = stash.get(out_item, 0) + made
    _supply_pass_hook(uid, "craft")
    return True, f"คราฟต์สำเร็จ x{made}", {"item": out_item, "qty": made, "craft_qty": craft_qty, "stash": dict(stash)}


def extraction_extract(uid):
    raid = EXTRACTION_RAIDS.get(uid)
    if not raid or not raid.get("active"):
        return False, "ไม่มี raid ที่กำลังเล่น", None
    now = time.time()
    ends_at = float(raid.get("ends_at") or (raid.get("entered_at", now) + raid.get("duration_sec", EXTRACTION_DEFAULT_DURATION_SEC)))
    remaining = max(0.0, ends_at - now)
    # หมดเวลาแมพแล้ว ถอนไม่ได้ในโหมดปกติก็ยังอนุญาต แต่ speedrun ต้องมีเวลาเหลือ
    if raid.get("mode") == "speedrun_infil":
        need = float(raid.get("required_remaining_sec") or SPEEDRUN_INFIL_REQUIRED_REMAINING_SEC)
        if remaining < need:
            return False, "ภารกิจ speed-run: ต้องหนีออกโดยให้เวลาในแมพเหลืออย่างน้อย 10 นาที (ตอนนี้เหลือ %.0f วินาที)" % remaining, {
                "remaining_sec": remaining, "required_remaining_sec": need,
            }
        if raid.get("weapons_used", 0) > 0 or raid.get("ban_weapons") and raid.get("violations"):
            if any(v.get("type") == "weapon" for v in (raid.get("violations") or [])):
                return False, "ภารกิจ speed-run ล้มเหลว: มีการใช้/พกอาวุธ", None
        if raid.get("meds_used", 0) > 0 or any(v.get("type") == "med" for v in (raid.get("violations") or [])):
            return False, "ภารกิจ speed-run ล้มเหลว: มีการใช้ยา/consumable", None
    stash = EXTRACTION_STASH[uid]
    for item_id, qty in raid["carry"].items():
        stash[item_id] = stash.get(item_id, 0) + qty
    raid["active"] = False
    raid["extracted"] = True
    vmax_gunsmith_snapshot(uid)   # [NEW] จบเรด -> จำชุดแต่งปืนที่ใส่อยู่เป็น "แต่งรอบที่แล้ว"
    result = {
        "raid_id": raid["raid_id"], "extracted_items": dict(raid["carry"]), "stash": dict(stash),
        "mode": raid.get("mode", "normal"), "remaining_sec": remaining,
    }
    raid["carry"] = {}
    if raid.get("mode") == "speedrun_infil":
        claim = _speedrun_weekly_complete(uid, remaining)
        result["weekly_mission"] = claim
    _supply_pass_hook(uid, "extract_success")
    return True, "ถอนกำลังสำเร็จ" + (" — เคลียร์ภารกิจ speed-run รายสัปดาห์!" if raid.get("mode") == "speedrun_infil" else ""), result


def extraction_random_supply_crate(uid):
    # Random supply crate: gameplay loot only; no real-money mechanic.
    choices = ["scrap_metal", "cloth", "electronics", "med_kit", "power_cell", "encrypted_drive"]
    item_id = random.choices(choices, weights=[30, 25, 20, 12, 8, 5], k=1)[0]
    qty = 2 if item_id in ("scrap_metal", "cloth") else 1
    stash = EXTRACTION_STASH[uid]
    stash[item_id] = stash.get(item_id, 0) + qty
    return {"item": item_id, "qty": qty, "stash": dict(stash)}


