def extraction_cauterize(uid):
    """เอา 'เหล็กร้อน' (hot_iron) 1 ชิ้นจาก stash มาจี้ปิดแผล — ต้องคราฟต์ hot_iron ผ่าน
    /api/extraction/craft (ซึ่งต้องมี campfire ในสแตชอยู่ก่อน) แล้วค่อยเรียกฟังก์ชันนี้
    ห้ามเลือดได้จริงตามหลักการ cauterization แต่เจ็บ+ได้แผลไฟไหม้เพิ่ม (ดู side_effect)"""
    ok_sr, msg_sr = extraction_speedrun_assert_action(uid, "med")
    if not ok_sr:
        return False, msg_sr, None
    stash = EXTRACTION_STASH[uid]
    if stash.get("hot_iron", 0) < 1:
        return False, "ไม่มี 'เหล็กร้อน' ในสแตช — ต้องคราฟต์ hot_iron ก่อน (ต้องมี campfire)", None
    stash["hot_iron"] -= 1
    result = {"used": "hot_iron", "restores": {"hp": 15, "bleed_stop": 1},
              "side_effect": {"pain": 25, "burn_dmg": 5}, "stash": dict(stash)}
    return True, "จี้ปิดแผลด้วยเหล็กร้อนแล้ว (ห้ามเลือดสำเร็จ แต่เจ็บและมีแผลไหม้เพิ่ม)", result


