@app.route('/extraction/studio')
def extraction_studio():
    uid = request.args.get("uid") or P.get("uid") or "guest"
    return render_template_string(r'''<!doctype html>
<html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>VMAX Extraction - Logistics Crafting</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#071018;color:#edf5f9;font-family:system-ui,-apple-system,Segoe UI,sans-serif}.wrap{max-width:1180px;margin:auto;padding:18px}.top{display:flex;justify-content:space-between;gap:14px;align-items:center;border-bottom:1px solid #263946;padding-bottom:14px}.brand{font-weight:900;letter-spacing:2px;font-size:19px}.sub{opacity:.65;font-size:12px;margin-top:3px}.actions{display:flex;flex-wrap:wrap;justify-content:flex-end}button{background:#132431;color:#fff;border:1px solid #3c5565;padding:10px 13px;border-radius:8px;margin:3px;cursor:pointer}button:hover{filter:brightness(1.18)}.danger{border-color:#a85e55}.primary{border-color:#6b9aa7}.grid{display:grid;grid-template-columns:1.15fr .85fr;gap:14px;margin-top:14px}.card{background:#0e1a23;border:1px solid #273b48;border-radius:13px;padding:15px;box-shadow:0 8px 28px rgba(0,0,0,.18)}.map{height:360px;border-radius:10px;background:linear-gradient(145deg,#1a2b33,#081118);position:relative;overflow:hidden;border:1px solid #304652}.map:before{content:"";position:absolute;inset:0;background:linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);background-size:36px 36px}.container{position:absolute;border:1px solid #9eb7c3;background:#162b37;padding:9px;border-radius:8px;cursor:pointer;z-index:2}.c1{left:11%;top:24%}.c2{left:45%;top:15%}.c3{left:72%;top:38%}.c4{left:27%;top:68%}.c5{left:63%;top:74%}.h{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.h h3{margin:0}.small{opacity:.66;font-size:12px}.pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#172b37;font-size:11px}.row{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #243642;padding:8px 0}.msg{min-height:28px;margin-top:9px;padding:7px 9px;background:#0a141c;border-radius:7px;font-size:13px}.craft-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.recipe{border:1px solid #2a414e;background:#0a151d;border-radius:10px;padding:11px}.recipe-title{font-weight:800}.material{font-size:12px;display:flex;justify-content:space-between;padding-top:4px}.have.good{font-weight:700}.have.bad{opacity:.55}.output{margin-top:8px;padding:7px;background:#101f29;border-radius:7px;font-size:12px}.qty{display:flex;align-items:center;gap:4px;margin-top:8px}.qty span{min-width:32px;text-align:center;font-weight:800}.section{margin-top:14px}.loot-panel{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.loot-item{border:1px solid #2c414c;border-radius:8px;padding:8px;background:#0a151d;font-size:12px}@media(max-width:820px){.grid{grid-template-columns:1fr}.map{height:300px}.craft-grid{grid-template-columns:1fr}.loot-panel{grid-template-columns:repeat(2,1fr)}.top{align-items:flex-start;flex-direction:column}.actions{justify-content:flex-start}}
</style></head><body><div class="wrap">
<div class="top"><div><div class="brand">VMAX / LOGISTICS CRAFTING</div><div class="sub">ยิง - ค้นของ - คราฟต์ - เก็บกลับ - ถอนกำลัง</div></div><div class="actions"><button class="primary" onclick="startRaid()">เริ่ม Raid</button><button class="danger" onclick="extract()">ถอนกำลัง</button><button onclick="crate()">Supply Crate</button></div></div>
<div class="grid"><div class="card"><div class="h"><h3>Raid / Loot</h3><span id="raidStatus" class="pill">ยังไม่ได้เข้า Raid</span></div><div class="map"><div class="container c1" onclick="openC('c1')">กล่อง</div><div class="container c2" onclick="openC('c2')">ล็อกเกอร์</div><div class="container c3" onclick="openC('c3')">เคส</div><div class="container c4" onclick="openC('c4')">กล่อง</div><div class="container c5" onclick="openC('c5')">ล็อกเกอร์</div></div><div id="msg" class="msg">พร้อมออก Raid</div><div class="section"><div class="h"><b>ของที่ถืออยู่</b><span id="weight" class="small">0 / 12 kg</span></div><div id="carry"></div></div></div>
<div class="card"><div class="h"><h3>Logistics Crafting</h3><span class="small">เลือกสูตร -> ปรับจำนวน -> สังเคราะห์</span></div><div id="recipes" class="craft-grid"></div><div class="section"><div class="h"><h3>Stash</h3><span class="small">ของที่รอดกลับมาจะเก็บไว้</span></div><div id="stash"></div></div><div class="section"><div class="h"><h3>Loot ที่เปิดได้</h3><span class="small">เลือกกล่องบนแผนที่</span></div><div id="lootPanel" class="loot-panel"><div class="small">ยังไม่ได้เปิดกล่อง</div></div></div></div></div></div>
<script>
const UID={{uid|tojson}};let state={},recipes={},items={},selectedRecipe=null,craftQty=1;
async function post(url,body={}){let r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid:UID,...body})});return r.json()}
function esc(x){return String(x).replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]))}
function itemName(id){return items[id]?.name||id}
function render(){let c=state.carry||{};document.getElementById('carry').innerHTML=Object.entries(c).map(([k,v])=>`<div class=row><span>${esc(itemName(k))}</span><b>x${v}</b></div>`).join('')||'<div class=small>ยังไม่มีของในกระเป๋า</div>';let st=state.stash||{};document.getElementById('stash').innerHTML=Object.entries(st).filter(([k,v])=>v>0).map(([k,v])=>`<div class=row><span>${esc(itemName(k))}</span><b>x${v}</b></div>`).join('')||'<div class=small>คลังว่าง</div>';document.getElementById('weight').textContent=`${(state.carry_weight||0).toFixed(1)} / ${state.capacity||12} kg`;document.getElementById('raidStatus').textContent=state.active?'RAID ACTIVE':'ยังไม่ได้เข้า Raid';renderRecipes()}
function renderRecipes(){document.getElementById('recipes').innerHTML=Object.entries(recipes).map(([id,r])=>{let mats=Object.entries(r.materials).map(([m,q])=>{let have=(state.stash||{})[m]||0,need=q*craftQty;return `<div class=material><span>${esc(itemName(m))} x${need}</span><span class="have ${have>=need?'good':'bad'}">มี ${have}</span></div>`}).join('');return `<div class=recipe><div class=recipe-title>${esc(r.name)}</div>${mats}<div class=output>ผลลัพธ์: <b>${esc(itemName(r.output))}</b> x${r.qty*craftQty}</div><div class=qty><button onclick="changeQty(-1)">-</button><span>${craftQty}</span><button onclick="changeQty(1)">+</button><button onclick="doCraft('${id}')">สังเคราะห์</button></div></div>`}).join('')}
function changeQty(d){craftQty=Math.max(1,Math.min(99,craftQty+d));renderRecipes()}
async function doCraft(id){selectedRecipe=id;let d=await post('/api/extraction/craft',{recipe_id:id,qty:craftQty});msg(d.msg);craftQty=1;await refresh()}
async function refresh(){let d=await fetch('/api/extraction/raid/state?uid='+encodeURIComponent(UID)).then(r=>r.json());state=d.raid||{};state.stash=d.stash||{};let rd=await fetch('/api/extraction/crafting/list').then(r=>r.json());recipes=rd.recipes||{};items=rd.items||{};render()}
async function startRaid(){let d=await post('/api/extraction/raid/start',{map:'warehouse'});state=d.raid||{};msg(d.msg);render()}
async function openC(shortId){if(!state.raid_id){msg('กด เริ่ม Raid ก่อน');return}let d=await post('/api/extraction/container/open',{container_id:state.raid_id+'-'+shortId});msg(d.msg);let c=d.container;if(c&&c.loot?.length)document.getElementById('lootPanel').innerHTML=c.loot.map((x,i)=>`<div class=loot-item><div>${esc(itemName(x))}</div><button onclick="pickup('${esc(c.id)}',${i})">เก็บ</button></div>`).join('');else document.getElementById('lootPanel').innerHTML='<div class=small>กล่องนี้ไม่มีของเหลือ</div>'}
async function pickup(id,i){let d=await post('/api/extraction/container/pickup',{container_id:id,item_index:i});msg(d.msg);await refresh()}
async function extract(){let d=await post('/api/extraction/extract');msg(d.msg);await refresh()}
async function crate(){let d=await post('/api/extraction/supply-crate');msg('ได้ '+itemName(d.result.item)+' x'+d.result.qty);await refresh()}
function msg(x){document.getElementById('msg').textContent=x||''}refresh();
</script></body></html>''', uid=uid)


