# --- สถานะ + บันทึกไฟล์ -------------------------------------------------------------
_VAELOR_LOCK = _vlr_thr.RLock()
_VAELOR = {"state": None}


def _vaelor_new_state():
    start = float(_vlr_os.environ.get("VAELOR_START_TS") or _vlr_time.time())
    return {"version": 1, "start_ts": start, "end_ts": start + VAELOR_DURATION_DAYS * 86400,
            "forced_phase": None, "community_points": 0, "players": {}}


def _vaelor_load():
    try:
        with open(VAELOR_STATE_PATH, "r", encoding="utf-8") as f:
            st = _vlr_json.load(f)
        if isinstance(st, dict) and "players" in st and "start_ts" in st:
            return st
    except FileNotFoundError:
        pass
    except Exception as e:
        print("[Vaelor] load state failed, starting fresh:", e)
    return _vaelor_new_state()


def _vaelor_save():
    with _VAELOR_LOCK:
        try:
            tmp = VAELOR_STATE_PATH + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                _vlr_json.dump(_VAELOR["state"], f, ensure_ascii=False)
            _vlr_os.replace(tmp, VAELOR_STATE_PATH)
        except Exception as e:
            print("[Vaelor] save state failed:", e)


_VAELOR["state"] = _vaelor_load()
_vaelor_save()


def _vaelor_player(uid):
    p = _VAELOR["state"]["players"].setdefault(str(uid), {})
    p.setdefault("points", 0)
    p.setdefault("exp", 0)
    p.setdefault("extracts", 0)
    p.setdefault("daily", {"date": "", "points": 0})
    p.setdefault("shop", {})
    p.setdefault("bounty", {})
    p.setdefault("hack", {"done": [], "wrong": 0, "locked_until": 0})
    p.setdefault("nodes", [])
    p.setdefault("community_claimed", [])
    p.setdefault("form", None)
    return p


def vaelor_player_exp(uid):
    """ให้ระบบอื่นดึง exp โบนัสที่ได้จากกิจกรรมนี้ไปบวกเข้า XP ของเกม"""
    with _VAELOR_LOCK:
        return int(_vaelor_player(uid).get("exp", 0))


def _vaelor_window(now=None):
    now = now or _vlr_time.time()
    st = _VAELOR["state"]
    return {"started": now >= st["start_ts"], "active": st["start_ts"] <= now < st["end_ts"],
            "open": st["start_ts"] <= now < st["end_ts"] + VAELOR_GRACE_DAYS * 86400,
            "seconds_left": max(0, int(st["end_ts"] - now)),
            "start_ts": st["start_ts"], "end_ts": st["end_ts"]}


def _vaelor_phase(now=None):
    st = _VAELOR["state"]
    if st.get("forced_phase") in ("corporate", "hacked"):
        return st["forced_phase"]
    now = now or _vlr_time.time()
    if now >= st["start_ts"] + VAELOR_HACK_AFTER_DAYS * 86400:
        return "hacked"
    if st["community_points"] >= VAELOR_COMMUNITY_GOAL * 0.5:
        return "hacked"
    return "corporate"


def _vaelor_stash_add(uid, item, qty):
    stash = EXTRACTION_STASH[uid]
    stash[item] = stash.get(item, 0) + int(qty)


def _vaelor_stash_take(uid, item, qty):
    stash = EXTRACTION_STASH[uid]
    if stash.get(item, 0) < qty:
        return False
    stash[item] -= int(qty)
    if stash[item] <= 0:
        stash.pop(item, None)
    return True


def _vaelor_grant(uid, reward):
    """reward = {item_id: qty, "exp": n}"""
    for k, q in (reward or {}).items():
        if k == "exp":
            _vaelor_player(uid)["exp"] += int(q)
        else:
            _vaelor_stash_add(uid, k, q)


def vaelor_award_points(uid, pts, source="extract"):
    """ให้แต้มกิจกรรม (เรียกจากฝั่งเซิร์ฟเวอร์เท่านั้น) — คืนจำนวนแต้มที่ได้จริงหลังหักเพดานรายวัน"""
    with _VAELOR_LOCK:
        if not _vaelor_window()["active"]:
            return 0
        p = _vaelor_player(uid)
        today = _vlr_time.strftime("%Y-%m-%d")
        if p["daily"].get("date") != today:
            p["daily"] = {"date": today, "points": 0}
        room = max(0, VAELOR_DAILY_POINT_CAP - p["daily"]["points"])
        got = max(0, min(int(pts), room))
        p["daily"]["points"] += got
        p["points"] += got
        _VAELOR["state"]["community_points"] += got
        _vaelor_save()
        return got


def _vaelor_item_value(items):
    total = 0
    for i, q in (items or {}).items():
        total += int(EXTRACTION_ITEM_DB.get(i, {}).get("value", 0)) * int(q)
    return total


# --- เกี่ยวกับระบบ Extraction เดิม: ถอนกำลังสำเร็จ -> ได้แต้ม + Zyren Alloy -------------
try:
    _vaelor_orig_extraction_extract = extraction_extract

    def extraction_extract(uid):
        ok, msg, result = _vaelor_orig_extraction_extract(uid)
        try:
            if ok and isinstance(result, dict) and _vaelor_window()["active"]:
                items = result.get("extracted_items") or {}
                value = _vaelor_item_value(items)
                pts = min(VAELOR_MAX_POINTS_PER_EXTRACT, 100 + 25 * len(items) + value // 40)
                got = vaelor_award_points(uid, pts, "extract")
                alloy = min(300, value // 30)
                with _VAELOR_LOCK:
                    if alloy > 0:
                        _vaelor_stash_add(uid, "zyren_alloy", alloy)
                    _vaelor_player(uid)["extracts"] += 1
                    _vaelor_save()
                result["vaelor"] = {"points": got, "zyren_alloy": alloy}
        except Exception as e:
            print("[Vaelor] extract hook error:", e)
        return ok, msg, result
except NameError:
    print("[Vaelor] extraction_extract not found — กิจกรรมจะไม่ได้แต้มจากการถอนกำลัง")

# --- ข้อมูลลับ Vaelor ตกในตู้/กล่องของ raid ระหว่างกิจกรรม --------------------------------
try:
    _vaelor_orig_roll_loot = _roll_loot

    def _roll_loot(table_name="warehouse", rolls=3):
        result = _vaelor_orig_roll_loot(table_name, rolls)
        try:
            if _vaelor_window()["active"] and result and _vlr_random.random() < VAELOR_INTEL_DROP_CHANCE:
                result[_vlr_random.randrange(len(result))] = "vaelor_intel"
        except Exception:
            pass
        return result
except NameError:
    print("[Vaelor] _roll_loot not found — ข้อมูลลับจะไม่ตกใน raid")


# --- API ---------------------------------------------------------------------------
def _vaelor_uid(body=None):
    u = getattr(request, "vmax_uid", None)
    if not u:
        try:
            u = _current_uid()
        except Exception:
            u = None
    if not u:
        b = body if isinstance(body, dict) else (request.get_json(silent=True) or {})
        u = b.get("uid") or request.args.get("uid")
    u = str(u or "").strip()
    return u or None


def _vaelor_err(msg, code=400):
    return jsonify({"st": "error", "msg": msg}), code


def _vaelor_nodes_view(p):
    out = {}
    for nid, n in VAELOR_GRID.items():
        claimed = nid in p["nodes"]
        parents_ok = all(r in p["nodes"] for r in n["requires"])
        out[nid] = {"name": n["name"], "cost": n["cost"], "requires": n["requires"], "pos": n["pos"],
                    "reward": n["reward"], "claimed": claimed,
                    "claimable": (not claimed) and parents_ok and p["points"] >= n["cost"]}
    return out


def _vaelor_state_view(uid):
    p = _vaelor_player(uid)
    st = _VAELOR["state"]
    stash = EXTRACTION_STASH[uid]
    phase = _vaelor_phase()
    goal = VAELOR_COMMUNITY_GOAL
    cp = st["community_points"]
    shop = {}
    for iid, s in VAELOR_SHOP.items():
        bought = p["shop"].get(iid, 0)
        shop[iid] = {"name": EXTRACTION_ITEM_DB.get(iid, {}).get("name", iid), **s,
                     "bought": bought, "remaining": max(0, s["limit"] - bought),
                     "unlocked": p["points"] >= s["requires_points"]}
    bounty = {}
    for bid, b in VAELOR_BOUNTIES.items():
        sub = p["bounty"].get(bid, {"submitted": 0, "done": False})
        bounty[bid] = {**b, "submitted": sub["submitted"], "done": sub["done"]}
    hack = None
    if phase == "hacked":
        steps = []
        unlocked_prev = True
        for s in VAELOR_HACK_STEPS:
            done = s["id"] in p["hack"]["done"]
            steps.append({"id": s["id"], "title": s["title"], "question": s["question"],
                          "options": s.get("options"), "requires_points": s["requires_points"],
                          "reward": s["reward"], "terminal": s["terminal"], "done": done,
                          "available": unlocked_prev and not done})
            unlocked_prev = unlocked_prev and done
        hack = {"steps": steps, "locked_until": p["hack"]["locked_until"], "terminal": VAELOR_TERMINAL["hijack"]}
    return {
        "st": "ok", "event": VAELOR_EVENT_ID, "window": _vaelor_window(), "phase": phase,
        "site_status": "HIJACKED" if phase == "hacked" else "ONLINE",
        "player": {"points": p["points"], "exp": p["exp"], "extracts": p["extracts"],
                   "zyren_alloy": stash.get("zyren_alloy", 0), "vaelor_intel": stash.get("vaelor_intel", 0),
                   "daily_points": p["daily"]["points"], "daily_cap": VAELOR_DAILY_POINT_CAP,
                   "form_done": p["form"] is not None},
        "community": {"points": cp, "goal": goal, "percent": round(cp * 100.0 / goal, 1) if goal else 0,
                      "milestones": [{**m, "reached": cp >= goal * m["ratio"],
                                      "claimed": m["id"] in p["community_claimed"]}
                                     for m in VAELOR_COMMUNITY_MILESTONES]},
        "shop": shop, "bounty": bounty, "hack": hack, "grid": _vaelor_nodes_view(p),
    }


