@app.route('/api/vaelor/shop/buy', methods=['POST'])
@require_auth_toggleable
def api_vaelor_shop_buy():
    """body: {uid, item_id} -> ซื้อเสื้อเกราะจาก Anvil Depot ด้วย Zyren Alloy (จำกัดจำนวนต่อคน)"""
    body = request.get_json(silent=True) or {}
    uid = _vaelor_uid(body)
    if not uid:
        return _vaelor_err("ไม่พบ uid", 401)
    iid = str(body.get("item_id") or "")
    s = VAELOR_SHOP.get(iid)
    if not s:
        return _vaelor_err("ไม่มีสินค้านี้", 404)
    with _VAELOR_LOCK:
        if not _vaelor_window()["open"]:
            return _vaelor_err("กิจกรรมจบแล้ว", 410)
        p = _vaelor_player(uid)
        if p["points"] < s["requires_points"]:
            return _vaelor_err("แต้มกิจกรรมยังไม่ถึง (ต้องมี %d)" % s["requires_points"], 403)
        if p["shop"].get(iid, 0) >= s["limit"]:
            return _vaelor_err("ซื้อครบจำนวนจำกัดแล้ว", 409)
        if not _vaelor_stash_take(uid, "zyren_alloy", s["price"]):
            return _vaelor_err("Zyren Alloy ไม่พอ (ต้องใช้ %d)" % s["price"], 402)
        p["shop"][iid] = p["shop"].get(iid, 0) + 1
        _vaelor_stash_add(uid, iid, 1)
        _vaelor_save()
        return jsonify({"st": "ok", "item": iid, "bought": p["shop"][iid], "limit": s["limit"],
                        "zyren_alloy": EXTRACTION_STASH[uid].get("zyren_alloy", 0)})


@app.route('/api/vaelor/bounty/submit', methods=['POST'])
@require_auth_toggleable
def api_vaelor_bounty_submit():
    """body: {uid, target_id, intel} -> ส่ง 'ข้อมูลลับ Vaelor' ตามหาบุคคล ครบตามกำหนดรับรางวัล (ครั้งเดียว)"""
    body = request.get_json(silent=True) or {}
    uid = _vaelor_uid(body)
    if not uid:
        return _vaelor_err("ไม่พบ uid", 401)
    tid = str(body.get("target_id") or "")
    b = VAELOR_BOUNTIES.get(tid)
    if not b:
        return _vaelor_err("ไม่มีบุคคลนี้ในประกาศ", 404)
    try:
        n = int(body.get("intel", 1))
    except (TypeError, ValueError):
        return _vaelor_err("จำนวนไม่ถูกต้อง")
    if n < 1:
        return _vaelor_err("จำนวนไม่ถูกต้อง")
    with _VAELOR_LOCK:
        if not _vaelor_window()["open"]:
            return _vaelor_err("กิจกรรมจบแล้ว", 410)
        p = _vaelor_player(uid)
        sub = p["bounty"].setdefault(tid, {"submitted": 0, "done": False})
        if sub["done"]:
            return _vaelor_err("ส่งข้อมูลครบและรับรางวัลแล้ว", 409)
        n = min(n, b["intel_required"] - sub["submitted"])
        if not _vaelor_stash_take(uid, "vaelor_intel", n):
            return _vaelor_err("ข้อมูลลับ Vaelor ไม่พอ", 402)
        sub["submitted"] += n
        paid = None
        if sub["submitted"] >= b["intel_required"]:
            sub["done"] = True
            _vaelor_grant(uid, b["payout"])
            paid = b["payout"]
        _vaelor_save()
        return jsonify({"st": "ok", "target": tid, "submitted": sub["submitted"],
                        "required": b["intel_required"], "done": sub["done"], "payout": paid})


@app.route('/api/vaelor/hack/answer', methods=['POST'])
@require_auth_toggleable
def api_vaelor_hack_answer():
    """body: {uid, step_id, answer} -> ไขรหัสเควสเฟสแฮ็กทีละขั้น (ต้องทำตามลำดับ, ตอบผิดครบกำหนดโดนล็อกชั่วคราว)"""
    body = request.get_json(silent=True) or {}
    uid = _vaelor_uid(body)
    if not uid:
        return _vaelor_err("ไม่พบ uid", 401)
    sid = str(body.get("step_id") or "")
    ans = str(body.get("answer") or "").strip().lower()
    with _VAELOR_LOCK:
        if not _vaelor_window()["open"]:
            return _vaelor_err("กิจกรรมจบแล้ว", 410)
        if _vaelor_phase() != "hacked":
            return _vaelor_err("เว็บยังไม่ถูกแฮ็ก", 403)
        p = _vaelor_player(uid)
        h = p["hack"]
        now = _vlr_time.time()
        if h["locked_until"] > now:
            return _vaelor_err("ระบบล็อกชั่วคราว รออีก %d วินาที" % int(h["locked_until"] - now), 429)
        step = next((s for s in VAELOR_HACK_STEPS if s["id"] == sid), None)
        if not step:
            return _vaelor_err("ไม่มีขั้นนี้", 404)
        if sid in h["done"]:
            return _vaelor_err("ขั้นนี้เสร็จแล้ว", 409)
        for prev in VAELOR_HACK_STEPS:
            if prev["id"] == sid:
                break
            if prev["id"] not in h["done"]:
                return _vaelor_err("ต้องทำขั้น '%s' ก่อน" % prev["title"], 403)
        if p["points"] < step["requires_points"]:
            return _vaelor_err("แต้มกิจกรรมยังไม่ถึง (ต้องมี %d)" % step["requires_points"], 403)
        if step["question"] is not None:
            if ans not in [a.lower() for a in step["answers"]]:
                h["wrong"] += 1
                if h["wrong"] >= VAELOR_QUIZ_MAX_WRONG:
                    h["wrong"] = 0
                    h["locked_until"] = now + VAELOR_QUIZ_LOCK_SEC
                _vaelor_save()
                return _vaelor_err("รหัสไม่ถูกต้อง", 403)
        h["wrong"] = 0
        h["done"].append(sid)
        _vaelor_grant(uid, step["reward"])
        _vaelor_save()
        return jsonify({"st": "ok", "step": sid, "reward": step["reward"], "terminal": step["terminal"],
                        "all_done": len(h["done"]) == len(VAELOR_HACK_STEPS)})


@app.route('/api/vaelor/grid/claim', methods=['POST'])
@require_auth_toggleable
def api_vaelor_grid_claim():
    """body: {uid, node_id} -> ปลดโหนดในเครือข่ายรางวัล Grid (ต้องปลดโหนดแม่ก่อน + แต้มถึง)"""
    body = request.get_json(silent=True) or {}
    uid = _vaelor_uid(body)
    if not uid:
        return _vaelor_err("ไม่พบ uid", 401)
    nid = str(body.get("node_id") or "")
    n = VAELOR_GRID.get(nid)
    if not n:
        return _vaelor_err("ไม่มีโหนดนี้", 404)
    with _VAELOR_LOCK:
        if not _vaelor_window()["open"]:
            return _vaelor_err("กิจกรรมจบแล้ว", 410)
        p = _vaelor_player(uid)
        if nid in p["nodes"]:
            return _vaelor_err("ปลดโหนดนี้แล้ว", 409)
        if not all(r in p["nodes"] for r in n["requires"]):
            return _vaelor_err("ต้องปลดโหนดก่อนหน้าก่อน", 403)
        if p["points"] < n["cost"]:
            return _vaelor_err("แต้มกิจกรรมยังไม่ถึง (ต้องมี %d)" % n["cost"], 403)
        p["nodes"].append(nid)
        _vaelor_grant(uid, n["reward"])
        _vaelor_save()
        return jsonify({"st": "ok", "node": nid, "reward": n["reward"]})


@app.route('/api/vaelor/community/claim', methods=['POST'])
@require_auth_toggleable
def api_vaelor_community_claim():
    """body: {uid, milestone} -> รับรางวัลเป้าหมายชุมชนรวมเมื่อถึงเปอร์เซ็นต์ที่กำหนด"""
    body = request.get_json(silent=True) or {}
    uid = _vaelor_uid(body)
    if not uid:
        return _vaelor_err("ไม่พบ uid", 401)
    mid = str(body.get("milestone") or "")
    m = next((x for x in VAELOR_COMMUNITY_MILESTONES if x["id"] == mid), None)
    if not m:
        return _vaelor_err("ไม่มีเป้าหมายนี้", 404)
    with _VAELOR_LOCK:
        if not _vaelor_window()["open"]:
            return _vaelor_err("กิจกรรมจบแล้ว", 410)
        p = _vaelor_player(uid)
        if _VAELOR["state"]["community_points"] < VAELOR_COMMUNITY_GOAL * m["ratio"]:
            return _vaelor_err("ชุมชนยังไปไม่ถึงเป้าหมายนี้", 403)
        if p["points"] <= 0:
            return _vaelor_err("ต้องมีส่วนร่วมในกิจกรรมก่อน (ถอนกำลังสำเร็จอย่างน้อย 1 ครั้ง)", 403)
        if mid in p["community_claimed"]:
            return _vaelor_err("รับรางวัลนี้แล้ว", 409)
        p["community_claimed"].append(mid)
        _vaelor_grant(uid, m["reward"])
        _vaelor_save()
        return jsonify({"st": "ok", "milestone": mid, "reward": m["reward"]})


@app.route('/api/vaelor/admin/phase', methods=['POST'])
def api_vaelor_admin_phase():
    """แอดมินเท่านั้น: body {phase: corporate|hacked|auto} -> บังคับเฟสเว็บ (auto = กลับไปคำนวณตามเวลา/ชุมชน)"""
