    body = request.get_json(silent=True) or {}
    ph = str(body.get("phase") or "auto")
    if ph not in ("corporate", "hacked", "auto"):
        return _vaelor_err("phase ไม่ถูกต้อง")
    with _VAELOR_LOCK:
        _VAELOR["state"]["forced_phase"] = None if ph == "auto" else ph
