EXTRACTION_ITEM_TIER_DB = {
    "scrap_metal":1,"cloth":1,"electronics":2,"med_kit":2,"power_cell":3,
    "encrypted_drive":4,"prototype_core":5,"keycard":3,"keycard_blue":3,
    "keycard_red":4,"keycard_black":5,"access_card":3,"access_card_red":4,
}
EXTRACTION_TIER_ROMAN={1:"I",2:"II",3:"III",4:"IV",5:"V",6:"VI",7:"VII",8:"VIII",9:"IX",10:"X"}
EXTRACTION_TIER_RGB={1:(120,210,255),2:(100,255,170),3:(255,220,90),4:(255,130,230),5:(255,95,95),6:(190,120,255),7:(80,230,255),8:(255,170,80),9:(255,90,190),10:(220,220,255)}
def extraction_item_tier(item_id, default_rarity=None):
    if item_id in EXTRACTION_ITEM_TIER_DB: return max(1,min(10,int(EXTRACTION_ITEM_TIER_DB[item_id])))
    return {"common":1,"uncommon":2,"rare":3,"epic":4,"legendary":5}.get(str(default_rarity or "common").lower(),1)
def extraction_item_tier_meta(item_id):
    r=EXTRACTION_ITEM_DB.get(item_id,{}).get("rarity"); t=extraction_item_tier(item_id,r)
    return {"tier":t,"roman":EXTRACTION_TIER_ROMAN.get(t,str(t)),"rgb":list(EXTRACTION_TIER_RGB.get(t,EXTRACTION_TIER_RGB[1]))}
def extraction_item_display(item_id):
    i=EXTRACTION_ITEM_DB.get(item_id,{}); m=extraction_item_tier_meta(item_id)
    return {"id":item_id,"name":i.get("name",item_id),"rarity":i.get("rarity","common"),**m,"label":f"{i.get('name',item_id)}  {m['roman']}"}
for _eid,_edata in EXTRACTION_ITEM_DB.items():
    _m=extraction_item_tier_meta(_eid); _edata.update({"tier":_m["tier"],"tier_roman":_m["roman"],"tier_rgb":_m["rgb"]})
@app.route('/api/extraction/item-display/<item_id>', methods=['GET'])
def api_extraction_item_display(item_id):
    return jsonify({"st":"ok","item":extraction_item_display(item_id)})
