#   1) "พัสดุระเบิด": ถ้าไอเทมระเบิด (frag_grenade / c4_charge / frag_mine) อยู่ใน
#      กระเป๋า (EXTRACTION_RAIDS[uid]["carry"]) ของผู้เล่นตอนที่ผู้เล่นคนนั้น "ตาย
#      หรือล้มลง" (pawn hp เหลือ 0 -> alive=False ไม่ว่าจะตายเพราะโดนยิง หรือเหตุ
#      อื่นเช่นตกที่สูง/fall damage) ไอเทมระเบิดทุกชิ้นในกระเป๋าจะถูก "จุดชนวน
#      อัตโนมัติ" ทันที ณ ตำแหน่งที่ตาย เป็นวงระเบิด (AOE) ใส่ทุกคนที่อยู่ในระยะ
#      รวมถึงคนที่วิ่งเข้ามาใกล้จุดนั้นด้วย (เช่นมาเก็บของ) แล้วไอเทมนั้นจะถูกเผา
#      ทิ้งออกจากกระเป๋า (ระเบิดไปแล้ว ไม่มีตกให้คนอื่นเก็บ)
#   2) "เลขดาเมจลอยกลางอากาศ + คิลฟีดบอก assist": ทุกครั้งที่ยิงโดนศัตรู (hook เข้า
#      @sio.on('player_shoot') เดิม) ระบบจะบันทึกดาเมจสะสมของแต่ละคนที่เคยตี
#      เป้าหมายนั้นไว้ (DAMAGE_CONTRIBUTIONS) แล้ว broadcast event 'damage_number'
#      (ดาเมจ, ตำแหน่ง x/y, ใครตี, เพื่อนร่วมทีมหรือศัตรู) ให้ client เอาไปแสดงเป็น
#      ตัวเลขลอยเหนือหัวเป้าหมาย พอเป้าหมายตาย จะสรุปเป็น 'kill_feed' บอกว่าใครปิด
#      จ๊อบ (killer) + ใครช่วยตี (assists พร้อมยอดดาเมจของแต่ละคน ไม่ว่าจะเป็นเพื่อน
#      ร่วมทีมหรือคนอื่นที่กำจัดมาก็ตาม) แล้วจึงค่อยไปจุดชนวนพัสดุระเบิดต่อจากข้อ 1
# ทั้งหมดตัดสินที่ backend (server-authoritative) ผูกกับ PLAYER_PAWNS / PLAYERS /
# EXTRACTION_RAIDS / EXTRACTION_ITEM_DB ที่มีอยู่แล้วในไฟล์ ไม่แก้โครงสร้างเดิม
# ==========================================================================

# --- ไอเทมระเบิดที่ใช้กับระบบ death-drop (เพิ่มเข้า EXTRACTION_ITEM_DB เดิม แบบไม่ทับของเก่า) ---
EXTRACTION_ITEM_DB.setdefault("frag_grenade", {"name": "ระเบิดสังหาร (Frag Grenade)", "rarity": "rare", "value": 150, "weight": 0.6})
EXTRACTION_ITEM_DB.setdefault("c4_charge", {"name": "ระเบิด C4", "rarity": "epic", "value": 300, "weight": 1.0})
EXTRACTION_ITEM_DB.setdefault("frag_mine", {"name": "กับระเบิดสังหาร (Mine)", "rarity": "uncommon", "value": 100, "weight": 0.8})

# --- [Vent Breach] เครื่องมืองัด/ตัด (ใช้กับตะแกรง/ท่อ ไม่หมดเมื่อใช้) เพิ่มเข้า item DB + loot table เดิม ไม่ทับของเก่า ---
EXTRACTION_ITEM_DB.setdefault("crowbar", {"name": "ชะแลง", "rarity": "common", "value": 40, "weight": 2.0})
EXTRACTION_ITEM_DB.setdefault("hammer", {"name": "ค้อนปอนด์", "rarity": "common", "value": 45, "weight": 3.0})
EXTRACTION_ITEM_DB.setdefault("bolt_cutter", {"name": "คีมตัดเหล็ก", "rarity": "uncommon", "value": 90, "weight": 2.5})
# น้ำหนักสุ่มเจอในกล่อง (ปรับได้ตรงนี้ — เลขน้อย = หายาก) ; C4/Frag ก็ใส่ไว้ต่ำ ๆ ไม่งั้นจะไม่มีทางได้ของมาใช้
VENT_LOOT_ADDITIONS = {
    "warehouse": [("crowbar", 6), ("hammer", 5), ("bolt_cutter", 4), ("frag_grenade", 2), ("c4_charge", 1)],
    "office":    [("crowbar", 3), ("bolt_cutter", 2)],
    "lab":       [("bolt_cutter", 3), ("frag_grenade", 1), ("c4_charge", 1)],
}
for _vtbl, _vitems in VENT_LOOT_ADDITIONS.items():
    _vcur = EXTRACTION_LOOT_TABLES.setdefault(_vtbl, [])
    for _vit in _vitems:
        if not any(x[0] == _vit[0] for x in _vcur):
            _vcur.append(_vit)

# item_id -> ค่าดาเมจที่จุดศูนย์กลางระเบิด + รัศมี AOE (หน่วยเดียวกับพิกัด x/y ในเกม)
DEATH_DROP_EXPLOSIVE_STATS = {
    "frag_grenade": {"damage": 70, "radius": 6.0},
    "c4_charge":    {"damage": 130, "radius": 9.0},
    "frag_mine":    {"damage": 55, "radius": 5.0},
}

PLAYER_TEAM = {}            # uid -> team_id (ใช้แยกเพื่อนร่วมทีม/ศัตรู สำหรับ kill-feed + damage_number)
PLAYER_DISPLAY_NAME = {}    # uid -> ชื่อที่โชว์ (fallback เป็น uid ถ้าไม่เคยตั้ง) — ใช้พิมพ์ชื่อผู้ฆ่าลงบนป้าย
PLAYER_RANK_TIER = {}       # uid -> แรงค์ปัจจุบันของผู้เล่นคนนั้น หนึ่งใน RANK_TIERS_ORDER (D..SS) fallback "D"
DAMAGE_CONTRIBUTIONS = {}   # target_sid -> {attacker_uid: {"dmg": รวมสะสม, "last_ts": เวลาล่าสุด, "is_teammate": bool}}
DEATH_EXPLOSION_LOG = []    # log การระเบิดหลังตายล่าสุด (ไว้ตรวจสอบ/self-test/แสดงผลย้อนหลัง)
KILL_FEED_LOG = []          # log สรุปผลการฆ่าล่าสุด (killer/assists) ไว้แสดง overlay คิลฟีด
# --- [NEW] ป้ายด็อกแท็กที่ "ตกอยู่กับศพ" ให้ไปขนศพแล้วเก็บเอง (แทนที่จะให้ client
# เรียก /api/territory/bounty/report_dogtag รายงานตัวเลขเองแบบเดิม ซึ่งไม่มีการเช็ค
# กับผลการต่อสู้จริงเลย ใครก็ยิง POST มั่วๆ เอาป้ายแรงค์ SS ฟรีได้โดยไม่เคยฆ่าใคร)
# ตอนนี้ป้ายจะถูกสร้างขึ้นจริงที่ backend ตอน resolve_kill_feed() ตัดสินว่าใครตาย
# พร้อมพิมพ์ "ชื่อผู้ฆ่า" ลงบนป้ายเลย เผื่อผู้เล่นไม่ถนัดดูคิลฟีดที่มุมจอด้านบน จะได้
# ไปขนศพแล้วดูป้ายที่ติดอยู่กับศพได้โดยตรง ต้องเดินไปเก็บ (loot) เองถึงจะได้เข้าคลัง
# กันการโกงรายงานป้ายมั่วๆ อย่างที่เดิมเป็น
CORPSE_DOGTAGS = {}         # target_sid -> ป้ายด็อกแท็กที่ตกอยู่กับศพ (ดูโครงสร้างใน resolve_kill_feed)
DEATH_EXPLOSION_LOG_MAXLEN = 200
KILL_FEED_LOG_MAXLEN = 200
CORPSE_DOGTAGS_MAXLEN = 500


def _is_teammate(uid_a, uid_b):
    """เพื่อนร่วมทีมกันไหม (ใช้บอกว่า damage_number/kill_feed รายการนี้เป็น friendly หรือศัตรู)"""
    if not uid_a or not uid_b or uid_a == uid_b:
        return uid_a == uid_b
    ta, tb = PLAYER_TEAM.get(uid_a), PLAYER_TEAM.get(uid_b)
    return ta is not None and ta == tb


def _display_name(uid):
    """ชื่อที่จะพิมพ์ลงบนป้ายด็อกแท็ก/คิลฟีด — ถ้าไม่เคยตั้งชื่อไว้ (ผ่าน /api/combat/name/set)
    fallback เป็น uid ตรงๆ ไปก่อน"""
    if not uid:
        return "ไม่ทราบชื่อ"
    return PLAYER_DISPLAY_NAME.get(uid, uid)


def _get_rank_tier(uid):
    """แรงค์ปัจจุบันของผู้เล่น (ตั้งผ่าน /api/combat/rank-tier/set) ใช้กำหนดว่าป้ายที่หล่นจะ
    เป็นแบบไหน (D..SS ตาม NAME_CARD_ANIMATION_BY_RANK) fallback เป็น "D" ถ้าไม่เคยตั้ง"""
    return PLAYER_RANK_TIER.get(uid, "D")


def record_damage_number(attacker_sid, target_sid, dmg, x=None, y=None, weapon=None):
    """เรียกทุกครั้งที่ยิงโดนเป้าหมาย (hit=True) — สะสมดาเมจของ attacker ใส่ target
    ไว้ใช้สรุป assist ตอนตาย แล้ว broadcast 'damage_number' ให้ client ขึ้นตัวเลข
    ดาเมจลอยกลางอากาศเหนือหัวเป้าหมาย ณ ตำแหน่งที่โดนยิง (ทั้งของตัวเองและเพื่อนร่วมทีม)"""
    attacker_uid = PLAYERS.get(attacker_sid, {}).get("uid") or attacker_sid
    target_uid = PLAYERS.get(target_sid, {}).get("uid") or target_sid
    target_pawn = PLAYER_PAWNS.get(target_sid, {})
    px = x if x is not None else target_pawn.get("x", 0.0)
    py = y if y is not None else target_pawn.get("y", 0.0)
    teammate = _is_teammate(attacker_uid, target_uid)

    bucket = DAMAGE_CONTRIBUTIONS.setdefault(target_sid, {})
    entry = bucket.setdefault(attacker_uid, {"dmg": 0, "last_ts": 0.0, "is_teammate": teammate})
    entry["dmg"] += int(dmg)
    entry["last_ts"] = time.time()
    entry["is_teammate"] = teammate  # เผื่อสลับทีมกลางเกม
    if weapon:
        entry["weapon"] = str(weapon)[:40]   # [AEC kill-feed] อาวุธล่าสุดที่ใช้ยิง (โชว์ไอคอนในแถบคิลฟี)

    payload = {
        "target_sid": target_sid, "target_uid": target_uid,
        "attacker_uid": attacker_uid, "dmg": int(dmg), "x": px, "y": py,
        "is_teammate": teammate,   # true = เพื่อนร่วมทีมยิงโดน (friendly-fire damage number)
        "hp_left": target_pawn.get("hp"),
    }
    # โชว์ตัวเลขดาเมจให้ทั้งคนยิงเห็น (บนหัวศัตรู) และตัวเป้าหมายเห็น (โดนเท่าไหร่)
    sio.emit('damage_number', payload, room=attacker_sid)
    if target_sid != attacker_sid:
        sio.emit('damage_number', payload, room=target_sid)
    return payload


def _explode_carry_item(uid, item_id, qty, cx, cy, cause):
    """จุดชนวนไอเทมระเบิด 1 ชนิด (qty ชิ้น) ที่เคยอยู่ในกระเป๋า ณ จุดที่ตาย (cx,cy)
    ทำ AOE damage ใส่ pawn ที่ยังไม่ตายทุกคนที่อยู่ในระยะรัศมี — รวมถึงเพื่อนร่วมทีม
    ของเจ้าของกระเป๋าเอง หรือใครก็ตามที่เดินเข้ามาใกล้จุดนั้น (ไม่จำกัดว่าต้องเป็นคนที่
    ฆ่าเจ้าของกระเป๋า) ดาเมจจะลดทอนตามระยะห่างจากจุดระเบิด (falloff)"""
    stats = DEATH_DROP_EXPLOSIVE_STATS.get(item_id)
    if not stats or qty <= 0:
        return None
    dmg_each, radius = stats["damage"], stats["radius"]
    hits = []
    for sid, pawn in list(PLAYER_PAWNS.items()):
        if not pawn.get("alive", True):
            continue
        d = _dist(cx, cy, pawn.get("x", 0.0), pawn.get("y", 0.0))
        if d <= radius:
            falloff = max(0.15, 1.0 - (d / radius))
            total_dmg = int(dmg_each * falloff) * qty
            pawn["hp"] = max(0, pawn["hp"] - total_dmg)
            if pawn["hp"] == 0:
                pawn["alive"] = False
            hits.append({"sid": sid, "uid": PLAYERS.get(sid, {}).get("uid") or sid,
                         "dmg": total_dmg, "hp_left": pawn["hp"], "dist": round(d, 2)})
    event = {
        "owner_uid": uid, "item_id": item_id, "qty": qty, "x": cx, "y": cy,
        "radius": radius, "cause": cause, "hits": hits, "ts": time.time(),
    }
    DEATH_EXPLOSION_LOG.append(event)
    if len(DEATH_EXPLOSION_LOG) > DEATH_EXPLOSION_LOG_MAXLEN:
        del DEATH_EXPLOSION_LOG[:len(DEATH_EXPLOSION_LOG) - DEATH_EXPLOSION_LOG_MAXLEN]
    sio.emit('death_explosion', event)  # broadcast ให้ทุกคนเห็นเอฟเฟกต์ระเบิดตรงจุดตาย
    for h in hits:
        if h["sid"] in PLAYER_PAWNS:
            sio.emit('you_were_hit', {"by": f"{item_id}(death_drop)", "hp": h["hp_left"]}, room=h["sid"])
    # Vent Breach bridge: แรงระเบิดทำลายตะแกรงช่องระบายอากาศ/สายแขวนท่อในรัศมีด้วย (ไม่ทำให้ระเบิดเดิมพังถ้าโมดูล vent ไม่ได้โหลด)
    _vent_boom = globals().get("vmax_vent_apply_explosion")
    if callable(_vent_boom):
        try:
            _vent_boom(uid, cx, cy, 1.0, radius, (dmg_each / 100.0) * min(max(1, int(qty)), 5))
        except Exception:
            pass
    return event


def trigger_death_explosive_dropcall(target_sid, cause="killed"):
    """[ฟีเจอร์หลักที่ขอ] เรียกทันทีที่ผู้เล่นตาย/ล้มลง (pawn alive=False) ไม่ว่าจะ
    ตายเพราะอะไรก็ตาม: เช็คกระเป๋า (EXTRACTION_RAIDS[uid]['carry']) ว่ามีไอเทมระเบิด
    ชนิดไหนอยู่บ้าง แล้วจุดชนวนทุกชนิดที่ตำแหน่งที่ตาย จากนั้นเผาไอเทมนั้นทิ้งออกจาก
    กระเป๋า (ระเบิดไปแล้ว ไม่ตกให้คนอื่นเก็บ) คืนรายการที่ระเบิดไปทั้งหมด"""
    pawn = PLAYER_PAWNS.get(target_sid)
    uid = PLAYERS.get(target_sid, {}).get("uid") or target_sid
    if not pawn:
        return []
    cx, cy = pawn.get("x", 0.0), pawn.get("y", 0.0)
    raid = EXTRACTION_RAIDS.get(uid)
    if not raid or not raid.get("carry"):
        return []
    carry = raid["carry"]
    exploded = []
    for item_id in list(carry.keys()):
        if item_id in DEATH_DROP_EXPLOSIVE_STATS:
            qty = carry.pop(item_id)
            ev = _explode_carry_item(uid, item_id, qty, cx, cy, cause)
            if ev:
                exploded.append(ev)
    return exploded


def _spawn_corpse_dogtag(target_sid, target_uid, killer, cause):
    """[NEW] สร้างป้ายด็อกแท็กจริงๆ ไว้ "ตกอยู่กับศพ" ณ ตำแหน่งที่ตาย พร้อมพิมพ์ชื่อผู้ฆ่า
    ลงบนป้ายไปเลย (killer_name) — ถ้าไม่มีคนยิง (ตายจากล้ม/fall damage เอง) จะขึ้นว่า
    "ไม่ทราบผู้สังหาร (เสียชีวิตจากเหตุอื่น)" แทน ป้ายนี้ต้องมีคนไป loot ที่ศพเอง
    ผ่าน /api/combat/corpse/loot_dogtag ถึงจะได้เข้าคลัง bounty จริง (เดิม client รายงาน
    ตัวเลขเองตรงๆ ผ่าน /api/territory/bounty/report_dogtag ซึ่งไม่มีการตรวจสอบใดๆ)"""
    pawn = PLAYER_PAWNS.get(target_sid, {})
    rank_tier = _get_rank_tier(target_uid)
    killer_uid = killer["uid"] if killer else None
    tag = {
        "tag_id": uuid.uuid4().hex[:12],
        "target_sid": target_sid,
        "victim_uid": target_uid, "victim_name": _display_name(target_uid),
        "killer_uid": killer_uid,
        "killer_name": _display_name(killer_uid) if killer_uid else "ไม่ทราบผู้สังหาร (เสียชีวิตจากเหตุอื่น)",
        "rank_tier": rank_tier, "cause": cause,
        "x": pawn.get("x", 0.0), "y": pawn.get("y", 0.0),
        "died_at": time.time(), "looted": False, "looted_by": None, "looted_at": None,
    }
    CORPSE_DOGTAGS[target_sid] = tag
    if len(CORPSE_DOGTAGS) > CORPSE_DOGTAGS_MAXLEN:
        # ตัดศพเก่าสุดทิ้งถ้าล้น (เรียงตามเวลาตาย) กันโตไม่รู้จบ
        oldest_sid = min(CORPSE_DOGTAGS, key=lambda k: CORPSE_DOGTAGS[k]["died_at"])
        if oldest_sid != target_sid:
            del CORPSE_DOGTAGS[oldest_sid]
    sio.emit('corpse_dogtag_dropped', tag)  # แจ้งทุกคนว่ามีป้ายให้ไปเก็บที่จุดนี้
    return tag


def resolve_kill_feed(target_sid, cause="killed"):
    """สรุปผลตอนผู้เล่นตาย: อ่านดาเมจสะสมของทุกคนที่เคยตี target (DAMAGE_CONTRIBUTIONS)
    แยกเป็น killer (ดาเมจสะสมสูงสุด) + assists (คนอื่นที่ช่วยตี ไม่ว่าจะเป็นเพื่อนร่วมทีม
    ของ target เองหรือคนที่กำจัดฝั่งตรงข้ามก็ตาม) broadcast 'kill_feed' ให้ทุกคนเห็น (พร้อม
    ชื่อจริงของ killer เผื่อใครไม่ถนัดดูคิลฟีดบนจอ จะได้ไปขนศพดูป้ายที่ตกอยู่กับศพแทนได้)
    แล้วจึงสร้างป้ายด็อกแท็กติดกับศพ + จุดชนวนพัสดุระเบิดในกระเป๋าของ target ต่อทันที"""
    target_uid = PLAYERS.get(target_sid, {}).get("uid") or target_sid
    bucket = DAMAGE_CONTRIBUTIONS.pop(target_sid, {})
    contributors = [
        {"uid": u, "name": _display_name(u), "dmg": v["dmg"], "is_teammate": v["is_teammate"]}
        for u, v in bucket.items() if u != target_uid
    ]
    contributors.sort(key=lambda c: c["dmg"], reverse=True)
    killer = contributors[0] if contributors else None
    assists = contributors[1:]
    dogtag = _spawn_corpse_dogtag(target_sid, target_uid, killer, cause)
    exploded = trigger_death_explosive_dropcall(target_sid, cause=cause)
    vmax_gunsmith_snapshot(target_uid)   # [NEW] ตาย -> จำชุดแต่งปืนที่ใส่อยู่เป็น "แต่งรอบที่แล้ว"

    result = {
        "target_uid": target_uid, "target_sid": target_sid, "cause": cause,
        "killer": killer, "assists": assists, "dogtag": dogtag,
        "exploded_items": [{"item_id": e["item_id"], "qty": e["qty"], "hits": len(e["hits"])} for e in exploded],
        "ts": time.time(),
    }
    KILL_FEED_LOG.append(result)
    if len(KILL_FEED_LOG) > KILL_FEED_LOG_MAXLEN:
        del KILL_FEED_LOG[:len(KILL_FEED_LOG) - KILL_FEED_LOG_MAXLEN]
    sio.emit('kill_feed', result)
    return result


def kill_player(target_sid, cause="unknown", attacker_uid=None):
    """บังคับให้ pawn ตายจากสาเหตุใดก็ได้ที่ไม่ใช่การยิง (เช่นตกที่หน้าผา/fall damage,
    ไฟไหม้, จมน้ำ ฯลฯ = 'ล้มลง' ตามที่ขอ) แล้วรันสรุปคิลฟีด + จุดชนวนพัสดุระเบิดใน
    กระเป๋าอัตโนมัติเหมือนตายจากโดนยิงทุกประการ กันตายซ้ำ (resolve ซ้ำ) ถ้าตายไปแล้ว"""
    pawn = PLAYER_PAWNS.get(target_sid)
    if not pawn:
        return None
    was_alive = pawn.get("alive", True)
    pawn["hp"] = 0
    pawn["alive"] = False
    if attacker_uid:
        bucket = DAMAGE_CONTRIBUTIONS.setdefault(target_sid, {})
        bucket.setdefault(attacker_uid, {"dmg": 0, "last_ts": time.time(), "is_teammate": False})
    if not was_alive:
        return None
    return resolve_kill_feed(target_sid, cause=cause)


@app.route('/api/combat/fall_death', methods=['POST'])
def api_combat_fall_death():
    """ผู้เล่น 'ล้มลง' ตายจากเหตุที่ไม่ใช่โดนยิง (ตกที่สูง/fall damage เป็นค่าเริ่มต้น)
    body: {sid, cause?} — ยัง trigger ระบบพัสดุระเบิดอัตโนมัติในกระเป๋าเหมือนกันทุกประการ"""
    data = request.get_json(silent=True) or {}
    sid = str(data.get("sid") or "")
    cause = str(data.get("cause") or "fall_damage")
    if not sid or sid not in PLAYER_PAWNS:
        return jsonify({"st": "error", "msg": "ไม่พบผู้เล่น (sid) นี้ในสนามรบ"}), 400
    result = kill_player(sid, cause=cause)
    return jsonify({"st": "ok", "msg": "ผู้เล่นล้มลงเสียชีวิต — เช็คพัสดุระเบิดในกระเป๋าแล้ว", "result": result})


@app.route('/api/combat/team/set', methods=['POST'])
def api_combat_team_set():
    """ตั้งทีมของผู้เล่น (ใช้แยกเพื่อนร่วมทีม/ศัตรูสำหรับ damage_number + kill_feed)
    body: {uid, team}"""
    data = request.get_json(silent=True) or {}
    uid = str(data.get("uid") or "guest")
    team = data.get("team")
    PLAYER_TEAM[uid] = team
    return jsonify({"st": "ok", "uid": uid, "team": team})


@app.route('/api/combat/name/set', methods=['POST'])
def api_combat_name_set():
    """ตั้งชื่อที่โชว์ของผู้เล่น (ใช้พิมพ์ลงบนป้ายด็อกแท็ก/คิลฟีด) body: {uid, name}"""
    data = request.get_json(silent=True) or {}
    uid = str(data.get("uid") or "guest")
    name = str(data.get("name") or uid).strip() or uid
    PLAYER_DISPLAY_NAME[uid] = name
    return jsonify({"st": "ok", "uid": uid, "name": name})


@app.route('/api/combat/rank-tier/set', methods=['POST'])
def api_combat_rank_tier_set():
    """ตั้งแรงค์ปัจจุบันของผู้เล่น (D..SS ตาม RANK_TIERS_ORDER) ใช้กำหนดว่าป้ายด็อกแท็ก
    ที่หล่นจากคนนี้ตอนตายจะเป็นแรงค์ไหน/มีเอฟเฟกต์แบบไหน body: {uid, tier}"""
    data = request.get_json(silent=True) or {}
    uid = str(data.get("uid") or "guest")
    tier = str(data.get("tier") or "D").strip().upper()
    if tier not in RANK_TIERS_ORDER:
        return jsonify({"st": "error", "msg": f"แรงค์ไม่ถูกต้อง ต้องเป็นหนึ่งใน {RANK_TIERS_ORDER}"}), 400
    PLAYER_RANK_TIER[uid] = tier
    return jsonify({"st": "ok", "uid": uid, "tier": tier})


@app.route('/api/combat/corpse/peek', methods=['GET'])
def api_combat_corpse_peek():
    """?sid= -> แค่ 'มอง' ป้ายด็อกแท็กที่ติดอยู่กับศพ (ดูชื่อผู้ตาย/ชื่อผู้ฆ่า/แรงค์) โดย
    ไม่เก็บ ไม่หักป้ายออก ไม่เข้าคลัง — ใช้ตอนเดินเข้าไปใกล้ศพแล้วอยากดูก่อนตัดสินใจเก็บ"""
    sid = request.args.get("sid", "")
    tag = CORPSE_DOGTAGS.get(sid)
    if not tag:
        return jsonify({"st": "error", "msg": "ไม่พบศพ/ป้ายด็อกแท็กที่จุดนี้"}), 404
    return jsonify({"st": "ok", "tag": tag})


@app.route('/api/combat/corpse/loot_dogtag', methods=['POST'])
def api_combat_corpse_loot_dogtag():
    """body: {sid, looter_uid} -> เก็บป้ายด็อกแท็กจากศพจริงๆ (ต้องเดินไปที่ศพ/ระบุ sid ของ
    ศพนั้นเอง) เก็บได้คนละครั้งเดียวต่อศพ 1 ใบ แล้วเครดิตเข้าคลัง bounty ของ looter_uid
    ที่ backend ตรงนี้เลย (ไม่ผ่าน client รายงานตัวเลขเองแบบ /api/territory/bounty/report_dogtag
    เดิมอีกต่อไป — ปิดช่องโกงรายงานป้ายแรงค์สูงๆ มั่วๆ ทั้งที่ไม่เคยฆ่าใครจริง) คืนป้ายเต็ม
    (มีชื่อผู้ฆ่าติดอยู่) + แอนิเมชั่นตอนเก็บกลับไปให้ client เล่นเอฟเฟกต์ด้วย"""
    data = request.get_json(silent=True) or {}
    sid = str(data.get("sid") or "")
    looter_uid = str(data.get("looter_uid") or "guest")
    tag = CORPSE_DOGTAGS.get(sid)
    if not tag:
        return jsonify({"st": "error", "msg": "ไม่พบศพ/ป้ายด็อกแท็กที่จุดนี้"}), 404
    if tag["looted"]:
        return jsonify({"st": "error", "msg": f"ป้ายนี้ถูกเก็บไปแล้วโดย {tag['looted_by']}"}), 400
    tag["looted"] = True
    tag["looted_by"] = looter_uid
    tag["looted_at"] = time.time()
    st = _bounty_player(looter_uid)
    st["dogtags_held"] += 1
    animation = _name_card_animation_for(tag["rank_tier"], st["dogtags_held"])
    return jsonify({"st": "ok", "msg": f"เก็บป้ายด็อกแท็กสำเร็จ — ฆ่าโดย: {tag['killer_name']}",
                    "tag": tag, "dogtags_held": st["dogtags_held"], "animation": animation})


