# ==========================================================================
# [ NEW MODULE ] TDM 4V4 — "Polygon: Gan" NO-LOADING TEAM DEATHMATCH
# --------------------------------------------------------------------------
# ตามที่ขอ: อีเวนต์โหมด 4 ปะทะ 4 (Team Deathmatch) บนแมพสไตล์โพลีกอน (low-poly) ชื่อ
# "Polygon: Gan" แบบ "no loading" — คือพอครบ 8 คน (ฝั่งละ 4) แมตช์จะเริ่มทันที ข้าม
# ขั้นตอนโหวตแมพ/แบนตัวละคร/หน้าจอโหลดแมพแบบระบบ xroom เดิมทั้งหมด (ซึ่งมีหลายเฟส
# กว่าจะเริ่มเล่นจริง) เพื่อให้ "ไม่มีจอโหลด" คั่นระหว่างเข้าคิวกับเริ่มเล่นจริง แมพเดียว
# ตายตัว ไม่มีให้โหวต/แบน จบแมตช์เมื่อฝั่งใดฝั่งหนึ่งถึงแต้มที่กำหนด (score_limit) หรือ
# หมดเวลา (time_limit_sec) — ใครแต้มเยอะกว่าชนะ (เท่ากัน = เสมอ) ทั้งหมดตัดสินที่
# backend (server-authoritative) แยกอิสระจากระบบ xroom เดิม ไม่แก้โครงสร้าง xroom
# ==========================================================================

TDM4V4_MAP = {"id": "polygon_gan", "name": "Polygon: Gan", "width": 320.0, "height": 320.0,
              "style": "low_poly", "no_loading": True}
TDM4V4_TEAM_SIZE       = int(os.environ.get("TDM4V4_TEAM_SIZE", "4"))
TDM4V4_SCORE_LIMIT     = int(os.environ.get("TDM4V4_SCORE_LIMIT", "30"))
TDM4V4_TIME_LIMIT_SEC  = int(os.environ.get("TDM4V4_TIME_LIMIT_SEC", str(10 * 60)))

TDM4V4_MATCHES = {}   # match_id -> match state (หายเมื่อ server รีสตาร์ท เหมือน XROOM_ROOMS/KILLER_MODE_MATCHES)


def _tdm4v4_room_name(match_id: str) -> str:
    return f"tdm4v4:{match_id}"


def tdm4v4_create_match(host_uid: str) -> tuple[str, dict]:
    """สร้างแมตช์ 4v4 ใหม่บนแมพ Polygon: Gan ตายตัว — host เข้าทีม 1 ให้อัตโนมัติ
    เฟสเริ่มต้นเป็น 'lobby' (รอผู้เล่นครบ 8 คน) ยังไม่ใช่ 'playing'"""
    match_id = f"tdm4v4_{uuid.uuid4().hex[:8]}"
    match = {
        "match_id": match_id,
        "map": dict(TDM4V4_MAP),
        "phase": "lobby",          # lobby -> playing -> finished (ไม่มี 'loading' คั่นกลาง)
        "teams": {1: {"uids": [], "score": 0}, 2: {"uids": [], "score": 0}},
        "team_of_uid": {},
        "score_limit": TDM4V4_SCORE_LIMIT,
        "time_limit_sec": TDM4V4_TIME_LIMIT_SEC,
        "started_at": None,
        "ends_at": None,
        "finished": False,
        "winner_team": None,       # 1, 2, หรือ None (เสมอ/ยังไม่จบ)
        "kill_log": [],
        "created_at": time.time(),
    }
    TDM4V4_MATCHES[match_id] = match
    tdm4v4_join_match(match_id, host_uid)
    return match_id, match


def tdm4v4_join_match(match_id: str, uid: str, team_no: int = None):
    """เข้าร่วมแมตช์ — ถ้าไม่ระบุ team_no หรือทีมนั้นเต็มแล้ว จะจัดให้ฝั่งที่คนน้อยกว่าอัตโนมัติ
    (auto-balance) พอครบ 4v4 (8 คน) จะเริ่มแมตช์ทันทีแบบ no-loading (ข้ามเฟสโหลดแมพ)"""
    match = TDM4V4_MATCHES.get(match_id)
    if not match:
        return False, "ไม่พบแมตช์", None
    if match["phase"] != "lobby":
        return False, "แมตช์เริ่มไปแล้ว เข้าร่วมไม่ได้", None
    if uid in match["team_of_uid"]:
        return True, "อยู่ในแมตช์นี้อยู่แล้ว", match

    t1, t2 = match["teams"][1], match["teams"][2]
    if team_no not in (1, 2) or len(match["teams"][team_no]["uids"]) >= TDM4V4_TEAM_SIZE:
        team_no = 1 if len(t1["uids"]) <= len(t2["uids"]) else 2
    if len(match["teams"][team_no]["uids"]) >= TDM4V4_TEAM_SIZE:
        return False, "ทีมเต็มแล้ว (4 คนต่อทีม)", None

    match["teams"][team_no]["uids"].append(uid)
    match["team_of_uid"][uid] = team_no
    sio.emit('tdm4v4_player_joined', {"match_id": match_id, "uid": uid, "team_no": team_no},
             room=_tdm4v4_room_name(match_id))

    if len(t1["uids"]) >= TDM4V4_TEAM_SIZE and len(t2["uids"]) >= TDM4V4_TEAM_SIZE:
        tdm4v4_start_match(match_id)
    return True, "เข้าร่วมแมตช์แล้ว", match


def tdm4v4_start_match(match_id: str):
    """เริ่มแมตช์ทันที — ตามคอนเซ็ปต์ 'no loading' จะไม่มีเฟสโหลดแมพ/รอนับถอยหลังยาวๆ
    คั่นกลาง ข้ามจาก lobby ไป playing ตรงๆ ทันทีที่ครบ 8 คน"""
    match = TDM4V4_MATCHES.get(match_id)
    if not match or match["phase"] != "lobby":
        return False, "เริ่มแมตช์ไม่ได้ (ต้องอยู่เฟส lobby เท่านั้น)", None
    now = time.time()
    match["phase"] = "playing"
    match["started_at"] = now
    match["ends_at"] = now + match["time_limit_sec"]
    sio.emit('tdm4v4_match_started', {"match_id": match_id, "map": match["map"],
                                       "teams": {str(k): list(v["uids"]) for k, v in match["teams"].items()},
                                       "no_loading": True},
             room=_tdm4v4_room_name(match_id))
    return True, "เริ่มแมตช์แล้ว (no loading)", match


def tdm4v4_record_kill(match_id: str, killer_uid: str, victim_uid: str):
    """บันทึกการฆ่า 1 ครั้งระหว่างแมตช์ — ต้องเป็นคนที่อยู่ในแมตช์เดียวกันทั้งคู่ ถ้าฆ่าข้ามทีม
    (ปกติ) ฝั่งของ killer ได้แต้ม ถ้าเป็นทีมเดียวกัน (ทีมเดียวกันฆ่ากันเอง) นับเป็น teamkill
    ไม่ให้แต้ม พอฝั่งใดถึง score_limit ก่อน จะจบแมตช์ทันที"""
    match = TDM4V4_MATCHES.get(match_id)
    if not match or match["phase"] != "playing":
        return False, "แมตช์นี้ไม่ได้กำลังเล่นอยู่", None
    kt = match["team_of_uid"].get(killer_uid)
    vt = match["team_of_uid"].get(victim_uid)
    if kt is None or vt is None:
        return False, "killer/victim ต้องอยู่ในแมตช์นี้ทั้งคู่", None

    is_teamkill = (kt == vt)
    if not is_teamkill:
        match["teams"][kt]["score"] += 1

    entry = {"killer_uid": killer_uid, "victim_uid": victim_uid, "killer_team": kt,
              "victim_team": vt, "is_teamkill": is_teamkill, "ts": time.time()}
    match["kill_log"].append(entry)
    sio.emit('tdm4v4_kill', {"match_id": match_id, **entry}, room=_tdm4v4_room_name(match_id))

    if match["teams"][kt]["score"] >= match["score_limit"] and not is_teamkill:
        tdm4v4_finish_match(match_id, reason="score_limit")
    return True, "บันทึกการฆ่าแล้ว", match


def tdm4v4_finish_match(match_id: str, reason: str = "manual"):
    """จบแมตช์ — ตัดสินผู้ชนะจากแต้มตอนจบ (เท่ากัน = เสมอ) ใช้ได้ทั้งกรณีถึง score_limit
    ก่อนเวลา หรือหมดเวลาแล้วแต้มถึงหรือไม่ถึงก็ตาม"""
    match = TDM4V4_MATCHES.get(match_id)
    if not match or match["finished"]:
        return False, "แมตช์นี้จบไปแล้วหรือไม่พบ", None
    s1, s2 = match["teams"][1]["score"], match["teams"][2]["score"]
    winner = 1 if s1 > s2 else (2 if s2 > s1 else None)
    match["phase"] = "finished"
    match["finished"] = True
    match["winner_team"] = winner
    payload = {"match_id": match_id, "reason": reason, "winner_team": winner,
               "final_score": {"1": s1, "2": s2}}
    sio.emit('tdm4v4_match_ended', payload, room=_tdm4v4_room_name(match_id))
    return True, "จบแมตช์แล้ว", match


def tdm4v4_tick_all():
    """เรียกทุก tick จาก loop หลัก (tele_loop) — เช็คแมตช์ที่กำลังเล่นอยู่ว่าหมดเวลาหรือยัง
    ถ้าหมดเวลาแล้วยังไม่จบ ให้ปิดแมตช์ทันทีตามแต้มปัจจุบัน"""
    now = time.time()
    for match_id, match in list(TDM4V4_MATCHES.items()):
        if match["phase"] == "playing" and match.get("ends_at") and now >= match["ends_at"]:
            tdm4v4_finish_match(match_id, reason="time_limit")


@app.route('/api/tdm4v4/create', methods=['POST'])
def api_tdm4v4_create():
    data = request.get_json(silent=True) or {}
    uid = str(data.get("uid") or P.get("uid") or "guest")
    match_id, match = tdm4v4_create_match(uid)
    return jsonify({"st": "ok", "match_id": match_id, "match": match})


@app.route('/api/tdm4v4/join', methods=['POST'])
def api_tdm4v4_join():
    data = request.get_json(silent=True) or {}
    uid = str(data.get("uid") or P.get("uid") or "guest")
    match_id = str(data.get("match_id", ""))
    team_no = data.get("team_no")
    ok, msg, match = tdm4v4_join_match(match_id, uid, int(team_no) if team_no in (1, 2, "1", "2") else None)
    return jsonify({"st": "ok" if ok else "error", "msg": msg, "match": match})


@app.route('/api/tdm4v4/kill', methods=['POST'])
def api_tdm4v4_kill():
    data = request.get_json(silent=True) or {}
    match_id = str(data.get("match_id", ""))
    ok, msg, match = tdm4v4_record_kill(match_id, str(data.get("killer_uid", "")),
                                        str(data.get("victim_uid", "")))
    return jsonify({"st": "ok" if ok else "error", "msg": msg, "match": match})


@app.route('/api/tdm4v4/finish', methods=['POST'])
def api_tdm4v4_finish():
    data = request.get_json(silent=True) or {}
    match_id = str(data.get("match_id", ""))
    ok, msg, match = tdm4v4_finish_match(match_id, reason=data.get("reason", "manual"))
    return jsonify({"st": "ok" if ok else "error", "msg": msg, "match": match})


@app.route('/api/tdm4v4/state')
def api_tdm4v4_state():
    match_id = request.args.get("match_id", "")
    match = TDM4V4_MATCHES.get(match_id)
    if not match:
        return jsonify({"st": "error", "msg": "ไม่พบแมตช์"}), 404
    return jsonify({"st": "ok", "match": match})


def _run_tdm4v4_selftests():
    """Self-test ของโมดูล tdm4v4_polygon_gan — เรียกด้วย:
    python3 <ไฟล์นี้> --selftest-tdm4v4"""
    c = app.test_client()
    results = []

    def check(name, cond):
        results.append((name, cond))
        print(("✅ PASS " if cond else "❌ FAIL ") + name)

    match_id, match = tdm4v4_create_match("host_u1")
    check("create_match: เฟสเริ่มต้นเป็น lobby", match["phase"] == "lobby")
    check("create_match: แมพเป็น Polygon: Gan แบบ no_loading", match["map"]["id"] == "polygon_gan"
          and match["map"]["no_loading"] is True)
    check("create_match: host เข้าทีม 1 อัตโนมัติ", match["team_of_uid"]["host_u1"] == 1)

    for i in range(2, 5):
        ok, msg, m = tdm4v4_join_match(match_id, f"u{i}")
        check(f"join: u{i} เข้าร่วมทีมอัตโนมัติสำเร็จ", ok)
    check("join: ทีม 1 มีครบ 4 คนแล้ว (auto-balance)", len(match["teams"][1]["uids"]) == 4)
    check("join: ยังไม่เริ่มเล่นตอนมีแค่ฝั่งเดียวครบ (รออีกฝั่ง)", match["phase"] == "lobby")

    for i in range(5, 9):
        tdm4v4_join_match(match_id, f"u{i}")
    check("join: ครบ 4v4 (8 คน) -> เริ่มแมตช์ทันทีแบบ no-loading (ข้าม lobby ไป playing เลย)",
          match["phase"] == "playing")
    check("start: ends_at ถูกตั้งตาม time_limit_sec", match["ends_at"] is not None)

    ok9, msg9, _ = tdm4v4_join_match(match_id, "u_late")
    check("join: เข้าไม่ได้แล้วหลังแมตช์เริ่มเล่น", ok9 is False)

    okk, msgk, _ = tdm4v4_record_kill(match_id, "host_u1", "u5")
    check("kill: ฆ่าข้ามทีมสำเร็จ ทีม 1 ได้แต้ม", okk and match["teams"][1]["score"] == 1)

    okk2, msgk2, _ = tdm4v4_record_kill(match_id, "host_u1", "u2")
    check("kill: teamkill (ทีมเดียวกัน) ไม่ได้แต้มเพิ่ม", okk2 and match["teams"][1]["score"] == 1)
    check("kill: teamkill ถูกบันทึกไว้ใน kill_log ว่า is_teamkill=True",
          match["kill_log"][-1]["is_teamkill"] is True)

    match["score_limit"] = 2
    tdm4v4_record_kill(match_id, "host_u1", "u6")
    check("kill: ถึง score_limit -> จบแมตช์ทันที (ไม่ต้องรอหมดเวลา)", match["phase"] == "finished")
    check("finish: ทีม 1 ชนะ (แต้มเยอะกว่า)", match["winner_team"] == 1)

    match_id2, match2 = tdm4v4_create_match("h2")
    match2["ends_at"] = time.time() - 1
    match2["phase"] = "playing"
    tdm4v4_tick_all()
    check("tick_all: แมตช์ที่หมดเวลาแล้วถูกปิดอัตโนมัติ", match2["phase"] == "finished")
    check("tick_all: แต้มเท่ากัน (0-0) ตอนหมดเวลา -> เสมอ (winner_team เป็น None)",
          match2["winner_team"] is None)

    r = c.post('/api/tdm4v4/create', json={"uid": "u_api_host"})
    check("POST /api/tdm4v4/create -> 200", r.status_code == 200)
    api_match_id = r.get_json()["match_id"]
    r = c.post('/api/tdm4v4/join', json={"uid": "u_api_2", "match_id": api_match_id})
    check("POST /api/tdm4v4/join -> 200", r.status_code == 200)
    r = c.get(f'/api/tdm4v4/state?match_id={api_match_id}')
    check("GET /api/tdm4v4/state -> 200", r.status_code == 200)
    r = c.get('/api/tdm4v4/state?match_id=ไม่มีจริง')
    check("GET /api/tdm4v4/state ผิด match_id -> 404", r.status_code == 404)

    print(f"\n{sum(1 for _, ok in results if ok)}/{len(results)} tests passed")
    return all(ok for _, ok in results)


