# ==========================================================================
# [ NEW MODULE ] LOADING SCREEN MINI-GAME + GAMEPLAY SHOWCASE
# --------------------------------------------------------------------------
# ตามที่ขอ 2 ระบบ:
#
# (1) แถบดาวน์โหลด + มินิเกมระหว่างโหลด — แถบโหลดผูกกับ "ตัวแปรจริง" ของระบบเสมอ ไม่ใช่
#     ตัวเลขปลอมฝั่ง frontend: ถ้าระบุ game_id จะอ่าน progress จริงจาก DOWNLOAD_QUEUE/
#     LAUNCHER_CATALOG เดิม (ระบบดาวน์โหลดเกมจริงที่มีอยู่แล้วในไฟล์นี้) ถ้าไม่ระบุ game_id
#     จะใช้ progress ที่ถูก report เข้ามาจริงผ่าน /api/loading/<sid>/tick (เช่น หน้าเว็บนับ
#     asset ที่โหลดเสร็จจริงแล้วส่งเข้ามา) มินิเกมเป็นเกมกระโดดหลบสิ่งกีดขวางสไตล์ Chrome-Dino
#     (canvas 2D ธรรมดา ไม่มี asset รูปภาพ/เสียงให้โหลดเพิ่ม ไม่กินทรัพยากรเครื่องเพิ่ม) พอโหลด
#     ครบ 100% เกมจะหยุดทันทีและเด้ง popup สรุปคะแนนสั้นๆ (ตัวเลือกเสริมที่ขอ) ก่อนพาไปหน้าหลัก
#     อัตโนมัติ (กันคนเจ็บใจโดนตัดจบกะทันหัน) คะแนนที่ดีที่สุดเซฟไว้ฝั่ง backend จริง (ไม่ใช่แค่
#     localStorage ฝั่ง client)
#
# (2) โซนโชว์วีดีโอเกมเพลย์ — วางคู่กับมินิเกม: มินิเกมอยู่ฝั่งซ้าย วีดีโอเกมเพลย์อยู่ฝั่งขวา มีปุ่ม
#     ลูกศร (ซ้าย/ขวา) ไว้เลื่อนดูวีดีโอเกมเพลย์ตัวอื่นในลิสต์ (GAMEPLAY_SHOWCASE_VIDEOS) —
#     ลิงก์วีดีโอในลิสต์เป็น placeholder ตัวอย่างเฉยๆ เหมือนแนวทางเดียวกับ EXTERNAL_STORE_URL/
#     EXTERNAL_DOWNLOAD_URL เดิมในไฟล์นี้ ต้องแก้เป็นลิงก์วีดีโอจริงของคุณก่อนใช้งานจริง
#     (รองรับทั้งลิงก์ .mp4 ตรงๆ และลิงก์ YouTube embed)
# ==========================================================================

LOADING_SESSIONS = {}   # session_id -> {session_id, game_id, progress, total, label, created_at, done}

LOADING_MINIGAME_SCORES = {}   # uid -> คะแนนสูงสุดที่เคยทำได้ (server-authoritative, ไม่ใช่ localStorage)

# [ placeholder ] แก้ url ตรงนี้เป็นลิงก์วีดีโอเกมเพลย์จริงของคุณก่อนใช้งาน (.mp4 ตรงๆ หรือ
# ลิงก์ YouTube embed เช่น https://www.youtube.com/embed/VIDEO_ID) — thumbnail เป็นออปชัน
GAMEPLAY_SHOWCASE_VIDEOS = [
    {"id": "v1", "title": "ตัวอย่างเกมเพลย์ 1", "url": "https://example.com/videos/gameplay1.mp4", "thumbnail": ""},
    {"id": "v2", "title": "ตัวอย่างเกมเพลย์ 2", "url": "https://example.com/videos/gameplay2.mp4", "thumbnail": ""},
    {"id": "v3", "title": "ตัวอย่างเกมเพลย์ 3", "url": "https://example.com/videos/gameplay3.mp4", "thumbnail": ""},
]

# [ placeholder ] โลโก้เล็กมุมซ้ายล่างในกรอบมินิเกม (สี่เหลี่ยมเล็กๆ ตามที่ขอ) — ใส่ url รูปโลโก้
# จริงของคุณตรงนี้ (เช่น "/static/logo_anti.png") ถ้าปล่อยว่างไว้จะโชว์ตัวอักษรย่อ "ANTI" แทน
CORNER_LOGO_URL = ""


def loading_session_create(total: float = 100.0, label: str = "กำลังโหลดข้อมูล...", game_id: str = None):
    """สร้าง session แถบโหลดใหม่ — ถ้าใส่ game_id จะผูกเข้ากับระบบดาวน์โหลดเกมจริง (LAUNCHER_CATALOG
    / DOWNLOAD_QUEUE) ที่มีอยู่แล้วในไฟล์นี้ทันที ไม่ต้องอัปเดต progress เองอีก"""
    session_id = f"load_{uuid.uuid4().hex[:8]}"
    LOADING_SESSIONS[session_id] = {
        "session_id": session_id, "game_id": game_id,
        "progress": 0.0, "total": float(total) if total else 100.0,
        "label": label, "created_at": time.time(), "done": False,
    }
    return session_id, LOADING_SESSIONS[session_id]


def loading_session_state(session_id: str):
    """คืนเปอร์เซ็นต์โหลดจริงตอนนี้ — ถ้า session ผูกกับ game_id จะอ่านค่าจาก DOWNLOAD_QUEUE/
    LAUNCHER_CATALOG โดยตรง (ตัวแปรจริงของระบบดาวน์โหลดเกม ไม่ใช่เลขจำลอง) ถ้าไม่ได้ผูก game_id
    จะคำนวณจาก progress/total ที่ถูก report เข้ามาเองผ่าน loading_session_tick()"""
    s = LOADING_SESSIONS.get(session_id)
    if not s:
        return None
    if s["game_id"]:
        g = LAUNCHER_CATALOG.get(s["game_id"])
        d = next((d for d in DOWNLOAD_QUEUE if d["game_id"] == s["game_id"]), None)
        if g and g.get("installed"):
            pct = 100.0
        elif d and d.get("total"):
            pct = min(100.0, (d["progress"] / d["total"]) * 100.0)
        else:
            pct = 0.0
    else:
        pct = 100.0 if s["total"] <= 0 else min(100.0, (s["progress"] / s["total"]) * 100.0)
    s["done"] = pct >= 100.0
    return {"session_id": session_id, "label": s["label"], "percent": round(pct, 1), "done": s["done"]}


def loading_session_tick(session_id: str, loaded, total=None):
    """ให้ frontend (หรือระบบอื่นฝั่ง backend) รายงานจำนวน asset ที่โหลดเสร็จจริงเข้ามา — ใช้ตอน
    session ไม่ได้ผูกกับ game_id ของ launcher (เช่น loading หน้าเว็บทั่วไปที่นับ asset เอง)"""
    s = LOADING_SESSIONS.get(session_id)
    if not s:
        return False, "ไม่พบ session"
    try:
        s["progress"] = float(loaded)
        if total is not None:
            s["total"] = float(total)
    except (TypeError, ValueError):
        return False, "ค่า loaded/total ไม่ถูกต้อง"
    return True, "อัปเดตแล้ว"


def loading_minigame_submit_score(uid: str, score) -> int:
    """เซฟคะแนนมินิเกมฝั่ง backend จริง — เก็บเฉพาะคะแนนสูงสุดที่เคยทำได้ คืนค่าคะแนนสูงสุด
    ล่าสุดหลังบันทึก (ไม่ว่ารอบนี้จะทำสถิติใหม่ได้หรือไม่)"""
    try:
        score = max(0, int(score))
    except (TypeError, ValueError):
        score = 0
    best = LOADING_MINIGAME_SCORES.get(uid, 0)
    if score > best:
        LOADING_MINIGAME_SCORES[uid] = score
        best = score
    return best


@app.route('/api/loading/create', methods=['POST'])
def api_loading_create():
    data = request.get_json(silent=True) or {}
    session_id, s = loading_session_create(total=data.get("total", 100.0),
                                            label=data.get("label", "กำลังโหลดข้อมูล..."),
                                            game_id=data.get("game_id") or None)
    return jsonify({"st": "ok", "session_id": session_id, "state": loading_session_state(session_id)})


@app.route('/api/loading/<session_id>/state')
def api_loading_state(session_id):
    state = loading_session_state(session_id)
    if not state:
        return jsonify({"st": "error", "msg": "ไม่พบ session"}), 404
    return jsonify({"st": "ok", **state})


@app.route('/api/loading/<session_id>/tick', methods=['POST'])
def api_loading_tick(session_id):
    data = request.get_json(silent=True) or {}
    ok, msg = loading_session_tick(session_id, data.get("loaded", 0), data.get("total"))
    if not ok:
        return jsonify({"st": "error", "msg": msg}), 404
    return jsonify({"st": "ok", "state": loading_session_state(session_id)})


@app.route('/api/loading-minigame/score', methods=['POST'])
def api_loading_minigame_score_submit():
    data = request.get_json(silent=True) or {}
    uid = str(data.get("uid") or P.get("uid") or "guest")
    best = loading_minigame_submit_score(uid, data.get("score", 0))
    return jsonify({"st": "ok", "best_score": best})


@app.route('/api/loading-minigame/score')
def api_loading_minigame_score_get():
    uid = str(request.args.get("uid") or P.get("uid") or "guest")
    return jsonify({"st": "ok", "best_score": LOADING_MINIGAME_SCORES.get(uid, 0)})


@app.route('/api/loading/showcase-videos')
def api_loading_showcase_videos():
    return jsonify({"st": "ok", "videos": GAMEPLAY_SHOWCASE_VIDEOS})


