# ==========================================
# [ 2K3. Reward Redemption Board — บอร์ดการ์ดแลกรับรางวัล (สุ่มเปิดช่องต่อเนื่อง) ]
# อ้างอิงสกรีนที่ส่งมา: กระดานช่องรางวัลที่ล็อกอยู่ทั้งหมด กดสุ่ม 1 ครั้งเพื่อ "จับรางวัล"
# แล้วเปิดเผยช่องถัดไปในลำดับให้ทันที (ไม่ใช่สุ่มตำแหน่งข้ามกระดาน) — ใช้ "สิทธิ์จับรางวัล"
# (roll ticket) เป็นตัวหักออกทีละ 1 ต่อการสุ่ม 1 ครั้ง ทุกครั้งที่ครบ 1 แถว (ROW_SIZE ช่อง)
# จะได้โบนัสพิเศษเพิ่มอีกก้อนนึงนอกเหนือจากรางวัลของช่องนั้นเอง เพื่อจูงใจให้สุ่มต่อเป็นแถว
# หมายเหตุสำคัญ: ระบบนี้เป็นกลไก "สุ่มของ/ล็อกซีเควนซ์" ไม่ใช่ระบบพนัน — สิทธิ์จับรางวัล
# (roll ticket) ที่ใช้หักในที่นี้ตั้งใจให้ได้มาจากการเล่นเกม/ภารกิจ/อีเวนต์เท่านั้น
# (แจกผ่าน grant_roll_tickets()) "ไม่ขายด้วยเงินจริงตรง ๆ" ในไฟล์นี้ — ถ้าจะเปิดให้ซื้อสิทธิ์
# ด้วยเงินจริงในอนาคต ควรตรวจข้อกำหนดกฎหมายเรื่อง loot box / การเปิดเผยอัตราสุ่มของแต่ละตลาด
# ก่อนเปิดใช้จริงเสมอ (ดู note ของโมดูล gacha_loot_box_pity ด้านบนในไฟล์นี้)
# ==========================================

REWARD_BOARD_ROW_SIZE = 6  # จำนวนช่องต่อแถว (ให้ตรงกับภาพอ้างอิง 5-6 ช่อง/แถว)

# game_id -> board_id -> {"cells": [ {reward...}, ... ], "row_bonus": {reward...}}
REWARD_BOARD_CATALOG = {
    "fighting": {
        "kamona_research_card": {
            "label": "การ์ดวิจัยการ์ดแลกรับรางวัล",
            "cells": [
                {"kind": "credits", "amount": 200, "label": "เครดิต 200"},
                {"kind": "item", "name": "กล่องสมบัติทอง", "qty": 1, "label": "กล่องสมบัติทอง x1"},
                {"kind": "credits", "amount": 600, "label": "เครดิต 600"},
                {"kind": "item", "name": "ตั๋วจับรางวัล", "qty": 100, "label": "ตั๋วจับรางวัล x100"},
                {"kind": "credits", "amount": 150, "label": "เครดิต 150"},
                {"kind": "item", "name": "มีด", "qty": 1, "label": "มีดสั้น x1"},
                {"kind": "credits", "amount": 400, "label": "เครดิต 400"},
                {"kind": "item", "name": "กล่องสมบัติทอง", "qty": 1, "label": "กล่องสมบัติทอง x1"},
                {"kind": "credits", "amount": 300, "label": "เครดิต 300"},
                {"kind": "knife_skin", "skin_id": None, "label": "สุ่มสกินมีดคอสเมติก 1 ชิ้น"},
            ],
            # ได้รางวัลพิเศษเพิ่มทุกครั้งที่สุ่มครบ REWARD_BOARD_ROW_SIZE ช่องพอดี
            "row_bonus": {"kind": "credits", "amount": 500, "label": "โบนัสครบแถว: เครดิต 500"},
        },
    },
}


def _rewardboard_get(game_id: str, board_id: str):
    return REWARD_BOARD_CATALOG.get(game_id, {}).get(board_id)


# (uid, game_id, board_id) -> {"revealed": int, "tickets": int}
REWARD_BOARD_STATE = {}


def _rewardboard_key(uid: str, game_id: str, board_id: str) -> str:
    return f"{uid}::{game_id}::{board_id}"


def _rewardboard_state(uid: str, game_id: str, board_id: str) -> dict:
    return REWARD_BOARD_STATE.setdefault(
        _rewardboard_key(uid, game_id, board_id), {"revealed": 0, "tickets": 0}
    )


def _rewardboard_apply_reward(uid: str, game_id: str, reward: dict) -> dict:
    """มอบรางวัล 1 ก้อนให้ผู้เล่นจริง — ใช้ตัวแปรกลางเดียวกับระบบร้านค้า (P / WALLET /
    GAME_INVENTORY) ที่มีอยู่แล้วในไฟล์นี้ เพื่อให้ของรางวัลใช้ได้จริงในเกมทันที"""
    kind = reward.get("kind")
    out = dict(reward)
    if kind == "credits":
        P["credits"] = P.get("credits", 0) + reward["amount"]
        WALLET["balance"] = P["credits"]
    elif kind == "item":
        inv = GAME_INVENTORY.setdefault(_gk(uid, game_id), {})
        inv[reward["name"]] = inv.get(reward["name"], 0) + reward.get("qty", 1)
    elif kind == "knife_skin":
        # แจกสกินมีดคอสเมติกแบบสุ่ม 1 ชิ้นจากแคตตาล็อกร้านค้า (2K4 ด้านล่าง) โดยตรง
        # ไม่ต้องผ่านการซื้อ — ใช้กลไกปลดล็อกเดียวกับตอนซื้อในร้าน
        pool = list(KNIFE_SKIN_CATALOG.keys())
        skin_id = random.choice(pool) if pool else None
        if skin_id:
            _knife_skin_unlock(uid, game_id, skin_id)
            out["skin_id"] = skin_id
            out["label"] = f"ได้สกินมีด: {KNIFE_SKIN_CATALOG[skin_id]['name']}"
    return out


def rewardboard_status(uid: str, game_id: str, board_id: str) -> dict:
    board = _rewardboard_get(game_id, board_id)
    if not board:
        return {"st": "error", "msg": "ไม่พบกระดานรางวัลนี้"}
    st = _rewardboard_state(uid, game_id, board_id)
    cells = board["cells"]
    return {
        "st": "ok",
        "label": board["label"],
        "row_size": REWARD_BOARD_ROW_SIZE,
        "total_cells": len(cells),
        "revealed": st["revealed"],
        "tickets_remaining": st["tickets"],
        "cells": [
            (cells[i] if i < st["revealed"] else {"locked": True})
            for i in range(len(cells))
        ],
        "complete": st["revealed"] >= len(cells),
    }


def rewardboard_grant_tickets(uid: str, game_id: str, board_id: str, amount: int) -> dict:
    """แจกสิทธิ์จับรางวัลให้ผู้เล่น — เรียกจากตอนจบภารกิจ/อีเวนต์/เควสในเกม (ไม่ใช่จุดขาย
    ด้วยเงินจริง) amount ต้องเป็นจำนวนเต็มบวกเท่านั้น"""
    if not _rewardboard_get(game_id, board_id):
        return {"st": "error", "msg": "ไม่พบกระดานรางวัลนี้"}
    if amount <= 0:
        return {"st": "error", "msg": "จำนวนสิทธิ์ต้องมากกว่า 0"}
    st = _rewardboard_state(uid, game_id, board_id)
    st["tickets"] += int(amount)
    return {"st": "ok", "tickets_remaining": st["tickets"]}


def rewardboard_roll(uid: str, game_id: str, board_id: str) -> dict:
    board = _rewardboard_get(game_id, board_id)
    if not board:
        return {"st": "error", "msg": "ไม่พบกระดานรางวัลนี้"}
    st = _rewardboard_state(uid, game_id, board_id)
    cells = board["cells"]
    if st["revealed"] >= len(cells):
        return {"st": "error", "msg": "เปิดครบทุกช่องแล้ว", **rewardboard_status(uid, game_id, board_id)}
    if st["tickets"] <= 0:
        return {"st": "error", "msg": "สิทธิ์จับรางวัลไม่พอ (จำนวนคงเหลือ: 0)"}

    st["tickets"] -= 1
    idx = st["revealed"]
    reward = _rewardboard_apply_reward(uid, game_id, cells[idx])
    cells[idx] = reward  # เก็บผลจริงที่ออก (เผื่อ knife_skin สุ่มมาแล้วอยากให้ค่าคงที่ตอนดูย้อนหลัง)
    st["revealed"] += 1

    row_bonus_awarded = None
    if st["revealed"] % REWARD_BOARD_ROW_SIZE == 0 and "row_bonus" in board:
        row_bonus_awarded = _rewardboard_apply_reward(uid, game_id, board["row_bonus"])

    try:
        sio.emit("reward_board_rolled", {"uid": uid, "game_id": game_id, "board_id": board_id,
                                          "cell_index": idx, "reward": reward,
                                          "row_bonus": row_bonus_awarded})
    except Exception:
        pass

    return {"st": "ok", "reward": reward, "row_bonus": row_bonus_awarded,
            **rewardboard_status(uid, game_id, board_id)}


@app.route('/api/rewardboard/<game_id>/<board_id>/status', methods=['GET'])
def api_rewardboard_status(game_id, board_id):
    uid = request.args.get('uid') or P.get('uid', 'VMAX-OP-01')
    result = rewardboard_status(uid, game_id, board_id)
    return jsonify(result), (200 if result.get('st') == 'ok' else 404)


@app.route('/api/rewardboard/<game_id>/<board_id>/roll', methods=['POST'])
@require_auth_toggleable
def api_rewardboard_roll(game_id, board_id):
    uid = getattr(request, 'vmax_uid', None) or resolve_uid() or P.get('uid', 'VMAX-OP-01')
    return jsonify(rewardboard_roll(uid, game_id, board_id))


@app.route('/api/rewardboard/<game_id>/<board_id>/grant_tickets', methods=['POST'])
@require_auth_toggleable
def api_rewardboard_grant_tickets(game_id, board_id):
    """จุดเรียกจากฝั่งระบบเกม (จบเควส/อีเวนต์) เพื่อแจกสิทธิ์จับรางวัล — ไม่ใช่ endpoint
    สำหรับผู้เล่นเรียกเองเพื่อเติมสิทธิ์ฟรี ควรผูก auth/permission ระดับ server-side
    ของแต่ละโปรเจกต์เองก่อนเปิดใช้จริง"""
    uid = getattr(request, 'vmax_uid', None) or resolve_uid() or P.get('uid', 'VMAX-OP-01')
    body = request.get_json(force=True, silent=True) or {}
    amount = int(body.get('amount', 1))
    return jsonify(rewardboard_grant_tickets(uid, game_id, board_id, amount))


VMAX_MODULES["reward_redemption_board"] = {
    "name": "บอร์ดการ์ดแลกรับรางวัล (สุ่มเปิดช่องต่อเนื่อง + โบนัสครบแถว)",
    "level": "advanced",
    "category": "economy",
    "desc": "กระดานช่องรางวัลล็อกไว้ทั้งหมด ใช้ 'สิทธิ์จับรางวัล' (roll ticket) หักทีละ 1 ต่อการสุ่ม "
            "1 ครั้งเพื่อเปิดเผยช่องถัดไปตามลำดับ (ไม่สุ่มตำแหน่ง) มอบรางวัลจริงทันที (เครดิต/ไอเทม/"
            "สกินมีดคอสเมติกแบบสุ่ม) ผ่านตัวแปรกลางเดียวกับร้านค้า (P/WALLET/GAME_INVENTORY) ครบทุก "
            f"{REWARD_BOARD_ROW_SIZE} ช่องได้โบนัสพิเศษเพิ่ม สิทธิ์จับรางวัลตั้งใจให้แจกจากการเล่นเกม/"
            "ภารกิจเท่านั้น ไม่ผูกกับการซื้อด้วยเงินจริงตรง ๆ ในไฟล์นี้",
    "routes": ["/api/rewardboard/<game_id>/<board_id>/status",
               "/api/rewardboard/<game_id>/<board_id>/roll",
               "/api/rewardboard/<game_id>/<board_id>/grant_tickets"],
    "socket_events": ["reward_board_rolled"],
}


# ==========================================
# [ 2K4. Knife Skin Cash Shop — สกินมีดคอสเมติก ขายด้วยเงินจริง (baht) ]
# อ้างอิงสกรีนร้านค้าที่ส่งมา (บันเดิลมีดคอสเมติกหลายเล่มขายรวมชุด, ตั้งราคาแยกตามชุด)
# ใช้ genre "fighting" เดิม (ดู GENRE_PROFILES ด้านบน) ต่อยอดจากไอเทม "มีด" ที่มีอยู่แล้ว
# เป็นสกินมีด "คอสเมติกล้วน" (cosmetic-only ไม่กระทบค่าพลัง/ดาเมจ) ผู้เล่นซื้อทีละเล่ม
# หรือซื้อ "ชุดครบเซ็ต" (ทั้ง 3 เล่ม) ในราคาที่ถูกกว่าซื้อแยก ต้องเทียบราคากับตลาด/ผู้ให้บริการ
# จ่ายเงินจริงเอง (App Store/Google Play/เกตเวย์ที่ผูกในระบบ) ก่อนเสมอ — endpoint ที่นี่
# ถือว่า "จ่ายเงินจริงผ่านแล้ว" เหมือนกับ shop_purchase()/boxskin_buy_mystery_supply() เดิม
# ในไฟล์นี้ (ตรวจ receipt กับผู้ให้บริการจริงก่อนเรียก mark เป็น purchased เสมอในโปรดักชัน)
# ==========================================

# ราคาตัวอย่างที่ตั้งไว้ในไฟล์นี้ (แก้ได้ตรงนี้จุดเดียว): เล่มละ 50 บาท / ชุดครบ 3 เล่ม 100 บาท
KNIFE_SKIN_PRICE_SINGLE_BAHT = 50
KNIFE_SKIN_BUNDLE_PRICE_BAHT = 100

KNIFE_SKIN_CATALOG = {
    "knife_skin_ember":   {"skin_id": "knife_skin_ember",   "name": "มีดคอสเมติก - เปลวเพลิง",   "tier": "red",   "color": "#ff4d2e"},
    "knife_skin_frost":   {"skin_id": "knife_skin_frost",   "name": "มีดคอสเมติก - น้ำแข็ง",     "tier": "blue",  "color": "#4fd7ff"},
    "knife_skin_venom":   {"skin_id": "knife_skin_venom",   "name": "มีดคอสเมติก - พิษเขียว",    "tier": "green", "color": "#4dff7a"},
}

# เพิ่มรายการเข้าไปในร้านค้าแนวต่อสู้เดิม (GENRE_PROFILES["fighting"]["shop_items"]) — ซื้อทีละเล่ม
# ราคา KNIFE_SKIN_PRICE_SINGLE_BAHT บาท/เล่ม หรือซื้อชุดครบ 3 เล่มในราคา KNIFE_SKIN_BUNDLE_PRICE_BAHT บาท
GENRE_PROFILES["fighting"]["shop_items"].extend([
    {"id": f"skin_{sid}", "name": s["name"], "price": KNIFE_SKIN_PRICE_SINGLE_BAHT,
     "currency": "baht", "grant": {"knife_skin": sid}}
    for sid, s in KNIFE_SKIN_CATALOG.items()
] + [
    {"id": "skin_bundle_all3", "name": "บันเดิลมีดคอสเมติกครบเซ็ต (3 เล่ม)",
     "price": KNIFE_SKIN_BUNDLE_PRICE_BAHT, "currency": "baht",
     "grant": {"knife_skin_bundle": list(KNIFE_SKIN_CATALOG.keys())}},
])

# "uid::game_id::skin_id" -> {"purchased": bool, "equipped": bool}
KNIFE_SKIN_PROGRESS = {}


def _knife_skin_key(uid, game_id, skin_id):
    return f"{uid}::{game_id}::{skin_id}"


def _knife_skin_unlock(uid, game_id, skin_id):
    key = _knife_skin_key(uid, game_id, skin_id)
    prog = KNIFE_SKIN_PROGRESS.setdefault(key, {"purchased": False, "equipped": False})
    prog["purchased"] = True
    return prog


def knife_skin_status(uid, game_id):
    out = []
    for sid, s in KNIFE_SKIN_CATALOG.items():
        prog = KNIFE_SKIN_PROGRESS.get(_knife_skin_key(uid, game_id, sid), {"purchased": False, "equipped": False})
        out.append({**s, "purchased": prog["purchased"], "equipped": prog["equipped"]})
    return {"st": "ok", "skins": out, "price_single_baht": KNIFE_SKIN_PRICE_SINGLE_BAHT,
            "price_bundle_baht": KNIFE_SKIN_BUNDLE_PRICE_BAHT}


def knife_skin_equip(uid, game_id, skin_id):
    key = _knife_skin_key(uid, game_id, skin_id)
    prog = KNIFE_SKIN_PROGRESS.get(key)
    if not prog or not prog["purchased"]:
        return {"st": "error", "msg": "ยังไม่ได้ซื้อสกินมีดนี้"}
    for k, p in KNIFE_SKIN_PROGRESS.items():  # สวมได้ทีละเล่ม ถอดเล่มอื่นของเกมเดียวกันก่อน
        if k.startswith(f"{uid}::{game_id}::"):
            p["equipped"] = False
    prog["equipped"] = True
    return {"st": "ok", "msg": f"สวมสกินมีด {KNIFE_SKIN_CATALOG[skin_id]['name']} แล้ว", "skin_id": skin_id}


@app.route('/api/knifeskin/<game_id>/list', methods=['GET'])
def api_knife_skin_list(game_id):
    uid = request.args.get('uid') or P.get('uid', 'VMAX-OP-01')
    return jsonify(knife_skin_status(uid, game_id))


@app.route('/api/knifeskin/<game_id>/equip/<skin_id>', methods=['POST'])
@require_auth_toggleable
def api_knife_skin_equip(game_id, skin_id):
    uid = getattr(request, 'vmax_uid', None) or resolve_uid() or P.get('uid', 'VMAX-OP-01')
    if skin_id not in KNIFE_SKIN_CATALOG:
        return jsonify({"st": "error", "msg": "ไม่พบสกินมีดนี้"}), 404
    return jsonify(knife_skin_equip(uid, game_id, skin_id))


