def _payment_room_name(uid: str) -> str:
    return f"payment:{uid}"


def _payment_set_status(order: dict, status: str):
    order["status"] = status
    try:
        sio.emit("payment_order_status", {"order_id": order["order_id"], "status": status,
                                           "item_id": order["item_id"]},
                 room=_payment_room_name(order["uid"]))
    except Exception:
        pass


def _find_baht_shop_item(game_id: str, item_id: str):
    """หา shop item ที่ currency == 'baht' จาก genre profile ของเกมนั้น (ครอบคลุมทั้ง
    topup_small/topup_large เดิม และสกินมีด [2K4] ที่เพิ่มเข้าไปในลิสต์เดียวกัน)"""
    profile = _genre_profile(game_id)
    item = next((i for i in profile["shop_items"] if i["id"] == item_id), None)
    if not item or item.get("currency") != "baht":
        return None
    return item


def _omise_request(method: str, path: str, **kwargs):
    """เรียก Omise API ด้วย Basic Auth (secret key เป็น username, password เว้นว่าง)
    ตามสเปกของ Omise ทุก request ไป Omise ต้องผ่านฟังก์ชันนี้จุดเดียว"""
    return requests.request(method, f"{OMISE_API_BASE}{path}",
                             auth=(OMISE_SECRET_KEY, ""), timeout=15, **kwargs)


OMISE_PAYMENT_METHOD_INFO = {
    "promptpay": {"omise": "promptpay", "label": "PromptPay"},
    "truemoney": {"omise": "truemoney_jumpapp", "label": "TrueMoney"},
    "wechat_pay": {"omise": "wechat_pay", "label": "WeChat Pay"},
    "alipay": {"omise": "alipay", "label": "Alipay"},
    "card": {"omise": "credit_card", "label": "บัตรเครดิต/เดบิต"},
}

# Omise Dashboard is where account payment methods/capabilities are managed.
OMISE_DASHBOARD_URL = "https://dashboard.omise.co/"
OMISE_SUPPORT_URL = "https://support.omise.co/"


def _omise_capabilities():
    """อ่าน payment_methods ที่บัญชี Omise เปิดให้ใช้จาก Capability API."""
    resp = _omise_request("GET", "/capability")
    resp.raise_for_status()
    payload = resp.json() or {}
    return set(payload.get("payment_methods") or [])


def _payment_setup_payload(method: str, reason: str = ""):
    """เมื่อช่องทางยังไม่เปิด — ส่งลิงก์ให้ client เด้งไปหน้าเปิดใช้ใน Omise"""
    info = OMISE_PAYMENT_METHOD_INFO.get(method, {})
    # หน้าในแอปเรา: มีปุ่มกดแล้วพาไป Dashboard
    open_path = "/payment/enable/%s" % method
    setup_api = "/api/payment/omise/setup/%s" % method
    return {
        "st": "payment_method_not_enabled",
        "code": "payment_method_not_enabled",
        "method": method,
        "label": info.get("label", method),
        "reason": reason or f"Omise ยังไม่ได้เปิดช่องทาง {info.get('label', method)} สำหรับบัญชีนี้",
        "omise_payment_method": info.get("omise"),
        "omise_dashboard_url": OMISE_DASHBOARD_URL,
        "omise_support_url": OMISE_SUPPORT_URL,
        # client เอา open_url ไป window.open / location.href ได้ทันที
        "open_url": open_path,
        "setup_api": setup_api,
        "auto_open": True,
        "button_label_th": "เปิดใช้ %s ใน Omise Dashboard" % info.get("label", method),
        "action": "กดปุ่มเพื่อเปิด Omise Dashboard แล้วเปิด Payment Method จากนั้นกลับมาลองชำระอีกครั้ง",
    }


@app.route('/api/payment/omise/capabilities', methods=['GET'])
@require_auth_toggleable
def api_payment_omise_capabilities():
    """ตรวจช่องทางที่บัญชี Omise เปิดใช้งานอยู่ และคืนลิงก์ไป Dashboard."""
    if not OMISE_SECRET_KEY:
        return jsonify({"st": "error", "msg": "ยังไม่ได้ตั้ง VMAX_OMISE_SECRET_KEY",
                        "omise_dashboard_url": OMISE_DASHBOARD_URL}), 503
    try:
        enabled = _omise_capabilities()
    except requests.RequestException as e:
        return jsonify({"st": "error", "msg": f"อ่านความสามารถของบัญชี Omise ไม่สำเร็จ: {e}",
                        "omise_dashboard_url": OMISE_DASHBOARD_URL}), 502
    return jsonify({
        "st": "ok",
        "enabled_payment_methods": sorted(enabled),
        "methods": {k: {**v, "enabled": v["omise"] in enabled}
                    for k, v in OMISE_PAYMENT_METHOD_INFO.items()},
        "keys": {
            "secret_key_set": bool(OMISE_SECRET_KEY),
            "public_key_set": bool(OMISE_PUBLIC_KEY),
            "webhook_secret_set": bool(OMISE_WEBHOOK_SECRET),
            "public_key_prefix": (OMISE_PUBLIC_KEY[:10] + "…") if OMISE_PUBLIC_KEY else None,
            "secret_key_is_test": str(OMISE_SECRET_KEY).startswith("skey_test"),
        },
        "promptpay_ready": "promptpay" in enabled,
        "truemoney_ready": ("truemoney_jumpapp" in enabled) or ("truemoney" in enabled),
        "omise_dashboard_url": OMISE_DASHBOARD_URL,
        "omise_support_url": OMISE_SUPPORT_URL,
        "setup_hint": [
            "1) ใส่ VMAX_OMISE_SECRET_KEY + VMAX_OMISE_PUBLIC_KEY + VMAX_OMISE_WEBHOOK_SECRET",
            "2) เปิด PromptPay (และ TrueMoney) ใน Omise Dashboard → Settings → Payment Methods",
            "3) ตั้ง Webhook URL = https://<โดเมน>/api/payment/omise/webhook",
            "4) เรียก GET /api/payment/omise/capabilities อีกรอบเพื่อยืนยัน",
        ],
    })


@app.route('/api/payment/omise/setup/<method>', methods=['GET'])
@require_auth_toggleable
def api_payment_omise_setup(method):
    """พาเจ้าของระบบไป Omise Dashboard เพื่อจัดการ Payment Method."""
    if method not in OMISE_PAYMENT_METHOD_INFO:
        return jsonify({"st": "error", "msg": "ไม่รู้จักช่องทางชำระเงินนี้"}), 404
    # redirect ตรงไป Dashboard (Omise ไม่มี deep-link เปิด method เดียวแบบ API —
    # ต้องกดเปิดในหน้า Payment Methods เอง)
    return redirect(OMISE_DASHBOARD_URL)


