# ==========================================
# [ 2K7. Treasure Map Hunt — ร่องรอยการล่าสัตว์ (แผนที่สมบัติ 3 ขั้นตอน) ]
# อ้างอิงสกรีนที่ส่งมา: 1) เข้าสู่แผนที่โดยใช้แผนที่สมบัติ 2) ค้นหาที่เก็บของสมบัติ ณ จุดที่ทำเครื่องหมาย
# ไว้ในแผนที่ (ภาพวาดมือมีวงกลม/กากบาทชี้ตำแหน่ง) 3) นำของที่เจอไปส่งมอบ/ใช้แผนที่เพื่อรับรางวัลจริง
# แยกอิสระจาก [2K6] แต่รับ "แผนที่สมบัติ" มาจากด่านสุดท้ายของ [2K6] ได้โดยตรง (เรียก
# treasuremap_grant() เองก็ได้เช่นกัน เช่นจากกล่องล็อกอิน/อีเวนต์อื่น)
# ==========================================

# คลังตำแหน่ง/รางวัลที่จะสุ่มออกให้ตอนเปิดแผนที่ — เพิ่ม/แก้ได้อิสระ
TREASURE_MAP_LOCATION_POOL = {
    "fighting": [
        {"map_id": "map_pier_container", "location_name": "ท่าเรือ - หลังตู้คอนเทนเนอร์ริมสะพานเหล็ก",
         "hint": "มองหาตู้คอนเทนเนอร์สีน้ำตาลใต้สะพานเหล็กโค้ง วงกลมสีแดงทำเครื่องหมายไว้ชัดเจน",
         "reward": {"kind": "item", "name": "หุ่นจิ๋วสะสม (FigurineUtopia)", "qty": 1,
                    "label": "หุ่นจิ๋วสะสมรุ่นพิเศษ x1"}},
    ],
}

# (uid, game_id) -> {"status": "none"/"unopened"/"active"/"found"/"delivered", "map_id": str|None}
TREASURE_MAP_STATE = {}


def _treasuremap_key(uid: str, game_id: str) -> str:
    return f"{uid}::{game_id}"


def _treasuremap_state(uid: str, game_id: str) -> dict:
    return TREASURE_MAP_STATE.setdefault(_treasuremap_key(uid, game_id), {"status": "none", "map_id": None})


def _treasuremap_current(uid: str, game_id: str):
    st = _treasuremap_state(uid, game_id)
    pool = TREASURE_MAP_LOCATION_POOL.get(game_id, [])
    return next((m for m in pool if m["map_id"] == st.get("map_id")), None)


def treasuremap_grant(uid: str, game_id: str) -> dict:
    """มอบกล่องแผนที่สมบัติ 1 ใบ (ยังไม่เปิด) — สุ่มตำแหน่งไว้ล่วงหน้าแต่ผู้เล่นยังไม่เห็น
    จนกว่าจะกดเปิดผ่าน treasuremap_open()"""
    pool = TREASURE_MAP_LOCATION_POOL.get(game_id, [])
    if not pool:
        return {"st": "error", "msg": "เกมนี้ยังไม่ได้ตั้งค่าตำแหน่งแผนที่สมบัติไว้"}
    picked = random.choice(pool)
    st = _treasuremap_state(uid, game_id)
    st["status"] = "unopened"
    st["map_id"] = picked["map_id"]
    return {"st": "ok", "msg": "ได้รับกล่องแผนที่สมบัติแล้ว (ยังไม่เปิด)"}


def treasuremap_status(uid: str, game_id: str) -> dict:
    st = _treasuremap_state(uid, game_id)
    current = _treasuremap_current(uid, game_id)
    out = {"st": "ok", "status": st["status"]}
    if current and st["status"] != "unopened":
        out["location_name"] = current["location_name"]
        out["hint"] = current["hint"]
    return out


def treasuremap_open(uid: str, game_id: str) -> dict:
    st = _treasuremap_state(uid, game_id)
    if st["status"] != "unopened":
        return {"st": "error", "msg": "ไม่มีกล่องแผนที่สมบัติที่ยังไม่เปิดอยู่ในตอนนี้"}
    current = _treasuremap_current(uid, game_id)
    if not current:
        return {"st": "error", "msg": "ข้อมูลแผนที่ผิดพลาด กรุณาขอแผนที่ใหม่"}
    st["status"] = "active"
    return {"st": "ok", "location_name": current["location_name"], "hint": current["hint"],
            "msg": "เปิดแผนที่สมบัติแล้ว — เดินทางไปยังจุดที่ทำเครื่องหมายไว้ในเกมเพื่อค้นหาของ"}


def treasuremap_found(uid: str, game_id: str) -> dict:
    """เรียกตอนผู้เล่นเดินไปถึงพิกัด/ค้นเจอของสมบัติในเกมจริง (ฝั่งเกมเป็นคนเช็คระยะ/ตำแหน่ง
    เองแล้วค่อยยิงมาเรียก endpoint นี้ยืนยัน — เซิร์ฟเวอร์นี้ไม่ได้ตรวจพิกัดในเกมเอง)"""
    st = _treasuremap_state(uid, game_id)
    if st["status"] != "active":
        return {"st": "error", "msg": "ต้องเปิดแผนที่สมบัติ (treasuremap_open) ก่อนถึงจะค้นหาของได้"}
    st["status"] = "found"
    return {"st": "ok", "msg": "พบของสมบัติแล้ว! นำไปส่งมอบ/ใช้แผนที่เพื่อรับรางวัลได้เลย"}


def treasuremap_deliver(uid: str, game_id: str) -> dict:
    st = _treasuremap_state(uid, game_id)
    if st["status"] != "found":
        return {"st": "error", "msg": "ต้องค้นหาของสมบัติให้เจอก่อน (treasuremap_found) ถึงจะส่งมอบได้"}
    current = _treasuremap_current(uid, game_id)
    if not current:
        return {"st": "error", "msg": "ข้อมูลแผนที่ผิดพลาด"}
    reward = _rewardboard_apply_reward(uid, game_id, current["reward"])  # reuse [2K3] grant helper
    st["status"] = "delivered"
    st["map_id"] = None
    return {"st": "ok", "reward": reward, "msg": "ส่งมอบสำเร็จ ได้รับรางวัลแล้ว"}


