# ==========================================
# [ 2K8. Physical Merch Redemption — แลกของสะสมในเกมเป็น "ของจริง" ส่งถึงบ้าน ]
# สำหรับกิจกรรมแบบฟิกเกอร์กล่องจริง (เหมือนที่วางขายในห้าง) ที่ผู้เล่นสะสมของในเกม (เช่น
# "หุ่นจิ๋วสะสม (FigurineUtopia)" ที่ได้จาก [2K7] treasure map hunt) แล้วเอามาแลกเป็นพัสดุจริง
# ระบบนี้ "ไม่ได้สั่งผลิต/สั่งส่งพัสดุเองอัตโนมัติ" — เป็นแค่ตัวรับคำขอแลก + เก็บที่อยู่จัดส่ง +
# ติดตามสถานะ ให้ทีมงานฝั่งคุณ (คน จริง/ระบบคลังสินค้าจริง) เป็นคนกดอัปเดตสถานะ/เลขพัสดุเอง
# ผ่าน endpoint แอดมินที่ล็อกด้วยคีย์ต่างหาก (แบบเดียวกับ X-Sakura-Backup-Key ด้านบนในไฟล์นี้)
# ⚠️ ข้อมูลที่อยู่จัดส่ง/เบอร์โทรเป็นข้อมูลส่วนบุคคลจริง — เก็บเฉพาะเท่าที่จำเป็นต่อการจัดส่ง
# ในโปรดักชันจริงควรต่อฐานข้อมูลถาวร + เข้ารหัสข้อมูลที่อยู่ตอนเก็บ (encryption at rest) และจำกัด
# สิทธิ์คนที่เข้าถึง endpoint แอดมินให้แคบที่สุดเท่าที่จะทำได้ (ในไฟล์นี้เก็บเป็น in-memory dict
# เพื่อสาธิตโครงสร้างเท่านั้น ข้อมูลจะหายเมื่อรีสตาร์ทเซิร์ฟเวอร์ ต้องย้ายไปเก็บถาวรเองก่อนใช้จริง)
# ==========================================

MERCH_ADMIN_KEY = os.environ.get("VMAX_MERCH_ADMIN_KEY", "")

# game_id -> item_key -> {"name": ..., "requires_item": ..., "requires_qty": int, "image_hint": ...}
PHYSICAL_MERCH_CATALOG = {
    "fighting": {
        "figurine_utopia_boxed": {
            "name": "หุ่นจิ๋วสะสม FigurineUtopia (กล่องจริง แบบวางขายในห้าง)",
            "requires_item": "หุ่นจิ๋วสะสม (FigurineUtopia)",  # ต้องมีไอเทมนี้ใน GAME_INVENTORY ก่อน
            "requires_qty": 1,
        },
    },
}

MERCH_ORDER_STATUSES = ["submitted", "verified", "processing", "shipped", "delivered", "cancelled"]

# order_id -> dict รายละเอียดคำขอแลกของจริง + ที่อยู่จัดส่ง + สถานะ
PHYSICAL_MERCH_ORDERS = {}
_merch_orders_lock = threading.Lock()


def _merch_admin_key_ok(req) -> bool:
    """ตรวจ X-Merch-Admin-Key เทียบกับ env var VMAX_MERCH_ADMIN_KEY แบบ constant-time
    ถ้ายังไม่ตั้ง env นี้เลย ปิดสิทธิ์เรียก endpoint แอดมินไว้เสมอ (fail-closed)"""
    if not MERCH_ADMIN_KEY:
        return False
    supplied = req.headers.get('X-Merch-Admin-Key', '')
    return hmac.compare_digest(supplied, MERCH_ADMIN_KEY)


def merch_request_redeem(uid: str, game_id: str, item_key: str, shipping: dict) -> dict:
    catalog = PHYSICAL_MERCH_CATALOG.get(game_id, {})
    merch = catalog.get(item_key)
    if not merch:
        return {"st": "error", "msg": "ไม่พบของสะสมชิ้นนี้ในระบบแลกของจริง"}

    required_fields = ["recipient_name", "phone", "address_line1", "subdistrict",
                        "district", "province", "postal_code"]
    missing = [f for f in required_fields if not str(shipping.get(f, "")).strip()]
    if missing:
        return {"st": "error", "msg": f"กรอกที่อยู่จัดส่งไม่ครบ ขาด: {', '.join(missing)}"}

    inv = GAME_INVENTORY.setdefault(_gk(uid, game_id), {})
    have = inv.get(merch["requires_item"], 0)
    need = merch["requires_qty"]
    if have < need:
        return {"st": "error", "msg": f"ของสะสมในเกมไม่พอสำหรับแลก (มี {have}/{need}: "
                                        f"{merch['requires_item']})"}

    inv[merch["requires_item"]] -= need  # หักของสะสมเสมือนออกทันทีตอนยื่นคำขอ กันแลกซ้ำ

    order_id = f"merch_{uuid.uuid4().hex[:12]}"
    order = {
        "order_id": order_id, "uid": uid, "game_id": game_id, "item_key": item_key,
        "item_name": merch["name"], "status": "submitted", "tracking_number": None,
        "shipping": {k: str(shipping.get(k, "")).strip() for k in
                     required_fields + ["address_line2"]},
        "created_ts": time.time(), "updated_ts": time.time(),
    }
    with _merch_orders_lock:
        PHYSICAL_MERCH_ORDERS[order_id] = order

    try:
        sio.emit("merch_order_status", {"order_id": order_id, "status": "submitted"},
                 room=_payment_room_name(uid))  # ใช้ห้อง socket เดียวกับระบบชำระเงิน [2K5]
    except Exception:
        pass

    return {"st": "ok", "order_id": order_id, "msg": "ยื่นคำขอแลกของจริงสำเร็จ รอทีมงานตรวจสอบ/จัดส่ง"}


def merch_order_status(order_id: str) -> dict:
    order = PHYSICAL_MERCH_ORDERS.get(order_id)
    if not order:
        return {"st": "error", "msg": "ไม่พบคำสั่งแลกของนี้"}
    # ไม่ส่งที่อยู่เต็ม ๆ กลับไปให้ client ทั่วไป (เลี่ยงรั่ว PII ผ่าน endpoint สาธารณะ) โชว์แค่สถานะ/เลขพัสดุ
    return {"st": "ok", "order_id": order["order_id"], "item_name": order["item_name"],
            "status": order["status"], "tracking_number": order["tracking_number"],
            "updated_ts": order["updated_ts"]}


def merch_list_orders_for_uid(uid: str) -> list:
    return [merch_order_status(oid) for oid, o in PHYSICAL_MERCH_ORDERS.items() if o["uid"] == uid]


def merch_admin_update_status(order_id: str, status: str, tracking_number: str | None) -> dict:
    order = PHYSICAL_MERCH_ORDERS.get(order_id)
    if not order:
        return {"st": "error", "msg": "ไม่พบคำสั่งแลกของนี้"}
    if status not in MERCH_ORDER_STATUSES:
        return {"st": "error", "msg": f"status ต้องเป็นหนึ่งใน {MERCH_ORDER_STATUSES}"}
    order["status"] = status
    if tracking_number:
        order["tracking_number"] = tracking_number
    order["updated_ts"] = time.time()
    try:
        sio.emit("merch_order_status", {"order_id": order_id, "status": status,
                                         "tracking_number": order["tracking_number"]},
                 room=_payment_room_name(order["uid"]))
    except Exception:
        pass
    return {"st": "ok", "order": merch_order_status(order_id)}


@app.route('/api/merchredeem/<game_id>/catalog', methods=['GET'])
def api_merch_catalog(game_id):
    catalog = PHYSICAL_MERCH_CATALOG.get(game_id, {})
    return jsonify({"st": "ok", "items": [{"item_key": k, **v} for k, v in catalog.items()]})


@app.route('/api/merchredeem/<game_id>/request', methods=['POST'])
@require_auth_toggleable
def api_merch_request(game_id):
    """ยื่นคำขอแลกของสะสมในเกมเป็นของจริง body: {uid, item_key, shipping: {recipient_name,
    phone, address_line1, address_line2, subdistrict, district, province, postal_code}}"""
    uid = getattr(request, 'vmax_uid', None) or resolve_uid() or P.get('uid', 'VMAX-OP-01')
    body = request.get_json(force=True, silent=True) or {}
    item_key = body.get('item_key', '')
    shipping = body.get('shipping', {}) or {}
    return jsonify(merch_request_redeem(uid, game_id, item_key, shipping))


