@app.route('/api/merchredeem/admin/<order_id>/update_status', methods=['POST'])
def api_merch_admin_update_status(order_id):
    """endpoint สำหรับทีมงานคลังสินค้า/แอดมิน (คนจริง) กดอัปเดตสถานะพัสดุเอง — ต้องแนบ
    X-Merch-Admin-Key ให้ตรงกับ env var VMAX_MERCH_ADMIN_KEY เท่านั้น (ยังไม่ตั้ง env = ปิดใช้งาน)"""
    if not _merch_admin_key_ok(request):
        return jsonify({"st": "error", "msg": "ต้องแนบ X-Merch-Admin-Key ให้ตรงกับ env var "
                                                "VMAX_MERCH_ADMIN_KEY (ถ้ายังไม่ตั้ง env นี้ "
                                                "endpoint นี้จะถูกปิดไว้เสมอ)"}), 403
    body = request.get_json(force=True, silent=True) or {}
    status = body.get('status', '')
    tracking_number = body.get('tracking_number')
    return jsonify(merch_admin_update_status(order_id, status, tracking_number))


