# ==========================================
# [ 2K9. Figurine Collection Vitrine — ตู้โชว์/อัลบั้มของสะสมฟิกเกอร์ในเกม ]
# ต่อยอดจาก [2K7] treasure map hunt: ของสะสม (เช่น "หุ่นจิ๋วสะสม (FigurineUtopia)") ที่ได้มา
# ไม่ได้เอาไปแลกเป็นของจริง แต่เก็บไว้ "โชว์ในตู้สะสมของเกม" เป็นชุด (เช่น ชุดครบรอบ 3 ปี มี
# กี่ตัว) ดูความคืบหน้าสะสมครบเซ็ตได้ พอครบทุกตัวในชุดรับโบนัสพิเศษเพิ่ม (ไม่ได้หักของสะสม
# ออกจากคลังตอนโชว์ — แค่ "นับ" จาก GAME_INVENTORY เดิม ยังเก็บของไว้ใช้/โชว์ต่อได้เรื่อย ๆ)
# ==========================================

# game_id -> set_id -> {"label": ..., "figurines": [ชื่อไอเทมที่ต้องมีใน GAME_INVENTORY แต่ละตัว],
#                        "set_bonus": {reward...}}
FIGURINE_SET_CATALOG = {
    "fighting": {
        "utopia_3rd_anniversary": {
            "label": "ชุดหุ่นจิ๋ว FigurineUtopia ครบรอบ 3 ปี",
            "figurines": [
                "หุ่นจิ๋วสะสม (FigurineUtopia)",
                "หุ่นจิ๋วสะสม (FigurineUtopia) - รุ่นทะเลทราย",
                "หุ่นจิ๋วสะสม (FigurineUtopia) - รุ่นราตรี",
            ],
            "set_bonus": {"kind": "credits", "amount": 5000, "label": "โบนัสสะสมครบเซ็ต: เครดิต 5,000"},
        },
    },
}

# (uid, game_id, set_id) -> {"bonus_claimed": bool}
FIGURINE_VITRINE_STATE = {}


def _vitrine_key(uid: str, game_id: str, set_id: str) -> str:
    return f"{uid}::{game_id}::{set_id}"


def figurine_vitrine_status(uid: str, game_id: str, set_id: str) -> dict:
    fset = FIGURINE_SET_CATALOG.get(game_id, {}).get(set_id)
    if not fset:
        return {"st": "error", "msg": "ไม่พบชุดของสะสมนี้"}
    inv = GAME_INVENTORY.get(_gk(uid, game_id), {})
    slots = [{"name": name, "owned_qty": inv.get(name, 0)} for name in fset["figurines"]]
    complete = all(s["owned_qty"] > 0 for s in slots)
    st = FIGURINE_VITRINE_STATE.setdefault(_vitrine_key(uid, game_id, set_id), {"bonus_claimed": False})
    return {"st": "ok", "label": fset["label"], "slots": slots,
            "owned_count": sum(1 for s in slots if s["owned_qty"] > 0), "total_count": len(slots),
            "complete": complete, "bonus": fset["set_bonus"],
            "bonus_claimable": complete and not st["bonus_claimed"],
            "bonus_claimed": st["bonus_claimed"]}


def figurine_vitrine_claim_bonus(uid: str, game_id: str, set_id: str) -> dict:
    status = figurine_vitrine_status(uid, game_id, set_id)
    if status.get("st") != "ok":
        return status
    if not status["complete"]:
        return {"st": "error", "msg": "สะสมยังไม่ครบเซ็ต ยังรับโบนัสไม่ได้"}
    st = FIGURINE_VITRINE_STATE[_vitrine_key(uid, game_id, set_id)]
    if st["bonus_claimed"]:
        return {"st": "error", "msg": "รับโบนัสชุดนี้ไปแล้ว"}
    fset = FIGURINE_SET_CATALOG[game_id][set_id]
    reward = _rewardboard_apply_reward(uid, game_id, fset["set_bonus"])  # reuse [2K3] grant helper
    st["bonus_claimed"] = True
    return {"st": "ok", "reward": reward, "msg": "รับโบนัสสะสมครบเซ็ตแล้ว"}


@app.route('/api/figurinecase/<game_id>/<set_id>/status', methods=['GET'])
def api_figurinecase_status(game_id, set_id):
    uid = request.args.get('uid') or P.get('uid', 'VMAX-OP-01')
    result = figurine_vitrine_status(uid, game_id, set_id)
    return jsonify(result), (200 if result.get('st') == 'ok' else 404)


