# (uid, game_id) -> {"blurred": bool, "temp_clear_until_ts": float|None}
VIAL_BLUR_STATE = {}


def _vial_blur_key(uid: str, game_id: str) -> str:
    return f"{uid}::{game_id}"


def _vial_blur_state(uid: str, game_id: str) -> dict:
    return VIAL_BLUR_STATE.setdefault(_vial_blur_key(uid, game_id),
                                       {"blurred": False, "temp_clear_until_ts": None})


def vial_blur_status(uid: str, game_id: str) -> dict:
    """ให้ฝั่ง client เรียกเช็คว่าตอนนี้ต้องเบลอจอไหม (โพลรอบ ๆ ก็ได้ หรือเรียกทุกครั้งก่อนเรนเดอร์เฟรม)"""
    st = _vial_blur_state(uid, game_id)
    temp_clear_active = bool(st["temp_clear_until_ts"] and time.time() < st["temp_clear_until_ts"])
    return {"st": "ok", "blurred": st["blurred"],
            "should_show_blur_effect": st["blurred"] and not temp_clear_active,
            "temp_clear_seconds_left": (max(0, round(st["temp_clear_until_ts"] - time.time()))
                                         if temp_clear_active else 0)}


@app.route('/api/vialmachine/<game_id>/location', methods=['GET'])
def api_vial_machine_location(game_id):
    """ให้ UI แผนที่มาร์คตำแหน่งเครื่องผสมยา (จุดคงที่ต่อเกม)"""
    loc = MEDICINE_MACHINE_LOCATIONS.get(game_id)
    if not loc:
        return jsonify({"st": "error", "msg": "เกมนี้ยังไม่ได้ตั้งค่าตำแหน่งเครื่องผสมยาไว้"}), 404
    return jsonify({"st": "ok", **loc})


def vial_machine_insert(uid: str, game_id: str) -> dict:
    inv = GAME_INVENTORY.setdefault(_gk(uid, game_id), {})
    if inv.get(VIAL_MACHINE_BASE_ITEM, 0) <= 0:
        return {"st": "error", "msg": f"ต้องมี '{VIAL_MACHINE_BASE_ITEM}' อย่างน้อย 1 ขวดถึงจะใส่เครื่องได้"}
    inv[VIAL_MACHINE_BASE_ITEM] -= 1

    poisoned = random.random() < VIAL_MACHINE_POISON_CHANCE
    if poisoned:
        st = _vial_blur_state(uid, game_id)
        st["blurred"] = True
        st["temp_clear_until_ts"] = None  # โดนซ้ำ ล้างชั่วคราวเดิมที่เคยมีถือว่าหมดฤทธิ์ไปด้วย

    names = [v["name"] for v in VIAL_RESULT_POOL]
    weights = [v["weight"] for v in VIAL_RESULT_POOL]
    result_name = random.choices(names, weights=weights, k=1)[0]
    inv[result_name] = inv.get(result_name, 0) + 1

    out = {"st": "ok", "result_vial": result_name, "poisoned": poisoned}
    if poisoned:
        out["msg"] = ("ยาพิษพ่นใส่หน้า! ตาเริ่มมัว — ล้างหน้าด้วยน้ำเปล่าเพื่อเห็นชัดชั่วคราว หรือใช้ "
                      f"'{SPECIAL_ANTIDOTE_ITEM}' เพื่อหายขาดถาวร")
    try:
        sio.emit("vial_machine_result", {"uid": uid, "game_id": game_id, "result_vial": result_name,
                                          "poisoned": poisoned}, room=_payment_room_name(uid))
    except Exception:
        pass
    return out


@app.route('/api/vialmachine/<game_id>/insert', methods=['POST'])
@require_auth_toggleable
def api_vial_machine_insert(game_id):
    uid = getattr(request, 'vmax_uid', None) or resolve_uid() or P.get('uid', 'VMAX-OP-01')
    return jsonify(vial_machine_insert(uid, game_id))


def vial_machine_wash(uid: str, game_id: str, item_used: str) -> dict:
    inv = GAME_INVENTORY.setdefault(_gk(uid, game_id), {})
    st = _vial_blur_state(uid, game_id)
    if not st["blurred"]:
        return {"st": "error", "msg": "ตอนนี้ไม่ได้โดนพิษ ไม่ต้องล้างหน้า"}

    if item_used == SPECIAL_ANTIDOTE_ITEM:
        if inv.get(SPECIAL_ANTIDOTE_ITEM, 0) <= 0:
            return {"st": "error", "msg": f"ไม่มี '{SPECIAL_ANTIDOTE_ITEM}' ในคลัง (ต้องพกติดตัวมาด้วยล่วงหน้า)"}
        inv[SPECIAL_ANTIDOTE_ITEM] -= 1
        st["blurred"] = False
        st["temp_clear_until_ts"] = None
        return {"st": "ok", "msg": "หายขาดถาวรแล้ว", "cured_permanently": True}

    if item_used == PLAIN_WATER_ITEM:
        if inv.get(PLAIN_WATER_ITEM, 0) <= 0:
            return {"st": "error", "msg": f"ไม่มี '{PLAIN_WATER_ITEM}' ในคลัง"}
        inv[PLAIN_WATER_ITEM] -= 1
        st["temp_clear_until_ts"] = time.time() + PLAIN_WATER_TEMP_CLEAR_SECONDS
        return {"st": "ok", "cured_permanently": False,
                "temp_clear_seconds": PLAIN_WATER_TEMP_CLEAR_SECONDS,
                "msg": f"เห็นชัดขึ้นชั่วคราว {PLAIN_WATER_TEMP_CLEAR_SECONDS} วิ แล้วจะมัวกลับมาเหมือนเดิม (ยังไม่หายขาด)"}

    return {"st": "error", "msg": f"item_used ต้องเป็น '{PLAIN_WATER_ITEM}' หรือ '{SPECIAL_ANTIDOTE_ITEM}' เท่านั้น"}


@app.route('/api/vialmachine/<game_id>/wash', methods=['POST'])
@require_auth_toggleable
def api_vial_machine_wash(game_id):
    """body: {uid, item_used}"""
    uid = getattr(request, 'vmax_uid', None) or resolve_uid() or P.get('uid', 'VMAX-OP-01')
    body = request.get_json(force=True, silent=True) or {}
    return jsonify(vial_machine_wash(uid, game_id, body.get('item_used', '')))


@app.route('/api/vialmachine/<game_id>/blur_status', methods=['GET'])
def api_vial_machine_blur_status(game_id):
    uid = request.args.get('uid') or P.get('uid', 'VMAX-OP-01')
    return jsonify(vial_blur_status(uid, game_id))


def vial_machine_sell(uid: str, game_id: str, item_name: str, qty: int) -> dict:
    entry = next((v for v in VIAL_RESULT_POOL if v["name"] == item_name), None)
    if not entry:
        return {"st": "error", "msg": "ไอเทมนี้ไม่ใช่ขวดยาที่ขายได้ที่ล็อบบี้"}
    if qty <= 0:
        return {"st": "error", "msg": "qty ต้องมากกว่า 0"}
    inv = GAME_INVENTORY.setdefault(_gk(uid, game_id), {})
    have = inv.get(item_name, 0)
    if have < qty:
        return {"st": "error", "msg": f"มีไม่พอจะขาย (มี {have} ต้องการขาย {qty})"}
    inv[item_name] = have - qty
    total = entry["sell_price_credits"] * qty
    P["credits"] = P.get("credits", 0) + total
    WALLET["balance"] = P["credits"]
    return {"st": "ok", "sold_qty": qty, "credits_received": total, "credits_balance": P["credits"]}


@app.route('/api/vialmachine/<game_id>/sell', methods=['POST'])
@require_auth_toggleable
def api_vial_machine_sell(game_id):
    """ขายขวดยาที่ได้จากเครื่องหน้าล็อบบี้ body: {uid, item_name, qty}"""
    uid = getattr(request, 'vmax_uid', None) or resolve_uid() or P.get('uid', 'VMAX-OP-01')
    body = request.get_json(force=True, silent=True) or {}
    return jsonify(vial_machine_sell(uid, game_id, body.get('item_name', ''), int(body.get('qty', 1))))


