CORE_MASTERY_STATE = {}   # uid -> {"unlocked": set(...), "active": str|None,
                          #         "mission_progress": {mastery_id: int}}


def _core_mastery_player(uid: str) -> dict:
    return CORE_MASTERY_STATE.setdefault(uid, {"unlocked": set(), "active": None, "mission_progress": {}})


def _core_mastery_active_effect(uid: str) -> str | None:
    """คืน effect_key ของ Core Mastery ที่กำลังแอคทีฟอยู่ของ uid นี้ (None ถ้ายังไม่ได้เลือก)"""
    st = CORE_MASTERY_STATE.get(uid)
    if not st or not st["active"]:
        return None
    return CORE_MASTERY_DEFS.get(st["active"], {}).get("effect_key")


@app.route('/api/core_mastery/list')
def api_core_mastery_list():
    """?uid= -> รายชื่อ Core Mastery ทั้งหมด พร้อมสถานะปลดล็อก/ความคืบหน้าภารกิจ/ตัวที่แอคทีฟของผู้เล่นนี้"""
    uid = request.args.get("uid", P["uid"])
    st = _core_mastery_player(uid)
    out = []
    for mid, mdef in CORE_MASTERY_DEFS.items():
        missions_done = st["mission_progress"].get(mid, 0)
        out.append({"mastery_id": mid, "label_th": mdef["label_th"], "desc_th": mdef["desc_th"],
                    "unlock_missions": mdef["unlock_missions"], "missions_done": missions_done,
                    "missions_total": len(mdef["unlock_missions"]), "unlocked": mid in st["unlocked"],
                    "active": st["active"] == mid})
    return jsonify({"st": "ok", "masteries": out, "active": st["active"]})


@app.route('/api/core_mastery/mission_progress', methods=['POST'])
@require_auth_toggleable
def api_core_mastery_mission_progress():
    """body: {uid, mastery_id} -> เพิ่มความคืบหน้าภารกิจปลดล็อก 1 ขั้น ครบตามจำนวนที่กำหนดจะปลดล็อกอัตโนมัติ"""
    body = request.json or {}
    uid, mid = body.get("uid", P["uid"]), body.get("mastery_id", "")
    mdef = CORE_MASTERY_DEFS.get(mid)
    if not mdef:
        return jsonify({"st": "error", "msg": "ไม่พบ Core Mastery นี้"}), 400
    st = _core_mastery_player(uid)
    if mid in st["unlocked"]:
        return jsonify({"st": "error", "msg": "ปลดล็อกไปแล้ว"}), 400
    st["mission_progress"][mid] = st["mission_progress"].get(mid, 0) + 1
    unlocked_now = False
    if st["mission_progress"][mid] >= len(mdef["unlock_missions"]):
        st["unlocked"].add(mid)
        unlocked_now = True
    return jsonify({"st": "ok", "missions_done": st["mission_progress"][mid],
                    "missions_total": len(mdef["unlock_missions"]), "unlocked_now": unlocked_now})


@app.route('/api/core_mastery/activate', methods=['POST'])
@require_auth_toggleable
def api_core_mastery_activate():
    """body: {uid, mastery_id} -> ตั้งเป็น Core Mastery ที่แอคทีฟ (ต้องปลดล็อกก่อน) แอคทีฟได้ทีละ 1 อัน
    เท่านั้น สลับไปมาได้ตลอดเวลานอกแมตช์"""
    body = request.json or {}
    uid, mid = body.get("uid", P["uid"]), body.get("mastery_id", "")
    if mid not in CORE_MASTERY_DEFS:
        return jsonify({"st": "error", "msg": "ไม่พบ Core Mastery นี้"}), 400
    st = _core_mastery_player(uid)
    if mid not in st["unlocked"]:
        return jsonify({"st": "error", "msg": "ยังไม่ปลดล็อก Core Mastery นี้"}), 400
    st["active"] = mid
    return jsonify({"st": "ok", "active": mid})


# ---- ผลของ Hidden Compartment: ค้นภาชนะที่รองรับ มีโอกาสเจอช่องลับ ----
HIDDEN_COMPARTMENT_CONTAINER_TYPES = {"gym_bag", "suitcase", "storage_case"}
HIDDEN_COMPARTMENT_CHANCE = 0.20
HIDDEN_COMPARTMENT_LOOT_POOL = [
    ("Handheld Recorder", 1, 0.35), ("ทองคำแท่ง", 1, 0.20), ("นาฬิกาข้อมือหรู", 1, 0.15),
    ("ไฟล์เข้ารหัสลับ", 1, 0.10), ("เครื่องประดับล้ำค่า", 1, 0.20),
]


def _roll_hidden_compartment_loot():
    total = sum(w for _, _, w in HIDDEN_COMPARTMENT_LOOT_POOL)
    r = random.random() * total
    acc = 0.0
    for name, qty, w in HIDDEN_COMPARTMENT_LOOT_POOL:
        acc += w
        if r <= acc:
            return name, qty
    return None


@app.route('/api/loot/search_container', methods=['POST'])
@require_auth_toggleable
def api_loot_search_container():
    """body: {uid, container_type} -> ค้นภาชนะ (gym_bag/suitcase/storage_case) ถ้าผู้เล่นแอคทีฟ Core Mastery
    'ช่องลับ (Hidden Compartment)' อยู่ จะมีโอกาสเจอของมีค่าเพิ่มจากช่องลับข้างในภาชนะนั้น"""
    body = request.json or {}
    uid, container_type = body.get("uid", P["uid"]), body.get("container_type", "")
    found = None
    if (container_type in HIDDEN_COMPARTMENT_CONTAINER_TYPES
            and _core_mastery_active_effect(uid) == "hidden_compartment_search"
            and random.random() < HIDDEN_COMPARTMENT_CHANCE):
        rolled = _roll_hidden_compartment_loot()
        if rolled:
            name, qty = rolled
            inv = INVENTORY.setdefault(uid, {})
            inv[name] = inv.get(name, 0) + qty
            found = {"item": name, "qty": qty}
    return jsonify({"st": "ok", "hidden_compartment_found": found})


# ---- ผลของ Acoustic Earpads: ลดเวลาหูอื้อ/สตันจากหมวกกันกระสุนโดนกระแทก ----
ACOUSTIC_STUN_REDUCTION_PCT = 0.5   # ลดเวลาสตันลงครึ่งหนึ่งถ้าแอคทีฟมาสเทอรีนี้อยู่


@app.route('/api/combat/audio_stun', methods=['POST'])
@require_auth_toggleable
def api_combat_audio_stun():
    """body: {uid, base_stun_seconds} -> คำนวณเวลาหูอื้อ/สตันจริงหลังโดนกระแทกหมวกใส่หัว (ลดลงถ้าแอคทีฟ
    Core Mastery 'หูฟังยูเรเนียมไทเทเนียม' อยู่)"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    base = max(0.0, float(body.get("base_stun_seconds", 0)))
    reduced = _core_mastery_active_effect(uid) == "acoustic_stun_reduction"
    final = base * (1 - ACOUSTIC_STUN_REDUCTION_PCT) if reduced else base
    return jsonify({"st": "ok", "base_stun_seconds": base, "final_stun_seconds": round(final, 2),
                    "acoustic_earpads_active": reduced})


