# =====================================================================================
# [ 6zzD. Credit Support Fund — ระบบยืมเครดิตมาเล่น (อ้างอิงคลิป: "โหมด OP มีระบบยืมเงินมาเล่นแล้ว") ]
# ผู้เล่นยืมเครดิตล่วงหน้าจากกองทุนสนับสนุนมาเล่นได้ ภายในวงเงินที่ตอนแรกเริ่มไม่สูงมาก แล้ว "เติบโต" ขึ้น
# เรื่อยๆ ตามประวัติการชำระคืนจริง จนแตะเพดานวงเงินสูงสุด (CREDIT_FUND_QUOTA_CAP) การชำระคืนเกิดแบบ
# อัตโนมัติ: ทุกครั้งที่ขายของในตลาด (Supply Station / market_sell) ระบบจะหัก CREDIT_FUND_AUTO_REPAY_PCT
# ของรายได้จากการขายครั้งนั้นไปโปะหนี้ที่ค้างอยู่ก่อนเสมอ จนกว่าจะครบยอด — เมื่อไม่มีหนี้ค้างแล้วระบบจะเลิก
# หักเองโดยอัตโนมัติ (ไม่ต้องมี flag เปิด/ปิดแยก เพราะ outstanding == 0 ก็ไม่มีอะไรให้หักอยู่แล้ว) ผู้เล่นยัง
# กดโปะหนี้คืนเองด้วยมือได้ทุกเมื่อถ้าอยากเคลียร์หนี้เร็วกว่ารอขายของ — กลไกทั้งหมดเป็นเครดิตภายในเกมล้วนๆ
# ไม่เกี่ยวกับเงินจริง/การชำระเงินนอกเกมแต่อย่างใด
# =====================================================================================
CREDIT_FUND_QUOTA_CAP = 3_000_000          # เพดานวงเงินสูงสุดที่วงเงินจะเติบโตไปถึงได้
CREDIT_FUND_STARTING_LIMIT = 300_000       # วงเงินเริ่มต้นของผู้เล่นใหม่ ก่อนวงเงินจะค่อยๆ โตตามประวัติชำระคืน
CREDIT_FUND_AUTO_REPAY_PCT = 0.20          # สัดส่วนที่หักจากรายได้ขายของแต่ละครั้งไปโปะหนี้ค้างอัตโนมัติ

# uid -> state ของกองทุนสนับสนุนของผู้เล่นคนนั้น
CREDIT_FUND_STATE = {}


def _credit_fund_state(uid: str) -> dict:
    return CREDIT_FUND_STATE.setdefault(uid, {
        "credit_limit": CREDIT_FUND_STARTING_LIMIT,
        "outstanding": 0,          # ยอดหนี้ที่ยังค้างชำระอยู่ตอนนี้ ("รอการชำระคืน" ในแท็บโควตา)
        "borrowed_total": 0,       # ยอดยืมสะสมทั้งหมดตลอดกาล
        "repaid_total": 0,         # ยอดชำระคืนสะสมทั้งหมดตลอดกาล (ใช้เป็นตัวโตวงเงิน)
        "repayment_log": [],       # [{ "source", "amount_returned", "remaining_owed", "ts" }, ...]
    })


def _credit_fund_grow_limit(fund: dict, repaid_amount: int):
    """วงเงินโตขึ้นทีละนิดตามยอดที่ชำระคืนได้จริง (1:1) แต่ไม่มีวันเกินเพดาน CREDIT_FUND_QUOTA_CAP"""
    fund["credit_limit"] = min(CREDIT_FUND_QUOTA_CAP, fund["credit_limit"] + repaid_amount)


def _credit_fund_log_repayment(fund: dict, source: str, amount_returned: int):
    fund["repayment_log"].append({
        "source": source,                       # เช่น "market_sell" (อัตโนมัติ) หรือ "manual" (กดโปะเอง)
        "amount_returned": amount_returned,
        "remaining_owed": fund["outstanding"],
        "ts": datetime.now().isoformat(timespec="seconds"),
    })


def credit_fund_auto_deduct(uid: str, sale_revenue: int, source: str = "market_sell") -> int:
    """เรียกทุกครั้งหลังผู้เล่นขายของได้เงินเข้ากระเป๋าแล้ว (P["credits"] += sale_revenue ไปแล้วก่อนเรียก
    ฟังก์ชันนี้) ถ้าผู้เล่นคนนี้ยังมีหนี้ Credit Support Fund ค้างอยู่ จะหัก CREDIT_FUND_AUTO_REPAY_PCT ของ
    รายได้ครั้งนี้ (ไม่มีวันเกินยอดหนี้ที่เหลือจริง) ออกจากเครดิตผู้เล่นไปโปะหนี้ทันที คืนค่าจำนวนที่หักไป
    (0 ถ้าไม่มีหนี้ค้าง/รายได้ครั้งนี้เป็น 0 — เท่ากับ "ยกเลิกการหักอัตโนมัติ" เองโดยไม่ต้องมี flag แยก)"""
    fund = _credit_fund_state(uid)
    if fund["outstanding"] <= 0 or sale_revenue <= 0:
        return 0
    deduct = min(fund["outstanding"], math.floor(sale_revenue * CREDIT_FUND_AUTO_REPAY_PCT))
    if deduct <= 0:
        return 0
    P["credits"] -= deduct
    WALLET["balance"] = P["credits"]
    fund["outstanding"] -= deduct
    fund["repaid_total"] += deduct
    _credit_fund_grow_limit(fund, deduct)
    _credit_fund_log_repayment(fund, source, deduct)
    return deduct


@app.route('/api/credit_fund/status')
def api_credit_fund_status():
    """?uid= -> ข้อมูลแท็บ "รายละเอียดโควตา": วงเงินปัจจุบัน / เพดานสูงสุด / ยอดหนี้ที่รอชำระคืนตอนนี้"""
    uid = request.args.get("uid", P["uid"])
    fund = _credit_fund_state(uid)
    available = max(0, fund["credit_limit"] - fund["outstanding"])
    return jsonify({
        "st": "ok",
        "credit_limit": fund["credit_limit"],
        "quota_cap": CREDIT_FUND_QUOTA_CAP,
        "available_to_borrow": available,
        "outstanding": fund["outstanding"],
        "borrowed_total": fund["borrowed_total"],
        "repaid_total": fund["repaid_total"],
        "auto_repay_pct": CREDIT_FUND_AUTO_REPAY_PCT,
    })


@app.route('/api/credit_fund/borrow', methods=['POST'])
@require_auth
def api_credit_fund_borrow():
    """body: {uid, amount} -> ยืมเครดิตจากกองทุนสนับสนุนมาเล่นก่อน ไม่เกินวงเงินที่ยืมได้ตอนนี้
    (credit_limit - outstanding) เครดิตที่ยืมได้จะเข้ากระเป๋าทันที และกลายเป็นหนี้ค้างชำระ"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    amount = max(0, int(body.get("amount", 0)))
    fund = _credit_fund_state(uid)
    available = fund["credit_limit"] - fund["outstanding"]
    if amount <= 0:
        return jsonify({"st": "error", "msg": "จำนวนต้องมากกว่า 0"}), 400
    if amount > available:
        return jsonify({"st": "error", "msg": "เกินวงเงินที่ยืมได้ตอนนี้",
                        "available_to_borrow": available}), 400
    P["credits"] += amount
    WALLET["balance"] = P["credits"]
    fund["outstanding"] += amount
    fund["borrowed_total"] += amount
    return jsonify({"st": "ok", "borrowed": amount, "outstanding": fund["outstanding"],
                    "credits": P["credits"], "available_to_borrow": fund["credit_limit"] - fund["outstanding"]})


@app.route('/api/credit_fund/repay', methods=['POST'])
@require_auth
def api_credit_fund_repay():
    """body: {uid, amount} -> ผู้เล่นกดโปะหนี้คืนเองด้วยมือ (นอกเหนือจากการหักอัตโนมัติตอนขายของ) หัก
    เครดิตผู้เล่นจริง ต้องมีเครดิตพอ และจ่ายได้ไม่เกินยอดหนี้ที่เหลืออยู่จริง"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    amount = max(0, int(body.get("amount", 0)))
    fund = _credit_fund_state(uid)
    if amount <= 0:
        return jsonify({"st": "error", "msg": "จำนวนต้องมากกว่า 0"}), 400
    amount = min(amount, fund["outstanding"])
    if amount <= 0:
        return jsonify({"st": "error", "msg": "ไม่มีหนี้ค้างชำระแล้ว"}), 400
    if P["credits"] < amount:
        return jsonify({"st": "error", "msg": "เครดิตไม่พอจะชำระคืน", "need": amount, "have": P["credits"]}), 400
    P["credits"] -= amount
    WALLET["balance"] = P["credits"]
    fund["outstanding"] -= amount
    fund["repaid_total"] += amount
    _credit_fund_grow_limit(fund, amount)
    _credit_fund_log_repayment(fund, "manual", amount)
    return jsonify({"st": "ok", "repaid": amount, "outstanding": fund["outstanding"],
                    "credits": P["credits"], "credit_limit": fund["credit_limit"]})


@app.route('/api/credit_fund/repayment_log')
def api_credit_fund_repayment_log():
    """?uid= -> ข้อมูลแท็บ "บันทึกการชำระคืน": ชำระโดย (source) / จำนวนที่คืน / ยอดค้างชำระ ณ ตอนนั้น
    เรียงจากรายการล่าสุดไปเก่าสุด"""
    uid = request.args.get("uid", P["uid"])
    fund = _credit_fund_state(uid)
    return jsonify({"st": "ok", "repayment_log": list(reversed(fund["repayment_log"]))})


VMAX_MODULES["credit_support_fund"] = {
    "name": "Credit Support Fund (ระบบยืมเครดิตมาเล่น)",
    "level": "intermediate",
    "category": "economy",
    "desc": "กองทุนสนับสนุนให้ผู้เล่นยืมเครดิตล่วงหน้ามาเล่นได้ภายในวงเงิน (เริ่มต้นไม่สูงมากแล้วโตขึ้นเรื่อยๆ "
            "ตามประวัติชำระคืน จนแตะเพดาน 3,000,000) ชำระคืนอัตโนมัติด้วยการหัก 20% จากรายได้ทุกครั้งที่ขาย"
            "ของในตลาด จนกว่าจะครบยอด ระบบจะยกเลิกการหักเองเมื่อไม่มีหนี้ค้างแล้ว ผู้เล่นโปะคืนเองด้วยมือได้"
            "เช่นกัน — เป็นกลไกเครดิตภายในเกมล้วนๆ ไม่เกี่ยวกับเงินจริง",
    "routes": ["/api/credit_fund/status", "/api/credit_fund/borrow", "/api/credit_fund/repay",
               "/api/credit_fund/repayment_log"],
}


# =====================================================================================
# [ 6zzE. Tarot x Monster Fuse Card Game — ต้นแบบตามที่คุยออกแบบกันไว้ ]
# กลไกตามที่สรุปจากบทสนทนา (มีจุดที่ผมตั้ง "สมมติฐาน" ไว้ชัดๆ เป็นคอมเมนต์ — ต้อง
# กลับมาปรับเลขจริง/เงื่อนไขจริงทีหลัง เพราะตอนคุยยังไม่ได้ฟิกซ์ตัวเลขทั้งหมด):
#
#   โซนสนามผู้เล่นแต่ละคน:
#     - MONSTER ZONE: ช่องมอนสเตอร์เรียงเป็นตำแหน่ง "front" / "back" (ยึดตามที่บอกว่า
#       ฟิวส์เพิ่มพลังบางใบ "กำหนดตายตัว" ว่าเสริมได้แค่ตัวหน้า หรือแค่ตัวหลังเท่านั้น)
#       เหนือมอนสเตอร์แต่ละตัวมี "ช่องฟิวส์" ซ้อนได้ 2 ชั้น (เหมือน Spell/Trap Zone
#       ในยูกิ แต่วางไพ่ฟิวส์ซ้อนกันในช่องเดียวได้):
#         ชั้น 1 = เวทฟิวส์ดอกจิก (Ved Fuse) — ผูกเอฟเฟกต์ให้มอนสเตอร์ตัวนั้นโดยตรง
#         ชั้น 2 = ฟิวส์แบบนับแต้ม (สไตล์ป๊อกเด้ง แต้มรวม mod 10 ใกล้ POK_TARGET ที่สุด
#                  ยิ่งใกล้ยิ่งแรง — เป็นกลไกนับแต้มภายในเกมล้วนๆ ไม่ใช่การพนัน) วางซ้อนบน
#                  ชั้น 1 ได้ แต่ [คอนเฟิร์มแล้ว] ชั้น 2 นี้ "ไม่" บัฟมอนสเตอร์ตัวที่มันซ้อนอยู่
#                  ด้วย — แต้มที่ได้เอาไปเสริมพลังให้ "ไพ่ทาโร่กึ่งกลางสนาม" (heart_hp/shield_val)
#                  แทน ส่วนมอนสเตอร์รับบัฟจากชั้น 1 (เวทฟิวส์ดอกจิก) เพียวๆ เท่านั้น
#     - TAROT ZONE (กึ่งกลางสนาม): การ์ดทาโร่ใบเดียว มีค่า heart_hp (เลือด) และถ้าเป็น
#       ประเภทอัศวินจะมี shield_val (โล่) เพิ่ม — หัวใจสูทหัวใจใช้เสริมพลังการ์ดนี้
#     - SPARROW ZONE: การ์ดนกกระจิบที่จั่ว/สะสมได้ ไม่มีเอฟเฟกต์เดี่ยวๆ [คอนเฟิร์มแล้ว]
#       จั่วทีนับเพิ่มทีละ 1 แบบธรรมดา ไม่ต้องเรียงเลข พอสะสมครบ SPARROW_WIN_THRESHOLD
#       ใบ จะทริกเกอร์ "สายฟ้าฟาด" ใส่คู่ต่อสู้ ชนะทันที
#
#   เอฟเฟกต์หัวใจ (heart fuse) เมื่อทาโร่โดนโจมตี:
#     - heart_hp ลด และ shield_val (ถ้ามี) ลดพร้อมกันในจังหวะเดียว
#     - ฝ่ายโจมตีถูกบังคับให้เล็งไปที่ทาโร่กึ่งกลางเท่านั้น เว้นแต่ผู้เล่นเจ้าของจะ
#       เลือก "ไม่ใช้ทาโร่กันเลย" แล้วใช้มอนสเตอร์ตั้งรับแทน (บล็อกการโจมตีได้)
#
#   หมายเหตุ: นี่คือโครงต้นแบบ (state ในหน่วยความจำ, ยังไม่ persist ลงไฟล์เหมือนโมดูล
#   อื่นๆ ในไฟล์นี้) พอกฎนิ่งกว่านี้ค่อยเพิ่ม win/lose แบบเต็มรูป, เด็ค, การจั่วไพ่ ฯลฯ
# =====================================================================================

POK_TARGET = 9                  # [สมมติฐาน] เป้าแต้มของฟิวส์ชั้น 2 แบบป๊อกเด้ง (mod 10 ใกล้เลขนี้ = บัฟแรงสุด)
SPARROW_WIN_THRESHOLD = 5   # [สมมติฐาน] จั่วนกกระจิบสะสมครบกี่ใบ (นับรวมธรรมดา +1 ต่อใบ) ถึงจะฟาดสายฟ้าชนะ
MONSTER_ZONE_POSITIONS = ["front", "back"]
PHASES = ["draw", "standby", "main1", "battle", "main2", "end"]   # เฟสต่อเทิร์น สไตล์ยูกิ
EFFECT_ACTIVATABLE_PHASES = {"standby", "main1"}   # [คอนเฟิร์มแล้ว] เอฟเฟกต์มอนสเตอร์เปิดได้เฉพาะ 2 เฟสนี้

TAROT_MONSTER_GAME_STATE = {}   # uid -> game state dict


def _tarot_monster_new_state() -> dict:
    return {
        "monster_zone": {
            pos: {"monster": None, "fuse_stack": []}  # fuse_stack: list of up to 2 fuse dicts
            for pos in MONSTER_ZONE_POSITIONS
        },
        "tarot_zone": None,      # {"tarot_type": "knight"/"other", "heart_hp": int, "shield_val": int}
        "sparrow_zone": [],      # ลำดับนกกระจิบที่สะสมมาแล้ว เช่น [1, 2, 3]
        "hand_kings": [],        # ไพ่คิงที่จั่วมาแล้วแต่ยังไม่ได้ใช้ [{id, attached_to_tarot: bool, value}]
        "hand_monsters": [],     # การ์ดมอนสเตอร์ที่จั่วมาแล้วแต่ยังไม่ได้ลงสนาม (แต่ละใบมี bonus fuse ติดมาด้วย)
        "phase": "draw",         # เฟสปัจจุบัน ดู PHASES ด้านล่าง (ระบบเฟสสไตล์ยูกิ)
        "pending_effects": [],   # เอฟเฟกต์มอนสเตอร์ที่เพิ่งเปิดใช้ แต่ยังไม่ resolve — โดนขัด (negate) ได้ก่อนจบ
        "set_traps": [],         # การ์ดกับดักที่คว่ำไว้บนสนาม [{id, trap}] — activate_trap เรียกใช้ได้ตลอด
        "extra_turn_locked_opponent": False,   # True เมื่อได้เอฟเฟกต์ "เทิร์นพิเศษ" — ฝั่งตรงข้ามทำอะไรไม่ได้
                                                # เลยยกเว้น activate_trap (Trap บายพาสการล็อกนี้เสมอ)
        "log": [],               # เหตุการณ์ล่าสุด อ่านง่ายๆ ไว้ debug/แสดงผล
        "winner": None,          # ตั้งเป็น True เมื่อทริกเกอร์เงื่อนไขชนะ (สายฟ้าฟาด)
    }


TAROT_MONSTER_DECKS = {}   # uid -> {"sparrow_deck": [...], "king_deck": [...], "monster_deck": [...]}
                            # แต่ละกองเป็น list เรียงลำดับ จั่วจากหัว list (index 0) ไปทีละใบ จนกองไหนหมดก็คือหมด


def _tarot_monster_state(uid: str) -> dict:
    return TAROT_MONSTER_GAME_STATE.setdefault(uid, _tarot_monster_new_state())


def _pok_score_strength(cards_sum: int) -> float:
    """ระยะห่างจาก POK_TARGET (mod 10) แปลงเป็นตัวคูณบัฟ 0.0-1.0 — ยิ่งใกล้ยิ่งแรง
    [สมมติฐาน] สูตรนี้ตั้งขึ้นเองให้พอใช้งานได้ก่อน รอเลขจริงจากดีไซน์"""
    dist = min(abs((cards_sum % 10) - POK_TARGET), 10 - abs((cards_sum % 10) - POK_TARGET))
    return round(max(0.0, 1.0 - dist / 5.0), 2)


def _sparrow_check_win(uid: str) -> bool:
    """สะสมนกกระจิบธรรมดา จั่วทีนับ +1 ไม่ต้องเรียงเลข พอถึง SPARROW_WIN_THRESHOLD ก็ชนะทันที"""
    state = _tarot_monster_state(uid)
    won = len(state["sparrow_zone"]) >= SPARROW_WIN_THRESHOLD
    if won:
        state["winner"] = True
        state["log"].append("⚡ สะสมนกกระจิบครบลำดับ — สายฟ้าฟาดคู่ต่อสู้ ชนะทันที!")
    return won


@app.route('/api/tarot_monster/new_game', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_new_game():
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    TAROT_MONSTER_GAME_STATE[uid] = _tarot_monster_new_state()
    return jsonify({"st": "ok", "state": TAROT_MONSTER_GAME_STATE[uid]})


@app.route('/api/tarot_monster/state')
def api_tarot_monster_state():
    uid = request.args.get("uid", P["uid"])
    return jsonify({"st": "ok", "state": _tarot_monster_state(uid)})


@app.route('/api/tarot_monster/play_monster', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_play_monster():
    """body: {uid, position: 'front'|'back', monster: {name, atk, def_}}"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    position = body.get("position")
    monster = body.get("monster") or {}
    if position not in MONSTER_ZONE_POSITIONS:
        return jsonify({"st": "error", "msg": f"position ต้องเป็น {MONSTER_ZONE_POSITIONS}"}), 400
    if "atk" not in monster or "def_" not in monster:
        return jsonify({"st": "error", "msg": "monster ต้องมี atk และ def_"}), 400
    state = _tarot_monster_state(uid)
    state["monster_zone"][position]["monster"] = monster
    state["monster_zone"][position]["fuse_stack"] = []
    state["log"].append(f"ลงมอนสเตอร์ '{monster.get('name', '?')}' ที่ตำแหน่ง {position}")
    return jsonify({"st": "ok", "state": state})


@app.route('/api/tarot_monster/attach_fuse', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_attach_fuse():
    """body: {uid, position, layer: 1|2, fuse: {...}}
    layer 1 = เวทฟิวส์ดอกจิก (ต้องวางก่อน), layer 2 = ฟิวส์นับแต้มป๊อกเด้ง (ต้องมี layer 1 อยู่แล้ว)
    fuse ตัวอย่าง layer 1: {"kind": "power_up", "target_position": "front"|"back", "atk_bonus": 3, "def_bonus": 0}
    fuse ตัวอย่าง layer 2: {"kind": "pok_score", "card_values": [3, 5]}  # ใช้คำนวณ _pok_score_strength
    """
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    position = body.get("position")
    layer = body.get("layer")
    fuse = body.get("fuse") or {}
    state = _tarot_monster_state(uid)
    if position not in state["monster_zone"]:
        return jsonify({"st": "error", "msg": "ไม่พบตำแหน่งมอนสเตอร์นี้"}), 400
    slot = state["monster_zone"][position]
    if not slot["monster"]:
        return jsonify({"st": "error", "msg": "ต้องลงมอนสเตอร์ในช่องนี้ก่อนถึงจะติดฟิวส์ได้"}), 400
    if layer == 1:
        if len(slot["fuse_stack"]) >= 1:
            return jsonify({"st": "error", "msg": "ช่องนี้มีฟิวส์ชั้น 1 อยู่แล้ว"}), 400
        # ฟิวส์เพิ่มพลังบังคับตำแหน่ง (front-only / back-only) ตามที่ดีไซน์ไว้
        target_pos = fuse.get("target_position")
        if fuse.get("kind") == "power_up" and target_pos and target_pos != position:
            return jsonify({"st": "error", "msg": f"ฟิวส์ใบนี้ใช้ได้เฉพาะตำแหน่ง {target_pos} เท่านั้น"}), 400
        slot["fuse_stack"] = [fuse]
    elif layer == 2:
        if len(slot["fuse_stack"]) != 1:
            return jsonify({"st": "error", "msg": "ต้องมีฟิวส์ชั้น 1 อยู่ก่อน ถึงจะวางชั้น 2 ซ้อนได้"}), 400
        slot["fuse_stack"].append(fuse)
    else:
        return jsonify({"st": "error", "msg": "layer ต้องเป็น 1 หรือ 2"}), 400

    # [แก้ตามคอนเฟิร์มล่าสุด] ชั้น 1 (เวทฟิวส์ดอกจิก) เท่านั้นที่บัฟมอนสเตอร์ตัวนี้โดยตรง
    # ชั้น 2 (คะแนนสไตล์ป๊อกเด้ง — นับแต้มภายในเกมล้วนๆ ไม่ใช่การพนัน) ไม่แตะมอนสเตอร์เลย
    # แต่เอาแต้มไปเสริมพลังให้ "ไพ่ทาโร่กึ่งกลางสนาม" แทน (heart_hp / shield_val)
    monster_atk_bonus = sum(f.get("atk_bonus", 0) for f in slot["fuse_stack"] if f.get("kind") == "power_up")
    monster_def_bonus = sum(f.get("def_bonus", 0) for f in slot["fuse_stack"] if f.get("kind") == "power_up")
    slot["monster"]["effective_atk"] = slot["monster"]["atk"] + monster_atk_bonus
    slot["monster"]["effective_def"] = slot["monster"]["def_"] + monster_def_bonus

    pok_fuse = next((f for f in slot["fuse_stack"] if f.get("kind") == "pok_score"), None)
    if pok_fuse:
        if not state["tarot_zone"]:
            return jsonify({"st": "error", "msg": "ต้องมีไพ่ทาโร่กึ่งกลางสนามก่อน ถึงจะติดฟิวส์คะแนนชั้น 2 ได้"}), 400
        strength = _pok_score_strength(sum(pok_fuse.get("card_values", [])))
        heart_bonus = round(strength * 3)     # [สมมติฐาน] สเกลตัวเลขยังกะเอง รอเลขจริง
        shield_bonus = round(strength * 2) if state["tarot_zone"].get("tarot_type") == "knight" else 0
        state["tarot_zone"]["heart_hp"] = state["tarot_zone"].get("heart_hp", 0) + heart_bonus
        state["tarot_zone"]["shield_val"] = state["tarot_zone"].get("shield_val", 0) + shield_bonus
        state["log"].append(f"ฟิวส์คะแนนชั้น 2 (strength={strength}) เสริมทาโร่: heart_hp +{heart_bonus}, shield_val +{shield_bonus}")

    state["log"].append(f"ติดฟิวส์ชั้น {layer} ที่ตำแหน่ง {position}")
    return jsonify({"st": "ok", "state": state})


@app.route('/api/tarot_monster/attack', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_attack():
    """body: {uid, mode: 'tarot' | 'monster_block', target_position (ถ้า mode=monster_block)}
    mode='tarot' -> โจมตีทาโร่กึ่งกลาง (บังคับเข้าเป้านี้ถ้ามีหัวใจฟิวส์ติดอยู่และยังไม่เลือกตั้งรับ)
    mode='monster_block' -> เจ้าของสนามเลือกไม่ใช้ทาโร่กันเลย ใช้มอนสเตอร์ตั้งรับแทน (บล็อกดาเมจ)
    """
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    mode = body.get("mode")
    state = _tarot_monster_state(uid)

    if mode == "monster_block":
        target_position = body.get("target_position")
        slot = state["monster_zone"].get(target_position)
        if not slot or not slot["monster"]:
            return jsonify({"st": "error", "msg": "ไม่มีมอนสเตอร์ในตำแหน่งนี้ให้ตั้งรับ"}), 400
        state["log"].append(f"ใช้มอนสเตอร์ที่ {target_position} ตั้งรับแทนทาโร่ — บล็อกดาเมจสำเร็จ")
        return jsonify({"st": "ok", "blocked": True, "state": state})

    if mode == "tarot":
        tarot = state["tarot_zone"]
        if not tarot:
            return jsonify({"st": "error", "msg": "ไม่มีการ์ดทาโร่อยู่กึ่งกลางสนาม"}), 400
        tarot["heart_hp"] = max(0, tarot.get("heart_hp", 0) - 1)
        if tarot.get("tarot_type") == "knight":
            tarot["shield_val"] = max(0, tarot.get("shield_val", 0) - 1)
        state["log"].append("โจมตีทาโร่กึ่งกลาง — heart_hp และ shield_val ลดลง 1")
        if tarot["heart_hp"] <= 0:
            state["log"].append("ทาโร่กึ่งกลางหมดเลือด — ถือว่าฝ่ายนี้แพ้ [สมมติฐาน เงื่อนไขแพ้]")
        return jsonify({"st": "ok", "state": state})

    return jsonify({"st": "error", "msg": "mode ต้องเป็น 'tarot' หรือ 'monster_block'"}), 400


@app.route('/api/tarot_monster/draw_sparrow', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_draw_sparrow():
    """body: {uid, sparrow_value: int} -> จั่ว/เก็บนกกระจิบใบใหม่เข้ามือ เช็คทันทีว่าครบเงื่อนไขชนะหรือยัง"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    sparrow_value = body.get("sparrow_value")
    if sparrow_value is None:
        return jsonify({"st": "error", "msg": "ต้องระบุ sparrow_value"}), 400
    state = _tarot_monster_state(uid)
    state["sparrow_zone"].append(sparrow_value)
    state["log"].append(f"จั่วไพ่นกกระจิบ: {sparrow_value}")
    won = _sparrow_check_win(uid)
    return jsonify({"st": "ok", "won": won, "state": state})


@app.route('/api/tarot_monster/setup_decks', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_setup_decks():
    """body: {uid, sparrow_deck: [values...], king_deck: [{value,...}...], monster_deck: [{name,atk,def_,fuse?}...]}
    ตั้งกอง 3 กองแยกของผู้เล่นคนนี้ (เรียกครั้งเดียวตอนเริ่มเกม/สับเด็ค)"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    TAROT_MONSTER_DECKS[uid] = {
        "sparrow_deck": list(body.get("sparrow_deck", [])),
        "king_deck": list(body.get("king_deck", [])),
        "monster_deck": list(body.get("monster_deck", [])),
    }
    return jsonify({"st": "ok", "decks": TAROT_MONSTER_DECKS[uid]})


@app.route('/api/tarot_monster/draw_turn', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_draw_turn():
    """body: {uid} -> จั่วทีเดียวจบทั้งเทิร์น: ทีละใบจากกองนกกระจิบ -> กองคิง -> กองมอนสเตอร์ ตามลำดับ
    (เหมือนยูกิ) กองไหนจั่วหมดแล้วก็ข้ามไป ไม่ error — มอนสเตอร์ที่จั่วได้ถ้ามี "fuse" ติดมาด้วยในตัวการ์ด
    จะเก็บเข้ามือเป็นฟิวส์แถมให้อัตโนมัติ (ผูก fuse ไว้ที่ตัวการ์ดมอนสเตอร์ใน hand_monsters เลย รอตอน
    play_monster + attach_fuse ค่อยเอาไปใช้จริง)"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    state = _tarot_monster_state(uid)
    decks = TAROT_MONSTER_DECKS.setdefault(uid, {"sparrow_deck": [], "king_deck": [], "monster_deck": []})
    drawn = {"sparrow": None, "king": None, "monster": None}

    if decks["sparrow_deck"]:
        sparrow_val = decks["sparrow_deck"].pop(0)
        state["sparrow_zone"].append(sparrow_val)
        drawn["sparrow"] = sparrow_val
        state["log"].append(f"จั่วนกกระจิบ: {sparrow_val}")

    if decks["king_deck"]:
        king_card = decks["king_deck"].pop(0)
        king_card = dict(king_card)
        king_card.setdefault("id", str(uuid.uuid4())[:8])
        king_card["attached_to_tarot"] = False
        state["hand_kings"].append(king_card)
        drawn["king"] = king_card
        state["log"].append(f"จั่วไพ่คิง: {king_card}")

    if decks["monster_deck"]:
        monster_card = decks["monster_deck"].pop(0)
        monster_card = dict(monster_card)
        monster_card.setdefault("id", str(uuid.uuid4())[:8])
        state["hand_monsters"].append(monster_card)
        drawn["monster"] = monster_card
        state["log"].append(f"จั่วมอนสเตอร์: {monster_card.get('name', '?')}"
                             + (" (มีฟิวส์ติดมาด้วย)" if monster_card.get("fuse") else ""))

    won = _sparrow_check_win(uid)
    return jsonify({"st": "ok", "drawn": drawn, "won": won, "state": state,
                     "decks_remaining": {k: len(v) for k, v in decks.items()}})


@app.route('/api/tarot_monster/king_action', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_king_action():
    """body: {uid, king_id, action}
    action ที่รองรับ (ทำได้หลายครั้ง/หลายอย่างในเทิร์นเดียวกัน [คอนเฟิร์มแล้ว]):
      - "boost_tarot": ใช้ไพ่คิงใบนี้เสริมพลังทาโร่ทันที (ใช้แล้วออกจากมือ)
      - "attach_defense": แนบไพ่คิงไว้กับทาโร่ก่อน (ยังไม่ทำอะไร รอ activate_defense ทีหลัง)
      - "activate_defense": ถึงตาตัวเองแล้ว เปลี่ยนคิงที่แนบไว้ให้ทาโร่สลับเข้าโหมดป้องกัน
    """
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    king_id = body.get("king_id")
    action = body.get("action")
    state = _tarot_monster_state(uid)
    king_card = next((k for k in state["hand_kings"] if k.get("id") == king_id), None)
    if not king_card:
        return jsonify({"st": "error", "msg": "ไม่พบไพ่คิงใบนี้ในมือ"}), 400
    if not state["tarot_zone"]:
        return jsonify({"st": "error", "msg": "ต้องมีไพ่ทาโร่กึ่งกลางสนามก่อน"}), 400

    if action == "boost_tarot":
        bonus = king_card.get("value", 1)   # [สมมติฐาน] สเกลโบนัสยังกะเอง
        state["tarot_zone"]["heart_hp"] = state["tarot_zone"].get("heart_hp", 0) + bonus
        state["hand_kings"].remove(king_card)
        state["log"].append(f"ใช้ไพ่คิงเสริมพลังทาโร่: heart_hp +{bonus}")
    elif action == "attach_defense":
        king_card["attached_to_tarot"] = True
        state["log"].append("แนบไพ่คิงไว้กับทาโร่ (รอเปิดโหมดป้องกันตอนตาตัวเอง)")
    elif action == "activate_defense":
        if not king_card.get("attached_to_tarot"):
            return jsonify({"st": "error", "msg": "ไพ่คิงใบนี้ยังไม่ได้แนบไว้กับทาโร่"}), 400
        state["tarot_zone"]["defense_mode"] = True
        state["hand_kings"].remove(king_card)
        state["log"].append("เปิดโหมดป้องกันให้ทาโร่ (จากไพ่คิงที่แนบไว้)")
    else:
        return jsonify({"st": "error", "msg": "action ต้องเป็น boost_tarot / attach_defense / activate_defense"}), 400

    return jsonify({"st": "ok", "state": state})


@app.route('/api/tarot_monster/set_phase', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_set_phase():
    """body: {uid, phase} -> เปลี่ยนเฟสปัจจุบันด้วยมือ (draw/standby/main1/battle/main2/end)
    [สมมติฐาน] ยังไม่บังคับลำดับเฟสจริงจัง แค่เก็บ state ไว้ให้ endpoint อื่นเช็คได้ว่าตอนนี้เฟสไหน"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    phase = body.get("phase")
    if phase not in PHASES:
        return jsonify({"st": "error", "msg": f"phase ต้องเป็นหนึ่งใน {PHASES}"}), 400
    state = _tarot_monster_state(uid)
    state["phase"] = phase
    state["log"].append(f"เข้าสู่เฟส: {phase}")
    return jsonify({"st": "ok", "state": state})


@app.route('/api/tarot_monster/activate_monster_effect', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_activate_monster_effect():
    """body: {uid, position} -> เปิดใช้เอฟเฟกต์ของมอนสเตอร์ที่ตำแหน่งนี้ ได้เฉพาะช่วง Standby/Main1
    เท่านั้น [คอนเฟิร์มแล้ว] เอฟเฟกต์จะค้างเป็น "pending" ให้อีกฝ่ายมีโอกาสขัด (negate) ก่อน แล้วค่อย
    resolve ทีหลังด้วย /resolve_effect"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    position = body.get("position")
    state = _tarot_monster_state(uid)
    if state["phase"] not in EFFECT_ACTIVATABLE_PHASES:
        return jsonify({"st": "error", "msg": f"เปิดเอฟเฟกต์มอนสเตอร์ได้เฉพาะช่วง {sorted(EFFECT_ACTIVATABLE_PHASES)} เท่านั้น"}), 400
    slot = state["monster_zone"].get(position)
    if not slot or not slot["monster"]:
        return jsonify({"st": "error", "msg": "ไม่มีมอนสเตอร์ในตำแหน่งนี้"}), 400
    effect_id = str(uuid.uuid4())[:8]
    state["pending_effects"].append({"id": effect_id, "position": position, "phase": state["phase"], "negated": False})
    state["log"].append(f"เปิดเอฟเฟกต์มอนสเตอร์ที่ {position} (เฟส {state['phase']}) — รอ resolve หรือโดนขัด")
    return jsonify({"st": "ok", "effect_id": effect_id, "state": state})


@app.route('/api/tarot_monster/negate_effect', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_negate_effect():
    """body: {uid, effect_id} -> ขัดเอฟเฟกต์ที่ยังค้าง pending อยู่ ทำให้มันทำงานต่อไม่ได้เลย"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    effect_id = body.get("effect_id")
    state = _tarot_monster_state(uid)
    eff = next((e for e in state["pending_effects"] if e["id"] == effect_id), None)
    if not eff:
        return jsonify({"st": "error", "msg": "ไม่พบเอฟเฟกต์นี้ (อาจ resolve ไปแล้วหรือหมดอายุ)"}), 400
    eff["negated"] = True
    state["log"].append(f"เอฟเฟกต์มอนสเตอร์ที่ {eff['position']} โดนขัด — ทำงานต่อไม่ได้แล้ว")
    return jsonify({"st": "ok", "state": state})


@app.route('/api/tarot_monster/resolve_effect', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_resolve_effect():
    """body: {uid, effect_id} -> resolve เอฟเฟกต์ที่ค้างไว้ ถ้าโดนขัดไปแล้วจะ resolve ไม่ได้"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    effect_id = body.get("effect_id")
    state = _tarot_monster_state(uid)
    eff = next((e for e in state["pending_effects"] if e["id"] == effect_id), None)
    if not eff:
        return jsonify({"st": "error", "msg": "ไม่พบเอฟเฟกต์นี้"}), 400
    if eff["negated"]:
        state["pending_effects"].remove(eff)
        return jsonify({"st": "error", "msg": "เอฟเฟกต์นี้โดนขัดไปแล้ว ทำงานต่อไม่ได้"}), 400
    state["pending_effects"].remove(eff)
    state["log"].append(f"เอฟเฟกต์มอนสเตอร์ที่ {eff['position']} resolve สำเร็จ")
    return jsonify({"st": "ok", "state": state})



@app.route('/api/tarot_monster/draw_choice', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_draw_choice():
    """body: {uid, pile: 'sparrow'|'king'|'monster'} -> จั่ว 1 ใบจากกองที่เลือกเอง (ใช้ซ้ำได้หลายครั้ง
    สำหรับเอฟเฟกต์มอนสเตอร์แบบ "จั่ว N ใบ" ที่ผู้เล่นเลือกกองเองทีละใบ ไม่ใช่จั่วเรียง 3 กองอัตโนมัติแบบ
    /draw_turn — หน้าบ้านเรียก endpoint นี้ซ้ำ N ครั้ง แล้วถามผู้เล่นใหม่ทุกครั้งว่าจะเอากองไหนต่อ)"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    pile = body.get("pile")
    if pile not in ("sparrow", "king", "monster"):
        return jsonify({"st": "error", "msg": "pile ต้องเป็น sparrow / king / monster"}), 400
    state = _tarot_monster_state(uid)
    decks = TAROT_MONSTER_DECKS.setdefault(uid, {"sparrow_deck": [], "king_deck": [], "monster_deck": []})
    deck_key = f"{pile}_deck"
    if not decks[deck_key]:
        return jsonify({"st": "error", "msg": f"กอง {pile} จั่วหมดแล้ว"}), 400

    if pile == "sparrow":
        val = decks[deck_key].pop(0)
        state["sparrow_zone"].append(val)
        state["log"].append(f"[เลือกจั่วเอง] นกกระจิบ: {val}")
        won = _sparrow_check_win(uid)
        return jsonify({"st": "ok", "drawn": val, "won": won, "state": state})
    elif pile == "king":
        card = dict(decks[deck_key].pop(0))
        card.setdefault("id", str(uuid.uuid4())[:8])
        card["attached_to_tarot"] = False
        state["hand_kings"].append(card)
        state["log"].append(f"[เลือกจั่วเอง] ไพ่คิง: {card}")
        return jsonify({"st": "ok", "drawn": card, "state": state})
    else:
        card = dict(decks[deck_key].pop(0))
        card.setdefault("id", str(uuid.uuid4())[:8])
        state["hand_monsters"].append(card)
        state["log"].append(f"[เลือกจั่วเอง] มอนสเตอร์: {card.get('name', '?')}")
        return jsonify({"st": "ok", "drawn": card, "state": state})


@app.route('/api/tarot_monster/grant_extra_turn', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_grant_extra_turn():
    """body: {uid} -> เอฟเฟกต์มอนสเตอร์ "เทิร์นพิเศษ": ล็อกไม่ให้ฝั่งตรงข้ามทำอะไรได้เลย ยกเว้นเปิด
    การ์ดกับดัก (Trap) ที่คว่ำไว้ (Trap บายพาสล็อกนี้เสมอ — ดู /activate_trap)"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    state = _tarot_monster_state(uid)
    state["extra_turn_locked_opponent"] = True
    state["log"].append("เปิดเอฟเฟกต์เทิร์นพิเศษ — ฝั่งตรงข้ามทำอะไรไม่ได้เลย ยกเว้นเปิด Trap")
    return jsonify({"st": "ok", "state": state})


@app.route('/api/tarot_monster/end_extra_turn', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_end_extra_turn():
    """body: {uid} -> จบเทิร์นพิเศษ ปลดล็อกฝั่งตรงข้ามให้เล่นได้ตามปกติ"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    state = _tarot_monster_state(uid)
    state["extra_turn_locked_opponent"] = False
    state["log"].append("จบเทิร์นพิเศษ — ฝั่งตรงข้ามเล่นได้ตามปกติแล้ว")
    return jsonify({"st": "ok", "state": state})


@app.route('/api/tarot_monster/set_trap', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_set_trap():
    """body: {uid, trap: {...}} -> คว่ำการ์ดกับดักไว้บนสนาม (เปิดใช้ได้ทุกเมื่อ แม้ระหว่างโดนล็อกด้วย
    เอฟเฟกต์เทิร์นพิเศษของอีกฝ่าย — ดู /activate_trap)"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    trap = body.get("trap") or {}
    state = _tarot_monster_state(uid)
    trap = dict(trap)
    trap.setdefault("id", str(uuid.uuid4())[:8])
    state["set_traps"].append(trap)
    state["log"].append(f"คว่ำการ์ดกับดัก: {trap.get('name', '?')}")
    return jsonify({"st": "ok", "state": state})


@app.route('/api/tarot_monster/activate_trap', methods=['POST'])
@require_auth_toggleable
def api_tarot_monster_activate_trap():
    """body: {uid, trap_id} -> เปิดการ์ดกับดักที่คว่ำไว้ ใช้ได้เสมอแม้ตอนโดนล็อกด้วยเอฟเฟกต์เทิร์นพิเศษ
    ของอีกฝ่าย (นี่คือทางเดียวที่ทำอะไรได้ตอนโดนล็อก [คอนเฟิร์มแล้ว])"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    trap_id = body.get("trap_id")
    state = _tarot_monster_state(uid)
    trap = next((t for t in state["set_traps"] if t["id"] == trap_id), None)
    if not trap:
        return jsonify({"st": "error", "msg": "ไม่พบการ์ดกับดักใบนี้"}), 400
    state["set_traps"].remove(trap)
    state["log"].append(f"เปิดการ์ดกับดัก: {trap.get('name', '?')}"
                         + (" (ตอบโต้ระหว่างโดนล็อกเทิร์นพิเศษ)" if state["extra_turn_locked_opponent"] else ""))
    return jsonify({"st": "ok", "state": state})



