# =====================================================================================
# [ 6zzF. Hotel Guest Wi-Fi Captive Portal — ยืนยันตัวตนผ่าน OTP + เช็คห้องพักจริงกับ PMS ]
# สถาปัตยกรรมมาตรฐานของระบบ Wi-Fi แขกโรงแรมทั่วไป (ไม่มีอะไรผิดปกติ เป็นของที่โรงแรม/
# คอนโด/หอพักใช้กันจริง): AP ดักผู้ใช้ใหม่ (captive portal) -> เด้งมาหน้านี้ -> กรอกเบอร์/
# เลขห้อง -> ยิง OTP ผ่าน SMS Gateway -> เช็คห้องกับ PMS -> ผ่านแล้วสั่ง AP ปล่อยเน็ต
# (ผ่าน RADIUS CoA หรือ API ของยี่ห้อ AP นั้นๆ) -> log ไว้เป็นหลักฐาน
#
# ข้อควรรู้ก่อนเอาไปใช้จริง (สำคัญ ไม่ใช่แค่ auto-generate ให้รันได้เลย):
#   1. MAC address ของอุปกรณ์ผู้ใช้ "เซิร์ฟเวอร์ฝั่งนี้ไม่มีทางรู้เอง" จาก HTTP request ธรรมดา
#      (MAC เป็นข้อมูล layer-2 เห็นได้แค่ในวง LAN เดียวกับ AP) — ต้องให้ตัว AP/Controller เป็น
#      คนแนบมาให้ตอน redirect ผู้ใช้เข้าหน้านี้ (ทุกยี่ห้อดังๆ เช่น UniFi/Cisco Meraki/MikroTik
#      hotspot ทำแบบนี้อยู่แล้ว คือใส่ ?mac=xx:xx:xx.. ต่อท้าย URL ให้อัตโนมัติ) โค้ดด้านล่าง
#      รับค่านี้จาก query param ไม่ได้เดาเอง
#   2. ฟังก์ชัน _sms_gateway_send_otp() และ _pms_check_room() และ _radius_grant_access()
#      เป็นแค่ "จุดเสียบ" (stub) — ต้องเอา API key/endpoint ของ SMS Gateway จริง, PMS จริง,
#      และ RADIUS/Controller API จริงของโรงแรมมาใส่แทนคอมเมนต์ TODO ก่อนใช้งานจริง
#   3. เก็บเบอร์โทรผู้ใช้ = ข้อมูลส่วนบุคคล ควรมีนโยบายเก็บ/ลบตามระยะเวลาที่เหมาะสม (PDPA)
#      ไม่ควร log เต็มเบอร์ในที่ที่คนอื่นเห็นได้ง่ายๆ ถ้าจะโชว์ในหน้า admin ควร mask บางหลัก
# =====================================================================================

WIFI_PORTAL_OTP_STORE = {}     # phone -> {"otp": str, "expires_at": float, "room_number": str}
WIFI_PORTAL_LOG = []           # รายการ session ที่ผ่านการยืนยันแล้ว (ip, mac, phone, room, เวลา)
WIFI_PORTAL_OTP_TTL_SECONDS = 300     # OTP หมดอายุใน 5 นาที
WIFI_PORTAL_OTP_MAX_ATTEMPTS = 5      # [สมมติฐาน] กันบรูทฟอร์ซเบื้องต้น ปรับได้ตามนโยบายจริง
WIFI_PORTAL_OTP_ATTEMPT_COUNTER = {}  # phone -> จำนวนครั้งที่กรอกผิดติดกัน


def _pms_check_room(room_number: str, phone: str) -> bool:
    """TODO: เชื่อม API จริงของระบบ PMS โรงแรม (เช่น Opera, Cloudbeds ฯลฯ) เพื่อเช็คว่า
    ห้องนี้มีแขกพักอยู่จริงไหม (และถ้าต้องการความปลอดภัยสูงขึ้น เช็คว่าเบอร์นี้ตรงกับที่
    ลงทะเบียนไว้ตอนเช็คอินด้วย) ตอนนี้เป็น stub คืนค่า True เสมอเพื่อให้ทดสอบ flow ได้ก่อน"""
    return bool(room_number)


def _sms_gateway_send_otp(phone: str, otp: str) -> bool:
    """TODO: เรียก API จริงของ SMS Gateway (Twilio / Ant Telecom / THAI BULK SMS ฯลฯ)
    ห้ามใส่ API key ตรงนี้ในโค้ด — ควรอ่านจาก environment variable เท่านั้น
    ตอนนี้เป็น stub แค่ log ไว้ดู ไม่ได้ส่ง SMS จริง"""
    print(f"[WIFI_PORTAL][STUB] ส่ง OTP {otp} ไปที่เบอร์ {phone[:4]}xxxx (ยังไม่ได้ต่อ SMS Gateway จริง)")
    return True


def _radius_grant_access(client_ip: str, client_mac: str) -> bool:
    """TODO: สั่งปล่อยเน็ตจริงผ่าน RADIUS CoA (Change-of-Authorization) หรือ REST API ของ
    Controller ยี่ห้อที่ใช้อยู่ (UniFi Controller API / Cisco Meraki Dashboard API / MikroTik
    RouterOS API) — รูปแบบเรียกต่างกันไปตามยี่ห้อ ต้องแทนที่ stub นี้ด้วยของจริง
    ตอนนี้เป็น stub คืน True เสมอเพื่อให้ทดสอบ flow ได้ก่อน"""
    print(f"[WIFI_PORTAL][STUB] สั่งปล่อยเน็ตให้ ip={client_ip} mac={client_mac} (ยังไม่ได้ต่อ RADIUS/Controller จริง)")
    return True


@app.route('/api/wifi_portal/request_otp', methods=['POST'])
@require_auth_toggleable
def api_wifi_portal_request_otp():
    """body: {phone, room_number} -> เช็คห้องกับ PMS ก่อน ผ่านแล้วค่อยส่ง OTP ไปเบอร์นั้น"""
    body = request.json or {}
    phone = (body.get("phone") or "").strip()
    room_number = (body.get("room_number") or "").strip()
    if not phone or not room_number:
        return jsonify({"st": "error", "msg": "ต้องกรอกทั้งเบอร์โทรและเลขห้อง"}), 400

    if not _pms_check_room(room_number, phone):
        return jsonify({"st": "error", "msg": "ไม่พบข้อมูลห้องพักนี้ กรุณาติดต่อเคาน์เตอร์"}), 400

    otp = f"{random.randint(0, 999999):06d}"
    WIFI_PORTAL_OTP_STORE[phone] = {
        "otp": otp,
        "expires_at": time.time() + WIFI_PORTAL_OTP_TTL_SECONDS,
        "room_number": room_number,
    }
    WIFI_PORTAL_OTP_ATTEMPT_COUNTER[phone] = 0
    _sms_gateway_send_otp(phone, otp)
    return jsonify({"st": "ok", "msg": f"ส่ง OTP แล้ว หมดอายุใน {WIFI_PORTAL_OTP_TTL_SECONDS // 60} นาที"})


@app.route('/api/wifi_portal/verify_otp', methods=['POST'])
@require_auth_toggleable
def api_wifi_portal_verify_otp():
    """body: {phone, otp, client_mac (แนบมาจาก AP ตอน redirect — ดูหมายเหตุข้อ 1 ด้านบนไฟล์)}
    client_ip ดึงจาก request โดยตรง ไม่ต้องส่งมา"""
    body = request.json or {}
    phone = (body.get("phone") or "").strip()
    otp_input = (body.get("otp") or "").strip()
    client_mac = (body.get("client_mac") or "").strip()
    client_ip = request.headers.get("X-Forwarded-For", request.remote_addr)

    if not client_mac:
        return jsonify({"st": "error", "msg": "ไม่พบ MAC address จาก Access Point — "
                                                "URL ที่ redirect มาต้องแนบ ?mac=... มาด้วย"}), 400

    record = WIFI_PORTAL_OTP_STORE.get(phone)
    if not record:
        return jsonify({"st": "error", "msg": "ยังไม่ได้ขอ OTP หรือ OTP หมดอายุแล้ว กรุณาขอใหม่"}), 400

    if WIFI_PORTAL_OTP_ATTEMPT_COUNTER.get(phone, 0) >= WIFI_PORTAL_OTP_MAX_ATTEMPTS:
        del WIFI_PORTAL_OTP_STORE[phone]
        return jsonify({"st": "error", "msg": "กรอกผิดเกินจำนวนที่กำหนด กรุณาขอ OTP ใหม่"}), 429

    if time.time() > record["expires_at"]:
        del WIFI_PORTAL_OTP_STORE[phone]
        return jsonify({"st": "error", "msg": "OTP หมดอายุแล้ว กรุณาขอใหม่"}), 400

    if otp_input != record["otp"]:
        WIFI_PORTAL_OTP_ATTEMPT_COUNTER[phone] = WIFI_PORTAL_OTP_ATTEMPT_COUNTER.get(phone, 0) + 1
        return jsonify({"st": "error", "msg": "OTP ไม่ถูกต้อง"}), 400

    granted = _radius_grant_access(client_ip, client_mac)
    if not granted:
        return jsonify({"st": "error", "msg": "ปล่อยเน็ตไม่สำเร็จ กรุณาติดต่อเคาน์เตอร์"}), 500

    WIFI_PORTAL_LOG.append({
        "ip": client_ip,
        "mac": client_mac,
        "phone": phone,           # [ข้อควรระวัง] ข้อมูลส่วนบุคคล — ถ้าโชว์หน้า admin ควร mask
        "room_number": record["room_number"],
        "granted_at": datetime.now().isoformat(),
    })
    del WIFI_PORTAL_OTP_STORE[phone]
    WIFI_PORTAL_OTP_ATTEMPT_COUNTER.pop(phone, None)
    return jsonify({"st": "ok", "msg": "ยืนยันตัวตนสำเร็จ ใช้อินเทอร์เน็ตได้แล้ว"})


@app.route('/api/wifi_portal/log', methods=['GET'])
@require_auth_toggleable
def api_wifi_portal_log():
    """ดึง log การเข้าใช้งาน — [ข้อควรระวัง] มีเบอร์โทรผู้ใช้จริงอยู่ในนี้ จำกัดสิทธิ์การเข้าถึง
    หน้านี้เฉพาะแอดมินเท่านั้น อย่าเปิดสาธารณะ"""
    masked = [{**entry, "phone": entry["phone"][:4] + "xxxx"} for entry in WIFI_PORTAL_LOG]
    return jsonify({"st": "ok", "log": masked, "count": len(masked)})


