def _run_wifi_portal_selftests():
    """Self-test ของโมดูล hotel_wifi_captive_portal — ใช้ app/P/ฟังก์ชันจริงจากไฟล์นี้เลย
    (ไม่สร้าง Flask app แยก ไม่มีปัญหาเรื่องชื่อชนกัน) เรียกด้วย: python3 <ไฟล์นี้> --selftest-wifi-portal
    หมายเหตุ: รันได้เฉพาะบนเครื่อง/เซิร์ฟเวอร์ที่ dependency ของไฟล์นี้ครบแล้วเท่านั้น (flask-socketio,
    opencv, mediapipe ฯลฯ) — แซนด์บ็อกซ์ที่ไม่มีอินเทอร์เน็ตจะ import ไฟล์นี้ไม่ผ่านตั้งแต่ต้น"""
    c = app.test_client()
    results = []

    def check(name, cond):
        results.append((name, cond))
        print(("✅ PASS " if cond else "❌ FAIL ") + name)

    r = c.post('/api/wifi_portal/request_otp', json={"phone": "", "room_number": ""})
    check("request_otp: ขาดข้อมูล -> 400", r.status_code == 400)

    r = c.post('/api/wifi_portal/request_otp', json={"phone": "0812345678", "room_number": "501"})
    check("request_otp: ข้อมูลครบ -> 200", r.status_code == 200)
    otp = WIFI_PORTAL_OTP_STORE["0812345678"]["otp"]   # อ่านจาก store จริงแทน (production ไม่ leak otp ผ่าน response)

    r = c.post('/api/wifi_portal/verify_otp', json={"phone": "0812345678", "otp": otp})
    check("verify_otp: ไม่มี mac -> 400", r.status_code == 400)

    r = c.post('/api/wifi_portal/verify_otp',
               json={"phone": "0812345678", "otp": "000000", "client_mac": "AA:BB:CC:DD:EE:FF"})
    check("verify_otp: OTP ผิด -> 400", r.status_code == 400)
    check("verify_otp: attempt counter ขึ้นเป็น 1", WIFI_PORTAL_OTP_ATTEMPT_COUNTER.get("0812345678") == 1)

    r = c.post('/api/wifi_portal/verify_otp',
               json={"phone": "0812345678", "otp": otp, "client_mac": "AA:BB:CC:DD:EE:FF"})
    check("verify_otp: OTP ถูก -> 200", r.status_code == 200)
    check("verify_otp: OTP ถูกลบออกจาก store หลังใช้แล้ว", "0812345678" not in WIFI_PORTAL_OTP_STORE)
    check("log: มี entry หลัง verify สำเร็จ", len(WIFI_PORTAL_LOG) >= 1)

    r = c.post('/api/wifi_portal/verify_otp',
               json={"phone": "0812345678", "otp": otp, "client_mac": "AA:BB:CC:DD:EE:FF"})
    check("verify_otp: ใช้ OTP ซ้ำไม่ได้ (replay) -> 400", r.status_code == 400)

    r = c.get('/api/wifi_portal/log')
    log_entry = r.get_json()["log"][-1]
    check("log: เบอร์โทรถูก mask (ไม่โชว์เต็ม)", log_entry["phone"] == "0812xxxx")

    r = c.post('/api/wifi_portal/request_otp', json={"phone": "0899999999", "room_number": "   "})
    check("request_otp: room_number เป็นช่องว่างล้วน -> ตกที่ PMS check -> 400", r.status_code == 400)

    c.post('/api/wifi_portal/request_otp', json={"phone": "0866666666", "room_number": "202"})
    for _ in range(WIFI_PORTAL_OTP_MAX_ATTEMPTS):
        c.post('/api/wifi_portal/verify_otp',
               json={"phone": "0866666666", "otp": "999999", "client_mac": "11:22:33:44:55:66"})
    r = c.post('/api/wifi_portal/verify_otp',
               json={"phone": "0866666666", "otp": "999999", "client_mac": "11:22:33:44:55:66"})
    check(f"verify_otp: กรอกผิดครบ {WIFI_PORTAL_OTP_MAX_ATTEMPTS} ครั้ง -> โดนบล็อก (429/400)",
          r.status_code in (429, 400))

    print(f"\n{sum(1 for _, ok in results if ok)}/{len(results)} tests passed")
    return all(ok for _, ok in results)


# ==========================================
# [ Module: meadow_town_builder ]
# เกมต้นแบบแนว "สร้างเมือง/ตกแต่งฟาร์ม + กาชาปอง + ร้านค้า + เนื้อเรื่อง" (ออกแบบเอง ไม่ได้ก๊อปปี้
# เกมเชิงพาณิชย์เกมไหน — ชื่อไอเทม/แบรนด์/ชื่อเกมทั้งหมดเป็นของใหม่ที่คิดขึ้นเอง) ระบบหลักที่ทำ:
#   1) ผู้เล่นมี "เมือง" เป็นกริด (x,y) วางของตกแต่งได้ ของตกแต่งเก็บใน inventory ก่อนค่อยเอาไปวาง
#   2) ร้านค้า (shop) ซื้อวัตถุดิบ/ของตกแต่งพื้นฐานด้วยเหรียญทอง (coins) หรือตั๋วแลก (tickets)
#   3) กาชาปอง (gacha) ใช้เพชร (gems) สุ่มของตกแต่งหายาก มีระบบ pity (การันตีของหายากถ้าสุ่มไม่ติดนานพอ)
#   4) เนื้อเรื่อง (story) เป็นบทเรียงลำดับ ต้องอ่านตามลำดับ อ่านจบได้รางวัล exp/coins แล้วเลเวลอัพได้
#   5) เควสประจำวันแบบง่าย (daily quest) เคลมรางวัลได้วันละครั้ง
# ทุก endpoint ใช้ pattern เดียวกับโมดูลอื่นในไฟล์นี้ (@require_auth_toggleable, uid มาจาก body หรือ
# fallback เป็น P["uid"], เก็บ state ใน dict ระดับโมดูล เพื่อความง่ายของต้นแบบ — โปรดักชันจริงควรย้าย
# ไปเก็บใน DB แทน dict ในหน่วยความจำ)
# ==========================================

