# ---- 7) API: เนื้อเรื่อง ----

@app.route('/api/meadow/story/list', methods=['GET'])
@require_auth_toggleable
def api_meadow_story_list():
    """คืนรายการบททั้งหมดพร้อมสถานะ: locked / unlocked (ยังไม่อ่าน) / read (อ่านแล้ว)
    ต้องอ่านเรียงลำดับ (บท N ปลดล็อกได้ต่อเมื่ออ่านบท N-1 จบแล้ว, บท 1 ปลดล็อกเสมอ)"""
    uid = request.args.get("uid", P["uid"])
    state = _meadow_get_player(uid)
    read_set = set(state["story_read"])
    chapters = []
    for ch in MEADOW_STORY_CHAPTERS:
        if ch["id"] in read_set:
            status = "read"
        elif ch["id"] == 1 or (ch["id"] - 1) in read_set:
            status = "unlocked"
        else:
            status = "locked"
        chapters.append({**ch, "status": status})
    return jsonify({"st": "ok", "chapters": chapters})


@app.route('/api/meadow/story/read', methods=['POST'])
@require_auth_toggleable
def api_meadow_story_read():
    """body: {uid, chapter_id} -> มาร์คว่าอ่านบทนี้จบแล้ว ได้รางวัล coins/exp ตามที่กำหนดในบทนั้น
    ต้องอ่านเรียงตามลำดับเท่านั้น (ข้ามบทไม่ได้), อ่านซ้ำบทเดิมไม่ได้รางวัลซ้ำ"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    chapter_id = body.get("chapter_id")

    chapter = next((c for c in MEADOW_STORY_CHAPTERS if c["id"] == chapter_id), None)
    if not chapter:
        return jsonify({"st": "error", "msg": f"ไม่พบบทที่ {chapter_id}"}), 400

    state = _meadow_get_player(uid)
    if chapter_id in state["story_read"]:
        return jsonify({"st": "error", "msg": "อ่านบทนี้ไปแล้ว ไม่ได้รางวัลซ้ำ"}), 400
    if chapter_id != 1 and (chapter_id - 1) not in state["story_read"]:
        return jsonify({"st": "error", "msg": f"ต้องอ่านบทที่ {chapter_id - 1} ให้จบก่อน"}), 400

    state["story_read"].append(chapter_id)
    state["coins"] += chapter["reward_coins"]
    leveled_up_to = _meadow_add_exp(state, chapter["reward_exp"])
    return jsonify({"st": "ok", "state": state,
                     "reward": {"coins": chapter["reward_coins"], "exp": chapter["reward_exp"]},
                     "leveled_up_to": leveled_up_to})


# ---- 8) API: เควสประจำวันแบบง่าย ----

@app.route('/api/meadow/daily_quest/claim', methods=['POST'])
@require_auth_toggleable
def api_meadow_daily_quest_claim():
    """body: {uid} -> เคลมรางวัลเควสประจำวัน (coins + gems) ได้วันละ 1 ครั้งต่อผู้เล่น
    เช็คจากวันที่ (YYYY-MM-DD) ของเวลาปัจจุบัน ไม่ใช่ระบบนับถอยหลัง 24 ชม. เป๊ะๆ (เหมือนเกมมือถือทั่วไป
    ที่รีเซ็ตตอนเที่ยงคืน ไม่ใช่รีเซ็ตครบ 24 ชม.นับจากตอนเคลม)"""
    body = request.json or {}
    uid = body.get("uid", P["uid"])
    state = _meadow_get_player(uid)
    today = datetime.now().strftime("%Y-%m-%d")

    if state["daily_quest_claimed_on"] == today:
        return jsonify({"st": "error", "msg": "วันนี้เคลมเควสประจำวันไปแล้ว กรุณากลับมาใหม่พรุ่งนี้"}), 400

    state["daily_quest_claimed_on"] = today
    state["coins"] += MEADOW_DAILY_QUEST_REWARD_COINS
    state["gems"] += MEADOW_DAILY_QUEST_REWARD_GEMS
    return jsonify({"st": "ok", "state": state,
                     "reward": {"coins": MEADOW_DAILY_QUEST_REWARD_COINS, "gems": MEADOW_DAILY_QUEST_REWARD_GEMS}})


