def _run_meadow_town_builder_selftests():
    """Self-test ของโมดูล meadow_town_builder เรียกด้วย: python3 <ไฟล์นี้> --selftest-meadow-town"""
    c = app.test_client()
    results = []

    def check(name, cond):
        results.append((name, cond))
        print(("✅ PASS " if cond else "❌ FAIL ") + name)

    uid = "selftest_meadow_player"

    r = c.get(f'/api/meadow/state?uid={uid}')
    check("state: ผู้เล่นใหม่ได้ coins เริ่มต้น 580", r.get_json()["state"]["coins"] == 580)

    r = c.post('/api/meadow/shop/buy_resource', json={"uid": uid, "item_id": "wheat", "qty": 1})
    check("buy_resource: ซื้อข้าวสาลีสำเร็จ -> 200", r.status_code == 200)
    check("buy_resource: ได้ข้าวสาลี 10 หน่วยเข้า inventory", r.get_json()["state"]["inventory"].get("wheat") == 10)
    check("buy_resource: เหรียญทองถูกหักถูกต้อง", r.get_json()["state"]["coins"] == 560)

    r = c.post('/api/meadow/shop/buy_resource', json={"uid": uid, "item_id": "not_exist", "qty": 1})
    check("buy_resource: item_id ไม่มีจริง -> 400", r.status_code == 400)

    r = c.post('/api/meadow/shop/buy_decor', json={"uid": uid, "item_id": "wood_crate"})
    check("buy_decor: ซื้อลังไม้สำเร็จ -> 200", r.status_code == 200)
    check("buy_decor: ลังไม้เข้า inventory", r.get_json()["state"]["inventory"].get("wood_crate") == 1)

    r = c.post('/api/meadow/decor/place', json={"uid": uid, "item_id": "wood_crate", "x": 2, "y": 3})
    check("decor/place: วางของสำเร็จ -> 200", r.status_code == 200)
    check("decor/place: ของหายจาก inventory หลังวาง", "wood_crate" not in r.get_json()["state"]["inventory"])
    check("decor/place: ปรากฏบน placed ที่ 2,3", r.get_json()["state"]["placed"].get("2,3") == "wood_crate")

    r = c.post('/api/meadow/decor/place', json={"uid": uid, "item_id": "wood_crate", "x": 2, "y": 3})
    check("decor/place: วางซ้ำตำแหน่งเดิมที่มีของอยู่แล้ว -> 400", r.status_code == 400)

    r = c.post('/api/meadow/decor/place', json={"uid": uid, "item_id": "wood_crate", "x": 999, "y": 3})
    check("decor/place: พิกัดเกินขอบแผนที่ -> 400", r.status_code == 400)

    r = c.post('/api/meadow/decor/remove', json={"uid": uid, "x": 2, "y": 3})
    check("decor/remove: ถอดของสำเร็จ -> 200", r.status_code == 200)
    check("decor/remove: ของกลับเข้า inventory", r.get_json()["state"]["inventory"].get("wood_crate") == 1)

    r = c.post('/api/meadow/decor/remove', json={"uid": uid, "x": 2, "y": 3})
    check("decor/remove: ถอดตำแหน่งว่างเปล่า -> 400", r.status_code == 400)

    # story ต้องอ่านเรียงลำดับ
    r = c.post('/api/meadow/story/read', json={"uid": uid, "chapter_id": 2})
    check("story/read: ข้ามไปอ่านบท 2 โดยยังไม่อ่านบท 1 -> 400", r.status_code == 400)

    r = c.post('/api/meadow/story/read', json={"uid": uid, "chapter_id": 1})
    check("story/read: อ่านบท 1 สำเร็จ -> 200", r.status_code == 200)
    coins_after_ch1 = r.get_json()["state"]["coins"]

    r = c.post('/api/meadow/story/read', json={"uid": uid, "chapter_id": 1})
    check("story/read: อ่านบท 1 ซ้ำ -> 400 (กันรับรางวัลซ้ำ)", r.status_code == 400)

    r = c.post('/api/meadow/story/read', json={"uid": uid, "chapter_id": 2})
    check("story/read: อ่านบท 2 ต่อได้แล้ว -> 200", r.status_code == 200)
    check("story/read: coins เพิ่มขึ้นจากรางวัลบท 2", r.get_json()["state"]["coins"] > coins_after_ch1)

    r = c.get(f'/api/meadow/story/list?uid={uid}')
    statuses = {c_["id"]: c_["status"] for c_ in r.get_json()["chapters"]}
    check("story/list: บท 1,2 เป็น read", statuses[1] == "read" and statuses[2] == "read")
    check("story/list: บท 3 unlocked (ยังไม่อ่าน)", statuses[3] == "unlocked")
    check("story/list: บท 4 ยัง locked", statuses[4] == "locked")

    # gacha: เพชรไม่พอ
    r = c.post('/api/meadow/gacha/pull', json={"uid": "poor_player_selftest", "times": 1})
    check("gacha/pull: เพชรไม่พอ -> 400", r.status_code == 400)

    # เติมเพชรให้ผู้เล่นทดสอบผ่าน state ตรงๆ (จำลองแอดมินเติมให้ เพื่อทดสอบระบบ pity แบบเจาะจง)
    MEADOW_PLAYERS[uid]["gems"] = 100000
    got_ssr_without_pity = False
    for i in range(MEADOW_GACHA_PITY_LIMIT - 1):
        r = c.post('/api/meadow/gacha/pull', json={"uid": uid, "times": 1})
        check(f"gacha/pull: ครั้งที่ {i+1}/{MEADOW_GACHA_PITY_LIMIT-1} ก่อนครบ pity -> 200", r.status_code == 200)
        if r.get_json()["results"][0]["rarity"] == "SSR":
            got_ssr_without_pity = True

    r = c.post('/api/meadow/gacha/pull', json={"uid": uid, "times": 1})
    result = r.get_json()["results"][0]
    if not got_ssr_without_pity:
        check(f"gacha/pull: ครั้งที่ {MEADOW_GACHA_PITY_LIMIT} การันตี SSR (pity)", result["rarity"] == "SSR" and result["pity_triggered"])
    else:
        check("gacha/pull: เคยได้ SSR ระหว่างทางแล้ว ตัวนับ pity ถูกรีเซ็ตไปก่อน (ข้ามเช็คนี้)", True)

    r = c.post('/api/meadow/gacha/pull', json={"uid": uid, "times": 3})
    check("gacha/pull: times ที่ไม่ใช่ 1 หรือ 10 -> 400", r.status_code == 400)

    # daily quest
    r = c.post('/api/meadow/daily_quest/claim', json={"uid": uid})
    check("daily_quest/claim: เคลมครั้งแรกของวัน -> 200", r.status_code == 200)
    r = c.post('/api/meadow/daily_quest/claim', json={"uid": uid})
    check("daily_quest/claim: เคลมซ้ำวันเดียวกัน -> 400", r.status_code == 400)

    print(f"\n{sum(1 for _, ok in results if ok)}/{len(results)} tests passed")
    return all(ok for _, ok in results)


# ==========================================
# [ 52. ID Screening API ] — เครื่องคัดกรองรายการ ID (Validate → Dedupe → Filter → Count)
# ==========================================
# เพิ่มตามคำขอ: โมดูล "ตัวเดียว" หน้าที่ตรง ๆ คือ รับรายการ ID -> คัดกรอง -> ค้นหา/นับ/แยกสถานะ
# แนวเดียวกับ FastAPI Inventory Management API (list/filter items) แต่ปรับให้ item = uid ของ VMAX
#
# ตั้งใจให้เป็น "เครื่องคัดกรองข้อมูล" อย่างเดียว ไม่ไปแก้/แทนที่ระบบ account เดิม:
#   - อ่านจาก USER_STORE (บัญชีที่มีอยู่จริง) และ BANNED_UIDS (รายชื่อแบน) แบบ read-only เท่านั้น
#   - ไม่มีจุดไหนใน section นี้เขียนกลับเข้า USER_STORE / BANNED_UIDS / ฐานข้อมูลเดิม
# ส่วนกฎว่า "ID ไหนผ่าน/ไม่ผ่าน" กำหนดเองได้ผ่าน "rules" ใน body ของ /screen (ดู docstring
# ของ _id_screening_run ด้านล่าง) — ระบบอื่นของ VMAX ยังทำงานเป็นเจ้าของข้อมูลของมันเหมือนเดิมทุกอย่าง

_ID_SCREENING_UID_RE = re.compile(r'^[A-Za-z0-9_\-\.]{1,64}$')


def _id_screening_validate_one(raw_id) -> tuple[bool, str]:
    """ตรวจรูปแบบ ID ตัวเดียว (แค่ format ยังไม่เช็คกับ DB) -> คืน (valid, reason)"""
    if raw_id is None:
        return False, "id เป็นค่าว่าง (None)"
    if not isinstance(raw_id, str):
        return False, "id ต้องเป็น string"
    s = raw_id.strip()
    if not s:
        return False, "id เป็นสตริงว่างเปล่า"
    if len(s) > 64:
        return False, "id ยาวเกิน 64 ตัวอักษร"
    if not _ID_SCREENING_UID_RE.match(s):
        return False, "id มีอักขระที่ไม่อนุญาต (อนุญาตแค่ a-z A-Z 0-9 _ - .)"
    return True, "ok"


def _id_screening_status_of(uid: str) -> dict:
    """เช็คสถานะ id เทียบกับระบบ account เดิมของ VMAX — อ่านอย่างเดียว ไม่แก้อะไรทั้งสิ้น"""
    return {
        "known_account": uid in USER_STORE,
        "banned": uid in BANNED_UIDS,
    }


def _id_screening_run(ids: list, rules: dict) -> dict:
    """
    Pipeline หลักของเครื่องคัดกรอง: รับรายการ -> (dedupe) -> คัดกรองตามกฎ -> นับ/แยกสถานะ

    rules ที่รองรับ (ทั้งหมด optional — ไม่ใส่ = ไม่บังคับกฎนั้น):
      - dedupe (bool, default True)            ตัด id ที่ซ้ำออก (เก็บตัวที่เจอก่อน)
      - exclude_banned (bool, default False)   ตัด id ที่อยู่ใน BANNED_UIDS ทิ้ง
      - require_known_account (bool, default False)
            ต้องเจอใน USER_STORE (ระบบบัญชีเดิม) เท่านั้นถึงจะผ่าน
      - whitelist (list[str])                  ถ้าใส่มา -> เหลือเฉพาะ id ที่อยู่ใน whitelist นี้
      - blacklist (list[str])                  id ไหนอยู่ใน blacklist -> ไม่ผ่านทันที
      - pattern (str, regex)                   ต้อง match เพิ่มเติมจาก format พื้นฐาน
    """
    dedupe = rules.get("dedupe", True)
    exclude_banned = bool(rules.get("exclude_banned", False))
    require_known = bool(rules.get("require_known_account", False))
    whitelist = set(rules.get("whitelist") or [])
    blacklist = set(rules.get("blacklist") or [])
    custom_pattern = rules.get("pattern")
    custom_re = None
    if custom_pattern:
        try:
            custom_re = re.compile(custom_pattern)
        except re.error as e:
            return {"error": f"'pattern' เป็น regex ที่ผิดพลาด: {e}"}

    seen = set()
    duplicates = 0
    passed = []
    rejected = []

    for raw in ids:
        if dedupe:
            dedupe_key = raw.strip() if isinstance(raw, str) else json.dumps(raw, sort_keys=True, default=str)
            if dedupe_key in seen:
                duplicates += 1
                continue
            seen.add(dedupe_key)

        ok, reason = _id_screening_validate_one(raw)
        if not ok:
            rejected.append({"id": raw, "reason": reason})
            continue

        uid_str = raw.strip()
        status = _id_screening_status_of(uid_str)

        if exclude_banned and status["banned"]:
            rejected.append({"id": uid_str, "reason": "อยู่ในรายชื่อแบน (BANNED_UIDS)"})
            continue
        if require_known and not status["known_account"]:
            rejected.append({"id": uid_str, "reason": "ไม่พบในระบบ account เดิม (USER_STORE)"})
            continue
        if whitelist and uid_str not in whitelist:
            rejected.append({"id": uid_str, "reason": "ไม่อยู่ใน whitelist ที่กำหนด"})
            continue
        if uid_str in blacklist:
            rejected.append({"id": uid_str, "reason": "อยู่ใน blacklist ที่กำหนด"})
            continue
        if custom_re and not custom_re.match(uid_str):
            rejected.append({"id": uid_str, "reason": "ไม่ตรง pattern ที่กำหนด"})
            continue

        passed.append({"id": uid_str, **status})

    return {
        "total_received": len(ids),
        "duplicates_removed": duplicates,
        "passed_count": len(passed),
        "rejected_count": len(rejected),
        "passed": passed,
        "rejected": rejected,
    }


@app.route('/api/id-screening/validate', methods=['POST'])
def api_id_screening_validate():
    """ตรวจรูปแบบ + สถานะของแต่ละ id ในรายการ (ไม่คัดออก แค่รายงานผลทีละตัว)"""
    data = request.get_json(silent=True) or {}
    ids = data.get("ids")
    if not isinstance(ids, list):
        return jsonify({"error": "ต้องส่ง 'ids' มาเป็น list"}), 400

    results = []
    for raw in ids:
        ok, reason = _id_screening_validate_one(raw)
        entry = {"id": raw, "valid": ok, "reason": reason}
        if ok:
            entry.update(_id_screening_status_of(raw.strip()))
        results.append(entry)

    return jsonify({
        "total": len(ids),
        "valid_count": sum(1 for r in results if r["valid"]),
        "invalid_count": sum(1 for r in results if not r["valid"]),
        "results": results,
    })


@app.route('/api/id-screening/deduplicate', methods=['POST'])
def api_id_screening_deduplicate():
    """ตัด id ที่ซ้ำออกจากรายการ (เก็บลำดับเดิม, เก็บตัวที่เจอก่อน)"""
    data = request.get_json(silent=True) or {}
    ids = data.get("ids")
    if not isinstance(ids, list):
        return jsonify({"error": "ต้องส่ง 'ids' มาเป็น list"}), 400

    seen = set()
    unique_ids = []
    for raw in ids:
        key = raw.strip() if isinstance(raw, str) else json.dumps(raw, sort_keys=True, default=str)
        if key in seen:
            continue
        seen.add(key)
        unique_ids.append(raw)

    return jsonify({
        "total_received": len(ids),
        "unique_count": len(unique_ids),
        "duplicates_removed": len(ids) - len(unique_ids),
        "ids": unique_ids,
    })


@app.route('/api/id-screening/count', methods=['POST'])
def api_id_screening_count():
    """นับสรุปรายการ id: ทั้งหมด / ไม่ซ้ำ / รู้จักในระบบบัญชีเดิม / โดนแบน"""
    data = request.get_json(silent=True) or {}
    ids = data.get("ids")
    if not isinstance(ids, list):
        return jsonify({"error": "ต้องส่ง 'ids' มาเป็น list"}), 400

    str_ids = [i.strip() for i in ids if isinstance(i, str)]
    return jsonify({
        "total": len(ids),
        "unique": len(set(str_ids)) + sum(1 for i in ids if not isinstance(i, str)),
        "known_account": sum(1 for i in str_ids if i in USER_STORE),
        "banned": sum(1 for i in str_ids if i in BANNED_UIDS),
    })


@app.route('/api/id-screening/screen', methods=['POST'])
def api_id_screening_screen():
    """
    Endpoint หลักของโมดูล: รับรายการ -> คัดกรอง -> ค้นหา/นับ/แยกสถานะ -> ส่งรายการที่ผ่านกลับ
    body:
      {
        "ids": ["u1", "u2", ...],
        "rules": { ... ดูตัวเลือกทั้งหมดใน docstring ของ _id_screening_run ... }
      }
    """
    data = request.get_json(silent=True) or {}
    ids = data.get("ids")
    if not isinstance(ids, list):
        return jsonify({"error": "ต้องส่ง 'ids' มาเป็น list"}), 400

    rules = data.get("rules") or {}
    if not isinstance(rules, dict):
        return jsonify({"error": "'rules' ต้องเป็น object"}), 400

    result = _id_screening_run(ids, rules)
    if "error" in result:
        return jsonify(result), 400
    return jsonify(result)


@app.route('/api/id-screening/status', methods=['GET'])
def api_id_screening_status():
    """ข้อมูลทั่วไปของโมดูล (ไว้เช็คว่าติดตั้ง/เชื่อมกับระบบบัญชีเดิมถูกไหม)"""
    return jsonify({
        "module": "id-screening",
        "description": "เครื่องคัดกรองรายการ ID แบบ read-only ไม่แก้ระบบ account/BANNED_UIDS เดิม",
        "known_accounts": len(USER_STORE),
        "banned_accounts": len(BANNED_UIDS),
        "endpoints": [
            "POST /api/id-screening/validate",
            "POST /api/id-screening/deduplicate",
            "POST /api/id-screening/count",
            "POST /api/id-screening/screen",
            "GET  /api/id-screening/status",
        ],
    })


def _run_id_screening_selftests():
    """Self-test ของโมดูล id-screening — เรียกด้วย:
    python3 <ไฟล์นี้> --selftest-id-screening"""
    c = app.test_client()
    results = []

    def check(name, cond):
        results.append((name, cond))
        print(("✅ PASS " if cond else "❌ FAIL ") + name)

    # เตรียมข้อมูลทดสอบแบบไม่แตะของจริง: เพิ่ม uid ทดสอบเข้า USER_STORE / BANNED_UIDS ชั่วคราว
    USER_STORE["id_screen_known_user"] = {"algo": "pbkdf2"}
    BANNED_UIDS.add("id_screen_banned_user")

    try:
        # validate: รูปแบบผิด vs ถูก
        r = c.post('/api/id-screening/validate', json={"ids": ["ok_id_1", "  ", "มีตัวไทย!", 12345]})
        body = r.get_json()
        check("validate: status 200", r.status_code == 200)
        check("validate: นับ valid/invalid ถูกต้อง", body["valid_count"] == 1 and body["invalid_count"] == 3)

        # deduplicate
        r = c.post('/api/id-screening/deduplicate', json={"ids": ["a", "b", "a", "c", "b", "a"]})
        body = r.get_json()
        check("deduplicate: เหลือ id ไม่ซ้ำ 3 ตัว", body["unique_count"] == 3)
        check("deduplicate: นับจำนวนซ้ำที่ตัดออกถูกต้อง", body["duplicates_removed"] == 3)

        # count
        r = c.post('/api/id-screening/count', json={"ids": ["id_screen_known_user", "id_screen_banned_user", "unknown_id"]})
        body = r.get_json()
        check("count: known_account นับถูก", body["known_account"] == 1)
        check("count: banned นับถูก", body["banned"] == 1)

        # screen: pipeline เต็ม พร้อม rules
        r = c.post('/api/id-screening/screen', json={
            "ids": ["id_screen_known_user", "id_screen_banned_user", "id_screen_banned_user", "bad id!!", "id_screen_known_user"],
            "rules": {"exclude_banned": True},
        })
        body = r.get_json()
        check("screen: status 200", r.status_code == 200)
        check("screen: ตัด id ซ้ำออก (duplicates_removed >= 1)", body["duplicates_removed"] >= 1)
        check("screen: id ที่โดนแบนถูกคัดออก", all(p["id"] != "id_screen_banned_user" for p in body["passed"]))
        check("screen: id รูปแบบผิดถูกคัดออก และมีเหตุผลกำกับ",
              any(rej["id"] == "bad id!!" for rej in body["rejected"]))
        check("screen: id ที่ผ่านครบตามคาด (เหลือแค่ known_user)",
              body["passed_count"] == 1 and body["passed"][0]["id"] == "id_screen_known_user")

        # screen: require_known_account
        r = c.post('/api/id-screening/screen', json={
            "ids": ["id_screen_known_user", "totally_unknown_id"],
            "rules": {"require_known_account": True},
        })
        body = r.get_json()
        check("screen: require_known_account คัด id ที่ไม่รู้จักออก", body["passed_count"] == 1)

        # screen: rules ผิด type -> 400
        r = c.post('/api/id-screening/screen', json={"ids": ["x"], "rules": "not-an-object"})
        check("screen: rules ผิด type -> 400", r.status_code == 400)

        # status
        r = c.get('/api/id-screening/status')
        check("status: status 200 และมี known_accounts", r.status_code == 200 and "known_accounts" in r.get_json())
    finally:
        # เก็บกวาดข้อมูลทดสอบ ไม่ให้ตกค้างปนกับของจริง
        USER_STORE.pop("id_screen_known_user", None)
        BANNED_UIDS.discard("id_screen_banned_user")

    print(f"\n{sum(1 for _, ok in results if ok)}/{len(results)} tests passed")
    return all(ok for _, ok in results)


# ==========================================
# [ N. ระบบทำความคุ้นเคย (Pet Affection & Trust System) ]
# แทนที่จะโยนไอเทมทีเดียวติด ให้ใช้เกจ "ความไว้ใจ" (Trust Meter) และ "ความหิว"
# (Hunger Meter) ประกอบกับนิสัยของสัตว์แต่ละตัว (Behavioral Types) เพื่อให้ผู้เล่น
# รู้สึกว่าสัตว์เลี้ยงเลือกที่จะอยู่กับเราเพราะ "ความรักและความผูกพัน" ไม่ใช่เพราะ
# ถูกบังคับ/ขังในลูกบอล
#   1) ให้อาหารตรงประเภท -> trust ขึ้นเร็ว, ให้ของที่เกลียด -> trust ลด/อาจวิ่งหนี
#   2) พอ trust ถึงเกณฑ์หนึ่ง จะเข้ามาใกล้ ให้กดปุ่ม "ลูบหัว/เกาพุง" ได้
#   3) ระหว่างลูบหัวมีมินิเกม QTE จังหวะหัวใจที่เต้นช้าลง กดสำเร็จ = ยอมเป็นพวกทันที
#   4) แบ่งนิสัย 3 สาย: greedy (ตะกละ) / skittish (ขี้กลัว) / aggressive (ดุร้าย)
#      แต่ละสายมีวิธีเข้าหาต่างกัน (ดู PET_BEHAVIOR_TYPES ด้านล่าง)
# ==========================================

PET_BEHAVIOR_TYPES = {
    "greedy":     {"name_th": "สายตะกละ",  "approach": "เทอาหารทิ้งไว้แล้วแอบดู พอเริ่มกินจนอิ่มค่อยๆ เดินเข้าไปลูบหัว"},
    "skittish":   {"name_th": "สายขี้กลัว", "approach": "ต้องกดหมอบ (Crouch) ค่อยๆ ยื่นอาหารให้จากระยะไกล พอชินกันแล้วถึงจะยอมให้ลูบหัว"},
    "aggressive": {"name_th": "สายดุร้าย",  "approach": "ต้องสู้กันก่อนให้มันเหนื่อย จากนั้นยื่นอาหารรักษาแผลให้ เปลี่ยนความกลัวเป็นความซาบซึ้ง แล้วค่อยเข้าไปปลอบใจด้วยการลูบหัว"},
}

PET_PET_UNLOCK_TRUST = 40   # เกณฑ์ trust ที่ต้องถึงก่อนจะ "ลูบหัว" ได้ (0-100)
PET_TAME_TRUST = 80         # เกณฑ์ trust ที่ถือว่า "เชื่อง" เต็มที่ / ตามติดผู้เล่น

# ==========================================
# [ ระบบ species: แต่ละสายพันธุ์ต้านทาน/อ่อนแอต่อวิธีจับแต่ละแบบไม่เท่ากัน ]
# ค่าใน "resistances" คือตัวคูณโอกาสสำเร็จของแต่ละวิธี (method key ตรงกับ
# CAPTURE_METHODS ด้านล่าง): > 1.0 = สายพันธุ์นี้ "อ่อนแอ" ต่อวิธีนั้น (จับง่ายขึ้น),
# < 1.0 = "ต้านทาน" (จับยากขึ้น), = 1.0 = เฉยๆ ไม่มีผล
# species ที่ไม่อยู่ในตารางนี้ (หรือไม่ส่งมาเลย) ถือว่าไม่มีผลต่อโอกาสใดๆ ทั้งสิ้น
# (multiplier = 1.0 ทุกวิธี, ไม่มี hint) — ของเดิมที่ไม่เคยส่ง species มาก่อนหน้านี้
# จึงยังทำงานเหมือนเดิมทุกประการ ไม่ breaking change
