# ==========================================
# [ ระบบเติบโต & โหมดบังคับควบคุม (Growth & Pilot Mode) ]
# สัตว์เลี้ยงที่รับเป็นพวก (captured) แล้วจะ "โตขึ้น" ตามความคุ้นเคยที่สะสมมา (care_points)
# ซึ่งได้จากการดูแล (ลูบหัว/ผ่าน QTE ในโมดูล pet-affection ด้านบน) ไล่ระดับ 3 ขั้น:
#   hatchling (วัยเด็ก) -> juvenile (วัยรุ่น) -> adult (โตเต็มวัย)
# เมื่อโตเต็มวัย (adult) แล้วเท่านั้น ผู้เล่นถึงจะเข้า "โหมดบังคับควบคุม" (piloted) ได้ — คือ
# ควบคุมสัตว์เลี้ยงตัวนั้นโดยตรงแทนการสั่งอ้อมๆ ผ่าน feed/pet เหมือนเดิม แล้วใช้ร่างที่บังคับ
# อยู่นี้ไปโจมตี/ลด HP มอนสเตอร์ป่าตัวอื่นก่อน เพื่อช่วยให้จับตัวนั้นได้ง่ายขึ้น (เข้ากันได้กับ
# ระบบแปลงร่างด้านบน — ถ้า transformed แล้วด้วย โจมตีตอนบังคับควบคุมจะแรงขึ้นอีก)
# ==========================================
GROWTH_STAGES_ORDER = ["hatchling", "juvenile", "adult"]

GROWTH_STAGE_INFO = {
    "hatchling": {"name_th": "วัยเด็ก", "care_points_required": 0},
    "juvenile":  {"name_th": "วัยรุ่น (โตครึ่งตัว)", "care_points_required": 40},
    "adult":     {"name_th": "โตเต็มวัย", "care_points_required": 100},
}

GROWTH_CARE_POINTS_PET = 6      # care_points ที่ได้ต่อการลูบหัวสำเร็จ 1 ครั้ง
GROWTH_CARE_POINTS_QTE = 10     # care_points ที่ได้ต่อการผ่าน QTE สำเร็จ 1 ครั้ง


def _pet_growth_stage_for_points(care_points):
    """คำนวณ growth_stage ที่ 'ควรจะเป็น' จากค่า care_points สะสม (ไล่จากขั้นสูงสุดลงมา)"""
    stage = GROWTH_STAGES_ORDER[0]
    for s in GROWTH_STAGES_ORDER:
        if care_points >= GROWTH_STAGE_INFO[s]["care_points_required"]:
            stage = s
    return stage


def _pet_apply_growth(st, points_gained):
    """เพิ่ม care_points ให้สัตว์เลี้ยง แล้วเลื่อนขั้น growth_stage ถ้าถึงเกณฑ์ (เลื่อนขึ้นได้ทาง
    เดียว ไม่มีการถอยขั้นย้อนกลับ) คืนค่า True ถ้าเพิ่งเลื่อนขั้นในครั้งนี้"""
    st["care_points"] = st["care_points"] + points_gained
    new_stage = _pet_growth_stage_for_points(st["care_points"])
    old_index = GROWTH_STAGES_ORDER.index(st["growth_stage"])
    new_index = GROWTH_STAGES_ORDER.index(new_stage)
    if new_index > old_index:
        st["growth_stage"] = new_stage
        return True
    return False


PET_STATE_STORE = {}  # key: "owner_id::pet_id" -> state dict


def _pet_key(owner_id, pet_id):
    return f"{owner_id}::{pet_id}"


def _pet_clamp(v, lo=0, hi=100):
    return max(lo, min(hi, v))


def _pet_get_or_create(owner_id, pet_id, behavior=None, favorite_food=None, hated_food=None, species=None):
    key = _pet_key(owner_id, pet_id)
    if key not in PET_STATE_STORE:
        _species_profile = _pet_species_profile(species)
        PET_STATE_STORE[key] = {
            "owner_id": owner_id,
            "pet_id": pet_id,
            "behavior": behavior if behavior in PET_BEHAVIOR_TYPES else random.choice(list(PET_BEHAVIOR_TYPES.keys())),
            "trust": 0,
            "hunger": 50,
            "favorite_food": favorite_food or "default_food",
            "hated_food": hated_food or "junk_food",
            "fled": False,
            "tamed": False,
            "crouched": False,
            "fight_progress": 0,   # ใช้กับสาย aggressive: สะสมจนถึงเกณฑ์แล้ว "เหนื่อย" พร้อมรับอาหารรักษาแผล
            "wounded": False,
            "pet_count": 0,
            "last_qte": None,
            "created_at": time.time(),
            # --- ฟิลด์เพิ่มสำหรับโมดูล capture-method (บอล/ตาข่าย/ยาสลบ/ติดสินบน) ---
            "hp": 100,
            "max_hp": 100,
            "asleep": False,
            "netted_turns": 0,      # จำนวนครั้งถัดไปที่ห้ามหนี (จากตาข่าย)
            "capture_attempts": 0,
            "captured": False,
            "capture_method_used": None,
            "preferred_capture_method": None,  # metadata สำหรับ UI เท่านั้น ไม่บังคับ endpoint ไหนใช้ได้
            # --- ฟิลด์เพิ่มสำหรับ species: กำหนดตอนสร้างครั้งแรกเท่านั้น (เหมือน behavior) ---
            "species": species,  # None/ไม่รู้จัก = ไม่มีผลต่อโอกาสจับใดๆ
            "capture_hint": _species_profile.get("hint_th"),  # ข้อความแนะนำเฉพาะสายพันธุ์ (ถ้ามี)
            # --- ฟิลด์เพิ่มสำหรับระบบแปลงร่าง (Monster Transformation) ---
            "transformed": False,
            "monster_form": None,       # ชื่อร่างมอนสเตอร์หลังแปลงร่างสำเร็จ (เช่น "dire_hare")
            "transform_item_used": None,
            # --- ฟิลด์เพิ่มสำหรับระบบเติบโต & โหมดบังคับควบคุม (Growth & Pilot Mode) ---
            "growth_stage": GROWTH_STAGES_ORDER[0],   # hatchling -> juvenile -> adult
            "care_points": 0,
            "piloted": False,
            "pilot_form": None,   # ชื่อร่างที่ใช้ตอนบังคับควบคุมอยู่ (ตั้งค่าตอน pilot-start)
        }
    return PET_STATE_STORE[key]


def pet_feed(owner_id, pet_id, food_item, behavior=None, species=None):
    """ให้อาหารสัตว์เลี้ยง — ปรับ trust/hunger ตามว่าเป็นอาหารโปรดหรือของที่มันเกลียด
    และตามนิสัย (behavior) เช่น สาย aggressive ต้องสู้ให้เหนื่อย/บาดเจ็บก่อน ถึงจะรับ
    อาหารรักษาแผลจากเราได้จริง"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    if st["fled"]:
        return {"error": "สัตว์เลี้ยงตัวนี้วิ่งหนีไปแล้ว ต้องตามหาใหม่ก่อนถึงจะให้อาหารได้", "state": st}

    behavior_type = st["behavior"]

    if st["netted_turns"] > 0:
        st["netted_turns"] -= 1

    if behavior_type == "aggressive" and not st["wounded"]:
        return {
            "error": "สัตว์ตัวนี้ยังดุอยู่ ต้องทำให้มันเหนื่อยก่อน (ดู endpoint /fight) ถึงจะยอมรับอาหารรักษาแผล",
            "state": st,
        }

    if behavior_type == "skittish" and not st["crouched"] and st["trust"] < PET_PET_UNLOCK_TRUST and st["netted_turns"] <= 0:
        if random.random() < 0.35:
            st["fled"] = True
            return {"result": "flee", "message": "สัตว์เลี้ยงตกใจแล้ววิ่งหนี ลองกดหมอบ (crouch) ก่อนค่อยยื่นอาหารครั้งหน้า", "state": st}

    is_favorite = (food_item == st["favorite_food"])
    is_hated = (food_item == st["hated_food"])

    if is_favorite:
        trust_gain = 18 if behavior_type == "greedy" else 12  # สายตะกละดีใจกับของโปรดเป็นพิเศษ
        hunger_gain = 25
        result = "loved_it"
    elif is_hated:
        trust_gain = -15
        hunger_gain = 5
        result = "hated_it"
        if st["trust"] < 30 and st["netted_turns"] <= 0 and random.random() < 0.4:
            st["fled"] = True
    else:
        trust_gain = 4
        hunger_gain = 15
        result = "ate_it"

    if behavior_type == "aggressive" and st["wounded"]:
        trust_gain += 20
        st["wounded"] = False
        st["fight_progress"] = 0
        result = "healed_and_soothed"

    st["trust"] = _pet_clamp(st["trust"] + trust_gain)
    st["hunger"] = _pet_clamp(st["hunger"] + hunger_gain)

    return {
        "result": result if not st["fled"] else "flee",
        "trust": st["trust"],
        "hunger": st["hunger"],
        "can_pet": st["trust"] >= PET_PET_UNLOCK_TRUST and not st["fled"],
        "state": st,
    }


def pet_crouch(owner_id, pet_id, crouched=True, behavior=None, species=None):
    """กดหมอบ/ยืนขึ้น — ใช้กับสายขี้กลัวเพื่อเข้าหาแบบไม่ให้ตกใจ"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    st["crouched"] = bool(crouched)
    return {"crouched": st["crouched"], "state": st}


def pet_fight_round(owner_id, pet_id, behavior=None, species=None):
    """สู้กับสัตว์สายดุร้ายหนึ่งยก — สะสมจนเหนื่อย (wounded) แล้วเปลี่ยนไปยื่นอาหารรักษาแผลแทน"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    if st["behavior"] != "aggressive":
        return {"error": "ใช้ endpoint นี้กับสัตว์สายดุร้ายเท่านั้น", "state": st}
    if st["wounded"]:
        return {"message": "สัตว์เหนื่อยพอแล้ว ยื่นอาหารรักษาแผลได้เลย (/feed)", "state": st}

    st["fight_progress"] = _pet_clamp(st["fight_progress"] + random.randint(15, 30))
    if st["fight_progress"] >= 100:
        st["wounded"] = True
        return {"result": "worn_out", "message": "สัตว์เหนื่อยแล้ว ยื่นอาหารรักษาแผลเพื่อปลอบใจแทนการสู้ต่อ", "state": st}
    return {"result": "still_fighting", "fight_progress": st["fight_progress"], "state": st}


def pet_qte_resolve(owner_id, pet_id, success, behavior=None, species=None):
    """มินิเกมจังหวะหัวใจระหว่างลูบหัว — กดตามจังหวะที่เต้นช้าลงของสัตว์เลี้ยงเพื่อแสดงความ
    ผ่อนคลาย ถ้ากดสำเร็จ สัตว์เลี้ยงจะยอมเป็นพวกทันทีเมื่อ trust ถึงเกณฑ์"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    if st["trust"] < PET_PET_UNLOCK_TRUST:
        return {"error": f"ต้องมี trust อย่างน้อย {PET_PET_UNLOCK_TRUST} ก่อนถึงจะเริ่มลูบหัวได้", "state": st}

    st["last_qte"] = {"success": bool(success), "at": time.time()}
    if success:
        st["trust"] = _pet_clamp(st["trust"] + 10)
        if st["trust"] >= PET_TAME_TRUST:
            st["tamed"] = True
        grew_up = _pet_apply_growth(st, GROWTH_CARE_POINTS_QTE)
        return {
            "result": "success", "tamed": st["tamed"], "trust": st["trust"],
            "growth_stage": st["growth_stage"], "care_points": st["care_points"], "grew_up": grew_up,
            "state": st,
        }
    else:
        st["trust"] = _pet_clamp(st["trust"] - 5)
        return {"result": "fail", "trust": st["trust"], "state": st}


def pet_pet_head(owner_id, pet_id, behavior=None, species=None):
    """ลูบหัว/เกาพุง — ต้องผ่านเกณฑ์ trust ก่อน เพิ่ม trust เล็กน้อยทุกครั้งที่ทำสำเร็จ"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    if st["fled"]:
        return {"error": "สัตว์เลี้ยงตัวนี้วิ่งหนีไปแล้ว", "state": st}
    if st["trust"] < PET_PET_UNLOCK_TRUST:
        return {"error": f"สัตว์เลี้ยงยังไม่ไว้ใจพอ (ต้องการ trust >= {PET_PET_UNLOCK_TRUST})", "state": st}

    st["pet_count"] += 1
    st["trust"] = _pet_clamp(st["trust"] + 3)
    if st["trust"] >= PET_TAME_TRUST:
        st["tamed"] = True
    grew_up = _pet_apply_growth(st, GROWTH_CARE_POINTS_PET)
    return {
        "pet_count": st["pet_count"], "trust": st["trust"], "tamed": st["tamed"],
        "growth_stage": st["growth_stage"], "care_points": st["care_points"], "grew_up": grew_up,
        "state": st,
    }


@app.route('/api/pet-affection/feed', methods=['POST'])
@require_auth
def api_pet_affection_feed():
    data = request.get_json(silent=True) or {}
    auth_uid = getattr(request, "vmax_uid", "")
    owner_id = data.get("owner_id") or auth_uid
    if owner_id != auth_uid:
        return jsonify({"error": "owner_id ต้องตรงกับบัญชีที่ล็อกอิน"}), 403
    pet_id = data.get("pet_id")
    food_item = data.get("food_item")
    behavior = data.get("behavior")
    species = data.get("species")
    if not owner_id or not pet_id or not food_item:
        return jsonify({"error": "ต้องส่ง owner_id, pet_id, food_item"}), 400
    return jsonify(pet_feed(owner_id, pet_id, food_item, behavior=behavior, species=species))


