@app.route('/api/pet-affection/status', methods=['GET'])
@require_auth
def api_pet_affection_status():
    auth_uid = getattr(request, "vmax_uid", "")
    owner_id = request.args.get("owner_id") or auth_uid
    if owner_id != auth_uid:
        return jsonify({"error": "owner_id ต้องตรงกับบัญชีที่ล็อกอิน"}), 403
    pet_id = request.args.get("pet_id")
    if not owner_id or not pet_id:
        return jsonify({"error": "ต้องส่ง owner_id, pet_id เป็น query param"}), 400
    key = _pet_key(owner_id, pet_id)
    st = PET_STATE_STORE.get(key)
    if not st:
        return jsonify({"error": "ไม่พบสัตว์เลี้ยงตัวนี้ (ยังไม่เคยมีการโต้ตอบ)"}), 404
    return jsonify(st)


