@app.route('/api/pet-affection/species', methods=['GET'])
def api_pet_affection_species():
    """ตารางสายพันธุ์ทั้งหมด: แต่ละสายพันธุ์ต้านทาน/อ่อนแอต่อวิธีจับไหนบ้าง (resistances)
    พร้อม hint ข้อความแนะนำเฉพาะสายพันธุ์ ไว้ให้ UI เด้งบอกผู้เล่นตอนเจอสัตว์ตัวนั้น"""
    return jsonify({
        "module": "pet-affection-species",
        "description": "ตัวคูณโอกาสสำเร็จของแต่ละวิธีจับ (ดู /api/capture/methods) แยกตามสายพันธุ์ "
                        "> 1.0 = สายพันธุ์นี้อ่อนแอต่อวิธีนั้น (จับง่ายขึ้น), < 1.0 = ต้านทาน (จับยากขึ้น). "
                        "สายพันธุ์ที่ไม่อยู่ในตารางนี้ถือว่าไม่มีผลใดๆ (multiplier 1.0 ทุกวิธี)",
        "species": SPECIES_CAPTURE_PROFILES,
    })


def _run_pet_affection_selftests():
    """Self-test ของโมดูล pet-affection — เรียกด้วย:
    python3 <ไฟล์นี้> --selftest-pet-affection"""
    c = app.test_client()
    results = []

    def check(name, cond):
        results.append((name, cond))
        print(("✅ PASS " if cond else "❌ FAIL ") + name)

    try:
        for k in list(PET_STATE_STORE.keys()):
            if k.startswith("pet_test_owner::"):
                del PET_STATE_STORE[k]

        r = c.post('/api/pet-affection/feed', json={
            "owner_id": "pet_test_owner", "pet_id": "greedy1",
            "food_item": "default_food", "behavior": "greedy",
        })
        body = r.get_json()
        check("greedy feed favorite: status 200", r.status_code == 200)
        check("greedy feed favorite: trust เพิ่มขึ้น", body["trust"] > 0)

        r = c.post('/api/pet-affection/pet', json={"owner_id": "pet_test_owner", "pet_id": "greedy1"})
        check("pet ก่อนถึงเกณฑ์ trust: error", r.status_code == 200 and "error" in r.get_json())

        for _ in range(5):
            c.post('/api/pet-affection/feed', json={
                "owner_id": "pet_test_owner", "pet_id": "greedy1", "food_item": "default_food",
            })
        r = c.post('/api/pet-affection/pet', json={"owner_id": "pet_test_owner", "pet_id": "greedy1"})
        body = r.get_json()
        check("pet หลังถึงเกณฑ์ trust: สำเร็จ", "pet_count" in body and body["pet_count"] >= 1)

        r = c.post('/api/pet-affection/feed', json={
            "owner_id": "pet_test_owner", "pet_id": "fierce1",
            "food_item": "default_food", "behavior": "aggressive",
        })
        check("aggressive feed ก่อนสู้: ต้อง error", r.status_code == 200 and "error" in r.get_json())

        wounded = False
        for _ in range(10):
            r = c.post('/api/pet-affection/fight', json={"owner_id": "pet_test_owner", "pet_id": "fierce1"})
            body = r.get_json()
            if body.get("result") == "worn_out":
                wounded = True
                break
        check("aggressive: สู้จนเหนื่อย (wounded) สำเร็จ", wounded)

        r = c.post('/api/pet-affection/feed', json={
            "owner_id": "pet_test_owner", "pet_id": "fierce1", "food_item": "default_food",
        })
        body = r.get_json()
        check("aggressive feed หลังเหนื่อย: สำเร็จ (healed_and_soothed)", body.get("result") == "healed_and_soothed")

        c.post('/api/pet-affection/crouch', json={"owner_id": "pet_test_owner", "pet_id": "shy1", "crouched": True, "behavior": "skittish"})
        all_ok = True
        for _ in range(5):
            r = c.post('/api/pet-affection/feed', json={
                "owner_id": "pet_test_owner", "pet_id": "shy1", "food_item": "default_food", "behavior": "skittish",
            })
            body = r.get_json()
            if body.get("result") == "flee":
                all_ok = False
        check("skittish: หมอบก่อนป้อนอาหารแล้วไม่หนี", all_ok)

        for _ in range(6):
            c.post('/api/pet-affection/feed', json={"owner_id": "pet_test_owner", "pet_id": "shy1", "food_item": "default_food", "behavior": "skittish"})
        r = c.post('/api/pet-affection/qte', json={"owner_id": "pet_test_owner", "pet_id": "shy1", "success": True})
        body = r.get_json()
        check("qte success: สำเร็จ", r.status_code == 200 and body.get("result") == "success")

        r = c.get('/api/pet-affection/status', query_string={"owner_id": "pet_test_owner", "pet_id": "shy1"})
        check("status: status 200", r.status_code == 200)

        r = c.get('/api/pet-affection/info')
        check("info: status 200 และมี behavior_types", r.status_code == 200 and "behavior_types" in r.get_json())

        r = c.get('/api/pet-affection/status', query_string={"owner_id": "pet_test_owner", "pet_id": "no_such_pet"})
        check("status: ไม่พบสัตว์ -> 404", r.status_code == 404)

        # species: endpoint ตารางสายพันธุ์ต้องมีครบทุกตัว
        r = c.get('/api/pet-affection/species')
        body = r.get_json()
        check("species: status 200 และมี species ครบ", r.status_code == 200 and
              all(k in body.get("species", {}) for k in ["meadow_hare", "ridge_wolf", "swamp_toad", "sky_moth"]))

        # species: สร้างสัตว์พร้อม species ครั้งแรก -> capture_hint ต้องตรงกับ profile
        c.post('/api/pet-affection/feed', json={
            "owner_id": "pet_test_owner", "pet_id": "hare1", "food_item": "default_food", "species": "meadow_hare",
        })
        r = c.get('/api/pet-affection/status', query_string={"owner_id": "pet_test_owner", "pet_id": "hare1"})
        body = r.get_json()
        check("species: state เก็บ species + capture_hint ถูกต้อง",
              body.get("species") == "meadow_hare" and body.get("capture_hint") == SPECIES_CAPTURE_PROFILES["meadow_hare"]["hint_th"])

        # species ไม่รู้จัก -> ไม่มีผล ไม่มี hint (ของเดิมยังทำงานเหมือนเดิม)
        c.post('/api/pet-affection/feed', json={
            "owner_id": "pet_test_owner", "pet_id": "plain1", "food_item": "default_food", "species": "not_a_real_species",
        })
        r = c.get('/api/pet-affection/status', query_string={"owner_id": "pet_test_owner", "pet_id": "plain1"})
        body = r.get_json()
        check("species: สายพันธุ์ไม่รู้จัก -> capture_hint เป็น None", body.get("capture_hint") is None)

    finally:
        for k in list(PET_STATE_STORE.keys()):
            if k.startswith("pet_test_owner::"):
                del PET_STATE_STORE[k]

    print(f"\n{sum(1 for _, ok in results if ok)}/{len(results)} tests passed")
    return all(ok for _, ok in results)


# ==========================================
# [ N+1. ระบบวิธี "จับ/รับเป็นพวก" แบบเลือกได้ (Capture Method Selector) ]
# ให้ผู้เล่น/ผู้ออกแบบด่านเลือกได้ว่าจะใช้วิธีไหนกับสัตว์แต่ละตัว — จะใช้แบบคลาสสิก
# "โยนบอล" (มีสูตรคำนวณโอกาสสำเร็จ + shake-check หลายจังหวะแบบเกมแนวจับสัตว์ทั่วไป)
# หรือจะใช้ระบบ "ทำความคุ้นเคย" (feed/pet/QTE จากโมดูลด้านบน) ก็ได้ หรือจะผสมกันก็ได้
# (เช่น ยิงยาสลบ/ตาข่ายให้หนีไม่ได้ก่อน แล้วค่อยโยนบอล หรือค่อยป้อนอาหารก็ได้เช่นกัน)
#
# วิธีที่มีให้เลือก (CAPTURE_METHODS):
#   - "affection" : ระบบทำความคุ้นเคย (ของเดิมด้านบน: feed / crouch / fight / pet / qte)
#   - "ball"      : โยนลูกบอลจับ มีสูตรคำนวณโอกาสสำเร็จตาม hp/สถานะของสัตว์ + ชนิดบอล
#   - "net_trap"  : ดักด้วยตาข่าย ทำให้หนีไม่ได้ชั่วคราว (เข้ากันดีกับสายขี้กลัว)
#   - "tranquilizer" : ยิงยาสลบ มีโอกาสทำให้หลับ (โอกาสจับสำเร็จเพิ่มขึ้นมากตอนหลับ)
#   - "bribe"     : ติดสินบนด้วยไอเทมหายาก รับเป็นพวกได้ทันทีโดยข้ามระบบ trust ทั้งหมด
# ทุกวิธีทำงานบน state เดียวกับโมดูล pet-affection (PET_STATE_STORE) เพื่อให้ผสมกันได้
# เช่น เลี้ยงจน trust สูงพอ (>= PET_TAME_TRUST) แล้วโยนบอลจะสำเร็จ 100% ทันที
# ==========================================

CAPTURE_METHODS = {
    "affection": {
        "name_th": "ทำความคุ้นเคย",
        "description": "ค่อยๆ ให้อาหาร/ลูบหัว/ผ่าน QTE จนสัตว์ไว้ใจแล้วยอมเป็นพวกเอง (ดูโมดูล pet-affection)",
    },
    "ball": {
        "name_th": "โยนบอล",
        "description": "โยนลูกบอลจับ โอกาสสำเร็จขึ้นกับ HP/สถานะของสัตว์และชนิดบอลที่ใช้",
    },
    "net_trap": {
        "name_th": "ดักตาข่าย",
        "description": "ทำให้สัตว์หนีไม่ได้ชั่วคราว เปิดโอกาสให้เข้าไปป้อนอาหารหรือโยนบอลตามได้ง่ายขึ้น",
    },
    "tranquilizer": {
        "name_th": "ยิงยาสลบ",
        "description": "มีโอกาสทำให้สัตว์หลับ ถ้าหลับสำเร็จโอกาสจับด้วยบอล/เข้าไปป้อนอาหารจะสูงขึ้นมาก",
    },
    "bribe": {
        "name_th": "ติดสินบน",
        "description": "ใช้ไอเทมหายากแลกรับเป็นพวกทันที ข้ามระบบ trust ทั้งหมด ใช้ได้ครั้งเดียวต่อไอเทม 1 ชิ้น",
    },
}

# ตัวคูณโอกาสจับตามชนิด "บอล" (ตั้งชื่อเป็นของทั่วไป ไม่อิงเกมใดเกมหนึ่ง)
CAPTURE_BALL_TYPES = {
    "orb_common":     {"multiplier": 1.0,  "name_th": "ลูกออร์บทั่วไป"},
    "orb_reinforced": {"multiplier": 1.5,  "name_th": "ลูกออร์บเสริมแรง"},
    "orb_heavy":      {"multiplier": 2.0,  "name_th": "ลูกออร์บหนักพิเศษ"},
    "orb_prime":      {"multiplier": 255,  "name_th": "ลูกออร์บชั้นสูงสุด (แทบจะจับติดเสมอ)"},
}

CAPTURE_SHAKE_CHECKS = 4  # จำนวนจังหวะ "เขย่า" ก่อนสรุปผลว่าจับสำเร็จ (คอนเซปต์แนวเกมจับสัตว์ทั่วไป)


def pet_weaken(owner_id, pet_id, amount, behavior=None, species=None):
    """ลด HP ของสัตว์เลี้ยง (ใช้ก่อนโยนบอลเพื่อเพิ่มโอกาสสำเร็จ) — ไม่ทำให้ตาย, พื้นต่ำสุด 1"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    st["hp"] = max(1, st["hp"] - abs(amount))
    return st


def pet_ball_throw(owner_id, pet_id, ball_type="orb_common", behavior=None, species=None):
    """โยนบอลจับ — คำนวณโอกาสสำเร็จจาก HP ปัจจุบัน, สถานะ (หลับ/ถูกตาข่าย), ชนิดบอล,
    trust ที่สะสมมาจากระบบทำความคุ้นเคย (ถ้ามี) และตัวคูณตามสายพันธุ์ (species) ถ้า trust
    ถึงเกณฑ์เชื่องเต็มที่แล้ว จะสำเร็จ 100% ทันทีไม่ต้องคำนวณ"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    if st["captured"]:
        return {"error": "สัตว์เลี้ยงตัวนี้เป็นพวกอยู่แล้ว", "state": st}
    if st["fled"]:
        return {"error": "สัตว์เลี้ยงตัวนี้วิ่งหนีไปแล้ว ต้องตามหาใหม่ก่อน", "state": st}
    if ball_type not in CAPTURE_BALL_TYPES:
        return {"error": f"ไม่รู้จักชนิดบอล '{ball_type}'", "available_ball_types": list(CAPTURE_BALL_TYPES.keys())}

    st["capture_attempts"] += 1

    # ลัดขั้นตอน: ถ้าเลี้ยงจน trust ถึงเกณฑ์เชื่องเต็มที่แล้ว บอลชนิดไหนก็จับติดทันที
    if st["trust"] >= PET_TAME_TRUST or st["tamed"]:
        st["captured"] = True
        st["capture_method_used"] = "ball(auto-trust)"
        return {"result": "captured", "reason": "trust ถึงเกณฑ์เชื่องเต็มที่แล้ว", "state": st}

    ball = CAPTURE_BALL_TYPES[ball_type]
    if ball["multiplier"] >= 255:
        st["captured"] = True
        st["capture_method_used"] = f"ball:{ball_type}"
        return {"result": "captured", "reason": "ใช้บอลชั้นสูงสุด", "state": st}

    hp_ratio = st["hp"] / max(1, st["max_hp"])
    hp_factor = max(0.1, 1.0 - (hp_ratio * 0.7))  # ยิ่ง HP เหลือน้อย ยิ่งจับง่ายขึ้น (แต่ไม่มีทางเป็น 0)

    status_multiplier = 1.0
    if st["asleep"]:
        status_multiplier *= 2.0
    if st["netted_turns"] > 0:
        status_multiplier *= 1.3
        st["netted_turns"] -= 1

    # เอา trust มาช่วยด้วยเล็กน้อย (เลี้ยงมาบ้างแล้วจับง่ายขึ้นกว่าตัวที่ trust=0)
    trust_bonus = 1.0 + (st["trust"] / 200.0)

    # ตัวคูณตามสายพันธุ์ (เก็บ species ไว้ใน state ตอนสร้างครั้งแรก ใช้ค่านั้นเป็นหลัก
    # เผื่อ caller ไม่ได้ส่ง species ซ้ำมาทุกครั้ง)
    species_mult = _pet_species_multiplier(species or st.get("species"), "ball")

    base_chance = 0.18  # โอกาสพื้นฐานต่อ 1 จังหวะ ก่อนคูณตัวแปรอื่น
    per_shake_chance = min(0.95, base_chance * ball["multiplier"] * hp_factor * status_multiplier * trust_bonus * species_mult)

    shakes_passed = 0
    for _ in range(CAPTURE_SHAKE_CHECKS):
        if random.random() < per_shake_chance:
            shakes_passed += 1
        else:
            break

    if shakes_passed >= CAPTURE_SHAKE_CHECKS:
        st["captured"] = True
        st["capture_method_used"] = f"ball:{ball_type}"
        return {"result": "captured", "shakes_passed": shakes_passed, "state": st}
    else:
        # จับไม่สำเร็จ มีโอกาสเล็กน้อยที่สัตว์จะหลุดวิ่งหนีไปเลยถ้าไม่ได้ถูกตาข่ายไว้
        out = {"result": "broke_free", "shakes_passed": shakes_passed, "state": st}
        if st["netted_turns"] <= 0 and random.random() < 0.15:
            st["fled"] = True
            out["result"] = "broke_free_and_fled"
        if st.get("capture_hint"):
            out["species_hint"] = st["capture_hint"]
        return out


def pet_net_trap(owner_id, pet_id, behavior=None, species=None):
    """ดักตาข่าย — ทำให้หนีไม่ได้ไปอีกไม่กี่ครั้งถัดไป (เข้ากันดีกับสายขี้กลัวที่ชอบวิ่งหนี)
    ระยะเวลาที่ติดตาข่าย (netted_turns) จะถูกปรับขึ้น/ลงตามตัวคูณของสายพันธุ์"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    if st["fled"]:
        return {"error": "สัตว์เลี้ยงตัวนี้วิ่งหนีไปไกลเกินจะดักแล้ว", "state": st}
    species_mult = _pet_species_multiplier(species or st.get("species"), "net_trap")
    st["netted_turns"] = max(1, round(3 * species_mult))
    out = {"result": "netted", "netted_turns": st["netted_turns"], "state": st}
    if st.get("capture_hint"):
        out["species_hint"] = st["capture_hint"]
    return out


def pet_tranquilizer(owner_id, pet_id, behavior=None, species=None):
    """ยิงยาสลบ — มีโอกาสทำให้สัตว์หลับ (asleep) ถ้าหลับสำเร็จจะช่วยเพิ่มโอกาสของทั้งบอล
    และลดโอกาสวิ่งหนีตอนป้อนอาหารในระบบทำความคุ้นเคยไปด้วย โอกาสสำเร็จปรับตามสายพันธุ์ด้วย"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    if st["fled"]:
        return {"error": "สัตว์เลี้ยงตัวนี้วิ่งหนีไปแล้ว", "state": st}
    if st["asleep"]:
        return {"message": "สัตว์เลี้ยงหลับอยู่แล้ว", "state": st}

    base_chance = 0.5 if st["behavior"] != "aggressive" else 0.35  # สายดุร้ายต้านทานยาสลบได้มากกว่า
    species_mult = _pet_species_multiplier(species or st.get("species"), "tranquilizer")
    success_chance = max(0.05, min(0.95, base_chance * species_mult))
    if random.random() < success_chance:
        st["asleep"] = True
        return {"result": "asleep", "state": st}
    out = {"result": "missed", "state": st}
    if st.get("capture_hint"):
        out["species_hint"] = st["capture_hint"]
    return out


def pet_bribe(owner_id, pet_id, rare_item, behavior=None, species=None):
    """ติดสินบนด้วยไอเทมหายาก — ข้ามระบบ trust ทั้งหมด รับเป็นพวกได้ทันที (ใช้ไอเทมหายากไป 1 ชิ้น)
    บางสายพันธุ์ (bribe_immune) ไม่สนของล่อทั่วไปเลย เว้นแต่จะเป็นไอเทมที่มันชอบเป็นพิเศษเท่านั้น"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    if st["captured"]:
        return {"error": "สัตว์เลี้ยงตัวนี้เป็นพวกอยู่แล้ว", "state": st}
    if not rare_item:
        return {"error": "ต้องระบุ rare_item ที่จะใช้ติดสินบน"}, 400

    profile = _pet_species_profile(species or st.get("species"))
    if profile.get("bribe_immune") and rare_item != profile.get("favorite_bribe_item"):
        out = {"result": "ignored", "message": "สัตว์สายพันธุ์นี้ไม่สนใจของล่อทั่วไป ลองไอเทมอื่นดู", "state": st}
        if st.get("capture_hint"):
            out["species_hint"] = st["capture_hint"]
        return out

    st["captured"] = True
    st["tamed"] = True
    st["trust"] = 100
    st["capture_method_used"] = f"bribe:{rare_item}"
    return {"result": "captured", "method": "bribe", "item_used": rare_item, "state": st}


def pet_set_preferred_method(owner_id, pet_id, method, behavior=None, species=None):
    """ตั้งค่า metadata ว่าสัตว์ตัวนี้ 'แนะนำ' ให้ใช้วิธีไหน (ไว้ให้ UI แสดงผล) —
    ไม่ได้บังคับว่าห้ามเรียก endpoint วิธีอื่น ผู้เล่นยังเลือกใช้วิธีไหนก็ได้เสมอ"""
    if method not in CAPTURE_METHODS:
        return {"error": f"ไม่รู้จักวิธี '{method}'", "available_methods": list(CAPTURE_METHODS.keys())}
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    st["preferred_capture_method"] = method
    return {"preferred_capture_method": method, "state": st}


def pet_transform(owner_id, pet_id, catalyst_item=None, behavior=None, species=None):
    """แปลงร่างสัตว์เลี้ยงที่เป็นพวกแล้วให้กลายเป็นร่างมอนสเตอร์ที่แข็งแกร่งขึ้น (ถาวร ทำได้ครั้งเดียว)
    เงื่อนไข: ต้อง captured แล้ว, trust >= PET_TAME_TRUST (เชื่องเต็มที่), สายพันธุ์ต้องมีร่าง
    มอนสเตอร์ให้แปลงจริง (ดู MONSTER_TRANSFORM_PROFILES) และต้องใช้ catalyst_item ที่ตรงกับ
    สายพันธุ์นั้นเท่านั้น — แปลงร่างสำเร็จแล้ว max_hp จะเพิ่มขึ้นตาม hp_multiplier และ heal เต็ม"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    if not st["captured"]:
        return {"error": "ต้องจับ/รับเป็นพวกให้ได้ก่อนถึงจะแปลงร่างได้", "state": st}
    if st["transformed"]:
        return {"error": f"แปลงร่างเป็น {st['monster_form']} ไปแล้ว แปลงซ้ำไม่ได้", "state": st}

    resolved_species = species or st.get("species")
    profile = _pet_transform_profile(resolved_species)
    if not profile:
        return {
            "error": "สายพันธุ์นี้ยังไม่มีร่างมอนสเตอร์ให้แปลง (หรือยังไม่ได้ตั้ง species ตอนสร้างสัตว์)",
            "available_species": list(MONSTER_TRANSFORM_PROFILES.keys()),
            "state": st,
        }
    if st["trust"] < PET_TAME_TRUST:
        return {"error": f"ต้องเลี้ยงจน trust >= {PET_TAME_TRUST} (เชื่องเต็มที่) ก่อนถึงจะแปลงร่างได้", "state": st}

    required_item = profile["catalyst_item"]
    if catalyst_item != required_item:
        return {
            "error": f"ต้องใช้ไอเทมตัวเร่ง '{required_item}' เท่านั้นถึงจะแปลงร่างสายพันธุ์นี้ได้",
            "required_item": required_item,
            "state": st,
        }

    old_max_hp = st["max_hp"]
    st["transformed"] = True
    st["monster_form"] = profile["monster_form"]
    st["transform_item_used"] = catalyst_item
    st["max_hp"] = max(old_max_hp, round(old_max_hp * profile["hp_multiplier"]))
    st["hp"] = st["max_hp"]  # แปลงร่างสำเร็จ ฟื้น HP เต็ม
    return {
        "result": "transformed",
        "monster_form": st["monster_form"],
        "name_th": profile["name_th"],
        "description_th": profile["description_th"],
        "old_max_hp": old_max_hp,
        "new_max_hp": st["max_hp"],
        "state": st,
    }


