# ==========================================
# [ N+1b. โหมดบังคับควบคุม (Pilot Mode) — ต่อยอดจากระบบเติบโตด้านบน ]
# ต้องโตเต็มวัย (growth_stage == "adult"), จับได้แล้ว (captured), และเชื่องเต็มที่แล้ว
# (trust >= PET_TAME_TRUST) ถึงจะเข้าโหมดนี้ได้ — พอเข้าแล้วผู้เล่น "บังคับ" สัตว์ตัวนั้น
# โดยตรง แล้วใช้เข้าโจมตี/ลด HP มอนสเตอร์ป่าตัวอื่น (ตัวที่ยังไม่ได้จับ) เพื่อช่วยจับง่ายขึ้น
# ==========================================
PILOT_ATTACK_DAMAGE_MIN = 8
PILOT_ATTACK_DAMAGE_MAX = 18
PILOT_ATTACK_TRANSFORMED_MULTIPLIER = 1.5  # ถ้าตัวที่บังคับอยู่แปลงร่างแล้วด้วย โจมตีแรงขึ้น


def pet_pilot_start(owner_id, pet_id, behavior=None, species=None):
    """เข้าโหมดบังคับควบคุมสัตว์เลี้ยง — ต้องโตเต็มวัย (adult), จับได้แล้ว, และเชื่องเต็มที่ก่อน"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    if not st["captured"]:
        return {"error": "ต้องจับ/รับเป็นพวกให้ได้ก่อนถึงจะเข้าโหมดบังคับควบคุมได้", "state": st}
    if st["trust"] < PET_TAME_TRUST:
        return {"error": f"ต้องเลี้ยงจน trust >= {PET_TAME_TRUST} (เชื่องเต็มที่) ก่อน", "state": st}
    if st["growth_stage"] != "adult":
        return {
            "error": "ต้องโตเต็มวัย (growth_stage == 'adult') ก่อนถึงจะบังคับควบคุมได้ "
                     "— เลี้ยงต่อด้วยการลูบหัว/ผ่าน QTE เพื่อสะสม care_points",
            "growth_stage": st["growth_stage"],
            "care_points": st["care_points"],
            "care_points_required": GROWTH_STAGE_INFO["adult"]["care_points_required"],
            "state": st,
        }
    if st["piloted"]:
        return {"message": "อยู่ในโหมดบังคับควบคุมอยู่แล้ว", "pilot_form": st["pilot_form"], "state": st}

    st["piloted"] = True
    st["pilot_form"] = st["monster_form"] if st["transformed"] else (st.get("species") or "adult_form")
    return {"result": "piloting", "pilot_form": st["pilot_form"], "state": st}


def pet_pilot_stop(owner_id, pet_id, behavior=None, species=None):
    """ออกจากโหมดบังคับควบคุม"""
    st = _pet_get_or_create(owner_id, pet_id, behavior=behavior, species=species)
    st["piloted"] = False
    st["pilot_form"] = None
    return {"result": "stopped", "state": st}


def pet_pilot_attack(owner_id, pilot_pet_id, target_pet_id, target_species=None, behavior=None, species=None):
    """ใช้ร่างที่กำลังบังคับควบคุมอยู่เข้าโจมตีมอนสเตอร์ป่าตัวอื่น (target_pet_id) เพื่อลด HP
    ให้จับง่ายขึ้น — ต้องเริ่มโหมดบังคับควบคุม (pilot-start) ก่อนเสมอ"""
    st = _pet_get_or_create(owner_id, pilot_pet_id, behavior=behavior, species=species)
    if not st["piloted"]:
        return {"error": "ต้องเข้าโหมดบังคับควบคุม (pilot-start) ก่อนถึงจะโจมตีได้", "state": st}

    damage = random.randint(PILOT_ATTACK_DAMAGE_MIN, PILOT_ATTACK_DAMAGE_MAX)
    if st["transformed"]:
        damage = round(damage * PILOT_ATTACK_TRANSFORMED_MULTIPLIER)
    target_st = pet_weaken(owner_id, target_pet_id, damage, species=target_species)
    return {
        "result": "attacked",
        "pilot_pet_id": pilot_pet_id,
        "pilot_form": st["pilot_form"],
        "damage_dealt": damage,
        "target_pet_id": target_pet_id,
        "target_hp": target_st["hp"],
        "target_state": target_st,
    }


