def _run_charge_jump_selftests():
    """Self-test ของโมดูล charge-jump — เรียกด้วย:
    python3 <ไฟล์นี้> --selftest-charge-jump"""
    c = app.test_client()
    results = []

    def check(name, cond):
        results.append((name, cond))
        print(("✅ PASS " if cond else "❌ FAIL ") + name)

    try:
        for k in list(CHARGE_JUMP_STATE.keys()):
            if k.startswith("charge_jump_test_"):
                del CHARGE_JUMP_STATE[k]

        uid = "charge_jump_test_p1"

        # ยังไม่วิ่งเลย กด execute ตรงๆ -> error (ต้องวิ่งค้างด้วย)
        r = c.post('/api/charge-jump/execute', json={"uid": uid})
        check("execute ก่อนวิ่ง -> error", r.status_code == 400 and "error" in r.get_json())

        # วิ่ง tick เดียว (charge ยังไม่เต็ม) แล้วกระโดด -> ได้แค่กระโดดปกติ (ไม่ charged)
        c.post('/api/charge-jump/run-tick', json={"uid": uid, "x": 0, "y": 0, "dir_x": 1, "dir_y": 0})
        r = c.post('/api/charge-jump/execute', json={"uid": uid})
        body = r.get_json()
        check("กระโดดตอน charge ไม่เต็ม -> normal_jump ระยะสั้น",
              body.get("result") == "normal_jump" and body.get("charged") is False)
        normal_distance = body.get("distance")

        # รอให้ลงจอด + คูลดาวน์หมดก่อนลองรอบถัดไป
        time.sleep(CHARGE_JUMP_CONFIG["normal_jump_air_seconds"] + CHARGE_JUMP_CONFIG["cooldown_seconds"] + 0.05)

        # วิ่งจน charge เต็ม แล้วกระโดด -> ต้องพุ่งไกลกว่าเดิมมาก และลอยอยู่ ~1 วิตามสเปก
        ticks_needed = -(-CHARGE_JUMP_CONFIG["charge_required"] // CHARGE_JUMP_CONFIG["charge_per_tick"])
        for _ in range(ticks_needed):
            c.post('/api/charge-jump/run-tick', json={"uid": uid, "dir_x": 1, "dir_y": 0})
        r = c.post('/api/charge-jump/execute', json={"uid": uid})
        body = r.get_json()
        check("กระโดดตอน charge เต็ม -> long_jump ไกลกว่าปกติมาก",
              body.get("result") == "long_jump" and body.get("charged") is True and body.get("distance") > normal_distance)
        check("long_jump ลอยกลางอากาศ 1 วินาทีตามสเปก", body.get("air_seconds") == 1.0)

        # ระหว่างลอยอยู่กลางอากาศ กด execute ซ้ำ -> ต้อง error (ยังไม่ลงจอด)
        r = c.post('/api/charge-jump/execute', json={"uid": uid})
        check("กระโดดซ้ำตอนยังลอยอยู่ -> error", r.status_code == 400 and "error" in r.get_json())

        # state endpoint ระหว่างลอยอยู่: airborne == True และ charge ถูกใช้จนหมด (รีเซ็ตเป็น 0)
        r = c.get('/api/charge-jump/state', query_string={"uid": uid})
        body = r.get_json()
        check("state ระหว่างลอย: airborne=True, charge=0, air_seconds_remaining > 0",
              body.get("airborne") is True and body.get("charge") == 0
              and body.get("air_seconds_remaining") > 0)

        # ลงจอดแล้วแต่ยังติดคูลดาวน์อยู่ -> execute อีกครั้งต้อง error เพราะ cooldown
        time.sleep(CHARGE_JUMP_CONFIG["charged_jump_air_seconds"] + 0.05)
        c.post('/api/charge-jump/run-tick', json={"uid": uid, "dir_x": 1, "dir_y": 0})
        r = c.post('/api/charge-jump/execute', json={"uid": uid})
        body = r.get_json()
        check("ลงจอดแล้วแต่ยังติดคูลดาวน์ -> error พร้อม seconds_remaining",
              r.status_code == 400 and "error" in body and "seconds_remaining" in body)

        # หยุดวิ่งแล้ว charge ต้องเริ่มลดลงตามเวลา (decay) ไม่ใช่ค้างอยู่ที่เดิม
        uid2 = "charge_jump_test_p2"
        c.post('/api/charge-jump/run-tick', json={"uid": uid2, "dir_x": 1, "dir_y": 0})
        c.post('/api/charge-jump/stop-run', json={"uid": uid2})
        time.sleep(0.3)
        r = c.get('/api/charge-jump/state', query_string={"uid": uid2})
        body = r.get_json()
        check("หยุดวิ่งแล้ว charge ค่อยๆ ลดลงตามเวลา (decay)",
              0 <= body.get("charge") < CHARGE_JUMP_CONFIG["charge_per_tick"])

        # info endpoint
        r = c.get('/api/charge-jump/info')
        check("info: status 200 และมี config/endpoints", r.status_code == 200 and
              "config" in r.get_json() and "endpoints" in r.get_json())

    finally:
        for k in list(CHARGE_JUMP_STATE.keys()):
            if k.startswith("charge_jump_test_"):
                del CHARGE_JUMP_STATE[k]

    print(f"\n{sum(1 for _, ok in results if ok)}/{len(results)} tests passed")
    return all(ok for _, ok in results)



