#form{display:flex;gap:7px;padding:9px;border-top:1px solid #1f4155;background:#081722}#prompt{padding:8px 0;color:#67d8ff}#input{flex:1;min-width:0;border:1px solid #315d74;background:#041018;color:#fff;border-radius:8px;padding:8px;font:inherit;outline:none}
