def _vmax_os_terminal_selftest():
    """Fast offline self-test for the guest + bridge, without starting Flask."""
    guest, bridge = vmax_create_os_style_virtual_computer(ram_size=1024 * 1024)
    assert guest.boot()['ok']
    info = bridge.connect('selftest')
    assert info['protocol'] == VMAXGameTerminalBridge.PROTOCOL
    status = bridge.request('status')
    assert status['state'] == 'running'
    out = bridge.request('shell', command='write /tmp/test hello world')
    assert out['ok'] is True
    cat = bridge.request('shell', command='cat /tmp/test')
    assert cat['output'] == 'hello world'
    job = bridge.request('job', job='selftest', payload={'n': 1})
    assert job['status'] == 'completed'
    events = bridge.poll()
    assert any(e['message'].startswith('[VMAX OS] job completed:') for e in events)
    assert _vmax_vm_rank_snapshot(STAFF_RANKS['support'])['permissions']['view'] is True
    assert _vmax_vm_rank_snapshot(STAFF_RANKS['support'])['permissions']['open'] is False
    assert _vmax_vm_rank_snapshot(STAFF_RANKS['moderator'])['permissions']['open'] is True
    assert _vmax_vm_rank_snapshot(STAFF_RANKS['developer'])['permissions']['terminal'] is True
    bridge.disconnect()
    return {'ok': True, 'checks': 7, 'protocol': VMAXGameTerminalBridge.PROTOCOL}


