def _arcane_district(district_id):
    """คืนข้อมูลย่าน — ถ้าไม่รู้จัก ตกกลับไปที่ HQ เพื่อไม่ให้ระบบพัง"""
    return TOKYO_DISTRICTS.get(district_id, TOKYO_DISTRICTS[TOKYO_DISTRICT_HQ])


def _arcane_travel_minutes(from_district_id, to_district_id):
    """เวลาเดินทางโดยประมาณระหว่าง 2 ย่าน โดยใช้ HQ เป็นจุดต่อ (ประมาณการ ไม่ใช่
    กราฟระยะทางจริง): ถ้าย่านเดียวกันใช้เวลา 0, ถ้าฝั่งใดฝั่งหนึ่งเป็น HQ ใช้เวลา
    ของอีกฝั่งตรงๆ, นอกนั้นบวกเวลาจาก HQ ของทั้งสองฝั่งเข้าด้วยกัน"""
    if from_district_id == to_district_id:
        return 0
    a = _arcane_district(from_district_id)["travel_minutes_from_hq"]
    b = _arcane_district(to_district_id)["travel_minutes_from_hq"]
    if from_district_id == TOKYO_DISTRICT_HQ or to_district_id == TOKYO_DISTRICT_HQ:
        return max(a, b)
    return a + b


ARCANE_ADMIN_CASTERS = {}     # uid -> caster profile dict
ARCANE_ADMIN_INCIDENTS = {}   # incident_id -> incident dict
ARCANE_ADMIN_BATTLES = {}     # battle_id -> battle state dict


def _arcane_caster(uid, name=None, has_staff=False):
    """สร้าง/ดึงโปรไฟล์นักเวทย์ในสังกัดหน่วยงานพิเศษ"""
    c = ARCANE_ADMIN_CASTERS.get(uid)
    if c is None:
        c = {
            "uid": uid,
            "name": name or uid,
            "hp": ARCANE_ADMIN_CONFIG["base_hp"],
            "max_hp": ARCANE_ADMIN_CONFIG["base_hp"],
            "ap": ARCANE_ADMIN_CONFIG["base_ap"],
            "max_ap": ARCANE_ADMIN_CONFIG["base_ap"],
            "casting_style": "hand",
            "has_staff": bool(has_staff),
            "unlocked_foci": [],   # focus_id ของอาวุธที่ยืมมาจากเกมอื่นแล้ว (hand/staff เช็คแยกด้วย has_staff) — list ไม่ใช่ set เพราะต้อง jsonify ได้ตรงๆ
            "combo_element": None,
            "combo_stacks": 0,
            "incidents_resolved": 0,
            "current_district": TOKYO_DISTRICT_HQ,  # เริ่มต้นประจำการที่ HQ เสมอ
        }
        ARCANE_ADMIN_CASTERS[uid] = c
    elif name:
        c["name"] = name
    return c


def arcane_set_casting_style(uid, style):
    if style not in ARCANE_FOCI:
        return {"error": f"casting_style/focus ต้องเป็นหนึ่งใน {list(ARCANE_FOCI.keys())} ไม่ใช่ {style}"}
    c = _arcane_caster(uid)
    if style == "hand":
        pass  # ร่ายมือเปล่าใช้ได้เสมอ ไม่ต้องปลดล็อก
    elif style == "staff":
        if not (c["has_staff"] or "staff" in c["unlocked_foci"]):
            return {"error": "ต้องมีคทา (staff) ติดตัวก่อนถึงจะสลับไปร่ายด้วยคทาได้"}
    elif style not in c["unlocked_foci"]:
        focus = ARCANE_FOCI[style]
        return {
            "error": f"ยังไม่ได้ยืมอาวุธนี้มาเป็นตัวกลางร่ายเวทย์ — import จาก {focus['source']} ก่อนด้วย "
                     "POST /api/arcane-administration/import-weapon",
        }
    c["casting_style"] = style
    return {"ok": True, "uid": uid, "casting_style": style}


def arcane_import_weapon(uid, weapon_id):
    """เอา weapon_id ของโหมดเกมอื่นในไฟล์นี้มา 'ยืม' เป็นตัวกลางร่ายเวทย์ใหม่ให้ uid นี้"""
    focus_id = _arcane_weapon_catalog_lookup(weapon_id)
    if focus_id is None:
        return {"error": f"ไม่รู้จักอาวุธ '{weapon_id}' ในระบบเกมไหนเลยที่เชื่อมกับเวทย์ได้ตอนนี้",
                "known_weapon_ids": sorted(KATANA_WEAPON_IDS) + [M82_WEAPON_ID]}
    c = _arcane_caster(uid)
    if focus_id not in c["unlocked_foci"]:
        c["unlocked_foci"].append(focus_id)
    return {"ok": True, "uid": uid, "weapon_id": weapon_id, "unlocked_focus": focus_id,
            "focus_info": ARCANE_FOCI[focus_id]}


def _arcane_resolve_cast(caster, spell_key):
    spell = ARCANE_SPELLBOOK.get(spell_key)
    if spell is None:
        return {"error": f"ไม่รู้จักเวทย์ {spell_key}"}

    style = caster["casting_style"]
    focus = ARCANE_FOCI.get(style, ARCANE_FOCI["hand"])
    ap_cost = spell["ap_cost"] + focus["ap_delta"]

    if caster["ap"] < ap_cost:
        return {"error": "AP ไม่พอ", "ap": caster["ap"], "ap_cost": ap_cost}

    caster["ap"] -= ap_cost

    power = float(spell["power"]) * focus["power_mult"]
    heal = float(spell.get("heal", 0)) * focus["power_mult"]

    element = spell["element"]
    if caster["combo_element"] == element:
        caster["combo_stacks"] = min(
            caster["combo_stacks"] + 1, ARCANE_ADMIN_CONFIG["combo_max_stacks"]
        )
    else:
        caster["combo_element"] = element
        caster["combo_stacks"] = 0

    combo_mult = 1.0 + caster["combo_stacks"] * ARCANE_ADMIN_CONFIG["combo_power_step"]
    power *= combo_mult
    heal *= combo_mult

    ap_refunded = 0
    if focus["combo_refund_ap"] > 0 and caster["combo_stacks"] > 0:
        ap_refunded = focus["combo_refund_ap"]
        caster["ap"] = min(caster["max_ap"], caster["ap"] + ap_refunded)

    if heal > 0:
        caster["hp"] = min(caster["max_hp"], caster["hp"] + heal)

    return {
        "ok": True,
        "spell": spell_key,
        "name_th": spell["name_th"],
        "element": element,
        "casting_style": style,
        "ap_spent": ap_cost,
        "ap_refunded": ap_refunded,
        "ap_remaining": caster["ap"],
        "combo_stacks": caster["combo_stacks"],
        "power_dealt": round(power, 1),
        "heal_done": round(heal, 1),
    }


@app.route('/api/arcane-administration/register', methods=['POST'])
def api_arcane_register():
    """body: {uid, name?, has_staff?} -> ลงทะเบียนนักเวทย์ในสังกัดหน่วยงานพิเศษ"""
    data = request.get_json(silent=True) or {}
    uid = data.get("uid")
    if not uid:
        return jsonify({"error": "ต้องส่ง uid"}), 400
    c = _arcane_caster(uid, name=data.get("name"), has_staff=data.get("has_staff", False))
    return jsonify({"ok": True, "caster": c})


@app.route('/api/arcane-administration/set-style', methods=['POST'])
def api_arcane_set_style():
    """body: {uid, style} -> สลับตัวกลางร่ายเวทย์ — style เป็นได้ทั้ง 'staff'/'hand' เดิม
    หรือ focus_id ของอาวุธที่ยืมมาจากเกมอื่นแล้ว (เช่น 'katana', 'm82_sniper') ดู
    ARCANE_FOCI ทั้งหมดที่ GET /api/arcane-administration/info"""
    data = request.get_json(silent=True) or {}
    uid = data.get("uid")
    style = data.get("style")
    if not uid or not style:
        return jsonify({"error": "ต้องส่ง uid และ style"}), 400
    result = arcane_set_casting_style(uid, style)
    if "error" in result:
        return jsonify(result), 400
    return jsonify(result)


@app.route('/api/arcane-administration/import-weapon', methods=['POST'])
def api_arcane_import_weapon():
    """body: {uid, weapon_id} -> ยืมอาวุธจากโหมดเกมอื่นในไฟล์นี้ (เช่น คาตานะจาก
    katana_duel_mode ตาม KATANA_WEAPON_IDS, หรือปืน M82 จาก m82_sniper_mode ตาม
    M82_WEAPON_ID) มาปลดล็อกเป็นตัวกลางร่ายเวทย์ใหม่ให้ uid นี้ — ปลดล็อกแล้วค่อยไป
    สลับใช้งานจริงด้วย POST /api/arcane-administration/set-style"""
    data = request.get_json(silent=True) or {}
    uid = data.get("uid")
    weapon_id = data.get("weapon_id")
    if not uid or not weapon_id:
        return jsonify({"error": "ต้องส่ง uid และ weapon_id"}), 400
    result = arcane_import_weapon(uid, weapon_id)
    if "error" in result:
        return jsonify(result), 400
    return jsonify(result)


@app.route('/api/arcane-administration/battle/start', methods=['POST'])
def api_arcane_battle_start():
    """body: {uid, enemy_name?} -> เริ่มการต่อสู้แบบผลัดตา (turn-based) กับมอนสเตอร์"""
    data = request.get_json(silent=True) or {}
    uid = data.get("uid")
    if not uid:
        return jsonify({"error": "ต้องส่ง uid"}), 400
    caster = _arcane_caster(uid)
    caster["hp"] = caster["max_hp"]
    caster["ap"] = caster["max_ap"]
    caster["combo_element"] = None
    caster["combo_stacks"] = 0

    battle_id = str(uuid.uuid4())
    ARCANE_ADMIN_BATTLES[battle_id] = {
        "battle_id": battle_id,
        "uid": uid,
        "enemy_name": data.get("enemy_name", "วิญญาณจร"),
        "enemy_hp": ARCANE_ADMIN_CONFIG["enemy_base_hp"],
        "enemy_max_hp": ARCANE_ADMIN_CONFIG["enemy_base_hp"],
        "turn": 1,
        "log": [],
        "finished": False,
        "result": None,
    }
    return jsonify({"ok": True, "battle": ARCANE_ADMIN_BATTLES[battle_id]})


@app.route('/api/arcane-administration/battle/cast', methods=['POST'])
def api_arcane_battle_cast():
    """body: {battle_id, spell} -> ร่ายเวทย์ใส่ศัตรูในเทิร์นนี้ แล้วให้ศัตรูสวนกลับอัตโนมัติ"""
    data = request.get_json(silent=True) or {}
    battle_id = data.get("battle_id")
    spell_key = data.get("spell")
    battle = ARCANE_ADMIN_BATTLES.get(battle_id)
    if battle is None:
        return jsonify({"error": "ไม่พบ battle_id นี้"}), 404
    if battle["finished"]:
        return jsonify({"error": "การต่อสู้นี้จบไปแล้ว", "result": battle["result"]}), 400

    caster = _arcane_caster(battle["uid"])
    cast_result = _arcane_resolve_cast(caster, spell_key)
    if "error" in cast_result:
        return jsonify(cast_result), 400

    battle["enemy_hp"] = max(0.0, battle["enemy_hp"] - cast_result["power_dealt"])
    battle["log"].append({"turn": battle["turn"], "actor": caster["name"], **cast_result})

    if battle["enemy_hp"] <= 0:
        battle["finished"] = True
        battle["result"] = "victory"
        caster["incidents_resolved"] += 1
        return jsonify({"ok": True, "cast": cast_result, "battle": battle})

    enemy_dmg = ARCANE_ADMIN_CONFIG["enemy_base_atk"] + random.randint(-2, 3)
    caster["hp"] = max(0.0, caster["hp"] - enemy_dmg)
    battle["log"].append({"turn": battle["turn"], "actor": battle["enemy_name"], "power_dealt": enemy_dmg})
    caster["ap"] = min(caster["max_ap"], caster["ap"] + ARCANE_ADMIN_CONFIG["ap_regen_per_turn"])
    battle["turn"] += 1

    if caster["hp"] <= 0:
        battle["finished"] = True
        battle["result"] = "defeat"

    return jsonify({"ok": True, "cast": cast_result, "enemy_damage": enemy_dmg, "battle": battle})


@app.route('/api/arcane-administration/battle/state', methods=['GET'])
def api_arcane_battle_state():
    """?battle_id= -> สถานะการต่อสู้ปัจจุบัน"""
    battle_id = request.args.get("battle_id")
    battle = ARCANE_ADMIN_BATTLES.get(battle_id)
    if battle is None:
        return jsonify({"error": "ไม่พบ battle_id นี้"}), 404
    caster = _arcane_caster(battle["uid"])
    return jsonify({"battle": battle, "caster": caster})


@app.route('/api/arcane-administration/incident/open', methods=['POST'])
def api_arcane_incident_open():
    """body: {title, description?, district_id?} -> เปิดคดี/เหตุการณ์ใหม่ในระบบของ
    หน่วยงานพิเศษ (เนื้อเรื่องฝั่งผู้เล่นในบทบาทหัวหน้าหน่วยที่ต้องตัดสินใจส่งนักเวทย์
    ไปจัดการ) — ระบุ district_id เพื่อผูกคดีเข้ากับย่านในแผนที่โตเกียว (ไม่ระบุ =
    เกิดที่ HQ) ดู GET /api/arcane-administration/districts สำหรับรายชื่อย่านทั้งหมด"""
    data = request.get_json(silent=True) or {}
    title = data.get("title")
    if not title:
        return jsonify({"error": "ต้องส่ง title"}), 400
    district_id = data.get("district_id", TOKYO_DISTRICT_HQ)
    if district_id not in TOKYO_DISTRICTS:
        return jsonify({"error": f"ไม่รู้จัก district_id '{district_id}'",
                        "known_districts": sorted(TOKYO_DISTRICTS.keys())}), 400
    incident_id = str(uuid.uuid4())
    ARCANE_ADMIN_INCIDENTS[incident_id] = {
        "incident_id": incident_id,
        "title": title,
        "description": data.get("description", ""),
        "status": "open",
        "assigned_uid": None,
        "district_id": district_id,
        "district_name_th": TOKYO_DISTRICTS[district_id]["name_th"],
        "danger_level": TOKYO_DISTRICTS[district_id]["danger_level"],
        "travel_minutes": None,   # คำนวณตอน assign เมื่อรู้ว่านักเวทย์อยู่ย่านไหน
        "opened_at": time.time(),
        "resolved_at": None,
        "outcome": None,
    }
    return jsonify({"ok": True, "incident": ARCANE_ADMIN_INCIDENTS[incident_id]})


@app.route('/api/arcane-administration/incident/assign', methods=['POST'])
def api_arcane_incident_assign():
    """body: {incident_id, uid} -> มอบหมายนักเวทย์ในสังกัดให้ไปจัดการคดี"""
    data = request.get_json(silent=True) or {}
    incident = ARCANE_ADMIN_INCIDENTS.get(data.get("incident_id"))
    uid = data.get("uid")
    if incident is None:
        return jsonify({"error": "ไม่พบคดีนี้"}), 404
    if incident["status"] != "open":
        return jsonify({"error": "คดีนี้ถูกจัดการไปแล้ว"}), 400
    if not uid:
        return jsonify({"error": "ต้องส่ง uid"}), 400
    caster = _arcane_caster(uid)

    travel_minutes = _arcane_travel_minutes(caster["current_district"], incident["district_id"])
    incident["assigned_uid"] = uid
    incident["status"] = "assigned"
    incident["travel_minutes"] = travel_minutes
    # นักเวทย์เดินทางไปถึงย่านเกิดเหตุแล้ว ตำแหน่งปัจจุบันจึงย้ายตาม
    caster["current_district"] = incident["district_id"]

    return jsonify({"ok": True, "incident": incident, "travel_minutes": travel_minutes,
                     "caster_current_district": caster["current_district"]})


@app.route('/api/arcane-administration/incident/resolve', methods=['POST'])
def api_arcane_incident_resolve():
    """body: {incident_id, outcome} -> ปิดคดี บันทึกผลลัพธ์ลงในสำนวน"""
    data = request.get_json(silent=True) or {}
    incident = ARCANE_ADMIN_INCIDENTS.get(data.get("incident_id"))
    if incident is None:
        return jsonify({"error": "ไม่พบคดีนี้"}), 404
    if incident["status"] not in ("assigned",):
        return jsonify({"error": "ต้องมอบหมายนักเวทย์ก่อนถึงจะปิดคดีได้"}), 400
    incident["status"] = "resolved"
    incident["outcome"] = data.get("outcome", "resolved")
    incident["resolved_at"] = time.time()

    hazard_ap_bonus = 0
    caster = ARCANE_ADMIN_CASTERS.get(incident["assigned_uid"])
    if caster is not None:
        caster["incidents_resolved"] += 1
        if incident["danger_level"] >= ARCANE_HAZARD_DANGER_THRESHOLD:
            hazard_ap_bonus = ARCANE_HAZARD_PAY_AP
            caster["ap"] = min(caster["max_ap"], caster["ap"] + hazard_ap_bonus)
    incident["hazard_ap_bonus"] = hazard_ap_bonus

    return jsonify({"ok": True, "incident": incident, "hazard_ap_bonus": hazard_ap_bonus})


@app.route('/api/arcane-administration/districts', methods=['GET'])
def api_arcane_districts():
    """รายชื่อย่านในแผนที่โตเกียวทั้งหมด พร้อม danger_level และเวลาเดินทางจาก HQ
    ใช้ประกอบการตัดสินใจก่อนเปิด/มอบหมายคดี (ดู POST .../incident/open ที่รับ
    district_id, และ POST .../incident/assign ที่คำนวณ travel_minutes จริงให้)"""
    return jsonify({
        "hq": TOKYO_DISTRICT_HQ,
        "districts": TOKYO_DISTRICTS,
        "hazard_pay": {
            "danger_threshold": ARCANE_HAZARD_DANGER_THRESHOLD,
            "ap_bonus": ARCANE_HAZARD_PAY_AP,
            "note": "ปิดคดีสำเร็จในย่านที่ danger_level >= threshold จะได้ AP คืนพิเศษ",
        },
    })


