def _run_arcane_administration_selftests():
    """Self-test ของโมดูล arcane-administration — เรียกด้วย:
    python3 <ไฟล์นี้> --selftest-arcane-administration"""
    c = app.test_client()
    results = []

    def check(name, cond):
        results.append((name, cond))
        print(("✅ PASS " if cond else "❌ FAIL ") + name)

    try:
        uid = "arcane_test_p1"
        for d in (ARCANE_ADMIN_CASTERS, ARCANE_ADMIN_INCIDENTS, ARCANE_ADMIN_BATTLES):
            for k in list(d.keys()):
                if isinstance(k, str) and k.startswith("arcane_test_"):
                    del d[k]

        # ลงทะเบียนแบบยังไม่มีคทา
        r = c.post('/api/arcane-administration/register', json={"uid": uid, "name": "เพื่อนทดสอบ"})
        check("register สำเร็จ ค่าเริ่มต้นเป็น hand style", r.status_code == 200 and
              r.get_json()["caster"]["casting_style"] == "hand")

        # สลับไปใช้คทาโดยยังไม่มีคทา -> error
        r = c.post('/api/arcane-administration/set-style', json={"uid": uid, "style": "staff"})
        check("สลับไปคทาตอนไม่มีคทา -> error", r.status_code == 400)

        # ให้มีคทาแล้วลองสลับใหม่ -> ผ่าน
        ARCANE_ADMIN_CASTERS[uid]["has_staff"] = True
        r = c.post('/api/arcane-administration/set-style', json={"uid": uid, "style": "staff"})
        check("สลับไปคทาตอนมีคทาแล้ว -> ผ่าน", r.status_code == 200 and
              r.get_json()["casting_style"] == "staff")

        # เริ่มการต่อสู้ (reset สไตล์กลับเป็น hand โดย default ผ่าน battle/start ไม่แตะ style)
        r = c.post('/api/arcane-administration/battle/start', json={"uid": uid, "enemy_name": "หมอกดำ"})
        battle_id = r.get_json()["battle"]["battle_id"]
        check("เริ่มการต่อสู้สำเร็จ มี enemy_hp เต็ม", r.status_code == 200 and
              r.get_json()["battle"]["enemy_hp"] == ARCANE_ADMIN_CONFIG["enemy_base_hp"])

        # ร่ายเวทย์ด้วยคทา (style ยังเป็น staff จากก่อนหน้า) -> ต้องแรงกว่าฐาน และกิน AP มากกว่าฐาน 1
        r = c.post('/api/arcane-administration/battle/cast', json={"battle_id": battle_id, "spell": "ember_lance"})
        body = r.get_json()
        base_power = ARCANE_SPELLBOOK["ember_lance"]["power"]
        check("ร่ายด้วยคทา -> power_dealt มากกว่าค่าฐานของเวทย์",
              r.status_code == 200 and body["cast"]["power_dealt"] > base_power)
        check("ร่ายด้วยคทา -> ap_spent มากกว่า ap_cost ฐาน 1 หน่วย",
              body["cast"]["ap_spent"] == ARCANE_SPELLBOOK["ember_lance"]["ap_cost"] +
              ARCANE_ADMIN_CONFIG["staff_extra_ap_cost"])

        # สลับมาร่ายมือเปล่าธาตุเดิมต่อ (ยิง fire ซ้ำ) -> ควรได้คอมโบ +1 stack และมี ap_refunded
        c.post('/api/arcane-administration/set-style', json={"uid": uid, "style": "hand"})
        r = c.post('/api/arcane-administration/battle/cast', json={"battle_id": battle_id, "spell": "ember_lance"})
        body = r.get_json()
        check("ร่ายมือเปล่าต่อคอมโบธาตุเดิม -> combo_stacks เพิ่มขึ้นและได้ ap คืน",
              r.status_code == 200 and body["cast"]["combo_stacks"] >= 1 and body["cast"]["ap_refunded"] > 0)

        # ร่ายเวทย์คนละธาตุ -> คอมโบต้องรีเซ็ตกลับ 0
        r = c.post('/api/arcane-administration/battle/cast', json={"battle_id": battle_id, "spell": "frost_needle"})
        body = r.get_json()
        check("เปลี่ยนธาตุ -> คอมโบรีเซ็ตเป็น 0", r.status_code == 200 and body["cast"]["combo_stacks"] == 0)

        # ตีจนศัตรูตายแล้วเช็คว่า battle จบแบบ victory
        while True:
            r = c.post('/api/arcane-administration/battle/cast', json={"battle_id": battle_id, "spell": "gale_slash"})
            body = r.get_json()
            if "error" in body:
                # AP หมดกลางทาง ให้รอฟื้นด้วยการยิงเวทย์ถูกๆ แทนสักตา
                r2 = c.post('/api/arcane-administration/battle/cast', json={"battle_id": battle_id, "spell": "frost_needle"})
                body2 = r2.get_json()
                if body2.get("battle", {}).get("finished"):
                    body = body2
                    break
                continue
            if body["battle"]["finished"]:
                break
        check("ต่อสู้จนจบ -> ได้ผล victory หรือ defeat", body["battle"]["result"] in ("victory", "defeat"))

        # ระบบคดี: เปิดคดี -> มอบหมาย -> ปิดคดี (ผูกกับย่านในแผนที่โตเกียว)
        r = c.post('/api/arcane-administration/incident/open',
                    json={"title": "หมอกวิเศษปกคลุมย่านเก่า", "description": "ทดสอบระบบคดี",
                          "district_id": "odaiba"})
        incident_id = r.get_json()["incident"]["incident_id"]
        check("เปิดคดีสำเร็จ status เป็น open และผูก district ถูกต้อง",
              r.get_json()["incident"]["status"] == "open" and
              r.get_json()["incident"]["district_id"] == "odaiba" and
              r.get_json()["incident"]["danger_level"] == TOKYO_DISTRICTS["odaiba"]["danger_level"])

        r = c.post('/api/arcane-administration/incident/open', json={"title": "ทดสอบ", "district_id": "ไม่มีย่านนี้"})
        check("เปิดคดีด้วย district_id ที่ไม่รู้จัก -> error", r.status_code == 400)

        r = c.post('/api/arcane-administration/incident/resolve', json={"incident_id": incident_id, "outcome": "clear"})
        check("ปิดคดีก่อนมอบหมาย -> ต้อง error", r.status_code == 400)

        # ก่อน assign นักเวทย์อยู่ที่ HQ -> เดินทางไป odaiba ต้องใช้เวลาเท่ากับ
        # travel_minutes_from_hq ของ odaiba (เพราะ HQ เป็นจุดต่อ)
        expected_travel = TOKYO_DISTRICTS["odaiba"]["travel_minutes_from_hq"]
        r = c.post('/api/arcane-administration/incident/assign', json={"incident_id": incident_id, "uid": uid})
        body = r.get_json()
        check("มอบหมายนักเวทย์ให้คดี -> ผ่าน และคำนวณ travel_minutes ถูกต้อง",
              r.status_code == 200 and body["incident"]["status"] == "assigned" and
              body["travel_minutes"] == expected_travel)
        check("นักเวทย์ย้ายตำแหน่งปัจจุบันไปที่ย่านเกิดเหตุแล้ว",
              ARCANE_ADMIN_CASTERS[uid]["current_district"] == "odaiba")

        ap_before_resolve = ARCANE_ADMIN_CASTERS[uid]["ap"]
        r = c.post('/api/arcane-administration/incident/resolve', json={"incident_id": incident_id, "outcome": "clear"})
        body = r.get_json()
        check("ปิดคดีหลังมอบหมายแล้ว -> ผ่าน status เป็น resolved",
              r.status_code == 200 and body["incident"]["status"] == "resolved")
        check("ปิดคดีในย่านอันตรายสูง (odaiba) -> ได้ hazard AP bonus",
              body["hazard_ap_bonus"] == ARCANE_HAZARD_PAY_AP and
              ARCANE_ADMIN_CASTERS[uid]["ap"] >= ap_before_resolve)

        # districts endpoint
        r = c.get('/api/arcane-administration/districts')
        check("districts: status 200 มี hq และรายชื่อย่านครบ",
              r.status_code == 200 and r.get_json()["hq"] == TOKYO_DISTRICT_HQ and
              "odaiba" in r.get_json()["districts"])

        # info endpoint
        r = c.get('/api/arcane-administration/info')
        check("info: status 200 และมี spellbook/endpoints/districts",
              r.status_code == 200 and "spellbook" in r.get_json() and
              "endpoints" in r.get_json() and "districts" in r.get_json())

    finally:
        for d in (ARCANE_ADMIN_CASTERS, ARCANE_ADMIN_INCIDENTS, ARCANE_ADMIN_BATTLES):
            for k in list(d.keys()):
                if isinstance(k, str) and k.startswith("arcane_test_"):
                    del d[k]

    print(f"\n{sum(1 for _, ok in results if ok)}/{len(results)} tests passed")
    return all(ok for _, ok in results)





# =====================================================================
# [ VMAX ARCANE UNIVERSAL HOOK — เชื่อมระบบร่ายเวทย์เข้ากับ "ทุกเกม" ในไฟล์ ]
# หลักการ: uid ของผู้เล่นใช้ร่วมกันทุกโมดูลในไฟล์นี้อยู่แล้ว (ARCANE_ADMIN_CASTERS
# ผูกกับ uid ตัวเดียวกับที่ pet/charge-jump/tdm4v4/ฯลฯ ใช้) ดังนั้น AP, สไตล์การร่าย
# (คทา/มือเปล่า), และคอมโบของผู้เล่นคนหนึ่งจึงเป็น "โปรไฟล์กลาง" ใบเดียวที่ทุกโหมด
# เกมดึงไปใช้ได้ทันทีผ่านฟังก์ชัน arcane_universal_boost() ด้านล่าง โดยไม่ต้องแก้
# โค้ดของแต่ละโหมดเกมเลย — แค่ห่อค่าตัวเลขผลลัพธ์ (ดาเมจ/ระยะ/อัตราสำเร็จ ฯลฯ)
# ของโหมดนั้นๆ ผ่านฟังก์ชันนี้ก่อนส่งกลับ
#   - เวทย์แบบคทา: ผลลัพธ์ตัวเลข x1.35 (แรงกว่า) แต่กิน AP ตามที่ระบุ
#   - เวทย์แบบมือเปล่า: ผลลัพธ์ตัวเลข x0.80 (เบากว่า) กิน AP เท่าเดิม
#   - AP ไม่พอ -> ไม่บูสต์ให้ (applied=False) คืนค่าเดิมไม่มีผลข้างเคียง
# ตัวอย่างการต่อกับเกมจริงสองโหมดด้านล่าง (charge-jump ระยะกระโดด, world-boss
# ดาเมจที่ทำร่วมกัน) ใช้แพทเทิร์นเดียวกันนี้ทั้งคู่ — โหมดอื่นที่เหลือ (tdm4v4,
# meadow-town, container-blast, search-and-rescue, capture-methods ฯลฯ) ต่อ
# เข้าด้วยแพทเทิร์นเดียวกันได้เลย: เรียก arcane_universal_boost(uid, ค่าเดิม)
# แล้วเอา result["value"] ไปแทนค่าเดิมก่อนส่ง response
# =====================================================================

def arcane_universal_boost(uid, base_value, ap_cost=1):
    """บูสต์ค่าตัวเลขใดๆ จากเกมไหนก็ได้ในไฟล์นี้ ด้วยโปรไฟล์เวทย์กลางของ uid —
    คืน dict เดิมเสมอ (ไม่ throw) เผื่อโหมดเกมอยากเช็ค applied ก่อนใช้ค่า"""
    caster = _arcane_caster(uid)
    if caster["ap"] < ap_cost:
        return {
            "applied": False, "value": base_value, "base_value": base_value,
            "reason": "AP ไม่พอสำหรับบูสต์เวทย์", "ap": caster["ap"], "ap_cost": ap_cost,
        }
    caster["ap"] -= ap_cost
    style = caster["casting_style"]
    mult = ARCANE_FOCI.get(style, ARCANE_FOCI["hand"])["power_mult"]
    boosted = base_value * mult
    return {
        "applied": True, "value": round(boosted, 2), "base_value": base_value,
        "casting_style": style, "multiplier": round(mult, 3),
        "ap_spent": ap_cost, "ap_remaining": caster["ap"],
    }


@app.route('/api/arcane-administration/apply-boost', methods=['POST'])
def api_arcane_apply_boost():
    """body: {uid, base_value, ap_cost?} -> จุดเชื่อมกลางที่ 'ทุกเกม' ในไฟล์นี้เรียกใช้ได้
    เพื่อบูสต์ผลลัพธ์ตัวเลขของโหมดตัวเองด้วยโปรไฟล์เวทย์ (คทา/มือเปล่า) ของผู้เล่นคนนั้น"""
    data = request.get_json(silent=True) or {}
    uid = data.get("uid")
    if not uid or "base_value" not in data:
        return jsonify({"error": "ต้องส่ง uid และ base_value"}), 400
    try:
        base_value = float(data["base_value"])
    except (TypeError, ValueError):
        return jsonify({"error": "base_value ต้องเป็นตัวเลข"}), 400
    ap_cost = int(data.get("ap_cost", 1))
    return jsonify(arcane_universal_boost(uid, base_value, ap_cost=ap_cost))


@app.route('/api/charge-jump/execute-arcane', methods=['POST'])
def api_charge_jump_execute_arcane():
    """body: {uid, ap_cost?} -> เหมือน /api/charge-jump/execute ทุกอย่าง แต่ถ้า AP พอ
    จะบูสต์ 'ระยะกระโดด' ด้วยโปรไฟล์เวทย์ของผู้เล่น แล้วขยับตำแหน่งลงจอดเพิ่มตามนั้น"""
    data = request.get_json(silent=True) or {}
    uid = data.get("uid")
    if not uid:
        return jsonify({"error": "ต้องส่ง uid"}), 400
    result = charge_jump_execute(uid)
    if "error" in result:
        return jsonify(result), 400

    boost = arcane_universal_boost(uid, result["distance"], ap_cost=int(data.get("ap_cost", 1)))
    result["arcane_boost"] = boost
    if boost["applied"]:
        extra = boost["value"] - result["distance"]
        st = _charge_jump_state(uid)
        st["x"] += st["facing_x"] * extra
        st["y"] += st["facing_y"] * extra
        result["distance"] = boost["value"]
        result["landing"] = {"x": round(st["x"], 2), "y": round(st["y"], 2)}
        result["state"] = st

    return jsonify(result)


@app.route('/api/worldmap/world_boss/damage-arcane', methods=['POST'])
def api_worldmap_world_boss_damage_arcane():
    """body: {uid, dmg, ap_cost?} -> ทำดาเมจเวิลด์บอสร่วมกับผู้เล่นคนอื่น เหมือน
    /api/worldmap/world_boss/damage แต่ค่าดาเมจถูกบูสต์ด้วยโปรไฟล์เวทย์ของ uid ก่อน"""
    data = request.get_json(silent=True) or {}
    uid = data.get("uid")
    if not uid:
        return jsonify({"error": "ต้องส่ง uid"}), 400
    if not WORLD_BOSS_STATE["active"]:
        return jsonify({"st": "error", "msg": "ไม่มีเวิลด์บอสอยู่ตอนนี้"}), 400

    base_dmg = float(data.get("dmg", 0))
    boost = arcane_universal_boost(uid, base_dmg, ap_cost=int(data.get("ap_cost", 1)))
    final_dmg = boost["value"] if boost["applied"] else base_dmg

    WORLD_BOSS_STATE["hp"] = max(0, WORLD_BOSS_STATE["hp"] - int(final_dmg))
    if WORLD_BOSS_STATE["hp"] <= 0:
        WORLD_BOSS_STATE["active"] = False
        WORLD_BOSS_STATE["respawn_at"] = time.time() + 3600
    return jsonify({"st": "ok", "arcane_boost": boost, "damage_dealt": final_dmg, **WORLD_BOSS_STATE})


VMAX_MODULES["arcane_administration"]["routes"] += [
    "/api/arcane-administration/apply-boost",
    "/api/charge-jump/execute-arcane",
    "/api/worldmap/world_boss/damage-arcane",
]
VMAX_MODULES["arcane_administration"]["universal_hook_note"] = (
    "arcane_universal_boost(uid, base_value, ap_cost) คือจุดเชื่อมกลาง ทุกโมดูล/เกมในไฟล์นี้ "
    "ต่อระบบเวทย์เข้าไปได้ด้วยแพทเทิร์นเดียวกับ charge-jump / world-boss ด้านบน "
    "(เรียกฟังก์ชันเกม -> เอาค่าตัวเลขผลลัพธ์ยัดเข้า arcane_universal_boost -> แทนค่าเดิม)"
)


def _run_arcane_universal_hook_selftests():
    """Self-test ของ universal hook — เรียกด้วย:
    python3 <ไฟล์นี้> --selftest-arcane-universal-hook"""
    c = app.test_client()
    results = []

    def check(name, cond):
        results.append((name, cond))
        print(("✅ PASS " if cond else "❌ FAIL ") + name)

    try:
        uid = "arcane_hook_test_p1"
        for d in (ARCANE_ADMIN_CASTERS,):
            for k in list(d.keys()):
                if isinstance(k, str) and k.startswith("arcane_hook_test_"):
                    del d[k]
        for k in list(CHARGE_JUMP_STATE.keys()):
            if k.startswith("arcane_hook_test_"):
                del CHARGE_JUMP_STATE[k]

        c.post('/api/arcane-administration/register', json={"uid": uid, "has_staff": True})
        c.post('/api/arcane-administration/set-style', json={"uid": uid, "style": "staff"})

        # apply-boost ทั่วไป: ค่าที่บูสต์แล้วต้องมากกว่าค่าเดิมตอนใช้คทา
        r = c.post('/api/arcane-administration/apply-boost', json={"uid": uid, "base_value": 100, "ap_cost": 1})
        body = r.get_json()
        check("apply-boost ด้วยคทา -> value มากกว่า base_value", body["applied"] and body["value"] > 100)

        # ยิงจน AP หมด -> ครั้งต่อไปต้อง applied=False และค่าตัวเลขไม่เปลี่ยน
        caster = ARCANE_ADMIN_CASTERS[uid]
        caster["ap"] = 0
        r = c.post('/api/arcane-administration/apply-boost', json={"uid": uid, "base_value": 50, "ap_cost": 1})
        body = r.get_json()
        check("AP หมด -> apply-boost ไม่บูสต์ (applied=False, value เท่าเดิม)",
              body["applied"] is False and body["value"] == 50)
        caster["ap"] = caster["max_ap"]

        # charge-jump แบบมีเวทย์: วิ่งจน charge เต็มแล้วกระโดด -> ระยะต้องมากกว่าฐานเพราะมีคทา
        ticks_needed = -(-CHARGE_JUMP_CONFIG["charge_required"] // CHARGE_JUMP_CONFIG["charge_per_tick"])
        for _ in range(ticks_needed):
            c.post('/api/charge-jump/run-tick', json={"uid": uid, "dir_x": 1, "dir_y": 0})
        r = c.post('/api/charge-jump/execute-arcane', json={"uid": uid})
        body = r.get_json()
        check("charge-jump-arcane: กระโดดไกลกว่าฐานเพราะร่ายด้วยคทา",
              r.status_code == 200 and body["arcane_boost"]["applied"] and
              body["distance"] > CHARGE_JUMP_CONFIG["charged_jump_distance"])

        # world boss แบบมีเวทย์: spawn บอสก่อน แล้วยิงดาเมจแบบบูสต์ -> hp ต้องลดมากกว่าค่าที่ส่งไปดิบๆ
        c.post('/api/worldmap/world_boss/spawn', json={"boss_id": "arcane_hook_test_boss", "hp_max": 100000})
        hp_before = WORLD_BOSS_STATE["hp"]
        r = c.post('/api/worldmap/world_boss/damage-arcane', json={"uid": uid, "dmg": 1000})
        body = r.get_json()
        hp_after = WORLD_BOSS_STATE["hp"]
        check("world-boss-arcane: ดาเมจจริงมากกว่าค่าดิบที่ส่งไปเพราะร่ายด้วยคทา",
              r.status_code == 200 and body["damage_dealt"] > 1000 and (hp_before - hp_after) > 1000)

    finally:
        for d in (ARCANE_ADMIN_CASTERS,):
            for k in list(d.keys()):
                if isinstance(k, str) and k.startswith("arcane_hook_test_"):
                    del d[k]
        for k in list(CHARGE_JUMP_STATE.keys()):
            if k.startswith("arcane_hook_test_"):
                del CHARGE_JUMP_STATE[k]
        WORLD_BOSS_STATE.update({"active": False, "boss_id": None, "hp": 0, "hp_max": 0, "respawn_at": None})

    print(f"\n{sum(1 for _, ok in results if ok)}/{len(results)} tests passed")
    return all(ok for _, ok in results)


def _run_arcane_weapon_import_selftests():
    """Self-test ของระบบยืมอาวุธข้ามเกมมาร่ายเวทย์ — เรียกด้วย:
    python3 <ไฟล์นี้> --selftest-arcane-weapon-import"""
    c = app.test_client()
    results = []

    def check(name, cond):
        results.append((name, cond))
        print(("✅ PASS " if cond else "❌ FAIL ") + name)

    try:
        uid = "arcane_weapon_test_p1"
        for k in list(ARCANE_ADMIN_CASTERS.keys()):
            if k.startswith("arcane_weapon_test_"):
                del ARCANE_ADMIN_CASTERS[k]

        c.post('/api/arcane-administration/register', json={"uid": uid})

        # ยืมอาวุธที่ไม่รู้จัก -> error พร้อมรายชื่ออาวุธที่รู้จัก
        r = c.post('/api/arcane-administration/import-weapon', json={"uid": uid, "weapon_id": "spoon"})
        check("ยืมอาวุธที่ระบบไม่รู้จัก -> error", r.status_code == 400 and "known_weapon_ids" in r.get_json())

        # สลับไปใช้ katana ก่อน import -> ต้อง error
        r = c.post('/api/arcane-administration/set-style', json={"uid": uid, "style": "katana"})
        check("สลับไป katana ก่อน import -> error", r.status_code == 400)

        # ยืมคาตานะจากโหมดดวลดาบ (ใช้ id จริงจาก KATANA_WEAPON_IDS)
        katana_id = sorted(KATANA_WEAPON_IDS)[0]
        r = c.post('/api/arcane-administration/import-weapon', json={"uid": uid, "weapon_id": katana_id})
        body = r.get_json()
        check("ยืมคาตานะสำเร็จ -> unlocked_focus เป็น katana",
              r.status_code == 200 and body["unlocked_focus"] == "katana")

        # สลับไปใช้ katana ได้แล้วหลัง import
        r = c.post('/api/arcane-administration/set-style', json={"uid": uid, "style": "katana"})
        check("สลับไป katana หลัง import -> ผ่าน", r.status_code == 200 and
              r.get_json()["casting_style"] == "katana")

        # ยืมปืน M82 แล้วสลับไปใช้ -> power_mult ต้องแรงกว่า katana และกิน ap มากกว่า
        r = c.post('/api/arcane-administration/import-weapon', json={"uid": uid, "weapon_id": M82_WEAPON_ID})
        check("ยืม M82 สำเร็จ -> unlocked_focus เป็น m82_sniper", r.get_json()["unlocked_focus"] == "m82_sniper")
        c.post('/api/arcane-administration/set-style', json={"uid": uid, "style": "m82_sniper"})

        r = c.post('/api/arcane-administration/battle/start', json={"uid": uid, "enemy_name": "เป้าทดสอบ"})
        battle_id = r.get_json()["battle"]["battle_id"]
        r = c.post('/api/arcane-administration/battle/cast', json={"battle_id": battle_id, "spell": "ember_lance"})
        body = r.get_json()
        base_power = ARCANE_SPELLBOOK["ember_lance"]["power"]
        staff_power = base_power * ARCANE_FOCI["staff"]["power_mult"]
        check("ร่ายผ่าน M82 -> power_dealt แรงกว่าร่ายผ่านคทา",
              r.status_code == 200 and body["cast"]["power_dealt"] > staff_power)
        check("ร่ายผ่าน M82 -> ap_spent มากกว่าร่ายผ่านคทา (กิน ap หนักสุด)",
              body["cast"]["ap_spent"] == ARCANE_SPELLBOOK["ember_lance"]["ap_cost"] + ARCANE_FOCI["m82_sniper"]["ap_delta"])

        # apply-boost แบบทั่วไปก็ต้องใช้ focus ที่ import ไว้ได้เหมือนกัน
        ARCANE_ADMIN_CASTERS[uid]["ap"] = ARCANE_ADMIN_CASTERS[uid]["max_ap"]
        r = c.post('/api/arcane-administration/apply-boost', json={"uid": uid, "base_value": 100})
        check("apply-boost ตอนใช้ M82 เป็นตัวกลาง -> บูสต์แรงกว่าคทา",
              r.get_json()["applied"] and r.get_json()["value"] > 100 * ARCANE_FOCI["staff"]["power_mult"])

    finally:
        for k in list(ARCANE_ADMIN_CASTERS.keys()):
            if k.startswith("arcane_weapon_test_"):
                del ARCANE_ADMIN_CASTERS[k]

    print(f"\n{sum(1 for _, ok in results if ok)}/{len(results)} tests passed")
    return all(ok for _, ok in results)



# =====================================================================
# [ VMAX WILDKIN CAPTURE — จับ/เลี้ยง/แปลงร่างเป็นสัตว์วิเศษ + กล่องเก็บสัตว์ ]
# แรงบันดาลใจจากเกมแนวจับสัตว์ประหลาดพกพา (เช่นสไตล์ตู้เก็บสัตว์ในเกม Pokémon)
# แต่ทุกชื่อ/สายพันธุ์/ดีไซน์เป็นของต้นฉบับที่สร้างขึ้นใหม่ในไฟล์นี้เอง ไม่ใช้ชื่อ
# ตัวละคร โลโก้ หรือทรัพย์สินทางปัญญาของเกมลิขสิทธิ์ใดๆ ทั้งสิ้น
#
# กลไกหลัก:
#   1) แผนที่ใช้ย่านเดียวกับ TOKYO_DISTRICTS ของโมดูล arcane-administration —
#      แต่ละย่านมีสัตว์วิเศษประจำถิ่นของตัวเอง (WILDKIN_SPAWN_POOL)
#   2) ไปที่ย่านหนึ่ง -> มีสัตว์ป่าตัวหนึ่ง "ยืนรอ" ให้จับ (spawn) พอจับสำเร็จ/พลาด
#      ตัวนั้นจะหายไป แล้วต้องรอ cooldown ก่อนจะมีตัวใหม่โผล่มาแทน
#   3) จับสำเร็จ -> เข้าไปอยู่ในทีมหลัก (party สูงสุด WILDKIN_PARTY_MAX ตัว) ถ้าทีม
#      เต็มจะไหลไปเก็บใน "กล่อง" (storage box) แบบตู้เก็บสัตว์อัตโนมัติ
#   4) ผู้เล่น "แปลงร่าง" เป็นสัตว์ตัวหนึ่งในทีมหลักได้ (ต้องอยู่ในทีม ไม่ใช่ในกล่อง)
#      เพื่อรับโบนัสพลัง (WILDKIN_TRANSFORM_POWER_MULT) ชั่วคราว แล้ว "คืนร่าง"
#      กลับเป็นมนุษย์เมื่อไรก็ได้ (ส่ง creature_uid เป็น None)
#   5) กล่องใหม่จะ "โผล่มา" ให้อัตโนมัติเมื่อเวลาผ่านไปครบตามกำหนด
#      (WILDKIN_BOX_UNLOCK_INTERVAL_SEC) นับจากกล่องล่าสุดที่เปิด — เรียกเช็คได้ทุก
#      ครั้งที่เปิดหน้ากล่อง เหมือนระบบกล่องรายวันของเกมจับสัตว์ทั่วไป
# =====================================================================

WILDKIN_PARTY_MAX = 6
WILDKIN_BOX_SLOTS = 30
WILDKIN_SPAWN_COOLDOWN_SEC = 60          # หลังจับ/พลาด ต้องรอเท่านี้ก่อนมีตัวใหม่โผล่
WILDKIN_BOX_UNLOCK_INTERVAL_SEC = 24 * 60 * 60   # กล่องใหม่โผล่มาทุกๆ 24 ชม. (ค่าเริ่มต้น)
WILDKIN_TRANSFORM_POWER_MULT = 1.30      # โบนัสพลังเมื่อแปลงร่างเป็นสัตว์ที่จับมาได้

WILDKIN_SPECIES = {
    "emberfox":  {"name_th": "เอมเบอร์ฟอกซ์",  "name_en": "Emberfox",  "element": "fire",     "rarity": "common",    "base_power": 14, "capture_rate": 0.55},
    "frostpup":  {"name_th": "ฟรอสต์พัพ",     "name_en": "Frostpup",  "element": "ice",      "rarity": "common",    "base_power": 13, "capture_rate": 0.55},
    "galewing":  {"name_th": "เกลวิง",        "name_en": "Galewing",  "element": "wind",     "rarity": "uncommon",  "base_power": 17, "capture_rate": 0.40},
    "sparkrat":  {"name_th": "สปาร์กแรท",     "name_en": "Sparkrat",  "element": "electric", "rarity": "common",    "base_power": 12, "capture_rate": 0.60},
    "tidalfin":  {"name_th": "ไทดัลฟิน",      "name_en": "Tidalfin",  "element": "water",    "rarity": "uncommon",  "base_power": 18, "capture_rate": 0.42},
    "duskmoth":  {"name_th": "ดัสก์มอธ",      "name_en": "Duskmoth",  "element": "shadow",   "rarity": "rare",      "base_power": 22, "capture_rate": 0.28},
    "gleamowl":  {"name_th": "กลีมอาวล์",     "name_en": "Gleamowl",  "element": "light",    "rarity": "rare",      "base_power": 23, "capture_rate": 0.27},
    "ironshell": {"name_th": "ไอรอนเชลล์",    "name_en": "Ironshell", "element": "earth",    "rarity": "uncommon",  "base_power": 19, "capture_rate": 0.38},
    "voltstag":  {"name_th": "โวลต์สแตก",     "name_en": "Voltstag",  "element": "electric", "rarity": "rare",      "base_power": 24, "capture_rate": 0.25},
    "aurawyrm":  {"name_th": "ออร่าเวิร์ม",    "name_en": "Aurawyrm",  "element": "light",    "rarity": "legendary", "base_power": 32, "capture_rate": 0.08},
}

# สัตว์ประจำถิ่นของแต่ละย่านในแผนที่โตเกียว (ใช้ TOKYO_DISTRICTS ร่วมกับ arcane-administration)
WILDKIN_SPAWN_POOL = {
    "chiyoda":   ["sparkrat", "gleamowl"],
    "shinjuku":  ["sparkrat", "duskmoth", "galewing"],
    "shibuya":   ["galewing", "sparkrat"],
    "asakusa":   ["gleamowl", "ironshell"],
    "akihabara": ["sparkrat", "voltstag"],
    "ikebukuro": ["emberfox", "duskmoth"],
    "ueno":      ["ironshell", "frostpup"],
    "odaiba":    ["tidalfin", "aurawyrm"],
    "roppongi":  ["duskmoth", "voltstag"],
    "ginza":     ["gleamowl", "emberfox"],
}

WILDKIN_BALL_TYPES = {
    "basic_orb":   {"name_th": "ลูกแก้วธรรมดา", "capture_mult": 1.0},
    "greater_orb": {"name_th": "ลูกแก้วขั้นสูง", "capture_mult": 1.5},
    "master_orb":  {"name_th": "ลูกแก้วสูงสุด",  "capture_mult": 3.0},
}

# กระเป๋าเริ่มต้นของนักล่าหน้าใหม่ — พอให้เริ่มจับได้ทันที ที่เหลือต้องไปเก็บจากจุดจ่ายเสบียง
WILDKIN_STARTER_INVENTORY = {"basic_orb": 5, "greater_orb": 0, "master_orb": 0}

# =====================================================================
# [ WILDKIN SUPPLY POINTS — จุดจ่ายเสบียง (แบบเดียวกับจุดแวะเก็บของบนแผนที่) ]
# ทุกย่านใน TOKYO_DISTRICTS มีจุดจ่ายเสบียง 1 จุด ผู้เล่นไปที่ย่านนั้นแล้ว "เก็บ"
# จะได้ลูกแก้วแบบสุ่ม (ตาม WILDKIN_SUPPLY_DROP_TABLE) จำนวนสุ่มเข้ากระเป๋าทันที
# แล้วจุดนั้นจะเข้าคูลดาวน์ก่อนเก็บซ้ำได้อีกครั้ง — แยกกันคนละระบบจากกล่องเก็บสัตว์
# (storage box) ที่เก็บแค่สัตว์วิเศษที่จับมาได้เท่านั้น
# =====================================================================

WILDKIN_SUPPLY_COOLDOWN_SEC = 5 * 60     # เก็บซ้ำจุดเดิมได้ทุกๆ กี่วินาที
WILDKIN_SUPPLY_DROP_QTY_MIN = 1          # จำนวนลูกแก้วที่ได้ต่อการเก็บ 1 ครั้ง (สุ่มช่วงนี้)
WILDKIN_SUPPLY_DROP_QTY_MAX = 3
WILDKIN_SUPPLY_DROP_TABLE = {            # ความน่าจะเป็นของลูกแก้วแต่ละชนิดที่จะได้ต่อ 1 ลูก (รวมกัน = 1.0)
    "basic_orb": 0.65,
    "greater_orb": 0.30,
    "master_orb": 0.05,
}

WILDKIN_SUPPLY_POINTS = {}   # "uid:district_id" -> {"last_collected_at", "next_available_at"}

WILDKIN_TRAINERS = {}   # uid -> โปรไฟล์นักล่าสัตว์วิเศษ (party/boxes/สถานะแปลงร่าง)
WILDKIN_SPAWNS = {}     # "uid:district_id" -> สัตว์ป่าที่กำลังยืนรอ (หรือกำลังรอ cooldown)


def _wildkin_new_box(box_number):
    return {"box_id": f"box_{box_number}", "name": f"กล่องที่ {box_number}", "slots": [None] * WILDKIN_BOX_SLOTS}


def _wildkin_trainer(uid):
    """สร้าง/ดึงโปรไฟล์นักล่าสัตว์วิเศษ — เริ่มต้นมีกล่องเปล่า 1 ใบเสมอ"""
    t = WILDKIN_TRAINERS.get(uid)
    if t is None:
        t = {
            "uid": uid,
            "party": [],                       # ทีมหลัก สูงสุด WILDKIN_PARTY_MAX ตัว
            "boxes": [_wildkin_new_box(1)],
            "transformed_as": None,             # creature_uid ที่กำลังแปลงร่างอยู่ (None = ร่างมนุษย์)
            "last_box_unlock_at": time.time(),
            "creatures_caught": 0,
            "inventory": dict(WILDKIN_STARTER_INVENTORY),   # กระเป๋าลูกแก้ว/เสบียง — เติมได้จากจุดจ่ายเสบียง
        }
        WILDKIN_TRAINERS[uid] = t
    return t


def _wildkin_spawn_key(uid, district_id):
    return f"{uid}:{district_id}"


def _wildkin_get_or_make_spawn(uid, district_id):
    """คืนสัตว์ป่าที่ยืนรออยู่ในย่านนี้ตอนนี้ (สุ่มตัวใหม่ถ้ายังไม่เคยมี หรือ cooldown
    ครบแล้ว) — ย่านที่ไม่มีในแผนที่/ไม่มีสัตว์ประจำถิ่นจะคืน error"""
    pool = WILDKIN_SPAWN_POOL.get(district_id)
    if not pool:
        return {"error": f"ย่าน '{district_id}' ไม่มีสัตว์วิเศษให้จับ",
                "known_districts": sorted(WILDKIN_SPAWN_POOL.keys())}
    key = _wildkin_spawn_key(uid, district_id)
    spawn = WILDKIN_SPAWNS.get(key)
    now = time.time()
    if spawn is None or (not spawn["available"] and now >= spawn["next_spawn_at"]):
        spawn = {
            "species_id": random.choice(pool),
            "spawned_at": now,
            "available": True,
            "next_spawn_at": None,
        }
        WILDKIN_SPAWNS[key] = spawn
    return spawn


def _wildkin_place_new_creature(trainer, creature):
    """ใส่สัตว์ที่เพิ่งจับได้ลงทีมหลักก่อนถ้ายังไม่เต็ม ไม่งั้นไหลลงกล่องช่องว่างแรกที่เจอ"""
    if len(trainer["party"]) < WILDKIN_PARTY_MAX:
        trainer["party"].append(creature)
        return "party"
    for box in trainer["boxes"]:
        for i, slot in enumerate(box["slots"]):
            if slot is None:
                box["slots"][i] = creature
                return box["box_id"]
    return "boxes_full"


def _wildkin_attempt_catch(uid, district_id, ball_type):
    spawn = _wildkin_get_or_make_spawn(uid, district_id)
    if "error" in spawn:
        return spawn
    if not spawn["available"]:
        wait = max(0.0, spawn["next_spawn_at"] - time.time())
        return {"error": "ยังไม่มีสัตว์วิเศษให้จับตอนนี้ รอสักครู่", "seconds_until_next_spawn": round(wait, 1)}
    ball = WILDKIN_BALL_TYPES.get(ball_type)
    if ball is None:
        return {"error": f"ไม่รู้จักลูกแก้ว '{ball_type}'", "known_ball_types": sorted(WILDKIN_BALL_TYPES.keys())}

    # ต้องมีลูกแก้วชนิดนี้ในกระเป๋าก่อนถึงจะขว้างได้ — เก็บเพิ่มได้จากจุดจ่ายเสบียงในแต่ละย่าน
    trainer = _wildkin_trainer(uid)
    have = trainer["inventory"].get(ball_type, 0)
    if have <= 0:
        return {"error": f"ไม่มี '{ball_type}' เหลือในกระเป๋าแล้ว ไปเก็บเสบียงจากจุดจ่ายเสบียงในย่านต่างๆ ก่อน",
                "inventory": dict(trainer["inventory"])}

    species_id = spawn["species_id"]
    species = WILDKIN_SPECIES[species_id]
    chance = min(1.0, species["capture_rate"] * ball["capture_mult"])
    success = random.random() < chance

    # ขว้างลูกแก้วออกไปแล้วก็หายไปจากกระเป๋าเสมอ ไม่ว่าจะจับติดหรือพลาด (เหมือนปาลูกบอลจริง)
    trainer["inventory"][ball_type] = have - 1

    # ไม่ว่าจับติดหรือพลาด ตัวที่ยืนรออยู่ก็หายไป ต้องรอ cooldown ก่อนมีตัวใหม่เสมอ
    spawn["available"] = False
    spawn["next_spawn_at"] = time.time() + WILDKIN_SPAWN_COOLDOWN_SEC

    result = {
        "attempted_species": species_id,
        "ball_type": ball_type,
        "capture_chance": round(chance, 3),
        "success": success,
        "seconds_until_next_spawn": WILDKIN_SPAWN_COOLDOWN_SEC,
        "inventory": dict(trainer["inventory"]),
    }
    if not success:
        return result

    creature = {
        "creature_uid": str(uuid.uuid4()),
        "species_id": species_id,
        "nickname": species["name_th"],
        "level": 1,
        "caught_in_district": district_id,
        "caught_at": time.time(),
    }
    trainer["creatures_caught"] += 1
    result["creature"] = creature
    result["placed_in"] = _wildkin_place_new_creature(trainer, creature)
    return result


def _wildkin_find_creature(trainer, creature_uid):
    """หา creature dict จาก creature_uid — คืน (creature, location, slot_index)
    location คือ "party" หรือ box_id, slot_index มีค่าเฉพาะตอนอยู่ในกล่อง"""
    for c in trainer["party"]:
        if c["creature_uid"] == creature_uid:
            return c, "party", None
    for box in trainer["boxes"]:
        for i, slot in enumerate(box["slots"]):
            if slot is not None and slot["creature_uid"] == creature_uid:
                return slot, box["box_id"], i
    return None, None, None


def wildkin_transform(uid, creature_uid):
    """creature_uid เป็น None/ไม่ส่ง -> คืนร่างกลับเป็นมนุษย์ ไม่งั้นแปลงร่างเป็นสัตว์
    ตัวนั้น (ต้องอยู่ในทีมหลักเท่านั้น ห้ามอยู่ในกล่อง)"""
    trainer = _wildkin_trainer(uid)
    if not creature_uid:
        trainer["transformed_as"] = None
        return {"ok": True, "uid": uid, "transformed_as": None, "note": "คืนร่างเป็นมนุษย์แล้ว"}

    creature, location, _ = _wildkin_find_creature(trainer, creature_uid)
    if creature is None:
        return {"error": "ไม่พบสัตว์วิเศษตัวนี้ในทีม/กล่องของคุณ"}
    if location != "party":
        return {"error": "แปลงร่างได้เฉพาะสัตว์ที่อยู่ในทีมหลัก (party) เท่านั้น ย้ายออกจากกล่องก่อน"}

    trainer["transformed_as"] = creature_uid
    species = WILDKIN_SPECIES[creature["species_id"]]
    return {"ok": True, "uid": uid, "transformed_as": creature_uid, "creature": creature,
            "species": species, "power_mult": WILDKIN_TRANSFORM_POWER_MULT}


def wildkin_box_move(uid, creature_uid, destination):
    """ย้ายสัตว์วิเศษระหว่างทีมหลัก <-> กล่อง — destination คือ "party" หรือ box_id
    (เช่น "box_1") ห้ามย้ายสัตว์ที่กำลังแปลงร่างเป็นอยู่ตอนนี้"""
    trainer = _wildkin_trainer(uid)
    creature, location, idx = _wildkin_find_creature(trainer, creature_uid)
    if creature is None:
        return {"error": "ไม่พบสัตว์วิเศษตัวนี้"}
    if trainer["transformed_as"] == creature_uid:
        return {"error": "กำลังแปลงร่างเป็นสัตว์ตัวนี้อยู่ ต้องคืนร่างก่อนถึงจะย้ายได้"}

    source_box = None if location == "party" else next(b for b in trainer["boxes"] if b["box_id"] == location)

    if destination == "party":
        if len(trainer["party"]) >= WILDKIN_PARTY_MAX:
            return {"error": f"ทีมหลักเต็มแล้ว (สูงสุด {WILDKIN_PARTY_MAX} ตัว)"}
    else:
        dest_box = next((b for b in trainer["boxes"] if b["box_id"] == destination), None)
        if dest_box is None:
            return {"error": f"ไม่พบกล่อง '{destination}'"}
        if all(s is not None for s in dest_box["slots"]):
            return {"error": f"กล่อง '{destination}' เต็มแล้ว"}

    # เอาออกจากที่เดิมก่อน (คำนวณปลายทางผ่านการตรวจสอบด้านบนแล้วว่าใส่ได้แน่)
    if location == "party":
        trainer["party"].remove(creature)
    else:
        source_box["slots"][idx] = None

    if destination == "party":
        trainer["party"].append(creature)
    else:
        dest_box = next(b for b in trainer["boxes"] if b["box_id"] == destination)
        empty_slot = next(i for i, s in enumerate(dest_box["slots"]) if s is None)
        dest_box["slots"][empty_slot] = creature

    return {"ok": True, "creature": creature, "moved_to": destination}


def wildkin_check_new_box(uid):
    """เช็คว่าเวลาผ่านไปครบ WILDKIN_BOX_UNLOCK_INTERVAL_SEC นับจากกล่องล่าสุดหรือยัง
    ถ้าครบ -> เพิ่มกล่องใหม่ให้อัตโนมัติ 1 ใบ (โผล่มาแบบเดียวกับกล่องรายวันเกมจับสัตว์ทั่วไป)"""
    trainer = _wildkin_trainer(uid)
    now = time.time()
    elapsed = now - trainer["last_box_unlock_at"]
    if elapsed >= WILDKIN_BOX_UNLOCK_INTERVAL_SEC:
        new_box = _wildkin_new_box(len(trainer["boxes"]) + 1)
        trainer["boxes"].append(new_box)
        trainer["last_box_unlock_at"] = now
        return {"ok": True, "new_box": new_box, "total_boxes": len(trainer["boxes"])}
    remaining = WILDKIN_BOX_UNLOCK_INTERVAL_SEC - elapsed
    return {"ok": True, "new_box": None, "seconds_until_next_box": round(remaining, 1),
            "total_boxes": len(trainer["boxes"])}


def _wildkin_supply_key(uid, district_id):
    return f"{uid}:{district_id}"


def _wildkin_roll_supply_drop():
    """สุ่มไอเทมที่ได้จากจุดจ่ายเสบียง 1 ชนิด ตามตารางความน่าจะเป็น WILDKIN_SUPPLY_DROP_TABLE"""
    roll = random.random()
    cumulative = 0.0
    for item_type, prob in WILDKIN_SUPPLY_DROP_TABLE.items():
        cumulative += prob
        if roll <= cumulative:
            return item_type
    return next(iter(WILDKIN_SUPPLY_DROP_TABLE))   # กันพลาดจากปัดเศษ float


def _wildkin_supply_status(uid, district_id):
    """เช็คสถานะจุดจ่ายเสบียงในย่านนี้สำหรับผู้เล่นคนนี้ — ทุกย่านใน TOKYO_DISTRICTS
    มีจุดจ่ายเสบียง 1 จุด (แยกคูลดาวน์ต่อผู้เล่นต่อย่าน เหมือนจุดจ่ายเสบียงบนแผนที่)"""
    if district_id not in TOKYO_DISTRICTS:
        return {"error": f"ย่าน '{district_id}' ไม่มีอยู่ในแผนที่", "known_districts": sorted(TOKYO_DISTRICTS.keys())}
    key = _wildkin_supply_key(uid, district_id)
    point = WILDKIN_SUPPLY_POINTS.get(key)
    now = time.time()
    if point is None or now >= point["next_available_at"]:
        available, seconds_remaining = True, 0.0
    else:
        available, seconds_remaining = False, round(point["next_available_at"] - now, 1)
    return {
        "district_id": district_id,
        "available": available,
        "seconds_until_available": seconds_remaining,
        "cooldown_sec": WILDKIN_SUPPLY_COOLDOWN_SEC,
        "last_collected_at": point["last_collected_at"] if point else None,
    }


def _wildkin_supply_collect(uid, district_id):
    """เก็บเสบียงจากจุดจ่ายเสบียงในย่านนี้ — ได้ลูกแก้วแบบสุ่มจำนวนสุ่มเข้ากระเป๋าทันที
    แล้วจุดนั้นจะเข้าคูลดาวน์ (WILDKIN_SUPPLY_COOLDOWN_SEC) ก่อนเก็บซ้ำได้อีกครั้ง"""
    status = _wildkin_supply_status(uid, district_id)
    if "error" in status:
        return status
    if not status["available"]:
        return {"error": "จุดจ่ายเสบียงจุดนี้ยังไม่พร้อมให้เก็บ รอสักครู่",
                "seconds_until_available": status["seconds_until_available"]}

    now = time.time()
    drops = {}
    for _ in range(random.randint(WILDKIN_SUPPLY_DROP_QTY_MIN, WILDKIN_SUPPLY_DROP_QTY_MAX)):
        item_type = _wildkin_roll_supply_drop()
        drops[item_type] = drops.get(item_type, 0) + 1

    trainer = _wildkin_trainer(uid)
    for item_type, qty in drops.items():
        trainer["inventory"][item_type] = trainer["inventory"].get(item_type, 0) + qty

    WILDKIN_SUPPLY_POINTS[_wildkin_supply_key(uid, district_id)] = {
        "last_collected_at": now,
        "next_available_at": now + WILDKIN_SUPPLY_COOLDOWN_SEC,
    }

    return {
        "ok": True,
        "district_id": district_id,
        "items_received": drops,
        "inventory": dict(trainer["inventory"]),
        "seconds_until_available": WILDKIN_SUPPLY_COOLDOWN_SEC,
    }


@app.route('/api/wildkin-capture/map', methods=['GET'])
def api_wildkin_map():
    """แผนที่จับสัตว์วิเศษ — ใช้ย่านเดียวกับ TOKYO_DISTRICTS ของโมดูล arcane-administration
    แต่ละย่านมีสัตว์วิเศษประจำถิ่นของตัวเอง (WILDKIN_SPAWN_POOL) และมีจุดจ่ายเสบียง 1 จุด
    (supply point) ที่ไปเก็บลูกแก้วแบบสุ่มได้ทุกๆ WILDKIN_SUPPLY_COOLDOWN_SEC วินาที"""
    return jsonify({
        "hq": TOKYO_DISTRICT_HQ,
        "districts": TOKYO_DISTRICTS,
        "spawn_pool_by_district": WILDKIN_SPAWN_POOL,
        "species": WILDKIN_SPECIES,
        "supply_points": sorted(TOKYO_DISTRICTS.keys()),
        "supply_drop_table": WILDKIN_SUPPLY_DROP_TABLE,
        "supply_cooldown_sec": WILDKIN_SUPPLY_COOLDOWN_SEC,
    })


@app.route('/api/wildkin-capture/spawn', methods=['GET'])
def api_wildkin_spawn():
    """?uid=&district_id= -> ดูว่าตอนนี้มีสัตว์วิเศษยืนรอให้จับอยู่ในย่านนั้นไหม"""
    uid = request.args.get("uid")
    district_id = request.args.get("district_id")
    if not uid or not district_id:
        return jsonify({"error": "ต้องส่ง uid และ district_id"}), 400
    spawn = _wildkin_get_or_make_spawn(uid, district_id)
    if "error" in spawn:
        return jsonify(spawn), 400
