def _vmax_role_for_session(sess):
    if not sess: return None
    if sess.get("uid") == "VMAX-OP-01": return "owner"
    rank_name = sess.get("rank_name", "")
    position = sess.get("position", "")
    return VMAX_POSITION_MENU_OVERRIDES.get(position, rank_name if rank_name in VMAX_ROLE_MENU_DEFINITIONS else None)

def _vmax_role_menu_for_session(sess):
    role = _vmax_role_for_session(sess)
    position = sess.get("position", "") if sess else ""
    if position in VMAX_POSITION_COMMANDS:
        base = VMAX_ROLE_MENU_DEFINITIONS.get(role, VMAX_ROLE_MENU_DEFINITIONS["support"])
        return {"role":role,"title":base["title"],"icon":base["icon"],"position":position,
                "commands":[dict(x) for x in VMAX_POSITION_COMMANDS[position]]}
    base = VMAX_ROLE_MENU_DEFINITIONS.get(role, {"title":"Team Workspace","icon":"👥","commands":[]})
    return {"role":role,"title":base["title"],"icon":base["icon"],"position":position,
            "commands":[dict(x) for x in base["commands"]]}

def _vmax_role_command_result(sess, command_id):
    if not sess: return {"st":"error","msg":"developer_session_invalid"}, 401
    menu = _vmax_role_menu_for_session(sess)
    allowed = {x["id"] for x in menu["commands"]}
    if command_id not in allowed:
        audit_log("staff_role_command_denied", uid=sess.get("uid"), command=command_id, role=menu.get("role"))
        return {"st":"error","msg":"คำสั่งนี้ไม่อยู่ในเมนูของตำแหน่ง/ยศนี้"}, 403
    uid, position = sess.get("uid"), sess.get("position", "")
    if command_id == "my_permissions":
        return {"st":"ok","command":command_id,"uid":uid,"rank":sess.get("rank_name"),"position":position,"allowed_commands":sorted(allowed)},200
    if command_id == "system_status":
        return {"st":"ok","command":command_id,"status":"online","modules":len(VMAX_MODULES) if isinstance(VMAX_MODULES,dict) else None,"staff_members":len(STAFF_MEMBERS)},200
    if command_id == "staff_directory":
        return {"st":"ok","command":command_id,"staff":[{"uid":k,**dict(v)} for k,v in STAFF_MEMBERS.items()]},200
    if command_id == "team_applications":
        if menu.get("role") != "owner": return {"st":"error","msg":"เฉพาะ owner เท่านั้น"},403
        items=[{"application_id":k,**dict(v)} for k,v in TEAM_APPLICATIONS.items()]
        items.sort(key=lambda x:x.get("created_at",0),reverse=True)
        return {"st":"ok","command":command_id,"applications":items},200
    if command_id == "admin_actions":
        rank=sess.get("rank",-1)
        return {"st":"ok","command":command_id,"actions":[{"id":k,"description":v[2]} for k,v in ADMIN_ACTIONS.items() if rank>=v[0]]},200
    if command_id == "module_registry":
        names=list(VMAX_MODULES.keys()) if isinstance(VMAX_MODULES,dict) else []
        return {"st":"ok","command":command_id,"count":len(names),"modules":names[:500]},200
    if command_id in {"game_modules","api_routes","ui_routes"}:
        routes=[]
        try:
            for rule in app.url_map.iter_rules():
                routes.append({"rule":str(rule),"methods":sorted(rule.methods-{"HEAD","OPTIONS"})})
        except Exception: pass
        if command_id=="game_modules":
            names=[k for k in (VMAX_MODULES.keys() if isinstance(VMAX_MODULES,dict) else []) if "game" in str(k).lower()]
            return {"st":"ok","command":command_id,"modules":names[:300]},200
        if command_id=="ui_routes": routes=[x for x in routes if not x["rule"].startswith("/api/")]
        return {"st":"ok","command":command_id,"routes":routes[:500]},200
    if command_id == "security_status":
        return {"st":"ok","command":command_id,"auth_gate":"enabled","developer_session":"enabled","challenge":"six-emoji","robot_checkbox":True},200
    if command_id == "test_status":
        tests=[k for k in globals() if str(k).startswith("_run_") and str(k).endswith("_selftests")]
        return {"st":"ok","command":command_id,"available_selftests":sorted(tests)[:300]},200
    if command_id == "moderation_scope":
        return {"st":"ok","command":command_id,"position":position,"scope":["review moderation queue","apply registered moderation actions"]},200
    if command_id == "support_scope":
        return {"st":"ok","command":command_id,"position":position,"scope":["support workflow","view permitted system status","escalate issues"]},200
    return {"st":"ok","command":command_id,"msg":"คำสั่งนี้พร้อมใช้งานตามสิทธิ์ของตำแหน่ง"},200

@app.route('/api/staff-role/menu', methods=['GET'])
def api_staff_role_menu():
    sess=_vmax_dev_current_session()
    if not sess: return jsonify({"st":"error","msg":"developer_session_invalid"}),401
    return jsonify({"st":"ok","menu":_vmax_role_menu_for_session(sess),"session":sess})

@app.route('/api/staff-role/command', methods=['POST'])
def api_staff_role_command():
    sess=_vmax_dev_current_session()
    body=request.get_json(silent=True) or {}
    result,code=_vmax_role_command_result(sess,str(body.get("command","")).strip())
    return jsonify(result),code

# Login เดิมใช้ gate เดียวกัน แต่หลังอนุมัติสามารถเข้า workspace ของยศ/ตำแหน่งได้ทั้งหมด
_ORIGINAL_VMAX_DEV_AUTHENTICATE = _vmax_dev_authenticate

def _vmax_dev_authenticate(username, password, pin, nonce, selected_index, robot_ok):
    _vmax_dev_cleanup_auth_state()
    username=str(username or "").strip()[:128]; password=str(password or ""); pin=str(pin or "")
    if not username or not password or not pin: return None,"กรุณากรอก Username, Password และ PIN ให้ครบ"
    if not robot_ok: return None,"กรุณายืนยันว่า ฉันไม่ใช่บอท"
    try: selected_index=int(selected_index)
    except (TypeError,ValueError): return None,"Image challenge ไม่ถูกต้อง"
    with _VMAX_DEV_LOCK: challenge=_VMAX_DEV_CHALLENGES.pop(str(nonce or ""),None)
    if not challenge or time.time()>=challenge.get("expires",0): return None,"Image challenge หมดอายุ — กดสร้างโจทย์ใหม่"
    if selected_index!=int(challenge["target_index"]):
        audit_log("staff_login_fail_challenge",uid=username); return None,"Image challenge ไม่ถูกต้อง"
    try: password_ok=bool(verify_password_for_uid(username,password))
    except Exception: password_ok=False
    if not password_ok: audit_log("staff_login_fail_password",uid=username); return None,"Username หรือ Password ไม่ถูกต้อง"
    if not _vmax_verify_owner_pin(pin): audit_log("staff_login_fail_pin",uid=username); return None,"PIN ไม่ถูกต้อง"
    if username=="VMAX-OP-01":
        rank,rank_name,position=STAFF_RANKS["owner"],"owner","Company Owner"
    else:
        member=STAFF_MEMBERS.get(username)
        if not member: audit_log("staff_login_denied_not_staff",uid=username); return None,"บัญชีนี้ยังไม่ได้รับอนุมัติเป็นทีมงาน"
        rank_name=str(member.get("rank","")); rank=STAFF_RANKS.get(rank_name,-1); position=str(member.get("position",""))
        if rank<0: return None,"ยศทีมงานไม่ถูกต้อง"
    token=_secrets.token_urlsafe(32)
    rec={"uid":username,"rank":rank,"rank_name":rank_name,"position":position,"created":time.time(),"expires":time.time()+_VMAX_DEV_LOGIN_TTL}
    rec["role_menu"]=_vmax_role_menu_for_session(rec)
    with _VMAX_DEV_LOCK: _VMAX_DEV_SESSIONS[token]=rec
    audit_log("staff_role_login_ok",uid=username,rank=rank_name,position=position)
    print("[VMAX STAFF] CONNECTED "+rank_name.upper()+" MENU — uid="+username+" position="+position)
    return token,None

# [SEC-AUDIT] จำกัดการลองรหัส dev/staff login: ผิดสะสม 8 ครั้ง/15 นาที ต่อ (IP + username) หรือ 30 ครั้งต่อ IP -> ล็อก 15 นาที
# (เดิมไม่มีเพดานเลย และ challenge ตอบเฉลยกลับมาใน response จึงไม่ได้กันบอท — ต้องพึ่งตัวจำกัดนี้แทน)
_VMAX_DEV_AUTH_INNER = _vmax_dev_authenticate


def _vmax_dev_authenticate(username, password, pin, nonce, selected_index, robot_ok):
    ip = request.remote_addr or "?"
    uname = str(username or "").strip().lower()[:128]
    k_user, k_ip = f"devlogin:{ip}:{uname}", f"devlogin-ip:{ip}"
    wait = max(_vs_rl_retry_after(k_user), _vs_rl_retry_after(k_ip))
    if wait:
        audit_log("developer_login_throttled", uid=uname, ip=ip)
        return None, f"ลองผิดหลายครั้งเกินไป กรุณารออีก {wait} วินาที"
    token, error = _VMAX_DEV_AUTH_INNER(username, password, pin, nonce, selected_index, robot_ok)
    if error:
        _vs_rl_fail(k_user, max_fails=8)
        _vs_rl_fail(k_ip, max_fails=30)
    else:
        _vs_rl_reset(k_user)
    return token, error


