def _vmax_game_access_cleanup():
    now=time.time()
    with _VMAX_GAME_ACCESS_LOCK:
        for token, rec in list(_VMAX_GAME_ACCESS_SESSIONS.items()):
            if now >= float(rec.get("expires",0)):
                _VMAX_GAME_ACCESS_SESSIONS.pop(token,None)


def _vmax_game_access_current_session():
    _vmax_game_access_cleanup()
    token=request.headers.get("X-VMAX-Game-Access-Token","").strip()
    if not token:
        return None
    with _VMAX_GAME_ACCESS_LOCK:
        rec=_VMAX_GAME_ACCESS_SESSIONS.get(token)
        if not rec:
            return None
        if time.time() >= float(rec.get("expires",0)):
            _VMAX_GAME_ACCESS_SESSIONS.pop(token,None)
            return None
        rec["last_seen"]=time.time()
        rec["expires"]=time.time()+_VMAX_GAME_ACCESS_TTL
        return dict(rec)


def _vmax_game_id_info(game_id):
    gid=str(game_id or "").strip()
    if not gid or len(gid)>120:
        return None
    catalog=globals().get("LAUNCHER_CATALOG",{})
    if not isinstance(catalog,dict) or gid not in catalog:
        return None
    g=catalog.get(gid) or {}
    return {
        "game_id": gid,
        "name": g.get("name",gid),
        "version": g.get("version"),
        "installed": bool(g.get("installed",False)),
        "genre": g.get("genre"),
        # optional metadata: ถ้าเกมภายนอกลงทะเบียนข้อมูลเหล่านี้ไว้ จะถูกแสดงในหน้า details
        "created_at": g.get("created_at", g.get("created", g.get("created_ts"))),
        "creator_uid": g.get("creator_uid", g.get("created_by_uid")),
        "creator_name": g.get("creator_name", g.get("created_by_name")),
        "creator_position": g.get("creator_position", g.get("created_by_position")),
        "build": g.get("build", g.get("build_number")),
        "engine": g.get("engine"),
        "platforms": g.get("platforms", g.get("supported_platforms", [])),
        "root_path": g.get("root_path", g.get("project_path", g.get("path"))),
        "package_path": g.get("package_path"),
        "size_mb": g.get("size_mb", 0),
        "file_count": g.get("file_count"),
        "energy_profile": g.get("energy_profile"),
    }


def _vmax_format_timestamp(value):
    """แปลง timestamp/ISO string เป็นเวลาท้องถิ่นแบบอ่านง่าย; ถ้าไม่มีข้อมูลคืน None."""
    if value in (None, "", 0):
        return None
    try:
        if isinstance(value, (int, float)):
            return datetime.fromtimestamp(float(value)).strftime("%Y-%m-%d %H:%M:%S")
        return str(value)
    except Exception:
        return str(value)


def _vmax_scan_game_files(game):
    """ถ้ามี root_path/package_path ที่ชี้ไปยังโฟลเดอร์/ไฟล์ที่มีอยู่จริง ให้คำนวณจำนวนไฟล์และขนาดจริง.
    ถ้าไม่มี path ที่ลงทะเบียนไว้ จะไม่เดาและใช้ size_mb/file_count จาก catalog แทน."""
    candidates=[]
    for key in ("root_path", "package_path"):
        value=game.get(key)
        if value:
            try:
                rp=os.path.realpath(os.path.abspath(str(value)))
                if os.path.exists(rp):
                    candidates.append(rp)
            except Exception:
                pass
    if not candidates:
        return None
    # เลือก path แรกที่มีอยู่จริง; ไม่รับ path ที่ชี้ออกไปผ่าน symlink หลัง realpath แล้ว
    target=candidates[0]
    count=0
    total=0
    try:
        if os.path.isfile(target):
            return {"file_count":1,"bytes":os.path.getsize(target),"scanned_path":target}
        for root, dirs, files in os.walk(target):
            # ไม่ลงโฟลเดอร์ VCS/cache ทั่วไป เพราะไม่ใช่ build content หลัก
            dirs[:] = [d for d in dirs if d not in {".git", ".svn", "__pycache__", ".pytest_cache"}]
            for fn in files:
                fp=os.path.join(root,fn)
                try:
                    total += os.path.getsize(fp)
                    count += 1
                except OSError:
                    continue
        return {"file_count":count,"bytes":total,"scanned_path":target}
    except Exception as exc:
        return {"scan_error":str(exc),"scanned_path":target}


def _vmax_energy_estimate(game):
    """โปรไฟล์พลังงานเป็น 'ประมาณการเชิงภาระงาน' ไม่ใช่ผลวัดแบตเตอรี่จริง.
    ถ้ามี energy_profile ที่เกมลงทะเบียนไว้ ให้ใช้ข้อมูลนั้นก่อน."""
    custom=game.get("energy_profile")
    if isinstance(custom, dict) and custom:
        return {"source":"registered_game_metadata","measured":bool(custom.get("measured",False)),"profiles":custom}
    try:
        size=float(game.get("size_mb") or 0)
    except Exception:
        size=0
    genre=str(game.get("genre") or "").lower()
    if any(k in genre for k in ("shooter","action","3d","open_world")) or size >= 8000:
        level="high"
    elif size >= 3000 or any(k in genre for k in ("rpg","fighting","simulation")):
        level="medium-high"
    elif size >= 1000:
        level="medium"
    else:
        level="light"
    return {
        "source":"estimated_from_catalog_size_and_genre",
        "measured":False,
        "note":"เป็นการประเมินภาระงาน ไม่ใช่ค่า Watt หรือ % แบตเตอรี่ที่วัดจริง",
        "load_level":level,
        "device_classes":{
            "entry_mobile":"อาจมีภาระสูงกว่าและควรใช้กราฟิกต่ำ",
            "mid_range_mobile":"เหมาะกับโปรไฟล์มาตรฐานของเกม",
            "performance_mobile":"มี headroom มากกว่า แต่การใช้พลังงานอาจเพิ่มตาม FPS/ความละเอียด",
        },
    }


def _vmax_game_version_details(game_id):
    game=_vmax_game_id_info(game_id)
    if not game:
        return None
    scan=_vmax_scan_game_files(game)
    file_count=game.get("file_count")
    size_mb=game.get("size_mb") or 0
    size_source="catalog"
    if scan and "bytes" in scan:
        file_count=scan.get("file_count",file_count)
        size_mb=round(float(scan.get("bytes",0))/1048576,2)
        size_source="filesystem_scan"
    creator_uid=game.get("creator_uid")
    creator_name=game.get("creator_name")
    creator_position=game.get("creator_position")
    if creator_uid:
        member=globals().get("STAFF_MEMBERS",{}).get(str(creator_uid))
        if isinstance(member,dict):
            creator_name=creator_name or member.get("name")
            creator_position=creator_position or member.get("position") or member.get("rank")
    return {
        "game_id":game["game_id"],
        "game_name":game.get("name"),
        "version":game.get("version") or "ยังไม่ได้ระบุ",
        "build":game.get("build") or "ยังไม่ได้ระบุ",
        "engine":game.get("engine") or "ยังไม่ได้ระบุ",
        "genre":game.get("genre") or "ยังไม่ได้ระบุ",
        "created_at":_vmax_format_timestamp(game.get("created_at")) or "ยังไม่มีข้อมูลวันสร้างใน catalog",
        "creator":{"uid":creator_uid or "ยังไม่มีข้อมูล","name":creator_name or "ยังไม่มีข้อมูล","position":creator_position or "ยังไม่มีข้อมูล"},
        "files":{"count":file_count if file_count is not None else "ยังไม่มีข้อมูล","size_mb":round(float(size_mb),2) if isinstance(size_mb,(int,float)) else size_mb,
                 "size_gb":round(float(size_mb)/1024,3) if isinstance(size_mb,(int,float)) else "ยังไม่มีข้อมูล","source":size_source},
        "installed":bool(game.get("installed",False)),
        "platforms":game.get("platforms") or ["ยังไม่ได้ระบุ"],
        "energy":_vmax_energy_estimate(game),
        "scan":scan or {"status":"ไม่มี path ของเกมที่ลงทะเบียนไว้ จึงไม่ได้สแกนไฟล์จริง"},
        "note":"ค่าที่ไม่มีอยู่ใน LAUNCHER_CATALOG จะแสดงเป็น 'ยังไม่มีข้อมูล' เพื่อไม่สร้างข้อมูลสมมติ",
    }


def _vmax_game_commands_for_session(sess):
    position=str(sess.get("position","") or "")
    commands=VMAX_GAME_POSITION_COMMANDS.get(position)
    if commands is None:
        rank_name=str(sess.get("rank_name","") or "")
        commands=VMAX_GAME_POSITION_COMMANDS.get(rank_name, VMAX_GAME_POSITION_COMMANDS["Community Support"])
    return [dict(x) for x in commands]


@app.route('/api/dev-game-login/games', methods=['GET'])
def api_dev_game_login_games():
    sess=_vmax_dev_current_session()
    if not sess:
        return jsonify({"st":"error","msg":"ต้องเข้าสู่ Developer Login ก่อน"}),401
    catalog=globals().get("LAUNCHER_CATALOG",{})
    games=[]
    if isinstance(catalog,dict):
        for gid,g in catalog.items():
            g=g or {}
            games.append({"game_id":str(gid),"name":g.get("name",gid),"version":g.get("version"),
                          "installed":bool(g.get("installed",False)),"genre":g.get("genre")})
    games.sort(key=lambda x:x["game_id"])
    return jsonify({"st":"ok","games":games})


@app.route('/dev-game-login', methods=['GET'])
def dev_game_login_page():
    return VMAX_GAME_LOGIN_HTML


@app.route('/api/dev-game-login', methods=['POST'])
def api_dev_game_login():
    sess=_vmax_dev_current_session()
    if not sess:
        return jsonify({"st":"error","msg":"Developer session หมดอายุหรือไม่ถูกต้อง — กรุณา Login ใหม่"}),401
    body=request.get_json(silent=True) or {}
    password=str(body.get("password", ""))
    game_id=str(body.get("game_id", "")).strip()
    if not password or not game_id:
        return jsonify({"st":"error","msg":"กรุณากรอก Password และ Game ID"}),400
    game=_vmax_game_id_info(game_id)
    if not game:
        return jsonify({"st":"error","msg":"ไม่พบ Game ID นี้ใน LAUNCHER_CATALOG — กรุณาตรวจสอบ Game ID"}),404
    try:
        ok=bool(verify_password_for_uid(sess.get("uid",""),password))
    except Exception:
        ok=False
    if not ok:
        audit_log("staff_game_login_fail_password",uid=sess.get("uid"),game_id=game_id)
        return jsonify({"st":"error","msg":"Password ไม่ถูกต้อง"}),403

    token=_secrets.token_urlsafe(32)
    rec={"uid":sess.get("uid"),"rank":sess.get("rank",-1),"rank_name":sess.get("rank_name"),
         "position":sess.get("position",""),"game_id":game_id,"game":game,
         "created":time.time(),"expires":time.time()+_VMAX_GAME_ACCESS_TTL}
    rec["commands"]=_vmax_game_commands_for_session(rec)
    with _VMAX_GAME_ACCESS_LOCK:
        _VMAX_GAME_ACCESS_SESSIONS[token]=rec
    audit_log("staff_game_access_granted",uid=rec["uid"],game_id=game_id,position=rec["position"])
    print("[VMAX STAFF] GAME CONNECTED — uid="+str(rec["uid"])+" position="+str(rec["position"])+" game_id="+game_id)
    return jsonify({"st":"ok","token":token,"session":rec,"msg":"CONNECTED GAME " + game_id})


