def api_dev_game_login_session():
    sess=_vmax_game_access_current_session()
    if not sess:
        return jsonify({"st":"error","msg":"game_access_session_invalid"}),401
    return jsonify({"st":"ok","session":sess})


@app.route('/api/dev-game-login/logout', methods=['POST'])
def api_dev_game_login_logout():
    token=request.headers.get("X-VMAX-Game-Access-Token","").strip()
    with _VMAX_GAME_ACCESS_LOCK:
        _VMAX_GAME_ACCESS_SESSIONS.pop(token,None)
    return jsonify({"st":"ok"})


def _vmax_game_command_result(sess, command_id):
    if not sess:
        return {"st":"error","msg":"game_access_session_invalid"},401
    allowed={x["id"] for x in sess.get("commands",[])}
    if command_id not in allowed:
        audit_log("staff_game_command_denied",uid=sess.get("uid"),game_id=sess.get("game_id"),command=command_id)
        return {"st":"error","msg":"คำสั่งนี้ไม่อยู่ในเมนูของตำแหน่งงานนี้"},403
    gid=sess.get("game_id","")
    game=_vmax_game_id_info(gid)
    if not game:
        return {"st":"error","msg":"Game ID ไม่พร้อมใช้งานแล้ว"},404
    if command_id=="game_version_details":
        details=_vmax_game_version_details(gid)
        if not details:
            return {"st":"error","msg":"ไม่พบข้อมูลเกม"},404
        audit_log("staff_game_version_details_view",uid=sess.get("uid"),game_id=gid,position=sess.get("position"))
        return {"st":"ok","command":command_id,"details":details,"staff_uid":sess.get("uid"),"position":sess.get("position")},200
    if command_id=="game_system_status":
        return {"st":"ok","command":command_id,"game":game,"status":"online",
                "staff_uid":sess.get("uid"),"position":sess.get("position")},200
    if command_id=="game_api_status":
        return {"st":"ok","command":command_id,"game_id":gid,"api_status":"available",
                "registered_routes":len(list(app.url_map.iter_rules()))},200
    if command_id=="game_module_registry":
        mods=list(VMAX_MODULES.keys()) if isinstance(globals().get("VMAX_MODULES"),dict) else []
        return {"st":"ok","command":command_id,"game_id":gid,"modules":mods[:500]},200
    if command_id=="game_modules":
        mods=list(VMAX_MODULES.keys()) if isinstance(globals().get("VMAX_MODULES"),dict) else []
        names=[m for m in mods if gid.lower() in str(m).lower() or "game" in str(m).lower()]
        return {"st":"ok","command":command_id,"game_id":gid,"modules":names[:300]},200
    if command_id=="game_ui_routes":
        routes=[]
        try:
            for rule in app.url_map.iter_rules():
                routes.append({"rule":str(rule),"methods":sorted(rule.methods-{"HEAD","OPTIONS"})})
        except Exception: pass
        routes=[r for r in routes if not r["rule"].startswith("/api/")]
        return {"st":"ok","command":command_id,"game_id":gid,"routes":routes[:500]},200
    if command_id=="game_security_status":
        return {"st":"ok","command":command_id,"game_id":gid,"developer_session":"enabled",
                "game_access_password_gate":"enabled","game_id_gate":"enabled"},200
    if command_id=="game_runtime_info":
        return {"st":"ok","command":command_id,"game":game,"runtime":"VMAX game workspace"},200
    if command_id=="game_test_status":
        tests=sorted(k for k in globals() if str(k).startswith("_run_") and str(k).endswith("_selftests"))
        return {"st":"ok","command":command_id,"game_id":gid,"available_selftests":tests[:300]},200
    if command_id=="game_moderation_scope":
        return {"st":"ok","command":command_id,"game_id":gid,"scope":["review moderation queue","apply registered moderation actions"]},200
    if command_id=="game_support_scope":
        return {"st":"ok","command":command_id,"game_id":gid,"scope":["support workflow","view permitted game status","escalate issues"]},200
    if command_id=="game_access_overview":
        return {"st":"ok","command":command_id,"game":game,"staff_uid":sess.get("uid"),
                "position":sess.get("position"),"access_expires":sess.get("expires")},200
    return {"st":"ok","command":command_id,"game_id":gid,"msg":"คำสั่งพร้อมใช้งาน"},200


