VMAX_GAME_LOGIN_HTML=r"""<!doctype html>
<html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>VMAX Game Developer Access</title><style>
*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#090c11;color:#eef2f7;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;display:flex;align-items:center;justify-content:center;padding:18px}.card{width:min(650px,100%);background:#121720;border:1px solid #303846;border-radius:18px;padding:24px}.muted{color:#9ca8b8;font-size:13px;line-height:1.6}.field{margin:14px 0}.field label{display:block;color:#b9c3d0;font-size:12px;margin-bottom:6px}input,select{width:100%;padding:13px;border-radius:10px;border:1px solid #394353;background:#0c1016;color:#fff;outline:none}button{padding:13px 16px;border:0;border-radius:11px;background:#79a7ff;color:#07101e;font-weight:800;cursor:pointer;width:100%}.secondary{margin-top:10px;background:#1b222d;color:#fff;border:1px solid #394353}.status{margin:12px 0;min-height:24px}.ok{color:#68e0a3}.err{color:#ff8d8d}.box{margin-top:14px;padding:14px;border:1px solid #303846;border-radius:12px;background:#0d1117}.link{color:#8fb3ff;text-decoration:none}
</style></head><body><div class="card"><h1>🎮 Game Developer Access</h1><div class="muted">หลังจากผ่าน Developer Login แล้ว ให้เลือก Game ID ที่ต้องการเข้า และยืนยัน Password ของบัญชีทีมงานอีกครั้ง ก่อนเปิดโหมดพัฒนาของเกมนั้น</div><div class="field"><label>Game ID</label><select id="game"></select></div><div id="gameInfo" class="muted"></div><div class="field"><label>Password ของบัญชีทีมงาน</label><input id="password" type="password" autocomplete="current-password" placeholder="กรอก Password เดิมของบัญชีทีมงาน"></div><div id="status" class="status"></div><button id="connect">🔐 Connect Game Developer Mode</button><button id="back" class="secondary">กลับ Developer Menu</button><div id="result" class="box" style="display:none"></div></div>
<script>
const devToken=localStorage.getItem('vmax_dev_token');
const $=id=>document.getElementById(id);
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
async function loadGames(){if(!devToken){location.href='/dev-login';return;}const r=await fetch('/api/dev-game-login/games',{headers:{'X-VMAX-Developer-Token':devToken}});const j=await r.json();if(j.st!=='ok'){location.href='/dev-login';return;}$('game').innerHTML='';(j.games||[]).forEach(g=>{const o=document.createElement('option');o.value=g.game_id;o.textContent=g.game_id+' — '+(g.name||g.game_id);o.dataset.info=JSON.stringify(g);$('game').appendChild(o);});updateInfo();if(!j.games?.length)$('status').innerHTML='<span class="err">❌ ยังไม่มี Game ID ใน LAUNCHER_CATALOG</span>';}
function updateInfo(){const o=$('game').selectedOptions[0];if(!o){$('gameInfo').textContent='';return;}try{const g=JSON.parse(o.dataset.info);$('gameInfo').textContent='เกม: '+(g.name||g.game_id)+' | Version: '+(g.version||'-')+' | Installed: '+(g.installed?'yes':'no');}catch(e){}}
$('game').addEventListener('change',updateInfo);
$('connect').addEventListener('click',async()=>{const st=$('status');$('connect').disabled=true;st.className='status';st.textContent='⏳ กำลังยืนยัน…';try{const r=await fetch('/api/dev-game-login',{method:'POST',headers:{'Content-Type':'application/json','X-VMAX-Developer-Token':devToken},body:JSON.stringify({game_id:$('game').value,password:$('password').value})});const j=await r.json();if(j.st!=='ok'){st.className='status err';st.textContent='❌ '+(j.msg||'เชื่อมต่อไม่สำเร็จ');return;}localStorage.setItem('vmax_game_access_token',j.token);st.className='status ok';st.textContent='✅ '+j.msg;setTimeout(()=>location.href='/dev-game-menu',250);}catch(e){st.className='status err';st.textContent='❌ '+e.message;}finally{$('connect').disabled=false;}});
$('back').addEventListener('click',()=>location.href='/role-menu');loadGames();
</script></body></html>"""


