    b=request.get_json(force=True,silent=True) or {};vid=vex_create_vehicle(str(b.get("type","scout_car")),float(b.get("x",0)),float(b.get("y",0)),b.get("loot") or []);return jsonify({"st":"ok","vehicle":vex_vehicle_state(vid)})
