# ============================================================================
# VMAX EXTENSION: WORLD TRANSACTION / CHUNK / NODE / COMBAT INTEGRATION
# ============================================================================
# Added as one-file, application-level simulation. Optional etcd/ZeroMQ support
# is loaded lazily so the main VMAX application can still start without them.
import math as _vext_math
import random as _vext_random
import time as _vext_time
import json as _vext_json
import threading as _vext_threading


class VMAXCouchbaseLandDeed:
    def __init__(self):
        self.store = {}

    def get_chunk(self, chunk_id):
        if chunk_id not in self.store:
            self.store[chunk_id] = {"tiles": {}, "cas": 1}
        return self.store[chunk_id]

    def update_cas(self, chunk_id, new_tiles, expected_cas):
        doc = self.get_chunk(chunk_id)
        if doc["cas"] != expected_cas:
            return False, doc["cas"]
        doc["tiles"] = dict(new_tiles)
        doc["cas"] += 1
        return True, doc["cas"]


class VMAXBaseTransactionEngine:
    def __init__(self, db):
        self.db = db

    def place_multi_chunk_object(self, object_name, placement_plan):
        executed_steps = []
        for chunk_id, tiles in placement_plan.items():
            doc = self.db.get_chunk(chunk_id)
            current_tiles = doc["tiles"].copy()
            cas_ver = doc["cas"]
            for tile in tiles:
                if tile in current_tiles:
                    self._rollback_inverse(executed_steps)
                    return False
                current_tiles[tile] = object_name
            success, _ = self.db.update_cas(chunk_id, current_tiles, cas_ver)
            if not success:
                self._rollback_inverse(executed_steps)
                return False
            executed_steps.append({"chunk_id": chunk_id, "added_tiles": list(tiles)})
        return True

    def _rollback_inverse(self, executed_steps):
        for step in reversed(executed_steps):
            doc = self.db.get_chunk(step["chunk_id"])
            current = doc["tiles"].copy()
            for tile in step["added_tiles"]:
                current.pop(tile, None)
            self.db.update_cas(step["chunk_id"], current, doc["cas"])


class VMAXMockNoSQLDatabase:
    def __init__(self):
        self.store = {}

    def get_document(self, doc_id):
        return self.store.setdefault(
            doc_id, {"data": [], "cas_version": 1}
        )

    def save_document(self, doc_id, new_data, current_cas):
        doc = self.get_document(doc_id)
        if doc["cas_version"] != current_cas:
            return False, doc["cas_version"]
        new_cas = current_cas + 1
        self.store[doc_id] = {"data": list(new_data), "cas_version": new_cas}
        return True, new_cas


class VMAXTransactionManager:
    def __init__(self, db, max_retries=5):
        self.db = db
        self.max_retries = max_retries

    def place_static_object(self, obj_data, target_chunk_id, tx_doc_id):
        for _ in range(self.max_retries):
            doc = self.db.get_document(tx_doc_id)
            plan = list(doc["data"])
            cas = doc["cas_version"]
            plan.append({"action": "install", "chunk": target_chunk_id,
                         "object": obj_data})
            ok, _ = self.db.save_document(tx_doc_id, plan, cas)
            if ok:
                return True
        return False


class VMAXDistributedChunk:
    def __init__(self, chunk_id, ttl=0.5):
        self.chunk_id = chunk_id
        self.ttl = ttl
        self.locked = False
        self.lock_expire_time = 0.0

    def acquire_lock(self):
        now = _vext_time.time()
        if self.locked and now < self.lock_expire_time:
            return False
        self.locked = True
        self.lock_expire_time = now + self.ttl
        return True

    def release_lock(self):
        self.locked = False
        self.lock_expire_time = 0.0


class VMAXAnimalAI:
    def __init__(self, animal_id, pos):
        self.animal_id = animal_id
        self.pos = tuple(pos)

    def compute_behavior(self, player_pos):
        distance = _vext_math.dist(self.pos, tuple(player_pos))
        if distance > 1000:
            return "SLEEP_MODE"
        if distance > 300:
            return "LOW_LOD"
        return "HIGH_LOD"


class VMAXServerNode:
    def __init__(self, node_id):
        self.node_id = f"Node_{node_id}"
        self.managed_players = {}
        self.proxy_objects = {}

    def update_vision_overlap(self, other_node, vision_radius=500):
        for pid, pos in other_node.managed_players.items():
            visible = any(
                _vext_math.dist(my_pos, pos) <= vision_radius * 2
                for my_pos in self.managed_players.values()
            )
            if visible:
                self.proxy_objects[pid] = {"pos": pos, "is_proxy": True}
            else:
                self.proxy_objects.pop(pid, None)


class VMAXGameNode:
    """Optional etcd + ZeroMQ node; dependencies are required only when used."""
    def __init__(self, node_type, node_id, port, etcd_host="localhost",
                 etcd_port=2379):
        try:
            import zmq
            import etcd3
        except ImportError as exc:
            raise RuntimeError(
                "VMAXGameNode requires pyzmq and etcd3"
            ) from exc
        self._zmq = zmq
        self._etcd = etcd3.client(host=etcd_host, port=etcd_port)
        self.node_type = str(node_type)
        self.node_id = f"{node_type}_{node_id}"
        self.address = f"tcp://127.0.0.1:{int(port)}"
        self.context = zmq.Context()

    def register_to_etcd(self, ttl=10):
        key = f"/game_nodes/{self.node_type}/{self.node_id}"
        lease = self._etcd.lease(ttl)
        self._etcd.put(key, _vext_json.dumps({
            "address": self.address, "status": "active"
        }), lease=lease)
        return key

    def start_colosseum_worker(self):
        socket = self.context.socket(self._zmq.REP)
        socket.bind(self.address)
        while True:
            msg = socket.recv_json()
            socket.send_json({
                "status": "success", "damage": 500, "target_hp": 0,
                "player_id": msg.get("player_id"),
                "target_id": msg.get("target_id")
            })


def vmax_run_world_network_selftest():
    db = VMAXCouchbaseLandDeed()
    tx = VMAXBaseTransactionEngine(db)
    db.store[2] = {"tiles": {(0, 0): "Big_Stone"}, "cas": 1}
    assert tx.place_multi_chunk_object(
        "Dragon_Statue", {1: [(15, 15)], 2: [(0, 0)]}
    ) is False
    assert db.get_chunk(1)["tiles"] == {}

    nosql = VMAXMockNoSQLDatabase()
    tm = VMAXTransactionManager(nosql)
    assert tm.place_static_object("Campfire", 4, "TX_REGION_1")
    lock = VMAXDistributedChunk(45)
    assert lock.acquire_lock() is True
    assert lock.acquire_lock() is False
    assert VMAXAnimalAI("T-Rex", (0, 0)).compute_behavior((2000, 2000)) == "SLEEP_MODE"

    a, b = VMAXServerNode("A"), VMAXServerNode("B")
    a.managed_players["neko"] = (0, 0)
    b.managed_players["p2"] = (10, 10)
    a.update_vision_overlap(b)
    assert "p2" in a.proxy_objects
    return True

# ============================================================================
# VMAX TX MAP DOCUMENT EXTENSION
# เก็บแผนที่/การเปลี่ยนแปลงของโลกไว้ในเอกสาร Transaction (Tx)
# ============================================================================

from dataclasses import dataclass as _vmax_dataclass, field as _vmax_field
from copy import deepcopy as _vmax_deepcopy
from time import time as _vmax_time


@_vmax_dataclass
class VMAXTxMapDocument:
    """เอกสาร Tx สำหรับบันทึกการเปลี่ยนแปลง map/chunk แบบ atomic."""

    tx_id: str
    operation: str
    status: str = "PREPARED"
    map_before: dict = _vmax_field(default_factory=dict)
    map_after: dict = _vmax_field(default_factory=dict)
    affected_chunks: list = _vmax_field(default_factory=list)
    changes: list = _vmax_field(default_factory=list)
    inverse_changes: list = _vmax_field(default_factory=list)
    created_at: float = _vmax_field(default_factory=_vmax_time)
    committed_at: float | None = None
    rolled_back_at: float | None = None
    error: str | None = None

    def to_document(self) -> dict:
        return {
            "tx_id": self.tx_id,
            "operation": self.operation,
            "status": self.status,
            "map_before": _vmax_deepcopy(self.map_before),
            "map_after": _vmax_deepcopy(self.map_after),
            "affected_chunks": list(self.affected_chunks),
            "changes": _vmax_deepcopy(self.changes),
            "inverse_changes": _vmax_deepcopy(self.inverse_changes),
            "created_at": self.created_at,
            "committed_at": self.committed_at,
            "rolled_back_at": self.rolled_back_at,
            "error": self.error,
        }


class VMAXTxMapStore:
    """ตัวเก็บเอกสาร Tx แบบ in-memory; เปลี่ยนเป็น Couchbase/NoSQL ได้ภายหลัง."""

    def __init__(self):
        self.documents = {}

    def create(self, tx_id: str, operation: str, map_before=None, affected_chunks=None):
        if tx_id in self.documents:
            raise ValueError(f"duplicate tx_id: {tx_id}")
        doc = VMAXTxMapDocument(
            tx_id=tx_id,
            operation=operation,
            map_before=_vmax_deepcopy(map_before or {}),
            affected_chunks=list(affected_chunks or []),
        )
        self.documents[tx_id] = doc
        return doc

    def get(self, tx_id: str):
        return self.documents.get(tx_id)

    def commit(self, tx_id: str, map_after: dict, changes=None):
        doc = self.documents[tx_id]
        doc.map_after = _vmax_deepcopy(map_after)
        doc.changes = _vmax_deepcopy(changes or [])
        doc.status = "COMMITTED"
        doc.committed_at = _vmax_time()
        return doc

    def rollback(self, tx_id: str, error: str | None = None):
        doc = self.documents[tx_id]
        doc.status = "ROLLED_BACK"
        doc.error = error
        doc.rolled_back_at = _vmax_time()
        return doc


class VMAXMapTransactionCoordinator:
    """ประสานการแก้ map กับ Tx document: prepare -> commit หรือ rollback."""

    def __init__(self, tx_store=None):
        self.tx_store = tx_store or VMAXTxMapStore()

    def apply_map_change(self, tx_id: str, operation: str, world_map: dict,
                         changes: list, affected_chunks=None):
        before = _vmax_deepcopy(world_map)
        doc = self.tx_store.create(
            tx_id=tx_id,
            operation=operation,
            map_before=before,
            affected_chunks=affected_chunks,
        )
        try:
            for change in changes:
                chunk_id = change["chunk_id"]
                key = change["key"]
                value = change.get("value")
                chunk = world_map.setdefault(chunk_id, {})
                if value is None:
                    chunk.pop(key, None)
                else:
                    chunk[key] = value

            return self.tx_store.commit(
                tx_id,
                map_after=world_map,
                changes=changes,
            )
        except Exception as exc:
            world_map.clear()
            world_map.update(_vmax_deepcopy(before))
            self.tx_store.rollback(tx_id, error=str(exc))
            raise

    def rollback_tx(self, tx_id: str, world_map: dict):
        doc = self.tx_store.get(tx_id)
        if doc is None:
            raise KeyError(f"unknown tx_id: {tx_id}")
        world_map.clear()
        world_map.update(_vmax_deepcopy(doc.map_before))
        return self.tx_store.rollback(tx_id)


# Self-test for the Tx map document flow.
def vmax_run_tx_map_document_selftest():
    world_map = {1: {"tree": "oak"}, 2: {"rock": "granite"}}
    coordinator = VMAXMapTransactionCoordinator()
    doc = coordinator.apply_map_change(
        tx_id="TX_MAP_001",
        operation="place_static_object",
        world_map=world_map,
        affected_chunks=[1, 2],
        changes=[
            {"chunk_id": 1, "key": "campfire", "value": "Campfire"},
            {"chunk_id": 2, "key": "rock", "value": "Big_Rock"},
        ],
    )
    assert doc.status == "COMMITTED"
    assert world_map[1]["campfire"] == "Campfire"
    assert world_map[2]["rock"] == "Big_Rock"

    coordinator.rollback_tx("TX_MAP_001", world_map)
    assert world_map == {1: {"tree": "oak"}, 2: {"rock": "granite"}}
    assert coordinator.tx_store.get("TX_MAP_001").status == "ROLLED_BACK"
    return True


# ============================================================================
# VMAX REAL-TIME COMBAT / RTP EXTENSION
# ============================================================================
# ระบบนี้แยกจาก Map Tx:
# - การต่อสู้/กลิ้งหลบ/โจมตี = transient real-time combat event
# - การเปลี่ยนแปลงโลกถาวร = ใช้ VMAXMapTransactionCoordinator เดิม
# - Access/permission = ให้ Engine เดิมของเกมตรวจสอบก่อนเรียก combat API

from dataclasses import dataclass, field
from typing import Any, Callable, Optional
import math
import random
import time as _vmax_combat_time


@dataclass
class VMAXCombatEntity:
    entity_id: str
    entity_type: str
    x: float = 0.0
    y: float = 0.0
    z: float = 0.0
    hp: float = 100.0
    max_hp: float = 100.0
    stamina: float = 100.0
    alive: bool = True
    state: str = "IDLE"
    last_action_at: float = 0.0
    metadata: dict = field(default_factory=dict)

    def distance_to(self, other: "VMAXCombatEntity") -> float:
        return math.sqrt(
            (self.x - other.x) ** 2
            + (self.y - other.y) ** 2
            + (self.z - other.z) ** 2
        )

    def apply_damage(self, amount: float) -> float:
        if not self.alive:
            return 0.0
        damage = max(0.0, float(amount))
        self.hp = max(0.0, self.hp - damage)
        if self.hp <= 0:
            self.alive = False
            self.state = "DEAD"
        return damage


@dataclass
class VMAXCombatEvent:
    event_id: str
    event_type: str
    attacker_id: Optional[str] = None
    target_id: Optional[str] = None
    timestamp: float = field(default_factory=_vmax_combat_time.time)
    accepted: bool = False
    hit: bool = False
    damage: float = 0.0
    reason: Optional[str] = None
    payload: dict = field(default_factory=dict)


class VMAXRealtimeCombatEngine:
    """
    Combat event engine สำหรับการต่อสู้แบบ real-time

    รองรับ:
    - punch / melee attack
    - roll / dodge
    - cooldown
    - stamina
    - hit range
    - event callback สำหรับ RTP/network layer
    - server-authoritative damage
    """

    def __init__(
        self,
        access_checker: Optional[Callable[[str, str], bool]] = None,
        event_sink: Optional[Callable[[VMAXCombatEvent], None]] = None,
        attack_range: float = 2.5,
        attack_cooldown: float = 0.35,
        roll_cost: float = 20.0,
        roll_duration: float = 0.45,
    ):
        self.entities: dict[str, VMAXCombatEntity] = {}
        self.access_checker = access_checker or (lambda _entity_id, _action: True)
        self.event_sink = event_sink
        self.attack_range = attack_range
        self.attack_cooldown = attack_cooldown
        self.roll_cost = roll_cost
        self.roll_duration = roll_duration
        self._sequence = 0
        self.active_rolls: dict[str, float] = {}

    def register_entity(self, entity: VMAXCombatEntity):
        self.entities[entity.entity_id] = entity
        return entity

    def get_entity(self, entity_id: str) -> Optional[VMAXCombatEntity]:
        return self.entities.get(entity_id)

    def _new_event(self, event_type: str, **kwargs) -> VMAXCombatEvent:
        self._sequence += 1
        return VMAXCombatEvent(
            event_id=f"COMBAT_{self._sequence:08d}",
            event_type=event_type,
            **kwargs,
        )

    def _emit(self, event: VMAXCombatEvent) -> VMAXCombatEvent:
        if self.event_sink:
            self.event_sink(event)
        return event

    def _reject(
        self,
        event_type: str,
        reason: str,
        attacker_id: Optional[str] = None,
        target_id: Optional[str] = None,
    ):
        return self._emit(
            self._new_event(
                event_type,
                attacker_id=attacker_id,
                target_id=target_id,
                accepted=False,
                reason=reason,
            )
        )

    def process_punch(
        self,
        attacker_id: str,
        target_id: str,
        damage: float = 10.0,
        attack_range: Optional[float] = None,
        now: Optional[float] = None,
    ) -> VMAXCombatEvent:
        now = _vmax_combat_time.time() if now is None else now
        attacker = self.get_entity(attacker_id)
        target = self.get_entity(target_id)

        if attacker is None or target is None:
            return self._reject("PUNCH", "ENTITY_NOT_FOUND", attacker_id, target_id)
        if not attacker.alive:
            return self._reject("PUNCH", "ATTACKER_DEAD", attacker_id, target_id)
        if not target.alive:
            return self._reject("PUNCH", "TARGET_DEAD", attacker_id, target_id)
        if not self.access_checker(attacker_id, "attack"):
            return self._reject("PUNCH", "ACCESS_DENIED", attacker_id, target_id)
        if now - attacker.last_action_at < self.attack_cooldown:
            return self._reject("PUNCH", "COOLDOWN", attacker_id, target_id)
        if attacker_id in self.active_rolls and self.active_rolls[attacker_id] > now:
            return self._reject("PUNCH", "ROLLING", attacker_id, target_id)

        limit = self.attack_range if attack_range is None else attack_range
        distance = attacker.distance_to(target)
        attacker.last_action_at = now

        event = self._new_event(
            "PUNCH",
            attacker_id=attacker_id,
            target_id=target_id,
            accepted=True,
            payload={"distance": distance, "range": limit},
        )

        if distance > limit:
            event.reason = "OUT_OF_RANGE"
            return self._emit(event)

        # ถ้าเป้าหมายกำลังกลิ้งหลบอยู่ ให้โจมตีพลาด
        if target_id in self.active_rolls and self.active_rolls[target_id] > now:
            event.reason = "TARGET_DODGED"
            return self._emit(event)

        event.hit = True
        event.damage = target.apply_damage(damage)
        event.payload["target_hp"] = target.hp
        event.payload["target_alive"] = target.alive
        return self._emit(event)

    def process_roll(
        self,
        entity_id: str,
        direction: Optional[dict] = None,
        now: Optional[float] = None,
    ) -> VMAXCombatEvent:
        now = _vmax_combat_time.time() if now is None else now
        entity = self.get_entity(entity_id)

        if entity is None:
            return self._reject("ROLL", "ENTITY_NOT_FOUND", entity_id)
        if not entity.alive:
            return self._reject("ROLL", "ENTITY_DEAD", entity_id)
        if not self.access_checker(entity_id, "roll"):
            return self._reject("ROLL", "ACCESS_DENIED", entity_id)
        if entity.stamina < self.roll_cost:
            return self._reject("ROLL", "NOT_ENOUGH_STAMINA", entity_id)
        if entity_id in self.active_rolls and self.active_rolls[entity_id] > now:
            return self._reject("ROLL", "ALREADY_ROLLING", entity_id)

        entity.stamina -= self.roll_cost
        entity.state = "ROLLING"
        self.active_rolls[entity_id] = now + self.roll_duration

        event = self._new_event(
            "ROLL",
            attacker_id=entity_id,
            accepted=True,
            payload={
                "direction": direction or {"x": 0.0, "y": 0.0, "z": 0.0},
                "expires_at": self.active_rolls[entity_id],
                "stamina": entity.stamina,
            },
        )
        return self._emit(event)

    def tick(self, now: Optional[float] = None):
        now = _vmax_combat_time.time() if now is None else now
        finished = []
        for entity_id, expires_at in list(self.active_rolls.items()):
            if expires_at <= now:
                finished.append(entity_id)
                entity = self.get_entity(entity_id)
                if entity:
                    entity.state = "IDLE" if entity.alive else "DEAD"
        for entity_id in finished:
            self.active_rolls.pop(entity_id, None)
        return finished


class VMAXCombatRTPBridge:
    """
    ชั้นเชื่อม RTP/network:
    รับ packet จาก client แล้วส่งผลลัพธ์ที่ server เป็นผู้ตัดสินกลับไป
    ไม่ให้ client เป็นคนกำหนด damage หรือผล hit เอง
    """

    def __init__(self, combat_engine: VMAXRealtimeCombatEngine):
        self.combat_engine = combat_engine

    def handle_packet(self, packet: dict) -> VMAXCombatEvent:
        packet_type = str(packet.get("type", "")).upper()
        attacker_id = packet.get("attacker_id") or packet.get("entity_id")

        if packet_type in {"PUNCH", "MELEE_ATTACK", "ATTACK"}:
            return self.combat_engine.process_punch(
                attacker_id=attacker_id,
                target_id=packet.get("target_id"),
                damage=float(packet.get("requested_damage", 10.0)),
            )

        if packet_type in {"ROLL", "DODGE"}:
            return self.combat_engine.process_roll(
                entity_id=attacker_id,
                direction=packet.get("direction"),
            )

        return self.combat_engine._reject(
            packet_type or "UNKNOWN",
            "UNKNOWN_COMBAT_PACKET",
            attacker_id=attacker_id,
        )


def vmax_run_realtime_combat_selftest():
    events = []
    engine = VMAXRealtimeCombatEngine(event_sink=events.append)
    player = engine.register_entity(
        VMAXCombatEntity("player_001", "PLAYER", x=0, y=0, z=0)
    )
    dinosaur = engine.register_entity(
        VMAXCombatEntity("dinosaur_001", "DINOSAUR", x=1, y=0, z=0, hp=50, max_hp=50)
    )
    bridge = VMAXCombatRTPBridge(engine)

    hit = bridge.handle_packet({
        "type": "PUNCH",
        "attacker_id": "player_001",
        "target_id": "dinosaur_001",
        "requested_damage": 15,
    })
    assert hit.accepted and hit.hit
    assert dinosaur.hp == 35

    roll = bridge.handle_packet({
        "type": "ROLL",
        "entity_id": "player_001",
        "direction": {"x": 1, "y": 0, "z": 0},
    })
    assert roll.accepted

    dodged = engine.process_punch("dinosaur_001", "player_001", damage=100)
    assert dodged.reason == "TARGET_DODGED"

    engine.tick(now=roll.timestamp + engine.roll_duration + 1.0)
    assert player.state == "IDLE"
    return True

# ============================================================================
# VMAX ENGINE INTEGRATION LAYER
# ============================================================================
# เชื่อมระบบ Combat/Map Tx เข้ากับ Game Engine ผ่าน callback adapter
# เนื่องจาก API ของ Engine จริงไม่ได้ถูกระบุไว้ จึงไม่เดา API เฉพาะของ Engine
# แต่เตรียมจุดเชื่อมมาตรฐานให้ Engine เรียกใช้งานได้ทันที

from dataclasses import dataclass as _vmax_dataclass
from typing import Any as _VMAXAny, Callable as _VMAXCallable, Optional as _VMAXOptional


@_vmax_dataclass
class VMAXEngineBindings:
    """ชุด callback ที่ Game Engine จริงต้องผูกเข้ามา"""
    get_entity: _VMAXOptional[_VMAXCallable] = None
    set_entity_hp: _VMAXOptional[_VMAXCallable] = None
    play_animation: _VMAXOptional[_VMAXCallable] = None
    move_entity: _VMAXOptional[_VMAXCallable] = None
    emit_event: _VMAXOptional[_VMAXCallable] = None
    can_access: _VMAXOptional[_VMAXCallable] = None
    get_time: _VMAXOptional[_VMAXCallable] = None


class VMAXGameEngineAdapter:
    """Adapter กลางระหว่าง VMAX Python systems กับ Engine จริง"""

    def __init__(self, bindings: VMAXEngineBindings | None = None):
        self.bindings = bindings or VMAXEngineBindings()
        self.combat_events = []
        self.map_events = []

    def _allowed(self, actor_id: str, action: str) -> bool:
        checker = self.bindings.can_access
        return True if checker is None else bool(checker(actor_id, action))

    def register_entity_from_engine(self, combat_engine, entity: VMAXCombatEntity):
        """ลงทะเบียน Entity จาก Engine เข้า Combat Engine"""
        if self.bindings.get_entity is not None:
            engine_entity = self.bindings.get_entity(entity.entity_id)
            if engine_entity is None:
                raise ValueError(f"Engine entity not found: {entity.entity_id}")
        return combat_engine.register_entity(entity)

    def handle_rtp_packet(self, bridge: VMAXCombatRTPBridge, packet: dict):
        """รับ packet จากระบบ RTP/Network แล้วส่งเข้า Combat Engine"""
        actor_id = packet.get("attacker_id") or packet.get("entity_id")
        action = str(packet.get("type", "UNKNOWN")).upper()
        if actor_id and not self._allowed(actor_id, action):
            return bridge.combat_engine._reject(
                action, "ACCESS_DENIED", attacker_id=actor_id
            )

        event = bridge.handle_packet(packet)
        self.combat_events.append(event)
        self._apply_combat_event(event)
        return event

    def _apply_combat_event(self, event):
        """สะท้อนผล Combat ไปยัง Engine จริง ถ้ามี callback ถูกผูกไว้"""
        if event is None:
            return

        if event.hit and event.target_id and self.bindings.set_entity_hp:
            self.bindings.set_entity_hp(event.target_id, event.target_hp)

        if event.action in {"PUNCH", "MELEE_ATTACK", "ATTACK"}:
            if self.bindings.play_animation and event.attacker_id:
                self.bindings.play_animation(event.attacker_id, "punch")
        elif event.action in {"ROLL", "DODGE"}:
            if self.bindings.play_animation and event.attacker_id:
                self.bindings.play_animation(event.attacker_id, "roll")

        if self.bindings.emit_event:
            self.bindings.emit_event("combat", event)

    def apply_map_tx_event(self, tx_document: dict):
        """ส่งผล Tx ของ Map ไปยัง Engine จริงหลัง commit เท่านั้น"""
        if tx_document.get("status") != "COMMITTED":
            return False
        self.map_events.append(tx_document)
        if self.bindings.emit_event:
            self.bindings.emit_event("map_tx_committed", tx_document)
        return True

    def tick(self, combat_engine):
        """เรียกจาก game loop ของ Engine"""
        now = self.bindings.get_time() if self.bindings.get_time else None
        return combat_engine.tick(now=now)


def vmax_connect_engine(
    combat_engine: VMAXRealtimeCombatEngine,
    bindings: VMAXEngineBindings | None = None,
):
    """สร้างชุดเชื่อมต่อพร้อมใช้ใน Engine จริง"""
    adapter = VMAXGameEngineAdapter(bindings)
    bridge = VMAXCombatRTPBridge(combat_engine)
    return {
        "adapter": adapter,
        "bridge": bridge,
        "combat_engine": combat_engine,
        "handle_packet": lambda packet: adapter.handle_rtp_packet(bridge, packet),
        "tick": lambda: adapter.tick(combat_engine),
    }


def vmax_engine_integration_selftest():
    """ตรวจการเชื่อม Adapter -> RTP Bridge -> Combat Engine"""
    emitted = []
    hp_updates = []
    animations = []

    bindings = VMAXEngineBindings(
        set_entity_hp=lambda entity_id, hp: hp_updates.append((entity_id, hp)),
        play_animation=lambda entity_id, animation: animations.append((entity_id, animation)),
        emit_event=lambda event_type, event: emitted.append((event_type, event)),
    )

    engine = VMAXRealtimeCombatEngine()
    engine.register_entity(VMAXCombatEntity("player_001", "PLAYER", x=0, y=0, z=0))
    engine.register_entity(VMAXCombatEntity("dino_001", "DINOSAUR", x=1, y=0, z=0, hp=40, max_hp=40))
    connection = vmax_connect_engine(engine, bindings)

    result = connection["handle_packet"]({
        "type": "PUNCH",
        "attacker_id": "player_001",
        "target_id": "dino_001",
        "requested_damage": 10,
    })

    assert result.accepted and result.hit
    assert hp_updates == [("dino_001", 30.0)]
    assert ("player_001", "punch") in animations
    assert emitted and emitted[-1][0] == "combat"
    return True


# สัญลักษณ์สำหรับระบบภายนอกที่ต้องการ import
VMAX_ENGINE_INTEGRATION_READY = True

# ============================================================
# VMAX CENTRAL API BRIDGE
# เชื่อมระหว่าง VMAX Engine กับ Engine ภายนอกผ่าน API ส่วนกลาง
# ============================================================

import json as _vmax_json
import time as _vmax_time
import urllib.request as _vmax_urllib_request
import urllib.error as _vmax_urllib_error


class VMAXCentralAPIError(RuntimeError):
    """ข้อผิดพลาดจาก Central API"""


class VMAXCentralAPIClient:
    """
    HTTP JSON client แบบกำหนดค่าได้สำหรับ API ส่วนกลาง

    หมายเหตุ:
    - ไม่ส่งข้อมูลออกไปเองตอน import ไฟล์
    - ต้องกำหนด base_url และเรียกเมธอดด้วยตนเอง
    - endpoint/auth/schema จริงต้องตรงกับ API ของผู้ใช้
    """

    def __init__(
        self,
        base_url: str,
        api_key: str | None = None,
        timeout: float = 5.0,
        retries: int = 2,
        user_agent: str = "VMAX-Central-Bridge/1.0",
    ):
        self.base_url = base_url.rstrip("/")
        self.api_key = api_key
        self.timeout = timeout
        self.retries = max(0, int(retries))
        self.user_agent = user_agent

    def _headers(self) -> dict:
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "User-Agent": self.user_agent,
        }
        if self.api_key:
            headers["Authorization"] = f"Bearer {self.api_key}"
        return headers

    def request(self, method: str, path: str, payload: dict | None = None) -> dict:
        url = f"{self.base_url}/{path.lstrip('/')}"
        body = None if payload is None else _vmax_json.dumps(payload).encode("utf-8")
        request = _vmax_urllib_request.Request(
            url=url,
            data=body,
            headers=self._headers(),
            method=method.upper(),
        )

        last_error = None
        for attempt in range(self.retries + 1):
            try:
                with _vmax_urllib_request.urlopen(request, timeout=self.timeout) as response:
                    raw = response.read().decode("utf-8")
                    if not raw:
                        return {"ok": True, "status": response.status}
                    parsed = _vmax_json.loads(raw)
                    return parsed if isinstance(parsed, dict) else {"data": parsed}
            except (_vmax_urllib_error.URLError, TimeoutError, ValueError) as exc:
                last_error = exc
                if attempt < self.retries:
                    _vmax_time.sleep(min(0.25 * (2 ** attempt), 2.0))

        raise VMAXCentralAPIError(f"Central API request failed: {method} {url}: {last_error}")

    def publish_event(self, event_type: str, event: dict) -> dict:
        return self.request(
            "POST",
            "/v1/events",
            {"event_type": event_type, "event": event},
        )

    def sync_entity(self, entity: dict) -> dict:
        return self.request("POST", "/v1/entities/sync", {"entity": entity})

    def commit_map_transaction(self, tx_document: dict) -> dict:
        return self.request("POST", "/v1/map/transactions/commit", {"tx": tx_document})

    def health(self) -> dict:
        return self.request("GET", "/health")


class VMAXCentralEngineBridge:
    """ตัวกลางส่ง Combat/Map/Entity Event ไปยัง API ส่วนกลาง"""

    def __init__(self, client: VMAXCentralAPIClient):
        self.client = client
        self.last_error = None
        self.sent_events = 0

    def emit_event(self, event_type: str, event) -> bool:
        try:
            payload = event if isinstance(event, dict) else vars(event)
            self.client.publish_event(event_type, payload)
            self.sent_events += 1
            self.last_error = None
            return True
        except Exception as exc:
            self.last_error = str(exc)
            return False

    def sync_entity(self, entity) -> bool:
        try:
            payload = entity if isinstance(entity, dict) else vars(entity)
            self.client.sync_entity(payload)
            self.last_error = None
            return True
        except Exception as exc:
            self.last_error = str(exc)
            return False

    def commit_map_tx(self, tx_document: dict) -> bool:
        if tx_document.get("status") != "COMMITTED":
            return False
        try:
            self.client.commit_map_transaction(tx_document)
            self.last_error = None
            return True
        except Exception as exc:
            self.last_error = str(exc)
            return False


def vmax_connect_central_api(
    combat_engine: VMAXRealtimeCombatEngine,
    base_url: str,
    api_key: str | None = None,
    timeout: float = 5.0,
    retries: int = 2,
):
    """
    เชื่อม Combat Engine เข้ากับ Central API

    ฟังก์ชันนี้เพียงสร้างการเชื่อมต่อ ไม่เรียก API จนกว่าจะมี event หรือ
    ผู้เรียกสั่ง health()/publish_event()/sync_entity() เอง
    """
    client = VMAXCentralAPIClient(
        base_url=base_url,
        api_key=api_key,
        timeout=timeout,
        retries=retries,
    )
    central_bridge = VMAXCentralEngineBridge(client)
    bindings = VMAXEngineBindings(
        emit_event=central_bridge.emit_event,
    )
    connection = vmax_connect_engine(combat_engine, bindings)
    connection.update({
        "central_client": client,
        "central_bridge": central_bridge,
    })
    return connection


