# ---------------------------------------------------------------------------
# VMAX AUTOMATIC CENTRAL-API ORCHESTRATOR
# ---------------------------------------------------------------------------
# This layer makes the existing bridge self-starting after configuration is
# available. It does not require a separate automation service.

import os as _vmax_os
import time as _vmax_time
import threading as _vmax_threading
import queue as _vmax_queue
import logging as _vmax_logging


class VMAXAutomaticCentralAPIOrchestrator:
    """Automatic connect/reconnect/health-check worker for the central API.

    Configuration is read from environment variables so deployment can start
    the same Python file without editing source code:
      VMAX_CENTRAL_API_URL
      VMAX_CENTRAL_API_KEY
      VMAX_ENGINE_ID
      VMAX_CENTRAL_AUTO_CONNECT=1|0
      VMAX_CENTRAL_HEALTH_INTERVAL=15
      VMAX_CENTRAL_RECONNECT_INTERVAL=5
    """

    def __init__(self, combat_engine=None, map_store=None, logger=None):
        self.combat_engine = combat_engine
        self.map_store = map_store
        self.logger = logger or _vmax_logging.getLogger("vmax.central")
        self.base_url = _vmax_os.getenv("VMAX_CENTRAL_API_URL", "").strip()
        self.api_key = _vmax_os.getenv("VMAX_CENTRAL_API_KEY", "").strip()
        self.engine_id = _vmax_os.getenv("VMAX_ENGINE_ID", "local-engine").strip()
        self.auto_connect = _vmax_os.getenv("VMAX_CENTRAL_AUTO_CONNECT", "1").lower() not in {"0", "false", "no"}
        self.health_interval = max(1.0, float(_vmax_os.getenv("VMAX_CENTRAL_HEALTH_INTERVAL", "15")))
        self.reconnect_interval = max(1.0, float(_vmax_os.getenv("VMAX_CENTRAL_RECONNECT_INTERVAL", "5")))
        self.client = None
        self.bridge = None
        self.connection = None
        self._stop = _vmax_threading.Event()
        self._wake = _vmax_threading.Event()
        self._thread = None
        self._connected = False
        self._last_error = None

    @property
    def connected(self):
        return self._connected

    def configure(self, base_url=None, api_key=None, engine_id=None):
        if base_url is not None:
            self.base_url = str(base_url).strip()
        if api_key is not None:
            self.api_key = str(api_key).strip()
        if engine_id is not None:
            self.engine_id = str(engine_id).strip()
        self._wake.set()
        return self

    def _connect_once(self):
        if not self.base_url:
            raise RuntimeError("VMAX_CENTRAL_API_URL is not configured")
        self.client = VMAXCentralAPIClient(
            base_url=self.base_url,
            api_key=self.api_key or None,
            timeout=10,
            retries=2,
        )
        # Health check is intentionally best-effort and uses the bridge's
        # existing client contract when available.
        if hasattr(self.client, "health_check"):
            self.client.health_check()
        self.bridge = VMAXCentralEngineBridge(self.client)
        if self.combat_engine is not None:
            bindings = VMAXEngineBindings(emit_event=self.bridge.emit_event)
            self.connection = vmax_connect_engine(self.combat_engine, bindings)
        self._connected = True
        self._last_error = None
        self.logger.info("VMAX central API connected: %s", self.base_url)

    def _disconnect(self, error=None):
        self._connected = False
        self._last_error = repr(error) if error else None
        self.client = None
        self.bridge = None
        self.connection = None

    def start(self):
        if self._thread and self._thread.is_alive():
            return self
        self._stop.clear()
        self._thread = _vmax_threading.Thread(target=self._worker, name="vmax-central-auto", daemon=True)
        self._thread.start()
        return self

    def stop(self, timeout=3):
        self._stop.set()
        self._wake.set()
        if self._thread and self._thread.is_alive():
            self._thread.join(timeout=timeout)
        self._disconnect()

    def reconnect_now(self):
        self._disconnect()
        self._wake.set()

    def status(self):
        return {
            "engine_id": self.engine_id,
            "base_url_configured": bool(self.base_url),
            "connected": self.connected,
            "last_error": self._last_error,
            "running": bool(self._thread and self._thread.is_alive()),
        }

    def _worker(self):
        next_health = 0.0
        while not self._stop.is_set():
            now = _vmax_time.monotonic()
            if not self._connected:
                if self.auto_connect:
                    try:
                        self._connect_once()
                        next_health = now + self.health_interval
                    except Exception as exc:
                        self._disconnect(exc)
                        self.logger.warning("VMAX central API unavailable; retrying: %s", exc)
                        self._stop.wait(self.reconnect_interval)
                        continue
            elif now >= next_health:
                try:
                    if self.client is not None and hasattr(self.client, "health_check"):
                        self.client.health_check()
                    next_health = now + self.health_interval
                except Exception as exc:
                    self.logger.warning("VMAX central API health check failed: %s", exc)
                    self._disconnect(exc)
                    self._stop.wait(self.reconnect_interval)
                    continue
            self._wake.wait(timeout=1.0)
            self._wake.clear()


def vmax_start_automatic_central_api(combat_engine=None, map_store=None, **config):
    """Create and start the automatic central API connector in this process."""
    orchestrator = VMAXAutomaticCentralAPIOrchestrator(combat_engine, map_store)
    orchestrator.configure(
        base_url=config.get("base_url"),
        api_key=config.get("api_key"),
        engine_id=config.get("engine_id"),
    )
    return orchestrator.start()


