# =====================================================================
# VMAX Shared Central Module Registry
# Reuses one central API client/connection across Combat, Map, Entity,
# Access and Engine Bridge modules in this single file.
# =====================================================================

class VMAXSharedCentralModuleRegistry:
    """Process-wide registry for one shared central API connection."""

    _lock = _vmax_threading.RLock()
    _orchestrator = None
    _modules = {}

    @classmethod
    def configure(cls, **config):
        with cls._lock:
            if cls._orchestrator is None:
                cls._orchestrator = VMAXAutomaticCentralAPIOrchestrator(
                    config.get("combat_engine"), config.get("map_store")
                )
            cls._orchestrator.configure(
                base_url=config.get("base_url"),
                api_key=config.get("api_key"),
                engine_id=config.get("engine_id"),
            )
            return cls._orchestrator

    @classmethod
    def start(cls, **config):
        with cls._lock:
            orchestrator = cls.configure(**config)
            if not orchestrator._thread or not orchestrator._thread.is_alive():
                orchestrator.start()
            return orchestrator

    @classmethod
    def register(cls, name, module):
        with cls._lock:
            cls._modules[str(name)] = module
            return module

    @classmethod
    def get(cls, name, default=None):
        with cls._lock:
            return cls._modules.get(str(name), default)

    @classmethod
    def status(cls):
        with cls._lock:
            orchestrator = cls._orchestrator
            return {
                "configured": orchestrator is not None,
                "running": bool(orchestrator and orchestrator._thread and orchestrator._thread.is_alive()),
                "connected": bool(orchestrator and orchestrator._connected),
                "modules": sorted(cls._modules),
            }


def vmax_start_shared_central_modules(combat_engine=None, map_store=None, **config):
    """Start/reuse one automatic central connection for all VMAX modules."""
    return VMAXSharedCentralModuleRegistry.start(
        combat_engine=combat_engine,
        map_store=map_store,
        **config,
    )


