# =====================================================================
# VMAX Existing Engine Integration
# Registers an engine already present in this file with the shared
# central module registry. The engine is not replaced; it is reused.
# =====================================================================

class VMAXExistingEngineAdapter:
    """Adapter for an engine object that already exists in this file/app."""

    def __init__(self, engine, engine_id="existing-engine"):
        if engine is None:
            raise ValueError("Existing engine instance is required")
        self.engine = engine
        self.engine_id = str(engine_id)
        self.connected = False

    def health_check(self):
        engine = self.engine
        checker = getattr(engine, "health_check", None)
        if callable(checker):
            return bool(checker())
        checker = getattr(engine, "is_healthy", None)
        if callable(checker):
            return bool(checker())
        return True

    def connect(self):
        engine = self.engine
        connector = getattr(engine, "connect", None)
        if callable(connector):
            result = connector()
            self.connected = result is not False
        else:
            self.connected = True
        return self.connected

    def disconnect(self):
        engine = self.engine
        closer = getattr(engine, "disconnect", None)
        if callable(closer):
            closer()
        self.connected = False
        return True

    def dispatch(self, method, *args, **kwargs):
        if not self.connected:
            raise RuntimeError("Existing engine is not connected")
        target = getattr(self.engine, method, None)
        if not callable(target):
            raise AttributeError("Engine method not found: %s" % method)
        return target(*args, **kwargs)


def vmax_register_existing_engine(engine, engine_id="existing-engine", **central_config):
    """Register the engine already defined in this file and optionally start
    the shared central connection. No duplicate engine connection is created.
    """
    adapter = VMAXExistingEngineAdapter(engine, engine_id=engine_id)
    VMAXSharedCentralModuleRegistry.register("engine", adapter)
    VMAXSharedCentralModuleRegistry.register("engine:%s" % engine_id, adapter)
    if central_config:
        VMAXSharedCentralModuleRegistry.configure(
            combat_engine=central_config.get("combat_engine"),
            map_store=central_config.get("map_store"),
            base_url=central_config.get("base_url"),
            api_key=central_config.get("api_key"),
            engine_id=engine_id,
        )
    return adapter


