# =====================================================================
# VMAX Terminal Engine Selector / Discovery Layer
# Allows selecting an already-defined engine by name from the terminal.
# =====================================================================

import argparse as _vmax_argparse


def _vmax_engine_candidates(namespace=None):
    """Find engine-like objects already created in the current module."""
    namespace = globals() if namespace is None else namespace
    candidates = {}
    for name, value in namespace.items():
        if name.startswith("_") or value is None:
            continue
        if isinstance(value, VMAXExistingEngineAdapter):
            candidates[name] = value
            candidates[value.engine_id] = value
            continue
        if any(callable(getattr(value, method, None)) for method in ("connect", "health_check", "is_healthy")):
            candidates[name] = value
    return candidates


def vmax_find_engine_by_name(engine_name, namespace=None):
    """Resolve an engine by exact name or case-insensitive name."""
    if not engine_name or not str(engine_name).strip():
        raise ValueError("Engine name is required")

    requested = str(engine_name).strip()
    candidates = _vmax_engine_candidates(namespace)

    if requested in candidates:
        return candidates[requested]

    lowered = requested.lower()
    for name, engine in candidates.items():
        if str(name).lower() == lowered:
            return engine

    # Also allow engines stored in the shared registry.
    for key in (requested, "engine:%s" % requested, "engine"):
        try:
            engine = VMAXSharedCentralModuleRegistry.get(key)
        except Exception:
            engine = None
        if engine is not None:
            return engine

    raise LookupError("Engine '%s' was not found" % requested)


def vmax_terminal_connect_engine(engine_name, namespace=None):
    """Find, connect, health-check, and register an engine selected by name."""
    engine = vmax_find_engine_by_name(engine_name, namespace=namespace)

    if not isinstance(engine, VMAXExistingEngineAdapter):
        engine = vmax_register_existing_engine(engine, engine_id=str(engine_name))

    if not engine.connect():
        raise ConnectionError("Engine '%s' could not connect" % engine_name)
    if not engine.health_check():
        engine.disconnect()
        raise ConnectionError("Engine '%s' failed health check" % engine_name)

    return engine


def vmax_terminal_list_engines(namespace=None):
    """Return discoverable engine names for terminal output."""
    candidates = _vmax_engine_candidates(namespace)
    return sorted(set(str(name) for name in candidates))


def vmax_terminal_main(argv=None):
    parser = _vmax_argparse.ArgumentParser(
        prog="vmax-engine",
        description="Select and connect to an engine already defined in VMAX."
    )
    subparsers = parser.add_subparsers(dest="command")

    list_parser = subparsers.add_parser("list-engines", help="List discoverable engines")
    list_parser.set_defaults(_handler="list")

    connect_parser = subparsers.add_parser("connect-engine", help="Connect to an engine by name")
    connect_parser.add_argument("engine_name", help="Registered/global engine name")
    connect_parser.set_defaults(_handler="connect")

    args = parser.parse_args(argv)

    if getattr(args, "_handler", None) == "list":
        names = vmax_terminal_list_engines()
        if not names:
            print("No engines found")
            return 1
        for name in names:
            print(name)
        return 0

    if getattr(args, "_handler", None) == "connect":
        try:
            engine = vmax_terminal_connect_engine(args.engine_name)
            print("Engine '%s' connected and health check passed" % args.engine_name)
            return 0
        except (ValueError, LookupError, ConnectionError, RuntimeError) as exc:
            print("Request rejected: %s" % exc)
            return 2

    parser.print_help()
    return 0


