# ============================================================================
# VMAX LEGACY SERVICE LAYER — PRE-ENGINE / "GREAT-GRANDPARENT" MODELS
# ----------------------------------------------------------------------------
# Includes the requested legacy concepts, excluding Transaction Monitor:
#   1) Service / Daemon
#   2) Server Process
#   4) Job Control / Batch System
#   5) Supervisor / Monitor
#   6) Executive / Control Program
#
# These are application-level simulations. They do not create OS daemons,
# replace the host operating system, or claim to be real mainframe services.
# ============================================================================

class VMAXLegacyServiceDaemon:
    """Background service/daemon that accepts and processes named requests."""

    def __init__(self, name="vmax-legacy-daemon", handler=None):
        self.name = str(name)
        self.handler = handler or (lambda payload: payload)
        self.running = False
        self.queue = []
        self.history = []

    def start(self):
        self.running = True
        return {"ok": True, "service": self.name, "state": "running"}

    def stop(self):
        self.running = False
        return {"ok": True, "service": self.name, "state": "stopped"}

    def submit(self, payload=None):
        if not self.running:
            raise RuntimeError("legacy daemon is not running")
        job = {"id": _v12_uuid.uuid4().hex[:12], "payload": payload,
               "submitted": _v12_time.time()}
        self.queue.append(job)
        return job["id"]

    def process_once(self):
        if not self.running:
            raise RuntimeError("legacy daemon is not running")
        if not self.queue:
            return None
        job = self.queue.pop(0)
        result = self.handler(job["payload"])
        record = {"id": job["id"], "result": result,
                  "completed": _v12_time.time()}
        self.history.append(record)
        return record


class VMAXLegacyServerProcess:
    """Old-style server process: a named request/response endpoint."""

    def __init__(self, name="vmax-server-process", handler=None):
        self.name = str(name)
        self.handler = handler or (lambda request: {"echo": request})
        self.running = False
        self.requests = 0

    def start(self):
        self.running = True
        return {"ok": True, "server": self.name, "state": "running"}

    def stop(self):
        self.running = False
        return {"ok": True, "server": self.name, "state": "stopped"}

    def handle(self, request):
        if not self.running:
            raise ConnectionError("server process is not running")
        self.requests += 1
        return {"ok": True, "server": self.name,
                "request_no": self.requests,
                "response": self.handler(request)}


class VMAXLegacyBatchSystem:
    """Job-control/batch queue for deferred, ordered processing."""

    def __init__(self, name="vmax-batch-system"):
        self.name = str(name)
        self.jobs = []
        self.completed = []
        self.next_job_id = 1

    def submit(self, name, payload=None, priority=0):
        job = {"id": self.next_job_id, "name": str(name),
               "payload": payload, "priority": int(priority),
               "state": "queued"}
        self.next_job_id += 1
        self.jobs.append(job)
        self.jobs.sort(key=lambda item: (-item["priority"], item["id"]))
        return dict(job)

    def run_next(self, handler=None):
        if not self.jobs:
            return None
        job = self.jobs.pop(0)
        job["state"] = "running"
        result = handler(job["payload"]) if handler else job["payload"]
        job["state"] = "completed"
        job["result"] = result
        self.completed.append(job)
        return dict(job)

    def status(self):
        return {"name": self.name, "queued": len(self.jobs),
                "completed": len(self.completed)}


class VMAXLegacySupervisorMonitor:
    """Supervisor/monitor that starts, stops, and checks legacy services."""

    def __init__(self, name="vmax-supervisor"):
        self.name = str(name)
        self.services = {}

    def register(self, service):
        self.services[service.name] = service
        return service.name

    def start_all(self):
        return [service.start() for service in self.services.values()]

    def stop_all(self):
        return [service.stop() for service in self.services.values()]

    def health(self):
        return {
            name: {
                "running": bool(getattr(service, "running", False)),
                "type": service.__class__.__name__,
            }
            for name, service in self.services.items()
        }


class VMAXLegacyExecutiveControlProgram:
    """Central control program for the legacy service layer."""

    def __init__(self, name="vmax-executive"):
        self.name = str(name)
        self.supervisor = VMAXLegacySupervisorMonitor()
        self.batch = VMAXLegacyBatchSystem()
        self.commands = {}
        self.audit_log = []

    def register_command(self, name, handler):
        self.commands[str(name)] = handler

    def execute(self, name, payload=None):
        command = str(name)
        if command not in self.commands:
            raise LookupError("unknown legacy control command: " + command)
        result = self.commands[command](payload)
        self.audit_log.append({
            "command": command, "payload": payload,
            "result": result, "at": _v12_time.time()
        })
        return result

    def status(self):
        return {
            "name": self.name,
            "commands": sorted(self.commands),
            "supervisor": self.supervisor.health(),
            "batch": self.batch.status(),
            "audit_entries": len(self.audit_log),
        }


def vmax_create_legacy_service_layer():
    """Create the requested legacy layer, excluding Transaction Monitor."""
    executive = VMAXLegacyExecutiveControlProgram()
    daemon = VMAXLegacyServiceDaemon()
    server = VMAXLegacyServerProcess()
    executive.supervisor.register(daemon)
    executive.supervisor.register(server)
    return {
        "executive": executive,
        "daemon": daemon,
        "server": server,
        "batch": executive.batch,
        "supervisor": executive.supervisor,
    }


