# ---------------------------------------------------------------------------
# VMAX LEGACY SERVICE LAYER - OPERATIONAL INTEGRATION
# ---------------------------------------------------------------------------
# This layer is application-level orchestration: process lifecycle, job queue,
# supervision, command control, audit events, and optional runtime callbacks.
# It deliberately avoids replacing the existing VMAX kernel/runtime.
import threading as _vmax_threading
import queue as _vmax_queue
import uuid as _vmax_uuid
import traceback as _vmax_traceback
from dataclasses import dataclass as _vmax_dataclass, field as _vmax_field


@_vmax_dataclass
class VMAXManagedProcess:
    name: str
    target: object = None
    args: tuple = ()
    kwargs: dict = _vmax_field(default_factory=dict)
    pid: str = _vmax_field(default_factory=lambda: "vpx-" + _vmax_uuid.uuid4().hex[:12])
    state: str = "created"
    started_at: float = None
    stopped_at: float = None
    exit_code: int = None
    error: str = None
    thread: object = None
    stop_event: object = None


class VMAXProcessTable:
    """Thread-safe process registry with start/stop/restart lifecycle."""

    def __init__(self):
        self._lock = _vmax_threading.RLock()
        self._items = {}

    def register(self, process):
        with self._lock:
            self._items[process.pid] = process
        return process

    def get(self, pid):
        with self._lock:
            return self._items.get(str(pid))

    def list(self):
        with self._lock:
            return [dict(vars(x)) for x in self._items.values()]

    def start(self, process):
        with self._lock:
            if process.thread and process.thread.is_alive():
                return process
            process.stop_event = _vmax_threading.Event()
            process.state = "starting"
            process.started_at = _v12_time.time()
            process.exit_code = None
            process.error = None

            def runner():
                process.state = "running"
                try:
                    if process.target is not None:
                        result = process.target(
                            *process.args, stop_event=process.stop_event,
                            **process.kwargs
                        )
                        if isinstance(result, int):
                            process.exit_code = result
                    process.exit_code = 0 if process.exit_code is None else process.exit_code
                    if process.stop_event.is_set():
                        process.state = "stopped"
                    else:
                        process.state = "exited"
                except Exception as exc:
                    process.error = "".join(_vmax_traceback.format_exception(exc))
                    process.exit_code = 1
                    process.state = "failed"
                finally:
                    process.stopped_at = _v12_time.time()

            process.thread = _vmax_threading.Thread(
                target=runner, name=process.name, daemon=True
            )
            process.thread.start()
            return process

    def stop(self, pid, timeout=5.0):
        process = self.get(pid)
        if not process:
            return False
        if process.stop_event:
            process.stop_event.set()
        if process.thread and process.thread.is_alive():
            process.thread.join(timeout=max(0.0, float(timeout)))
        if process.thread and process.thread.is_alive():
            process.state = "stop_requested"
        else:
            process.state = "stopped"
        process.stopped_at = _v12_time.time()
        return True

    def restart(self, pid):
        process = self.get(pid)
        if not process:
            raise KeyError(pid)
        self.stop(pid)
        return self.start(process)


@_vmax_dataclass
class VMAXBatchJob:
    job_id: str = _vmax_field(default_factory=lambda: "job-" + _vmax_uuid.uuid4().hex[:12])
    name: str = "job"
    target: object = None
    args: tuple = ()
    kwargs: dict = _vmax_field(default_factory=dict)
    priority: int = 100
    state: str = "queued"
    result: object = None
    error: str = None
    submitted_at: float = _vmax_field(default_factory=_v12_time.time)
    finished_at: float = None


class VMAXOperationalBatchScheduler:
    """Priority queue scheduler with bounded workers, retry, and job records."""

    def __init__(self, workers=2, max_retries=1):
        self.workers = max(1, int(workers))
        self.max_retries = max(0, int(max_retries))
        self.queue = _vmax_queue.PriorityQueue()
        self.jobs = {}
        self.lock = _vmax_threading.RLock()
        self.stop_event = _vmax_threading.Event()
        self.threads = []

    def start(self):
        if self.threads:
            return
        for index in range(self.workers):
            t = _vmax_threading.Thread(
                target=self._worker, name=f"vmax-batch-{index}", daemon=True
            )
            self.threads.append(t)
            t.start()

    def submit(self, job):
        with self.lock:
            self.jobs[job.job_id] = job
            self.queue.put((int(job.priority), job.submitted_at, job.job_id))
        self.start()
        return job.job_id

    def _worker(self):
        while not self.stop_event.is_set():
            try:
                _, _, job_id = self.queue.get(timeout=0.2)
            except _vmax_queue.Empty:
                continue
            job = self.jobs.get(job_id)
            if not job:
                self.queue.task_done()
                continue
            job.state = "running"
            try:
                job.result = job.target(*job.args, **job.kwargs)
                job.state = "completed"
            except Exception as exc:
                job.error = "".join(_vmax_traceback.format_exception(exc))
                job.state = "failed"
            finally:
                job.finished_at = _v12_time.time()
                self.queue.task_done()

    def cancel(self, job_id):
        job = self.jobs.get(str(job_id))
        if not job or job.state != "queued":
            return False
        job.state = "cancelled"
        return True

    def shutdown(self):
        self.stop_event.set()
        for t in self.threads:
            t.join(timeout=1.0)

    def status(self):
        with self.lock:
            return {
                "workers": self.workers,
                "queued": self.queue.qsize(),
                "jobs": {k: vars(v).copy() for k, v in self.jobs.items()},
            }


class VMAXOperationalSupervisor:
    """Heartbeat and failure supervisor for managed processes."""

    def __init__(self, process_table=None, interval=1.0, auto_restart=False):
        self.process_table = process_table or VMAXProcessTable()
        self.interval = float(interval)
        self.auto_restart = bool(auto_restart)
        self.stop_event = _vmax_threading.Event()
        self.thread = None
        self.events = []

    def start(self):
        if self.thread and self.thread.is_alive():
            return
        self.stop_event.clear()
        self.thread = _vmax_threading.Thread(
            target=self._loop, name="vmax-supervisor", daemon=True
        )
        self.thread.start()

    def _loop(self):
        while not self.stop_event.wait(self.interval):
            for item in self.process_table.list():
                if item["state"] == "failed":
                    self.events.append({
                        "type": "process_failed", "pid": item["pid"],
                        "at": _v12_time.time(), "error": item["error"],
                    })
                    if self.auto_restart:
                        try:
                            self.process_table.restart(item["pid"])
                            self.events.append({
                                "type": "process_restarted",
                                "pid": item["pid"], "at": _v12_time.time(),
                            })
                        except Exception:
                            pass

    def stop(self):
        self.stop_event.set()
        if self.thread:
            self.thread.join(timeout=2.0)

    def health(self):
        items = self.process_table.list()
        return {
            "running": sum(x["state"] == "running" for x in items),
            "failed": sum(x["state"] == "failed" for x in items),
            "total": len(items),
            "events": len(self.events),
        }


class VMAXIntegratedExecutive:
    """Single control facade for services, processes, jobs and supervision."""

    def __init__(self, runtime_callback=None, workers=2, auto_restart=False):
        self.runtime_callback = runtime_callback
        self.processes = VMAXProcessTable()
        self.scheduler = VMAXOperationalBatchScheduler(workers=workers)
        self.supervisor = VMAXOperationalSupervisor(
            self.processes, auto_restart=auto_restart
        )
        self.audit = []
        self.commands = {}
        self._register_builtin_commands()

    def _record(self, action, payload=None, result=None):
        self.audit.append({
            "action": action, "payload": payload, "result": result,
            "at": _v12_time.time(),
        })

    def _register_builtin_commands(self):
        self.commands.update({
            "status": lambda payload=None: self.status(),
            "process.list": lambda payload=None: self.processes.list(),
            "process.stop": lambda payload: self.processes.stop(payload),
            "process.restart": lambda payload: self.processes.restart(payload),
            "job.status": lambda payload=None: self.scheduler.status(),
            "supervisor.health": lambda payload=None: self.supervisor.health(),
        })

    def register_process(self, name, target=None, args=(), kwargs=None):
        process = VMAXManagedProcess(
            name=name, target=target, args=tuple(args),
            kwargs=dict(kwargs or {})
        )
        self.processes.register(process)
        return process

    def start_process(self, process_or_pid):
        process = (self.processes.get(process_or_pid)
                   if isinstance(process_or_pid, str)
                   else process_or_pid)
        if not process:
            raise KeyError(process_or_pid)
        result = self.processes.start(process)
        self._record("process.start", process.pid, result.state)
        return result

    def submit_job(self, name, target, args=(), kwargs=None, priority=100):
        job = VMAXBatchJob(
            name=name, target=target, args=tuple(args),
            kwargs=dict(kwargs or {}), priority=priority
        )
        job_id = self.scheduler.submit(job)
        self._record("job.submit", job_id, "queued")
        return job_id

    def execute(self, command, payload=None):
        if command not in self.commands:
            raise LookupError("unknown command: " + str(command))
        result = self.commands[command](payload)
        self._record(command, payload, result)
        return result

    def start(self):
        self.scheduler.start()
        self.supervisor.start()
        self._record("system.start", result="started")
        return self.status()

    def shutdown(self):
        self.supervisor.stop()
        self.scheduler.shutdown()
        for item in self.processes.list():
            self.processes.stop(item["pid"])
        self._record("system.shutdown", result="stopped")

    def status(self):
        return {
            "processes": self.processes.list(),
            "jobs": self.scheduler.status(),
            "supervisor": self.supervisor.health(),
            "audit_entries": len(self.audit),
            "runtime_callback": bool(self.runtime_callback),
        }


def vmax_create_operational_legacy_layer(runtime_callback=None,
                                         workers=2, auto_restart=False):
    """Factory for the operational legacy layer, excluding Transaction Monitor."""
    executive = VMAXIntegratedExecutive(
        runtime_callback=runtime_callback,
        workers=workers,
        auto_restart=auto_restart,
    )
    executive.start()
    return {
        "executive": executive,
        "process_table": executive.processes,
        "scheduler": executive.scheduler,
        "supervisor": executive.supervisor,
    }


VMAX_OPERATIONAL_LEGACY_LAYER_READY = True


# ---------------------------------------------------------------------------
# VMAX PRE-LEGACY / HISTORICAL COMPUTING COMPATIBILITY LAYER
# ---------------------------------------------------------------------------
# Application-level emulation of older computing conventions:
# punched-card decks, JCL-like control statements, spool files, tape reels,
# teleprinter-style operator messages, and batch monitor semantics.
# This does not claim to emulate physical hardware or a complete historical OS.

from dataclasses import dataclass as _vmax_hist_dataclass
from collections import deque as _vmax_hist_deque
import time as _vmax_hist_time
import uuid as _vmax_hist_uuid


@_vmax_hist_dataclass
class VMAXPunchedCard:
    sequence: int
    text: str
    card_type: str = "DATA"

    def as_card_image(self) -> str:
        return f"{self.sequence:08d} {self.card_type:<8} {self.text[:80]}"


class VMAXPunchedCardDeck:
    """80-column punched-card deck abstraction with deck sequencing."""

    def __init__(self, cards=None, name="SYSIN"):
        self.name = name
        self.cards = []
        for i, card in enumerate(cards or [], 1):
            self.cards.append(
                card if isinstance(card, VMAXPunchedCard)
                else VMAXPunchedCard(i, str(card))
            )

    def add(self, text, card_type="DATA"):
        card = VMAXPunchedCard(len(self.cards) + 1, str(text), card_type)
        self.cards.append(card)
        return card

    def read(self):
        return [card.text for card in self.cards]

    def image(self):
        return "\n".join(card.as_card_image() for card in self.cards)


class VMAXJCLControlLanguage:
    """Small JCL-like parser for JOB/EXEC/DD control statements."""

    def parse(self, deck):
        lines = deck.read() if isinstance(deck, VMAXPunchedCardDeck) else list(deck)
        result = {"job": None, "steps": [], "dd": [], "raw": lines}
        for line in lines:
            text = line.strip()
            upper = text.upper()
            if upper.startswith("//") and " JOB " in f" {upper} ":
                result["job"] = text
            elif upper.startswith("//") and " EXEC " in f" {upper} ":
                result["steps"].append(text)
            elif upper.startswith("//") and " DD " in f" {upper} ":
                result["dd"].append(text)
        return result


class VMAXSpoolFile:
    """Persistent-in-memory reader/punch/printer spool abstraction."""

    def __init__(self, name=None):
        self.name = name or f"SPOOL-{_vmax_hist_uuid.uuid4().hex[:8].upper()}"
        self.records = []
        self.closed = False

    def write(self, record):
        if self.closed:
            raise RuntimeError("spool file is closed")
        self.records.append(str(record))

    def rewind(self):
        return list(self.records)

    def close(self):
        self.closed = True

    def __len__(self):
        return len(self.records)


class VMAXTapeReel:
    """Sequential magnetic-tape-style block storage."""

    def __init__(self, label="TAPE001"):
        self.label = label
        self.blocks = []
        self.position = 0

    def write_block(self, data):
        self.blocks.append(data)

    def rewind(self):
        self.position = 0

    def read_block(self):
        if self.position >= len(self.blocks):
            return None
        value = self.blocks[self.position]
        self.position += 1
        return value


class VMAXTeleprinterOperatorConsole:
    """Slow-era operator console with message and reply queues."""

    def __init__(self):
        self.messages = []
        self.replies = _vmax_hist_deque()

    def write(self, message, severity="INFO"):
        entry = {
            "timestamp": _vmax_hist_time.time(),
            "severity": severity,
            "message": str(message),
        }
        self.messages.append(entry)
        return entry

    def ask(self, message):
        self.write(message, "REPLY")
        return self.replies.popleft() if self.replies else None

    def reply(self, value):
        self.replies.append(str(value))


class VMAXHistoricalMonitor:
    """Older monitor/control-program style facade over the new components."""

    def __init__(self, runtime_callback=None):
        self.runtime_callback = runtime_callback
        self.console = VMAXTeleprinterOperatorConsole()
        self.spools = {}
        self.tapes = {}
        self.decks = {}
        self.jcl = VMAXJCLControlLanguage()
        self.started = False

    def start(self):
        self.started = True
        self.console.write("HISTORICAL MONITOR READY")
        return self

    def mount_deck(self, name, cards):
        deck = VMAXPunchedCardDeck(cards, name)
        self.decks[name] = deck
        return deck

    def allocate_spool(self, name=None):
        spool = VMAXSpoolFile(name)
        self.spools[spool.name] = spool
        return spool

    def mount_tape(self, label="TAPE001"):
        tape = VMAXTapeReel(label)
        self.tapes[label] = tape
        return tape

    def submit_jcl(self, deck_or_lines):
        parsed = self.jcl.parse(deck_or_lines)
        self.console.write(
            f"JOB ACCEPTED: steps={len(parsed['steps'])}, dd={len(parsed['dd'])}"
        )
        if self.runtime_callback:
            return self.runtime_callback(parsed)
        return parsed


def vmax_create_historical_compatibility_layer(runtime_callback=None):
    monitor = VMAXHistoricalMonitor(runtime_callback=runtime_callback)
    monitor.start()
    return {
        "historical_monitor": monitor,
        "jcl": monitor.jcl,
        "console": monitor.console,
        "decks": monitor.decks,
        "spools": monitor.spools,
        "tapes": monitor.tapes,
    }


VMAX_HISTORICAL_COMPATIBILITY_LAYER_READY = True


# ---------------------------------------------------------------------------
# VMAX PRE-MAINFRAME HISTORICAL EMULATION LAYER
# Application-level emulation of early computing technologies.
# ---------------------------------------------------------------------------
from dataclasses import dataclass as _vmax_dataclass
from collections import deque as _vmax_deque
import time as _vmax_time
import threading as _vmax_threading
import uuid as _vmax_uuid


@_vmax_dataclass
class VMAXRelay:
    name: str
    energized: bool = False
    normally_closed: bool = False
    transitions: int = 0

    def set(self, state: bool):
        state = bool(state)
        if state != self.energized:
            self.transitions += 1
        self.energized = state
        return self.energized

    def contact(self) -> bool:
        return self.energized if not self.normally_closed else not self.energized


class VMAXRelayComputer:
    """Small relay-logic machine with explicit timing and fault injection."""
    def __init__(self, relay_count=16, cycle_delay=0.001):
        self.relays = {f"R{i}": VMAXRelay(f"R{i}") for i in range(relay_count)}
        self.cycle_delay = cycle_delay
        self.faults = set()
        self.cycles = 0

    def set_fault(self, relay_name, failed=True):
        if failed:
            self.faults.add(relay_name)
        else:
            self.faults.discard(relay_name)

    def write_bus(self, value, width=8):
        bits = [(value >> i) & 1 for i in range(width)]
        for i, bit in enumerate(bits):
            name = f"R{i}"
            if name in self.relays and name not in self.faults:
                self.relays[name].set(bool(bit))
        self.cycles += 1
        _vmax_time.sleep(self.cycle_delay)
        return self.read_bus(width)

    def read_bus(self, width=8):
        value = 0
        for i in range(width):
            relay = self.relays.get(f"R{i}")
            if relay and relay.contact():
                value |= 1 << i
        return value


class VMAXVacuumTube:
    def __init__(self, name, warmup_seconds=0.05):
        self.name = name
        self.warmup_seconds = warmup_seconds
        self.temperature = 20.0
        self.ready = False
        self.failed = False
        self.cycles = 0

    def warmup(self):
        if self.failed:
            raise RuntimeError(f"Tube {self.name} has failed")
        _vmax_time.sleep(self.warmup_seconds)
        self.temperature = 180.0
        self.ready = True
        return True

    def pulse(self, signal):
        if not self.ready:
            self.warmup()
        if self.failed:
            raise RuntimeError(f"Tube {self.name} failure")
        self.cycles += 1
        return bool(signal)


class VMAXTubeRack:
    def __init__(self, count=8):
        self.tubes = {f"T{i}": VMAXVacuumTube(f"T{i}") for i in range(count)}

    def warmup_all(self):
        return {name: tube.warmup() for name, tube in self.tubes.items()}

    def logic_and(self, a, b):
        return self.tubes["T0"].pulse(a) and self.tubes["T1"].pulse(b)

    def logic_or(self, a, b):
        return self.tubes["T0"].pulse(a) or self.tubes["T1"].pulse(b)


class VMAXPaperTape:
    def __init__(self, width=8):
        self.width = width
        self.data = bytearray()
        self.position = 0

    def punch(self, value):
        self.data.append(int(value) & ((1 << self.width) - 1))
        return len(self.data)

    def read(self):
        if self.position >= len(self.data):
            return None
        value = self.data[self.position]
        self.position += 1
        return value

    def rewind(self):
        self.position = 0

    def export_bytes(self):
        return bytes(self.data)


class VMAXMercuryDelayLine:
    def __init__(self, capacity=128, propagation_delay=0.002):
        self.capacity = capacity
        self.propagation_delay = propagation_delay
        self.buffer = _vmax_deque(maxlen=capacity)
        self.lock = _vmax_threading.RLock()

    def write(self, value):
        with self.lock:
            self.buffer.append(int(value))
            _vmax_time.sleep(self.propagation_delay)
            return len(self.buffer)

    def read(self):
        with self.lock:
            if not self.buffer:
                return None
            value = self.buffer[0]
            _vmax_time.sleep(self.propagation_delay)
            return value

    def circulate(self):
        with self.lock:
            if self.buffer:
                self.buffer.rotate(-1)
            return list(self.buffer)


class VMAXWilliamsKilburnMemory:
    def __init__(self, capacity=1024, decay_seconds=1.0):
        self.capacity = capacity
        self.decay_seconds = decay_seconds
        self.cells = {}
        self.lock = _vmax_threading.RLock()

    def write(self, address, value):
        with self.lock:
            if not 0 <= int(address) < self.capacity:
                raise IndexError("memory address out of range")
            self.cells[int(address)] = (int(value), _vmax_time.monotonic())
            return value

    def read(self, address, destructive=True):
        with self.lock:
            item = self.cells.get(int(address))
            if item is None:
                return 0
            value, timestamp = item
            if _vmax_time.monotonic() - timestamp > self.decay_seconds:
                self.cells.pop(int(address), None)
                return 0
            if destructive:
                self.cells.pop(int(address), None)
            return value

    def refresh(self):
        with self.lock:
            now = _vmax_time.monotonic()
            self.cells = {a: (v, now) for a, (v, _) in self.cells.items()}


class VMAXMagneticDrum:
    def __init__(self, tracks=16, blocks_per_track=32, rotation_delay=0.001):
        self.tracks = tracks
        self.blocks_per_track = blocks_per_track
        self.rotation_delay = rotation_delay
        self.blocks = {}
        self.current_block = 0
        self.lock = _vmax_threading.RLock()

    @property
    def capacity(self):
        return self.tracks * self.blocks_per_track

    def _latency(self, block):
        distance = (int(block) - self.current_block) % self.capacity
        _vmax_time.sleep(distance * self.rotation_delay)
        self.current_block = int(block) % self.capacity

    def write(self, block, value):
        with self.lock:
            if not 0 <= int(block) < self.capacity:
                raise IndexError("drum block out of range")
            self._latency(block)
            self.blocks[int(block)] = value
            return value

    def read(self, block):
        with self.lock:
            self._latency(block)
            return self.blocks.get(int(block), 0)


class VMAXFerriteCoreMemory:
    def __init__(self, capacity=4096):
        self.capacity = capacity
        self.bits = [False] * capacity
        self.lock = _vmax_threading.RLock()

    def write_bit(self, address, value):
        if not 0 <= int(address) < self.capacity:
            raise IndexError("core address out of range")
        with self.lock:
            self.bits[int(address)] = bool(value)
            return self.bits[int(address)]

    def read_bit(self, address):
        if not 0 <= int(address) < self.capacity:
            raise IndexError("core address out of range")
        with self.lock:
            value = self.bits[int(address)]
            self.bits[int(address)] = False  # destructive read
            return value

    def read_restore(self, address):
        value = self.read_bit(address)
        self.write_bit(address, value)
        return value


class VMAXMechanicalTabulator:
    def __init__(self):
        self.counters = {}
        self.card_count = 0
        self.jammed = False

    def feed_card(self, fields):
        if self.jammed:
            raise RuntimeError("tabulator is jammed")
        self.card_count += 1
        for key, value in dict(fields).items():
            self.counters[key] = self.counters.get(key, 0) + value
        return dict(self.counters)

    def jam(self):
        self.jammed = True

    def clear_jam(self):
        self.jammed = False


class VMAXPlugboard:
    def __init__(self):
        self.routes = {}
        self.enabled = True

    def patch(self, source, destination):
        self.routes[str(source)] = str(destination)

    def route(self, source):
        if not self.enabled:
            raise RuntimeError("plugboard disabled")
        return self.routes.get(str(source), str(source))


class VMAXHistoricalOperatorConsole:
    def __init__(self):
        self.messages = []
        self.commands = _vmax_deque()

    def write(self, message):
        entry = {"time": _vmax_time.time(), "message": str(message)}
        self.messages.append(entry)
        return entry

    def submit(self, command):
        self.commands.append(str(command))
        return len(self.commands)

    def receive(self):
        return self.commands.popleft() if self.commands else None


class VMAXPrimitiveHistoricalLayer:
    """Unified façade for pre-mainframe hardware and operator emulation."""
    def __init__(self):
        self.relay = VMAXRelayComputer()
        self.tubes = VMAXTubeRack()
        self.paper_tape = VMAXPaperTape()
        self.delay_line = VMAXMercuryDelayLine()
        self.williams_memory = VMAXWilliamsKilburnMemory()
        self.drum = VMAXMagneticDrum()
        self.core = VMAXFerriteCoreMemory()
        self.tabulator = VMAXMechanicalTabulator()
        self.plugboard = VMAXPlugboard()
        self.console = VMAXHistoricalOperatorConsole()
        self.instance_id = str(_vmax_uuid.uuid4())

    def diagnostics(self):
        return {
            "instance_id": self.instance_id,
            "relay_cycles": self.relay.cycles,
            "tube_count": len(self.tubes.tubes),
            "paper_tape_bytes": len(self.paper_tape.data),
            "delay_line_depth": len(self.delay_line.buffer),
            "williams_cells": len(self.williams_memory.cells),
            "drum_blocks": len(self.drum.blocks),
            "core_capacity": self.core.capacity,
            "tabulator_cards": self.tabulator.card_count,
            "plugboard_routes": len(self.plugboard.routes),
            "console_messages": len(self.console.messages),
        }


def vmax_create_primitive_historical_layer():
    return VMAXPrimitiveHistoricalLayer()


VMAX_PRIMITIVE_HISTORICAL_LAYER_READY = True



# ============================================================================
# VMAX MAGIC STAFF / MANA COMBAT
# ----------------------------------------------------------------------------
# Optional extraction-shooter side system:
#   - staff/caster weapon can spend Mana to fire server-authoritative spells
#   - spells are real server projectiles with finite lifetime/range
#   - normal ballistic bullets can intercept and destroy magic projectiles
#   - Mana regenerates slowly; spell costs prevent unlimited casting
#   - this does NOT turn ordinary firearms into duel weapons
# ============================================================================
VMAX_MAGIC_LOCK = threading.RLock()
VMAX_MAGIC_STATE = {}
VMAX_MAGIC_PROJECTILES = {}
VMAX_MAGIC_CAP = 100.0
VMAX_MAGIC_REGEN_PER_SEC = 5.0
VMAX_MAGIC_TICK = 1.0 / 60.0

VMAX_MAGIC_SPELLS = {
    "firebolt": {"cost": 18.0, "speed": 34.0, "damage": 34.0, "radius": 0.48, "range": 55.0, "life": 2.0},
    "arcane_bolt": {"cost": 12.0, "speed": 42.0, "damage": 22.0, "radius": 0.32, "range": 70.0, "life": 2.0},
    "lightning": {"cost": 30.0, "speed": 55.0, "damage": 52.0, "radius": 0.28, "range": 65.0, "life": 1.5},
}


def _vmax_magic_player(uid):
    uid = str(uid)
    with VMAX_MAGIC_LOCK:
        st = VMAX_MAGIC_STATE.get(uid)
        if st is None:
            st = {"uid": uid, "mana": VMAX_MAGIC_CAP, "max_mana": VMAX_MAGIC_CAP,
                  "last_update": time.time(), "staff": False, "casts": 0}
            VMAX_MAGIC_STATE[uid] = st
        now = time.time()
        dt = max(0.0, min(5.0, now - float(st.get("last_update", now))))
        st["mana"] = min(VMAX_MAGIC_CAP, float(st.get("mana", 0.0)) + dt * VMAX_MAGIC_REGEN_PER_SEC)
        st["last_update"] = now
        return st


def _vmax_magic_weapon_ok(uid):
    """Magic is opt-in: only an explicit staff/caster weapon can cast."""
    try:
        st = VMAX_MOUNTED_EXTRACTION_COMBAT.get(str(uid), {})
        w = str(st.get("weapon_id") or st.get("weapon") or "").strip().lower()
        return w in {"magic_staff", "staff", "wizard_staff", "wand", "arcane_staff"}
    except Exception:
        return False


def vmax_magic_cast(uid, spell, direction):
    uid = str(uid)
    spell = str(spell or "firebolt").strip().lower()
    profile = VMAX_MAGIC_SPELLS.get(spell)
    if not profile:
        return False, {"reason": "unknown_spell"}
    if not _finite3(direction):
        return False, {"reason": "invalid_direction"}
    pawn = _pawn_by_uid(uid)
    if not pawn or not pawn.get("alive", True):
        return False, {"reason": "caster_not_found"}
    if not _vmax_magic_weapon_ok(uid):
        return False, {"reason": "staff_required"}
    dx, dy, dz = map(float, direction)
    mag = math.sqrt(dx*dx + dy*dy + dz*dz)
    if mag < 1e-6:
        return False, {"reason": "zero_direction"}
    dx, dy, dz = dx/mag, dy/mag, dz/mag
    with VMAX_MAGIC_LOCK:
        st = _vmax_magic_player(uid)
        if st["mana"] < profile["cost"]:
            return False, {"reason": "not_enough_mana", "mana": round(st["mana"], 2)}
        st["mana"] -= profile["cost"]
        st["casts"] += 1
        pid = uuid.uuid4().hex[:12]
        VMAX_MAGIC_PROJECTILES[pid] = {
            "projectile_id": pid, "owner": uid, "spell": spell,
            "x": float(pawn.get("x", 0.0)), "y": float(pawn.get("y", 0.0)), "z": 1.45,
            "vx": dx * profile["speed"], "vy": dy * profile["speed"], "vz": dz * profile["speed"],
            "distance": 0.0, "age": 0.0, "status": "flying",
            "damage": profile["damage"], "radius": profile["radius"],
            "range": profile["range"], "life": profile["life"], "created_at": time.time(),
        }
        result = dict(VMAX_MAGIC_PROJECTILES[pid])
        result["mana"] = round(st["mana"], 2)
    sio.emit("magic_cast", result, room=uid)
    return True, result


def vmax_magic_tick(dt=VMAX_MAGIC_TICK):
    now = time.time()
    # Regen for known casters even while they are not casting.
    with VMAX_MAGIC_LOCK:
        for uid in list(VMAX_MAGIC_STATE):
            _vmax_magic_player(uid)
        projectiles = list(VMAX_MAGIC_PROJECTILES.items())

    for pid, s in projectiles:
        if s.get("status") != "flying":
            continue
        ox, oy, oz = s["x"], s["y"], s["z"]
        s["x"] += s["vx"] * dt
        s["y"] += s["vy"] * dt
        s["z"] += s["vz"] * dt
        s["age"] += dt
        s["distance"] += math.sqrt((s["x"]-ox)**2 + (s["y"]-oy)**2 + (s["z"]-oz)**2)

        # Firearms are a hard counter: if a live ballistic projectile crosses
        # the spell segment, the spell is cancelled before it can hit a player.
        bullet_break = False
        with BALLISTIC_LOCK:
            for bid, b in BALLISTIC_PROJECTILES.items():
                if b.get("status") != "flying" or b.get("owner") == s.get("owner"):
                    continue
                if _point_segment_distance_sq(s["x"], s["y"], s["z"],
                                               ox, oy, oz, b.get("x", 0), b.get("y", 0), b.get("z", 0)) <= (s["radius"] + 0.38) ** 2:
                    bullet_break = True
                    break
        if bullet_break:
            s["status"] = "shot_down"
            sio.emit("magic_shot_down", {"projectile_id": pid, "spell": s["spell"],
                                          "x": s["x"], "y": s["y"], "z": s["z"]})
            continue

        if s["z"] <= 0.0 or s["distance"] >= s["range"] or s["age"] >= s["life"]:
            s["status"] = "expired"
            continue

        with _PAWNS_LOCK:
            pawns = [(sid2, dict(p)) for sid2, p in PLAYER_PAWNS.items()]
        for target_sid, pawn in pawns:
            target_uid = PLAYERS.get(target_sid, {}).get("uid", target_sid)
            if target_uid == s["owner"] or not pawn.get("alive", True):
                continue
            tx, ty, tz = float(pawn.get("x", 0)), float(pawn.get("y", 0)), 1.45
            if _point_segment_distance_sq(tx, ty, tz, ox, oy, oz, s["x"], s["y"], s["z"]) <= (0.72 + s["radius"]) ** 2:
                pawn["hp"] = max(0, float(pawn.get("hp", 100)) - s["damage"])
                with _PAWNS_LOCK:
                    if target_sid in PLAYER_PAWNS:
                        PLAYER_PAWNS[target_sid]["hp"] = pawn["hp"]
                        PLAYER_PAWNS[target_sid]["alive"] = pawn["hp"] > 0
                s["status"] = "hit"
                s["hit_uid"] = target_uid
                payload = {"projectile_id": pid, "owner": s["owner"], "spell": s["spell"],
                           "hit_uid": target_uid, "damage": s["damage"],
                           "x": s["x"], "y": s["y"], "z": s["z"]}
                sio.emit("magic_hit", payload, room=s["owner"])
                sio.emit("magic_hit", payload, room=target_uid)
                break

    with VMAX_MAGIC_LOCK:
        for pid, s in list(VMAX_MAGIC_PROJECTILES.items()):
            if s.get("status") != "flying" and now - s.get("created_at", now) > 5.0:
                VMAX_MAGIC_PROJECTILES.pop(pid, None)


def vmax_magic_public_state(uid=None):
    uid = str(uid) if uid else None
    with VMAX_MAGIC_LOCK:
        out = {}
        for pid, s in VMAX_MAGIC_PROJECTILES.items():
            if uid and s.get("owner") != uid:
                continue
            out[pid] = {k: s.get(k) for k in
                        ("projectile_id", "owner", "spell", "x", "y", "z", "vx", "vy", "vz",
                         "distance", "age", "status", "hit_uid")}
        states = {u: {"mana": round(float(_vmax_magic_player(u)["mana"]), 2),
                      "max_mana": VMAX_MAGIC_CAP, "casts": VMAX_MAGIC_STATE[u].get("casts", 0)}
                  for u in list(VMAX_MAGIC_STATE)}
    return {"projectiles": out, "players": states}


