@app.route('/api/github/octocat', methods=['GET'])
def api_get_octocat_profile():
    # ดึงข้อมูลจาก GitHub API (แมวปลาหมึก)
    # แก้จากเดิม: https://github.com คืนหน้า HTML ทำให้ resp.json() พังทุกครั้ง -> ต้องเรียก api.github.com/users/octocat
    url = "https://api.github.com/users/octocat"
    headers = {"User-Agent": "VMAX-Kernel-App", "Accept": "application/vnd.github+json"}
    # token ไม่ฝังในโค้ด: อ่านจาก env (VMAX_GITHUB_TOKEN / GITHUB_TOKEN) หรือที่ที่เก็บแบบเข้ารหัส
    # ตั้งแบบมีคนพาทำได้ด้วยคำสั่ง github-token ใน --mcp-console
    gh_token = vmax_github_token_get()
    if gh_token:
        headers["Authorization"] = f"Bearer {gh_token}"
    try:
        import requests as _vmax_gh_requests
        resp = _vmax_gh_requests.get(url, headers=headers, timeout=10)
        resp.raise_for_status()
        return jsonify({"st": "ok", "authenticated": bool(gh_token),
                        "rate_limit_remaining": resp.headers.get("X-RateLimit-Remaining"),
                        "github_data": resp.json()})
    except Exception as e:
        return jsonify({"st": "error", "msg": f"ต่อแมวปลาหมึกไม่สำเร็จ: {e}"}), 502

# ============================================================================
# DEVICE COMPATIBILITY GATE
# -----------------------------------------------------------------------------
# Checks client device facts against configurable minimum requirements.
# Unsupported devices receive the Thai warning with two choices: ออก / เล่นต่อ.
# This is a compatibility warning, not a security boundary.
# ============================================================================
VMAX_DEVICE_REQUIREMENTS = {
    "min_memory_mb": int(os.environ.get("VMAX_MIN_MEMORY_MB", "2048")),
    "min_cpu_cores": int(os.environ.get("VMAX_MIN_CPU_CORES", "4")),
    "min_screen_width": int(os.environ.get("VMAX_MIN_SCREEN_WIDTH", "960")),
    "min_screen_height": int(os.environ.get("VMAX_MIN_SCREEN_HEIGHT", "540")),
    "require_webgl": os.environ.get("VMAX_REQUIRE_WEBGL", "0") == "1",
}

def vmax_check_device_compatibility(device=None):
    device = device or {}
    req = VMAX_DEVICE_REQUIREMENTS
    checks = {
        "memory": int(device.get("memory_mb", 0) or 0) >= req["min_memory_mb"],
        "cpu": int(device.get("cpu_cores", 0) or 0) >= req["min_cpu_cores"],
        "screen": (int(device.get("screen_width", 0) or 0) >= req["min_screen_width"] and
                   int(device.get("screen_height", 0) or 0) >= req["min_screen_height"]),
        "webgl": (not req["require_webgl"]) or bool(device.get("webgl", False)),
    }
    supported = all(checks.values())
    return {"supported": supported, "checks": checks, "requirements": dict(req),
            "message": "อุปกรณ์ของคุณไม่ถึงเกณฑ์ตรงตามกำหนด" if not supported else "อุปกรณ์รองรับ"}

@app.post('/api/device/compatibility')
def vmax_device_compatibility_api():
    return jsonify(vmax_check_device_compatibility(request.get_json(silent=True) or {}))

