# ============================================================================
# VMAX PRIMITIVE COMPUTING / PRE-ELECTRONIC COMPATIBILITY LAYER
# Historical emulation: tally, abacus, water clock, gears, analog scales,
# Napier bones, Pascaline, stepped drum, Jacquard cards, and Babbage model.
# ============================================================================

class VMAXManualTally:
    def __init__(self, value=0):
        self.value = int(value)
    def add(self, amount=1):
        self.value += int(amount)
        return self.value
    def subtract(self, amount=1):
        self.value -= int(amount)
        return self.value
    def reset(self):
        self.value = 0
        return self.value
    def read(self):
        return self.value


class VMAXAbacusRegister:
    def __init__(self, rods=10, base=10):
        self.base = int(base)
        self.rods = [0] * int(rods)
    def set(self, value):
        value = int(value)
        for i in range(len(self.rods)):
            self.rods[i] = value % self.base
            value //= self.base
        return self.read()
    def add(self, value):
        return self.set(self.read() + int(value))
    def subtract(self, value):
        return self.set(self.read() - int(value))
    def read(self):
        total = 0
        multiplier = 1
        for digit in self.rods:
            total += digit * multiplier
            multiplier *= self.base
        return total


class VMAXWaterClock:
    def __init__(self, capacity=100, level=0, flow_rate=1):
        self.capacity = float(capacity)
        self.level = float(level)
        self.flow_rate = float(flow_rate)
        self.ticks = 0
        self.blocked = False
    def advance(self, units=1):
        if not self.blocked:
            self.level += self.flow_rate * float(units)
            self.ticks += int(units)
            if self.level > self.capacity:
                self.level = self.capacity
        return self.level
    def drain(self, amount):
        self.level = max(0.0, self.level - float(amount))
        return self.level
    def overflowed(self):
        return self.level >= self.capacity
    def reset(self):
        self.level = 0.0
        self.ticks = 0
        return self.level


class VMAXGearMechanism:
    def __init__(self, teeth_a=10, teeth_b=20):
        self.teeth_a = int(teeth_a)
        self.teeth_b = int(teeth_b)
        self.angle_a = 0.0
        self.angle_b = 0.0
    @property
    def ratio(self):
        return self.teeth_a / self.teeth_b
    def rotate_a(self, degrees):
        self.angle_a = (self.angle_a + float(degrees)) % 360.0
        self.angle_b = (self.angle_b - float(degrees) * self.ratio) % 360.0
        return self.angle_a, self.angle_b


class VMAXAnalogScale:
    def __init__(self, scale=1.0, precision=3):
        self.scale = float(scale)
        self.precision = int(precision)
    def multiply(self, a, b):
        return round(float(a) * float(b), self.precision)
    def divide(self, a, b):
        if float(b) == 0:
            raise ZeroDivisionError("analog scale division by zero")
        return round(float(a) / float(b), self.precision)
    def logarithmic(self, value):
        import math
        if value <= 0:
            raise ValueError("logarithmic scale requires positive value")
        return round(math.log10(float(value)) * self.scale, self.precision)


class VMAXNapierBones:
    def multiply(self, a, b):
        return int(a) * int(b)
    def divide(self, a, b):
        if int(b) == 0:
            raise ZeroDivisionError("Napier division by zero")
        return int(a) // int(b)


class VMAXPascaline:
    def __init__(self, digits=8):
        self.digits = int(digits)
        self.modulus = 10 ** self.digits
        self.value = 0
    def add(self, value):
        self.value = (self.value + int(value)) % self.modulus
        return self.value
    def subtract(self, value):
        self.value = (self.value - int(value)) % self.modulus
        return self.value
    def overflow(self, value):
        return abs(int(value)) >= self.modulus
    def read(self):
        return self.value


class VMAXSteppedDrumEngine:
    def __init__(self):
        self.accumulator = 0
        self.step_count = 0
    def step_add(self, value, steps=1):
        self.accumulator += int(value) * int(steps)
        self.step_count += int(steps)
        return self.accumulator
    def step_subtract(self, value, steps=1):
        self.accumulator -= int(value) * int(steps)
        self.step_count += int(steps)
        return self.accumulator
    def multiply(self, a, b):
        return self.step_add(a, abs(int(b))) if int(b) >= 0 else self.step_subtract(a, abs(int(b)))
    def reset(self):
        self.accumulator = 0
        self.step_count = 0


class VMAXJacquardProgramDeck:
    def __init__(self, cards=None):
        self.cards = list(cards or [])
        self.position = 0
    def insert(self, pattern):
        self.cards.append(pattern)
    def rewind(self):
        self.position = 0
    def read(self):
        if self.position >= len(self.cards):
            return None
        item = self.cards[self.position]
        self.position += 1
        return item
    def remaining(self):
        return len(self.cards) - self.position


class VMAXBabbageAnalyticalModel:
    def __init__(self, store_size=1024):
        self.store = [0] * int(store_size)
        self.accumulator = 0
        self.program = []
        self.ip = 0
    def load(self, address, value):
        self.store[int(address)] = int(value)
    def fetch(self):
        if self.ip >= len(self.program):
            return None
        instruction = self.program[self.ip]
        self.ip += 1
        return instruction
    def execute(self, instruction):
        if instruction is None:
            return None
        opcode = instruction[0]
        args = instruction[1:]
        if opcode == "LOAD":
            self.accumulator = self.store[int(args[0])]
        elif opcode == "STORE":
            self.store[int(args[0])] = self.accumulator
        elif opcode == "ADD":
            self.accumulator += int(args[0])
        elif opcode == "SUB":
            self.accumulator -= int(args[0])
        elif opcode == "MUL":
            self.accumulator *= int(args[0])
        elif opcode == "HALT":
            self.ip = len(self.program)
        else:
            raise ValueError("unknown Babbage opcode: " + str(opcode))
        return self.accumulator
    def run(self, program=None):
        if program is not None:
            self.program = list(program)
            self.ip = 0
        result = None
        while self.ip < len(self.program):
            result = self.execute(self.fetch())
        return result


class VMAXPrimitiveComputingLayer:
    def __init__(self):
        self.tally = VMAXManualTally()
        self.abacus = VMAXAbacusRegister()
        self.water_clock = VMAXWaterClock()
        self.gears = VMAXGearMechanism()
        self.analog = VMAXAnalogScale()
        self.napier = VMAXNapierBones()
        self.pascaline = VMAXPascaline()
        self.stepped_drum = VMAXSteppedDrumEngine()
        self.jacquard = VMAXJacquardProgramDeck()
        self.babbage = VMAXBabbageAnalyticalModel()
    def diagnostics(self):
        return {
            "tally": self.tally.read(),
            "abacus": self.abacus.read(),
            "water_clock_level": self.water_clock.level,
            "gear_angles": (self.gears.angle_a, self.gears.angle_b),
            "pascaline": self.pascaline.read(),
            "stepped_drum_accumulator": self.stepped_drum.accumulator,
            "jacquard_remaining": self.jacquard.remaining(),
            "babbage_accumulator": self.babbage.accumulator,
        }


def vmax_create_primitive_computing_layer():
    return VMAXPrimitiveComputingLayer()


