def _vmax_exauction_uid(value=None):
    # JWT identity always wins over client-supplied uid.
    try:
        auth_uid = getattr(request, "vmax_uid", None)
        uid = str(auth_uid or value or request.args.get("uid") or P.get("uid") or VMAX_EXTRACTION_AUCTION_DEFAULT_UID).strip()
    except Exception:
        uid = str(value or VMAX_EXTRACTION_AUCTION_DEFAULT_UID).strip()
    return uid or VMAX_EXTRACTION_AUCTION_DEFAULT_UID


def _vmax_exauction_build_catalog():
    catalog = [dict(x) for x in VMAX_EXTRACTION_AUCTION_FEATURED]
    rarity_cycle = ["gray","gray","green","green","blue","purple","orange","red"]
    kind_cycle = list(VMAX_EXTRACTION_AUCTION_KIND_LABELS)
    for i in range(len(catalog), 470):
        n = i + 1
        rarity = rarity_cycle[i % len(rarity_cycle)]
        kind = kind_cycle[i % len(kind_cycle)]
        sil = VMAX_EXTRACTION_AUCTION_SILHOUETTES[i % len(VMAX_EXTRACTION_AUCTION_SILHOUETTES)]
        mult = VMAX_EXTRACTION_AUCTION_RARITIES[rarity]["mult"]
        base = 650 + ((i * 7919) % 240000)
        price = int(max(900, base * mult))
        catalog.append({
            "id": f"auction_item_{n:03d}",
            "name": f"Extraction Item {n:03d}",
            "kind": kind,
            "rarity": rarity,
            "price": price,
            "value": max(50, int(price * 0.10)),
            "weight": round(0.2 + ((i * 17) % 38) / 10.0, 1),
            "silhouette": sil,
            "icon": "◆" if sil in ("crystal","relic") else "□",
        })
    return catalog


