def _vmax_exauction_player(uid):
    with VMAX_EXTRACTION_AUCTION_LOCK:
        p = VMAX_EXTRACTION_AUCTION_PLAYERS.setdefault(uid, {
            # วงจรเศรษฐกิจตามภาพ: เงินเกม -> Auction Coin -> Ticket -> เข้า Raid ->
            # เก็บของ -> ถอนกำลัง -> ขายของ -> Auction Coin -> ซื้อ Ticket รอบถัดไป
            "cash": 638000,
            "auction_coins": 0,
            "tickets": 0,
            "purchased": {},
            "selected_operator": VMAX_EXTRACTION_AUCTION_OPERATORS[0]["id"],
            "active_match": None,
            "card_draws": [],
            "skill_state": {},
            "history": [],
        })
        return p


def _vmax_exauction_register_item_to_extraction(item):
    # Make auction loot visible to the existing extraction tier/stash system.
    item_id = item["id"]
    if "EXTRACTION_ITEM_DB" in globals():
        EXTRACTION_ITEM_DB.setdefault(item_id, {
            "name": item["name"],
            "rarity": {"gray":"common","green":"uncommon","blue":"rare","purple":"epic","orange":"legendary","red":"legendary"}.get(item["rarity"],"common"),
            "value": int(item.get("value", 0)),
            "weight": float(item.get("weight", 1.0)),
        })
    return item_id


def _vmax_exauction_add_stash(uid, item_id, qty=1):
    qty = max(1, int(qty))
    if "EXTRACTION_STASH" in globals():
        stash = EXTRACTION_STASH.setdefault(uid, {})
        stash[item_id] = int(stash.get(item_id, 0)) + qty
        return stash
    inv = INVENTORY.setdefault(uid, {}) if "INVENTORY" in globals() else {}
    inv[item_id] = int(inv.get(item_id, 0)) + qty
    return inv


def _vmax_exauction_card_for(p):
    if not p.get("card_draws"):
        return None
    return p["card_draws"][-1]


@app.route('/api/extraction/auction/state', methods=['GET'])
def api_vmax_exauction_state():
    uid = _vmax_exauction_uid()
    p = _vmax_exauction_player(uid)
    stash = dict(EXTRACTION_STASH.get(uid, {})) if "EXTRACTION_STASH" in globals() else dict(INVENTORY.get(uid, {}))
    return jsonify({
        "st":"ok", "version":VMAX_EXTRACTION_AUCTION_VERSION, "uid":uid,
        "wallet":{"cash":p["cash"],"auction_coins":p["auction_coins"],"tickets":p["tickets"]},
        "operators":VMAX_EXTRACTION_AUCTION_OPERATORS,
        "selected_operator":p["selected_operator"],
        "skill_used":p.get("skill_state",{}).get(p["selected_operator"],0) >= 1,
        "card":_vmax_exauction_card_for(p),
        "economy":{"cash_to_coin":{"cash":10000,"coins":11000},"coin_to_ticket":{"coins":20000,"tickets":1}},
        "maps":VMAX_EXTRACTION_AUCTION_MAPS,
        "active_match":p["active_match"],
        "catalog_count":len(VMAX_EXTRACTION_AUCTION_CATALOG),
        "stash":stash,
        "recent_history":p["history"][-12:],
    })


@app.route('/api/extraction/auction/catalog', methods=['GET'])
def api_vmax_exauction_catalog():
    rarity = request.args.get("rarity", "all")
    kind = request.args.get("kind", "all")
    silhouette = request.args.get("silhouette", "all")
    q = request.args.get("q", "").strip().lower()
    out = []
    for item in VMAX_EXTRACTION_AUCTION_CATALOG:
        if rarity != "all" and item["rarity"] != rarity: continue
        if kind != "all" and item["kind"] != kind: continue
        if silhouette != "all" and item["silhouette"] != silhouette: continue
        if q and q not in item["name"].lower() and q not in item["id"].lower(): continue
        out.append(item)
    return jsonify({"st":"ok","total":len(out),"items":out[:500],
                    "filters":{"rarities":VMAX_EXTRACTION_AUCTION_RARITIES,"kinds":VMAX_EXTRACTION_AUCTION_KIND_LABELS,
                               "silhouettes":VMAX_EXTRACTION_AUCTION_SILHOUETTES}})


@app.route('/api/extraction/auction/buy-coins', methods=['POST'])
def api_vmax_exauction_buy_coins():
    uid = _vmax_exauction_uid((request.get_json(silent=True) or {}).get("uid"))
    body = request.get_json(silent=True) or {}
    qty = max(1, min(100, int(body.get("qty", 1))))
    p = _vmax_exauction_player(uid)
    cost = 10000 * qty
    coins = 11000 * qty
    if p["cash"] < cost:
        return jsonify({"st":"error","msg":"เครดิตไม่พอ"}), 400
    p["cash"] -= cost
    p["auction_coins"] += coins
    p["history"].append({"type":"coin_exchange","cost":cost,"coins":coins,"at":time.time()})
    return jsonify({"st":"ok","msg":f"ได้รับ Auction Coin x{coins:,}","wallet":p})


@app.route('/api/extraction/auction/buy', methods=['POST'])
def api_vmax_exauction_buy():
    body = request.get_json(silent=True) or {}
    uid = _vmax_exauction_uid(body.get("uid"))
    item_id = str(body.get("item_id", ""))
    qty = max(1, min(99, int(body.get("qty", 1))))
    item = VMAX_EXTRACTION_AUCTION_BY_ID.get(item_id)
    if not item:
        return jsonify({"st":"error","msg":"ไม่พบรายการประมูล"}), 404
    p = _vmax_exauction_player(uid)
    total = int(item["price"]) * qty
    if p["auction_coins"] < total:
        return jsonify({"st":"error","msg":"Auction Coin ไม่พอ"}), 400
    p["auction_coins"] -= total
    p["purchased"][item_id] = int(p["purchased"].get(item_id, 0)) + qty
    _vmax_exauction_register_item_to_extraction(item)
    stash = _vmax_exauction_add_stash(uid, item_id, qty)
    p["history"].append({"type":"buy","item":item_id,"qty":qty,"cost":total,"at":time.time()})
    return jsonify({"st":"ok","msg":f"ซื้อ {item['name']} x{qty} สำเร็จ","wallet":p,"stash":stash,"item":item})


@app.route('/api/extraction/auction/select-operator', methods=['POST'])
def api_vmax_exauction_select_operator():
    body = request.get_json(silent=True) or {}
    uid = _vmax_exauction_uid(body.get("uid"))
    op = next((x for x in VMAX_EXTRACTION_AUCTION_OPERATORS if x["id"] == body.get("operator_id")), None)
    if not op:
        return jsonify({"st":"error","msg":"ไม่พบ Operator"}), 404
    p = _vmax_exauction_player(uid)
    p["selected_operator"] = op["id"]
    return jsonify({"st":"ok","operator":op})


@app.route('/api/extraction/auction/draw-card', methods=['POST'])
def api_vmax_exauction_draw_card():
    body = request.get_json(silent=True) or {}
    uid = _vmax_exauction_uid(body.get("uid"))
    p = _vmax_exauction_player(uid)
    # Draw is free once per matchmaking session; additional draws are limited
    # by the number of completed sessions, keeping it gameplay-only.
    if len(p["card_draws"]) >= 3 and not p.get("active_match"):
        return jsonify({"st":"error","msg":"โควตาการ์ดเต็มสำหรับรอบนี้"}), 400
    card = dict(random.choice(VMAX_EXTRACTION_AUCTION_CARDS))
    card["effect_multiplier"] = random.randint(1, 3)
    card["drawn_at"] = time.time()
    p["card_draws"].append(card)
    return jsonify({"st":"ok","msg":"ได้รับการ์ดผลพิเศษ","card":card})



@app.route('/api/extraction/auction/buy-ticket', methods=['POST'])
def api_vmax_exauction_buy_ticket():
    body = request.get_json(silent=True) or {}
    uid = _vmax_exauction_uid(body.get("uid"))
    qty = max(1, min(100, int(body.get("qty", 1))))
    p = _vmax_exauction_player(uid)
    # ภาพอ้างอิงแสดง Ticket 20,000 และ Auction Coin เป็นสกุลเงินกิจกรรม
    cost = 20000 * qty
    if p["auction_coins"] < cost:
        return jsonify({"st":"error","msg":f"Auction Coin ไม่พอ ต้องใช้ {cost:,} Coin"}), 400
    p["auction_coins"] -= cost
    p["tickets"] += qty
    p["history"].append({"type":"ticket_buy","qty":qty,"cost":cost,"at":time.time()})
    return jsonify({"st":"ok","msg":f"ซื้อ Ticket x{qty} สำเร็จ","wallet":p})


@app.route('/api/extraction/auction/sell-loot', methods=['POST'])
def api_vmax_exauction_sell_loot():
    body = request.get_json(silent=True) or {}
    uid = _vmax_exauction_uid(body.get("uid"))
    item_id = str(body.get("item_id", ""))
    qty = max(1, min(999, int(body.get("qty", 1))))
    p = _vmax_exauction_player(uid)
    stash = EXTRACTION_STASH.setdefault(uid, {}) if "EXTRACTION_STASH" in globals() else INVENTORY.setdefault(uid, {})
    have = int(stash.get(item_id, 0))
    if have < qty:
        return jsonify({"st":"error","msg":"ของในคลังไม่พอ"}), 400
    db = EXTRACTION_ITEM_DB.get(item_id, {}) if "EXTRACTION_ITEM_DB" in globals() else {}
    base_value = int(db.get("value", 0))
    if base_value <= 0:
        auction_item = VMAX_EXTRACTION_AUCTION_BY_ID.get(item_id)
        base_value = int(auction_item.get("value", 0)) if auction_item else 0
    if base_value <= 0:
        return jsonify({"st":"error","msg":"ไอเทมนี้ขายใน Auction Market ไม่ได้"}), 400
    # ราคาขายเป็น Auction Coin ตามมูลค่าไอเทมในเกม
    earned = max(1, base_value) * qty
    stash[item_id] = have - qty
    p["auction_coins"] += earned
    p["history"].append({"type":"sell","item":item_id,"qty":qty,"coins":earned,"at":time.time()})
    return jsonify({"st":"ok","msg":f"ขายสำเร็จ +{earned:,} Auction Coin","earned":earned,"wallet":p,"stash":dict(stash)})


@app.route('/api/extraction/auction/skill', methods=['POST'])
def api_vmax_exauction_skill():
    body = request.get_json(silent=True) or {}
    uid = _vmax_exauction_uid(body.get("uid"))
    p = _vmax_exauction_player(uid)
    if not p.get("active_match"):
        return jsonify({"st":"error","msg":"ต้องอยู่ใน Raid ก่อนใช้ Skill"}), 400
    op = next(x for x in VMAX_EXTRACTION_AUCTION_OPERATORS if x["id"] == p["selected_operator"])
    used = int(p.setdefault("skill_state", {}).get(op["id"], 0))
    if used >= 1:
        return jsonify({"st":"error","msg":"Skill นี้ใช้ไปแล้วในรอบนี้"}), 400
    p["skill_state"][op["id"]] = used + 1
    effect = {"operator":op["id"],"skill":op["skill"],"description":op["skill_desc"]}
    raid = EXTRACTION_RAIDS.get(uid) if "EXTRACTION_RAIDS" in globals() else None
    if raid:
        raid.setdefault("skill_effects", []).append(effect)
        if op["id"] == "operator_kilo": raid["capacity"] += 4
        elif op["id"] == "operator_ivy": raid["carry"]["med_kit"] = raid["carry"].get("med_kit", 0) + 1
        elif op["id"] == "operator_ash": raid["carry"]["electronics"] = raid["carry"].get("electronics", 0) + 1
    p["history"].append({"type":"skill","skill":op["skill"],"at":time.time()})
    return jsonify({"st":"ok","msg":f"ใช้ {op['skill']} แล้ว","effect":effect,"raid":extraction_raid_state(uid) if "extraction_raid_state" in globals() else raid})


@app.route('/api/extraction/auction/match/start', methods=['POST'])
def api_vmax_exauction_match_start():
    body = request.get_json(silent=True) or {}
    uid = _vmax_exauction_uid(body.get("uid"))
    map_id = str(body.get("map", "warehouse"))
    map_info = VMAX_EXTRACTION_AUCTION_MAP_BY_ID.get(map_id)
    if not map_info:
        return jsonify({"st":"error","msg":"ไม่พบแผนที่"}), 404
    p = _vmax_exauction_player(uid)
    if p.get("active_match"):
        return jsonify({"st":"error","msg":"มี Match ที่กำลังค้นหาอยู่แล้ว","match":p["active_match"]}), 409
    op = next(x for x in VMAX_EXTRACTION_AUCTION_OPERATORS if x["id"] == p["selected_operator"])
    fee = int(map_info["entry_fee"])
    if op["id"] == "operator_sable":
        fee = int(fee * 0.90)
    # Ticket เป็นบัตรผ่านของ Auction Raid ตามกลไกในภาพ: 1 รอบใช้ 1 Ticket
    # ส่วน entry_fee ยังคงเป็นค่าลงสนามที่แสดงในหน้า Matching
    if p["cash"] < fee or p["tickets"] < 1:
        return jsonify({"st":"error","msg":"เครดิตหรือตั๋วไม่พอ (ต้องมี 1 Ticket)"}), 400
    p["cash"] -= fee
    p["tickets"] -= 1
    p["skill_state"] = {}
    # Bridge directly into the existing extraction raid system.
    raid = None
    raid_msg = ""
    if "extraction_raid_start" in globals():
        ok, raid_msg, raid = extraction_raid_start(uid, map_id, capacity=14 if op["id"] == "operator_kilo" else 12)
        if not ok:
            p["cash"] += fee
            p["tickets"] += int(map_info["ticket"])
            return jsonify({"st":"error","msg":raid_msg}), 409
    match = {
        "match_id": uuid.uuid4().hex[:10], "map":map_id, "map_name":map_info["name"],
        "players":int(map_info["players"]), "entry_fee":fee, "ticket":int(map_info["ticket"]),
        "operator":op["id"], "status":"raid_active", "started_at":time.time(),
        "raid_id": raid.get("raid_id") if isinstance(raid, dict) else None,
    }
    p["active_match"] = match
    p["history"].append({"type":"match_start","map":map_id,"match_id":match["match_id"],"at":time.time()})
    return jsonify({"st":"ok","msg":"Match เริ่มแล้วและเชื่อมเข้าระบบ Extraction Raid","match":match,"raid":extraction_raid_state(uid) if "extraction_raid_state" in globals() else raid,"wallet":p})


@app.route('/api/extraction/auction/match/finish', methods=['POST'])
def api_vmax_exauction_match_finish():
    body = request.get_json(silent=True) or {}
    uid = _vmax_exauction_uid(body.get("uid"))
    p = _vmax_exauction_player(uid)
    if not p.get("active_match"):
        return jsonify({"st":"error","msg":"ไม่มี Match ที่กำลังเล่น"}), 400
    extracted = bool(body.get("extracted", True))
    result = None
    if extracted and "extraction_extract" in globals():
        ok, msg, result = extraction_extract(uid)
        if not ok:
            return jsonify({"st":"error","msg":msg}), 400
    match = dict(p["active_match"])
    match["status"] = "extracted" if extracted else "left"
    match["finished_at"] = time.time()
    p["active_match"] = None
    p["history"].append({"type":"match_finish","match_id":match["match_id"],"extracted":extracted,"at":time.time()})
    # Reward cards are resolved at the end and remain informational rather than
    # bypassing the existing stash/economy systems.
    card = _vmax_exauction_card_for(p)
    reward_mult = int(card.get("effect_multiplier", 1)) if card else 1
    sellable_value = 0
    if extracted and isinstance(result, dict):
        for item_id, qty in result.get("extracted_items", {}).items():
            db = EXTRACTION_ITEM_DB.get(item_id, {}) if "EXTRACTION_ITEM_DB" in globals() else {}
            sellable_value += int(db.get("value", 0)) * int(qty)
    return jsonify({"st":"ok","msg":"ถอนกำลังสำเร็จ" if extracted else "จบรอบ","match":match,"raid_result":result,"card_multiplier":reward_mult,"sellable_auction_coin_value":sellable_value,"wallet":p})


VMAX_EXTRACTION_AUCTION_PAGE_HTML = r'''
<!doctype html><html lang="th"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>Extraction Shooter — Auction Hub</title>
<style>
:root{--bg:#090d0c;--panel:#121916;--panel2:#18201c;--line:#2d3932;--text:#e7eee8;--muted:#8e9a91;--lime:#b7f332;--cyan:#61e4cf;--red:#f45b67;--gold:#f1c75b}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 70% -10%,#20362c 0,#0a0e0c 42%,#060806 100%);color:var(--text);font-family:Inter,system-ui,sans-serif;min-height:100vh}.wrap{max-width:1280px;margin:auto;padding:18px}.top{display:flex;justify-content:space-between;gap:14px;align-items:center;border:1px solid var(--line);background:#0e1411e8;padding:14px 16px;border-radius:14px;position:sticky;top:8px;z-index:5;backdrop-filter:blur(10px)}.brand{font-weight:900;letter-spacing:.06em}.brand small{display:block;color:var(--muted);font-weight:600;letter-spacing:0}.wallet{display:flex;gap:8px;flex-wrap:wrap}.pill{border:1px solid var(--line);background:#111814;padding:8px 11px;border-radius:9px;font-size:12px}.pill b{color:var(--lime)}.tabs{display:flex;gap:7px;margin:14px 0;overflow:auto}.tabs button,.btn{border:1px solid var(--line);background:#131a16;color:var(--text);padding:9px 13px;border-radius:9px;cursor:pointer;font-weight:800}.tabs button.active,.btn.primary{background:var(--lime);color:#11170d;border-color:var(--lime)}.grid{display:grid;grid-template-columns:290px 1fr;gap:12px}.card{background:linear-gradient(180deg,#151d19,#0f1512);border:1px solid var(--line);border-radius:14px;padding:13px;box-shadow:0 10px 30px #0005}.card h2{font-size:15px;margin:0 0 10px}.filters{display:grid;gap:8px}.filters input,.filters select{width:100%;background:#0b100d;border:1px solid var(--line);color:var(--text);padding:9px;border-radius:8px}.catalog{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:9px}.item{min-height:150px;border:1px solid var(--line);background:#111713;border-radius:11px;padding:10px;position:relative;overflow:hidden}.item:before{content:"";position:absolute;inset:0;background:linear-gradient(135deg,transparent 50%,#ffffff05)}.icon{height:70px;display:grid;place-items:center;font-size:36px;background:#0a0e0c;border-radius:8px;margin-bottom:8px}.name{font-weight:800;font-size:12px}.meta{display:flex;justify-content:space-between;color:var(--muted);font-size:10px;margin:4px 0}.price{color:var(--gold);font-weight:900;font-size:12px}.buy{width:100%;margin-top:7px;padding:7px;border:0;border-radius:7px;background:#2b3930;color:#fff;font-weight:900;cursor:pointer}.buy:hover{background:#3b4b40}.rar-gray{box-shadow:inset 0 2px #8e9690}.rar-green{box-shadow:inset 0 2px #61dc78}.rar-blue{box-shadow:inset 0 2px #5c9dff}.rar-purple{box-shadow:inset 0 2px #c879ff}.rar-orange{box-shadow:inset 0 2px #ff9a55}.rar-red{box-shadow:inset 0 2px #ff4c61}.operator-grid,.map-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px}.operator,.map{border:1px solid var(--line);background:#101612;border-radius:12px;padding:11px;cursor:pointer}.operator.sel,.map.sel{outline:2px solid var(--lime)}.portrait{height:150px;border-radius:9px;display:grid;place-items:center;background:linear-gradient(135deg,#27322d,#0b0e0c);font-size:48px}.role{color:var(--cyan);font-size:11px}.effect{color:var(--muted);font-size:11px;line-height:1.4}.map-art{height:120px;border-radius:9px;background:radial-gradient(circle,#425b4b 1px,transparent 1px);background-size:12px 12px;display:grid;place-items:center;font-size:34px}.row{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:9px 0;border-bottom:1px solid #ffffff0d}.muted{color:var(--muted)}.notice{padding:10px;border:1px solid #9ab94c44;background:#9ab94c10;border-radius:9px;color:#d8e6bf;font-size:12px;margin-bottom:10px}.hero-title{display:flex;justify-content:space-between;align-items:center}.big{font-size:24px;font-weight:900}.hidden{display:none}.toast{position:fixed;right:16px;bottom:16px;max-width:340px;background:#151e18;border:1px solid var(--line);padding:11px 13px;border-radius:10px;display:none;z-index:9}.tiny{font-size:10px;color:var(--muted)}@media(max-width:800px){.grid{grid-template-columns:1fr}.top{position:static}.catalog{grid-template-columns:repeat(2,minmax(0,1fr))}.wrap{padding:10px}}
</style></head><body><div class="wrap">
<div class="top"><div class="brand">EXTRACTION / AUCTION HUB<small>ยิง • เก็บ • ถอนกำลัง • ซื้อขาย</small></div><div class="wallet"><div class="pill">เครดิต <b id="cash">-</b></div><div class="pill">Auction Coin <b id="coins">-</b></div><div class="pill">Ticket <b id="tickets">-</b></div></div></div>
<div class="tabs"><button class="active" onclick="tab('market',this)">Auction Catalog</button><button onclick="tab('operators',this)">Operators</button><button onclick="tab('match',this)">Matching / Map</button><button onclick="tab('stash',this)">Extraction Stash</button></div>
<section id="market"><div class="grid"><div class="card"><h2>ตัวกรอง</h2><div class="filters"><input id="q" placeholder="ค้นหาชื่อไอเทม" oninput="loadCatalog()"><select id="rarity" onchange="loadCatalog()"><option value="all">ทุก Rarity</option><option value="gray">Common</option><option value="green">Uncommon</option><option value="blue">Rare</option><option value="purple">Epic</option><option value="orange">Legendary</option><option value="red">Mythic</option></select><select id="kind" onchange="loadCatalog()"><option value="all">ทุกประเภท</option></select><select id="sil" onchange="loadCatalog()"><option value="all">ทุก Silhouette</option></select><button class="btn primary" onclick="buyCoins()">แลก 10,000 เครดิต → 11,000 Coin</button><button class="btn primary" onclick="buyTicket()">ซื้อ Ticket 1 ใบ = 20,000 Coin</button></div><div class="notice" style="margin-top:10px">Catalog <b id="count">470</b> รายการ · ซื้อแล้วเข้า Stash ของ Extraction โดยตรง</div></div><div class="card"><div class="hero-title"><h2>Shadow Auction Catalog</h2><span class="tiny">470 items</span></div><div id="catalog" class="catalog"></div></div></div></section>
<section id="operators" class="hidden"><div class="card"><div class="hero-title"><h2>Operator Selection</h2><button class="btn primary" onclick="drawCard()">สุ่ม Card Effect</button></div><div id="card" class="notice">ยังไม่ได้สุ่มการ์ด</div><div id="operators" class="operator-grid"></div><div style="margin-top:12px"><button class="btn primary" onclick="useSkill()">ใช้ Boss / Operator Skill</button></div></div></section>
<section id="match" class="hidden"><div class="card"><div class="hero-title"><h2>Matching Mode / Map Selection</h2><span class="pill">4 Players</span></div><div class="notice">ค่าลงเล่นและตั๋วจะถูกหักตอนเริ่ม Match และระบบจะเรียก Extraction Raid เดิมต่อทันที</div><div id="maps" class="map-grid"></div><div style="margin-top:12px"><button class="btn primary" onclick="startMatch()">เริ่ม Matching</button> <button class="btn" onclick="finishMatch(true)">ถอนกำลัง</button> <button class="btn" onclick="finishMatch(false)">ออกจากรอบ</button></div><div id="matchState" style="margin-top:12px"></div></div></section>
<section id="stash" class="hidden"><div class="grid"><div class="card"><h2>Extraction Stash</h2><div id="stashList"></div></div><div class="card"><h2>Recent Activity</h2><div id="history"></div></div></div></section>
</div><div id="toast" class="toast"></div>
<script>
const UID=new URLSearchParams(location.search).get('uid')||'guest';let STATE={};let selectedMap='warehouse';
async function j(url,opt={}){let r=await fetch(url,opt);return r.json()}
function money(n){return Number(n||0).toLocaleString()}
function toast(s){let x=document.getElementById('toast');x.textContent=s;x.style.display='block';setTimeout(()=>x.style.display='none',2200)}
function tab(id,btn){document.querySelectorAll('section').forEach(x=>x.classList.add('hidden'));document.getElementById(id).classList.remove('hidden');document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');if(id==='stash')renderStash()}
async function state(){let d=await j('/api/extraction/auction/state?uid='+encodeURIComponent(UID));if(d.st!=='ok')return;STATE=d;cash.textContent=money(d.wallet.cash);coins.textContent=money(d.wallet.auction_coins);tickets.textContent=money(d.wallet.tickets);renderOps();renderMaps();renderStash();}
async function loadFilters(){let d=await j('/api/extraction/auction/catalog');let k=document.getElementById('kind'),s=document.getElementById('sil');Object.entries(d.filters.kinds).forEach(([id,n])=>k.insertAdjacentHTML('beforeend',`<option value="${id}">${n}</option>`));d.filters.silhouettes.forEach(x=>s.insertAdjacentHTML('beforeend',`<option value="${x}">${x}</option>`));}
async function loadCatalog(){let u='/api/extraction/auction/catalog?rarity='+encodeURIComponent(rarity.value)+'&kind='+encodeURIComponent(kind.value)+'&silhouette='+encodeURIComponent(sil.value)+'&q='+encodeURIComponent(q.value);let d=await j(u);count.textContent=d.total;catalog.innerHTML=d.items.map(x=>`<div class="item rar-${x.rarity}"><div class="icon">${x.icon||'□'}</div><div class="name">${x.name}</div><div class="meta"><span>${x.kind}</span><span>${x.silhouette}</span></div><div class="price">${money(x.price)} Coin</div><button class="buy" onclick="buy('${x.id}')">ซื้อ</button></div>`).join('')}
async function buy(id){let d=await j('/api/extraction/auction/buy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid:UID,item_id:id,qty:1})});toast(d.msg||'');if(d.st==='ok')state()}
async function sellLoot(id,qty){let d=await j('/api/extraction/auction/sell-loot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid:UID,item_id:id,qty:qty})});toast(d.msg||'');if(d.st==='ok')state()}
async function buyCoins(){let d=await j('/api/extraction/auction/buy-coins',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid:UID,qty:1})});toast(d.msg||'');state()}
async function buyTicket(){let d=await j('/api/extraction/auction/buy-ticket',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid:UID,qty:1})});toast(d.msg||'');state()}
async function useSkill(){let d=await j('/api/extraction/auction/skill',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid:UID})});toast(d.msg||'');if(d.st==='ok')state()}
function renderOps(){operators.innerHTML=STATE.operators.map(o=>`<div class="operator ${STATE.selected_operator===o.id?'sel':''}" onclick="selectOp('${o.id}')"><div class="portrait">${o.id.split('_')[1][0].toUpperCase()}</div><b>${o.name}</b><div class="role">${o.role}</div><div class="effect">Passive: ${o.passive}</div><div class="effect">Skill: ${o.skill} — ${o.skill_desc}</div></div>`).join('');if(STATE.card)card.innerHTML=`<b>${STATE.card.name}</b> ×${STATE.card.effect_multiplier}<br><span class="muted">${STATE.card.desc}</span>`}
async function selectOp(id){let d=await j('/api/extraction/auction/select-operator',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid:UID,operator_id:id})});toast(d.msg||'เลือก Operator แล้ว');state()}
async function drawCard(){let d=await j('/api/extraction/auction/draw-card',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid:UID})});toast(d.msg||'');state()}
function renderMaps(){maps.innerHTML=STATE.maps.map(m=>`<div class="map ${selectedMap===m.id?'sel':''}" onclick="selectedMap='${m.id}';renderMaps()"><div class="map-art">⌁</div><b>${m.name}</b><div class="muted">${m.subtitle}</div><div class="meta"><span>Fee ${money(m.entry_fee)}</span><span>Ticket ${money(m.ticket)}</span></div><div class="tiny">${m.players} players · ${m.difficulty}</div></div>`).join('');matchState.innerHTML=STATE.active_match?`<div class="notice">Match ${STATE.active_match.match_id} · ${STATE.active_match.map_name} · ${STATE.active_match.status}</div>`:'ยังไม่มี Match'}
async function startMatch(){let d=await j('/api/extraction/auction/match/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid:UID,map:selectedMap})});toast(d.msg||'');if(d.st==='ok')state()}
async function finishMatch(extracted){let d=await j('/api/extraction/auction/match/finish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid:UID,extracted})});toast(d.msg||'');state()}
function renderStash(){let st=STATE.stash||{};stashList.innerHTML=Object.entries(st).filter(([k,v])=>v>0).map(([k,v])=>`<div class="row"><span>${k} <span class="tiny">x${v}</span></span><button class="btn" onclick="sellLoot('${k}',${v})">ขายทั้งหมด</button></div>`).join('')||'<div class="muted">คลังว่าง</div>';history.innerHTML=(STATE.recent_history||[]).slice().reverse().map(x=>`<div class="row"><span>${x.type}</span><span class="tiny">${new Date((x.at||0)*1000).toLocaleTimeString()}</span></div>`).join('')||'<div class="muted">ยังไม่มีกิจกรรม</div>'}
(async()=>{await loadFilters();await state();await loadCatalog()})();
</script></body></html>'''


