_VMAX_USB_KEY_FILE = ".vmax_employee_key.json"
_VMAX_USB_STORE = os.environ.get(
    "VMAX_USB_KEY_STORE",
    os.path.join(os.environ.get("VMAX_DATA_DIR", os.path.dirname(os.path.abspath(__file__))),
                 "vmax_usb_keys.json")
)
_VMAX_USB_LOCK = threading.RLock()
_VMAX_USB_SCAN_CACHE = {"ts": 0.0, "drives": []}

def _vmax_usb_load_store():
    with _VMAX_USB_LOCK:
        try:
            if not os.path.exists(_VMAX_USB_STORE):
                return {}
            with open(_VMAX_USB_STORE, "r", encoding="utf-8") as f:
                data = json.load(f)
            return data if isinstance(data, dict) else {}
        except Exception as e:
            print("[VMAX USB] store read error:", e)
            return {}

def _vmax_usb_save_store(data):
    parent = os.path.dirname(os.path.abspath(_VMAX_USB_STORE))
    os.makedirs(parent, exist_ok=True)
    tmp = _VMAX_USB_STORE + ".tmp"
    with _VMAX_USB_LOCK:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        os.replace(tmp, _VMAX_USB_STORE)

def _vmax_usb_token_digest(token):
    return hashlib.sha256(str(token).encode("utf-8")).hexdigest()

def _vmax_usb_drive_candidates():
    now = time.time()
    with _VMAX_USB_LOCK:
        if now - float(_VMAX_USB_SCAN_CACHE.get("ts", 0)) < 0.75:
            return list(_VMAX_USB_SCAN_CACHE.get("drives", []))
    roots = []
    system = platform.system().lower()
    try:
        if system == "windows":
            import ctypes
            bitmask = ctypes.windll.kernel32.GetLogicalDrives()
            get_type = ctypes.windll.kernel32.GetDriveTypeW
            for n in range(26):
                if bitmask & (1 << n):
                    root = chr(65 + n) + ":\\"
                    if int(get_type(root)) == 2:
                        roots.append(root)
        elif system == "darwin":
            vol = "/Volumes"
            if os.path.isdir(vol):
                roots = [os.path.join(vol, x) for x in os.listdir(vol)
                         if os.path.isdir(os.path.join(vol, x))]
        else:
            user = os.environ.get("USER") or os.environ.get("USERNAME") or ""
            bases = []
            if user:
                bases += [os.path.join("/media", user), os.path.join("/run/media", user)]
            bases += ["/mnt", "/media", "/run/media"]
            seen = set()
            for base in bases:
                if not os.path.isdir(base):
                    continue
                for name in os.listdir(base):
                    root = os.path.join(base, name)
                    if os.path.isdir(root) and root not in seen:
                        seen.add(root)
                        roots.append(root)
    except Exception as e:
        print("[VMAX USB] drive scan error:", e)
    roots = [os.path.abspath(x) for x in roots if os.path.isdir(x) and os.access(x, os.R_OK)]
    with _VMAX_USB_LOCK:
        _VMAX_USB_SCAN_CACHE["ts"] = now
        _VMAX_USB_SCAN_CACHE["drives"] = list(roots)
    return roots

def _vmax_usb_read_key(drive):
    try:
        with open(os.path.join(drive, _VMAX_USB_KEY_FILE), "r", encoding="utf-8") as f:
            obj = json.load(f)
        if not isinstance(obj, dict):
            return None
        uid = str(obj.get("uid", "")).strip()
        token = str(obj.get("token", ""))
        key_id = str(obj.get("key_id", "")).strip()
        if not uid or not token:
            return None
        return {"uid": uid, "token": token, "key_id": key_id, "drive": drive}
    except Exception:
        return None

def _vmax_usb_verify_drive(drive):
    key = _vmax_usb_read_key(drive)
    if not key:
        return None
    store = _vmax_usb_load_store()
    rec = store.get(key["key_id"]) if key.get("key_id") else None
    if rec is None:
        for _, candidate in store.items():
            if isinstance(candidate, dict) and candidate.get("uid") == key["uid"]:
                rec = candidate
                break
    if not isinstance(rec, dict):
        return None
    if not hmac.compare_digest(_vmax_usb_token_digest(key["token"]),
                               str(rec.get("token_sha256", ""))):
        return None
    if rec.get("revoked"):
        return None
    return {"uid": key["uid"], "key_id": key.get("key_id") or rec.get("key_id", ""), "drive": drive}

def _vmax_usb_scan():
    return [x for d in _vmax_usb_drive_candidates() for x in [_vmax_usb_verify_drive(d)] if x]

def _vmax_usb_issue_login(uid, device_id="usb-security-key"):
    uid = str(uid).strip()
    if not uid or uid not in USER_STORE:
        return None
    clear_failed_logins(uid)
    is_new_device = register_device(uid, device_id)
    if is_new_device:
        audit_log("new_device", uid=uid, device_id=device_id)
    token = generate_jwt(uid, device_id)
    rt = issue_refresh_token(uid)
    audit_log("login_ok_usb_key", uid=uid, device_id=device_id)
    return {"token": token, "refresh_token": rt, "new_device": is_new_device, "uid": uid}

@app.route('/employee-login', methods=['GET'])
def vmax_employee_login_page():
    return VMAX_EMPLOYEE_LOGIN_HTML

@app.route('/api/auth/usb/status', methods=['GET'])
def api_auth_usb_status():
    found = _vmax_usb_scan()
    return jsonify({"st": "ok", "inserted": bool(found),
                    "keys": [{"uid": x["uid"], "key_id": x["key_id"]} for x in found]})

@app.route('/api/auth/usb/login', methods=['POST'])
def api_auth_usb_login():
    body = request.get_json(silent=True) or {}
    requested_uid = str(body.get("uid", "")).strip()
    found = _vmax_usb_scan()
    if not found:
        audit_log("login_fail_usb_missing", uid=requested_uid or None)
        return jsonify({"st": "error", "msg": "ไม่พบ USB Security Key ที่ลงทะเบียนไว้"}), 401
    candidate = next((x for x in found if not requested_uid or x["uid"] == requested_uid), None)
    if not candidate:
        audit_log("login_fail_usb_uid_mismatch", uid=requested_uid or None)
        return jsonify({"st": "error", "msg": "USB Key ไม่ตรงกับ Employee ID"}), 403
    uid = candidate["uid"]
    if is_login_locked_out(uid):
        audit_log("login_locked_out_usb", uid=uid)
        return jsonify({"st": "error", "msg": "บัญชีถูกล็อกชั่วคราว กรุณาลองใหม่ภายหลัง"}), 429
    issued = _vmax_usb_issue_login(uid)
    if not issued:
        audit_log("login_fail_usb_unknown_uid", uid=uid)
        return jsonify({"st": "error", "msg": "ไม่พบบัญชีพนักงานนี้ในระบบ"}), 404
    issued.update({"st": "ok", "auth_method": "usb_security_key",
                   "key_id": candidate["key_id"], "msg": "ACCESS GRANTED"})
    return jsonify(issued)

@app.route('/api/auth/usb/keys', methods=['GET'])
@require_auth_toggleable
def api_auth_usb_keys():
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    sess = verify_jwt(token)
    if not sess:
        return jsonify({"st": "error", "msg": "Invalid or expired token"}), 401
    store = _vmax_usb_load_store()
    return jsonify({"st": "ok", "keys": [
        {"key_id": str(k), "uid": v.get("uid"), "revoked": bool(v.get("revoked"))}
        for k, v in store.items() if isinstance(v, dict)
    ]})

def _vmax_provision_usb_key(uid, drive):
    import secrets as _vmax_secrets
    uid = str(uid).strip()
    drive = os.path.abspath(os.path.expanduser(str(drive).strip().strip('"')))
    if not uid:
        raise ValueError("UID is required")
    if uid not in USER_STORE:
        raise ValueError("UID is not present in USER_STORE")
    if not os.path.isdir(drive):
        raise ValueError("Drive path does not exist or is not a directory")
    key_id = "USB-" + uuid.uuid4().hex[:16].upper()
    token = _vmax_secrets.token_urlsafe(32)
    store = _vmax_usb_load_store()
    store[key_id] = {"key_id": key_id, "uid": uid,
                     "token_sha256": _vmax_usb_token_digest(token),
                     "created_at": time.time(), "revoked": False}
    marker = {"version": 1, "uid": uid, "key_id": key_id, "token": token}
    marker_path = os.path.join(drive, _VMAX_USB_KEY_FILE)
    with open(marker_path, "w", encoding="utf-8") as f:
        json.dump(marker, f, ensure_ascii=False, indent=2)
    _vmax_usb_save_store(store)
    audit_log("usb_key_provisioned", uid=uid, key_id=key_id)
    return {"uid": uid, "key_id": key_id, "path": marker_path}

