# ============================================================================
# [NEW MODULE] EXTRACTION SURVIVAL — SHURIKEN/CALTROP HORSE TRAP + PRONE QTE
# ----------------------------------------------------------------------------
# ดาวกระจาย/ตะปูม้า: วางกับพื้นไว้ก่อน เมื่อม้าวิ่งทับจะทำให้ม้าสะดุดและ
# ผู้ขี่กระเด็นคว่ำชั่วคราว; ผู้ขี่ที่ล้มยังโดน ballistic hit ตามระบบเดิมได้
# และฝั่งผู้ล้มต้องกด/ดันขึ้นเพื่อ recover ก่อนกลับมาควบคุมตัวละครได้เต็มที่
# ============================================================================
VMAX_MOUNTED_TRAPS = {}       # trap_id -> {owner_uid,x,y,radius,armed,...}
VMAX_PRONE_PLAYERS = {}       # uid -> {until, trap_id, horse_id, started_at, ...}
VMAX_SURVIVAL_LOCK = threading.RLock()


def _surv_now():
    return time.monotonic()


def vmax_place_star_trap(uid, x, y, kind="shuriken"):
    uid = str(uid)
    trap_id = f"startrap_{uuid.uuid4().hex[:12]}"
    with VMAX_SURVIVAL_LOCK:
        VMAX_MOUNTED_TRAPS[trap_id] = {
            "id": trap_id, "owner_uid": uid, "kind": str(kind),
            "x": float(x), "y": float(y), "radius": 1.05,
            "armed": True, "created_at": time.time(), "triggered_at": None,
        }
    return True, "วางดาวกระจายดักม้าแล้ว", dict(VMAX_MOUNTED_TRAPS[trap_id])


def vmax_trigger_star_traps():
    """ตรวจม้าที่กำลังวิ่งทับกับดัก; คืนเหตุการณ์ที่เกิดขึ้นใน tick นี้."""
    events = []
    now = _surv_now()
    with VMAX_SURVIVAL_LOCK:
        for hid, horse in list(VMAX_HORSES.items()):
            if horse.get("mount_state") != "mounted" or not horse.get("mounted_by"):
                continue
            if not horse.get("moving") and str(horse.get("gait", "stand")) not in ("trot", "gallop", "run", "sprint"):
                continue
            hx, hy = float(horse.get("x", 0.0)), float(horse.get("y", 0.0))
            for tid, trap in list(VMAX_MOUNTED_TRAPS.items()):
                if not trap.get("armed"):
                    continue
                if _mec_dist(hx, hy, trap["x"], trap["y"]) > float(trap.get("radius", 1.05)):
                    continue
                trap["armed"] = False
                trap["triggered_at"] = time.time()
                rider = str(horse.get("mounted_by"))
                VMAX_PRONE_PLAYERS[rider] = {
                    "uid": rider, "until": now + 4.8, "trap_id": tid,
                    "horse_id": str(hid), "started_at": now,
                    "state": "face_down", "recover_progress": 0,
                }
                horse["mounted_by"] = None
                horse["mount_state"] = "idle"
                horse["moving"] = False
                horse["gait"] = "stand"
                horse["bolting"] = True
                if VMAX_HORSE_RIDERS.get(rider) == hid:
                    VMAX_HORSE_RIDERS.pop(rider, None)
                cst = VMAX_MOUNTED_EXTRACTION_COMBAT.get(rider)
                if cst:
                    cst["state"] = "prone_after_trap"
                    cst["last_event"] = "horse_tripped_by_star_trap"
                payload = {"uid": rider, "horse_id": str(hid), "trap_id": tid,
                           "x": hx, "y": hy, "reason": "star_trap_horse_trip"}
                events.append(payload)
                sio.emit("mounted_star_trap_triggered", payload, room=rider)
                break
    return events


def vmax_prone_state(uid):
    uid = str(uid)
    with VMAX_SURVIVAL_LOCK:
        p = VMAX_PRONE_PLAYERS.get(uid)
        if not p:
            return None
        out = dict(p)
        out["remaining"] = max(0.0, float(p["until"]) - _surv_now())
        out["vulnerable"] = True
        out["recover_required"] = True
        return out


def vmax_prone_recover(uid, action="up"):
    uid = str(uid)
    action = str(action).lower()
    with VMAX_SURVIVAL_LOCK:
        p = VMAX_PRONE_PLAYERS.get(uid)
        if not p:
            return False, "ไม่ได้อยู่ในสถานะล้มคว่ำ", None
        if action not in ("up", "stand", "recover"):
            return False, "ตอนนี้ต้องดันขึ้นเพื่อยืน", vmax_prone_state(uid)
        p["recover_progress"] = int(p.get("recover_progress", 0)) + 1
        # กด/ดันขึ้น 2 จังหวะเพื่อให้มีเวลาหลบกระสุนจริง ๆ
        if p["recover_progress"] < 2:
            return True, "กำลังดันตัวลุกขึ้น...", vmax_prone_state(uid)
        VMAX_PRONE_PLAYERS.pop(uid, None)
        cst = VMAX_MOUNTED_EXTRACTION_COMBAT.get(uid)
        if cst:
            cst["state"] = "ready"
            cst["last_event"] = "recovered_from_prone"
        sio.emit("mounted_prone_recovered", {"uid": uid}, room=uid)
        return True, "ลุกขึ้นแล้ว", None


# ============================================================================
# [NEW MODULE] EXTRACTION SURVIVAL — FISH / GUT / SKEWER / CAMPFIRE GRILL
# ============================================================================
VMAX_FISHING = {}             # uid -> fishing session
VMAX_FOOD_STATE = {}          # uid -> hunger/power/qi
VMAX_FISH_LOCK = threading.RLock()
VMAX_FISH_TYPES = {
    "river_fish": {"name": "ปลาน้ำจืด", "catch_time": 2.5, "fullness": 22, "power": 9, "qi": 7},
    "silver_fish": {"name": "ปลาประกายเงิน", "catch_time": 3.4, "fullness": 28, "power": 12, "qi": 11},
    "red_fish": {"name": "ปลาทองแดง", "catch_time": 4.0, "fullness": 34, "power": 16, "qi": 14},
}


def _food_state(uid):
    uid = str(uid)
    st = VMAX_FOOD_STATE.setdefault(uid, {"fullness": 100.0, "power": 100.0, "qi": 100.0})
    return st


def vmax_fishing_cast(uid, fish_type="river_fish"):
    uid = str(uid)
    ft = VMAX_FISH_TYPES.get(str(fish_type), VMAX_FISH_TYPES["river_fish"])
    with VMAX_FISH_LOCK:
        VMAX_FISHING[uid] = {
            "uid": uid, "state": "waiting", "fish_type": str(fish_type),
            "started_at": _surv_now(), "bite_at": _surv_now() + float(ft["catch_time"]),
            "caught": False, "gutted": False, "skewered": False, "grilled": False,
        }
    return True, f"หย่อนเบ็ดแล้ว — รอ {ft['name']}", dict(VMAX_FISHING[uid])


def vmax_fishing_reel(uid):
    uid = str(uid)
    with VMAX_FISH_LOCK:
        s = VMAX_FISHING.get(uid)
        if not s:
            return False, "ยังไม่ได้ตกปลา", None
        if _surv_now() < float(s["bite_at"]):
            return False, "ปลายังไม่กินเบ็ด", dict(s)
        s["caught"] = True
        s["state"] = "caught"
        return True, "ตกปลาได้แล้ว", dict(s)


def vmax_fish_gut(uid):
    uid = str(uid)
    with VMAX_FISH_LOCK:
        s = VMAX_FISHING.get(uid)
        if not s or not s.get("caught"):
            return False, "ต้องจับปลาให้ได้ก่อน", None
        if s.get("gutted"):
            return False, "ปลาแล่ไส้ออกแล้ว", dict(s)
        s["gutted"] = True
        s["state"] = "gutted"
        return True, "ผ่าและเอาไส้ออกแล้ว", dict(s)


def vmax_fish_skewer(uid):
    uid = str(uid)
    with VMAX_FISH_LOCK:
        s = VMAX_FISHING.get(uid)
        if not s or not s.get("gutted"):
            return False, "ต้องเอาไส้ออกก่อนจึงเสียบไม้ได้", None
        s["skewered"] = True
        s["state"] = "skewered"
        return True, "เสียบปลาเข้ากับไม้แล้ว", dict(s)


def vmax_fish_grill(uid):
    uid = str(uid)
    with VMAX_FISH_LOCK:
        s = VMAX_FISHING.get(uid)
        if not s or not s.get("skewered"):
            return False, "ต้องเสียบปลาเข้ากับไม้ก่อน", None
        if s.get("grilled"):
            return False, "ปลาสุกแล้ว", dict(s)
        s["grilled"] = True
        s["state"] = "grilled"
        ft = VMAX_FISH_TYPES.get(s.get("fish_type"), VMAX_FISH_TYPES["river_fish"])
        food = _food_state(uid)
        food["fullness"] = min(100.0, food["fullness"] + float(ft["fullness"]))
        food["power"] = min(100.0, food["power"] + float(ft["power"]))
        food["qi"] = min(100.0, food["qi"] + float(ft["qi"]))
        return True, "ย่างปลาสุกแล้ว — อิ่มขึ้น พลังและลมปราณเพิ่ม", {"fish": dict(s), "food": dict(food)}


def vmax_survival_state(uid):
    uid = str(uid)
    return {"food": dict(_food_state(uid)), "fishing": dict(VMAX_FISHING.get(uid, {})),
            "prone": vmax_prone_state(uid)}


# กระบี่ลมปราณใช้พลังลมปราณจริง ไม่ใช่ยิงฟรี
# ค่าใช้จ่ายต่อการปล่อยกระบี่แสงจะถูกหักจาก survival state ของผู้เล่น
VMAX_QI_BEAM_COST = 14.0
_old_vmax_mec_sword_beam = vmax_mec_sword_beam

def vmax_mec_sword_beam(uid, angle=None):
    uid = str(uid)
    food = _food_state(uid)
    if float(food.get("qi", 0.0)) < VMAX_QI_BEAM_COST:
        return False, f"ลมปราณไม่พอ (ต้องใช้ {VMAX_QI_BEAM_COST:.0f})", _mec_state(uid)
    ok, msg, state = _old_vmax_mec_sword_beam(uid, angle)
    if ok:
        food["qi"] = max(0.0, float(food.get("qi", 0.0)) - VMAX_QI_BEAM_COST)
        state = _mec_state(uid)
        state["qi"] = food["qi"]
    return ok, msg, state


