# Client overlay: adds touch QTE + mounted combat controls to the existing 3D
# Killer/Survivor page without replacing its original movement/shooting controls.
MOUNTED_EXTRACTION_COMBAT_JS = r"""
<script>
(function(){
  const uid = () => (window.vmState && vmState.uid) || localStorage.getItem('vmax_uid') || '';
  let prone = false;
  async function pronePoll(){ try { const r=await fetch('/api/mounted-combat/prone?uid='+encodeURIComponent(uid())); const j=await r.json(); prone=!!j.prone; if(prone && !document.getElementById('vmax-prone-recover')){ const b=document.createElement('button'); b.id='vmax-prone-recover'; b.textContent='⬆️ ดันขึ้นเพื่อยืน'; Object.assign(b.style,{position:'fixed',left:'50%',bottom:'20%',transform:'translateX(-50%)',zIndex:99999,padding:'16px 24px',borderRadius:'16px',fontSize:'20px',fontWeight:'800'}); let n=0; b.onclick=async()=>{n++; await fetch('/api/mounted-combat/prone/recover',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid:uid(),action:'up'})}); if(n>=2)b.remove();}; document.body.appendChild(b);} if(!prone){document.getElementById('vmax-prone-recover')?.remove();} }catch(e){} }
  setInterval(pronePoll,220);
  let mcTimer = null, mcState = null, swipeX = 0, swipeY = 0;
  function post(url, body){
    return fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.assign({uid:uid()},body||{}))}).then(r=>r.json());
  }
  function ensureMCUI(){
    if(document.getElementById('vmax-mounted-combat-ui')) return;
    const box=document.createElement('div'); box.id='vmax-mounted-combat-ui';
    box.style.cssText='position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:80;display:none;pointer-events:none;font-family:system-ui,sans-serif;';
    box.innerHTML=
      '<div id="vmax-mc-qte" style="background:rgba(5,10,18,.92);border:2px solid #8fd8ff;border-radius:14px;padding:12px 14px;color:#fff;text-align:center;min-width:290px;box-shadow:0 0 28px rgba(80,180,255,.35);pointer-events:auto">'+
      '<div style="font-weight:800">🐎 ศัตรูกำลังพุ่งชน!</div>'+
      '<div id="vmax-mc-seq" style="font-size:13px;margin:7px 0">ปัดซ้าย → ปัดขวา → ปัดขึ้น</div>'+
      '<div id="vmax-mc-status" style="font-size:12px;opacity:.8">เตรียมสวน</div>'+
      '<button id="vmax-mc-punch" style="display:none;margin-top:8px;font-size:22px;padding:10px 22px;border-radius:12px;background:#39151a;color:#fff;border:2px solid #ff8c8c;pointer-events:auto">👊</button>'+
      '</div>';
    document.body.appendChild(box);
    document.getElementById('vmax-mc-punch').onclick=()=>post('/api/mounted-combat/qte',{action:'punch'}).then(showResult);
  }
  function showResult(d){
    const q=mcState&&mcState.incoming_charge;
    const ui=document.getElementById('vmax-mounted-combat-ui');
    if(!d || d.st!=='ok'){
      const s=document.getElementById('vmax-mc-status'); if(s) s.textContent=(d&&d.msg)||'พลาดจังหวะ';
      setTimeout(()=>{if(ui)ui.style.display='none'},900); return;
    }
    if(d.state && d.state.incoming_charge){
      mcState=d.state; renderQTE(); return;
    }
    const s=document.getElementById('vmax-mc-status'); if(s) s.textContent=d.msg||'สำเร็จ!';
    setTimeout(()=>{if(ui)ui.style.display='none'},1100);
  }
  function renderQTE(){
    ensureMCUI();
    const ui=document.getElementById('vmax-mounted-combat-ui'), q=mcState&&mcState.incoming_charge;
    if(!q){ui.style.display='none';return}
    ui.style.display='block';
    const stage=q.stage||0;
    document.getElementById('vmax-mc-seq').textContent=stage<3?('ขั้น '+(stage+1)+'/3: '+['⬅️ ปัดซ้าย','➡️ ปัดขวา','⬆️ ปัดขึ้น'][stage]):'🔥 ขั้นสุดท้าย: กดหมัด';
    document.getElementById('vmax-mc-punch').style.display=stage>=3?'inline-block':'none';
    document.getElementById('vmax-mc-status').textContent=stage<3?'ทำตามทิศทางให้ทัน!':'ขึ้นหลังม้าแล้ว — ต่อยคนขี่!';
  }
  function poll(){
    if(!uid()) return;
    fetch('/api/mounted-combat/state?uid='+encodeURIComponent(uid())).then(r=>r.json()).then(d=>{
      if(d.st==='ok'){mcState=d.state;renderQTE();}
    }).catch(()=>{});
  }
  function sendSwipe(dir){ post('/api/mounted-combat/qte',{action:dir}).then(showResult); }
  document.addEventListener('touchstart',e=>{
    if(!mcState || !mcState.incoming_charge) return;
    const t=e.changedTouches[0]; swipeX=t.clientX; swipeY=t.clientY;
  },{passive:true});
  document.addEventListener('touchend',e=>{
    if(!mcState || !mcState.incoming_charge) return;
    const t=e.changedTouches[0],dx=t.clientX-swipeX,dy=t.clientY-swipeY;
    if(Math.max(Math.abs(dx),Math.abs(dy))<45)return;
    const dir=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy<0?'up':'down');
    if(dir==='down') return;
    sendSwipe(dir);
  },{passive:true});
  // Desktop fallback: arrow keys = QTE directions; Space = punch.
  document.addEventListener('keydown',e=>{
    if(!mcState || !mcState.incoming_charge)return;
    const k=e.key.toLowerCase();
    if(k==='arrowleft')sendSwipe('left');
    else if(k==='arrowright')sendSwipe('right');
    else if(k==='arrowup')sendSwipe('up');
    else if(k===' '){e.preventDefault();post('/api/mounted-combat/qte',{action:'punch'}).then(showResult);}
  });
  // Public helpers for the existing game UI / dev console.
  window.VMAXMountedCombat={
    equip:(weapon,horse_id)=>post('/api/mounted-combat/equip',{weapon,horse_id}),
    charge:(target_uid,target_x,target_y)=>post('/api/mounted-combat/charge',{target_uid,target_x,target_y}),
    beam:(angle)=>post('/api/mounted-combat/beam',{angle}),
    state:()=>fetch('/api/mounted-combat/state?uid='+encodeURIComponent(uid())).then(r=>r.json())
  };
  ensureMCUI();
  mcTimer=setInterval(poll,220);
})();
</script>
"""

