# Backward-compatible module self-test (does not require Flask request context).
def _run_mounted_extraction_combat_selftests():
    """python <file>.py --selftest-mounted-extraction-combat"""
    ok_all = True
    def check(name, cond):
        nonlocal ok_all
        ok_all = ok_all and bool(cond)
        print(("PASS " if cond else "FAIL ") + name)

    # Preserve any pre-existing state from a running dev process.
    saved_horses = dict(VMAX_HORSES)
    saved_riders = dict(VMAX_HORSE_RIDERS)
    saved_combat = dict(VMAX_MOUNTED_EXTRACTION_COMBAT)
    saved_qte = dict(VMAX_MOUNTED_EXTRACTION_QTE)
    try:
        hid_a = vmax_create_horse(x=0, y=0, heading=0)
        hid_b = vmax_create_horse(x=4, y=0, heading=180)
        vmax_mount_horse("mec_a", hid_a, "left", "forward")
        vmax_mount_horse("mec_b", hid_b, "right", "forward")
        vmax_horse_animation_tick(hid_a, 5.0)
        vmax_horse_animation_tick(hid_b, 5.0)

        check("equip long weapon", vmax_mec_equip("mec_a", "lance")[0])
        check("charge creates QTE", vmax_mec_charge("mec_a", "mec_b")[0] and "mec_b" in VMAX_MOUNTED_EXTRACTION_QTE)

        check("QTE left", vmax_mec_qte("mec_b", "left")[0])
        check("QTE right", vmax_mec_qte("mec_b", "right")[0])
        check("QTE up", vmax_mec_qte("mec_b", "up")[0])
        check("QTE punch counter-mount", vmax_mec_qte("mec_b", "punch")[0])
        check("defender is now on attacker's horse", VMAX_HORSE_RIDERS.get("mec_b") == hid_a)
        check("attacker was unseated", "mec_a" not in VMAX_HORSE_RIDERS)

        vmax_mec_equip("mec_b", "katana", hid_a)
        check("sword beam", vmax_mec_sword_beam("mec_b", 0)[0])
        beams = list(VMAX_MOUNTED_EXTRACTION_BEAMS)
        if beams:
            b = VMAX_MOUNTED_EXTRACTION_BEAMS[beams[-1]]
            # ยิงกระสุนตัดผ่านกลางลำแสง
            broken, _, _ = vmax_mec_bullet_hit_beam("mec_a", b["x"] + b["range"]/2, b["y"])
            check("bullet shatters beam", broken and not b["active"])
        else:
            check("bullet shatters beam", False)
    finally:
        VMAX_HORSES.clear(); VMAX_HORSES.update(saved_horses)
        VMAX_HORSE_RIDERS.clear(); VMAX_HORSE_RIDERS.update(saved_riders)
        VMAX_MOUNTED_EXTRACTION_COMBAT.clear(); VMAX_MOUNTED_EXTRACTION_COMBAT.update(saved_combat)
        VMAX_MOUNTED_EXTRACTION_QTE.clear(); VMAX_MOUNTED_EXTRACTION_QTE.update(saved_qte)
        VMAX_MOUNTED_EXTRACTION_BEAMS.clear()





# ============================================================================
# VMAX SPEAR DUEL ARENA — SAME-SPEAR CHALLENGE / INSTANT ARENA
# ============================================================================
VMAX_SPEAR_DUEL_LOCK = threading.RLock()
VMAX_SPEAR_DUEL_STATE = {}
VMAX_SPEAR_DUEL_RANGE = 7.0
VMAX_SPEAR_DUEL_DURATION = 45.0
VMAX_SPEAR_DUEL_READY = True

def _vsd_now():
    return time.time()

def _vsd_player_state(uid):
    uid = str(uid)
    st = VMAX_MOUNTED_EXTRACTION_COMBAT.get(uid, {})
    weapon = str(st.get('weapon_id') or st.get('weapon') or '').lower()
    return st, weapon

def _vsd_distance(a, b):
    try:
        ax=float(a.get('x',0)); ay=float(a.get('y',0)); az=float(a.get('z',0))
        bx=float(b.get('x',0)); by=float(b.get('y',0)); bz=float(b.get('z',0))
        return ((ax-bx)**2+(ay-by)**2+(az-bz)**2)**0.5
    except Exception:
        return 0.0

def _vsd_get(uid):
    return VMAX_SPEAR_DUEL_STATE.get(str(uid))

def _vsd_clear_pair(duel):
    a,b=str(duel['a']),str(duel['b'])
    VMAX_SPEAR_DUEL_STATE.pop(a,None)
    VMAX_SPEAR_DUEL_STATE.pop(b,None)

def vmax_spear_duel_challenge(attacker_uid, defender_uid):
    a,b=str(attacker_uid),str(defender_uid)
    if not a or not b or a == b:
        return {'ok':False,'reason':'invalid_players'}
    with VMAX_SPEAR_DUEL_LOCK:
        _, wa = _vsd_player_state(a); _, wb = _vsd_player_state(b)
        if wa != 'spear' or wb != 'spear':
            return {'ok':False,'reason':'both_players_must_hold_same_spear','attacker_weapon':wa,'defender_weapon':wb}
        if _vsd_get(a) or _vsd_get(b):
            return {'ok':False,'reason':'player_already_in_duel'}
        # Position check when position data exists. Missing position is allowed for
        # compatibility with the existing server's player-state representation.
        sa,_=_vsd_player_state(a); sb,_=_vsd_player_state(b)
        if all(k in sa for k in ('x','y')) and all(k in sb for k in ('x','y')):
            if _vsd_distance(sa,sb) > VMAX_SPEAR_DUEL_RANGE:
                return {'ok':False,'reason':'too_far','distance':_vsd_distance(sa,sb),'range':VMAX_SPEAR_DUEL_RANGE}
        duel={'id':f'spear_duel_{int(_vsd_now()*1000)}_{a}_{b}','a':a,'b':b,'status':'pending','weapon':'spear','created_at':_vsd_now(),'expires_at':_vsd_now()+20.0,'winner':None,'loser':None,'arena':None}
        VMAX_SPEAR_DUEL_STATE[a]=duel; VMAX_SPEAR_DUEL_STATE[b]=duel
        sio.emit('spear_duel_challenge',{'duel_id':duel['id'],'from':a,'to':b,'weapon':'spear','expires_at':duel['expires_at']},room=b)
        return {'ok':True,'status':'pending','duel':duel}

def vmax_spear_duel_accept(uid, duel_id=None, accept=True):
    uid=str(uid)
    with VMAX_SPEAR_DUEL_LOCK:
        duel=_vsd_get(uid)
        if not duel or duel.get('status')!='pending': return {'ok':False,'reason':'no_pending_duel'}
        if duel_id and str(duel_id)!=duel['id']: return {'ok':False,'reason':'duel_id_mismatch'}
        if _vsd_now()>float(duel['expires_at']):
            _vsd_clear_pair(duel); return {'ok':False,'reason':'challenge_expired'}
        if not accept:
            duel['status']='declined'; sio.emit('spear_duel_declined',{'duel_id':duel['id']},room=str(duel['a'])); _vsd_clear_pair(duel)
            return {'ok':True,'status':'declined'}
        duel['status']='active'
        duel['started_at']=_vsd_now(); duel['ends_at']=duel['started_at']+VMAX_SPEAR_DUEL_DURATION
        # The arena is a logical combat boundary: no map reload is needed.
        duel['arena']={'type':'instant_spear_arena','radius':6.5,'center':'midpoint','collision_wall':True,'outsider_interference_blocked':True}
        for uid2 in (duel['a'],duel['b']):
            sio.emit('spear_duel_arena_start',{'duel':duel,'opponent':duel['b'] if uid2==duel['a'] else duel['a']},room=str(uid2))
        return {'ok':True,'status':'active','duel':duel}

def vmax_spear_duel_strike(uid, action='strike'):
    uid=str(uid)
    with VMAX_SPEAR_DUEL_LOCK:
        duel=_vsd_get(uid)
        if not duel or duel.get('status')!='active': return {'ok':False,'reason':'not_in_active_duel'}
        if _vsd_now()>float(duel.get('ends_at',0)):
            duel['status']='timeout'; duel['winner']=None; duel['loser']=None
            _vsd_clear_pair(duel); return {'ok':True,'status':'timeout'}
        if str(action) not in ('strike','thrust','parry','block'): return {'ok':False,'reason':'bad_action'}
        opponent=duel['b'] if uid==duel['a'] else duel['a']
        event={'duel_id':duel['id'],'uid':uid,'opponent':opponent,'action':str(action),'at':_vsd_now()}
        sio.emit('spear_duel_action',event,room=str(duel['a'])); sio.emit('spear_duel_action',event,room=str(duel['b']))
        return {'ok':True,'status':'active','event':event,'duel_id':duel['id']}

def vmax_spear_duel_finish(uid, winner_uid=None):
    uid=str(uid)
    with VMAX_SPEAR_DUEL_LOCK:
        duel=_vsd_get(uid)
        if not duel or duel.get('status')!='active': return {'ok':False,'reason':'not_in_active_duel'}
        winner=str(winner_uid) if winner_uid else uid
        if winner not in (duel['a'],duel['b']): return {'ok':False,'reason':'invalid_winner'}
        loser=duel['b'] if winner==duel['a'] else duel['a']
        duel['status']='finished'; duel['winner']=winner; duel['loser']=loser; duel['finished_at']=_vsd_now()
        payload={'duel_id':duel['id'],'winner':winner,'loser':loser,'status':'finished'}
        sio.emit('spear_duel_arena_end',payload,room=str(duel['a'])); sio.emit('spear_duel_arena_end',payload,room=str(duel['b']))
        _vsd_clear_pair(duel)
        return {'ok':True,**payload}

def vmax_spear_duel_public(uid):
    with VMAX_SPEAR_DUEL_LOCK:
        duel=_vsd_get(uid)
        return {'ok':True,'duel':dict(duel) if duel else None,'arena_active':bool(duel and duel.get('status')=='active')}

@app.route('/api/spear-duel/challenge',methods=['POST'])
@require_auth_toggleable
def api_spear_duel_challenge():
    b=request.get_json(silent=True) or {}; a=resolve_uid(b,required=True); d=str(b.get('target_uid') or b.get('defender_uid') or '')
    if not a or not d: return jsonify({'ok':False,'reason':'uid_and_target_required'}),400
    return jsonify(vmax_spear_duel_challenge(a,d))

@app.route('/api/spear-duel/accept',methods=['POST'])
@require_auth_toggleable
def api_spear_duel_accept():
    b=request.get_json(silent=True) or {}; uid=resolve_uid(b,required=True)
    if not uid: return jsonify({'ok':False,'reason':'uid_required'}),401
    return jsonify(vmax_spear_duel_accept(uid,b.get('duel_id'),bool(b.get('accept',True))))

@app.route('/api/spear-duel/state',methods=['GET'])
@require_auth_toggleable
def api_spear_duel_state():
    uid=request.args.get('uid') or request.args.get('user_id')
    if not uid: return jsonify({'ok':False,'reason':'uid_required'}),400
    return jsonify(vmax_spear_duel_public(uid))

@app.route('/api/spear-duel/action',methods=['POST'])
@require_auth_toggleable
def api_spear_duel_action():
    b=request.get_json(silent=True) or {}; uid=resolve_uid(b,required=True)
    if not uid: return jsonify({'ok':False,'reason':'uid_required'}),401
    return jsonify(vmax_spear_duel_strike(uid,b.get('action','strike')))

@app.route('/api/spear-duel/finish',methods=['POST'])
@require_auth_toggleable
def api_spear_duel_finish():
    b=request.get_json(silent=True) or {}; uid=resolve_uid(b,required=True)
    if not uid: return jsonify({'ok':False,'reason':'uid_required'}),401
    return jsonify(vmax_spear_duel_finish(uid,b.get('winner_uid')))

