# VMAX BAMBOO SWORD DUEL — SAME-SWORD CHALLENGE / BAMBOO FOREST ARENA
# ============================================================================
VMAX_BAMBOO_DUEL_LOCK = threading.RLock()
VMAX_BAMBOO_DUEL_STATE = {}
VMAX_BAMBOO_DUEL_RANGE = 8.0
VMAX_BAMBOO_DUEL_DURATION = 60.0
VMAX_BAMBOO_DUEL_READY = True

def _vbd_now(): return time.time()
def _vbd_player_state(uid):
    uid=str(uid); st=VMAX_MOUNTED_EXTRACTION_COMBAT.get(uid,{})
    return st,str(st.get('weapon_id') or st.get('weapon') or '').lower()
def _vbd_distance(a,b):
    try:
        ax,ay,az=float(a.get('x',0)),float(a.get('y',0)),float(a.get('z',0)); bx,by,bz=float(b.get('x',0)),float(b.get('y',0)),float(b.get('z',0))
        return ((ax-bx)**2+(ay-by)**2+(az-bz)**2)**0.5
    except Exception: return 0.0
def _vbd_get(uid): return VMAX_BAMBOO_DUEL_STATE.get(str(uid))
def _vbd_clear(d):
    VMAX_BAMBOO_DUEL_STATE.pop(str(d['a']),None); VMAX_BAMBOO_DUEL_STATE.pop(str(d['b']),None)

def vmax_bamboo_sword_duel_challenge(attacker_uid,defender_uid):
    a,b=str(attacker_uid),str(defender_uid)
    if not a or not b or a==b: return {'ok':False,'reason':'invalid_players'}
    with VMAX_BAMBOO_DUEL_LOCK:
        sa,wa=_vbd_player_state(a); sb,wb=_vbd_player_state(b)
        if wa not in {'katana','sword','jian','blade'} or wb!=wa: return {'ok':False,'reason':'both_players_must_hold_same_sword','attacker_weapon':wa,'defender_weapon':wb}
        if _vbd_get(a) or _vbd_get(b): return {'ok':False,'reason':'player_already_in_duel'}
        if all(k in sa for k in ('x','y')) and all(k in sb for k in ('x','y')):
            dist=_vbd_distance(sa,sb)
            if dist>VMAX_BAMBOO_DUEL_RANGE: return {'ok':False,'reason':'too_far','distance':dist,'range':VMAX_BAMBOO_DUEL_RANGE}
        now=_vbd_now(); d={'id':f'bamboo_sword_duel_{int(now*1000)}_{a}_{b}','a':a,'b':b,'status':'pending','weapon':wa,'created_at':now,'expires_at':now+20.0,'winner':None,'loser':None,'arena':None}
        VMAX_BAMBOO_DUEL_STATE[a]=d; VMAX_BAMBOO_DUEL_STATE[b]=d
        sio.emit('bamboo_sword_duel_challenge',{'duel_id':d['id'],'from':a,'to':b,'weapon':wa,'expires_at':d['expires_at']},room=b)
        return {'ok':True,'status':'pending','duel':d}

def vmax_bamboo_sword_duel_accept(uid,duel_id=None,accept=True):
    uid=str(uid)
    with VMAX_BAMBOO_DUEL_LOCK:
        d=_vbd_get(uid)
        if not d or d.get('status')!='pending': return {'ok':False,'reason':'no_pending_duel'}
        if duel_id and str(duel_id)!=str(d['id']): return {'ok':False,'reason':'duel_id_mismatch'}
        if _vbd_now()>float(d['expires_at']): _vbd_clear(d); return {'ok':False,'reason':'challenge_expired'}
        if not accept:
            d['status']='declined'; sio.emit('bamboo_sword_duel_declined',{'duel_id':d['id']},room=str(d['a'])); _vbd_clear(d); return {'ok':True,'status':'declined'}
        now=_vbd_now(); d['status']='active'; d['started_at']=now; d['ends_at']=now+VMAX_BAMBOO_DUEL_DURATION
        d['arena']={'type':'bamboo_forest_sword_arena','environment':'bamboo_forest','radius':9.0,'center':'midpoint','collision_wall':True,'outsider_interference_blocked':True,'visual_theme':'wuxia_bamboo_forest','dynamic_bamboo':True,'air_combat':True}
        payload={'duel':d,'opponent_a':d['b'],'opponent_b':d['a']}
        sio.emit('bamboo_sword_duel_arena_start',payload,room=str(d['a'])); sio.emit('bamboo_sword_duel_arena_start',payload,room=str(d['b']))
        return {'ok':True,'status':'active','duel':d}

def vmax_bamboo_sword_duel_action(uid,action='slash'):
    uid=str(uid); allowed={'slash','thrust','parry','jump','air_dash','bamboo_bounce','finish'}
    with VMAX_BAMBOO_DUEL_LOCK:
        d=_vbd_get(uid)
        if not d or d.get('status')!='active': return {'ok':False,'reason':'not_in_active_duel'}
        if _vbd_now()>float(d.get('ends_at',0)):
            payload={'duel_id':d['id'],'status':'timeout'}; d['status']='timeout'; sio.emit('bamboo_sword_duel_arena_end',payload,room=str(d['a'])); sio.emit('bamboo_sword_duel_arena_end',payload,room=str(d['b'])); _vbd_clear(d); return {'ok':True,**payload}
        action=str(action or 'slash')
        if action not in allowed: return {'ok':False,'reason':'bad_action'}
        opponent=d['b'] if uid==d['a'] else d['a']; event={'duel_id':d['id'],'uid':uid,'opponent':opponent,'action':action,'at':_vbd_now(),'movement':action in {'jump','air_dash','bamboo_bounce'},'airborne':action in {'jump','air_dash','bamboo_bounce'}}
        sio.emit('bamboo_sword_duel_action',event,room=str(d['a'])); sio.emit('bamboo_sword_duel_action',event,room=str(d['b']))
        return {'ok':True,'status':'active','event':event}

def vmax_bamboo_sword_duel_finish(uid,winner_uid=None):
    uid=str(uid)
    with VMAX_BAMBOO_DUEL_LOCK:
        d=_vbd_get(uid)
        if not d or d.get('status')!='active': return {'ok':False,'reason':'not_in_active_duel'}
        winner=str(winner_uid) if winner_uid else uid
        if winner not in (d['a'],d['b']): return {'ok':False,'reason':'invalid_winner'}
        loser=d['b'] if winner==d['a'] else d['a']; d['status']='finished'; d['winner']=winner; d['loser']=loser; d['finished_at']=_vbd_now(); payload={'duel_id':d['id'],'winner':winner,'loser':loser,'status':'finished'}
        sio.emit('bamboo_sword_duel_arena_end',payload,room=str(d['a'])); sio.emit('bamboo_sword_duel_arena_end',payload,room=str(d['b'])); _vbd_clear(d); return {'ok':True,**payload}

def vmax_bamboo_sword_duel_public(uid):
    with VMAX_BAMBOO_DUEL_LOCK:
        d=_vbd_get(str(uid)); return {'ok':True,'duel':dict(d) if d else None,'arena_active':bool(d and d.get('status')=='active')}

