# VMAX NEEDLE POLE DUEL: matching needle weapons open a local pole-forest arena.
VMAX_NEEDLE_POLE_LOCK=threading.RLock(); VMAX_NEEDLE_POLE_STATE={}
VMAX_NEEDLE_POLE_MATCHING_WEAPONS={"needle","needle_sword","flying_needle","silver_needle"}
VMAX_NEEDLE_POLE_COUNT=28

def _vnp_now(): return time.time()
def _vnp_weapon(w): return str(w or "").strip().lower()
def _vnp_new(uid):
    poles=[]
    for n in range(VMAX_NEEDLE_POLE_COUNT):
        a=(n/max(1,VMAX_NEEDLE_POLE_COUNT))*math.tau; r=4.0+(n%7)*1.35
        poles.append({"id":f"pole_{n:02d}","x":round(math.cos(a)*r,3),"y":round(2+(n%5)*1.15,3),"z":round(math.sin(a)*r,3),"radius":.18,"height":round(5+(n%4)*.9,3)})
    return {"uid":str(uid),"status":"idle","challenger":None,"opponent":None,"weapon":None,"arena":"needle_pole_forest","poles":poles,"fighters":{},"last_action":None,"updated_at":_vnp_now()}
def _vnp_state(uid):
    with VMAX_NEEDLE_POLE_LOCK: return VMAX_NEEDLE_POLE_STATE.setdefault(str(uid),_vnp_new(uid))
def vmax_needle_pole_challenge(challenger,opponent,weapon):
    c,o,w=str(challenger),str(opponent),_vnp_weapon(weapon)
    if not c or not o or c==o: return {"ok":False,"reason":"invalid_players"}
    if w not in VMAX_NEEDLE_POLE_MATCHING_WEAPONS: return {"ok":False,"reason":"weapon_not_needle"}
    with VMAX_NEEDLE_POLE_LOCK:
        st=_vnp_state(c); st.update(status="challenged",challenger=c,opponent=o,weapon=w,updated_at=_vnp_now())
        return {"ok":True,"status":"challenged","challenger":c,"opponent":o,"weapon":w}
def vmax_needle_pole_accept(opponent,challenger,weapon):
    o,c,w=str(opponent),str(challenger),_vnp_weapon(weapon)
    if w not in VMAX_NEEDLE_POLE_MATCHING_WEAPONS: return {"ok":False,"reason":"weapon_not_needle"}
    with VMAX_NEEDLE_POLE_LOCK:
        st=_vnp_state(c)
        if st.get("status")!="challenged" or st.get("opponent")!=o or st.get("weapon")!=w: return {"ok":False,"reason":"challenge_not_found"}
        st["status"]="active"; st["updated_at"]=_vnp_now(); st["fighters"]={c:{"x":-1.8,"y":0,"z":0,"mode":"ground","pole":None,"energy":100},o:{"x":1.8,"y":0,"z":0,"mode":"ground","pole":None,"energy":100}}
        VMAX_NEEDLE_POLE_STATE[o]=st
        try: sio.emit("needle_pole_arena_start",{"challenger":c,"opponent":o,"weapon":w,"arena":"needle_pole_forest","poles":st["poles"]})
        except Exception: pass
        return {"ok":True,"status":"active","arena":"needle_pole_forest","poles":st["poles"],"fighters":st["fighters"]}
def vmax_needle_pole_action(uid,action,pole_id=None,dx=0,dz=0):
    uid=str(uid); action=str(action or "").lower(); valid={"back_jump","latch","pole_rebound","air_dash","needle_strike","release"}
    if action not in valid: return {"ok":False,"reason":"bad_action"}
    with VMAX_NEEDLE_POLE_LOCK:
        st=_vnp_state(uid)
        if st.get("status")!="active" or uid not in st.get("fighters",{}): return {"ok":False,"reason":"duel_not_active"}
        f=st["fighters"][uid]
        if action=="back_jump": f.update(mode="air",y=max(1.5,float(f["y"])+2.2),x=float(f["x"])-float(dx or 0)*1.5,z=float(f["z"])-float(dz or 0)*1.5)
        elif action=="latch":
            if not pole_id or not any(p["id"]==str(pole_id) for p in st["poles"]): return {"ok":False,"reason":"pole_not_found"}
            f.update(mode="latched",pole=str(pole_id))
        elif action=="pole_rebound":
            if f.get("mode")!="latched": return {"ok":False,"reason":"not_latched"}
            f.update(mode="air",pole=None,y=max(2,float(f["y"])+2.8),x=float(f["x"])+float(dx or 0)*3,z=float(f["z"])+float(dz or 0)*3)
        elif action=="air_dash": f.update(mode="air",x=float(f["x"])+float(dx or 0)*4,z=float(f["z"])+float(dz or 0)*4,y=max(1.2,float(f["y"])))
        elif action=="needle_strike": f["mode"]="air" if float(f["y"])>1 else "ground"
        else: f.update(mode="ground",pole=None,y=0)
        st["last_action"]={"uid":uid,"action":action,"pole":pole_id,"at":_vnp_now()}; st["updated_at"]=_vnp_now()
        return {"ok":True,"action":action,"fighter":f,"arena":"needle_pole_forest"}
