# ============================================================================
# VMAX UNIVERSAL WEAPON DUEL — ONE SWING = CHALLENGE / WEAPON-SPECIFIC MAP
# ============================================================================
VMAX_UNIVERSAL_DUEL_LOCK = threading.RLock()
VMAX_UNIVERSAL_DUEL_STATE = {}
VMAX_UNIVERSAL_DUEL_DURATION = 60.0

# ทุกอาวุธมีสนามของตัวเอง แต่ยังอยู่ใน extraction map เดิมและเป็น local arena
VMAX_WEAPON_DUEL_MAPS = {
    "lance": {"arena":"horse_duel_plain","environment":"open_grassland","label":"LANCE DUEL — WIND PLAIN"},
    "spear": {"arena":"spear_duel_courtyard","environment":"stone_courtyard","label":"SPEAR DUEL — IRON COURTYARD"},
    "glaive": {"arena":"glaive_ruins","environment":"ancient_ruins","label":"GLAIVE DUEL — ANCIENT RUINS"},
    "katana": {"arena":"bamboo_forest","environment":"bamboo_forest","label":"SWORD DUEL — BAMBOO FOREST"},
    "sword": {"arena":"bamboo_forest","environment":"bamboo_forest","label":"SWORD DUEL — BAMBOO FOREST"},
    "jian": {"arena":"bamboo_forest","environment":"bamboo_forest","label":"JIAN DUEL — BAMBOO FOREST"},
    "blade": {"arena":"bamboo_forest","environment":"bamboo_forest","label":"BLADE DUEL — BAMBOO FOREST"},
    "great_sword": {"arena":"storm_cliff","environment":"storm_cliff","label":"GREAT SWORD DUEL — STORM CLIFF"},
    "needle": {"arena":"needle_pole_forest","environment":"needle_pole_forest","label":"NEEDLE DUEL — POLE FOREST"},
    "needle_sword": {"arena":"needle_pole_forest","environment":"needle_pole_forest","label":"NEEDLE SWORD DUEL — POLE FOREST"},
    "flying_needle": {"arena":"needle_pole_forest","environment":"needle_pole_forest","label":"FLYING NEEDLE DUEL — POLE FOREST"},
    "silver_needle": {"arena":"needle_pole_forest","environment":"needle_pole_forest","label":"SILVER NEEDLE DUEL — POLE FOREST"},
}

def _vuwd_weapon(uid, supplied=None):
    if supplied: return str(supplied).strip().lower()
    try:
        st = VMAX_MOUNTED_EXTRACTION_COMBAT.get(str(uid), {})
        return str(st.get("weapon_id") or st.get("weapon") or "").strip().lower()
    except Exception:
        return ""

def _vuwd_map_for(w):
    return VMAX_WEAPON_DUEL_MAPS.get(str(w).lower(), {"arena":"weapon_duel_arena","environment":"weapon_duel_arena","label":"WEAPON DUEL"})

def _vuwd_get(uid): return VMAX_UNIVERSAL_DUEL_STATE.get(str(uid))

def _vuwd_clear(d):
    if d:
        VMAX_UNIVERSAL_DUEL_STATE.pop(str(d.get("a")), None)
        VMAX_UNIVERSAL_DUEL_STATE.pop(str(d.get("b")), None)

def vmax_universal_weapon_swing(attacker_uid, defender_uid, weapon=None):
    """กดฟัน/โจมตีหนึ่งครั้ง = ส่งคำท้าดวล ถ้าอีกฝ่ายถืออาวุธชนิดเดียวกัน"""
    a, b = str(attacker_uid or ""), str(defender_uid or "")
    w = _vuwd_weapon(a, weapon)
    if not a or not b or a == b: return {"ok":False,"reason":"invalid_players"}
    with VMAX_UNIVERSAL_DUEL_LOCK:
        wb = _vuwd_weapon(b)
        if not w or not wb: return {"ok":False,"reason":"weapon_required"}
        if w != wb: return {"ok":False,"reason":"weapons_must_match","attacker_weapon":w,"defender_weapon":wb}
        if _vuwd_get(a) or _vuwd_get(b): return {"ok":False,"reason":"player_already_in_duel"}
        profile = _vuwd_map_for(w)
        now = time.time()
        d = {"id":f"weapon_duel_{int(now*1000)}_{a}_{b}","a":a,"b":b,"weapon":w,
             "status":"pending","created_at":now,"expires_at":now+20.0,"started_at":None,
             "ends_at":None,"winner":None,"loser":None,"arena":profile}
        VMAX_UNIVERSAL_DUEL_STATE[a] = d; VMAX_UNIVERSAL_DUEL_STATE[b] = d
        payload={"duel_id":d["id"],"from":a,"to":b,"weapon":w,"arena":profile,"expires_at":d["expires_at"]}
        try: sio.emit("universal_weapon_duel_challenge", payload, room=b)
        except Exception: pass
        return {"ok":True,"status":"pending","duel":d}

def vmax_universal_weapon_duel_accept(uid, duel_id=None, accept=True):
    uid=str(uid)
    with VMAX_UNIVERSAL_DUEL_LOCK:
        d=_vuwd_get(uid)
        if not d or d.get("status")!="pending": return {"ok":False,"reason":"no_pending_duel"}
        if duel_id and str(duel_id)!=str(d.get("id")): return {"ok":False,"reason":"duel_id_mismatch"}
        if not accept:
            d["status"]="declined"
            try: sio.emit("universal_weapon_duel_declined", {"duel_id":d["id"]}, room=str(d["a"]))
            except Exception: pass
            _vuwd_clear(d); return {"ok":True,"status":"declined"}
        now=time.time(); d["status"]="active"; d["started_at"]=now; d["ends_at"]=now+VMAX_UNIVERSAL_DUEL_DURATION
        payload={"duel":d,"arena":d["arena"],"map_transform":"local_area_only","reload_map":False}
        try:
            sio.emit("universal_weapon_duel_arena_start",payload,room=str(d["a"]))
            sio.emit("universal_weapon_duel_arena_start",payload,room=str(d["b"]))
        except Exception: pass
        return {"ok":True,"status":"active","duel":d}

def vmax_universal_weapon_duel_action(uid, action="swing"):
    uid=str(uid); action=str(action or "swing")
    allowed={"swing","slash","thrust","parry","jump","dash","air_dash","block","finish"}
    if action not in allowed: return {"ok":False,"reason":"invalid_action"}
    with VMAX_UNIVERSAL_DUEL_LOCK:
        d=_vuwd_get(uid)
        if not d or d.get("status")!="active": return {"ok":False,"reason":"duel_not_active"}
        if time.time() >= float(d.get("ends_at") or 0):
            d["status"]="timeout"; _vuwd_clear(d); return {"ok":True,"status":"timeout"}
        ev={"duel_id":d["id"],"uid":uid,"action":action,"weapon":d["weapon"],"arena":d["arena"],"at":time.time()}
        try:
            sio.emit("universal_weapon_duel_action",ev,room=str(d["a"]))
            sio.emit("universal_weapon_duel_action",ev,room=str(d["b"]))
        except Exception: pass
        return {"ok":True,"status":"active","event":ev}

