# ============================================================================
# [ 6zzG. QUICK UNIVERSE — 1v1 ด่วน: ดวลการ์ดเผชิญหน้า จักรวาลบิดเบือนจนแตก ]
# ----------------------------------------------------------------------------
# กติกา (ต้นฉบับ คิดเองทั้งหมด):
#   - 2 ผู้เล่น 1v1 แต่ละคนมีการ์ดในมือ 4 ใบ ทุกรอบ "ทั้งสองฝ่ายต้องลงการ์ด 1 ใบ"
#     พร้อมกัน (ล็อกลับ แล้วเปิดเผยพร้อมกัน) แล้วการ์ดชนกันเป็นผลลัพธ์ของรอบนั้น
#   - ไม่มี HP: แต่ละฝ่ายมี "ค่าบิดเบือนของอวกาศ" (distortion 0-100) ยิ่งโดนโจมตีมาก
#     ค่ายิ่งขึ้น:  stable -> warped(35) -> torn(65) -> critical(90) -> shattered(100)
#   - ยิ่งอวกาศฝั่งไหนบิดมาก ฝั่งนั้นยิ่งโดนแรงขึ้น (x1.15 / x1.3 / x1.5) และที่ระดับ
#     critical การโจมตีที่โดนจะสะท้อนความไม่เสถียรกลับไปหาผู้โจมตีด้วย
#   - ฝั่งใดค่าถึง 100 = จักรวาลของฝั่งนั้นแตก ฝ่ายนั้นแพ้ทันที (ถ้าแตกพร้อมกัน = เสมอ
#     "จักรวาลแตกทั้งคู่") ถ้าครบ QU_MAX_ROUNDS รอบ ฝั่งที่บิดน้อยกว่าชนะ
#   - "ด่วน": รอบละ QU_ROUND_SEC วินาที ไม่ลงการ์ดทันเวลา = ระบบสุ่มลงให้
#   - ไม่ผูกเงินจริง/ของรางวัลพรีเมียม ผลแพ้ชนะส่งผ่านอีเวนต์ + state เท่านั้น
# ============================================================================
import time as _qu_time
import threading as _qu_thr
import random as _qu_rand

QU_LOCK = _qu_thr.RLock()
QU_DUELS = {}        # duel_id -> duel dict
QU_BY_UID = {}       # uid -> duel_id (เฉพาะแมตช์ที่ยังไม่จบ)
QU_MAX_ROUNDS = 8
QU_ROUND_SEC = 15.0
QU_PENDING_SEC = 20.0
QU_HAND_SIZE = 4
QU_SHATTER_AT = 100.0
QU_KEEP_FINISHED_SEC = 300.0
QU_STAGES = [(0, "stable"), (35, "warped"), (65, "torn"), (90, "critical"), (100, "shattered")]
QU_STAGE_AMP = {"stable": 1.0, "warped": 1.15, "torn": 1.3, "critical": 1.5, "shattered": 1.5}
QU_CRITICAL_ECHO = 5.0   # ที่ critical ผู้โจมตีที่ตีโดนจะได้ค่าบิดเบือนย้อนกลับเท่านี้

QU_CARDS = {
    "star_strike":  {"name": "Star Strike",  "name_th": "ดาวตกพุ่งชน",   "kind": "attack",  "power": 18, "weight": 4},
    "comet_fall":   {"name": "Comet Fall",   "name_th": "ดาวหางถล่ม",    "kind": "attack",  "power": 30, "self_dist": 8, "weight": 2},
    "void_needle":  {"name": "Void Needle",  "name_th": "เข็มสุญญากาศ",  "kind": "attack",  "power": 14, "pierce": 0.5, "weight": 3},
    "orbit_shield": {"name": "Orbit Shield", "name_th": "โล่วงโคจร",     "kind": "guard",   "guard": 22, "weight": 4},
    "mirror_rift":  {"name": "Mirror Rift",  "name_th": "รอยแยกกระจก",   "kind": "reflect", "reflect": 0.5, "weight": 2},
    "stitch_space": {"name": "Stitch Space", "name_th": "เย็บอวกาศ",     "kind": "mend",    "mend": 20, "weight": 2},
}


def _qu_stage(dist):
    st = "stable"
    for th, name in QU_STAGES:
        if dist >= th:
            st = name
    return st


def _qu_draw(rng):
    ids = list(QU_CARDS.keys())
    return rng.choices(ids, weights=[QU_CARDS[i]["weight"] for i in ids], k=1)[0]


def _qu_new_side(uid, rng):
    return {"uid": uid, "dist": 0.0, "hand": [_qu_draw(rng) for _ in range(QU_HAND_SIZE)],
            "locked": None, "hits_taken": 0}


def _qu_clear(d):
    for u in (d["a"], d["b"]):
        if QU_BY_UID.get(u) == d["id"]:
            QU_BY_UID.pop(u, None)


def _qu_get(uid):
    did = QU_BY_UID.get(str(uid))
    return QU_DUELS.get(did) if did else None


def _qu_view(d, uid):
    """มุมมองของผู้เล่น: เห็นมือตัวเอง, ไม่เห็นการ์ดที่คู่ต่อสู้ล็อกไว้จนกว่ารอบจะเปิด"""
    uid = str(uid)
    me = d["sides"].get(uid)
    opp_uid = d["b"] if uid == d["a"] else d["a"]
    opp = d["sides"].get(opp_uid)
    now = _qu_time.time()
    v = {"id": d["id"], "status": d["status"], "round": d["round"], "max_rounds": QU_MAX_ROUNDS,
         "you": uid, "opponent": opp_uid,
         "round_seconds_left": max(0.0, round(d["round_deadline"] - now, 1)) if d["status"] == "active" else 0.0,
         "last_round": d["log"][-1] if d["log"] else None,
         "winner": d["winner"], "loser": d["loser"], "result": d["result"], "reason": d["reason"],
         "universe_shattered": d["result"] in ("shatter", "double_shatter")}
    if me:
        v["me"] = {"distortion": round(me["dist"], 1), "stage": _qu_stage(me["dist"]),
                   "hand": list(me["hand"]), "locked": me["locked"]}
    if opp:
        v["opp"] = {"distortion": round(opp["dist"], 1), "stage": _qu_stage(opp["dist"]),
                    "locked": opp["locked"] is not None}
    return v


def _qu_emit(d, event):
    for u in (d["a"], d["b"]):
        try:
            sio.emit(event, _qu_view(d, u), room=str(u))
        except Exception:
            pass


def _qu_finish(d, result, winner=None, reason=""):
    d["status"] = "finished"
    d["result"] = result
    d["winner"] = winner
    d["loser"] = (d["b"] if winner == d["a"] else d["a"]) if winner else None
    d["reason"] = reason
    d["finished_at"] = _qu_time.time()
    _qu_clear(d)
    _qu_emit(d, "quick_universe_end")
    if result in ("shatter", "double_shatter"):
        _qu_emit(d, "quick_universe_shatter")


def _qu_calc(att_card, def_side_dist_start, def_card):
    """คืน (ดาเมจที่ผู้รับโดน, ดาเมจสะท้อนกลับผู้โจมตี, echo ที่ critical ผู้โจมตีได้)"""
    if att_card["kind"] != "attack":
        return 0.0, 0.0, 0.0
    stage = _qu_stage(def_side_dist_start)
    raw = att_card["power"] * QU_STAGE_AMP[stage]
    guard = def_card.get("guard", 0) * (1.0 - att_card.get("pierce", 0.0))
    dmg = max(0.0, raw - guard)
    back = 0.0
    if def_card["kind"] == "reflect" and dmg > 0:
        back = dmg * def_card["reflect"]
        dmg -= back
    echo = QU_CRITICAL_ECHO if (stage in ("critical", "shattered") and dmg > 0) else 0.0
    return dmg, back, echo


def _qu_resolve_round(d):
    ua, ub = d["a"], d["b"]
    A, B = d["sides"][ua], d["sides"][ub]
    ida, idb = A["locked"], B["locked"]
    ca, cb = QU_CARDS[ida], QU_CARDS[idb]
    da0, db0 = A["dist"], B["dist"]          # ใช้ค่าต้นรอบทั้งคู่ เพื่อให้ชนกันพร้อมกันยุติธรรม
    dmg_b, back_a, echo_a = _qu_calc(ca, db0, cb)   # A ตี B
    dmg_a, back_b, echo_b = _qu_calc(cb, da0, ca)   # B ตี A
    gain_a = dmg_a + back_a + echo_a + ca.get("self_dist", 0)
    gain_b = dmg_b + back_b + echo_b + cb.get("self_dist", 0)
    A["dist"] = max(0.0, da0 + gain_a - (ca.get("mend", 0)))
    B["dist"] = max(0.0, db0 + gain_b - (cb.get("mend", 0)))
    if dmg_a > 0:
        A["hits_taken"] += 1
    if dmg_b > 0:
        B["hits_taken"] += 1
    # เติมมือ: เอาใบที่ลงออก แล้วจั่วใบใหม่
    for s, cid in ((A, ida), (B, idb)):
        try:
            s["hand"].remove(cid)
        except ValueError:
            pass
        s["hand"].append(_qu_draw(d["rng"]))
        s["locked"] = None
    entry = {"round": d["round"],
             "cards": {ua: ida, ub: idb},
             "damage": {ua: round(dmg_a, 1), ub: round(dmg_b, 1)},
             "reflected": {ua: round(back_a, 1), ub: round(back_b, 1)},
             "distortion": {ua: round(A["dist"], 1), ub: round(B["dist"], 1)},
             "stage": {ua: _qu_stage(A["dist"]), ub: _qu_stage(B["dist"])}}
    d["log"].append(entry)
    shatter_a, shatter_b = A["dist"] >= QU_SHATTER_AT, B["dist"] >= QU_SHATTER_AT
    if shatter_a and shatter_b:
        _qu_emit(d, "quick_universe_round")
        _qu_finish(d, "double_shatter", None, "จักรวาลแตกทั้งคู่พร้อมกัน")
        return
    if shatter_a or shatter_b:
        winner = ub if shatter_a else ua
        _qu_emit(d, "quick_universe_round")
        _qu_finish(d, "shatter", winner, "อวกาศของอีกฝ่ายบิดเบือนจนจักรวาลแตก")
        return
    if d["round"] >= QU_MAX_ROUNDS:
        _qu_emit(d, "quick_universe_round")
        if abs(A["dist"] - B["dist"]) < 0.05:
            _qu_finish(d, "draw", None, "ครบรอบ ค่าบิดเบือนเท่ากัน")
        else:
            _qu_finish(d, "decision", ua if A["dist"] < B["dist"] else ub, "ครบรอบ ฝั่งที่อวกาศบิดน้อยกว่าชนะ")
        return
    d["round"] += 1
    d["round_deadline"] = _qu_time.time() + QU_ROUND_SEC
    _qu_emit(d, "quick_universe_round")


def _qu_autoplay(d, s):
    if s["locked"] is None and s["hand"]:
        s["locked"] = d["rng"].choice(s["hand"])


def _qu_tick(d, now=None):
    """เรียกซ้ำได้ปลอดภัย: หมดเวลา pending / หมดเวลารอบ -> ระบบสุ่มการ์ดให้ฝั่งที่ยังไม่ลง"""
    now = _qu_time.time() if now is None else now
    if d["status"] == "pending" and now >= d["expires_at"]:
        d["status"] = "expired"
        _qu_clear(d)
        _qu_emit(d, "quick_universe_end")
    elif d["status"] == "active" and now >= d["round_deadline"]:
        for s in d["sides"].values():
            _qu_autoplay(d, s)
        _qu_resolve_round(d)


def vmax_qu_challenge(uid, target_uid):
    a, b = str(uid or ""), str(target_uid or "")
    if not a or not b or a == b:
        return {"ok": False, "reason": "invalid_players"}
    with QU_LOCK:
        for u in (a, b):
            old = _qu_get(u)
            if old:
                _qu_tick(old)
        if _qu_get(a) or _qu_get(b):
            return {"ok": False, "reason": "player_already_in_duel"}
        now = _qu_time.time()
        did = f"quick_universe_{int(now * 1000)}_{a}_{b}"
        rng = _qu_rand.Random()
        d = {"id": did, "a": a, "b": b, "status": "pending", "created_at": now,
             "expires_at": now + QU_PENDING_SEC, "round": 0, "round_deadline": 0.0,
             "sides": {}, "log": [], "winner": None, "loser": None, "result": None,
             "reason": "", "rng": rng, "finished_at": None}
        QU_DUELS[did] = d
        QU_BY_UID[a] = did
        QU_BY_UID[b] = did
        try:
            sio.emit("quick_universe_challenge", {"duel_id": did, "from": a, "to": b,
                                                  "expires_at": d["expires_at"]}, room=b)
        except Exception:
            pass
        return {"ok": True, "status": "pending", "duel_id": did}


def vmax_qu_accept(uid, duel_id=None, accept=True):
    uid = str(uid or "")
    with QU_LOCK:
        d = _qu_get(uid)
        if d:
            _qu_tick(d)
        if not d or d["status"] != "pending":
            return {"ok": False, "reason": "no_pending_duel"}
        if uid != d["b"]:
            return {"ok": False, "reason": "only_challenged_player_can_accept"}
        if duel_id and str(duel_id) != d["id"]:
            return {"ok": False, "reason": "duel_id_mismatch"}
        if not accept:
            d["status"] = "declined"
            _qu_clear(d)
            try:
                sio.emit("quick_universe_declined", {"duel_id": d["id"]}, room=d["a"])
            except Exception:
                pass
            return {"ok": True, "status": "declined"}
        d["sides"] = {d["a"]: _qu_new_side(d["a"], d["rng"]), d["b"]: _qu_new_side(d["b"], d["rng"])}
        d["status"] = "active"
        d["round"] = 1
        d["round_deadline"] = _qu_time.time() + QU_ROUND_SEC
        _qu_emit(d, "quick_universe_start")
        return {"ok": True, "status": "active", "state": _qu_view(d, uid)}


def vmax_qu_play(uid, card_id):
    uid = str(uid or "")
    with QU_LOCK:
        d = _qu_get(uid)
        if d:
            _qu_tick(d)
        if not d or d["status"] != "active":
            return {"ok": False, "reason": "duel_not_active"}
        s = d["sides"][uid]
        if s["locked"] is not None:
            return {"ok": False, "reason": "already_locked"}
        if card_id not in s["hand"]:
            return {"ok": False, "reason": "card_not_in_hand"}
        s["locked"] = card_id
        if all(x["locked"] is not None for x in d["sides"].values()):
            _qu_resolve_round(d)
        else:
            try:
                sio.emit("quick_universe_opponent_locked", {"duel_id": d["id"]},
                         room=str(d["b"] if uid == d["a"] else d["a"]))
            except Exception:
                pass
        return {"ok": True, "state": _qu_view(d, uid)}


def vmax_qu_forfeit(uid):
    uid = str(uid or "")
    with QU_LOCK:
        d = _qu_get(uid)
        if not d or d["status"] not in ("pending", "active"):
            return {"ok": False, "reason": "no_duel"}
        if d["status"] == "pending":
            d["status"] = "declined"
            _qu_clear(d)
            return {"ok": True, "status": "declined"}
        winner = d["b"] if uid == d["a"] else d["a"]
        _qu_finish(d, "forfeit", winner, "ยอมแพ้")
        return {"ok": True, "state": _qu_view(d, uid)}


def vmax_qu_state(uid):
    uid = str(uid or "")
    with QU_LOCK:
        d = _qu_get(uid)
        if not d:
            # แมตช์ที่เพิ่งจบ ให้ดูผลล่าสุดได้ช่วงสั้น ๆ
            recent = [x for x in QU_DUELS.values() if uid in (x["a"], x["b"]) and x["status"] != "pending"
                      and (x.get("finished_at") or 0) > _qu_time.time() - QU_KEEP_FINISHED_SEC]
            if recent:
                recent.sort(key=lambda x: x.get("finished_at") or 0)
                return {"ok": True, "duel": _qu_view(recent[-1], uid)}
            return {"ok": True, "duel": None}
        _qu_tick(d)
        return {"ok": True, "duel": _qu_view(d, uid)}


def _qu_sweeper():
    while True:
        _qu_time.sleep(1.0)
        try:
            with QU_LOCK:
                now = _qu_time.time()
                for d in list(QU_DUELS.values()):
                    if d["status"] in ("pending", "active"):
                        _qu_tick(d, now)
                    elif now - (d.get("finished_at") or d["created_at"]) > QU_KEEP_FINISHED_SEC:
                        QU_DUELS.pop(d["id"], None)
        except Exception:
            pass


_QU_SWEEPER_STARTED = False
if not _QU_SWEEPER_STARTED:
    _QU_SWEEPER_STARTED = True
    try:
        _qu_thr.Thread(target=_qu_sweeper, name="vmax-quick-universe", daemon=True).start()
    except Exception:
        pass


