# ============================================================================
# VMAX DAY/NIGHT PAN QI — SUN + CRESCENT MOON SYNERGY
# ============================================================================
VMAX_DAYNIGHT_LOCK = threading.RLock()
VMAX_DAYNIGHT_STATE = {}
VMAX_DAYNIGHT_DAY_SEC = 240.0
VMAX_DAYNIGHT_NIGHT_SEC = 180.0
VMAX_DAYNIGHT_MAX_PAN = 100.0
VMAX_DAYNIGHT_PAN_DAY_RATE = 0.20
VMAX_DAYNIGHT_PAN_NIGHT_RATE = 0.45
VMAX_DAYNIGHT_SYNC_WINDOW = 0.18


def _vmax_daynight_now():
    return time.time()


def _vmax_daynight_phase(now=None):
    now = _vmax_daynight_now() if now is None else float(now)
    cycle = VMAX_DAYNIGHT_DAY_SEC + VMAX_DAYNIGHT_NIGHT_SEC
    pos = now % cycle
    if pos < VMAX_DAYNIGHT_DAY_SEC:
        return "day", pos / VMAX_DAYNIGHT_DAY_SEC
    return "night", (pos - VMAX_DAYNIGHT_DAY_SEC) / VMAX_DAYNIGHT_NIGHT_SEC


def _vmax_daynight_sky(phase, progress):
    if phase == "day":
        sun_angle = progress * 180.0
        return {
            "sky": "sunrise" if progress < 0.18 else ("sunset" if progress > 0.82 else "sunny_day"),
            "celestial": "sun",
            "celestial_icon": "☀️",
            "celestial_angle_deg": round(sun_angle, 2),
            "moon_visible": False,
            "sun_visible": True,
            "crescent_moon": False,
        }
    moon_angle = (progress * 180.0) - 90.0
    return {
        "sky": "night",
        "celestial": "crescent_moon",
        "celestial_icon": "☾",
        "celestial_angle_deg": round(moon_angle, 2),
        "moon_visible": True,
        "sun_visible": False,
        "crescent_moon": True,
    }


def _vmax_daynight_state(uid):
    uid = str(uid or "guest")
    now = _vmax_daynight_now()
    phase, progress = _vmax_daynight_phase(now)
    with VMAX_DAYNIGHT_LOCK:
        st = VMAX_DAYNIGHT_STATE.setdefault(uid, {"pan": 0.0, "last": now})
        dt = max(0.0, min(now - float(st.get("last", now)), 5.0))
        rate = VMAX_DAYNIGHT_PAN_NIGHT_RATE if phase == "night" else VMAX_DAYNIGHT_PAN_DAY_RATE
        st["pan"] = min(VMAX_DAYNIGHT_MAX_PAN, float(st.get("pan", 0.0)) + dt * rate)
        st["last"] = now
        sky = _vmax_daynight_sky(phase, progress)
        # The power only reaches its special synchronized boost when the sun/moon cycle
        # is inside the short transition window. Outside it, normal accumulation applies.
        transition = min(progress, 1.0 - progress)
        celestial_sync = transition <= VMAX_DAYNIGHT_SYNC_WINDOW
        sync_multiplier = 1.75 if celestial_sync else 1.0
        return {
            "uid": uid,
            "phase": phase,
            "phase_progress": round(progress, 4),
            "pan": round(st["pan"], 3),
            "pan_max": VMAX_DAYNIGHT_MAX_PAN,
            "pan_rate": rate,
            "celestial_sync": celestial_sync,
            "sync_multiplier": sync_multiplier,
            "sync_window": VMAX_DAYNIGHT_SYNC_WINDOW,
            "day_seconds": VMAX_DAYNIGHT_DAY_SEC,
            "night_seconds": VMAX_DAYNIGHT_NIGHT_SEC,
            "sky": sky,
            "ui_hint": "☾ กลางคืน: พลังปานฟื้นเร็วขึ้น" if phase == "night" else "☀️ กลางวัน: พลังปานสะสมต่อเนื่อง",
        }


def vmax_daynight_get(uid="guest"):
    return _vmax_daynight_state(uid)


def vmax_daynight_reset(uid="guest"):
    uid = str(uid or "guest")
    with VMAX_DAYNIGHT_LOCK:
        VMAX_DAYNIGHT_STATE[uid] = {"pan": 0.0, "last": _vmax_daynight_now()}
    return _vmax_daynight_state(uid)


