# VMAX EXTRACTION — PHYSICAL BACKPACK DETACH / ARM-SWING / THROW / PICKUP
# ----------------------------------------------------------------------------
# กระเป๋าเป้เป็นอุปกรณ์ที่พกติดตัวจริงใน state ของเกม ไม่ใช่แค่ inventory UI:
#   - ถอดเป้ออกจากตัว -> ของที่อยู่ในเป้ถูกย้ายไปอยู่กับวัตถุ backpack ที่ถืออยู่
#   - ช่วง arm_swing ให้ client เล่นท่าควงเป้รอบแขนก่อนปล่อย
#   - โยน -> สร้างวัตถุ backpack บนโลกพร้อม velocity + spin แบบ server-authoritative
#   - ผู้เล่นอื่น/เจ้าของเดินมาเก็บ -> ได้ backpack และของด้านในกลับเข้ากระเป๋า
#   - ใช้ PLAYER_STORAGE/backpack เดิม จึงไม่สร้าง inventory ใหม่มาซ้อนกัน
# ============================================================================
VMAX_BACKPACK_THROW_LOCK = threading.RLock()
VMAX_BACKPACK_THROW_STATE = {}       # uid -> current carried/animation state
VMAX_BACKPACK_THROW_GROUND = {}      # backpack_id -> thrown world object
VMAX_BACKPACK_THROW_EXPIRE_SEC = 15 * 60
VMAX_BACKPACK_THROW_SWING_SEC = 0.55
VMAX_BACKPACK_THROW_GRAVITY = 9.81
VMAX_BACKPACK_THROW_DEFAULT_SPEED = 8.5
VMAX_BACKPACK_THROW_READY = True


def _vmax_bp_contents_copy(box):
    return {
        str(slot): {
            "item": str(v.get("item", "")),
            "qty": max(0, int(v.get("qty", 0))),
        }
        for slot, v in dict(box or {}).items()
        if isinstance(v, dict) and str(v.get("item", "")) and int(v.get("qty", 0)) > 0
    }


def _vmax_bp_player_state(uid):
    uid = str(uid)
    return VMAX_BACKPACK_THROW_STATE.setdefault(uid, {
        "equipped": True,
        "phase": "equipped",
        "backpack_id": None,
        "held_contents": {},
        "animation_started_at": None,
        "animation_until": None,
        "last_throw_id": None,
    })


def _vmax_bp_public_state(uid):
    uid = str(uid)
    with VMAX_BACKPACK_THROW_LOCK:
        st = dict(_vmax_bp_player_state(uid))
        st["held_contents"] = _vmax_bp_contents_copy(st.get("held_contents", {}))
        storage = storage_get(uid)
        st["backpack_slots"] = int(storage.get("backpack_slots", STORAGE_SLOTS_DEFAULT))
        st["storage_backpack_items"] = _vmax_bp_contents_copy(storage.get("backpack", {}))
        return st


def _vmax_bp_detach_locked(uid):
    st = _vmax_bp_player_state(uid)
    if not st.get("equipped", True):
        return {"ok": False, "reason": "backpack_not_equipped", "state": dict(st)}
    storage = storage_get(uid)
    contents = _vmax_bp_contents_copy(storage.get("backpack", {}))
    storage["backpack"].clear()
    now = time.time()
    st.update({
        "equipped": False,
        "phase": "arm_swing",
        "backpack_id": str(uuid.uuid4()),
        "held_contents": contents,
        "animation_started_at": now,
        "animation_until": now + VMAX_BACKPACK_THROW_SWING_SEC,
        "last_throw_id": None,
    })
    return {"ok": True, "phase": "arm_swing", "backpack_id": st["backpack_id"],
            "contents_slots": len(contents), "animation_sec": VMAX_BACKPACK_THROW_SWING_SEC}


def vmax_backpack_detach(uid):
    """ถอดเป้ออกมาถือที่แขน; ยังไม่โยนจนกว่าจะเรียก throw."""
    uid = str(uid)
    with VMAX_BACKPACK_THROW_LOCK:
        return _vmax_bp_detach_locked(uid)


def vmax_backpack_throw(uid, x=0.0, y=1.0, z=0.0, dx=0.0, dy=0.18, dz=1.0, speed=None):
    """ถอดเป้ (ถ้ายังใส่อยู่) -> ควงแขน -> ปล่อยเป้เป็นวัตถุฟิสิกส์บนโลก."""
    uid = str(uid)
    try:
        x, y, z = float(x), float(y), float(z)
        dx, dy, dz = float(dx), float(dy), float(dz)
    except (TypeError, ValueError):
        return {"ok": False, "reason": "invalid_position_or_direction"}
    with VMAX_BACKPACK_THROW_LOCK:
        st = _vmax_bp_player_state(uid)
        if st.get("phase") == "arm_swing" and st.get("backpack_id"):
            pass
        elif st.get("equipped", True):
            r = _vmax_bp_detach_locked(uid)
            if not r.get("ok"):
                return r
            st = _vmax_bp_player_state(uid)
        elif st.get("phase") != "arm_swing" or not st.get("backpack_id"):
            return {"ok": False, "reason": "backpack_not_available"}

        mag = math.sqrt(dx*dx + dy*dy + dz*dz) or 1.0
        dx, dy, dz = dx/mag, dy/mag, dz/mag
        power = max(1.0, min(30.0, float(speed if speed is not None else VMAX_BACKPACK_THROW_DEFAULT_SPEED)))
        now = time.time()
        backpack_id = st["backpack_id"]
        ground = {
            "backpack_id": backpack_id,
            "uid_thrower": uid,
            "contents": _vmax_bp_contents_copy(st.get("held_contents", {})),
            "x": x,
            "y": max(0.15, y),
            "z": z,
            "vx": dx * power,
            "vy": dy * power + 1.2,
            "vz": dz * power,
            "gravity": VMAX_BACKPACK_THROW_GRAVITY,
            "spin": {"x": 7.5, "y": 11.0, "z": 5.0},
            "thrown_at": now,
            "landed": False,
            "claimed": False,
            "expires_at": now + VMAX_BACKPACK_THROW_EXPIRE_SEC,
            "animation": {
                "type": "backpack_arm_swing_throw",
                "swing_sec": VMAX_BACKPACK_THROW_SWING_SEC,
                "release_sec": VMAX_BACKPACK_THROW_SWING_SEC,
            },
        }
        VMAX_BACKPACK_THROW_GROUND[backpack_id] = ground
        st.update({
            "equipped": False,
            "phase": "thrown",
            "held_contents": {},
            "animation_started_at": now,
            "animation_until": now + VMAX_BACKPACK_THROW_SWING_SEC,
            "last_throw_id": backpack_id,
        })
        payload = {
            "ok": True,
            "backpack_id": backpack_id,
            "phase": "thrown",
            "position": {"x": x, "y": max(0.15, y), "z": z},
            "velocity": {"x": dx*power, "y": dy*power + 1.2, "z": dz*power},
            "animation": ground["animation"],
            "contents_slots": len(ground["contents"]),
        }
        try:
            sio.emit("backpack_arm_swing_throw", {"uid": uid, **payload})
        except Exception:
            pass
        return payload


def _vmax_bp_ground_position(d, now=None):
    now = time.time() if now is None else float(now)
    t = max(0.0, now - float(d.get("thrown_at", now)))
    x = float(d.get("x", 0.0)) + float(d.get("vx", 0.0)) * t
    z = float(d.get("z", 0.0)) + float(d.get("vz", 0.0)) * t
    y0 = float(d.get("y", 0.15))
    y = y0 + float(d.get("vy", 0.0))*t - 0.5*float(d.get("gravity", VMAX_BACKPACK_THROW_GRAVITY))*t*t
    if y <= 0.15:
        y = 0.15
        d["landed"] = True
    return {"x": x, "y": y, "z": z, "t": t, "landed": bool(d.get("landed"))}


def vmax_backpack_ground_items():
    now = time.time()
    with VMAX_BACKPACK_THROW_LOCK:
        expired = [bid for bid, d in VMAX_BACKPACK_THROW_GROUND.items()
                   if d.get("claimed") or now >= float(d.get("expires_at", now))]
        for bid in expired:
            VMAX_BACKPACK_THROW_GROUND.pop(bid, None)
        out = {}
        for bid, d in VMAX_BACKPACK_THROW_GROUND.items():
            pos = _vmax_bp_ground_position(d, now)
            out[bid] = {
                "backpack_id": bid,
                "uid_thrower": d.get("uid_thrower"),
                "position": {k: pos[k] for k in ("x", "y", "z")},
                "landed": pos["landed"],
                "expires_in_sec": max(0, int(float(d.get("expires_at", now)) - now)),
                "contents_slots": len(d.get("contents", {})),
                "claimed": bool(d.get("claimed")),
                "animation": d.get("animation", {}),
            }
        return out


def vmax_backpack_pickup(uid, backpack_id, x=None, y=None, z=None, max_distance=4.0):
    uid = str(uid)
    backpack_id = str(backpack_id or "")
    with VMAX_BACKPACK_THROW_LOCK:
        d = VMAX_BACKPACK_THROW_GROUND.get(backpack_id)
        if not d:
            return {"ok": False, "reason": "backpack_not_found"}
        now = time.time()
        if d.get("claimed"):
            return {"ok": False, "reason": "backpack_already_claimed"}
        if now >= float(d.get("expires_at", now)):
            VMAX_BACKPACK_THROW_GROUND.pop(backpack_id, None)
            return {"ok": False, "reason": "backpack_expired"}
        st = _vmax_bp_player_state(uid)
        if st.get("equipped", True):
            return {"ok": False, "reason": "backpack_already_equipped"}
        pos = _vmax_bp_ground_position(d, now)
        if x is not None and z is not None:
            try:
                dist = math.sqrt((float(x)-pos["x"])**2 + (float(z)-pos["z"])**2)
                if dist > float(max_distance):
                    return {"ok": False, "reason": "too_far", "distance": dist, "max_distance": float(max_distance)}
            except (TypeError, ValueError):
                return {"ok": False, "reason": "invalid_pickup_position"}
        storage = storage_get(uid)
        box = storage["backpack"]
        incoming = _vmax_bp_contents_copy(d.get("contents", {}))
        # Merge by item name; only consume a new slot when the item is not already present.
        existing_items = {str(v.get("item")): k for k, v in box.items() if isinstance(v, dict)}
        needed_new = sum(1 for v in incoming.values() if str(v.get("item")) not in existing_items)
        if len(box) + needed_new > int(storage.get("backpack_slots", STORAGE_SLOTS_DEFAULT)):
            return {"ok": False, "reason": "backpack_capacity_exceeded"}
        for v in incoming.values():
            item = str(v["item"]); qty = int(v["qty"])
            if item in existing_items:
                box[existing_items[item]]["qty"] += qty
            else:
                slot = str(len(box))
                box[slot] = {"item": item, "qty": qty}
                existing_items[item] = slot
        d["claimed"] = True
        VMAX_BACKPACK_THROW_GROUND.pop(backpack_id, None)
        st.update({
            "equipped": True,
            "phase": "equipped",
            "backpack_id": None,
            "held_contents": {},
            "animation_started_at": now,
            "animation_until": now,
        })
        try:
            sio.emit("backpack_equipped", {"uid": uid, "backpack_id": backpack_id})
        except Exception:
            pass
        return {"ok": True, "picked_up": backpack_id, "items_restored": incoming,
                "backpack": box, "phase": "equipped"}


def _vmax_backpack_throw_expire_loop():
    while True:
        try:
            now = time.time()
            with VMAX_BACKPACK_THROW_LOCK:
                expired = [bid for bid, d in VMAX_BACKPACK_THROW_GROUND.items()
                           if d.get("claimed") or now >= float(d.get("expires_at", now))]
                for bid in expired:
                    VMAX_BACKPACK_THROW_GROUND.pop(bid, None)
        except Exception as exc:
            print(f"[backpack_throw] expire loop error: {exc}")
        time.sleep(30)


def _run_backpack_throw_selftest():
    """Selftest แบบไม่ต้องเปิด Flask: detach -> throw -> pickup และเช็ค inventory ไม่ดูป."""
    uid = "__backpack_throw_selftest__"
    with VMAX_BACKPACK_THROW_LOCK:
        PLAYER_STORAGE.pop(uid, None)
        VMAX_BACKPACK_THROW_STATE.pop(uid, None)
        stg = storage_get(uid)
        stg["backpack"]["0"] = {"item": "bandage", "qty": 3}
        r1 = vmax_backpack_detach(uid)
        assert r1["ok"] and r1["phase"] == "arm_swing"
        assert storage_get(uid)["backpack"] == {}
        r2 = vmax_backpack_throw(uid, 0, 1, 0, 0, 0.2, 1, 4)
        assert r2["ok"] and r2["phase"] == "thrown"
        bid = r2["backpack_id"]
        # ให้ pickup ผ่านโดยไม่ต้องพึ่งระยะ/ฟิสิกส์จริง
        r3 = vmax_backpack_pickup(uid, bid)
        assert r3["ok"]
        assert storage_get(uid)["backpack"]["0"]["item"] == "bandage"
        assert storage_get(uid)["backpack"]["0"]["qty"] == 3
        PLAYER_STORAGE.pop(uid, None)
        VMAX_BACKPACK_THROW_STATE.pop(uid, None)
        VMAX_BACKPACK_THROW_GROUND.pop(bid, None)
    return True


@app.route('/api/backpack/state', methods=['GET'])
@require_auth_toggleable
def api_backpack_throw_state():
    uid = request.args.get("uid") or request.args.get("user_id") or "guest"
    return jsonify({"ok": True, "player": _vmax_bp_public_state(uid),
                    "ground": vmax_backpack_ground_items()})


@app.route('/api/backpack/detach', methods=['POST'])
@require_auth_toggleable
def api_backpack_detach():
    body = request.get_json(silent=True) or {}
    uid = _vmax_authenticated_owner_uid(body)
    if not uid:
        return jsonify({"ok": False, "reason": "uid_required"}), 401
    return jsonify(vmax_backpack_detach(uid))


@app.route('/api/backpack/throw', methods=['POST'])
@require_auth_toggleable
def api_backpack_throw():
    body = request.get_json(silent=True) or {}
    uid = _vmax_authenticated_owner_uid(body)
    if not uid:
        return jsonify({"ok": False, "reason": "uid_required"}), 401
    return jsonify(vmax_backpack_throw(
        uid,
        body.get("x", 0), body.get("y", 1.0), body.get("z", 0),
        body.get("dx", 0), body.get("dy", 0.18), body.get("dz", 1),
        body.get("speed", VMAX_BACKPACK_THROW_DEFAULT_SPEED),
    ))


@app.route('/api/backpack/pickup', methods=['POST'])
@require_auth_toggleable
def api_backpack_pickup():
    body = request.get_json(silent=True) or {}
    uid = _vmax_authenticated_owner_uid(body)
    if not uid:
        return jsonify({"ok": False, "reason": "uid_required"}), 401
    return jsonify(vmax_backpack_pickup(uid, body.get("backpack_id"),
                                        body.get("x"), body.get("y"), body.get("z"),
                                        body.get("max_distance", 4.0)))


