def _vmax_network_mission(mid):
    return VMAX_SKY_CITY_MISSIONS.get(str(mid or "").strip())


def _vmax_network_state(uid, mid):
    # Reuse the already-existing mission-state store so every access point sees
    # exactly the same accepted/progress/submitted/completed state.
    return _vmax_mission_state(uid, mid)


def _vmax_network_visible_missions(uid, mission_ids=None):
    ids = mission_ids or list(VMAX_SKY_CITY_MISSIONS.keys())
    out = []
    for mid in ids:
        m = _vmax_network_mission(mid)
        if not m:
            continue
        out.append({**m, **_pass_mission_game_info(m), "state": _vmax_network_state(uid, mid)})
    return out


def _vmax_network_accept(uid, mid, source_type, source_id):
    mission = _vmax_network_mission(mid)
    if not mission:
        return None, {"st": "error", "msg": "ไม่พบภารกิจในเครือข่าย"}, 404
    state = _vmax_network_state(uid, mid)
    if state["status"] not in ("available", "cancelled"):
        return None, {"st": "error", "msg": "ภารกิจนี้รับไปแล้ว"}, 409
    state.update({
        "status": "active",
        "progress": 0,
        "required": max(1, int(mission.get("objective", {}).get("count", 1))),
        "reward_claimed": False,
        "accepted_at": time.time(),
        "accepted_source": {
            "type": source_type,
            "id": source_id,
        },
    })
    return state, None, 200


def _vmax_network_submit(uid, mid, source_type, source_id):
    mission = _vmax_network_mission(mid)
    if not mission:
        return None, {"st": "error", "msg": "ไม่พบภารกิจในเครือข่าย"}, 404
    state = _vmax_network_state(uid, mid)
    if state["status"] != "ready_to_submit":
        return None, {"st": "error", "msg": "ภารกิจยังทำไม่ครบ"}, 409
    state.update({
        "status": "submitted",
        "submitted_at": time.time(),
        "submitted_source": {
            "type": source_type,
            "id": source_id,
        },
    })
    return state, None, 200


def _vmax_network_claim(uid, mid, source_type, source_id):
    mission = _vmax_network_mission(mid)
    if not mission:
        return None, {"st": "error", "msg": "ไม่พบภารกิจในเครือข่าย"}, 404
    state = _vmax_network_state(uid, mid)
    if state["status"] != "submitted":
        return None, {"st": "error", "msg": "ยังไม่มีรางวัลให้รับ"}, 409
    if state.get("reward_claimed"):
        return None, {"st": "error", "msg": "รับรางวัลไปแล้ว"}, 409
    state.update({
        "reward_claimed": True,
        "status": "completed",
        "completed_at": time.time(),
        "claimed_source": {
            "type": source_type,
            "id": source_id,
        },
    })
    _pass_mission_claimed(uid, mid, state, source_type, source_id)   # EXP ให้ 2 พาส (NPC มอบ = เยอะกว่า)
    return state, None, 200


