@app.route("/api/missions/network/accept", methods=["POST"])
def api_mission_network_accept():
    data = request.get_json(silent=True) or {}
    uid = _vmax_mission_uid(data.get("uid"))
    mid = str(data.get("mission_id") or "").strip()
    source_type = str(data.get("source_type") or "mission_tab").strip()
    source_id = str(data.get("source_id") or "player_mission_tab").strip()
    state, err, code = _vmax_network_accept(uid, mid, source_type, source_id)
    if err:
        return jsonify(err), code
    return jsonify({
        "st": "ok",
        "accepted": True,
        "shared_mission": True,
        "state": state,
        "message": "รับภารกิจแล้ว สามารถไปทำและกลับมาส่งจากจุดภารกิจที่เชื่อมต่อได้",
    })


@app.route("/api/missions/network/progress", methods=["POST"])
def api_mission_network_progress():
    data = request.get_json(silent=True) or {}
    uid = _vmax_mission_uid(data.get("uid"))
    mid = str(data.get("mission_id") or "").strip()
    mission = _vmax_network_mission(mid)
    if not mission:
        return jsonify({"st": "error", "msg": "ไม่พบภารกิจในเครือข่าย"}), 404
    _need_game = _pass_mission_requires_game(mission)
    if _need_game:
        return jsonify({"st": "error", "msg": "ภารกิจนี้ต้องไปทำในเกม " + str(PASS_GAMES[_need_game].get("name_th") or _need_game),
                        "target_game_id": _need_game}), 403
    state = _vmax_network_state(uid, mid)
    if state["status"] != "active":
        return jsonify({"st": "error", "msg": "ภารกิจยังไม่ได้รับ"}), 409
    amount = max(1, int(data.get("amount", 1)))
    state["progress"] = min(state["required"], int(state.get("progress", 0)) + amount)
    if state["progress"] >= state["required"]:
        state["status"] = "ready_to_submit"
    return jsonify({"st": "ok", "shared_mission": True, "state": state})


@app.route("/api/missions/network/submit", methods=["POST"])
def api_mission_network_submit():
    data = request.get_json(silent=True) or {}
    uid = _vmax_mission_uid(data.get("uid"))
    mid = str(data.get("mission_id") or "").strip()
    source_type = str(data.get("source_type") or "mission_tab").strip()
    source_id = str(data.get("source_id") or "player_mission_tab").strip()
    state, err, code = _vmax_network_submit(uid, mid, source_type, source_id)
    if err:
        return jsonify(err), code
    return jsonify({
        "st": "ok",
        "submitted": True,
        "claim_available": True,
        "shared_mission": True,
        "state": state,
    })


@app.route("/api/missions/network/claim", methods=["POST"])
def api_mission_network_claim():
    data = request.get_json(silent=True) or {}
    uid = _vmax_mission_uid(data.get("uid"))
    mid = str(data.get("mission_id") or "").strip()
    source_type = str(data.get("source_type") or "mission_tab").strip()
    source_id = str(data.get("source_id") or "player_mission_tab").strip()
    state, err, code = _vmax_network_claim(uid, mid, source_type, source_id)
    if err:
        return jsonify(err), code
    mission = _vmax_network_mission(mid)
    return jsonify({
        "st": "ok",
        "mission_completed": True,
        "reward": dict(mission.get("reward") or {}),
        "shared_mission": True,
        "state": state,
    })


