# ============================================================================
# VMAX IMAGE EMBEDDING / VECTOR MEMORY — CLIP + FAISS + ChromaDB
# ----------------------------------------------------------------------------
# ระบบนี้เพิ่ม "ความจำภาพ" ให้ VMAX แบบจริง:
#   1) OpenAI CLIP (ViT-B/32) -> image/text embeddings ที่อยู่ใน space เดียวกัน
#   2) FAISS -> vector index เร็วสำหรับค้นหาภาพจำนวนมาก (ถ้าติดตั้ง faiss-cpu)
#   3) ChromaDB -> persistent vector collection (ถ้าติดตั้ง chromadb)
#   4) SQLite -> metadata/index manifest และ fallback ที่ไม่ต้องมี vector DB
#
# สำคัญ: ถ้าไม่มี CLIP จะไม่แอบอ้างว่าเป็น image embedding จริง
# ระบบจะใช้ perceptual-hash (pHash) ได้เฉพาะ image-to-image fallback
# และ text-to-image semantic search จะตอบว่า CLIP ยังไม่พร้อม
#
# Environment:
#   VMAX_IMAGE_VECTOR_DIR=./vmax_image_vectors
#   VMAX_IMAGE_VECTOR_BACKEND=auto|faiss|chroma|sqlite
#   VMAX_CLIP_MODEL=ViT-B/32
#   VMAX_CLIP_DEVICE=auto|cpu|cuda
#   VMAX_IMAGE_EMBED_ALLOW_LOCAL_PATH=0
#
# Optional packages:
#   pip install faiss-cpu
#   pip install chromadb
#   pip install git+https://github.com/openai/CLIP.git
#   หรือใช้ transformers + torch:
#   pip install transformers torch torchvision
# ============================================================================

import os as _vimg_os
import io as _vimg_io
import json as _vimg_json
import time as _vimg_time
import uuid as _vimg_uuid
import hashlib as _vimg_hashlib
import sqlite3 as _vimg_sqlite3
import math as _vimg_math
import threading as _vimg_threading
import mimetypes as _vimg_mimetypes
from pathlib import Path as _vimg_Path

VMAX_IMAGE_VECTOR_DIR = _vimg_Path(
    _vimg_os.environ.get("VMAX_IMAGE_VECTOR_DIR", "vmax_image_vectors")
).resolve()
VMAX_IMAGE_VECTOR_DIR.mkdir(parents=True, exist_ok=True)
VMAX_IMAGE_VECTOR_DB = VMAX_IMAGE_VECTOR_DIR / "image_vectors.sqlite3"
VMAX_IMAGE_VECTOR_BACKEND = _vimg_os.environ.get(
    "VMAX_IMAGE_VECTOR_BACKEND", "auto"
).strip().lower()
VMAX_CLIP_MODEL_NAME = _vimg_os.environ.get("VMAX_CLIP_MODEL", "ViT-B/32")
VMAX_CLIP_DEVICE = _vimg_os.environ.get("VMAX_CLIP_DEVICE", "auto").strip().lower()
VMAX_IMAGE_EMBED_ALLOW_LOCAL_PATH = (
    _vimg_os.environ.get("VMAX_IMAGE_EMBED_ALLOW_LOCAL_PATH", "0") == "1"
)
VMAX_IMAGE_VECTOR_LOCK = _vimg_threading.RLock()
VMAX_IMAGE_VECTOR_READY = False


def _vimg_optional_imports():
    """โหลด optional backends แบบ lazy เพื่อไม่ทำให้ VMAX เดิมพังถ้าไม่มี package."""
    out = {
        "np": None, "Image": None, "faiss": None, "chromadb": None,
        "clip": None, "torch": None, "transformers": None
    }
    try:
        import numpy as _np
        out["np"] = _np
    except Exception:
        pass
    try:
        from PIL import Image as _Image
        out["Image"] = _Image
    except Exception:
        pass
    try:
        import faiss as _faiss
        out["faiss"] = _faiss
    except Exception:
        pass
    try:
        import chromadb as _chromadb
        out["chromadb"] = _chromadb
    except Exception:
        pass
    try:
        import torch as _torch
        out["torch"] = _torch
    except Exception:
        pass
    try:
        import clip as _clip
        if hasattr(_clip, "load") and hasattr(_clip, "tokenize"):
            out["clip"] = _clip
    except Exception:
        pass
    try:
        import transformers as _transformers
        if hasattr(_transformers, "CLIPModel") and hasattr(_transformers, "CLIPProcessor"):
            out["transformers"] = _transformers
    except Exception:
        pass
    return out


_VIMG_LIBS = _vimg_optional_imports()


def _vimg_db():
    conn = _vimg_sqlite3.connect(str(VMAX_IMAGE_VECTOR_DB), timeout=30)
    conn.row_factory = _vimg_sqlite3.Row
    conn.execute("""
        CREATE TABLE IF NOT EXISTS image_vectors (
            id TEXT PRIMARY KEY,
            sha256 TEXT UNIQUE NOT NULL,
            original_name TEXT,
            stored_path TEXT NOT NULL,
            mime_type TEXT,
            width INTEGER,
            height INTEGER,
            vector_dim INTEGER,
            vector_path TEXT,
            backend TEXT,
            phash TEXT,
            caption TEXT,
            metadata_json TEXT NOT NULL DEFAULT '{}',
            created_at REAL NOT NULL,
            updated_at REAL NOT NULL
        )
    """)
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_image_vectors_created "
        "ON image_vectors(created_at DESC)"
    )
    conn.commit()
    return conn


def _vimg_sha256(raw):
    return _vimg_hashlib.sha256(bytes(raw)).hexdigest()


def _vimg_safe_name(name):
    name = _vimg_Path(str(name or "image")).name
    return "".join(c if (c.isalnum() or c in "._-") else "_" for c in name)[:180] or "image"


def _vimg_phash(raw):
    """pHash fallback: useful for visual-near-duplicate detection, not semantic CLIP."""
    Image = _VIMG_LIBS["Image"]
    if Image is None:
        return None
    try:
        img = Image.open(_vimg_io.BytesIO(raw)).convert("L").resize((32, 32))
        np = _VIMG_LIBS["np"]
        if np is None:
            return None
        a = np.asarray(img, dtype=np.float32)
        # DCT without scipy: small 32x32 cosine transform matrix.
        n = 32
        x = np.arange(n, dtype=np.float32)
        k = np.arange(n, dtype=np.float32)
        c = np.cos(((2.0 * x[:, None] + 1.0) * k[None, :]) * _vimg_math.pi / (2.0 * n))
        c[:, 0] *= 1.0 / _vimg_math.sqrt(2.0)
        dct = (2.0 / n) * (c.T @ a @ c)
        low = dct[:8, :8]
        med = float(np.median(low[1:, 1:]))
        bits = "".join("1" if float(v) > med else "0" for v in low.ravel())
        return f"{int(bits, 2):016x}"
    except Exception:
        return None


def _vimg_hamming(a, b):
    if not a or not b:
        return None
    try:
        return (int(a, 16) ^ int(b, 16)).bit_count()
    except Exception:
        return None


class VMAXOpenAIClipEncoder:
    """OpenAI CLIP encoder with transformers fallback using OpenAI CLIP weights."""

    def __init__(self):
        self.backend = None
        self.model = None
        self.preprocess = None
        self.tokenizer = None
        self.processor = None
        self.device = "cpu"
        self.dim = None
        self.model_name = VMAX_CLIP_MODEL_NAME
        self.error = None
        self._load()

    def _choose_device(self):
        torch = _VIMG_LIBS["torch"]
        if torch is None:
            return "cpu"
        if VMAX_CLIP_DEVICE in ("cpu", "cuda"):
            if VMAX_CLIP_DEVICE == "cuda" and not torch.cuda.is_available():
                return "cpu"
            return VMAX_CLIP_DEVICE
        return "cuda" if torch.cuda.is_available() else "cpu"

    def _load(self):
        self.device = self._choose_device()

        # 1) OpenAI's reference CLIP package.
        clip = _VIMG_LIBS["clip"]
        if clip is not None:
            try:
                self.model, self.preprocess = clip.load(
                    self.model_name, device=self.device,
                    download_root=str(VMAX_IMAGE_VECTOR_DIR / "clip_cache")
                )
                self.model.eval()
                self.backend = "openai-clip"
                try:
                    self.dim = int(self.model.visual.output_dim)
                except Exception:
                    self.dim = None
                return
            except Exception as exc:
                self.error = f"OpenAI CLIP load failed: {exc}"

        # 2) Hugging Face transformers with OpenAI's published CLIP checkpoint.
        tr = _VIMG_LIBS["transformers"]
        torch = _VIMG_LIBS["torch"]
        if tr is not None and torch is not None:
            try:
                model_id = "openai/clip-vit-base-patch32"
                self.processor = tr.CLIPProcessor.from_pretrained(model_id)
                self.model = tr.CLIPModel.from_pretrained(model_id).to(self.device)
                self.model.eval()
                self.backend = "transformers-openai-clip"
                self.dim = int(self.model.config.projection_dim)
                return
            except Exception as exc:
                self.error = f"Transformers OpenAI CLIP load failed: {exc}"

        if not self.error:
            self.error = (
                "ยังไม่มี OpenAI CLIP backend — ติดตั้ง openai-clip + torch "
                "หรือ transformers + torch ก่อนใช้งาน semantic image/text search"
            )

    @property
    def available(self):
        return self.backend is not None and self.model is not None

    def _normalise(self, arr):
        np = _VIMG_LIBS["np"]
        if np is None:
            raise RuntimeError("numpy is required for CLIP embeddings")
        x = np.asarray(arr, dtype=np.float32)
        if x.ndim == 1:
            x = x[None, :]
        norms = np.linalg.norm(x, axis=1, keepdims=True)
        x = x / np.maximum(norms, 1e-12)
        return x.astype(np.float32)

    def image(self, raw):
        if not self.available:
            raise RuntimeError(self.error or "CLIP unavailable")
        Image = _VIMG_LIBS["Image"]
        if Image is None:
            raise RuntimeError("Pillow is required for image embeddings")
        img = Image.open(_vimg_io.BytesIO(raw)).convert("RGB")
        torch = _VIMG_LIBS["torch"]
        with torch.no_grad():
            if self.backend == "openai-clip":
                tensor = self.preprocess(img).unsqueeze(0).to(self.device)
                feat = self.model.encode_image(tensor)
                return self._normalise(feat.detach().cpu().numpy())[0]
            inputs = self.processor(images=img, return_tensors="pt")
            inputs = {k: v.to(self.device) for k, v in inputs.items()}
            feat = self.model.get_image_features(**inputs)
            return self._normalise(feat.detach().cpu().numpy())[0]

    def text(self, text):
        if not self.available:
            raise RuntimeError(self.error or "CLIP unavailable")
        torch = _VIMG_LIBS["torch"]
        with torch.no_grad():
            if self.backend == "openai-clip":
                tokens = self._openai_tokenize(text).to(self.device)
                feat = self.model.encode_text(tokens)
                return self._normalise(feat.detach().cpu().numpy())[0]
            inputs = self.processor(text=[str(text)], return_tensors="pt", padding=True)
            inputs = {k: v.to(self.device) for k, v in inputs.items()}
            feat = self.model.get_text_features(**inputs)
            return self._normalise(feat.detach().cpu().numpy())[0]

    def _openai_tokenize(self, text):
        clip = _VIMG_LIBS["clip"]
        return clip.tokenize([str(text)], truncate=True)


_VIMG_ENCODER = None
_VIMG_ENCODER_LOCK = _vimg_threading.Lock()


def vmax_image_embedding_encoder():
    """คืน encoder แบบ lazy เพื่อไม่โหลดโมเดล CLIP ตอน import ไฟล์หลัก."""
    global _VIMG_ENCODER
    with _VIMG_ENCODER_LOCK:
        if _VIMG_ENCODER is None:
            _VIMG_ENCODER = VMAXOpenAIClipEncoder()
        return _VIMG_ENCODER


def _vimg_backend():
    requested = VMAX_IMAGE_VECTOR_BACKEND
    if requested in ("faiss", "chroma", "sqlite"):
        if requested == "faiss" and _VIMG_LIBS["faiss"] is not None:
            return "faiss"
        if requested == "chroma" and _VIMG_LIBS["chromadb"] is not None:
            return "chroma"
        if requested == "sqlite":
            return "sqlite"
        return "sqlite"
    if _VIMG_LIBS["faiss"] is not None:
        return "faiss"
    if _VIMG_LIBS["chromadb"] is not None:
        return "chroma"
    return "sqlite"


def _vimg_vector_path(image_id):
    return VMAX_IMAGE_VECTOR_DIR / "vectors" / f"{_vimg_safe_name(image_id)}.json"


def _vimg_save_vector(image_id, vector):
    p = _vimg_vector_path(image_id)
    p.parent.mkdir(parents=True, exist_ok=True)
    with open(p, "w", encoding="utf-8") as f:
        _vimg_json.dump([float(x) for x in vector], f, separators=(",", ":"))
    return p


def _vimg_load_vector(row):
    p = row["vector_path"]
    if not p:
        return None
    try:
        with open(p, "r", encoding="utf-8") as f:
            return [float(x) for x in _vimg_json.load(f)]
    except Exception:
        return None


def _vimg_cosine(a, b):
    np = _VIMG_LIBS["np"]
    if np is None:
        dot = sum(float(x) * float(y) for x, y in zip(a, b))
        na = _vimg_math.sqrt(sum(float(x) * float(x) for x in a))
        nb = _vimg_math.sqrt(sum(float(y) * float(y) for y in b))
        return dot / max(na * nb, 1e-12)
    aa = np.asarray(a, dtype=np.float32)
    bb = np.asarray(b, dtype=np.float32)
    den = float(np.linalg.norm(aa) * np.linalg.norm(bb))
    return float(np.dot(aa, bb) / max(den, 1e-12))


def _vimg_read_row_image(row):
    try:
        return _vimg_Path(row["stored_path"]).read_bytes()
    except Exception:
        return None


class VMAXImageVectorStore:
    """Persistent image memory with CLIP vectors + optional FAISS/Chroma mirrors."""

    def __init__(self):
        self.backend = _vimg_backend()
        self._faiss_index = None
        self._faiss_ids = []
        self._chroma = None
        self._chroma_collection = None
        self._ensure_backend()

    def _ensure_backend(self):
        if self.backend == "faiss":
            self._load_faiss()
        elif self.backend == "chroma":
            self._load_chroma()

    def _load_faiss(self):
        faiss = _VIMG_LIBS["faiss"]
        np = _VIMG_LIBS["np"]
        if faiss is None or np is None:
            self.backend = "sqlite"
            return
        index_path = VMAX_IMAGE_VECTOR_DIR / "faiss.index"
        ids_path = VMAX_IMAGE_VECTOR_DIR / "faiss_ids.json"
        if index_path.exists() and ids_path.exists():
            try:
                self._faiss_index = faiss.read_index(str(index_path))
                self._faiss_ids = _vimg_json.loads(ids_path.read_text(encoding="utf-8"))
                return
            except Exception:
                self._faiss_index = None
                self._faiss_ids = []
        self._rebuild_faiss()

    def _rebuild_faiss(self):
        faiss = _VIMG_LIBS["faiss"]
        np = _VIMG_LIBS["np"]
        if faiss is None or np is None:
            return
        conn = _vimg_db()
        try:
            rows = conn.execute(
                "SELECT * FROM image_vectors WHERE vector_path IS NOT NULL ORDER BY created_at"
            ).fetchall()
        finally:
            conn.close()
        vecs, ids = [], []
        for row in rows:
            vec = _vimg_load_vector(row)
            if vec:
                vecs.append(vec); ids.append(row["id"])
        if not vecs:
            self._faiss_index = None
            self._faiss_ids = []
            return
        arr = np.asarray(vecs, dtype=np.float32)
        arr /= np.maximum(np.linalg.norm(arr, axis=1, keepdims=True), 1e-12)
        index = faiss.IndexFlatIP(arr.shape[1])
        index.add(arr)
        self._faiss_index = index
        self._faiss_ids = ids
        faiss.write_index(index, str(VMAX_IMAGE_VECTOR_DIR / "faiss.index"))
        (VMAX_IMAGE_VECTOR_DIR / "faiss_ids.json").write_text(
            _vimg_json.dumps(ids, ensure_ascii=False), encoding="utf-8"
        )

    def _load_chroma(self):
        chromadb = _VIMG_LIBS["chromadb"]
        if chromadb is None:
            self.backend = "sqlite"
            return
        try:
            self._chroma = chromadb.PersistentClient(path=str(VMAX_IMAGE_VECTOR_DIR / "chroma"))
            self._chroma_collection = self._chroma.get_or_create_collection(
                name="vmax_images",
                metadata={"hnsw:space": "cosine"}
            )
        except Exception:
            self.backend = "sqlite"
            self._chroma = None
            self._chroma_collection = None

    def add(self, raw, original_name="image", metadata=None, caption=""):
        Image = _VIMG_LIBS["Image"]
        if Image is None:
            raise RuntimeError("Pillow is required for image indexing")
        with _vimg_threading.RLock():
            digest = _vimg_sha256(raw)
            conn = _vimg_db()
            try:
                old = conn.execute(
                    "SELECT id FROM image_vectors WHERE sha256=?", (digest,)
                ).fetchone()
                if old:
                    return self.get(old["id"])
            finally:
                conn.close()

            img = Image.open(_vimg_io.BytesIO(raw)).convert("RGB")
            width, height = img.size
            image_id = _vimg_uuid.uuid4().hex
            stored_dir = VMAX_IMAGE_VECTOR_DIR / "images"
            stored_dir.mkdir(parents=True, exist_ok=True)
            ext = _vimg_Path(original_name).suffix.lower()
            if ext not in (".jpg", ".jpeg", ".png", ".webp", ".bmp", ".gif"):
                ext = ".png"
            stored = stored_dir / f"{image_id}{ext}"
            stored.write_bytes(raw)

            # CLIP is the semantic embedding path. If it is not installed yet,
            # keep the image + pHash instead of pretending pHash is a CLIP vector.
            # This makes ingestion durable even before the optional ML stack is installed.
            encoder = vmax_image_embedding_encoder()
            vector = None
            clip_error = None
            try:
                vector = encoder.image(raw)
            except Exception as exc:
                clip_error = str(exc)
            vector_path = _vimg_save_vector(image_id, vector) if vector is not None else None
            phash = _vimg_phash(raw)
            now = _vimg_time.time()
            backend = self.backend if vector is not None else "sqlite-phash"

            conn = _vimg_db()
            try:
                conn.execute("""
                    INSERT INTO image_vectors
                    (id,sha256,original_name,stored_path,mime_type,width,height,
                     vector_dim,vector_path,backend,phash,caption,metadata_json,created_at,updated_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """, (
                    image_id, digest, _vimg_safe_name(original_name), str(stored),
                    _vimg_mimetypes.guess_type(str(stored))[0] or "image/png",
                    int(width), int(height), (len(vector) if vector is not None else 0),
                    (str(vector_path) if vector_path is not None else None), backend,
                    phash, str(caption or ""),
                    _vimg_json.dumps(metadata or {}, ensure_ascii=False),
                    now, now
                ))
                conn.commit()
            finally:
                conn.close()

            if vector is not None and backend == "faiss":
                self._rebuild_faiss()
            elif vector is not None and backend == "chroma" and self._chroma_collection is not None:
                try:
                    self._chroma_collection.upsert(
                        ids=[image_id],
                        embeddings=[[float(x) for x in vector]],
                        metadatas=[{
                            "sha256": digest,
                            "original_name": _vimg_safe_name(original_name),
                            "stored_path": str(stored),
                            "caption": str(caption or "")
                        }]
                    )
                except Exception:
                    pass
            return self.get(image_id)

    def get(self, image_id):
        conn = _vimg_db()
        try:
            row = conn.execute(
                "SELECT * FROM image_vectors WHERE id=?", (str(image_id),)
            ).fetchone()
        finally:
            conn.close()
        return dict(row) if row else None

    def list(self, limit=50):
        limit = max(1, min(int(limit), 500))
        conn = _vimg_db()
        try:
            rows = conn.execute(
                "SELECT * FROM image_vectors ORDER BY created_at DESC LIMIT ?",
                (limit,)
            ).fetchall()
        finally:
            conn.close()
        return [dict(r) for r in rows]

    def _search_sqlite(self, vector, limit):
        conn = _vimg_db()
        try:
            rows = conn.execute("SELECT * FROM image_vectors").fetchall()
        finally:
            conn.close()
        scored = []
        for row in rows:
            vec = _vimg_load_vector(row)
            if not vec or len(vec) != len(vector):
                continue
            score = _vimg_cosine(vector, vec)
            scored.append((score, dict(row)))
        scored.sort(key=lambda x: x[0], reverse=True)
        return [{"score": float(score), "item": row} for score, row in scored[:limit]]

    def search_vector(self, vector, limit=10):
        limit = max(1, min(int(limit), 100))
        if self.backend == "faiss" and self._faiss_index is not None:
            np = _VIMG_LIBS["np"]
            q = np.asarray([vector], dtype=np.float32)
            q /= np.maximum(np.linalg.norm(q, axis=1, keepdims=True), 1e-12)
            scores, indices = self._faiss_index.search(q, min(limit, self._faiss_index.ntotal))
            out = []
            for score, idx in zip(scores[0], indices[0]):
                if idx < 0 or idx >= len(self._faiss_ids):
                    continue
                row = self.get(self._faiss_ids[idx])
                if row:
                    out.append({"score": float(score), "item": row})
            return out
        if self.backend == "chroma" and self._chroma_collection is not None:
            try:
                result = self._chroma_collection.query(
                    query_embeddings=[[float(x) for x in vector]],
                    n_results=limit,
                    include=["metadatas", "distances"]
                )
                ids = (result.get("ids") or [[]])[0]
                dists = (result.get("distances") or [[]])[0]
                out = []
                for iid, dist in zip(ids, dists):
                    row = self.get(iid)
                    if row:
                        out.append({"score": float(1.0 - dist), "item": row})
                return out
            except Exception:
                pass
        return self._search_sqlite(vector, limit)

    def search_image(self, raw, limit=10):
        encoder = vmax_image_embedding_encoder()
        try:
            vector = encoder.image(raw)
            return self.search_vector(vector, limit)
        except Exception:
            # Honest fallback: visual near-duplicate search only.
            return self.search_phash(raw, limit)

    def search_text(self, text, limit=10):
        encoder = vmax_image_embedding_encoder()
        vector = encoder.text(text)
        return self.search_vector(vector, limit)

    def search_phash(self, raw, limit=10):
        q = _vimg_phash(raw)
        if not q:
            return []
        conn = _vimg_db()
        try:
            rows = conn.execute(
                "SELECT * FROM image_vectors WHERE phash IS NOT NULL"
            ).fetchall()
        finally:
            conn.close()
        scored = []
        for row in rows:
            d = _vimg_hamming(q, row["phash"])
            if d is not None:
                # 64-bit pHash: 0.0 = identical, 1.0 = maximally different.
                score = 1.0 - (d / 64.0)
                scored.append((score, dict(row)))
        scored.sort(key=lambda x: x[0], reverse=True)
        return [{"score": float(s), "item": r} for s, r in scored[:limit]]

    def delete(self, image_id):
        row = self.get(image_id)
        if not row:
            return {"ok": False, "reason": "not_found"}
        conn = _vimg_db()
        try:
            conn.execute("DELETE FROM image_vectors WHERE id=?", (str(image_id),))
            conn.commit()
        finally:
            conn.close()
        for key in ("stored_path", "vector_path"):
            try:
                _vimg_Path(row[key]).unlink(missing_ok=True)
            except Exception:
                pass
        if self.backend == "faiss":
            self._rebuild_faiss()
        if self.backend == "chroma" and self._chroma_collection is not None:
            try:
                self._chroma_collection.delete(ids=[str(image_id)])
            except Exception:
                pass
        return {"ok": True, "id": str(image_id)}

    def status(self):
        conn = _vimg_db()
        try:
            count = int(conn.execute("SELECT COUNT(*) FROM image_vectors").fetchone()[0])
        finally:
            conn.close()
        encoder = _VIMG_ENCODER
        return {
            "ready": True,
            "backend": self.backend,
            "indexed_images": count,
            "vector_dir": str(VMAX_IMAGE_VECTOR_DIR),
            "faiss_available": _VIMG_LIBS["faiss"] is not None,
            "chromadb_available": _VIMG_LIBS["chromadb"] is not None,
            "numpy_available": _VIMG_LIBS["np"] is not None,
            "pillow_available": _VIMG_LIBS["Image"] is not None,
            "sqlite_fallback": True,
            "phash_fallback": True,
            "clip": {
                "loaded": bool(encoder and encoder.available),
                "backend": encoder.backend if encoder else None,
                "model": encoder.model_name if encoder else VMAX_CLIP_MODEL_NAME,
                "device": encoder.device if encoder else None,
                "dimension": encoder.dim if encoder else None,
                "error": encoder.error if encoder and not encoder.available else None
            }
        }


_VMAX_IMAGE_VECTOR_STORE = VMAXImageVectorStore()
VMAX_IMAGE_VECTOR_READY = True


def _vimg_json_result(row):
    if not row:
        return None
    out = dict(row)
    try:
        out["metadata"] = _vimg_json.loads(out.pop("metadata_json", "{}"))
    except Exception:
        out["metadata"] = {}
        out.pop("metadata_json", None)
    # ไม่ส่ง absolute local path ออก API โดยตรง
    out.pop("vector_path", None)
    out.pop("stored_path", None)
    return out


@app.route("/api/image-embedding/status", methods=["GET"])
def api_image_embedding_status():
    return jsonify({"st": "ok", "system": _VMAX_IMAGE_VECTOR_STORE.status()})


@app.route("/api/image-embedding/list", methods=["GET"])
@require_auth_toggleable
def api_image_embedding_list():
    limit = request.args.get("limit", 50)
    try:
        limit = max(1, min(int(limit), 500))
    except Exception:
        limit = 50
    return jsonify({
        "st": "ok",
        "items": [_vimg_json_result(x) for x in _VMAX_IMAGE_VECTOR_STORE.list(limit)]
    })


@app.route("/api/image-embedding/index", methods=["POST"])
@require_auth_toggleable
def api_image_embedding_index():
    """รับ multipart file: image หรือ JSON {image_path: ...} เมื่อเปิด local-path mode."""
    try:
        metadata = {}
        caption = ""
        if request.files.get("image") is not None:
            f = request.files["image"]
            raw = f.read()
            name = secure_filename(f.filename or "image") or "image"
            metadata_raw = request.form.get("metadata", "{}")
            caption = request.form.get("caption", "")
            try:
                metadata = _vimg_json.loads(metadata_raw) if metadata_raw else {}
                if not isinstance(metadata, dict):
                    metadata = {}
            except Exception:
                return jsonify({"st": "error", "msg": "metadata ต้องเป็น JSON object"}), 400
        else:
            body = request.get_json(silent=True) or {}
            local_path = str(body.get("image_path", "")).strip()
            if not local_path or not VMAX_IMAGE_EMBED_ALLOW_LOCAL_PATH:
                return jsonify({
                    "st": "error",
                    "msg": "ส่งไฟล์ field=image หรือเปิด VMAX_IMAGE_EMBED_ALLOW_LOCAL_PATH=1 สำหรับ image_path"
                }), 400
            p = _vimg_Path(local_path).resolve()
            raw = p.read_bytes()
            name = p.name
            metadata = body.get("metadata") if isinstance(body.get("metadata"), dict) else {}
            caption = str(body.get("caption", ""))
        if not raw:
            return jsonify({"st": "error", "msg": "ไฟล์ภาพว่าง"}), 400
        if len(raw) > 25 * 1024 * 1024:
            return jsonify({"st": "error", "msg": "ไฟล์ภาพใหญ่เกิน 25 MB"}), 413

        item = _VMAX_IMAGE_VECTOR_STORE.add(
            raw, original_name=name, metadata=metadata, caption=caption
        )
        return jsonify({"st": "ok", "item": _vimg_json_result(item)})
    except Exception as exc:
        return jsonify({"st": "error", "msg": str(exc)}), 400


@app.route("/api/image-embedding/search", methods=["POST"])
@require_auth_toggleable
def api_image_embedding_search():
    """รองรับ image-to-image หรือ text-to-image ผ่าน CLIP; mode=phash เป็น fallback."""
    try:
        body = request.get_json(silent=True) or {}
        limit = max(1, min(int(body.get("limit", 10)), 100))
        mode = str(body.get("mode", "text")).lower()
        if mode == "text":
            query = str(body.get("query", "")).strip()
            if not query:
                return jsonify({"st": "error", "msg": "ต้องมี query"}), 400
            results = _VMAX_IMAGE_VECTOR_STORE.search_text(query, limit)
        elif mode == "phash":
            if request.files.get("image") is not None:
                raw = request.files["image"].read()
            else:
                raw_b64 = str(body.get("image_base64", ""))
                if not raw_b64:
                    return jsonify({"st": "error", "msg": "ต้องมี image หรือ image_base64"}), 400
                import base64 as _vimg_b64
                raw = _vimg_b64.b64decode(raw_b64)
            results = _VMAX_IMAGE_VECTOR_STORE.search_phash(raw, limit)
        else:
            return jsonify({
                "st": "error",
                "msg": "โหมด image ต้องส่ง multipart field=image; ใช้ mode=text สำหรับข้อความ หรือ mode=phash สำหรับ fallback"
            }), 400
        return jsonify({
            "st": "ok",
            "mode": mode,
            "results": [
                {"score": r["score"], "item": _vimg_json_result(r["item"])}
                for r in results
            ]
        })
    except Exception as exc:
        return jsonify({"st": "error", "msg": str(exc)}), 400


@app.route("/api/image-embedding/search-image", methods=["POST"])
@require_auth_toggleable
def api_image_embedding_search_image():
    try:
        if request.files.get("image") is not None:
            raw = request.files["image"].read()
        else:
            body = request.get_json(silent=True) or {}
            import base64 as _vimg_b64
            raw = _vimg_b64.b64decode(str(body.get("image_base64", "")))
        if not raw:
            return jsonify({"st": "error", "msg": "ไม่พบภาพค้นหา"}), 400
        limit = max(1, min(int((request.args.get("limit") or 10)), 100))
        results = _VMAX_IMAGE_VECTOR_STORE.search_image(raw, limit)
        return jsonify({
            "st": "ok", "mode": "clip-image", "results": [
                {"score": r["score"], "item": _vimg_json_result(r["item"])}
                for r in results
            ]
        })
    except Exception as exc:
        return jsonify({"st": "error", "msg": str(exc)}), 400


@app.route("/api/image-embedding/<image_id>", methods=["GET", "DELETE"])
@require_auth_toggleable
def api_image_embedding_item(image_id):
    if request.method == "GET":
        row = _VMAX_IMAGE_VECTOR_STORE.get(image_id)
        if not row:
            return jsonify({"st": "error", "msg": "not_found"}), 404
        return jsonify({"st": "ok", "item": _vimg_json_result(row)})
    return jsonify(_VMAX_IMAGE_VECTOR_STORE.delete(image_id))


