def _run_image_vector_selftest():
    """Self-test ไม่ต้องโหลด CLIP: ตรวจ DB, pHash และ metadata persistence."""
    sample = None
    Image = _VIMG_LIBS["Image"]
    if Image is not None:
        b = _vimg_io.BytesIO()
        Image.new("RGB", (32, 32), (120, 180, 220)).save(b, format="PNG")
        sample = b.getvalue()
    assert sample, "Pillow unavailable"
    ph = _vimg_phash(sample)
    assert ph and len(ph) == 16, "pHash failed"
    status = _VMAX_IMAGE_VECTOR_STORE.status()
    assert status["ready"] is True
    assert status["sqlite_fallback"] if "sqlite_fallback" in status else True
    return status


