# ============================================================================
# [VMAX DAILY WORLD MISSION / NPC SCHEDULE / CITY SITUATION SYSTEM]
# - Daily mission pool resets at 00:00 Asia/Bangkok.
# - Missions can be posted on central boards, city boards, NPCs and Mission Tab.
# - Existing jobs can remain on boards; world events may expire them early.
# - NPCs have schedules and city situations influence available jobs.
# ============================================================================
try:
    from datetime import datetime as _VMAX_DT, timedelta as _VMAX_TD, timezone as _VMAX_TZ
    from zoneinfo import ZoneInfo as _VMAX_ZoneInfo
except Exception:
    _VMAX_DT = None
    _VMAX_TD = None
    _VMAX_TZ = None
    _VMAX_ZoneInfo = None

VMAX_DAILY_MISSION_SYSTEM = {
    "id": "daily_world_mission_network",
    "reset_timezone": "Asia/Bangkok",
    "reset_at": "00:00",
    "daily_new_missions": True,
    "daily_rewards": True,
    "world_event_expiration": True,
    "npc_schedules": True,
    "shared_mission_state": True,
}

VMAX_CITY_SITUATIONS = {
    "sky_city": {"status": "normal", "severity": 0, "updated_at": None, "effects": []},
    "frontier_city": {"status": "supply_shortage", "severity": 1, "updated_at": None, "effects": ["supply_jobs", "escort_jobs"]},
    "river_city": {"status": "river_inspection", "severity": 1, "updated_at": None, "effects": ["inspection_jobs", "water_jobs"]},
}

VMAX_NPC_WORK_SCHEDULES = {
    "quartermaster": {"city_id": "sky_city", "hours": [(6, 14)], "roles": ["supply", "delivery", "equipment"]},
    "mission_clerk": {"city_id": "sky_city", "hours": [(8, 22)], "roles": ["contract", "submission", "reward"]},
    "field_officer": {"city_id": "frontier_city", "hours": [(7, 19)], "roles": ["escort", "recon", "security"]},
    "river_inspector": {"city_id": "river_city", "hours": [(5, 17)], "roles": ["inspection", "water", "recovery"]},
}

VMAX_WORLD_JOB_TEMPLATES = [
    {"id": "supply_run", "title": "Supply Run", "role": "supply", "duration_hours": 24, "reward": {"cash": 5000}},
    {"id": "city_escort", "title": "City Escort", "role": "escort", "duration_hours": 18, "reward": {"cash": 7000}},
    {"id": "field_recon", "title": "Field Recon", "role": "recon", "duration_hours": 24, "reward": {"cash": 6500}},
    {"id": "river_inspection", "title": "River Inspection", "role": "inspection", "duration_hours": 12, "reward": {"cash": 5000}},
    {"id": "data_recovery", "title": "Data Recovery", "role": "recovery", "duration_hours": 30, "reward": {"cash": 9000}},
    {"id": "equipment_delivery", "title": "Equipment Delivery", "role": "delivery", "duration_hours": 24, "reward": {"cash": 6000}},
]

VMAX_WORLD_MISSION_STATE = globals().get("VMAX_WORLD_MISSION_STATE", {})
VMAX_WORLD_MISSION_DAY = globals().get("VMAX_WORLD_MISSION_DAY", None)
VMAX_WORLD_MISSION_COUNTER = globals().get("VMAX_WORLD_MISSION_COUNTER", 0)


def _vmax_world_now():
    try:
        return _VMAX_DT.now(_VMAX_ZoneInfo("Asia/Bangkok"))
    except Exception:
        return _VMAX_DT.now() if _VMAX_DT else None


def _vmax_world_day_key(now=None):
    now = now or _vmax_world_now()
    return now.strftime("%Y-%m-%d") if now else "unknown"


def _vmax_world_schedule_open(npc_id, now=None):
    now = now or _vmax_world_now()
    cfg = VMAX_NPC_WORK_SCHEDULES.get(str(npc_id))
    if not cfg or not now:
        return False
    hour = now.hour + (now.minute / 60.0)
    return any(start <= hour < end for start, end in cfg.get("hours", []))


def _vmax_world_generate_daily_pool(day_key):
    global VMAX_WORLD_MISSION_COUNTER
    existing = [m for m in VMAX_WORLD_MISSION_STATE.values() if m.get("daily_day") == day_key]
    if existing:
        return
    now = _vmax_world_now()
    situations = list(VMAX_CITY_SITUATIONS.items())
    templates = list(VMAX_WORLD_JOB_TEMPLATES)
    for i, tpl in enumerate(templates):
        city_id = situations[i % len(situations)][0]
        situation = VMAX_CITY_SITUATIONS[city_id]
        # Situation-driven jobs receive a real reason for appearing.
        if situation.get("effects") and tpl["role"] not in situation["effects"]:
            continue
        VMAX_WORLD_MISSION_COUNTER += 1
        mission_id = f"daily_{day_key}_{VMAX_WORLD_MISSION_COUNTER:04d}"
        expires = now + _VMAX_TD(hours=int(tpl.get("duration_hours", 24))) if now and _VMAX_TD else None
        VMAX_WORLD_MISSION_STATE[mission_id] = {
            "id": mission_id,
            "template_id": tpl["id"],
            "title": tpl["title"],
            "city_id": city_id,
            "role": tpl["role"],
            "daily_day": day_key,
            "status": "posted",
            "posted_at": now.isoformat() if now else None,
            "expires_at": expires.isoformat() if expires else None,
            "reward": dict(tpl.get("reward", {})),
            "accepted_by": None,
            "progress": 0,
            "target": 1,
            "reward_claimed": False,
            "expired_reason": None,
            "available_at": ["mission_tab", "central_board", "city_board", "npc"],
            "npc_ids": [],
        }


def _vmax_world_refresh_daily(force=False):
    global VMAX_WORLD_MISSION_DAY
    day = _vmax_world_day_key()
    if force or VMAX_WORLD_MISSION_DAY != day:
        VMAX_WORLD_MISSION_DAY = day
        _vmax_world_generate_daily_pool(day)
    # World events can expire jobs before their normal deadline.
    now = _vmax_world_now()
    for mission in VMAX_WORLD_MISSION_STATE.values():
        if mission.get("status") in ("completed", "expired"):
            continue
        try:
            if mission.get("expires_at") and now and _VMAX_DT.fromisoformat(mission["expires_at"]) <= now:
                mission["status"] = "expired"
                mission["expired_reason"] = "contract_deadline"
        except Exception:
            pass
        situation = VMAX_CITY_SITUATIONS.get(mission.get("city_id"), {})
        if situation.get("status") in ("evacuated", "city_under_attack", "route_destroyed"):
            mission["status"] = "expired"
            mission["expired_reason"] = "world_event_changed_route"
    return day


def _vmax_world_available_missions(source="mission_tab", city_id=None, npc_id=None):
    _vmax_world_refresh_daily()
    now = _vmax_world_now()
    result = []
    for mission in VMAX_WORLD_MISSION_STATE.values():
        if mission.get("status") in ("expired", "completed"):
            continue
        if city_id and mission.get("city_id") != city_id:
            continue
        if source == "npc" and npc_id:
            cfg = VMAX_NPC_WORK_SCHEDULES.get(str(npc_id), {})
            if mission.get("role") not in cfg.get("roles", []):
                continue
            if not _vmax_world_schedule_open(npc_id, now):
                continue
        if source not in mission.get("available_at", []):
            continue
        result.append(dict(mission))
    return result


def _vmax_world_accept(user_id, mission_id):
    _vmax_world_refresh_daily()
    mission = VMAX_WORLD_MISSION_STATE.get(str(mission_id))
    if not mission:
        return None, "mission_not_found"
    if mission.get("status") == "expired":
        return None, "mission_expired"
    if mission.get("accepted_by") not in (None, str(user_id)):
        return None, "mission_already_taken"
    mission["accepted_by"] = str(user_id)
    mission["status"] = "active"
    return dict(mission), None


def _vmax_world_progress(user_id, mission_id, amount=1):
    mission = VMAX_WORLD_MISSION_STATE.get(str(mission_id))
    if not mission or mission.get("accepted_by") != str(user_id):
        return None, "mission_not_owned"
    if mission.get("status") == "expired":
        return None, "mission_expired"
    mission["progress"] = min(int(mission.get("target", 1)), int(mission.get("progress", 0)) + max(0, int(amount)))
    if mission["progress"] >= mission["target"]:
        mission["status"] = "ready_to_submit"
    return dict(mission), None


def _vmax_world_submit(user_id, mission_id):
    mission = VMAX_WORLD_MISSION_STATE.get(str(mission_id))
    if not mission or mission.get("accepted_by") != str(user_id):
        return None, "mission_not_owned"
    if mission.get("status") != "ready_to_submit":
        return None, "mission_not_ready"
    mission["status"] = "submitted"
    return dict(mission), None


def _vmax_world_claim(user_id, mission_id):
    mission = VMAX_WORLD_MISSION_STATE.get(str(mission_id))
    if not mission or mission.get("accepted_by") != str(user_id):
        return None, "mission_not_owned"
    if mission.get("status") not in ("submitted", "ready_to_submit"):
        return None, "mission_not_claimable"
    if mission.get("reward_claimed"):
        return None, "reward_already_claimed"
    mission["reward_claimed"] = True
    mission["status"] = "completed"
    return {"mission": dict(mission), "reward": dict(mission.get("reward", {}))}, None


try:
    @app.get("/api/world-missions/state")
    def vmax_world_missions_state():
        source = request.args.get("source", "mission_tab")
        city_id = request.args.get("city_id")
        npc_id = request.args.get("npc_id")
        return jsonify({
            "system": VMAX_DAILY_MISSION_SYSTEM,
            "day": _vmax_world_refresh_daily(),
            "missions": _vmax_world_available_missions(source, city_id, npc_id),
            "city_situations": VMAX_CITY_SITUATIONS,
            "npc_schedules": VMAX_NPC_WORK_SCHEDULES,
        })

    @app.get("/api/world-missions/npc/<npc_id>")
    def vmax_world_npc_missions(npc_id):
        now = _vmax_world_now()
        return jsonify({
            "npc_id": npc_id,
            "open_now": _vmax_world_schedule_open(npc_id, now),
            "schedule": VMAX_NPC_WORK_SCHEDULES.get(str(npc_id)),
            "missions": _vmax_world_available_missions("npc", npc_id=npc_id),
        })

    @app.get("/api/world-missions/city/<city_id>/board")
    def vmax_world_city_board(city_id):
        return jsonify({
            "city_id": city_id,
            "situation": VMAX_CITY_SITUATIONS.get(str(city_id), {"status": "unknown"}),
            "missions": _vmax_world_available_missions("city_board", city_id=city_id),
        })

    @app.post("/api/world-missions/accept")
    def vmax_world_accept_route():
        data = request.get_json(silent=True) or {}
        result, err = _vmax_world_accept(data.get("user_id", "guest"), data.get("mission_id"))
        return jsonify({"ok": not bool(err), "error": err, "mission": result}), (400 if err else 200)

    @app.post("/api/world-missions/progress")
    def vmax_world_progress_route():
        data = request.get_json(silent=True) or {}
        result, err = _vmax_world_progress(data.get("user_id", "guest"), data.get("mission_id"), data.get("amount", 1))
        return jsonify({"ok": not bool(err), "error": err, "mission": result}), (400 if err else 200)

    @app.post("/api/world-missions/submit")
    def vmax_world_submit_route():
        data = request.get_json(silent=True) or {}
        result, err = _vmax_world_submit(data.get("user_id", "guest"), data.get("mission_id"))
        return jsonify({"ok": not bool(err), "error": err, "mission": result}), (400 if err else 200)

    @app.post("/api/world-missions/claim")
    def vmax_world_claim_route():
        data = request.get_json(silent=True) or {}
        result, err = _vmax_world_claim(data.get("user_id", "guest"), data.get("mission_id"))
        return jsonify({"ok": not bool(err), "error": err, "result": result}), (400 if err else 200)

    @app.post("/api/world-missions/refresh-day")
    def vmax_world_force_daily_refresh():
        # Developer/admin hook for testing the midnight reset without changing the clock.
        _vmax_world_refresh_daily(force=True)
        return jsonify({"ok": True, "day": VMAX_WORLD_MISSION_DAY, "missions": len(VMAX_WORLD_MISSION_STATE)})

    if isinstance(globals().get("VMAX_MODULES"), dict):
        VMAX_MODULES["daily_world_mission_network"] = VMAX_DAILY_MISSION_SYSTEM
except Exception:
    pass

_vmax_world_refresh_daily()



