def _vmax_tower_user(user_id):
    uid = str(user_id or "default_player")
    state = VMAX_SKY_CITY_TOWER_STATE.setdefault(uid, {
        "current_floor": 0,
        "highest_floor": 0,
        "run_active": False,
        "run_id": None,
        "last_clear": None,
        "rewards_claimed": [],
    })
    return state


@app.route('/api/sky-city/challenge-tower', methods=['GET'])
def vmax_sky_city_challenge_tower_state():
    user_id = str(request.args.get('user_id', 'default_player'))
    state = _vmax_tower_user(user_id)
    return jsonify({"st": "ok", "tower": VMAX_SKY_CITY_CHALLENGE_TOWER, "player": state})


@app.route('/api/sky-city/challenge-tower/start', methods=['POST'])
def vmax_sky_city_challenge_tower_start():
    payload = request.get_json(silent=True) or {}
    user_id = str(payload.get('user_id') or 'default_player')
    state = _vmax_tower_user(user_id)
    if state["run_active"]:
        return jsonify({"st": "error", "msg": "กำลังอยู่ในรอบหอคอยอยู่แล้ว", "player": state}), 400
    state["run_active"] = True
    state["current_floor"] = max(1, int(payload.get("start_floor", 1)))
    state["current_floor"] = min(state["current_floor"], VMAX_SKY_CITY_CHALLENGE_TOWER["max_floor"])
    state["run_id"] = f"tower-{user_id}-{int(time.time() * 1000)}"
    return jsonify({"st": "ok", "run_id": state["run_id"], "floor": state["current_floor"], "player": state})


@app.route('/api/sky-city/challenge-tower/clear-floor', methods=['POST'])
def vmax_sky_city_challenge_tower_clear_floor():
    payload = request.get_json(silent=True) or {}
    user_id = str(payload.get('user_id') or 'default_player')
    state = _vmax_tower_user(user_id)
    if not state["run_active"]:
        return jsonify({"st": "error", "msg": "ยังไม่ได้เริ่มรอบหอคอย"}), 400
    requested = int(payload.get("floor", state["current_floor"]))
    if requested != state["current_floor"]:
        return jsonify({"st": "error", "msg": "ชั้นที่ส่งมาไม่ตรงกับชั้นปัจจุบัน", "current_floor": state["current_floor"]}), 400

    state["highest_floor"] = max(state["highest_floor"], requested)
    state["last_clear"] = requested
    checkpoint = (requested % VMAX_SKY_CITY_CHALLENGE_TOWER["floor_rules"]["checkpoint_every"] == 0)
    if requested >= VMAX_SKY_CITY_CHALLENGE_TOWER["max_floor"]:
        state["run_active"] = False
        reward = {"cash": 25000, "items": ["tower_artifact_core"]}
        state["rewards_claimed"].append({"floor": requested, "reward": reward})
        state["run_id"] = None
        return jsonify({"st": "ok", "status": "tower_cleared", "floor": requested, "reward": reward, "checkpoint": True, "player": state})

    state["current_floor"] = requested + 1
    return jsonify({"st": "ok", "status": "floor_cleared", "cleared_floor": requested, "next_floor": state["current_floor"], "checkpoint": checkpoint, "player": state})


@app.route('/api/sky-city/challenge-tower/leave', methods=['POST'])
def vmax_sky_city_challenge_tower_leave():
    payload = request.get_json(silent=True) or {}
    user_id = str(payload.get('user_id') or 'default_player')
    state = _vmax_tower_user(user_id)
    state["run_active"] = False
    state["run_id"] = None
    return jsonify({"st": "ok", "status": "left_tower", "checkpoint_floor": max(0, state["highest_floor"]), "player": state})


