VMAX_SKY_CITY_ROADS = {
    "main_ring": {"road_id": "main_ring", "name": "Sky Ring Road", "lanes": 2, "speed_limit": 45, "loop": True},
    "market_avenue": {"road_id": "market_avenue", "name": "Market Avenue", "lanes": 2, "speed_limit": 35, "loop": False},
    "tower_boulevard": {"road_id": "tower_boulevard", "name": "Tower Boulevard", "lanes": 2, "speed_limit": 40, "loop": False},
    "airship_road": {"road_id": "airship_road", "name": "Airship Dock Road", "lanes": 2, "speed_limit": 30, "loop": False},
}

VMAX_SKY_CITY_TRAFFIC = {
    "vehicles": {},
    "next_vehicle": 1,
    "last_tick": 0.0,
}


def _vmax_spawn_city_vehicle(vehicle_type="car", road_id="main_ring", npc_name=None):
    road = VMAX_SKY_CITY_ROADS.get(road_id, VMAX_SKY_CITY_ROADS["main_ring"])
    vid = f"city_vehicle_{VMAX_SKY_CITY_TRAFFIC['next_vehicle']}"
    VMAX_SKY_CITY_TRAFFIC["next_vehicle"] += 1
    vehicle = {
        "vehicle_id": vid,
        "type": vehicle_type,
        "road_id": road["road_id"],
        "lane": 0,
        "speed": min(float(road["speed_limit"]), 30.0),
        "position": 0.0,
        "npc_driver": npc_name or f"city_driver_{VMAX_SKY_CITY_TRAFFIC['next_vehicle']}",
        "traffic_state": "cruising",
    }
    VMAX_SKY_CITY_TRAFFIC["vehicles"][vid] = vehicle
    return vehicle


@app.route('/api/sky-city/roads', methods=['GET'])
def vmax_sky_city_roads():
    return jsonify({"st": "ok", "roads": list(VMAX_SKY_CITY_ROADS.values()), "traffic": list(VMAX_SKY_CITY_TRAFFIC["vehicles"].values())})


@app.route('/api/sky-city/roads/spawn-traffic', methods=['POST'])
def vmax_sky_city_spawn_traffic():
    payload = request.get_json(silent=True) or {}
    road_id = str(payload.get("road_id") or "main_ring")
    if road_id not in VMAX_SKY_CITY_ROADS:
        return jsonify({"st": "error", "msg": "ไม่พบถนนนี้"}), 404
    count = max(1, min(int(payload.get("count", 1)), 20))
    vehicle_type = str(payload.get("vehicle_type") or "car")
    spawned = [_vmax_spawn_city_vehicle(vehicle_type, road_id) for _ in range(count)]
    return jsonify({"st": "ok", "spawned": spawned})


@app.route('/api/sky-city/roads/traffic-tick', methods=['POST'])
def vmax_sky_city_traffic_tick():
    payload = request.get_json(silent=True) or {}
    dt = max(0.01, min(float(payload.get("delta_seconds", 1.0)), 10.0))
    for vehicle in VMAX_SKY_CITY_TRAFFIC["vehicles"].values():
        road = VMAX_SKY_CITY_ROADS.get(vehicle["road_id"], VMAX_SKY_CITY_ROADS["main_ring"])
        vehicle["position"] += vehicle["speed"] * dt / 100.0
        if vehicle["position"] >= 1.0:
            vehicle["position"] -= 1.0
            if not road["loop"]:
                vehicle["traffic_state"] = "turning"
        else:
            vehicle["traffic_state"] = "cruising"
    VMAX_SKY_CITY_TRAFFIC["last_tick"] = time.time()
    return jsonify({"st": "ok", "traffic": list(VMAX_SKY_CITY_TRAFFIC["vehicles"].values())})


