@app.route('/api/sky-city/artifact-shop/store', methods=['POST'])
@require_auth
def vmax_sky_city_artifact_shop_store():
    payload = request.get_json(silent=True) or {}
    user_id = _vmax_shop_user_id(payload)
    item_id = str(payload.get("item_id") or "")
    quantity = max(1, min(int(payload.get("quantity", 1)), 20))
    item = next((x for x in VMAX_SKY_CITY_ARTIFACT_SHOP["items"] if x["item_id"] == item_id), None)
    if not item:
        return jsonify({"st": "error", "msg": "ไม่พบ Artifact/Potion ชิ้นนี้"}), 404

    # ใช้ wallet ที่ระบบร้านค้ากลางมีอยู่ หากไม่พบจะใช้ 0 อย่างปลอดภัย
    wallet = globals().get("VMAX_SHOP_WALLETS", {})
    wallet_state = wallet.setdefault(user_id, {"cash": 0}) if isinstance(wallet, dict) else {"cash": 0}
    total = int(item["price"]) * quantity
    if int(wallet_state.get("cash", 0)) < total:
        return jsonify({"st": "error", "msg": "เงินไม่พอ", "required": total, "wallet_cash": int(wallet_state.get("cash", 0))}), 400

    storage = _vmax_airship_storage(user_id)
    total_weight = float(item.get("weight", 0.0)) * quantity
    if storage["used_weight"] + total_weight > VMAX_AIRSHIP_STORAGE_CAPACITY:
        return jsonify({"st": "error", "msg": "พื้นที่เก็บของบนยานไม่พอ", "required_weight": total_weight}), 400

    wallet_state["cash"] -= total
    existing = next((x for x in storage["items"] if x["item_id"] == item_id and x["source_game_id"] == VMAX_SKY_CITY_ARTIFACT_SHOP["game_id"]), None)
    if existing:
        existing["quantity"] += quantity
    else:
        storage["items"].append({
            "item_id": item_id,
            "name": item["name"],
            "name_th": item.get("name_th", item["name"]),
            "quantity": quantity,
            "weight_each": float(item.get("weight", 0.0)),
            "source_game_id": VMAX_SKY_CITY_ARTIFACT_SHOP["game_id"],
            "category": item["category"],
            "effect": item.get("effect", {}),
            "stored_on": "player_airship",
        })
    storage["used_weight"] += total_weight
    return jsonify({"st": "ok", "purchased": {"item_id": item_id, "quantity": quantity, "total": total}, "storage": storage, "wallet_cash_after": wallet_state["cash"]})


