@app.route('/api/sky-city/hotel/rest', methods=['POST'])
def vmax_sky_city_hotel_rest():
    data = _vmax_hotel_get_json()
    uid = _vmax_hotel_uid(data.get('user_id', 'guest'))
    guest = _vmax_hotel_guest(uid)
    room = _vmax_hotel_room_for(uid)
    if not room:
        return jsonify({"ok": False, "error": "not_checked_in"}), 400
    duration = max(1, min(int(data.get('minutes', 60)), 720))
    guest['rested'] = True
    guest['living_status']['rest'] = min(100, guest['living_status']['rest'] + min(100, duration // 6))
    guest['living_status']['comfort'] = min(100, guest['living_status']['comfort'] + 15)
    return jsonify({"ok": True, "action": "rest", "minutes": duration, "living_status": guest['living_status']})


@app.route('/api/sky-city/hotel/personal-items', methods=['GET'])
def vmax_sky_city_hotel_personal_items():
    return jsonify({"items": VMAX_SKY_CITY_HOTEL["personal_items"]})


@app.route('/api/sky-city/hotel/personal-items/buy', methods=['POST'])
def vmax_sky_city_hotel_buy_personal_item():
    data = _vmax_hotel_get_json()
    uid = _vmax_hotel_uid(data.get('user_id', 'guest'))
    item_id = str(data.get('item_id', ''))
    qty = max(1, min(int(data.get('quantity', 1)), 50))
    item = VMAX_SKY_CITY_HOTEL["personal_items"].get(item_id)
    if not item:
        return jsonify({"ok": False, "error": "unknown_personal_item"}), 400
    total = int(item['price']) * qty
    ok, payment = _vmax_hotel_charge(uid, total)
    if not ok:
        return jsonify({"ok": False, **payment}), 402
    inv = VMAX_SKY_CITY_HOTEL_STATE["inventory"].setdefault(uid, {})
    inv[item_id] = int(inv.get(item_id, 0)) + qty
    return jsonify({"ok": True, "item_id": item_id, "quantity": qty, "inventory": inv, "payment": payment})


