# Links multiple challenge towers through the Sky City / world network.
# ============================================================
VMAX_CONNECTED_TOWERS = {
    "network_id": "challenge_tower_network",
    "hub": "sky_city_tower_gateway",
    "towers": {
        "sky_tower_main": {"name": "Sky City Challenge Tower", "world_id": "sky_city", "floors": 30, "status": "online"},
        "world_tower_alpha": {"name": "World Tower Alpha", "world_id": "world_01", "floors": 20, "status": "online"},
        "world_tower_beta": {"name": "World Tower Beta", "world_id": "world_02", "floors": 25, "status": "online"},
    },
    "connections": [
        {"from": "sky_tower_main", "to": "world_tower_alpha", "method": "tower_gateway", "status": "online"},
        {"from": "sky_tower_main", "to": "world_tower_beta", "method": "tower_gateway", "status": "online"},
        {"from": "world_tower_alpha", "to": "world_tower_beta", "method": "tower_gateway", "status": "online"},
    ],
}
VMAX_CONNECTED_TOWER_STATE = {"sessions": {}, "progress": {}, "cooldowns": {}}

def _vmax_tower_session_uid(user_id):
    return str(user_id or "guest")

def _vmax_tower_exists(tower_id):
    return tower_id in VMAX_CONNECTED_TOWERS["towers"]

def _vmax_tower_connections(tower_id):
    out = []
    for c in VMAX_CONNECTED_TOWERS["connections"]:
        if c["from"] == tower_id:
            out.append(dict(c))
        elif c["to"] == tower_id:
            c2 = dict(c)
            c2["from"], c2["to"] = c2["to"], c2["from"]
            out.append(c2)
    return out

@app.get('/api/challenge-towers/network')
def vmax_connected_towers_network():
    return jsonify({
        "ok": True,
        "network": VMAX_CONNECTED_TOWERS,
        "towers": list(VMAX_CONNECTED_TOWERS["towers"].values()),
    })

@app.get('/api/challenge-towers/<tower_id>/connections')
def vmax_connected_tower_connections(tower_id):
    if not _vmax_tower_exists(tower_id):
        return jsonify({"ok": False, "error": "tower_not_found"}), 404
    return jsonify({"ok": True, "tower_id": tower_id, "connections": _vmax_tower_connections(tower_id)})

@app.post('/api/challenge-towers/connect')
def vmax_connected_tower_connect():
    data = request.get_json(silent=True) or {}
    user_id = data.get('user_id', 'guest')
    from_tower = data.get('from_tower', 'sky_tower_main')
    to_tower = data.get('to_tower')
    if not _vmax_tower_exists(from_tower) or not _vmax_tower_exists(to_tower):
        return jsonify({"ok": False, "error": "tower_not_found"}), 404
    if from_tower == to_tower:
        return jsonify({"ok": False, "error": "same_tower"}), 400
    connected = any(
        (c['from'] == from_tower and c['to'] == to_tower) or
        (c['from'] == to_tower and c['to'] == from_tower)
        for c in VMAX_CONNECTED_TOWERS['connections']
    )
    if not connected:
        return jsonify({"ok": False, "error": "tower_not_connected"}), 400
    sid = _vmax_tower_session_uid(user_id)
    VMAX_CONNECTED_TOWER_STATE['sessions'][sid] = {
        "user_id": user_id,
        "from_tower": from_tower,
        "current_tower": to_tower,
        "connected_at": time.time(),
        "method": "tower_gateway",
    }
    return jsonify({"ok": True, "session": VMAX_CONNECTED_TOWER_STATE['sessions'][sid]})

@app.post('/api/challenge-towers/progress')
def vmax_connected_tower_progress():
    data = request.get_json(silent=True) or {}
    user_id = data.get('user_id', 'guest')
    tower_id = data.get('tower_id', 'sky_tower_main')
    floor = max(0, int(data.get('floor', 0)))
    if not _vmax_tower_exists(tower_id):
        return jsonify({"ok": False, "error": "tower_not_found"}), 404
    max_floor = VMAX_CONNECTED_TOWERS['towers'][tower_id]['floors']
    floor = min(floor, max_floor)
    VMAX_CONNECTED_TOWER_STATE['progress'][_vmax_tower_session_uid(user_id)] = {
        "tower_id": tower_id,
        "floor": floor,
        "max_floor": max_floor,
        "updated_at": time.time(),
    }
    return jsonify({"ok": True, "progress": VMAX_CONNECTED_TOWER_STATE['progress'][_vmax_tower_session_uid(user_id)]})

