def _vmax_sky_wallet(uid):
    uid = str(uid or "guest")
    return VMAX_SKY_CITY_WALLETS.setdefault(uid, {"currency": "sky_crest", "balance": 0, "transactions": []})

def _vmax_sky_credit(uid, amount, reason="reward"):
    w = _vmax_sky_wallet(uid)
    amount = max(0, int(amount))
    w["balance"] += amount
    w["transactions"].append({"type":"credit", "amount":amount, "reason":reason, "balance":w["balance"]})
    w["transactions"] = w["transactions"][-50:]
    return w

def _vmax_sky_debit(uid, amount, reason="purchase"):
    w = _vmax_sky_wallet(uid)
    amount = max(0, int(amount))
    if w["balance"] < amount:
        return False, w["balance"]
    w["balance"] -= amount
    w["transactions"].append({"type":"debit", "amount":amount, "reason":reason, "balance":w["balance"]})
    w["transactions"] = w["transactions"][-50:]
    return True, w["balance"]

