# SKY CITY CENTRAL BANK / CURRENCY EXCHANGE / TAX DOCUMENTS
# ============================================================
VMAX_SKY_BANK = {
    "id": "sky_city_central_bank",
    "name_th": "ธนาคารกลางนครลอยฟ้า",
    "currency": "SC",
    "currency_name": "Sky Crest",
    "reference_value_normal_cash": 100000,
    "exchange_fee_rate": 0.015,
    "tax_rate": 0.025,
    "supported_assets": ["normal_cash", "gem", "jewel", "sky_crest"],
    "document_required_before_exchange": True,
}

VMAX_SKY_BANK_RATES = {
    "normal_cash": {"to_sc": 100000, "from_sc": 100000},
    "gem": {"to_sc": 10, "from_sc": 10},
    "jewel": {"to_sc": 1, "from_sc": 1},
}
VMAX_SKY_BANK_ACCOUNTS = {}
VMAX_SKY_BANK_DOCUMENTS = {}


def _vmax_sky_bank_uid(payload):
    return str((payload or {}).get("user_id") or "guest")


def _vmax_sky_bank_account(user_id):
    uid = _vmax_sky_bank_uid({"user_id": user_id})
    if uid not in VMAX_SKY_BANK_ACCOUNTS:
        VMAX_SKY_BANK_ACCOUNTS[uid] = {
            "user_id": uid,
            "sky_crest": 0,
            "assets": {"normal_cash": 0, "gem": 0, "jewel": 0},
            "exchange_history": [],
        }
    return VMAX_SKY_BANK_ACCOUNTS[uid]


def _vmax_sky_bank_quote(asset, amount, direction):
    asset = str(asset or "").lower()
    amount = float(amount or 0)
    if asset not in VMAX_SKY_BANK_RATES or amount <= 0:
        raise ValueError("invalid exchange asset or amount")
    rate = float(VMAX_SKY_BANK_RATES[asset][direction])
    # rate = units of asset required per 1 SC when exchanging to/from SC.
    gross_sc = amount / rate if direction == "to_sc" else amount
    gross_asset = amount if direction == "to_sc" else amount * rate
    fee = gross_sc * float(VMAX_SKY_BANK["exchange_fee_rate"])
    taxable_base = max(0.0, gross_sc)
    tax_sc = taxable_base * float(VMAX_SKY_BANK["tax_rate"])
    net_sc = max(0.0, gross_sc - fee - tax_sc)
    return {
        "asset": asset,
        "direction": direction,
        "input_amount": amount,
        "gross_sc": gross_sc,
        "gross_asset": gross_asset,
        "exchange_fee_sc": fee,
        "tax_sc": tax_sc,
        "net_sc": net_sc,
        "tax_rate": VMAX_SKY_BANK["tax_rate"],
        "exchange_fee_rate": VMAX_SKY_BANK["exchange_fee_rate"],
    }


@app.get("/api/sky-city/bank")
def vmax_sky_bank_state():
    uid = _vmax_sky_bank_uid(request.args)
    account = _vmax_sky_bank_account(uid)
    return jsonify({
        "bank": VMAX_SKY_BANK,
        "rates": VMAX_SKY_BANK_RATES,
        "account": account,
    })


@app.post("/api/sky-city/bank/document")
def vmax_sky_bank_document():
    payload = request.get_json(silent=True) or {}
    uid = _vmax_sky_bank_uid(payload)
    document_id = f"SKY-BANK-{uuid.uuid4().hex[:12].upper()}"
    document = {
        "document_id": document_id,
        "user_id": uid,
        "status": "issued",
        "issued_at": time.time(),
        "title": "เอกสารแจ้งการแลกเปลี่ยนเงินนครลอยฟ้า",
        "purpose": "แสดงอัตราแลกเปลี่ยน ค่าธรรมเนียม และภาษีก่อนยืนยันรายการ",
    }
    VMAX_SKY_BANK_DOCUMENTS[document_id] = document
    return jsonify({"ok": True, "document": document})


@app.post("/api/sky-city/bank/quote")
def vmax_sky_bank_quote_route():
    payload = request.get_json(silent=True) or {}
    try:
        quote = _vmax_sky_bank_quote(payload.get("asset"), payload.get("amount"), payload.get("direction", "to_sc"))
    except ValueError as exc:
        return jsonify({"ok": False, "error": str(exc)}), 400
    uid = _vmax_sky_bank_uid(payload)
    document_id = payload.get("document_id")
    document = VMAX_SKY_BANK_DOCUMENTS.get(document_id)
    if VMAX_SKY_BANK["document_required_before_exchange"] and (not document or document.get("user_id") != uid):
        return jsonify({"ok": False, "error": "bank document required before exchange", "quote": quote}), 400
    return jsonify({"ok": True, "quote": quote, "document": document})


@app.post("/api/sky-city/bank/exchange")
def vmax_sky_bank_exchange():
    payload = request.get_json(silent=True) or {}
    uid = _vmax_sky_bank_uid(payload)
    document_id = payload.get("document_id")
    document = VMAX_SKY_BANK_DOCUMENTS.get(document_id)
    if VMAX_SKY_BANK["document_required_before_exchange"] and (not document or document.get("user_id") != uid):
        return jsonify({"ok": False, "error": "valid bank document required"}), 400
    try:
        quote = _vmax_sky_bank_quote(payload.get("asset"), payload.get("amount"), payload.get("direction", "to_sc"))
    except ValueError as exc:
        return jsonify({"ok": False, "error": str(exc)}), 400

    account = _vmax_sky_bank_account(uid)
    asset = quote["asset"]
    amount = quote["input_amount"]
    direction = quote["direction"]

    if direction == "to_sc":
        if account["assets"].get(asset, 0) < amount:
            return jsonify({"ok": False, "error": "insufficient asset balance", "quote": quote}), 400
        account["assets"][asset] -= amount
        account["sky_crest"] += quote["net_sc"]
    else:
        if account["sky_crest"] < amount:
            return jsonify({"ok": False, "error": "insufficient Sky Crest balance", "quote": quote}), 400
        account["sky_crest"] -= amount
        account["assets"][asset] += quote["gross_asset"]

    transaction = {
        "transaction_id": f"EX-{uuid.uuid4().hex[:12].upper()}",
        "timestamp": time.time(),
        "document_id": document_id,
        "quote": quote,
        "status": "completed",
    }
    account["exchange_history"].append(transaction)
    if document:
        document["status"] = "completed"
        document["transaction_id"] = transaction["transaction_id"]
    return jsonify({"ok": True, "transaction": transaction, "account": account})


