def _vmax_new_game_snapshot(uid):
    import time as _ng_time
    st = _vmax_new_game_state(uid)
    if st["skill_until"] and _ng_time.time() >= st["skill_until"]:
        st["skill_until"] = 0.0; st["skill_ready"] = True
    # Zombie mode is server-ticked whenever state is requested, so mobile clients
    # do not need a second realtime transport just for the horde/airdrop loop.
    _zombie_tick = globals().get("_vmax_new_game_zombie_tick")
    if _zombie_tick:
        _zombie_tick(st)
