@app.route('/api/new-game/extraction/move', methods=['POST'])
def api_vmax_new_game_move():
    b=request.get_json(silent=True) or {}; uid=str(getattr(request,'vmax_uid',None) or b.get('uid') or 'guest'); st=_vmax_new_game_state(uid)
    if st['status']!='raid': return jsonify({"st":"error","msg":"ยังไม่ได้อยู่ใน Raid"}),400
    dx,dy=float(b.get('dx',0)),float(b.get('dy',0)); mag=max((dx*dx+dy*dy)**0.5,1.0); speed=18.0
    st['x']=max(30.0,min(870.0,st['x']+dx/mag*speed)); st['y']=max(40.0,min(530.0,st['y']+dy/mag*speed))
    if st.get('mode') == 'zombie':
        st.setdefault('noise_events',[]).append({'x':st['x'],'y':st['y'],'type':'footstep','at':time.time(),'radius':70.0})
    return jsonify({"st":"ok","game":_vmax_new_game_snapshot(uid)})

@app.route('/api/new-game/extraction/shoot', methods=['POST'])
def api_vmax_new_game_shoot():
    b=request.get_json(silent=True) or {}; uid=str(getattr(request,'vmax_uid',None) or b.get('uid') or 'guest'); st=_vmax_new_game_state(uid)
    if st['status']!='raid': return jsonify({"st":"error","msg":"ยังไม่ได้อยู่ใน Raid"}),400
    target=next((e for e in st['enemies'] if e['id']==str(b.get('target_id','')) and e['alive']),None)
    if target is None:
        alive=[e for e in st['enemies'] if e['alive']]
        target=min(alive,key=lambda e:(e['x']-st['x'])**2+(e['y']-st['y'])**2) if alive else None
    if target is None: return jsonify({"st":"ok","game":_vmax_new_game_snapshot(uid),"msg":"ไม่มีศัตรูเหลือแล้ว"})
    if st.get('mode') == 'zombie':
        _gr=_vmax_gunshot_radius(uid,b)   # ตัวเก็บเสียง/เบรก ของปืนที่ถือ มีผลต่อรัศมีที่ซอมบี้ได้ยิน
        st.setdefault('noise_events',[]).append({'x':st['x'],'y':st['y'],'type':'gunshot','at':time.time(),'radius':_gr})
        st['last_noise']={'x':st['x'],'y':st['y'],'type':'gunshot','at':time.time(),'radius':_gr}
    target['alert_until']=time.time()+12.0   # โดนยิง = รู้ตัว หันมาทางผู้เล่น (ล็อคคอจากด้านหลังไม่ได้)
    bonus=1.75 if st['skill_until'] and st['operator']=='warden' else 1.0; target['hp']-=int(28*bonus)
    if target['hp']<=0:
        target['hp']=0; target['alive']=False; st['kills']+=1; st['score']+=100; st['auction_coins']+=5; st['message']='กำจัดศัตรูสำเร็จ +5 Auction Coins'
    else:
        _ff=globals().get('momentum_kick_enemy_fire_factor')   # ศัตรูที่โดนถีบปืนหลุด/พัง/ข้อมือร้าว ยิงสวนไม่ได้
        _ff=_ff(target) if _ff else 1.0
        if _ff<=0.0:
            st['message']='ยิงโดนเป้าหมาย — ศัตรูไม่มีปืนที่ใช้ได้ ยิงสวนไม่ได้'
        else:
            dmg=max(1,int(round((2 if st['operator']=='juggernaut' else 5)*_ff))); st['hp']=max(0,st['hp']-dmg); st['message']='ยิงโดนเป้าหมาย'
    if st['hp']<=0: st['status']='dead'; st['message']='ถูกกำจัด — ของที่ยังไม่ Extract หายไป'; st['bag']=[]
    return jsonify({"st":"ok","game":_vmax_new_game_snapshot(uid)})

@app.route('/api/new-game/extraction/loot', methods=['POST'])
def api_vmax_new_game_loot():
    b=request.get_json(silent=True) or {}; uid=str(getattr(request,'vmax_uid',None) or b.get('uid') or 'guest'); st=_vmax_new_game_state(uid)
    if st['status']!='raid': return jsonify({"st":"error","msg":"เก็บของได้เฉพาะใน Raid"}),400
    target=next((x for x in st['loot'] if x['id']==str(b.get('loot_id','')) and not x['taken']),None)
    if target is None: return jsonify({"st":"error","msg":"ไม่พบไอเทม"}),404
    item=VMAX_NEW_GAME_LOOT[target['item_id']]
    if sum(VMAX_NEW_GAME_LOOT[i]['weight'] for i in st['bag'])+item['weight']+_vmax_gear_bag_weight(st)>12: return jsonify({"st":"error","msg":"กระเป๋าเต็ม"}),400
    target['taken']=True; st['bag'].append(target['item_id']); st['score']+=item['value']; st['message']=f"เก็บ {item['name']} +{item['value']}"
    return jsonify({"st":"ok","game":_vmax_new_game_snapshot(uid)})

@app.route('/api/new-game/extraction/skill', methods=['POST'])
def api_vmax_new_game_skill():
    b=request.get_json(silent=True) or {}; uid=str(getattr(request,'vmax_uid',None) or b.get('uid') or 'guest'); st=_vmax_new_game_state(uid)
    if st['status']!='raid' or not st['skill_ready']: return jsonify({"st":"error","msg":"สกิลยังไม่พร้อม"}),400
    import time
    st['skill_ready']=False; st['skill_until']=time.time()+8.0
    st['message']={'phantom':'Phase ทำงาน — ลดโอกาสโดนโจมตี','juggernaut':'Bulwark ทำงาน — รับความเสียหายน้อยลง'}.get(st['operator'],'Overdrive ทำงาน — ยิงแรงขึ้น')
    return jsonify({"st":"ok","game":_vmax_new_game_snapshot(uid)})

@app.route('/api/new-game/extraction/zombie/flare', methods=['POST'])
def api_vmax_new_game_zombie_flare():
    b=request.get_json(silent=True) or {}; uid=str(getattr(request,'vmax_uid',None) or b.get('uid') or 'guest')
    st=_vmax_new_game_state(uid)
    if st.get('status')!='raid' or st.get('mode')!='zombie':
        return jsonify({"st":"error","msg":"ต้องอยู่ในโหมดซอมบี้ก่อน"}),400
    now=time.time()
    if now < float(st.get('flare_ready_at',0.0)):
        remain=max(0.0,float(st['flare_ready_at'])-now)
        return jsonify({"st":"error","msg":f"Flare ยังไม่พร้อม ({remain:.1f} วินาที)"}),400
    aid=f"ad_{uuid.uuid4().hex[:8]}"
    airdrop={"id":aid,"x":float(st['x']),"y":float(st['y']),"fired_at":now,"eta":now+8.0,
             "landed":False,"contents":["ammo","medkit","artifact"],"noise_radius":850.0,
             "loot_ids":[]}
    st['airdrop']=airdrop
    st['flare_ready_at']=now+15.0
    st.setdefault('noise_events',[]).append({'x':st['x'],'y':st['y'],'type':'flare','at':now,'radius':850.0})
    st['last_noise']={'x':st['x'],'y':st['y'],'type':'flare','at':now,'radius':850.0}
    st['message']='ยิง Flare ขึ้นฟ้าแล้ว — Airdrop กำลังตกลงมา! เสียงดังทำให้ Zombies แห่เข้าหา'
    return jsonify({"st":"ok","game":_vmax_new_game_snapshot(uid)})

@app.route('/api/new-game/extraction/extract', methods=['POST'])
def api_vmax_new_game_extract():
    b=request.get_json(silent=True) or {}; uid=str(getattr(request,'vmax_uid',None) or b.get('uid') or 'guest'); st=_vmax_new_game_state(uid)
    if st['status']!='raid': return jsonify({"st":"error","msg":"ไม่มี Raid ที่กำลังเล่น"}),400
    near=((st['x']-820)**2+(st['y']-455)**2)**0.5<=95
    if not near: return jsonify({"st":"error","msg":"เดินเข้าเขต Extract ก่อน"}),400
    _vmax_gear_return_to_stash(uid, st)   # gear ในกระเป๋า/ในมือ กลับเข้าคลัง
    value=sum(VMAX_NEW_GAME_LOOT[i]['value'] for i in st['bag']); st['game_cash']+=value; st['auction_coins']+=max(10,value//50)
    st['extracted_value']=value; st['status']='extracted'; st['message']=f'Extract สำเร็จ! ขายของได้ {value} Cash'; st['bag']=[]
    return jsonify({"st":"ok","game":_vmax_new_game_snapshot(uid)})

@app.route('/api/new-game/extraction/buy-ticket', methods=['POST'])
def api_vmax_new_game_buy_ticket():
    b=request.get_json(silent=True) or {}; uid=str(getattr(request,'vmax_uid',None) or b.get('uid') or 'guest'); st=_vmax_new_game_state(uid); cost=30
    if st['auction_coins']<cost: return jsonify({"st":"error","msg":"Auction Coins ไม่พอ"}),400
    st['auction_coins']-=cost; st['tickets']+=1; st['message']='ซื้อ Ticket ใหม่สำเร็จ'; return jsonify({"st":"ok","game":_vmax_new_game_snapshot(uid)})

@app.route('/api/new-game/extraction/reset', methods=['POST'])
def api_vmax_new_game_reset():
    b=request.get_json(silent=True) or {}; uid=str(getattr(request,'vmax_uid',None) or b.get('uid') or 'guest'); VMAX_NEW_GAME_STATE.pop(uid,None)
    return jsonify({"st":"ok","game":_vmax_new_game_snapshot(uid)})

