# ============================================================================
# [NEW GAME BRIDGE] EXTRACTION BOSS RAID -> EXISTING AI/WORLD MAP LAYER
# ---------------------------------------------------------------------------
# The new game consumes the existing VMAX world/map systems in this same file:
# XROOM_MAP_POOL, KILLER_MODE_MAP_SPOTS, generator/gate coordinates,
# MAP_DESIGNS (AI blueprint generation), and SURVIVAL_WORLD_STREAMING.
# ============================================================================
VMAX_NEW_GAME_WORLD_BRIDGE_VERSION = "1.0.0"
VMAX_NEW_GAME_WORLD_BRIDGE = {}


def _new_game_pick_shared_map(map_id=None):
    maps = globals().get("XROOM_MAP_POOL", []) or []
    wanted = str(map_id or "").strip()
    if wanted:
        hit = next((m for m in maps if str(m.get("id")) == wanted), None)
        if hit:
            return dict(hit)
    return dict(maps[0]) if maps else {"id":"shared_world","name":"Shared World","width":1000,"height":1000}


def _new_game_build_world_bridge(uid, map_id=None):
    import time as _bridge_time
    shared_map = _new_game_pick_shared_map(map_id)
    spots = globals().get("KILLER_MODE_MAP_SPOTS", {}) or {}
    generators = globals().get("KILLER_MODE_GENERATOR_SPOTS", {}) or {}
    gates = globals().get("KILLER_MODE_GATE_SPOTS", {}) or {}
    designs = globals().get("MAP_DESIGNS", {}) or {}

    ai_designs = [(did, d) for did, d in designs.items()
                  if str(d.get("uid")) == str(uid) and d.get("status") == "done"]
    ai_designs.sort(key=lambda item: float(item[1].get("created_ts", 0)), reverse=True)
    ai_design = ai_designs[0][1] if ai_designs else None

    def norm_xy(x, y, src_w=900.0, src_h=800.0):
        return {
            "x": max(30.0, min(870.0, float(x) / max(src_w, 1.0) * 840.0 + 30.0)),
            "y": max(40.0, min(530.0, float(y) / max(src_h, 1.0) * 490.0 + 40.0)),
        }

    loot_points=[]
    for sid, spot in list(spots.items()):
        if isinstance(spot, dict):
            loot_points.append({"source_id":str(sid), **norm_xy(spot.get("x",0), spot.get("y",0)),
                                "item_pool":list(spot.get("item_pool") or [])})

    objective_points=[]
    for gid, point in list(generators.items()):
        if isinstance(point, dict):
            objective_points.append({"id":str(gid), **norm_xy(point.get("x",0), point.get("y",0))})

    extraction_points=[]
    for gid, point in list(gates.items()):
        if isinstance(point, dict):
            extraction_points.append({"id":str(gid), **norm_xy(point.get("x",0), point.get("y",0))})

    extract = extraction_points[0] if extraction_points else {"id":"extract_shared","x":820.0,"y":455.0}
    world={
        "bridge_version": VMAX_NEW_GAME_WORLD_BRIDGE_VERSION,
        "source":"shared_vmax_world",
        "map":shared_map,
        "map_id":shared_map.get("id"),
        "map_name":shared_map.get("name"),
        "ai_blueprint":dict(ai_design) if ai_design else None,
        "loot_points":loot_points,
        "objective_points":objective_points,
        "extraction_points":extraction_points,
        "extract":extract,
        "streaming":dict(globals().get("SURVIVAL_WORLD_STREAMING", {})),
        "connected_at":_bridge_time.time(),
    }
    VMAX_NEW_GAME_WORLD_BRIDGE[str(uid)] = world
    return world


def _new_game_world_for(uid, map_id=None):
    key=str(uid)
    current=VMAX_NEW_GAME_WORLD_BRIDGE.get(key)
    if current is None or (map_id and str(current.get("map_id")) != str(map_id)):
        current=_new_game_build_world_bridge(uid,map_id)
    return current


# Existing raid endpoints already call these global spawn functions. Replacing
# only the functions makes the old endpoints consume the shared world without
# duplicating or rewriting the whole game loop.
def _vmax_new_game_spawn_enemies(st):
    import random as _bridge_random
    uid=str(st.get("uid","guest"))
    world=_new_game_world_for(uid,st.get("map_id"))
    points=list(world.get("loot_points") or [])+list(world.get("objective_points") or [])
    if not points:
        points=[{"x":300.0,"y":150.0},{"x":600.0,"y":220.0},{"x":740.0,"y":420.0}]
    _bridge_random.shuffle(points)
    st["enemies"]=[]
    for i in range(7):
        p=points[i%len(points)]; hp=45+i*5
        st["enemies"].append({
            "id":f"e{i}",
            "x":max(40.0,min(860.0,float(p.get("x",300))+_bridge_random.uniform(-22,22))),
            "y":max(50.0,min(520.0,float(p.get("y",150))+_bridge_random.uniform(-18,18))),
            "hp":hp,"max_hp":hp,"alive":True,
            "world_source":p.get("source_id") or p.get("id") or "shared_world",
        })


def _vmax_new_game_spawn_loot(st):
    import random as _bridge_random
    uid=str(st.get("uid","guest"))
    world=_new_game_world_for(uid,st.get("map_id"))
    points=list(world.get("loot_points") or [])
    ids=list(VMAX_NEW_GAME_LOOT)
    st["loot"]=[]
    if not points:
        points=[{"source_id":"generated","x":_bridge_random.randint(170,850),"y":_bridge_random.randint(70,500)} for _ in range(9)]
    for i in range(9):
        p=points[i%len(points)]
        st["loot"].append({
            "id":f"l{i}","item_id":_bridge_random.choice(ids),
            "x":max(40.0,min(860.0,float(p.get("x",300))+_bridge_random.uniform(-16,16))),
            "y":max(50.0,min(520.0,float(p.get("y",150))+_bridge_random.uniform(-16,16))),
            "taken":False,"world_source":p.get("source_id") or "shared_world",
        })


_old_new_game_snapshot=_vmax_new_game_snapshot
def _vmax_new_game_snapshot(uid):
    snap=_old_new_game_snapshot(uid)
    snap["world"]=_new_game_world_for(snap.get("uid",uid),snap.get("map_id"))
    return snap


