def _vmax_cross_game_events_for(game_id, include_other_game_teasers=True):
    gid=str(game_id or "all")
    selected=[]
    for src in VMAX_CROSS_GAME_EVENT_HUB:
        src_game=src.get("game_id")
        if src_game==gid or src_game=="all" or include_other_game_teasers:
            e=dict(src)
            e["is_local"]=(src_game==gid)
            e["event_page"]=(f"/game/{src_game}/events" if src_game not in ("all",gid) else e.get("route"))
            selected.append(e)
    return selected

@app.route('/api/cross-game/events/<game_id>')
def api_cross_game_events(game_id):
    """Return only event metadata for the requested game + shared cross-game cards."""
    known={"vmax","iron_fist","attackion_root"}
    gid=str(game_id)
    if gid not in known:
        return jsonify({"st":"error","msg":"unknown_game","game_id":gid}),404
    return jsonify({
        "st":"ok", "game_id":gid,
        "events":_vmax_cross_game_events_for(gid),
        "connection":"shared_event_index_only",
        "gameplay_isolated":True,
    })

@app.route('/game/<game_id>/events')
def vmax_game_event_page(game_id):
    """Generic event page used by every game without merging their gameplay."""
    known={"vmax":"VMAX","iron_fist":"Iron Fist Arena","attackion_root":"Attackion Root"}
    gid=str(game_id)
    if gid not in known:
        return "<h2>Unknown game</h2>",404
    import html as _html
    name=_html.escape(known[gid])
    return CROSS_GAME_EVENT_PAGE_HTML.replace("__GAME_ID__",_html.escape(gid)).replace("__GAME_NAME__",name)

