@app.route('/api/new-game/extraction/events')
def api_vmax_new_game_extraction_events():
    """Event bar data for the extraction game's top strip."""
    now_date=time.strftime('%Y-%m-%d')
    catalog=[]
    try:
        for e in EVENT_CATALOG:
            item=dict(e)
            item.setdefault('name',item.get('name_th',item.get('id','Event')))
            item['active_now']=bool(item.get('start','') <= now_date <= item.get('end','9999-12-31')) if item.get('start') else True
            catalog.append(item)
    except Exception:
        catalog=[]
    extraction_events=_vmax_cross_game_events_for("vmax")
    # Keep the existing extraction-only Zombie/4v4 cards, then append the
    # cross-game event cards. De-duplicate by id so the bar stays stable.
    merged=[]; seen=set()
    for item in list(VMAX_EXTRACTION_EVENT_BAR)+extraction_events:
        iid=str(item.get("id"))
        if iid in seen: continue
        seen.add(iid); merged.append(item)
    return jsonify({"st":"ok","events":merged,"catalog":catalog,
                    "connection":"shared_event_index_only","gameplay_isolated":True})


def _vmax_new_game_spawn_zombies(st):
    """Spawn a dedicated zombie horde for the extraction game's zombie event."""
    import random as _zr
    world=globals().get('_new_game_world_for')
    pts=[]
    if world:
        try:
            w=world(str(st.get('uid','guest')),st.get('map_id'))
            pts=list(w.get('enemy_points') or [])+list(w.get('loot_points') or [])+list(w.get('objective_points') or [])
        except Exception:
            pts=[]
    if not pts:
        pts=[{"x":_zr.randint(260,840),"y":_zr.randint(60,510)} for _ in range(14)]
    _zr.shuffle(pts)
    st['enemies']=[]
    for i in range(16):
        p=pts[i%len(pts)]
        hp=_zr.randint(32,52)+(i//6)*8
        st['enemies'].append({
            'id':f'z{i}', 'kind':'zombie',
            'x':max(35.0,min(875.0,float(p.get('x',300))+_zr.uniform(-35,35))),
            'y':max(45.0,min(525.0,float(p.get('y',150))+_zr.uniform(-25,25))),
            'hp':hp,'max_hp':hp,'alive':True,
            'hearing_range':360.0 if i%5 else 520.0,
            'state':'wandering', 'last_heard_at':0.0,
        })
    st['message']='คืนซอมบี้: ยิงได้ แต่ทุกเสียงสำคัญ — Flare เรียก Airdrop และเรียกฝูงด้วย'


def _vmax_new_game_zombie_tick(st):
    if st.get('mode')!='zombie' or st.get('status')!='raid':
        return
    now=time.time()
    last=float(st.get('zombie_tick_at',0.0))
    if now-last < 0.12:
        return
    dt=min(0.45,max(0.12,now-last)) if last else 0.12
    st['zombie_tick_at']=now
    ad=st.get('airdrop')
    if ad and not ad.get('landed') and now>=float(ad.get('eta',now+1)):
        ad['landed']=True
        ad['landed_at']=now
        # Airdrop creates real loot entries in the same Extraction inventory/loot system.
        for idx,item_id in enumerate(ad.get('contents',[])):
            if item_id not in VMAX_NEW_GAME_LOOT:
                continue
            loot_id=f"{ad['id']}_loot_{idx}"
            st.setdefault('loot',[]).append({
                'id':loot_id, 'item_id':item_id,
                'x':float(ad['x']) + (idx-1)*22.0, 'y':float(ad['y']) + (idx%2)*18.0, 'taken':False,
                'airdrop_id':ad['id'], 'airdrop':True,
            })
            ad.setdefault('loot_ids',[]).append(loot_id)
        st['message']='Airdrop ลงพื้นแล้ว — มีของจาก Airdrop ให้เก็บ ก่อนฝูง Zombie จะมาถึง'
    # Zombies react to actual noise events. They do NOT automatically know the
    # player's location just because the player is inside a generic distance.
    recent_noises=[n for n in st.get('noise_events',[]) if now-float(n.get('at',0))<=10.0]
    last_noise=max(recent_noises,key=lambda n:float(n.get('at',0)),default=None)
    for z in st.get('enemies',[]):
        if not z.get('alive'):
            continue
        dp=((float(st['x'])-float(z['x']))**2+(float(st['y'])-float(z['y']))**2)**0.5
        hearing=float(z.get('hearing_range',360.0))
        target_x,target_y=float(z['x']),float(z['y']); state='wandering'
        if last_noise:
            nx=float(last_noise.get('x',st['x'])); ny=float(last_noise.get('y',st['y']))
            dn=((nx-float(z['x']))**2+(ny-float(z['y']))**2)**0.5
            noise_radius=float(last_noise.get('radius',hearing))
            if dn <= min(hearing,noise_radius):
                target_x,target_y=nx,ny; state='heard_'+str(last_noise.get('type','noise'))
                z['last_heard_at']=now
                # Once the horde has actually reached the noisy area, it can track
                # the player at close range instead of magically tracking across the map.
                if dp <= 70.0:
                    target_x,target_y=st['x'],st['y']; state='chasing_player'
        dx=target_x-float(z['x']); dy=target_y-float(z['y']); d=(dx*dx+dy*dy)**0.5
        if d>4.0:
            speed=22.0 if state=='chasing_player' else 18.0
            z['x']+=dx/d*speed*dt; z['y']+=dy/d*speed*dt
        z['state']=state
        if dp<34.0 and now-float(st.get('zombie_last_hit_at',0.0))>=0.8:
            dmg=7
            if st.get('operator')=='juggernaut': dmg=3
            if st.get('operator')=='phantom' and random.random()<0.45: dmg=0
            st['hp']=max(0,int(st.get('hp',0))-dmg)
            st['zombie_last_hit_at']=now
            if dmg: st['message']=f'Zombie กัด/โจมตี — HP -{dmg}'
            if st['hp']<=0:
                st['status']='dead'; st['message']='ถูกฝูง Zombie ล้อม — ของที่ยังไม่ Extract หายไป'; st['bag']=[]
                break
    # Keep only recent noise so the horde eventually loses the trail.
    st['noise_events']=[n for n in st.get('noise_events',[]) if now-float(n.get('at',0))<10.0][-24:]

def _run_extraction_event_zombie_selftests():
    # Event-bar separation: only Zombie Night is a playable mode on this page;
    # other-game cards must never be labeled as extraction gameplay.
    assert any(e['id']=='zombie_night' and e['type']=='extraction_mode' for e in VMAX_EXTRACTION_EVENT_BAR)
    assert any(e['id']=='iron_fist_event' and e['type']=='other_game' and e['source_game_id']=='iron_fist' for e in VMAX_EXTRACTION_EVENT_BAR)
    assert any(e['id']=='attackion_root_event' and e['type']=='other_game' and e['source_game_id']=='attackion_root' for e in VMAX_EXTRACTION_EVENT_BAR)
    # Cross-game pages share only metadata/links; local gameplay remains isolated.
    for _gid in ('vmax','iron_fist','attackion_root'):
        _ev=_vmax_cross_game_events_for(_gid)
        assert any(e.get('game_id')==_gid and e.get('is_local') is True for e in _ev)
        assert all('gameplay_state' not in e for e in _ev)
    uid='__selftest_extraction_zombie__'
    VMAX_NEW_GAME_STATE.pop(uid,None)
    try:
        st=_vmax_new_game_state(uid)
        st['tickets']=2
        start=api_vmax_new_game_start
        with app.test_request_context('/api/new-game/extraction/start',method='POST',json={'uid':uid,'operator':'warden','mode':'zombie'}):
            resp=start()
        assert resp[1] if isinstance(resp,tuple) else True
        st=VMAX_NEW_GAME_STATE[uid]
        assert st['mode']=='zombie' and len([z for z in st['enemies'] if z.get('kind')=='zombie'])>=10
        with app.test_request_context('/api/new-game/extraction/zombie/flare',method='POST',json={'uid':uid}):
            resp=api_vmax_new_game_zombie_flare()
        data=resp.get_json() if hasattr(resp,'get_json') else resp[0].get_json()
        assert data['st']=='ok' and data['game']['airdrop']['landed'] is False
        ad=VMAX_NEW_GAME_STATE[uid]['airdrop']
        ad['eta']=time.time()-1
        _vmax_new_game_zombie_tick(VMAX_NEW_GAME_STATE[uid])
        assert ad['landed'] is True and len(ad.get('loot_ids',[]))==3
        # A recent gunshot must be heard only within hearing/noise range.
        st=VMAX_NEW_GAME_STATE[uid]
        z=st['enemies'][0]; z['x']=st['x']+1000; z['y']=st['y']
        st['noise_events']=[{'x':st['x'],'y':st['y'],'type':'gunshot','at':time.time(),'radius':420.0}]
        old=(z['x'],z['y'])
        _vmax_new_game_zombie_tick(st)
        assert (z['x'],z['y'])==old or z['state']=='wandering'
        return True
    finally:
        VMAX_NEW_GAME_STATE.pop(uid,None)


