# ============================================================================
# VMAX LORE CIPHER — WWI-STYLE ADFGVX PUZZLE (ของเล่น/lore เท่านั้น — ไม่ใช่ระบบความ
# ปลอดภัย ไม่เกี่ยวกับ auth/encryption ของระบบจริงเลย)
# ----------------------------------------------------------------------------
# แรงบันดาลใจจากรหัส ADFGVX ที่กองทัพเยอรมันใช้ปี 1918 (Polybius square 6x6 +
# columnar transposition) เอามาทำเป็นปริศนาในเกม: ผู้เล่นเก็บ "เศษข้อความลับ"
# (lore fragment) ที่เข้ารหัสด้วยวิธีนี้จริงๆ แล้วต้องถอดรหัสเอง (ด้วยมือ/เครื่องมือ
# ในเกม) เพื่อปลดล็อกเนื้อเรื่องเบื้องหลังของแผนที่ + ได้รางวัลเป็น "เศษตำนาน"
# (lore shard) ไม่มีผลต่อความปลอดภัยบัญชีหรือข้อมูลผู้เล่นแต่อย่างใด
# ============================================================================
import time as _lc_time
import string as _lc_string
import threading as _lc_threading
import difflib as _lc_difflib

VMAX_LORE_CIPHER_LOCK = _lc_threading.RLock()
VMAX_LORE_CIPHER_STATE = {}  # uid -> player state

_ADFGVX_AXIS = "ADFGVX"
_ADFGVX_CHARSET = (_lc_string.ascii_uppercase + "0123456789")  # 36 ตัว พอดีกับ 6x6


def _adfgvx_square(polybius_key: str):
    """สร้างตาราง Polybius 6x6 จากคีย์เวิร์ด: เอาตัวอักษรไม่ซ้ำในคีย์ขึ้นก่อน
    ตามด้วยตัวที่เหลือของ charset ตามลำดับ แล้ววางลงช่อง 6x6 ที่มีหัวแถว/คอลัมน์
    เป็น A D F G V X (ตามของจริงในประวัติศาสตร์)"""
    seen = []
    for ch in (polybius_key or "").upper():
        if ch in _ADFGVX_CHARSET and ch not in seen:
            seen.append(ch)
    for ch in _ADFGVX_CHARSET:
        if ch not in seen:
            seen.append(ch)
    char_to_pair = {}
    pair_to_char = {}
    for idx, ch in enumerate(seen):
        r, c = divmod(idx, 6)
        pair = _ADFGVX_AXIS[r] + _ADFGVX_AXIS[c]
        char_to_pair[ch] = pair
        pair_to_char[pair] = ch
    return char_to_pair, pair_to_char


def _adfgvx_columnar_encode(pair_string: str, trans_key: str) -> str:
    """เข้ารหัสขั้นที่ 2 ของ ADFGVX: columnar transposition ตามคีย์เวิร์ด —
    เขียน pair_string ลงตารางทีละแถว กว้างเท่าความยาวคีย์ แล้วอ่านออกทีละคอลัมน์
    ตามลำดับตัวอักษรของคีย์ (คอลัมน์ที่ตัวอักษรคีย์เรียงตามตัวอักษรก่อนสุด อ่านก่อน)"""
    key = trans_key.upper()
    ncols = len(key)
    rows = [pair_string[i:i + ncols] for i in range(0, len(pair_string), ncols)]
    order = sorted(range(ncols), key=lambda i: (key[i], i))
    out = []
    for col in order:
        for row in rows:
            if col < len(row):
                out.append(row[col])
    return "".join(out)


def _adfgvx_columnar_decode(cipher: str, trans_key: str) -> str:
    key = trans_key.upper()
    ncols = len(key)
    n = len(cipher)
    nrows = -(-n // ncols)  # ceil
    n_full_cols = n - (nrows - 1) * ncols  # จำนวนคอลัมน์ที่มีครบทุกแถว
    order = sorted(range(ncols), key=lambda i: (key[i], i))
    col_lens = [nrows if col < n_full_cols else nrows - 1 for col in range(ncols)]
    cols_by_index = {}
    pos = 0
    for col in order:
        length = col_lens[col]
        cols_by_index[col] = cipher[pos:pos + length]
        pos += length
    rows = []
    for r in range(nrows):
        row_chars = []
        for c in range(ncols):
            if r < len(cols_by_index[c]):
                row_chars.append(cols_by_index[c][r])
        rows.append("".join(row_chars))
    return "".join(rows)


def adfgvx_encode(plaintext: str, polybius_key: str, trans_key: str) -> str:
    char_to_pair, _ = _adfgvx_square(polybius_key)
    clean = "".join(ch for ch in plaintext.upper() if ch in _ADFGVX_CHARSET)
    pairs = "".join(char_to_pair[ch] for ch in clean)
    return _adfgvx_columnar_encode(pairs, trans_key)


def adfgvx_decode(ciphertext: str, polybius_key: str, trans_key: str) -> str:
    _, pair_to_char = _adfgvx_square(polybius_key)
    pairs = _adfgvx_columnar_decode(ciphertext, trans_key)
    out = []
    for i in range(0, len(pairs) - 1, 2):
        pair = pairs[i:i + 2]
        out.append(pair_to_char.get(pair, "?"))
    return "".join(out)


# --- คลังเศษข้อความลับ (lore fragments) ---
# plaintext เป็น "ต้นฉบับจริง" ที่ผู้เล่นต้องถอดให้ได้ (normalize เป็นตัวใหญ่ ไม่มีช่องว่าง
# ก่อนเทียบ) polybius_key / trans_key เป็นคีย์ประจำเศษนั้นๆ (fix ไว้ ไม่สุ่ม เพราะ
# เป็นปริศนาที่ต้องแก้ได้จริง ไม่ใช่ความปลอดภัย)
VMAX_LORE_FRAGMENTS = [
    {
        "id": "frag_01_outpost",
        "title": "จารึกด่านหน้าที่ถูกทิ้งร้าง",
        "plaintext": "THE OUTPOST FELL AT DAWN NO SURVIVORS FOUND",
        "polybius_key": "SHADOW",
        "trans_key": "NEEDLE",
        "reward_shards": 15,
    },
    {
        "id": "frag_02_general",
        "title": "คำสั่งลับของนายพลไร้ชื่อ",
        "plaintext": "HOLD THE RIDGE UNTIL THE BAMBOO SWORD ARRIVES",
        "polybius_key": "TACTICAL",
        "trans_key": "DUEL",
        "reward_shards": 20,
    },
    {
        "id": "frag_03_legend",
        "title": "ตำนานเข็มขั้วมรกต",
        "plaintext": "WHOEVER FINDS THE GREEN NEEDLE FIRST CONTROLS THE STORM",
        "polybius_key": "EMERALD",
        "trans_key": "POLE",
        "reward_shards": 25,
    },
]
VMAX_LORE_FRAGMENTS_BY_ID = {f["id"]: f for f in VMAX_LORE_FRAGMENTS}
for _f in VMAX_LORE_FRAGMENTS:
    _f["ciphertext"] = adfgvx_encode(_f["plaintext"], _f["polybius_key"], _f["trans_key"])


def _lc_now():
    return _lc_time.time()


def _lc_normalize(s: str) -> str:
    return "".join(ch for ch in (s or "").upper() if ch in _ADFGVX_CHARSET)


def _lc_new_state(uid):
    return {
        "uid": str(uid),
        "shards": 0,
        "discovered": {},  # fragment_id -> {"hints_revealed": int, "solved": bool, "attempts": int}
        "updated_at": _lc_now(),
    }


def _lc_state(uid):
    with VMAX_LORE_CIPHER_LOCK:
        return VMAX_LORE_CIPHER_STATE.setdefault(str(uid), _lc_new_state(uid))


def vmax_lore_cipher_discover(uid, fragment_id):
    """ปลดล็อกให้ผู้เล่นเห็น ciphertext ของเศษข้อความนี้ (ยังไม่เฉลย plaintext) —
    เรียกจากจุดใดก็ได้ในเกมที่อยากผูกไว้ เช่น เก็บไอเทม/ฆ่าศัตรู/เดินผ่านจุดที่กำหนด"""
    frag = VMAX_LORE_FRAGMENTS_BY_ID.get(fragment_id)
    if not frag:
        return {"ok": False, "reason": "unknown_fragment"}
    st = _lc_state(uid)
    with VMAX_LORE_CIPHER_LOCK:
        entry = st["discovered"].setdefault(
            fragment_id, {"hints_revealed": 0, "solved": False, "attempts": 0}
        )
        st["updated_at"] = _lc_now()
        return {
            "ok": True,
            "fragment_id": fragment_id,
            "title": frag["title"],
            "ciphertext": frag["ciphertext"],
            "already_discovered": entry is not None,
        }


def vmax_lore_cipher_attempt(uid, fragment_id, guess_text):
    frag = VMAX_LORE_FRAGMENTS_BY_ID.get(fragment_id)
    if not frag:
        return {"ok": False, "reason": "unknown_fragment"}
    st = _lc_state(uid)
    with VMAX_LORE_CIPHER_LOCK:
        entry = st["discovered"].get(fragment_id)
        if entry is None:
            return {"ok": False, "reason": "not_discovered_yet"}
        if entry["solved"]:
            return {"ok": True, "already_solved": True, "shards": st["shards"]}
        entry["attempts"] += 1
        guess_norm = _lc_normalize(guess_text)
        answer_norm = _lc_normalize(frag["plaintext"])
        if guess_norm == answer_norm:
            entry["solved"] = True
            st["shards"] += frag["reward_shards"]
            st["updated_at"] = _lc_now()
            return {
                "ok": True, "correct": True, "reward_shards": frag["reward_shards"],
                "total_shards": st["shards"], "plaintext": frag["plaintext"],
            }
        similarity = _lc_difflib.SequenceMatcher(None, guess_norm, answer_norm).ratio()
        st["updated_at"] = _lc_now()
        return {
            "ok": True, "correct": False, "attempts": entry["attempts"],
            "similarity_pct": round(similarity * 100, 1),
        }


def vmax_lore_cipher_hint(uid, fragment_id):
    """เฉลยทีละตัวอักษรจากซ้ายไปขวาของ plaintext (นับเฉพาะตัวอักษร/ตัวเลข ไม่รวม
    ช่องว่าง) แลกด้วย shard เล็กน้อย — ไม่บังคับใช้ เป็นทางลัดสำหรับคนไม่อยากถอดเอง"""
    frag = VMAX_LORE_FRAGMENTS_BY_ID.get(fragment_id)
    if not frag:
        return {"ok": False, "reason": "unknown_fragment"}
    st = _lc_state(uid)
    with VMAX_LORE_CIPHER_LOCK:
        entry = st["discovered"].get(fragment_id)
        if entry is None:
            return {"ok": False, "reason": "not_discovered_yet"}
        if entry["solved"]:
            return {"ok": True, "already_solved": True}
        answer_norm = _lc_normalize(frag["plaintext"])
        if entry["hints_revealed"] >= len(answer_norm):
            return {"ok": True, "hint": "เฉลยครบทุกตัวอักษรแล้ว", "revealed": answer_norm}
        entry["hints_revealed"] += 1
        st["shards"] = max(0, st["shards"] - 2)
        revealed = answer_norm[: entry["hints_revealed"]]
        st["updated_at"] = _lc_now()
        return {
            "ok": True, "revealed_so_far": revealed,
            "revealed_count": entry["hints_revealed"], "total_len": len(answer_norm),
            "shards": st["shards"],
        }


def vmax_lore_cipher_public(uid):
    st = _lc_state(uid)
    with VMAX_LORE_CIPHER_LOCK:
        frags = []
        for fid, entry in st["discovered"].items():
            frag = VMAX_LORE_FRAGMENTS_BY_ID[fid]
            frags.append({
                "id": fid, "title": frag["title"], "ciphertext": frag["ciphertext"],
                "solved": entry["solved"], "hints_revealed": entry["hints_revealed"],
                "attempts": entry["attempts"],
            })
        return {"ok": True, "shards": st["shards"], "fragments": frags, "updated_at": st["updated_at"]}


def _run_lore_cipher_selftest():
    # 1) round-trip เข้ารหัส/ถอดรหัสต้องได้ข้อความเดิมเป๊ะ
    for frag in VMAX_LORE_FRAGMENTS:
        decoded = adfgvx_decode(frag["ciphertext"], frag["polybius_key"], frag["trans_key"])
        assert decoded == _lc_normalize(frag["plaintext"]), (frag["id"], decoded)

    uid = "__vmax_lore_cipher_selftest__"
    with VMAX_LORE_CIPHER_LOCK:
        VMAX_LORE_CIPHER_STATE.pop(uid, None)

    fid = VMAX_LORE_FRAGMENTS[0]["id"]
    d = vmax_lore_cipher_discover(uid, fid)
    assert d["ok"] and d["ciphertext"]

    wrong = vmax_lore_cipher_attempt(uid, fid, "WRONG GUESS")
    assert wrong["ok"] and wrong["correct"] is False

    h = vmax_lore_cipher_hint(uid, fid)
    assert h["ok"] and h["revealed_count"] == 1

    correct = vmax_lore_cipher_attempt(uid, fid, VMAX_LORE_FRAGMENTS[0]["plaintext"])
    assert correct["ok"] and correct["correct"] is True
    assert correct["total_shards"] > 0

    already = vmax_lore_cipher_attempt(uid, fid, "anything")
    assert already["ok"] and already["already_solved"] is True

    pub = vmax_lore_cipher_public(uid)
    assert pub["shards"] > 0 and pub["fragments"][0]["solved"] is True
    return True


