# [EVENT] 4v4 TEAM CLASH — อีเวนต์ 4 ปะทะ 4
# ============================================================================
# ==================== EVENT: 4v4 TEAM CLASH ====================
FOUR_VS_FOUR_EVENT = {
    "id":"event_4v4_team_clash","name":"4v4 Team Clash","name_th":"ศึกทีม 4 ปะทะ 4",
    "type":"4v4","category":"event","team_size":4,"max_players":8,
    "round_time_sec":600,"score_to_win":30,
    "entry_fee_credits":85000,"entry_fee_currency":"credits",
}
FOUR_VS_FOUR_MAP = {
    "id":"quarry_crossing_4v4","name":"Quarry Crossing","width":420.0,"height":420.0,
    "spawn_points":[
        {"team":1,"x":-150,"y":-150},{"team":1,"x":-120,"y":-175},{"team":1,"x":-175,"y":-120},{"team":1,"x":-100,"y":-120},
        {"team":2,"x":150,"y":150},{"team":2,"x":120,"y":175},{"team":2,"x":175,"y":120},{"team":2,"x":100,"y":120},
    ],
}
FOUR_VS_FOUR_MATCHES={};FOUR_VS_FOUR_PLAYER_INDEX={};FOUR_VS_FOUR_LOCK=threading.RLock()
FOUR_VS_FOUR_MAILBOX={}  # uid -> [{mail_id,title,reward,claimed,received_at}]
FOUR_VS_FOUR_KILL_BONUS_CREDITS=2000

def _4v4_room(mid): return f"4v4:{mid}"

def _4v4_mail_add(uid, reward, title, match_id):
    uid=str(uid)
    entry={"mail_id":uuid.uuid4().hex[:10],"title":title,"source":"4v4 Team Clash","match_id":match_id,
           "reward":dict(reward),"claimed":False,"received_at":time.time()}
    FOUR_VS_FOUR_MAILBOX.setdefault(uid,[]).append(entry)
    return entry

def _4v4_public(m):
    return {"match_id":m["match_id"],"event":FOUR_VS_FOUR_EVENT,"map":m["map"],"phase":m["phase"],"started_at":m["started_at"],"ends_at":m["ends_at"],"teams":{str(t):{"uids":list(d["uids"]),"score":d["score"],"alive":d["alive"]} for t,d in m["teams"].items()},"players":{u:{"team":p["team"],"status":p["status"],"x":p["x"],"y":p["y"],"kills":p["kills"],"deaths":p["deaths"]} for u,p in m["players"].items()},"winner_team":m.get("winner_team"),"result_reason":m.get("result_reason"),"rewards":m.get("rewards",{})}

def _4v4_finish(mid,reason):
    m=FOUR_VS_FOUR_MATCHES.get(mid)
    if not m or m["phase"]=="finished": return False
    a,b=m["teams"][1]["score"],m["teams"][2]["score"];w=1 if a>b else 2 if b>a else None
    m["phase"]="finished";m["winner_team"]=w;m["result_reason"]=reason
    rewards={}
    if w in (1,2):
        for uid in m["teams"][w]["uids"]:
            kills=int(m["players"].get(uid,{}).get("kills",0))
            bonus=kills*FOUR_VS_FOUR_KILL_BONUS_CREDITS
            total=int(FOUR_VS_FOUR_EVENT["entry_fee_credits"])+bonus
            mail=_4v4_mail_add(uid,{"credits":total,"base_win_reward":int(FOUR_VS_FOUR_EVENT["entry_fee_credits"]),"kill_bonus":bonus,"kills":kills},
                               f"รางวัลชนะ 4v4 — {kills} Kills",mid)
            rewards[uid]={"credits":total,"base_win_reward":int(FOUR_VS_FOUR_EVENT["entry_fee_credits"]),"kill_bonus":bonus,"kills":kills,"mail_id":mail["mail_id"]}
    m["rewards"]=rewards
    sio.emit("4v4_finished",{"match_id":mid,"winner_team":w,"scores":{"1":a,"2":b},"reason":reason,"rewards":rewards,"reward_delivery":"mailbox"},room=_4v4_room(mid));return True
def _4v4_start(mid):
    m=FOUR_VS_FOUR_MATCHES.get(mid)
    if not m or m["phase"]!="lobby": return False
    m["phase"]="combat";m["started_at"]=time.time();m["ends_at"]=m["started_at"]+FOUR_VS_FOUR_EVENT["round_time_sec"]
    sio.emit("4v4_started",{"match":_4v4_public(m)},room=_4v4_room(mid));return True
def _4v4_join(mid,uid,team=None):
    m=FOUR_VS_FOUR_MATCHES.get(mid);uid=str(uid)
    if not m:return False,"ไม่พบแมตช์ 4v4",None
    if m["phase"]!="lobby":return False,"แมตช์เริ่มแล้ว",None
    if uid in m["team_of_uid"]:return True,"อยู่ในแมตช์แล้ว",m
    if team not in (1,2):team=1 if len(m["teams"][1]["uids"])<=len(m["teams"][2]["uids"]) else 2
    if len(m["teams"][team]["uids"])>=4:
        team=2 if team==1 else 1
        if len(m["teams"][team]["uids"])>=4:return False,"แมตช์เต็ม 4v4",None

    # ค่าเข้าอีเวนต์ตามต้นแบบ: 85,000 เครดิต / ผู้เล่น / ครั้ง
    # ใช้ P proxy เพื่อหักจากกระเป๋าของ uid ปัจจุบันของ request โดยตรง
    entry_fee=int(FOUR_VS_FOUR_EVENT.get("entry_fee_credits",85000))
    if int(P.get("credits",0)) < entry_fee:
        return False,f"เครดิตไม่พอสำหรับค่าเข้า 4v4 ({entry_fee:,} เครดิต)",None
    P["credits"] -= entry_fee
    try:
        WALLET["balance"] = P["credits"]
    except Exception:
        pass

    slot=len(m["teams"][team]["uids"]);sp=FOUR_VS_FOUR_MAP["spawn_points"][(team-1)*4+slot]
    m["teams"][team]["uids"].append(uid);m["teams"][team]["alive"]+=1;m["team_of_uid"][uid]=team
    m["players"][uid]={"uid":uid,"team":team,"status":"alive","x":sp["x"],"y":sp["y"],"kills":0,"deaths":0}
    FOUR_VS_FOUR_PLAYER_INDEX[uid]=mid;sio.emit("4v4_player_joined",{"match_id":mid,"uid":uid,"team":team},room=_4v4_room(mid))
    if all(len(m["teams"][t]["uids"])==4 for t in (1,2)): _4v4_start(mid)
    return True,"เข้าร่วม 4v4 แล้ว",m
def four_vs_four_create_match(uid):
    uid=str(uid or "guest")
    with FOUR_VS_FOUR_LOCK:
        old=FOUR_VS_FOUR_PLAYER_INDEX.get(uid)
        if old and old in FOUR_VS_FOUR_MATCHES and FOUR_VS_FOUR_MATCHES[old]["phase"] in ("lobby","combat"):return old,FOUR_VS_FOUR_MATCHES[old]
        mid=f"4v4_{uuid.uuid4().hex[:10]}"
        m={"match_id":mid,"event_id":FOUR_VS_FOUR_EVENT["id"],"map":FOUR_VS_FOUR_MAP,"phase":"lobby","teams":{1:{"uids":[],"score":0,"alive":0},2:{"uids":[],"score":0,"alive":0}},"team_of_uid":{},"players":{},"started_at":None,"ends_at":None,"winner_team":None,"result_reason":None}
        FOUR_VS_FOUR_MATCHES[mid]=m;_4v4_join(mid,uid,1);return mid,m
def four_vs_four_join_match(mid,uid,team=None):
    with FOUR_VS_FOUR_LOCK:return _4v4_join(mid,uid,team)
def four_vs_four_move(mid,uid,x,y):
    with FOUR_VS_FOUR_LOCK:
        m=FOUR_VS_FOUR_MATCHES.get(mid);p=m and m["players"].get(str(uid))
        if not m or m["phase"]!="combat" or not p or p["status"]!="alive":return False,"ขยับไม่ได้",None
        p["x"],p["y"]=float(x),float(y);return True,"อัปเดตตำแหน่งแล้ว",p
def four_vs_four_eliminate(mid,killer_uid,victim_uid):
    with FOUR_VS_FOUR_LOCK:
        m=FOUR_VS_FOUR_MATCHES.get(mid);k=m and m["players"].get(str(killer_uid));v=m and m["players"].get(str(victim_uid))
        if not m or m["phase"]!="combat" or not k or not v:return False,"ไม่พบผู้เล่น",None
        if str(killer_uid)==str(victim_uid):return False,"ยิงตัวเองไม่ได้",None
        if k["status"]!="alive" or v["status"]!="alive":return False,"ผู้เล่นไม่ได้อยู่ในสถานะต่อสู้",None
        if k["team"]==v["team"]:return False,"ห้ามยิงพวกเดียวกัน",None
        v["status"]="dead";v["deaths"]+=1;k["kills"]+=1;m["teams"][v["team"]]["alive"]=max(0,m["teams"][v["team"]]["alive"]-1);m["teams"][k["team"]]["score"]+=1
        payload={"match_id":mid,"killer_uid":str(killer_uid),"victim_uid":str(victim_uid),"team":k["team"],"scores":{"1":m["teams"][1]["score"],"2":m["teams"][2]["score"]}}
        sio.emit("4v4_elimination",payload,room=_4v4_room(mid))
        if m["teams"][k["team"]]["score"]>=FOUR_VS_FOUR_EVENT["score_to_win"]:_4v4_finish(mid,"score_limit")
        return True,"กำจัดสำเร็จ",payload
def four_vs_four_respawn(mid,uid):
    with FOUR_VS_FOUR_LOCK:
        m=FOUR_VS_FOUR_MATCHES.get(mid);p=m and m["players"].get(str(uid))
        if not m or m["phase"]!="combat" or not p or p["status"]!="dead":return False,"ยังเกิดใหม่ไม่ได้",None
        team=p["team"];slot=m["teams"][team]["uids"].index(str(uid));sp=FOUR_VS_FOUR_MAP["spawn_points"][(team-1)*4+slot]
        p["status"]="alive";p["x"],p["y"]=sp["x"],sp["y"];m["teams"][team]["alive"]+=1;sio.emit("4v4_respawned",{"match_id":mid,"uid":str(uid),"team":team},room=_4v4_room(mid));return True,"เกิดใหม่แล้ว",p
def four_vs_four_tick_all():
    with FOUR_VS_FOUR_LOCK:
        now=time.time()
        for mid,m in list(FOUR_VS_FOUR_MATCHES.items()):
            if m["phase"]=="combat" and m.get("ends_at") and now>=m["ends_at"]:_4v4_finish(mid,"time_limit")
VMAX_MODULES["4v4_team_clash"]={"name":FOUR_VS_FOUR_EVENT["name"],"name_th":FOUR_VS_FOUR_EVENT["name_th"],"version":"1.0.0","category":"event","genre":"shooter","routes":["/events/4v4","/api/events/4v4/catalog","/api/events/4v4/create","/api/events/4v4/join","/api/events/4v4/state","/api/events/4v4/move","/api/events/4v4/eliminate","/api/events/4v4/respawn","/api/events/4v4/mailbox","/api/events/4v4/mailbox/claim"]}
try:
    if isinstance(EVENT_CATALOG,dict):EVENT_CATALOG.setdefault(FOUR_VS_FOUR_EVENT["id"],dict(FOUR_VS_FOUR_EVENT))
except NameError:pass
