def _run_blast_armor_selftest():
    uid = "__blast_armor_selftest__"
    with VMAX_ARMOR_LOCK:
        VMAX_PLAYER_ARMOR_DURABILITY.pop(uid, None)

    # ไกลเกิน max_radius -> ไม่เสียหายเลย
    far = vmax_apply_explosion_armor_damage(uid, 999, "frag_grenade")
    assert far["ok"] and far["damage_fraction"] == 0.0 and far["durability_after"] == 100.0

    # อยู่ในระยะ fatal_radius (1 เมตร < 1.5) -> เกราะเหลือ 0 ทันที ตามที่ผู้ใช้ถาม
    close = vmax_apply_explosion_armor_damage(uid, 1.0, "frag_grenade")
    assert close["ok"] and close["fatal_radius_hit"] is True
    assert close["durability_after"] == 0.0 and close["destroyed"] is True

    # ซ่อมแล้วต้องกลับมาเต็ม และ destroyed ต้องเป็น False
    fixed = vmax_repair_armor(uid)
    assert fixed["ok"] and fixed["durability"] == 100.0 and fixed["destroyed"] is False

    # ระยะกึ่งกลาง (ไม่ fatal ไม่ปลอดภัย) -> เสียหายบางส่วน ไม่ใช่ 0% หรือ 100%
    mid = vmax_apply_explosion_armor_damage(uid, 3.0, "frag_grenade")
    assert mid["ok"] and 0.0 < mid["damage_fraction"] < 1.0

    with VMAX_ARMOR_LOCK:
        VMAX_PLAYER_ARMOR_DURABILITY.pop(uid, None)
    return True


if '--selftest-blast-armor' in sys.argv:
    ok = _run_blast_armor_selftest()
    sys.exit(0 if ok else 1)


# =====================================================================
# VMAX TIMED BAN SYSTEM — ระบบแบนแบบกำหนดระยะเวลา (7 วัน / 30 วัน / 60 วัน / ถาวร)
# =====================================================================
# ต่อยอดจากระบบแบนเดิม (BANNED_UIDS) ที่มีอยู่แล้วในไฟล์นี้ — ของเดิมเป็นแค่
# set() แบนถาวรอย่างเดียว ระบบนี้เพิ่มการแบนแบบมีกำหนดเวลา พอครบกำหนดจะ
# ปลดแบนให้อัตโนมัติ (มีเธรดพื้นหลังคอยเช็ค) โดยยังคง enforce ผ่าน BANNED_UIDS
# ตัวเดิม เพื่อไม่ต้องแก้จุดเช็คสิทธิ์ (เช่น socket connect) ที่มีอยู่แล้วทั่วไฟล์
# =====================================================================
VMAX_TEMP_BAN_DURATIONS_DAYS = (7, 30, 60)   # ตัวเลือกมาตรฐานที่ระบบรองรับ (None = แบนถาวร)

# uid -> {"banned_at", "expires_at" (None ถ้าถาวร), "duration_days" (None ถ้าถาวร),
#         "reason", "banned_by", "permanent"}
VMAX_TEMP_BANS = {}
VMAX_BAN_LOCK = _arm_threading.Lock()

import sqlite3 as _ban_sqlite3

# ---------------------------------------------------------------------
# (1) PERSISTENT STORAGE — เก็บแบนที่ยัง active ลง sqlite3 กันหายตอน server
#     restart, และ (2) BAN HISTORY — เก็บ log ทุกเหตุการณ์แบน/ปลดแบน/หมดอายุ
#     ไว้ถาวร (ไม่ลบแม้ปลดแบนแล้ว) เพื่อดูย้อนหลังได้ว่า uid ไหนเคยโดนแบนกี่ครั้ง
# ---------------------------------------------------------------------
VMAX_BAN_DB_PATH = os.environ.get(
    "VMAX_BAN_DB_PATH",
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "vmax_ban_system.sqlite3"),
)


def _ban_db():
    conn = _ban_sqlite3.connect(VMAX_BAN_DB_PATH, timeout=20, check_same_thread=False)
    conn.execute("""CREATE TABLE IF NOT EXISTS active_bans (
        uid TEXT PRIMARY KEY, banned_at REAL, expires_at REAL,
        duration_days INTEGER, reason TEXT, banned_by TEXT, permanent INTEGER
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS ban_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT, uid TEXT, event_type TEXT,
        at REAL, duration_days INTEGER, reason TEXT, actor_uid TEXT, permanent INTEGER
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS ban_moderators (
        uid TEXT PRIMARY KEY, added_at REAL, added_by TEXT
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS ban_appeals (
        id INTEGER PRIMARY KEY AUTOINCREMENT, uid TEXT, submitted_at REAL,
        message TEXT, status TEXT, reviewed_by TEXT, reviewed_at REAL, review_note TEXT
    )""")
    return conn


def _ban_persist_upsert(uid, rec):
    """เขียน/อัปเดตแบนที่ active อยู่ลง DB — เรียกทุกครั้งที่แบนใหม่ ให้รอด restart"""
    conn = _ban_db()
    try:
        conn.execute(
            "INSERT INTO active_bans (uid, banned_at, expires_at, duration_days, reason, banned_by, permanent) "
            "VALUES (?,?,?,?,?,?,?) "
            "ON CONFLICT(uid) DO UPDATE SET banned_at=excluded.banned_at, expires_at=excluded.expires_at, "
            "duration_days=excluded.duration_days, reason=excluded.reason, banned_by=excluded.banned_by, "
            "permanent=excluded.permanent",
            (uid, rec["banned_at"], rec["expires_at"], rec["duration_days"], rec["reason"],
             rec["banned_by"], int(rec["permanent"])))
        conn.commit()
    finally:
        conn.close()


def _ban_persist_delete(uid):
    conn = _ban_db()
    try:
        conn.execute("DELETE FROM active_bans WHERE uid=?", (uid,))
        conn.commit()
    finally:
        conn.close()


def _ban_history_log(uid, event_type, duration_days=None, reason="", actor_uid="system", permanent=None):
    """บันทึก event ลง ban_history — เก็บถาวรตลอดไป ไม่ถูกลบแม้จะปลดแบน/หมดอายุแล้ว
    ใช้สำหรับดูว่า uid นี้เคยมีประวัติโดนแบนมาแล้วกี่ครั้ง (เผื่อทำ escalation ต่อยอดวันหลัง)"""
    conn = _ban_db()
    try:
        conn.execute(
            "INSERT INTO ban_history (uid, event_type, at, duration_days, reason, actor_uid, permanent) "
            "VALUES (?,?,?,?,?,?,?)",
            (uid, event_type, _arm_time.time(), duration_days, reason, actor_uid,
             None if permanent is None else int(permanent)))
        conn.commit()
    finally:
        conn.close()


def vmax_get_ban_history(uid):
    conn = _ban_db()
    try:
        rows = conn.execute(
            "SELECT event_type, at, duration_days, reason, actor_uid, permanent FROM ban_history "
            "WHERE uid=? ORDER BY at ASC", (uid,)).fetchall()
    finally:
        conn.close()
    events = [{"event_type": r[0], "at": r[1], "duration_days": r[2], "reason": r[3],
               "actor_uid": r[4], "permanent": (None if r[5] is None else bool(r[5]))} for r in rows]
    prior_ban_count = sum(1 for e in events if e["event_type"] == "ban")
    return {"ok": True, "uid": uid, "events": events, "prior_ban_count": prior_ban_count}


def _vmax_load_persisted_bans_at_startup():
    """ตอนบูต server โหลดแบนที่ยัง active (จาก sqlite3) กลับเข้า VMAX_TEMP_BANS/BANNED_UIDS
    แบนที่หมดอายุไปแล้วระหว่าง server ดับจะถูกปลดและลบออกจาก DB ทันทีตอนโหลด"""
    now = _arm_time.time()
    conn = _ban_db()
    try:
        rows = conn.execute("SELECT uid, banned_at, expires_at, duration_days, reason, banned_by, "
                             "permanent FROM active_bans").fetchall()
    finally:
        conn.close()
    for uid, banned_at, expires_at, duration_days, reason, banned_by, permanent in rows:
        permanent = bool(permanent)
        if not permanent and expires_at is not None and now >= expires_at:
            _ban_persist_delete(uid)
            _ban_history_log(uid, "auto_expire", duration_days, reason, "system_startup", False)
            continue
        with VMAX_BAN_LOCK:
            VMAX_TEMP_BANS[uid] = {"banned_at": banned_at, "expires_at": expires_at,
                                    "duration_days": duration_days, "reason": reason,
                                    "banned_by": banned_by, "permanent": permanent}
            BANNED_UIDS.add(uid)


# ---------------------------------------------------------------------
# (3) PERMISSION — จำกัดว่าใครมีสิทธิ์สั่งแบน/ปลดแบนได้บ้าง (ban moderator)
#     seed รายชื่อเริ่มต้นจาก env var VMAX_BAN_MODERATOR_UIDS (คั่นด้วยจุลภาค)
#     เพราะต้องมี "คนแรก" ที่มีสิทธิ์อยู่ก่อน ถึงจะมาเพิ่ม/ถอดคนอื่นผ่าน API ได้
# ---------------------------------------------------------------------
VMAX_BAN_MODERATOR_UIDS = set(
    u.strip() for u in os.environ.get("VMAX_BAN_MODERATOR_UIDS", "").split(",") if u.strip()
)


def vmax_is_ban_moderator(uid):
    return bool(uid) and uid in VMAX_BAN_MODERATOR_UIDS


def vmax_add_ban_moderator(target_uid, added_by):
    if not vmax_is_ban_moderator(added_by):
        return {"ok": False, "reason": "not_authorized"}
    if not target_uid:
        return {"ok": False, "reason": "uid_required"}
    VMAX_BAN_MODERATOR_UIDS.add(target_uid)
    conn = _ban_db()
    try:
        conn.execute("INSERT OR REPLACE INTO ban_moderators (uid, added_at, added_by) VALUES (?,?,?)",
                     (target_uid, _arm_time.time(), added_by))
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "uid": target_uid}


def vmax_remove_ban_moderator(target_uid, removed_by):
    if not vmax_is_ban_moderator(removed_by):
        return {"ok": False, "reason": "not_authorized"}
    VMAX_BAN_MODERATOR_UIDS.discard(target_uid)
    conn = _ban_db()
    try:
        conn.execute("DELETE FROM ban_moderators WHERE uid=?", (target_uid,))
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "uid": target_uid}


def _vmax_load_persisted_moderators_at_startup():
    conn = _ban_db()
    try:
        rows = conn.execute("SELECT uid FROM ban_moderators").fetchall()
    finally:
        conn.close()
    for (uid,) in rows:
        VMAX_BAN_MODERATOR_UIDS.add(uid)


_vmax_load_persisted_moderators_at_startup()
_vmax_load_persisted_bans_at_startup()


# ---------------------------------------------------------------------
# (4) APPEAL SYSTEM — ผู้เล่นที่โดนแบนยื่นอุทธรณ์ได้ 1 คำร้องต่อครั้งที่โดนแบน
#     มี moderator เท่านั้นที่ approve (ปลดแบนให้อัตโนมัติ) หรือ reject ได้
# ---------------------------------------------------------------------
def vmax_submit_ban_appeal(uid, message):
    if not uid:
        return {"ok": False, "reason": "uid_required"}
    if uid not in BANNED_UIDS:
        return {"ok": False, "reason": "not_currently_banned"}
    conn = _ban_db()
    try:
        existing = conn.execute(
            "SELECT id FROM ban_appeals WHERE uid=? AND status='pending'", (uid,)).fetchone()
        if existing:
            return {"ok": False, "reason": "appeal_already_pending", "appeal_id": existing[0]}
        cur = conn.execute(
            "INSERT INTO ban_appeals (uid, submitted_at, message, status) VALUES (?,?,?,?)",
            (uid, _arm_time.time(), message or "", "pending"))
        conn.commit()
        appeal_id = cur.lastrowid
    finally:
        conn.close()
    return {"ok": True, "appeal_id": appeal_id, "status": "pending"}


def vmax_list_ban_appeals(status="pending"):
    conn = _ban_db()
    try:
        if status:
            rows = conn.execute(
                "SELECT id, uid, submitted_at, message, status, reviewed_by, reviewed_at, review_note "
                "FROM ban_appeals WHERE status=? ORDER BY submitted_at ASC", (status,)).fetchall()
        else:
            rows = conn.execute(
                "SELECT id, uid, submitted_at, message, status, reviewed_by, reviewed_at, review_note "
                "FROM ban_appeals ORDER BY submitted_at ASC").fetchall()
    finally:
        conn.close()
    return {"ok": True, "appeals": [
        {"id": r[0], "uid": r[1], "submitted_at": r[2], "message": r[3], "status": r[4],
         "reviewed_by": r[5], "reviewed_at": r[6], "review_note": r[7]} for r in rows]}


def vmax_review_ban_appeal(appeal_id, approve, reviewed_by, review_note=""):
    if not vmax_is_ban_moderator(reviewed_by):
        return {"ok": False, "reason": "not_authorized"}
    conn = _ban_db()
    try:
        row = conn.execute("SELECT uid, status FROM ban_appeals WHERE id=?", (appeal_id,)).fetchone()
        if not row:
            return {"ok": False, "reason": "appeal_not_found"}
        uid, status = row
        if status != "pending":
            return {"ok": False, "reason": "appeal_already_reviewed", "status": status}
        new_status = "approved" if approve else "rejected"
        conn.execute("UPDATE ban_appeals SET status=?, reviewed_by=?, reviewed_at=?, review_note=? "
                     "WHERE id=?", (new_status, reviewed_by, _arm_time.time(), review_note, appeal_id))
        conn.commit()
    finally:
        conn.close()
    if approve:
        vmax_unban_user(uid, unbanned_by=f"appeal_approved_by:{reviewed_by}")
    return {"ok": True, "appeal_id": appeal_id, "uid": uid, "status": new_status}


def vmax_ban_user(uid, duration_days=None, reason="", banned_by="system"):
    """แบน uid โดยระบุจำนวนวัน (แนะนำ 7 / 30 / 60) หรือไม่ระบุ (None) = แบนถาวร
    รองรับตัวเลขวันอื่นนอกเหนือ 7/30/60 ได้ด้วยถ้าต้องใช้กรณีพิเศษ"""
    if not uid:
        return {"ok": False, "reason": "uid_required"}

    permanent = duration_days is None
    if not permanent:
        try:
            duration_days = int(duration_days)
        except (TypeError, ValueError):
            return {"ok": False, "reason": "invalid_duration_days"}
        if duration_days <= 0:
            return {"ok": False, "reason": "invalid_duration_days"}

    now = _arm_time.time()
    expires_at = None if permanent else now + duration_days * 86400

    rec = {
        "banned_at": now, "expires_at": expires_at, "duration_days": duration_days,
        "reason": reason or "", "banned_by": banned_by or "system", "permanent": permanent,
    }
    with VMAX_BAN_LOCK:
        VMAX_TEMP_BANS[uid] = rec
        BANNED_UIDS.add(uid)   # ให้จุด enforce เดิมทั่วไฟล์ (เช่น socket connect) เห็นผลทันที

    _ban_persist_upsert(uid, rec)                                             # (1) รอด restart
    _ban_history_log(uid, "ban", duration_days, reason, banned_by, permanent) # (2) เก็บประวัติถาวร

    try:
        sio.emit("player_banned", {
            "uid": uid, "permanent": permanent, "duration_days": duration_days,
            "expires_at": expires_at, "reason": reason,
        }, room=uid)
    except Exception:
        pass

    return {"ok": True, "uid": uid, "permanent": permanent, "duration_days": duration_days,
            "banned_at": now, "expires_at": expires_at, "reason": reason, "banned_by": banned_by}


def vmax_unban_user(uid, unbanned_by="system"):
    """ปลดแบน uid ก่อนกำหนด (manual unban / appeal สำเร็จ)"""
    if not uid:
        return {"ok": False, "reason": "uid_required"}
    with VMAX_BAN_LOCK:
        had_record = VMAX_TEMP_BANS.pop(uid, None)
        was_banned = uid in BANNED_UIDS
        BANNED_UIDS.discard(uid)
    if not was_banned and had_record is None:
        return {"ok": False, "reason": "not_banned"}
    _ban_persist_delete(uid)                              # (1) เอาออกจาก DB ด้วย
    _ban_history_log(uid, "unban", actor_uid=unbanned_by)  # (2) บันทึกประวัติปลดแบน
    try:
        sio.emit("player_unbanned", {"uid": uid, "unbanned_by": unbanned_by})
    except Exception:
        pass
    return {"ok": True, "uid": uid, "unbanned_by": unbanned_by}


def vmax_get_ban_status(uid):
    """เช็คสถานะแบนปัจจุบันของ uid พร้อมเวลาที่เหลือ (วินาที) ถ้าเป็นแบบมีกำหนดเวลา"""
    with VMAX_BAN_LOCK:
        rec = VMAX_TEMP_BANS.get(uid)
        is_banned = uid in BANNED_UIDS
    if rec is None:
        return {"ok": True, "uid": uid, "banned": is_banned, "permanent": is_banned or None}
    remaining = None
    if not rec["permanent"] and rec["expires_at"] is not None:
        remaining = max(0.0, rec["expires_at"] - _arm_time.time())
    return {"ok": True, "uid": uid, "banned": is_banned, "permanent": rec["permanent"],
            "duration_days": rec["duration_days"], "banned_at": rec["banned_at"],
            "expires_at": rec["expires_at"], "seconds_remaining": remaining,
            "reason": rec["reason"], "banned_by": rec["banned_by"]}


def vmax_list_active_bans():
    with VMAX_BAN_LOCK:
        return {"ok": True, "count": len(VMAX_TEMP_BANS),
                "bans": [dict(v, uid=k) for k, v in VMAX_TEMP_BANS.items()]}


def _vmax_ban_expire_loop():
    """เธรดพื้นหลัง — เช็คทุก 60 วิว่าแบนแบบมีกำหนดเวลาอันไหนครบกำหนดแล้ว ปลดแบนอัตโนมัติ"""
    while True:
        try:
            now = _arm_time.time()
            expired_uids = []
            with VMAX_BAN_LOCK:
                for uid, rec in list(VMAX_TEMP_BANS.items()):
                    if not rec["permanent"] and rec["expires_at"] is not None and now >= rec["expires_at"]:
                        expired_uids.append(uid)
                popped = {}
                for uid in expired_uids:
                    popped[uid] = VMAX_TEMP_BANS.pop(uid, None)
                    BANNED_UIDS.discard(uid)
            for uid in expired_uids:
                _ban_persist_delete(uid)                                 # (1) ลบออกจาก DB ด้วย
                rec = popped.get(uid) or {}
                _ban_history_log(uid, "auto_expire", rec.get("duration_days"),
                                  rec.get("reason", ""), "auto_expire", False)  # (2) เก็บประวัติ
                try:
                    sio.emit("player_unbanned", {"uid": uid, "unbanned_by": "auto_expire"})
                except Exception:
                    pass
        except Exception as exc:
            print(f"[timed_ban] expire loop error: {exc}")
        _arm_time.sleep(60)


VMAX_MODULES["timed_ban_system"] = {
    "name": "Timed Ban System", "name_th": "ระบบแบนแบบกำหนดระยะเวลา",
    "version": "1.0", "category": "moderation", "genre": "all",
    "description": "แบนผู้เล่นแบบกำหนดวันได้ (7 / 30 / 60 วัน หรือถาวร) พร้อมปลดแบนอัตโนมัติเมื่อครบกำหนด "
                    "ต่อยอดจากระบบ BANNED_UIDS เดิมโดยไม่กระทบจุด enforce ที่มีอยู่แล้ว "
                    "เก็บ log ประวัติถาวรลง sqlite3, รอดจาก server restart, จำกัดสิทธิ์เฉพาะ "
                    "ban moderator, และมีระบบอุทธรณ์ (appeal) ให้ผู้เล่นยื่นขอทบทวนได้",
    "routes": ["/api/anticheat/ban-timed", "/api/anticheat/unban-timed",
               "/api/anticheat/ban-status", "/api/anticheat/active-bans-timed",
               "/api/anticheat/ban-history", "/api/anticheat/ban-moderators/add",
               "/api/anticheat/ban-moderators/remove", "/api/anticheat/appeal/submit",
               "/api/anticheat/appeal/list", "/api/anticheat/appeal/review"],
}


@app.route('/api/anticheat/ban-timed', methods=['POST'])
@require_auth_toggleable
def api_ban_timed():
    body = request.get_json(silent=True) or {}
    target_uid = body.get("uid")
    if not target_uid:
        return jsonify({"ok": False, "reason": "uid_required"}), 400
    banned_by = resolve_uid(body) or "system"
    if not vmax_is_ban_moderator(banned_by):   # (3) จำกัดสิทธิ์ — ต้องเป็น ban moderator เท่านั้น
        return jsonify({"ok": False, "reason": "not_authorized"}), 403
    duration_days = body.get("duration_days")   # 7, 30, 60 หรือ None = ถาวร
    return jsonify(vmax_ban_user(target_uid, duration_days, body.get("reason", ""), banned_by))


@app.route('/api/anticheat/unban-timed', methods=['POST'])
@require_auth_toggleable
def api_unban_timed():
    body = request.get_json(silent=True) or {}
    target_uid = body.get("uid")
    if not target_uid:
        return jsonify({"ok": False, "reason": "uid_required"}), 400
    unbanned_by = resolve_uid(body) or "system"
    if not vmax_is_ban_moderator(unbanned_by):   # (3) จำกัดสิทธิ์เช่นกัน
        return jsonify({"ok": False, "reason": "not_authorized"}), 403
    return jsonify(vmax_unban_user(target_uid, unbanned_by))


@app.route('/api/anticheat/ban-status', methods=['GET'])
def api_ban_status():
    target_uid = request.args.get("uid")
    if not target_uid:
        return jsonify({"ok": False, "reason": "uid_required"}), 400
    return jsonify(vmax_get_ban_status(target_uid))


@app.route('/api/anticheat/active-bans-timed', methods=['GET'])
@require_auth_toggleable
def api_active_bans_timed():
    caller = resolve_uid({})
    if not vmax_is_ban_moderator(caller):
        return jsonify({"ok": False, "reason": "not_authorized"}), 403
    return jsonify(vmax_list_active_bans())


# ---- (2) ban history endpoint ----
@app.route('/api/anticheat/ban-history', methods=['GET'])
@require_auth_toggleable
def api_ban_history():
    caller = resolve_uid({})
    if not vmax_is_ban_moderator(caller):
        return jsonify({"ok": False, "reason": "not_authorized"}), 403
    target_uid = request.args.get("uid")
    if not target_uid:
        return jsonify({"ok": False, "reason": "uid_required"}), 400
    return jsonify(vmax_get_ban_history(target_uid))


# ---- (3) moderator management endpoints ----
