def _run_dev_sandbox_selftest():
    dev_uid = "__dev_sandbox_selftest_dev__"
    killer_uid = "__dev_sandbox_selftest_killer__"
    VMAX_DEV_UIDS.add(dev_uid)

    # ผู้เล่นทั่วไปต้องไม่เห็นเมนู / เบิกของไม่ได้
    normal_visible = vmax_dev_menu_visible("__not_a_dev__")
    assert normal_visible["ok"] and normal_visible["visible"] is False
    denied = vmax_dev_requisition_item("__not_a_dev__", "M4A1", 1)
    assert not denied["ok"] and denied["reason"] == "not_authorized"

    # dev เห็นเมนู และเบิกของได้ เข้าคลังทดสอบ (แยกจากของจริง)
    dev_visible = vmax_dev_menu_visible(dev_uid)
    assert dev_visible["ok"] and dev_visible["visible"] is True
    r1 = vmax_dev_requisition_item(dev_uid, "M4A1_Test", 1)
    assert r1["ok"] and r1["new_total"] == 1
    r2 = vmax_dev_requisition_item(dev_uid, "M4A1_Test", 2)
    assert r2["ok"] and r2["new_total"] == 3   # เบิกซ้ำต้องบวกสะสม ไม่ทับ
    inv = vmax_dev_get_sandbox_inventory(dev_uid)
    assert inv["ok"] and any(i["item"] == "M4A1_Test" and i["qty"] == 3 for i in inv["items"])

    # console command: ตั้งของเป็น ∞ สำหรับทดสอบระบบใหญ่
    denied_console = vmax_dev_console_command("__not_a_dev__", "give Ammo_9mm inf")
    assert not denied_console["ok"] and denied_console["reason"] == "not_authorized"

    inf_r = vmax_dev_console_command(dev_uid, "give Ammo_9mm inf")
    assert inf_r["ok"] and inf_r.get("infinite") is True
    inv2 = vmax_dev_get_sandbox_inventory(dev_uid)
    assert "Ammo_9mm" in inv2["infinite_items"]
    assert not any(i["item"] == "Ammo_9mm" for i in inv2["items"])   # ∞ ต้องไม่ปนกับของจำกัดจำนวน

    # เบิกซ้ำของที่เป็น ∞ อยู่แล้วต้องเป็น no-op ไม่ error
    noop = vmax_dev_requisition_item(dev_uid, "Ammo_9mm", 500)
    assert noop["ok"] and noop.get("already_infinite") is True

    # list command ทำงานได้
    listed = vmax_dev_console_command(dev_uid, "list")
    assert listed["ok"] and "∞" in listed["output"]

    # เดฟตายในแมพ -> ของในคลังทดสอบร่วงเป็น loot แล้วคลังทดสอบต้องว่าง
    # *** สำคัญ: Ammo_9mm ที่เป็น ∞ ต้อง "ไม่ร่วง" ไปด้วยเด็ดขาด (แยกจากโลกจริง 100%) ***
    drop = vmax_dev_death_drop(dev_uid, "match_selftest", 10, 0, 10)
    assert drop["ok"] and drop["items"].get("M4A1_Test") == 3
    assert "Ammo_9mm" not in drop["items"]
    inv_after = vmax_dev_get_sandbox_inventory(dev_uid)
    assert inv_after["ok"] and inv_after["items"] == []
    assert "Ammo_9mm" in inv_after["infinite_items"]   # ∞ ยังอยู่ในคลังทดสอบเหมือนเดิม ไม่หายไปไหน

    # อยู่ไกลเกินไป เก็บไม่ได้
    too_far = vmax_loot_dev_drop(killer_uid, drop["drop_id"], 999, 999, 999)
    assert not too_far["ok"] and too_far["reason"] == "too_far"

    # เข้าใกล้แล้วเก็บได้ -> ต้องเข้า "คลังจริง" ของผู้ฆ่า
    got = vmax_loot_dev_drop(killer_uid, drop["drop_id"], 10, 0, 10)
    assert got["ok"] and got["items_received"].get("M4A1_Test") == 3
    real_inv = vmax_get_real_loot_inventory(killer_uid)
    assert any(i["item"] == "M4A1_Test" and i["qty"] == 3 for i in real_inv["items"])

    # เก็บซ้ำจาก drop เดิมต้องไม่ได้ (claimed ไปแล้ว)
    again = vmax_loot_dev_drop(killer_uid, drop["drop_id"], 10, 0, 10)
    assert not again["ok"] and again["reason"] == "already_claimed"

    # permission — ผู้เล่นทั่วไปเพิ่ม dev คนอื่นไม่ได้
    bad_add = vmax_add_dev("someone", added_by="__not_a_dev__")
    assert not bad_add["ok"] and bad_add["reason"] == "not_authorized"
    good_add = vmax_add_dev("new_dev_uid", added_by=dev_uid)
    assert good_add["ok"] and vmax_is_dev("new_dev_uid")
    vmax_remove_dev("new_dev_uid", removed_by=dev_uid)
    assert not vmax_is_dev("new_dev_uid")

    VMAX_DEV_UIDS.discard(dev_uid)
    conn = _dev_db()
    try:
        conn.execute("DELETE FROM dev_real_loot_inventory WHERE uid=?", (killer_uid,))
        conn.execute("DELETE FROM dev_sandbox_inventory WHERE uid=?", (dev_uid,))
        conn.execute("DELETE FROM dev_sandbox_infinite_flags WHERE uid=?", (dev_uid,))
        conn.execute("DELETE FROM dev_users WHERE uid IN (?,?)", (dev_uid, "new_dev_uid"))
        conn.commit()
    finally:
        conn.close()
    return True


# =====================================================================
# VMAX DEVELOPER ARMORY — unified facade over the dev-sandbox subsystems
# ---------------------------------------------------------------------
#   Permission Manager -> vmax_is_dev / vmax_add_dev / vmax_remove_dev
#   Warehouse           -> vmax_dev_requisition_item / get_sandbox_inventory / clear_sandbox
#   Claim System        -> vmax_dev_death_drop / vmax_loot_dev_drop / list_nearby_drops
#   Audit Log           -> dev_sandbox_audit_log table / _dev_audit()  (already logs every action)
#   Loot Integration    -> vmax_get_real_loot_inventory (bridges claimed items into real loot)
#   Lobby Integration   -> vmax_lobby_menu() below: adds a "DEV ARMORY" button next to
#                          PLAY / INVENTORY / TEAM, visible only to developers
# =====================================================================

# Seed the developer UIDs requested for this build. Still fully overridable/extendable
# via the VMAX_DEV_UIDS env var at deploy time and vmax_add_dev()/vmax_remove_dev() at runtime.
for _armory_seed_uid in ("uid_001", "uid_002", "uid_003"):
    VMAX_DEV_UIDS.add(_armory_seed_uid)


def is_developer(uid):
    """Permission Manager entry point (canonical name for the Armory API)."""
    return vmax_is_dev(uid)


class VMAXDeveloperArmory:
    """Thin facade grouping the six Developer Armory subsystems behind one object,
    so callers (lobby UI, console commands, other services) have a single surface
    instead of reaching into the dev-sandbox internals directly."""

    # ---- Permission Manager ----
    is_developer = staticmethod(is_developer)
    add_developer = staticmethod(vmax_add_dev)
    remove_developer = staticmethod(vmax_remove_dev)

    # ---- Warehouse ----
    requisition = staticmethod(vmax_dev_requisition_item)
    inventory = staticmethod(vmax_dev_get_sandbox_inventory)
    clear = staticmethod(vmax_dev_clear_sandbox)

    # ---- Claim System ----
    death_drop = staticmethod(vmax_dev_death_drop)
    nearby_drops = staticmethod(vmax_dev_list_nearby_drops)
    claim = staticmethod(vmax_loot_dev_drop)

    # ---- Loot Integration ----
    real_loot_inventory = staticmethod(vmax_get_real_loot_inventory)

    # ---- Audit Log ----
    @staticmethod
    def audit_log(uid=None, limit=100):
        conn = _dev_db()
        try:
            if uid:
                rows = conn.execute(
                    "SELECT id, uid, action, detail, at FROM dev_sandbox_audit_log "
                    "WHERE uid=? ORDER BY id DESC LIMIT ?", (uid, int(limit))
                ).fetchall()
            else:
                rows = conn.execute(
                    "SELECT id, uid, action, detail, at FROM dev_sandbox_audit_log "
                    "ORDER BY id DESC LIMIT ?", (int(limit),)
                ).fetchall()
        finally:
            conn.close()
        return {"ok": True, "entries": [
            {"id": r[0], "uid": r[1], "action": r[2], "detail": r[3], "at": r[4]} for r in rows
        ]}

    # ---- Lobby Integration ----
    @staticmethod
    def lobby_menu(uid):
        return vmax_lobby_menu(uid)


def vmax_lobby_menu(uid):
    """Lobby Integration — buttons the lobby screen should render for this uid.
    Base buttons match every player's lobby (PLAY / INVENTORY / TEAM); the
    DEV ARMORY button is appended only for developers, following the same
    visible-before-render pattern as vmax_dev_menu_visible()."""
    buttons = ["PLAY", "INVENTORY", "TEAM"]
    dev = is_developer(uid)
    if dev:
        buttons.append("DEV ARMORY")
    return {"ok": True, "uid": uid, "buttons": buttons, "is_developer": dev}


VMAX_MODULES["developer_armory"] = {
    "name": "Developer Armory", "name_th": "คลังอาวุธนักพัฒนา",
    "version": "1.0", "category": "developer_tools", "genre": "all",
    "description": "ระบบรวม Developer Armory หกส่วน: Permission Manager (is_developer / add / remove), "
                    "Warehouse (คลังทดสอบแยกขาดจากของจริง), Claim System (ของร่วงเป็น loot ให้ผู้เล่นอื่นเก็บ), "
                    "Audit Log (บันทึกทุก action ของ dev), Loot Integration (เชื่อมของที่เก็บได้เข้าคลังจริง) "
                    "และ Lobby Integration (ปุ่ม DEV ARMORY โผล่ในล็อบบี้ข้าง PLAY / INVENTORY / TEAM เฉพาะ dev)",
    "routes": ["/api/dev-armory/lobby-menu", "/api/dev-armory/audit-log"],
}


@app.route('/api/dev-armory/lobby-menu', methods=['GET'])
@require_auth_toggleable
def api_dev_armory_lobby_menu():
    uid = str(getattr(request, "vmax_uid", None) or "")
    return jsonify(vmax_lobby_menu(uid))


@app.route('/api/dev-armory/audit-log', methods=['GET'])
@require_auth_toggleable
def api_dev_armory_audit_log():
    uid = str(getattr(request, "vmax_uid", None) or "")
    if not is_developer(uid):
        return jsonify({"ok": False, "reason": "not_authorized"}), 403
    target = request.args.get("target_uid")
    limit = request.args.get("limit", 100)
    return jsonify(VMAXDeveloperArmory.audit_log(target, limit))


def _run_developer_armory_selftest():
    dev_uid = "uid_001"                       # seeded developer
    normal_uid = "__armory_selftest_normal__"  # ordinary player

    # Permission Manager
    assert is_developer(dev_uid) is True
    assert is_developer(normal_uid) is False

    # Lobby Integration — DEV ARMORY button only shows for developers
    normal_menu = vmax_lobby_menu(normal_uid)
    assert normal_menu["buttons"] == ["PLAY", "INVENTORY", "TEAM"]
    dev_menu = vmax_lobby_menu(dev_uid)
    assert dev_menu["buttons"] == ["PLAY", "INVENTORY", "TEAM", "DEV ARMORY"]

    # Warehouse
    req = VMAXDeveloperArmory.requisition(dev_uid, "Armory_Selftest_Item", 2)
    assert req["ok"] and req["new_total"] == 2

    # Audit Log — the requisition above must already be recorded
    log = VMAXDeveloperArmory.audit_log(dev_uid, limit=5)
    assert log["ok"] and any(e["action"] == "requisition" for e in log["entries"])

    # cleanup (leave uid_001/002/003 seeded as developers)
    VMAXDeveloperArmory.clear(dev_uid, cleared_by=dev_uid)
    return True


if '--selftest-dev-armory' in sys.argv:
    ok = _run_developer_armory_selftest()
    print("dev-armory selftest:", "OK" if ok else "FAILED")
    sys.exit(0 if ok else 1)


# =====================================================================
# VMAX LUCKY MERCHANT — Mystery Cargo gacha ("พ่อค้าโชคดี" / กล่องสุ่ม)
# ---------------------------------------------------------------------
# ผู้เล่นจ่าย currency ในเกมเพื่อสุ่มเปิด Mystery Cargo แล้วได้ item คุณภาพสุ่มตาม weight
# (Mystery Cargo / Uncommon Mystery Cargo / Military Items / Computer Parts /
#  Uncommon Military Items / Rare Mystery Cargo / Collectibles) เหมือนในภาพตัวอย่าง
#
# ข้อกำหนดสำคัญที่ขอมา — "ฟังเสียงแล้วทายของได้ล่วงหน้าไม่ได้ ต้องลุ้นจริง":
# ปัญหาของระบบกล่องสุ่มแบบเดิมในหลายเกมคือ client เล่น sfx/จังหวะต่างกันไปตาม rarity
# *ก่อน* ที่แอนิเมชันจะเผยผลบนจอ ทำให้คนฟังเสียงเก่งเดา rarity ได้ก่อนเห็นจริง ระบบนี้ปิดช่องทาง
# นั้นตั้งแต่ฝั่ง server:
#   1. ผลลัพธ์ถูกสุ่มแบบ atomic ที่ server ตอนยืนยันซื้อจุดเดียว แล้วส่งผลจริงกลับไปพร้อมกันทีเดียว
#      ไม่มี endpoint แยกให้ "peek" ผลก่อนเปิดที่จะรั่วข้อมูลออกไปได้
#   2. ทุกผลลัพธ์ ไม่ว่าจะได้ของหายากแค่ไหน ใช้ reveal_sfx คำเดียวกันเป๊ะ ("cargo_open_generic")
#      — client ต้องเล่นเสียงนี้เสียงเดียวเสมอตอนเปิดกล่อง ห้ามผูก sfx คนละตัวกับแต่ละ rarity
#   3. reveal_delay_ms (ช่วงเวลาก่อนเผยผลบนจอ) สุ่มจากช่วงเดียวกันเสมอ ไม่ผูกกับ rarity ที่สุ่มได้
#      จริง จึงจับจังหวะ/ระยะเวลาไปเดาของล่วงหน้าไม่ได้เช่นกัน
# =====================================================================
import sqlite3 as _lm_sqlite3
import time as _lm_time
import threading as _lm_threading
import random as _lm_random
import os as _lm_os

VMAX_LUCKY_MERCHANT_DB_PATH = _lm_os.environ.get(
    "VMAX_LUCKY_MERCHANT_DB_PATH",
    _lm_os.path.join(_lm_os.path.dirname(_lm_os.path.abspath(__file__)), "vmax_lucky_merchant.sqlite3"),
)
VMAX_LUCKY_MERCHANT_LOCK = _lm_threading.Lock()

# reveal_sfx เดียวกันทุก rarity ตามข้อกำหนด — ห้ามมี sfx เฉพาะ tier ฝั่ง client เด็ดขาด


def _vmax_authenticated_owner_uid(body=None):
    """Return the identity established by authentication; never trust a client-supplied UID for owner actions."""
    auth_uid = getattr(request, "vmax_uid", None)
    if auth_uid:
        supplied = (body or {}).get("uid") if isinstance(body, dict) else None
        if supplied is not None and str(supplied) != str(auth_uid):
            raise PermissionError("uid_mismatch")
        return str(auth_uid)
    return resolve_uid(body or {}, required=True)

VMAX_LUCKY_MERCHANT_REVEAL_SFX = "cargo_open_generic"
VMAX_LUCKY_MERCHANT_REVEAL_DELAY_RANGE = (900, 1400)  # ms, สุ่มช่วงเดียวกันทุกผลลัพธ์

# ตาราง loot + weight (รวม weight = 100) อ้างอิงชื่อ tier จากภาพตัวอย่าง (Lucky Merchant)
VMAX_LUCKY_MERCHANT_TABLE = [
    {"rarity": "common",   "item": "Mystery Cargo",           "weight": 40, "value_min": 50000,   "value_max": 150000},
    {"rarity": "uncommon", "item": "Uncommon Mystery Cargo",  "weight": 22, "value_min": 150000,  "value_max": 350000},
    {"rarity": "uncommon", "item": "Military Items",          "weight": 15, "value_min": 200000,  "value_max": 400000},
    {"rarity": "uncommon", "item": "Computer Parts",          "weight": 10, "value_min": 250000,  "value_max": 450000},
    {"rarity": "uncommon", "item": "Uncommon Military Items", "weight": 6,  "value_min": 300000,  "value_max": 500000},
    {"rarity": "rare",     "item": "Rare Mystery Cargo",      "weight": 5,  "value_min": 600000,  "value_max": 1500000},
    {"rarity": "rare",     "item": "Collectibles",            "weight": 2,  "value_min": 1000000, "value_max": 3000000},
]


def _lm_db():
    conn = _lm_sqlite3.connect(VMAX_LUCKY_MERCHANT_DB_PATH, timeout=20, check_same_thread=False)
    conn.execute("""CREATE TABLE IF NOT EXISTS lucky_merchant_currency (
        uid TEXT PRIMARY KEY, balance INTEGER
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS lucky_merchant_inventory (
        uid TEXT, item TEXT, rarity TEXT, qty INTEGER, PRIMARY KEY (uid, item)
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS lucky_merchant_purchase_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT, uid TEXT, item TEXT, rarity TEXT,
        cost INTEGER, value INTEGER, at REAL
    )""")
    return conn


def vmax_lucky_merchant_odds():
    """ตารางอัตราสุ่ม (โปร่งใสให้ผู้เล่นดูได้) — นี่คือ 'อัตรา' เท่านั้น ไม่ใช่ผลจริง
    ไม่ทำให้ทายผลของรอบถัดไปได้ล่วงหน้าแต่อย่างใด"""
    total = sum(e["weight"] for e in VMAX_LUCKY_MERCHANT_TABLE)
    return {"ok": True, "odds": [
        {"item": e["item"], "rarity": e["rarity"], "chance_pct": round(e["weight"] * 100 / total, 2)}
        for e in VMAX_LUCKY_MERCHANT_TABLE
    ]}


def vmax_lucky_merchant_get_balance(uid):
    conn = _lm_db()
    try:
        row = conn.execute("SELECT balance FROM lucky_merchant_currency WHERE uid=?", (uid,)).fetchone()
    finally:
        conn.close()
    return int(row[0]) if row else 0


def vmax_lucky_merchant_grant_currency(uid, amount, granted_by=None):
    """เติม currency ให้ uid (ใช้โดย dev/ระบบเติมเงินจริงที่มีอยู่แล้ว ผูกเข้าจุดนี้จุดเดียว)"""
    if not uid:
        return {"ok": False, "reason": "uid_required"}
    try:
        amount = int(amount)
    except (TypeError, ValueError):
        return {"ok": False, "reason": "invalid_amount"}
    with VMAX_LUCKY_MERCHANT_LOCK:
        conn = _lm_db()
        try:
            row = conn.execute("SELECT balance FROM lucky_merchant_currency WHERE uid=?", (uid,)).fetchone()
            new_balance = (row[0] if row else 0) + amount
            conn.execute(
                "INSERT INTO lucky_merchant_currency (uid, balance) VALUES (?,?) "
                "ON CONFLICT(uid) DO UPDATE SET balance = ?", (uid, new_balance, new_balance))
            conn.commit()
        finally:
            conn.close()
    return {"ok": True, "uid": uid, "balance": new_balance}


def _vmax_lucky_merchant_roll():
    """สุ่มผลลัพธ์ 1 ครั้งแบบ atomic — เรียกเฉพาะตอนยืนยันซื้อภายใน vmax_lucky_merchant_purchase()
    เท่านั้น ห้ามมีจุดเรียกแยกที่ทำให้รู้ผลก่อนจ่ายเงินจริง"""
    total = sum(e["weight"] for e in VMAX_LUCKY_MERCHANT_TABLE)
    r = _lm_random.uniform(0, total)
    upto = 0.0
    for entry in VMAX_LUCKY_MERCHANT_TABLE:
        upto += entry["weight"]
        if r <= upto:
            value = _lm_random.randint(entry["value_min"], entry["value_max"])
            return entry["item"], entry["rarity"], value
    entry = VMAX_LUCKY_MERCHANT_TABLE[-1]
    return entry["item"], entry["rarity"], entry["value_max"]


def vmax_lucky_merchant_purchase(uid, cost=600000, qty=1):
    """ซื้อ Mystery Cargo qty ชิ้น หัก currency แล้วสุ่มผลทั้งหมดพร้อมกันในทีเดียว ส่งผลจริงกลับ
    ในคำตอบเดียวกัน (ไม่มี endpoint แยกให้ poll ผลก่อนเปิด) — ทุกผลลัพธ์ได้ reveal_sfx เดียวกัน
    และ reveal_delay_ms สุ่มจากช่วงเดียวกันเสมอ ไม่ว่าจะสุ่มได้ของหายากแค่ไหน"""
    if not uid:
        return {"ok": False, "reason": "uid_required"}
    try:
        qty = max(1, int(qty))
        cost = int(cost)
    except (TypeError, ValueError):
        return {"ok": False, "reason": "invalid_qty"}
    total_cost = cost * qty

    with VMAX_LUCKY_MERCHANT_LOCK:
        conn = _lm_db()
        try:
            row = conn.execute("SELECT balance FROM lucky_merchant_currency WHERE uid=?", (uid,)).fetchone()
            balance = row[0] if row else 0
            if balance < total_cost:
                return {"ok": False, "reason": "insufficient_funds", "balance": balance, "required": total_cost}

            results = []
            for _ in range(qty):
                item, rarity, value = _vmax_lucky_merchant_roll()
                conn.execute(
                    "INSERT INTO lucky_merchant_inventory (uid, item, rarity, qty) VALUES (?,?,?,1) "
                    "ON CONFLICT(uid, item) DO UPDATE SET qty = qty + 1", (uid, item, rarity))
                conn.execute(
                    "INSERT INTO lucky_merchant_purchase_log (uid, item, rarity, cost, value, at) "
                    "VALUES (?,?,?,?,?,?)", (uid, item, rarity, cost, value, _lm_time.time()))
                results.append({
                    "item": item, "rarity": rarity, "value": value,
                    "reveal_sfx": VMAX_LUCKY_MERCHANT_REVEAL_SFX,
                    "reveal_delay_ms": _lm_random.randint(*VMAX_LUCKY_MERCHANT_REVEAL_DELAY_RANGE),
                })

            new_balance = balance - total_cost
            conn.execute(
                "INSERT INTO lucky_merchant_currency (uid, balance) VALUES (?,?) "
                "ON CONFLICT(uid) DO UPDATE SET balance = ?", (uid, new_balance, new_balance))
            conn.commit()
        finally:
            conn.close()

    return {"ok": True, "uid": uid, "qty": qty, "cost_each": cost, "total_cost": total_cost,
            "new_balance": new_balance, "results": results}


def vmax_lucky_merchant_inventory(uid):
    conn = _lm_db()
    try:
        rows = conn.execute("SELECT item, rarity, qty FROM lucky_merchant_inventory WHERE uid=? AND qty>0",
                             (uid,)).fetchall()
    finally:
        conn.close()
    return {"ok": True, "uid": uid, "items": [
        {"item": r[0], "rarity": r[1], "qty": r[2]} for r in rows
    ]}


VMAX_MODULES["lucky_merchant"] = {
    "name": "Lucky Merchant", "name_th": "พ่อค้าโชคดี (กล่องสุ่ม Mystery Cargo)",
    "version": "1.0", "category": "economy", "genre": "shooter_looter",
    "description": "ระบบกล่องสุ่ม Mystery Cargo แบบในภาพตัวอย่าง — จ่าย currency สุ่มเปิดได้ item "
                    "คุณภาพสุ่ม (Common ไป Collectibles หายากสุด) ผลสุ่ม atomic ที่ server จุดเดียว "
                    "ตอนยืนยันซื้อ ไม่มี endpoint ให้ peek ก่อนจ่าย ทุกผลลัพธ์ใช้ reveal_sfx เดียวกัน "
                    "และ reveal_delay_ms สุ่มช่วงเดียวกันเสมอ ป้องกันการฟังเสียง/จับจังหวะทายของก่อนเห็นจริง",
    "routes": ["/api/lucky-merchant/odds", "/api/lucky-merchant/balance",
               "/api/lucky-merchant/purchase", "/api/lucky-merchant/inventory",
               "/api/lucky-merchant/grant-currency"],
}


@app.route('/api/lucky-merchant/odds', methods=['GET'])
@require_auth_toggleable
def api_lucky_merchant_odds():
    return jsonify(vmax_lucky_merchant_odds())


@app.route('/api/lucky-merchant/balance', methods=['GET'])
@require_auth_toggleable
def api_lucky_merchant_balance():
    uid = str(getattr(request, "vmax_uid", None) or "")
    if not uid:
        return jsonify({"ok": False, "reason": "uid_required"}), 401
    return jsonify({"ok": True, "uid": uid, "balance": vmax_lucky_merchant_get_balance(uid)})


@app.route('/api/lucky-merchant/purchase', methods=['POST'])
@require_auth
def api_lucky_merchant_purchase():
    body = request.get_json(silent=True) or {}
    uid = _vmax_authenticated_owner_uid(body)
    if not uid:
        return jsonify({"ok": False, "reason": "uid_required"}), 401
    return jsonify(vmax_lucky_merchant_purchase(
        uid, body.get("cost", 600000), body.get("qty", 1)))


@app.route('/api/lucky-merchant/inventory', methods=['GET'])
@require_auth_toggleable
def api_lucky_merchant_inventory():
    uid = str(getattr(request, "vmax_uid", None) or "")
    if not uid:
        return jsonify({"ok": False, "reason": "uid_required"}), 401
    return jsonify(vmax_lucky_merchant_inventory(uid))


@app.route('/api/lucky-merchant/grant-currency', methods=['POST'])
@require_auth
def api_lucky_merchant_grant_currency():
    """สำหรับเดฟ/ระบบเติมเงินจริงเชื่อมเข้ามาเติม currency ให้ uid — ไม่ใช่ปุ่มให้ผู้เล่นกดเอง"""
    body = request.get_json(silent=True) or {}
    granter = resolve_uid(body) or "system"
    if not is_developer(granter) and granter != "system":
        return jsonify({"ok": False, "reason": "not_authorized"}), 403
    target_uid = body.get("target_uid") or body.get("uid")
    return jsonify(vmax_lucky_merchant_grant_currency(target_uid, body.get("amount", 0), granter))


def _run_lucky_merchant_selftest():
    uid = "__lucky_merchant_selftest__"

    # เริ่มจากยอด 0 ซื้อไม่ได้
    poor = vmax_lucky_merchant_purchase(uid, cost=600000, qty=1)
    assert not poor["ok"] and poor["reason"] == "insufficient_funds"

    # เติมเงินแล้วซื้อได้
    grant = vmax_lucky_merchant_grant_currency(uid, 6000000)
    assert grant["ok"] and grant["balance"] == 6000000

    purchase = vmax_lucky_merchant_purchase(uid, cost=600000, qty=5)
    assert purchase["ok"]
    assert purchase["new_balance"] == 6000000 - 600000 * 5
    assert len(purchase["results"]) == 5

    # ข้อกำหนดสำคัญ: reveal_sfx ต้องเหมือนกันทุกผลลัพธ์ (ทายจากเสียงไม่ได้)
    sfx_set = {r["reveal_sfx"] for r in purchase["results"]}
    assert sfx_set == {VMAX_LUCKY_MERCHANT_REVEAL_SFX}

    # reveal_delay_ms ต้องอยู่ในช่วงเดียวกันเสมอ ไม่ผูกกับ rarity
    lo, hi = VMAX_LUCKY_MERCHANT_REVEAL_DELAY_RANGE
    assert all(lo <= r["reveal_delay_ms"] <= hi for r in purchase["results"])

    # ของที่ได้ต้องเข้าคลังจริงของ uid
    inv = vmax_lucky_merchant_inventory(uid)
    assert inv["ok"] and sum(i["qty"] for i in inv["items"]) == 5

    # ตาราง odds รวมกันต้องเท่ากับ 100%
    odds = vmax_lucky_merchant_odds()
    assert odds["ok"] and abs(sum(o["chance_pct"] for o in odds["odds"]) - 100.0) < 0.01

    # cleanup
    conn = _lm_db()
    try:
        conn.execute("DELETE FROM lucky_merchant_currency WHERE uid=?", (uid,))
        conn.execute("DELETE FROM lucky_merchant_inventory WHERE uid=?", (uid,))
        conn.execute("DELETE FROM lucky_merchant_purchase_log WHERE uid=?", (uid,))
        conn.commit()
    finally:
        conn.close()
    return True


if '--selftest-lucky-merchant' in sys.argv:
    ok = _run_lucky_merchant_selftest()
    print("lucky-merchant selftest:", "OK" if ok else "FAILED")
    sys.exit(0 if ok else 1)


