def _vmax_retro_engine_path(engine_id):
    return _re_os.path.join(VMAX_RETRO_ENGINE_DIR, engine_id)


def vmax_retro_engine_list():
    """Lobby/launcher เรียกอันนี้เพื่อโชว์รายการเอนจิ้นที่เชื่อมไว้ พร้อมสถานะติดตั้งของแต่ละตัว"""
    out = []
    for eid, meta in VMAX_RETRO_ENGINES.items():
        out.append({
            "id": eid, "name": meta["name"], "genre": meta["genre"],
            "license": meta["license"], "note": meta["note"],
            "installed": vmax_retro_engine_is_installed(eid),
        })
    return {"ok": True, "engines": out}


def vmax_retro_engine_is_installed(engine_id):
    meta = VMAX_RETRO_ENGINES.get(engine_id)
    if not meta:
        return False
    # เช็คสองทาง: (1) build ไว้ในโฟลเดอร์ retro_engines/<id>/ แล้ว หรือ (2) มี binary อยู่ใน PATH อยู่แล้ว
    local_bin = _re_os.path.join(_vmax_retro_engine_path(engine_id), meta["binary"])
    return _re_os.path.isfile(local_bin) or _re_shutil.which(meta["binary"]) is not None


def vmax_retro_engine_install(engine_id):
    """Clone + build เอนจิ้นที่ระบุจาก repo ทางการของโปรเจกต์นั้นๆ ต้องมีอินเทอร์เน็ตและ
    เครื่องมือ build ของภาษานั้น (go/cmake/cargo) ติดตั้งไว้ก่อนแล้วบนเครื่อง"""
    if _re_os.environ.get("VMAX_RETRO_ENGINE_AUTO_INSTALL", "1") != "1":
        return {"ok": False, "reason": "auto_install_disabled"}
    meta = VMAX_RETRO_ENGINES.get(engine_id)
    if not meta:
        return {"ok": False, "reason": "unknown_engine"}
    if vmax_retro_engine_is_installed(engine_id):
        return {"ok": True, "engine": engine_id, "already_installed": True}

    dest = _vmax_retro_engine_path(engine_id)
    _re_os.makedirs(VMAX_RETRO_ENGINE_DIR, exist_ok=True)
    try:
        if not _re_os.path.isdir(dest):
            _re_subprocess.check_call(["git", "clone", "--depth", "1", meta["repo"], dest])
        for cmd in meta["build_cmds"]:
            _re_subprocess.check_call(cmd, cwd=dest)
    except (OSError, _re_subprocess.CalledProcessError) as exc:
        return {"ok": False, "reason": "install_failed", "detail": str(exc)}
    return {"ok": True, "engine": engine_id, "path": dest,
            "installed": vmax_retro_engine_is_installed(engine_id)}


def vmax_retro_engine_launch(engine_id, project_path=None, extra_args=None):
    """เปิดเอนจิ้นที่ติดตั้งไว้แล้ว (ไม่บล็อกโปรเซสหลัก) โดยส่ง project_path เป็นอาร์กิวเมนต์แรก
    ถ้ามี — ใช้เปิดโปรเจกต์เกมเรโทรของผู้เล่น/ผู้พัฒนาเอง"""
    meta = VMAX_RETRO_ENGINES.get(engine_id)
    if not meta:
        return {"ok": False, "reason": "unknown_engine"}
    if not vmax_retro_engine_is_installed(engine_id):
        return {"ok": False, "reason": "not_installed"}

    local_bin = _re_os.path.join(_vmax_retro_engine_path(engine_id), meta["binary"])
    exe = local_bin if _re_os.path.isfile(local_bin) else _re_shutil.which(meta["binary"])
    cmd = [exe] + ([project_path] if project_path else []) + list(extra_args or [])
    try:
        proc = _re_subprocess.Popen(cmd)
    except OSError as exc:
        return {"ok": False, "reason": "launch_failed", "detail": str(exc)}
    return {"ok": True, "engine": engine_id, "pid": proc.pid}


