@app.route('/api/retro-engines', methods=['GET'])
@require_auth_toggleable
def api_retro_engine_list():
    return jsonify(vmax_retro_engine_list())


@app.route('/api/retro-engines/<engine_id>/install', methods=['POST'])
@require_auth_toggleable
def api_retro_engine_install(engine_id):
    body = request.get_json(silent=True) or {}
    uid = resolve_uid(body) or "system"
    if not is_developer(uid) and uid != "system":
        return jsonify({"ok": False, "reason": "not_authorized"}), 403
    return jsonify(vmax_retro_engine_install(engine_id))


@app.route('/api/retro-engines/<engine_id>/launch', methods=['POST'])
@require_auth_toggleable
def api_retro_engine_launch(engine_id):
    body = request.get_json(silent=True) or {}
    uid = str(getattr(request, "vmax_uid", None) or "")
    if not is_developer(uid):
        return jsonify({"ok": False, "reason": "not_authorized"}), 403
    project_path = body.get("project_path")
    if project_path:
        root = _re_os.path.realpath(_vmax_retro_engine_path(engine_id))
        candidate = _re_os.path.realpath(project_path)
        if candidate != root and not candidate.startswith(root + _re_os.sep):
            return jsonify({"ok": False, "reason": "project_path_not_allowed"}), 403
    extra_args = body.get("extra_args") or []
    if not isinstance(extra_args, list) or any(not isinstance(x, str) or len(x) > 256 for x in extra_args):
        return jsonify({"ok": False, "reason": "invalid_extra_args"}), 400
    return jsonify(vmax_retro_engine_launch(engine_id, project_path, extra_args))


def _run_retro_engine_bridge_selftest():
    # ตรวจ registry ครบ 5 ตัวตามที่คุยกัน แต่ละตัวมีคีย์ที่จำเป็นครบ
    assert set(VMAX_RETRO_ENGINES.keys()) == {
        "ikemen_go", "easyrpg_player", "solarus", "renpy", "ruffle", "openttd"
    }
    for eid, meta in VMAX_RETRO_ENGINES.items():
        for key in ("name", "genre", "license", "repo", "build_cmds", "binary", "note"):
            assert key in meta, f"{eid} missing {key}"
        # is_installed ต้องไม่ error แม้ยังไม่เคย clone (เครื่องทดสอบนี้ไม่มีอินเทอร์เน็ต)
        assert isinstance(vmax_retro_engine_is_installed(eid), bool)

    listing = vmax_retro_engine_list()
    assert listing["ok"] and len(listing["engines"]) == 5

    # เอนจิ้นที่ยังไม่ติดตั้ง ต้อง launch ไม่ได้ (กัน error แทนที่จะ crash)
    launch = vmax_retro_engine_launch("solarus", project_path="/tmp/does-not-exist")
    assert not launch["ok"] and launch["reason"] in ("not_installed", "unknown_engine")

    # engine id ที่ไม่มีจริงต้องตอบ unknown_engine ทั้งสองฟังก์ชัน
    bad = vmax_retro_engine_install("not_a_real_engine")
    assert not bad["ok"] and bad["reason"] == "unknown_engine"
    return True


if '--selftest-retro-engine-bridge' in sys.argv:
    ok = _run_retro_engine_bridge_selftest()
    print("retro-engine-bridge selftest:", "OK" if ok else "FAILED")
    sys.exit(0 if ok else 1)


