def _vmax_retro_ai_node_id(engine_id):
    return f"retro::{engine_id}"


def vmax_retro_engine_ai_register(engine_id):
    """ลงทะเบียน (หรือ heartbeat ถ้ามีอยู่แล้ว) AI node ของเอนจิ้นนี้เข้า AI Mesh กลาง"""
    meta = VMAX_RETRO_ENGINES.get(engine_id)
    role = VMAX_RETRO_ENGINE_AI_ROLE.get(engine_id)
    if not meta or not role:
        return {"ok": False, "reason": "unknown_engine"}
    node = _ai_mesh_register(
        _vmax_retro_ai_node_id(engine_id), "engine", f"{meta['name']} {role['role']}",
        [role["role"]], {"engine": engine_id, "genre": meta["genre"], "brief": role["brief"]},
    )
    return {"ok": True, "node": node}


def vmax_retro_engine_ai_ask(engine_id, question, context=None):
    """ถาม AI ที่ผูกกับเอนจิ้นนี้โดยเฉพาะ ผ่าน AI Mesh กลางตัวเดิมในไฟล์ — แนบบทบาท/บริบทของ
    เอนจิ้นเข้าไปใน context ให้ AI เห็นว่ากำลังช่วยเรื่องอะไรอยู่"""
    role = VMAX_RETRO_ENGINE_AI_ROLE.get(engine_id)
    if not role:
        return {"ok": False, "reason": "unknown_engine"}
    vmax_retro_engine_ai_register(engine_id)  # เผื่อยังไม่เคย register หรือ heartbeat ให้ online
    merged_context = dict(context or {})
    merged_context.setdefault("engine", engine_id)
    merged_context.setdefault("engine_role", role["role"])
    merged_context.setdefault("engine_brief", role["brief"])
    return _ai_mesh_ask(question, _vmax_retro_ai_node_id(engine_id), "global", None, None, merged_context)


