@app.route('/api/vault-relay/report-breach', methods=['POST'])
@require_auth_toggleable
def api_vault_relay_report_breach():
    """เฉพาะ dev/ระบบเฝ้าระวัง (IDS ของจริง) เท่านั้นที่ควรยิงมาที่ endpoint นี้"""
    body = request.get_json(silent=True) or {}
    uid = resolve_uid(body) or "system"
    if not is_developer(uid):
        return jsonify({"ok": False, "reason": "not_authorized"}), 403
    return jsonify(vmax_relay_report_breach(body.get("relay_id", ""), body.get("reason", "manual_report")))


@app.route('/api/vault-relay/sync', methods=['POST'])
@require_auth_toggleable
def api_vault_relay_sync():
    body = request.get_json(silent=True) or {}
    uid = resolve_uid(body) or "system"
    if not is_developer(uid):
        return jsonify({"ok": False, "reason": "not_authorized"}), 403
    return jsonify(vmax_relay_sync_all())


# เปิดเครื่อง — สร้างพูล relay เริ่มต้นไว้ล่วงหน้าตามจำนวนที่ตั้งไว้ (ค่าเริ่มต้น 3 ใบ) แล้ว sync
# ข้อมูลที่มีอยู่ใน vault (ถ้ามี) เข้าไปทันที ระบบจะพร้อมให้บริการตั้งแต่เปิดเซิร์ฟเวอร์
with VMAX_VAULT_LOCK:
    _vmax_relay_existing = len(VMAX_RELAY_ACTIVE_POOL)
for _ in range(max(0, VMAX_RELAY_COUNT_DEFAULT - _vmax_relay_existing)):
    vmax_relay_create()
vmax_relay_sync_all()


def _run_core_vault_relay_mesh_selftest():
    test_key = "__vault_selftest_key__"
    vmax_vault_set(test_key, {"hello": "world"}, actor="selftest")
    sync = vmax_relay_sync_all()
    assert sync["ok"] and sync["keys"] >= 1

    # ต้องอ่านผ่าน relay ได้ (ไม่ใช่จาก vault ตรงๆ)
    read = vmax_relay_read(test_key)
    assert read["ok"] and read["value"] == {"hello": "world"}
    original_relay = read["relay_id"]

    status_before = vmax_relay_status()
    assert status_before["ok"] and status_before["active_count"] >= 1

    # จำลอง breach ที่ relay ตัวที่กำลังให้บริการอยู่
    breach = vmax_relay_report_breach(original_relay, "selftest_breach")
    assert breach["ok"] and breach["quarantined"] == original_relay
    assert original_relay not in VMAX_RELAY_ACTIVE_POOL   # ต้องถูกตัดออกจาก pool ทันที
    assert original_relay not in VMAX_RELAY_REGISTRY       # ต้องถูกลบทิ้งจริง ไม่ใช่แค่ทำเครื่องหมาย

    # ต้อง failover ไป relay ใหม่ได้ และยังอ่านข้อมูลเดิมได้ครบ (sync ใหม่จาก vault สำเร็จ)
    assert breach["failover_to"] is not None
    read_after = vmax_relay_read(test_key)
    assert read_after["ok"] and read_after["value"] == {"hello": "world"}
    assert read_after["relay_id"] != original_relay

    # จำนวน relay healthy ต้องกลับมาครบตามเป้าหมายเดิม (สร้างลังทดแทนอัตโนมัติ)
    status_after = vmax_relay_status()
    assert status_after["active_count"] >= VMAX_RELAY_COUNT_DEFAULT

    # relay/key ที่ไม่มีจริงต้องตอบ error แบบสุภาพ ไม่ crash
    assert not vmax_relay_heartbeat("__no_such_relay__")["ok"]
    assert vmax_relay_read("__no_such_key__")["reason"] == "key_not_found"

    # cleanup: ลบ key ทดสอบออกจาก vault
    conn = _vault_db()
    try:
        conn.execute("DELETE FROM vault_kv WHERE key=?", (test_key,))
        conn.commit()
    finally:
        conn.close()
    return True


if '--selftest-core-vault-relay-mesh' in sys.argv:
    ok = _run_core_vault_relay_mesh_selftest()
    print("core-vault-relay-mesh selftest:", "OK" if ok else "FAILED")
    sys.exit(0 if ok else 1)


if '--selftest-dev-sandbox' in sys.argv:
    ok = _run_dev_sandbox_selftest()
    sys.exit(0 if ok else 1)


# =====================================================================
# VMAX SITE-SCOPED VAULT NAMESPACE + LOCAL MCP TOGGLE CONSOLE
# ----------------------------------------------------------------------
# ส่วนที่ 1) แยกข้อมูลที่ vault เก็บออกเป็น "รายเว็บไซต์" (site_id / domain)
#    ของแต่ละเว็บจะไม่ปนกัน อ่านผ่าน relay ได้เฉพาะ site ที่ระบุเท่านั้น
#
# ส่วนที่ 2) คอนโซล MCP แบบสลับได้ในเครื่องเดียว — รันเป็นโปรแกรม cmd ตัวเดียว
#    พิมพ์คำสั่งภาษาไทย/อังกฤษเพื่อสลับสถานะ:
#      เปิด / start   -> เครื่องเปิดเซิร์ฟเวอร์ MCP ในเครื่อง (local only, 127.0.0.1)
#                        ให้ AI/โปรแกรมอื่นต่อเข้ามาอ่าน-เขียนข้อมูลที่ scrape มาได้
#      ปิด / stop     -> ปิดเซิร์ฟเวอร์ MCP ทันที กลับไปเป็นคอมพิวเตอร์ใช้งานปกติ
#      สถานะ / status -> ดูว่าตอนนี้เปิดหรือปิดอยู่ พอร์ตอะไร มีกี่ไซต์ในฐานข้อมูล
#      ออก / exit     -> ปิดเซิร์ฟเวอร์ (ถ้าเปิดอยู่) แล้วออกจากโปรแกรม
#    เซิร์ฟเวอร์ MCP ผูกกับ 127.0.0.1 เท่านั้น (ไม่เปิดออกอินเทอร์เน็ต) และเขียน/อ่าน
#    ผ่าน relay ชั้นเดียวกับระบบเดิม ไม่มีทางแตะ CORE VAULT ตรงๆ
# =====================================================================

import sys as _vmc_sys
import threading as _vmc_threading
import http.server as _vmc_http
import socketserver as _vmc_socketserver
import urllib.parse as _vmc_urlparse
import json as _vmc_json
import secrets as _vmc_secrets
import hmac as _vmc_hmac
import time as _vmc_time


def _vmax_site_key(site_id, key):
    """ประกอบ key ภายในให้ผูกกับ site_id เพื่อกันข้อมูลปนกันข้ามเว็บ"""
    site_id = (site_id or "unscoped").strip().lower()
    return f"site::{site_id}::{key}"


def vmax_vault_set_site(site_id, key, value, actor="mcp_console"):
    """บันทึกข้อมูลที่ scrape มาจากเว็บไซต์หนึ่งๆ ลง vault แบบแยก namespace ตาม site_id"""
    return vmax_vault_set(_vmax_site_key(site_id, key), value, actor=actor)


def vmax_relay_read_site(site_id, key):
    """อ่านข้อมูลของเว็บไซต์หนึ่งๆ ผ่าน relay (read-only เหมือนเดิม) — ไม่ข้ามไซต์กัน"""
    return vmax_relay_read(_vmax_site_key(site_id, key))


def vmax_vault_list_sites():
    """ไล่ดู key ทั้งหมดใน vault แล้วสรุปว่ามีกี่ site_id ต่างกัน"""
    conn = _vault_db()
    try:
        rows = conn.execute("SELECT key FROM vault_kv").fetchall()
    finally:
        conn.close()
    sites = {}
    for (k,) in rows:
        if k.startswith("site::"):
            parts = k.split("::", 2)
            if len(parts) == 3:
                sites.setdefault(parts[1], 0)
                sites[parts[1]] += 1
    return sites


VMAX_MODULES["site_scoped_vault"] = {
    "name": "Site-Scoped Vault Namespace", "name_th": "แยกข้อมูล vault ตามรายเว็บไซต์",
    "version": "1.0", "category": "infrastructure", "genre": "all",
    "description": "ห่อ key ของ vault ด้วย site_id ก่อนเก็บ/อ่าน เพื่อไม่ให้ข้อมูลที่ AI เก็บจากคนละเว็บไซต์ปนกัน "
                    "อ่านผ่าน relay ตามช่องทางเดิมทุกอย่าง ไม่มี route ใหม่ที่แตะ CORE VAULT ตรงๆ",
}


# --- สถานะ MCP console (สลับ เปิด/ปิด) -----------------------------------
VMAX_MCP_LOCK = _v12_threading.Lock()
VMAX_MCP_STATE = {"running": False, "port": None, "httpd": None, "thread": None, "token": None}
VMAX_MCP_DEFAULT_PORT = 8765

# --- กันบรุตฟอร์ซ token: ผิดติดกันเกินกำหนดจาก IP เดียวกัน -> ล็อกชั่วคราว ---
VMAX_MCP_MAX_ATTEMPTS = 5
VMAX_MCP_LOCKOUT_SECONDS = 60
VMAX_MCP_FAILED_ATTEMPTS = {}   # {ip: [timestamp, ...]}
VMAX_MCP_FAIL_LOCK = _v12_threading.Lock()


def _vmax_mcp_ip_locked_out(ip):
    now = _vmc_time.time()
    with VMAX_MCP_FAIL_LOCK:
        attempts = [t for t in VMAX_MCP_FAILED_ATTEMPTS.get(ip, []) if now - t < VMAX_MCP_LOCKOUT_SECONDS]
        VMAX_MCP_FAILED_ATTEMPTS[ip] = attempts
        return len(attempts) >= VMAX_MCP_MAX_ATTEMPTS


def _vmax_mcp_record_failure(ip):
    with VMAX_MCP_FAIL_LOCK:
        VMAX_MCP_FAILED_ATTEMPTS.setdefault(ip, []).append(_vmc_time.time())


class _VMAXMCPHandler(_vmc_http.BaseHTTPRequestHandler):
    """เซิร์ฟเวอร์ MCP เล็กๆ ที่ผูกกับ localhost เท่านั้น — คุยผ่าน relay (read-only) เสมอ
    ต้องแนบ header  X-VMAX-Token: <token>  ทุก request (token สุ่มใหม่ทุกครั้งที่เปิดโหมด MCP)
    /mcp/read?site=...&key=...   (GET)  อ่านข้อมูล
    /mcp/write                   (POST) {"site":..., "key":..., "value":...} เขียนลง vault"""

    def log_message(self, fmt, *args):
        return  # เงียบ ไม่ spam log ลง console หลัก

    def _send(self, code, obj):
        body = _vmc_json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _authorized(self):
        """เทียบ token แบบ constant-time + ล็อก IP ที่ยิง token ผิดถี่เกินไป กัน brute force"""
        ip = self.client_address[0]
        if _vmax_mcp_ip_locked_out(ip):
            return False, self._send(429, {"ok": False, "reason": "too_many_failed_attempts",
                                            "retry_after_seconds": VMAX_MCP_LOCKOUT_SECONDS})
        with VMAX_MCP_LOCK:
            expected = VMAX_MCP_STATE.get("token")
        supplied = self.headers.get("X-VMAX-Token", "")
        if not expected or not _vmc_hmac.compare_digest(str(expected), str(supplied)):
            _vmax_mcp_record_failure(ip)
            return False, self._send(401, {"ok": False, "reason": "unauthorized"})
        return True, None

    def do_GET(self):
        parsed = _vmc_urlparse.urlparse(self.path)
        if parsed.path.startswith("/mcp/ops/"):
            ok, _ = self._authorized()
            if not ok:
                return
            code, obj = vmax_ops_http("GET", parsed.path, _vmc_urlparse.parse_qs(parsed.query), None)
            return self._send(code, obj)
        if parsed.path != "/mcp/read":
            return self._send(404, {"ok": False, "reason": "not_found"})
        ok, _ = self._authorized()
        if not ok:
            return
        qs = _vmc_urlparse.parse_qs(parsed.query)
        site = (qs.get("site") or [""])[0]
        key = (qs.get("key") or [""])[0]
        if not key:
            return self._send(400, {"ok": False, "reason": "key_required"})
        return self._send(200, vmax_relay_read_site(site, key))

    def do_POST(self):
        parsed = _vmc_urlparse.urlparse(self.path)
        if parsed.path.startswith("/mcp/ops/"):
            ok, _ = self._authorized()
            if not ok:
                return
            length = int(self.headers.get("Content-Length", 0) or 0)
            if length > 65536:
                return self._send(413, {"ok": False, "reason": "body_too_large"})
            try:
                body = _vmc_json.loads(self.rfile.read(length) or b"{}")
            except Exception:
                return self._send(400, {"ok": False, "reason": "bad_json"})
            code, obj = vmax_ops_http("POST", parsed.path, {}, body)
            return self._send(code, obj)
        if parsed.path != "/mcp/write":
            return self._send(404, {"ok": False, "reason": "not_found"})
        ok, _ = self._authorized()
        if not ok:
            return
        length = int(self.headers.get("Content-Length", 0) or 0)
        try:
            body = _vmc_json.loads(self.rfile.read(length) or b"{}")
        except Exception:
            return self._send(400, {"ok": False, "reason": "bad_json"})
        site, key, value = body.get("site", ""), body.get("key"), body.get("value")
        if not key:
            return self._send(400, {"ok": False, "reason": "key_required"})
        result = vmax_vault_set_site(site, key, value, actor="mcp_remote")
        vmax_relay_sync_all()
        return self._send(200, result)


class _VMAXMCPServer(_vmc_socketserver.ThreadingTCPServer):
    """เซิร์ฟเวอร์ MCP ผูก 127.0.0.1 เท่านั้น
    - Linux/macOS: เปิด allow_reuse_address ให้ stop แล้ว start พอร์ตเดิมได้ทันที
    - Windows: SO_REUSEADDR เปิดช่องให้โปรเซสอื่นเปิดพอร์ตเดียวกันซ้อนได้ จึงไม่ใช้
      แต่ล็อกพอร์ตแบบ exclusive (SO_EXCLUSIVEADDRUSE) แทน — โปรเซสอื่นแย่ง/แชร์พอร์ตไม่ได้"""
    _IS_WINDOWS = _vmc_sys.platform.startswith("win")
    allow_reuse_address = not _IS_WINDOWS
    daemon_threads = True

    def server_bind(self):
        if self._IS_WINDOWS:
            import socket as _vmc_socket
            try:
                self.socket.setsockopt(_vmc_socket.SOL_SOCKET, _vmc_socket.SO_EXCLUSIVEADDRUSE, 1)
            except (AttributeError, OSError):
                pass
        super().server_bind()


def _vmax_mcp_bind_with_retry(port, attempts=6, delay=0.3):
    """สร้างเซิร์ฟเวอร์ โดยลองใหม่สั้นๆ ถ้าพอร์ตเพิ่งถูกปล่อยจาก stop ครั้งก่อน"""
    last_err = None
    for _ in range(attempts):
        try:
            return _VMAXMCPServer(("127.0.0.1", port), _VMAXMCPHandler)
        except OSError as e:
            last_err = e
            _vmc_time.sleep(delay)
    raise last_err


def vmax_mcp_start(port=None):
    """สลับเครื่องเข้าโหมด MCP — เปิดเซิร์ฟเวอร์เก็บ/อ่านข้อมูลเว็บไซต์บน 127.0.0.1 เท่านั้น
    สุ่ม token ใหม่ทุกครั้งที่เปิด — ต้องแนบ header X-VMAX-Token ถึงจะเรียก /mcp/read, /mcp/write ได้"""
    with VMAX_MCP_LOCK:
        if VMAX_MCP_STATE["running"]:
            return {"ok": False, "reason": "already_running", "port": VMAX_MCP_STATE["port"]}
        port = int(port or VMAX_MCP_DEFAULT_PORT)
        token = _vmc_secrets.token_urlsafe(32)
        httpd = _vmax_mcp_bind_with_retry(port)
        thread = _vmc_threading.Thread(target=httpd.serve_forever, daemon=True)
        thread.start()
        VMAX_MCP_STATE.update({"running": True, "port": port, "httpd": httpd, "thread": thread, "token": token})
    return {"ok": True, "port": port, "token": token,
            "read": f"http://127.0.0.1:{port}/mcp/read?site=SITE&key=KEY  (header X-VMAX-Token: {token})",
            "write": f"http://127.0.0.1:{port}/mcp/write (POST JSON: site,key,value; header X-VMAX-Token: {token})"}


def vmax_mcp_stop():
    """สลับกลับเป็นคอมพิวเตอร์ใช้งานปกติ — ปิดเซิร์ฟเวอร์ MCP ทันที และทิ้ง token เดิม (ใช้ต่อไม่ได้อีก)"""
    with VMAX_MCP_LOCK:
        if not VMAX_MCP_STATE["running"]:
            return {"ok": False, "reason": "not_running"}
        httpd = VMAX_MCP_STATE["httpd"]
    httpd.shutdown()
    httpd.server_close()
    with VMAX_MCP_LOCK:
        VMAX_MCP_STATE.update({"running": False, "port": None, "httpd": None, "thread": None, "token": None})
    return {"ok": True}


def vmax_mcp_status():
    with VMAX_MCP_LOCK:
        running, port = VMAX_MCP_STATE["running"], VMAX_MCP_STATE["port"]
    return {"ok": True, "running": running, "port": port, "sites": vmax_vault_list_sites()}


_VMAX_MCP_COMMANDS_ON = {"เปิด", "start", "on", "เริ่ม"}
_VMAX_MCP_COMMANDS_OFF = {"ปิด", "stop", "off", "หยุด", "ปกติ"}
