# =====================================================================
# VMAX OPS AGENT — เอเจนต์ดูแลระบบตู้ MC ต่อจาก MCP console
# ----------------------------------------------------------------------
# หน้าที่: เก็บสถิติ "ตัวเลข/สถานะล้วนๆ" จากระบบเดิม (audit log, vault, relay,
#   MCP console, watchdog thread, เกม/รายงานโกง) -> ตรวจกฎแจ้งเตือน -> สรุปรายงานเป็นภาษาไทย
#   ใช้ได้ 3 ทาง:
#     1) คอนโซล:   ops-run / ops-status / ops-alerts / ops-report / ops-start [วินาที] / ops-stop
#                  ops-config / ops-set <ชื่อ> <ค่า>   (มีคำไทย: ตรวจระบบ / สถานะระบบ / แจ้งเตือน / รายงานระบบ)
#     2) MCP API (127.0.0.1 + X-VMAX-Token เท่านั้น):
#          GET  /mcp/ops/status | /mcp/ops/report | /mcp/ops/alerts?limit=N | /mcp/ops/history?limit=N | /mcp/ops/config
#          POST /mcp/ops/run    | /mcp/ops/config {"name":..., "value":...}
#     3) อ่านย้อนหลังผ่าน relay:  /mcp/read?site=ops_agent&key=last_report (หรือ last_snapshot)
#
#   หลักความปลอดภัย (สำคัญ):
#     - Ops Agent "อ่านอย่างเดียว" จากระบบเดิม ไม่แก้ผู้เล่น/เงิน/แบน/กุญแจ ไม่แตะ CORE VAULT ตรงๆ
#       สิ่งเดียวที่เขียนคือรายงานของตัวเองลง namespace site=ops_agent ผ่าน vault API เดิม
#     - snapshot ใช้ whitelist ฟิลด์ (ตัวเลข/บูลีนเท่านั้น) ไม่ดึง token, key_dir, base64 ของกุญแจ,
#       รหัสผ่าน, uid/ip รายตัว, ยอดเงินผู้เล่น ออกมาเลย
#     - ก่อนเก็บ/ส่งออกทุกครั้งจะผ่าน _vmax_ops_sanitize อีกชั้น (ตัด key ที่ชื่อคล้ายความลับ
#       และปิดค่าที่หน้าตาเหมือน token/base64 ยาวๆ) กันพลาดถ้ามีคนเพิ่มฟิลด์ใหม่ในอนาคต
#     - audit event ของ Ops Agent: ops_agent_run, ops_agent_alert, ops_agent_config_changed,
#       ops_agent_started, ops_agent_stopped  (ตัวเก็บข้อมูลไม่นับ event เหล่านี้ กันวนลูป)
# =====================================================================

import re as _vmax_ops_re
from collections import deque as _vmax_ops_deque

VMAX_OPS_LOCK = _vmc_threading.RLock()

VMAX_OPS_DEFAULT_CONFIG = {
    "window_seconds": 300,           # ช่วงเวลาย้อนหลังที่นับเหตุการณ์ใน audit log
    "interval_seconds": 60,          # รอบตรวจอัตโนมัติ (ops-start)
    "alert_cooldown_seconds": 300,   # กันแจ้งเตือนกฎเดิมซ้ำถี่เกินไป (ยกเว้นความรุนแรงเพิ่มขึ้น)
    "login_fail_warn": 10,           # ล็อกอินพลาดในช่วง window -> warning
    "login_fail_critical": 30,       # -> critical
    "staff_fail_warn": 3,            # staff/developer/vault ล็อกอินพลาด -> warning
    "identity_reject_warn": 10,      # uid_mismatch / strict_auth / rank denied -> warning
    "cheat_pending_warn": 10,        # รายงานโกงค้างรอตรวจ -> warning
    "thread_restart_warn": 3,        # watchdog restart thread เดิมกี่ครั้งถึงเตือน
}
VMAX_OPS_CONFIG_LIMITS = {
    "window_seconds": (10, 86400),
    "interval_seconds": (5, 3600),
    "alert_cooldown_seconds": (0, 86400),
    "login_fail_warn": (1, 100000),
    "login_fail_critical": (1, 100000),
    "staff_fail_warn": (1, 100000),
    "identity_reject_warn": (1, 100000),
    "cheat_pending_warn": (1, 100000),
    "thread_restart_warn": (1, 1000),
}
VMAX_OPS_CONFIG = dict(VMAX_OPS_DEFAULT_CONFIG)

VMAX_OPS_STATE = {
    "running": False, "thread": None, "stop": None, "interval": None,
    "runs": 0, "last_run_ts": None, "last_report": None, "last_snapshot": None,
    "last_alert_ts": {}, "last_alert_rank": {}, "persist_error": None,
}
VMAX_OPS_HISTORY = _vmax_ops_deque(maxlen=200)   # สรุปย่อของแต่ละรอบ
VMAX_OPS_ALERTS = _vmax_ops_deque(maxlen=200)    # เฉพาะแจ้งเตือนที่ถูก "ปล่อย" จริง (ผ่าน cooldown แล้ว)

_VMAX_OPS_SEV_RANK = {"info": 1, "warning": 2, "critical": 3}
_VMAX_OPS_LEVEL_BY_RANK = {0: "ok", 1: "info", 2: "warning", 3: "critical"}
_VMAX_OPS_LEVEL_TH = {"ok": "ปกติ", "info": "ข้อมูล", "warning": "เฝ้าระวัง", "critical": "วิกฤต"}

_VMAX_OPS_SECRET_KEY_RE = _vmax_ops_re.compile(
    r"(token|secret|passw|passphrase|api[_-]?key|private|base64|credential|cookie|totp|otp\b|(^|_)pin($|_)|key_dir)",
    _vmax_ops_re.I)
_VMAX_OPS_LONG_TOKEN_RE = _vmax_ops_re.compile(r"^[A-Za-z0-9+/=_\-]{40,}$")
_VMAX_OPS_TOKEN_PREFIX_RE = _vmax_ops_re.compile(r"(ghp_|gho_|ghu_|ghs_|github_pat_|sk-[A-Za-z0-9]|AKIA[0-9A-Z]{8})")


def _vmax_ops_sanitize(obj, _depth=0):
    """ชั้นกันหลุดสุดท้าย: เก็บเฉพาะ dict/list/str/int/float/bool/None,
    ตัด key ที่ชื่อคล้ายความลับ, ปิดค่า string ที่หน้าตาเหมือน token/base64 ยาว, จำกัดความลึกและความยาว"""
    if _depth > 6:
        return None
    if isinstance(obj, dict):
        out = {}
        for k, v in obj.items():
            ks = str(k)
            if _VMAX_OPS_SECRET_KEY_RE.search(ks):
                continue
            out[ks] = _vmax_ops_sanitize(v, _depth + 1)
        return out
    if isinstance(obj, (list, tuple)):
        return [_vmax_ops_sanitize(v, _depth + 1) for v in list(obj)[:200]]
    if isinstance(obj, bool) or obj is None:
        return obj
    if isinstance(obj, (int, float)):
        return obj
    if isinstance(obj, str):
        if _VMAX_OPS_LONG_TOKEN_RE.match(obj) or _VMAX_OPS_TOKEN_PREFIX_RE.search(obj):
            return "[redacted]"
        return obj[:300]
    return None


def _vmax_ops_cfg():
    with VMAX_OPS_LOCK:
        return dict(VMAX_OPS_CONFIG)


def _vmax_ops_safe_copy(seq, tries=4):
    """คัดลอก deque/dict/list ที่ thread อื่นอาจแก้ระหว่างอ่าน (mutated during iteration) แบบลองซ้ำ"""
    for _ in range(tries):
        try:
            return list(seq)
        except RuntimeError:
            continue
    return []


def _vmax_ops_safe_items(d, tries=4):
    for _ in range(tries):
        try:
            return list(d.items())
        except RuntimeError:
            continue
    return []


# --- ตัวเก็บข้อมูล (แต่ละตัวห่อ try เอง — ตัวหนึ่งพังไม่ทำให้ทั้งรอบพัง) ---------------------

def _vmax_ops_collect_game():
    try:
        g = globals()
        pending = 0
        for _, r in _vmax_ops_safe_items(g.get("CHEAT_REPORTS", {}) or {}):
            if isinstance(r, dict) and r.get("status") in ("pending", "needs_human_review"):
                pending += 1

        def _n(name):
            try:
                return len(g[name])
            except Exception:
                return None
        return {"ok": True, "players_online": _n("PLAYERS"), "banned_uid_count": _n("BANNED_UIDS"),
                "cheat_reports_total": _n("CHEAT_REPORTS"), "cheat_reports_pending": pending,
                "bridge_events_total": _n("BRIDGE_EVENTS"), "modules_loaded": _n("VMAX_MODULES")}
    except Exception as e:
        return {"ok": False, "error": type(e).__name__}


# (ชื่อกลุ่ม, event ตรงตัว, prefix) — ชื่อ event ตรงกับที่ระบบเดิมเรียก audit_log จริง
_VMAX_OPS_EVENT_GROUPS = (
    ("login_fail", {"login_fail_password", "login_fail_2fa", "2fa_setup_fail_password", "2fa_enable_fail"}, ()),
    ("login_locked_out", {"login_locked_out"}, ()),
    ("staff_fail", set(), ("staff_login_fail", "developer_login_fail", "developer_login_denied",
                           "developer_login_throttled", "staff_login_denied", "staff_game_login_fail")),
    ("identity_reject", {"uid_mismatch_rejected", "strict_auth_rejected", "staff_rank_denied",
                         "staff_role_command_denied", "staff_game_command_denied"}, ()),
    ("vault_unlock_fail", set(), ("vault_unlock_fail", "vault_passphrase_change_fail")),
    ("dev_console_denied", {"dev_console_run_denied"}, ()),
    ("topup_bad_signature", {"topup_callback_bad_signature"}, ()),
)


def _vmax_ops_collect_auth(window):
    try:
        cutoff = _vmc_time.time() - window
        counts = {name: 0 for name, _, _ in _VMAX_OPS_EVENT_GROUPS}
        login_fail_ips, total = set(), 0
        for ev in _vmax_ops_safe_copy(globals().get("AUDIT_LOG", []) or []):
            if not isinstance(ev, dict) or ev.get("ts", 0) < cutoff:
                continue
            name = str(ev.get("event", ""))
            if name.startswith("ops_agent_"):
                continue   # ไม่นับ event ของตัวเอง
            total += 1
            for group, exact, prefixes in _VMAX_OPS_EVENT_GROUPS:
                if name in exact or (prefixes and name.startswith(prefixes)):
                    counts[group] += 1
                    if group == "login_fail" and ev.get("ip"):
                        login_fail_ips.add(ev.get("ip"))
                    break
        counts.update({"ok": True, "events_in_window": total,
                       "distinct_ips_login_fail": len(login_fail_ips)})   # เก็บแค่จำนวน ไม่เก็บ ip/uid
        return counts
    except Exception as e:
        return {"ok": False, "error": type(e).__name__}


def _vmax_ops_collect_vault(window):
    out = {"ok": True}
    g = globals()
    try:
        ks = vmax_key_status()   # whitelist: ไม่เอา key_dir / reminder
        out["key_mode"] = ks.get("mode")
        out["gate_configured"] = bool(ks.get("gate_configured"))
        out["gate_factors"] = ks.get("gate_factors")
        out["plain_key_files_on_disk"] = ks.get("plain_key_files_on_disk")
    except Exception as e:
        out["key_status_error"] = type(e).__name__
    try:
        sites = vmax_vault_list_sites()
        out["sites"] = len([s for s in sites if s != "ops_agent"])
    except Exception as e:
        out["sites_error"] = type(e).__name__
    try:
        lock = g.get("VMAX_VAULT_LOCK")
        reg = g.get("VMAX_RELAY_REGISTRY", {}) or {}
        if lock is not None:
            with lock:
                statuses = [info.get("status") for info in reg.values()]
                pool = len(g.get("VMAX_RELAY_ACTIVE_POOL", []) or [])
        else:
            statuses, pool = [info.get("status") for info in _vmax_ops_safe_copy(reg.values())], 0
        out["relays"] = {"registered": len(statuses), "healthy": sum(1 for s in statuses if s == "healthy"),
                         "active_pool": pool, "target": g.get("VMAX_RELAY_COUNT_DEFAULT")}
    except Exception as e:
        out["relays_error"] = type(e).__name__
    try:
        conn = _vault_db()
        try:
            rows = conn.execute(
                "SELECT action, COUNT(*) FROM vault_audit_log WHERE at>=? AND COALESCE(actor,'')!='ops_agent' GROUP BY action",
                (_vmc_time.time() - window,)).fetchall()
        finally:
            conn.close()
        by_action = {a: n for a, n in rows}
        out["vault_writes"] = by_action.get("vault_set", 0)
        out["relay_quarantined"] = by_action.get("relay_quarantined", 0)
    except Exception as e:
        out["vault_audit_error"] = type(e).__name__
    if "key_mode" not in out and "relays" not in out:
        out["ok"] = False   # ไม่ได้ข้อมูลหลักของ vault เลย -> ให้กฎ collector_failure แจ้ง
    return out


def _vmax_ops_collect_mcp(window):
    try:
        with VMAX_MCP_LOCK:
            running, port = VMAX_MCP_STATE.get("running"), VMAX_MCP_STATE.get("port")
        now = _vmc_time.time()
        locked, recent = 0, 0
        with VMAX_MCP_FAIL_LOCK:
            for _, ts in VMAX_MCP_FAILED_ATTEMPTS.items():
                in_window = [t for t in ts if now - t < window]
                recent += len(in_window)
                if len([t for t in ts if now - t < VMAX_MCP_LOCKOUT_SECONDS]) >= VMAX_MCP_MAX_ATTEMPTS:
                    locked += 1
        return {"ok": True, "running": bool(running), "port": port,
                "locked_out_ips": locked, "recent_failures": recent}   # ไม่มี token / ไม่มีรายชื่อ ip
    except Exception as e:
        return {"ok": False, "error": type(e).__name__}


def _vmax_ops_collect_threads():
    try:
        out = {}
        for name, entry in _vmax_ops_safe_items(globals().get("WATCHDOG_REGISTRY", {}) or {}):
            th = entry.get("thread") if isinstance(entry, dict) else None
            out[str(name)] = {"alive": bool(th and th.is_alive()),
                              "restarts": int((entry or {}).get("restarts", 0))}
        return {"ok": True, "threads": out}
    except Exception as e:
        return {"ok": False, "error": type(e).__name__}


def vmax_ops_collect_snapshot():
    cfg = _vmax_ops_cfg()
    w = cfg["window_seconds"]
    snap = {"ts": _vmc_time.time(), "window_seconds": w,
            "game": _vmax_ops_collect_game(), "auth": _vmax_ops_collect_auth(w),
            "vault": _vmax_ops_collect_vault(w), "mcp": _vmax_ops_collect_mcp(w),
            "threads": _vmax_ops_collect_threads()}
    return _vmax_ops_sanitize(snap)


# --- กฎแจ้งเตือน ---------------------------------------------------------------------------

def _vmax_ops_alert(rule, severity, message, value=None, threshold=None):
    return {"rule": rule, "severity": severity, "message": message, "value": value, "threshold": threshold}


def _vmax_ops_evaluate(snap, cfg):
    """รับ snapshot + config -> คืน list ของ alert ที่ 'เป็นจริงตอนนี้' (ยังไม่ผ่าน cooldown)"""
    alerts = []
    auth, vault = snap.get("auth", {}) or {}, snap.get("vault", {}) or {}
    mcp, game = snap.get("mcp", {}) or {}, snap.get("game", {}) or {}
    thr = (snap.get("threads", {}) or {}).get("threads", {}) or {}
    w = snap.get("window_seconds")

    n = auth.get("login_fail") or 0
    if n >= cfg["login_fail_critical"]:
        alerts.append(_vmax_ops_alert("auth_bruteforce", "critical",
                      f"ล็อกอินพลาด {n} ครั้งใน {w} วินาที (จาก {auth.get('distinct_ips_login_fail', 0)} ไอพี) เข้าข่ายเดารหัส",
                      n, cfg["login_fail_critical"]))
    elif n >= cfg["login_fail_warn"]:
        alerts.append(_vmax_ops_alert("auth_bruteforce", "warning",
                      f"ล็อกอินพลาด {n} ครั้งใน {w} วินาที สูงกว่าปกติ", n, cfg["login_fail_warn"]))
    n = auth.get("login_locked_out") or 0
    if n >= 1:
        alerts.append(_vmax_ops_alert("login_lockouts", "info", f"มีบัญชีถูกล็อกชั่วคราว {n} ครั้งใน {w} วินาที", n, 1))
    n = auth.get("staff_fail") or 0
    if n >= cfg["staff_fail_warn"]:
        alerts.append(_vmax_ops_alert("staff_auth_fail", "warning",
                      f"ล็อกอินทีมงาน/นักพัฒนาผิดพลาด {n} ครั้ง ควรตรวจว่าใช่ตัวจริงหรือไม่", n, cfg["staff_fail_warn"]))
    n = auth.get("identity_reject") or 0
    if n >= cfg["identity_reject_warn"]:
        alerts.append(_vmax_ops_alert("identity_reject", "warning",
                      f"คำขอถูกปฏิเสธเรื่องตัวตน/สิทธิ์ {n} ครั้ง (uid ไม่ตรง / rank ไม่พอ)", n, cfg["identity_reject_warn"]))
    n = auth.get("vault_unlock_fail") or 0
    if n >= cfg["staff_fail_warn"]:
        alerts.append(_vmax_ops_alert("vault_unlock_fail", "warning",
                      f"ปลดล็อก vault ผู้เล่นพลาด {n} ครั้ง", n, cfg["staff_fail_warn"]))
    n = auth.get("dev_console_denied") or 0
    if n >= 1:
        alerts.append(_vmax_ops_alert("dev_console_denied", "warning", f"มีคนพยายามรันคำสั่ง dev console โดยไม่มีสิทธิ์ {n} ครั้ง", n, 1))
    n = auth.get("topup_bad_signature") or 0
    if n >= 1:
        alerts.append(_vmax_ops_alert("topup_bad_signature", "warning", f"callback เติมเงินลายเซ็นไม่ถูกต้อง {n} ครั้ง", n, 1))

    n = mcp.get("locked_out_ips") or 0
    if n >= 1:
        alerts.append(_vmax_ops_alert("mcp_lockout", "warning", f"MCP console ล็อก {n} ไอพีที่ยิง token ผิดถี่เกินไป", n, 1))

    mode = vault.get("key_mode")
    if mode == "plain_files":
        alerts.append(_vmax_ops_alert("key_unprotected", "info", "กุญแจ vault ยังเป็นไฟล์ดิบบนดิสก์ (พิจารณา gate-setup + seal-key)"))
    elif isinstance(mode, str) and mode.startswith("sealed") and (vault.get("plain_key_files_on_disk") or 0) > 0:
        alerts.append(_vmax_ops_alert("key_plain_leftover", "warning",
                      f"ปิดผนึกกุญแจแล้วแต่ยังเหลือไฟล์กุญแจดิบ {vault.get('plain_key_files_on_disk')} ไฟล์บนดิสก์",
                      vault.get("plain_key_files_on_disk"), 0))
    relays = vault.get("relays") or {}
    if (relays.get("registered") or 0) > 0:
        healthy, target = relays.get("healthy") or 0, relays.get("target") or 0
        if healthy == 0:
            alerts.append(_vmax_ops_alert("relay_health", "critical", "ไม่มี relay ที่ healthy เลย ผู้อ่านผ่าน relay จะอ่านไม่ได้", healthy, 1))
        elif target and healthy < target:
            alerts.append(_vmax_ops_alert("relay_health", "warning", f"relay healthy {healthy}/{target} ต่ำกว่าเป้า", healthy, target))
    n = vault.get("relay_quarantined") or 0
    if n >= 1:
        alerts.append(_vmax_ops_alert("relay_quarantined", "warning", f"มี relay ถูกกักกัน (breach) {n} ครั้งใน {w} วินาที", n, 1))

    dead = sorted(name for name, t in thr.items() if not t.get("alive"))
    if dead:
        alerts.append(_vmax_ops_alert("thread_dead", "critical" if len(dead) >= 2 else "warning",
                      f"thread พื้นหลังไม่ทำงาน {len(dead)} ตัว: {', '.join(dead[:5])}", len(dead), 0))
    hot = sorted(name for name, t in thr.items() if (t.get("restarts") or 0) >= cfg["thread_restart_warn"])
    if hot:
        alerts.append(_vmax_ops_alert("thread_restarts", "warning",
                      f"thread ถูก watchdog restart บ่อย: {', '.join(hot[:5])}", len(hot), cfg["thread_restart_warn"]))

    n = game.get("cheat_reports_pending") or 0
    if n >= cfg["cheat_pending_warn"]:
        alerts.append(_vmax_ops_alert("cheat_pending", "warning", f"รายงานโกงค้างรอตรวจ {n} รายการ", n, cfg["cheat_pending_warn"]))

    failed = [name for name in ("game", "auth", "vault", "mcp", "threads") if (snap.get(name) or {}).get("ok") is False]
    if failed:
        alerts.append(_vmax_ops_alert("collector_failure", "info", f"ตัวเก็บข้อมูลล้มเหลว: {', '.join(failed)}", len(failed), 0))
    return alerts


def _vmax_ops_emit_alerts(alerts, cfg, now):
    """ปล่อย alert จริงลง log/audit/bridge โดยเว้น cooldown; ความรุนแรงเพิ่มขึ้นให้ปล่อยทันที"""
    emitted = []
    with VMAX_OPS_LOCK:
        active_rules = {a["rule"] for a in alerts}
        for rule in list(VMAX_OPS_STATE["last_alert_rank"]):
            if rule not in active_rules:
                VMAX_OPS_STATE["last_alert_rank"].pop(rule, None)   # เคลียร์เมื่อหายแล้ว (cooldown ยังกัน flapping)
        for a in alerts:
            rank = _VMAX_OPS_SEV_RANK[a["severity"]]
            last_ts = VMAX_OPS_STATE["last_alert_ts"].get(a["rule"], 0)
            last_rank = VMAX_OPS_STATE["last_alert_rank"].get(a["rule"], 0)
            if rank > last_rank or now - last_ts >= cfg["alert_cooldown_seconds"]:
                rec = dict(a, ts=now)
                VMAX_OPS_ALERTS.append(rec)
                VMAX_OPS_STATE["last_alert_ts"][a["rule"]] = now
                VMAX_OPS_STATE["last_alert_rank"][a["rule"]] = rank
                emitted.append(rec)
    for rec in emitted:
        try:
            audit_log("ops_agent_alert", uid="ops_agent", rule=rec["rule"], severity=rec["severity"], value=rec.get("value"))
        except Exception:
            pass
        try:
            fn = globals().get("bridge_push_event")
            if fn:
                fn("ops_agent", "ops_alert", {"rule": rec["rule"], "severity": rec["severity"], "message": rec["message"]})
        except Exception:
            pass
    return emitted


# --- สรุปรายงาน ----------------------------------------------------------------------------

def vmax_ops_build_report(snap, alerts):
    rank = max([_VMAX_OPS_SEV_RANK[a["severity"]] for a in alerts] or [0])
    level = _VMAX_OPS_LEVEL_BY_RANK[rank]
    if level == "ok":
        headline = "ระบบปกติ ไม่มีเรื่องที่ต้องจัดการ"
    else:
        n_hi = sum(1 for a in alerts if a["severity"] in ("warning", "critical"))
        headline = (f"ระดับ{_VMAX_OPS_LEVEL_TH[level]}: พบ {len(alerts)} เรื่อง (เร่งด่วน/เฝ้าระวัง {n_hi})"
                    if n_hi else f"มี {len(alerts)} เรื่องเพื่อทราบ ยังไม่ต้องลงมือ")
    game, auth = snap.get("game", {}) or {}, snap.get("auth", {}) or {}
    vault, mcp = snap.get("vault", {}) or {}, snap.get("mcp", {}) or {}
    relays = vault.get("relays") or {}
    lines = [
        f"ผู้เล่นออนไลน์ {game.get('players_online')} | แบน {game.get('banned_uid_count')} | รายงานโกงค้าง {game.get('cheat_reports_pending')}/{game.get('cheat_reports_total')}",
        f"ความปลอดภัย ({snap.get('window_seconds')} วิ): ล็อกอินพลาด {auth.get('login_fail')} | ล็อกชั่วคราว {auth.get('login_locked_out')} | ทีมงานพลาด {auth.get('staff_fail')} | ปฏิเสธตัวตน {auth.get('identity_reject')}",
        f"Vault: กุญแจ {vault.get('key_mode')} | ด่าน {'ตั้งแล้ว' if vault.get('gate_configured') else 'ยังไม่ตั้ง'} | ไซต์ {vault.get('sites')} | relay healthy {relays.get('healthy')}/{relays.get('registered')}",
        f"MCP: {'เปิด' if mcp.get('running') else 'ปิด'} | ไอพีถูกล็อก {mcp.get('locked_out_ips')}",
    ]
    return _vmax_ops_sanitize({"ts": snap.get("ts"), "level": level, "headline": headline,
                               "lines": lines, "alerts": alerts})


def vmax_ops_format_report_text(report):
    ts = report.get("ts")
    when = _vmc_time.strftime("%Y-%m-%d %H:%M:%S", _vmc_time.localtime(ts)) if ts else "-"
    out = [f"=== Ops Agent [{_VMAX_OPS_LEVEL_TH.get(report.get('level'), report.get('level'))}] {when} ===", report.get("headline", "")]
    out += [f"  {ln}" for ln in report.get("lines", [])]
    for a in report.get("alerts", []):
        out.append(f"  ! [{a['severity']}] {a['rule']}: {a['message']}")
    return "\n".join(out)


# --- รันหนึ่งรอบ / ลูปพื้นหลัง -----------------------------------------------------------------

def _vmax_ops_persist(report, snapshot):
    """เขียนรายงานของตัวเองลง site=ops_agent (ผ่าน vault API เดิม) แล้ว sync relay — คืนชื่อ error หรือ None"""
    try:
        vmax_vault_set_site("ops_agent", "last_report", report, actor="ops_agent")
        vmax_vault_set_site("ops_agent", "last_snapshot", snapshot, actor="ops_agent")
    except Exception as e:
        return type(e).__name__
    try:
        vmax_relay_sync_all()
    except Exception as e:
        return "relay_sync_" + type(e).__name__
    return None


def vmax_ops_run_once(persist=True):
    cfg = _vmax_ops_cfg()
    snap = vmax_ops_collect_snapshot()
    now = snap.get("ts") or _vmc_time.time()
    alerts = _vmax_ops_evaluate(snap, cfg)
    emitted = _vmax_ops_emit_alerts(alerts, cfg, now)
    report = vmax_ops_build_report(snap, alerts)
    perr = _vmax_ops_persist(report, snap) if persist else None
    with VMAX_OPS_LOCK:
        VMAX_OPS_STATE.update({"runs": VMAX_OPS_STATE["runs"] + 1, "last_run_ts": now,
                               "last_report": report, "last_snapshot": snap, "persist_error": perr})
        VMAX_OPS_HISTORY.append({"ts": now, "level": report["level"], "alerts": len(alerts),
                                 "login_fail": (snap.get("auth") or {}).get("login_fail"),
                                 "players_online": (snap.get("game") or {}).get("players_online")})
    try:
        audit_log("ops_agent_run", uid="ops_agent", level=report["level"], alerts=len(alerts), emitted=len(emitted))
    except Exception:
        pass
    return {"ok": True, "report": report, "emitted": len(emitted), "persist_error": perr}


def _vmax_ops_loop(stop_event, interval):
    while not stop_event.wait(interval):
        try:
            vmax_ops_run_once()
        except Exception:
            pass   # ห้ามให้ลูปตาย — รอบหน้าลองใหม่


def vmax_ops_start(interval=None):
    with VMAX_OPS_LOCK:
        if VMAX_OPS_STATE["running"]:
            return {"ok": False, "reason": "already_running", "interval": VMAX_OPS_STATE["interval"]}
        lo, hi = VMAX_OPS_CONFIG_LIMITS["interval_seconds"]
        try:
            interval = int(interval if interval is not None else VMAX_OPS_CONFIG["interval_seconds"])
        except (TypeError, ValueError):
            return {"ok": False, "reason": "bad_interval"}
        if not lo <= interval <= hi:
            return {"ok": False, "reason": "interval_out_of_range", "min": lo, "max": hi}
        stop = _vmc_threading.Event()
        th = _vmc_threading.Thread(target=_vmax_ops_loop, args=(stop, interval), daemon=True)
        VMAX_OPS_STATE.update({"running": True, "thread": th, "stop": stop, "interval": interval})
        th.start()
    try:
        audit_log("ops_agent_started", uid="ops_agent", interval=interval)
    except Exception:
        pass
    return {"ok": True, "interval": interval}


def vmax_ops_stop():
    with VMAX_OPS_LOCK:
        if not VMAX_OPS_STATE["running"]:
            return {"ok": False, "reason": "not_running"}
        stop, th = VMAX_OPS_STATE["stop"], VMAX_OPS_STATE["thread"]
        VMAX_OPS_STATE.update({"running": False, "thread": None, "stop": None, "interval": None})
    stop.set()
    if th is not None and th is not _vmc_threading.current_thread():
        th.join(timeout=3)
    try:
        audit_log("ops_agent_stopped", uid="ops_agent")
    except Exception:
        pass
    return {"ok": True}


def vmax_ops_status():
    with VMAX_OPS_LOCK:
        rep = VMAX_OPS_STATE["last_report"]
        return _vmax_ops_sanitize({
            "ok": True, "running": VMAX_OPS_STATE["running"], "interval": VMAX_OPS_STATE["interval"],
            "runs": VMAX_OPS_STATE["runs"], "last_run_ts": VMAX_OPS_STATE["last_run_ts"],
            "level": rep["level"] if rep else None, "headline": rep["headline"] if rep else None,
            "alerts_logged": len(VMAX_OPS_ALERTS), "persist_error": VMAX_OPS_STATE["persist_error"]})


def vmax_ops_set_config(name, value, actor="mcp_console"):
    if name not in VMAX_OPS_DEFAULT_CONFIG:
        return {"ok": False, "reason": "unknown_setting", "allowed": sorted(VMAX_OPS_DEFAULT_CONFIG)}
    try:
        v = int(value)
    except (TypeError, ValueError):
        return {"ok": False, "reason": "value_must_be_integer"}
    lo, hi = VMAX_OPS_CONFIG_LIMITS[name]
    if not lo <= v <= hi:
        return {"ok": False, "reason": "out_of_range", "min": lo, "max": hi}
    with VMAX_OPS_LOCK:
        old = VMAX_OPS_CONFIG[name]
        VMAX_OPS_CONFIG[name] = v
    try:
        audit_log("ops_agent_config_changed", uid=str(actor), setting=name, old=old, new=v)
    except Exception:
        pass
    return {"ok": True, "name": name, "old": old, "new": v}


def _vmax_ops_recent(deq, limit):
    with VMAX_OPS_LOCK:
        items = list(deq)
    return items[-limit:] if limit > 0 else []


def _vmax_ops_qs_int(qs, name, default, lo, hi):
    try:
        v = int((qs.get(name) or [default])[0])
    except (TypeError, ValueError):
        v = default
    return max(lo, min(hi, v))


def vmax_ops_http(method, path, qs, body):
    """ตัวจัดการ /mcp/ops/* (ถูกเรียกหลังผ่านการตรวจ X-VMAX-Token แล้วเท่านั้น) -> (status_code, obj)"""
    route = path[len("/mcp/ops/"):].strip("/")
    if method == "GET":
        if route == "status":
            return 200, vmax_ops_status()
        if route == "report":
            with VMAX_OPS_LOCK:
                rep, snap = VMAX_OPS_STATE["last_report"], VMAX_OPS_STATE["last_snapshot"]
            if rep is None:
                res = vmax_ops_run_once()
                rep = res["report"]
                with VMAX_OPS_LOCK:
                    snap = VMAX_OPS_STATE["last_snapshot"]
            out = {"ok": True, "report": rep}
            if (qs.get("full") or ["0"])[0] == "1":
                out["snapshot"] = snap
            return 200, out
        if route == "alerts":
            return 200, {"ok": True, "alerts": _vmax_ops_recent(VMAX_OPS_ALERTS, _vmax_ops_qs_int(qs, "limit", 20, 1, 200))}
        if route == "history":
            return 200, {"ok": True, "history": _vmax_ops_recent(VMAX_OPS_HISTORY, _vmax_ops_qs_int(qs, "limit", 30, 1, 200))}
        if route == "config":
            return 200, {"ok": True, "config": _vmax_ops_cfg(), "limits": {k: list(v) for k, v in VMAX_OPS_CONFIG_LIMITS.items()}}
        _choke_res = vmax_choke_http("GET", route, qs, None)
        if _choke_res is not None:
            return _choke_res
        _supply_res = vmax_supply_http("GET", route, qs, None)
        if _supply_res is not None:
            return _supply_res
        return 404, {"ok": False, "reason": "not_found"}
    if method == "POST":
        if route == "run":
            return 200, vmax_ops_run_once()
        if route == "config":
            if not isinstance(body, dict):
                return 400, {"ok": False, "reason": "bad_json"}
            res = vmax_ops_set_config(body.get("name"), body.get("value"), actor="mcp_remote")
            return (200 if res.get("ok") else 400), res
        _choke_res = vmax_choke_http("POST", route, qs, body)
        if _choke_res is not None:
            return _choke_res
        _supply_res = vmax_supply_http("POST", route, qs, body)
        if _supply_res is not None:
            return _supply_res
        return 404, {"ok": False, "reason": "not_found"}
    return 405, {"ok": False, "reason": "method_not_allowed"}


# --- คำสั่งในคอนโซล ------------------------------------------------------------------------

_VMAX_OPS_CONSOLE_CMDS = {
    "ops-run": "run", "ตรวจระบบ": "run",
    "ops-status": "status", "สถานะระบบ": "status",
    "ops-alerts": "alerts", "แจ้งเตือน": "alerts",
    "ops-report": "report", "รายงานระบบ": "report",
    "ops-start": "start", "ops-stop": "stop",
    "ops-config": "config", "ops-set": "set",
    "choke-start": "choke_start", "ล็อคคอ": "choke_start",
    "choke-aim": "choke_aim", "เล็งปืน": "choke_aim",
    "choke-counter": "choke_counter", "สวนกลับ": "choke_counter",
    "choke-heal": "choke_heal", "รักษา": "choke_heal",
    "choke-state": "choke_state", "สถานะล็อคคอ": "choke_state",
}
_VMAX_OPS_CONSOLE_CMDS.update(_VMAX_SUPPLY_CONSOLE_CMDS)   # supply-* / เสบียง-*


def _vmax_ops_print_json(obj):
    print(_vmc_json.dumps(obj, ensure_ascii=False, indent=2, default=str))


def _vmax_ops_console_dispatch(parts):
    action = _VMAX_OPS_CONSOLE_CMDS.get(parts[0])
    args = parts[1:]
    if action in _VMAX_SUPPLY_CONSOLE_CMDS.values():
        _vmax_ops_print_json(_vmax_supply_console(action, args))
        return
    if action == "run":
        print(vmax_ops_format_report_text(vmax_ops_run_once()["report"]))
    elif action == "status":
        _vmax_ops_print_json(vmax_ops_status())
    elif action == "alerts":
        n = int(args[0]) if args and args[0].isdigit() else 20
        items = _vmax_ops_recent(VMAX_OPS_ALERTS, n)
        if not items:
            print("ยังไม่มีแจ้งเตือน (ลอง ops-run ก่อน)")
        for a in items:
            print(f"[{_vmc_time.strftime('%H:%M:%S', _vmc_time.localtime(a['ts']))}] {a['severity']:8s} {a['rule']}: {a['message']}")
    elif action == "report":
        with VMAX_OPS_LOCK:
            rep = VMAX_OPS_STATE["last_report"]
        print(vmax_ops_format_report_text(rep or vmax_ops_run_once()["report"]))
    elif action == "start":
        _vmax_ops_print_json(vmax_ops_start(args[0] if args else None))
    elif action == "stop":
        _vmax_ops_print_json(vmax_ops_stop())
    elif action == "config":
        _vmax_ops_print_json({"config": _vmax_ops_cfg(), "limits": {k: list(v) for k, v in VMAX_OPS_CONFIG_LIMITS.items()}})
    elif action == "set":
        if len(args) != 2:
            print("ใช้: ops-set <ชื่อ> <ตัวเลข>   (ดูชื่อทั้งหมดด้วย ops-config)")
        else:
            _vmax_ops_print_json(vmax_ops_set_config(args[0], args[1]))
    elif action == "choke_start":
        if len(args) < 2:
            print("ใช้: choke-start <ผู้ล็อค> <เป้าหมาย> [victim|away] [left|right]")
        else:
            _vmax_ops_print_json(vmax_choke_start(args[0], args[1], args[2] if len(args) > 2 else "victim",
                                                  args[3] if len(args) > 3 else "right")[1])
    elif action == "choke_aim":
        if len(args) != 2:
            print("ใช้: choke-aim <เป้าหมาย> <victim|away>")
        else:
            _vmax_ops_print_json(vmax_choke_aim(args[0], args[1])[1])
    elif action == "choke_counter":
        if len(args) != 1:
            print("ใช้: choke-counter <เป้าหมาย>")
        else:
            _vmax_ops_print_json(vmax_choke_counter(args[0])[1])
    elif action == "choke_heal":
        if not args:
            print("ใช้: choke-heal <uid> [ส่วนร่างกาย]   (head/neck/torso/left_arm/right_arm/left_leg/right_leg)")
        else:
            _vmax_ops_print_json(vmax_choke_heal(args[0], args[1] if len(args) > 1 else "")[1])
    elif action == "choke_state":
        if not args:
            print("ใช้: choke-state <เป้าหมาย> [ผู้ล็อค]")
        else:
            _vmax_ops_print_json(vmax_choke_state(args[0], args[1] if len(args) > 1 else "")[1])


VMAX_MODULES["ops_agent"] = {
    "name": "Ops Agent", "name_th": "เอเจนต์ดูแลระบบตู้ MC (อ่านอย่างเดียว)",
    "version": "1.0", "category": "infrastructure", "genre": "all",
    "description": "เก็บสถิติตัวเลขจาก audit log / vault / relay / MCP / watchdog / เกม -> กฎแจ้งเตือน -> สรุปรายงานไทย "
                   "ผ่านคอนโซล (ops-*) และ MCP API /mcp/ops/* (127.0.0.1 + token) "
                   "ไม่แก้ข้อมูลระบบเดิม ไม่ส่ง token/กุญแจ/รหัสผ่าน/ยอดเงินออกมา",
    "routes": ["/mcp/ops/status", "/mcp/ops/report", "/mcp/ops/alerts", "/mcp/ops/history",
               "/mcp/ops/config", "/mcp/ops/run"],
}


# --- selftest: python <ไฟล์นี้> --selftest-ops-agent -----------------------------------------

def _run_ops_agent_selftest():
    import urllib.request as _t_req
    import urllib.error as _t_err
    import json as _t_json

    # 1) sanitize: key ลับต้องหาย, ค่าที่หน้าตาเหมือน token/base64 ต้องถูกปิด
    fake_token = "ghp_" + "A1b2C3d4" * 5
    fake_b64 = "QUJD" * 20
    dirty = {"ok": True, "n": 3, "vault_token": "x", "key_dir": "/secret/dir", "note": fake_token,
             "blob": fake_b64, "nested": {"api_key": "k", "pin": "1234", "fine": "hello"}, "seq": [fake_token, 1]}
    clean = _vmax_ops_sanitize(dirty)
    dumped = _t_json.dumps(clean)
    for bad in (fake_token, fake_b64, "/secret/dir", "vault_token", "api_key", "1234"):
        assert bad not in dumped, f"sanitize รั่ว: {bad}"
    assert clean["nested"]["fine"] == "hello" and clean["n"] == 3

    # 2) กฎแจ้งเตือน: snapshot ปกติต้องไม่มี alert, ล็อกอินพลาดเยอะต้อง critical
    cfg = dict(VMAX_OPS_DEFAULT_CONFIG)
    healthy = {"window_seconds": 300, "game": {"ok": True, "cheat_reports_pending": 0}, "auth": {"ok": True},
               "vault": {"ok": True, "key_mode": "sealed", "plain_key_files_on_disk": 0,
                         "relays": {"registered": 3, "healthy": 3, "target": 3}},
               "mcp": {"ok": True, "locked_out_ips": 0}, "threads": {"ok": True, "threads": {"t": {"alive": True, "restarts": 0}}}}
    assert _vmax_ops_evaluate(healthy, cfg) == []
    bad = _t_json.loads(_t_json.dumps(healthy))
    bad["auth"].update({"login_fail": 40, "distinct_ips_login_fail": 2})
    bad["vault"]["relays"]["healthy"] = 0
    bad["threads"]["threads"]["t"]["alive"] = False
    rules = {a["rule"]: a["severity"] for a in _vmax_ops_evaluate(bad, cfg)}
    assert rules["auth_bruteforce"] == "critical" and rules["relay_health"] == "critical" and rules["thread_dead"] == "warning", rules

    # 3) cooldown + escalation
    with VMAX_OPS_LOCK:
        VMAX_OPS_STATE["last_alert_ts"].clear()
        VMAX_OPS_STATE["last_alert_rank"].clear()
    warn = [_vmax_ops_alert("auth_bruteforce", "warning", "x")]
    crit = [_vmax_ops_alert("auth_bruteforce", "critical", "x")]
    assert len(_vmax_ops_emit_alerts(warn, cfg, 1000.0)) == 1
    assert len(_vmax_ops_emit_alerts(warn, cfg, 1010.0)) == 0            # ติด cooldown
    assert len(_vmax_ops_emit_alerts(crit, cfg, 1020.0)) == 1            # รุนแรงขึ้น ปล่อยทันที
    assert len(_vmax_ops_emit_alerts(warn, cfg, 1000.0 + 400)) == 1      # พ้น cooldown

    # 4) collector นับ audit event จริง และไม่นับ event ของตัวเอง
    before = _vmax_ops_collect_auth(300)["login_fail"]
    for _ in range(4):
        AUDIT_LOG.append({"ts": _vmc_time.time(), "event": "login_fail_password", "uid": "selftest_uid", "ip": "203.0.113.9"})
    AUDIT_LOG.append({"ts": _vmc_time.time(), "event": "ops_agent_run", "uid": "ops_agent", "ip": None})
    after = _vmax_ops_collect_auth(300)
    assert after["login_fail"] == before + 4 and after["distinct_ips_login_fail"] >= 1
    assert "203.0.113.9" not in _t_json.dumps(after) and "selftest_uid" not in _t_json.dumps(after)

    # 5) run_once + persist ลง site=ops_agent และอ่านกลับได้
    res = vmax_ops_run_once(persist=True)
    assert res["ok"] and res["report"]["level"] in ("ok", "info", "warning", "critical")
    stored = vmax_vault_get(_vmax_site_key("ops_agent", "last_report"))
    assert stored and stored["value"]["headline"] == res["report"]["headline"]

    # 6) MCP API: ไม่มี token = 401, มี token = ได้, และผลลัพธ์ทุกอย่างต้องไม่มี token / ความลับ
    import socket as _t_sock
    _probe = _t_sock.socket()
    _probe.bind(("127.0.0.1", 0))
    free_port = _probe.getsockname()[1]   # หาพอร์ตว่างเอง กันชนพอร์ตที่ยังค้าง TIME_WAIT จากการรันก่อนหน้า
    _probe.close()
    start = vmax_mcp_start(port=free_port)
    assert start["ok"], start
    token, base = start["token"], f"http://127.0.0.1:{start['port']}"
    everything = []
    try:
        try:
            _t_req.urlopen(f"{base}/mcp/ops/status", timeout=3)
            assert False, "ต้อง 401 เมื่อไม่แนบ token"
        except _t_err.HTTPError as e:
            assert e.code == 401

        def call(method, path, payload=None):
            data = _t_json.dumps(payload).encode() if payload is not None else None
            req = _t_req.Request(base + path, data=data, method=method,
                                 headers={"X-VMAX-Token": token, "Content-Type": "application/json"})
            try:
                with _t_req.urlopen(req, timeout=5) as r:
                    txt = r.read().decode()
                    code = r.status
            except _t_err.HTTPError as e:
                txt, code = e.read().decode(), e.code
            everything.append(txt)
            return code, _t_json.loads(txt)

        assert call("POST", "/mcp/ops/run")[0] == 200
        assert call("GET", "/mcp/ops/status")[0] == 200
        assert call("GET", "/mcp/ops/report?full=1")[0] == 200
        assert call("GET", "/mcp/ops/alerts?limit=5")[0] == 200
        assert call("GET", "/mcp/ops/history?limit=5")[0] == 200
        assert call("GET", "/mcp/ops/config")[0] == 200
        assert call("POST", "/mcp/ops/config", {"name": "window_seconds", "value": 120})[0] == 200
        assert call("POST", "/mcp/ops/config", {"name": "no_such_setting", "value": 1})[0] == 400
        assert call("POST", "/mcp/ops/config", {"name": "window_seconds", "value": -5})[0] == 400
        assert call("GET", "/mcp/ops/nope")[0] == 404
    finally:
        vmax_mcp_stop()
        vmax_ops_set_config("window_seconds", VMAX_OPS_DEFAULT_CONFIG["window_seconds"])
    blob = "\n".join(everything) + _t_json.dumps(VMAX_OPS_STATE["last_report"]) + _t_json.dumps(VMAX_OPS_STATE["last_snapshot"])
    for secret in (token, fake_token):
        assert secret not in blob, "พบความลับหลุดในผลลัพธ์ Ops Agent"

    # 7) ลูปพื้นหลังเริ่ม/หยุดได้ และตัวเลือกผิดถูกปฏิเสธ
    assert vmax_ops_start(1)["reason"] == "interval_out_of_range"
    assert vmax_ops_start(30)["ok"] and vmax_ops_start(30)["reason"] == "already_running"
    assert vmax_ops_stop()["ok"] and vmax_ops_stop()["reason"] == "not_running"

    conn = _vault_db()
    try:
        conn.execute("DELETE FROM vault_kv WHERE key LIKE 'site::ops_agent::%'")
        conn.commit()
    finally:
        conn.close()
    with VMAX_OPS_LOCK:   # ล้างข้อมูลทดสอบ ไม่ให้ค้างเป็น alert/ประวัติปลอม
        VMAX_OPS_STATE["last_alert_ts"].clear()
        VMAX_OPS_STATE["last_alert_rank"].clear()
        VMAX_OPS_STATE.update({"runs": 0, "last_run_ts": None, "last_report": None, "last_snapshot": None,
                               "persist_error": None})
        VMAX_OPS_ALERTS.clear()
        VMAX_OPS_HISTORY.clear()
    return True


if '--selftest-ops-agent' in sys.argv:
    ok = _run_ops_agent_selftest()
    print("ops-agent selftest:", "OK" if ok else "FAILED")
    sys.exit(0 if ok else 1)


def vmax_mcp_console():
    """คอนโซลตัวเดียวที่สลับสถานะเครื่องได้ — MCP เก็บข้อมูลเว็บไซต์ <-> คอมพิวเตอร์ปกติ
    รันด้วย: python <ไฟล์นี้> --mcp-console"""
    print("=== VMAX MCP Console ===")
    print("พิมพ์: เปิด/start = เปิดโหมด MCP (เก็บข้อมูลเว็บไซต์)")
    print("       ปิด/stop  = ปิดโหมด MCP กลับเป็นคอมพิวเตอร์ปกติ")
    print("       สถานะ/status, export-key, import-key <base64>, ออก/exit, help")
    print("       export-binary / export-morse / import-text <0/1 หรือมอร์ส>, gate-setup / gate-change (รหัสคู่ + หมากรุกจีน + เครื่องดนตรี)")
    print("       seal-key / seal-keyring / unseal-key / key-status (กันขโมยกุญแจจากดิสก์)")
    print("       github-token (พาตั้ง token GitHub ทีละขั้น) / github-token-remove")
    print("       ops-run / ops-status / ops-alerts / ops-report / ops-start [วินาที] / ops-stop / ops-config / ops-set <ชื่อ> <เลข> (Ops Agent ดูแลระบบ)")
    print("       choke-start <ผู้ล็อค> <เป้าหมาย> [victim|away] [left|right] / choke-aim <เป้าหมาย> <victim|away> / choke-counter <เป้าหมาย> / choke-heal <uid> [ส่วน] / choke-state <เป้าหมาย> [ผู้ล็อค]  (ระบบสวนกลับท่าล็อคคอ)")
    while True:
        try:
            raw = input("vmax> " if not VMAX_MCP_STATE["running"] else "vmax[MCP:{}]> ".format(VMAX_MCP_STATE["port"]))
        except (EOFError, KeyboardInterrupt):
            vmax_ops_stop()
            vmax_mcp_stop()
            print()
            break
        cmd = raw.strip().lower()
        matched_import_prefix = next((p for p in _VMAX_MCP_COMMANDS_IMPORT_PREFIXES if cmd.startswith(p)), None)
        matched_text_prefix = next((p for p in _VMAX_MCP_COMMANDS_IMPORT_TEXT_PREFIXES if cmd.startswith(p)), None)
        ops_parts = cmd.split()
        if cmd in _VMAX_MCP_COMMANDS_ON:
            print(vmax_mcp_start())
        elif cmd in _VMAX_MCP_COMMANDS_OFF:
            print(vmax_mcp_stop())
        elif cmd in _VMAX_MCP_COMMANDS_STATUS:
            print(vmax_mcp_status())
        elif ops_parts and ops_parts[0] in _VMAX_OPS_CONSOLE_CMDS:
            _vmax_ops_console_dispatch(ops_parts)
        elif cmd in _VMAX_MCP_COMMANDS_GATE_SETUP:
            _vmax_console_gate_setup()
        elif cmd in _VMAX_MCP_COMMANDS_GATE_CHANGE:
            _vmax_console_gate_change()
        elif cmd in _VMAX_MCP_COMMANDS_GITHUB_TOKEN:
            _vmax_console_github_token()
        elif cmd in _VMAX_MCP_COMMANDS_GITHUB_TOKEN_REMOVE:
            print(vmax_github_token_remove())
        elif cmd in _VMAX_MCP_COMMANDS_KEYSTATUS:
            print(vmax_key_status())
        elif cmd in _VMAX_MCP_COMMANDS_SEAL or cmd in _VMAX_MCP_COMMANDS_SEAL_KEYRING:
            if not vmax_gate_configured():
                print("ต้องตั้งด่านก่อน: พิมพ์ gate-setup")
                continue
            ok_gate, gate_secret = _vmax_console_gate_ok()
            if not ok_gate:
                continue
            print("คำเตือน: ปิดผนึกแล้วไฟล์กุญแจดิบจะถูกลบ ถ้าลืมรหัส 1/รหัส 2/ลำดับหมากรุก = กู้ข้อมูล vault ไม่ได้")
            if input("พิมพ์ YES เพื่อยืนยัน: ").strip() == "YES":
                print(vmax_seal_key(gate_secret, use_keyring=cmd in _VMAX_MCP_COMMANDS_SEAL_KEYRING))
            else:
                print("ยกเลิก")
        elif cmd in _VMAX_MCP_COMMANDS_UNSEAL:
            if not vmax_gate_configured() or not _vmax_console_gate_ok()[0]:
                continue
            print(vmax_unseal_key())
        elif cmd in _VMAX_MCP_COMMANDS_EXPORT:
            if not _vmax_console_gate_ok()[0]:
                continue
            result = vmax_mcp_export_key_base64()
            if result["ok"]:
                print(f"--- base64 ของไฟล์คีย์ ({result['source']}) เก็บไว้ให้ดี ---")
                print(result["base64"])
                print("--- จบ base64 ---")
            else:
                print(result)
        elif cmd in _VMAX_MCP_COMMANDS_EXPORT_BINARY or cmd in _VMAX_MCP_COMMANDS_EXPORT_MORSE:
            import getpass as _vr_getpass
            fn = vmax_mcp_export_key_binary if cmd in _VMAX_MCP_COMMANDS_EXPORT_BINARY else vmax_mcp_export_key_morse
            if vmax_gate_configured():
                ok_gate, gate_secret = _vmax_console_gate_ok()
                if not ok_gate:
                    continue
                result = fn(gate_secret, dual=True)   # ล็อกด้วย รหัส 1 + รหัส 2 + ลำดับหมากรุก
            else:
                pw = _vr_getpass.getpass("passphrase ล็อกคีย์ (เว้นว่าง = ไม่ล็อก แค่เปลี่ยนรูปแบบ | ตั้งรหัสคู่+หมากรุกด้วย gate-setup): ")
                if pw and pw != _vr_getpass.getpass("ยืนยัน passphrase อีกครั้ง: "):
                    print("passphrase ไม่ตรงกัน ยกเลิก")
                    continue
                result = fn(pw or None)
            if result["ok"]:
                print(f"--- {result['format']} ({'ล็อกด้วย passphrase' if result['encrypted'] else 'ไม่ได้ล็อก = ใครได้ไปก็ใช้ได้ทันที'}) ---")
                print(result["text"])
                print("--- จบ ---")
            else:
                print(result)
        elif matched_text_prefix:
            text_arg = raw.strip()[len(matched_text_prefix):].strip()
            fmt = "binary" if matched_text_prefix == "import-bin " else "morse" if matched_text_prefix == "import-morse " else "auto"
            ok_gate, gate_secret = _vmax_console_gate_ok()
            if not ok_gate:
                continue
            result = vmax_mcp_import_key_text(text_arg, fmt=fmt, passphrase=gate_secret, seal_secret=gate_secret)
            if not result["ok"] and result.get("reason") == "gate_required":
                # ข้อความล็อกด้วยรหัสคู่+หมากรุก (จากเครื่องอื่นที่ตั้งด่านไว้) -> ใส่ค่าชุดเดียวกัน ไม่ต้องตั้งด่านในเครื่องนี้ก่อน
                ok2, secret2 = _vmax_console_collect_gate(verify=False)
                result = vmax_mcp_import_key_text(text_arg, fmt=fmt, passphrase=secret2, seal_secret=gate_secret)
            elif not result["ok"] and result.get("reason") == "passphrase_required":
                import getpass as _vr_getpass
                result = vmax_mcp_import_key_text(text_arg, fmt=fmt, passphrase=_vr_getpass.getpass("คีย์นี้ล็อกไว้ ใส่ passphrase: "))
            print(result)
        elif matched_import_prefix:
            # ใช้ raw (ไม่ lower) กันข้อความ base64 ที่ case-sensitive เพี้ยนไป
            if not _vmax_console_gate_ok()[0]:
                continue
            b64_arg = raw.strip()[len(matched_import_prefix):].strip()
            print(vmax_mcp_import_key_base64(b64_arg))
        elif cmd in _VMAX_MCP_COMMANDS_HELP:
            print("เปิด/start | ปิด/stop | สถานะ/status | export-key | import-key <base64> | export-binary | export-morse | import-text <0/1|มอร์ส> | ออก/exit")
            print("ops-run | ops-status | ops-alerts [n] | ops-report | ops-start [วินาที] | ops-stop | ops-config | ops-set <ชื่อ> <เลข>  (ไทย: ตรวจระบบ / สถานะระบบ / แจ้งเตือน / รายงานระบบ)")
        elif cmd in _VMAX_MCP_COMMANDS_EXIT:
            vmax_ops_stop()
            if VMAX_MCP_STATE["running"]:
                vmax_mcp_stop()
            break
        elif cmd == "":
            continue
        else:
            print(f"ไม่รู้จักคำสั่ง: {raw!r} (พิมพ์ help)")


if '--mcp-console' in sys.argv:
    vmax_mcp_console()
    sys.exit(0)


def _run_site_scoped_vault_selftest():
    a = vmax_vault_set_site("example.com", "title", "Example Site", actor="selftest")
    b = vmax_vault_set_site("other.com", "title", "Other Site", actor="selftest")
    assert a["ok"] and b["ok"]
    vmax_relay_sync_all()
    ra = vmax_relay_read_site("example.com", "title")
    rb = vmax_relay_read_site("other.com", "title")
    assert ra["ok"] and ra["value"] == "Example Site"
    assert rb["ok"] and rb["value"] == "Other Site"
    assert ra["value"] != rb["value"]  # ต้องไม่ปนกันข้ามไซต์
    sites = vmax_vault_list_sites()
    assert sites.get("example.com", 0) >= 1 and sites.get("other.com", 0) >= 1
    conn = _vault_db()
    try:
        conn.execute("DELETE FROM vault_kv WHERE key LIKE 'site::example.com::%' OR key LIKE 'site::other.com::%'")
        conn.commit()
    finally:
        conn.close()
    return True


if '--selftest-site-scoped-vault' in sys.argv:
    ok = _run_site_scoped_vault_selftest()
    print("site-scoped-vault selftest:", "OK" if ok else "FAILED")
    sys.exit(0 if ok else 1)


def _run_mcp_auth_selftest():
    import urllib.request as _t_req
    import urllib.error as _t_err

    start = vmax_mcp_start(port=0 or 8799)
    assert start["ok"], start
    token = start["token"]
    base = f"http://127.0.0.1:{start['port']}"
    try:
        # ไม่แนบ token -> ต้องโดน 401
        try:
            _t_req.urlopen(f"{base}/mcp/read?site=test&key=x", timeout=3)
            assert False, "expected 401 without token"
        except _t_err.HTTPError as e:
            assert e.code == 401

        # แนบ token ผิด -> ต้องโดน 401 เช่นกัน
        req_bad = _t_req.Request(f"{base}/mcp/read?site=test&key=x", headers={"X-VMAX-Token": "wrong"})
        try:
            _t_req.urlopen(req_bad, timeout=3)
            assert False, "expected 401 with wrong token"
        except _t_err.HTTPError as e:
            assert e.code == 401

        # แนบ token ถูก -> ต้องผ่าน (key ยังไม่มีก็ต้องตอบ ok:False key_not_found ไม่ใช่ 401)
        req_ok = _t_req.Request(f"{base}/mcp/read?site=test&key=x", headers={"X-VMAX-Token": token})
        resp = _vmc_json.loads(_t_req.urlopen(req_ok, timeout=3).read())
        assert resp.get("reason") in ("key_not_found",) or resp.get("ok") is False or resp.get("ok") is True
    finally:
        vmax_mcp_stop()
    return True


if '--selftest-mcp-auth' in sys.argv:
    ok = _run_mcp_auth_selftest()
    print("mcp-auth selftest:", "OK" if ok else "FAILED")
    sys.exit(0 if ok else 1)


def _run_vault_encryption_selftest():
    secret_marker = "__vmax_plaintext_should_not_appear_on_disk__"
    test_key = "__vault_encryption_selftest_key__"
    vmax_vault_set(test_key, {"secret": secret_marker}, actor="selftest")

    # อ่านไฟล์ .sqlite3 ตรงๆ แบบไบต์ดิบ ต้อง "ไม่เจอ" plaintext อยู่ในนั้นเลย
    raw = _vr_os.path.join(VMAX_VAULT_DIR, "core_vault.sqlite3")
    with open(raw, "rb") as f:
        blob = f.read()
    assert secret_marker.encode("utf-8") not in blob, "พบ plaintext ในไฟล์ .sqlite3 — เข้ารหัสไม่ทำงาน"

    # แต่ผ่าน API ปกติต้องอ่านค่าที่ถูกต้องได้เหมือนเดิม (ถอดรหัสอัตโนมัติ)
    got = vmax_vault_get(test_key)
    assert got and got["value"] == {"secret": secret_marker}

    # คีย์ต้องถูกเก็บแยกไฟล์ สิทธิ์ owner-only
    # คีย์ต้องถูกซ่อนอยู่ในไฟล์ภาพ (steganography) ทั้งไฟล์หลักและไฟล์สำรอง
    assert _vr_os.path.exists(_VMAX_VAULT_KEY_PNG)
    assert _vr_os.path.exists(_VMAX_VAULT_KEY_BACKUP_PNG)
    # ต้องดึงคีย์กลับจากภาพได้ และคีย์จากไฟล์หลัก/สำรองต้องตรงกัน (derive กลับมาได้เหมือนกัน)
    assert _vmax_stego_read_bytes(_VMAX_VAULT_KEY_PNG) == _vmax_stego_read_bytes(_VMAX_VAULT_KEY_BACKUP_PNG)

    conn = _vault_db()
    try:
        conn.execute("DELETE FROM vault_kv WHERE key=?", (test_key,))
        conn.commit()
    finally:
        conn.close()
    return True


if '--selftest-vault-encryption' in sys.argv:
    ok = _run_vault_encryption_selftest()
    print("vault-encryption selftest:", "OK" if ok else "FAILED")
    sys.exit(0 if ok else 1)


