VMAX_AIRSHIP_STORAGE = {}
VMAX_AIRSHIP_STORAGE_CAPACITY = 200.0
VMAX_AIRSHIP_STORAGE_ITEM_CAP = 200


def _vmax_shop_user_id(payload=None):
    payload = payload or {}
    # Authenticated identity wins; never let a request body select another user's wallet/storage.
    auth_uid = getattr(request, "vmax_uid", None)
    if auth_uid:
        return str(auth_uid)
    return str(payload.get("user_id") or payload.get("player_id") or "default_player")


def _vmax_airship_storage(user_id):
    state = VMAX_AIRSHIP_STORAGE.setdefault(user_id, {"items": [], "used_weight": 0.0})
    state.setdefault("items", [])
    state.setdefault("used_weight", 0.0)
    return state


def _vmax_shop_item(shop, item_id):
    for item in shop.get("items", []):
        if item.get("item_id") == item_id:
            return item
    return None


def _vmax_shop_public(shop):
    return {
        "shop_id": shop["shop_id"],
        "game_id": shop["game_id"],
        "name": shop["name"],
        "city_zone": shop["city_zone"],
        "currency": shop.get("currency", "cash"),
        "items": shop.get("items", []),
    }


@app.route('/api/sky-city/game-shops', methods=['GET'])
def vmax_sky_city_game_shops():
    return jsonify({
        "st": "ok",
        "shops": [_vmax_shop_public(shop) for shop in VMAX_SKY_CITY_GAME_SHOPS.values()],
        "storage_capacity": VMAX_AIRSHIP_STORAGE_CAPACITY,
        "storage_item_cap": VMAX_AIRSHIP_STORAGE_ITEM_CAP,
        "note": "ร้านแต่ละเกมสามารถมีสาขาในนครลอยฟ้า และสินค้าที่ซื้อสามารถเก็บบนยานได้",
    })


@app.route('/api/sky-city/game-shops/<shop_id>', methods=['GET'])
def vmax_sky_city_game_shop_detail(shop_id):
    shop = next((x for x in VMAX_SKY_CITY_GAME_SHOPS.values() if x["shop_id"] == shop_id), None)
    if not shop:
        return jsonify({"st": "error", "msg": "ไม่พบสาขาร้านค้า"}), 404
    return jsonify({"st": "ok", "shop": _vmax_shop_public(shop)})


@app.route('/api/sky-city/game-shops/buy', methods=['POST'])
@require_auth
def vmax_sky_city_game_shop_buy():
    payload = request.get_json(silent=True) or {}
    user_id = _vmax_shop_user_id(payload)
    shop_id = str(payload.get("shop_id", ""))
    item_id = str(payload.get("item_id", ""))
    quantity = max(1, min(int(payload.get("quantity", 1)), 100))
    # [SEC-AUDIT round 3] Never trust a client-supplied wallet balance.
    wallet_cash = int(P.get("credits", 0))

    shop = next((x for x in VMAX_SKY_CITY_GAME_SHOPS.values() if x["shop_id"] == shop_id), None)
    if not shop:
        return jsonify({"st": "error", "msg": "ไม่พบร้านค้า"}), 404
    item = _vmax_shop_item(shop, item_id)
    if not item:
        return jsonify({"st": "error", "msg": "ไม่พบสินค้า"}), 404

    total_price = int(item["price"]) * quantity
    total_weight = float(item.get("weight", 0.0)) * quantity
    storage = _vmax_airship_storage(user_id)
    current_count = sum(int(x.get("quantity", 0)) for x in storage["items"])

    if wallet_cash < total_price:
        return jsonify({"st": "error", "msg": "เงินไม่พอ", "required": total_price, "wallet_cash": wallet_cash}), 400
    if storage["used_weight"] + total_weight > VMAX_AIRSHIP_STORAGE_CAPACITY:
        return jsonify({"st": "error", "msg": "พื้นที่เก็บของบนยานไม่พอ", "required_weight": total_weight, "remaining_weight": VMAX_AIRSHIP_STORAGE_CAPACITY - storage["used_weight"]}), 400
    if current_count + quantity > VMAX_AIRSHIP_STORAGE_ITEM_CAP:
        return jsonify({"st": "error", "msg": "จำนวนช่องเก็บของบนยานเต็ม"}), 400

    existing = next((x for x in storage["items"] if x["item_id"] == item_id and x["source_game_id"] == shop["game_id"]), None)
    if existing:
        existing["quantity"] += quantity
    else:
        storage["items"].append({
            "item_id": item_id,
            "name": item["name"],
            "quantity": quantity,
            "weight_each": item.get("weight", 0.0),
            "source_game_id": shop["game_id"],
            "source_shop_id": shop["shop_id"],
            "stored_on": "player_airship",
        })
    P["credits"] = wallet_cash - total_price
    WALLET["balance"] = P["credits"]
    WALLET["history"].append({"ts": time.time(), "source": "sky_city_shop",
                               "shop_id": shop_id, "item": item_id, "quantity": quantity,
                               "price": total_price, "uid": user_id})
    storage["used_weight"] += total_weight

    return jsonify({
        "st": "ok",
        "purchase": {"shop_id": shop_id, "item_id": item_id, "quantity": quantity, "total_price": total_price},
        "storage": storage,
        "wallet_cash_after": P["credits"],
    })


@app.route('/api/airship/storage', methods=['GET'])
@require_auth
def vmax_airship_storage():
    # Private inventory: always resolve the owner from the JWT, never from query string.
    user_id = str(request.vmax_uid)
    storage = _vmax_airship_storage(user_id)
    return jsonify({
        "st": "ok",
        "user_id": user_id,
        "storage": storage,
        "capacity": VMAX_AIRSHIP_STORAGE_CAPACITY,
        "remaining_weight": max(0.0, VMAX_AIRSHIP_STORAGE_CAPACITY - storage["used_weight"]),
    })


@app.route('/api/airship/storage/store', methods=['POST'])
@require_auth
def vmax_airship_storage_store():
    payload = request.get_json(silent=True) or {}
    user_id = _vmax_shop_user_id(payload)
    item_id = str(payload.get("item_id", ""))
    quantity = max(1, min(int(payload.get("quantity", 1)), 100))
    source_game_id = str(payload.get("source_game_id", "unknown"))
    storage = _vmax_airship_storage(user_id)

    # [SEC-AUDIT round 3] Airship storage is a transfer, not an item generator.
    source_inv = GAME_INVENTORY.get(_gk(user_id, source_game_id), {})
    available = int(source_inv.get(item_id, 0)) if isinstance(source_inv, dict) else 0
    source_meta = None
    if isinstance(VMAX_EXTRACTION_AUCTION_BY_ID, dict):
        source_meta = VMAX_EXTRACTION_AUCTION_BY_ID.get(item_id)
    if source_meta is None and isinstance(globals().get("EXTRACTION_ITEM_DB"), dict):
        source_meta = EXTRACTION_ITEM_DB.get(item_id)
    if source_meta is None:
        for _shop in VMAX_SKY_CITY_GAME_SHOPS.values():
            source_meta = _vmax_shop_item(_shop, item_id)
            if source_meta:
                break
    if available < quantity:
        return jsonify({"st": "error", "msg": "ไอเทมในคลังต้นทางไม่พอสำหรับย้ายขึ้นยาน",
                        "available": available, "required": quantity}), 400
    if source_meta is None:
        return jsonify({"st": "error", "msg": "ไม่รู้จักไอเทมนี้จากระบบต้นทาง"}), 400
    name = str(source_meta.get("name") or item_id)
    weight_each = float(source_meta.get("weight", source_meta.get("weight_each", 0.0)))
    total_weight = weight_each * quantity
    current_count = sum(int(x.get("quantity", 0)) for x in storage["items"])
    if storage["used_weight"] + total_weight > VMAX_AIRSHIP_STORAGE_CAPACITY:
        return jsonify({"st": "error", "msg": "พื้นที่เก็บของบนยานไม่พอ"}), 400
    if current_count + quantity > VMAX_AIRSHIP_STORAGE_ITEM_CAP:
        return jsonify({"st": "error", "msg": "จำนวนช่องเก็บของบนยานเต็ม"}), 400
    existing = next((x for x in storage["items"] if x["item_id"] == item_id and x["source_game_id"] == source_game_id), None)
    if existing:
        existing["quantity"] += quantity
    else:
        storage["items"].append({"item_id": item_id, "name": name, "quantity": quantity, "weight_each": weight_each, "source_game_id": source_game_id, "stored_on": "player_airship"})
    source_inv[item_id] = available - quantity
    storage["used_weight"] += total_weight
    return jsonify({"st": "ok", "storage": storage})


VMAX_MODULES["cross_game_sky_city_shops"] = {
    "name": "Cross-Game Sky City Shops + Airship Storage",
    "status": "active",
    "shop_count": len(VMAX_SKY_CITY_GAME_SHOPS),
    "storage_capacity": VMAX_AIRSHIP_STORAGE_CAPACITY,
    "features": ["multi_game_branches", "sky_city_shopping", "airship_storage", "shared_world_inventory"],
}


# ============================================================================
# VMAX SHARED CPU POOL + DUAL-CHIP INTERCONNECT
# ----------------------------------------------------------------------------
# โมดูลนี้เป็น "application-level CPU access layer" สำหรับแนวคิดในแบบ:
#   Website/Game A ----\
#                        > shared CPU pool -> Chip 0 / Chip 1
#   Website/Game B ----/                 \-> direct logical interconnect
#
# ไม่อ้างว่า Python สามารถสร้าง CPU จริง/zero-hardware-latency ได้
# แต่จำลองการจัดสรร compute แบบสอง logical chips ที่อยู่ใน pool เดียวกัน
# ให้ทุกโมดูลใน process เดียวกันใช้ scheduler/lease ชุดเดียวกันได้
#
# จุดแทรก: ต่อท้ายทุก game/web module และ "ก่อน" __main__ โดยตั้งใจ
# เพื่อให้ class/route/module ทั้งหมดในไฟล์ถูกประกาศครบก่อน server start
# และไม่ไปแก้ state/gameplay ของโมดูลเดิมโดยตรง
# ============================================================================

import time as _vcpu_time
import uuid as _vcp_uuid
import threading as _vcp_threading
from collections import deque as _vcp_deque

class VMAXSharedCPUInterconnect:
    """Direct logical message path between the two CPU chips.

    เป็น in-process mailbox ไม่ผ่าน HTTP/router/database จึงไม่มี network hop
    ระหว่าง Chip 0 และ Chip 1 ใน process เดียวกัน
    """

    def __init__(self, chip_count=2, max_queue=4096):
        chip_count = int(chip_count)
        if chip_count != 2:
            raise ValueError("VMAX dual-chip interconnect requires exactly 2 chips")
        self.chip_count = chip_count
        self.max_queue = max(1, int(max_queue))
        self._lock = _vcp_threading.RLock()
        self._queues = {0: _vcp_deque(maxlen=self.max_queue),
                        1: _vcp_deque(maxlen=self.max_queue)}
        self._seq = 0
        self._sent = 0
        self._dropped = 0

    def send(self, source_chip, target_chip, payload=None):
        source_chip = int(source_chip)
        target_chip = int(target_chip)
        if source_chip not in (0, 1) or target_chip not in (0, 1):
            raise ValueError("chip id must be 0 or 1")
        if source_chip == target_chip:
            raise ValueError("interconnect target must be the other chip")
        with self._lock:
            self._seq += 1
            msg = {
                "id": _vcp_uuid.uuid4().hex,
                "seq": self._seq,
                "source_chip": source_chip,
                "target_chip": target_chip,
                "payload": payload,
                "created_at": _vcpu_time.time(),
            }
            q = self._queues[target_chip]
            if len(q) >= self.max_queue:
                self._dropped += 1
                return {"ok": False, "reason": "interconnect_queue_full"}
            q.append(msg)
            self._sent += 1
            return {"ok": True, "message": dict(msg)}

    def receive(self, chip_id, limit=64):
        chip_id = int(chip_id)
        if chip_id not in (0, 1):
            raise ValueError("chip id must be 0 or 1")
        limit = max(1, int(limit))
        out = []
        with self._lock:
            q = self._queues[chip_id]
            while q and len(out) < limit:
                msg = q.popleft()
                msg["delivered_at"] = _vcpu_time.time()
                out.append(msg)
        return out

    def status(self):
        with self._lock:
            return {
                "chips": self.chip_count,
                "queues": {str(k): len(v) for k, v in self._queues.items()},
                "sent": self._sent,
                "dropped": self._dropped,
                "transport": "in-process-direct-logical-interconnect",
                "external_network_hop": False,
            }


class VMAXSharedCPUPool:
    """Thread-safe shared compute pool with two logical CPU chips.

    งานที่ขอ CPU จะได้ lease ก่อน จากนั้น caller ใช้ lease เป็นสิทธิ์เชิง
    logical ในการทำงาน ไม่ได้เปิดช่องให้ส่ง Python code/string เข้าไป execute
    เพื่อความปลอดภัยและเพื่อไม่ให้โมดูลเกมอื่นถูกเรียกข้ามกันโดยตรง
    """

    def __init__(self, chips=2, units_per_chip=4, max_leases=1024):
        if int(chips) != 2:
            raise ValueError("VMAXSharedCPUPool is a dual-chip pool")
        self.chips = 2
        self.units_per_chip = max(1, int(units_per_chip))
        self.total_units = self.chips * self.units_per_chip
        self.max_leases = max(1, int(max_leases))
        self._lock = _vcp_threading.RLock()
        self._leases = {}
        self._used_by_chip = {0: 0, 1: 0}
        self._chip_health = {0: "online", 1: "online"}
        self._rr = 0
        self.interconnect = VMAXSharedCPUInterconnect(2)

    def _choose_chip(self, preferred=None):
        if preferred is not None:
            chip = int(preferred)
            if chip not in (0, 1):
                raise ValueError("chip_preference must be 0 or 1")
            return chip
        # Pick the least-loaded healthy chip; round-robin breaks ties.
        candidates = [c for c in (0, 1) if self._chip_health[c] == "online"]
        if not candidates:
            return None
        min_used = min(self._used_by_chip[c] for c in candidates)
        tied = [c for c in candidates if self._used_by_chip[c] == min_used]
        chip = tied[self._rr % len(tied)]
        self._rr += 1
        return chip

    def acquire(self, owner, units=1, chip_preference=None, metadata=None):
        owner = str(owner or "").strip()
        units = int(units)
        if not owner:
            return {"ok": False, "reason": "owner_required"}
        if units <= 0 or units > self.units_per_chip:
            return {"ok": False, "reason": "invalid_units"}
        with self._lock:
            if len(self._leases) >= self.max_leases:
                return {"ok": False, "reason": "lease_limit"}
            chip = self._choose_chip(chip_preference)
            if chip is None:
                return {"ok": False, "reason": "all_chips_offline"}
            if self._used_by_chip[chip] + units > self.units_per_chip:
                # Try the other chip when the preferred/default choice is full.
                other = 1 - chip
                if self._chip_health[other] == "online" and self._used_by_chip[other] + units <= self.units_per_chip:
                    chip = other
                else:
                    return {"ok": False, "reason": "cpu_pool_busy"}
            lease_id = _vcp_uuid.uuid4().hex
            lease = {
                "lease_id": lease_id,
                "owner": owner,
                "chip": chip,
                "units": units,
                "metadata": dict(metadata or {}),
                "created_at": _vcpu_time.time(),
            }
            self._leases[lease_id] = lease
            self._used_by_chip[chip] += units
            return {"ok": True, "lease": dict(lease)}

    def release(self, lease_id):
        with self._lock:
            lease = self._leases.pop(str(lease_id), None)
            if lease is None:
                return {"ok": False, "reason": "lease_not_found"}
            chip = int(lease["chip"])
            self._used_by_chip[chip] = max(0, self._used_by_chip[chip] - int(lease["units"]))
            return {"ok": True, "released": lease}

    def set_chip_health(self, chip_id, health):
        chip_id = int(chip_id)
        health = str(health)
        if chip_id not in (0, 1) or health not in ("online", "offline", "degraded"):
            raise ValueError("invalid chip health")
        with self._lock:
            self._chip_health[chip_id] = health
            return {"ok": True, "chip": chip_id, "health": health}

    def status(self):
        with self._lock:
            return {
                "model": "shared-central-cpu-pool",
                "chips": 2,
                "units_per_chip": self.units_per_chip,
                "total_units": self.total_units,
                "used_units": sum(self._used_by_chip.values()),
                "free_units": self.total_units - sum(self._used_by_chip.values()),
                "used_by_chip": {str(k): v for k, v in self._used_by_chip.items()},
                "chip_health": {str(k): v for k, v in self._chip_health.items()},
                "active_leases": len(self._leases),
                "interconnect": self.interconnect.status(),
            }

    def route_work(self, owner, operation, units=1, chip_preference=None, metadata=None):
        """Allocate a short-lived compute lease without executing arbitrary code."""
        lease_result = self.acquire(owner, units, chip_preference, metadata)
        if not lease_result.get("ok"):
            return lease_result
        lease = lease_result["lease"]
        try:
            return {
                "ok": True,
                "operation": str(operation),
                "chip": lease["chip"],
                "units": lease["units"],
                "lease_id": lease["lease_id"],
                "shared_pool": True,
            }
        finally:
            self.release(lease["lease_id"])


_VMAX_SHARED_CPU_POOL = VMAXSharedCPUPool(
    chips=2,
    units_per_chip=int(os.environ.get("VMAX_CPU_UNITS_PER_CHIP", "4")),
)

def vmax_shared_cpu_pool():
    """คืน shared CPU pool เดียวสำหรับทุก module ใน process นี้."""
    return _VMAX_SHARED_CPU_POOL

# Connect it to the existing central registry without replacing the registry
# or creating a second API/engine connection.
try:
    VMAXSharedCentralModuleRegistry.register("shared_cpu_pool", _VMAX_SHARED_CPU_POOL)
    VMAXSharedCentralModuleRegistry.register("dual_chip_interconnect", _VMAX_SHARED_CPU_POOL.interconnect)
except Exception as _vcp_registry_exc:
    print("[VMAX CPU Pool] registry attach skipped:", _vcp_registry_exc)

