@app.route("/api/cpu-pool/status", methods=["GET"])
def api_cpu_pool_status():
    return jsonify(vmax_shared_cpu_pool().status())

@app.route("/api/cpu-pool/acquire", methods=["POST"])
@require_auth_toggleable
def api_cpu_pool_acquire():
    body = request.get_json(silent=True) or {}
    owner = str(body.get("owner") or body.get("uid") or "").strip()
    if not owner:
        return jsonify({"ok": False, "reason": "owner_required"}), 400
    result = vmax_shared_cpu_pool().acquire(
        owner=owner,
        units=body.get("units", 1),
        chip_preference=body.get("chip_preference"),
        metadata=body.get("metadata") if isinstance(body.get("metadata"), dict) else {},
    )
    return jsonify(result), (200 if result.get("ok") else 409)

@app.route("/api/cpu-pool/release", methods=["POST"])
@require_auth_toggleable
def api_cpu_pool_release():
    body = request.get_json(silent=True) or {}
    result = vmax_shared_cpu_pool().release(body.get("lease_id"))
    return jsonify(result), (200 if result.get("ok") else 404)

@app.route("/api/cpu-pool/interconnect", methods=["POST"])
@require_auth_toggleable
def api_cpu_pool_interconnect():
    body = request.get_json(silent=True) or {}
    try:
        result = vmax_shared_cpu_pool().interconnect.send(
            body.get("source_chip"),
            body.get("target_chip"),
            body.get("payload"),
        )
        return jsonify(result), (200 if result.get("ok") else 409)
    except (TypeError, ValueError) as exc:
        return jsonify({"ok": False, "reason": str(exc)}), 400

@app.route("/api/cpu-pool/interconnect/<int:chip_id>", methods=["GET"])
@require_auth_toggleable
def api_cpu_pool_interconnect_receive(chip_id):
    try:
        return jsonify({
            "ok": True,
            "messages": vmax_shared_cpu_pool().interconnect.receive(chip_id),
        })
    except ValueError as exc:
        return jsonify({"ok": False, "reason": str(exc)}), 400


def _run_shared_cpu_pool_selftest():
    """End-to-end in-process test: pool -> two chips -> interconnect -> release."""
    pool = VMAXSharedCPUPool(chips=2, units_per_chip=2, max_leases=16)
    a = pool.acquire("selftest-A", units=1, chip_preference=0)
    b = pool.acquire("selftest-B", units=1, chip_preference=1)
    assert a["ok"] and b["ok"]
    assert a["lease"]["chip"] == 0 and b["lease"]["chip"] == 1

    msg = pool.interconnect.send(0, 1, {"event": "cpu_sync", "value": 42})
    assert msg["ok"]
    received = pool.interconnect.receive(1)
    assert len(received) == 1 and received[0]["payload"]["value"] == 42

    assert pool.release(a["lease"]["lease_id"])["ok"]
    assert pool.release(b["lease"]["lease_id"])["ok"]
    st = pool.status()
    assert st["used_units"] == 0 and st["free_units"] == 4
    assert st["chip_health"]["0"] == "online"
    assert st["chip_health"]["1"] == "online"
    return {
        "ok": True,
        "checks": [
            "dual-chip allocation",
            "shared pool accounting",
            "direct logical interconnect",
            "lease release / no leaked CPU units",
            "chip health state",
        ],
        "status": st,
    }


def _run_shared_cpu_pool_http_selftest():
    """Test the real Flask routes with app.test_client()."""
    c = app.test_client()
    status = c.get("/api/cpu-pool/status")
    assert status.status_code == 200
    payload = status.get_json()
    assert payload["chips"] == 2

    # Auth toggle is respected. If auth is enabled, this route should reject
    # without credentials rather than silently bypassing the application's gate.
    acquire = c.post(
        "/api/cpu-pool/acquire",
        json={"owner": "__cpu_http_selftest__", "units": 1},
    )
    assert acquire.status_code in (200, 401, 403, 409)
    if acquire.status_code == 200:
        lease = acquire.get_json()["lease"]["lease_id"]
        release = c.post("/api/cpu-pool/release", json={"lease_id": lease})
        assert release.status_code == 200
    return {
        "ok": True,
        "status_endpoint": status.status_code,
        "acquire_endpoint": acquire.status_code,
    }

# ============================================================================
# VMAX EXTRACTION SHOOTER — BALANCE / STAGGER / RAGDOLL-RECOVERY SYSTEM
# ----------------------------------------------------------------------------
# ต่อยอดจาก VMAXFlashlightResistanceGlasses / VMAXStunRecoverySystem เดิม
# (ที่เคยอยู่หลัง `if __name__=='__main__':` เลยไม่เคยถูกลงทะเบียนจริงตอนรันเซิร์ฟเวอร์
# — ดูหมายเหตุที่บรรทัด ~63110 ของไฟล์นี้) ย้ายมาไว้ก่อน main guard และทำให้สมบูรณ์
# พร้อมเชื่อมเข้ากับเกม "Extraction Boss Raid" (ยิง/เก็บของ/หนี) ที่มีอยู่แล้วในไฟล์นี้จริง ๆ
#
# กลไกรวม 2 แบบจากที่คุยกันไว้:
#   1) State-based switching: พอโดนสตัน (balance <= 0) ปุ่มเดินหน้าจะเปลี่ยนความหมาย
#      ไปเป็น "เติมเกจฟื้นตัว" ชั่วคราว — ถ้ากดค้างเฉย ๆ ตัวละครจะโซเซ/ล้มในที่สุด
#   2) Input blending: ระหว่างสตัน ทิศทางที่ผู้เล่นสั่งจะถูกผสมกับการสุ่มส่าย (ragdoll
#      wobble) และคูณความเร็วลดลงเสมอ — ยิ่งกดรัว (mash) มุมส่ายจะแคบลงและความเร็ว
#      จะเพิ่มขึ้น ให้ความรู้สึก "พยายามฝืนทรงตัว" แทนที่จะสลับโหมดเดินแบบขาวดำ
# ============================================================================
import math as _stagger_math
import random as _stagger_random
import time as _stagger_time


class VMAXFlashlightResistanceGlasses:
    ITEM_ID = "tactical_anti_flash_glasses"
    FLASH_REDUCTION = 0.70
    STUN_REDUCTION = 0.50

    @staticmethod
    def apply(player_state, flash_duration, stun_duration):
        if player_state.get("glasses_equipped", False):
            flash_duration *= (1.0 - VMAXFlashlightResistanceGlasses.FLASH_REDUCTION)
            stun_duration *= (1.0 - VMAXFlashlightResistanceGlasses.STUN_REDUCTION)
        return flash_duration, stun_duration


class VMAXBalanceRecoverySystem:
    """Balance/stagger/ragdoll-recovery for the extraction shooter.

    Works on any plain dict (e.g. the extraction game's own per-player `st`
    dict from VMAX_NEW_GAME_STATE) — no separate storage needed, so it can be
    reused by other games in this file too.
    """

    default_balance = 100.0

    # -- ปรับจูนตรงนี้ได้ทั้งหมด --
    BASE_SLOW = 0.22               # ความเร็วที่เหลือเมื่อกดค้างเฉย ๆ ระหว่างสตัน (22%)
    MASH_SPEED_GAIN = 0.09         # ความเร็วเพิ่มต่อ (ครั้ง/วินาที) ที่กดรัว
    MAX_MOVE_MULT = 0.85           # เพดานความเร็วสูงสุดระหว่างยังสตันอยู่ (ไม่มีวันเต็ม 100%)
    MAX_DEVIATION_DEG = 30.0       # มุมส่ายแบบ ragdoll สูงสุด (กดค้างเฉย ๆ)
    MIN_DEVIATION_DEG = 4.0        # มุมส่ายต่ำสุด (กดรัวเก่งมาก)
    MASH_DEVIATION_REDUCTION = 4.0
    MIN_MASH_RATE_TO_STAND = 1.5   # ต้องกดเร็วกว่านี้ (ครั้ง/วิ) ไม่งั้นล้มคว่ำ
    FALL_GRACE_SECONDS = 1.4       # เผื่อเวลาก่อนจะตัดสินว่า "ล้ม" จริง
    TAP_WINDOW = 1.2               # หน้าต่างเวลาที่ใช้คำนวณอัตรารัว
    RECOVERY_PER_TAP = 9.0
    GETUP_TAPS_REQUIRED = 4        # ต้องรัวกี่ครั้งถึงจะลุกจากล้มคว่ำ
    SHAKE_DECAY_PER_SEC = 0.6
    PASSIVE_REGEN_PER_SEC = 4.0    # ตัวสมดุลค่อย ๆ ฟื้นเองเมื่อไม่ได้สตัน/ล้ม

    def ensure_state(self, player):
        player.setdefault("balance", self.default_balance)
        player.setdefault("max_balance", self.default_balance)
        player.setdefault("stunned", False)
        player.setdefault("fallen", False)
        player.setdefault("recovery_meter", 0.0)
        player.setdefault("camera_shake", 0.0)
        player.setdefault("glasses_equipped", False)
        player.setdefault("_tap_times", [])
        player.setdefault("_getup_taps", 0)
        return player

    def _decay(self, player, now):
        last = player.get("_last_tick_at")
        player["_last_tick_at"] = now
        if last is None:
            return
        dt = max(0.0, min(1.0, now - last))
        if player.get("camera_shake", 0.0) > 0.0:
            player["camera_shake"] = max(0.0, player["camera_shake"] - self.SHAKE_DECAY_PER_SEC * dt)
        if not player.get("stunned") and not player.get("fallen"):
            player["balance"] = min(player.get("max_balance", self.default_balance),
                                     player.get("balance", self.default_balance) + self.PASSIVE_REGEN_PER_SEC * dt)

    def _tap_rate(self, player, now):
        taps = [t for t in player.get("_tap_times", []) if now - t <= self.TAP_WINDOW]
        player["_tap_times"] = taps
        if not taps:
            return 0.0
        return len(taps) / self.TAP_WINDOW

    def apply_stagger_force(self, player, force, now=None):
        """Reduce balance by `force` (0-100ish). Crossing 0 triggers a stun."""
        self.ensure_state(player)
        now = now if now is not None else _stagger_time.time()
        self._decay(player, now)
        player["balance"] = max(0.0, player.get("balance", self.default_balance) - float(force))
        player["camera_shake"] = min(1.0, player.get("camera_shake", 0.0) + float(force) / 100.0)
        if player["balance"] <= 0.0 and not player.get("stunned") and not player.get("fallen"):
            player["stunned"] = True
            player["recovery_meter"] = 0.0
            player["_tap_times"] = []
            player["stagger_started_at"] = now
        return {"balance": player["balance"], "stunned": player["stunned"],
                "camera_shake": player["camera_shake"]}

    def apply_explosion(self, player, distance, explosive_type=None, now=None):
        """Stagger caused by a real explosive from VMAX_EXPLOSIVE_PROFILES.

        Re-uses the same distance/profile math as the armor-damage system
        (`_vmax_blast_damage_fraction`) so "how close was the blast" behaves
        identically for armor damage and for stagger. Flashbangs carry zero
        armor damage by design (see VMAX_EXPLOSIVE_PROFILES), so they use
        their own short flash/stun-only falloff instead.
        """
        self.ensure_state(player)
        explosive_type = explosive_type or VMAX_DEFAULT_EXPLOSIVE_TYPE
        profile = VMAX_EXPLOSIVE_PROFILES.get(explosive_type, VMAX_EXPLOSIVE_PROFILES[VMAX_DEFAULT_EXPLOSIVE_TYPE])
        if explosive_type == "flashbang":
            fb_range = 8.0
            fraction = max(0.0, 1.0 - (max(0.0, float(distance)) / fb_range))
            force = fraction * 85.0
            if player.get("glasses_equipped"):
                _flash, stun_scale = VMAXFlashlightResistanceGlasses.apply(
                    {"glasses_equipped": True}, flash_duration=1.0, stun_duration=1.0)
                force *= stun_scale
        else:
            fraction = _vmax_blast_damage_fraction(distance, profile)
            force = fraction * 100.0
        result = self.apply_stagger_force(player, force, now=now)
        result.update({"explosive_type": explosive_type, "distance": float(distance),
                        "force": force, "name_th": profile.get("name_th", explosive_type)})
        return result

    def register_input_tap(self, player, now=None):
        """Call once per movement key-press (not per held frame) while stunned
        or fallen — this is the "กด W รัว ๆ เพื่อฟื้นตัว" QTE input."""
        self.ensure_state(player)
        now = now if now is not None else _stagger_time.time()
        self._decay(player, now)
        taps = player.setdefault("_tap_times", [])
        taps.append(now)
        cutoff = now - self.TAP_WINDOW
        player["_tap_times"] = [t for t in taps if t >= cutoff]

        if player.get("fallen"):
            player["_getup_taps"] = player.get("_getup_taps", 0) + 1
            if player["_getup_taps"] >= self.GETUP_TAPS_REQUIRED:
                player["fallen"] = False
                player["_getup_taps"] = 0
                player["stunned"] = True  # ลุกขึ้นได้แต่ยังโซเซ ต้องรัวต่ออีกนิด
                player["recovery_meter"] = 30.0
                player["stagger_started_at"] = now
                return {"recovered": False, "standing_up": True, "fallen": False}
            return {"recovered": False, "standing_up": True, "fallen": True}

        if not player.get("stunned"):
            return {"recovered": False, "standing_up": False, "fallen": False}

        tap_rate = self._tap_rate(player, now)
        gain = self.RECOVERY_PER_TAP * (1.0 + min(tap_rate / 6.0, 1.5))
        player["recovery_meter"] = min(100.0, player.get("recovery_meter", 0.0) + gain)
        if player["recovery_meter"] >= 100.0:
            player["stunned"] = False
            player["recovery_meter"] = 0.0
            player["balance"] = player.get("max_balance", self.default_balance) * 0.5
            return {"recovered": True, "standing_up": False, "fallen": False}
        return {"recovered": False, "standing_up": False, "fallen": False}

    def compute_movement(self, player, dx, dy, now=None):
        """Take the player's intended direction (dx, dy) and return the
        actual (dx, dy, speed_multiplier, deviation_deg) after applying
        stagger/ragdoll blending. Call this from the movement endpoint
        instead of using the raw dx/dy directly while stunned/fallen."""
        self.ensure_state(player)
        now = now if now is not None else _stagger_time.time()
        self._decay(player, now)

        if player.get("fallen"):
            return 0.0, 0.0, 0.0, 0.0

        if not player.get("stunned"):
            return dx, dy, 1.0, 0.0

        tap_rate = self._tap_rate(player, now)
        speed_mult = min(self.MAX_MOVE_MULT, self.BASE_SLOW + tap_rate * self.MASH_SPEED_GAIN)
        deviation_deg = max(self.MIN_DEVIATION_DEG,
                             self.MAX_DEVIATION_DEG - tap_rate * self.MASH_DEVIATION_REDUCTION)

        theta = _stagger_math.radians(_stagger_random.uniform(-deviation_deg, deviation_deg))
        cos_t, sin_t = _stagger_math.cos(theta), _stagger_math.sin(theta)
        ndx = dx * cos_t - dy * sin_t
        ndy = dx * sin_t + dy * cos_t

        since_stagger = now - float(player.get("stagger_started_at", now))
        if tap_rate < self.MIN_MASH_RATE_TO_STAND and since_stagger > self.FALL_GRACE_SECONDS:
            player["fallen"] = True
            player["_getup_taps"] = 0
            return 0.0, 0.0, 0.0, deviation_deg

        return ndx, ndy, speed_mult, deviation_deg

    def equip_glasses(self, player, equipped=True):
        self.ensure_state(player)
        player["glasses_equipped"] = bool(equipped)
        return player["glasses_equipped"]

    def public_view(self, player):
        """HUD-safe snapshot (no internal tap-timestamp bookkeeping)."""
        self.ensure_state(player)
        return {
            "balance": round(player["balance"], 1),
            "max_balance": player["max_balance"],
            "stunned": player["stunned"],
            "fallen": player["fallen"],
            "recovery_meter": round(player["recovery_meter"], 1),
            "camera_shake": round(player["camera_shake"], 2),
            "glasses_equipped": player["glasses_equipped"],
        }


# ตัวจริงตัวเดียวที่ใช้ทั้งไฟล์ — ผูกกับ dict ของผู้เล่นแต่ละคนตรง ๆ (เช่น `st` ของ
# Extraction Boss Raid) จึงไม่ต้องมี storage แยกเป็นของตัวเอง
VMAX_BALANCE = VMAXBalanceRecoverySystem()

# เก็บ backward-compat ชื่อเดิมไว้เผื่อโค้ดที่อื่นอ้างถึง (ตัวจริงคือ VMAX_BALANCE ด้านบน)
VMAXStunRecoverySystem = VMAXBalanceRecoverySystem


# ----------------------------------------------------------------------------
# เชื่อมเข้ากับ Extraction Boss Raid จริง — ต่อ endpoint เดิมที่มีอยู่แล้ว แทนที่จะ
# แก้โค้ดเดิมตรง ๆ (ปลอดภัยกว่า ไม่เสี่ยงพังของเดิม/ของ selftest เดิม)
# ----------------------------------------------------------------------------

def api_vmax_new_game_move_with_stagger():
    """แทนที่ view function เดิมของ /api/new-game/extraction/move — ไม่ต้องแก้
    HTML/JS ฝั่ง client เลยสักบรรทัด: ทุกครั้งที่ joystick เดิมส่ง dx/dy ที่ไม่ใช่ศูนย์
    เข้ามาระหว่างผู้เล่นกำลังสตัน/ล้มคว่ำ ระบบจะถือว่านั่นคือ "ความพยายามขยับ/รัวหนึ่ง
    ครั้ง" ในตัวเอง แล้วป้อนเข้า register_input_tap ให้อัตโนมัติ (ยิ่งผู้เล่นสั่น/ลาก
    joystick ถี่แค่ไหน endpoint เดิมนี้ก็จะถูกยิงถี่แค่นั้น เกจฟื้นตัวก็ขึ้นไวตามไปด้วย)
    จากนั้นค่อยเอาทิศทางไปผสม (blend) กับสถานะ balance/stagger ก่อนขยับตัวละครจริง
    endpoint /stagger/mash ที่มีแยกไว้ยังใช้ได้เผื่ออนาคตอยากทำปุ่มกดเฉพาะ แต่ไม่จำเป็น
    ต้องเรียกเลยถ้าไม่อยากแก้หน้าเกม"""
    b = request.get_json(silent=True) or {}
    uid = str(getattr(request, 'vmax_uid', None) or b.get('uid') or 'guest')
    st = _vmax_new_game_state(uid)
    VMAX_BALANCE.ensure_state(st)
    if st['status'] != 'raid':
        return jsonify({"st": "error", "msg": "ยังไม่ได้อยู่ใน Raid"}), 400
    dx, dy = float(b.get('dx', 0)), float(b.get('dy', 0))
    now = time.time()
    has_intent = (dx != 0.0 or dy != 0.0)
    tap_result = None
    if has_intent and (st.get('stunned') or st.get('fallen')):
        tap_result = VMAX_BALANCE.register_input_tap(st, now=now)
    ndx, ndy, speed_mult, deviation_deg = VMAX_BALANCE.compute_movement(st, dx, dy, now)
    mag = (ndx * ndx + ndy * ndy) ** 0.5
    base_speed = 18.0
    if mag > 1e-6:
        step = base_speed * speed_mult
        st['x'] = max(30.0, min(870.0, st['x'] + ndx / mag * step))
        st['y'] = max(40.0, min(530.0, st['y'] + ndy / mag * step))
    if st.get('mode') == 'zombie':
        # เสียงฝีเท้าโซเซดังกว่าเดินปกติ — ระบบเดิมของ zombie hearing เอาไปใช้ต่อได้เลย
        noise_radius = 70.0 if not st.get('stunned') else 150.0
        st.setdefault('noise_events', []).append(
            {'x': st['x'], 'y': st['y'], 'type': 'footstep', 'at': now, 'radius': noise_radius})
    if tap_result and tap_result.get('recovered'):
        st['message'] = 'ฟื้นตัวสำเร็จ — ทรงตัวได้แล้ว!'
    elif tap_result and tap_result.get('standing_up') and not st.get('fallen'):
        st['message'] = 'ลุกขึ้นได้แล้ว แต่ยังโซเซอยู่ — ฝืนเดินต่อ!'
    elif st.get('fallen'):
        st['message'] = 'ล้มคว่ำกับพื้น! ขยับ/สั่น joystick รัว ๆ เพื่อลุกขึ้น'
    elif st.get('stunned') and deviation_deg > 0:
        st['message'] = 'โดนสตัน — สั่น/ลาก joystick รัว ๆ เพื่อพยุงตัวและฝืนเดินหน้า!'
    return jsonify({"st": "ok", "game": _vmax_new_game_snapshot(uid)})


if 'api_vmax_new_game_move' in app.view_functions:
    app.view_functions['api_vmax_new_game_move'] = api_vmax_new_game_move_with_stagger


