# ==========================================
# [ Extraction: คลังเก็บของ -> จัด Loadout ก่อนเข้าแมพ -> ใส่กระเป๋า (กินช่อง) -> ติดตั้งในมือ ]
# ลำดับ: 1) ซื้อ/มีของในคลัง (stash = storage_box ของผู้เล่น)  2) ก่อนเริ่ม Raid จัด loadout หยิบจากคลังไปใส่กระเป๋า
#        3) เริ่ม Raid: ของใน loadout ลงกระเป๋า กินน้ำหนัก/ช่อง (เพดาน 12 ร่วมกับของลูท)  4) ในแมพ "ติดตั้ง" ลงมือ (เบิกจากกระเป๋า)
#        5) Extract สำเร็จ ของ gear ทั้งในกระเป๋า/ในมือกลับเข้าคลัง ; ตาย = หายพร้อมของลูท
# ของ gear แยกจาก VMAX_NEW_GAME_LOOT (ไม่ถูกสุ่มเป็นลูท ไม่ถูกขายตอน Extract)
# ==========================================
VMAX_RAID_BAG_CAPACITY = 12
VMAX_RAID_GEAR = {
    "combat_knife":  {"name_th": "มีดทหาร (Combat Knife)", "weight": 1, "price": 400, "slot": "melee", "glass_breaker": True,
                      "desc_th": "ตูดมีดมีหมุดทุบกระจกทังสเตนคาร์ไบด์ ทุบกระจกนิรภัยได้"},
    "utility_knife": {"name_th": "มีดพับอเนกประสงค์", "weight": 1, "price": 120, "slot": "melee", "glass_breaker": False,
                      "desc_th": "ใบมีดอย่างเดียว ไม่มีหมุดทุบกระจก"},
}
VMAX_RAID_LOADOUT_MAX_ITEMS = 4


def _vmax_gear_stash(uid: str) -> dict:
    """คลัง = storage_box ของผู้เล่น -> {item_id: qty} เฉพาะของ gear"""
    box = storage_get(uid)["storage_box"]
    out = {}
    for slot in box.values():
        if slot["item"] in VMAX_RAID_GEAR:
            out[slot["item"]] = out.get(slot["item"], 0) + slot["qty"]
    return out


def _vmax_gear_stash_take(uid: str, item_id: str, qty: int = 1) -> bool:
    if _vmax_gear_stash(uid).get(item_id, 0) < qty:
        return False
    box = storage_get(uid)["storage_box"]
    remaining = qty
    for slot in list(box.values()):
        if remaining <= 0:
            break
        if slot["item"] == item_id:
            t = min(slot["qty"], remaining)
            slot["qty"] -= t
            remaining -= t
    st = storage_get(uid)
    st["storage_box"] = {k: v for k, v in st["storage_box"].items() if v["qty"] > 0}
    return True


def _vmax_gear_stash_put(uid: str, item_id: str, qty: int = 1):
    _storage_add_item(storage_get(uid), "storage_box", item_id, qty)


def _vmax_gear_bag_weight(st: dict) -> int:
    return sum(VMAX_RAID_GEAR[i]["weight"] for i in st.get("gear_bag", []) if i in VMAX_RAID_GEAR)


def _vmax_gear_load_into_bag(uid: str, st: dict):
    """เรียกตอนเริ่ม Raid: ย้าย loadout เข้ากระเป๋า (กินช่อง) และล้างของมือ"""
    for i in list(st.get("loadout", [])) + ([st["loadout_hand"]] if st.get("loadout_hand") else []):
        if _vmax_gear_expired(i):                 # ซีซั่นจบระหว่างที่จัด loadout ไว้: คืนเข้าคลัง ไม่พาเข้าแมพ
            _vmax_gear_stash_put(uid, i, 1)
            if i in st.get("loadout", []):
                st["loadout"].remove(i)
            if st.get("loadout_hand") == i:
                st["loadout_hand"] = None
    st["gear_bag"] = list(st.get("loadout", []))
    st["equipped"] = st.get("loadout_hand")      # ถ้าตั้งไว้ถือในมือตั้งแต่ต้น ก็ติดตั้งให้เลย (ไม่กินช่องกระเป๋า)
    st["loadout"] = []
    st["loadout_hand"] = None


def _vmax_gear_return_to_stash(uid: str, st: dict):
    """เรียกตอน Extract สำเร็จ: gear ในกระเป๋า + ในมือ กลับเข้าคลัง"""
    for item_id in list(st.get("gear_bag", [])) + ([st["equipped"]] if st.get("equipped") else []):
        if item_id in VMAX_RAID_GEAR:
            _vmax_gear_stash_put(uid, item_id, 1)
    st["gear_bag"], st["equipped"] = [], None


def _vmax_gear_view(uid: str, st: dict) -> dict:
    return {"catalog": VMAX_RAID_GEAR, "stash": _vmax_gear_stash(uid), "loadout": st.get("loadout", []), "loadout_hand": st.get("loadout_hand"),
            "gear_bag": st.get("gear_bag", []), "equipped": st.get("equipped"),
            "expired": [k for k in VMAX_RAID_GEAR if _vmax_gear_expired(k)], "bag_capacity": VMAX_RAID_BAG_CAPACITY, "game_cash": st.get("game_cash", 0)}


def _vmax_uid_from(b: dict) -> str:
    return str(getattr(request, 'vmax_uid', None) or b.get('uid') or request.args.get('uid') or 'guest')


@app.route('/api/new-game/extraction/gear')
def api_vmax_gear_state():
    uid = _vmax_uid_from({})
    return jsonify({"st": "ok", **_vmax_gear_view(uid, _vmax_new_game_state(uid))})


@app.route('/api/new-game/extraction/gear/buy', methods=['POST'])
def api_vmax_gear_buy():
    """body: {uid, item_id, qty?} -> ซื้อของ gear ด้วย game_cash เข้าคลัง (ไม่ใช่เข้ากระเป๋าเลย)"""
    b = request.get_json(silent=True) or {}
    uid = _vmax_uid_from(b)
    st = _vmax_new_game_state(uid)
    item_id, qty = str(b.get("item_id", "")), max(1, min(int(b.get("qty", 1)), 10))
    if item_id not in VMAX_RAID_GEAR:
        return jsonify({"st": "error", "msg": "ไม่มีของชนิดนี้ขาย", "known": list(VMAX_RAID_GEAR)}), 400
    cost = VMAX_RAID_GEAR[item_id]["price"] * qty
    if st["game_cash"] < cost:
        return jsonify({"st": "error", "msg": f"Cash ไม่พอ (ต้องการ {cost})"}), 400
    st["game_cash"] -= cost
    _vmax_gear_stash_put(uid, item_id, qty)
    return jsonify({"st": "ok", "msg": f"ซื้อ {VMAX_RAID_GEAR[item_id]['name_th']} x{qty} เข้าคลังแล้ว", **_vmax_gear_view(uid, st)})


@app.route('/api/new-game/extraction/loadout/set', methods=['POST'])
def api_vmax_loadout_set():
    """body: {uid, items: [item_id,...], hand?: item_id}
    items = ของที่จะใส่กระเป๋า (กินช่อง) ; hand = ของที่จะถือติดมือตั้งแต่เริ่ม Raid (ไม่กินช่องกระเป๋า มีได้ 1 ชิ้น ต้องเป็นของ slot melee)
    ใส่ทั้งสองแบบได้ หรือไม่ใส่อะไรเลยก็ได้ แล้วค่อยเอาของเข้ามือ/ถอดสลับในแมพภายหลัง (/gear/equip, /gear/unequip)
    เรียกซ้ำเพื่อเปลี่ยนได้ ของ loadout เดิมคืนคลังก่อน"""
    b = request.get_json(silent=True) or {}
    uid = _vmax_uid_from(b)
    st = _vmax_new_game_state(uid)
    if st["status"] == "raid":
        return jsonify({"st": "error", "msg": "จัด loadout ได้เฉพาะก่อนเริ่ม Raid"}), 400
    items = [str(i) for i in (b.get("items") or [])]
    hand = str(b["hand"]) if b.get("hand") else None
    everything = items + ([hand] if hand else [])
    if len(everything) > VMAX_RAID_LOADOUT_MAX_ITEMS:
        return jsonify({"st": "error", "msg": f"พาเข้าแมพได้สูงสุด {VMAX_RAID_LOADOUT_MAX_ITEMS} ชิ้น (รวมของในมือ)"}), 400
    for i in everything:
        if i not in VMAX_RAID_GEAR:
            return jsonify({"st": "error", "msg": f"ไม่รู้จักไอเทม {i}"}), 400
        if _vmax_gear_expired(i):
            return jsonify({"st": "error", "msg": f"{VMAX_RAID_GEAR[i]['name_th']} หมดซีซั่นแล้ว เอาเข้าแมพไม่ได้ — แลกคืนเป็นกุญแจที่ /api/battlepass/knife/retire"}), 400
    if hand and VMAX_RAID_GEAR[hand]["slot"] != "melee":
        return jsonify({"st": "error", "msg": "ของในมือต้องเป็นอาวุธติดมือ"}), 400
    if sum(VMAX_RAID_GEAR[i]["weight"] for i in items) > VMAX_RAID_BAG_CAPACITY:
        return jsonify({"st": "error", "msg": "กระเป๋าไม่พอสำหรับ loadout นี้"}), 400
    old = list(st.get("loadout", [])) + ([st["loadout_hand"]] if st.get("loadout_hand") else [])
    for i in old:
        _vmax_gear_stash_put(uid, i, 1)               # คืนของ loadout เก่าเข้าคลังก่อน
    taken = []
    for i in everything:
        if _vmax_gear_stash_take(uid, i, 1):
            taken.append(i)
        else:
            for t in taken:
                _vmax_gear_stash_put(uid, t, 1)       # ของไม่พอ -> ย้อนคืนทั้งหมดแล้วเซ็ตกลับเป็นอันเดิม
            for o in old:
                _vmax_gear_stash_take(uid, o, 1)
            return jsonify({"st": "error", "msg": f"ในคลังไม่มี {i} เพียงพอ"}), 400
    st["loadout"] = taken[:len(items)]
    st["loadout_hand"] = taken[len(items)] if hand else None
    return jsonify({"st": "ok", "msg": "จัด loadout แล้ว", **_vmax_gear_view(uid, st)})


@app.route('/api/new-game/extraction/gear/equip', methods=['POST'])
def api_vmax_gear_equip():
    """body: {uid, item_id} -> (ในแมพ) ติดตั้งของจากกระเป๋าลงมือ ของในมือไม่กินช่องกระเป๋า มีได้ทีละ 1 ชิ้นต่อ slot"""
    b = request.get_json(silent=True) or {}
    uid = _vmax_uid_from(b)
    st = _vmax_new_game_state(uid)
    if st["status"] != "raid":
        return jsonify({"st": "error", "msg": "ติดตั้งได้เฉพาะใน Raid"}), 400
    item_id = str(b.get("item_id", ""))
    if _vmax_gear_expired(item_id):
        return jsonify({"st": "error", "msg": "ของชิ้นนี้หมดซีซั่นแล้ว ใช้ไม่ได้"}), 400
    if item_id not in st.get("gear_bag", []):
        return jsonify({"st": "error", "msg": "ไม่มีของชิ้นนี้ในกระเป๋า (ต้องจัด loadout จากคลังก่อนเริ่ม Raid)"}), 400
    st["gear_bag"].remove(item_id)
    swapped = st.get("equipped")
    if swapped:
        st["gear_bag"].append(swapped)      # สลับ: ของในมือเดิมกลับเข้ากระเป๋า (ช่องที่เพิ่งว่างจากของที่หยิบ พอดีกัน)
    st["equipped"] = item_id
    return jsonify({"st": "ok", "msg": f"ติดตั้ง {VMAX_RAID_GEAR[item_id]['name_th']} แล้ว" + (" (สลับของเดิมเก็บเข้ากระเป๋า)" if swapped else ""), **_vmax_gear_view(uid, st)})


@app.route('/api/new-game/extraction/gear/unequip', methods=['POST'])
def api_vmax_gear_unequip():
    """ถอดของในมือกลับเข้ากระเป๋า (ต้องมีที่ว่าง ไม่งั้นต้องทิ้งของลูทก่อน)"""
    b = request.get_json(silent=True) or {}
    uid = _vmax_uid_from(b)
    st = _vmax_new_game_state(uid)
    if st["status"] != "raid" or not st.get("equipped"):
        return jsonify({"st": "error", "msg": "ไม่มีของติดตั้งอยู่"}), 400
    w_loot = sum(VMAX_NEW_GAME_LOOT[i]["weight"] for i in st["bag"])
    if w_loot + _vmax_gear_bag_weight(st) + VMAX_RAID_GEAR[st["equipped"]]["weight"] > VMAX_RAID_BAG_CAPACITY:
        return jsonify({"st": "error", "msg": "กระเป๋าเต็ม ไม่มีที่เก็บของที่ถอด"}), 400
    st["gear_bag"].append(st["equipped"])
    st["equipped"] = None
    return jsonify({"st": "ok", "msg": "ถอดเก็บเข้ากระเป๋าแล้ว", **_vmax_gear_view(uid, st)})



# ==========================================
# [ BP Economy Store — แหล่งความจริงแหล่งเดียวของเหรียญพาส/คลังยาซีซั่น/มีดที่ซื้อ/นับกล่องสุ่ม (SQLite) ]
# - ทุกการเปลี่ยนเหรียญ/ยา เป็นธุรกรรมเดียว (BEGIN IMMEDIATE ... COMMIT) + CHECK(coins>=0) -> เหรียญติดลบ/แลกคืนซ้ำสองรอบไม่ได้
#   แม้ request ซ้อนกัน หรือมีหลาย process ชี้ไฟล์ DB เดียวกัน (ล็อกที่ระดับฐานข้อมูล ไม่ใช่แค่ในหน่วยความจำ)
# - บันทึกลงดิสก์ (WAL) รีสตาร์ทเซิร์ฟเวอร์แล้วเหรียญ/ยาไม่หาย  ที่เก็บ: env BP_ECON_DB หรือ vmax_bp_econ.sqlite3 ข้างไฟล์นี้
# - ตาราง tx = บันทึกทุกการเคลื่อนไหวของเหรียญ (ใช้ตรวจย้อนหลัง/ไล่โกง) ดูได้ที่ GET /api/battlepass/econ/log (admin)
# - ต้องการแยกเป็นบริการข้างนอกในอนาคต: เปลี่ยนเฉพาะคลาส _BpEcon นี้ endpoint ด้านล่างเรียกผ่าน _bp_econ() ทั้งหมด
# - ผู้เล่นเดิมที่มีเหรียญในหน่วยความจำ (BATTLE_PASS_STATE) จะถูกย้ายเข้า DB อัตโนมัติครั้งแรกที่แตะกระเป๋าเหรียญ
# ==========================================
import sqlite3 as _bp_sqlite3
from contextlib import contextmanager as _bp_cm

_BP_ECON_SCHEMA = """
CREATE TABLE IF NOT EXISTS wallet(uid TEXT PRIMARY KEY, coins INTEGER NOT NULL CHECK(coins>=0), box_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS meds(uid TEXT NOT NULL, season_id TEXT NOT NULL, item_id TEXT NOT NULL,
    qty INTEGER NOT NULL CHECK(qty>=0), paid INTEGER NOT NULL CHECK(paid>=0), PRIMARY KEY(uid,season_id,item_id));
CREATE TABLE IF NOT EXISTS knives(uid TEXT NOT NULL, item_id TEXT NOT NULL, PRIMARY KEY(uid,item_id));
CREATE TABLE IF NOT EXISTS tx(id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL NOT NULL, uid TEXT NOT NULL, kind TEXT NOT NULL,
    delta INTEGER NOT NULL, ref TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS tx_uid ON tx(uid, id);
"""


class _BpEcon:
    def __init__(self, path):
        self._lock = threading.RLock()
        self._db = _bp_sqlite3.connect(path, check_same_thread=False, isolation_level=None, timeout=15)
        try:
            self._db.execute("PRAGMA journal_mode=WAL")
        except Exception:
            pass
        self._db.execute("PRAGMA synchronous=FULL")
        self._db.executescript(_BP_ECON_SCHEMA)

    @_bp_cm
    def _tx(self):
        with self._lock:
            self._db.execute("BEGIN IMMEDIATE")
            try:
                yield self._db
                self._db.execute("COMMIT")
            except BaseException:
                self._db.execute("ROLLBACK")
                raise

    @staticmethod
    def _log(db, uid, kind, delta=0, ref=""):
        db.execute("INSERT INTO tx(ts,uid,kind,delta,ref) VALUES(?,?,?,?,?)", (time.time(), uid, kind, int(delta), str(ref)[:200]))

    @staticmethod
    def _seed(db, uid):
        row = db.execute("SELECT coins FROM wallet WHERE uid=?", (uid,)).fetchone()
        if row is None:
            legacy = 0
            try:
                legacy = max(0, int((BATTLE_PASS_STATE.get(uid) or {}).get("coins", 0) or 0))   # ย้ายเหรียญเก่าในหน่วยความจำเข้า DB
            except Exception:
                pass
            db.execute("INSERT INTO wallet(uid,coins,box_count) VALUES(?,?,0)", (uid, legacy))
            if legacy:
                _BpEcon._log(db, uid, "legacy_import", legacy)
            return legacy
        return row[0]

    def coins(self, uid):
        with self._tx() as db:
            return self._seed(db, uid)

    def credit(self, uid, amount, kind, ref=""):
        amount = int(amount)
        if amount <= 0:
            return self.coins(uid)
        with self._tx() as db:
            self._seed(db, uid)
            db.execute("UPDATE wallet SET coins=coins+? WHERE uid=?", (amount, uid))
            self._log(db, uid, kind, amount, ref)
            return db.execute("SELECT coins FROM wallet WHERE uid=?", (uid,)).fetchone()[0]

    def _spend_in(self, db, uid, amount, kind, ref):
        self._seed(db, uid)
        cur = db.execute("UPDATE wallet SET coins=coins-? WHERE uid=? AND coins>=?", (amount, uid, amount))
        if cur.rowcount == 0:
            return None
        self._log(db, uid, kind, -amount, ref)
        return db.execute("SELECT coins FROM wallet WHERE uid=?", (uid,)).fetchone()[0]

    def spend(self, uid, amount, kind, ref=""):
        """หักเหรียญแบบ atomic -> เหรียญคงเหลือ หรือ None ถ้าไม่พอ"""
        with self._tx() as db:
            return self._spend_in(db, uid, int(amount), kind, ref)

    # ---- ยาซีซั่น ----
    def med_buy(self, uid, season_id, item_id, add_qty, cost):
        with self._tx() as db:
            coins = self._spend_in(db, uid, int(cost), "med_buy", f"{season_id}:{item_id}x{add_qty}")
            if coins is None:
                return None
            db.execute("INSERT INTO meds(uid,season_id,item_id,qty,paid) VALUES(?,?,?,?,?) "
                       "ON CONFLICT(uid,season_id,item_id) DO UPDATE SET qty=qty+excluded.qty, paid=paid+excluded.paid",
                       (uid, season_id, item_id, int(add_qty), int(cost)))
            return coins

    def med_use(self, uid, season_id, item_id):
        with self._tx() as db:
            row = db.execute("SELECT qty,paid FROM meds WHERE uid=? AND season_id=? AND item_id=?", (uid, season_id, item_id)).fetchone()
            if not row or row[0] < 1:
                return False
            qty, paid = row
            db.execute("UPDATE meds SET qty=?, paid=? WHERE uid=? AND season_id=? AND item_id=?",
                       (qty - 1, paid - paid // qty, uid, season_id, item_id))     # ใช้แล้วตัดเหรียญของชิ้นนั้นออก แลกคืนไม่ได้
            db.execute("DELETE FROM meds WHERE uid=? AND qty<=0", (uid,))
            self._log(db, uid, "med_use", 0, f"{season_id}:{item_id}")
            return True

    def med_items(self, uid, season_id):
        with self._lock:
            rows = self._db.execute("SELECT item_id,qty,paid FROM meds WHERE uid=? AND season_id=? AND qty>0", (uid, season_id)).fetchall()
        return {r[0]: {"qty": r[1], "paid": r[2]} for r in rows}

    def med_sweep(self, uid, current_season, expired_now):
        """ยาของซีซั่นที่ไม่ใช่ซีซั่นปัจจุบัน (หรือซีซั่นปัจจุบันที่เลยเวลา) หายไป — เหรียญไม่แตะ"""
        with self._tx() as db:
            rows = db.execute("SELECT season_id,SUM(qty) FROM meds WHERE uid=? AND (season_id<>? OR ?) GROUP BY season_id",
                              (uid, current_season, 1 if expired_now else 0)).fetchall()
            gone = 0
            for sid, q in rows:
                gone += int(q or 0)
                if q:
                    self._log(db, uid, "med_vanish", 0, f"{sid}:{int(q)}")
            if rows:
                db.execute("DELETE FROM meds WHERE uid=? AND (season_id<>? OR ?)", (uid, current_season, 1 if expired_now else 0))
            return gone

    def last_vanished(self, uid):
        with self._lock:
            r = self._db.execute("SELECT ref FROM tx WHERE uid=? AND kind='med_vanish' ORDER BY id DESC LIMIT 1", (uid,)).fetchone()
        try:
            return int(r[0].rsplit(":", 1)[1]) if r else 0
        except Exception:
            return 0

    def med_refund(self, uid, season_id, only, qty, rate):
        """แลกคืนยา -> เหรียญ ในธุรกรรมเดียว: (total, detail, coins) หรือ None ถ้าไม่มียา"""
        with self._tx() as db:
            if only:
                rows = db.execute("SELECT item_id,qty,paid FROM meds WHERE uid=? AND season_id=? AND item_id=? AND qty>0", (uid, season_id, only)).fetchall()
            else:
                rows = db.execute("SELECT item_id,qty,paid FROM meds WHERE uid=? AND season_id=? AND qty>0", (uid, season_id)).fetchall()
            total, detail = 0, {}
            for item_id, have, paid in rows:
                q = have if (not only or qty is None) else max(1, min(int(qty), have))
                part = paid if q >= have else paid * q // have
                coins = int(part * rate)
                db.execute("UPDATE meds SET qty=qty-?, paid=paid-? WHERE uid=? AND season_id=? AND item_id=?", (q, part, uid, season_id, item_id))
                total += coins
                detail[item_id] = {"qty": q, "coins": coins}
            if not detail:
                return None
            db.execute("DELETE FROM meds WHERE uid=? AND qty<=0", (uid,))
            self._seed(db, uid)
            if total:
                db.execute("UPDATE wallet SET coins=coins+? WHERE uid=?", (total, uid))
            self._log(db, uid, "med_refund", total, f"{season_id}:{detail}")
            return total, detail, db.execute("SELECT coins FROM wallet WHERE uid=?", (uid,)).fetchone()[0]

    # ---- มีดซีซั่น / กล่องสุ่ม ----
    def knives(self, uid):
        with self._lock:
            return {r[0] for r in self._db.execute("SELECT item_id FROM knives WHERE uid=?", (uid,)).fetchall()}

    def knife_buy(self, uid, item_id, price):
        with self._tx() as db:
            if db.execute("SELECT 1 FROM knives WHERE uid=? AND item_id=?", (uid, item_id)).fetchone():
                return "owned", None
            coins = self._spend_in(db, uid, int(price), "knife_buy", item_id)
            if coins is None:
                return "poor", self._seed(db, uid)
            db.execute("INSERT INTO knives(uid,item_id) VALUES(?,?)", (uid, item_id))
            return "ok", coins

    def box_open(self, uid, cost, count):
        with self._tx() as db:
            coins = self._spend_in(db, uid, int(cost), "mystery_box", f"x{count}")
            if coins is None:
                return None
            start = db.execute("SELECT box_count FROM wallet WHERE uid=?", (uid,)).fetchone()[0]
            db.execute("UPDATE wallet SET box_count=box_count+? WHERE uid=?", (int(count), uid))
            return coins, start

    def box_count(self, uid):
        with self._tx() as db:
            self._seed(db, uid)
            return db.execute("SELECT box_count FROM wallet WHERE uid=?", (uid,)).fetchone()[0]

    def season_sync(self, season):
        """โหมดในเครื่อง: BP_SEASON เป็นตัวเดียวกันอยู่แล้ว ไม่ต้องซิงก์ (โหมด remote จะส่งไปให้บริการกลาง)"""
        return True

    def log(self, uid, limit=100):
        with self._lock:
            rows = self._db.execute("SELECT id,ts,kind,delta,ref FROM tx WHERE uid=? ORDER BY id DESC LIMIT ?", (uid, int(limit))).fetchall()
        return [{"id": r[0], "ts": r[1], "kind": r[2], "delta": r[3], "ref": r[4]} for r in rows]


_BP_ECON_SINGLETON = None
_BP_ECON_INIT_LOCK = threading.Lock()

def _bp_econ_local() -> "_BpEcon":
    global _BP_ECON_SINGLETON
    if _BP_ECON_SINGLETON is None:
        with _BP_ECON_INIT_LOCK:
            if _BP_ECON_SINGLETON is None:
                path = os.environ.get("BP_ECON_DB") or os.path.join(os.path.dirname(os.path.abspath(__file__)), "vmax_bp_econ.sqlite3")
                try:
                    _BP_ECON_SINGLETON = _BpEcon(path)
                except Exception as e:   # เขียนดิสก์ไม่ได้ -> ใช้หน่วยความจำ (เหรียญจะไม่คงอยู่ข้ามรีสตาร์ท) แต่ยังมีธุรกรรม atomic
                    print(f"[BP-ECON] เปิดฐานข้อมูล {path} ไม่ได้ ({e}) -> ใช้ :memory: ชั่วคราว")
                    _BP_ECON_SINGLETON = _BpEcon(":memory:")
    return _BP_ECON_SINGLETON


# ==========================================
# [ BP Economy Gateway (MCP) — จุดเช็คส่วนกลาง + ระบบความปลอดภัย ]
# แนวคิด: ให้ "บริการเศรษฐกิจ" เป็นเจ้าของเหรียญ/คลังยา/กติกาแลกคืน แล้วเกมเซิร์ฟเวอร์ (ตัวลูก) หลายตัวเรียกเข้ามาตรวจ/ตัดสินที่เดียว
# ไม่ใช่ MCP สำหรับ AI อย่างเดียว — ใช้โปรโตคอล MCP (JSON-RPC 2.0: initialize / tools/list / tools/call) เป็นภาษากลางที่ client อะไรก็คุยได้
# โหมดการใช้งาน:
#   1) ค่าเริ่มต้น (ไม่ตั้ง env อะไร): ทุกอย่างทำงานในเครื่องเดียวผ่าน _BpEcon โดยตรง  และ endpoint /mcp/bp-econ ปิดอยู่ (503)
#   2) เปิดเป็นบริการกลาง: ตั้ง BP_MCP_KEYS='{"game-1":{"secret":"<hex 64 ตัว>","scopes":["read","spend","refund"]}}' ที่ตัวบริการ
#      (secret สร้างด้วย python -c "import secrets;print(secrets.token_hex(32))")
#   3) เกมเซิร์ฟเวอร์ตัวลูก: ตั้ง BP_ECON_REMOTE_URL=https://<บริการกลาง>/mcp/bp-econ  BP_ECON_REMOTE_KEY_ID=game-1  BP_ECON_REMOTE_SECRET=<secret>
#      แล้ว _bp_econ() จะส่งทุกการเช็ค/หัก/แลกคืนไปที่บริการกลางแทนที่จะแตะ DB เอง
# ความปลอดภัย (ฝั่งบริการกลาง):
#   - ทุกคำขอเซ็นด้วย HMAC-SHA256(secret, ts.nonce.sha256(body).path) -> ปลอมไม่ได้ แก้ body กลางทางไม่ได้
#   - ts ต้องห่างจากเวลาเซิร์ฟเวอร์ไม่เกิน BP_GW_SKEW_SEC (60 วิ) + nonce ใช้ซ้ำไม่ได้ (กัน replay)
#   - scope ต่อ key: read / spend / credit / refund / admin — key ของเกมปกติไม่ควรมี credit/admin
#   - เพดานต่อครั้ง (BP_GW_MAX_CREDIT ฯลฯ) + rate limit ต่อ key + ล็อกชั่วคราวเมื่อเซ็นผิดรัว + audit_log ทุกครั้ง
#   - กติกาแลกคืน (หน้าต่างชั่วโมงสุดท้าย) ถูกตัดสินที่ตัวบริการกลางเอง ตัวลูกที่โดนเจาะก็แลกคืนนอกเวลาไม่ได้
#   - ขอบเขตความเชื่อใจ: ผู้เล่น -> เกมเซิร์ฟเวอร์ (JWT) -> บริการกลาง (HMAC)  ถ้าเกมเซิร์ฟเวอร์ถูกยึดทั้งเครื่อง key ที่มี scope ก็ยังทำได้เท่า scope + เพดาน
# ==========================================
import hmac as _bpgw_hmac
import hashlib as _bpgw_hashlib
import inspect as _bpgw_inspect
import json as _bpgw_json
import secrets as _bpgw_secrets
import urllib.request as _bpgw_urlreq
import urllib.error as _bpgw_urlerr
from collections import deque as _bpgw_deque

BP_GW_SKEW_SEC = int(os.environ.get("BP_GW_SKEW_SEC", "60"))
BP_GW_RATE_PER_MIN = int(os.environ.get("BP_GW_RATE_PER_MIN", "600"))
BP_GW_MAX_BODY = 64 * 1024
BP_GW_MAX_CREDIT = int(os.environ.get("BP_GW_MAX_CREDIT", "1000"))      # เหรียญที่ credit ได้ต่อครั้ง
BP_GW_MAX_SPEND = int(os.environ.get("BP_GW_MAX_SPEND", "100000"))
BP_GW_MAX_QTY = 1000
BP_GW_FAIL_LIMIT = 10                                                    # เซ็นผิดกี่ครั้งใน 60 วิ ถึงล็อก IP นั้น 60 วิ

# method -> (scope, คำอธิบายสำหรับ tools/list)
_BP_GW_METHODS = {
    "coins":         ("read",   "ยอดเหรียญพาสของผู้เล่น"),
    "med_items":     ("read",   "คลังยาซีซั่นของผู้เล่นในซีซั่นที่ระบุ"),
    "last_vanished": ("read",   "จำนวนยาซีซั่นที่หายไปครั้งล่าสุด"),
    "knives":        ("read",   "มีดซีซั่นที่ผู้เล่นซื้อไปแล้ว"),
    "box_count":     ("read",   "จำนวนกล่องสุ่มที่เปิดสะสม"),
    "spend":         ("spend",  "หักเหรียญแบบ atomic (ไม่พอ = None)"),
    "med_buy":       ("spend",  "หักเหรียญ + เพิ่มยาซีซั่น ในธุรกรรมเดียว"),
    "med_use":       ("spend",  "ใช้ยาซีซั่น 1 ชิ้น"),
    "med_sweep":     ("spend",  "ล้างยาของซีซั่นที่จบ/หมดเวลา"),
    "knife_buy":     ("spend",  "ซื้อมีดซีซั่น (หักเหรียญ+บันทึกว่าซื้อ)"),
    "box_open":      ("spend",  "หักเหรียญ + นับกล่องสุ่ม"),
    "med_refund":    ("refund", "แลกยาซีซั่นคืนเป็นเหรียญ — ตัวบริการเช็คหน้าต่างชั่วโมงสุดท้ายเอง"),
    "credit":        ("credit", "เพิ่มเหรียญ (ภารกิจ/เคลมเลเวล) — จำกัดต่อครั้ง"),
    "log":           ("admin",  "ประวัติเคลื่อนไหวเหรียญของผู้เล่น"),
}
_BP_GW_VALID_SCOPES = {"read", "spend", "credit", "refund", "admin"}
_BP_GW_NONCES = {}                 # (key_id, nonce) -> หมดอายุเมื่อไหร่
_BP_GW_RATE = {}                   # key_id -> deque เวลาที่เรียก
_BP_GW_FAILS = {}                  # ip -> deque เวลาที่เซ็นผิด
_BP_GW_LOCK = threading.Lock()


class _BpGwDenied(Exception):
    """บริการกลางปฏิเสธตามกติกา (เช่น นอกหน้าต่างแลกคืน / เกินเพดาน)"""


class _BpGwUnavailable(Exception):
    """ติดต่อบริการกลางไม่ได้ / auth ไม่ผ่าน"""


def _bp_gw_keys() -> dict:
    raw = os.environ.get("BP_MCP_KEYS", "").strip()
    if not raw:
        return {}
    try:
        data = _bpgw_json.loads(raw)
    except Exception:
        print("[BP-GW] BP_MCP_KEYS ไม่ใช่ JSON ที่ถูกต้อง -> ปิดบริการกลาง")
        return {}
    out = {}
    for kid, v in (data or {}).items():
        secret = str((v or {}).get("secret", ""))
        scopes = set((v or {}).get("scopes", [])) & _BP_GW_VALID_SCOPES
        if len(secret) >= 32 and scopes:                 # secret สั้นกว่า 32 ตัวอักษรไม่รับ
            out[str(kid)] = {"secret": secret, "scopes": scopes}
    return out


def _bp_gw_sign(secret: str, ts: str, nonce: str, body: bytes, path: str) -> str:
    msg = f"{ts}.{nonce}.{_bpgw_hashlib.sha256(body).hexdigest()}.{path}".encode()
    return _bpgw_hmac.new(secret.encode(), msg, _bpgw_hashlib.sha256).hexdigest()


def _bp_gw_fail(ip, why, key_id=""):
    now = time.time()
    with _BP_GW_LOCK:
        dq = _BP_GW_FAILS.setdefault(ip, _bpgw_deque())
        dq.append(now)
        while dq and now - dq[0] > 60:
            dq.popleft()
    audit_log("bp_mcp_auth_fail", uid=key_id, why=why, ip_seen=ip)


def _bp_gw_authenticate(body: bytes, path: str):
    """-> (key_id, scopes) หรือ (None, (status, message))"""
    keys = _bp_gw_keys()
    if not keys:
        return None, (503, "บริการกลางปิดอยู่ (ยังไม่ได้ตั้ง BP_MCP_KEYS)")
    ip = request.remote_addr or "?"
    now = time.time()
    with _BP_GW_LOCK:
        dq = _BP_GW_FAILS.get(ip)
        if dq:
            while dq and now - dq[0] > 60:
                dq.popleft()
            if len(dq) >= BP_GW_FAIL_LIMIT:
                return None, (429, "เซ็นผิดบ่อยเกินไป ถูกล็อกชั่วคราว")
    kid = request.headers.get("X-BP-Key", "")
    ts = request.headers.get("X-BP-Ts", "")
    nonce = request.headers.get("X-BP-Nonce", "")
    sig = request.headers.get("X-BP-Sig", "")
    k = keys.get(kid)
    if not k or not ts or not nonce or not sig or len(nonce) < 16 or len(nonce) > 128:
        _bp_gw_fail(ip, "missing_or_unknown_key", kid)
        return None, (401, "auth ไม่ผ่าน")
    try:
        ts_f = float(ts)
    except ValueError:
        _bp_gw_fail(ip, "bad_ts", kid)
        return None, (401, "auth ไม่ผ่าน")
    if abs(now - ts_f) > BP_GW_SKEW_SEC:
        _bp_gw_fail(ip, "clock_skew", kid)
        return None, (401, "เวลาไม่ตรง/คำขอเก่าเกินไป")
    expect = _bp_gw_sign(k["secret"], ts, nonce, body, path)
    if not _bpgw_hmac.compare_digest(expect, sig):
        _bp_gw_fail(ip, "bad_signature", kid)
        return None, (401, "auth ไม่ผ่าน")
    with _BP_GW_LOCK:
        for nk in [nk for nk, exp in _BP_GW_NONCES.items() if exp < now]:    # เก็บกวาด nonce ที่หมดอายุ
            del _BP_GW_NONCES[nk]
        if (kid, nonce) in _BP_GW_NONCES:
            replay = True
        else:
            replay = False
            _BP_GW_NONCES[(kid, nonce)] = now + BP_GW_SKEW_SEC * 2
        rl = _BP_GW_RATE.setdefault(kid, _bpgw_deque())
        while rl and now - rl[0] > 60:
            rl.popleft()
        limited = len(rl) >= BP_GW_RATE_PER_MIN
        if not limited:
            rl.append(now)
    if replay:
        _bp_gw_fail(ip, "replay", kid)
        return None, (401, "nonce ถูกใช้ไปแล้ว")
    if limited:
        return None, (429, "เรียกถี่เกินกำหนด")
    return kid, k["scopes"]


def _bp_gw_jsonable(v):
    if isinstance(v, (set, frozenset)):
        return sorted(v)
    if isinstance(v, tuple):
        return [_bp_gw_jsonable(x) for x in v]
    if isinstance(v, dict):
        return {k: _bp_gw_jsonable(x) for k, x in v.items()}
    if isinstance(v, list):
        return [_bp_gw_jsonable(x) for x in v]
    return v


def _bp_gw_exec(method: str, args: dict):
    """ตัวตัดสินกลาง: ตรวจเพดาน/กติกา แล้วเรียก _BpEcon จริง"""
    E = _bp_econ_local()
    fn = getattr(E, method)
    try:
        _bpgw_inspect.signature(fn).bind(**args)
    except TypeError as e:
        raise ValueError(f"พารามิเตอร์ไม่ถูกต้อง: {e}")
    for k in ("uid", "season_id", "item_id", "only"):
        if k in args and args[k] is not None and (not isinstance(args[k], str) or len(args[k]) > 200):
            raise ValueError(f"{k} ต้องเป็นข้อความยาวไม่เกิน 200")
    if method == "credit":
        amt = int(args["amount"])
        if not 0 < amt <= BP_GW_MAX_CREDIT:
            raise _BpGwDenied(f"credit ต่อครั้งต้องอยู่ระหว่าง 1-{BP_GW_MAX_CREDIT}")
    if method in ("spend", "med_buy", "knife_buy", "box_open"):
        amt = int(args.get("amount", args.get("cost", args.get("price", 0))))
        if not 0 <= amt <= BP_GW_MAX_SPEND:
            raise _BpGwDenied("จำนวนเหรียญที่หักต่อครั้งเกินเพดาน")
    if method == "med_buy" and not 0 < int(args["add_qty"]) <= BP_GW_MAX_QTY:
        raise _BpGwDenied("จำนวนยาต่อครั้งเกินเพดาน")
    if method == "med_refund":
        if not _bp_med_refund_window()["open"]:           # กติกาตัดสินที่ตัวกลางเอง ไม่เชื่อตัวลูก
            raise _BpGwDenied("นอกหน้าต่างแลกคืน (เปิดเฉพาะชั่วโมงสุดท้ายก่อนซีซั่นจบ)")
        if not 0 <= float(args.get("rate", 1.0)) <= BP_MED_REFUND_RATE:    # ตัวลูกขอคืนเกินอัตราที่ตั้งไว้ไม่ได้
            raise _BpGwDenied("อัตราคืนเกินที่กำหนด")
    if method == "med_sweep":
        args = {**args, "expired_now": bool(args.get("expired_now")) or _bp_season_expired(str(args.get("current_season", "")))}
    return _bp_gw_jsonable(fn(**args))


def _bp_gw_tools() -> list:
    tools = []
    for m, (scope, desc) in _BP_GW_METHODS.items():
        sig = _bpgw_inspect.signature(getattr(_BpEcon, m))
        params = [p for n, p in sig.parameters.items() if n != "self"]
        tools.append({"name": f"bp_{m}", "description": f"[scope:{scope}] {desc}",
                      "inputSchema": {"type": "object", "properties": {p.name: {} for p in params},
                                      "required": [p.name for p in params if p.default is p.empty]}})
    tools.append({"name": "bp_season_sync", "description": "[scope:admin] ซิงก์สถานะซีซั่น (season_id/ends_at/refund_open) ให้บริการกลาง",
                  "inputSchema": {"type": "object", "properties": {"season_id": {}, "name_th": {}, "ends_at": {}, "refund_open": {}},
                                  "required": ["season_id"]}})
    return tools


def _bp_gw_rpc(msg: dict, key_id: str, scopes: set):
    """ประมวลผล JSON-RPC 1 ข้อความ -> dict ตอบกลับ (หรือ None ถ้าเป็น notification)"""
    mid, method, params = msg.get("id"), msg.get("method"), msg.get("params") or {}

    def ok(result):
        return {"jsonrpc": "2.0", "id": mid, "result": result}

    def err(code, text):
        return {"jsonrpc": "2.0", "id": mid, "error": {"code": code, "message": text}}

    if mid is None and isinstance(method, str) and method.startswith("notifications/"):
        return None
    if method == "initialize":
        return ok({"protocolVersion": "2025-03-26", "capabilities": {"tools": {}},
                   "serverInfo": {"name": "vmax-bp-econ", "version": "1.0.0"}})
    if method == "ping":
        return ok({})
    if method == "tools/list":
        return ok({"tools": _bp_gw_tools()})
    if method == "tools/call":
        name, args = str(params.get("name", "")), params.get("arguments") or {}
        if not isinstance(args, dict):
            return err(-32602, "arguments ต้องเป็น object")
        if name == "bp_season_sync":
            need = "admin"
        elif name.startswith("bp_") and name[3:] in _BP_GW_METHODS:
            need = _BP_GW_METHODS[name[3:]][0]
        else:
            return err(-32601, f"ไม่มีเครื่องมือ {name}")
        if need not in scopes:
            audit_log("bp_mcp_scope_denied", uid=key_id, tool=name, need=need)
            return ok({"isError": True, "content": [{"type": "text", "text": _bpgw_json.dumps({"error": "scope_denied", "need": need})}]})
        try:
            if name == "bp_season_sync":
                BP_SEASON.update({k: args[k] for k in ("season_id", "name_th", "ends_at", "refund_open") if k in args})
                result = True
            else:
                result = _bp_gw_exec(name[3:], args)
        except _BpGwDenied as e:
            audit_log("bp_mcp_denied", uid=key_id, tool=name, why=str(e))
            return ok({"isError": True, "content": [{"type": "text", "text": _bpgw_json.dumps({"error": "denied", "msg": str(e)})}]})
        except (ValueError, TypeError, KeyError) as e:
            return err(-32602, f"พารามิเตอร์ไม่ถูกต้อง: {e}")
        if name in ("bp_credit", "bp_med_refund", "bp_season_sync"):
            audit_log("bp_mcp_call", uid=key_id, tool=name, uid_target=str(args.get("uid", "")))
        return ok({"isError": False, "content": [{"type": "text", "text": _bpgw_json.dumps({"result": result})}]})
    return err(-32601, "method not found")


@app.route('/mcp/bp-econ', methods=['POST'])
def mcp_bp_econ():
    """MCP (JSON-RPC 2.0 over HTTP POST) ของบริการเศรษฐกิจ — ต้องเซ็น HMAC ทุกคำขอ ดูหัวข้อด้านบน"""
    body = request.get_data(cache=True)
    if len(body) > BP_GW_MAX_BODY:
        return jsonify({"error": "body ใหญ่เกินไป"}), 413
    key_id, info = _bp_gw_authenticate(body, request.path)
    if key_id is None:
        return jsonify({"error": info[1]}), info[0]
    try:
        msg = _bpgw_json.loads(body.decode("utf-8"))
    except Exception:
        return jsonify({"jsonrpc": "2.0", "id": None, "error": {"code": -32700, "message": "parse error"}}), 400
    if not isinstance(msg, dict):
        return jsonify({"jsonrpc": "2.0", "id": None, "error": {"code": -32600, "message": "ไม่รับ batch"}}), 400
    out = _bp_gw_rpc(msg, key_id, info)
    if out is None:
        return "", 202
    return jsonify(out)


class _BpEconRemote:
    """ไคลเอนต์ (ตัวลูก) — หน้าตาเหมือน _BpEcon แต่ส่งทุกอย่างไปบริการกลางผ่าน MCP ที่เซ็น HMAC"""
    def __init__(self, url, key_id, secret, timeout=5.0):
        from urllib.parse import urlparse
        self.url, self.key_id, self.secret, self.timeout = url, key_id, secret, timeout
        self.path = urlparse(url).path or "/"
        if len(secret) < 32:
            raise ValueError("BP_ECON_REMOTE_SECRET ต้องยาวอย่างน้อย 32 ตัวอักษร")

    def _rpc(self, method, params):
        body = _bpgw_json.dumps({"jsonrpc": "2.0", "id": _bpgw_secrets.token_hex(4), "method": method, "params": params}).encode()
        ts, nonce = str(time.time()), _bpgw_secrets.token_hex(16)
        req = _bpgw_urlreq.Request(self.url, data=body, method="POST", headers={
            "Content-Type": "application/json", "X-BP-Key": self.key_id, "X-BP-Ts": ts, "X-BP-Nonce": nonce,
            "X-BP-Sig": _bp_gw_sign(self.secret, ts, nonce, body, self.path)})
        try:
            with _bpgw_urlreq.urlopen(req, timeout=self.timeout) as r:
                return _bpgw_json.loads(r.read().decode("utf-8"))
        except _bpgw_urlerr.HTTPError as e:
            raise _BpGwUnavailable(f"บริการกลางตอบ {e.code}")
        except Exception as e:
            raise _BpGwUnavailable(f"ติดต่อบริการกลางไม่ได้: {e}")

    def _call(self, tool, **args):
        resp = self._rpc("tools/call", {"name": tool, "arguments": args})
        if "error" in resp:
            raise _BpGwUnavailable(resp["error"].get("message", "error"))
        res = resp["result"]
        data = _bpgw_json.loads(res["content"][0]["text"])
        if res.get("isError"):
            raise _BpGwDenied(data.get("msg") or data.get("error", "denied"))
        return data["result"]

    def coins(self, uid): return self._call("bp_coins", uid=uid)
    def credit(self, uid, amount, kind, ref=""): return self._call("bp_credit", uid=uid, amount=int(amount), kind=kind, ref=ref)
    def spend(self, uid, amount, kind, ref=""): return self._call("bp_spend", uid=uid, amount=int(amount), kind=kind, ref=ref)
    def med_buy(self, uid, season_id, item_id, add_qty, cost):
        return self._call("bp_med_buy", uid=uid, season_id=season_id, item_id=item_id, add_qty=int(add_qty), cost=int(cost))
    def med_use(self, uid, season_id, item_id): return self._call("bp_med_use", uid=uid, season_id=season_id, item_id=item_id)
    def med_items(self, uid, season_id): return self._call("bp_med_items", uid=uid, season_id=season_id)
    def med_sweep(self, uid, current_season, expired_now):
        return self._call("bp_med_sweep", uid=uid, current_season=current_season, expired_now=bool(expired_now))
    def last_vanished(self, uid): return self._call("bp_last_vanished", uid=uid)
    def med_refund(self, uid, season_id, only, qty, rate):
        try:
            r = self._call("bp_med_refund", uid=uid, season_id=season_id, only=only, qty=qty, rate=float(rate))
        except _BpGwDenied:
            return None
        return None if r is None else (r[0], r[1], r[2])
    def knives(self, uid): return set(self._call("bp_knives", uid=uid))
    def knife_buy(self, uid, item_id, price):
        r = self._call("bp_knife_buy", uid=uid, item_id=item_id, price=int(price))
        return r[0], r[1]
    def box_open(self, uid, cost, count):
        r = self._call("bp_box_open", uid=uid, cost=int(cost), count=int(count))
        return None if r is None else (r[0], r[1])
    def box_count(self, uid): return self._call("bp_box_count", uid=uid)
    def log(self, uid, limit=100): return self._call("bp_log", uid=uid, limit=int(limit))
    def season_sync(self, season):
        return self._call("bp_season_sync", **{k: season[k] for k in ("season_id", "name_th", "ends_at", "refund_open") if k in season})


_BP_REMOTE_SINGLETON = None

def _bp_econ():
    """จุดเข้าเดียวของโค้ดเกม: มี BP_ECON_REMOTE_URL = ใช้บริการกลาง (MCP) / ไม่มี = ใช้ DB ในเครื่อง"""
    global _BP_REMOTE_SINGLETON
    url = os.environ.get("BP_ECON_REMOTE_URL", "").strip()
    if not url:
        return _bp_econ_local()
    if _BP_REMOTE_SINGLETON is None:
        with _BP_ECON_INIT_LOCK:
            if _BP_REMOTE_SINGLETON is None:
                _BP_REMOTE_SINGLETON = _BpEconRemote(url, os.environ.get("BP_ECON_REMOTE_KEY_ID", ""),
                                                     os.environ.get("BP_ECON_REMOTE_SECRET", ""))
                try:
                    _BP_REMOTE_SINGLETON.season_sync(dict(BP_SEASON))     # แจ้งสถานะซีซั่นให้บริการกลางครั้งแรก (ต้องมี scope admin; ไม่มีก็ข้าม)
                except Exception:
                    pass
    return _BP_REMOTE_SINGLETON


def _bp_med_sync(uid: str) -> str:
    """ล้างยาของซีซั่นที่จบแล้ว/หมดเวลา แล้วคืน season_id ปัจจุบัน"""
    sid = BP_SEASON["season_id"]
    _bp_econ().med_sweep(uid, sid, _bp_season_expired(sid))
    return sid

# ==========================================
# [ Battle Pass: มีดซีซั่น (Season Knife) — แลกด้วยเหรียญพาส หมดซีซั่นแล้วใช้ในแมพไม่ได้ แต่เอาไป "แลกคืน" เป็นของจิปาถะได้ ]
# - ได้เหรียญพาส (bp_coin) จากภารกิจประจำสัปดาห์/เคลมเลเวล (ดู BP_COINS_*)
# - ซื้อได้เฉพาะมีดของ "ซีซั่นปัจจุบัน" ซื้อได้คนละ 1 เล่มต่อซีซั่น เข้าคลัง (stash) ใช้ผ่านระบบ loadout เดียวกับมีดปกติ
# - ความพิเศษ: ทุบกระจกได้แรงกว่า (pommel_bonus) และฟันกระจกบางไม่บาดมือ (no_injury)
# - ซีซั่นจบ (admin เรียก /api/battlepass/season/end หรือถึง BP_SEASON.ends_at): มีดซีซั่นเก่าเอาเข้าแมพ/ติดตั้งไม่ได้อีก
#   แต่ยังอยู่ในคลัง -> /api/battlepass/knife/retire แลกคืนเป็นกุญแจ (keycard) + สแครป
# - ยาประจำซีซั่น (bpmed_*): หมดซีซั่นแล้วหายไป แต่แลกคืนเป็นเหรียญพาสได้ในชั่วโมงสุดท้ายก่อนซีซั่นจบ (ดู BP_MED_SPEC ด้านล่าง)
# ==========================================
BP_SEASON = {"season_id": "s1", "name_th": "ซีซั่น 1",
             "ends_at": float(os.environ.get("BP_SEASON_ENDS_AT", "0") or 0)}   # 0 = ยังไม่กำหนดวันจบ (จบด้วยมือผ่าน admin)
BP_SEASON_HISTORY = []   # [{"season_id","ended_at"}]

# [SEC] ล็อกเดียวครอบทุก endpoint ที่แตะเหรียญพาส/คลังยา — กันยิง request ซ้อนพร้อมกัน (race) เพื่อแลกคืน/ซื้อซ้ำสองรอบก่อนระบบหักของ
_BP_LOCK = threading.RLock()
def _bp_locked(fn):
    from functools import wraps
    @wraps(fn)
    def _w(*a, **kw):
        try:
            with _BP_LOCK:
                return fn(*a, **kw)
        except Exception as e:
            if e.__class__.__name__ == "_BpGwUnavailable":      # บริการเศรษฐกิจกลางล่ม/auth ไม่ผ่าน -> ไม่แตะเหรียญ ตอบ 503
                return jsonify({"st": "error", "msg": "ระบบเหรียญไม่พร้อมใช้งานชั่วคราว ลองใหม่อีกครั้ง"}), 503
            raise
    return _w

def _bp_safe_int(v, default=1, lo=1, hi=20):
    try:
        return max(lo, min(int(v), hi))
    except (TypeError, ValueError):
        return default
