def _bp_grant_items(uid: str, items: dict) -> dict:
    """จ่ายของ: 'scrap' เข้ากระเป๋าสแครปเดิม ที่เหลือเข้า BAG_INVENTORY['item']"""
    got = {}
    with BAG_LOCK:
        bag = _bag_get(uid)["item"]
        for k, n in items.items():
            if k == "scrap":
                continue
            bag[k] = bag.get(k, 0) + n
            got[k] = n
    if items.get("scrap"):
        _currency_get(uid)["scrap"] += int(items["scrap"])
        got["scrap"] = int(items["scrap"])
    return got


def _bp_season_expired(season_id: str) -> bool:
    """มีดของซีซั่นนี้หมดอายุแล้วไหม: ซีซั่นปัจจุบันเปลี่ยนไปแล้ว หรือเลยเวลา ends_at"""
    if season_id != BP_SEASON["season_id"]:
        return True
    return bool(BP_SEASON["ends_at"]) and time.time() >= BP_SEASON["ends_at"]


def _vmax_gear_expired(item_id: str) -> bool:
    sid = VMAX_RAID_GEAR.get(item_id, {}).get("season_id")
    return bool(sid) and _bp_season_expired(sid)


@app.route('/api/battlepass/knife/shop')
def api_bp_knife_shop():
    uid = _vmax_uid_from({})
    owned = _bp_econ().knives(uid)
    items = {k: {**v, "bought": k in owned, "expired": _vmax_gear_expired(k)}
             for k, v in VMAX_RAID_GEAR.items() if v.get("season_id")}
    return jsonify({"st": "ok", "season": {**BP_SEASON, "expired": _bp_season_expired(BP_SEASON["season_id"])},
                    "coins": _bp_econ().coins(uid), "knives": items, "retire_choices": BP_KNIFE_RETIRE_CHOICES})


@app.route('/api/battlepass/knife/buy', methods=['POST'])
@require_auth_toggleable
@_bp_locked
def api_bp_knife_buy():
    """body: {uid, item_id} -> แลกเหรียญพาสเป็นมีดซีซั่นปัจจุบัน (เข้าคลัง)"""
    b = request.get_json(silent=True) or {}
    uid = _vmax_uid_from(b)
    item_id = str(b.get("item_id", ""))
    spec = VMAX_RAID_GEAR.get(item_id)
    if not spec or not spec.get("season_id"):
        return jsonify({"st": "error", "msg": "ไม่มีมีดซีซั่นนี้"}), 404
    if _vmax_gear_expired(item_id):
        return jsonify({"st": "error", "msg": "มีดซีซั่นนี้หมดอายุแล้ว แลกซื้อไม่ได้"}), 400
    price = int(spec["bp_coin_price"])
    res, coins = _bp_econ().knife_buy(uid, item_id, price)       # เช็ค+หักเหรียญ+บันทึกว่าซื้อแล้ว ในธุรกรรมเดียว
    if res == "owned":
        return jsonify({"st": "error", "msg": "ซีซั่นนี้แลกเล่มนี้ไปแล้ว"}), 400
    if res == "poor":
        return jsonify({"st": "error", "msg": f"เหรียญพาสไม่พอ (ต้องการ {price} มี {coins})"}), 400
    _vmax_gear_stash_put(uid, item_id, 1)
    return jsonify({"st": "ok", "msg": f"แลก {spec['name_th']} เข้าคลังแล้ว", "coins": coins})


@app.route('/api/battlepass/knife/retire', methods=['POST'])
@require_auth_toggleable
def api_bp_knife_retire():
    """body: {uid, item_id, qty?, choice?} -> (เฉพาะมีดของซีซั่นที่จบแล้ว) แลกคืนเป็นของที่เลือก
    choice: keycards (ค่าเริ่มต้น) | breach_charge | plating_kit | scrap  — ดู BP_KNIFE_RETIRE_CHOICES"""
    b = request.get_json(silent=True) or {}
    uid = _vmax_uid_from(b)
    item_id, qty = str(b.get("item_id", "")), max(1, min(int(b.get("qty", 1)), 20))
    choice = str(b.get("choice", "keycards"))
    if choice not in BP_KNIFE_RETIRE_CHOICES:
        return jsonify({"st": "error", "msg": "choice ไม่ถูกต้อง", "choices": list(BP_KNIFE_RETIRE_CHOICES)}), 400
    spec = VMAX_RAID_GEAR.get(item_id)
    if not spec or not spec.get("season_id"):
        return jsonify({"st": "error", "msg": "ไม่ใช่มีดซีซั่น"}), 400
    if not _vmax_gear_expired(item_id):
        return jsonify({"st": "error", "msg": "ซีซั่นยังไม่จบ มีดยังใช้งานได้ ยังแลกคืนไม่ได้"}), 400
    gst = _vmax_new_game_state(uid)
    if gst["status"] != "raid":                    # มีดที่ค้างอยู่ใน loadout (ยังไม่ได้เข้าแมพ) คืนเข้าคลังก่อน จะได้แลกคืนได้
        for i in list(gst.get("loadout", [])):
            if i == item_id:
                gst["loadout"].remove(i)
                _vmax_gear_stash_put(uid, i, 1)
        if gst.get("loadout_hand") == item_id:
            gst["loadout_hand"] = None
            _vmax_gear_stash_put(uid, item_id, 1)
    if not _vmax_gear_stash_take(uid, item_id, qty):
        return jsonify({"st": "error", "msg": "ในคลังมีมีดไม่พอ"}), 400
    got = _bp_grant_items(uid, {k: n * qty for k, n in BP_KNIFE_RETIRE_CHOICES[choice]["items"].items()})
    return jsonify({"st": "ok", "msg": f"แลกคืน {spec['name_th']} x{qty} เป็น {BP_KNIFE_RETIRE_CHOICES[choice]['name_th']} แล้ว", "received": got})


@app.route('/api/battlepass/coin_shop')
def api_bp_coin_shop():
    uid = _vmax_uid_from({})
    return jsonify({"st": "ok", "coins": _bp_econ().coins(uid), "shop": BP_COIN_SHOP, "mystery_box_price": BP_MYSTERY_BOX_PRICE,
                    "box_pity_in": BP_BOX_PITY - (_bp_econ().box_count(uid) % BP_BOX_PITY), "misc_items": BP_MISC_ITEMS,
                    "med_specs": BP_MED_SPEC, "med_refund": _bp_med_refund_window()})


@app.route('/api/battlepass/coin_shop/buy', methods=['POST'])
@require_auth_toggleable
@_bp_locked
def api_bp_coin_shop_buy():
    """body: {uid, shop_id, qty?} -> ใช้เหรียญพาสที่เหลือแลกของตรงๆ (คีย์การ์ด/ระเบิดเจาะประตู/ชุดชุบเกราะ/ยาซีซั่น)"""
    b = request.get_json(silent=True) or {}
    uid = _vmax_uid_from(b)
    shop_id = str(b.get("shop_id", ""))
    row = BP_COIN_SHOP.get(shop_id)
    qty = _bp_safe_int(b.get("qty", 1))
    if not row:
        return jsonify({"st": "error", "msg": "ไม่มีสินค้านี้", "known": list(BP_COIN_SHOP)}), 404
    econ = _bp_econ()
    cost = row["price"] * qty
    if row.get("bp_med"):                     # ยาประจำซีซั่น: เข้าคลังยาซีซั่น (หมดซีซั่นแล้วหาย / แลกคืนได้ชั่วโมงสุดท้าย)
        if _bp_season_expired(BP_SEASON["season_id"]):
            return jsonify({"st": "error", "msg": "ซีซั่นนี้หมดเวลาแล้ว ซื้อยาซีซั่นไม่ได้ รอซีซั่นใหม่"}), 400
        sid = _bp_med_sync(uid)
        coins = econ.med_buy(uid, sid, row["bp_med"], int(row["qty"]) * qty, cost)    # หักเหรียญ + เพิ่มยา ในธุรกรรมเดียว
        if coins is None:
            return jsonify({"st": "error", "msg": f"เหรียญพาสไม่พอ (ต้องการ {cost} มี {econ.coins(uid)})"}), 400
        return jsonify({"st": "ok", "msg": f"แลก {row['name_th']} x{qty} เข้าคลังยาซีซั่นแล้ว (หมดซีซั่นแล้วหาย แต่แลกคืนเป็นเหรียญได้ก่อนจบซีซั่น)",
                        "received": {row["bp_med"]: int(row["qty"]) * qty}, "coins": coins, "season_id": sid})
    coins = econ.spend(uid, cost, "shop_buy", f"{shop_id}x{qty}")
    if coins is None:
        return jsonify({"st": "error", "msg": f"เหรียญพาสไม่พอ (ต้องการ {cost} มี {econ.coins(uid)})"}), 400
    got = _bp_grant_items(uid, {k: n * qty for k, n in row["items"].items()})
    return jsonify({"st": "ok", "msg": f"แลก {row['name_th']} x{qty} แล้ว", "received": got, "coins": coins})


@app.route('/api/battlepass/mystery_box/open', methods=['POST'])
@require_auth_toggleable
@_bp_locked
def api_bp_mystery_box_open():
    """body: {uid, count?(1-10)} -> เปิดกล่องสุ่มด้วยเหรียญพาส (ลุ้นดวง) ทุก BP_BOX_PITY กล่องการันตีกุญแจแดง/ทองหนึ่งใบ"""
    b = request.get_json(silent=True) or {}
    uid = _vmax_uid_from(b)
    count = _bp_safe_int(b.get("count", 1), 1, 1, 10)
    cost = BP_MYSTERY_BOX_PRICE * count
    res = _bp_econ().box_open(uid, cost, count)           # หักเหรียญ + นับกล่อง ในธุรกรรมเดียว
    if res is None:
        return jsonify({"st": "error", "msg": f"เหรียญพาสไม่พอ (ต้องการ {cost} มี {_bp_econ().coins(uid)})"}), 400
    coins, start = res
    results = []
    for i in range(count):
        pity = (start + i + 1) % BP_BOX_PITY == 0
        pool = BP_MYSTERY_BOX_PITY_POOL if pity else BP_MYSTERY_BOX_POOL
        reward = random.choices([r for _, r in pool], weights=[w for w, _ in pool])[0]
        results.append({"reward": _bp_grant_items(uid, reward), "pity": pity})
    return jsonify({"st": "ok", "results": results, "coins": coins,
                    "box_pity_in": BP_BOX_PITY - ((start + count) % BP_BOX_PITY)})


def _bp_med_refund_window() -> dict:
    """หน้าต่างแลกคืนยา: เปิดใน BP_MED_REFUND_WINDOW_SEC วินาทีสุดท้ายก่อน ends_at หรือเมื่อ admin เปิดเอง"""
    now = time.time()
    ends = float(BP_SEASON.get("ends_at") or 0)
    expired = _bp_season_expired(BP_SEASON["season_id"])
    sched = bool(ends) and 0 < ends - now <= BP_MED_REFUND_WINDOW_SEC
    manual = bool(BP_SEASON.get("refund_open"))
    return {"open": (not expired) and (sched or manual), "window_sec": BP_MED_REFUND_WINDOW_SEC,
            "ends_in_sec": int(ends - now) if ends else None,
            "opens_in_sec": max(0, int(ends - BP_MED_REFUND_WINDOW_SEC - now)) if ends else None,
            "season_expired": expired}


def _bp_med_tick(st: dict):
    """เดินบัฟยาซีซั่นแบบ lazy (ฟื้น HP ต่อวินาที / หมดเวลา max HP ชั่วคราว) — เรียกตอนดึงสถานะเกม/ใช้ยา"""
    buffs = st.get("bp_buffs")
    if not buffs:
        return
    now, rk = time.time(), st.get("started_at", 0.0)
    if st.get("status") != "raid":                       # Raid จบแล้ว: คืน max HP ที่บวกไว้ (ถ้ายังเป็น Raid เดิม) แล้วล้างบัฟ
        t = buffs.get("tough")
        if t and t.get("raid_key") == rk:
            st["max_hp"] = max(1, st["max_hp"] - t["bonus"])
            st["hp"] = min(st["hp"], st["max_hp"])
        st["bp_buffs"] = {}
        return
    for slot, b in list(buffs.items()):
        if b.get("raid_key") != rk:                      # เป็นของ Raid ก่อนหน้า (start รีเซ็ต max HP ไปแล้ว) -> ทิ้งเฉยๆ
            del buffs[slot]
            continue
        if slot == "regen":
            t = min(now, b["until"])
            dt = t - b["last"]
            if dt > 0:
                b["carry"] += dt * b["rate"]
                whole = int(b["carry"])
                b["carry"] -= whole
                if whole and st.get("hp", 0) > 0:
                    st["hp"] = min(st["max_hp"], st["hp"] + whole)
                b["last"] = t
            if now >= b["until"]:
                del buffs[slot]
        elif slot == "tough" and now >= b["until"]:
            st["max_hp"] = max(1, st["max_hp"] - b["bonus"])
            st["hp"] = max(1, min(st["hp"], st["max_hp"])) if st.get("hp", 0) > 0 else st["hp"]
            del buffs[slot]


def _bp_med_apply_buff(st: dict, buff: dict):
    _bp_med_tick(st)                                      # เคลียร์ของเก่าก่อน แล้วค่อยใส่ของใหม่
    now, rk = time.time(), st.get("started_at", 0.0)
    buffs = st.setdefault("bp_buffs", {})
    kind = buff["kind"]
    old = buffs.get(kind)
    if kind == "regen":
        buffs["regen"] = {"raid_key": rk, "rate": max(buff["rate"], old["rate"] if old else 0.0), "last": now,
                          "carry": old["carry"] if old else 0.0, "until": max(now + buff["secs"], old["until"] if old else 0.0)}
    elif kind == "tough":
        ob = old["bonus"] if old else 0
        nb = min(BP_MED_TOUGH_CAP, max(ob, buff["bonus"]))
        diff = nb - ob
        st["max_hp"] += diff
        st["hp"] = min(st["max_hp"], st["hp"] + diff)
        buffs["tough"] = {"raid_key": rk, "bonus": nb, "until": max(now + buff["secs"], old["until"] if old else 0.0)}


def _bp_med_active_buffs(st: dict) -> dict:
    now = time.time()
    return {k: {**{kk: (round(vv, 2) if isinstance(vv, float) else vv) for kk, vv in b.items() if kk in ("rate", "bonus")},
                "secs_left": max(0, int(b["until"] - now))}
            for k, b in (st.get("bp_buffs") or {}).items()}


@app.route('/api/battlepass/med/use', methods=['POST'])
@require_auth_toggleable
@_bp_locked
def api_bp_med_use():
    """body: {uid, item_id} -> ใช้ยา ฟื้น HP ใน Raid (ต้องอยู่ใน Raid และ HP ยังไม่เต็ม)
    - item_id ยาปกติ (bandage/painkiller/...): ตัดจากกระเป๋าไอเทมเหมือนเดิม ฟื้น HP ตาม BP_MED_HEAL
    - item_id ยาซีซั่น (bpmed_*): ตัดจากคลังยาซีซั่น ฟื้น HP ตาม BP_MED_SPEC + บัฟพิเศษเล็กน้อย (ซีซั่นหมดแล้วใช้ไม่ได้)"""
    b = request.get_json(silent=True) or {}
    uid = _vmax_uid_from(b)
    item_id = str(b.get("item_id", ""))
    spec = BP_MED_SPEC.get(item_id)
    heal = spec["heal"] if spec else BP_MED_HEAL.get(item_id)
    if heal is None:
        return jsonify({"st": "error", "msg": "ไม่ใช่ยาที่ใช้ได้", "known": list(BP_MED_HEAL) + list(BP_MED_SPEC)}), 400
    st = _vmax_new_game_state(uid)
    if st["status"] != "raid":
        return jsonify({"st": "error", "msg": "ใช้ยาได้เฉพาะใน Raid"}), 400
    _bp_med_tick(st)
    if st["hp"] >= st["max_hp"]:
        return jsonify({"st": "error", "msg": "HP เต็มอยู่แล้ว"}), 400
    if spec:
        sid = _bp_med_sync(uid)                         # ซีซั่นจบ/หมดเวลา -> ยาที่เหลือถูกล้างตรงนี้
        if _bp_season_expired(sid):
            return jsonify({"st": "error", "msg": "ยาซีซั่นหมดอายุแล้ว ใช้ไม่ได้"}), 400
        if not _bp_econ().med_use(uid, sid, item_id):   # ตัดยา 1 ชิ้น + ตัดเหรียญของชิ้นนั้น (แลกคืนไม่ได้) แบบ atomic
            return jsonify({"st": "error", "msg": "ไม่มียาชนิดนี้ในคลังยาซีซั่น"}), 400
    else:
        with BAG_LOCK:
            bag = _bag_get(uid)["item"]
            if bag.get(item_id, 0) < 1:
                return jsonify({"st": "error", "msg": "ไม่มียาชนิดนี้ในกระเป๋า"}), 400
            bag[item_id] -= 1
    st["hp"] = min(st["max_hp"], st["hp"] + heal)
    out = {"st": "ok", "msg": f"ใช้ {item_id} ฟื้น HP +{heal}", "hp": st["hp"], "max_hp": st["max_hp"]}
    if spec:
        _bp_med_apply_buff(st, spec["buff"])
        out.update({"msg": f"ใช้ {spec['name_th']} ฟื้น HP +{heal} · {spec['buff']['label_th']}", "hp": st["hp"], "max_hp": st["max_hp"],
                    "buffs": _bp_med_active_buffs(st), "survival_effect": spec.get("survival_effect", {})})
    return jsonify(out)


@app.route('/api/battlepass/med/status')
@require_auth_toggleable
def api_bp_med_status():
    """?uid= -> คลังยาซีซั่น + บัฟที่ทำงานอยู่ + หน้าต่างแลกคืน (ดูก่อนซีซั่นจบว่าเหลือยาอะไรให้แลกคืน)"""
