@app.route('/api/battlepass/med/refund', methods=['POST'])
@require_auth_toggleable
@_bp_locked
def api_bp_med_refund():
    """body: {uid, item_id?, qty?} -> แลกยาซีซั่นที่ยังไม่ได้ใช้คืนเป็นเหรียญพาส (เฉพาะช่วงหน้าต่างก่อนซีซั่นจบ)
    ไม่ใส่ item_id = แลกคืนทุกชนิด / ไม่ใส่ qty = แลกคืนทั้งหมดของชนิดนั้น  เหรียญที่ได้ไม่ผูกซีซั่น เก็บไว้แลกซีซั่นหน้าได้
    ตัดยา + เติมเหรียญ + บันทึก tx ในธุรกรรมเดียว -> ยิงซ้อนพร้อมกันก็ได้เหรียญครั้งเดียว"""
    b = request.get_json(silent=True) or {}
    uid = _vmax_uid_from(b)
    win = _bp_med_refund_window()
    if not win["open"]:
        msg = "ซีซั่นจบแล้ว ยาที่เหลือหายไปแล้ว แลกคืนไม่ได้" if win["season_expired"] else "ยังไม่ถึงช่วงแลกคืน (เปิดเฉพาะชั่วโมงสุดท้ายก่อนซีซั่นจบ)"
        if win["season_expired"]:
            _bp_med_sync(uid)
        return jsonify({"st": "error", "msg": msg, "refund": win}), 400
    sid = _bp_med_sync(uid)
    only = str(b.get("item_id", "")).strip()
    qty = None if b.get("qty") in (None, "") else _bp_safe_int(b.get("qty"), 1, 1, 100000)
    res = _bp_econ().med_refund(uid, sid, only, qty, BP_MED_REFUND_RATE)
    if res is None:
        return jsonify({"st": "error", "msg": "ไม่มียาซีซั่นให้แลกคืน" if not only else "ไม่มียาชนิดนี้ในคลังยาซีซั่น"}), 400
    total, detail, coins = res
    audit_log("bp_med_refund", uid=uid, season_id=sid, coins=total, detail=detail)
    return jsonify({"st": "ok", "msg": f"แลกคืนยาซีซั่นเป็นเหรียญพาส +{total} (เก็บไว้ใช้ซีซั่นหน้าได้)", "refunded": detail, "coins": coins})


