@app.route('/api/battlepass/season/end', methods=['POST'])
@require_staff_rank('admin')
def api_bp_season_end():
    """body: {next_season_id, next_name_th?, next_ends_at?} -> ปิดซีซั่นปัจจุบัน มีดซีซั่นเก่าหมดอายุทันที"""
    b = request.get_json(silent=True) or {}
    nxt = str(b.get("next_season_id", "")).strip()
    if not nxt or nxt == BP_SEASON["season_id"]:
        return jsonify({"st": "error", "msg": "ต้องระบุ next_season_id ที่ไม่ซ้ำกับซีซั่นปัจจุบัน"}), 400
    BP_SEASON_HISTORY.append({"season_id": BP_SEASON["season_id"], "ended_at": time.time()})
    BP_SEASON.update({"season_id": nxt, "name_th": str(b.get("next_name_th", nxt)), "ends_at": float(b.get("next_ends_at", 0) or 0), "refund_open": False})
