@app.route('/api/game-service/games', methods=['GET'])
def api_gs_games():
    return jsonify({"st": "ok", "version": VMAX_GS_VERSION,
                    "games": [{"game_id": g['game_id'], "name": g['name'], "builtin": g['builtin'],
                               "bounds": g['bounds']} for g in VMAX_GS_GAMES.values()]})


@app.route('/api/game-service/games/register', methods=['POST'])
@require_staff_rank('admin')
def api_gs_games_register():
    """body: {game_id, name?, bounds?:{min_x,min_y,max_x,max_y}, zones?:[{id,name,x,y,w,h}], breakers?:[{id,x,y,zone}]}"""
    b = request.get_json(silent=True) or {}
    try:
        cfg = vmax_game_service_register(b.get('game_id'), b.get('name'), b.get('bounds'),
                                         b.get('zones'), b.get('breakers'))
    except ValueError as exc:
        return jsonify({"st": "error", "code": "bad_game_id", "msg": str(exc)}), 400
    except PermissionError as exc:
        return jsonify({"st": "error", "code": "builtin", "msg": str(exc)}), 409
    audit_log("game_service_register", uid=str(request.vmax_uid), game_id=cfg['game_id'])
    return jsonify({"st": "ok", "game": cfg})


@app.route('/api/game-service/<game_id>/session', methods=['POST'])
@require_auth
def api_gs_session_create(game_id):
    """body: {mode?, x?, y?, hp?, max_hp?, aim?, glasses_equipped?, zones?, breakers?}
    -> {session_id, config, effects}  (ผู้เล่น 1 คนมีได้ 5 session ต่อเกม; เกินจะไล่อันเก่าสุดทิ้ง)"""
    game, err = _vmax_gs_game_or_404(game_id)
    if err:
        return err
    b = request.get_json(silent=True)
    b = b if isinstance(b, dict) else {}
    uid = str(request.vmax_uid)
    _vmax_gs_prune()
    with VMAX_SL_LOCK:
        mine = sorted([s for s in VMAX_GS_SESSIONS.values() if s['uid'] == uid and s['game_id'] == game['game_id']],
                      key=lambda s: s['last'])
        for old in mine[:max(0, len(mine) - VMAX_GS_MAX_SESSIONS_PER_UID + 1)]:
            VMAX_GS_SESSIONS.pop(old['sid'], None)
        st = _vmax_gs_make_state(game, uid, b)
        sid = f"gs_{uuid.uuid4().hex[:16]}"
        VMAX_GS_SESSIONS[sid] = {"sid": sid, "game_id": game['game_id'], "uid": uid, "st": st,
                                 "created": time.time(), "last": time.time()}
        _vmax_sl_tick(st)
        eff = _vmax_gs_effects(st)
    audit_log("game_service_session_create", uid=uid, game_id=game['game_id'], session_id=sid)
    return jsonify({"st": "ok", "session_id": sid, "game_id": game['game_id'],
                    "config": _vmax_gs_config_public(game), "effects": eff})


@app.route('/api/game-service/<game_id>/session/<sid>', methods=['GET'])
@require_auth
def api_gs_session_get(game_id, sid):
    return _vmax_gs_run(game_id, sid, _vmax_gs_act_get)


@app.route('/api/game-service/<game_id>/session/<sid>', methods=['DELETE'])
@require_auth
def api_gs_session_close(game_id, sid):
    uid = str(request.vmax_uid)
    with VMAX_SL_LOCK:
        s = VMAX_GS_SESSIONS.get(str(sid))
        if s is None or s['uid'] != uid or s['game_id'] != str(game_id).strip().lower():
            return jsonify({"st": "error", "code": "no_session", "msg": "ไม่พบ session"}), 404
        VMAX_GS_SESSIONS.pop(str(sid), None)
    return jsonify({"st": "ok", "closed": str(sid)})


def _vmax_gs_register_action_route(suffix, endpoint, fn):
    def _view(game_id, sid):
        return _vmax_gs_run(game_id, sid, fn)
    _view.__name__ = endpoint
    app.add_url_rule(f'/api/game-service/<game_id>/session/<sid>/{suffix}', endpoint=endpoint,
                     view_func=require_auth(_view), methods=['POST'])


for _gs_suffix, _gs_endpoint, _gs_fn in (
        ('sync', 'api_gs_sync', _vmax_gs_act_sync),
        ('light', 'api_gs_light', _vmax_gs_act_light),
        ('smoke', 'api_gs_smoke', _vmax_gs_act_smoke),
        ('shot', 'api_gs_shot', _vmax_gs_act_shot),
        ('breaker/shoot', 'api_gs_breaker_shoot', _vmax_gs_act_breaker_shoot),
        ('breaker/switch', 'api_gs_breaker_switch', _vmax_gs_act_breaker_switch),
        ('breaker/repair', 'api_gs_breaker_repair', _vmax_gs_act_breaker_repair)):
    _vmax_gs_register_action_route(_gs_suffix, _gs_endpoint, _gs_fn)


@app.route('/api/game-service/spec', methods=['GET'])
def api_gs_spec():
    return jsonify({
        "st": "ok", "name": "VMAX Game Service", "version": VMAX_GS_VERSION,
        "sdk": "/sdk/vmax-game-service.js", "auth": "Authorization: Bearer <JWT>",
        "flow": ["POST /api/game-service/<game_id>/session", "POST .../sync {x,y,hp,aim,enemies[]}",
                 "POST .../light | smoke | shot | breaker/shoot | breaker/switch | breaker/repair",
                 "GET .../session/<sid>", "DELETE .../session/<sid>"],
        "you_own": ["position", "hp (apply effects.hp_delta)", "enemy AI (apply effects.enemies[].hp/alive/blind_left)"],
        "service_owns": ["smoke clouds", "flashlight backscatter (wall of light)", "beacon noise",
                         "breaker panels / arc fault / zone power", "flash blindness", "shot miss probability"],
        "errors": "ทุก error มี code (no_session, no_charges, cooldown, battery_empty, out_of_range, too_far, jammed, destroyed, not_broken, repair_pending, not_active, unknown_game)",
        "games": sorted(VMAX_GS_GAMES),
    })


@app.route('/sdk/vmax-game-service.js', methods=['GET'])
def vmax_gs_sdk_js():
    resp = app.response_class(VMAX_GAME_SERVICE_SDK_JS, mimetype='application/javascript')
    resp.headers['Cache-Control'] = 'public, max-age=300'
    return resp


@app.after_request
def _vmax_gs_cors(resp):
    """CORS แบบ allow-list เท่านั้น (env VMAX_GAME_SERVICE_CORS_ORIGINS) — ไม่ตั้ง = same-origin อย่างเดียว"""
    try:
        if request.path.startswith('/api/game-service/'):
            allow = {o.strip() for o in os.environ.get("VMAX_GAME_SERVICE_CORS_ORIGINS", "").split(",") if o.strip()}
            origin = request.headers.get('Origin', '')
            if origin and origin in allow:
                resp.headers['Access-Control-Allow-Origin'] = origin
                resp.headers['Vary'] = 'Origin'
                resp.headers['Access-Control-Allow-Headers'] = 'Authorization, Content-Type'
                resp.headers['Access-Control-Allow-Methods'] = 'GET, POST, DELETE, OPTIONS'
                resp.headers['Access-Control-Max-Age'] = '600'
    except Exception:
        pass
    return resp


