# ---------------------------------------------------------------------------
# JavaScript SDK  (เสิร์ฟที่ /sdk/vmax-game-service.js)
# ---------------------------------------------------------------------------
VMAX_GAME_SERVICE_SDK_JS = r'''/* VMAX Game Service SDK v1.0.0 — smoke / flashlight (wall of light) / breaker panels for any game
 *
 *   const svc = new VMAXGameService({ gameId: 'my-game' });          // token: localStorage 'vmax_token' หรือส่ง { token } / { tokenProvider }
 *   const s = await svc.createSession({ x: 100, y: 200, hp: 100, mode: 'normal' });
 *   s.startAutoSync(() => ({ x: player.x, y: player.y, aim: player.aim, hp: player.hp,
 *                            enemies: enemies.map(e => ({ id: e.id, x: e.x, y: e.y, hp: e.hp, alive: e.alive })) }));
 *   s.on('effects', fx => { ... });           // ทุกครั้งที่ server ตอบ
 *   s.on('damage', d => player.hp -= d.amount); // hp_delta < 0 (อาร์คแฟลช ฯลฯ)
 *   s.on('enemies', list => applyToYourEnemies(list));  // hp/alive/blind_left หลังโดนอาร์ค/ไฟฉาย
 *   await s.toggleLight(); await s.setPreset('warm_low'); await s.throwSmoke(tx, ty);
 *   const shot = await s.shot();               // { miss, reason, beacon, beacon_bonus_damage } — เรียกก่อนคำนวณการยิงของเกม
 *   await s.shootBreaker({ hitZone: 'live' }); await s.switchBreaker(); await s.repairBreaker();
 *   // ทุกเฟรมวาด:  s.draw(ctx, { camX, camY, width, height });
 *   s.close();
 */
(function (root) {
  'use strict';
  if (root.VMAXGameService) return;

  function VMAXGameError(message, status, code, data) {
    const e = new Error(message); e.name = 'VMAXGameError'; e.status = status; e.code = code; e.data = data; return e;
  }

  class VMAXGameSession {
    constructor(svc, data) {
      this.svc = svc; this.id = data.session_id; this.gameId = data.game_id; this.config = data.config || {};
      this.effects = data.effects || {}; this.closed = false;
      this._l = {}; this._q = Promise.resolve(); this._seenFx = {}; this._timer = null; this._inflight = false;
      this._pos = { x: 0, y: 0, aim: 0 };
      this._repairTimers = {};
    }
    on(evt, fn) { (this._l[evt] = this._l[evt] || []).push(fn); return this; }
    off(evt, fn) { this._l[evt] = (this._l[evt] || []).filter(f => f !== fn); return this; }
    _emit(evt, v) { (this._l[evt] || []).slice().forEach(f => { try { f(v); } catch (e) { console.error('[VMAXGameService]', e); } }); }
    _path(suffix) { return '/api/game-service/' + encodeURIComponent(this.gameId) + '/session/' + encodeURIComponent(this.id) + (suffix ? '/' + suffix : ''); }
    _apply(data) {
      const fx = data.effects; if (!fx) return data;
      this.effects = fx; this._emit('effects', fx);
      if (fx.hp_delta < 0) this._emit('damage', { amount: -fx.hp_delta, hp: fx.hp });
      if (fx.dead) this._emit('dead', fx);
      if (fx.enemies && fx.enemies.length) this._emit('enemies', fx.enemies);
      (fx.fx || []).forEach(f => { if (!this._seenFx[f.id]) { this._seenFx[f.id] = 1; this._emit(f.type, f); } });
      return data;
    }
    // คิวแบบเรียงลำดับ: คำสั่งที่เปลี่ยน state จะไม่ชนกันเอง
    _call(method, suffix, body) {
      if (this.closed) return Promise.reject(VMAXGameError('session closed', 0, 'closed'));
      const run = () => this.svc._req(method, this._path(suffix), body).then(d => this._apply(d));
      const p = this._q.then(run, run);
      this._q = p.catch(() => {});
      p.catch(err => this._emit('error', err));
      return p;
    }
    refresh() { return this._call('GET', ''); }
    sync(state) {
      if (state) { if (state.x != null) this._pos.x = state.x; if (state.y != null) this._pos.y = state.y; if (state.aim != null) this._pos.aim = state.aim; }
      return this._call('POST', 'sync', state || {});
    }
    startAutoSync(getState, intervalMs) {
      this.stopAutoSync();
      this._timer = setInterval(() => {
        if (this._inflight || this.closed) return;
        this._inflight = true;
        this.sync(getState()).catch(() => {}).then(() => { this._inflight = false; });
      }, intervalMs || 250);
      return this;
    }
    stopAutoSync() { if (this._timer) { clearInterval(this._timer); this._timer = null; } return this; }
    setLight(opts) { return this._call('POST', 'light', opts || {}); }
    toggleLight() { return this.setLight({}); }
    setPreset(preset) { return this.setLight({ preset: preset }); }
    cyclePreset() {
      const ids = (this.config.presets || []).map(p => p.id); const cur = (this.effects.light || {}).preset;
      if (!ids.length) return Promise.resolve(null);
      return this.setPreset(ids[(ids.indexOf(cur) + 1) % ids.length]);
    }
    throwSmoke(targetX, targetY) {
      const b = {}; if (targetX != null) { b.target_x = targetX; b.target_y = targetY; }
      return this._call('POST', 'smoke', b);
    }
    // เรียกก่อนคำนวณการยิงของเกม -> { miss, reason, beacon, beacon_bonus_damage }
    shot(opts) { return this._call('POST', 'shot', opts || {}).then(d => d.shot); }
    nearestBreaker(x, y, maxDist) {
      const px = x != null ? x : this._pos.x, py = y != null ? y : this._pos.y; let best = null, bd = Infinity;
      (this.effects.breakers || []).forEach(b => { const d = Math.hypot(b.x - px, b.y - py); if (d < bd) { bd = d; best = b; } });
      return best && (maxDist == null || bd <= maxDist) ? best : null;
    }
    shootBreaker(opts) {
      opts = opts || {}; const id = opts.breakerId || (this.nearestBreaker() || {}).id;
      return this._call('POST', 'breaker/shoot', { breaker_id: id, hit_zone: opts.hitZone || 'auto' }).then(d => d.result);
    }
    switchBreaker(breakerId) {
      const id = breakerId || (this.nearestBreaker() || {}).id; return this._call('POST', 'breaker/switch', { breaker_id: id });
    }
    // เริ่มซ่อม แล้วตั้งเวลาเรียกซ่อมเสร็จให้อัตโนมัติ (resolve เมื่อซ่อมเสร็จ / ถูกยกเลิกเพราะเดินออก)
    repairBreaker(breakerId) {
      const id = breakerId || (this.nearestBreaker() || {}).id;
      return this._call('POST', 'breaker/repair', { breaker_id: id }).then(d => {
        if (!(d.repair && d.repair.started)) return d;
        return new Promise((resolve, reject) => {
          clearTimeout(this._repairTimers[id]);
          this._repairTimers[id] = setTimeout(() => {
            this._call('POST', 'breaker/repair', { breaker_id: id }).then(resolve, reject);
          }, (d.repair.seconds || 5) * 1000 + 250);
        });
      });
    }
    close() {
      if (this.closed) return Promise.resolve();
      this.stopAutoSync(); Object.keys(this._repairTimers).forEach(k => clearTimeout(this._repairTimers[k]));
      this.closed = true;
      return this.svc._req('DELETE', this._path(''), undefined, true).catch(() => {});
    }
    // ---- Canvas 2D renderer (ควัน, โซนไฟดับ, ตู้เบรกเกอร์, กรวยไฟฉาย, กำแพงแสง, อาร์คแฟลช) ----
    // o = { camX, camY, width, height, playerX?, playerY? }   (world -> screen = world - cam)
    draw(ctx, o) {
      const fx = this.effects || {}, L = fx.light || {}; o = o || {};
      const cx = o.camX || 0, cy = o.camY || 0, W = o.width || ctx.canvas.width, H = o.height || ctx.canvas.height;
      const px = (o.playerX != null ? o.playerX : this._pos.x) - cx, py = (o.playerY != null ? o.playerY : this._pos.y) - cy;
      const S = (x, y) => ({ x: x - cx, y: y - cy });
      ctx.save();
      (fx.zones || []).forEach(z => {
        if (fx.power && fx.power[z.id] === false) { const q = S(z.x, z.y); ctx.fillStyle = 'rgba(2,4,14,.58)'; ctx.fillRect(q.x, q.y, z.w, z.h); }
      });
      const COL = { on: '#3fbf6f', off: '#8a8f94', jammed_on: '#e0a93a', jammed_off: '#e0a93a', arc_destroyed: '#3b2626' };
      (fx.breakers || []).forEach(b => {
        const q = S(b.x, b.y);
        ctx.fillStyle = '#22262a'; ctx.fillRect(q.x - 15, q.y - 20, 30, 40);
        ctx.fillStyle = COL[b.state] || '#888'; ctx.fillRect(q.x - 11, q.y - 16, 22, 10);
        ctx.fillStyle = '#111'; ctx.fillRect(q.x - 11, q.y - 2, 22, 14);
        ctx.fillStyle = 'rgba(255,255,255,.85)'; ctx.font = '11px system-ui'; ctx.fillText(String(b.state).replace('_', ' ').toUpperCase(), q.x - 24, q.y + 34);
      });
      (fx.smoke_clouds || []).forEach(s => {
        const q = S(s.x, s.y), a = 0.78 * (s.fade == null ? 1 : s.fade);
        for (let i = 0; i < 5; i++) {
          const ox = Math.cos(i * 1.9 + s.x) * s.r * 0.35, oy = Math.sin(i * 2.3 + s.y) * s.r * 0.3;
          const g = ctx.createRadialGradient(q.x + ox, q.y + oy, 4, q.x + ox, q.y + oy, s.r * 0.75);
          g.addColorStop(0, 'rgba(170,175,180,' + a * 0.55 + ')'); g.addColorStop(1, 'rgba(170,175,180,0)');
          ctx.fillStyle = g; ctx.beginPath(); ctx.arc(q.x + ox, q.y + oy, s.r * 0.75, 0, 6.283); ctx.fill();
        }
      });
      if (L.on) {
        const warm = L.preset === 'warm_low', col = warm ? '255,214,140' : '235,245,255', a0 = L.preset === 'ground_low' ? 0.10 : 0.2;
        ctx.save(); ctx.translate(px, py); ctx.rotate(L.aim || 0);
        const g = ctx.createRadialGradient(0, 0, 10, 0, 0, L.reach || 200);
        g.addColorStop(0, 'rgba(' + col + ',' + a0 * 2 + ')'); g.addColorStop(1, 'rgba(' + col + ',0)');
        ctx.fillStyle = g; ctx.beginPath(); ctx.moveTo(0, 0); ctx.arc(0, 0, L.reach || 200, -0.42, 0.42); ctx.closePath(); ctx.fill(); ctx.restore();
        if (L.smoke_density > 0.05) {
          const r = 60 + 170 * L.smoke_density, g2 = ctx.createRadialGradient(px, py, 6, px, py, r);
          g2.addColorStop(0, 'rgba(255,255,255,' + 0.55 * L.smoke_density + ')'); g2.addColorStop(1, 'rgba(255,255,255,0)');
          ctx.fillStyle = g2; ctx.beginPath(); ctx.arc(px, py, r, 0, 6.283); ctx.fill();
        }
      }
      (fx.fx || []).forEach(f => {
        const q = S(f.x, f.y), age = f.age || 0, k = Math.max(0, 1 - age / (f.ttl || 1));
        if (f.type === 'arc_flash') {
          const g = ctx.createRadialGradient(q.x, q.y, 4, q.x, q.y, 150);
          g.addColorStop(0, 'rgba(255,255,255,' + k + ')'); g.addColorStop(0.4, 'rgba(170,200,255,' + 0.55 * k + ')'); g.addColorStop(1, 'rgba(170,200,255,0)');
          ctx.fillStyle = g; ctx.beginPath(); ctx.arc(q.x, q.y, 150, 0, 6.283); ctx.fill();
        } else if (f.type === 'sparks' || f.type === 'spark_small') {
          ctx.strokeStyle = 'rgba(255,210,90,' + k + ')'; ctx.lineWidth = 2;
          for (let i = 0; i < 9; i++) {
            const an = i * 0.7 + f.x, ln = 8 + ((i * 7) % 5) * 5 * (1 - k * 0.4);
            ctx.beginPath(); ctx.moveTo(q.x + Math.cos(an) * 6, q.y + Math.sin(an) * 6); ctx.lineTo(q.x + Math.cos(an) * (6 + ln), q.y + Math.sin(an) * (6 + ln)); ctx.stroke();
          }
        }
      });
      const wo = Math.max(L.whiteout || 0, Math.min(1, (fx.blind_left || 0) / 1.2));
      if (wo > 0.03) {
        const g = ctx.createRadialGradient(W / 2, H / 2, 40, W / 2, H / 2, Math.max(W, H) * 0.6);
        g.addColorStop(0, 'rgba(255,255,255,' + Math.min(0.95, wo * 0.95) + ')'); g.addColorStop(1, 'rgba(245,248,255,' + Math.min(0.98, wo) + ')');
        ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
      }
      ctx.restore();
    }
  }

  class VMAXGameService {
    constructor(opts) {
      opts = opts || {};
      if (!opts.gameId) throw new Error('VMAXGameService: gameId is required');
      this.gameId = String(opts.gameId).toLowerCase(); this.baseUrl = (opts.baseUrl || '').replace(/\/+$/, '');
      this.token = opts.token || null; this.tokenProvider = opts.tokenProvider || null;
    }
    _token() {
      if (this.tokenProvider) return this.tokenProvider();
      if (this.token) return this.token;
      try { return localStorage.getItem('vmax_token') || ''; } catch (e) { return ''; }
    }
    _req(method, path, body, keepalive) {
      const headers = { 'Authorization': 'Bearer ' + this._token() };
      if (body !== undefined) headers['Content-Type'] = 'application/json';
      return fetch(this.baseUrl + path, { method: method, headers: headers, keepalive: !!keepalive,
        body: body === undefined ? undefined : JSON.stringify(body) }).then(r =>
        r.json().catch(() => null).then(d => {
          if (!r.ok || !d || d.st !== 'ok') throw VMAXGameError((d && d.msg) || ('HTTP ' + r.status), r.status, d && d.code, d);
          return d;
        }));
    }
    listGames() { return this._req('GET', '/api/game-service/games').then(d => d.games); }
    // opts: { mode, x, y, hp, max_hp, aim, glasses_equipped, zones:[{id,name,x,y,w,h}], breakers:[{id,x,y,zone}] }
    createSession(opts) {
      return this._req('POST', '/api/game-service/' + encodeURIComponent(this.gameId) + '/session', opts || {})
        .then(d => new VMAXGameSession(this, d));
    }
  }

  VMAXGameService.Session = VMAXGameSession;
  VMAXGameService.version = '1.0.0';
  root.VMAXGameService = VMAXGameService;
})(typeof window !== 'undefined' ? window : this);
'''


# ---------------------------------------------------------------------------
# Python SDK  (เสิร์ฟที่ /sdk/vmax_game_service.py — ใช้ stdlib ล้วน ไม่ต้องติดตั้งอะไรเพิ่ม)
# สำหรับเกมที่รันเซิร์ฟเวอร์เป็น Python (Flask/FastAPI/pygame/บอท ฯลฯ)
#
#   import vmax_game_service as vgs           # ดาวน์โหลดจาก /sdk/vmax_game_service.py
#   svc = vgs.VMAXGameServiceClient("https://your-vmax-host", "my-game", token=JWT)
#   with svc.create_session(x=100, y=200, hp=100) as s:
#       s.on("damage", lambda d: player.hurt(d["amount"]))
#       s.sync(x=player.x, y=player.y, aim=player.aim, enemies=[{"id": e.id, "x": e.x, "y": e.y, "hp": e.hp, "alive": e.alive} ...])
#       s.toggle_light(); s.throw_smoke(tx, ty)
#       if s.shot()["miss"]: ...              # เรียกก่อนคำนวณการยิงของเกม
#       s.shoot_breaker(hit_zone="live"); s.repair_breaker()   # repair_breaker(wait=True) รอจนซ่อมเสร็จ
# ---------------------------------------------------------------------------
VMAX_GAME_SERVICE_PY_SDK = r'''"""VMAX Game Service SDK for Python v1.0.0 (stdlib only)."""
import json
import math
import threading
import time
import urllib.error
import urllib.request

__version__ = "1.0.0"
__all__ = ["VMAXGameServiceClient", "VMAXGameSession", "VMAXGameServiceError"]


class VMAXGameServiceError(Exception):
    """Raised for any non-ok response. .status = HTTP status (0 = network), .code = service error code, .data = raw JSON."""

    def __init__(self, message, status=0, code=None, data=None):
        super().__init__(message)
        self.status, self.code, self.data = status, code, data


def _default_transport(method, url, headers, body, timeout):
    data = None if body is None else json.dumps(body).encode("utf-8")
    req = urllib.request.Request(url, data=data, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            raw, status = r.read(), r.status
    except urllib.error.HTTPError as e:
        raw, status = e.read(), e.code
    except (urllib.error.URLError, OSError) as e:
        raise VMAXGameServiceError("network error: %s" % e, 0, "network")
    try:
        return status, json.loads(raw.decode("utf-8")) if raw else None
    except ValueError:
        return status, None


class VMAXGameSession:
    def __init__(self, client, data):
        self.client = client
        self.id = data["session_id"]
        self.game_id = data.get("game_id", client.game_id)
        self.config = data.get("config") or {}
        self.effects = data.get("effects") or {}
        self.closed = False
        self._pos = {"x": 0.0, "y": 0.0, "aim": 0.0}
        self._listeners = {}
        self._lock = threading.RLock()        # เรียงลำดับคำสั่งที่เปลี่ยน state ไม่ให้ชนกัน
        self._seen_fx = set()
        self._auto = None
        self._auto_stop = threading.Event()

    # ---- events: effects | damage | dead | enemies | error | <fx type เช่น arc_flash, sparks, smoke_pop> ----
    def on(self, event, fn):
        self._listeners.setdefault(event, []).append(fn)
        return self

    def off(self, event, fn):
        self._listeners[event] = [f for f in self._listeners.get(event, []) if f is not fn]
        return self

    def _emit(self, event, value):
        for fn in list(self._listeners.get(event, [])):
            try:
                fn(value)
            except Exception as exc:  # listener พังต้องไม่ทำให้เกมล้ม
                print("[VMAXGameService] listener error:", repr(exc))

    def _path(self, suffix=""):
        from urllib.parse import quote
        base = "/api/game-service/%s/session/%s" % (quote(self.game_id, safe=""), quote(self.id, safe=""))
        return base + ("/" + suffix if suffix else "")

    def _apply(self, data):
        fx = data.get("effects")
        if not fx:
            return data
        self.effects = fx
        self._emit("effects", fx)
        if fx.get("hp_delta", 0) < 0:
            self._emit("damage", {"amount": -fx["hp_delta"], "hp": fx.get("hp")})
        if fx.get("dead"):
            self._emit("dead", fx)
        if fx.get("enemies"):
            self._emit("enemies", fx["enemies"])
        for f in fx.get("fx", []):
            if f.get("id") not in self._seen_fx:
                self._seen_fx.add(f.get("id"))
                if len(self._seen_fx) > 256:
                    self._seen_fx = set(list(self._seen_fx)[-64:])
                self._emit(f.get("type"), f)
        return data

    def _call(self, method, suffix="", body=None):
        if self.closed:
            raise VMAXGameServiceError("session closed", 0, "closed")
        with self._lock:
            try:
                data = self.client._request(method, self._path(suffix), body)
            except VMAXGameServiceError as exc:
                self._emit("error", exc)
                raise
            return self._apply(data)

    # ---- state ----
    def refresh(self):
        return self._call("GET")

    def sync(self, **state):
        """x, y, aim, hp, max_hp, glasses_equipped, mode, enemies=[{id,x,y,hp,alive}]"""
        for k in ("x", "y", "aim"):
            if state.get(k) is not None:
                self._pos[k] = float(state[k])
        return self._call("POST", "sync", state)

    def start_auto_sync(self, get_state, interval=0.25):
        """get_state() -> dict ของ kwargs ที่จะส่งเข้า sync(); รันใน thread แยกจนกว่าจะ stop/close"""
        self.stop_auto_sync()
        self._auto_stop.clear()

        def loop():
            while not self._auto_stop.wait(interval) and not self.closed:
                try:
                    self.sync(**(get_state() or {}))
                except VMAXGameServiceError:
                    pass  # ส่ง error event ไปแล้วใน _call
                except Exception as exc:
                    print("[VMAXGameService] auto-sync error:", repr(exc))
        self._auto = threading.Thread(target=loop, name="vmax-gs-autosync", daemon=True)
        self._auto.start()
        return self

    def stop_auto_sync(self):
        self._auto_stop.set()
        t, self._auto = self._auto, None
        if t is not None and t is not threading.current_thread():
            t.join(timeout=2.0)
        return self

    # ---- flashlight / smoke ----
    def set_light(self, on=None, preset=None):
        body = {}
        if on is not None:
            body["on"] = bool(on)
        if preset is not None:
            body["preset"] = preset
        return self._call("POST", "light", body)

    def toggle_light(self):
        return self.set_light()

    def set_preset(self, preset):
        return self.set_light(preset=preset)

    def cycle_preset(self):
        ids = [p["id"] for p in self.config.get("presets", [])]
        if not ids:
            return None
        cur = (self.effects.get("light") or {}).get("preset")
        return self.set_preset(ids[(ids.index(cur) + 1) % len(ids)] if cur in ids else ids[0])

    def throw_smoke(self, target_x=None, target_y=None):
        body = {} if target_x is None else {"target_x": target_x, "target_y": target_y}
        return self._call("POST", "smoke", body)

    def shot(self, heavy_armor=False):
        """-> {miss, reason, beacon, beacon_bonus_damage} — เรียกก่อนคำนวณการยิงของเกม"""
        return self._call("POST", "shot", {"heavy_armor": bool(heavy_armor)})["shot"]

    # ---- breaker ----
    def nearest_breaker(self, x=None, y=None, max_dist=None):
        px = self._pos["x"] if x is None else x
        py = self._pos["y"] if y is None else y
        best, bd = None, math.inf
        for b in self.effects.get("breakers", []):
            d = math.hypot(b["x"] - px, b["y"] - py)
            if d < bd:
                best, bd = b, d
        return best if best is not None and (max_dist is None or bd <= max_dist) else None

    def _bid(self, breaker_id):
        if breaker_id:
            return breaker_id
        b = self.nearest_breaker()
        if b is None:
            raise VMAXGameServiceError("ไม่มีตู้เบรกเกอร์ใน session นี้", 0, "no_breaker")
        return b["id"]

    def shoot_breaker(self, breaker_id=None, hit_zone="auto"):
        """-> result {outcome: miss|jam|jam_no_arc|arc_fault|already_destroyed, breaker_id, ...}"""
        return self._call("POST", "breaker/shoot", {"breaker_id": self._bid(breaker_id), "hit_zone": hit_zone})["result"]

    def switch_breaker(self, breaker_id=None):
        return self._call("POST", "breaker/switch", {"breaker_id": self._bid(breaker_id)})

    def repair_breaker(self, breaker_id=None, wait=False):
        """เริ่มซ่อม (เซิร์ฟเวอร์นับ 5 วิ). wait=True = บล็อกรอแล้วเรียกซ่อมเสร็จให้ (อย่าใช้ใน game loop หลัก — ใช้ thread แยก)"""
        bid = self._bid(breaker_id)
        d = self._call("POST", "breaker/repair", {"breaker_id": bid})
        if wait and (d.get("repair") or {}).get("started"):
            time.sleep(float(d["repair"].get("seconds", 5)) + 0.25)
            d = self._call("POST", "breaker/repair", {"breaker_id": bid})
        return d

    def close(self):
        if self.closed:
            return
        self.stop_auto_sync()
        self.closed = True
        try:
            self.client._request("DELETE", self._path())
        except VMAXGameServiceError:
            pass

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False


class VMAXGameServiceClient:
    def __init__(self, base_url, game_id, token=None, token_provider=None, timeout=8.0, transport=None):
        """token = JWT ของผู้เล่น | token_provider = callable คืน token ล่าสุด
        transport(method, url, headers, body, timeout) -> (status, json) — override ได้ (เทส/proxy/async)"""
        self.base_url = str(base_url or "").rstrip("/")
        self.game_id = str(game_id).strip().lower()
        self.token, self.token_provider = token, token_provider
        self.timeout = timeout
        self._transport = transport or _default_transport

    def _request(self, method, path, body=None):
        tok = self.token_provider() if self.token_provider else self.token
        headers = {"Authorization": "Bearer %s" % (tok or ""), "Accept": "application/json"}
        if body is not None:
            headers["Content-Type"] = "application/json"
        status, data = self._transport(method, self.base_url + path, headers, body, self.timeout)
        if status >= 400 or not isinstance(data, dict) or data.get("st") != "ok":
            d = data if isinstance(data, dict) else {}
            raise VMAXGameServiceError(d.get("msg") or "HTTP %s" % status, status, d.get("code"), data)
        return data

    def list_games(self):
        return self._request("GET", "/api/game-service/games")["games"]

    def spec(self):
        return self._request("GET", "/api/game-service/spec")

    def create_session(self, **opts):
        """x, y, hp, max_hp, aim, mode, glasses_equipped, zones=[{id,name,x,y,w,h}], breakers=[{id,x,y,zone}]"""
        from urllib.parse import quote
        d = self._request("POST", "/api/game-service/%s/session" % quote(self.game_id, safe=""), opts)
        return VMAXGameSession(self, d)
'''

# ใช้ซอร์สเดียวกันทั้งใน server (import ได้เลย) และตอนเสิร์ฟให้ดาวน์โหลด
_vmax_gs_py_ns = {"__name__": "vmax_game_service"}
exec(compile(VMAX_GAME_SERVICE_PY_SDK, "vmax_game_service.py", "exec"), _vmax_gs_py_ns)
VMAXGameServiceClient = _vmax_gs_py_ns["VMAXGameServiceClient"]
VMAXGameSession = _vmax_gs_py_ns["VMAXGameSession"]
VMAXGameServiceError = _vmax_gs_py_ns["VMAXGameServiceError"]


@app.route('/sdk/vmax_game_service.py', methods=['GET'])
def vmax_gs_sdk_py():
    resp = app.response_class(VMAX_GAME_SERVICE_PY_SDK, mimetype='text/x-python; charset=utf-8')
    resp.headers['Cache-Control'] = 'public, max-age=300'
    resp.headers['Content-Disposition'] = 'inline; filename="vmax_game_service.py"'
    return resp


VMAX_MODULES['game_service_api']['routes'].append('/sdk/vmax_game_service.py')
VMAX_MODULES['game_service_api']['features'].append('python_sdk_stdlib')


def _run_game_service_py_sdk_selftests():
    """python <ไฟล์นี้> --selftest-game-service  (รวมเทส Python SDK; ใช้ transport ต่อเข้า Flask test client)"""
    uid = '__gs_pysdk_selftest__'
    gid = 'gs-pysdk-selftest'
    tokens = {}
    try:
        register_device(uid, 'gs-py-dev')
        tokens[uid] = generate_jwt(uid, 'gs-py-dev')
        vmax_game_service_register(gid, 'GS PySDK', bounds={"min_x": 0, "min_y": 0, "max_x": 1000, "max_y": 600},
                                   zones=[{"id": "z1", "name": "Z1", "x": 0, "y": 0, "w": 500, "h": 600}],
                                   breakers=[{"id": "b1", "x": 300, "y": 300, "zone": "z1"}], persist=False)
        tc = app.test_client()

        def transport(method, url, headers, body, timeout):
            r = tc.open(url, method=method, headers=headers, json=body)
            return r.status_code, r.get_json(silent=True)

        assert 'class VMAXGameServiceClient' in tc.get('/sdk/vmax_game_service.py').get_data(as_text=True)
        svc = VMAXGameServiceClient('', gid, token=tokens[uid], transport=transport)
        assert any(g['game_id'] == gid for g in svc.list_games())

        events = {"damage": [], "arc_flash": [], "enemies": []}
        with svc.create_session(x=300, y=340, hp=100) as s:
            for k in events:
                s.on(k, events[k].append)
            s.sync(x=300, y=340, aim=0.0, enemies=[{"id": "e1", "x": 305, "y": 305, "hp": 40, "alive": True}])
            assert s.nearest_breaker(max_dist=100)["id"] == "b1"

            # อาร์คแฟลช: ผลเข้า event + hp_delta + โซนดับ
            res = s.shoot_breaker(hit_zone="live")
            assert res["outcome"] == "arc_fault" and s.effects["power"]["z1"] is False
            assert events["damage"] and events["arc_flash"] and events["enemies"]
            assert s.effects["enemies"][0]["hp"] == 25

            # ซ่อม: เร็วเกินไป -> error code, จากนั้นข้ามเวลา -> เสร็จ
            d = s.repair_breaker()
            assert d["repair"]["started"]
            try:
                s.repair_breaker(); assert False
            except VMAXGameServiceError as exc:
                assert exc.code == "repair_pending" and exc.status == 400
            VMAX_GS_SESSIONS[s.id]['st']['breakers'][0]['repair_until'] = time.time() - 1.0
            assert s.repair_breaker()["repair"]["finished"] and s.effects["breakers"][0]["state"] == "off"

            # ไฟฉาย + ควัน + shot()
            s.throw_smoke(300, 340)
            VMAX_GS_SESSIONS[s.id]['st']['smoke_clouds'][-1]['born'] -= 5.0
            s.set_light(on=True, preset="cool_high")
            assert s.effects["light"]["whiteout"] >= 0.9
            assert s.shot()["beacon"] is True
            assert s.cycle_preset()["effects"]["light"]["preset"] != "cool_high"
            try:
                s.set_preset("bogus"); assert False
            except VMAXGameServiceError as exc:
                assert exc.code == "bad_preset"

            # auto-sync thread ทำงานและหยุดได้
            n = {"c": 0}
            def gs():
                n["c"] += 1
                return {"x": 310.0, "y": 340.0}
            s.start_auto_sync(gs, interval=0.05); time.sleep(0.3); s.stop_auto_sync()
            assert n["c"] >= 2
            sid = s.id
        assert sid not in VMAX_GS_SESSIONS               # with-block ปิด session ให้
        try:
            s.toggle_light(); assert False
        except VMAXGameServiceError as exc:
            assert exc.code == "closed"

        # token ผิด -> 401 เป็น exception ที่มี status
        bad = VMAXGameServiceClient('', gid, token='nope', transport=transport)
        try:
            bad.create_session(); assert False
        except VMAXGameServiceError as exc:
            assert exc.status == 401
        return True
    finally:
        for sid in [k for k, s in VMAX_GS_SESSIONS.items() if s['uid'] == uid]:
            VMAX_GS_SESSIONS.pop(sid, None)
        VMAX_GS_GAMES.pop(gid, None)
        for t in tokens.values():
            SESSIONS.pop(t, None)
        DEVICES.pop(uid, None)


def _run_game_service_selftests():
    """python <ไฟล์นี้> --selftest-game-service"""
    uid, other = '__gs_selftest__', '__gs_selftest_other__'
    gid = 'gs-selftest'
    tokens = {}
    try:
        for u in (uid, other):
            register_device(u, 'gs-selftest-dev')
            tokens[u] = generate_jwt(u, 'gs-selftest-dev')
        vmax_game_service_register(gid, 'GS Selftest', bounds={"min_x": 0, "min_y": 0, "max_x": 1000, "max_y": 600},
                                   zones=[{"id": "z1", "name": "Z1", "x": 0, "y": 0, "w": 500, "h": 600}],
                                   breakers=[{"id": "b1", "x": 300, "y": 300, "zone": "z1"}], persist=False)
        c = app.test_client()
        H = lambda u=uid: {"Authorization": "Bearer " + tokens[u]}
        base = f'/api/game-service/{gid}'

        # 0) public endpoints + auth + unknown game
        assert c.get('/api/game-service/games').get_json()['st'] == 'ok'
        assert 'VMAXGameService' in c.get('/sdk/vmax-game-service.js').get_data(as_text=True)
        assert c.get('/api/game-service/spec').get_json()['st'] == 'ok'
        assert c.post(base + '/session', json={}).status_code == 401
        assert c.post('/api/game-service/nope-game/session', json={}, headers=H()).status_code == 404

        # 1) create session with the game's own registered breaker
        r = c.post(base + '/session', json={'x': 350, 'y': 300, 'hp': 100}, headers=H())
        d = r.get_json(); assert r.status_code == 200, d
        sid = d['session_id']; sp = f'{base}/session/{sid}'
        assert len(d['effects']['breakers']) == 1 and d['effects']['power'] == {'z1': True}
        assert c.get(sp, headers=H(other)).status_code == 404          # ไม่ใช่ของผู้เล่นคนอื่น

        # 2) arc fault on energized panel -> zone blackout, flash blindness, hp_delta < 0
        r = c.post(sp + '/breaker/shoot', json={'breaker_id': 'b1', 'hit_zone': 'live'}, headers=H())
        d = r.get_json(); assert r.status_code == 200 and d['result']['outcome'] == 'arc_fault', d
        assert d['effects']['power']['z1'] is False and d['effects']['blind_left'] > 0 and d['effects']['hp_delta'] < 0
        assert any(f['type'] == 'arc_flash' for f in d['effects']['fx'])

        # 3) repair flow: start -> too early -> finish (breaker OFF)
        assert c.post(sp + '/breaker/repair', json={'breaker_id': 'b1'}, headers=H()).status_code == 200
        r = c.post(sp + '/breaker/repair', json={'breaker_id': 'b1'}, headers=H())
        assert r.status_code == 400 and r.get_json()['code'] == 'repair_pending'
        VMAX_GS_SESSIONS[sid]['st']['breakers'][0]['repair_until'] = time.time() - 1.0
        d = c.post(sp + '/breaker/repair', json={'breaker_id': 'b1'}, headers=H()).get_json()
        assert d['repair']['finished'] and d['effects']['breakers'][0]['state'] == 'off'

        # 4) flashlight in smoke = wall of light, beacon, shot miss probability; light off clears it
        r = c.post(base + '/session', json={'x': 400, 'y': 300}, headers=H()); sid2 = r.get_json()['session_id']; sp2 = f'{base}/session/{sid2}'
        assert c.post(sp2 + '/smoke', json={'target_x': 400, 'target_y': 300}, headers=H()).status_code == 200
        VMAX_GS_SESSIONS[sid2]['st']['smoke_clouds'][0]['born'] -= 5.0
        d = c.post(sp2 + '/light', json={'on': True, 'preset': 'cool_high'}, headers=H()).get_json()
        assert d['effects']['light']['whiteout'] >= 0.9 and d['effects']['light']['beacon'] is True
        assert d['effects']['miss_probability'] >= 0.8
        d = c.post(sp2 + '/shot', json={}, headers=H()).get_json()
        assert d['shot']['beacon'] is True and d['shot']['beacon_bonus_damage'] == 4
        d = c.post(sp2 + '/light', json={'on': False}, headers=H()).get_json()
        assert d['effects']['light']['whiteout'] == 0.0 and d['effects']['miss_probability'] == 0.0
        assert c.post(sp2 + '/light', json={'preset': 'bogus'}, headers=H()).get_json()['code'] == 'bad_preset'

        # 5) external enemies: sync in, arc kills the ones next to the panel (returned for the game to apply)
        r = c.post(base + '/session', json={'x': 300, 'y': 340, 'breakers': [{'id': 'bx', 'x': 300, 'y': 300, 'zone': 'z1'}],
                                             'zones': [{'id': 'z1', 'x': 0, 'y': 0, 'w': 500, 'h': 600}]}, headers=H())
        sid3 = r.get_json()['session_id']; sp3 = f'{base}/session/{sid3}'
        d = c.post(sp3 + '/sync', json={'x': 300, 'y': 340, 'enemies': [{'id': 'e1', 'x': 305, 'y': 305, 'hp': 40, 'alive': True},
                                                                       {'id': 'e2', 'x': 900, 'y': 500, 'hp': 10, 'alive': True}]}, headers=H()).get_json()
        assert len(d['effects']['enemies']) == 2
        d = c.post(sp3 + '/breaker/shoot', json={'hit_zone': 'live'}, headers=H()).get_json()
        en = {e['id']: e for e in d['effects']['enemies']}
        assert en['e1']['hp'] == 25 and en['e2']['hp'] == 10 and en['e1']['blind_left'] > 0 and en['e2']['blind_left'] == 0, en
        # ตายแล้ว sync hp กลับมา = ชุบชีวิต
        VMAX_GS_SESSIONS[sid3]['st']['status'] = 'dead'
        assert c.post(sp3 + '/light', json={'on': True}, headers=H()).get_json()['code'] == 'not_active'
        assert c.post(sp3 + '/sync', json={'hp': 50}, headers=H()).get_json()['effects']['status'] == 'raid'

        # 6) register endpoint needs staff rank; builtin cannot be overwritten
        assert c.post('/api/game-service/games/register', json={'game_id': 'x1'}, headers=H()).status_code in (401, 403)
        try:
            vmax_game_service_register('extraction_boss_raid', 'hack'); assert False
        except PermissionError:
            pass

        # 7) close
        assert c.delete(sp, headers=H()).status_code == 200 and c.get(sp, headers=H()).status_code == 404
        return True
    finally:
        for sid in [k for k, s in VMAX_GS_SESSIONS.items() if s['uid'] in (uid, other)]:
            VMAX_GS_SESSIONS.pop(sid, None)
        VMAX_GS_GAMES.pop(gid, None)
        for u, t in tokens.items():
            SESSIONS.pop(t, None); DEVICES.pop(u, None)


# =====================================================================
# VMAX BALLISTIC SENSE SKILLS — สกิลสายรับรู้กระสุน (เกมแนวยิง เก็บของ หนี / Extraction)
# =====================================================================
# ชุดสกิล 4 ใบที่เชื่อมโยงกันเป็นสายเดียว (ไอคอนตามที่ผู้ออกแบบวาดไว้):
#
#   1) ballistic_eye      👁️🔥  ตาสไนเปอร์ (ขนนก/คิ้วไฟ + สโคปรอบตา + กระสุนพุ่งผ่านมา)
#        ตอนกระสุนโดนเกราะ ความคงทนเกราะลดลง (เช่น 100% -> 58%) แล้ววิเคราะห์ย้อนกลับได้ว่า
#        เป็นกระสุนชนิดใด (กระสุนไม่ได้ช้าลงจริง แต่ผู้เล่นรับรู้ละเอียดขึ้น)
#   2) bullet_map_trace   🗺️   แผนที่วิถีกระสุน (ลูกกระสุนในแผนที่ + ลูกศรชี้ + ค่า 0.2 วิ)
#        วาดแนววิถีบนแผนที่ และคำนวณว่า ณ ช่วง 0.2 วินาทีที่คนเริ่มตอบสนองได้ กระสุนอยู่ตรงไหนของวิถี
#        (ปรับให้สมจริง: เดิมใช้จุด 0.5 เมตรแรก ซึ่งกระสุนใช้เวลาแค่ ~0.6 มิลลิวินาที คนไม่มีทางทัน)
#   3) muzzle_flash_read  🔫✨ อ่านแสงปลายกระบอกปืน (ปากกระบอกปืนกำลังยิง + แสงวาบ)
#        เห็นแสงวาบที่ปลายกระบอก -> ได้ตำแหน่ง/ทิศของคนยิง (ปืนเก็บเสียง/ซับเพรสเซอร์เห็นได้ใกล้ขึ้นเท่านั้น)
#   4) dual_eye_dodge     👁️👁️ +2  ตาคู่ (สองตาในวงสไนเปอร์ + เครื่องหมาย +2)
#        รวมพลัง 2 สกิลข้างบน (แผนที่ + แสงปลายกระบอก) คำนวณเป็นวิถีบนแผนที่
#        แล้ว "หลบกระสุนได้ 1 ครั้งต่อ Raid" — เฉพาะนัดที่ยิงมาจากไกลพอ (กระสุนถึงตัวช้ากว่า 0.2 วิ)
#
# หมายเหตุการออกแบบ:
# - ไม่แก้ระบบเดิม: อ่านโปรไฟล์อาวุธจาก BALLISTIC_WEAPON_PROFILES / ballistic_profile_for_weapon
#   และหักความคงทนเกราะผ่าน VMAX_PLAYER_ARMOR_DURABILITY ตัวเดียวกับระบบเกราะระเบิด
# - หน่วยพิกัดบนแผนที่ = เมตร
# - สกิลผูกกับ Raid ที่กำลังเล่นอยู่ (EXTRACTION_RAIDS) ประจุหลบกระสุนจะรีเซ็ตเมื่อเริ่ม Raid ใหม่
# - จุดแทรก: ต่อท้ายทุกโมดูลและ "ก่อน" __main__ เพื่อให้ route ถูกลงทะเบียนก่อน server start
# =====================================================================
import math as _bsk_math
import threading as _bsk_threading
import time as _bsk_time

