SH_X2_TYPES = {
    "x2_points":   {"name": "แต้มกิจกรรมรายสัปดาห์ x2",          "effect": "points",   "mult": 2},
    "x2_xp":       {"name": "XP ซีซันจากภารกิจรายสัปดาห์ x2",    "effect": "xp",       "mult": 2},
    "x2_progress": {"name": "ความคืบหน้าภารกิจตลาด/ขายนอกเรด x2", "effect": "progress", "mult": 2},
}
SH_X2_ROTATION = [("x2_points",), ("x2_xp", "x2_progress"), ("x2_points", "x2_xp"), ("x2_progress",)]
SH_X2_ROWS_AHEAD = 3


def _sh_now():
    return _sh_dt.now(_SH_TZ)


def _sh_week_start(now=None):
    now = now or _sh_now()
    s = (now - _sh_td(days=(now.weekday() - SH_WEEK_RESET_WEEKDAY) % 7)).replace(
        hour=SH_WEEK_RESET_HOUR, minute=0, second=0, microsecond=0)
    if s > now:
        s -= _sh_td(days=7)
    return s


def _sh_week_events(ws):
    row = SH_X2_ROTATION[(ws.date().toordinal() // 7) % len(SH_X2_ROTATION)]
    return [{"id": i, **SH_X2_TYPES[i]} for i in row]


def _sh_mult(effect):
    return max([e["mult"] for e in _sh_week_events(_sh_week_start()) if e["effect"] == effect] or [1])


def _sh_x2_rows():
    ws0 = _sh_week_start()
    rows = []
    for n in range(SH_X2_ROWS_AHEAD + 1):
        ws = ws0 + _sh_td(days=7 * n)
        rows.append({"week_start": ws.isoformat(), "week_end": (ws + _sh_td(days=7)).isoformat(),
                     "current": n == 0, "events": _sh_week_events(ws)})
    return rows


def _sh_parse_hm(s):
    h, m = s.split(":")
    return int(h) * 60 + int(m)


def _sh_event_view(ev, now, uid=None):
    today = now.date()
    status = "open"
    if ev.get("start") and today < _sh_date.fromisoformat(ev["start"]):
        status = "upcoming"
    elif ev.get("end") and today > _sh_date.fromisoformat(ev["end"]):
        status = "ended"
    elif ev.get("daily_window"):
        mins = now.hour * 60 + now.minute
        if not (_sh_parse_hm(ev["daily_window"][0]) <= mins < _sh_parse_hm(ev["daily_window"][1])):
            status = "waiting_window"
    view = {k: ev.get(k) for k in ("id", "name", "tagline", "mode", "desc", "start", "end", "daily_window", "entry_item")}
    view["status"] = status
    if ev.get("mode") == "pvpve_zone":
        cutoff = time.time() - SH_ZONE_TTL_SEC
        view["players_in_zone"] = sum(1 for t in SH_STATE["event_joins"].get(ev["id"], {}).values() if t.get("ts", 0) >= cutoff)
    if ev.get("entry_item"):
        view["entry_item_name"] = SH_NEW_ITEMS.get(ev["entry_item"], {}).get("name", ev["entry_item"])
        view["entry_item_uses"] = SH_NEW_ITEMS.get(ev["entry_item"], {}).get("uses", 1)
        if uid:
            view["entry_item_uses_left"] = SH_STATE["durability"].get(uid, {}).get(ev["entry_item"], 0)
            view["entry_item_cards"] = EXTRACTION_STASH.get(uid, {}).get(ev["entry_item"], 0)
    return view


# ----------------------------------------------------------------------------
# สถานะผู้เล่น + บันทึกลงไฟล์ JSON (เขียนแบบ atomic)
# ----------------------------------------------------------------------------
SH_STATE = {"durability": {}, "weekly": {}, "season": {}, "mentor": {}, "handoff_claimed": {},
            "activity": {}, "invite": {"code2uid": {}, "uid2code": {}}, "event_joins": {}}


def _sh_save():
    try:
        tmp = _SH_DB_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(SH_STATE, f, ensure_ascii=False)
        os.replace(tmp, _SH_DB_PATH)
    except Exception as exc:
        print("[SEASON HUB] save failed:", repr(exc))


def _sh_load():
    try:
        if os.path.isfile(_SH_DB_PATH):
            with open(_SH_DB_PATH, "r", encoding="utf-8") as f:
                data = json.load(f)
            for k in SH_STATE:
                if k in data and isinstance(data[k], dict):
                    SH_STATE[k] = data[k]
    except Exception as exc:
        print("[SEASON HUB] load failed:", repr(exc))


_sh_load()


def _sh_weekly(uid):
    key = _sh_week_start().strftime("%Y-%m-%d")
    st = SH_STATE["weekly"].get(uid)
    if not st or st.get("week_key") != key:
        st = {"week_key": key, "progress": {}, "login_days": [], "claimed": [], "points": 0, "track_claimed": []}
        SH_STATE["weekly"][uid] = st
    return st


def _sh_season(uid):
    return SH_STATE["season"].setdefault(uid, {"xp": 0})


def _sh_activity(uid, typ, text):
    feed = SH_STATE["activity"].setdefault(uid, [])
    feed.append({"ts": time.time(), "type": typ, "text": text})
    del feed[:-SH_ACTIVITY_KEEP]


def _sh_mark_login(uid):
    st = _sh_weekly(uid)
    today = _sh_now().strftime("%Y-%m-%d")
    if today not in st["login_days"]:
        st["login_days"].append(today)
    st["progress"]["login_days"] = len(st["login_days"])


def season_hub_report(uid, metric, amount=1):
    """เรียกจากโค้ดฝั่งเซิร์ฟเวอร์เท่านั้น เพื่อเพิ่มความคืบหน้าภารกิจรายสัปดาห์ (metric: market_earn / raid_sell / ...)"""
    amount = int(amount)
    if amount <= 0:
        return
    with _SH_LOCK:
        st = _sh_weekly(str(uid))
        if metric in ("market_earn", "raid_sell"):
            amount *= _sh_mult("progress")
        st["progress"][metric] = st["progress"].get(metric, 0) + amount
        _sh_save()


# ----------------------------------------------------------------------------
# ของรางวัล / คลัง / เครดิต (ใช้ตัวแปรกลางเดิมของไฟล์: P, WALLET, EXTRACTION_STASH)
# ----------------------------------------------------------------------------
def _sh_add_credits(amount):
    P["credits"] = P.get("credits", 0) + int(amount)
    try:
        WALLET["balance"] = P["credits"]
    except Exception:
        pass


def _sh_stash_add(uid, item_id, qty):
    box = EXTRACTION_STASH[uid]
    box[item_id] = box.get(item_id, 0) + int(qty)


def _sh_stash_take(uid, item_id, qty):
    box = EXTRACTION_STASH[uid]
    if box.get(item_id, 0) < qty:
        return False
    box[item_id] -= qty
    if box[item_id] <= 0:
        box.pop(item_id, None)
    return True


def _sh_use_item(uid, item_id):
    """ตัดความทนทาน 1 ครั้งของคีย์/คีย์การ์ด: ใบที่กำลังใช้อยู่เหลือเท่าไหร่เก็บไว้ใน SH_STATE["durability"]
    หมดแล้วใบถัดไปในคลังถูกหยิบมาใช้อัตโนมัติ คืนจำนวนครั้งที่เหลือของใบปัจจุบัน หรือ None ถ้าไม่มีของ"""
    uses = int(SH_NEW_ITEMS.get(item_id, {}).get("uses", 1))
    dur = SH_STATE["durability"].setdefault(uid, {})
    left = int(dur.get(item_id, 0))
    if left <= 0:
        if not _sh_stash_take(uid, item_id, 1):
            return None
        left = uses
    left -= 1
    if left > 0:
        dur[item_id] = left
    else:
        dur.pop(item_id, None)   # ใบนี้ใช้ครบแล้ว
    return left


def _sh_stash_value(uid):
    return sum(int(q) * int(EXTRACTION_ITEM_DB.get(i, {}).get("value", 0)) for i, q in EXTRACTION_STASH.get(uid, {}).items())


def _sh_sell_price(item_id, uses_left=None):
    """ราคารับซื้อของตลาด ต่อ 1 ชิ้น
    - ของใหม่ (ไม่ส่ง uses_left)        -> มูลค่า x SH_MARKET_SELL_RATIO เต็มราคา
    - ใบที่ใช้ไปแล้วบางส่วน (uses_left) -> ลดตามความทนทานที่เหลือ = ราคาเต็ม x (เหลือ / ใช้ได้ทั้งหมด)
      เช่น การ์ด 10 ครั้ง เหลือ 7 ครั้ง ได้ 70% ของราคารับซื้อใบใหม่ (ขั้นต่ำ 1 เครดิต)"""
    val = int(EXTRACTION_ITEM_DB.get(item_id, {}).get("value", 0))
    if val <= 0:
        return 0
    full = int(val * SH_MARKET_SELL_RATIO)
    if uses_left is None:
        return full
    uses_max = max(1, int(SH_NEW_ITEMS.get(item_id, {}).get("uses", 1)))
    left = max(0, min(int(uses_left), uses_max))
    if left <= 0:
        return 0
    return max(1, int(full * left / uses_max))


def _sh_grant(uid, reward):
    kind = reward.get("kind")
    out = dict(reward)
    if kind == "credits":
        _sh_add_credits(reward["amount"])
    elif kind == "item":
        _sh_stash_add(uid, reward["item_id"], reward.get("qty", 1))
    elif kind == "crate":
        weights = [1.0 / max(1, SH_NEW_ITEMS[i]["value"]) for i in SH_CRATE_POOL]
        pick = random.choices(SH_CRATE_POOL, weights=weights, k=1)[0]
        _sh_stash_add(uid, pick, 1)
        out.update({"item_id": pick, "qty": 1, "label": "กล่องรางวัล → " + SH_NEW_ITEMS[pick]["name"]})
    return out


def _sh_uid():
    return str(request.vmax_uid)


def _sh_err(msg, code=400):
    return jsonify({"st": "error", "msg": msg}), code


def _sh_int(v, lo, hi, default=None):
    if isinstance(v, bool):
        return default
    try:
        n = int(v)
    except (TypeError, ValueError):
        return default
    return n if lo <= n <= hi else default


# ----------------------------------------------------------------------------
# API: state / weekly / event
# ----------------------------------------------------------------------------
def _sh_state_view(uid):
    st = _sh_weekly(uid)
    xp = _sh_season(uid)["xp"]
    missions = []
    for m in SH_WEEKLY_MISSIONS:
        prog = min(st["progress"].get(m["metric"], 0), m["target"])
        missions.append({**m, "progress": prog, "complete": prog >= m["target"], "claimed": m["id"] in st["claimed"]})
    track = [{**t, "unlocked": st["points"] >= t["points"], "claimed": t["points"] in st["track_claimed"]}
             for t in SH_WEEKLY_TRACK]
    now = _sh_now()
    ws = _sh_week_start(now)
    return {
        "st": "ok", "now": now.isoformat(),
        "season": {"id": SH_SEASON_ID, "level": 1 + xp // SH_XP_PER_LEVEL, "xp": xp % SH_XP_PER_LEVEL,
                   "xp_per_level": SH_XP_PER_LEVEL},
        "weekly": {"week_key": st["week_key"], "refresh_at": (ws + _sh_td(days=7)).isoformat(),
                   "points": st["points"], "missions": missions, "track": track,
                   "active_multipliers": {e["effect"]: e["mult"] for e in _sh_week_events(ws)}},
        "events": {"main": [_sh_event_view(e, now, uid) for e in SH_MAIN_EVENTS], "weekly_x2_rows": _sh_x2_rows()},
    }


