SH_HANDOFF_TRACK = [   # มูลค่าทรัพย์สินรวมของศิษย์ (ที่นับได้) -> รางวัลของอาจารย์
    {"threshold": 600_000,   "reward": {"kind": "item", "item_id": "event_coin", "qty": 200, "label": "เหรียญกิจกรรม x200"}},
    {"threshold": 1_200_000, "reward": {"kind": "item", "item_id": "event_coin", "qty": 200, "label": "เหรียญกิจกรรม x200"}},
    {"threshold": 1_800_000, "reward": {"kind": "item", "item_id": "event_coin", "qty": 200, "label": "เหรียญกิจกรรม x200"}},
    {"threshold": 3_000_000, "reward": {"kind": "item", "item_id": "event_coin", "qty": 200, "label": "เหรียญกิจกรรม x200"}},
]


def _sh_invite_code(uid):
    inv = SH_STATE["invite"]
    code = inv["uid2code"].get(uid)
    if not code:
        code = uuid.uuid4().hex[:8].upper()
        inv["uid2code"][uid] = code
        inv["code2uid"][code] = uid
    return code


def _sh_account_bound(uid):
    try:
        return uid in USER_STORE
    except NameError:
        return True


def _sh_students(uid):
    return [s for s, rec in SH_STATE["mentor"].items() if rec.get("mentor") == uid]


def _sh_counted_students_value(uid):
    now = time.time()
    total, rows = 0, []
    for s in _sh_students(uid):
        rec = SH_STATE["mentor"][s]
        counted = (now - rec.get("bound_at", now)) >= SH_MENTOR_MIN_BOUND_AGE_SEC
        val = _sh_stash_value(s)
        if counted:
            total += val
        rows.append({"uid": s, "asset_value": val, "counted": counted,
                     "counts_after": rec.get("bound_at", now) + SH_MENTOR_MIN_BOUND_AGE_SEC})
    return total, rows


@app.route('/api/season/social', methods=['GET'])
@require_auth
def api_season_social():
    uid = _sh_uid()
    with _SH_LOCK:
        total, students = _sh_counted_students_value(uid)
        claimed = SH_STATE["handoff_claimed"].get(uid, [])
        mine = SH_STATE["mentor"].get(uid, {})
        _sh_save()
        return jsonify({
            "st": "ok", "uid": uid, "invite_code": _sh_invite_code(uid),
            "friends": FRIENDS_LIST.get(uid, []),
            "friend_requests": FRIEND_REQUESTS.get(uid, []),
            "mentor": mine.get("mentor"),
            "students": students, "max_students": SH_MENTOR_MAX_STUDENTS,
            "handoff": {"total_asset_value": total,
                        "track": [{**t, "unlocked": total >= t["threshold"], "claimed": t["threshold"] in claimed}
                                  for t in SH_HANDOFF_TRACK]},
            "activity": list(reversed(SH_STATE["activity"].get(uid, []))),
        })


