@app.route('/api/season/mentor/bind', methods=['POST'])
@require_auth
def api_season_mentor_bind():
    uid = _sh_uid()
    code = str((request.get_json(silent=True) or {}).get("code") or "").strip().upper()
    with _SH_LOCK:
        mentor = SH_STATE["invite"]["code2uid"].get(code)
        if not mentor:
            return _sh_err("โค้ดเชิญไม่ถูกต้อง", 404)
        if mentor == uid:
            return _sh_err("ผูกกับตัวเองไม่ได้")
        if not _sh_account_bound(uid):
            return _sh_err("ต้องผูกบัญชีก่อน", 403)
        if SH_STATE["mentor"].get(uid, {}).get("mentor"):
            return _sh_err("มีอาจารย์อยู่แล้ว", 409)
        cur, hops = mentor, 0                     # กันวงวน: อาจารย์ของอาจารย์... ห้ามย้อนมาเป็นเรา
        while cur and hops < 50:
            if cur == uid:
                return _sh_err("ผูกแบบวงวนไม่ได้", 409)
            cur, hops = SH_STATE["mentor"].get(cur, {}).get("mentor"), hops + 1
        if len(_sh_students(mentor)) >= SH_MENTOR_MAX_STUDENTS:
            return _sh_err("อาจารย์คนนี้รับศิษย์ครบแล้ว", 409)
        SH_STATE["mentor"][uid] = {"mentor": mentor, "bound_at": time.time()}
        _sh_activity(uid, "mentor", f"ผูกเป็นศิษย์ของ {mentor}")
        _sh_activity(mentor, "mentor", f"{uid} ผูกเป็นศิษย์")
        _sh_save()
    return jsonify({"st": "ok", "mentor": mentor})


@app.route('/api/season/mentor/claim', methods=['POST'])
@require_auth
def api_season_mentor_claim():
    uid = _sh_uid()
    th = _sh_int((request.get_json(silent=True) or {}).get("threshold"), 1, 10**9)
    node = next((t for t in SH_HANDOFF_TRACK if t["threshold"] == th), None)
    if not node:
        return _sh_err("ไม่พบด่านรางวัลนี้", 404)
    with _SH_LOCK:
        claimed = SH_STATE["handoff_claimed"].setdefault(uid, [])
        if th in claimed:
            return _sh_err("รับรางวัลด่านนี้ไปแล้ว", 409)
        total, _rows = _sh_counted_students_value(uid)
        if total < th:
            return _sh_err(f"มูลค่าทรัพย์สินศิษย์รวมยังไม่ถึง {th:,} (ตอนนี้ {total:,})", 409)
        claimed.append(th)
        reward = _sh_grant(uid, node["reward"])
        _sh_activity(uid, "handoff", f"รับรางวัลส่งต่อคนไฟ {th:,}: {reward.get('label', '')}")
        _sh_save()
    return jsonify({"st": "ok", "reward": reward})


