def _sh_item_view(iid):
    it = EXTRACTION_ITEM_DB.get(iid, {})
    keep = ("name", "category", "rarity", "tier", "tier_roman", "value", "weight", "durability", "uses",
            "armor_class", "pen_class", "slots", "map", "effect")
    return {"id": iid, **{k: it[k] for k in keep if k in it}}


@app.route('/api/season/market', methods=['GET'])
@require_auth
def api_season_market():
    items = []
    for iid, it in SH_NEW_ITEMS.items():
        if it.get("market"):
            items.append({**_sh_item_view(iid), "price": int(it["value"])})
    return jsonify({"st": "ok", "items": items, "credits": P.get("credits", 0),
                    "sell_ratio": SH_MARKET_SELL_RATIO})


@app.route('/api/season/stash', methods=['GET'])
@require_auth
def api_season_stash():
    uid = _sh_uid()
    rows = []
    # ใบที่กำลังใช้อยู่ (ความทนทานเหลือไม่เต็ม) แสดงเป็นแถวแยก ราคาลดตามความทนทานที่เหลือ
    for iid, left in sorted(SH_STATE["durability"].get(uid, {}).items()):
        left = int(left)
        if left > 0 and iid in SH_NEW_ITEMS:
            rows.append({**_sh_item_view(iid), "qty": 1, "used": True, "uses_left": left,
                         "uses_max": int(SH_NEW_ITEMS[iid].get("uses", 1)),
                         "sell_price": _sh_sell_price(iid, left)})
    for iid, q in sorted(EXTRACTION_STASH.get(uid, {}).items()):
        rows.append({**_sh_item_view(iid), "qty": q, "used": False,
                     "sell_price": _sh_sell_price(iid)})
    return jsonify({"st": "ok", "stash": rows, "credits": P.get("credits", 0)})


@app.route('/api/season/market/buy', methods=['POST'])
@require_auth
def api_season_market_buy():
    uid = _sh_uid()
    b = request.get_json(silent=True) or {}
    iid = str(b.get("item_id") or "")
    qty = _sh_int(b.get("qty", 1), 1, SH_MARKET_MAX_QTY)
    it = SH_NEW_ITEMS.get(iid)
    if not it or not it.get("market"):
        return _sh_err("ไอเทมนี้ไม่ได้ขายในตลาด", 404)
    if qty is None:
        return _sh_err(f"จำนวนต้องอยู่ระหว่าง 1-{SH_MARKET_MAX_QTY}")
    cost = int(it["value"]) * qty
    with _SH_LOCK:
        if P.get("credits", 0) < cost:
            return _sh_err(f"เครดิตไม่พอ (ต้องการ {cost:,})", 402)
        _sh_add_credits(-cost)
        _sh_stash_add(uid, iid, qty)
        _sh_save()
    return jsonify({"st": "ok", "spent": cost, "credits": P.get("credits", 0)})


@app.route('/api/season/market/sell', methods=['POST'])
@require_auth
def api_season_market_sell():
    uid = _sh_uid()
    b = request.get_json(silent=True) or {}
    iid = str(b.get("item_id") or "")
    sell_used = bool(b.get("used"))          # True = ขายใบที่กำลังใช้อยู่ (ความทนทานไม่เต็ม)
    qty = 1 if sell_used else _sh_int(b.get("qty", 1), 1, 10**6)
    val = int(EXTRACTION_ITEM_DB.get(iid, {}).get("value", 0))
    if qty is None or val <= 0:
        return _sh_err("ขายไม่ได้")
    with _SH_LOCK:
        if sell_used:
            dur = SH_STATE["durability"].setdefault(uid, {})
            left = int(dur.get(iid, 0))
            if left <= 0:
                return _sh_err("ไม่มีใบที่ใช้อยู่ให้ขาย", 409)
            gain = _sh_sell_price(iid, left)
            dur.pop(iid, None)               # ใบที่ใช้อยู่ถูกขายออกไปแล้ว
        else:
            if not _sh_stash_take(uid, iid, qty):
                return _sh_err("ของในคลังไม่พอ", 409)
            gain = _sh_sell_price(iid) * qty   # ของใหม่ในคลัง = ราคาเต็ม
        _sh_add_credits(gain)
        season_hub_report(uid, "market_earn", gain)
        season_hub_report(uid, "raid_sell", gain)   # ขายจากคลัง = ขายออกนอกเรด
        _sh_save()
    return jsonify({"st": "ok", "gained": gain, "credits": P.get("credits", 0)})


