SEASON_HUB_PAGE = r"""<!DOCTYPE html>
<html lang="th"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Season Hub</title>
<style>
:root{--bg:#0d0f12;--card:#171a1f;--line:#2a2f37;--tx:#e8e6df;--mut:#8b919a;--gold:#d9a441;--ok:#5fbf7a;--bad:#d9605a}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:15px/1.45 system-ui,"Noto Sans Thai",sans-serif}
header{padding:12px 14px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:8px;align-items:center}
nav{display:flex;gap:6px;padding:8px 10px;overflow-x:auto;border-bottom:1px solid var(--line)}
nav button{background:var(--card);color:var(--tx);border:1px solid var(--line);padding:8px 14px;border-radius:8px;white-space:nowrap}
nav button.on{border-color:var(--gold);color:var(--gold)}
main{padding:12px;max-width:900px;margin:auto}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px;margin-bottom:10px}
.row{display:flex;gap:8px;align-items:center;justify-content:space-between;flex-wrap:wrap}
.mut{color:var(--mut);font-size:13px}.gold{color:var(--gold)}h3{margin:14px 0 8px;font-size:16px}
button.act{background:var(--gold);color:#111;border:0;border-radius:7px;padding:7px 14px;font-weight:700}
button.act:disabled{background:#3a3f47;color:#777}
.bar{height:8px;background:#262a31;border-radius:5px;overflow:hidden}.bar>i{display:block;height:100%;background:var(--gold)}
.chip{display:inline-block;background:#2a2417;border:1px solid var(--gold);color:var(--gold);border-radius:20px;padding:3px 10px;margin:2px 4px 2px 0;font-size:13px;font-weight:700}
.badge{font-size:12px;padding:2px 8px;border-radius:10px;background:#262a31}.badge.open{background:#173a24;color:var(--ok)}
.nodes{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.node{border:1px solid var(--line);border-radius:8px;padding:8px;text-align:center;font-size:13px}
.node.ok{border-color:var(--gold)}.cur{border-color:var(--gold)!important}
input{background:#0d0f12;border:1px solid var(--line);color:var(--tx);padding:8px;border-radius:7px}
#msg{position:fixed;left:10px;right:10px;bottom:10px;background:#222;border:1px solid var(--gold);border-radius:8px;padding:10px;display:none}
</style></head><body>
<header><b>Season Hub <span class="gold" id="sid"></span></b><span class="mut" id="cred"></span></header>
<nav id="nav"></nav><main id="main">กำลังโหลด…</main><div id="msg"></div>
<script>
const T=()=>localStorage.getItem('vmax_token')||'';
const $=s=>document.querySelector(s);
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString();
async function api(p,body){const o={headers:{'Authorization':'Bearer '+T()}};
 if(body!==undefined){o.method='POST';o.headers['Content-Type']='application/json';o.body=JSON.stringify(body)}
 const r=await fetch(p,o);let j={};try{j=await r.json()}catch(e){}
 if(!r.ok||j.st==='error'){toast(j.msg||('ผิดพลาด '+r.status));throw new Error(j.msg||r.status)}return j}
function toast(t){const m=$('#msg');m.textContent=t;m.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>m.style.display='none',3200)}
const TABS={events:'อีเวนต์',weekly:'ภารกิจรายสัปดาห์',social:'ความสัมพันธ์',market:'ตลาด/คลัง'};
let tab='events';
$('#nav').innerHTML=Object.entries(TABS).map(([k,v])=>`<button data-t="${k}">${v}</button>`).join('');
$('#nav').onclick=e=>{const t=e.target.dataset.t;if(t){tab=t;render()}};
const stLabel={open:'เปิดอยู่',upcoming:'ยังไม่เริ่ม',ended:'จบแล้ว',waiting_window:'นอกช่วงเวลาเปิด'};
const d=s=>new Date(s).toLocaleDateString('th-TH',{day:'numeric',month:'short'});
async function render(){
 document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('on',b.dataset.t===tab));
 try{await VIEWS[tab]()}catch(e){$('#main').innerHTML='<div class="card">โหลดไม่สำเร็จ — ต้องล็อกอินก่อน ('+esc(e.message)+')</div>'}}
const VIEWS={
async events(){const s=await api('/api/season/state');$('#sid').textContent=s.season.id;
 let h='<h3>อีเวนต์หลัก</h3>';
 for(const e of s.events.main){const w=e.daily_window?` · ทุกวัน ${esc(e.daily_window[0])}–${esc(e.daily_window[1])}`:'';
  const r=(e.start||e.end)?`${esc(e.start||'')} → ${esc(e.end||'')}`:'ไม่กำหนดวันสิ้นสุด';
  h+=`<div class="card"><div class="row"><b>${esc(e.name)}</b><span class="badge ${e.status==='open'?'open':''}">${stLabel[e.status]||esc(e.status)}</span></div>
  <div class="gold">${esc(e.tagline)}</div><div class="mut">${r}${w}</div><p>${esc(e.desc)}</p>
  <div class="row"><span class="mut">${e.entry_item_name?'ใช้: '+esc(e.entry_item_name)+' (ความทนทาน −1) · ใบที่ใช้อยู่เหลือ '+(e.entry_item_uses_left||0)+'/'+e.entry_item_uses+' · ในคลัง '+(e.entry_item_cards||0)+' ใบ':'ไม่ต้องใช้ไอเทม'}${e.players_in_zone!=null?' · ผู้เล่นในโซน '+e.players_in_zone:''}</span>
  <button class="act" ${e.status!=='open'?'disabled':''} onclick="joinEv('${esc(e.id)}')">ไปเลย</button></div></div>`}
 h+='<h3>อีเวนต์รายสัปดาห์ (คูณ 2)</h3>';
 for(const r of s.events.weekly_x2_rows){h+=`<div class="card ${r.current?'cur':''}"><div class="mut">${d(r.week_start)} – ${d(new Date(new Date(r.week_end)-1))}${r.current?' · สัปดาห์นี้':''}</div>`+
  r.events.map(e=>`<span class="chip">${esc(e.name)}</span>`).join('')+'</div>'}
 $('#main').innerHTML=h},
async weekly(){const s=await api('/api/season/state');const w=s.weekly,se=s.season;$('#sid').textContent=se.id;
 const mu=Object.entries(w.active_multipliers).map(([k,v])=>`<span class="chip">x${v} ${esc(k)}</span>`).join('');
 let h=`<div class="card"><div class="row"><b>${esc(se.id)} เลเวล ${se.level}</b><span class="mut">${fmt(se.xp)}/${fmt(se.xp_per_level)} XP</span></div>
 <div class="bar"><i style="width:${se.xp/se.xp_per_level*100}%"></i></div>
 <div class="row" style="margin-top:8px"><span>แต้มกิจกรรม <b class="gold">${w.points}</b></span><span class="mut">รีเฟรช ${d(w.refresh_at)} (ทุกวันศุกร์)</span></div>${mu}</div>
 <h3>รางวัลตามแต้ม</h3><div class="nodes">`;
 for(const t of w.track)h+=`<div class="node ${t.unlocked?'ok':''}"><b>${t.points} แต้ม</b><div>${esc(t.reward.label)}</div>
  <button class="act" ${(!t.unlocked||t.claimed)?'disabled':''} onclick="claimTrack(${t.points})">${t.claimed?'รับแล้ว':'รับ'}</button></div>`;
 h+='</div><h3>ภารกิจรายสัปดาห์</h3>';
 for(const m of w.missions)h+=`<div class="card"><div class="row"><span>${esc(m.label)}</span><span class="mut">${fmt(m.progress)}/${fmt(m.target)}</span></div>
  <div class="bar"><i style="width:${m.progress/m.target*100}%"></i></div>
  <div class="row" style="margin-top:8px"><span class="mut">+${fmt(m.xp)} XP · +${m.points} แต้ม</span>
  <button class="act" ${(!m.complete||m.claimed)?'disabled':''} onclick="claimM('${esc(m.id)}')">${m.claimed?'เสร็จสมบูรณ์':'รับ'}</button></div></div>`;
 $('#main').innerHTML=h},
async social(){const s=await api('/api/season/social');
 let h=`<div class="card"><div class="row"><span>โค้ดเชิญของฉัน</span><b class="gold">${esc(s.invite_code)}</b></div>
 <div class="row" style="margin-top:8px"><input id="bc" placeholder="โค้ดของอาจารย์" maxlength="16"><button class="act" onclick="bind()">ผูกเป็นศิษย์</button></div>
 <div class="mut" style="margin-top:6px">${s.mentor?'อาจารย์ของฉัน: '+esc(s.mentor):'ยังไม่มีอาจารย์'}</div></div>
 <h3>ส่งต่อคนไฟ</h3><div class="card"><div class="mut">มูลค่าทรัพย์สินศิษย์ที่นับได้: <b class="gold">${fmt(s.handoff.total_asset_value)}</b> · ศิษย์ ${s.students.length}/${s.max_students}</div>
 <div class="nodes" style="margin-top:8px">`+s.handoff.track.map(t=>`<div class="node ${t.unlocked?'ok':''}"><b>${fmt(t.threshold)}</b><div>${esc(t.reward.label)}</div>
 <button class="act" ${(!t.unlocked||t.claimed)?'disabled':''} onclick="claimH(${t.threshold})">${t.claimed?'รับแล้ว':'รับ'}</button></div>`).join('')+'</div>'+
 s.students.map(x=>`<div class="mut" style="margin-top:6px">ศิษย์ ${esc(x.uid)} — ${fmt(x.asset_value)} ${x.counted?'':'(ยังไม่นับ: รอครบ 24 ชม.)'}</div>`).join('')+'</div>';
 h+='<h3>เพื่อน</h3><div class="card"><div class="row"><input id="fr" placeholder="uid เพื่อน"><button class="act" onclick="freq()">ส่งคำขอ</button></div>'+
  s.friend_requests.map(u=>`<div class="row" style="margin-top:6px"><span>${esc(u)} ขอเป็นเพื่อน</span><button class="act" onclick="facc('${esc(u)}')">ตอบรับ</button></div>`).join('')+
  (s.friends.length?s.friends.map(f=>`<div style="margin-top:6px">${esc(f.name||f.uid)} <span class="mut">${esc(f.status||'')}</span></div>`).join(''):'<div class="mut" style="margin-top:6px">ยังไม่มีเพื่อน</div>')+'</div>';
 h+='<h3>ความเคลื่อนไหวล่าสุด</h3><div class="card">'+(s.activity.length?s.activity.map(a=>`<div class="mut">${new Date(a.ts*1000).toLocaleString('th-TH')} — ${esc(a.text)}</div>`).join(''):'<div class="mut">ยังไม่มี</div>')+'</div>';
 $('#main').innerHTML=h},
async market(){const[m,s]=await Promise.all([api('/api/season/market'),api('/api/season/stash')]);$('#cred').textContent='เครดิต '+fmt(m.credits);
 const gr={key:'กุญแจ',keycard:'คีย์การ์ด'};let h='<h3>ตลาด</h3>';
 for(const i of m.items){const x=[i.durability&&'ความทนทาน '+i.durability,i.uses&&'ใช้ได้ '+i.uses+' ครั้ง',i.armor_class&&'เกราะ '+i.armor_class,i.pen_class&&'เจาะ '+i.pen_class].filter(Boolean).join(' · ');
  h+=`<div class="card"><div class="row"><b>${esc(i.name)}</b><span class="gold">${fmt(i.price)}</span></div><div class="mut">${esc(gr[i.category]||i.category)} ${i.tier_roman?'· '+esc(i.tier_roman):''} ${x?'· '+esc(x):''}</div>
  <div style="margin-top:6px"><button class="act" onclick="buy('${esc(i.id)}')">ซื้อ 1</button></div></div>`}
 h+='<h3>คลังของฉัน</h3>'+(s.stash.length?s.stash.map(i=>`<div class="card"><div class="row"><span>${esc(i.name||i.id)} ${i.used?'<span class="mut">(ใช้แล้ว '+i.uses_left+'/'+i.uses_max+')</span>':'x'+i.qty}</span>
  <button class="act" ${i.sell_price<=0?'disabled':''} onclick="sell('${esc(i.id)}',${i.used?'true':'false'})">ขาย 1 (${fmt(i.sell_price)})</button></div></div>`).join(''):'<div class="card mut">คลังว่าง</div>');
 $('#main').innerHTML=h}};
const go=async(p,b,ok)=>{try{await api(p,b);if(ok)toast(ok);render()}catch(e){}};
const joinEv=id=>go('/api/season/event/join',{event_id:id},'เข้าร่วมแล้ว');
const claimM=id=>go('/api/season/weekly/claim',{mission_id:id},'รับรางวัลแล้ว');
const claimTrack=p=>go('/api/season/weekly/track/claim',{points:p},'รับรางวัลแล้ว');
const bind=()=>go('/api/season/mentor/bind',{code:$('#bc').value},'ผูกสำเร็จ');
const claimH=t=>go('/api/season/mentor/claim',{threshold:t},'รับรางวัลแล้ว');
const freq=()=>go('/api/season/friends/request',{to_uid:$('#fr').value},'ส่งคำขอแล้ว');
const facc=u=>go('/api/season/friends/accept',{from_uid:u},'เป็นเพื่อนกันแล้ว');
const buy=id=>go('/api/season/market/buy',{item_id:id,qty:1},'ซื้อแล้ว');
const sell=(id,used)=>go('/api/season/market/sell',{item_id:id,qty:1,used:!!used},'ขายแล้ว');
render();
</script></body></html>"""


