_LO_LOCK = _lo_thr.RLock()
_LO_RT = {"gates": (), "phases": {}, "thread": None, "last_tick": 0.0}
LIVEOPS_STATE = {"fired": {}, "added": [], "overrides": {}, "removed": []}


def _lo_save():
    try:
        tmp = LIVEOPS_STATE_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _lo_json.dump(LIVEOPS_STATE, f, ensure_ascii=False)
        _lo_os.replace(tmp, LIVEOPS_STATE_PATH)
    except Exception as exc:
        print("[LIVEOPS] save failed:", repr(exc))


def _lo_load():
    try:
        if _lo_os.path.isfile(LIVEOPS_STATE_PATH):
            with open(LIVEOPS_STATE_PATH, "r", encoding="utf-8") as f:
                data = _lo_json.load(f)
            for k, default in LIVEOPS_STATE.items():
                if k in data and isinstance(data[k], type(default)):
                    LIVEOPS_STATE[k] = data[k]
    except Exception as exc:
        print("[LIVEOPS] load failed:", repr(exc))


_lo_load()


def _lo_parse(s):
    """'YYYY-MM-DDTHH:MM' (เวลาไทย) -> epoch seconds"""
    return _lo_dt.fromisoformat(str(s)).replace(tzinfo=_SH_TZ).timestamp()


def _lo_iso(ts):
    return _lo_dt.fromtimestamp(ts, _SH_TZ).isoformat(timespec="minutes")


def _lo_date(ts):
    return _lo_dt.fromtimestamp(ts, _SH_TZ).date().isoformat()


def _lo_end_date(end_ts):
    """วันที่สุดท้ายที่อีเวนต์ยังเปิด (end เป็นเวลาปิดพอดี จึงลอยถอยหลัง 1 วินาที)"""
    return _lo_date(end_ts - 1)


def _lo_effective():
    removed = set(LIVEOPS_STATE.get("removed", []))
    out = []
    for e in list(LIVEOPS_DEFAULT_SCHEDULE) + list(LIVEOPS_STATE.get("added", [])):
        if e["id"] in removed:
            continue
        ov = LIVEOPS_STATE.get("overrides", {}).get(e["id"])
        out.append({**e, **ov} if ov else e)
    return out


def _lo_phase(e, now):
    s, en = _lo_parse(e["start"]), _lo_parse(e["end"])
    return "upcoming" if now < s else ("active" if now < en else "ended")


def _lo_group_key(e):
    return (e["action"], (e.get("params") or {}).get("event_id", ""))


def _lo_pick_focus(entries, now):
    """ต่อกลุ่มอีเวนต์เดียวกัน เลือกรอบที่กำลังเปิด > รอบถัดไปที่ใกล้สุด > รอบล่าสุดที่จบแล้ว"""
    by = {}
    for e in entries:
        if not e.get("disabled"):
            by.setdefault(_lo_group_key(e), []).append(e)
    out = {}
    for key, lst in by.items():
        act = sorted([e for e in lst if _lo_phase(e, now) == "active"], key=lambda x: _lo_parse(x["start"]))
        up = sorted([e for e in lst if _lo_phase(e, now) == "upcoming"], key=lambda x: _lo_parse(x["start"]))
        end = sorted([e for e in lst if _lo_phase(e, now) == "ended"], key=lambda x: -_lo_parse(x["end"]))
        pick = (act or up or end)[0]
        out[key] = (pick, _lo_phase(pick, now))
    return out


# ---------------- actions: เรียกซ้ำได้ทุก tick (idempotent) ----------------
def _lo_act_season_hub_event(e, phase):
    s, en = _lo_parse(e["start"]), _lo_parse(e["end"])
    for ev in SH_MAIN_EVENTS:
        if ev["id"] == (e.get("params") or {}).get("event_id"):
            ev["start"], ev["end"] = _lo_date(s), _lo_end_date(en)


def _lo_act_vaelor_breach(e, phase):
    s, en = _lo_parse(e["start"]), _lo_parse(e["end"])
    with _VAELOR_LOCK:
        st = _VAELOR["state"]
        if st.get("start_ts") != s or st.get("end_ts") != en:
            st["start_ts"], st["end_ts"] = s, en
            _vaelor_save()


def _lo_act_vial_drive(e, phase):
    s, en = _lo_parse(e["start"]), _lo_parse(e["end"])
    VIALRUN_EVENT["start"], VIALRUN_EVENT["end"] = _lo_date(s), _lo_end_date(en)


def _lo_act_season_finale_boost(e, phase):
    ev = SEASON_FINALE_EVENT
    s, en = _lo_parse(e["start"]), _lo_parse(e["end"])
    mine = ev.get("_liveops_id") == e["id"]
    if phase == "active":
        if ev["active"] and not mine:
            return                      # แอดมินเปิดเองผ่าน /api/seasonevent/activate อยู่ — ไม่แตะ
        if not ev["active"] or ev.get("ends_at") != en:
            was_active = bool(ev["active"])
            for key, val in (e.get("params") or {}).items():
                if key in ("item_drop_rate", "char_exp_mult", "battlepass_exp_mult", "loot_qty_mult"):
                    ev[key] = float(val)
            ev.update({"active": True, "started_at": s, "ends_at": en, "_liveops_id": e["id"]})
            if not was_active:
                try:
                    sio.emit('season_finale_event_started', dict(ev))
                except Exception:
                    pass
    elif mine and ev["active"]:
        ev["active"] = False
        ev["ends_at"] = None
        ev.pop("_liveops_id", None)
        try:
            sio.emit('season_finale_event_ended', {"name_th": ev["name_th"]})
        except Exception:
            pass


def _lo_act_sky_city_festival(e, phase):
    """เปิด/ปิดเทศกาลเมืองลอยฟ้า (ลดราคา / เหรียญเว็บ / พลุ / แลก NPC)"""
    try:
        params = e.get("params") or {}
        s, en = _lo_parse(e["start"]), _lo_parse(e["end"])
        if phase == "active":
            VMAX_SKY_CITY_FESTIVAL.update({
                "active": True,
                "event_id": e.get("id"),
                "name_th": e.get("name_th"),
                "start_ts": s,
                "end_ts": en,
                "price_mult": float(params.get("price_mult", 0.5)),
                "web_activity_coin_mult": float(params.get("web_activity_coin_mult", 0.5)),
                "fireworks_hour_local": int(params.get("fireworks_hour_local", 0)),
                "npc_exchange_enabled": bool(params.get("npc_exchange_enabled", True)),
            })
        else:
            if VMAX_SKY_CITY_FESTIVAL.get("event_id") == e.get("id"):
                VMAX_SKY_CITY_FESTIVAL["active"] = False
                VMAX_SKY_CITY_FESTIVAL["end_ts"] = en
    except NameError:
        pass  # module not loaded yet
    except Exception as _scf_exc:
        print("[LIVEOPS] sky_city_festival action failed:", repr(_scf_exc))


LIVEOPS_ACTIONS = {
    "season_hub_event": _lo_act_season_hub_event,
    "vaelor_breach": _lo_act_vaelor_breach,
    "vial_drive": _lo_act_vial_drive,
    "season_finale_boost": _lo_act_season_finale_boost,
    "sky_city_festival": _lo_act_sky_city_festival,
    "calendar_only": lambda e, phase: None,     # แค่ประกาศ + ขึ้นปฏิทิน (ไม่ผูกระบบใด)
}


def _lo_announce_all(entries, now):
    """ประกาศล่วงหน้า/เริ่ม/จบ — ส่งครั้งเดียวต่ออีเวนต์ (จำใน state) และไม่ส่งย้อนหลังถ้าพลาดช่วงนานแล้ว"""
    dirty = False
    for e in entries:
        if e.get("disabled"):
            continue
        s, en = _lo_parse(e["start"]), _lo_parse(e["end"])
        fired = LIVEOPS_STATE["fired"].setdefault(e["id"], {})
        for which, ok in (
            ("pre",   lambda c: s - float(c.get("pre_hours", 24)) * 3600 <= now < s),
            ("start", lambda c: s <= now < s + 24 * 3600),
            ("end",   lambda c: en <= now < en + 12 * 3600),
        ):
            cfg = (e.get("announce") or {}).get(which)
            if not cfg or which in fired or not ok(cfg):
                continue
            fired[which] = now
            dirty = True
            try:
                post_announcement("event", cfg["title"], cfg["body"],
                                  expires_in=int(float(cfg.get("hours", 24)) * 3600))
            except Exception as exc:
                print("[LIVEOPS] announce failed:", repr(exc))
    return dirty


def _lo_sync_catalog(entries, now):
    """ให้ปฏิทิน/แท็บอีเวนต์เดิม (EVENT_CATALOG) ตรงกับตารางเสมอ"""
    by = {}
    for e in entries:
        if e.get("catalog") and not e.get("disabled"):
            by.setdefault(e.get("catalog_id") or e["id"], []).append(e)
    for cid, lst in by.items():
        act = sorted([e for e in lst if _lo_phase(e, now) == "active"], key=lambda x: _lo_parse(x["start"]))
        up = sorted([e for e in lst if _lo_phase(e, now) == "upcoming"], key=lambda x: _lo_parse(x["start"]))
        end = sorted([e for e in lst if _lo_phase(e, now) == "ended"], key=lambda x: -_lo_parse(x["end"]))
        pick = (act or up or end)[0]
        row = {"id": cid, "name_th": pick["name_th"], "type": "limited",
               "start": _lo_date(_lo_parse(pick["start"])), "end": _lo_end_date(_lo_parse(pick["end"]))}
        for i, cur in enumerate(EVENT_CATALOG):
            if cur.get("id") == cid:
                EVENT_CATALOG[i] = {**cur, **row}
                break
        else:
            EVENT_CATALOG.append(row)
    if LIVEOPS_PRUNE_ENDED_CATALOG:
        today = _lo_date(now)
        EVENT_CATALOG[:] = [c for c in EVENT_CATALOG
                            if not (c.get("type") == "limited" and c.get("end") and c["end"] < today)]


def _lo_tick(now=None):
    with _LO_LOCK:
        now = _lo_time.time() if now is None else now
        entries = _lo_effective()
        focus = _lo_pick_focus(entries, now)
        gates = []
        for _key, (e, phase) in focus.items():
            fn = LIVEOPS_ACTIONS.get(e["action"])
            try:
                if fn:
                    fn(e, phase)
            except Exception as exc:
                print("[LIVEOPS] action failed", e["id"], repr(exc))
            for prefix in e.get("gate_prefixes") or ():
                gates.append((prefix, _lo_parse(e["start"]), _lo_parse(e["end"]), e["name_th"]))
        dirty = _lo_announce_all(entries, now)
        try:
            _lo_sync_catalog(entries, now)
        except Exception as exc:
            print("[LIVEOPS] catalog sync failed:", repr(exc))
        _LO_RT["gates"] = tuple(gates)
        _LO_RT["phases"] = {e["id"]: _lo_phase(e, now) for e in entries}
        _LO_RT["last_tick"] = now
        if dirty:
            _lo_save()


def _lo_loop():
    while True:
        try:
            _lo_tick()
        except Exception as exc:
            print("[LIVEOPS] tick failed:", repr(exc))
        _lo_time.sleep(LIVEOPS_TICK_SEC)


@app.before_request
def _liveops_gate():
    """endpoint ของอีเวนต์ที่ตั้ง gate_prefixes ไว้ ใช้ไม่ได้นอกช่วงเวลา (ตอบ 403 พร้อมเวลาเปิด/ปิด)"""
    path = request.path
    for prefix, s, en, name in _LO_RT.get("gates", ()):
        if path.startswith(prefix):
            now = _lo_time.time()
            if s <= now < en:
                return None
            msg = f"{name} ยังไม่เปิด" if now < s else f"{name} จบแล้ว"
            return jsonify({"st": "error", "msg": msg,
                            "liveops": {"opens_at": _lo_iso(s), "closes_at": _lo_iso(en)}}), 403
    return None


def _lo_is_admin():
    try:
        if vmax_admin_unlocked():
            return True
    except Exception:
        pass
    try:
        uid, rank = _staff_from_request()
        return uid is not None and rank is not None and rank >= STAFF_RANKS["admin"]
    except Exception:
        return False


def _lo_view(e, now):
    s, en = _lo_parse(e["start"]), _lo_parse(e["end"])
    phase = "disabled" if e.get("disabled") else _lo_phase(e, now)
    return {"id": e["id"], "name_th": e["name_th"], "action": e["action"],
            "start": _lo_iso(s), "end": _lo_iso(en), "phase": phase,
            "starts_in_sec": max(0, int(s - now)), "ends_in_sec": max(0, int(en - now)),
            "custom": any(x["id"] == e["id"] for x in LIVEOPS_STATE.get("added", []))}


@app.route('/api/liveops/schedule')
def api_liveops_schedule():
    """ตารางอีเวนต์ทั้งหมด + สถานะตอนนี้ (?phase=active|upcoming|ended กรองได้)"""
    now = _lo_time.time()
    rows = [_lo_view(e, now) for e in _lo_effective()]
    want = request.args.get("phase")
    if want:
        rows = [r for r in rows if r["phase"] == want]
    rows.sort(key=lambda r: r["start"])
    return jsonify({"st": "ok", "enabled": LIVEOPS_ENABLED, "now": _lo_iso(now), "events": rows})


def _lo_validate(body, need_all):
    for k in ("start", "end"):
        if need_all or k in body:
            try:
                _lo_parse(body[k])
            except Exception:
                return f"{k} ต้องเป็นรูปแบบ YYYY-MM-DDTHH:MM (เวลาไทย)"
    if need_all and body.get("action") not in LIVEOPS_ACTIONS:
        return "action ต้องเป็นหนึ่งใน: " + ", ".join(LIVEOPS_ACTIONS)
    s = body.get("start")
    en = body.get("end")
    if s and en and _lo_parse(en) <= _lo_parse(s):
        return "end ต้องอยู่หลัง start"
    return None


@app.route('/api/liveops/admin/add', methods=['POST'])
def api_liveops_admin_add():
    """แอดมิน: body {id, name_th, start, end, action, params?, announce?, catalog?, catalog_id?, gate_prefixes?}"""
    if not _lo_is_admin():
        return jsonify({"st": "error", "msg": "ต้องเป็นแอดมิน"}), 403
    b = request.get_json(silent=True) or {}
    if not b.get("id") or not b.get("name_th"):
        return jsonify({"st": "error", "msg": "ต้องมี id และ name_th"}), 400
    err = _lo_validate(b, True)
    if err:
        return jsonify({"st": "error", "msg": err}), 400
    with _LO_LOCK:
        if any(e["id"] == b["id"] for e in _lo_effective()):
            return jsonify({"st": "error", "msg": "id นี้มีอยู่แล้ว"}), 409
        keep = ("id", "name_th", "start", "end", "action", "params", "announce", "catalog", "catalog_id", "gate_prefixes")
        LIVEOPS_STATE["added"].append({k: b[k] for k in keep if k in b})
        LIVEOPS_STATE["removed"] = [x for x in LIVEOPS_STATE["removed"] if x != b["id"]]
        _lo_save()
        _lo_tick()
    return jsonify({"st": "ok"})


@app.route('/api/liveops/admin/update', methods=['POST'])
def api_liveops_admin_update():
    """แอดมิน: body {id, start?, end?, disabled?, name_th?} — เลื่อนวัน/ปิดรอบชั่วคราว (ประกาศของรอบนี้ถูกรีเซ็ตให้ส่งใหม่)"""
    if not _lo_is_admin():
        return jsonify({"st": "error", "msg": "ต้องเป็นแอดมิน"}), 403
    b = request.get_json(silent=True) or {}
    eid = b.get("id")
    err = _lo_validate(b, False)
    if err:
        return jsonify({"st": "error", "msg": err}), 400
    with _LO_LOCK:
        cur = next((e for e in _lo_effective() if e["id"] == eid), None)
        if not cur:
            return jsonify({"st": "error", "msg": "ไม่พบอีเวนต์นี้"}), 404
        merged = {**cur, **{k: b[k] for k in ("start", "end", "name_th") if k in b}}
        if _lo_parse(merged["end"]) <= _lo_parse(merged["start"]):
            return jsonify({"st": "error", "msg": "end ต้องอยู่หลัง start"}), 400
        ov = LIVEOPS_STATE["overrides"].setdefault(eid, {})
        for k in ("start", "end", "name_th", "disabled"):
            if k in b:
                ov[k] = b[k]
        LIVEOPS_STATE["fired"].pop(eid, None)
        _lo_save()
        _lo_tick()
    return jsonify({"st": "ok"})


@app.route('/api/liveops/admin/remove', methods=['POST'])
def api_liveops_admin_remove():
    """แอดมิน: body {id} — เอารอบนี้ออกจากตาราง"""
    if not _lo_is_admin():
        return jsonify({"st": "error", "msg": "ต้องเป็นแอดมิน"}), 403
    b = request.get_json(silent=True) or {}
    eid = b.get("id")
    with _LO_LOCK:
        LIVEOPS_STATE["added"] = [e for e in LIVEOPS_STATE["added"] if e["id"] != eid]
        if eid not in LIVEOPS_STATE["removed"]:
            LIVEOPS_STATE["removed"].append(eid)
        LIVEOPS_STATE["overrides"].pop(eid, None)
        LIVEOPS_STATE["fired"].pop(eid, None)
        _lo_save()
        _lo_tick()
    return jsonify({"st": "ok"})


def _run_liveops_selftest():
    """python <ไฟล์นี้> --selftest-liveops  — จำลองเวลาไล่ทั้งตาราง ไม่ต้องรอจริง"""
    global _lo_save
    import copy as _lo_copy
    _saved_state = _lo_copy.deepcopy(LIVEOPS_STATE)
    _real_save = _lo_save
    _lo_save = lambda: None            # จำลองเวลา — ไม่เขียนไฟล์ state จริง

    def at(s):
        return _lo_parse(s)

    def active_ids(now):
        return sorted(e["id"] for e in _lo_effective() if _lo_phase(e, now) == "active")

    checks = [
        ("2026-10-07T12:00", ["biohazard_r1", "frontline_siege_r1"]),
        ("2026-10-08T00:00", ["biohazard_r1"]),
        ("2026-10-09T00:00", ["biohazard_r1", "vaelor_breach_r1"]),
        ("2026-10-22T23:59", ["biohazard_r1", "vaelor_breach_r1"]),
        ("2026-10-23T00:00", ["biohazard_r1", "frontline_siege_r2"]),
        ("2026-11-06T00:00", ["biohazard_r1", "vial_drive_r2"]),
        ("2026-11-20T00:00", []),
        ("2026-12-04T00:00", ["season_finale_boost_s13"]),
        ("2026-12-11T00:00", []),
    ]
    ok = True
    for ts, want in checks:
        got = active_ids(at(ts))
        good = got == sorted(want)
        ok &= good
        print(("PASS" if good else "FAIL"), ts, got)
    # ผูกกับระบบจริง: Vaelor / Finale / Vial / Season Hub / catalog / gate
    _lo_tick(at("2026-10-09T08:00"))
    ok &= abs(_VAELOR["state"]["start_ts"] - at("2026-10-09T00:00")) < 1
    _lo_tick(at("2026-12-05T08:00"))
    ok &= bool(SEASON_FINALE_EVENT["active"]) and SEASON_FINALE_EVENT["ends_at"] == at("2026-12-11T00:00")
    _lo_tick(at("2026-12-12T08:00"))
    ok &= not SEASON_FINALE_EVENT["active"]
    _lo_tick(at("2026-11-07T08:00"))
    ok &= VIALRUN_EVENT["start"] == "2026-11-06" and VIALRUN_EVENT["end"] == "2026-11-19"
    ok &= any(c["id"] == "field_vial_drive" and c["end"] == "2026-11-19" for c in EVENT_CATALOG)
    ok &= all(not (c.get("type") == "limited" and c.get("end") and c["end"] < "2026-11-07") for c in EVENT_CATALOG)
    fl = next(ev for ev in SH_MAIN_EVENTS if ev["id"] == "frontline_arsenal_siege")
    ok &= (fl["start"], fl["end"]) == ("2026-10-23", "2026-11-05")
    gate = [g for g in _LO_RT["gates"] if g[0].startswith("/api/vialrun/collect")]
    ok &= bool(gate) and gate[0][1] == at("2026-11-06T00:00")
    _lo_save = _real_save
    LIVEOPS_STATE.clear()
    LIVEOPS_STATE.update(_saved_state)
    _lo_tick()                         # sync กลับเป็นเวลาจริง (ไฟล์ Vaelor ไม่ค้างค่าจำลอง)
    print("LIVEOPS SELFTEST:", "OK" if ok else "FAILED")
    return ok


