def _scf_now_bangkok():
    try:
        from zoneinfo import ZoneInfo
        return _scf_dt.now(ZoneInfo("Asia/Bangkok"))
    except Exception:
        return _scf_dt.utcnow() + _scf_td(hours=7)


def vmax_sky_city_festival_active():
    """True ถ้าเทศกาลกำลังเปิด (LiveOps หรือเปิดมือ)"""
    st = VMAX_SKY_CITY_FESTIVAL
    if not st.get("active"):
        return False
    now = _scf_time.time()
    end_ts = st.get("end_ts")
    if end_ts and now > float(end_ts):
        st["active"] = False
        return False
    start_ts = st.get("start_ts")
    if start_ts and now < float(start_ts):
        return False
    return True


def vmax_sky_city_price_mult():
    """ตัวคูณราคาในร้านเมืองลอยฟ้า (1.0 = ปกติ, 0.5 = ลดครึ่ง)"""
    if vmax_sky_city_festival_active():
        return float(VMAX_SKY_CITY_FESTIVAL.get("price_mult", 0.5))
    return 1.0


def vmax_web_activity_coin_mult():
    """ตัวคูณต้นทุนเหรียญกิจกรรมบนเว็บ"""
    if vmax_sky_city_festival_active():
        return float(VMAX_SKY_CITY_FESTIVAL.get("web_activity_coin_mult", 0.5))
    return 1.0


def vmax_apply_sky_city_price(base_price):
    """คำนวณราคาหลังส่วนลดเทศกาล (ปัดเศษขึ้นเป็น int อย่างน้อย 1 ถ้า base > 0)"""
    try:
        p = float(base_price)
    except Exception:
        return base_price
    mult = vmax_sky_city_price_mult()
    if mult >= 0.999:
        return int(round(p))
    out = int(max(1, round(p * mult))) if p > 0 else 0
    return out


def vmax_web_activity_cost(activity_id):
    """ต้นทุนเหรียญกิจกรรมบนเว็บหลังส่วนลดเทศกาล"""
    base = int(VMAX_WEB_ACTIVITY_COIN["activity_costs"].get(str(activity_id), 0))
    mult = vmax_web_activity_coin_mult()
    if mult >= 0.999:
        return base
    return int(max(1, round(base * mult))) if base > 0 else 0


def vmax_web_activity_coin_balance(uid):
    uid = str(uid or "default_player")
    return int(VMAX_WEB_ACTIVITY_COIN["balances"].get(uid, 0))


def vmax_web_activity_coin_grant(uid, amount):
    uid = str(uid or "default_player")
    bal = VMAX_WEB_ACTIVITY_COIN["balances"]
    bal[uid] = int(bal.get(uid, 0)) + int(amount)
    return bal[uid]


def vmax_web_activity_coin_spend(uid, amount):
    uid = str(uid or "default_player")
    bal = VMAX_WEB_ACTIVITY_COIN["balances"]
    cur = int(bal.get(uid, 0))
    need = int(amount)
    if cur < need:
        return False, cur
    bal[uid] = cur - need
    return True, bal[uid]


def _scf_fireworks_payload(now=None):
    now = now or _scf_now_bangkok()
    colors = ["แดง", "ทอง", "ม่วง", "เขียว", "ฟ้า", "ขาว", "ชมพู"]
    patterns = ["ดอกบัว", "ฝนดาว", "วงแหวน", "ดอกซากุระ", "เกลียวมังกร", "พุ่มไฟ"]
    return {
        "at": now.isoformat(),
        "zone": "sky_city_sky",
        "title_th": "พลุไฟเทศกาลเมืองลอยฟ้า",
        "desc_th": "พลุไฟจุดขึ้นบนท้องฟ้าเมืองลอยฟ้า — ชมได้จากทุกเขต",
        "bursts": [
            {
                "color": _scf_random.choice(colors),
                "pattern": _scf_random.choice(patterns),
                "altitude_m": _scf_random.randint(180, 420),
            }
            for _ in range(_scf_random.randint(6, 12))
        ],
        "duration_sec": 90,
    }


def vmax_sky_city_fireworks_tick(force=False):
    """
    ยิงพลุไฟตอนถึงชั่วโมงที่ตั้ง (ค่าเริ่มต้น 00:00 เวลาไทย) วันละครั้ง
    เรียกจาก LiveOps tick / background หรือ API ทดสอบ
    """
    if not vmax_sky_city_festival_active() and not force:
        return {"fired": False, "reason": "festival_inactive"}
    now = _scf_now_bangkok()
    hour = int(VMAX_SKY_CITY_FESTIVAL.get("fireworks_hour_local", 0))
    date_key = now.strftime("%Y-%m-%d")
    if not force:
        if now.hour != hour:
            return {"fired": False, "reason": "not_midnight_hour", "hour": now.hour, "want": hour}
        if VMAX_SKY_CITY_FESTIVAL.get("last_fireworks_date") == date_key:
            return {"fired": False, "reason": "already_fired_today", "date": date_key}
    payload = _scf_fireworks_payload(now)
    VMAX_SKY_CITY_FESTIVAL["last_fireworks_date"] = date_key
    log = VMAX_SKY_CITY_FESTIVAL.setdefault("fireworks_log", [])
    log.append(payload)
    if len(log) > 30:
        del log[:-30]
    try:
        sio.emit("sky_city_fireworks", payload)
    except Exception:
        pass
    try:
        if callable(globals().get("post_announcement")):
            post_announcement(
                title=payload["title_th"],
                body=payload["desc_th"],
                channel="event",
            )
    except Exception:
        pass
    return {"fired": True, "payload": payload}


def vmax_sky_city_festival_status():
    st = dict(VMAX_SKY_CITY_FESTIVAL)
    st["is_active_now"] = vmax_sky_city_festival_active()
    st["price_mult_effective"] = vmax_sky_city_price_mult()
    st["web_activity_coin_mult_effective"] = vmax_web_activity_coin_mult()
    st["npc_exchange_count"] = len(VMAX_SKY_CITY_NPC_EXCHANGE)
    st["web_activity_costs_effective"] = {
        k: vmax_web_activity_cost(k) for k in VMAX_WEB_ACTIVITY_COIN["activity_costs"]
    }
    # ไม่ส่ง log ยาวใน status สั้น
    st.pop("fireworks_log", None)
    return st


def vmax_sky_city_npc_exchange_list(uid=None):
    uid = str(uid or "")
    used = VMAX_SKY_CITY_NPC_EXCHANGE_STATE.get(uid, {}) if uid else {}
    fest = vmax_sky_city_festival_active()
    out = []
    for row in VMAX_SKY_CITY_NPC_EXCHANGE:
        if row.get("festival_only") and not fest:
            continue
        r = dict(row)
        recv = dict(row["receive"])
        if fest and row.get("festival_bonus_receive_mult"):
            recv["qty"] = int(max(1, round(recv["qty"] * float(row["festival_bonus_receive_mult"]))))
            r["festival_bonus_applied"] = True
        r["receive"] = recv
        r["used"] = int(used.get(row["exchange_id"], 0))
        r["remaining"] = max(0, int(row.get("limit_per_player", 99)) - r["used"])
        r["available"] = r["remaining"] > 0
        out.append(r)
    return out


def vmax_sky_city_npc_exchange_do(uid, exchange_id, inventory_provider=None):
    """
    แลกของกับ NPC
    inventory_provider: optional callable(uid) -> dict item_id->qty ที่แก้ได้
    ถ้าไม่ส่ง ใช้ dict ในหน่วยความจำต่อ uid
    """
    uid = str(uid or "default_player")
    if not exchange_id:
        return {"st": "error", "msg": "ต้องระบุ exchange_id"}
    row = next((x for x in VMAX_SKY_CITY_NPC_EXCHANGE if x["exchange_id"] == exchange_id), None)
    if not row:
        return {"st": "error", "msg": "ไม่พบรายการแลก"}
    fest = vmax_sky_city_festival_active()
    if row.get("festival_only") and not fest:
        return {"st": "error", "msg": "รายการนี้เปิดเฉพาะช่วงเทศกาล"}
    used_map = VMAX_SKY_CITY_NPC_EXCHANGE_STATE.setdefault(uid, {})
    used = int(used_map.get(exchange_id, 0))
    limit = int(row.get("limit_per_player", 99))
    if used >= limit:
        return {"st": "error", "msg": "ครบโควต้าแล้ว"}

    # inventory
    if inventory_provider is None:
        if not hasattr(vmax_sky_city_npc_exchange_do, "_inv"):
            vmax_sky_city_npc_exchange_do._inv = {}
        inv = vmax_sky_city_npc_exchange_do._inv.setdefault(uid, {})
    else:
        inv = inventory_provider(uid)

    give = row["give"]
    gid, gqty = give["item_id"], int(give["qty"])
    have = int(inv.get(gid, 0))
    if have < gqty:
        return {"st": "error", "msg": f"ของไม่พอ ต้องการ {give.get('name_th', gid)} x{gqty} (มี {have})"}

    recv = dict(row["receive"])
    if fest and row.get("festival_bonus_receive_mult"):
        recv["qty"] = int(max(1, round(recv["qty"] * float(row["festival_bonus_receive_mult"]))))

    inv[gid] = have - gqty
    rid = recv["item_id"]
    inv[rid] = int(inv.get(rid, 0)) + int(recv["qty"])

    # ถ้าเป็นเหรียญกิจกรรมเว็บ ให้ sync เข้า balance ด้วย
    if rid == "web_activity_coin":
        vmax_web_activity_coin_grant(uid, int(recv["qty"]))
    if gid == "web_activity_coin":
        vmax_web_activity_coin_spend(uid, gqty)

    used_map[exchange_id] = used + 1
    return {
        "st": "ok",
        "gave": give,
        "received": recv,
        "used": used_map[exchange_id],
        "remaining": limit - used_map[exchange_id],
        "inventory_snapshot": {gid: inv.get(gid, 0), rid: inv.get(rid, 0)},
    }


# ---- patch ราคาในร้านเมืองลอยฟ้า (แสดง + ซื้อ) ----
def _vmax_shop_public_with_festival(shop):
    """ห่อ _vmax_shop_public เดิมให้ใส่ราคาหลังส่วนลด"""
    try:
        base = _vmax_shop_public(shop)
    except Exception:
        base = {
            "shop_id": shop.get("shop_id"),
            "name": shop.get("name"),
            "city_zone": shop.get("city_zone"),
            "currency": shop.get("currency"),
            "items": list(shop.get("items") or []),
        }
    mult = vmax_sky_city_price_mult()
    items = []
    for it in base.get("items") or []:
        it2 = dict(it)
        bp = it2.get("price", it2.get("base_price"))
        if bp is not None:
            it2["base_price"] = int(bp)
            it2["price"] = vmax_apply_sky_city_price(bp)
            it2["festival_discount"] = mult < 0.999
            it2["price_mult"] = mult
        items.append(it2)
    base["items"] = items
    base["festival_active"] = vmax_sky_city_festival_active()
    base["price_mult"] = mult
    return base


# แทนที่ _vmax_shop_public ถ้ามีอยู่แล้ว
try:
    if callable(globals().get("_vmax_shop_public")) and not getattr(_vmax_shop_public, "_scf_wrapped", False):
        _scf_orig_shop_public = _vmax_shop_public
        def _vmax_shop_public(shop):
            return _vmax_shop_public_with_festival(shop) if True else _scf_orig_shop_public(shop)
        # re-bind properly
        def _vmax_shop_public(shop, _orig=_scf_orig_shop_public):
            base = _orig(shop)
            mult = vmax_sky_city_price_mult()
            items = []
            for it in base.get("items") or []:
                it2 = dict(it)
                bp = it2.get("price", it2.get("base_price"))
                if bp is not None:
                    it2["base_price"] = int(bp)
                    it2["price"] = vmax_apply_sky_city_price(bp)
                    it2["festival_discount"] = mult < 0.999
                    it2["price_mult"] = mult
                items.append(it2)
            base["items"] = items
            base["festival_active"] = vmax_sky_city_festival_active()
            base["price_mult"] = mult
            return base
        _vmax_shop_public._scf_wrapped = True
        globals()["_vmax_shop_public"] = _vmax_shop_public
except Exception as _scf_wrap_exc:
    print("[SKY FESTIVAL] shop public wrap skip:", repr(_scf_wrap_exc))


# ---- Flask routes ----
try:
    @app.route("/api/sky-city/festival", methods=["GET"])
    def api_sky_city_festival_status():
        return jsonify({"st": "ok", **vmax_sky_city_festival_status()})

    @app.route("/api/sky-city/festival/fireworks", methods=["GET"])
    def api_sky_city_festival_fireworks_log():
        return jsonify({
            "st": "ok",
            "active": vmax_sky_city_festival_active(),
            "log": list(VMAX_SKY_CITY_FESTIVAL.get("fireworks_log") or [])[-10:],
            "last_date": VMAX_SKY_CITY_FESTIVAL.get("last_fireworks_date"),
        })

    @app.route("/api/sky-city/festival/fireworks/trigger", methods=["POST"])
    def api_sky_city_festival_fireworks_trigger():
        """ทดสอบยิงพลุ (force=1 ข้ามเงื่อนไขชั่วโมง)"""
        body = request.get_json(silent=True) or {}
        force = bool(body.get("force", True))
        result = vmax_sky_city_fireworks_tick(force=force)
        return jsonify({"st": "ok" if result.get("fired") else "skip", **result})

    @app.route("/api/sky-city/festival/npc-exchange", methods=["GET"])
    def api_sky_city_npc_exchange_list():
        uid = request.args.get("uid") or getattr(request, "vmax_uid", None) or "default_player"
        return jsonify({
            "st": "ok",
            "festival_active": vmax_sky_city_festival_active(),
            "exchanges": vmax_sky_city_npc_exchange_list(uid),
        })

    @app.route("/api/sky-city/festival/npc-exchange", methods=["POST"])
    def api_sky_city_npc_exchange_do():
        body = request.get_json(silent=True) or {}
        uid = body.get("uid") or getattr(request, "vmax_uid", None) or "default_player"
        exchange_id = body.get("exchange_id")
        result = vmax_sky_city_npc_exchange_do(uid, exchange_id)
        code = 200 if result.get("st") == "ok" else 400
        return jsonify(result), code

    @app.route("/api/web/activity-coin/balance", methods=["GET"])
    def api_web_activity_coin_balance():
        uid = request.args.get("uid") or getattr(request, "vmax_uid", None) or "default_player"
        return jsonify({
            "st": "ok",
            "uid": uid,
            "balance": vmax_web_activity_coin_balance(uid),
            "costs": {k: vmax_web_activity_cost(k) for k in VMAX_WEB_ACTIVITY_COIN["activity_costs"]},
            "festival_active": vmax_sky_city_festival_active(),
            "cost_mult": vmax_web_activity_coin_mult(),
        })

    @app.route("/api/web/activity-coin/spend", methods=["POST"])
    def api_web_activity_coin_spend():
        body = request.get_json(silent=True) or {}
        uid = body.get("uid") or getattr(request, "vmax_uid", None) or "default_player"
        activity_id = body.get("activity_id")
        if not activity_id:
            return jsonify({"st": "error", "msg": "ต้องระบุ activity_id"}), 400
        cost = vmax_web_activity_cost(activity_id)
        if cost <= 0:
            return jsonify({"st": "error", "msg": "ไม่รู้จัก activity_id"}), 400
        ok, bal = vmax_web_activity_coin_spend(uid, cost)
        if not ok:
            return jsonify({"st": "error", "msg": "เหรียญไม่พอ", "balance": bal, "need": cost}), 400
        return jsonify({
            "st": "ok",
            "activity_id": activity_id,
            "spent": cost,
            "balance": bal,
            "festival_discount": vmax_web_activity_coin_mult() < 0.999,
        })

    @app.route("/api/web/activity-coin/grant", methods=["POST"])
    def api_web_activity_coin_grant():
        body = request.get_json(silent=True) or {}
        uid = body.get("uid") or getattr(request, "vmax_uid", None) or "default_player"
        amount = int(body.get("amount", 0))
        if amount <= 0:
            return jsonify({"st": "error", "msg": "amount ต้อง > 0"}), 400
        bal = vmax_web_activity_coin_grant(uid, amount)
        return jsonify({"st": "ok", "balance": bal, "granted": amount})

    @app.route("/api/sky-city/festival/admin/set", methods=["POST"])
    def api_sky_city_festival_admin_set():
        """เปิด/ปิดเทศกาลมือ (แอดมิน) body: {active, price_mult?, web_activity_coin_mult?, hours?}"""
        try:
            if callable(globals().get("vmax_admin_require")):
                vmax_admin_require("sky_city_festival_admin")
        except Exception:
            pass
        body = request.get_json(silent=True) or {}
        active = bool(body.get("active", True))
        now = _scf_time.time()
        hours = float(body.get("hours", 24))
        VMAX_SKY_CITY_FESTIVAL.update({
            "active": active,
            "event_id": body.get("event_id") or "manual_admin",
            "name_th": body.get("name_th") or VMAX_SKY_CITY_FESTIVAL.get("name_th"),
            "start_ts": now if active else VMAX_SKY_CITY_FESTIVAL.get("start_ts"),
            "end_ts": (now + hours * 3600) if active else now,
            "price_mult": float(body.get("price_mult", VMAX_SKY_CITY_FESTIVAL.get("price_mult", 0.5))),
            "web_activity_coin_mult": float(body.get("web_activity_coin_mult", VMAX_SKY_CITY_FESTIVAL.get("web_activity_coin_mult", 0.5))),
            "npc_exchange_enabled": bool(body.get("npc_exchange_enabled", True)),
        })
        return jsonify({"st": "ok", **vmax_sky_city_festival_status()})

except Exception as _scf_route_exc:
    print("[SKY FESTIVAL] routes skip:", repr(_scf_route_exc))


# ผูก fireworks เข้า LiveOps tick ถ้าเป็นไปได้
_scf_orig_lo_tick = globals().get("_lo_tick")
if callable(_scf_orig_lo_tick) and not getattr(_scf_orig_lo_tick, "_scf_fw_hooked", False):
    def _lo_tick(*a, **k):
        out = _scf_orig_lo_tick(*a, **k)
        try:
            vmax_sky_city_fireworks_tick(force=False)
        except Exception:
            pass
        return out
    _lo_tick._scf_fw_hooked = True
    globals()["_lo_tick"] = _lo_tick


def _run_sky_city_festival_selftest():
    ok = True
    # เปิดเทศกาลมือ
    VMAX_SKY_CITY_FESTIVAL.update({
        "active": True, "event_id": "selftest", "start_ts": _scf_time.time() - 10,
        "end_ts": _scf_time.time() + 3600, "price_mult": 0.5, "web_activity_coin_mult": 0.5,
        "npc_exchange_enabled": True, "last_fireworks_date": None,
    })
    ok &= vmax_sky_city_festival_active() is True
    ok &= vmax_apply_sky_city_price(1000) == 500
    ok &= vmax_web_activity_cost("web_daily_spin") == 5  # 10 * 0.5
    # grant + spend
    vmax_web_activity_coin_grant("t_user", 100)
    ok &= vmax_web_activity_coin_balance("t_user") == 100
    spent_ok, bal = vmax_web_activity_coin_spend("t_user", vmax_web_activity_cost("web_daily_spin"))
    ok &= spent_ok and bal == 95
    # NPC exchange
    if not hasattr(vmax_sky_city_npc_exchange_do, "_inv"):
        vmax_sky_city_npc_exchange_do._inv = {}
    vmax_sky_city_npc_exchange_do._inv["t_user"] = {"scrap_metal": 20, "field_food": 4}
    r = vmax_sky_city_npc_exchange_do("t_user", "npc_festival_lantern")
    ok &= r.get("st") == "ok" and r["received"]["item_id"] == "festival_lantern"
    # fireworks force
    fw = vmax_sky_city_fireworks_tick(force=True)
    ok &= fw.get("fired") is True
    # ปิดเทศกาล
    VMAX_SKY_CITY_FESTIVAL["active"] = False
    ok &= vmax_apply_sky_city_price(1000) == 1000
    ok &= vmax_web_activity_cost("web_daily_spin") == 10
    print("SKY CITY FESTIVAL SELFTEST:", "OK" if ok else "FAILED")
    return ok


