# FESTIVAL THEME ENGINE EXTENSION
VMAX_FESTIVAL_ACTIVITY_PAGE = '<!doctype html>\n<html lang="th">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>VMAX กิจกรรม</title>\n<style id="vmax-theme-vars">\n:root {\n  --vmax-accent: #0fc2ff;\n  --vmax-accent-2: #7c5cff;\n  --vmax-bg: #0a0e17;\n  --vmax-bg-2: #121a2a;\n  --vmax-card: #152033;\n  --vmax-text: #e8f1ff;\n  --vmax-muted: #8aa0bf;\n  --vmax-border: #2a3d5c;\n  --vmax-coin: #f5d76e;\n  --vmax-gradient: linear-gradient(135deg,#0a0e17 0%,#152033 50%,#1a1040 100%);\n}\n</style>\n<style>\n* { box-sizing: border-box; }\nbody {\n  margin: 0; min-height: 100vh;\n  font-family: system-ui, "Segoe UI", sans-serif;\n  background: var(--vmax-gradient);\n  color: var(--vmax-text);\n  transition: background .6s ease, color .4s ease;\n}\n.header {\n  position: sticky; top: 0; z-index: 20;\n  background: color-mix(in srgb, var(--vmax-bg) 88%, transparent);\n  backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--vmax-border);\n  padding: 14px 18px;\n  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;\n}\n.header .icon { font-size: 28px; }\n.header h1 { margin: 0; font-size: 1.15rem; font-weight: 700; }\n.header .sub { color: var(--vmax-muted); font-size: .85rem; }\n.badge {\n  margin-left: auto;\n  background: var(--vmax-accent-2);\n  color: #fff; padding: 4px 10px; border-radius: 999px;\n  font-size: .75rem; font-weight: 600;\n}\n.wrap { max-width: 960px; margin: 0 auto; padding: 18px; }\n.grid { display: grid; grid-template-columns: repeat(auto-fill,minmax(260px,1fr)); gap: 14px; }\n.card {\n  background: var(--vmax-card);\n  border: 1px solid var(--vmax-border);\n  border-radius: 16px; padding: 16px;\n  transition: transform .15s, border-color .2s, box-shadow .2s;\n}\n.card:hover {\n  transform: translateY(-2px);\n  border-color: var(--vmax-accent);\n  box-shadow: 0 8px 24px color-mix(in srgb, var(--vmax-accent) 25%, transparent);\n}\n.card h3 { margin: 0 0 6px; font-size: 1rem; }\n.card p { margin: 0; color: var(--vmax-muted); font-size: .88rem; line-height: 1.45; }\n.coin-bar {\n  display: flex; align-items: center; gap: 10px;\n  background: var(--vmax-bg-2);\n  border: 1px solid var(--vmax-border);\n  border-radius: 14px; padding: 12px 16px; margin-bottom: 16px;\n}\n.coin-bar .coin-icon {\n  font-size: 28px;\n  filter: drop-shadow(0 0 8px var(--vmax-coin));\n}\n.coin-bar .coin-name { font-weight: 600; }\n.coin-bar .coin-bal {\n  margin-left: auto; font-size: 1.25rem; font-weight: 700;\n  color: var(--vmax-coin);\n}\n.btn {\n  display: inline-block; margin-top: 10px;\n  background: var(--vmax-accent); color: #111;\n  border: none; border-radius: 10px; padding: 8px 14px;\n  font-weight: 600; cursor: pointer; font-size: .88rem;\n}\n.btn:hover { filter: brightness(1.08); }\n.banner {\n  border-radius: 18px; padding: 22px 20px; margin-bottom: 16px;\n  background: linear-gradient(120deg, var(--vmax-accent-2), var(--vmax-accent));\n  color: #fff; position: relative; overflow: hidden;\n}\n.banner h2 { margin: 0 0 6px; font-size: 1.35rem; }\n.banner p { margin: 0; opacity: .92; font-size: .92rem; }\n.particles {\n  pointer-events: none; position: fixed; inset: 0; z-index: 0; overflow: hidden;\n}\n.particles span {\n  position: absolute; font-size: 18px; opacity: .35;\n  animation: floatUp linear infinite;\n}\n@keyframes floatUp {\n  from { transform: translateY(100vh) rotate(0deg); opacity: 0; }\n  10% { opacity: .4; }\n  to { transform: translateY(-10vh) rotate(360deg); opacity: 0; }\n}\n.footer {\n  text-align: center; color: var(--vmax-muted); font-size: .78rem;\n  padding: 24px 12px 40px;\n}\n</style>\n</head>\n<body>\n<div class="particles" id="particles"></div>\n<header class="header">\n  <span class="icon" id="themeIcon">⚡</span>\n  <div>\n    <h1 id="bannerTitle">กิจกรรม VMAX</h1>\n    <div class="sub" id="bannerSub">ภารกิจ · อีเวนต์ · แลกของ</div>\n  </div>\n  <span class="badge" id="festBadge" style="display:none">เทศกาล</span>\n</header>\n<main class="wrap">\n  <div class="banner" id="heroBanner">\n    <h2 id="heroTitle">ยินดีต้อนรับ</h2>\n    <p id="heroSub">โหลดธีมกิจกรรม...</p>\n  </div>\n  <div class="coin-bar">\n    <span class="coin-icon" id="coinIcon">🪙</span>\n    <div>\n      <div class="coin-name" id="coinName">เหรียญกิจกรรมเว็บ</div>\n      <div class="sub" id="coinSym" style="font-size:.8rem;color:var(--vmax-muted)"></div>\n    </div>\n    <div class="coin-bal" id="coinBal">0</div>\n  </div>\n  <div class="grid" id="actGrid">\n    <div class="card"><h3>⏳ กำลังโหลด</h3><p>ดึงรายการกิจกรรม...</p></div>\n  </div>\n</main>\n<footer class="footer">ธีมเปลี่ยนอัตโนมัติตามเทศกาลที่เปิดอยู่ · VMAX Festival Theme Engine</footer>\n<script>\nconst uid = new URLSearchParams(location.search).get(\'uid\') || \'default_player\';\n\nfunction applyTheme(t) {\n  const root = document.getElementById(\'vmax-theme-vars\');\n  const vars = t.css_vars || {};\n  let css = \':root {\\n\';\n  Object.keys(vars).forEach(k => { css += \'  \' + k + \': \' + vars[k] + \';\\n\'; });\n  css += \'}\\n\';\n  root.textContent = css;\n  document.getElementById(\'themeIcon\').textContent = t.icon || \'⚡\';\n  document.getElementById(\'bannerTitle\').textContent = t.name_th || \'กิจกรรม\';\n  document.getElementById(\'bannerSub\').textContent = t.subtitle_th || \'\';\n  document.getElementById(\'heroTitle\').textContent = t.banner_th || t.name_th || \'\';\n  document.getElementById(\'heroSub\').textContent = t.subtitle_th || \'\';\n  const badge = document.getElementById(\'festBadge\');\n  if (t.is_festival) { badge.style.display = \'inline-block\'; badge.textContent = t.name_th; }\n  else badge.style.display = \'none\';\n  const coin = t.coin || {};\n  document.getElementById(\'coinIcon\').textContent = coin.icon || \'🪙\';\n  document.getElementById(\'coinName\').textContent = coin.name_th || \'เหรียญ\';\n  document.getElementById(\'coinSym\').textContent = (coin.symbol || \'\') + \' · \' + (coin.name_en || \'\');\n  spawnParticles(t.particle);\n}\n\nfunction spawnParticles(kind) {\n  const box = document.getElementById(\'particles\');\n  box.innerHTML = \'\';\n  const map = {\n    lanterns: [\'🏮\',\'✨\',\'🎆\',\'⭐\'],\n    red_lanterns: [\'🏮\',\'🧧\',\'✨\'],\n    bats: [\'🦇\',\'🎃\',\'👻\'],\n    water_splash: [\'💧\',\'💦\',\'🌊\'],\n    none: [],\n  };\n  const pool = map[kind] || map.none;\n  if (!pool.length) return;\n  for (let i = 0; i < 18; i++) {\n    const s = document.createElement(\'span\');\n    s.textContent = pool[i % pool.length];\n    s.style.left = (Math.random() * 100) + \'%\';\n    s.style.animationDuration = (8 + Math.random() * 12) + \'s\';\n    s.style.animationDelay = (Math.random() * 8) + \'s\';\n    s.style.fontSize = (14 + Math.random() * 16) + \'px\';\n    box.appendChild(s);\n  }\n}\n\nasync function loadAll() {\n  try {\n    const [th, coin] = await Promise.all([\n      fetch(\'/api/festival/theme\').then(r => r.json()),\n      fetch(\'/api/festival/coin/balance?uid=\' + encodeURIComponent(uid)).then(r => r.json()),\n    ]);\n    if (th && th.st === \'ok\') applyTheme(th.theme);\n    if (coin && coin.st === \'ok\') {\n      document.getElementById(\'coinBal\').textContent = Number(coin.balance || 0).toLocaleString();\n    }\n    const costs = (coin && coin.costs) || {};\n    const grid = document.getElementById(\'actGrid\');\n    const acts = [\n      { id: \'web_daily_spin\', title: \'สปินรายวัน\', desc: \'หมุนรับรางวัลทุกวัน\' },\n      { id: \'web_event_gacha\', title: \'กาชาอีเวนต์\', desc: \'สุ่มของเทศกาล\' },\n      { id: \'web_season_pass_boost\', title: \'บูสต์ซีซันพาส\', desc: \'เร่ง EXP Battle Pass\' },\n      { id: \'web_mini_game_entry\', title: \'มินิเกม\', desc: \'เข้าเล่นมินิเกมบนเว็บ\' },\n      { id: \'npc_exchange\', title: \'แลกของกับ NPC\', desc: \'เมืองลอยฟ้า / เทศกาล\', link: true },\n      { id: \'fireworks\', title: \'พลุไฟกลางคืน\', desc: \'ชมพลุบนฟ้าเมืองลอยฟ้า\', link: true },\n    ];\n    grid.innerHTML = acts.map(a => {\n      const cost = costs[a.id];\n      const costLabel = cost != null ? (\'ใช้ \' + cost + \' เหรียญ\') : (a.link ? \'เข้าดู\' : \'เข้าร่วม\');\n      return \'<div class="card"><h3>\' + a.title + \'</h3><p>\' + a.desc + \'</p>\' +\n        \'<button class="btn" onclick="doAct(\\\'\' + a.id + \'\\\')">\' + costLabel + \'</button></div>\';\n    }).join(\'\');\n  } catch (e) {\n    console.error(e);\n  }\n}\n\nasync function doAct(id) {\n  if (id === \'npc_exchange\') {\n    const r = await fetch(\'/api/sky-city/festival/npc-exchange?uid=\' + encodeURIComponent(uid)).then(x => x.json());\n    alert(\'รายการแลก NPC: \' + ((r.exchanges || []).length) + \' รายการ\' + (r.festival_active ? \' (เทศกาลเปิด)\' : \'\'));\n    return;\n  }\n  if (id === \'fireworks\') {\n    const r = await fetch(\'/api/sky-city/festival/fireworks\').then(x => x.json());\n    alert(\'พลุล่าสุด: \' + (r.last_date || \'ยังไม่มียิง\'));\n    return;\n  }\n  const r = await fetch(\'/api/web/activity-coin/spend\', {\n    method: \'POST\', headers: {\'Content-Type\': \'application/json\'},\n    body: JSON.stringify({ uid: uid, activity_id: id }),\n  }).then(x => x.json());\n  if (r.st === \'ok\') {\n    alert(\'ใช้ \' + r.spent + \' เหรียญสำเร็จ\' + (r.festival_discount ? \' (ลดเทศกาล)\' : \'\'));\n    loadAll();\n  } else {\n    alert(r.msg || \'ไม่สำเร็จ\');\n  }\n}\n\nloadAll();\nsetInterval(loadAll, 60000);\n</script>\n</body>\n</html>\n'


