VMAX_FESTIVAL_THEME_OVERRIDE = {"theme_id": None, "forced_until": None}
VMAX_FESTIVAL_COIN_BALANCES = {}


def vmax_resolve_active_festival_theme_id():
    ov = VMAX_FESTIVAL_THEME_OVERRIDE
    if ov.get("theme_id"):
        until = ov.get("forced_until")
        if until is None or _scf_time.time() < float(until):
            return ov["theme_id"]
        ov["theme_id"] = None
        ov["forced_until"] = None
    try:
        if vmax_sky_city_festival_active():
            return "sky_city_festival"
    except Exception:
        pass
    try:
        st = globals().get("LIVEOPS_STATE") or {}
        active_ids = st.get("active_ids") or st.get("active") or []
        if isinstance(active_ids, dict):
            active_ids = list(active_ids.keys())
        for aid in active_ids:
            aid = str(aid)
            if "halloween" in aid:
                return "halloween"
            if "lunar" in aid or "cny" in aid:
                return "lunar_new_year"
            if "songkran" in aid:
                return "songkran"
            if "sky_city_festival" in aid:
                return "sky_city_festival"
    except Exception:
        pass
    return "default"


def vmax_get_festival_theme(theme_id=None):
    tid = theme_id or vmax_resolve_active_festival_theme_id()
    base = VMAX_FESTIVAL_THEMES.get(tid) or VMAX_FESTIVAL_THEME_DEFAULT
    out = dict(base)
    out["coin"] = dict(base.get("coin") or {})
    out["game_ui"] = dict(base.get("game_ui") or {})
    out["css_vars"] = dict(base.get("css_vars") or {})
    out["is_festival"] = tid != "default"
    out["resolved_at"] = _scf_time.time()
    return out


def vmax_festival_theme_css(theme=None):
    theme = theme or vmax_get_festival_theme()
    vars_ = theme.get("css_vars") or {}
    lines = ["  %s: %s;" % (k, v) for k, v in vars_.items()]
    return ":root {\n" + "\n".join(lines) + "\n}\n"


def vmax_festival_coin_info(theme=None):
    theme = theme or vmax_get_festival_theme()
    coin = dict(theme.get("coin") or VMAX_FESTIVAL_THEME_DEFAULT["coin"])
    coin["theme_id"] = theme.get("theme_id")
    coin["is_festival"] = theme.get("is_festival", False)
    return coin


def vmax_festival_coin_balance(uid, coin_id=None):
    uid = str(uid or "default_player")
    info = vmax_festival_coin_info()
    cid = coin_id or info.get("id") or "web_activity_coin"
    total = 0
    try:
        total += int(VMAX_WEB_ACTIVITY_COIN["balances"].get(uid, 0))
    except Exception:
        pass
    bag = VMAX_FESTIVAL_COIN_BALANCES.get(cid) or {}
    if cid != "web_activity_coin":
        total += int(bag.get(uid, 0))
    return total


def vmax_festival_coin_grant(uid, amount, coin_id=None):
    uid = str(uid or "default_player")
    info = vmax_festival_coin_info()
    cid = coin_id or info.get("id") or "web_activity_coin"
    if cid == "web_activity_coin" or cid in (info.get("aliases") or []):
        return vmax_web_activity_coin_grant(uid, amount)
    bag = VMAX_FESTIVAL_COIN_BALANCES.setdefault(cid, {})
    bag[uid] = int(bag.get(uid, 0)) + int(amount)
    return bag[uid]


def vmax_festival_coin_spend(uid, amount, coin_id=None):
    uid = str(uid or "default_player")
    info = vmax_festival_coin_info()
    cid = coin_id or info.get("id") or "web_activity_coin"
    need = int(amount)
    try:
        web_bal = int(VMAX_WEB_ACTIVITY_COIN["balances"].get(uid, 0))
    except Exception:
        web_bal = 0
    bag = VMAX_FESTIVAL_COIN_BALANCES.setdefault(cid, {})
    fest_bal = int(bag.get(uid, 0)) if cid != "web_activity_coin" else 0
    if web_bal + fest_bal < need:
        return False, web_bal + fest_bal
    remain = need
    if web_bal > 0:
        take = min(web_bal, remain)
        VMAX_WEB_ACTIVITY_COIN["balances"][uid] = web_bal - take
        remain -= take
    if remain > 0 and cid != "web_activity_coin":
        bag[uid] = fest_bal - remain
    return True, vmax_festival_coin_balance(uid, cid)


def vmax_game_ui_theme_payload(theme=None):
    theme = theme or vmax_get_festival_theme()
    return {
        "theme_id": theme.get("theme_id"),
        "name_th": theme.get("name_th"),
        "is_festival": theme.get("is_festival", False),
        "icon": theme.get("icon"),
        "css_vars": theme.get("css_vars"),
        "game_ui": theme.get("game_ui"),
        "coin": vmax_festival_coin_info(theme),
        "particle": theme.get("particle"),
        "banner_th": theme.get("banner_th"),
    }


try:
    from flask import Response as _FestResp

    @app.route("/activity")
    @app.route("/festival/activity")
    def api_festival_activity_page():
        return _FestResp(VMAX_FESTIVAL_ACTIVITY_PAGE, mimetype="text/html; charset=utf-8")

    @app.route("/api/festival/theme", methods=["GET"])
    def api_festival_theme():
        theme = vmax_get_festival_theme()
        return jsonify({
            "st": "ok",
            "theme": theme,
            "css": vmax_festival_theme_css(theme),
            "game_ui": vmax_game_ui_theme_payload(theme),
        })

    @app.route("/api/festival/theme/list", methods=["GET"])
    def api_festival_theme_list():
        return jsonify({
            "st": "ok",
            "active": vmax_resolve_active_festival_theme_id(),
            "themes": [
                {
                    "theme_id": t["theme_id"],
                    "name_th": t["name_th"],
                    "name_en": t.get("name_en"),
                    "icon": t.get("icon"),
                    "coin_name_th": (t.get("coin") or {}).get("name_th"),
                }
                for t in VMAX_FESTIVAL_THEMES.values()
            ],
        })

    @app.route("/api/festival/theme/css", methods=["GET"])
    def api_festival_theme_css():
        css = vmax_festival_theme_css()
        return _FestResp(css, mimetype="text/css; charset=utf-8")

    @app.route("/api/festival/game-ui", methods=["GET"])
    def api_festival_game_ui():
        return jsonify({"st": "ok", **vmax_game_ui_theme_payload()})

    @app.route("/api/festival/coin", methods=["GET"])
    def api_festival_coin_info_route():
        return jsonify({"st": "ok", "coin": vmax_festival_coin_info()})

    @app.route("/api/festival/coin/balance", methods=["GET"])
    def api_festival_coin_balance_route():
        uid = request.args.get("uid") or getattr(request, "vmax_uid", None) or "default_player"
        info = vmax_festival_coin_info()
        return jsonify({
            "st": "ok",
            "uid": uid,
            "balance": vmax_festival_coin_balance(uid),
            "coin": info,
            "costs": {k: vmax_web_activity_cost(k) for k in VMAX_WEB_ACTIVITY_COIN.get("activity_costs", {})},
            "cost_mult": vmax_web_activity_coin_mult(),
            "festival_active": info.get("is_festival", False),
        })

    @app.route("/api/festival/coin/spend", methods=["POST"])
    def api_festival_coin_spend_route():
        body = request.get_json(silent=True) or {}
        uid = body.get("uid") or getattr(request, "vmax_uid", None) or "default_player"
        amount = body.get("amount")
        activity_id = body.get("activity_id")
        if activity_id:
            amount = vmax_web_activity_cost(activity_id)
        amount = int(amount or 0)
        if amount <= 0:
            return jsonify({"st": "error", "msg": "amount/activity_id ไม่ถูกต้อง"}), 400
        ok, bal = vmax_festival_coin_spend(uid, amount)
        if not ok:
            return jsonify({"st": "error", "msg": "เหรียญไม่พอ", "balance": bal, "need": amount}), 400
        return jsonify({
            "st": "ok",
            "spent": amount,
            "balance": bal,
            "coin": vmax_festival_coin_info(),
            "activity_id": activity_id,
        })

    @app.route("/api/festival/coin/grant", methods=["POST"])
    def api_festival_coin_grant_route():
        body = request.get_json(silent=True) or {}
        uid = body.get("uid") or getattr(request, "vmax_uid", None) or "default_player"
        amount = int(body.get("amount", 0))
        if amount <= 0:
            return jsonify({"st": "error", "msg": "amount ต้อง > 0"}), 400
        bal = vmax_festival_coin_grant(uid, amount)
        return jsonify({"st": "ok", "balance": bal, "granted": amount, "coin": vmax_festival_coin_info()})

    @app.route("/api/festival/theme/admin/set", methods=["POST"])
    def api_festival_theme_admin_set():
        try:
            if callable(globals().get("vmax_admin_require")):
                vmax_admin_require("festival_theme_admin")
        except Exception:
            pass
        body = request.get_json(silent=True) or {}
        tid = body.get("theme_id")
        if tid in (None, "", "default", "auto"):
            VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = None
            VMAX_FESTIVAL_THEME_OVERRIDE["forced_until"] = None
        else:
            if tid not in VMAX_FESTIVAL_THEMES:
                return jsonify({"st": "error", "msg": "ไม่รู้จัก theme_id", "known": list(VMAX_FESTIVAL_THEMES)}), 400
            hours = float(body.get("hours", 24))
            VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = tid
            VMAX_FESTIVAL_THEME_OVERRIDE["forced_until"] = _scf_time.time() + hours * 3600
        theme = vmax_get_festival_theme()
        try:
            sio.emit("festival_theme_changed", vmax_game_ui_theme_payload(theme))
        except Exception:
            pass
        return jsonify({"st": "ok", "theme": theme, "override": dict(VMAX_FESTIVAL_THEME_OVERRIDE)})

except Exception as _fest_api_exc:
    print("[FESTIVAL THEME] API skip:", repr(_fest_api_exc))


_scf_prev_theme_id = {"v": None}

def vmax_festival_theme_watch_tick():
    tid = vmax_resolve_active_festival_theme_id()
    if tid != _scf_prev_theme_id["v"]:
        _scf_prev_theme_id["v"] = tid
        payload = vmax_game_ui_theme_payload()
        try:
            sio.emit("festival_theme_changed", payload)
        except Exception:
            pass
        return {"changed": True, "theme_id": tid, "payload": payload}
    return {"changed": False, "theme_id": tid}


_lo_tick_ref = globals().get("_lo_tick")
if callable(_lo_tick_ref) and not getattr(_lo_tick_ref, "_fest_theme_hooked", False):
    _prev_lo = _lo_tick_ref
    def _lo_tick(*a, **k):
        out = _prev_lo(*a, **k)
        try:
            vmax_festival_theme_watch_tick()
        except Exception:
            pass
        return out
    _lo_tick._fest_theme_hooked = True
    _lo_tick._scf_fw_hooked = getattr(_prev_lo, "_scf_fw_hooked", False)
    globals()["_lo_tick"] = _lo_tick


def _run_festival_theme_selftest():
    ok = True
    VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = None
    VMAX_SKY_CITY_FESTIVAL["active"] = False
    t = vmax_get_festival_theme()
    ok &= t["theme_id"] == "default"
    ok &= vmax_festival_coin_info()["id"] == "web_activity_coin"
    VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = "sky_city_festival"
    VMAX_FESTIVAL_THEME_OVERRIDE["forced_until"] = _scf_time.time() + 60
    t2 = vmax_get_festival_theme()
    ok &= t2["theme_id"] == "sky_city_festival"
    ok &= t2["coin"]["name_th"] == "เหรียญลอยฟ้า"
    ok &= t2["is_festival"] is True
    css = vmax_festival_theme_css(t2)
    ok &= "--vmax-accent" in css and "#ffd166" in css
    gui = vmax_game_ui_theme_payload(t2)
    ok &= gui["game_ui"].get("firework_enabled") is True
    vmax_festival_coin_grant("theme_u", 40)
    ok &= vmax_festival_coin_balance("theme_u") >= 40
    so, bal = vmax_festival_coin_spend("theme_u", 10)
    ok &= so is True
    VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = "lunar_new_year"
    ok &= vmax_festival_coin_info()["name_th"] == "เหรียญตรุษจีน"
    VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = None
