# เกมที่รองรับ overlay พื้นหลังเทศกาล (ทุกเกมใช้ชุดเดียวกันได้ — ระบุเพิ่มได้)
VMAX_FESTIVAL_BG_GAMES = [
    "vmax", "extraction", "iron_fist", "meadow_town", "sky_city",
    "warzone", "kagatsu", "tdm4v4", "container_blast", "arcane",
    "launcher", "season_hub", "activity",
]

# HTML/JS overlay widget — แปะในหน้าเกมแล้วเรียก vmaxFestivalBgMount()
VMAX_FESTIVAL_BG_OVERLAY_JS = r"""
(function(){
  if (window.VMAXFestivalBg) return;
  const STYLE_ID = 'vmax-fest-bg-style';
  const ROOT_ID = 'vmax-fest-bg-root';
  function ensureStyle(){
    if (document.getElementById(STYLE_ID)) return;
    const s = document.createElement('style');
    s.id = STYLE_ID;
    s.textContent = `
#vmax-fest-bg-root{position:fixed;inset:0;pointer-events:none;z-index:5;overflow:hidden}
#vmax-fest-bg-root .vfb-layer{position:absolute;inset:0}
#vmax-fest-bg-root .vfb-prop{
  position:absolute;transform:translate(-50%,-50%);
  user-select:none;line-height:1;will-change:transform,opacity;
}
@keyframes vfb-float{0%,100%{transform:translate(-50%,-50%) translateY(0)}50%{transform:translate(-50%,-50%) translateY(-12px)}}
@keyframes vfb-drift{0%{transform:translate(-50%,-50%) translateX(0)}50%{transform:translate(-50%,-50%) translateX(18px)}100%{transform:translate(-50%,-50%) translateX(0)}}
@keyframes vfb-pulse{0%,100%{opacity:var(--vfb-op,.5);transform:translate(-50%,-50%) scale(1)}50%{opacity:calc(var(--vfb-op,.5)*1.25);transform:translate(-50%,-50%) scale(1.08)}}
@keyframes vfb-sparkle{0%,100%{opacity:.3;transform:translate(-50%,-50%) scale(.9)}50%{opacity:.85;transform:translate(-50%,-50%) scale(1.15)}}
.vfb-anim-float{animation:vfb-float 4.5s ease-in-out infinite}
.vfb-anim-drift{animation:vfb-drift 7s ease-in-out infinite}
.vfb-anim-pulse{animation:vfb-pulse 3s ease-in-out infinite}
.vfb-anim-sparkle{animation:vfb-sparkle 2.2s ease-in-out infinite}
`;
    document.head.appendChild(s);
  }
  function clear(){
    const r = document.getElementById(ROOT_ID);
    if (r) r.remove();
  }
  function render(props){
    ensureStyle();
    clear();
    if (!props || !props.length) return;
    const root = document.createElement('div');
    root.id = ROOT_ID;
    const layers = {back:1, mid:2, front:3};
    ['back','mid','front'].forEach(L => {
      const box = document.createElement('div');
      box.className = 'vfb-layer';
      box.style.zIndex = layers[L];
      props.filter(p => (p.layer||'mid') === L).forEach(p => {
        const el = document.createElement('div');
        el.className = 'vfb-prop vfb-anim-' + (p.anim||'none');
        el.textContent = p.emoji || p.icon || '•';
        el.style.left = ((p.x||0.5)*100) + '%';
        el.style.top = ((p.y||0.5)*100) + '%';
        el.style.fontSize = ((p.scale||1)*28) + 'px';
        el.style.opacity = p.opacity != null ? p.opacity : 0.5;
        el.style.setProperty('--vfb-op', p.opacity != null ? p.opacity : 0.5);
        if (p.anim === 'none') el.style.animation = 'none';
        box.appendChild(el);
      });
      root.appendChild(box);
    });
    document.body.appendChild(root);
  }
  async function mount(gameId){
    try {
      const q = gameId ? ('?game_id=' + encodeURIComponent(gameId)) : '';
      const r = await fetch('/api/festival/background' + q);
      const d = await r.json();
      if (d && d.st === 'ok') render(d.props || []);
      else clear();
    } catch(e){ console.warn('[fest-bg]', e); }
  }
  window.VMAXFestivalBg = { mount, clear, render };
  // auto-mount
  if (document.readyState === 'loading')
    document.addEventListener('DOMContentLoaded', () => mount(window.VMAX_GAME_ID || window.VMAX_KEYBOARD_SOURCE));
  else
    setTimeout(() => mount(window.VMAX_GAME_ID || window.VMAX_KEYBOARD_SOURCE), 400);
  setInterval(() => mount(window.VMAX_GAME_ID || window.VMAX_KEYBOARD_SOURCE), 60000);
  try {
    const s = window.sio || window.socket;
    if (s && s.on) s.on('festival_theme_changed', () => mount(window.VMAX_GAME_ID || window.VMAX_KEYBOARD_SOURCE));
  } catch(_){}
})();
"""


def vmax_festival_background_props(theme_id=None, game_id=None):
    """คืนรายการ props ตกแต่งพื้นหลังตามเทศกาล (ใช้ได้ทุกเกม)"""
    tid = theme_id or vmax_resolve_active_festival_theme_id()
    props = list(VMAX_FESTIVAL_BACKGROUND_PROPS.get(tid) or [])
    # เกมที่ไม่รองรับก็ยังได้ props ว่างถ้า default
    if game_id and str(game_id) not in VMAX_FESTIVAL_BG_GAMES and tid != "default":
        # ยังอนุญาตทุกเกม — แค่ tag ไว้
        pass
    return {
        "theme_id": tid,
        "game_id": game_id,
        "is_festival": tid != "default",
        "props": props,
        "count": len(props),
    }


def vmax_festival_keyboard_theme(theme_id=None):
    """สีคีย์บอร์ดตามเทศกาล"""
    theme = vmax_get_festival_theme(theme_id)
    kb = (theme.get("game_ui") or {}).get("keyboard") or {}
    if not kb and theme.get("theme_id") != "default":
        kb = {
            "bg": theme.get("bg2") or theme.get("bg"),
            "fg": theme.get("accent"),
            "border": theme.get("accent2") or theme.get("accent"),
            "key_bg": theme.get("card"),
            "key_fg": theme.get("text"),
            "label": ((theme.get("icon") or "") + " " + (theme.get("name_th") or "")).strip(),
        }
    return {
        "theme_id": theme.get("theme_id"),
        "is_festival": theme.get("is_festival", False),
        "keyboard": kb,
        "name_th": theme.get("name_th"),
        "icon": theme.get("icon"),
    }


# ลงทะเบียน festival themes เข้า KEYBOARD_CUSTOM_THEMES ให้ API เดิมเห็น
try:
    for _tid, _th in VMAX_FESTIVAL_THEMES.items():
        if _tid == "default":
            continue
        kb = (_th.get("game_ui") or {}).get("keyboard") or {}
        if not kb:
            continue
        KEYBOARD_CUSTOM_THEMES[_tid] = {
            "id": _tid,
            "name": kb.get("label") or _th.get("name_th") or _tid,
            "colors": {
                "bg": kb.get("bg", _th.get("bg2")),
                "fg": kb.get("fg", _th.get("accent")),
                "border": kb.get("border", _th.get("accent2")),
            },
            "festival": True,
        }
except Exception as _kb_reg_exc:
    print("[FESTIVAL KB] register skip:", repr(_kb_reg_exc))


try:
    @app.route("/api/festival/background", methods=["GET"])
    def api_festival_background():
        game_id = request.args.get("game_id") or request.args.get("source")
        data = vmax_festival_background_props(game_id=game_id)
        return jsonify({"st": "ok", **data})

    @app.route("/api/festival/keyboard", methods=["GET"])
    def api_festival_keyboard():
        return jsonify({"st": "ok", **vmax_festival_keyboard_theme()})

    @app.route("/widgets/festival-bg.js", methods=["GET"])
    def api_festival_bg_js():
        from flask import Response as _JsResp
        return _JsResp(VMAX_FESTIVAL_BG_OVERLAY_JS, mimetype="application/javascript; charset=utf-8")

    @app.route("/api/festival/background/admin/set", methods=["POST"])
    def api_festival_background_admin_set():
        """เพิ่ม/แทน props ของธีม: body {theme_id, props: [...]}"""
        try:
            if callable(globals().get("vmax_admin_require")):
                vmax_admin_require("festival_bg_admin")
        except Exception:
            pass
        body = request.get_json(silent=True) or {}
        tid = body.get("theme_id")
        props = body.get("props")
        if not tid or not isinstance(props, list):
            return jsonify({"st": "error", "msg": "ต้องมี theme_id และ props[]"}), 400
        VMAX_FESTIVAL_BACKGROUND_PROPS[tid] = props
        return jsonify({"st": "ok", "theme_id": tid, "count": len(props)})

except Exception as _fbg_exc:
    print("[FESTIVAL BG] routes skip:", repr(_fbg_exc))


# รวม keyboard + background เข้า game-ui payload
_orig_game_ui_payload = vmax_game_ui_theme_payload

def vmax_game_ui_theme_payload(theme=None):
    base = _orig_game_ui_payload(theme)
    tid = base.get("theme_id")
    base["keyboard"] = vmax_festival_keyboard_theme(tid).get("keyboard") or {}
    base["background_props"] = vmax_festival_background_props(tid).get("props") or []
    return base


def _run_festival_kb_bg_selftest():
    ok = True
    VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = "sky_city_festival"
    VMAX_FESTIVAL_THEME_OVERRIDE["forced_until"] = _scf_time.time() + 60
    kb = vmax_festival_keyboard_theme()
    ok &= kb["is_festival"] is True
    ok &= bool(kb.get("keyboard", {}).get("fg"))
    bg = vmax_festival_background_props()
    ok &= bg["count"] >= 5
    ok &= any(p.get("emoji") == "🏮" for p in bg["props"])
    gui = vmax_game_ui_theme_payload()
    ok &= "keyboard" in gui and "background_props" in gui
    ok &= len(gui["background_props"]) >= 5
    # halloween
    VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = "halloween"
    bg2 = vmax_festival_background_props()
    ok &= any(p.get("emoji") == "🎃" for p in bg2["props"])
    VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = None
    VMAX_FESTIVAL_THEME_OVERRIDE["forced_until"] = None
    bg0 = vmax_festival_background_props()
    ok &= bg0["count"] == 0
    print("FESTIVAL KB+BG SELFTEST:", "OK" if ok else "FAILED")
    return ok


try:
    VMAX_MODULES["festival_keyboard_background"] = {
        "name": "Festival Keyboard + Game Background Props",
        "name_th": "คีย์บอร์ดเทศกาล + ของตกแต่งพื้นหลังเกม",
        "version": "1.0.0",
        "routes": [
            "/api/festival/background",
            "/api/festival/keyboard",
            "/widgets/festival-bg.js",
            "/api/festival/background/admin/set",
        ],
        "games": list(VMAX_FESTIVAL_BG_GAMES),
        "themes_with_props": [k for k, v in VMAX_FESTIVAL_BACKGROUND_PROPS.items() if v],
    }
except Exception:
    pass

print("[VMAX] Festival Keyboard + Background Props loaded.",
      "themes_with_props=", [k for k, v in VMAX_FESTIVAL_BACKGROUND_PROPS.items() if v])


