def _run_device_gate_selftest():
    ok = True
    # good report
    good = {
        "ua": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/120.0.0.0 Safari/537.36",
        "platform": "Win32",
        "cores": 8,
        "memory_gb": 8,
        "screen_w": 1920,
        "screen_h": 1080,
        "color_depth": 24,
        "device_pixel_ratio": 1,
        "webgl": True,
        "canvas": True,
        "local_storage": True,
        "webdriver": False,
        "headless": False,
        "client_ts": _dg_time.time(),
    }
    r1 = vmax_device_gate_evaluate(good)
    ok &= r1["ok"] is True
    tok, exp = vmax_device_gate_issue_token("dev-test", r1, good)
    vok, vmsg = vmax_device_gate_verify_token(tok, device_id="dev-test")
    ok &= vok is True
    # soft fail: สเปคต่ำ แต่ไม่ใช่บอท → อนุญาต compat
    low = dict(good)
    low["cores"] = 1
    low["memory_gb"] = 0.5
    low["screen_w"] = 400
    low["screen_h"] = 300
    r_soft = vmax_device_gate_evaluate(low)
    ok &= r_soft["ok"] is False
    ok &= r_soft.get("soft_fail") is True
    ok &= r_soft.get("allow_compat") is True
    tok_c, _ = vmax_device_gate_issue_token("dev-low", r_soft, low, mode="compat")
    vok_c, msg_c = vmax_device_gate_verify_token(tok_c, device_id="dev-low")
    ok &= vok_c is True and msg_c == "ok_compat"
    ok &= vmax_device_gate_token_mode(tok_c) == "compat"
    # bad: headless bot → hard block
    bad = dict(good)
    bad["ua"] = "HeadlessChrome/120"
    bad["webdriver"] = True
    bad["headless"] = True
    bad["cores"] = 1
    r2 = vmax_device_gate_evaluate(bad)
    ok &= r2["ok"] is False
    ok &= r2.get("hard_block") is True
    ok &= r2.get("allow_compat") is False
    # bad token
    vok2, _ = vmax_device_gate_verify_token("nope.invalid", device_id="dev-test")
    ok &= vok2 is False
    print("DEVICE GATE SELFTEST:", "OK" if ok else "FAILED")
    return ok


