# override มือ: {"game": 0.5, ...} หรือ None
VMAX_FESTIVAL_PRICE_OVERRIDE = None


def vmax_festival_price_mult(category="general", theme_id=None):
    """ตัวคูณราคาตามเทศกาล + หมวดหมู่"""
    cat = str(category or "general").lower().strip()
    aliases = {
        "games": "game", "gameshop": "game", "launcher": "game",
        "มังงะ": "manga", "comic": "manga", "comics": "manga",
        "activity": "web_activity", "coin": "web_activity",
        "sky": "sky_city", "shop": "store",
        "social_app": "social", "subscription": "social", "สมาชิก": "social",
        "ai_chat": "ai", "ai_credit": "ai", "llm": "ai",
        "game_topup": "topup", "เติมเกม": "topup", "เติมเงิน": "topup",
    }
    cat = aliases.get(cat, cat)
    # override มือมาก่อน
    ov = VMAX_FESTIVAL_PRICE_OVERRIDE
    if isinstance(ov, dict) and cat in ov:
        try:
            return float(ov[cat])
        except Exception:
            pass
    # ธีมปัจจุบัน
    try:
        tid = theme_id or vmax_resolve_active_festival_theme_id()
    except Exception:
        tid = "default"
    table = VMAX_FESTIVAL_PRICE_DEFAULTS.get(tid) or VMAX_FESTIVAL_PRICE_DEFAULTS["default"]
    try:
        mult = float(table.get(cat, table.get("general", 1.0)))
    except Exception:
        mult = 1.0
    # ผูกกับ sky city festival price_mult ถ้ามีและเป็นหมวด sky_city
    try:
        if cat == "sky_city" and callable(globals().get("vmax_sky_city_festival_active")):
            if vmax_sky_city_festival_active():
                mult = min(mult, float(VMAX_SKY_CITY_FESTIVAL.get("price_mult", mult)))
    except Exception:
        pass
    return max(0.05, min(1.0, mult))


def vmax_festival_price_apply(base_price, category="general", theme_id=None):
    """คืน {base, final, mult, discounted, category, theme_id}"""
    try:
        base = float(base_price or 0)
    except Exception:
        base = 0.0
    mult = vmax_festival_price_mult(category, theme_id=theme_id)
    if base <= 0:
        final = 0
    elif mult >= 0.999:
        final = int(round(base)) if float(base).is_integer() else round(base, 2)
    else:
        final = max(1, int(round(base * mult))) if base >= 1 else round(base * mult, 2)
    try:
        tid = theme_id or vmax_resolve_active_festival_theme_id()
    except Exception:
        tid = "default"
    return {
        "base": base if not float(base).is_integer() else int(base),
        "final": final,
        "mult": round(mult, 4),
        "discounted": mult < 0.999,
        "category": category,
        "theme_id": tid,
        "save_pct": int(round((1.0 - mult) * 100)) if mult < 0.999 else 0,
    }


def vmax_festival_price_catalog(category=None):
    """รายการราคาเกมตัวอย่างหลังลดเทศกาล"""
    out = []
    for gid, info in VMAX_FESTIVAL_GAME_CATALOG.items():
        cat = info.get("category") or "game"
        if category and cat != category:
            continue
        priced = vmax_festival_price_apply(info.get("price", 0), cat)
        out.append({
            "id": gid,
            "name_th": info.get("name_th"),
            "currency": info.get("currency", "THB"),
            "category": cat,
            **priced,
        })
    return out


# ให้ sky city price_mult ใช้ตัวคูณเทศกาลรวมได้ (ถ้ายังไม่ active sky festival แยก)
_orig_sky_price_mult = globals().get("vmax_sky_city_price_mult")
if callable(_orig_sky_price_mult) and not getattr(_orig_sky_price_mult, "_fest_price_wrapped", False):
    def vmax_sky_city_price_mult():
        try:
            if vmax_sky_city_festival_active():
                return _orig_sky_price_mult()
        except Exception:
            pass
        return vmax_festival_price_mult("sky_city")
    vmax_sky_city_price_mult._fest_price_wrapped = True
    globals()["vmax_sky_city_price_mult"] = vmax_sky_city_price_mult


