def _run_festival_pricing_selftest():
    ok = True
    # default = ไม่ลด
    try:
        VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = None
    except Exception:
        pass
    p0 = vmax_festival_price_apply(100, "game")
    ok &= p0["final"] == 100 and p0["discounted"] is False
    # sky festival = ครึ่ง
    try:
        VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = "sky_city_festival"
        VMAX_FESTIVAL_THEME_OVERRIDE["forced_until"] = _scf_time.time() + 60
    except Exception:
        pass
    p1 = vmax_festival_price_apply(100, "game")
    ok &= p1["final"] == 50 and p1["discounted"] is True
    p2 = vmax_festival_price_apply(200, "manga")
    ok &= p2["final"] == 100
    cat = vmax_festival_price_catalog("game")
    ok &= len(cat) >= 1 and all("final" in x for x in cat)
    # override
    global VMAX_FESTIVAL_PRICE_OVERRIDE
    VMAX_FESTIVAL_PRICE_OVERRIDE = {"manga": 0.25}
    p3 = vmax_festival_price_apply(100, "manga")
    ok &= p3["final"] == 25
    VMAX_FESTIVAL_PRICE_OVERRIDE = None
    try:
        VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = None
        VMAX_FESTIVAL_THEME_OVERRIDE["forced_until"] = None
    except Exception:
        pass
    print("FESTIVAL PRICING SELFTEST:", "OK" if ok else "FAILED")
    return ok


