VMAX_AI_UNIT_COST = float(__import__("os").environ.get("VMAX_AI_UNIT_COST", "1"))  # 1 credit / message
# อนุญาตเครดิตเริ่มต้น 0 = ไม่ฟรีจริง
VMAX_AI_STARTING_CREDITS = int(__import__("os").environ.get("VMAX_AI_STARTING_CREDITS", "0"))

# state
VMAX_SOCIAL_SUB_STATE = {}   # uid -> {plan_id, expires_at, features, ai_credits_monthly}
VMAX_AI_CREDIT_BAL = {}      # uid -> int credits
VMAX_AI_USAGE_LOG = []       # optional light log


def _vmax_paid_now():
    import time as _t
    return _t.time()


def vmax_social_plan_price(plan_id):
    plan = VMAX_SOCIAL_SUB_PLANS.get(plan_id)
    if not plan:
        return None
    return vmax_festival_price_apply(plan["price"], "social")


def vmax_ai_pack_price(pack_id):
    pack = VMAX_AI_CREDIT_PACKS.get(pack_id)
    if not pack:
        return None
    return vmax_festival_price_apply(pack["price"], "ai")


def vmax_ai_unit_cost_now():
    """ต้นทุนเครดิตต่อ 1 ครั้งใช้ AI (หลังลดเทศกาล — อย่างน้อย 1 ถ้า base >= 1)"""
    base = float(VMAX_AI_UNIT_COST)
    priced = vmax_festival_price_apply(base, "ai")
    # เครดิตเป็นจำนวนเต็ม
    cost = priced["final"]
    if base >= 1:
        cost = max(1, int(round(float(cost))))
    else:
        cost = max(0, int(round(float(cost))))
    return {
        "base": base,
        "cost": cost,
        "mult": priced["mult"],
        "discounted": priced["discounted"],
        "theme_id": priced.get("theme_id"),
    }


def vmax_ai_credits_balance(uid):
    uid = str(uid or "anon")
    if uid not in VMAX_AI_CREDIT_BAL:
        VMAX_AI_CREDIT_BAL[uid] = int(VMAX_AI_STARTING_CREDITS)
    return int(VMAX_AI_CREDIT_BAL[uid])


def vmax_ai_credits_grant(uid, amount):
    uid = str(uid or "anon")
    VMAX_AI_CREDIT_BAL[uid] = vmax_ai_credits_balance(uid) + int(amount)
    return VMAX_AI_CREDIT_BAL[uid]


def vmax_social_sub_active(uid):
    uid = str(uid or "anon")
    st = VMAX_SOCIAL_SUB_STATE.get(uid)
    if not st:
        return False
    exp = float(st.get("expires_at") or 0)
    if exp and exp < _vmax_paid_now():
        return False
    return st.get("plan_id") not in (None, "social_free")


def vmax_ai_usage_charge(uid, units=1, feature="ai_chat"):
    """
    หักเครดิต AI ก่อนใช้งาน — ไม่ฟรี
    คืน {ok, spent, balance, ...} หรือ {ok: False, msg}
    สมาชิก social ที่มี ai_credits_monthly ยังใช้เครดิตจาก balance ปกติ
    (ตอน subscribe จะ grant เครดิตเข้า balance)
    """
    uid = str(uid or "anon")
    unit_info = vmax_ai_unit_cost_now()
    need = int(unit_info["cost"]) * max(1, int(units))
    bal = vmax_ai_credits_balance(uid)
    if bal < need:
        return {
            "ok": False,
            "msg": "เครดิต AI ไม่พอ (ต้องการ %s มี %s) — ซื้อแพ็ก AI หรือสมัคร Social ที่มีเครดิต" % (need, bal),
            "balance": bal,
            "pricing": {
                "unit_cost": unit_info,
                "packs": [
                    {"pack_id": k, **vmax_ai_pack_price(k), "credits": v["credits"], "name_th": v["name_th"]}
                    for k, v in VMAX_AI_CREDIT_PACKS.items()
                ],
                "social_plans": [
                    {"plan_id": k, **vmax_social_plan_price(k), "name_th": v["name_th"], "ai_credits_monthly": v.get("ai_credits_monthly", 0)}
                    for k, v in VMAX_SOCIAL_SUB_PLANS.items() if v.get("price", 0) > 0
                ],
            },
        }
    VMAX_AI_CREDIT_BAL[uid] = bal - need
    try:
        VMAX_AI_USAGE_LOG.append({
            "uid": uid, "feature": feature, "spent": need,
            "ts": _vmax_paid_now(), "mult": unit_info["mult"],
        })
        if len(VMAX_AI_USAGE_LOG) > 500:
            del VMAX_AI_USAGE_LOG[:-500]
    except Exception:
        pass
    return {
        "ok": True,
        "spent": need,
        "balance": VMAX_AI_CREDIT_BAL[uid],
        "festival_discount": unit_info["discounted"],
        "price_mult": unit_info["mult"],
        "unit_cost": unit_info,
    }


# pending wallet charges สำหรับ social / ai / topup
VMAX_PAID_PENDING = {}  # charge_id -> {kind, uid, item_id, amount, currency, meta}


def vmax_paid_wallet_ready():
    """True ถ้าตั้งค่า wallet แล้วและเปิด auto charge"""
    try:
        base = globals().get("SITE_WALLET_API_BASE") or ""
        allow = bool(globals().get("SITE_WALLET_ALLOW_AUTO_CHARGE"))
        return bool(base) and allow and callable(globals().get("_wallet_call_auto"))
    except Exception:
        return False


def vmax_paid_start_charge(uid, amount, currency, ref, kind, item_id, meta=None):
    """
    เริ่มตัดเงินจริงผ่าน wallet ของเว็บไซต์
    คืน {ok, payment_pending, charge_id} หรือ {ok, mock, ...} ถ้ายังไม่ต่อ wallet
    หรือ {ok: False, msg}
    """
    uid = str(uid or "anon")
    amount = float(amount)
    currency = currency or "THB"
    if amount <= 0:
        return {"ok": True, "free": True, "charge_id": None}
    if not vmax_paid_wallet_ready():
        # ยังไม่ต่อ wallet จริง — โหมด dev mock (ระบุชัด)
        return {
            "ok": True,
            "mock": True,
            "charge_id": None,
            "msg": "wallet ยังไม่พร้อม (ตั้ง SITE_WALLET_API_BASE + SITE_WALLET_ALLOW_AUTO_CHARGE=1) — ใช้ mock สำเร็จ",
        }
    charge = _wallet_call_auto("charge", json={
        "uid": uid,
        "amount": amount,
        "currency": currency,
        "ref": ref,
    })
    if charge.get("st") != "ok" and charge.get("status") not in ("ok", "pending"):
        return {"ok": False, "msg": charge.get("msg") or "เรียก wallet charge ไม่สำเร็จ", "wallet": charge}
    charge_id = charge.get("charge_id")
    if not charge_id:
        return {"ok": False, "msg": "wallet ไม่ได้ส่ง charge_id", "wallet": charge}
    VMAX_PAID_PENDING[charge_id] = {
        "kind": kind,
        "uid": uid,
        "item_id": item_id,
        "amount": amount,
        "currency": currency,
        "meta": meta or {},
        "ref": ref,
    }
    return {
        "ok": True,
        "payment_pending": True,
        "charge_id": charge_id,
        "amount": amount,
        "currency": currency,
        "msg": "สร้างรายการตัดเงินที่ wallet แล้ว — ยืนยันที่ /api/paid/confirm",
    }


def vmax_paid_confirm_and_fulfill(charge_id):
    """ยืนยันกับ wallet แล้วปลดล็อกของ + นำเงินเข้าแอปธนาคาร"""
    pending = VMAX_PAID_PENDING.get(charge_id)
    if not pending:
        return {"ok": False, "msg": "ไม่พบ charge_id หรือยืนยันไปแล้ว"}
    if vmax_paid_wallet_ready():
        confirm = _wallet_call_auto("confirm", json={"charge_id": charge_id})
        if confirm.get("st") != "ok" or confirm.get("status") not in ("ok", "success", "confirmed", None):
            if confirm.get("status") in ("failed", "error", "cancelled"):
                return {"ok": False, "msg": "wallet ยังไม่ยืนยันการตัดเงิน", "wallet": confirm}
            if confirm.get("st") != "ok":
                return {"ok": False, "msg": "wallet ยังไม่ยืนยันการตัดเงิน", "wallet": confirm}
    kind = pending["kind"]
    uid = pending["uid"]
    item_id = pending["item_id"]
    amount = float(pending.get("amount") or 0)
    currency = pending.get("currency") or "THB"
    result = {"ok": True, "kind": kind, "uid": uid, "item_id": item_id}
    if kind == "social":
        result.update(_vmax_social_fulfill(uid, item_id, amount, pending.get("meta") or {}))
    elif kind == "ai_pack":
        result.update(_vmax_ai_pack_fulfill(uid, item_id, amount))
    elif kind == "topup":
        result.update(_vmax_topup_fulfill(uid, item_id, pending.get("meta") or {}))
    else:
        return {"ok": False, "msg": "unknown kind"}
    # นำเงินเข้าแอปธนาคาร (รายได้แพลตฟอร์ม + บันทึกบัญชีผู้ใช้)
    try:
        if callable(globals().get("vmax_bank_on_purchase")) and amount > 0:
            bank_rec = vmax_bank_on_purchase(
                uid=uid, amount=amount, currency=currency,
                kind=kind, item_id=item_id, charge_id=charge_id,
            )
            result["bank"] = bank_rec
    except Exception as _bk_exc:
        result["bank_error"] = repr(_bk_exc)
    VMAX_PAID_PENDING.pop(charge_id, None)
    return result


def _vmax_social_fulfill(uid, plan_id, paid_amount, meta=None):
    plan = VMAX_SOCIAL_SUB_PLANS.get(plan_id)
    if not plan:
        return {"ok": False, "msg": "ไม่พบแพ็ก"}
    import time as _t
    days = int(plan.get("days") or 0)
    expires = (_t.time() + days * 86400) if days > 0 else 0
    priced_mult = (meta or {}).get("price_mult", 1.0)
    VMAX_SOCIAL_SUB_STATE[uid] = {
        "plan_id": plan_id,
        "expires_at": expires,
        "features": list(plan.get("features") or []),
        "ai_credits_monthly": int(plan.get("ai_credits_monthly") or 0),
        "paid_amount": paid_amount,
        "price_mult": priced_mult,
    }
    granted = int(plan.get("ai_credits_monthly") or 0)
    if granted > 0:
        vmax_ai_credits_grant(uid, granted)
    return {
        "ok": True,
        "subscription": VMAX_SOCIAL_SUB_STATE[uid],
        "ai_credits_granted": granted,
        "ai_balance": vmax_ai_credits_balance(uid),
    }


def _vmax_ai_pack_fulfill(uid, pack_id, paid_amount):
    pack = VMAX_AI_CREDIT_PACKS.get(pack_id)
    if not pack:
        return {"ok": False, "msg": "ไม่พบแพ็ก"}
    vmax_ai_credits_grant(uid, int(pack["credits"]))
    return {
        "ok": True,
        "pack_id": pack_id,
        "credits_added": pack["credits"],
        "balance": vmax_ai_credits_balance(uid),
        "paid_amount": paid_amount,
    }


def vmax_social_subscribe(uid, plan_id, pay_confirmed=False):
    """สมัครแพ็ก social — ตัดเงิน wallet จริง (หรือ mock ถ้ายังไม่ต่อ)"""
    uid = str(uid or "anon")
    plan = VMAX_SOCIAL_SUB_PLANS.get(plan_id)
    if not plan:
        return {"ok": False, "msg": "ไม่พบแพ็ก"}
    priced = vmax_social_plan_price(plan_id)
    amount = float(priced["final"]) if priced else float(plan["price"])
    if amount <= 0:
        return _vmax_social_fulfill(uid, plan_id, 0, {"price_mult": 1.0})
    started = vmax_paid_start_charge(
        uid, amount, plan.get("currency", "THB"),
        ref="social:%s" % plan_id, kind="social", item_id=plan_id,
        meta={"price_mult": priced.get("mult", 1.0)},
    )
    if not started.get("ok"):
        return started
    if started.get("payment_pending"):
        return {
            "ok": True,
            "payment_pending": True,
            "charge_id": started["charge_id"],
            "pricing": priced,
            "msg": started.get("msg"),
        }
    # mock path — fulfill ทันที
    if started.get("mock") or started.get("free"):
        out = _vmax_social_fulfill(uid, plan_id, amount, {"price_mult": priced.get("mult", 1.0)})
        out["pricing"] = priced
        out["mock"] = bool(started.get("mock"))
        try:
            if amount > 0 and callable(globals().get("vmax_bank_on_purchase")):
                out["bank"] = vmax_bank_on_purchase(
                    uid=uid, amount=amount, currency=plan.get("currency", "THB"),
                    kind="social", item_id=plan_id, charge_id=None, mock=True)
        except Exception:
            pass
        return out
    return started


