    @app.route("/api/ai/credits/buy", methods=["POST"])
    def api_ai_credits_buy():
        body = request.get_json(silent=True) or {}
        uid = body.get("uid") or getattr(request, "vmax_uid", None) or "anon"
        pack_id = body.get("pack_id")
        pay_method = (body.get("payment_method") or body.get("pay_method") or "wallet").lower()
        channel = body.get("channel") or "seven_eleven"
        if pay_method in ("billpay", "bill", "7eleven", "counter", "counter_service"):
            if channel in ("counter", "counter_service"):
                channel = "counter_service"
            pack = VMAX_AI_CREDIT_PACKS.get(pack_id)
            if not pack:
                return jsonify({"st": "error", "msg": "ไม่พบแพ็ก"}), 400
            priced = vmax_ai_pack_price(pack_id)
            amount = float(priced["final"]) if priced else float(pack["price"])
            if not callable(globals().get("vmax_billpay_create")):
                return jsonify({"st": "error", "msg": "ระบบ billpay ยังไม่พร้อม"}), 503
            bp = vmax_billpay_create(
                uid=uid, amount_thb=amount, channel=channel,
                purpose="ai_pack", item_id=pack_id, meta={"pricing": priced},
            )
            if not bp.get("ok"):
                return jsonify({"st": "error", **bp}), 400
            return jsonify({"st": "billpay_pending", "payment_method": "billpay", **bp})
        result = vmax_ai_buy_pack(uid, pack_id)
        if result.get("payment_pending"):
            return jsonify({"st": "payment_pending", **result})
        code = 200 if result.get("ok") else 400
        return jsonify({"st": "ok" if result.get("ok") else "error", **result}), code

