    @app.route("/api/topup/purchase", methods=["POST"])
    def api_topup_purchase():
        body = request.get_json(silent=True) or {}
        uid = body.get("uid") or getattr(request, "vmax_uid", None) or "anon"
        pack_id = body.get("pack_id") or "topup_35"
        pay_method = (body.get("payment_method") or body.get("pay_method") or "wallet").lower()
        channel = body.get("channel") or "seven_eleven"
        if pay_method in ("billpay", "bill", "7eleven", "counter", "counter_service"):
            if channel in ("counter", "counter_service"):
                channel = "counter_service"
            elif channel not in ("seven_eleven", "lotus", "counter_service"):
                channel = "seven_eleven"
            if not callable(globals().get("vmax_billpay_create_for_topup")):
                return jsonify({"st": "error", "msg": "ระบบ billpay ยังไม่พร้อม"}), 503
            bp = vmax_billpay_create_for_topup(uid, pack_id=pack_id, channel=channel)
            if not bp.get("ok"):
                return jsonify({"st": "error", **bp}), 400
            return jsonify({"st": "billpay_pending", "payment_method": "billpay", **bp})
        if pay_method in ("promptpay", "truemoney", "omise", "qr"):
            method = "truemoney" if pay_method == "truemoney" else "promptpay"
            if not callable(globals().get("vmax_omise_create_source_charge")):
                return jsonify({"st": "error", "msg": "Omise ยังไม่พร้อม"}), 503
            priced = vmax_topup_pack_price(pack_id) if callable(globals().get("vmax_topup_pack_price")) else None
            amount = float(priced["final"]) if priced else float((VMAX_GAME_TOPUP_PACKS.get(pack_id) or {}).get("price") or 35)
            oc = vmax_omise_create_source_charge(
                uid=uid, amount_thb=amount, method=method,
                description="topup:%s:%s" % (pack_id, uid),
                meta={"purpose": "topup", "item_id": pack_id},
            )
            if not oc.get("ok"):
                return jsonify({"st": "error", **oc}), 400
            return jsonify({"st": "omise_pending", "payment_method": method, **oc})
        result = vmax_game_topup_purchase(uid, pack_id)
        if result.get("payment_pending"):
            return jsonify({"st": "payment_pending", **result})
        code = 200 if result.get("ok") else 400
        return jsonify({"st": "ok" if result.get("ok") else "error", **result}), code

