def _run_social_ai_paid_selftest():
    ok = True
    uid = "paid_test_u"
    VMAX_AI_CREDIT_BAL[uid] = 0
    r0 = vmax_ai_usage_charge(uid, 1)
    ok &= r0["ok"] is False
    buy = vmax_ai_buy_pack(uid, "ai_pack_50")
    ok &= buy.get("ok") is True
    if buy.get("mock") or not buy.get("payment_pending"):
        ok &= buy.get("balance", 0) == 50 or buy.get("credits_added") == 50
    r1 = vmax_ai_usage_charge(uid, 1)
    if VMAX_AI_CREDIT_BAL.get(uid, 0) > 0:
        ok &= r1["ok"] is True
    uid2 = "social_u"
    VMAX_AI_CREDIT_BAL[uid2] = 0
    sub = vmax_social_subscribe(uid2, "social_plus")
    ok &= sub.get("ok") is True
    # topup 35 -> ~20 + bonus
    try:
        VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = "sky_city_festival"
        VMAX_FESTIVAL_THEME_OVERRIDE["forced_until"] = _vmax_paid_now() + 60
    except Exception:
        pass
    tp = vmax_topup_pack_price("topup_35")
    ok &= tp is not None and tp["base"] == 35
    ok &= tp["final"] <= 22 and tp["final"] >= 18  # ประมาณ 20
    ok &= tp["discounted"] is True
    top = vmax_game_topup_purchase("top_u", "topup_35")
    ok &= top.get("ok") is True
    if top.get("mock") or not top.get("payment_pending"):
        ok &= top.get("credits_granted", 0) >= 350
        ok &= top.get("festival_bonus_credits", 0) >= 50
    p = vmax_social_plan_price("social_plus")
    ok &= p["discounted"] is True and p["final"] < p["base"]
    try:
        VMAX_FESTIVAL_THEME_OVERRIDE["theme_id"] = None
        VMAX_FESTIVAL_THEME_OVERRIDE["forced_until"] = None
    except Exception:
        pass
    print("SOCIAL+AI PAID SELFTEST:", "OK" if ok else "FAILED")
    return ok


