# ==========================================================================
# [ VMAX BANK APP — แอปคล้ายธนาคาร รับเงินจากการซื้อ ]
# -------------------------------------------------------------------------
# ของเดิมที่มีอยู่แล้ว:
#   - banknote exchange (แลก credits → ธนบัตรในเกม)
#   - WALLET / credits กระเป๋ากลาง
#   - SITE_WALLET (wallet เว็บภายนอก)
# โมดูลนี้ = "บัญชีธนาคารในแพลตฟอร์ม":
#   - บัญชีผู้ใช้ (ดูยอด / ประวัติ)
#   - บัญชีรายได้แพลตฟอร์ม (เงินจากการซื้อ social / AI / topup เข้าที่นี่)
#   - เชื่อมกับ banknote: โอน credits ไปแลกธนบัตรได้
# เมื่อมีคนซื้อ → vmax_bank_on_purchase() นำเงินเข้าธนาคารอัตโนมัติ
# ==========================================================================
import json as _bank_json
import os as _bank_os
import threading as _bank_thr
import time as _bank_time
import uuid as _bank_uuid

VMAX_BANK_DATA_DIR = _bank_os.environ.get("VMAX_BANK_DATA_DIR", "vmax_bank_data")
_bank_os.makedirs(VMAX_BANK_DATA_DIR, exist_ok=True)
_VMAX_BANK_LOCK = _bank_thr.RLock()

# in-memory + file-backed
VMAX_BANK_ACCOUNTS = {}   # uid -> {balance_thb, currency, ledger:[]}
VMAX_BANK_PLATFORM = {    # บัญชีกลางแพลตฟอร์ม (รายได้)
    "account_id": "platform_treasury",
    "balance_thb": 0.0,
    "currency": "THB",
    "ledger": [],
}


def _bank_acct_path(uid):
    safe = "".join(c if c.isalnum() or c in "-_" else "_" for c in str(uid))[:80]
    return _bank_os.path.join(VMAX_BANK_DATA_DIR, "acct_%s.json" % safe)


def _bank_platform_path():
    return _bank_os.path.join(VMAX_BANK_DATA_DIR, "platform_treasury.json")


def _bank_load_account(uid):
    uid = str(uid or "anon")
    with _VMAX_BANK_LOCK:
        if uid in VMAX_BANK_ACCOUNTS:
            return VMAX_BANK_ACCOUNTS[uid]
        acct = {"uid": uid, "balance_thb": 0.0, "currency": "THB", "ledger": [], "updated_at": _bank_time.time()}
        path = _bank_acct_path(uid)
        try:
            if _bank_os.path.exists(path):
                with open(path, "r", encoding="utf-8") as f:
                    raw = _bank_json.load(f)
                acct["balance_thb"] = float(raw.get("balance_thb") or 0)
                acct["ledger"] = list(raw.get("ledger") or [])[-200:]
                acct["currency"] = raw.get("currency") or "THB"
        except Exception as exc:
            print("[VMAX BANK] load acct fail:", uid, repr(exc))
        VMAX_BANK_ACCOUNTS[uid] = acct
        return acct


def _bank_save_account(uid, acct=None):
    uid = str(uid)
    with _VMAX_BANK_LOCK:
        acct = acct or VMAX_BANK_ACCOUNTS.get(uid) or _bank_load_account(uid)
        acct["ledger"] = list(acct.get("ledger") or [])[-200:]
        acct["updated_at"] = _bank_time.time()
        VMAX_BANK_ACCOUNTS[uid] = acct
        try:
            with open(_bank_acct_path(uid), "w", encoding="utf-8") as f:
                _bank_json.dump(acct, f, ensure_ascii=False, indent=2)
        except Exception as exc:
            print("[VMAX BANK] save acct fail:", uid, repr(exc))


def _bank_load_platform():
    with _VMAX_BANK_LOCK:
        path = _bank_platform_path()
        try:
            if _bank_os.path.exists(path):
                with open(path, "r", encoding="utf-8") as f:
                    raw = _bank_json.load(f)
                VMAX_BANK_PLATFORM["balance_thb"] = float(raw.get("balance_thb") or 0)
                VMAX_BANK_PLATFORM["ledger"] = list(raw.get("ledger") or [])[-500:]
        except Exception as exc:
            print("[VMAX BANK] load platform fail:", repr(exc))
        return VMAX_BANK_PLATFORM


def _bank_save_platform():
    with _VMAX_BANK_LOCK:
        VMAX_BANK_PLATFORM["ledger"] = list(VMAX_BANK_PLATFORM.get("ledger") or [])[-500:]
        try:
            with open(_bank_platform_path(), "w", encoding="utf-8") as f:
                _bank_json.dump(VMAX_BANK_PLATFORM, f, ensure_ascii=False, indent=2)
        except Exception as exc:
            print("[VMAX BANK] save platform fail:", repr(exc))


# โหลด platform ตอน import
try:
    _bank_load_platform()
except Exception:
    pass


def vmax_bank_on_purchase(uid, amount, currency="THB", kind="purchase",
                          item_id=None, charge_id=None, mock=False):
    """
    เมื่อมีคนซื้อสำเร็จ — นำเงินเข้า:
      1) บัญชีรายได้แพลตฟอร์ม (treasury)
      2) บันทึกใน ledger บัญชีผู้ใช้ (ประวัติการใช้จ่าย)
    ไม่ได้เพิ่ม balance ผู้ใช้เป็นเงินสดถอนได้ (เงินจ่ายไปแล้ว) — เป็นใบเสร็จ/ประวัติ
    ยกเว้น kind=topup จะบันทึกว่าเติม credits แล้วเชื่อม banknote ได้
    """
    uid = str(uid or "anon")
    amount = float(amount or 0)
    if amount <= 0:
        return {"ok": False, "msg": "amount ต้อง > 0"}
    currency = currency or "THB"
    tx_id = "tx_" + _bank_uuid.uuid4().hex[:12]
    ts = _bank_time.time()
    entry = {
        "tx_id": tx_id,
        "ts": ts,
        "uid": uid,
        "amount": amount,
        "currency": currency,
        "kind": kind,
        "item_id": item_id,
        "charge_id": charge_id,
        "mock": bool(mock),
        "direction": "in_platform",  # เข้าคลังแพลตฟอร์ม
    }
    with _VMAX_BANK_LOCK:
        plat = _bank_load_platform()
        plat["balance_thb"] = round(float(plat.get("balance_thb") or 0) + amount, 2)
        plat.setdefault("ledger", []).append(dict(entry, account="platform_treasury"))
        _bank_save_platform()

        acct = _bank_load_account(uid)
        user_entry = dict(entry, direction="spent", note="ซื้อ %s/%s — เงินเข้าคลังแพลตฟอร์ม" % (kind, item_id))
        acct.setdefault("ledger", []).append(user_entry)
        # ไม่เพิ่ม balance_thb ของ user (จ่ายออกแล้ว) — เก็บ spent_total
        acct["spent_total"] = round(float(acct.get("spent_total") or 0) + amount, 2)
        _bank_save_account(uid, acct)

    return {
        "ok": True,
        "tx_id": tx_id,
        "platform_balance_thb": VMAX_BANK_PLATFORM["balance_thb"],
        "user_spent_total": acct.get("spent_total"),
        "kind": kind,
        "item_id": item_id,
        "amount": amount,
        "mock": bool(mock),
    }


def vmax_bank_deposit_user(uid, amount, note="deposit", ref=None):
    """ฝากเงินเข้าบัญชีผู้ใช้ (เช่น โอนจากภายนอก / แอดมิน)"""
    uid = str(uid or "anon")
    amount = float(amount or 0)
    if amount <= 0:
        return {"ok": False, "msg": "amount ต้อง > 0"}
    with _VMAX_BANK_LOCK:
        acct = _bank_load_account(uid)
        acct["balance_thb"] = round(float(acct.get("balance_thb") or 0) + amount, 2)
        acct.setdefault("ledger", []).append({
            "tx_id": "dep_" + _bank_uuid.uuid4().hex[:10],
            "ts": _bank_time.time(),
            "direction": "deposit",
            "amount": amount,
            "note": note,
            "ref": ref,
        })
        _bank_save_account(uid, acct)
    return {"ok": True, "balance_thb": acct["balance_thb"]}


def vmax_bank_get(uid):
    acct = _bank_load_account(uid)
    return {
        "uid": acct["uid"],
        "balance_thb": acct.get("balance_thb", 0),
        "spent_total": acct.get("spent_total", 0),
        "currency": acct.get("currency", "THB"),
        "ledger": list(acct.get("ledger") or [])[-50:],
        "updated_at": acct.get("updated_at"),
    }


def vmax_bank_platform_status():
    plat = _bank_load_platform()
    return {
        "account_id": plat.get("account_id"),
        "balance_thb": plat.get("balance_thb", 0),
        "currency": plat.get("currency", "THB"),
        "recent_ledger": list(plat.get("ledger") or [])[-30:],
    }


