    rec = vmax_bank_on_purchase(uid, 20, kind="topup", item_id="topup_35", mock=True)
    ok &= rec.get("ok") is True
    ok &= float(VMAX_BANK_PLATFORM["balance_thb"]) >= before + 20
    acct = vmax_bank_get(uid)
    ok &= float(acct.get("spent_total") or 0) >= 20
    ok &= len(acct.get("ledger") or []) >= 1
    dep = vmax_bank_deposit_user(uid, 5, note="test")
    ok &= dep.get("ok") is True and dep.get("balance_thb", 0) >= 5
    print("VMAX BANK SELFTEST:", "OK" if ok else "FAILED")
    return ok


