# ==========================================================================
# [ VCHAT — แอปคล้าย WeChat ]
# -------------------------------------------------------------------------
# ของเดิมที่มี: เพื่อน (/api/friends/*), แชทเกม+moderation, gallery/moments คร่าวๆ,
#               ธนาคาร, Social subscription
# ยังไม่มีแอปรวมสไตล์ WeChat → โมดูลนี้รวม:
#   1) แชทส่วนตัว (DM) + กลุ่ม
#   2) โมเมนต์ (timeline โพสต์/ไลก์/คอมเมนต์)
#   3) โปรไฟล์ / สถานะ
#   4) โอนเงิน / ซองอั่งเปา ผ่าน VMAX Bank
#   5) หน้า app shell เบา ๆ
# ==========================================================================
import time as _vc_time
import uuid as _vc_uuid
import threading as _vc_thr
import json as _vc_json
import os as _vc_os

VCHAT_DATA_DIR = _vc_os.environ.get("VCHAT_DATA_DIR", "vchat_data")
_vc_os.makedirs(VCHAT_DATA_DIR, exist_ok=True)
_VCHAT_LOCK = _vc_thr.RLock()

# uid -> {display_name, avatar, status, bio, updated_at}
VCHAT_PROFILES = {}
# sorted pair key "a|b" -> [{id, from, text, ts, type}]
VCHAT_DMS = {}
# group_id -> {name, owner, members:[], messages:[]}
VCHAT_GROUPS = {}
# moments: [{id, uid, text, media, ts, likes:set, comments:[]}]
VCHAT_MOMENTS = []
# red packets: packet_id -> {...}
VCHAT_RED_PACKETS = {}


def _vc_pair_key(a, b):
    a, b = str(a), str(b)
    return "%s|%s" % tuple(sorted([a, b]))


def _vc_profile_path(uid):
    safe = "".join(c if c.isalnum() or c in "-_" else "_" for c in str(uid))[:80]
    return _vc_os.path.join(VCHAT_DATA_DIR, "profile_%s.json" % safe)


def vchat_get_profile(uid):
    uid = str(uid or "anon")
    with _VCHAT_LOCK:
        if uid in VCHAT_PROFILES:
            return dict(VCHAT_PROFILES[uid])
        p = {
            "uid": uid,
            "display_name": uid,
            "avatar": "",
            "status": "online",
            "bio": "",
            "updated_at": _vc_time.time(),
        }
        path = _vc_profile_path(uid)
        try:
            if _vc_os.path.exists(path):
                with open(path, "r", encoding="utf-8") as f:
                    raw = _vc_json.load(f)
                p.update({k: raw.get(k, p[k]) for k in ("display_name", "avatar", "status", "bio", "updated_at")})
        except Exception:
            pass
        VCHAT_PROFILES[uid] = p
        return dict(p)


def vchat_update_profile(uid, **fields):
    uid = str(uid)
    with _VCHAT_LOCK:
        p = vchat_get_profile(uid)
        for k in ("display_name", "avatar", "status", "bio"):
            if k in fields and fields[k] is not None:
                p[k] = fields[k]
        p["updated_at"] = _vc_time.time()
        VCHAT_PROFILES[uid] = p
        try:
            with open(_vc_profile_path(uid), "w", encoding="utf-8") as f:
                _vc_json.dump(p, f, ensure_ascii=False, indent=2)
        except Exception:
            pass
        return dict(p)


def vchat_dm_send(from_uid, to_uid, text, msg_type="text"):
    from_uid, to_uid = str(from_uid), str(to_uid)
    text = (text or "").strip()
    if not text:
        return {"ok": False, "msg": "ข้อความว่าง"}
    if from_uid == to_uid:
        return {"ok": False, "msg": "ส่งหาตัวเองไม่ได้"}
    # ใช้เพื่อนถ้ามีระบบ — ไม่บังคับเพื่อให้ลองใช้ได้ แต่แนะนำเป็นเพื่อน
    friends_ok = True
    try:
        if callable(globals().get("are_friends")):
            friends_ok = are_friends(from_uid, to_uid)
    except Exception:
        pass
    # moderate ถ้ามี
    was_censored = False
    try:
        if callable(globals().get("moderate_chat_message")):
            mod = moderate_chat_message(from_uid, text, to_uid=to_uid, game_id="vchat")
            text = mod.get("text", text)
            was_censored = bool(mod.get("was_censored"))
    except Exception:
        pass
    msg = {
        "id": "m_" + _vc_uuid.uuid4().hex[:10],
        "from": from_uid,
        "to": to_uid,
        "text": text,
        "type": msg_type,
        "ts": _vc_time.time(),
        "was_censored": was_censored,
    }
    key = _vc_pair_key(from_uid, to_uid)
    with _VCHAT_LOCK:
        VCHAT_DMS.setdefault(key, []).append(msg)
        if len(VCHAT_DMS[key]) > 500:
            VCHAT_DMS[key] = VCHAT_DMS[key][-500:]
    # socket ถ้ามี
    try:
        if "sio" in globals() and sio:
            sio.emit("vchat_dm", msg, room=to_uid)
            sio.emit("vchat_dm", msg, room=from_uid)
    except Exception:
        pass
    return {"ok": True, "message": msg, "friends": friends_ok}


def vchat_dm_history(uid_a, uid_b, limit=50):
    key = _vc_pair_key(uid_a, uid_b)
    with _VCHAT_LOCK:
        msgs = list(VCHAT_DMS.get(key) or [])
    return msgs[-int(limit):]


def vchat_group_create(owner, name, members=None):
    owner = str(owner)
    gid = "g_" + _vc_uuid.uuid4().hex[:8]
    mem = set([owner] + [str(m) for m in (members or [])])
    g = {
        "group_id": gid,
        "name": (name or "กลุ่มใหม่").strip()[:40],
        "owner": owner,
        "members": list(mem),
        "messages": [],
        "created_at": _vc_time.time(),
    }
    with _VCHAT_LOCK:
        VCHAT_GROUPS[gid] = g
    return {"ok": True, "group": {k: v for k, v in g.items() if k != "messages"}}


def vchat_group_send(gid, from_uid, text):
    from_uid = str(from_uid)
    text = (text or "").strip()
    if not text:
        return {"ok": False, "msg": "ข้อความว่าง"}
    with _VCHAT_LOCK:
        g = VCHAT_GROUPS.get(gid)
        if not g:
            return {"ok": False, "msg": "ไม่พบกลุ่ม"}
        if from_uid not in g["members"]:
            return {"ok": False, "msg": "ไม่ใช่สมาชิกกลุ่ม"}
        msg = {
            "id": "gm_" + _vc_uuid.uuid4().hex[:10],
            "from": from_uid,
            "text": text,
            "ts": _vc_time.time(),
        }
        g["messages"].append(msg)
        if len(g["messages"]) > 500:
            g["messages"] = g["messages"][-500:]
        members = list(g["members"])
    try:
        if "sio" in globals() and sio:
            for m in members:
                sio.emit("vchat_group", {"group_id": gid, **msg}, room=m)
    except Exception:
        pass
    return {"ok": True, "message": msg}


def vchat_moment_post(uid, text, media=None):
    uid = str(uid)
    text = (text or "").strip()
    if not text and not media:
        return {"ok": False, "msg": "ไม่มีเนื้อหา"}
    post = {
        "id": "mom_" + _vc_uuid.uuid4().hex[:10],
        "uid": uid,
        "text": text[:1000],
        "media": media or "",
        "ts": _vc_time.time(),
        "likes": [],
        "comments": [],
    }
    with _VCHAT_LOCK:
        VCHAT_MOMENTS.insert(0, post)
        if len(VCHAT_MOMENTS) > 500:
            del VCHAT_MOMENTS[500:]
    return {"ok": True, "moment": post}


def vchat_moment_feed(limit=30, uid=None):
    with _VCHAT_LOCK:
        feed = list(VCHAT_MOMENTS)[:int(limit)]
    # enrich profile
    out = []
    for m in feed:
        row = dict(m)
        row["likes_count"] = len(row.get("likes") or [])
        row["profile"] = vchat_get_profile(row["uid"])
        out.append(row)
    return out


def vchat_moment_like(moment_id, uid):
    uid = str(uid)
    with _VCHAT_LOCK:
        for m in VCHAT_MOMENTS:
            if m["id"] == moment_id:
                likes = m.setdefault("likes", [])
                if uid in likes:
                    likes.remove(uid)
                    liked = False
                else:
                    likes.append(uid)
                    liked = True
                return {"ok": True, "liked": liked, "likes_count": len(likes)}
    return {"ok": False, "msg": "ไม่พบโพสต์"}


def vchat_moment_comment(moment_id, uid, text):
    uid = str(uid)
    text = (text or "").strip()[:300]
    if not text:
        return {"ok": False, "msg": "ข้อความว่าง"}
    with _VCHAT_LOCK:
        for m in VCHAT_MOMENTS:
            if m["id"] == moment_id:
                c = {"id": "c_" + _vc_uuid.uuid4().hex[:8], "uid": uid, "text": text, "ts": _vc_time.time()}
                m.setdefault("comments", []).append(c)
                return {"ok": True, "comment": c}
    return {"ok": False, "msg": "ไม่พบโพสต์"}


def vchat_transfer(from_uid, to_uid, amount, note=""):
    """โอนเงินในแอป (หักจากบัญชีธนาคารผู้ใช้ → ฝากเข้าผู้รับ)"""
    from_uid, to_uid = str(from_uid), str(to_uid)
    amount = float(amount or 0)
    if amount <= 0:
        return {"ok": False, "msg": "จำนวนต้อง > 0"}
    if from_uid == to_uid:
        return {"ok": False, "msg": "โอนให้ตัวเองไม่ได้"}
    if not callable(globals().get("vmax_bank_get")):
        return {"ok": False, "msg": "ระบบธนาคารยังไม่พร้อม"}
    acct = vmax_bank_get(from_uid)
    bal = float(acct.get("balance_thb") or 0)
    if bal < amount:
        return {"ok": False, "msg": "ยอดในบัญชีธนาคารไม่พอ (มี %.2f)" % bal, "balance": bal}
    # หักผู้ส่ง
    with _VMAX_BANK_LOCK:
        a = _bank_load_account(from_uid)
        a["balance_thb"] = round(float(a.get("balance_thb") or 0) - amount, 2)
        a.setdefault("ledger", []).append({
            "tx_id": "xfer_" + _vc_uuid.uuid4().hex[:10],
            "ts": _vc_time.time(),
            "direction": "transfer_out",
            "amount": amount,
            "to": to_uid,
            "note": note or "VChat transfer",
        })
        _bank_save_account(from_uid, a)
    vmax_bank_deposit_user(to_uid, amount, note="รับโอนจาก %s (VChat)" % from_uid, ref=from_uid)
    # แจ้งใน DM
    vchat_dm_send(from_uid, to_uid, "[โอนเงิน] %.2f THB %s" % (amount, note or ""), msg_type="transfer")
    return {
        "ok": True,
        "amount": amount,
        "from": from_uid,
        "to": to_uid,
        "from_balance": vmax_bank_get(from_uid).get("balance_thb"),
        "to_balance": vmax_bank_get(to_uid).get("balance_thb"),
    }


def vchat_red_packet_create(from_uid, total_amount, count=1, to_uid=None, group_id=None, greeting="อั่งเปา"):
    """สร้างซองอั่งเปา — หักจากบัญชีธนาคารผู้สร้าง"""
    from_uid = str(from_uid)
    total_amount = float(total_amount or 0)
    count = max(1, int(count or 1))
    if total_amount <= 0:
        return {"ok": False, "msg": "จำนวนต้อง > 0"}
    if not callable(globals().get("vmax_bank_get")):
        return {"ok": False, "msg": "ระบบธนาคารยังไม่พร้อม"}
    bal = float(vmax_bank_get(from_uid).get("balance_thb") or 0)
    if bal < total_amount:
        return {"ok": False, "msg": "ยอดไม่พอ", "balance": bal}
    with _VMAX_BANK_LOCK:
        a = _bank_load_account(from_uid)
        a["balance_thb"] = round(float(a.get("balance_thb") or 0) - total_amount, 2)
        a.setdefault("ledger", []).append({
            "tx_id": "rp_" + _vc_uuid.uuid4().hex[:10],
            "ts": _vc_time.time(),
            "direction": "red_packet_out",
            "amount": total_amount,
            "note": greeting,
        })
        _bank_save_account(from_uid, a)
    pid = "rp_" + _vc_uuid.uuid4().hex[:10]
    packet = {
        "packet_id": pid,
        "from_uid": from_uid,
        "total": total_amount,
        "remain_amount": total_amount,
        "count": count,
        "claimed": [],
        "to_uid": str(to_uid) if to_uid else None,
        "group_id": group_id,
        "greeting": greeting,
        "created_at": _vc_time.time(),
    }
    with _VCHAT_LOCK:
        VCHAT_RED_PACKETS[pid] = packet
    if to_uid:
        vchat_dm_send(from_uid, to_uid, "[ซองอั่งเปา] %s — เปิดที่ /api/vchat/redpacket/claim" % greeting, msg_type="red_packet")
    return {"ok": True, "packet": {k: v for k, v in packet.items()}}


def vchat_red_packet_claim(packet_id, uid):
    uid = str(uid)
    with _VCHAT_LOCK:
        p = VCHAT_RED_PACKETS.get(packet_id)
        if not p:
            return {"ok": False, "msg": "ไม่พบซอง"}
        if any(c.get("uid") == uid for c in p["claimed"]):
            return {"ok": False, "msg": "เปิดไปแล้ว"}
        if len(p["claimed"]) >= p["count"] or p["remain_amount"] <= 0:
            return {"ok": False, "msg": "ซองหมดแล้ว"}
        if p.get("to_uid") and p["to_uid"] != uid:
            return {"ok": False, "msg": "ซองนี้ไม่ใช่ของคุณ"}
        left_slots = p["count"] - len(p["claimed"])
        if left_slots <= 1:
            take = round(p["remain_amount"], 2)
        else:
            # แบ่งคร่าว ๆ
            take = round(min(p["remain_amount"] * 0.5, p["remain_amount"] / left_slots * 1.5), 2)
            take = max(0.01, min(take, p["remain_amount"]))
        p["remain_amount"] = round(p["remain_amount"] - take, 2)
        p["claimed"].append({"uid": uid, "amount": take, "ts": _vc_time.time()})
    if callable(globals().get("vmax_bank_deposit_user")):
        vmax_bank_deposit_user(uid, take, note="เปิดซองอั่งเปา %s" % packet_id, ref=packet_id)
    return {"ok": True, "amount": take, "balance": vmax_bank_get(uid).get("balance_thb") if callable(globals().get("vmax_bank_get")) else None}


