def _run_vchat_selftest():
    ok = True
    a, b = "vc_a", "vc_b"
    # seed bank balances for transfer
    try:
        vmax_bank_deposit_user(a, 100, note="seed")
    except Exception:
        pass
    r = vchat_dm_send(a, b, "สวัสดี")
    ok &= r.get("ok") is True
    hist = vchat_dm_history(a, b)
    ok &= len(hist) >= 1
    m = vchat_moment_post(a, "โมเมนต์ทดสอบ")
    ok &= m.get("ok") is True
    feed = vchat_moment_feed(10)
    ok &= any(x.get("text") == "โมเมนต์ทดสอบ" for x in feed)
    like = vchat_moment_like(m["moment"]["id"], b)
    ok &= like.get("ok") is True
    g = vchat_group_create(a, "กลุ่มทดสอบ", [b])
    ok &= g.get("ok") is True
    gs = vchat_group_send(g["group"]["group_id"], a, "hello group")
    ok &= gs.get("ok") is True
    # transfer if bank has money
    try:
        if float(vmax_bank_get(a).get("balance_thb") or 0) >= 1:
            tr = vchat_transfer(a, b, 1, "test")
            ok &= tr.get("ok") is True
    except Exception:
        pass
    print("VCHAT SELFTEST:", "OK" if ok else "FAILED")
    return ok


