# แทรก hook: ถ้าส่ง DM หา vmax_helper ให้ตีความเป็น onboarding reply
_orig_vchat_dm_send = globals().get("vchat_dm_send")
if callable(_orig_vchat_dm_send) and not getattr(_orig_vchat_dm_send, "_onboarding_wrapped", False):
    def vchat_dm_send(from_uid, to_uid, text, msg_type="text"):
        result = _orig_vchat_dm_send(from_uid, to_uid, text, msg_type=msg_type)
        try:
            if str(to_uid) == VMAX_HELPER_UID and str(from_uid) != VMAX_HELPER_UID:
                # ผู้ใช้คุยกับผู้ช่วย → เดิน onboarding
                vmax_onboarding_reply(from_uid, text)
        except Exception:
            pass
        return result
    vchat_dm_send._onboarding_wrapped = True
    globals()["vchat_dm_send"] = vchat_dm_send


def _run_onboarding_selftest():
    ok = True
    uid = "ob_new_user"
    with _OB_LOCK:
        VMAX_ONBOARDING_STATE.pop(uid, None)
    r0 = vmax_onboarding_start(uid)
    ok &= r0.get("started") is True and r0.get("step") == "choose_lang"
    r1 = vmax_onboarding_reply(uid, "th")
    ok &= r1.get("ok") is True and r1.get("step") == "choose_help"
    r2 = vmax_onboarding_reply(uid, "topup")
    ok &= r2.get("ok") is True and r2.get("done") is True
    with _OB_LOCK:
        st = VMAX_ONBOARDING_STATE.get(uid) or {}
    ok &= st.get("lang") == "th" and st.get("help_topic") == "topup"
    print("ONBOARDING SELFTEST:", "OK" if ok else "FAILED")
    return ok


