# ==========================================================================
# [ BILL PAYMENT — รหัสจ่ายที่ 7-Eleven / เคาน์เตอร์เซอร์วิส ]
# -------------------------------------------------------------------------
# สร้างบิล + รหัสอ้างอิง ให้ผู้เล่นไปจ่ายที่:
#   - 7-Eleven
#   - เคาน์เตอร์เซอร์วิส
#   - (ทางเลือก) ตู้/เคาน์เตอร์อื่นที่รับบิลเดียวกัน
# หลังจ่ายสำเร็จ:
#   1) webhook / ยืนยันด้วยมือ / ผู้ให้บริการแจ้ง
#   2) ระบบ fulfill ของ (topup / social / ai) + เงินเข้าธนาคารแพลตฟอร์ม
#
# โหมด:
#   - local: สร้างรหัสในระบบเราเอง (ใช้คู่ webhook/แอดมินยืนยัน) — ใช้ได้ทันทีตอน dev
#   - omise: พยายามสร้าง source ผ่าน Omise ถ้าบัญชีรองรับ bill payment
#   - external: ส่งต่อไปยัง API ผู้ให้บริการภายนอก (GBPrimePay ฯลฯ) ถ้าตั้ง URL
# ==========================================================================
import hashlib as _bp_hl
import json as _bp_json
import os as _bp_os
import random as _bp_rand
import string as _bp_str
import threading as _bp_thr
import time as _bp_time
import uuid as _bp_uuid

VMAX_BILLPAY_DATA_DIR = _bp_os.environ.get("VMAX_BILLPAY_DATA_DIR", "vmax_billpay_data")
_bp_os.makedirs(VMAX_BILLPAY_DATA_DIR, exist_ok=True)
_BP_LOCK = _bp_thr.RLock()

# รหัสร้าน/บิล prefix (ปรับได้) — รูปแบบคล้าย ref ที่เคาน์เตอร์ใช้
VMAX_BILLPAY_PREFIX = _bp_os.environ.get("VMAX_BILLPAY_PREFIX", "VMAX")
VMAX_BILLPAY_TTL_SEC = int(_bp_os.environ.get("VMAX_BILLPAY_TTL_SEC", str(24 * 3600)))  # 24 ชม.
VMAX_BILLPAY_PROVIDER = _bp_os.environ.get("VMAX_BILLPAY_PROVIDER", "local")  # local|omise|external
VMAX_BILLPAY_EXTERNAL_URL = _bp_os.environ.get("VMAX_BILLPAY_EXTERNAL_URL", "").rstrip("/")
VMAX_BILLPAY_EXTERNAL_KEY = _bp_os.environ.get("VMAX_BILLPAY_EXTERNAL_KEY", "")
VMAX_BILLPAY_WEBHOOK_SECRET = _bp_os.environ.get("VMAX_BILLPAY_WEBHOOK_SECRET", "")

# channel labels
VMAX_BILLPAY_CHANNELS = {
    "seven_eleven": {
        "id": "seven_eleven",
        "name_th": "7-Eleven",
        "name_en": "7-Eleven",
        "instruction_th": "ไปที่ 7-Eleven แจ้งพนักงานว่าต้องการชำระบิล/ชำระเงิน แล้วให้รหัสอ้างอิงด้านล่าง (หรือสแกนบาร์โค้ดถ้ามี)",
    },
    "counter_service": {
        "id": "counter_service",
        "name_th": "เคาน์เตอร์เซอร์วิส",
        "name_en": "Counter Service",
        "instruction_th": "ไปที่เคาน์เตอร์เซอร์วิส เลือกชำระบิล/ชำระเงิน แล้วให้รหัสอ้างอิง",
    },
    "lotus": {
        "id": "lotus",
        "name_th": "โลตัส / เคาน์เตอร์ในห้าง",
        "name_en": "Lotus / mall counter",
        "instruction_th": "ชำระที่เคาน์เตอร์ในห้างที่รองรับบิลเดียวกัน ด้วยรหัสอ้างอิง",
    },
}

# bill_id -> record
VMAX_BILLPAY_ORDERS = {}


def _bp_path(bill_id):
    safe = "".join(c if c.isalnum() or c in "-_" else "_" for c in str(bill_id))[:80]
    return _bp_os.path.join(VMAX_BILLPAY_DATA_DIR, "bill_%s.json" % safe)


def _bp_save(bill):
    try:
        with open(_bp_path(bill["bill_id"]), "w", encoding="utf-8") as f:
            _bp_json.dump(bill, f, ensure_ascii=False, indent=2)
    except Exception as exc:
        print("[BILLPAY] save fail:", repr(exc))


def _bp_load(bill_id):
    with _BP_LOCK:
        if bill_id in VMAX_BILLPAY_ORDERS:
            return VMAX_BILLPAY_ORDERS[bill_id]
    path = _bp_path(bill_id)
    try:
        if _bp_os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                bill = _bp_json.load(f)
            with _BP_LOCK:
                VMAX_BILLPAY_ORDERS[bill_id] = bill
            return bill
    except Exception:
        pass
    return None


def _bp_gen_ref_code(amount_thb, uid=""):
    """
    สร้างรหัสอ้างอิงที่อ่านง่ายสำหรับเคาน์เตอร์
    รูปแบบ: VMAX + YYMMDD + 8 ตัวอักษร/ตัวเลข (ไม่ใช้ 0O1I เพื่อลดสับสน)
    """
    alphabet = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"
    day = _bp_time.strftime("%y%m%d")
    rnd = "".join(_bp_rand.choice(alphabet) for _ in range(8))
    # checksum ง่าย ๆ จาก amount+uid
    raw = "%s|%s|%s|%s" % (VMAX_BILLPAY_PREFIX, day, amount_thb, uid)
    chk = _bp_hl.sha256(raw.encode("utf-8")).hexdigest()[:2].upper()
    return "%s%s%s%s" % (VMAX_BILLPAY_PREFIX, day, rnd, chk)


def _bp_barcode_payload(ref_code, amount_thb):
    """payload สำหรับสร้างบาร์โค้ดฝั่ง client (Code128) — ไม่บังคับมีรูปบนเซิร์ฟเวอร์"""
    # รูปแบบข้อความ: REF|AMOUNT
    return "%s|%s" % (ref_code, int(round(float(amount_thb) * 100)))


def vmax_billpay_create(uid, amount_thb, channel="seven_eleven",
                        purpose="topup", item_id=None, meta=None, currency="THB"):
    """
    สร้างบิลรอชำระที่ตู้/เคาน์เตอร์
    purpose: topup | social | ai_pack | general
    """
    uid = str(uid or "anon")
    amount_thb = round(float(amount_thb or 0), 2)
    if amount_thb < 1:
        return {"ok": False, "msg": "ยอดขั้นต่ำ 1 บาท"}
    channel = str(channel or "seven_eleven").lower()
    if channel not in VMAX_BILLPAY_CHANNELS:
        channel = "seven_eleven"
    ch = VMAX_BILLPAY_CHANNELS[channel]

    bill_id = "bp_" + _bp_uuid.uuid4().hex[:12]
    ref_code = _bp_gen_ref_code(amount_thb, uid)
    now = _bp_time.time()
    expires = now + VMAX_BILLPAY_TTL_SEC

    bill = {
        "bill_id": bill_id,
        "ref_code": ref_code,
        "barcode_payload": _bp_barcode_payload(ref_code, amount_thb),
        "uid": uid,
        "amount_thb": amount_thb,
        "currency": currency or "THB",
        "channel": channel,
        "channel_name_th": ch["name_th"],
        "instruction_th": ch["instruction_th"],
        "purpose": purpose or "general",
        "item_id": item_id,
        "meta": meta or {},
        "status": "pending",  # pending | paid | expired | cancelled
        "provider": VMAX_BILLPAY_PROVIDER,
        "provider_ref": None,
        "created_at": now,
        "expires_at": expires,
        "paid_at": None,
    }

    # พยายามต่อ external / omise ถ้าตั้งค่า
    provider_note = None
    if VMAX_BILLPAY_PROVIDER == "external" and VMAX_BILLPAY_EXTERNAL_URL:
        try:
            import requests as _bp_req
            headers = {"Content-Type": "application/json"}
            if VMAX_BILLPAY_EXTERNAL_KEY:
                headers["Authorization"] = "Bearer " + VMAX_BILLPAY_EXTERNAL_KEY
            resp = _bp_req.post(
                VMAX_BILLPAY_EXTERNAL_URL + "/bills",
                json={
                    "ref_code": ref_code,
                    "amount": amount_thb,
                    "currency": "THB",
                    "uid": uid,
                    "channel": channel,
                    "callback_hint": "/api/billpay/webhook",
                },
                headers=headers,
                timeout=12,
            )
            if resp.status_code < 300:
                data = resp.json() if resp.content else {}
                bill["provider_ref"] = data.get("provider_ref") or data.get("id")
                if data.get("ref_code"):
                    bill["ref_code"] = data["ref_code"]
                provider_note = "created_via_external"
            else:
                provider_note = "external_http_%s_fallback_local" % resp.status_code
        except Exception as exc:
            provider_note = "external_error_fallback_local: %s" % repr(exc)
    elif VMAX_BILLPAY_PROVIDER == "omise":
        # Omise บางบัญชีอาจมี bill payment source — ถ้าไม่สำเร็จใช้ local ref
        try:
            if globals().get("OMISE_SECRET_KEY") and callable(globals().get("_omise_request")):
                amount_satang = int(round(amount_thb * 100))
                # ลองสร้าง charge/source แบบ barcode ถ้า API รองรับ — ไม่บังคับสำเร็จ
                src = _omise_request("POST", "/sources", data={
                    "amount": amount_satang,
                    "currency": "thb",
                    "type": "bill_payment_tesco_lotus",  # ตัวอย่าง type เก่าของ Omise (อาจไม่เปิดในบัญชี)
                })
                if src.status_code < 300:
                    body = src.json()
                    bill["provider_ref"] = body.get("id")
                    provider_note = "omise_source_created"
                else:
                    provider_note = "omise_source_unavailable_use_local_ref"
            else:
                provider_note = "omise_keys_missing_use_local_ref"
        except Exception as exc:
            provider_note = "omise_error_use_local: %s" % repr(exc)

    bill["provider_note"] = provider_note

    with _BP_LOCK:
        VMAX_BILLPAY_ORDERS[bill_id] = bill
        _bp_save(bill)

    return {
        "ok": True,
        "bill": _bp_public_view(bill),
        "how_to_pay_th": [
            "1) จดรหัสอ้างอิง: %s" % bill["ref_code"],
            "2) ไปที่ %s" % ch["name_th"],
            "3) แจ้งพนักงานว่าต้องการชำระบิล/ชำระเงิน ยอด %.2f บาท" % amount_thb,
            "4) ให้รหัสอ้างอิง (หรือสแกนบาร์โค้ดจากแอปถ้ามี)",
            "5) หลังจ่ายสำเร็จ ระบบจะปลดล็อกของอัตโนมัติ (หรือกดตรวจสถานะ)",
        ],
    }


def _bp_public_view(bill):
    return {
        "bill_id": bill["bill_id"],
        "ref_code": bill["ref_code"],
        "barcode_payload": bill.get("barcode_payload"),
        "amount_thb": bill["amount_thb"],
        "currency": bill.get("currency", "THB"),
        "channel": bill["channel"],
        "channel_name_th": bill.get("channel_name_th"),
        "instruction_th": bill.get("instruction_th"),
        "purpose": bill.get("purpose"),
        "item_id": bill.get("item_id"),
        "status": bill["status"],
        "created_at": bill.get("created_at"),
        "expires_at": bill.get("expires_at"),
        "paid_at": bill.get("paid_at"),
        "provider": bill.get("provider"),
        "provider_note": bill.get("provider_note"),
    }


def vmax_billpay_get(bill_id=None, ref_code=None):
    if bill_id:
        bill = _bp_load(bill_id)
        if bill:
            _bp_expire_if_needed(bill)
            return bill
    if ref_code:
        with _BP_LOCK:
            for b in VMAX_BILLPAY_ORDERS.values():
                if b.get("ref_code") == ref_code:
                    _bp_expire_if_needed(b)
                    return b
        # disk scan light — only cached ones; full scan optional
        try:
            for fn in _bp_os.listdir(VMAX_BILLPAY_DATA_DIR):
                if not fn.startswith("bill_"):
                    continue
                path = _bp_os.path.join(VMAX_BILLPAY_DATA_DIR, fn)
                with open(path, "r", encoding="utf-8") as f:
                    b = _bp_json.load(f)
                if b.get("ref_code") == ref_code:
                    with _BP_LOCK:
                        VMAX_BILLPAY_ORDERS[b["bill_id"]] = b
                    _bp_expire_if_needed(b)
                    return b
        except Exception:
            pass
    return None


def _bp_expire_if_needed(bill):
    if bill.get("status") == "pending" and float(bill.get("expires_at") or 0) < _bp_time.time():
        bill["status"] = "expired"
        with _BP_LOCK:
            VMAX_BILLPAY_ORDERS[bill["bill_id"]] = bill
            _bp_save(bill)


def vmax_billpay_mark_paid(bill_id=None, ref_code=None, paid_amount=None, source="webhook"):
    """
    ยืนยันว่าจ่ายแล้ว → fulfill ตาม purpose
    """
    bill = vmax_billpay_get(bill_id=bill_id, ref_code=ref_code)
    if not bill:
        return {"ok": False, "msg": "ไม่พบบิล"}
    if bill.get("status") == "paid":
        return {"ok": True, "already_paid": True, "bill": _bp_public_view(bill)}
    if bill.get("status") == "expired":
        return {"ok": False, "msg": "บิลหมดอายุ"}
    if bill.get("status") == "cancelled":
        return {"ok": False, "msg": "บิลถูกยกเลิก"}

    amount = float(bill["amount_thb"])
    if paid_amount is not None:
        try:
            if abs(float(paid_amount) - amount) > 0.05:
                return {"ok": False, "msg": "ยอดที่จ่ายไม่ตรงบิล", "expected": amount, "got": paid_amount}
        except Exception:
            pass

    bill["status"] = "paid"
    bill["paid_at"] = _bp_time.time()
    bill["paid_source"] = source
    with _BP_LOCK:
        VMAX_BILLPAY_ORDERS[bill["bill_id"]] = bill
        _bp_save(bill)

    fulfill = vmax_billpay_fulfill(bill)
    return {"ok": True, "bill": _bp_public_view(bill), "fulfill": fulfill}


def vmax_billpay_fulfill(bill):
    """ปลดล็อกของตาม purpose ของบิล"""
    uid = bill.get("uid")
    purpose = bill.get("purpose") or "general"
    item_id = bill.get("item_id")
    amount = float(bill.get("amount_thb") or 0)
    result = {"purpose": purpose, "item_id": item_id}

    try:
        if purpose == "topup" and callable(globals().get("_vmax_topup_fulfill")):
            result.update(_vmax_topup_fulfill(uid, item_id or "topup_35", bill.get("meta") or {}))
        elif purpose == "social" and callable(globals().get("_vmax_social_fulfill")):
            result.update(_vmax_social_fulfill(uid, item_id or "social_plus", amount, bill.get("meta") or {}))
        elif purpose == "ai_pack" and callable(globals().get("_vmax_ai_pack_fulfill")):
            result.update(_vmax_ai_pack_fulfill(uid, item_id or "ai_pack_50", amount))
        else:
            result["note"] = "general payment recorded"
    except Exception as exc:
        result["fulfill_error"] = repr(exc)

    # เงินเข้าธนาคารแพลตฟอร์ม
    try:
        if callable(globals().get("vmax_bank_on_purchase")) and amount > 0:
            result["bank"] = vmax_bank_on_purchase(
                uid=uid, amount=amount, currency=bill.get("currency") or "THB",
                kind="billpay_%s" % purpose, item_id=item_id or bill.get("ref_code"),
                charge_id=bill.get("bill_id"),
            )
    except Exception as exc:
        result["bank_error"] = repr(exc)

    return result


def vmax_billpay_create_for_topup(uid, pack_id="topup_35", channel="seven_eleven"):
    """สร้างบิลเติมเกม — ใช้ราคาหลังลดเทศกาล"""
    pack_id = pack_id or "topup_35"
    amount = 35.0
    try:
        if callable(globals().get("vmax_topup_pack_price")):
            priced = vmax_topup_pack_price(pack_id)
            if priced:
                amount = float(priced["final"])
                meta = {"pricing": priced}
            else:
                meta = {}
        else:
            meta = {}
    except Exception:
        meta = {}
    try:
        pack = (globals().get("VMAX_GAME_TOPUP_PACKS") or {}).get(pack_id) or {}
        if pack.get("price") and not meta.get("pricing"):
            amount = float(pack["price"])
    except Exception:
        pass
    return vmax_billpay_create(
        uid=uid, amount_thb=amount, channel=channel,
        purpose="topup", item_id=pack_id, meta=meta,
    )


try:
    @app.route("/api/billpay/channels", methods=["GET"])
    def api_billpay_channels():
        return jsonify({
            "st": "ok",
            "channels": list(VMAX_BILLPAY_CHANNELS.values()),
            "provider": VMAX_BILLPAY_PROVIDER,
            "ttl_sec": VMAX_BILLPAY_TTL_SEC,
        })

    @app.route("/api/billpay/create", methods=["POST"])
    def api_billpay_create():
        body = request.get_json(silent=True) or {}
        uid = body.get("uid") or getattr(request, "vmax_uid", None) or "anon"
        amount = body.get("amount")
        channel = body.get("channel") or "seven_eleven"
        purpose = body.get("purpose") or "general"
        item_id = body.get("item_id") or body.get("pack_id")
        # shortcut เติมเกม
        if purpose == "topup" or body.get("pack_id"):
            result = vmax_billpay_create_for_topup(uid, pack_id=item_id or body.get("pack_id") or "topup_35",
                                                  channel=channel)
        else:
            if amount is None:
                return jsonify({"st": "error", "msg": "ต้องระบุ amount หรือ purpose=topup"}), 400
            result = vmax_billpay_create(
                uid=uid, amount_thb=amount, channel=channel,
                purpose=purpose, item_id=item_id, meta=body.get("meta"),
            )
        code = 200 if result.get("ok") else 400
        return jsonify({"st": "ok" if result.get("ok") else "error", **result}), code

    @app.route("/api/billpay/status", methods=["GET"])
    def api_billpay_status():
        bill_id = request.args.get("bill_id")
        ref_code = request.args.get("ref_code")
        bill = vmax_billpay_get(bill_id=bill_id, ref_code=ref_code)
        if not bill:
            return jsonify({"st": "error", "msg": "ไม่พบบิล"}), 404
        return jsonify({"st": "ok", "bill": _bp_public_view(bill)})

    @app.route("/api/billpay/mark-paid", methods=["POST"])
    def api_billpay_mark_paid():
        """แอดมิน/ระบบยืนยันว่าเคาน์เตอร์รับเงินแล้ว (ใช้ตอน local provider หรือทดสอบ)"""
        try:
            if callable(globals().get("vmax_admin_require")):
                vmax_admin_require("billpay_mark_paid")
        except Exception:
            pass
        body = request.get_json(silent=True) or {}
        result = vmax_billpay_mark_paid(
            bill_id=body.get("bill_id"),
            ref_code=body.get("ref_code"),
            paid_amount=body.get("paid_amount"),
            source=body.get("source") or "admin",
        )
        code = 200 if result.get("ok") else 400
        return jsonify({"st": "ok" if result.get("ok") else "error", **result}), code

    @app.route("/api/billpay/webhook", methods=["POST"])
    def api_billpay_webhook():
        """
        ผู้ให้บริการภายนอก / ระบบเคาน์เตอร์ แจ้งว่าจ่ายแล้ว
        body ตัวอย่าง: {ref_code|bill_id, amount, secret?}
        """
        body = request.get_json(silent=True) or {}
        # ตรวจ secret ถ้าตั้งไว้
        if VMAX_BILLPAY_WEBHOOK_SECRET:
            got = (body.get("secret") or request.headers.get("X-VMAX-Billpay-Secret") or "")
            if got != VMAX_BILLPAY_WEBHOOK_SECRET:
                return jsonify({"st": "error", "msg": "invalid webhook secret"}), 403
        result = vmax_billpay_mark_paid(
            bill_id=body.get("bill_id"),
            ref_code=body.get("ref_code") or body.get("payment_code") or body.get("barcode"),
            paid_amount=body.get("amount") or body.get("paid_amount"),
            source="webhook",
        )
        code = 200 if result.get("ok") else 400
        return jsonify({"st": "ok" if result.get("ok") else "error", **result}), code

    @app.route("/api/billpay/cancel", methods=["POST"])
    def api_billpay_cancel():
        body = request.get_json(silent=True) or {}
        bill = vmax_billpay_get(bill_id=body.get("bill_id"), ref_code=body.get("ref_code"))
        if not bill:
            return jsonify({"st": "error", "msg": "ไม่พบบิล"}), 404
        if bill.get("status") == "paid":
            return jsonify({"st": "error", "msg": "บิลจ่ายแล้ว ยกเลิกไม่ได้"}), 400
        bill["status"] = "cancelled"
        with _BP_LOCK:
            VMAX_BILLPAY_ORDERS[bill["bill_id"]] = bill
            _bp_save(bill)
        return jsonify({"st": "ok", "bill": _bp_public_view(bill)})

except Exception as _bp_exc:
    print("[BILLPAY] routes skip:", repr(_bp_exc))


def _run_billpay_selftest():
    ok = True
    r = vmax_billpay_create("bp_user", 20, channel="seven_eleven", purpose="topup", item_id="topup_35")
    ok &= r.get("ok") is True
    bill = r["bill"]
    ok &= bill["status"] == "pending" and bill["ref_code"].startswith(VMAX_BILLPAY_PREFIX)
    ok &= bill["amount_thb"] == 20
    # mark paid
    paid = vmax_billpay_mark_paid(bill_id=bill["bill_id"], paid_amount=20, source="selftest")
    ok &= paid.get("ok") is True
    again = vmax_billpay_get(bill_id=bill["bill_id"])
    ok &= again.get("status") == "paid"
    # channel counter
    r2 = vmax_billpay_create("bp_user2", 35, channel="counter_service", purpose="general")
    ok &= r2.get("ok") is True and r2["bill"]["channel"] == "counter_service"
    print("BILLPAY SELFTEST:", "OK" if ok else "FAILED")
    return ok


