# ==========================================================================
# [ MOTION FILTER / ANTI-SHAKE — กรองแรงสั่นสะเทือนจากภายนอก ]
# -------------------------------------------------------------------------
# ตามแนวคิด:
#  1) Motion Filtering: แยก micro-movement ความถี่สูง (โต๊ะสั่น) ออกจาก
#     การลากเมาส์ของมนุษย์ แล้วตัด/ลดส่วนที่เป็นสั่น
#  2) Sensor hybrid: รับ gyro/accel จากจอย/มือถือ แล้วหัก (cancel) แรงสั่น
#     ออกจาก aim ในเกม
# ใช้ได้ทั้งฝั่งเซิร์ฟเวอร์ (API รับตัวอย่าง motion) และเป็น logic ให้ client เรียก
# ==========================================================================
import math as _mf_math
import time as _mf_time
import threading as _mf_thr
from collections import deque as _mf_deque

# --- config ---
VMAX_MOTION_FILTER_ENABLED = __import__("os").environ.get("VMAX_MOTION_FILTER", "1") != "0"
# ความถี่ที่ถือว่าเป็น "สั่นโต๊ะ" โดยประมาณ (Hz) — สูงกว่าการเล็งมือมนุษย์ปกติ
VMAX_MOTION_SHAKE_HZ_MIN = float(__import__("os").environ.get("VMAX_MOTION_SHAKE_HZ_MIN", "8.0"))
# ค่า alpha ของ low-pass (0..1) ยิ่งสูงยิ่งตามเมาส์เร็ว / ยิ่งต่ำยิ่งนิ่ง
VMAX_MOTION_LP_ALPHA = float(__import__("os").environ.get("VMAX_MOTION_LP_ALPHA", "0.35"))
# เกณฑ์ความเร่งจากเซ็นเซอร์ที่ถือว่าเป็นสั่นภายนอก (arbitrary unit / g)
VMAX_MOTION_ACCEL_SHAKE_G = float(__import__("os").environ.get("VMAX_MOTION_ACCEL_SHAKE_G", "0.12"))
# ค่า gain ตอนหักสั่นจากเซ็นเซอร์เข้า aim
VMAX_MOTION_SENSOR_CANCEL_GAIN = float(__import__("os").environ.get("VMAX_MOTION_SENSOR_CANCEL_GAIN", "1.0"))

_MF_LOCK = _mf_thr.RLock()
# uid -> filter state
VMAX_MOTION_STATE = {}


class VmaxKalman1D:
    """Kalman filter 1 มิติแบบง่าย สำหรับ dx/dy ของเมาส์"""
    __slots__ = ("x", "p", "q", "r")

    def __init__(self, q=0.02, r=0.5):
        self.x = 0.0
        self.p = 1.0
        self.q = float(q)  # process noise
        self.r = float(r)  # measurement noise

    def update(self, measurement):
        # predict
        self.p = self.p + self.q
        # update
        k = self.p / (self.p + self.r)
        self.x = self.x + k * (float(measurement) - self.x)
        self.p = (1.0 - k) * self.p
        return self.x


class VmaxMotionFilter:
    """
    กรอง motion ของเมาส์/aim:
      - low-pass / Kalman แยกสัญญาณเรียบ (มือมนุษย์) จากความถี่สูง (โต๊ะสั่น)
      - ถ้ามี accel/gyro: หักส่วนสั่นออกจาก delta
    """

    def __init__(self, uid="default"):
        self.uid = str(uid)
        self.kx = VmaxKalman1D()
        self.ky = VmaxKalman1D()
        self.lp_x = 0.0
        self.lp_y = 0.0
        self.last_ts = None
        self.history = _mf_deque(maxlen=64)  # (ts, dx, dy)
        self.total_raw = 0.0
        self.total_filtered = 0.0
        self.shake_events = 0

    def filter_mouse_delta(self, dx, dy, ts=None, method="hybrid"):
        """
        รับ delta เมาส์ดิบ → คืน delta ที่กรองแล้ว
        method: "kalman" | "lowpass" | "hybrid" | "highfreq_reject"
        """
        if not VMAX_MOTION_FILTER_ENABLED:
            return {"dx": float(dx), "dy": float(dy), "filtered": False}
        ts = float(ts if ts is not None else _mf_time.time())
        dx, dy = float(dx), float(dy)
        raw_mag = _mf_math.hypot(dx, dy)

        # ประมาณความถี่จากประวัติสั้น ๆ
        freq_hint = 0.0
        if self.history:
            last_t, last_dx, last_dy = self.history[-1]
            dt = max(1e-4, ts - last_t)
            # ถ้าทิศทางสลับเร็ว + ขนาดเล็ก → น่าจะสั่น
            if raw_mag > 0 and last_dx * dx + last_dy * dy < 0 and raw_mag < 12:
                freq_hint = 1.0 / dt
        self.history.append((ts, dx, dy))

        is_shake_like = freq_hint >= VMAX_MOTION_SHAKE_HZ_MIN and raw_mag < 20

        if method == "kalman":
            fx = self.kx.update(dx)
            fy = self.ky.update(dy)
        elif method == "lowpass":
            a = VMAX_MOTION_LP_ALPHA
            self.lp_x = a * dx + (1 - a) * self.lp_x
            self.lp_y = a * dy + (1 - a) * self.lp_y
            fx, fy = self.lp_x, self.lp_y
        elif method == "highfreq_reject":
            if is_shake_like:
                fx = fy = 0.0
                self.shake_events += 1
            else:
                a = min(0.85, VMAX_MOTION_LP_ALPHA + 0.25)
                self.lp_x = a * dx + (1 - a) * self.lp_x
                self.lp_y = a * dy + (1 - a) * self.lp_y
                fx, fy = self.lp_x, self.lp_y
        else:  # hybrid = kalman + reject สั่นชัด
            fx = self.kx.update(dx)
            fy = self.ky.update(dy)
            if is_shake_like:
                # ลดส่วนที่ต่างจากค่า kalman (ส่วนสั่น)
                fx *= 0.15
                fy *= 0.15
                self.shake_events += 1

        self.last_ts = ts
        self.total_raw += raw_mag
        self.total_filtered += _mf_math.hypot(fx, fy)
        return {
            "dx": fx,
            "dy": fy,
            "raw_dx": dx,
            "raw_dy": dy,
            "filtered": True,
            "shake_like": is_shake_like,
            "freq_hint_hz": round(freq_hint, 2),
            "method": method,
        }

    def apply_sensor_cancel(self, dx, dy, accel=None, gyro=None):
        """
        หักแรงสั่นจากเซ็นเซอร์ออกจาก delta
        accel: {x,y,z} เป็น g โดยประมาณ
        gyro: {x,y,z} rad/s หรือ deg/s (ใช้แค่ขนาด)
        """
        dx, dy = float(dx), float(dy)
        if not accel and not gyro:
            return {"dx": dx, "dy": dy, "sensor_cancel": False}

        cancel_x = cancel_y = 0.0
        shake = False
        if accel:
            ax = float(accel.get("x") or 0)
            ay = float(accel.get("y") or 0)
            az = float(accel.get("z") or 0)
            # ความเร่งแนวนอน (ตัด gravity ประมาณบน z)
            horiz = _mf_math.hypot(ax, ay)
            if horiz >= VMAX_MOTION_ACCEL_SHAKE_G:
                shake = True
                gain = VMAX_MOTION_SENSOR_CANCEL_GAIN
                # map แรงสั่นเซ็นเซอร์ → ชดเชย aim (ทิศตรงข้าม)
                cancel_x = -ax * gain * 8.0
                cancel_y = -ay * gain * 8.0

        if gyro:
            gx = float(gyro.get("x") or 0)
            gy = float(gyro.get("y") or 0)
            # หมุนเล็ก ๆ ความถี่สูง → ลด aim
            spin = _mf_math.hypot(gx, gy)
            if spin > 0.8:
                shake = True
                cancel_x += -gx * 0.5 * VMAX_MOTION_SENSOR_CANCEL_GAIN
                cancel_y += -gy * 0.5 * VMAX_MOTION_SENSOR_CANCEL_GAIN

        if shake:
            self.shake_events += 1
        return {
            "dx": dx + cancel_x,
            "dy": dy + cancel_y,
            "cancel_x": cancel_x,
            "cancel_y": cancel_y,
            "sensor_cancel": shake,
        }

    def process(self, dx, dy, ts=None, method="hybrid", accel=None, gyro=None):
        """pipeline เต็ม: filter เมาส์ แล้วค่อย sensor cancel"""
        base = self.filter_mouse_delta(dx, dy, ts=ts, method=method)
        if accel or gyro:
            sc = self.apply_sensor_cancel(base["dx"], base["dy"], accel=accel, gyro=gyro)
            base["dx"] = sc["dx"]
            base["dy"] = sc["dy"]
            base["sensor_cancel"] = sc.get("sensor_cancel")
            base["cancel_x"] = sc.get("cancel_x")
            base["cancel_y"] = sc.get("cancel_y")
        return base

    def stats(self):
        return {
            "uid": self.uid,
            "shake_events": self.shake_events,
            "total_raw": round(self.total_raw, 3),
            "total_filtered": round(self.total_filtered, 3),
            "reduction_ratio": round(
                1.0 - (self.total_filtered / self.total_raw) if self.total_raw > 1e-6 else 0.0, 4
            ),
        }


def vmax_motion_get(uid="default"):
    uid = str(uid or "default")
    with _MF_LOCK:
        if uid not in VMAX_MOTION_STATE:
            VMAX_MOTION_STATE[uid] = VmaxMotionFilter(uid)
        return VMAX_MOTION_STATE[uid]


def vmax_motion_filter(uid, dx, dy, **kwargs):
    """API helper"""
    f = vmax_motion_get(uid)
    return f.process(dx, dy, **kwargs)


# --- JS snippet ให้ client ใส่ในเกม (optional) ---
VMAX_MOTION_FILTER_JS = r"""
/* VMAX Motion Filter (client-side companion) */
(function(global){
  function Kalman(q,r){this.x=0;this.p=1;this.q=q||0.02;this.r=r||0.5;}
  Kalman.prototype.update=function(m){
    this.p+=this.q; var k=this.p/(this.p+this.r);
    this.x=this.x+k*(m-this.x); this.p=(1-k)*this.p; return this.x;
  };
  function MotionFilter(){
    this.kx=new Kalman(); this.ky=new Kalman();
    this.lpX=0; this.lpY=0; this.last=null; this.alpha=0.35;
  }
  MotionFilter.prototype.filter=function(dx,dy,method){
    method=method||'hybrid';
    var now=performance.now()/1000, shake=false, freq=0;
    if(this.last){
      var dt=Math.max(1e-4, now-this.last.t);
      if((dx*this.last.dx+dy*this.last.dy)<0 && Math.hypot(dx,dy)<12) freq=1/dt;
      shake = freq>=8 && Math.hypot(dx,dy)<20;
    }
    this.last={t:now,dx:dx,dy:dy};
    var fx,fy;
    if(method==='kalman'||method==='hybrid'){ fx=this.kx.update(dx); fy=this.ky.update(dy); }
    else { fx=this.lpX=this.alpha*dx+(1-this.alpha)*this.lpX; fy=this.lpY=this.alpha*dy+(1-this.alpha)*this.lpY; }
    if(method==='hybrid'&&shake){ fx*=0.15; fy*=0.15; }
    if(method==='highfreq_reject'&&shake){ fx=0; fy=0; }
    return {dx:fx,dy:fy,shake:shake,freq:freq};
  };
  MotionFilter.prototype.sensorCancel=function(dx,dy,accel){
    if(!accel) return {dx:dx,dy:dy};
    var ax=+accel.x||0, ay=+accel.y||0, h=Math.hypot(ax,ay);
    if(h<0.12) return {dx:dx,dy:dy,sensor:false};
    return {dx:dx-ax*8, dy:dy-ay*8, sensor:true};
  };
  global.VmaxMotionFilter = MotionFilter;
})(window);
"""


try:
    @app.route("/api/motion/filter", methods=["POST"])
    def api_motion_filter():
        """
        body: {
          uid, dx, dy, method?,
          accel?: {x,y,z}, gyro?: {x,y,z}, ts?
        }
        """
        body = request.get_json(silent=True) or {}
        uid = body.get("uid") or "default"
        try:
            dx = float(body.get("dx") or 0)
            dy = float(body.get("dy") or 0)
        except Exception:
            return jsonify({"st": "error", "msg": "dx/dy ต้องเป็นตัวเลข"}), 400
        out = vmax_motion_filter(
            uid, dx, dy,
            method=body.get("method") or "hybrid",
            accel=body.get("accel"),
            gyro=body.get("gyro"),
            ts=body.get("ts"),
        )
        return jsonify({"st": "ok", "enabled": VMAX_MOTION_FILTER_ENABLED, **out})

    @app.route("/api/motion/stats", methods=["GET"])
    def api_motion_stats():
        uid = request.args.get("uid") or "default"
        f = vmax_motion_get(uid)
        return jsonify({"st": "ok", "enabled": VMAX_MOTION_FILTER_ENABLED, **f.stats()})

    @app.route("/api/motion/reset", methods=["POST"])
    def api_motion_reset():
        body = request.get_json(silent=True) or {}
        uid = str(body.get("uid") or "default")
        with _MF_LOCK:
            VMAX_MOTION_STATE[uid] = VmaxMotionFilter(uid)
        return jsonify({"st": "ok", "uid": uid})

    @app.route("/api/motion/js")
    def api_motion_js():
        from flask import Response as _MFResp
        return _MFResp(VMAX_MOTION_FILTER_JS, mimetype="application/javascript")

    @app.route("/api/motion/config", methods=["GET"])
    def api_motion_config():
        return jsonify({
            "st": "ok",
            "enabled": VMAX_MOTION_FILTER_ENABLED,
            "shake_hz_min": VMAX_MOTION_SHAKE_HZ_MIN,
            "lp_alpha": VMAX_MOTION_LP_ALPHA,
            "accel_shake_g": VMAX_MOTION_ACCEL_SHAKE_G,
            "sensor_cancel_gain": VMAX_MOTION_SENSOR_CANCEL_GAIN,
            "methods": ["kalman", "lowpass", "hybrid", "highfreq_reject"],
            "note_th": "กรองแรงสั่นโต๊ะออกจาก aim — ไม่ใช่ระบบโกง aimbot แค่ลด noise จากสภาพแวดล้อม",
        })

except Exception as _mf_exc:
    print("[MOTION FILTER] routes skip:", repr(_mf_exc))


def _run_motion_filter_selftest():
    ok = True
    f = VmaxMotionFilter("mf_test")
    # สัญญาณมือมนุษย์ (ช้า ทิศทางคงที่)
    r1 = f.filter_mouse_delta(5, 0, ts=1.0, method="hybrid")
    r2 = f.filter_mouse_delta(5, 0, ts=1.05, method="hybrid")
    ok &= abs(r2["dx"]) > 0
    # สั่นความถี่สูง สลับทิศ ขนาดเล็ก
    f2 = VmaxMotionFilter("mf_shake")
    t = 10.0
    for i in range(20):
        d = 3 if i % 2 == 0 else -3
        f2.filter_mouse_delta(d, d, ts=t + i * 0.02, method="highfreq_reject")  # ~50Hz
    st = f2.stats()
    ok &= st["shake_events"] >= 1
    # sensor cancel
    f3 = VmaxMotionFilter("mf_sensor")
    sc = f3.apply_sensor_cancel(10, 0, accel={"x": 0.3, "y": 0, "z": 1})
    ok &= sc["sensor_cancel"] is True and sc["dx"] < 10
    # API helper
    out = vmax_motion_filter("mf_api", 2, 2, method="kalman")
    ok &= "dx" in out
    print("MOTION FILTER SELFTEST:", "OK" if ok else "FAILED")
    return ok


