# ระดับเกราะที่รองรับในเกม
VMAX_ARMOR_LEVELS = ("II", "IIIA", "III", "IV")

# ค่าลด penetration ตามระยะ (เมตร) — ยิ่งไกล เจาะยากขึ้นเล็กน้อย
def _vmax_distance_penalty(distance_m: float) -> float:
    if distance_m <= 10:
        return 1.0
    if distance_m <= 50:
        return 1.0 - (distance_m - 10) * 0.004   # ลดช้า ๆ
    return max(0.55, 0.84 - (distance_m - 50) * 0.003)


def vmax_get_ammo_info(ammo_id: str) -> Optional[Dict[str, Any]]:
    """คืนข้อมูลกระสุนจากฐานข้อมูลอ้างอิง"""
    key = str(ammo_id or "").lower().strip().replace("-", "").replace("_", "")
    # รองรับชื่อย่อ
    aliases = {
        "ss190": "ss190",
        "ss197": "ss197sr",
        "ss197sr": "ss197sr",
        "ss196": "ss196sr",
        "ss196sr": "ss196sr",
        "ss198": "ss198lf",
        "ss198lf": "ss198lf",
        "ap": "armor_piercing",
        "hp": "hollow_point",
        "fmj": "standard",
    }
    resolved = aliases.get(key, key)
    return VMAX_AMMO_BALLISTIC_DB.get(resolved)


def vmax_resolve_ammo_vs_armor(
    ammo_id: str,
    armor_level: str = "IIIA",
    distance_m: float = 15.0,
    is_helmet: bool = False,
    from_long_barrel: bool = False,
) -> Dict[str, Any]:
    """
    คำนวณผลกระสุนกับเกราะ (ใช้ในเกม Extraction)

    คืนค่า:
      {
        "penetrated": bool,
        "pen_chance": float,          # 0.0-1.0
        "damage_mult": float,         # ตัวคูณดาเมจหลังผ่านเกราะ
        "final_damage": float,
        "armor_damage": float,        # ความเสียหายต่อเกราะ
        "msg": str,
        "ammo": dict,
      }
    """
    ammo = vmax_get_ammo_info(ammo_id)
    if not ammo:
        return {
            "penetrated": False,
            "pen_chance": 0.0,
            "damage_mult": 0.0,
            "final_damage": 0.0,
            "armor_damage": 0.0,
            "msg": f"ไม่พบข้อมูลกระสุน '{ammo_id}'",
            "ammo": None,
        }

    level = str(armor_level or "IIIA").upper().replace("LEVEL", "").strip()
    if level not in VMAX_ARMOR_LEVELS:
        level = "IIIA"

    base_pen = float(ammo.get("armor_pen", {}).get(level, 0.1))

    # โบนัสจากปืนยาว (ตามที่ภาพระบุว่า SS197 จาก AR57 ลำกล้อง 16" ผลเปลี่ยน)
    if from_long_barrel and ammo.get("type") in ("sporting", "armor_piercing"):
        base_pen = min(0.98, base_pen + 0.18)

    # โบนัสหมวกสำหรับ SS198LF (ตามที่ตั้งค่าในภาพ/เกม)
    if is_helmet and ammo.get("helmet_pen_bonus"):
        base_pen = min(0.95, base_pen + float(ammo["helmet_pen_bonus"]))

    # ลดตามระยะ
    pen_chance = base_pen * _vmax_distance_penalty(float(distance_m or 0))

    # สุ่มผล (ใช้ deterministic เล็กน้อยถ้าต้องการ replay)
    import random
    penetrated = random.random() < pen_chance

    if penetrated:
        # เจาะสำเร็จ → ดาเมจลดลงเล็กน้อยเพราะสูญเสียพลังงาน
        damage_mult = 0.75 + (pen_chance * 0.2)
        armor_damage = ammo["base_damage"] * 0.35
        msg = f"{ammo['name']} เจาะเกราะ {level} สำเร็จ"
    else:
        # ไม่เจาะ → ดาเมจต่อตัวน้อยมาก / ส่วนใหญ่ไปที่เกราะ
        damage_mult = 0.08 + (pen_chance * 0.12)
        armor_damage = ammo["base_damage"] * 0.85
        msg = f"{ammo['name']} ถูกเกราะ {level} หยุดไว้"

    final_damage = round(ammo["base_damage"] * damage_mult, 1)

    return {
        "penetrated": penetrated,
        "pen_chance": round(pen_chance, 3),
        "damage_mult": round(damage_mult, 3),
        "final_damage": final_damage,
        "armor_damage": round(armor_damage, 1),
        "msg": msg,
        "ammo": {
            "id": ammo_id,
            "name": ammo["name"],
            "caliber": ammo.get("caliber"),
            "type": ammo.get("type"),
            "color": ammo.get("color"),
            "notes": ammo.get("notes", ""),
        },
        "armor_level": level,
        "distance_m": distance_m,
    }


def vmax_list_5_7_ammo() -> Dict[str, Any]:
    """รายการกระสุน 5.7x28mm ทั้งหมดในระบบอ้างอิง"""
    out = {}
    for k, v in VMAX_AMMO_BALLISTIC_DB.items():
        if v.get("caliber") == "5.7x28mm":
            out[k] = {
                "name": v["name"],
                "type": v["type"],
                "color": v["color"],
                "base_damage": v["base_damage"],
                "armor_pen": v["armor_pen"],
                "notes": v.get("notes", ""),
            }
    return out


