# =====================================================================
# [ VMAX Role — admin guards on sensitive ops ]
# =====================================================================
def _vmax_role_guard_sensitive():
    try:
        if not callable(globals().get("vmax_admin_require")):
            return
    except Exception:
        return
    sensitive = [
        "_vmax_kernel_build",
        "vmax_stage_kernel_for_game",
        "vmax_stage_kernel_for_web",
        "_vmax_run_wallet_service",
    ]
    for name in sensitive:
        fn = globals().get(name)
        if callable(fn) and not getattr(fn, "_vmax_role_wrapped", False):
            def _make(f, n):
                def _w(*a, **k):
                    vmax_admin_require(n)
                    return f(*a, **k)
                _w.__name__ = getattr(f, "__name__", n)
                _w._vmax_role_wrapped = True
                return _w
            globals()[name] = _make(fn, name)

try:
    _vmax_role_guard_sensitive()
except Exception:
    pass

