# =====================================================================
# [ VMAX Network Mesh + Gameplay MCP Server + Tunnel / Overlay / Routing ]
# ---------------------------------------------------------------------
# รวมระบบจากแนวคิด:
#   1. Reverse Proxy / Tunneling (Localtonet / ngrok style)
#   2. Virtual LAN / Software-Defined Overlay (Tailscale / ZeroTier style)
#   3. Multi-Interface Routing Shifting
#   4. Gameplay MCP Server (Model Context Protocol) ฝังใน Runtime
#   5. Mesh Context-Sharing (Ad-hoc P2P + Mirrored Server)
#   6. Disaster Recovery / Virtual Server Shifting (เมื่อไฟดับ+เน็ตดับ)
#
# ใช้ได้ทั้งฝั่งเกม (player client) และฝั่งเว็บไซต์บริการ (Flask API)
# ไม่บังคับ dependency ภายนอก — ถ้ามี pyngrok / localtonet / tailscale CLI
# จะพยายามเรียกใช้จริง ถ้าไม่มีจะทำงานในโหมด simulate / config-only
# =====================================================================

import socket as _net_socket
import threading as _net_threading
import queue as _net_queue
import uuid as _net_uuid
import struct as _net_struct
from typing import Optional, Dict, Any, List, Callable, Tuple
from collections import defaultdict as _net_defaultdict
from datetime import datetime as _net_datetime

# --- soft optional imports ---
_VMAX_NGROK = None
try:
    from pyngrok import ngrok as _VMAX_NGROK
except Exception:
    _VMAX_NGROK = None

# =====================================================================
# 1. Reverse Proxy / Tunneling ส่วนตัว
# =====================================================================

_VMAX_TUNNELS: Dict[str, Dict[str, Any]] = {}
_VMAX_TUNNEL_LOCK = _net_threading.Lock()

def vmax_tunnel_status() -> Dict[str, Any]:
    """สถานะอุโมงค์ทั้งหมด"""
    with _VMAX_TUNNEL_LOCK:
        return {
            "tunnels": {k: {kk: vv for kk, vv in v.items() if kk != "process"}
                        for k, v in _VMAX_TUNNELS.items()},
            "pyngrok_available": _VMAX_NGROK is not None,
            "count": len(_VMAX_TUNNELS),
        }

def vmax_create_tunnel(
    local_port: int = 5000,
    protocol: str = "http",
    name: Optional[str] = None,
    provider: str = "simulate",  # "ngrok" | "localtonet" | "simulate"
    auth_token: Optional[str] = None,
    subdomain: Optional[str] = None,
) -> Dict[str, Any]:
    """
    สร้าง Public IP/Port จำลอง หรือจริง (ถ้ามี pyngrok)
    เพื่อให้ผู้เล่นภายนอกยิงข้อมูลตรงเข้าหา MCP Server ในเครื่องคุณได้
    โดยไม่ต้องพึ่งเซิร์ฟเวอร์กลางของเกม
    """
    tid = name or f"tunnel-{_net_uuid.uuid4().hex[:8]}"
    result = {
        "id": tid,
        "local_port": int(local_port),
        "protocol": protocol,
        "provider": provider,
        "public_url": None,
        "status": "pending",
        "created_at": _net_datetime.utcnow().isoformat() + "Z",
        "msg": "",
    }

    if provider == "ngrok" and _VMAX_NGROK is not None:
        try:
            if auth_token:
                _VMAX_NGROK.set_auth_token(auth_token)
            opts = {}
            if subdomain:
                opts["subdomain"] = subdomain
            tunnel = _VMAX_NGROK.connect(local_port, protocol, **opts)
            result["public_url"] = tunnel.public_url
            result["status"] = "active"
            result["msg"] = f"ngrok tunnel สำเร็จ → {tunnel.public_url}"
            result["tunnel_obj"] = True
        except Exception as exc:
            result["status"] = "error"
            result["msg"] = f"ngrok ล้มเหลว: {exc}"
            result["provider"] = "simulate"
            provider = "simulate"

    if provider in ("simulate", "localtonet"):
        # จำลอง public URL (ใช้ใน dev / เมื่อไม่มี token จริง)
        fake_host = subdomain or f"{tid}.vmax-tunnel.local"
        if protocol == "tcp":
            result["public_url"] = f"tcp://{fake_host}:{local_port + 10000}"
        else:
            result["public_url"] = f"https://{fake_host}"
        result["status"] = "simulated"
        result["msg"] = (
            f"โหมดจำลอง ({provider}) — public_url = {result['public_url']} "
            "(ตั้ง provider='ngrok' + auth_token เพื่อใช้จริง)"
        )

    with _VMAX_TUNNEL_LOCK:
        _VMAX_TUNNELS[tid] = result
    return {k: v for k, v in result.items() if k != "tunnel_obj"}

def vmax_close_tunnel(tunnel_id: str) -> Dict[str, Any]:
    with _VMAX_TUNNEL_LOCK:
        t = _VMAX_TUNNELS.pop(tunnel_id, None)
    if not t:
        return {"st": "error", "msg": f"ไม่พบ tunnel {tunnel_id}"}
    if t.get("provider") == "ngrok" and _VMAX_NGROK is not None:
        try:
            _VMAX_NGROK.disconnect(t.get("public_url") or "")
        except Exception:
            pass
    return {"st": "ok", "msg": f"ปิด {tunnel_id} แล้ว", "closed": t}

# =====================================================================
# 2. Virtual LAN / Overlay Network (Tailscale / ZeroTier style)
# =====================================================================

_VMAX_OVERLAY_NODES: Dict[str, Dict[str, Any]] = {}
_VMAX_OVERLAY_LOCK = _net_threading.Lock()

def vmax_overlay_join(
    node_id: Optional[str] = None,
    display_name: str = "player",
    network_id: str = "vmax-default",
    role: str = "peer",  # peer | gateway | host
) -> Dict[str, Any]:
    """
    เข้าร่วม Overlay Network จำลอง (Virtual LAN)
    เมื่อเกมตรวจจับว่าระบบเครือข่ายภายนอกล่ม ตัวเกมจะสลับมาใช้ overlay นี้
    เพื่อผูกคอมพิวเตอร์ของผู้เล่นเข้าเป็นวง LAN เดียวกันผ่านอินเทอร์เน็ต
    """
    nid = node_id or f"node-{_net_uuid.uuid4().hex[:10]}"
    # จำลอง IP ในวง overlay (100.x.y.z แบบ Tailscale CGNAT)
    with _VMAX_OVERLAY_LOCK:
        existing = [n for n in _VMAX_OVERLAY_NODES.values() if n["network_id"] == network_id]
        seq = len(existing) + 1
        virtual_ip = f"100.64.{(seq // 254) % 256}.{(seq % 254) + 1}"
        node = {
            "node_id": nid,
            "display_name": display_name,
            "network_id": network_id,
            "role": role,
            "virtual_ip": virtual_ip,
            "status": "online",
            "joined_at": _net_datetime.utcnow().isoformat() + "Z",
            "last_seen": _net_datetime.utcnow().isoformat() + "Z",
            "peers": [],
        }
        _VMAX_OVERLAY_NODES[nid] = node
        # อัปเดต peers ของทุกคนใน network เดียวกัน
        for other in _VMAX_OVERLAY_NODES.values():
            if other["network_id"] == network_id and other["node_id"] != nid:
                if nid not in other["peers"]:
                    other["peers"].append(nid)
                if other["node_id"] not in node["peers"]:
                    node["peers"].append(other["node_id"])
    return dict(node)

def vmax_overlay_leave(node_id: str) -> Dict[str, Any]:
    with _VMAX_OVERLAY_LOCK:
        node = _VMAX_OVERLAY_NODES.pop(node_id, None)
        if node:
            for other in _VMAX_OVERLAY_NODES.values():
                if node_id in other.get("peers", []):
                    other["peers"].remove(node_id)
    if not node:
        return {"st": "error", "msg": f"ไม่พบ node {node_id}"}
    return {"st": "ok", "left": node}

def vmax_overlay_list(network_id: Optional[str] = None) -> Dict[str, Any]:
    with _VMAX_OVERLAY_LOCK:
        nodes = list(_VMAX_OVERLAY_NODES.values())
        if network_id:
            nodes = [n for n in nodes if n["network_id"] == network_id]
    return {
        "st": "ok",
        "network_id": network_id or "all",
        "count": len(nodes),
        "nodes": nodes,
    }

def vmax_overlay_heartbeat(node_id: str) -> Dict[str, Any]:
    with _VMAX_OVERLAY_LOCK:
        node = _VMAX_OVERLAY_NODES.get(node_id)
        if not node:
            return {"st": "error", "msg": "node not found"}
        node["last_seen"] = _net_datetime.utcnow().isoformat() + "Z"
        node["status"] = "online"
    return {"st": "ok", "node_id": node_id, "last_seen": node["last_seen"]}

# =====================================================================
# 3. Multi-Interface Routing Shifting
# =====================================================================

_VMAX_ROUTING_TABLE: Dict[str, Any] = {
    "default_interface": "eth0",
    "game_bind_ip": None,          # ถ้าตั้ง จะบังคับ game traffic ออก interface นี้
    "interfaces": {},
    "shift_history": [],
}

def vmax_detect_interfaces() -> Dict[str, Any]:
    """ตรวจจับ network interfaces ที่มีในเครื่อง (ใช้ stdlib)"""
    ifaces = {}
    try:
        import netifaces  # optional
        for name in netifaces.interfaces():
            addrs = netifaces.ifaddresses(name)
            ipv4 = addrs.get(netifaces.AF_INET, [])
            ifaces[name] = {
                "ipv4": [a.get("addr") for a in ipv4 if a.get("addr")],
                "up": True,
            }
    except Exception:
        # fallback: ใช้ hostname / 127.0.0.1
        hostname = _net_socket.gethostname()
        try:
            local_ip = _net_socket.gethostbyname(hostname)
        except Exception:
            local_ip = "127.0.0.1"
        ifaces = {
            "lo": {"ipv4": ["127.0.0.1"], "up": True},
            "primary": {"ipv4": [local_ip], "up": True},
        }
    _VMAX_ROUTING_TABLE["interfaces"] = ifaces
    return {"st": "ok", "interfaces": ifaces}

def vmax_set_game_bind_ip(ip: Optional[str], interface: Optional[str] = None) -> Dict[str, Any]:
    """
    บังคับให้เกม bind / ส่ง-รับ ข้อมูลเครือข่ายเกมผ่าน Network Interface ที่ 2
    แยกจากทราฟฟิกอินเทอร์เน็ตปกติ
    """
    prev = _VMAX_ROUTING_TABLE.get("game_bind_ip")
    _VMAX_ROUTING_TABLE["game_bind_ip"] = ip
    if interface:
        _VMAX_ROUTING_TABLE["default_interface"] = interface
    entry = {
        "from": prev,
        "to": ip,
        "interface": interface,
        "at": _net_datetime.utcnow().isoformat() + "Z",
    }
    _VMAX_ROUTING_TABLE["shift_history"].append(entry)
    if len(_VMAX_ROUTING_TABLE["shift_history"]) > 50:
        _VMAX_ROUTING_TABLE["shift_history"] = _VMAX_ROUTING_TABLE["shift_history"][-50:]
    return {
        "st": "ok",
        "game_bind_ip": ip,
        "interface": interface or _VMAX_ROUTING_TABLE["default_interface"],
        "msg": f"เกมจะส่ง/รับผ่าน {ip or 'default'} แล้ว" if ip else "กลับไปใช้ default interface",
        "history_len": len(_VMAX_ROUTING_TABLE["shift_history"]),
    }

def vmax_routing_status() -> Dict[str, Any]:
    if not _VMAX_ROUTING_TABLE.get("interfaces"):
        vmax_detect_interfaces()
    return {
        "st": "ok",
        **{k: v for k, v in _VMAX_ROUTING_TABLE.items()},
    }

# =====================================================================
# 4. Gameplay MCP Server (Model Context Protocol)
# ---------------------------------------------------------------------
# แต่ละตัวเกมทำหน้าที่เป็น MCP Host/Client ที่รัน MCP Server ภายในตัวเอง
# (Local stdio / JSON-RPC) คอยรวบรวม "บริบท (Context)", สถานะเกม,
# ดาต้าเบสจำลอง และตรรกะทั้งหมด แล้วแปลงเป็นชุดข้อมูลมาตรฐาน
# =====================================================================

class VMaxMCPServer:
    """
    Lightweight in-process MCP-style context server
    ใช้ JSON-RPC แบบง่าย ๆ สำหรับ share game state / context
    """
    def __init__(self, server_id: Optional[str] = None, name: str = "vmax-mcp"):
        self.server_id = server_id or f"mcp-{_net_uuid.uuid4().hex[:8]}"
        self.name = name
        self.context: Dict[str, Any] = {
            "game_state": {},
            "players": {},
            "world": {},
            "session": {},
            "custom": {},
        }
        self.subscribers: Dict[str, Callable] = {}
        self.lock = _net_threading.RLock()
        self.running = False
        self.created_at = _net_datetime.utcnow().isoformat() + "Z"
        self.version = "1.0.0"

    def update_context(self, path: str, value: Any) -> None:
        """อัปเดต context ตาม path เช่น 'game_state.score' หรือ 'players.uid123'"""
        with self.lock:
            parts = path.split(".")
            d = self.context
            for p in parts[:-1]:
                if p not in d or not isinstance(d[p], dict):
                    d[p] = {}
                d = d[p]
            d[parts[-1]] = value
            self._notify(path, value)

    def get_context(self, path: Optional[str] = None) -> Any:
        with self.lock:
            if not path:
                return dict(self.context)
            parts = path.split(".")
            d = self.context
            for p in parts:
                if not isinstance(d, dict) or p not in d:
                    return None
                d = d[p]
            return d

    def merge_context(self, data: Dict[str, Any], prefix: str = "") -> None:
        with self.lock:
            for k, v in data.items():
                full = f"{prefix}.{k}" if prefix else k
                if isinstance(v, dict) and isinstance(self.get_context(full), dict):
                    self.merge_context(v, full)
                else:
                    self.update_context(full, v)

    def subscribe(self, sub_id: str, callback: Callable) -> None:
        self.subscribers[sub_id] = callback

    def unsubscribe(self, sub_id: str) -> None:
        self.subscribers.pop(sub_id, None)

    def _notify(self, path: str, value: Any) -> None:
        for cb in list(self.subscribers.values()):
            try:
                cb(path, value)
            except Exception:
                pass

    def handle_rpc(self, request: Dict[str, Any]) -> Dict[str, Any]:
        """รับ JSON-RPC request แบบง่าย"""
        method = request.get("method", "")
        params = request.get("params") or {}
        req_id = request.get("id")
        try:
            if method == "context/get":
                result = self.get_context(params.get("path"))
            elif method == "context/set":
                self.update_context(params["path"], params["value"])
                result = {"ok": True}
            elif method == "context/merge":
                self.merge_context(params.get("data") or {}, params.get("prefix", ""))
                result = {"ok": True}
            elif method == "context/snapshot":
                result = self.get_context()
            elif method == "server/info":
                result = {
                    "server_id": self.server_id,
                    "name": self.name,
                    "version": self.version,
                    "created_at": self.created_at,
                }
            else:
                return {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "error": {"code": -32601, "message": f"Method not found: {method}"},
                }
            return {"jsonrpc": "2.0", "id": req_id, "result": result}
        except Exception as exc:
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "error": {"code": -32000, "message": str(exc)},
            }

    def to_dict(self) -> Dict[str, Any]:
        return {
            "server_id": self.server_id,
            "name": self.name,
            "version": self.version,
            "created_at": self.created_at,
            "context_keys": list(self.context.keys()),
            "subscriber_count": len(self.subscribers),
        }


_VMAX_MCP_SERVERS: Dict[str, VMaxMCPServer] = {}
_VMAX_MCP_LOCK = _net_threading.Lock()
_VMAX_DEFAULT_MCP: Optional[VMaxMCPServer] = None

def vmax_mcp_create(name: str = "gameplay-mcp", server_id: Optional[str] = None) -> Dict[str, Any]:
    global _VMAX_DEFAULT_MCP
    srv = VMaxMCPServer(server_id=server_id, name=name)
    with _VMAX_MCP_LOCK:
        _VMAX_MCP_SERVERS[srv.server_id] = srv
        if _VMAX_DEFAULT_MCP is None:
            _VMAX_DEFAULT_MCP = srv
    return {"st": "ok", **srv.to_dict()}

def vmax_mcp_get(server_id: Optional[str] = None) -> Optional[VMaxMCPServer]:
    if server_id:
        return _VMAX_MCP_SERVERS.get(server_id)
    return _VMAX_DEFAULT_MCP

def vmax_mcp_list() -> Dict[str, Any]:
    with _VMAX_MCP_LOCK:
        return {
            "st": "ok",
            "count": len(_VMAX_MCP_SERVERS),
            "servers": [s.to_dict() for s in _VMAX_MCP_SERVERS.values()],
        }

def vmax_mcp_rpc(server_id: Optional[str], request: Dict[str, Any]) -> Dict[str, Any]:
    srv = vmax_mcp_get(server_id)
    if not srv:
        return {"jsonrpc": "2.0", "id": request.get("id"), "error": {"code": -32001, "message": "MCP server not found"}}
    return srv.handle_rpc(request)

# =====================================================================
# 5. Mesh Context-Sharing (Ad-hoc P2P + Mirrored Server Architecture)
# =====================================================================

_VMAX_MESH: Dict[str, Any] = {
    "enabled": False,
    "mode": "idle",          # idle | mesh | gateway | disaster
    "local_nodes": [],
    "gateway_node": None,
    "shared_context": {},
    "last_sync": None,
}

def vmax_mesh_enable(mode: str = "mesh") -> Dict[str, Any]:
    """
    เปิด Mesh Context-Sharing
    เมื่อเน็ตมือถือภายนอกตัดขาด → ใช้สัญญาณที่ยังเหลือ (Local WiFi / BT Ad-hoc / P2P Mesh)
    ตัวที่เป็น Gateway จะแบ่งปันท่อข้อมูลและ Context เสมือนสร้างเครือข่ายอินเทอร์เน็ตจำลอง
    """
    _VMAX_MESH["enabled"] = True
    _VMAX_MESH["mode"] = mode
    _VMAX_MESH["last_sync"] = _net_datetime.utcnow().isoformat() + "Z"
    return {"st": "ok", "mesh": dict(_VMAX_MESH)}

def vmax_mesh_disable() -> Dict[str, Any]:
    _VMAX_MESH["enabled"] = False
    _VMAX_MESH["mode"] = "idle"
    return {"st": "ok", "mesh": dict(_VMAX_MESH)}

def vmax_mesh_share_context(context: Dict[str, Any], from_node: str = "local") -> Dict[str, Any]:
    """กระจาย context ไปยัง mesh (และ mirror เข้า MCP ถ้ามี)"""
    _VMAX_MESH["shared_context"].update(context)
    _VMAX_MESH["last_sync"] = _net_datetime.utcnow().isoformat() + "Z"
    # mirror ไป default MCP
    mcp = vmax_mcp_get()
    if mcp:
        mcp.merge_context(context, prefix="mesh")
    return {
        "st": "ok",
        "from_node": from_node,
        "keys": list(context.keys()),
        "last_sync": _VMAX_MESH["last_sync"],
    }

def vmax_mesh_status() -> Dict[str, Any]:
    return {"st": "ok", **{k: v for k, v in _VMAX_MESH.items()}}

# =====================================================================
# 6. Disaster Recovery / Virtual Server Shifting
# =====================================================================

_VMAX_DISASTER: Dict[str, Any] = {
    "active": False,
    "reason": None,
    "virtual_server_id": None,
    "sandbox_context": {},
    "activated_at": None,
}

def vmax_disaster_activate(reason: str = "power_and_network_outage") -> Dict[str, Any]:
    """
    เมื่อเกิดวิกฤต "ไฟดับ + เน็ตดับพร้อมกัน"
    ตัว MCP Server ที่ฝังในเครื่องผู้เล่นจะแปลงร่างเป็น Virtual Server Shifting
    สร้างสภาพแวดล้อมจำลอง (Sandboxed) ป้อนข้อมูลบริบทจำลอง (Mocked Internet Context)
    เพื่อให้เกมเพลย์ลูปยังทำงานต่อได้
    """
    vsid = f"vs-{_net_uuid.uuid4().hex[:8]}"
    _VMAX_DISASTER.update({
        "active": True,
        "reason": reason,
        "virtual_server_id": vsid,
        "activated_at": _net_datetime.utcnow().isoformat() + "Z",
        "sandbox_context": {
            "mocked_internet": True,
            "local_only": True,
            "message": "ระบบทำงานในโหมดกู้ภัย — ใช้ข้อมูลบริบทจำลอง",
        },
    })
    # สร้าง MCP เฉพาะสำหรับ disaster
    mcp = vmax_mcp_create(name=f"disaster-{vsid}", server_id=vsid)
    srv = vmax_mcp_get(vsid)
    if srv:
        srv.merge_context(_VMAX_DISASTER["sandbox_context"], prefix="disaster")
        # คัดลอก context เดิมมาเท่าที่ทำได้
        default = vmax_mcp_get()
        if default and default.server_id != vsid:
            snap = default.get_context()
            if snap:
                srv.merge_context(snap, prefix="mirrored")
    # เปิด mesh ในโหมด disaster
    vmax_mesh_enable(mode="disaster")
    return {
        "st": "ok",
        "disaster": dict(_VMAX_DISASTER),
        "mcp": mcp,
        "msg": "Virtual Server Shifting เปิดใช้งานแล้ว — เกมเพลย์ลูปยังทำงานต่อได้ในสภาพแวดล้อมจำลอง",
    }

def vmax_disaster_deactivate() -> Dict[str, Any]:
    _VMAX_DISASTER.update({
        "active": False,
        "reason": None,
        "virtual_server_id": None,
        "sandbox_context": {},
        "activated_at": None,
    })
    vmax_mesh_disable()
    return {"st": "ok", "msg": "กลับสู่โหมดปกติ", "disaster": dict(_VMAX_DISASTER)}

def vmax_disaster_status() -> Dict[str, Any]:
    return {"st": "ok", **dict(_VMAX_DISASTER)}

