# =====================================================================
# 7. Hierarchical / Nested Micro-Agent MCP Architecture
# ---------------------------------------------------------------------
# โครงสร้าง MCP แบบรังนกซ้อนกัน (Nested / Hierarchical MCP)
#
# Parent MCP = "ผู้จัดการใหญ่" คอยสั่งงาน
# Child MCPs = "พนักงานเฉพาะทาง" ที่ทำงานภายใต้คำสั่ง โดยแยก Context เด็ดขาด
#              (Micro-Context Isolation) ทำให้ใช้ CPU/RAM น้อยมาก
#              และระบบตายแล้วฟื้นเองได้ (Self-Healing / Respawn)
#
# ตัวอย่าง Child ตามแนวคิดจากเอกสาร:
#   1. network_signal   – ตัวคุมสัญญาณเครือข่ายย่อย (hotspot / local mesh)
#   2. item_storage     – ตัวจัดการคลังไอเทมเฉพาะกิจ (Context Ticket)
#   3. validation       – ตัวตรวจสอบการโกง / ปลอมแปลงค่าพลัง / ปั๊มเงิน
#
# เพิ่มเติมแนวคิด "กระจายอินเทอร์เน็ต + ที่เก็บข้อมูล MCP":
#   - MCP Storage Node: ย้าย context / snapshot ไปเก็บบน node อื่นใน mesh
#     เพื่อลดภาระเครื่องหลัก (offload storage)
#   - MCP Relay / Internet Distribution: node ที่มีเน็ตคอยเป็น gateway
#     ส่งต่อ context/RPC ให้ node ที่ไม่มีเน็ต (เหมือนกระจายอินเทอร์เน็ต
#     ให้ที่เก็บข้อมูลเพื่อให้ MCP ส่งต่อกันได้)
# =====================================================================

from enum import Enum as _net_Enum

class VMaxMCPRole(_net_Enum):
    PARENT = "parent"
    CHILD = "child"
    STORAGE = "storage"      # ที่เก็บ context แบบ offload
    RELAY = "relay"          # ตัวส่งต่อเน็ต / context ระหว่าง node


class VMaxChildMCPKind(_net_Enum):
    NETWORK_SIGNAL = "network_signal"   # Child #1 ตัวคุมสัญญาณเครือข่ายย่อย
    ITEM_STORAGE = "item_storage"       # Child #2 ตัวจัดการคลังไอเทมเฉพาะกิจ
    VALIDATION = "validation"           # Child #3 ตัวตรวจสอบการโกง
    CUSTOM = "custom"


# --- extended MCP server ที่รองรับ hierarchy + isolation + self-healing ---

class VMaxHierarchicalMCPServer(VMaxMCPServer):
    """
    MCP Server ที่รองรับ:
      - Parent / Child nesting
      - Micro-Context Isolation (แต่ละ child มี context แคบของตัวเอง)
      - Self-Healing / Respawn เมื่อ child ตาย
      - Storage offload (ย้าย context ไป node อื่น)
      - Relay (ส่งต่อ RPC/context ผ่าน mesh)
    """

    def __init__(
        self,
        server_id: Optional[str] = None,
        name: str = "vmax-hier-mcp",
        role: VMaxMCPRole = VMaxMCPRole.PARENT,
        kind: Optional[VMaxChildMCPKind] = None,
        parent_id: Optional[str] = None,
        isolated_context_keys: Optional[List[str]] = None,
    ):
        super().__init__(server_id=server_id, name=name)
        self.role = role
        self.kind = kind
        self.parent_id = parent_id
        self.children: Dict[str, str] = {}          # child_id -> kind value
        self.isolated = bool(isolated_context_keys)
        # ถ้าเป็น child จะจำกัด context เฉพาะ keys ที่กำหนด (Micro-Context Isolation)
        if isolated_context_keys:
            self.context = {k: {} for k in isolated_context_keys}
        self.health = "alive"                       # alive | degraded | dead
        self.respawn_count = 0
        self.max_respawn = 5
        self.storage_nodes: List[str] = []          # server_ids ที่ offload ไป
        self.relay_peers: List[str] = []            # peer ที่ใช้ส่งต่อ
        self.resource_budget = {                    # จำกัดทรัพยากรต่อ child
            "max_context_keys": 64 if role == VMaxMCPRole.CHILD else 1024,
            "max_subscribers": 8 if role == VMaxMCPRole.CHILD else 64,
            "cpu_hint": "low" if role == VMaxMCPRole.CHILD else "normal",
        }
        self.version = "2.0.0-hierarchical"

    # ----- hierarchy helpers -----

    def attach_child(self, child_id: str, kind: str) -> None:
        with self.lock:
            self.children[child_id] = kind

    def detach_child(self, child_id: str) -> None:
        with self.lock:
            self.children.pop(child_id, None)

    def mark_dead(self) -> None:
        with self.lock:
            self.health = "dead"
            self.running = False

    def mark_alive(self) -> None:
        with self.lock:
            self.health = "alive"
            self.running = True

    def can_respawn(self) -> bool:
        return self.respawn_count < self.max_respawn

    def bump_respawn(self) -> None:
        with self.lock:
            self.respawn_count += 1
            self.health = "alive"
            self.running = True

    # ----- isolated context update (ไม่วนสมองส่วนอื่น) -----

    def update_context(self, path: str, value: Any) -> None:
        with self.lock:
            if self.isolated:
                root = path.split(".", 1)[0]
                if root not in self.context:
                    # ไม่อนุญาตให้ child แตะ context นอก scope
                    return
            super().update_context(path, value)

    def to_dict(self) -> Dict[str, Any]:
        base = super().to_dict()
        base.update({
            "role": self.role.value if isinstance(self.role, VMaxMCPRole) else self.role,
            "kind": self.kind.value if isinstance(self.kind, VMaxChildMCPKind) else self.kind,
            "parent_id": self.parent_id,
            "children": dict(self.children),
            "health": self.health,
            "respawn_count": self.respawn_count,
            "isolated": self.isolated,
            "storage_nodes": list(self.storage_nodes),
            "relay_peers": list(self.relay_peers),
            "resource_budget": dict(self.resource_budget),
        })
        return base

    def handle_rpc(self, request: Dict[str, Any]) -> Dict[str, Any]:
        """ขยาย RPC ให้รองรับ hierarchy / health / offload"""
        method = request.get("method", "")
        params = request.get("params") or {}
        req_id = request.get("id")

        # methods เฉพาะ hierarchical
        if method == "hierarchy/info":
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "result": self.to_dict(),
            }
        if method == "hierarchy/children":
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "result": {"children": dict(self.children)},
            }
        if method == "health/get":
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "result": {
                    "health": self.health,
                    "respawn_count": self.respawn_count,
                    "running": self.running,
                },
            }
        if method == "health/mark_dead":
            self.mark_dead()
            return {"jsonrpc": "2.0", "id": req_id, "result": {"ok": True, "health": "dead"}}
        if method == "storage/list":
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "result": {"storage_nodes": list(self.storage_nodes)},
            }
        # fallback ไป base
        return super().handle_rpc(request)


# registry แยกสำหรับ hierarchical (ยังเชื่อมกับ registry เดิมได้)
_VMAX_HIER_MCP: Dict[str, VMaxHierarchicalMCPServer] = {}
_VMAX_HIER_LOCK = _net_threading.Lock()
_VMAX_HIER_DEFAULT_PARENT: Optional[str] = None


def _hier_register(srv: VMaxHierarchicalMCPServer) -> None:
    with _VMAX_HIER_LOCK:
        _VMAX_HIER_MCP[srv.server_id] = srv
    # mirror เข้า registry เดิมด้วย เพื่อให้ API เก่าเรียกได้
    with _VMAX_MCP_LOCK:
        _VMAX_MCP_SERVERS[srv.server_id] = srv


def _hier_get(server_id: Optional[str] = None) -> Optional[VMaxHierarchicalMCPServer]:
    if server_id:
        return _VMAX_HIER_MCP.get(server_id)
    if _VMAX_HIER_DEFAULT_PARENT:
        return _VMAX_HIER_MCP.get(_VMAX_HIER_DEFAULT_PARENT)
    return None


# ----- factory: สร้าง Parent MCP -----

def vmax_hier_create_parent(
    name: str = "parent-mcp",
    server_id: Optional[str] = None,
) -> Dict[str, Any]:
    """
    สร้าง Parent MCP (ผู้จัดการใหญ่)
    """
    global _VMAX_HIER_DEFAULT_PARENT
    srv = VMaxHierarchicalMCPServer(
        server_id=server_id,
        name=name,
        role=VMaxMCPRole.PARENT,
    )
    srv.mark_alive()
    _hier_register(srv)
    if _VMAX_HIER_DEFAULT_PARENT is None:
        _VMAX_HIER_DEFAULT_PARENT = srv.server_id
    return {"st": "ok", **srv.to_dict()}


# ----- factory: สร้าง Child MCP ตามชนิดมาตรฐาน -----

_CHILD_ISOLATION_MAP = {
    VMaxChildMCPKind.NETWORK_SIGNAL: ["network", "signal", "hotspot", "mesh_local"],
    VMaxChildMCPKind.ITEM_STORAGE: ["items", "inventory", "context_ticket", "queue"],
    VMaxChildMCPKind.VALIDATION: ["validation", "anti_cheat", "integrity", "flags"],
    VMaxChildMCPKind.CUSTOM: ["custom"],
}


def vmax_hier_spawn_child(
    kind: str = "network_signal",
    parent_id: Optional[str] = None,
    name: Optional[str] = None,
    server_id: Optional[str] = None,
    custom_isolation_keys: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """
    สร้าง Child MCP ภายใต้ Parent
    kind: network_signal | item_storage | validation | custom
    """
    parent_id = parent_id or _VMAX_HIER_DEFAULT_PARENT
    parent = _hier_get(parent_id)
    if not parent or parent.role != VMaxMCPRole.PARENT:
        # auto-create parent ถ้ายังไม่มี
        p = vmax_hier_create_parent()
        parent_id = p["server_id"]
        parent = _hier_get(parent_id)

    try:
        kind_enum = VMaxChildMCPKind(kind)
    except ValueError:
        kind_enum = VMaxChildMCPKind.CUSTOM

    isolation = custom_isolation_keys or _CHILD_ISOLATION_MAP.get(kind_enum, ["custom"])
    child_name = name or f"child-{kind_enum.value}"
    child = VMaxHierarchicalMCPServer(
        server_id=server_id,
        name=child_name,
        role=VMaxMCPRole.CHILD,
        kind=kind_enum,
        parent_id=parent_id,
        isolated_context_keys=isolation,
    )
    child.mark_alive()
    _hier_register(child)
    if parent:
        parent.attach_child(child.server_id, kind_enum.value)

    return {
        "st": "ok",
        "msg": f"Child MCP '{child_name}' ({kind_enum.value}) spawned under parent {parent_id}",
        **child.to_dict(),
    }


def vmax_hier_spawn_standard_trio(parent_id: Optional[str] = None) -> Dict[str, Any]:
    """
    สร้าง Child ทั้ง 3 ตัวมาตรฐานในคำเดียว:
      1. network_signal
      2. item_storage
      3. validation
    """
    results = []
    for k in (
        VMaxChildMCPKind.NETWORK_SIGNAL,
        VMaxChildMCPKind.ITEM_STORAGE,
        VMaxChildMCPKind.VALIDATION,
    ):
        results.append(vmax_hier_spawn_child(kind=k.value, parent_id=parent_id))
    return {
        "st": "ok",
        "msg": "Standard trio (network_signal, item_storage, validation) spawned",
        "children": results,
        "parent_id": parent_id or _VMAX_HIER_DEFAULT_PARENT,
    }


# ----- Self-Healing / Respawn -----

def vmax_hier_kill_child(child_id: str, reason: str = "manual") -> Dict[str, Any]:
    """
    จำลองการตายของ Child (เช่น validation ค้างเพราะถูก flood)
    Parent ยังทำงานต่อได้ — เกมไม่ล่ม
    """
    child = _hier_get(child_id)
    if not child or child.role != VMaxMCPRole.CHILD:
        return {"st": "error", "msg": f"Child {child_id} not found"}
    child.mark_dead()
    return {
        "st": "ok",
        "msg": f"Child {child_id} marked dead (reason={reason}). Parent still alive.",
        "child": child.to_dict(),
    }


def vmax_hier_respawn_child(child_id: str) -> Dict[str, Any]:
    """
    Parent สั่ง Respawn Child ที่ตาย
    เหมือนเกมที่ตัวละครตายแล้วเกิดใหม่ — ระบบหลักไม่ล่ม
    """
    old = _hier_get(child_id)
    if not old or old.role != VMaxMCPRole.CHILD:
        return {"st": "error", "msg": f"Child {child_id} not found"}
    if old.health != "dead" and old.health != "degraded":
        return {"st": "ok", "msg": "Child still alive, no respawn needed", "child": old.to_dict()}
    if not old.can_respawn():
        return {"st": "error", "msg": f"Max respawn ({old.max_respawn}) reached for {child_id}"}

    # สร้าง instance ใหม่ด้วย id เดิม (หรือ id ใหม่แล้วอัปเดต parent)
    kind_val = old.kind.value if isinstance(old.kind, VMaxChildMCPKind) else (old.kind or "custom")
    isolation = list(old.context.keys()) if old.isolated else None
    new_child = VMaxHierarchicalMCPServer(
        server_id=old.server_id,  # reuse id เพื่อให้ parent ชี้ตัวเดิม
        name=old.name,
        role=VMaxMCPRole.CHILD,
        kind=old.kind,
        parent_id=old.parent_id,
        isolated_context_keys=isolation,
    )
    new_child.respawn_count = old.respawn_count + 1
    new_child.mark_alive()
    # คัดลอก context เก่าเท่าที่ปลอดภัย (ถ้ามี)
    try:
        snap = old.get_context()
        if snap:
            new_child.merge_context(snap)
    except Exception:
        pass
    _hier_register(new_child)
    parent = _hier_get(old.parent_id)
    if parent:
        parent.attach_child(new_child.server_id, kind_val)

    return {
        "st": "ok",
        "msg": f"Child {child_id} respawned (count={new_child.respawn_count})",
        "child": new_child.to_dict(),
    }


def vmax_hier_auto_heal(parent_id: Optional[str] = None) -> Dict[str, Any]:
    """
    ตรวจ Child ทั้งหมดของ Parent แล้ว Respawn ตัวที่ตายอัตโนมัติ
    """
    parent_id = parent_id or _VMAX_HIER_DEFAULT_PARENT
    parent = _hier_get(parent_id)
    if not parent:
        return {"st": "error", "msg": "No parent MCP"}
    healed = []
    failed = []
    for cid in list(parent.children.keys()):
        child = _hier_get(cid)
        if child and child.health in ("dead", "degraded"):
            r = vmax_hier_respawn_child(cid)
            if r.get("st") == "ok":
                healed.append(cid)
            else:
                failed.append({"id": cid, "err": r.get("msg")})
    return {
        "st": "ok",
        "parent_id": parent_id,
        "healed": healed,
        "failed": failed,
        "msg": f"Auto-heal done: {len(healed)} respawned, {len(failed)} failed",
    }


# ----- Micro-Context Isolation helpers -----

def vmax_hier_child_context_get(child_id: str, path: Optional[str] = None) -> Dict[str, Any]:
    child = _hier_get(child_id)
    if not child:
        return {"st": "error", "msg": "Child not found"}
    return {"st": "ok", "context": child.get_context(path), "isolated": child.isolated}


def vmax_hier_child_context_set(
    child_id: str,
    path: str,
    value: Any,
) -> Dict[str, Any]:
    """
    อัปเดต context ของ Child เท่านั้น — ไม่กระทบ Parent หรือ sibling
    (Micro-Context Isolation)
    """
    child = _hier_get(child_id)
    if not child:
        return {"st": "error", "msg": "Child not found"}
    child.update_context(path, value)
    return {"st": "ok", "path": path, "isolated": child.isolated}


# =====================================================================
# 8. Distributed MCP Storage + Internet Relay (Offload)
# ---------------------------------------------------------------------
# แนวคิด: กระจาย "ที่เก็บข้อมูล MCP" ไปยัง node อื่นใน mesh
# และใช้ node ที่มีเน็ตเป็น Relay ส่งต่อ context/RPC
# → เครื่องหลักไม่ต้องทำงานหนัก (ลด CPU/RAM)
# =====================================================================

_VMAX_MCP_STORAGE: Dict[str, Dict[str, Any]] = {}
# structure: storage_id -> {
#   "node_id": str,
#   "owner_mcp": str,          # MCP ที่ offload มา
#   "blobs": { key: payload }, # context snapshots / tickets
#   "size_bytes": int,
#   "max_bytes": int,
#   "created_at": iso,
# }

_VMAX_MCP_STORAGE_LOCK = _net_threading.Lock()
_VMAX_DEFAULT_STORAGE_MAX = 2 * 1024 * 1024  # 2 MB ต่อ storage node (เบา)


def vmax_mcp_storage_create(
    node_id: Optional[str] = None,
    owner_mcp: Optional[str] = None,
    max_bytes: int = _VMAX_DEFAULT_STORAGE_MAX,
    storage_id: Optional[str] = None,
) -> Dict[str, Any]:
    """
    สร้าง MCP Storage Node ขนาดเล็ก (ที่เก็บ context แบบ offload)
    ใช้เก็บบนเครื่องอื่น / node อื่นใน mesh เพื่อลดภาระเครื่องหลัก
    """
    sid = storage_id or f"stor-{_net_uuid.uuid4().hex[:8]}"
    nid = node_id or f"node-{_net_uuid.uuid4().hex[:6]}"
    with _VMAX_MCP_STORAGE_LOCK:
        _VMAX_MCP_STORAGE[sid] = {
            "storage_id": sid,
            "node_id": nid,
            "owner_mcp": owner_mcp,
            "blobs": {},
            "size_bytes": 0,
            "max_bytes": int(max_bytes),
            "created_at": _net_datetime.utcnow().isoformat() + "Z",
        }
    # ถ้ามี hierarchical MCP ที่เป็น owner ให้ผูก storage_nodes
    if owner_mcp:
        srv = _hier_get(owner_mcp) or vmax_mcp_get(owner_mcp)
        if srv and hasattr(srv, "storage_nodes"):
            if sid not in srv.storage_nodes:
                srv.storage_nodes.append(sid)
    return {"st": "ok", **_VMAX_MCP_STORAGE[sid]}


def vmax_mcp_storage_put(
    storage_id: str,
    key: str,
    payload: Any,
) -> Dict[str, Any]:
    """
    เก็บ blob (context snapshot / ticket / raw data) ลง storage node
    """
    import json as _json_local
    with _VMAX_MCP_STORAGE_LOCK:
        stor = _VMAX_MCP_STORAGE.get(storage_id)
        if not stor:
            return {"st": "error", "msg": "Storage not found"}
        try:
            raw = _json_local.dumps(payload, ensure_ascii=False, default=str)
        except Exception:
            raw = str(payload)
        size = len(raw.encode("utf-8"))
        old = stor["blobs"].get(key)
        old_size = 0
        if old is not None:
            try:
                old_size = len(_json_local.dumps(old, ensure_ascii=False, default=str).encode("utf-8"))
            except Exception:
                old_size = 0
        new_total = stor["size_bytes"] - old_size + size
        if new_total > stor["max_bytes"]:
            return {
                "st": "error",
                "msg": f"Storage full ({new_total} > {stor['max_bytes']})",
            }
        stor["blobs"][key] = payload
        stor["size_bytes"] = new_total
        return {
            "st": "ok",
            "storage_id": storage_id,
            "key": key,
            "size_bytes": size,
            "total_bytes": stor["size_bytes"],
        }


def vmax_mcp_storage_get(storage_id: str, key: str) -> Dict[str, Any]:
    with _VMAX_MCP_STORAGE_LOCK:
        stor = _VMAX_MCP_STORAGE.get(storage_id)
        if not stor:
            return {"st": "error", "msg": "Storage not found"}
        if key not in stor["blobs"]:
            return {"st": "error", "msg": f"Key '{key}' not found"}
        return {"st": "ok", "key": key, "payload": stor["blobs"][key]}


def vmax_mcp_storage_delete(storage_id: str, key: Optional[str] = None) -> Dict[str, Any]:
    import json as _json_local
    with _VMAX_MCP_STORAGE_LOCK:
        stor = _VMAX_MCP_STORAGE.get(storage_id)
        if not stor:
            return {"st": "error", "msg": "Storage not found"}
        if key is None:
            # ลบทั้ง node
            _VMAX_MCP_STORAGE.pop(storage_id, None)
            return {"st": "ok", "msg": f"Storage {storage_id} removed"}
        if key in stor["blobs"]:
            try:
                old_size = len(
                    _json_local.dumps(stor["blobs"][key], ensure_ascii=False, default=str).encode("utf-8")
                )
            except Exception:
                old_size = 0
            del stor["blobs"][key]
            stor["size_bytes"] = max(0, stor["size_bytes"] - old_size)
            return {"st": "ok", "msg": f"Key '{key}' deleted", "total_bytes": stor["size_bytes"]}
        return {"st": "error", "msg": f"Key '{key}' not found"}


def vmax_mcp_storage_list(owner_mcp: Optional[str] = None) -> Dict[str, Any]:
    with _VMAX_MCP_STORAGE_LOCK:
        items = []
        for sid, s in _VMAX_MCP_STORAGE.items():
            if owner_mcp and s.get("owner_mcp") != owner_mcp:
                continue
            items.append({
                "storage_id": sid,
                "node_id": s["node_id"],
                "owner_mcp": s.get("owner_mcp"),
                "blob_count": len(s["blobs"]),
                "size_bytes": s["size_bytes"],
                "max_bytes": s["max_bytes"],
                "created_at": s["created_at"],
            })
        return {"st": "ok", "count": len(items), "storages": items}


def vmax_mcp_offload_context(
    mcp_id: str,
    storage_id: Optional[str] = None,
    path: Optional[str] = None,
    clear_local: bool = False,
) -> Dict[str, Any]:
    """
    ย้าย context (ทั้งหมดหรือเฉพาะ path) จาก MCP ไปเก็บบน Storage Node
    ถ้า clear_local=True จะลบออกจากเครื่องหลักหลังเก็บสำเร็จ → ลด RAM
    """
    srv = _hier_get(mcp_id) or vmax_mcp_get(mcp_id)
    if not srv:
        return {"st": "error", "msg": "MCP not found"}

    # สร้าง storage อัตโนมัติถ้ายังไม่มี
    if not storage_id:
        created = vmax_mcp_storage_create(owner_mcp=mcp_id)
        storage_id = created["storage_id"]

    ctx = srv.get_context(path)
    key = path or "__full_snapshot__"
    put = vmax_mcp_storage_put(storage_id, key, ctx)
    if put.get("st") != "ok":
        return put

    if clear_local and path:
        # ลบเฉพาะ path นั้น (set เป็น {})
        try:
            srv.update_context(path, {})
        except Exception:
            pass
    elif clear_local and not path:
        # เคลียร์ context หลักเหลือแต่โครง
        with srv.lock:
            for k in list(srv.context.keys()):
                srv.context[k] = {}

    if hasattr(srv, "storage_nodes") and storage_id not in srv.storage_nodes:
        srv.storage_nodes.append(storage_id)

    return {
        "st": "ok",
        "msg": f"Context offloaded to storage {storage_id}" + (" (local cleared)" if clear_local else ""),
        "storage_id": storage_id,
        "key": key,
        "put": put,
    }


def vmax_mcp_restore_context(
    mcp_id: str,
    storage_id: str,
    key: str = "__full_snapshot__",
    prefix: str = "",
) -> Dict[str, Any]:
    """ดึง context กลับจาก Storage Node เข้า MCP"""
    srv = _hier_get(mcp_id) or vmax_mcp_get(mcp_id)
    if not srv:
        return {"st": "error", "msg": "MCP not found"}
    got = vmax_mcp_storage_get(storage_id, key)
    if got.get("st") != "ok":
        return got
    payload = got["payload"]
    if isinstance(payload, dict):
        srv.merge_context(payload, prefix=prefix)
    else:
        srv.update_context(prefix or "restored", payload)
    return {
        "st": "ok",
        "msg": f"Context restored from {storage_id}/{key}",
        "mcp_id": mcp_id,
    }


# ----- Internet / Context Relay (กระจายอินเทอร์เน็ตให้ที่เก็บ) -----

_VMAX_MCP_RELAY: Dict[str, Any] = {
    "enabled": False,
    "gateways": [],          # node_id ที่มีเน็ตจริง
    "routes": {},            # target_node -> gateway_node
    "pending": [],           # queue ของ RPC/context ที่รอส่งต่อ
    "last_forward": None,
}


def vmax_mcp_relay_enable(gateway_nodes: Optional[List[str]] = None) -> Dict[str, Any]:
    """
    เปิดโหมด Relay: node ที่มีอินเทอร์เน็ตคอยเป็น gateway
    ส่งต่อ context / RPC ให้ storage node หรือ peer ที่ไม่มีเน็ต
    """
    _VMAX_MCP_RELAY["enabled"] = True
    if gateway_nodes:
        _VMAX_MCP_RELAY["gateways"] = list(gateway_nodes)
    _VMAX_MCP_RELAY["last_forward"] = _net_datetime.utcnow().isoformat() + "Z"
    return {"st": "ok", "relay": dict(_VMAX_MCP_RELAY)}


def vmax_mcp_relay_disable() -> Dict[str, Any]:
    _VMAX_MCP_RELAY["enabled"] = False
    return {"st": "ok", "relay": dict(_VMAX_MCP_RELAY)}


def vmax_mcp_relay_register_route(target_node: str, gateway_node: str) -> Dict[str, Any]:
    """กำหนดว่า target_node ที่ไม่มีเน็ต ให้ส่งผ่าน gateway_node"""
    _VMAX_MCP_RELAY["routes"][target_node] = gateway_node
    if gateway_node not in _VMAX_MCP_RELAY["gateways"]:
        _VMAX_MCP_RELAY["gateways"].append(gateway_node)
    return {
        "st": "ok",
        "target": target_node,
        "gateway": gateway_node,
        "routes": dict(_VMAX_MCP_RELAY["routes"]),
    }


def vmax_mcp_relay_forward(
    payload: Dict[str, Any],
    target_node: str,
    from_node: str = "local",
) -> Dict[str, Any]:
    """
    ส่งต่อ payload (context / RPC / storage blob) ไปยัง target
    ผ่าน gateway ถ้าจำเป็น — จำลองการกระจายอินเทอร์เน็ตให้ที่เก็บข้อมูล
    """
    if not _VMAX_MCP_RELAY["enabled"]:
        return {"st": "error", "msg": "Relay not enabled"}

    gateway = _VMAX_MCP_RELAY["routes"].get(target_node)
    entry = {
        "from": from_node,
        "target": target_node,
        "gateway": gateway or "direct",
        "payload_keys": list(payload.keys()) if isinstance(payload, dict) else [],
        "at": _net_datetime.utcnow().isoformat() + "Z",
    }
    _VMAX_MCP_RELAY["pending"].append(entry)
    if len(_VMAX_MCP_RELAY["pending"]) > 100:
        _VMAX_MCP_RELAY["pending"] = _VMAX_MCP_RELAY["pending"][-100:]
    _VMAX_MCP_RELAY["last_forward"] = entry["at"]

    # ถ้า target เป็น storage ให้ put ลง storage ด้วย (จำลอง)
    if isinstance(payload, dict) and payload.get("_storage_id") and payload.get("_key"):
        vmax_mcp_storage_put(
            payload["_storage_id"],
            payload["_key"],
            payload.get("data"),
        )

    # mirror เข้า mesh shared context
    try:
        vmax_mesh_share_context(
            {"relay_forward": entry, "data_preview": str(payload)[:200]},
            from_node=from_node,
        )
    except Exception:
        pass

    return {
        "st": "ok",
        "msg": f"Forwarded to {target_node} via {gateway or 'direct'}",
        "entry": entry,
    }


def vmax_mcp_relay_status() -> Dict[str, Any]:
    return {"st": "ok", **{k: v for k, v in _VMAX_MCP_RELAY.items()}}


# ----- สรุปสถานะ Hierarchical ทั้งก้อน -----

def vmax_hier_status(parent_id: Optional[str] = None) -> Dict[str, Any]:
    parent_id = parent_id or _VMAX_HIER_DEFAULT_PARENT
    parent = _hier_get(parent_id)
    children_info = []
    if parent:
        for cid, kind in parent.children.items():
            c = _hier_get(cid)
            children_info.append(c.to_dict() if c else {"server_id": cid, "kind": kind, "missing": True})
    with _VMAX_HIER_LOCK:
        all_ids = list(_VMAX_HIER_MCP.keys())
    return {
        "st": "ok",
        "default_parent": _VMAX_HIER_DEFAULT_PARENT,
        "parent": parent.to_dict() if parent else None,
        "children": children_info,
        "total_hier_servers": len(all_ids),
        "all_ids": all_ids,
        "storage": vmax_mcp_storage_list(),
        "relay": vmax_mcp_relay_status(),
    }


def vmax_hier_bootstrap() -> Dict[str, Any]:
    """
    ชุดเริ่มต้นครบวงจร:
      1. สร้าง Parent MCP
      2. Spawn Child มาตรฐาน 3 ตัว
      3. สร้าง Storage Node เล็ก ๆ ผูกกับ Parent
      4. เปิด Relay (พร้อมใช้เมื่อมี mesh)
    """
    parent = vmax_hier_create_parent(name="vmax-parent-mcp")
    pid = parent["server_id"]
    trio = vmax_hier_spawn_standard_trio(parent_id=pid)
    storage = vmax_mcp_storage_create(owner_mcp=pid, max_bytes=_VMAX_DEFAULT_STORAGE_MAX)
    relay = vmax_mcp_relay_enable(gateway_nodes=["local"])
    return {
        "st": "ok",
        "msg": "Hierarchical MCP bootstrapped (Parent + 3 Children + Storage + Relay)",
        "parent": parent,
        "children": trio.get("children"),
        "storage": storage,
        "relay": relay,
    }


