from copy import deepcopy
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

# ---------------------------------------------------------------------------
# Optional Flask (ถ้าไม่มีก็ยังใช้ CLI / function API ได้)
