VMAX_OSS_VERSION = "1.0.0"
VMAX_OSS_NAME = "VMAX OSS Scanner"
VMAX_OSS_NAME_TH = "ระบบสแกนช่องโหว่โอเพนซอร์ส VMAX"

_DATA_DIR = Path(os.environ.get("VMAX_OSS_DATA_DIR", "vmax_oss_data"))
_DATA_DIR.mkdir(parents=True, exist_ok=True)

_PROJECTS_FILE = _DATA_DIR / "projects.json"
_REPORTS_DIR = _DATA_DIR / "reports"
_REPORTS_DIR.mkdir(parents=True, exist_ok=True)

_HOST = os.environ.get("VMAX_OSS_HOST", "0.0.0.0")
_PORT = int(os.environ.get("VMAX_OSS_PORT", "8765"))

# ความรุนแรง
SEVERITIES = ("critical", "high", "medium", "low", "info")

# ---------------------------------------------------------------------------
# In-memory + disk state
# ---------------------------------------------------------------------------

_LOCK = threading.RLock()
_PROJECTS: Dict[str, Dict[str, Any]] = {}
_REPORTS: Dict[str, List[Dict[str, Any]]] = {}  # project_id -> list of reports


def _utc_now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _load_projects() -> None:
    global _PROJECTS
    if _PROJECTS_FILE.exists():
        try:
            with open(_PROJECTS_FILE, "r", encoding="utf-8") as f:
                _PROJECTS = json.load(f)
        except Exception:
            _PROJECTS = {}
    else:
        _PROJECTS = {}


def _save_projects() -> None:
    with open(_PROJECTS_FILE, "w", encoding="utf-8") as f:
        json.dump(_PROJECTS, f, ensure_ascii=False, indent=2)


def _load_reports(project_id: str) -> List[Dict[str, Any]]:
    path = _REPORTS_DIR / f"{project_id}.json"
    if path.exists():
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    return []


def _save_reports(project_id: str, reports: List[Dict[str, Any]]) -> None:
    path = _REPORTS_DIR / f"{project_id}.json"
    with open(path, "w", encoding="utf-8") as f:
        json.dump(reports, f, ensure_ascii=False, indent=2)


_load_projects()

