# ---------------------------------------------------------------------------
# Project enrollment (opt-in, คล้าย project.yaml ของ Anthropic)
# ---------------------------------------------------------------------------

def vmax_oss_enroll(
    name: str,
    repo_url: str = "",
    primary_contact: str = "",
    description: str = "",
    language: str = "python",
    critical_impact: bool = True,
    dockerfile: str = "",
    threat_model: str = "",
    tags: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """
    ลงทะเบียนโปรเจกต์โอเพนซอร์สเข้า OSS Scanner (opt-in)

    คล้ายการเปิด PR ใส่ projects/<name>/project.yaml ของ Anthropic
    """
    name = (name or "").strip()
    if not name:
        return {"st": "error", "msg": "ต้องระบุ name ของโปรเจกต์"}

    project_id = re.sub(r"[^a-z0-9_-]", "-", name.lower())[:64]
    if not project_id:
        project_id = secrets.token_hex(8)

    with _LOCK:
        if project_id in _PROJECTS:
            return {"st": "error", "msg": f"โปรเจกต์ '{project_id}' มีอยู่แล้ว", "project_id": project_id}

        entry = {
            "id": project_id,
            "name": name,
            "repo_url": repo_url or "",
            "primary_contact": primary_contact or "",
            "description": description or "",
            "language": language or "python",
            "critical_impact": bool(critical_impact),
            "dockerfile": dockerfile or "",
            "threat_model": threat_model or "",
            "tags": tags or [],
            "status": "enrolled",
            "enrolled_at": _utc_now(),
            "last_scan_at": None,
            "scan_count": 0,
            "finding_count": 0,
            "source": "local",  # local | path | git
            "local_path": None,
        }
        _PROJECTS[project_id] = entry
        _save_projects()
        _REPORTS[project_id] = []
        _save_reports(project_id, [])

    return {
        "st": "ok",
        "msg": f"ลงทะเบียนโปรเจกต์ '{name}' สำเร็จ (opt-in)",
        "project": entry,
        "note": (
            "Reports are model-generated (rule + heuristic engine) without human review. "
            "Expected true-positive rate target > 90% (inspired by Anthropic OSS Scanner)."
        ),
    }


def vmax_oss_set_local_path(project_id: str, path: str) -> Dict[str, Any]:
    """ผูก path ในเครื่องให้โปรเจกต์เพื่อสแกนโค้ดจริง"""
    path = str(Path(path).expanduser().resolve())
    if not Path(path).is_dir():
        return {"st": "error", "msg": f"ไม่พบ directory: {path}"}

    with _LOCK:
        if project_id not in _PROJECTS:
            return {"st": "error", "msg": f"ไม่พบโปรเจกต์ {project_id}"}
        _PROJECTS[project_id]["local_path"] = path
        _PROJECTS[project_id]["source"] = "path"
        _save_projects()
        return {"st": "ok", "project_id": project_id, "local_path": path}


def vmax_oss_list_projects(status: Optional[str] = None) -> Dict[str, Any]:
    with _LOCK:
        items = list(_PROJECTS.values())
        if status:
            items = [p for p in items if p.get("status") == status]
        items.sort(key=lambda x: x.get("enrolled_at", ""), reverse=True)
        return {"st": "ok", "count": len(items), "projects": items}


def vmax_oss_get_project(project_id: str) -> Dict[str, Any]:
    with _LOCK:
        p = _PROJECTS.get(project_id)
        if not p:
            return {"st": "error", "msg": f"ไม่พบโปรเจกต์ {project_id}"}
        return {"st": "ok", "project": deepcopy(p)}


def vmax_oss_unenroll(project_id: str) -> Dict[str, Any]:
    with _LOCK:
        if project_id not in _PROJECTS:
            return {"st": "error", "msg": f"ไม่พบโปรเจกต์ {project_id}"}
        del _PROJECTS[project_id]
        _save_projects()
        _REPORTS.pop(project_id, None)
        report_file = _REPORTS_DIR / f"{project_id}.json"
        if report_file.exists():
            try:
                report_file.unlink()
            except Exception:
                pass
        return {"st": "ok", "msg": f"ยกเลิกการลงทะเบียน {project_id} แล้ว"}


