def _iter_source_files(root: Path, language: str = "python") -> List[Path]:
    """รวบรวมไฟล์ source ที่จะสแกน"""
    extensions = {
        "python": {".py"},
        "javascript": {".js", ".jsx", ".ts", ".tsx", ".mjs"},
        "java": {".java"},
        "go": {".go"},
        "ruby": {".rb"},
        "php": {".php"},
        "c": {".c", ".h", ".cpp", ".hpp", ".cc"},
        "any": {
            ".py", ".js", ".jsx", ".ts", ".tsx", ".java", ".go", ".rb",
            ".php", ".c", ".h", ".cpp", ".hpp", ".rs", ".cs",
        },
    }
    exts = extensions.get(language.lower(), extensions["any"])
    skip_dirs = {
        ".git", "node_modules", "venv", ".venv", "__pycache__",
        "dist", "build", ".tox", ".mypy_cache", "vendor", "target",
    }
    files: List[Path] = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in skip_dirs and not d.startswith(".")]
        for fn in filenames:
            p = Path(dirpath) / fn
            if p.suffix.lower() in exts:
                files.append(p)
    return files


def _scan_file(path: Path, content: str) -> List[Dict[str, Any]]:
    """สแกนไฟล์เดียวด้วย pattern database"""
    findings: List[Dict[str, Any]] = []
    lines = content.splitlines()

    for rule in _VULN_PATTERNS:
        for pat in rule["patterns"]:
            try:
                regex = re.compile(pat)
            except re.error:
                continue
            for i, line in enumerate(lines, start=1):
                if regex.search(line):
                    findings.append({
                        "rule_id": rule["id"],
                        "name": rule["name"],
                        "name_th": rule["name_th"],
                        "severity": rule["severity"],
                        "file": str(path),
                        "line": i,
                        "snippet": line.strip()[:200],
                        "explanation": rule["explanation"],
                        "explanation_th": rule["explanation_th"],
                        "poc": rule["poc_template"],
                        "candidate_patch": rule["patch_template"],
                    })
                    break  # หนึ่ง rule ต่อไฟล์พอ (ลด noise)
    return findings


def _scan_codebase(local_path: str, language: str = "python") -> List[Dict[str, Any]]:
    root = Path(local_path)
    if not root.is_dir():
        return []

    all_findings: List[Dict[str, Any]] = []
    files = _iter_source_files(root, language)
    # จำกัดจำนวนไฟล์เพื่อไม่ให้ช้าเกินไป
    max_files = 400
    for fp in files[:max_files]:
        try:
            text = fp.read_text(encoding="utf-8", errors="ignore")
            if len(text) > 1_500_000:  # ข้ามไฟล์ใหญ่ผิดปกติ
                continue
            # เก็บ path สัมพัทธ์
            rel = fp.relative_to(root)
            findings = _scan_file(rel, text)
            for f in findings:
                f["file"] = str(rel)
            all_findings.extend(findings)
        except Exception:
            continue
    return all_findings


def _synthetic_findings(project: Dict[str, Any]) -> List[Dict[str, Any]]:
    """
    เมื่อไม่มี local_path จะสร้างตัวอย่าง findings จำลอง
    (เพื่อให้ demo / API ทำงานได้แม้ยังไม่ผูก path)
    """
    demo = [
        {
            "rule_id": "CWE-89",
            "name": "SQL Injection",
            "name_th": "SQL Injection",
            "severity": "high",
            "file": "src/db.py",
            "line": 42,
            "snippet": 'cursor.execute(f"SELECT * FROM users WHERE id = {user_id}")',
            "explanation": _VULN_PATTERNS[0]["explanation"],
            "explanation_th": _VULN_PATTERNS[0]["explanation_th"],
            "poc": _VULN_PATTERNS[0]["poc_template"],
            "candidate_patch": _VULN_PATTERNS[0]["patch_template"],
        },
        {
            "rule_id": "CWE-798",
            "name": "Hard-coded Credentials",
            "name_th": "Hard-coded Credentials",
            "severity": "high",
            "file": "config.py",
            "line": 12,
            "snippet": 'API_SECRET = "sk-live-xxxxxxxxxxxxxxxx"',
            "explanation": _VULN_PATTERNS[3]["explanation"],
            "explanation_th": _VULN_PATTERNS[3]["explanation_th"],
            "poc": _VULN_PATTERNS[3]["poc_template"],
            "candidate_patch": _VULN_PATTERNS[3]["patch_template"],
        },
    ]
    # ถ้า critical_impact เพิ่ม critical ตัวอย่าง
    if project.get("critical_impact"):
        demo.append({
            "rule_id": "CWE-78",
            "name": "OS Command Injection",
            "name_th": "Command Injection",
            "severity": "critical",
            "file": "utils/shell.py",
            "line": 7,
            "snippet": 'os.system("ping " + host)',
            "explanation": _VULN_PATTERNS[1]["explanation"],
            "explanation_th": _VULN_PATTERNS[1]["explanation_th"],
            "poc": _VULN_PATTERNS[1]["poc_template"],
            "candidate_patch": _VULN_PATTERNS[1]["patch_template"],
        })
    return demo


def vmax_oss_scan(
    project_id: str,
    force_synthetic: bool = False,
) -> Dict[str, Any]:
    """
    รันสแกนหนึ่งครั้งสำหรับโปรเจกต์ที่ลงทะเบียนแล้ว

    ผลลัพธ์:
      - report_id
      - findings[] แต่ละตัวมี: rule_id, severity, file, line, snippet,
        explanation, poc (reproducer), candidate_patch
      - ไม่มี human review (model/rule-generated)
    """
    with _LOCK:
        project = _PROJECTS.get(project_id)
        if not project:
            return {"st": "error", "msg": f"ไม่พบโปรเจกต์ {project_id} — ต้อง enroll ก่อน"}
        if project.get("status") not in ("enrolled", "active"):
            return {"st": "error", "msg": f"สถานะโปรเจกต์ไม่พร้อมสแกน: {project.get('status')}"}

        local_path = project.get("local_path")
        language = project.get("language", "python")

    started = time.time()
    if local_path and not force_synthetic:
        findings = _scan_codebase(local_path, language)
        scan_mode = "path"
    else:
        findings = _synthetic_findings(project)
        scan_mode = "synthetic"

    # จัดเรียงตามความรุนแรง
    sev_order = {s: i for i, s in enumerate(SEVERITIES)}
    findings.sort(key=lambda f: sev_order.get(f.get("severity", "info"), 99))

    report_id = f"rpt_{uuid.uuid4().hex[:12]}"
    report = {
        "report_id": report_id,
        "project_id": project_id,
        "project_name": project["name"],
        "generated_at": _utc_now(),
        "scan_mode": scan_mode,
        "duration_sec": round(time.time() - started, 3),
        "engine": f"VMAX-OSS-Scanner/{VMAX_OSS_VERSION}",
        "human_reviewed": False,
        "note": (
            "This report is fully model/rule-generated without human triage "
            "(inspired by Anthropic OSS Scanner). Some findings may be false positives."
        ),
        "summary": {
            "total": len(findings),
            "critical": sum(1 for f in findings if f["severity"] == "critical"),
            "high": sum(1 for f in findings if f["severity"] == "high"),
            "medium": sum(1 for f in findings if f["severity"] == "medium"),
            "low": sum(1 for f in findings if f["severity"] == "low"),
            "info": sum(1 for f in findings if f["severity"] == "info"),
        },
        "findings": findings,
    }

    with _LOCK:
        reports = _load_reports(project_id)
        reports.append(report)
        # เก็บรายงานล่าสุดไม่เกิน 50 ฉบับ
        if len(reports) > 50:
            reports = reports[-50:]
        _save_reports(project_id, reports)
        _REPORTS[project_id] = reports

        _PROJECTS[project_id]["last_scan_at"] = report["generated_at"]
        _PROJECTS[project_id]["scan_count"] = _PROJECTS[project_id].get("scan_count", 0) + 1
        _PROJECTS[project_id]["finding_count"] = len(findings)
        _PROJECTS[project_id]["status"] = "active"
        _save_projects()

    return {
        "st": "ok",
        "report_id": report_id,
        "summary": report["summary"],
        "scan_mode": scan_mode,
        "duration_sec": report["duration_sec"],
        "report": report,
    }


def vmax_oss_list_reports(project_id: str, limit: int = 10) -> Dict[str, Any]:
    with _LOCK:
        if project_id not in _PROJECTS:
            return {"st": "error", "msg": f"ไม่พบโปรเจกต์ {project_id}"}
        reports = _load_reports(project_id)
        reports = list(reversed(reports))[: max(1, min(limit, 50))]
        # สรุปย่อ (ไม่ส่ง findings เต็มถ้าไม่จำเป็น)
        brief = []
        for r in reports:
            brief.append({
                "report_id": r["report_id"],
                "generated_at": r["generated_at"],
                "scan_mode": r.get("scan_mode"),
                "summary": r.get("summary"),
                "human_reviewed": r.get("human_reviewed", False),
            })
        return {"st": "ok", "count": len(brief), "reports": brief}


def vmax_oss_get_report(project_id: str, report_id: str) -> Dict[str, Any]:
    with _LOCK:
        if project_id not in _PROJECTS:
            return {"st": "error", "msg": f"ไม่พบโปรเจกต์ {project_id}"}
        reports = _load_reports(project_id)
        for r in reports:
            if r.get("report_id") == report_id:
                return {"st": "ok", "report": r}
        return {"st": "error", "msg": f"ไม่พบรายงาน {report_id}"}


def vmax_oss_status() -> Dict[str, Any]:
    with _LOCK:
        total_projects = len(_PROJECTS)
        total_scans = sum(p.get("scan_count", 0) for p in _PROJECTS.values())
        return {
            "st": "ok",
            "name": VMAX_OSS_NAME,
            "name_th": VMAX_OSS_NAME_TH,
            "version": VMAX_OSS_VERSION,
            "projects": total_projects,
            "total_scans": total_scans,
            "rules": len(_VULN_PATTERNS),
            "data_dir": str(_DATA_DIR.resolve()),
            "inspired_by": "Anthropic OSS Scanner / Project Glasswing / OSS-Fuzz",
            "human_reviewed_default": False,
        }


