def create_app() -> Any:
    if not _HAS_FLASK:
        raise RuntimeError("Flask not installed — pip install flask")

    app = Flask(__name__)

    @app.route("/api/oss/status", methods=["GET"])
    def api_status():
        return jsonify(vmax_oss_status())

    @app.route("/api/oss/enroll", methods=["POST"])
    def api_enroll():
        body = request.get_json(silent=True) or {}
        return jsonify(vmax_oss_enroll(
            name=str(body.get("name", "")),
            repo_url=str(body.get("repo_url", "")),
            primary_contact=str(body.get("primary_contact", "")),
            description=str(body.get("description", "")),
            language=str(body.get("language", "python")),
            critical_impact=bool(body.get("critical_impact", True)),
            dockerfile=str(body.get("dockerfile", "")),
            threat_model=str(body.get("threat_model", "")),
            tags=body.get("tags"),
        ))

    @app.route("/api/oss/projects", methods=["GET"])
    def api_projects():
        return jsonify(vmax_oss_list_projects(request.args.get("status")))

    @app.route("/api/oss/project/<project_id>", methods=["GET"])
    def api_project(project_id: str):
        return jsonify(vmax_oss_get_project(project_id))

    @app.route("/api/oss/unenroll/<project_id>", methods=["POST", "DELETE"])
    def api_unenroll(project_id: str):
        return jsonify(vmax_oss_unenroll(project_id))

    @app.route("/api/oss/set-path", methods=["POST"])
    def api_set_path():
        body = request.get_json(silent=True) or {}
        return jsonify(vmax_oss_set_local_path(
            str(body.get("project_id", "")),
            str(body.get("path", "")),
        ))

    @app.route("/api/oss/scan", methods=["POST"])
    def api_scan():
        body = request.get_json(silent=True) or {}
        return jsonify(vmax_oss_scan(
            project_id=str(body.get("project_id", "")),
            force_synthetic=bool(body.get("force_synthetic", False)),
        ))

    @app.route("/api/oss/reports/<project_id>", methods=["GET"])
    def api_reports(project_id: str):
        limit = int(request.args.get("limit", 10))
        return jsonify(vmax_oss_list_reports(project_id, limit=limit))

    @app.route("/api/oss/report/<project_id>/<report_id>", methods=["GET"])
    def api_report(project_id: str, report_id: str):
        return jsonify(vmax_oss_get_report(project_id, report_id))

    @app.route("/api/oss/rules", methods=["GET"])
    def api_rules():
        rules = [
            {
                "id": r["id"],
                "name": r["name"],
                "name_th": r["name_th"],
                "severity": r["severity"],
            }
            for r in _VULN_PATTERNS
        ]
        return jsonify({"st": "ok", "count": len(rules), "rules": rules})

    @app.route("/", methods=["GET"])
    def index():
        return jsonify({
            "service": VMAX_OSS_NAME,
            "version": VMAX_OSS_VERSION,
            "endpoints": [
                "GET  /api/oss/status",
                "POST /api/oss/enroll",
                "GET  /api/oss/projects",
                "GET  /api/oss/project/<id>",
                "POST /api/oss/unenroll/<id>",
                "POST /api/oss/set-path",
                "POST /api/oss/scan",
                "GET  /api/oss/reports/<id>",
                "GET  /api/oss/report/<id>/<report_id>",
                "GET  /api/oss/rules",
            ],
            "inspired_by": "Anthropic OSS Scanner (Oct 2026)",
        })

    return app


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def _cli() -> None:
    parser = argparse.ArgumentParser(
        description=f"{VMAX_OSS_NAME} v{VMAX_OSS_VERSION} — inspired by Anthropic OSS Scanner"
    )
    parser.add_argument("--host", default=_HOST)
    parser.add_argument("--port", type=int, default=_PORT)
    parser.add_argument("--list", action="store_true", help="แสดงโปรเจกต์ที่ลงทะเบียน")
    parser.add_argument("--status", action="store_true", help="สถานะระบบ")
    parser.add_argument("--enroll", action="store_true", help="ลงทะเบียนโปรเจกต์ใหม่")
    parser.add_argument("--name", default="", help="ชื่อโปรเจกต์ (ใช้กับ --enroll)")
    parser.add_argument("--repo", default="", help="URL ของ repo")
    parser.add_argument("--path", default="", help="local path ของโค้ด (ผูกกับโปรเจกต์)")
    parser.add_argument("--scan", metavar="PROJECT_ID", help="สแกนโปรเจกต์")
    parser.add_argument("--reports", metavar="PROJECT_ID", help="ดูรายงานของโปรเจกต์")
    parser.add_argument("--no-server", action="store_true", help="ไม่เปิด Flask server")

    args = parser.parse_args()

    if args.status:
        print(json.dumps(vmax_oss_status(), ensure_ascii=False, indent=2))
        return

    if args.list:
        print(json.dumps(vmax_oss_list_projects(), ensure_ascii=False, indent=2))
        return

    if args.enroll:
        if not args.name:
            print("ต้องระบุ --name")
            return
        result = vmax_oss_enroll(name=args.name, repo_url=args.repo)
        print(json.dumps(result, ensure_ascii=False, indent=2))
        if result.get("st") == "ok" and args.path:
            pid = result["project"]["id"]
            print(json.dumps(vmax_oss_set_local_path(pid, args.path), ensure_ascii=False, indent=2))
        return

    if args.scan:
        if args.path:
            # ถ้ามี path ให้ set ก่อน
            vmax_oss_set_local_path(args.scan, args.path)
        result = vmax_oss_scan(args.scan)
        # พิมพ์สรุป + findings ย่อ
        if result.get("st") == "ok":
            summary = result["summary"]
            print(f"[OK] report_id={result['report_id']}  mode={result['scan_mode']}  "
                  f"findings={summary['total']} "
                  f"(critical={summary['critical']} high={summary['high']} "
                  f"medium={summary['medium']})")
            for f in result["report"]["findings"][:15]:
                print(f"  [{f['severity'].upper():8}] {f['rule_id']:10}  "
                      f"{f['file']}:{f['line']}  {f['name']}")
            if summary["total"] > 15:
                print(f"  ... และอีก {summary['total'] - 15} รายการ")
        else:
            print(json.dumps(result, ensure_ascii=False, indent=2))
        return

    if args.reports:
        print(json.dumps(vmax_oss_list_reports(args.reports), ensure_ascii=False, indent=2))
        return

    # Default: เปิด server
    if args.no_server:
        print("ใช้ --list / --enroll / --scan / --status ได้")
        return

    if not _HAS_FLASK:
        print("Flask ไม่ได้ติดตั้ง — ใช้ CLI flags แทน หรือ pip install flask")
        print("ตัวอย่าง: python VMAX_OSS_Scanner.py --enroll --name mylib --path ./src")
        return

    app = create_app()
    print(f"[VMAX OSS Scanner] v{VMAX_OSS_VERSION} listening on http://{args.host}:{args.port}")
    print("  Inspired by Anthropic OSS Scanner — free opt-in vulnerability scans for OSS")
    app.run(host=args.host, port=args.port, debug=False, threaded=True)


