def lj(p, d=None):
    if p.exists():
        try: return json.loads(p.read_text(encoding="utf-8"))
        except Exception: pass
    return d if d is not None else {}
def sj(p, data): p.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
def load_state():
    return lj(_STATE, {"installed":False,"hostname":"VMAX-PC","username":"User","password":"",
        "installed_at":None,"boot_count":0,"language":"th","notifications_enabled":True,"volume":70,
        "recycle_auto_days":30, "cleanup_temps":False,
        "update_auto_days":7, "last_update_check":None,
        "wifi_ssid":None, "wifi_connected":False,
        "theme":"dark", "volume":70, "brightness":80,
        "screensaver_min":0, "startup_apps":["explorer"],
        "firewall_on":True, "backup_last":None,
        "region":"TH", "timezone":"Asia/Bangkok"})
def save_state(s): sj(_STATE, s)
def log_ev(level, src, msg):
    logs = lj(_LOG, []); logs.append({"time":datetime.now().isoformat(timespec="seconds"),"level":level,"source":src,"message":msg})
    sj(_LOG, logs[-500:])
