def _is_activated(product_id: str) -> bool:
    db = _license_db()
    act = db.get("activated", {})
    if product_id in act: return True
    if "full_suite" in act: return True
    return False

def _redeem_key(key: str) -> dict:
    norm = _normalize_key(key)
    h = _key_hash(norm)
    db = _license_db()
    if h in db.get("used_keys", []):
        return {"st": "error", "msg": "รหัสนี้ถูกใช้ไปแล้วบนเครื่องนี้"}
    product_id = _BUILTIN_KEYS.get(h)
    if not product_id:
        # accept pattern VMAX-XXXX-XXXX-XXXX with checksum toy rule for "store-bought" feel
        body = "".join(ch for ch in norm if ch.isalnum())
        if len(body) >= 16 and body.startswith("VMAX"):
            # fake online validate: last char digit sum even = full_suite, else writer_pro
            s = sum(ord(c) for c in body)
            product_id = "full_suite" if s % 5 == 0 else "writer_pro"
        else:
            return {"st": "error", "msg": "รหัสไม่ถูกต้อง"}
    db.setdefault("used_keys", []).append(h)
    db.setdefault("activated", {})[product_id] = {
        "key_hint": norm[:9] + "****",
        "at": datetime.now().isoformat(timespec="seconds"),
    }
    if product_id == "full_suite":
        for pid in _PRODUCT_CATALOG:
            db["activated"][pid] = db["activated"][product_id]
    _license_save(db)
    log_ev("INFO", "License", f"Activated {product_id}")
    return {"st": "ok", "product_id": product_id, "product": _PRODUCT_CATALOG.get(product_id, {}).get("name", product_id), "msg": "เปิดใช้งานสำเร็จ"}



