def _file_age_days(p: Path) -> float:
    try:
        return (time.time() - p.stat().st_mtime) / 86400.0
    except Exception:
        return 0.0

def _auto_maintenance(state: dict) -> list:
    """Run recycle purge + optional temp cleanup. Returns log lines."""
    lines = []
    days = int(state.get("recycle_auto_days") or 0)
    if days > 0 and _RECYCLE.exists():
        removed = 0
        for p in list(_RECYCLE.iterdir()):
            if _file_age_days(p) >= days:
                try:
                    if p.is_file(): p.unlink()
                    else: shutil.rmtree(p, ignore_errors=True)
                    removed += 1
                except Exception:
                    pass
        if removed:
            lines.append(f"Recycle: removed {removed} item(s) older than {days} days")
            log_ev("INFO", "Cleanup", lines[-1])
    if state.get("cleanup_temps"):
        removed = 0
        for folder in (_TEMP, _DATA / "cache"):
            folder.mkdir(parents=True, exist_ok=True)
            for p in list(folder.iterdir()):
                if _file_age_days(p) >= float(state.get("recycle_auto_days") or 30):
                    try:
                        if p.is_file(): p.unlink()
                        else: shutil.rmtree(p, ignore_errors=True)
                        removed += 1
                    except Exception:
                        pass
        # also drop very old event log trim already handled; mark leftover temp stubs
        if removed:
            lines.append(f"Temp/Leftover: removed {removed} item(s)")
            log_ev("INFO", "Cleanup", lines[-1])
    # auto update check marker
    udays = int(state.get("update_auto_days") or 0)
    if udays > 0:
        last = state.get("last_update_check")
        due = True
        if last:
            try:
                from datetime import datetime as _dt
                due = (_dt.now() - _dt.fromisoformat(last)).days >= udays
            except Exception:
                due = True
        if due:
            state["last_update_check"] = datetime.now().isoformat(timespec="seconds")
            save_state(state)
            lines.append(f"Update: auto-check (every {udays} days) — up to date")
            log_ev("INFO", "Update", lines[-1])
    return lines


