def _import_os_file(path: str) -> dict:
    p = Path(path)
    if not p.exists():
        return {"st": "error", "msg": "ไฟล์ไม่พบ"}
    try:
        raw = p.read_text(encoding="utf-8")
        if p.suffix.lower() == ".json" or raw.strip().startswith("{"):
            data = json.loads(raw)
        else:
            data = {"id": p.stem, "name": p.stem, "version": "1.0", "author": "Imported"}
            for line in raw.splitlines():
                if "=" in line and not line.strip().startswith("#"):
                    k, _, v = line.partition("=")
                    data[k.strip()] = v.strip()
        if not isinstance(data, dict):
            return {"st": "error", "msg": "รูปแบบไฟล์ไม่ถูกต้อง"}
        pid = (data.get("id") or data.get("name") or p.stem).lower().replace(" ", "-")
        profile = _default_os_profile()
        profile.update({
            "id": pid, "name": data.get("name") or pid,
            "version": str(data.get("version") or "1.0"),
            "author": data.get("author") or "Imported",
            "logo_text": data.get("logo_text") or data.get("name") or pid,
            "boot_subtitle": data.get("boot_subtitle") or "Starting...",
            "theme": data.get("theme") or profile["theme"],
            "installed": False,
            "hostname": data.get("hostname") or (pid.upper()[:12] + "-PC"),
            "username": data.get("username") or "User",
            "password": data.get("password") or "",
            "source_file": str(p),
        })
        if isinstance(data.get("theme"), dict):
            profile["theme"].update(data["theme"])
        _save_os_profile(profile)
        log_ev("INFO", "OS", f"Imported profile {pid}")
        return {"st": "ok", "profile": profile}
    except Exception as ex:
        return {"st": "error", "msg": str(ex)}



