def _lock_file(path: str, password: str, owner: str = "User") -> dict:
    p = Path(path)
    if not p.exists() or not p.is_file():
        return {"st": "error", "msg": "ไฟล์ไม่พบ"}
    db = _locks_db()
    key = str(p.resolve())
    db[key] = {
        "password_hash": _key_hash(password),
        "owner": owner,
        "locked_at": datetime.now().isoformat(timespec="seconds"),
        "name": p.name,
    }
    _locks_save(db)
    log_ev("INFO", "FileLock", f"Locked {p.name}")
    return {"st": "ok", "msg": f"ล็อก {p.name} แล้ว"}

def _unlock_file(path: str, password: str) -> dict:
    p = Path(path)
    key = str(p.resolve()) if p.exists() else path
    db = _locks_db()
    # try resolve match
    hit = None
    for k, v in db.items():
        if k == key or k.endswith(path) or Path(k).name == Path(path).name:
            hit = k; break
    if not hit:
        return {"st": "error", "msg": "ไฟล์นี้ไม่ได้ล็อก"}
    if db[hit].get("password_hash") != _key_hash(password):
        return {"st": "error", "msg": "รหัสปลดล็อกไม่ถูกต้อง"}
    del db[hit]; _locks_save(db)
    log_ev("INFO", "FileLock", f"Unlocked {hit}")
    return {"st": "ok", "msg": "ปลดล็อกแล้ว"}

def _is_locked(path: str) -> bool:
    p = Path(path)
    key = str(p.resolve()) if p.exists() else path
    db = _locks_db()
    for k in db:
        if k == key or Path(k).name == p.name:
            return True
    return False


