def _run_python_source(source: str, filename: str = "<script>") -> str:
    """Execute Python source in a restricted-ish namespace; capture stdout."""
    import io, contextlib
    buf = io.StringIO()
    # Safe-ish builtins subset + full python still available for power users in this sim
    ns = {"__name__": "__main__", "__file__": filename}
    try:
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            code = compile(source, filename, "exec")
            exec(code, ns, ns)
        out = buf.getvalue()
        return out if out else "(ran successfully, no output)"
    except Exception as ex:
        return f"Python error: {type(ex).__name__}: {ex}"


# ---------------------------------------------------------------------------
# Host computer bridge — ใช้ทรัพยากรเครื่องจริงของผู้ใช้
# ไม่ต้องพึ่ง QEMU/nasm สำหรับโหมดนี้: อ่าน CPU/RAM/Disk/Process จริงจากเครื่อง
# ---------------------------------------------------------------------------
def _host_probe():
    """Collect real host stats. Best-effort; never crashes the OS GUI."""
    info = {
        "platform": platform.system(),
        "release": platform.release(),
        "machine": platform.machine(),
        "processor": platform.processor() or platform.machine(),
        "python": platform.python_version(),
        "cpu_count": os.cpu_count() or 1,
        "hostname_host": platform.node(),
    }
    # memory
    try:
        if platform.system() == "Linux":
            mem = {}
            with open("/proc/meminfo", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    if ":" in line:
                        k, v = line.split(":", 1)
                        mem[k.strip()] = v.strip()
            def kb(key):
                raw = mem.get(key, "0").split()[0]
                return int(raw)
            total = kb("MemTotal") * 1024
            avail = kb("MemAvailable") * 1024 if "MemAvailable" in mem else kb("MemFree") * 1024
            info["ram_total"] = total
            info["ram_available"] = avail
            info["ram_used"] = max(0, total - avail)
        elif platform.system() == "Darwin":
            import subprocess as _sp
            out = _sp.check_output(["sysctl", "-n", "hw.memsize"], text=True).strip()
            info["ram_total"] = int(out)
            info["ram_available"] = None
            info["ram_used"] = None
        elif platform.system() == "Windows":
            import ctypes
            class M(ctypes.Structure):
                _fields_ = [
                    ("dwLength", ctypes.c_ulong),
                    ("dwMemoryLoad", ctypes.c_ulong),
                    ("ullTotalPhys", ctypes.c_ulonglong),
                    ("ullAvailPhys", ctypes.c_ulonglong),
                    ("ullTotalPageFile", ctypes.c_ulonglong),
                    ("ullAvailPageFile", ctypes.c_ulonglong),
                    ("ullTotalVirtual", ctypes.c_ulonglong),
                    ("ullAvailVirtual", ctypes.c_ulonglong),
                    ("ullAvailExtendedVirtual", ctypes.c_ulonglong),
                ]
            m = M(); m.dwLength = ctypes.sizeof(M)
            ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(m))
            info["ram_total"] = int(m.ullTotalPhys)
            info["ram_available"] = int(m.ullAvailPhys)
            info["ram_used"] = int(m.ullTotalPhys - m.ullAvailPhys)
            info["memory_load_pct"] = int(m.dwMemoryLoad)
        else:
            info["ram_total"] = None
    except Exception as ex:
        info["ram_error"] = str(ex)
    # disk
    try:
        usage = shutil.disk_usage(str(Path.home()))
        info["disk_total"] = usage.total
        info["disk_used"] = usage.used
        info["disk_free"] = usage.free
    except Exception as ex:
        info["disk_error"] = str(ex)
    # processes (best effort)
    procs = []
    try:
        if platform.system() == "Linux" and Path("/proc").exists():
            for p in list(Path("/proc").iterdir())[:80]:
                if p.name.isdigit():
                    try:
                        comm = (p / "comm").read_text(encoding="utf-8", errors="ignore").strip()
                        procs.append({"pid": int(p.name), "name": comm or p.name})
                    except Exception:
                        pass
        elif platform.system() == "Windows":
            import subprocess as _sp
            out = _sp.check_output(["tasklist", "/FO", "CSV", "/NH"], text=True, errors="ignore")
            for line in out.splitlines()[:40]:
                parts = [x.strip().strip('"') for x in line.split(",")]
                if len(parts) >= 2 and parts[1].isdigit():
                    procs.append({"pid": int(parts[1]), "name": parts[0]})
        else:
            import subprocess as _sp
            out = _sp.check_output(["ps", "-Ao", "pid,comm"], text=True, errors="ignore")
            for line in out.splitlines()[1:40]:
                parts = line.split(None, 1)
                if len(parts) == 2 and parts[0].isdigit():
                    procs.append({"pid": int(parts[0]), "name": parts[1][:40]})
    except Exception as ex:
        info["proc_error"] = str(ex)
    info["processes"] = procs
    # load avg
    try:
        if hasattr(os, "getloadavg"):
            info["loadavg"] = os.getloadavg()
    except Exception:
        pass
    return info

def _host_brief():
    try:
        h=_host_probe()
        return (f"Host: {h.get('platform')} {h.get('release')} | CPU x{h.get('cpu_count')} | "
                f"RAM {_fmt_bytes(h.get('ram_total'))} | Disk free {_fmt_bytes(h.get('disk_free'))}")
    except Exception as ex:
        return f"Host probe: {ex}"

def _fmt_bytes(n):
    if n is None:
        return "—"
    n = float(n)
    for u in ("B", "KB", "MB", "GB", "TB"):
        if n < 1024 or u == "TB":
            return f"{n:.1f} {u}" if u != "B" else f"{int(n)} B"
        n /= 1024

class FW:
    z=100
    def __init__(self, master, title, w=640, h=420, x=120, y=60, on_close=None):
        self.master, self.on_close_cb, self.width, self.height = master, on_close, w, h
        self._d={"x":0,"y":0}; self.minimized=False; FW.z+=1
        self.frame=tk.Frame(master,bg=T["window_bg"],highlightbackground=T["border"],highlightthickness=1)
        self.frame.place(x=x,y=y,width=w,height=h); self.frame.lift()
        self.tb=tk.Frame(self.frame,bg=T["window_title_active"],height=32); self.tb.pack(fill=tk.X); self.tb.pack_propagate(False)
        self.tl=tk.Label(self.tb,text=f"  {title}",bg=T["window_title_active"],fg=T["text"],font=("Segoe UI",10),anchor="w")
        self.tl.pack(side=tk.LEFT,fill=tk.X,expand=True)
        bf=tk.Frame(self.tb,bg=T["window_title_active"]); bf.pack(side=tk.RIGHT)
        tk.Button(bf,text="—",width=3,relief=tk.FLAT,bg=T["window_title_active"],fg=T["text"],command=self.minimize).pack(side=tk.LEFT)
        tk.Button(bf,text="✕",width=3,relief=tk.FLAT,bg=T["window_title_active"],fg=T["text"],activebackground=T["danger"],command=self.close).pack(side=tk.LEFT)
        self.content=tk.Frame(self.frame,bg=T["window_bg"]); self.content.pack(fill=tk.BOTH,expand=True)
        for wdg in (self.tb,self.tl):
            wdg.bind("<ButtonPress-1>",self._sd); wdg.bind("<B1-Motion>",self._od); wdg.bind("<Button-1>",self._fc)
        self.frame.bind("<Button-1>",self._fc)
    def _fc(self,e=None): FW.z+=1; self.frame.lift()
    def _sd(self,e): self._d={"x":e.x,"y":e.y}; self._fc()
    def _od(self,e):
        x=max(0,min(self.frame.winfo_x()+e.x-self._d["x"], self.master.winfo_width()-80))
        y=max(0,min(self.frame.winfo_y()+e.y-self._d["y"], self.master.winfo_height()-TH-40))
        self.frame.place(x=x,y=y)
    def minimize(self): self.frame.place_forget(); self.minimized=True
    def restore(self): self.frame.place(x=120,y=60,width=self.width,height=self.height); self.minimized=False; self._fc()
    def close(self):
        self.frame.destroy()
        if self.on_close_cb: self.on_close_cb(self)

class DI:
    def __init__(self, parent, x, y, label, emoji, command, color="#0078d4"):
        self.parent,self.command,self._x,self._y,self._h=parent,command,x,y,None
        self.items=[]
        parent.create_rectangle(x,y,x+IS,y+IS-8,fill="",outline="",tags="icon")
        e=parent.create_text(x+IS//2,y+26,text=emoji,font=("Segoe UI Emoji",28),fill=color,tags="icon")
        l=parent.create_text(x+IS//2,y+IS+4,text=label,font=("Segoe UI",9),fill=T["text"],tags="icon",width=IS+20)
        self.items=[e,l]
        for it in self.items:
            parent.tag_bind(it,"<Button-1>",lambda e:command())
            parent.tag_bind(it,"<Double-Button-1>",lambda e:command())

class SF(tk.Frame):
    def __init__(self, root, bg="#000"):
        super().__init__(root,bg=bg); self.place(x=0,y=0,relwidth=1,relheight=1); self.lift()

class VMaxWindowsOS:
    def __init__(self, fullscreen=False, force_reinstall=False):
        self.root=tk.Tk(); self.root.title("VMAX OS"); self.root.geometry(f"{SW}x{SH}"); self.root.minsize(960,600)
        self.root.configure(bg="#000"); self.fullscreen=fullscreen
        if fullscreen: self.root.attributes("-fullscreen", True)
        self.state=load_state()
        if force_reinstall: self.state["installed"]=False; self.state["boot_count"]=0; save_state(self.state)
        self.open_windows=[]; self.start_menu_open=False; self.notif_open=False; self._clock_job=None
        self.desktop=self.taskbar=self.start_menu=self.notif_panel=self.stage=None
        self.cwd=str(_FS); self.procs=[dict(p) for p in PROCS]
        self.root.bind("<Escape>", self._tf); self.root.bind("<F11>", self._tf)
        self.root.bind("<Control-r>", lambda e: self._open_run()); self.root.bind("<Control-l>", lambda e: self._lock())
        self.root.protocol("WM_DELETE_WINDOW", self._quit)
        log_ev("INFO","Kernel","Power-on"); self.root.after(50, self._power)

    def _cs(self):
        if self.stage: self.stage.destroy(); self.stage=None

    def _power(self):
        self._cs(); self.stage=SF(self.root, T["bios_bg"])
        tx=tk.Text(self.stage,bg=T["bios_bg"],fg=T["bios_fg"],font=("Consolas",11),relief=tk.FLAT,state=tk.DISABLED,cursor="arrow")
        tx.pack(fill=tk.BOTH,expand=True,padx=24,pady=20)
        lines=["VMAX BIOS / UEFI  Version 2.0.0","","CPU ...... Python "+platform.python_version(),
               f"Host ..... {platform.system()} {platform.release()}","Memory ... OK","Storage .. OK  [vmax_os_data]",
               "Network .. OK","", "Boot device: Internal VMAX Image","Loading boot manager...","",]
        def tl(i=0):
            if i>=len(lines): self.root.after(400, self._ab); return
            tx.configure(state=tk.NORMAL); tx.insert(tk.END, lines[i]+"\n"); tx.configure(state=tk.DISABLED); tx.see(tk.END)
            self.root.after(50 if i>2 else 30, lambda: tl(i+1))
        tl()

    def _ab(self):
        (self._setup if not self.state.get("installed") else self._boot)()

    def _setup(self):
        self._cs(); self.stage=SF(self.root, T["setup_bg"]); self._ss=0
        self._sd={"language":"th","hostname":"VMAX-PC","username":"User","password":""}; self._rs()

    def _rs(self):
        for w in self.stage.winfo_children(): w.destroy()
        left=tk.Frame(self.stage,bg="#005a9e",width=260); left.pack(side=tk.LEFT,fill=tk.Y); left.pack_propagate(False)
        tk.Label(left,text="VMAX OS",bg="#005a9e",fg="#fff",font=("Segoe UI",20,"bold")).pack(anchor="w",padx=24,pady=(40,4))
        tk.Label(left,text="Setup",bg="#005a9e",fg="#cce4f7",font=("Segoe UI",11)).pack(anchor="w",padx=24)
        for i,s in enumerate(["1. Language","2. PC name","3. Account","4. Install","5. Done"]):
            tk.Label(left,text=s,bg="#005a9e",fg="#fff" if i==self._ss else "#8eb8d8",
                     font=("Segoe UI",10,"bold" if i==self._ss else "normal")).pack(anchor="w",padx=24,pady=5)
        right=tk.Frame(self.stage,bg="#f3f3f3"); right.pack(side=tk.LEFT,fill=tk.BOTH,expand=True)
        if self._ss==0:
            tk.Label(right,text="Language",bg="#f3f3f3",fg="#111",font=("Segoe UI",15,"bold")).pack(anchor="w",padx=36,pady=(36,10))
            lang=tk.StringVar(value=self._sd["language"])
            for c,l in [("th","ไทย"),("en","English")]:
                tk.Radiobutton(right,text=l,variable=lang,value=c,bg="#f3f3f3",fg="#111",font=("Segoe UI",11),selectcolor="#fff").pack(anchor="w",padx=44,pady=3)
            def n(): self._sd["language"]=lang.get(); self._ss=1; self._rs()
            tk.Button(right,text="Next →",bg=T["accent"],fg="#fff",relief=tk.FLAT,padx=18,pady=7,command=n).pack(anchor="w",padx=36,pady=24)
        elif self._ss==1:
            tk.Label(right,text="Computer name",bg="#f3f3f3",fg="#111",font=("Segoe UI",15,"bold")).pack(anchor="w",padx=36,pady=(36,8))
            host=tk.StringVar(value=self._sd["hostname"])
            tk.Entry(right,textvariable=host,font=("Segoe UI",12),width=26).pack(anchor="w",padx=36,pady=10)
            def n(): self._sd["hostname"]=(host.get().strip() or "VMAX-PC")[:32]; self._ss=2; self._rs()
            tk.Button(right,text="Next →",bg=T["accent"],fg="#fff",relief=tk.FLAT,padx=18,pady=7,command=n).pack(anchor="w",padx=36,pady=16)
        elif self._ss==2:
            tk.Label(right,text="Create account",bg="#f3f3f3",fg="#111",font=("Segoe UI",15,"bold")).pack(anchor="w",padx=36,pady=(36,8))
            user,pwd=tk.StringVar(value=self._sd["username"]),tk.StringVar()
            tk.Entry(right,textvariable=user,font=("Segoe UI",12),width=26).pack(anchor="w",padx=36,pady=6)
            tk.Entry(right,textvariable=pwd,font=("Segoe UI",12),width=26,show="•").pack(anchor="w",padx=36,pady=6)
            def n():
                self._sd["username"]=(user.get().strip() or "User")[:24]; self._sd["password"]=pwd.get(); self._ss=3; self._rs(); self.root.after(120, self._ip)
            tk.Button(right,text="Install →",bg=T["success"],fg="#fff",relief=tk.FLAT,padx=18,pady=7,command=n).pack(anchor="w",padx=36,pady=20)
        elif self._ss==3:
            tk.Label(right,text="Installing...",bg="#f3f3f3",fg="#111",font=("Segoe UI",15,"bold")).pack(anchor="w",padx=36,pady=(36,10))
            self._il=tk.Text(right,bg="#1a1a1a",fg="#33ff33",font=("Consolas",10),height=12,relief=tk.FLAT,state=tk.DISABLED)
            self._il.pack(fill=tk.BOTH,expand=True,padx=36,pady=6)
            self._ib=tk.Label(right,text="0%",bg="#f3f3f3",fg="#333"); self._ib.pack(anchor="w",padx=36)
        else:
            tk.Label(right,text="Installation complete",bg="#f3f3f3",fg="#111",font=("Segoe UI",16,"bold")).pack(anchor="w",padx=36,pady=(50,10))
            tk.Label(right,text=f"PC: {self.state['hostname']}\nUser: {self.state['username']}",bg="#f3f3f3",fg="#333",font=("Segoe UI",11),justify=tk.LEFT).pack(anchor="w",padx=36)
            tk.Button(right,text="Start VMAX OS",bg=T["accent"],fg="#fff",font=("Segoe UI",12,"bold"),relief=tk.FLAT,padx=22,pady=9,command=self._boot).pack(anchor="w",padx=36,pady=24)

    def _ip(self):
        tasks=[("Partitioning...",8),("Copying system files...",20),("Installing kernel...",35),
               ("Drivers...",48),("User profile...",58),("Shell components...",68),
               ("Applications...",78),("OSS Scanner service...",86),("Registry...",93),("Boot record...",100)]
        def w(m):
            self._il.configure(state=tk.NORMAL); self._il.insert(tk.END,m+"\n"); self._il.configure(state=tk.DISABLED); self._il.see(tk.END)
        def run(i=0):
            if i>=len(tasks):
                self.state.update(installed=True,hostname=self._sd["hostname"],username=self._sd["username"],
                    password=self._sd["password"],language=self._sd["language"],
                    installed_at=datetime.now().isoformat(timespec="seconds"),boot_count=0)
                save_state(self.state); log_ev("INFO","Setup","Installed")
                (_FS/"Documents"/"Welcome.txt").write_text(f"Welcome, {self.state['username']}!\n",encoding="utf-8")
                self.root.after(350, lambda: (setattr(self,"_ss",4), self._rs())); return
            m,p=tasks[i]; w(f"[{p:3d}%]  {m}"); self._ib.configure(text=f"{p}%")
            self.root.after(200+i*25, lambda: run(i+1))
        w("VMAX OS Setup\n"); run()

    def _boot(self):
        self._cs(); self.stage=SF(self.root,"#000")
        cv=tk.Canvas(self.stage,bg="#000",highlightthickness=0); cv.pack(fill=tk.BOTH,expand=True)
        def draw(p=0):
            cv.delete("all"); w,h=max(cv.winfo_width(),100),max(cv.winfo_height(),100)
            cv.create_text(w//2,h//2-36,text="VMAX OS",fill="#fff",font=("Segoe UI",34,"bold"))
            cv.create_text(w//2,h//2+6,text=self.state.get("hostname","VMAX-PC"),fill="#888",font=("Segoe UI",11))
            bw=220; x0,y0=w//2-bw//2,h//2+48
            cv.create_rectangle(x0,y0,x0+bw,y0+4,outline="#333",fill="#222")
            cv.create_rectangle(x0,y0,x0+int(bw*p/100),y0+4,outline="",fill="#0078d4")
        def tick(p=0):
            draw(p)
            if p>=100:
                self.state["boot_count"]=self.state.get("boot_count",0)+1; save_state(self.state)
                log_ev("INFO","Boot",f"Boot #{self.state['boot_count']}"); self.root.after(280, self._login); return
            self.root.after(35, lambda: tick(p+5))
        self.root.after(60, lambda: tick(0))

    def _login(self):
        self._cs(); self.stage=SF(self.root, T["login_bg"])
        bg=tk.Canvas(self.stage,highlightthickness=0,bg=T["login_bg"]); bg.pack(fill=tk.BOTH,expand=True)
        def paint(e=None):
            bg.delete("all"); w,h=bg.winfo_width(),bg.winfo_height()
            if w<10: return
            for i in range(18):
                r,g,b=int(26+i*1.5),int(26+i*2),int(46+i*3)
                bg.create_rectangle(0,int(h*i/18),w,int(h*(i+1)/18)+1,fill=f"#{r:02x}{g:02x}{b:02x}",outline="")
            bg.create_text(w//2,h*0.2,text=datetime.now().strftime("%H:%M"),fill="#fff",font=("Segoe UI",52,"bold"))
            bg.create_text(w//2,h*0.2+46,text=datetime.now().strftime("%A, %d %B %Y"),fill="#ccc",font=("Segoe UI",13))
        bg.bind("<Configure>", paint)
        card=tk.Frame(self.stage,bg="#2b2b2b",highlightbackground="#404040",highlightthickness=1)
        card.place(relx=0.5,rely=0.62,anchor="center",width=330,height=250)
        tk.Label(card,text="👤",bg="#2b2b2b",fg="#fff",font=("Segoe UI Emoji",34)).pack(pady=(14,2))
        tk.Label(card,text=self.state.get("username","User"),bg="#2b2b2b",fg="#fff",font=("Segoe UI",13,"bold")).pack()
        tk.Label(card,text=self.state.get("hostname","VMAX-PC"),bg="#2b2b2b",fg="#999",font=("Segoe UI",9)).pack(pady=(0,6))
        pv=tk.StringVar(); need=bool(self.state.get("password"))
        if need:
            tk.Entry(card,textvariable=pv,show="•",font=("Segoe UI",12),bg="#3c3c3c",fg="#fff",insertbackground="#fff",relief=tk.FLAT,width=20).pack(pady=5,ipady=3)
        else:
            tk.Label(card,text="No password — Sign in",bg="#2b2b2b",fg="#888",font=("Segoe UI",9)).pack(pady=5)
        err=tk.Label(card,text="",bg="#2b2b2b",fg=T["danger"],font=("Segoe UI",9)); err.pack()
        def go(e=None):
            if need and pv.get()!=self.state.get("password",""):
                err.configure(text="Incorrect password"); log_ev("WARN","Login","Failed"); return
            log_ev("INFO","Login",f"User {self.state.get('username')}"); self._desktop()
        tk.Button(card,text="Sign in",bg=T["accent"],fg="#fff",font=("Segoe UI",11),relief=tk.FLAT,padx=26,pady=5,command=go).pack(pady=8)
        if need: card.bind_all("<Return>", go)

