        tk.Label(t,text=body,bg="#2d2d2d",fg="#ccc",font=("Segoe UI",9)).pack(anchor="w",padx=12,pady=(0,8))
        t.place(relx=1.0,rely=1.0,x=-16,y=-(TH+16),anchor="se"); self.root.after(3200, t.destroy)

