    def _tsm(self):
        if self.start_menu_open: self.start_menu.place_forget(); self.start_menu_open=False
        else:
            self.root.update_idletasks(); h=self.root.winfo_height()
            self.start_menu.place(x=8,y=h-TH-8,width=280,height=min(500,h-70),anchor="sw"); self.start_menu.lift(); self.start_menu_open=True

    def _tnotif(self):
        if self.notif_open: self.notif_panel.place_forget(); self.notif_open=False; return
        for w in self.notif_panel.winfo_children(): w.destroy()
        tk.Label(self.notif_panel,text="Notifications",bg=T["menu_bg"],fg=T["text"],font=("Segoe UI",11,"bold")).pack(anchor="w",padx=10,pady=8)
        for ev in reversed(lj(_LOG,[])[-8:]):
            tk.Label(self.notif_panel,text=f"{str(ev.get('time',''))[11:19]} {ev.get('source')}: {str(ev.get('message',''))[:45]}",
                     bg=T["menu_bg"],fg=T["text_dim"],font=("Segoe UI",8),anchor="w",wraplength=250,justify=tk.LEFT).pack(fill=tk.X,padx=10,pady=1)
        self.root.update_idletasks(); h=self.root.winfo_height()
        self.notif_panel.place(x=self.root.winfo_width()-8,y=h-TH-8,width=280,height=300,anchor="se"); self.notif_panel.lift(); self.notif_open=True

    def _sar(self, cmd):
        if self.start_menu_open: self.start_menu.place_forget(); self.start_menu_open=False
        cmd()

    def _tick(self):
        if getattr(self,"clock",None): self.clock.configure(text=datetime.now().strftime("%H:%M\n%d/%m/%Y"))
        for p in self.procs: p["cpu"]=max(0.0,min(40.0,p["cpu"]+random.uniform(-0.7,0.7)))
        self._clock_job=self.root.after(1000, self._tick)

    def _spawn(self, title, w=700, h=460):
        n=len(self.open_windows)
        win=FW(self.desktop,title,w,h,60+(n%7)*28,28+(n%6)*22,self._rw)
        self.open_windows.append(win)
        if self.start_menu_open: self.start_menu.place_forget(); self.start_menu_open=False
        return win

    def _rw(self, win):
        if win in self.open_windows: self.open_windows.remove(win)

    def _ctx(self, e):
        m=tk.Menu(self.root,tearoff=0,bg=T["menu_bg"],fg=T["text"],activebackground=T["accent"],font=("Segoe UI",9))
        m.add_command(label="Refresh",command=self._wp)
        m.add_command(label="New Text File",command=self._newfile)
        m.add_separator(); m.add_command(label="Terminal",command=self._terminal)
        m.add_command(label="Task Manager",command=self._taskmgr)
        try: m.tk_popup(e.x_root,e.y_root)
        finally: m.grab_release()

    def _newfile(self):
        name=simpledialog.askstring("New","File name:",initialvalue="New.txt",parent=self.root)
        if name: (_FS/"Desktop"/name).write_text("",encoding="utf-8"); self._toast("Explorer",f"Created {name}")

    # ---- apps ----
    def _thispc(self): self.cwd=str(_FS); self._explorer(str(_FS))
    def _recycle(self):
        win=self._spawn("🗑️ Recycle Bin",520,340)
        lb=tk.Listbox(win.content,bg="#1a1a1a",fg=T["text"],font=("Consolas",10),relief=tk.FLAT); lb.pack(fill=tk.BOTH,expand=True,padx=8,pady=8)
        items=list(_RECYCLE.iterdir()) if _RECYCLE.exists() else []
        lb.insert(tk.END,"(empty)" if not items else "")
        for p in items: lb.insert(tk.END,p.name)
        def empty():
            for p in list(_RECYCLE.iterdir()):
                if p.is_file(): p.unlink()
                else: shutil.rmtree(p,ignore_errors=True)
            lb.delete(0,tk.END); lb.insert(tk.END,"(empty)")
        tk.Button(win.content,text="Empty",bg=T["danger"],fg="#fff",relief=tk.FLAT,command=empty).pack(pady=4)

    def _explorer(self, start=None):
        win=self._spawn("📁 File Explorer",720,460); c=win.content
        pv=tk.StringVar(value=start or self.cwd or str(_FS))
        top=tk.Frame(c,bg=T["window_bg"]); top.pack(fill=tk.X,padx=8,pady=4)
        for lab,p in [("This PC",str(_FS)),("Desktop",str(_FS/"Desktop")),("Docs",str(_FS/"Documents")),("Data",str(_DATA))]:
            tk.Button(top,text=lab,bg=T["taskbar_hover"],fg=T["text"],relief=tk.FLAT,font=("Segoe UI",8),
                      command=lambda p=p: (pv.set(p), ref())).pack(side=tk.LEFT,padx=2)
        row=tk.Frame(c,bg=T["window_bg"]); row.pack(fill=tk.X,padx=8)
        tk.Entry(row,textvariable=pv,bg=T["entry_bg"],fg=T["text"],insertbackground="#fff",font=("Segoe UI",10),relief=tk.FLAT).pack(side=tk.LEFT,fill=tk.X,expand=True,padx=(0,6))
        lb=tk.Listbox(c,bg="#1a1a1a",fg=T["text"],font=("Consolas",10),selectbackground=T["accent"],relief=tk.FLAT); lb.pack(fill=tk.BOTH,expand=True,padx=8,pady=6)
        def ref():
            lb.delete(0,tk.END); p=Path(pv.get())
            if not p.is_dir(): lb.insert(tk.END,"(invalid)"); return
            lb.insert(tk.END,"  ..")
            try:
                for e in sorted(p.iterdir(), key=lambda x:(not x.is_dir(),x.name.lower())):
                    lb.insert(tk.END,f"{'📁 ' if e.is_dir() else '📄 '}{e.name}")
            except Exception: lb.insert(tk.END,"(denied)")
        def go(e=None):
            sel=lb.curselection()
            if not sel: return
            name=lb.get(sel[0]).strip().replace("📁 ","").replace("📄 ","")
            cur=Path(pv.get())
            if name=="..": pv.set(str(cur.parent))
            else:
                n=cur/name
                if n.is_dir(): pv.set(str(n))
                elif n.is_file() and n.suffix.lower()==".py": self._python_lab_open(str(n))
                elif n.is_file() and n.suffix.lower() in (".txt",".log",".md",".json"): self._notepad(str(n))
            ref()
        def delete():
            sel=lb.curselection()
            if not sel: return
            name=lb.get(sel[0]).strip().replace("📁 ","").replace("📄 ","")
            if name=="..": return
            t=Path(pv.get())/name
            if messagebox.askyesno("Delete",f"Move to Recycle?\n{t.name}"):
                dest=_RECYCLE/t.name
                if dest.exists(): dest=_RECYCLE/f"{t.stem}_{int(time.time())}{t.suffix}"
                try: shutil.move(str(t),str(dest)); ref()
                except Exception as ex: messagebox.showerror("Err",str(ex))
        tk.Button(row,text="Go",bg=T["accent"],fg="#fff",relief=tk.FLAT,command=ref).pack(side=tk.LEFT)
        tk.Button(row,text="Del",bg=T["danger"],fg="#fff",relief=tk.FLAT,command=delete).pack(side=tk.LEFT,padx=3)
        lb.bind("<Double-Button-1>",go); ref()

    def _terminal(self):
        win=self._spawn("💻 Terminal",700,400)
        term=scrolledtext.ScrolledText(win.content,bg="#0c0c0c",fg="#ccc",font=("Consolas",11),insertbackground="#fff",relief=tk.FLAT)
        term.pack(fill=tk.BOTH,expand=True,padx=2,pady=2)
        user,host=self.state.get("username","User"),self.state.get("hostname","VMAX-PC")
        prompt=f"{user}@{host}> "
        def sp(): term.insert(tk.END,prompt); term.mark_set("is",tk.INSERT); term.see(tk.END)
        term.insert(tk.END,f"VMAX OS Shell 2.0\nType help.\n\n"); sp(); term.focus_set()
        hist=[]; hi={"i":-1}
        def run(cmd):
            nonlocal prompt
            cmd=cmd.strip()
            if not cmd: return
            hist.append(cmd); hi["i"]=len(hist); parts=cmd.split(); op=parts[0].lower(); args=parts[1:]
            def o(s=""): term.insert(tk.END,(s+"\n") if s else "\n")
            if op in ("help","?"): o(" cd dir mkdir type echo cls ver whoami date tasklist ipconfig systeminfo reg services devices oss notepad calc exit reboot")
            elif op=="cd":
                t=" ".join(args) if args else str(_FS)
                p=Path(t) if Path(t).is_absolute() else Path(self.cwd)/t
                if p.is_dir(): self.cwd=str(p.resolve())
                else: o(" path not found")
            elif op in ("dir","ls"):
                try:
                    for e in sorted(Path(self.cwd).iterdir(), key=lambda x:(not x.is_dir(),x.name.lower())): o(f"  {'<DIR>' if e.is_dir() else '    '} {e.name}")
                except Exception as ex: o(str(ex))
            elif op=="mkdir" and args: (Path(self.cwd)/args[0]).mkdir(exist_ok=True); o(f" created {args[0]}")
            elif op=="type" and args:
                try: o((Path(self.cwd)/args[0]).read_text(encoding="utf-8",errors="ignore")[:2500])
                except Exception as ex: o(str(ex))
            elif op=="echo": o(" "+" ".join(args))
            elif op in ("cls","clear"): term.delete("1.0",tk.END)
            elif op=="ver": o(f" VMAX OS 2.0  boots={self.state.get('boot_count')}")
            elif op=="whoami": o(f" {user}")
            elif op=="date": o(f" {datetime.now():%Y-%m-%d %H:%M:%S}")
            elif op=="tasklist":
                o(f" {'Name':20} {'PID':>6} {'CPU':>6}"); [o(f" {p['name']:20} {p['pid']:6d} {p['cpu']:6.1f}") for p in self.procs]
            elif op=="ipconfig": o(" VMAX NIC  IPv4=10.0.0.2  GW=10.0.0.1")
            elif op=="systeminfo": o(f" OS=VMAX OS 2.0  Host={host}  User={user}  Platform={platform.system()}")
            elif op=="reg":
                for k,v in list(reg_get().items())[:15]: o(f" {k}={v}")
            elif op=="services":
                for n,s,st in SERVICES: o(f" {n:24} {s:10} {st}")
            elif op=="devices":
                for n,s,c in DEVICES: o(f" [{c}] {n} {s}")
            elif op=="oss": self.root.after(40,self._oss)
            elif op=="notepad": self.root.after(40,self._notepad)
            elif op=="calc": self.root.after(40,self._calc)
            elif op=="reboot": o(" Rebooting..."); self.root.after(350,self._reboot); return
            elif op in ("python","py"):
                # run inline: python -c code   OR  python file.py
                if args and args[0] == "-c":
                    o(_run_python_source(" ".join(args[1:]), "<stdin>"))
                elif args:
                    fp = Path(args[0]) if Path(args[0]).is_absolute() else Path(self.cwd)/args[0]
                    if fp.exists():
                        o(_run_python_source(fp.read_text(encoding="utf-8", errors="ignore"), str(fp)))
                    else:
                        o(f"  cannot find {args[0]}")
                else:
                    o(f"  Python {platform.python_version()} (VMAX runtime)")
                    o("  usage: python file.py | python -c code")
            elif op in ("exit","quit"): win.close(); return
            else: o(f" '{op}' not recognized")
            sp()
        def on(e):
            if e.keysym=="Return": run(term.get("is",tk.END).rstrip("\n")); return "break"
            if e.keysym=="BackSpace" and term.compare(tk.INSERT,"<=","is"): return "break"
            if e.keysym=="Up" and hist:
                hi["i"]=max(0,hi["i"]-1); term.delete("is",tk.END); term.insert("is",hist[hi["i"]]); return "break"
            if term.compare(tk.INSERT,"<","is"): term.mark_set(tk.INSERT,tk.END)
        term.bind("<Key>",on)

    def _notepad(self, path=None):
        win=self._spawn("📝 Notepad",560,400)
        text=scrolledtext.ScrolledText(win.content,bg="#1e1e1e",fg="#d4d4d4",font=("Consolas",11),insertbackground="#fff",relief=tk.FLAT,undo=True)
        text.pack(fill=tk.BOTH,expand=True); cur={"p":path}
        if path and Path(path).is_file(): text.insert(tk.END, Path(path).read_text(encoding="utf-8",errors="ignore"))
        bar=tk.Frame(win.content,bg=T["window_title"]); bar.pack(fill=tk.X,side=tk.BOTTOM)
        def save():
            p=cur["p"] or filedialog.asksaveasfilename(defaultextension=".txt",initialdir=str(_FS/"Documents"))
            if p: Path(p).write_text(text.get("1.0",tk.END),encoding="utf-8"); cur["p"]=p; self._toast("Notepad","Saved")
        def load():
            p=filedialog.askopenfilename(initialdir=str(_FS))
            if p: text.delete("1.0",tk.END); text.insert(tk.END,Path(p).read_text(encoding="utf-8",errors="ignore")); cur["p"]=p
        tk.Button(bar,text="Open",bg=T["accent"],fg="#fff",relief=tk.FLAT,command=load).pack(side=tk.LEFT,padx=4,pady=4)
        tk.Button(bar,text="Save",bg=T["success"],fg="#fff",relief=tk.FLAT,command=save).pack(side=tk.LEFT,padx=4,pady=4)

    def _calc(self):
        win=self._spawn("🧮 Calculator",300,380); c=win.content; expr=tk.StringVar(value="")
        tk.Label(c,textvariable=expr,bg="#111",fg="#0f0",font=("Consolas",16),anchor="e",padx=8,pady=10).pack(fill=tk.X,padx=6,pady=6)
        grid=tk.Frame(c,bg=T["window_bg"]); grid.pack()
        def press(k):
            if k=="C": expr.set("")
            elif k=="=":
                try: expr.set(str(eval(expr.get(),{"__builtins__":{}},{})))
                except Exception: expr.set("Error")
            else: expr.set(expr.get()+k)
        for r,row in enumerate([("7","8","9","/"),("4","5","6","*"),("1","2","3","-"),("0",".","=","+"),("C","(",")","%")]):
            for col,k in enumerate(row):
                tk.Button(grid,text=k,width=4,height=2,font=("Segoe UI",11),bg=T["entry_bg"],fg=T["text"],relief=tk.FLAT,command=lambda x=k:press(x)).grid(row=r,column=col,padx=2,pady=2)

    def _paint(self):
        win=self._spawn("🎨 Paint",600,440); cv=tk.Canvas(win.content,bg="#fff",highlightthickness=1); cv.pack(fill=tk.BOTH,expand=True,padx=4,pady=4)
        st={"x":None,"y":None,"c":"#000","w":3}
        def start(e): st["x"],st["y"]=e.x,e.y
        def draw(e):
            if st["x"] is not None:
                cv.create_line(st["x"],st["y"],e.x,e.y,fill=st["c"],width=st["w"],capstyle=tk.ROUND); st["x"],st["y"]=e.x,e.y
        def stop(e): st["x"]=st["y"]=None
        cv.bind("<Button-1>",start); cv.bind("<B1-Motion>",draw); cv.bind("<ButtonRelease-1>",stop)
        bar=tk.Frame(win.content,bg=T["window_bg"]); bar.pack(fill=tk.X)
        def pick():
            c=colorchooser.askcolor(color=st["c"])[1]
            if c: st["c"]=c
        tk.Button(bar,text="Color",bg=T["accent"],fg="#fff",relief=tk.FLAT,command=pick).pack(side=tk.LEFT,padx=4,pady=4)
        tk.Button(bar,text="Clear",bg=T["danger"],fg="#fff",relief=tk.FLAT,command=lambda:cv.delete("all")).pack(side=tk.LEFT,padx=4)

