        def ref():
            lb.delete(0,tk.END); lb.insert(tk.END,f"{'Name':20} {'PID':>6} {'CPU%':>7} {'Mem':>5}")
            for p in sorted(self.procs,key=lambda x:-x["cpu"]): lb.insert(tk.END,f"{p['name']:20} {p['pid']:6d} {p['cpu']:7.1f} {p['mem']:5d}")
