    def _oss(self):
        win=self._spawn("🛡️ OSS Scanner",760,500); c=win.content
        top=tk.Frame(c,bg=T["window_bg"]); top.pack(fill=tk.X,padx=10,pady=6)
        tk.Label(top,text="OSS Scanner",bg=T["window_bg"],fg=T["text"],font=("Segoe UI",14,"bold")).pack(side=tk.LEFT)
        tk.Label(top,text="Ready" if _OSS_AVAILABLE else "Demo",bg=T["window_bg"],fg=T["success"] if _OSS_AVAILABLE else T["text_dim"]).pack(side=tk.RIGHT)
        ctrl=tk.Frame(c,bg=T["window_bg"]); ctrl.pack(fill=tk.X,padx=10)
        nv,pv=tk.StringVar(value="demo-lib"),tk.StringVar()
        tk.Entry(ctrl,textvariable=nv,bg=T["entry_bg"],fg=T["text"],width=14,relief=tk.FLAT).pack(side=tk.LEFT,padx=3)
        tk.Button(ctrl,text="Path",bg=T["accent"],fg="#fff",relief=tk.FLAT,command=lambda:pv.set(filedialog.askdirectory() or "")).pack(side=tk.LEFT,padx=3)
        out=scrolledtext.ScrolledText(c,bg="#151515",fg="#d4d4d4",font=("Consolas",10),relief=tk.FLAT,height=16); out.pack(fill=tk.BOTH,expand=True,padx=10,pady=6)
        def log(m): out.insert(tk.END,m+"\n"); out.see(tk.END)
        def enroll():
            if _OSS_AVAILABLE:
                r=_oss.vmax_oss_enroll(name=nv.get().strip() or "demo"); log(json.dumps(r,ensure_ascii=False,indent=2))
                if pv.get() and r.get("st")=="ok": log(json.dumps(_oss.vmax_oss_set_local_path(r["project"]["id"],pv.get()),ensure_ascii=False,indent=2))
            else: log("[demo] enrolled")
        def scan():
            pid=(nv.get().strip() or "demo-lib").lower().replace(" ","-")
            if _OSS_AVAILABLE:
                try: _oss.vmax_oss_enroll(name=nv.get().strip() or "demo-lib")
                except Exception: pass
                if pv.get(): _oss.vmax_oss_set_local_path(pid,pv.get())
                r=_oss.vmax_oss_scan(pid)
                if r.get("st")=="ok":
                    s=r["summary"]; log(f"\n=== {r['report_id']} findings={s['total']} ===")
                    for f in r["report"]["findings"][:15]: log(f"  [{f['severity'].upper():8}] {f['rule_id']} {f['file']}:{f['line']} {f['name']}")
                else: log(json.dumps(r,ensure_ascii=False,indent=2))
            else: log("[demo] CWE-78 CRITICAL | CWE-89 HIGH | CWE-798 HIGH")
        bf=tk.Frame(c,bg=T["window_bg"]); bf.pack(fill=tk.X,padx=10,pady=4)
        tk.Button(bf,text="Enroll",bg=T["accent"],fg="#fff",relief=tk.FLAT,command=enroll).pack(side=tk.LEFT,padx=3)
        tk.Button(bf,text="Scan",bg=T["success"],fg="#fff",relief=tk.FLAT,command=scan).pack(side=tk.LEFT,padx=3)
        log("OSS Scanner ready.")

    def _open_run(self):
        win=self._spawn("Run",400,130); c=win.content
        tk.Label(c,text="Open:",bg=T["window_bg"],fg=T["text"],font=("Segoe UI",10)).pack(anchor="w",padx=14,pady=(12,2))
        v=tk.StringVar(); e=tk.Entry(c,textvariable=v,bg=T["entry_bg"],fg=T["text"],insertbackground="#fff",font=("Segoe UI",11),relief=tk.FLAT)
        e.pack(fill=tk.X,padx=14,pady=4); e.focus_set()
        mp={"cmd":self._terminal,"notepad":self._notepad,"calc":self._calc,"mspaint":self._paint,"explorer":self._explorer,
            "taskmgr":self._taskmgr,"control":self._control,"devmgmt":self._devices,"services":self._services,
            "eventvwr":self._events,"regedit":self._registry,"msinfo32":self._sysinfo,"oss":self._oss,
            "store":self._store,"mail":self._mail,"wmplayer":self._media,"photos":self._photos,
            "clock":self._clock_app,"weather":self._weather,"writer":self._writer,"excel":self._sheets,
            "sheets":self._sheets,"defender":self._defender,"chat":self._chat,"gacha":self._gacha_app,"activate":self._activate,"slui":self._activate,"wifi":self._wifi}
        def go(ev=None):
            k=v.get().strip().lower()
            for key,fn in mp.items():
                if key in k or k in key: win.close(); fn(); return
            messagebox.showinfo("Run",f"Cannot find '{v.get()}'")
        tk.Button(c,text="OK",bg=T["accent"],fg="#fff",relief=tk.FLAT,command=go).pack(pady=6); e.bind("<Return>",go)

    def _search(self):
        q=simpledialog.askstring("Search","Search:",parent=self.root)
        if not q: return
        ql=q.lower()
        for key,fn in [("oss",self._oss),("term",self._terminal),("note",self._notepad),("calc",self._calc),
                       ("paint",self._paint),("task",self._taskmgr),("device",self._devices),("service",self._services),
                       ("event",self._events),("reg",self._registry),("network",self._network),("update",self._update),
                       ("system",self._sysinfo),("control",self._control),("explorer",self._explorer),("setting",self._settings)]:
            if key in ql: fn(); return
        messagebox.showinfo("Search",f"No results for '{q}'")


