        canvas=tk.Canvas(c,bg="#111",highlightthickness=0,height=220); canvas.pack(fill=tk.BOTH,expand=True,padx=14,pady=6)
        def draw(e=None):
            canvas.delete("all"); w,h=max(canvas.winfo_width(),100),max(canvas.winfo_height(),100)
            # fake photo gradient
            for i in range(12):
                r,g,b=40+i*8,60+i*5,90+i*6
                canvas.create_rectangle(0,int(h*i/12),w,int(h*(i+1)/12)+1,fill=f"#{r:02x}{g:02x}{b:02x}",outline="")
            canvas.create_text(w//2,h//2,text="📷  No photos yet\nDrop images into Pictures folder",fill="#ffffff99",font=("Segoe UI",12),justify=tk.CENTER)
        canvas.bind("<Configure>",draw)
