        win=self._spawn("🕐 Clock",360,300); c=win.content
        lbl=tk.Label(c,text="",bg=T["window_bg"],fg=T["text"],font=("Segoe UI",36,"bold")); lbl.pack(pady=(30,4))
        date=tk.Label(c,text="",bg=T["window_bg"],fg=T["text_dim"],font=("Segoe UI",11)); date.pack()
        def tick():
            if not win.frame.winfo_exists(): return
            lbl.configure(text=datetime.now().strftime("%H:%M:%S"))
            date.configure(text=datetime.now().strftime("%A, %d %B %Y"))
            win.frame.after(500, tick)
        tick()
        tk.Label(c,text="Alarm / Timer — demo mode",bg=T["window_bg"],fg=T["text_dim"],font=("Segoe UI",9)).pack(pady=16)

