        days_var=tk.StringVar(value=str(self.state.get("recycle_auto_days",30)))
        tk.Entry(c,textvariable=days_var,bg=T["entry_bg"],fg=T["text"],insertbackground="#fff",font=("Segoe UI",12),relief=tk.FLAT,width=8).pack(anchor="w",padx=16,pady=4)
        temp_var=tk.BooleanVar(value=bool(self.state.get("cleanup_temps", False)))
