        bf=tk.Frame(c,bg=T["window_bg"]); bf.pack(anchor="w",padx=16,pady=12)
        tk.Button(bf,text="บันทึก",bg=T["accent"],fg="#fff",relief=tk.FLAT,padx=14,command=save).pack(side=tk.LEFT,padx=3)
        tk.Button(bf,text="ล้างตอนนี้",bg=T["danger"],fg="#fff",relief=tk.FLAT,padx=14,command=run_now).pack(side=tk.LEFT,padx=3)
        tk.Label(c,text="ตัวเลือก 1: ลบเฉพาะถังขยะที่เก่ากว่า N วัน\nตัวเลือก 2: เปิด leftover แล้วจะลบ temp/cache ที่เก่ากว่า N วันด้วย",
                 bg=T["window_bg"],fg=T["text_dim"],font=("Segoe UI",8),justify=tk.LEFT).pack(anchor="w",padx=16,pady=8)

