    def _wifi(self):
        win=self._spawn("📶 Wi‑Fi & Internet", 520, 440); c=win.content
        tk.Label(c,text="เครือข่ายใกล้เคียง",bg=T["window_bg"],fg=T["text"],font=("Segoe UI",14,"bold")).pack(anchor="w",padx=14,pady=(12,4))
        conn=self.state.get("wifi_ssid")
        status=tk.Label(c,text=(f"● เชื่อมต่อ: {conn}" if self.state.get("wifi_connected") and conn else "○ ไม่ได้เชื่อมต่อ"),
                        bg=T["window_bg"],fg=(T["success"] if self.state.get("wifi_connected") else T["text_dim"]),font=("Segoe UI",10))
        status.pack(anchor="w",padx=14,pady=4)
        lb=tk.Listbox(c,bg="#1a1a1a",fg=T["text"],font=("Segoe UI",10),selectbackground=T["accent"],relief=tk.FLAT,height=8)
        lb.pack(fill=tk.BOTH,expand=True,padx=14,pady=6)
        nets=list(_FAKE_WIFI)
        def refresh():
            lb.delete(0,tk.END)
            for n in nets:
                lock="🔒" if n["secure"] else "🔓"
                bar="▂▄▆█"[min(3,n["signal"]//25)]
                mark=" (connected)" if self.state.get("wifi_connected") and self.state.get("wifi_ssid")==n["ssid"] else ""
                lb.insert(tk.END, f" {lock}  {n['ssid']:<18}  {bar} {n['signal']}%{mark}")
        refresh()
        def connect():
            sel=lb.curselection()
            if not sel: return
            net=nets[sel[0]]
            if net["secure"]:
                # password dialog
                dlg=tk.Toplevel(self.root); dlg.title("Connect"); dlg.geometry("360x180"); dlg.configure(bg=T["window_bg"])
                dlg.transient(self.root); dlg.grab_set()
                tk.Label(dlg,text=f"รหัสผ่านสำหรับ\n{net['ssid']}",bg=T["window_bg"],fg=T["text"],font=("Segoe UI",11)).pack(pady=(16,6))
                pw=tk.StringVar()
                ent=tk.Entry(dlg,textvariable=pw,show="•",bg=T["entry_bg"],fg=T["text"],insertbackground="#fff",font=("Segoe UI",12),relief=tk.FLAT,width=22)
                ent.pack(pady=6,ipady=4); ent.focus_set()
                err=tk.Label(dlg,text="",bg=T["window_bg"],fg=T["danger"],font=("Segoe UI",9)); err.pack()
                def go(ev=None):
                    # demo: accept any password length >= 4, or "vmax123"
                    p=pw.get()
                    if len(p)<4:
                        err.configure(text="รหัสสั้นเกินไป (อย่างน้อย 4 ตัว)"); return
                    self.state["wifi_ssid"]=net["ssid"]; self.state["wifi_connected"]=True; save_state(self.state)
                    status.configure(text=f"● เชื่อมต่อ: {net['ssid']}",fg=T["success"])
                    log_ev("INFO","Network",f"Connected to {net['ssid']}")
                    self._toast("Wi‑Fi", f"Connected to {net['ssid']}")
                    dlg.destroy(); refresh()
                tk.Button(dlg,text="Connect",bg=T["accent"],fg="#fff",relief=tk.FLAT,padx=16,pady=6,command=go).pack(pady=8)
                ent.bind("<Return>", go)
            else:
                self.state["wifi_ssid"]=net["ssid"]; self.state["wifi_connected"]=True; save_state(self.state)
                status.configure(text=f"● เชื่อมต่อ: {net['ssid']}",fg=T["success"])
                log_ev("INFO","Network",f"Connected to {net['ssid']} (open)")
                self._toast("Wi‑Fi", f"Connected to {net['ssid']}"); refresh()
        def disconnect():
            self.state["wifi_connected"]=False; self.state["wifi_ssid"]=None; save_state(self.state)
            status.configure(text="○ ไม่ได้เชื่อมต่อ",fg=T["text_dim"]); refresh()
            self._toast("Wi‑Fi","Disconnected")
        bf=tk.Frame(c,bg=T["window_bg"]); bf.pack(fill=tk.X,padx=14,pady=8)
        tk.Button(bf,text="Connect",bg=T["accent"],fg="#fff",relief=tk.FLAT,padx=12,command=connect).pack(side=tk.LEFT,padx=3)
        tk.Button(bf,text="Disconnect",bg=T["danger"],fg="#fff",relief=tk.FLAT,padx=12,command=disconnect).pack(side=tk.LEFT,padx=3)
        tk.Button(bf,text="Refresh",bg=T["taskbar_hover"],fg="#fff",relief=tk.FLAT,padx=12,command=refresh).pack(side=tk.LEFT,padx=3)



