    def _backup(self):
        win=self._spawn("💾 Backup", 460, 340); c=win.content
        tk.Label(c,text="Backup & Restore",bg=T["window_bg"],fg=T["text"],font=("Segoe UI",13,"bold")).pack(anchor="w",padx=14,pady=(12,6))
        last=self.state.get("backup_last") or "ยังไม่เคยสำรอง"
        st=tk.Label(c,text=f"ล่าสุด: {last}",bg=T["window_bg"],fg=T["text_dim"],font=("Segoe UI",10)); st.pack(anchor="w",padx=14)
        log=scrolledtext.ScrolledText(c,bg="#151515",fg="#aaa",font=("Consolas",9),height=8,relief=tk.FLAT); log.pack(fill=tk.BOTH,expand=True,padx=14,pady=8)
        def run():
            log.insert(tk.END,"Starting backup of vmax_os_data...\n")
            bdir=_DATA/"backups"; bdir.mkdir(exist_ok=True)
            name=f"backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
            payload={"state":self.state,"registry":reg_get(),"licenses":_license_db(),
                     "time":datetime.now().isoformat(timespec="seconds")}
            (bdir/name).write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding="utf-8")
            self.state["backup_last"]=payload["time"]; save_state(self.state)
            st.configure(text=f"ล่าสุด: {payload['time']}")
            log.insert(tk.END,f"Saved {name}\nDone.\n"); log_ev("INFO","Backup",name); self._toast("Backup","Completed")
        tk.Button(c,text="Backup now",bg=T["accent"],fg="#fff",relief=tk.FLAT,padx=14,pady=6,command=run).pack(pady=4)

    def _calendar(self):
        win=self._spawn("📅 Calendar", 420, 360); c=win.content
        now=datetime.now()
        tk.Label(c,text=now.strftime("%B %Y"),bg=T["window_bg"],fg=T["text"],font=("Segoe UI",14,"bold")).pack(pady=(12,4))
        tk.Label(c,text=now.strftime("%A, %d %B %Y"),bg=T["window_bg"],fg=T["accent2"],font=("Segoe UI",11)).pack()
        grid=tk.Frame(c,bg=T["window_bg"]); grid.pack(pady=12)
        for i,d in enumerate(["Mo","Tu","We","Th","Fr","Sa","Su"]):
            tk.Label(grid,text=d,bg=T["window_bg"],fg=T["text_dim"],width=4,font=("Segoe UI",8)).grid(row=0,column=i)
        import calendar as _cal
        weeks=_cal.monthcalendar(now.year,now.month)
        for r,week in enumerate(weeks):
            for col,day in enumerate(week):
                txt=str(day) if day else ""
                bg=T["accent"] if day==now.day else T["entry_bg"]
                tk.Label(grid,text=txt,bg=bg,fg=T["text"],width=4,font=("Segoe UI",9)).grid(row=r+1,column=col,padx=1,pady=1)

