    def _perfmon(self):
        win=self._spawn("📈 Performance", 520, 380); c=win.content
        tk.Label(c,text="Performance Monitor",bg=T["window_bg"],fg=T["text"],font=("Segoe UI",13,"bold")).pack(anchor="w",padx=12,pady=(10,4))
        canvas=tk.Canvas(c,bg="#0d0d0d",height=160,highlightthickness=0); canvas.pack(fill=tk.X,padx=12,pady=6)
        hist=[]
        info=tk.Label(c,text="",bg=T["window_bg"],fg=T["text_dim"],font=("Consolas",9),justify=tk.LEFT); info.pack(anchor="w",padx=12)
        def tick():
            if not win.frame.winfo_exists(): return
            cpu=sum(p["cpu"] for p in self.procs)/max(1,len(self.procs))
            mem=sum(p["mem"] for p in self.procs)
            hist.append(cpu)
            if len(hist)>60: hist.pop(0)
            canvas.delete("all"); w,h=max(canvas.winfo_width(),100),160
            if len(hist)>1:
                pts=[]
                for i,v in enumerate(hist):
                    x=int(i*(w-4)/max(1,len(hist)-1)); y=h-10-int(min(100,v)/100*(h-20))
                    pts.extend([x,y])
                if len(pts)>=4: canvas.create_line(*pts,fill="#0078d4",width=2)
            canvas.create_text(8,12,text=f"CPU ~{cpu:.1f}%",fill="#7dd3fc",anchor="w",font=("Consolas",9))
            info.configure(text=f"Processes: {len(self.procs)}  Mem (sim): {mem} MB  Volume: {self.state.get('volume')}%  Wi-Fi: {self.state.get('wifi_ssid') or '—'}")
            win.frame.after(800, tick)
        tick()

