    def _apply_os_theme(self):
        profiles = _list_os_profiles()
        pid = _get_active_os_id()
        prof = profiles.get(pid) or _default_os_profile()
        th = prof.get("theme") or {}
        if th.get("desktop_top"): T["desktop_top"] = th["desktop_top"]
        if th.get("desktop_bot"): T["desktop_bot"] = th["desktop_bot"]
        if th.get("accent"):
            T["accent"] = th["accent"]
            T["start_btn"] = th["accent"]
            T["window_title_active"] = th["accent"]
        if th.get("taskbar"): T["taskbar"] = th["taskbar"]
        self.active_os = prof
        return prof

    def _os_system(self):
        win=self._spawn("🖥️ OS System", 560, 480); c=win.content
        tk.Label(c,text="OS System — สลับระบบปฏิบัติการ",bg=T["window_bg"],fg=T["text"],font=("Segoe UI",13,"bold")).pack(anchor="w",padx=14,pady=(12,4))
        tk.Label(c,text="เลือก OS ที่ติดตั้งแล้ว หรือนำเข้าไฟล์ OS จากภายนอก แล้วสลับใช้งาน",
                 bg=T["window_bg"],fg=T["text_dim"],font=("Segoe UI",9)).pack(anchor="w",padx=14)
        cur=tk.Label(c,text=f"กำลังใช้: {_get_active_os_id()}",bg=T["window_bg"],fg=T["success"],font=("Segoe UI",10)); cur.pack(anchor="w",padx=14,pady=6)
        lb=tk.Listbox(c,bg="#1a1a1a",fg=T["text"],font=("Consolas",10),selectbackground=T["accent"],relief=tk.FLAT,height=10)
        lb.pack(fill=tk.BOTH,expand=True,padx=14,pady=6)
        profiles={}
        def refresh():
            nonlocal profiles
            lb.delete(0,tk.END); profiles=_list_os_profiles()
            for pid,p in profiles.items():
                mark="► " if pid==_get_active_os_id() else "  "
                inst="[installed]" if p.get("installed") else "[not installed]"
                lb.insert(tk.END, f"{mark}{p.get('name','?'):16}  {p.get('version','?'):8}  {inst}  by {p.get('author','?')}")
            cur.configure(text=f"กำลังใช้: {_get_active_os_id()}")
        refresh()
        def do_switch():
            sel=lb.curselection()
            if not sel: return
            pid=list(profiles.keys())[sel[0]]; prof=profiles[pid]
            if not messagebox.askyesno("Switch OS", f"สลับไปใช้ «{prof.get('name')}» ?\nเครื่องจะรีบูตเข้าสู่ OS นี้"):
                return
            _set_active_os_id(pid); log_ev("INFO","OS",f"Switch to {pid}")
            self._switch_reboot(prof)
        def do_import():
            fp=filedialog.askopenfilename(title="เลือกไฟล์ OS",filetypes=[("OS Profile","*.json"),("All","*.*")])
            if not fp: return
            r=_import_os_file(fp)
            if r.get("st")=="ok":
                self._toast("OS System", f"นำเข้า {r['profile'].get('name')} แล้ว"); refresh()
            else:
                messagebox.showerror("Import", r.get("msg","error"))
        def do_export():
            sel=lb.curselection()
            if not sel: return
            pid=list(profiles.keys())[sel[0]]; prof=profiles[pid]
            fp=filedialog.asksaveasfilename(defaultextension=".json",initialfile=f"{pid}.json",filetypes=[("OS Profile","*.json")])
            if fp:
                Path(fp).write_text(json.dumps(prof,ensure_ascii=False,indent=2),encoding="utf-8")
                self._toast("OS System", f"Export {pid}")
        bf=tk.Frame(c,bg=T["window_bg"]); bf.pack(fill=tk.X,padx=14,pady=8)
        tk.Button(bf,text="สลับ OS",bg=T["accent"],fg="#fff",relief=tk.FLAT,padx=12,command=do_switch).pack(side=tk.LEFT,padx=3)
        tk.Button(bf,text="นำเข้าไฟล์ OS",bg=T["success"],fg="#fff",relief=tk.FLAT,padx=12,command=do_import).pack(side=tk.LEFT,padx=3)
        tk.Button(bf,text="Export",bg=T["taskbar_hover"],fg="#fff",relief=tk.FLAT,padx=12,command=do_export).pack(side=tk.LEFT,padx=3)
        tk.Button(bf,text="Refresh",bg=T["taskbar_hover"],fg="#fff",relief=tk.FLAT,command=refresh).pack(side=tk.LEFT,padx=3)
        tk.Label(c,text="ไฟล์ที่นำเข้าได้: .json (name, theme, logo_text, hostname...)\nหลังสลับ: ติดตั้ง(ครั้งแรก) → โลโก้โหลด → ล็อกอินรหัสผ่าน",
                 bg=T["window_bg"],fg=T["text_dim"],font=("Segoe UI",8),justify=tk.LEFT).pack(anchor="w",padx=14,pady=4)

    def _switch_reboot(self, prof: dict):
        self._pending_os = prof
        _set_active_os_id(prof.get("id","vmax-os"))
        if self._clock_job:
            try: self.root.after_cancel(self._clock_job)
            except Exception: pass
        for w in list(self.open_windows):
            try: w.frame.destroy()
            except Exception: pass
        self.open_windows.clear()
        for a in ("taskbar","desktop","start_menu","notif_panel"):
            w=getattr(self,a,None)
            if w:
                try: w.destroy()
                except Exception: pass
                setattr(self,a,None)
        self.start_menu_open=self.notif_open=False
        self.root.configure(bg="#000")
        self.root.after(200, self._os_switch_flow)

    def _os_switch_flow(self):
        prof = getattr(self, "_pending_os", None) or _list_os_profiles().get(_get_active_os_id()) or _default_os_profile()
        self._apply_os_theme()
        if not prof.get("installed"):
            self._os_install_source(prof)
        else:
            self._os_logo_boot(prof)

    def _os_install_wizard(self, prof: dict):
        self._cs(); self.stage=SF(self.root, prof.get("theme",{}).get("accent") or T["setup_bg"])
        self._os_inst = {"prof": prof, "step": 0, "username": prof.get("username") or "User",
                         "password": "", "hostname": prof.get("hostname") or "PC"}
        self._os_inst_render()

    def _os_inst_render(self):
        for w in self.stage.winfo_children(): w.destroy()
        prof=self._os_inst["prof"]; step=self._os_inst["step"]
        accent=prof.get("theme",{}).get("accent") or "#0078d4"
        left=tk.Frame(self.stage,bg="#111",width=240); left.pack(side=tk.LEFT,fill=tk.Y); left.pack_propagate(False)
        tk.Label(left,text=prof.get("logo_text") or prof.get("name"),bg="#111",fg="#fff",font=("Segoe UI",16,"bold")).pack(anchor="w",padx=20,pady=(36,4))
        tk.Label(left,text="Install",bg="#111",fg="#888",font=("Segoe UI",10)).pack(anchor="w",padx=20)
        for i,s in enumerate(["Welcome","Account","Installing","Done"]):
            tk.Label(left,text=f"{i+1}. {s}",bg="#111",fg="#fff" if i==step else "#666",
                     font=("Segoe UI",10,"bold" if i==step else "normal")).pack(anchor="w",padx=20,pady=4)
        right=tk.Frame(self.stage,bg="#f3f3f3"); right.pack(side=tk.LEFT,fill=tk.BOTH,expand=True)
        if step==0:
            tk.Label(right,text=f"ติดตั้ง {prof.get('name')}",bg="#f3f3f3",fg="#111",font=("Segoe UI",16,"bold")).pack(anchor="w",padx=36,pady=(40,8))
            tk.Label(right,text=f"เวอร์ชัน {prof.get('version')} · โดย {prof.get('author')}\n\nระบบจะตั้งค่าบัญชีผู้ใช้แล้วติดตั้งอิมเมจ",
                     bg="#f3f3f3",fg="#333",font=("Segoe UI",11),justify=tk.LEFT).pack(anchor="w",padx=36)
            def n(): self._os_inst["step"]=1; self._os_inst_render()
            tk.Button(right,text="ถัดไป →",bg=accent,fg="#fff",relief=tk.FLAT,padx=18,pady=8,command=n).pack(anchor="w",padx=36,pady=24)
        elif step==1:
            tk.Label(right,text="สร้างบัญชี",bg="#f3f3f3",fg="#111",font=("Segoe UI",16,"bold")).pack(anchor="w",padx=36,pady=(40,8))
            host=tk.StringVar(value=self._os_inst["hostname"])
            user=tk.StringVar(value=self._os_inst["username"])
            pwd=tk.StringVar()
            for lab,var in [("Computer name",host),("Username",user),("Password (optional)",pwd)]:
                tk.Label(right,text=lab,bg="#f3f3f3",fg="#555",font=("Segoe UI",9)).pack(anchor="w",padx=36,pady=(8,2))
                tk.Entry(right,textvariable=var,show=("•" if "Password" in lab else ""),font=("Segoe UI",12),width=26).pack(anchor="w",padx=36)
            def n():
                self._os_inst["hostname"]=(host.get().strip() or "PC")[:32]
                self._os_inst["username"]=(user.get().strip() or "User")[:24]
                self._os_inst["password"]=pwd.get()
                self._os_inst["step"]=2; self._os_inst_render(); self.root.after(120, self._os_inst_progress)
            tk.Button(right,text="ติดตั้ง →",bg=accent,fg="#fff",relief=tk.FLAT,padx=18,pady=8,command=n).pack(anchor="w",padx=36,pady=20)
        elif step==2:
            tk.Label(right,text=f"กำลังติดตั้ง {prof.get('name')}...",bg="#f3f3f3",fg="#111",font=("Segoe UI",14,"bold")).pack(anchor="w",padx=36,pady=(36,8))
            self._os_il=tk.Text(right,bg="#1a1a1a",fg="#33ff33",font=("Consolas",10),height=12,relief=tk.FLAT,state=tk.DISABLED)
            self._os_il.pack(fill=tk.BOTH,expand=True,padx=36,pady=6)
            self._os_ib=tk.Label(right,text="0%",bg="#f3f3f3",fg="#333"); self._os_ib.pack(anchor="w",padx=36)
        else:
            tk.Label(right,text="ติดตั้งเสร็จสิ้น",bg="#f3f3f3",fg="#111",font=("Segoe UI",16,"bold")).pack(anchor="w",padx=36,pady=(50,10))
            tk.Label(right,text=f"OS: {prof.get('name')}\nPC: {prof.get('hostname')}\nUser: {prof.get('username')}",
                     bg="#f3f3f3",fg="#333",font=("Segoe UI",11),justify=tk.LEFT).pack(anchor="w",padx=36)
            tk.Button(right,text="เริ่มใช้งาน",bg=accent,fg="#fff",font=("Segoe UI",12,"bold"),
                      relief=tk.FLAT,padx=22,pady=10,command=lambda: self._os_logo_boot(prof)).pack(anchor="w",padx=36,pady=28)

    def _os_inst_progress(self):
        prof=self._os_inst["prof"]
        tasks=[("Preparing disk...",10),("Copying system image...",30),("Writing boot config...",50),
               ("Creating user profile...",70),("Applying theme...",85),("Finalizing...",100)]
        def w(m):
            self._os_il.configure(state=tk.NORMAL); self._os_il.insert(tk.END,m+"\n"); self._os_il.configure(state=tk.DISABLED); self._os_il.see(tk.END)
        def run(i=0):
            if i>=len(tasks):
                prof["installed"]=True
                prof["hostname"]=self._os_inst["hostname"]
                prof["username"]=self._os_inst["username"]
                prof["password"]=self._os_inst["password"]
                prof["installed_at"]=datetime.now().isoformat(timespec="seconds")
                prof["boot_count"]=0
                _save_os_profile(prof)
                self.state["hostname"]=prof["hostname"]; self.state["username"]=prof["username"]
                self.state["password"]=prof["password"]; save_state(self.state)
                self.root.after(400, lambda: (self._os_inst.update(step=3), self._os_inst_render()))
                return
            m,p=tasks[i]; w(f"[{p:3d}%] {m}"); self._os_ib.configure(text=f"{p}%")
            self.root.after(280+i*40, lambda: run(i+1))
        w(f"Installing {prof.get('name')}...\n"); run()

    def _os_logo_boot(self, prof: dict):
        self._cs(); self.stage=SF(self.root,"#000")
        cv=tk.Canvas(self.stage,bg="#000",highlightthickness=0); cv.pack(fill=tk.BOTH,expand=True)
        accent=prof.get("theme",{}).get("accent") or "#0078d4"
        logo=prof.get("logo_text") or prof.get("name") or "OS"
        sub=prof.get("boot_subtitle") or "Loading..."
        def draw(p=0):
            cv.delete("all"); w,h=max(cv.winfo_width(),100),max(cv.winfo_height(),100)
            cv.create_text(w//2,h//2-40,text=logo,fill="#fff",font=("Segoe UI",36,"bold"))
            cv.create_text(w//2,h//2+4,text=prof.get("hostname",""),fill="#888",font=("Segoe UI",11))
            bw=240; x0,y0=w//2-bw//2,h//2+48
            cv.create_rectangle(x0,y0,x0+bw,y0+4,outline="#333",fill="#222")
            cv.create_rectangle(x0,y0,x0+int(bw*p/100),y0+4,outline="",fill=accent)
            cv.create_text(w//2,y0+28,text=sub,fill="#666",font=("Segoe UI",9))
        def tick(p=0):
            draw(p)
            if p>=100:
                prof["boot_count"]=int(prof.get("boot_count") or 0)+1
                _save_os_profile(prof)
                self.state["hostname"]=prof.get("hostname") or self.state.get("hostname")
                self.state["username"]=prof.get("username") or self.state.get("username")
                if prof.get("password") is not None:
                    self.state["password"]=prof.get("password")
                save_state(self.state)
                self.root.after(300, lambda: self._os_login(prof)); return
            self.root.after(40, lambda: tick(p+4))
        self.root.after(80, lambda: tick(0))

    def _os_login(self, prof: dict):
        self._cs()
        bot=prof.get("theme",{}).get("desktop_bot") or T["login_bg"]
        self.stage=SF(self.root, bot)
        bg=tk.Canvas(self.stage,highlightthickness=0,bg=bot); bg.pack(fill=tk.BOTH,expand=True)
        accent=prof.get("theme",{}).get("accent") or T["accent"]
        def paint(e=None):
            bg.delete("all"); w,h=bg.winfo_width(),bg.winfo_height()
            if w<10: return
            bg.create_rectangle(0,0,w,h,fill=bot,outline="")
            bg.create_text(w//2,h*0.2,text=datetime.now().strftime("%H:%M"),fill="#fff",font=("Segoe UI",52,"bold"))
            bg.create_text(w//2,h*0.2+46,text=prof.get("logo_text") or prof.get("name"),fill="#ccc",font=("Segoe UI",12))
        bg.bind("<Configure>",paint)
        card=tk.Frame(self.stage,bg="#2b2b2b",highlightbackground="#404040",highlightthickness=1)
        card.place(relx=0.5,rely=0.62,anchor="center",width=330,height=250)
        tk.Label(card,text="👤",bg="#2b2b2b",fg="#fff",font=("Segoe UI Emoji",34)).pack(pady=(14,2))
        tk.Label(card,text=prof.get("username") or "User",bg="#2b2b2b",fg="#fff",font=("Segoe UI",13,"bold")).pack()
        tk.Label(card,text=prof.get("hostname") or "",bg="#2b2b2b",fg="#999",font=("Segoe UI",9)).pack(pady=(0,6))
        pv=tk.StringVar(); need=bool(prof.get("password"))
        if need:
            tk.Entry(card,textvariable=pv,show="•",font=("Segoe UI",12),bg="#3c3c3c",fg="#fff",insertbackground="#fff",relief=tk.FLAT,width=20).pack(pady=5,ipady=3)
        else:
            tk.Label(card,text="No password — Sign in",bg="#2b2b2b",fg="#888",font=("Segoe UI",9)).pack(pady=5)
        err=tk.Label(card,text="",bg="#2b2b2b",fg=T["danger"],font=("Segoe UI",9)); err.pack()
        def go(e=None):
            if need and pv.get()!=prof.get("password",""):
                err.configure(text="รหัสผ่านไม่ถูกต้อง"); return
            try: self.root.unbind_all("<Return>")
            except Exception: pass
            self._apply_os_theme(); self._desktop()
        tk.Button(card,text="Sign in",bg=accent,fg="#fff",font=("Segoe UI",11),relief=tk.FLAT,padx=26,pady=5,command=go).pack(pady=8)
        if need: card.bind_all("<Return>", go)



