        tk.Label(c,text="ไฟล์ที่ล็อกอยู่",bg=T["window_bg"],fg=T["text_dim"],font=("Segoe UI",9)).pack(anchor="w",padx=14,pady=(8,2))
        lb=tk.Listbox(c,bg="#1a1a1a",fg=T["text"],font=("Consolas",9),relief=tk.FLAT,height=8); lb.pack(fill=tk.BOTH,expand=True,padx=14,pady=4)
        def refresh():
            lb.delete(0,tk.END)
