        tk.Button(row,text="Browse",bg=T["accent"],fg="#fff",relief=tk.FLAT,command=lambda: path_var.set(filedialog.askopenfilename(initialdir=str(_FS)) or path_var.get())).pack(side=tk.LEFT)
        row2=tk.Frame(c,bg=T["window_bg"]); row2.pack(fill=tk.X,padx=14,pady=4)
