# =============================================================================
# VMAX LIVE VIEWER CLIP POPUP  v1.0
# ----------------------------------------------------------------------------
# ฟีเจอร์: ตอนกำลังดูไลฟ์สดของคนอื่น → มีปุ่มป๊อปอัปโผล่ขึ้นมา
# ให้สำรวจคลิปของคนดูคนอื่น (ที่เข้ามาดูไลฟ์ด้วยกัน หรือคนที่กำลังคอมเมนต์อยู่)
#
# ออกแบบตามแนวคิดจากบทสนทนา:
#   - เน้น Community / ร่วมห้องไลฟ์ ไม่แย่งโฟกัสจากเจ้าของไลฟ์
#   - จำกัดเฉพาะโปรไฟล์ที่เปิดสาธารณะ (open profile) กันสแปม
#   - ไม่มีบนแพลตฟอร์มหลัก ๆ ตอนนี้ (TikTok/YouTube/Facebook)
#     เพราะระบบโฟกัสเจ้าของไลฟ์ + กันสแปม
#
# CLI:  python this.py --live-viewer-clip-demo
# =============================================================================

import json as _lvc_json
import os as _lvc_os
import threading as _lvc_thr
import time as _lvc_time
import uuid as _lvc_uuid
from pathlib import Path as _LvcPath
from collections import defaultdict as _lvc_dd
from typing import Optional as _LvcOpt, List as _LvcList, Dict as _LvcDict

try:
    _LVC_DATA = _LvcPath(globals().get("_DATA", _LvcPath.home() / ".vmax_os_data")) / "live_viewer_clips"
except Exception:
    _LVC_DATA = _LvcPath.home() / ".vmax_os_data" / "live_viewer_clips"
_LVC_DATA.mkdir(parents=True, exist_ok=True)
_LVC_LOCK = _lvc_thr.Lock()

# ---------------------------------------------------------------------------
# Config
# ---------------------------------------------------------------------------
LVC_ENABLED_DEFAULT = _lvc_os.environ.get("VMAX_LIVE_VIEWER_CLIP", "1").strip().lower() in (
    "1", "true", "yes", "on",
)
# จำนวนคลิปสูงสุดที่แสดงในป๊อปอัปต่อครั้ง
LVC_MAX_CLIPS_PER_POPUP = int(_lvc_os.environ.get("VMAX_LVC_MAX_CLIPS", "12"))
# คลิปเก่ากว่ากี่วินาทีจะไม่โชว์ในป๊อปอัป (กันคลิปค้าง)
LVC_CLIP_MAX_AGE_SEC = float(_lvc_os.environ.get("VMAX_LVC_CLIP_AGE", "3600"))  # 1 ชม.
# ต้องเปิดโปรไฟล์สาธารณะถึงจะถูกแสดงคลิป
LVC_REQUIRE_OPEN_PROFILE = True

# live_id -> set of viewer uids ที่กำลังอยู่ในห้อง
LVC_LIVE_VIEWERS: Dict[str, set] = _lvc_dd(set)
# uid -> profile settings (open_profile, display_name, avatar_url ...)
LVC_PROFILES: Dict[str, dict] = {}
# clip_id -> clip record
LVC_CLIPS: Dict[str, dict] = {}
# live_id -> list of recent clip_ids (ordered newest first)
LVC_LIVE_CLIP_INDEX: Dict[str, list] = _lvc_dd(list)
# uid_viewer -> last popup state (เพื่อไม่ให้ปุ่มเด้งซ้ำถี่เกิน)
LVC_POPUP_COOLDOWN: Dict[str, float] = {}
LVC_POPUP_COOLDOWN_SEC = 8.0


def _lvc_profile(uid: str) -> dict:
    uid = str(uid or "anon")
    return LVC_PROFILES.setdefault(uid, {
        "uid": uid,
        "display_name": uid,
        "avatar_url": "",
        "open_profile": True,          # ค่าเริ่มต้นเปิดสาธารณะ (เกมภายใน)
        "allow_clip_share_in_live": True,
        "bio": "",
        "updated_at": _lvc_time.time(),
    })


def live_viewer_set_profile(uid: str, **kwargs) -> dict:
    """ตั้งค่าโปรไฟล์ผู้ดู — open_profile / allow_clip_share_in_live"""
    p = _lvc_profile(uid)
    if "display_name" in kwargs and kwargs["display_name"]:
        p["display_name"] = str(kwargs["display_name"])[:64]
    if "avatar_url" in kwargs:
        p["avatar_url"] = str(kwargs["avatar_url"] or "")[:512]
    if "open_profile" in kwargs and kwargs["open_profile"] is not None:
        p["open_profile"] = bool(kwargs["open_profile"])
    if "allow_clip_share_in_live" in kwargs and kwargs["allow_clip_share_in_live"] is not None:
        p["allow_clip_share_in_live"] = bool(kwargs["allow_clip_share_in_live"])
    if "bio" in kwargs:
        p["bio"] = str(kwargs["bio"] or "")[:200]
    p["updated_at"] = _lvc_time.time()
    return {"ok": True, "profile": dict(p)}


def live_viewer_get_profile(uid: str) -> dict:
    return {"ok": True, "profile": dict(_lvc_profile(uid))}


def live_viewer_join(live_id: str, uid: str) -> dict:
    """เข้าห้องไลฟ์ → ถูกนับเป็นคนดูในห้อง"""
    live_id, uid = str(live_id), str(uid)
    with _LVC_LOCK:
        LVC_LIVE_VIEWERS[live_id].add(uid)
        count = len(LVC_LIVE_VIEWERS[live_id])
    return {
        "ok": True,
        "live_id": live_id,
        "uid": uid,
        "viewer_count": count,
        "msg": f"เข้าห้องไลฟ์แล้ว (คนดูปัจจุบัน {count})",
    }


def live_viewer_leave(live_id: str, uid: str) -> dict:
    live_id, uid = str(live_id), str(uid)
    with _LVC_LOCK:
        s = LVC_LIVE_VIEWERS.get(live_id)
        if s and uid in s:
            s.discard(uid)
        count = len(LVC_LIVE_VIEWERS.get(live_id) or set())
    return {"ok": True, "live_id": live_id, "viewer_count": count}


def live_viewer_list(live_id: str, only_open: bool = True) -> dict:
    """รายชื่อคนดูในห้อง (กรองเฉพาะโปรไฟล์เปิดสาธารณะถ้า only_open=True)"""
    live_id = str(live_id)
    with _LVC_LOCK:
        uids = list(LVC_LIVE_VIEWERS.get(live_id) or set())
    out = []
    for uid in uids:
        p = _lvc_profile(uid)
        if only_open and LVC_REQUIRE_OPEN_PROFILE and not p.get("open_profile"):
            continue
        out.append({
            "uid": uid,
            "display_name": p.get("display_name") or uid,
            "avatar_url": p.get("avatar_url") or "",
            "open_profile": bool(p.get("open_profile")),
            "allow_clip_share": bool(p.get("allow_clip_share_in_live")),
        })
    return {
        "ok": True,
        "live_id": live_id,
        "viewers": out,
        "count": len(out),
        "total_in_room": len(uids),
    }


def _lvc_new_clip_id() -> str:
    return "lvc_" + _lvc_uuid.uuid4().hex[:12]


def live_viewer_publish_clip(
    owner_uid: str,
    live_id: str,
    title: str = "",
    media_url: str = "",
    thumb_url: str = "",
    duration_sec: float = 0,
    tags: _LvcList | None = None,
    source: str = "manual",  # manual | highlight | comment_clip
) -> dict:
    """
    เผยแพร่คลิปของตัวเองเข้าห้องไลฟ์ (จะโผล่ในป๊อปอัปของคนอื่น
    เฉพาะเมื่อโปรไฟล์เปิดสาธารณะ + อนุญาตแชร์คลิป)
    """
    owner_uid, live_id = str(owner_uid), str(live_id)
    p = _lvc_profile(owner_uid)
    if LVC_REQUIRE_OPEN_PROFILE and not p.get("open_profile"):
        return {"ok": False, "msg": "โปรไฟล์ปิดอยู่ — เปิด open_profile ก่อนถึงจะแชร์คลิปในห้องไลฟ์ได้"}
    if not p.get("allow_clip_share_in_live", True):
        return {"ok": False, "msg": "ปิดการแชร์คลิปในไลฟ์ไว้"}

    cid = _lvc_new_clip_id()
    now = _lvc_time.time()
    rec = {
        "id": cid,
        "owner_uid": owner_uid,
        "owner_name": p.get("display_name") or owner_uid,
        "owner_avatar": p.get("avatar_url") or "",
        "live_id": live_id,
        "title": str(title or "")[:120] or f"คลิปของ {p.get('display_name') or owner_uid}",
        "media_url": str(media_url or "")[:1024],
        "thumb_url": str(thumb_url or "")[:1024],
        "duration_sec": max(0.0, float(duration_sec or 0)),
        "tags": list(tags or [])[:8],
        "source": str(source or "manual")[:32],
        "created_at": now,
        "views": 0,
        "likes": 0,
    }
    with _LVC_LOCK:
        LVC_CLIPS[cid] = rec
        idx = LVC_LIVE_CLIP_INDEX[live_id]
        idx.insert(0, cid)
        # เก็บไม่เกิน 200 คลิปต่อห้อง
        del idx[200:]
    return {
        "ok": True,
        "clip_id": cid,
        "msg": "เผยแพร่คลิปเข้าห้องไลฟ์แล้ว — คนดูคนอื่นจะเห็นในป๊อปอัป",
        "clip": _lvc_public_clip(rec),
    }


def _lvc_public_clip(rec: dict) -> dict:
    return {
        "id": rec["id"],
        "owner_uid": rec["owner_uid"],
        "owner_name": rec["owner_name"],
        "owner_avatar": rec.get("owner_avatar") or "",
        "live_id": rec["live_id"],
        "title": rec["title"],
        "media_url": rec.get("media_url") or "",
        "thumb_url": rec.get("thumb_url") or "",
        "duration_sec": rec.get("duration_sec") or 0,
        "tags": rec.get("tags") or [],
        "source": rec.get("source") or "manual",
        "created_at": rec["created_at"],
        "age_sec": round(_lvc_time.time() - float(rec["created_at"]), 1),
        "views": int(rec.get("views") or 0),
        "likes": int(rec.get("likes") or 0),
    }


def live_viewer_popup_clips(
    viewer_uid: str,
    live_id: str,
    limit: int | None = None,
    exclude_self: bool = True,
) -> dict:
    """
    ดึงรายการคลิปสำหรับป๊อปอัปตอนกำลังดูไลฟ์
    - เฉพาะคนที่อยู่ในห้องเดียวกัน
    - เฉพาะโปรไฟล์เปิดสาธารณะ
    - คลิปไม่เก่าเกิน LVC_CLIP_MAX_AGE_SEC
    - มี cooldown กันปุ่มเด้งถี่เกิน
    """
    viewer_uid, live_id = str(viewer_uid), str(live_id)
    limit = max(1, min(50, int(limit or LVC_MAX_CLIPS_PER_POPUP)))
    now = _lvc_time.time()

    # cooldown
    last = LVC_POPUP_COOLDOWN.get(viewer_uid) or 0
    if now - last < LVC_POPUP_COOLDOWN_SEC:
        remain = round(LVC_POPUP_COOLDOWN_SEC - (now - last), 1)
        return {
            "ok": True,
            "popup": False,
            "cooldown_remain_sec": remain,
            "clips": [],
            "msg": f"ปุ่มป๊อปอัปยังคูลดาวน์อีก {remain} วิ",
        }

    with _LVC_LOCK:
        room_uids = set(LVC_LIVE_VIEWERS.get(live_id) or set())
        clip_ids = list(LVC_LIVE_CLIP_INDEX.get(live_id) or [])

    clips = []
    for cid in clip_ids:
        rec = LVC_CLIPS.get(cid)
        if not rec:
            continue
        age = now - float(rec.get("created_at") or 0)
        if age > LVC_CLIP_MAX_AGE_SEC:
            continue
        owner = rec.get("owner_uid")
        if exclude_self and owner == viewer_uid:
            continue
        # เจ้าของต้องยังอยู่ในห้อง (หรือเพิ่งออกไปไม่นานก็ยังโชว์ได้ — เลือกเข้ม: ต้องอยู่ในห้อง)
        if owner not in room_uids:
            continue
        p = _lvc_profile(owner)
        if LVC_REQUIRE_OPEN_PROFILE and not p.get("open_profile"):
            continue
        if not p.get("allow_clip_share_in_live", True):
            continue
        clips.append(_lvc_public_clip(rec))
        if len(clips) >= limit:
            break

    LVC_POPUP_COOLDOWN[viewer_uid] = now

    return {
        "ok": True,
        "popup": True,
        "live_id": live_id,
        "viewer_uid": viewer_uid,
        "clips": clips,
        "count": len(clips),
        "viewer_count_in_room": len(room_uids),
        "hint_th": (
            "ป๊อปอัปคลิปคนดูในห้องไลฟ์เดียวกัน — "
            "เฉพาะโปรไฟล์เปิดสาธารณะ และอนุญาตแชร์คลิป "
            "ไม่แย่งโฟกัสจากเจ้าของไลฟ์"
        ),
        "msg": f"พบ {len(clips)} คลิปจากคนดูในห้อง" if clips else "ยังไม่มีคลิปจากคนดูคนอื่นในห้องนี้",
    }


def live_viewer_view_clip(clip_id: str, viewer_uid: str = "") -> dict:
    """กดดูคลิป → นับวิว"""
    clip_id = str(clip_id)
    with _LVC_LOCK:
        rec = LVC_CLIPS.get(clip_id)
        if not rec:
            return {"ok": False, "msg": "ไม่พบคลิป"}
        rec["views"] = int(rec.get("views") or 0) + 1
        public = _lvc_public_clip(rec)
    return {"ok": True, "clip": public, "msg": "เปิดดูคลิปแล้ว"}


def live_viewer_like_clip(clip_id: str, uid: str = "") -> dict:
    clip_id = str(clip_id)
    with _LVC_LOCK:
        rec = LVC_CLIPS.get(clip_id)
        if not rec:
            return {"ok": False, "msg": "ไม่พบคลิป"}
        rec["likes"] = int(rec.get("likes") or 0) + 1
        public = _lvc_public_clip(rec)
    return {"ok": True, "clip": public}


def live_viewer_delete_clip(clip_id: str, owner_uid: str) -> dict:
    clip_id, owner_uid = str(clip_id), str(owner_uid)
    with _LVC_LOCK:
        rec = LVC_CLIPS.get(clip_id)
        if not rec:
            return {"ok": False, "msg": "ไม่พบคลิป"}
        if rec.get("owner_uid") != owner_uid:
            return {"ok": False, "msg": "ลบได้เฉพาะเจ้าของคลิป"}
        live_id = rec.get("live_id")
        LVC_CLIPS.pop(clip_id, None)
        if live_id and clip_id in LVC_LIVE_CLIP_INDEX.get(live_id, []):
            LVC_LIVE_CLIP_INDEX[live_id] = [c for c in LVC_LIVE_CLIP_INDEX[live_id] if c != clip_id]
    return {"ok": True, "msg": "ลบคลิปแล้ว"}


def live_viewer_state(live_id: str) -> dict:
    """สรุปสถานะห้องไลฟ์ + จำนวนคลิปที่พร้อมโชว์"""
    live_id = str(live_id)
    with _LVC_LOCK:
        viewers = list(LVC_LIVE_VIEWERS.get(live_id) or set())
        clip_ids = list(LVC_LIVE_CLIP_INDEX.get(live_id) or [])
    now = _lvc_time.time()
    active_clips = 0
    for cid in clip_ids:
        rec = LVC_CLIPS.get(cid)
        if rec and (now - float(rec.get("created_at") or 0)) <= LVC_CLIP_MAX_AGE_SEC:
            active_clips += 1
    return {
        "ok": True,
        "live_id": live_id,
        "viewer_count": len(viewers),
        "active_clips": active_clips,
        "feature_enabled": LVC_ENABLED_DEFAULT,
        "require_open_profile": LVC_REQUIRE_OPEN_PROFILE,
        "max_clips_per_popup": LVC_MAX_CLIPS_PER_POPUP,
        "clip_max_age_sec": LVC_CLIP_MAX_AGE_SEC,
        "msg_th": (
            "ฟีเจอร์ปุ่มป๊อปอัปดูคลิปคนดูคนอื่นในห้องไลฟ์ — "
            "จำกัดเฉพาะโปรไฟล์เปิดสาธารณะ กันสแปมและไม่แย่งโฟกัสเจ้าของไลฟ์"
        ),
    }


def live_viewer_clip_demo():
    print("=== Live Viewer Clip Popup demo ===")
    live = "live_demo_001"
    # โปรไฟล์
    print(live_viewer_set_profile("alice", display_name="Alice", open_profile=True))
    print(live_viewer_set_profile("bob", display_name="Bob", open_profile=True))
    print(live_viewer_set_profile("carol", display_name="Carol", open_profile=False))  # ปิดโปรไฟล์
    # เข้าห้อง
    print(live_viewer_join(live, "alice"))
    print(live_viewer_join(live, "bob"))
    print(live_viewer_join(live, "carol"))
    print(live_viewer_list(live))
    # เผยแพร่คลิป
    print(live_viewer_publish_clip("alice", live, title="ไฮไลท์ยิงหัว", media_url="https://example.com/a.mp4", duration_sec=12))
    print(live_viewer_publish_clip("bob", live, title="คลิปตลกในไลฟ์", media_url="https://example.com/b.mp4", duration_sec=8))
    print(live_viewer_publish_clip("carol", live, title="คลิปปิดโปรไฟล์", media_url="https://example.com/c.mp4"))  # ควร fail
    # ป๊อปอัปจากมุมมองคนดู
    print("popup for alice:", live_viewer_popup_clips("alice", live))
    print("popup for bob:", live_viewer_popup_clips("bob", live))
    print("state:", live_viewer_state(live))
    print("=== done ===")


# ---------------------------------------------------------------------------
# Flask routes + module registry
# ---------------------------------------------------------------------------

def _lvc_register_routes():
    app = globals().get("app")
    if app is None:
        return
    require = globals().get("require_auth_toggleable")
    if require is None:
        def require(f):
            return f

    @app.route("/api/live_viewer/profile", methods=["GET", "POST"])
    def api_lvc_profile():
        from flask import request, jsonify
        if request.method == "GET":
            uid = request.args.get("uid") or "player"
            return jsonify(live_viewer_get_profile(uid))
        b = request.json or {}
        uid = b.get("uid") or "player"
        return jsonify(live_viewer_set_profile(uid, **{k: b.get(k) for k in (
            "display_name", "avatar_url", "open_profile", "allow_clip_share_in_live", "bio",
        )}))

    @app.route("/api/live_viewer/join", methods=["POST"])
    @require
    def api_lvc_join():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(live_viewer_join(b.get("live_id") or "default", b.get("uid") or "player"))

    @app.route("/api/live_viewer/leave", methods=["POST"])
    @require
    def api_lvc_leave():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(live_viewer_leave(b.get("live_id") or "default", b.get("uid") or "player"))

    @app.route("/api/live_viewer/list")
    def api_lvc_list():
        from flask import request, jsonify
        live_id = request.args.get("live_id") or "default"
        only_open = request.args.get("only_open", "1") not in ("0", "false", "no")
        return jsonify(live_viewer_list(live_id, only_open=only_open))

    @app.route("/api/live_viewer/publish", methods=["POST"])
    @require
    def api_lvc_publish():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(live_viewer_publish_clip(
            b.get("uid") or b.get("owner_uid") or "player",
            b.get("live_id") or "default",
            title=b.get("title") or "",
            media_url=b.get("media_url") or "",
            thumb_url=b.get("thumb_url") or "",
            duration_sec=float(b.get("duration_sec") or 0),
            tags=b.get("tags"),
            source=b.get("source") or "manual",
        ))

    @app.route("/api/live_viewer/popup")
    def api_lvc_popup():
        from flask import request, jsonify
        return jsonify(live_viewer_popup_clips(
            request.args.get("uid") or "player",
            request.args.get("live_id") or "default",
            limit=int(request.args.get("limit") or LVC_MAX_CLIPS_PER_POPUP),
            exclude_self=request.args.get("exclude_self", "1") not in ("0", "false"),
        ))

    @app.route("/api/live_viewer/view", methods=["POST"])
    def api_lvc_view():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(live_viewer_view_clip(b.get("clip_id") or "", b.get("uid") or ""))

    @app.route("/api/live_viewer/like", methods=["POST"])
    def api_lvc_like():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(live_viewer_like_clip(b.get("clip_id") or "", b.get("uid") or ""))

    @app.route("/api/live_viewer/delete", methods=["POST"])
    @require
    def api_lvc_delete():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(live_viewer_delete_clip(b.get("clip_id") or "", b.get("uid") or "player"))

    @app.route("/api/live_viewer/state")
    def api_lvc_state():
        from flask import request, jsonify
        return jsonify(live_viewer_state(request.args.get("live_id") or "default"))


try:
    _lvc_register_routes()
except Exception:
    pass

