# persistent cash ข้ามแมตช์ (uid -> cash)
WD_BANK: Dict[str, int] = {}
# match state
WD_MATCHES: Dict[str, dict] = {}
# uid -> current match_id
WD_PLAYER_MATCH: Dict[str, str] = {}


def _wd_uid() -> str:
    return "wd_" + _wd_uuid.uuid4().hex[:10]


def _wd_bank_get(uid: str) -> int:
    uid = str(uid)
    if uid not in WD_BANK:
        WD_BANK[uid] = WD_START_CASH
    return int(WD_BANK[uid])


def _wd_bank_set(uid: str, amount: int) -> int:
    uid = str(uid)
    WD_BANK[uid] = max(0, int(amount))
    return WD_BANK[uid]


def wardogs_bank(uid: str) -> dict:
    return {"ok": True, "uid": str(uid), "cash": _wd_bank_get(uid), "start_cash": WD_START_CASH}


def wardogs_catalog() -> dict:
    return {"ok": True, "catalog": WD_LOADOUT_CATALOG, "teams": list(WD_TEAMS),
            "score_to_win": WD_SCORE_TO_WIN, "max_players": WD_MAX_PLAYERS}


def _wd_empty_match(match_id: str | None = None) -> dict:
    mid = match_id or ("match_" + _wd_uuid.uuid4().hex[:8])
    return {
        "id": mid,
        "status": "lobby",          # lobby | live | ended
        "created_at": _wd_time.time(),
        "started_at": None,
        "ended_at": None,
        "winner_team": None,
        "scores": {t: 0 for t in WD_TEAMS},
        "players": {},              # uid -> player state
        "team_counts": {t: 0 for t in WD_TEAMS},
        "control_zone": {
            "name": "Control Zone",
            "size_km": WD_MAP_SIZE_KM,
            "held_by": None,        # ทีมที่มีคนมากสุดในโซนตอนนี้
            "occupants": {t: 0 for t in WD_TEAMS},
            "last_tick_at": None,
        },
        "structures": {             # สิ่งปลูกสร้างที่ทำลายได้
            "radio_tower": {"hp": 500, "hp_max": 500, "destroyed": False},
            "supply_depot": {"hp": 800, "hp_max": 800, "destroyed": False},
            "watchtower_a": {"hp": 300, "hp_max": 300, "destroyed": False},
            "watchtower_b": {"hp": 300, "hp_max": 300, "destroyed": False},
        },
        "kill_feed": [],
        "max_players": WD_MAX_PLAYERS,
    }


def _wd_player_state(uid: str, team: str) -> dict:
    cash = _wd_bank_get(uid)
    return {
        "uid": uid,
        "team": team,
        "alive": True,
        "hp": 100,
        "hp_max": 100,
        "cash_on_hand": cash,
        "loadout": {
            "primary": "pistol",
            "secondary": "pistol",
            "gear": [],
            "vehicle": "none",
        },
        "kills": 0,
        "deaths": 0,
        "in_zone": False,
        "x": _wd_rand.uniform(-1000, 1000),
        "y": _wd_rand.uniform(-1000, 1000),
        "joined_at": _wd_time.time(),
    }


def wardogs_create_match() -> dict:
    with _WD_LOCK:
        m = _wd_empty_match()
        WD_MATCHES[m["id"]] = m
    return {"ok": True, "match_id": m["id"], "status": "lobby", "msg": "สร้างแมตช์ lobby แล้ว — ให้ผู้เล่น join"}


def wardogs_join(match_id: str, uid: str, preferred_team: str | None = None) -> dict:
    match_id, uid = str(match_id), str(uid)
    with _WD_LOCK:
        m = WD_MATCHES.get(match_id)
        if not m:
            return {"ok": False, "msg": "ไม่พบแมตช์"}
        if m["status"] == "ended":
            return {"ok": False, "msg": "แมตช์จบแล้ว"}
        if uid in m["players"]:
            return {"ok": True, "msg": "อยู่ในแมตช์แล้ว", "player": m["players"][uid], "match_id": match_id}
        if len(m["players"]) >= m["max_players"]:
            return {"ok": False, "msg": f"เต็มแล้ว ({m['max_players']} คน)"}

        # จัดทีมสมดุล
        counts = m["team_counts"]
        if preferred_team in WD_TEAMS and counts[preferred_team] <= min(counts.values()) + 1:
            team = preferred_team
        else:
            team = min(WD_TEAMS, key=lambda t: counts[t])

        pl = _wd_player_state(uid, team)
        m["players"][uid] = pl
        m["team_counts"][team] = m["team_counts"].get(team, 0) + 1
        WD_PLAYER_MATCH[uid] = match_id

    return {
        "ok": True,
        "match_id": match_id,
        "team": team,
        "player": pl,
        "team_counts": dict(m["team_counts"]),
        "msg": f"เข้าทีม {team} แล้ว (เงินติดตัว ${pl['cash_on_hand']:,})",
    }


def wardogs_leave(match_id: str, uid: str) -> dict:
    match_id, uid = str(match_id), str(uid)
    with _WD_LOCK:
        m = WD_MATCHES.get(match_id)
        if not m or uid not in m["players"]:
            return {"ok": False, "msg": "ไม่ได้อยู่ในแมตช์"}
        pl = m["players"].pop(uid)
        team = pl.get("team")
        if team in m["team_counts"]:
            m["team_counts"][team] = max(0, m["team_counts"][team] - 1)
        WD_PLAYER_MATCH.pop(uid, None)
        # บันทึกเงินกลับธนาคาร
        _wd_bank_set(uid, pl.get("cash_on_hand", _wd_bank_get(uid)))
    return {"ok": True, "msg": "ออกจากแมตช์แล้ว เงินถูกบันทึก"}


def wardogs_buy_loadout(match_id: str, uid: str, category: str, item_id: str) -> dict:
    """ซื้ออาวุธ/เกียร์/ยาน ด้วยเงินติดตัวในแมตช์"""
    match_id, uid = str(match_id), str(uid)
    category = str(category or "").lower()
    item_id = str(item_id or "").lower()
    catalog = WD_LOADOUT_CATALOG.get(category)
    if not catalog or item_id not in catalog:
        return {"ok": False, "msg": f"ไม่มี {category}/{item_id} ในแคตตาล็อก"}

    item = catalog[item_id]
    price = int(item.get("price") or 0)

    with _WD_LOCK:
        m = WD_MATCHES.get(match_id)
        if not m or uid not in m["players"]:
            return {"ok": False, "msg": "ไม่ได้อยู่ในแมตช์"}
        pl = m["players"][uid]
        if not pl.get("alive"):
            return {"ok": False, "msg": "ตายอยู่ ซื้อตอนรอเกิดไม่ได้ (จำลอง: ต้องมีชีวิต)"}
        cash = int(pl.get("cash_on_hand") or 0)
        if cash < price:
            return {"ok": False, "msg": f"เงินไม่พอ (มี ${cash:,} ต้องการ ${price:,})"}

        pl["cash_on_hand"] = cash - price
        lo = pl["loadout"]
        if category == "weapons":
            slot = item.get("slot") or "primary"
            lo[slot] = item_id
        elif category == "gear":
            if item_id not in lo["gear"]:
                lo["gear"].append(item_id)
            # เกราะเพิ่มเลือดสูงสุด
            if "hp_bonus" in item:
                pl["hp_max"] = 100 + int(item["hp_bonus"])
                pl["hp"] = min(pl["hp"], pl["hp_max"])
        elif category == "vehicles":
            lo["vehicle"] = item_id

    return {
        "ok": True,
        "bought": item_id,
        "category": category,
        "price": price,
        "cash_left": pl["cash_on_hand"],
        "loadout": pl["loadout"],
        "msg": f"ซื้อ {item.get('name')} แล้ว เหลือ ${pl['cash_on_hand']:,}",
    }


def wardogs_start(match_id: str) -> dict:
    with _WD_LOCK:
        m = WD_MATCHES.get(match_id)
        if not m:
            return {"ok": False, "msg": "ไม่พบแมตช์"}
        if m["status"] != "lobby":
            return {"ok": False, "msg": f"สถานะปัจจุบัน: {m['status']}"}
        if len(m["players"]) < 2:
            return {"ok": False, "msg": "ต้องมีอย่างน้อย 2 คน"}
        m["status"] = "live"
        m["started_at"] = _wd_time.time()
        m["control_zone"]["last_tick_at"] = m["started_at"]
    return {"ok": True, "msg": "แมตช์เริ่มแล้ว — ชิง Control Zone!", "match_id": match_id}


def wardogs_set_in_zone(match_id: str, uid: str, in_zone: bool = True) -> dict:
    """ผู้เล่นเข้า/ออก Control Zone (client รายงานตำแหน่ง)"""
    match_id, uid = str(match_id), str(uid)
    with _WD_LOCK:
        m = WD_MATCHES.get(match_id)
        if not m or uid not in m["players"]:
            return {"ok": False, "msg": "ไม่ได้อยู่ในแมตช์"}
        if m["status"] != "live":
            return {"ok": False, "msg": "แมตช์ยังไม่ live"}
        pl = m["players"][uid]
        if not pl.get("alive"):
            return {"ok": False, "msg": "ตายอยู่"}
        pl["in_zone"] = bool(in_zone)
    return {"ok": True, "in_zone": bool(in_zone)}


def _wd_recount_zone(m: dict) -> None:
    occ = {t: 0 for t in WD_TEAMS}
    for pl in m["players"].values():
        if pl.get("alive") and pl.get("in_zone"):
            t = pl.get("team")
            if t in occ:
                occ[t] += 1
    m["control_zone"]["occupants"] = occ
    # ทีมที่มีคนมากสุด (เสมอ = ไม่มีคนถือ)
    mx = max(occ.values()) if occ else 0
    if mx <= 0:
        m["control_zone"]["held_by"] = None
    else:
        leaders = [t for t, c in occ.items() if c == mx]
        m["control_zone"]["held_by"] = leaders[0] if len(leaders) == 1 else None


def wardogs_zone_tick(match_id: str) -> dict:
    """เรียกเป็นระยะ (หรือ auto) — ทีมที่ถือโซนได้คะแนน"""
    match_id = str(match_id)
    with _WD_LOCK:
        m = WD_MATCHES.get(match_id)
        if not m:
            return {"ok": False, "msg": "ไม่พบแมตช์"}
        if m["status"] != "live":
            return {"ok": False, "msg": "แมตช์ไม่ได้อยู่ในสถานะ live"}

        now = _wd_time.time()
        last = m["control_zone"].get("last_tick_at") or now
        if now - last < WD_ZONE_TICK_SEC * 0.5:
            return {"ok": True, "skipped": True, "msg": "ยังไม่ถึงรอบ tick"}

        _wd_recount_zone(m)
        held = m["control_zone"].get("held_by")
        gained = 0
        if held:
            m["scores"][held] = int(m["scores"].get(held) or 0) + WD_POINTS_PER_TICK
            gained = WD_POINTS_PER_TICK

        m["control_zone"]["last_tick_at"] = now

        # เช็คชนะ
        winner = None
        for t, sc in m["scores"].items():
            if sc >= WD_SCORE_TO_WIN:
                winner = t
                break
        if winner:
            m["status"] = "ended"
            m["ended_at"] = now
            m["winner_team"] = winner
            # บันทึกเงินทุกคนกลับธนาคาร
            for uid, pl in m["players"].items():
                _wd_bank_set(uid, pl.get("cash_on_hand", _wd_bank_get(uid)))

    return {
        "ok": True,
        "held_by": held,
        "gained": gained,
        "scores": dict(m["scores"]),
        "occupants": dict(m["control_zone"]["occupants"]),
        "status": m["status"],
        "winner_team": m.get("winner_team"),
        "msg": (
            f"ทีม {winner} ชนะ! คะแนนถึง {WD_SCORE_TO_WIN}" if winner
            else (f"ทีม {held} ได้ +{gained} (ถือโซน)" if held else "ยังไม่มีทีมถือโซน")
        ),
    }


def wardogs_damage_structure(match_id: str, structure_id: str, damage: float, uid: str = "") -> dict:
    match_id, structure_id = str(match_id), str(structure_id)
    with _WD_LOCK:
        m = WD_MATCHES.get(match_id)
        if not m:
            return {"ok": False, "msg": "ไม่พบแมตช์"}
        st = m["structures"].get(structure_id)
        if not st:
            return {"ok": False, "msg": f"ไม่มีสิ่งปลูกสร้าง {structure_id}"}
        if st.get("destroyed"):
            return {"ok": True, "already_destroyed": True, "msg": "ถูกทำลายไปแล้ว"}
        st["hp"] = max(0.0, float(st["hp"]) - float(damage))
        if st["hp"] <= 0:
            st["destroyed"] = True
            st["hp"] = 0
            return {
                "ok": True,
                "destroyed": True,
                "structure": structure_id,
                "msg": f"ทำลาย {structure_id} สำเร็จ!",
                "structures": {k: dict(v) for k, v in m["structures"].items()},
            }
    return {
        "ok": True,
        "destroyed": False,
        "structure": structure_id,
        "hp_left": round(st["hp"], 1),
        "msg": f"{structure_id} เหลือ HP {st['hp']:.0f}",
    }


def wardogs_kill(match_id: str, killer_uid: str, victim_uid: str) -> dict:
    """จำลองการฆ่า — เพิ่ม kill/death + เงินรางวัลเล็กน้อย"""
    match_id = str(match_id)
    with _WD_LOCK:
        m = WD_MATCHES.get(match_id)
        if not m or m["status"] != "live":
            return {"ok": False, "msg": "แมตช์ไม่ live"}
        killer = m["players"].get(killer_uid)
        victim = m["players"].get(victim_uid)
        if not victim or not victim.get("alive"):
            return {"ok": False, "msg": "เหยื่อไม่พร้อม"}
        victim["alive"] = False
        victim["hp"] = 0
        victim["in_zone"] = False
        victim["deaths"] = int(victim.get("deaths") or 0) + 1
        # เงินติดตัวลดเมื่อตาย
        victim["cash_on_hand"] = int(int(victim.get("cash_on_hand") or 0) * WD_RESPAWN_CASH_KEEP)

        reward = 200
        if killer and killer.get("alive") and killer.get("team") != victim.get("team"):
            killer["kills"] = int(killer.get("kills") or 0) + 1
            killer["cash_on_hand"] = int(killer.get("cash_on_hand") or 0) + reward

        feed = {
            "at": _wd_time.time(),
            "killer": killer_uid if killer else None,
            "victim": victim_uid,
            "killer_team": killer.get("team") if killer else None,
            "victim_team": victim.get("team"),
        }
        m["kill_feed"].append(feed)
        del m["kill_feed"][:-30]

    return {
        "ok": True,
        "killer": killer_uid,
        "victim": victim_uid,
        "reward": reward if killer else 0,
        "msg": f"{killer_uid or 'โลก'} ฆ่า {victim_uid}",
    }


def wardogs_respawn(match_id: str, uid: str) -> dict:
    match_id, uid = str(match_id), str(uid)
    with _WD_LOCK:
        m = WD_MATCHES.get(match_id)
        if not m or uid not in m["players"]:
            return {"ok": False, "msg": "ไม่ได้อยู่ในแมตช์"}
        pl = m["players"][uid]
        if pl.get("alive"):
            return {"ok": True, "msg": "ยังมีชีวิตอยู่"}
        pl["alive"] = True
        pl["hp"] = pl.get("hp_max") or 100
        pl["in_zone"] = False
        pl["x"] = _wd_rand.uniform(-800, 800)
        pl["y"] = _wd_rand.uniform(-800, 800)
    return {"ok": True, "msg": "เกิดใหม่แล้ว", "player": pl}


def wardogs_state(match_id: str) -> dict:
    match_id = str(match_id)
    with _WD_LOCK:
        m = WD_MATCHES.get(match_id)
        if not m:
            return {"ok": False, "msg": "ไม่พบแมตช์"}
        _wd_recount_zone(m)
        players_public = []
        for uid, pl in m["players"].items():
            players_public.append({
                "uid": uid,
                "team": pl["team"],
                "alive": pl["alive"],
                "hp": pl["hp"],
                "kills": pl.get("kills") or 0,
                "deaths": pl.get("deaths") or 0,
                "in_zone": pl.get("in_zone"),
                "vehicle": (pl.get("loadout") or {}).get("vehicle"),
                "cash_on_hand": pl.get("cash_on_hand"),
            })
        return {
            "ok": True,
            "match_id": match_id,
            "status": m["status"],
            "scores": dict(m["scores"]),
            "team_counts": dict(m["team_counts"]),
            "control_zone": dict(m["control_zone"]),
            "structures": {k: dict(v) for k, v in m["structures"].items()},
            "players": players_public,
            "player_count": len(m["players"]),
            "winner_team": m.get("winner_team"),
            "kill_feed": list(m.get("kill_feed") or [])[-10:],
            "score_to_win": WD_SCORE_TO_WIN,
        }


def wardogs_list_matches() -> dict:
    with _WD_LOCK:
        items = []
        for mid, m in WD_MATCHES.items():
            items.append({
                "match_id": mid,
                "status": m["status"],
                "players": len(m["players"]),
                "scores": dict(m["scores"]),
                "winner_team": m.get("winner_team"),
            })
    return {"ok": True, "matches": items, "count": len(items)}


def wardogs_demo():
    print("=== WARDOGS-style demo (3 teams · Control Zone) ===")
    print(wardogs_catalog()["teams"], "score_to_win=", WD_SCORE_TO_WIN)
    r = wardogs_create_match()
    mid = r["match_id"]
    print("create:", mid)
    for i, name in enumerate(["alice", "bob", "carol", "dave", "erin", "frank"]):
        print(wardogs_join(mid, name)["msg"])
    print(wardogs_start(mid)["msg"])
    # ซื้อของ
    print(wardogs_buy_loadout(mid, "alice", "weapons", "ar")["msg"])
    print(wardogs_buy_loadout(mid, "alice", "vehicles", "jeep")["msg"])
    print(wardogs_buy_loadout(mid, "bob", "weapons", "shotgun")["msg"])
    # เข้าโซน
    for u in ["alice", "bob", "carol"]:
        wardogs_set_in_zone(mid, u, True)
    print("tick1:", wardogs_zone_tick(mid)["msg"])
    print("tick2:", wardogs_zone_tick(mid)["msg"])
    # ฆ่า + ทำลาย
    print(wardogs_kill(mid, "alice", "dave")["msg"])
    print(wardogs_damage_structure(mid, "radio_tower", 200)["msg"])
    print(wardogs_damage_structure(mid, "radio_tower", 350)["msg"])
    st = wardogs_state(mid)
    print("scores:", st["scores"], "held_by:", st["control_zone"]["held_by"])
    print("=== done ===")


