def _vkb_register_routes():
    app = globals().get("app")
    if app is None:
        return
    require = globals().get("require_auth_toggleable")
    if require is None:
        def require(f):
            return f

    @app.route("/api/voice_kb/settings", methods=["GET", "POST"])
    def api_vkb_settings():
        from flask import request, jsonify
        if request.method == "GET":
            return jsonify(voice_kb_get_settings(request.args.get("uid") or "player"))
        b = request.json or {}
        uid = b.get("uid") or "player"
        return jsonify(voice_kb_set_settings(uid, **{k: b.get(k) for k in (
            "enabled", "input_lang", "output_lang", "preferred_langs", "auto_detect_lang",
            "ai_correct", "auto_punctuate",
            "insert_mode", "show_preview", "silence_end_sec", "platform",
            "as_system_keyboard", "default_keyboard", "hotkey", "cloud_ai",
        )}))

    @app.route("/api/voice_kb/platforms")
    def api_vkb_platforms():
        from flask import jsonify
        return jsonify(voice_kb_list_platforms())

    @app.route("/api/voice_kb/languages")
    def api_vkb_languages():
        from flask import request, jsonify
        return jsonify(voice_kb_list_languages(request.args.get("q") or request.args.get("query")))

    @app.route("/api/voice_kb/embed_modes")
    def api_vkb_embed_modes():
        from flask import jsonify
        return jsonify(voice_kb_embed_modes())

    @app.route("/api/voice_kb/use_embedded", methods=["POST"])
    def api_vkb_use_embedded():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_use_embedded(
            b.get("uid") or "player",
            mode=b.get("mode") or "embedded_in_game",
        ))

    @app.route("/api/voice_kb/quick_start", methods=["POST"])
    def api_vkb_quick_start():
        """จุดเข้าผู้เล่น — ฝังในเกม ไม่ต้องติดตั้งแอปแยก"""
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_zero_friction_start(
            b.get("uid") or "player",
            target_field=b.get("target_field") or "chat_input",
            app_context=b.get("app_context") or "game",
        ))

    @app.route("/api/voice_kb/enable_system_wide", methods=["POST"])
    def api_vkb_enable_system_wide():
        """คนที่อยากเลิก Gboard — ใช้แป้น VMAX ทั้งเครื่อง"""
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_enable_system_wide(
            b.get("uid") or "player",
            set_as_default=bool(b.get("set_as_default", True)),
        ))

    @app.route("/api/voice_kb/native_ime")
    def api_vkb_native_ime():
        from flask import jsonify
        return jsonify(voice_kb_native_ime_info())

    @app.route("/api/voice_kb/export_native_ime", methods=["POST"])
    def api_vkb_export_native_ime():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_export_native_ime(b.get("dest_dir")))

    @app.route("/api/voice_kb/detect_lang", methods=["GET", "POST"])
    def api_vkb_detect_lang():
        from flask import request, jsonify
        if request.method == "POST":
            b = request.json or {}
            text = b.get("text") or ""
        else:
            text = request.args.get("text") or ""
        return jsonify(voice_kb_detect_language(text))

    @app.route("/api/voice_kb/lang_pair", methods=["POST"])
    def api_vkb_lang_pair():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_set_language_pair(
            b.get("uid") or "player",
            b.get("input_lang") or b.get("from") or "th",
            b.get("output_lang") if ("output_lang" in b or "to" in b) else None,
        ))

    @app.route("/api/voice_kb/platform")
    def api_vkb_platform():
        from flask import request, jsonify
        return jsonify(voice_kb_platform_info(request.args.get("id") or request.args.get("platform")))

    @app.route("/api/voice_kb/install_guide")
    def api_vkb_install_guide():
        from flask import request, jsonify
        return jsonify(voice_kb_install_guide(request.args.get("platform") or request.args.get("id")))

    @app.route("/api/voice_kb/register_system", methods=["POST"])
    @require
    def api_vkb_register_system():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_register_as_system_keyboard(
            b.get("uid") or "player",
            platform_id=b.get("platform"),
            set_default=bool(b.get("set_default") or b.get("default")),
        ))

    @app.route("/api/voice_kb/unregister_system", methods=["POST"])
    @require
    def api_vkb_unregister_system():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_uninstall_system_keyboard(b.get("platform")))

    @app.route("/api/voice_kb/bridge_manifest")
    def api_vkb_bridge_manifest():
        from flask import request, jsonify
        return jsonify(voice_kb_bridge_manifest(request.args.get("platform")))

    @app.route("/api/voice_kb/start", methods=["POST"])
    @require
    def api_vkb_start():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_start_session(
            b.get("uid") or "player",
            target_field=b.get("target_field") or "default",
            app_context=b.get("app_context") or "",
            platform=b.get("platform"),
        ))

    @app.route("/api/voice_kb/push", methods=["POST"])
    @require
    def api_vkb_push():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_push_partial(
            b.get("uid") or "player",
            text_chunk=b.get("text") or b.get("text_chunk") or "",
            audio_ref=b.get("audio_ref") or "",
            ended=bool(b.get("ended")),
        ))

    @app.route("/api/voice_kb/end", methods=["POST"])
    @require
    def api_vkb_end():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_end_utterance(
            b.get("uid") or "player",
            text_hint=b.get("text") or b.get("text_hint"),
        ))

    @app.route("/api/voice_kb/commit", methods=["POST"])
    @require
    def api_vkb_commit():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_commit(b.get("uid") or "player"))

    @app.route("/api/voice_kb/cancel", methods=["POST"])
    @require
    def api_vkb_cancel():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_cancel(b.get("uid") or "player"))

    @app.route("/api/voice_kb/session")
    def api_vkb_session():
        from flask import request, jsonify
        return jsonify(voice_kb_get_session(request.args.get("uid") or "player"))

    @app.route("/api/voice_kb/insert")
    def api_vkb_insert():
        from flask import request, jsonify
        return jsonify(voice_kb_insert_payload(request.args.get("uid") or "player"))

    @app.route("/api/voice_kb/history")
    def api_vkb_history():
        from flask import request, jsonify
        return jsonify(voice_kb_history(
            request.args.get("uid") or "player",
            limit=int(request.args.get("limit") or 10),
        ))

    @app.route("/api/voice_kb/state")
    def api_vkb_state():
        from flask import request, jsonify
        return jsonify(voice_kb_state(request.args.get("uid") or "player"))

    @app.route("/api/voice_kb/stt_fix", methods=["POST"])
    @require
    def api_vkb_stt_fix():
        from flask import request, jsonify
        b = request.json or {}
        return jsonify(voice_kb_register_stt_fix(b.get("wrong") or "", b.get("right") or "", lang=b.get("lang")))


