# ============================================================
# VMAX AI Native Binary Builder — ELF64 (Linux) + PE32+ (Windows)
# เขียน executable จริงจาก machine code ที่ประกอบขึ้นเอง (ไม่พึ่ง gcc/nasm)
# ทดสอบแล้ว: ELF รันจริงบน Linux ได้ output/exit code ถูกต้อง,
#            PE ผ่านการตรวจโครงสร้างด้วย file/objdump (import table,
#            calling convention x64 ถูกต้อง: shadow space, stack align 16,
#            call ผ่าน IAT ไปยัง KERNEL32.DLL: GetStdHandle/WriteFile/ExitProcess)
# ============================================================
import struct as _vbb_struct
import hashlib as _vbb_hashlib
import os as _vbb_os

VMAX_BINBUILDER_DIR = globals().get("VMAX_BINBUILDER_DIR", "/tmp/vmax_binbuilder")


def _vbb_align(v: int, a: int) -> int:
    return (v + a - 1) // a * a


def vmax_build_elf64(message: bytes, exit_code: int = 0, base: int = 0x400000) -> bytes:
    """สร้าง ELF64 executable (Linux x86-64) แบบ static ตรงๆ ด้วย syscall write()+exit()
    ไม่พึ่งไลบรารีใดๆ — เหมาะกับโปรแกรมเล็กๆ ที่พิมพ์ข้อความแล้วจบด้วย exit code ที่กำหนด"""
    if isinstance(message, str):
        message = message.encode("utf-8")

    code = b""
    code += b"\xB8\x01\x00\x00\x00"                      # mov eax,1      (sys_write)
    code += b"\xBF\x01\x00\x00\x00"                      # mov edi,1      (fd=stdout)
    lea_pos = len(code)
    code += b"\x48\x8D\x35" + b"\x00\x00\x00\x00"        # lea rsi,[rip+disp32] -> msg
    code += b"\xBA" + _vbb_struct.pack("<I", len(message))  # mov edx,len
    code += b"\x0F\x05"                                   # syscall
    code += b"\xB8\x3C\x00\x00\x00"                      # mov eax,60     (sys_exit)
    code += b"\xBF" + _vbb_struct.pack("<i", exit_code)   # mov edi,exit_code
    code += b"\x0F\x05"                                   # syscall
    code_len = len(code)

    next_off = lea_pos + 7
    disp32 = code_len - next_off               # message sits right after code
    code = code[:lea_pos + 3] + _vbb_struct.pack("<i", disp32) + code[lea_pos + 7:]

    HEADER_SIZE = 64 + 56
    total_size = HEADER_SIZE + code_len + len(message)
    entry = base + HEADER_SIZE

    ehdr = b"\x7fELF" + bytes([2, 1, 1, 0]) + b"\x00" * 8
    ehdr += _vbb_struct.pack("<HHI", 2, 0x3E, 1)          # ET_EXEC, EM_X86_64, version
    ehdr += _vbb_struct.pack("<Q", entry)
    ehdr += _vbb_struct.pack("<Q", 64)                     # e_phoff
    ehdr += _vbb_struct.pack("<Q", 0)                      # e_shoff
    ehdr += _vbb_struct.pack("<I", 0)                      # e_flags
    ehdr += _vbb_struct.pack("<HHHHHH", 64, 56, 1, 0, 0, 0)

    phdr = _vbb_struct.pack("<IIQQQQQQ", 1, 5, 0, base, base, total_size, total_size, 0x1000)

    return ehdr + phdr + code + message


def vmax_build_pe64(message: bytes, exit_code: int = 0, image_base: int = 0x140000000) -> bytes:
    """สร้าง PE32+ executable (Windows x86-64 console .exe) โดยเขียน machine code
    + import table เองทั้งหมด เรียก KERNEL32.DLL (GetStdHandle/WriteFile/ExitProcess)
    ตาม Microsoft x64 calling convention (shadow space 32 ไบต์, stack align 16,
    เรียกผ่าน IAT ด้วย call qword ptr [rip+disp32])"""
    if isinstance(message, str):
        message = message.encode("utf-8")

    SECTION_RVA = 0x1000
    FILE_ALIGN = 0x200
    SECT_ALIGN = 0x1000

    code = b""
    code += b"\x48\x83\xE4\xF0"                            # and rsp,-16        (บังคับ align 16)
    code += b"\x48\x83\xEC\x40"                             # sub rsp,0x40        (shadow space+local)
    code += b"\xB9\xF5\xFF\xFF\xFF"                         # mov ecx,-11         (STD_OUTPUT_HANDLE)
    call1_pos = len(code)
    code += b"\xFF\x15" + b"\x00\x00\x00\x00"               # call [rip+d] -> GetStdHandle
    store_pos = len(code)
    code += b"\x48\x89\x05" + b"\x00\x00\x00\x00"           # mov [rip+d],rax -> hStdOut
    load_pos = len(code)
    code += b"\x48\x8B\x0D" + b"\x00\x00\x00\x00"           # mov rcx,[rip+d] <- hStdOut
    lea_msg_pos = len(code)
    code += b"\x48\x8D\x15" + b"\x00\x00\x00\x00"           # lea rdx,[rip+d] -> msg
    code += b"\x41\xB8" + _vbb_struct.pack("<I", len(message))  # mov r8d,len
    lea_written_pos = len(code)
    code += b"\x4C\x8D\x0D" + b"\x00\x00\x00\x00"           # lea r9,[rip+d] -> written
    code += b"\x48\xC7\x44\x24\x20" + _vbb_struct.pack("<I", 0)  # mov qword[rsp+0x20],0 (lpOverlapped)
    call2_pos = len(code)
    code += b"\xFF\x15" + b"\x00\x00\x00\x00"               # call [rip+d] -> WriteFile
    code += b"\xB9" + _vbb_struct.pack("<i", exit_code)      # mov ecx,exit_code
    call3_pos = len(code)
    code += b"\xFF\x15" + b"\x00\x00\x00\x00"               # call [rip+d] -> ExitProcess
    code += b"\x0F\x0B"                                      # ud2 (ป้องกันไหลต่อ)
    CODE_LEN = len(code)

    off = CODE_LEN
    off += (8 - off % 8) % 8
    HSTDOUT_OFF = off; off += 8
    WRITTEN_OFF = off; off += 4
    MSG_OFF = off; off += len(message)
    off += (4 - off % 4) % 4
    IMPDIR_OFF = off; off += 40
    IAT_OFF = off; off += 32
    H_GETSTDHANDLE_OFF = off
    gsh = (b"\x00\x00" + b"GetStdHandle\x00")
    gsh += b"\x00" * (len(gsh) % 2)
    off += len(gsh)
    H_WRITEFILE_OFF = off
    wf = (b"\x00\x00" + b"WriteFile\x00")
    wf += b"\x00" * (len(wf) % 2)
    off += len(wf)
    H_EXITPROCESS_OFF = off
    ep = (b"\x00\x00" + b"ExitProcess\x00")
    ep += b"\x00" * (len(ep) % 2)
    off += len(ep)
    DLLNAME_OFF = off
    dll = b"KERNEL32.DLL\x00"
    dll += b"\x00" * (len(dll) % 2)
    off += len(dll)
    SECTION_SIZE = off

    def fix(buf, pos, instr_len, target_off):
        next_off = pos + instr_len
        disp = target_off - next_off
        opcode_len = instr_len - 4
        return buf[:pos] + buf[pos:pos + opcode_len] + _vbb_struct.pack("<i", disp) + buf[pos + instr_len:]

    code = fix(code, call1_pos, 6, IAT_OFF + 0)
    code = fix(code, store_pos, 7, HSTDOUT_OFF)
    code = fix(code, load_pos, 7, HSTDOUT_OFF)
    code = fix(code, lea_msg_pos, 7, MSG_OFF)
    code = fix(code, lea_written_pos, 7, WRITTEN_OFF)
    code = fix(code, call2_pos, 6, IAT_OFF + 8)
    code = fix(code, call3_pos, 6, IAT_OFF + 16)

    section = bytearray(SECTION_SIZE)
    section[0:CODE_LEN] = code
    section[MSG_OFF:MSG_OFF + len(message)] = message
    section[IMPDIR_OFF:IMPDIR_OFF + 20] = _vbb_struct.pack(
        "<IIIII", 0, 0, 0, SECTION_RVA + DLLNAME_OFF, SECTION_RVA + IAT_OFF)
    iat = (_vbb_struct.pack("<Q", SECTION_RVA + H_GETSTDHANDLE_OFF) +
           _vbb_struct.pack("<Q", SECTION_RVA + H_WRITEFILE_OFF) +
           _vbb_struct.pack("<Q", SECTION_RVA + H_EXITPROCESS_OFF) +
           _vbb_struct.pack("<Q", 0))
    section[IAT_OFF:IAT_OFF + 32] = iat
    section[H_GETSTDHANDLE_OFF:H_GETSTDHANDLE_OFF + len(gsh)] = gsh
    section[H_WRITEFILE_OFF:H_WRITEFILE_OFF + len(wf)] = wf
    section[H_EXITPROCESS_OFF:H_EXITPROCESS_OFF + len(ep)] = ep
    section[DLLNAME_OFF:DLLNAME_OFF + len(dll)] = dll
    section = bytes(section)

    dos = bytearray(64)
    dos[0:2] = b"MZ"
    _vbb_struct.pack_into("<I", dos, 0x3C, 0x40)

    size_opt_hdr = 240
    characteristics = 0x0002 | 0x0020  # EXECUTABLE_IMAGE | LARGE_ADDRESS_AWARE
    coff = _vbb_struct.pack("<HHIIIHH", 0x8664, 1, 0, 0, 0, size_opt_hdr, characteristics)

    headers_raw_nopad = 64 + 4 + 20 + size_opt_hdr + 40
    size_of_headers = _vbb_align(headers_raw_nopad, FILE_ALIGN)
    size_of_image = _vbb_align(SECTION_RVA + SECTION_SIZE, SECT_ALIGN)
    size_of_raw_data = _vbb_align(SECTION_SIZE, FILE_ALIGN)

    opt = b""
    opt += _vbb_struct.pack("<H", 0x20B)
    opt += _vbb_struct.pack("<BB", 1, 0)
    opt += _vbb_struct.pack("<I", _vbb_align(CODE_LEN, FILE_ALIGN))
    opt += _vbb_struct.pack("<I", _vbb_align(SECTION_SIZE - CODE_LEN, FILE_ALIGN))
    opt += _vbb_struct.pack("<I", 0)
    opt += _vbb_struct.pack("<I", SECTION_RVA)
    opt += _vbb_struct.pack("<I", SECTION_RVA)
    opt += _vbb_struct.pack("<Q", image_base)
    opt += _vbb_struct.pack("<I", SECT_ALIGN)
    opt += _vbb_struct.pack("<I", FILE_ALIGN)
    opt += _vbb_struct.pack("<HH", 6, 0)
    opt += _vbb_struct.pack("<HH", 0, 0)
    opt += _vbb_struct.pack("<HH", 6, 0)
    opt += _vbb_struct.pack("<I", 0)
    opt += _vbb_struct.pack("<I", size_of_image)
    opt += _vbb_struct.pack("<I", size_of_headers)
    opt += _vbb_struct.pack("<I", 0)
    opt += _vbb_struct.pack("<H", 3)
    opt += _vbb_struct.pack("<H", 0x0100)
    opt += _vbb_struct.pack("<Q", 0x100000)
    opt += _vbb_struct.pack("<Q", 0x1000)
    opt += _vbb_struct.pack("<Q", 0x100000)
    opt += _vbb_struct.pack("<Q", 0x1000)
    opt += _vbb_struct.pack("<I", 0)
    opt += _vbb_struct.pack("<I", 16)
    data_dirs = [(0, 0)] * 16
    data_dirs[1] = (SECTION_RVA + IMPDIR_OFF, 40)
    for rva, size in data_dirs:
        opt += _vbb_struct.pack("<II", rva, size)

    sect_hdr = b".text\x00\x00\x00"
    sect_hdr += _vbb_struct.pack("<I", SECTION_SIZE)
    sect_hdr += _vbb_struct.pack("<I", SECTION_RVA)
    sect_hdr += _vbb_struct.pack("<I", size_of_raw_data)
    sect_hdr += _vbb_struct.pack("<I", size_of_headers)
    sect_hdr += _vbb_struct.pack("<IIHH", 0, 0, 0, 0)
    sect_char = 0x00000020 | 0x00000040 | 0x20000000 | 0x40000000 | 0x80000000
    sect_hdr += _vbb_struct.pack("<I", sect_char & 0xFFFFFFFF)

    headers = (bytes(dos) + b"PE\x00\x00" + coff + opt + sect_hdr).ljust(size_of_headers, b"\x00")
    raw = (headers + section).ljust(size_of_headers + size_of_raw_data, b"\x00")
    return raw


def vmax_ai_write_binary(message: str = "Hello from VMAX!", exit_code: int = 0,
                          target: str = "linux", filename: str | None = None,
                          out_dir: str | None = None) -> dict:
    """API หลัก: สร้าง native executable จริงๆ (ไม่พึ่ง gcc/nasm/compiler ภายนอก)
    target: "linux" -> ELF64 x86-64 (รันได้ทันทีด้วย chmod +x)
            "windows" -> PE32+ x86-64 .exe (เปิดบน Windows จริง, ผ่าน file/objdump validate)
    คืนค่า path, ขนาดไฟล์, sha256, และรายละเอียด target"""
    target = (target or "linux").strip().lower()
    if target not in ("linux", "windows", "elf", "pe", "exe"):
        return {"ok": False, "error": f"target ไม่รองรับ: {target} (ใช้ 'linux' หรือ 'windows')"}

    is_windows = target in ("windows", "pe", "exe")
    data = vmax_build_pe64(message, exit_code) if is_windows else vmax_build_elf64(message, exit_code)

    out_dir = out_dir or VMAX_BINBUILDER_DIR
    _vbb_os.makedirs(out_dir, exist_ok=True)
    default_name = "vmax_output.exe" if is_windows else "vmax_output"
    filename = filename or default_name
    path = _vbb_os.path.join(out_dir, filename)
    with open(path, "wb") as f:
        f.write(data)
    if not is_windows:
        _vbb_os.chmod(path, 0o755)

    return {
        "ok": True,
        "target": "windows" if is_windows else "linux",
        "format": "PE32+ (x86-64)" if is_windows else "ELF64 (x86-64)",
        "path": path,
        "size_bytes": len(data),
        "sha256": _vbb_hashlib.sha256(data).hexdigest(),
        "message": message,
        "exit_code": exit_code,
    }


def vmax_binbuilder_demo() -> dict:
    """ทดสอบ: build ทั้ง linux และ windows แล้วคืนผลลัพธ์ทั้งคู่"""
    results = {
        "linux": vmax_ai_write_binary("Hello from VMAX AI compiler!\n", exit_code=7, target="linux"),
        "windows": vmax_ai_write_binary("Hello from VMAX AI compiler!\n", exit_code=7, target="windows"),
    }
    return results


def _vbb_register_routes():
    app = globals().get("app")
    if app is None:
        return
    require = globals().get("require_auth_toggleable")
    if require is None:
        def require(f):
            return f

    @app.route("/api/binbuilder/build", methods=["POST"])
    @require
    def api_binbuilder_build():
        from flask import request, jsonify
        b = request.json or {}
        result = vmax_ai_write_binary(
            message=b.get("message") or "Hello from VMAX!",
            exit_code=int(b.get("exit_code") or 0),
            target=b.get("target") or "linux",
            filename=b.get("filename"),
        )
        return jsonify(result)

    @app.route("/api/binbuilder/download")
    def api_binbuilder_download():
        from flask import request, send_file
        target = (request.args.get("target") or "linux").lower()
        result = vmax_ai_write_binary(
            message=request.args.get("message") or "Hello from VMAX!",
            exit_code=int(request.args.get("exit_code") or 0),
            target=target,
        )
        if not result.get("ok"):
            from flask import jsonify
            return jsonify(result), 400
        return send_file(result["path"], as_attachment=True,
                          download_name=_vbb_os.path.basename(result["path"]))

    @app.route("/api/binbuilder/demo")
    def api_binbuilder_demo():
        from flask import jsonify
        return jsonify(vmax_binbuilder_demo())


try:
    _vbb_register_routes()
except Exception:
    pass

try:
    if isinstance(globals().get("VMAX_MODULES"), dict):
        VMAX_MODULES["ai_binary_builder"] = {
            "name": "AI Native Binary Builder (ELF64 Linux + PE32+ Windows ในไฟล์เดียว)",
            "version": "1.0.0",
            "desc": (
                "เขียน native executable จริงจาก machine code ที่ประกอบขึ้นเอง ไม่พึ่ง gcc/nasm/compiler ภายนอก. "
                "Linux: ELF64 เรียก syscall write()+exit() ตรงๆ. "
                "Windows: PE32+ x86-64 พร้อม import table ไป KERNEL32.DLL "
                "(GetStdHandle/WriteFile/ExitProcess) ตาม Microsoft x64 calling convention "
                "(stack align 16, shadow space 32 ไบต์, call ผ่าน IAT) — ตรวจผ่าน file/objdump แล้ว"
            ),
            "category": "dev_tools",
            "functions": [
                "vmax_build_elf64", "vmax_build_pe64",
                "vmax_ai_write_binary", "vmax_binbuilder_demo",
            ],
            "routes": [
                "/api/binbuilder/build", "/api/binbuilder/download", "/api/binbuilder/demo",
            ],
            "targets": ["linux", "windows"],
        }
except Exception:
    pass

if __name__ == "__main__":
    import sys as _vbb_sys
    if "--binbuilder-demo" in _vbb_sys.argv:
        import json as _vbb_json
        print(_vbb_json.dumps(vmax_binbuilder_demo(), ensure_ascii=False, indent=2))
        raise SystemExit(0)

print("[VMAX] AI Native Binary Builder v1.0 | ELF64(Linux)+PE32+(Windows) ในไฟล์เดียว | --binbuilder-demo")


# ---- ส่วนขยาย: เส้นทาง gcc จริง (ใช้เมื่อมี c_code ส่งมา) ----
import subprocess as _vbb_sp
import shutil as _vbb_shutil
import tempfile as _vbb_tempfile

VMAX_BINBUILDER_GCC_LINUX = "gcc"
VMAX_BINBUILDER_GCC_WINDOWS = "x86_64-w64-mingw32-gcc"  # mingw-w64 cross compiler


def vmax_compile_c_gcc(c_code: str, target: str = "linux", out_path: str | None = None,
                        optimize: str = "-O2") -> dict:
    """คอมไพล์ซอร์ส C จริงด้วย gcc (ไม่ใช่ machine code มือเขียนแบบ vmax_build_elf64/pe64)
    Linux  -> ใช้ gcc ตรงๆ (มีอยู่แล้วทั่วไปบนลินุกซ์)
    Windows -> ใช้ x86_64-w64-mingw32-gcc (mingw-w64 cross compiler, ต้องติดตั้งเพิ่มเอง
               เช่น `apt install mingw-w64` บน Debian/Ubuntu)
    ถ้าไม่มี compiler ที่ต้องการ จะคืน ok=False พร้อม missing_tool ให้ส่วนเรียกตัดสินใจ fallback เอง"""
    target = (target or "linux").strip().lower()
    is_windows = target in ("windows", "pe", "exe")
    compiler = VMAX_BINBUILDER_GCC_WINDOWS if is_windows else VMAX_BINBUILDER_GCC_LINUX

    if not _vbb_shutil.which(compiler):
        return {
            "ok": False,
            "error": f"ไม่พบ compiler '{compiler}' บนเครื่องนี้",
            "missing_tool": compiler,
            "hint": ("ติดตั้งด้วย: apt install mingw-w64" if is_windows
                      else "ติดตั้งด้วย: apt install gcc"),
        }

    out_dir = out_path and _vbb_os.path.dirname(out_path) or VMAX_BINBUILDER_DIR
    _vbb_os.makedirs(out_dir, exist_ok=True)
    out_path = out_path or _vbb_os.path.join(
        out_dir, "vmax_gcc_output.exe" if is_windows else "vmax_gcc_output")

    with _vbb_tempfile.NamedTemporaryFile(
            mode="w", suffix=".c", delete=False, dir=out_dir, encoding="utf-8") as f:
        f.write(c_code)
        src_path = f.name

    cmd = [compiler, optimize, "-o", out_path, src_path]
    try:
        proc = _vbb_sp.run(cmd, capture_output=True, text=True, timeout=60)
    except Exception as e:
        return {"ok": False, "error": f"เรียก {compiler} ไม่สำเร็จ: {e}", "command": " ".join(cmd)}
    finally:
        try:
            _vbb_os.remove(src_path)
        except OSError:
            pass

    if proc.returncode != 0:
        return {
            "ok": False,
            "error": "คอมไพล์ล้มเหลว (โค้ด C มีปัญหา)",
            "compiler": compiler,
            "command": " ".join(cmd),
            "stdout": proc.stdout,
            "stderr": proc.stderr,
        }

    if not is_windows:
        _vbb_os.chmod(out_path, 0o755)
    with open(out_path, "rb") as f:
        data = f.read()

    return {
        "ok": True,
        "target": "windows" if is_windows else "linux",
        "format": f"คอมไพล์จริงด้วย {compiler} ({optimize})",
        "path": out_path,
        "size_bytes": len(data),
        "sha256": _vbb_hashlib.sha256(data).hexdigest(),
        "compiler": compiler,
        "stderr_warnings": proc.stderr or None,
    }


def vmax_ai_write_binary(message: str = "Hello from VMAX!", exit_code: int = 0,
                          target: str = "linux", c_code: str | None = None,
                          filename: str | None = None, out_dir: str | None = None,
                          optimize: str = "-O2") -> dict:
    """API หลัก (อัปเดต): สองเส้นทาง
    1) ส่ง c_code (ซอร์ส C จริง) -> พยายามคอมไพล์ด้วย gcc จริงก่อน (ได้ logic/optimizer เต็มรูปแบบ
       ของ gcc) ถ้าไม่มี compiler ที่ต้องการในเครื่อง จะ fallback มาใช้ builder แบบไม่พึ่งอะไรเลย
       (ซึ่งรองรับได้แค่ message+exit_code เท่านั้น — c_code จะถูกข้าม พร้อมแจ้งเตือนใน "warning")
    2) ไม่ส่ง c_code -> ใช้ builder แบบไม่พึ่งอะไรภายนอกเลยเหมือนเดิม (message+exit_code,
       รับประกันว่าใช้ได้ทุกเครื่องไม่ว่าจะลง gcc/mingw ไว้หรือไม่)
    target: "linux" หรือ "windows"
    """
    target = (target or "linux").strip().lower()
    if target not in ("linux", "windows", "elf", "pe", "exe"):
        return {"ok": False, "error": f"target ไม่รองรับ: {target} (ใช้ 'linux' หรือ 'windows')"}
    is_windows = target in ("windows", "pe", "exe")

    out_dir = out_dir or VMAX_BINBUILDER_DIR
    _vbb_os.makedirs(out_dir, exist_ok=True)

    if c_code:
        default_name = filename or ("vmax_gcc_output.exe" if is_windows else "vmax_gcc_output")
        out_path = _vbb_os.path.join(out_dir, default_name)
        result = vmax_compile_c_gcc(c_code, target=target, out_path=out_path, optimize=optimize)
        if result.get("ok"):
            return result
        if result.get("missing_tool"):
            # fallback ไปใช้ builder มือเขียนแบบไม่พึ่งอะไรเลย (c_code ใช้ไม่ได้ ข้ามไป)
            fallback = _vbb_write_native(message, exit_code, target, filename, out_dir)
            fallback["warning"] = (
                f"ไม่มี {result['missing_tool']} ในเครื่องนี้ — ใช้ builder แบบไม่พึ่งอะไรภายนอกแทน "
                f"(c_code ที่ส่งมาถูกข้ามไป ได้แค่โปรแกรมพิมพ์ message+exit_code เท่านั้น). "
                f"{result.get('hint', '')}"
            )
            return fallback
        return result  # คอมไพล์ล้มเหลวจริง (โค้ด C ผิด) — ไม่ fallback เพราะปัญหาอยู่ที่โค้ดเอง

    return _vbb_write_native(message, exit_code, target, filename, out_dir)


def _vbb_write_native(message, exit_code, target, filename, out_dir) -> dict:
    is_windows = target in ("windows", "pe", "exe")
    data = vmax_build_pe64(message, exit_code) if is_windows else vmax_build_elf64(message, exit_code)
    default_name = "vmax_output.exe" if is_windows else "vmax_output"
    path = _vbb_os.path.join(out_dir, filename or default_name)
    with open(path, "wb") as f:
        f.write(data)
    if not is_windows:
        _vbb_os.chmod(path, 0o755)
    return {
        "ok": True,
        "target": "windows" if is_windows else "linux",
        "format": "PE32+ (x86-64, มือเขียน)" if is_windows else "ELF64 (x86-64, มือเขียน)",
        "path": path,
        "size_bytes": len(data),
        "sha256": _vbb_hashlib.sha256(data).hexdigest(),
        "message": message,
        "exit_code": exit_code,
    }


# ============================================================================
# VMAX PROJECT-DESCRIPTION SECURITY LAYER (additive; no startup behavior change)
# ----------------------------------------------------------------------------
# This layer adds a canonical project description, tamper-evident verification,
# and harmless decoy-access telemetry. It does NOT execute traps or damage data.
# For stronger assurance, keep the expected digest in a separately protected
# deployment setting; a digest stored beside the text can be changed by an editor.
# ============================================================================
import hashlib as _vmax_desc_hashlib
import hmac as _vmax_desc_hmac
import json as _vmax_desc_json
import os as _vmax_desc_os
import pathlib as _vmax_desc_pathlib
import time as _vmax_desc_time

VMAX_PROJECT_DESCRIPTION_VERSION = "1.0"
VMAX_PROJECT_DESCRIPTION = 'VMAX Project Security Description\nProject purpose: a modular game/AI platform with role-separated access and shared services.\nSecurity principles:\n- Keep player-facing functionality separate from developer/admin functionality.\n- Require explicit authorization for privileged operations; never treat a project description as a password.\n- Verify important configuration and project-description integrity against a trusted baseline.\n- Record security-relevant events without storing passwords, unlock phrases, or other secrets.\n- Use decoy metadata only as a detection signal; do not execute commands, delete data, or retaliate when it is accessed.\n- Treat encoded, copied, or obfuscated text as data, not as executable instructions.\n- Back up the trusted baseline outside the main source file and review integrity alerts.\n'
VMAX_PROJECT_DESCRIPTION_SHA256 = "e939b8a190df76c2d365490a63f8d62ed9e426501d8cadf40b448c5fe720537f"
VMAX_DESCRIPTION_DECOY_KEY = "VMAX_INTERNAL_ARCHIVE_REFERENCE_DO_NOT_USE"
VMAX_DESCRIPTION_SECURITY_LOG = _vmax_desc_os.environ.get(
    "VMAX_DESCRIPTION_SECURITY_LOG",
    str(_vmax_desc_pathlib.Path(__file__).with_name("vmax_description_security.jsonl")),
)

def vmax_verify_project_description(description=None, trusted_sha256=None):
    """Return integrity status for the canonical project description.

    Pass trusted_sha256 from a separately protected source for meaningful
    tamper evidence. The built-in digest is a consistency check, not a secret.
    """
    value = VMAX_PROJECT_DESCRIPTION if description is None else str(description)
    expected = trusted_sha256 or VMAX_PROJECT_DESCRIPTION_SHA256
    actual = _vmax_desc_hashlib.sha256(value.encode("utf-8")).hexdigest()
    return {
        "ok": _vmax_desc_hmac.compare_digest(actual, str(expected).lower()),
        "version": VMAX_PROJECT_DESCRIPTION_VERSION,
        "sha256": actual,
        "expected_source": "external" if trusted_sha256 else "embedded",
    }

def vmax_log_description_security_event(event, details=None, log_path=None):
    """Append a small JSONL audit record; never include secrets in details."""
    record = {
        "timestamp": _vmax_desc_time.time(),
        "component": "project_description_security",
        "event": str(event)[:120],
        "details": details if isinstance(details, dict) else {},
    }
    path = _vmax_desc_pathlib.Path(log_path or VMAX_DESCRIPTION_SECURITY_LOG)
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("a", encoding="utf-8") as stream:
            stream.write(_vmax_desc_json.dumps(record, ensure_ascii=False, sort_keys=True) + "\\n")
        return {"ok": True, "path": str(path)}
    except OSError as exc:
        return {"ok": False, "error": type(exc).__name__}

def vmax_access_description_decoy(reference):
    """Record access to a decoy reference and return a neutral result.

    This is a detection hook only: it does not block, execute, or retaliate.
    Call it from a real access-control boundary if the project exposes decoy
    metadata. Do not treat this function alone as an access-control mechanism.
    """
    token = str(reference)[:256]
    if token == VMAX_DESCRIPTION_DECOY_KEY:
        vmax_log_description_security_event(
            "decoy_reference_accessed",
            {"reference": "decoy", "source": "application-hook"},
        )
        return {"ok": False, "status": "not_available"}
    return {"ok": True, "status": "ordinary_reference"}

def vmax_project_description_security_status(trusted_sha256=None):
    """Convenience status function for diagnostics or the central API."""
    result = vmax_verify_project_description(trusted_sha256=trusted_sha256)
    if not result["ok"]:
        vmax_log_description_security_event(
            "description_integrity_mismatch",
            {"expected_source": result["expected_source"], "actual_sha256": result["sha256"]},
        )
    return result

# Optional central-API registration is intentionally explicit to avoid guessing
# the project's API object/name and accidentally changing startup behavior.
def vmax_register_description_security(api, prefix="project_description_security"):
    """Register the security functions with a dict-like central API."""
    if not hasattr(api, "__setitem__"):
        raise TypeError("api must support item assignment")
    api[f"{prefix}.verify"] = vmax_verify_project_description
    api[f"{prefix}.status"] = vmax_project_description_security_status
    api[f"{prefix}.log_event"] = vmax_log_description_security_event
    api[f"{prefix}.decoy_access"] = vmax_access_description_decoy
    return {"ok": True, "registered": 4}
# ============================================================================
# VMAX CENTRAL API UNIVERSAL MODULE GATEWAY (additive integration layer)
# ----------------------------------------------------------------------------
# Modules can be registered here and moved within the application without
# binding them to a provider-specific client. External connectivity is enabled
# only when VMAX_CENTRAL_API_URL is configured by the deployment.
# ============================================================================

class VMAXCentralModuleGateway:
    """Shared internal gateway for portable module registration and dispatch."""
    _lock = _vmax_threading.RLock()
    _modules = {}
    _client = None

    @classmethod
    def register(cls, name, module, actions=None):
        key = str(name or "").strip()
        if not key or module is None:
            raise ValueError("A non-empty module name and module object are required")
        if actions is None:
            actions = getattr(module, "central_api_actions", ())
        if isinstance(actions, str):
            actions = (actions,)
        normalized = tuple(sorted({str(a).strip() for a in (actions or ())
                                   if str(a).strip() and not str(a).startswith("_")}))
        with cls._lock:
            cls._modules[key] = {"module": module, "actions": normalized}
            VMAXSharedCentralModuleRegistry.register(key, module)
        return {"ok": True, "module": key, "actions": list(normalized)}

    @classmethod
    def unregister(cls, name):
        with cls._lock:
            return cls._modules.pop(str(name), None) is not None

    @classmethod
    def get(cls, name):
        with cls._lock:
            entry = cls._modules.get(str(name))
            return entry["module"] if entry else None

    @classmethod
    def call(cls, module_name, action, *args, **kwargs):
        """Dispatch only actions explicitly declared by a registered module."""
        with cls._lock:
            entry = cls._modules.get(str(module_name))
        if entry is None:
            raise LookupError("Central gateway module is not registered: %s" % module_name)
        if str(action) not in entry["actions"]:
            raise PermissionError("Action is not exposed by central gateway: %s.%s" % (module_name, action))
        target = getattr(entry["module"], str(action), None)
        if not callable(target):
            raise AttributeError("Registered module action is not callable: %s.%s" % (module_name, action))
        return target(*args, **kwargs)

    @classmethod
    def attach_client(cls, client):
        with cls._lock:
            cls._client = client
        return client

    @classmethod
    def publish_event(cls, module_name, event_type, payload):
        with cls._lock:
            client = cls._client
        if client is None:
            raise RuntimeError("Central API client is not connected/configured")
        return client.publish_event(str(event_type), {
            "module": str(module_name),
            "engine_id": _vmax_os.getenv("VMAX_ENGINE_ID", "local-engine"),
            "payload": payload if isinstance(payload, dict) else {"value": payload},
        })

    @classmethod
    def status(cls):
        with cls._lock:
            names = sorted(cls._modules)
            client_ready = cls._client is not None
        central = VMAXSharedCentralModuleRegistry.status()
        return {
            "ok": True,
            "gateway_ready": True,
            "module_count": len(names),
            "modules": names,
            "client_ready": client_ready,
            "central": central,
            "base_url_configured": bool(_vmax_os.getenv("VMAX_CENTRAL_API_URL", "").strip()),
        }


def vmax_central_register_module(name, module, actions=None):
    """Register a portable module and its explicitly approved callable actions."""
    return VMAXCentralModuleGateway.register(name, module, actions=actions)


def vmax_central_call(module_name, action, *args, **kwargs):
    """Call an explicitly registered module action through the shared gateway."""
    return VMAXCentralModuleGateway.call(module_name, action, *args, **kwargs)


def vmax_central_publish_event(module_name, event_type, payload):
    """Publish a module event through the shared central API client."""
    return VMAXCentralModuleGateway.publish_event(module_name, event_type, payload)


def vmax_central_gateway_status():
    """Return a secret-free status report for gateway diagnostics."""
    return VMAXCentralModuleGateway.status()


# Make the orchestrator's health-check contract consistent with the client.
# The original orchestrator looked for health_check(), while the client exposed
# health(); this alias makes the health probe actually execute when configured.
def _vmax_central_client_health_check(self):
    return self.health()

VMAXCentralAPIClient.health_check = _vmax_central_client_health_check

# Attach the active client whenever the orchestrator creates one, so all
# registered modules use the same client rather than creating provider clients.
_vmax_original_connect_once = VMAXAutomaticCentralAPIOrchestrator._connect_once

def _vmax_gateway_connect_once(self):
    result = _vmax_original_connect_once(self)
    if self.client is not None:
        VMAXCentralModuleGateway.attach_client(self.client)
    return result

VMAXAutomaticCentralAPIOrchestrator._connect_once = _vmax_gateway_connect_once

# Reuse the encrypted central credential already managed by the service setup.
# No key is written into source code and no network call occurs without a URL.
def vmax_configure_central_gateway(start=True, base_url=None, api_key=None, engine_id=None):
    resolved_url = (base_url or _vmax_os.getenv("VMAX_CENTRAL_API_URL", "")).strip()
    resolved_key = api_key
    if resolved_key is None:
        resolved_key = (_vmax_os.getenv("VMAX_CENTRAL_API_KEY", "").strip()
                        or _vmax_os.getenv("CENTRAL_API_KEY", "").strip())
    if not resolved_url:
        return {"ok": False, "configured": False,
                "message": "Set VMAX_CENTRAL_API_URL to your real central API endpoint first.",
                "gateway": vmax_central_gateway_status()}
    orchestrator = VMAXSharedCentralModuleRegistry.configure(
        base_url=resolved_url,
        api_key=resolved_key or None,
        engine_id=engine_id or _vmax_os.getenv("VMAX_ENGINE_ID", "local-engine"),
    )
    if start:
        orchestrator.start()
    return {"ok": True, "configured": True, "started": bool(start),
            "gateway": vmax_central_gateway_status()}


VMAX_CENTRAL_UNIVERSAL_GATEWAY_READY = True

# Register only explicitly marked module adapters already present in this file.
# We deliberately do not expose arbitrary globals or arbitrary methods.
def vmax_discover_central_modules(namespace=None):
    namespace = globals() if namespace is None else namespace
    found = []
    # Only harmless, read-oriented diagnostics plus explicit event/entity hooks
    # are eligible for automatic exposure. Mutating actions must be declared
    # explicitly by the module author via central_api_actions.
    safe_actions = {
        "health_check", "status", "get_status", "describe", "snapshot",
        "export_state", "emit_event", "sync_entity", "health", "metrics",
        "get_state", "list_items",
    }
    for name, obj in list(namespace.items()):
        if not isinstance(name, str) or name.startswith("_") or obj is None:
            continue
        if isinstance(obj, type) or isinstance(obj, (str, bytes, int, float, bool, dict, list, tuple, set)):
            continue
        declared = getattr(obj, "central_api_actions", None)
        if declared:
            actions = declared
        else:
            actions = [action for action in safe_actions
                       if callable(getattr(obj, action, None))]
        if not actions:
            continue
        try:
            result = VMAXCentralModuleGateway.register(name, obj, actions=actions)
            found.append(result["module"])
        except (TypeError, ValueError):
            continue
    return sorted(set(found))

VMAX_CENTRAL_DISCOVERED_MODULES = vmax_discover_central_modules()

# Auto-start only when a real endpoint has been supplied by deployment config.
# A missing endpoint leaves the app usable and reports a clear unconfigured state.
if _vmax_os.getenv("VMAX_CENTRAL_AUTO_CONNECT", "1").strip().lower() not in {"0", "false", "no"} and _vmax_os.getenv("VMAX_CENTRAL_API_URL", "").strip():
    try:
        vmax_configure_central_gateway(start=True)
    except Exception as _vmax_gateway_start_error:
        _vmax_logging.getLogger("vmax.central").warning(
            "Central gateway startup deferred: %s", type(_vmax_gateway_start_error).__name__
        )

# ============================================================================
# VMAX HERMES AGENT API BRIDGE / REPAIR CENTER (optional)
# Uses Hermes Agent's OpenAI-compatible API server. This does not install or
# launch Hermes, and deliberately does not edit project files automatically.
# Configure secrets through environment variables, never hard-code them here.
# ============================================================================
try:
    import urllib.request as _vmax_hermes_urlrequest
    import urllib.error as _vmax_hermes_urlerror
    import urllib.parse as _vmax_hermes_urlparse
    import hmac as _vmax_hermes_hmac
except Exception:  # pragma: no cover
    _vmax_hermes_urlrequest = None
    _vmax_hermes_urlerror = None
    _vmax_hermes_urlparse = None
    _vmax_hermes_hmac = None


def vmax_hermes_agent_status():
    """Report non-secret Hermes configuration and whether a call can be made."""
    _base = os.environ.get("HERMES_API_BASE_URL", "http://127.0.0.1:8642/v1").strip().rstrip("/")
    _model = os.environ.get("HERMES_API_MODEL", "hermes").strip()
    _api_key = os.environ.get("HERMES_API_KEY", "").strip()
    _guard_key = os.environ.get("VMAX_REPAIR_CENTER_KEY", "").strip()
    _valid_url = False
    if _vmax_hermes_urlparse is not None:
        try:
            _parsed = _vmax_hermes_urlparse.urlparse(_base)
            _valid_url = _parsed.scheme in ("http", "https") and bool(_parsed.netloc) and not _parsed.username and not _parsed.password
        except Exception:
            _valid_url = False
    return {
        "ok": True,
        "provider": "Hermes Agent (Nous Research)",
        "base_url": _base,
        "model_configured": bool(_model),
        "model": _model,
        "hermes_api_key_configured": bool(_api_key),
        "repair_center_auth_configured": bool(_guard_key),
        "base_url_valid": _valid_url,
        "ready_to_call": bool(_vmax_hermes_urlrequest and _valid_url and _api_key and _model and _guard_key),
        "note": "Hermes Agent API server and its model must be configured and running separately; no automatic file edits are performed.",
    }


def vmax_hermes_agent_chat(messages, timeout=None):
    """Send validated chat messages to Hermes Agent's OpenAI-compatible endpoint."""
    if _vmax_hermes_urlrequest is None or _vmax_hermes_urlparse is None:
        raise RuntimeError("Python HTTP client is unavailable")
    _base = os.environ.get("HERMES_API_BASE_URL", "http://127.0.0.1:8642/v1").strip().rstrip("/")
    _model = os.environ.get("HERMES_API_MODEL", "hermes").strip()
    _api_key = os.environ.get("HERMES_API_KEY", "").strip()
    if not _api_key:
        raise RuntimeError("HERMES_API_KEY is not configured")
    if not _model:
        raise RuntimeError("HERMES_API_MODEL is not configured")
    try:
        _parsed = _vmax_hermes_urlparse.urlparse(_base)
        if _parsed.scheme not in ("http", "https") or not _parsed.netloc or _parsed.username or _parsed.password:
            raise ValueError()
    except Exception:
        raise RuntimeError("HERMES_API_BASE_URL must be a valid HTTP(S) base URL without embedded credentials") from None
    if not isinstance(messages, list) or not messages or len(messages) > 40:
        raise RuntimeError("messages must contain 1 to 40 entries")
    _safe_messages = []
    _total_chars = 0
    for _message in messages:
        if not isinstance(_message, dict) or _message.get("role") not in ("system", "user", "assistant"):
            raise RuntimeError("Each message must have role system, user, or assistant")
        _content = _message.get("content", "")
        if not isinstance(_content, str):
            raise RuntimeError("Message content must be text")
        _total_chars += len(_content)
        if _total_chars > 50000:
            raise RuntimeError("Message content exceeds 50000 characters")
        _safe_messages.append({"role": _message["role"], "content": _content})
    _payload = json.dumps({"model": _model, "messages": _safe_messages, "stream": False}).encode("utf-8")
    _url = _base + ("" if _base.endswith("/chat/completions") else "/chat/completions")
    _req = _vmax_hermes_urlrequest.Request(
        _url, data=_payload, method="POST",
        headers={"Authorization": "Bearer " + _api_key, "Content-Type": "application/json"},
    )
    try:
        _timeout = int(timeout if timeout is not None else os.environ.get("HERMES_API_TIMEOUT_SECONDS", "90"))
        with _vmax_hermes_urlrequest.urlopen(_req, timeout=max(1, min(_timeout, 300))) as _response:
            _raw = _response.read(2_000_000)
        _data = json.loads(_raw.decode("utf-8"))
    except Exception as _exc:
        # Do not leak headers, API keys, or server response bodies in error text.
        raise RuntimeError("Hermes API request failed: " + type(_exc).__name__) from None
    _choices = _data.get("choices") if isinstance(_data, dict) else None
    if not isinstance(_choices, list) or not _choices or not isinstance(_choices[0], dict):
        raise RuntimeError("Hermes API returned no valid choices")
    _message = _choices[0].get("message", {})
    _content = _message.get("content", "") if isinstance(_message, dict) else ""
    if isinstance(_content, list):
        _content = "\n".join(str(_part.get("text", "")) for _part in _content if isinstance(_part, dict))
    return {"ok": True, "model": str(_data.get("model", _model)), "content": str(_content)}


def _vmax_repair_center_authorized():
    _expected = os.environ.get("VMAX_REPAIR_CENTER_KEY", "").strip()
    if not _expected or _vmax_hermes_hmac is None:
        return False
    _provided = request.headers.get("Authorization", "")
    if _provided.lower().startswith("bearer "):
        _provided = _provided[7:].strip()
    else:
        _provided = request.headers.get("X-Repair-Center-Key", "")
    return _vmax_hermes_hmac.compare_digest(str(_provided), _expected)


@app.route("/api/repair-center/hermes/status", methods=["GET"])
def vmax_repair_center_hermes_status_route():
    # Intentionally excludes all secrets; deployment should still restrict access.
    return jsonify(vmax_hermes_agent_status())


@app.route("/api/repair-center/hermes/chat", methods=["POST"])
def vmax_repair_center_hermes_chat_route():
    if not _vmax_repair_center_authorized():
        return jsonify({"ok": False, "error": "repair_center_auth_required",
                        "message": "Configure VMAX_REPAIR_CENTER_KEY and send it as a Bearer token."}), 401
    _body = request.get_json(silent=True)
    if not isinstance(_body, dict):
        return jsonify({"ok": False, "error": "invalid_json_body"}), 400
    _messages = _body.get("messages")
    if not isinstance(_messages, list) or not _messages or len(_messages) > 40:
        return jsonify({"ok": False, "error": "invalid_messages",
                        "message": "messages must be a non-empty array with at most 40 entries."}), 400
    _total_chars = 0
    for _item in _messages:
        if not isinstance(_item, dict) or _item.get("role") not in ("system", "user", "assistant"):
            return jsonify({"ok": False, "error": "invalid_message_role"}), 400
        if not isinstance(_item.get("content", ""), str):
            return jsonify({"ok": False, "error": "message_content_must_be_text"}), 400
        _total_chars += len(_item.get("content", ""))
        if _total_chars > 50000:
            return jsonify({"ok": False, "error": "messages_too_large", "max_chars": 50000}), 413
    try:
        return jsonify(vmax_hermes_agent_chat(_messages)), 200
    except RuntimeError as _exc:
        return jsonify({"ok": False, "error": "hermes_unavailable", "message": str(_exc)}), 502


VMAX_HERMES_REPAIR_CENTER_BRIDGE_READY = True
